INSERT INTO `community_categories` (`id`, `name`, `slug`, `description`, `icon`, `color_theme`, `created_at`) VALUES
(1, 'Cảm xúc & Tâm lý', 'cam-xuc-tam-ly', 'Nơi chia sẻ, giải tỏa những lo lắng, áp lực tinh thần học tập và cuộc sống.', 'Smile', 'emerald', '2026-06-26 08:23:17'),
(2, 'Học tập & Định hướng', 'hoc-tap-dinh-huong', 'Chia sẻ phương pháp học tập hiệu quả, tài liệu ôn thi và thảo luận định hướng tương lai.', 'BookOpen', 'indigo', '2026-06-26 08:23:17'),
(3, 'Gia đình & Bạn bè', 'gia-dinh-ban-be', 'Tâm sự về những mâu thuẫn, cách ứng xử và gắn kết tình cảm với bố mẹ, bạn bè.', 'Users', 'amber', '2026-06-26 08:23:17'),
(4, 'An toàn & Kỹ năng', 'an-toan-ky-nang', 'Trang bị kỹ năng tự bảo vệ mình trên không gian mạng và phòng chống bạo lực học đường.', 'Shield', 'rose', '2026-06-26 08:23:17'),
(5, 'Góc tâm sự tự do', 'tam-su-tu-do', 'Không gian chia sẻ tự do mọi câu chuyện đời thường thú vị của bạn.', 'MessageCircle', 'violet', '2026-06-26 08:23:17');
