INSERT INTO `courses` (`id`, `title`, `description`, `thumbnail`, `color_theme`, `course_order`, `category_id`, `created_at`, `updated_at`) VALUES
(4, 'Tự Tin Lớn Lên, Tự Chủ Khám Phá', 'Khóa học về sự đồng thuận, ranh giới cá nhân và phát triển lành mạnh dành cho tuổi teen.', 'consent-course.png', '#4361ee', 10, 2, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(5, 'Mối Quan Hệ Lành Mạnh', 'Tìm hiểu về cách xây dựng tình bạn, tình yêu tôn trọng, đặt ranh giới cá nhân và ứng xử văn minh trước cờ đỏ.', 'relationship-course.png', '#ff5d8f', 20, 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(6, 'Lướt Mạng Tỉnh Táo, Kết Nối Cực Chất', 'Tìm hiểu cách bảo vệ quyền riêng tư, thiết lập ranh giới số, hiểu về sự đồng thuận trực tuyến, chia sẻ ảnh an toàn và ứng phó với cờ đỏ thao túng.', 'digital-safety-course.png', '#7209b7', 21, 4, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(10, 'Dậy Thì Thành Công: Cẩm Nang \"Upgrade\" Bản Thân!', 'Tìm hiểu về thay đổi thể chất, hệ sinh sản, kinh nguyệt, mộng tinh, bão cảm xúc và cách tự chăm sóc cơ thể tuổi dậy thì.', 'puberty-course.png', '#f77f00', 22, 1, '2026-06-05 13:58:05', '2026-07-07 08:37:03'),
(11, 'Tâm Lý Tuổi Teen: \"Gỡ Rối\" Bão Cảm Xúc!', 'Học cách nhận diện và làm quen với những biến động cảm xúc tuổi dậy thì, xây dựng sự tự tin, ứng phó áp lực học tập và nuôi dưỡng các mối quan hệ lành mạnh.', 'emotional-wellbeing-course.png', '#06d6a0', 23, 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(22, 'Yêu An Toàn, Tránh Thai Chủ Động', 'Trang bị kiến thức khoa học và thực tế về các biện pháp tránh thai chủ động, phòng ngừa bệnh lây qua đường tình dục (STI) và rèn luyện kỹ năng đưa ra quyết định an toàn.', 'sexual-health-course.png', '#ff5d8f', 40, 1, '2026-07-04 14:18:59', '2026-07-04 15:53:22'),
(25, 'Bản Đồ Bản Thân: Tự Tin Khám Phá Giới & Bản Dạng', 'Trang bị kiến thức khoa học, thân thiện về bản dạng giới, xu hướng tính dục, phá vỡ định kiến giới và rèn luyện kỹ năng giao tiếp văn minh, tôn trọng sự đa dạng.', 'gender-diversity-course.png', '#7c3aed', 50, NULL, '2026-07-06 21:15:44', '2026-07-06 21:15:44'),
(27, 'Kỹ Năng Phòng Chống Xâm Hại & Tự Bảo Vệ', 'Trang bị các kỹ năng nhận diện ranh giới, đồng thuận, cảnh giác trước các hành vi dụ dỗ, thao túng và phản xạ ứng phó khẩn cấp để tự bảo vệ bản thân.', 'personal-safety-course.png', '#ef4444', 60, NULL, '2026-07-06 21:48:45', '2026-07-06 21:48:45'),
(33, 'Chăm Sóc Cảm Xúc & Ứng Phó Áp Lực Bạn Bè', 'Giúp bạn thấu hiểu và quản lý cảm xúc bản thân, nâng cao sự tự tin, ứng phó lành mạnh với áp lực bạn bè và xây dựng mạng lưới hỗ trợ an toàn.', 'emotional-wellbeing-course.png', '#06b6d4', 70, 3, '2026-07-07 01:57:45', '2026-07-07 01:57:45'),
(35, 'Sức Khỏe Tuổi Dậy Thì & Chăm Sóc Cơ Thể', 'Giải mã các thay đổi thể chất và sinh lý tuổi dậy thì, trang bị kiến thức giải phẫu, chu kỳ kinh nguyệt, xây dựng thói quen tự chăm sóc vệ sinh và củng cố ngoại hình tự tin.', 'puberty-health-course.png', '#9333ea', 80, 1, '2026-07-07 03:19:45', '2026-07-07 03:19:45'),
(37, 'Kỹ Năng Giao Tiếp & Giải Quyết Xung Đột', 'Học cách giao tiếp lành mạnh, lắng nghe chủ động, đặt ranh giới tôn trọng, xây dựng lòng tin và giải quyết xung đột ôn hòa trong mối quan hệ.', 'communication-course.png', '#ef4444', 90, NULL, '2026-07-07 05:53:40', '2026-07-07 05:53:40');
