INSERT INTO `games` (`id`, `slug`, `title`, `summary`, `description`, `game_type`, `play_path`, `cover_image`, `accent_color`, `is_published`, `created_at`, `updated_at`) VALUES
(1, 'quiz-quick', 'Quiz nhanh 10 câu', 'Một lượt chơi gọn để kiểm tra kiến thức và cộng điểm cá nhân.', 'Chế độ quiz nhanh được rút gọn trong 10 câu hỏi ngẫu nhiên từ ngân hàng câu hỏi.\nNgười chơi đi hết lượt mà không bị dừng lại khi sai.\nKết quả sau mỗi lượt được cộng vào tổng điểm quiz và cập nhật streak tương tác.', 'QUIZ', '/games/quiz?mode=quick', 'hero-illustration.png', '#9b5de5', 1, '2026-05-20 06:53:29', '2026-05-20 06:53:29'),
(2, 'quiz-long', 'Quiz dài 30 câu', 'Chế độ dài dành cho người muốn luyện tập sâu hơn và đưa lên bảng xếp hạng.', 'Chế độ quiz dài lấy 30 câu hỏi ngẫu nhiên từ quiz bank.\nCàng làm nhiều, điểm cá nhân và streak càng được cập nhật rõ hơn.\nĐây là chế độ chính để nhận biết mức độ hiểu bài và giữ nhịp học đều.', 'QUIZ', '/games/quiz?mode=long', 'hero-illustration.png', '#f15bb5', 1, '2026-05-20 06:53:29', '2026-05-20 06:53:29'),
(3, 'anh-sang-tu-tin', 'Ánh sáng tự tin', 'Mini game phong cách flash nhẹ nhàng, hợp chủ đề tuổi teen và xây dựng tự tin.', 'Người chơi điều khiển nhân vật thu thập bóng đèn tích cực và tránh đám mây lo âu.\nGame có phong cách HTML vui mắt, nhịp nhanh và phù hợp để chơi trong vài phút nghỉ giải lao.\nTrang game được thiết kế theo hướng flash game nhưng vẫn đồng bộ giao diện chung của EDUcare.', 'FLASH', '/games/flash-light-run', 'hero-illustration.png', '#00bbbf', 1, '2026-05-20 06:53:29', '2026-05-20 06:53:29');
INSERT INTO `lessons` (`id`, `course_id`, `slug`, `title`, `summary`, `content`, `lesson_order`, `is_free`, `xp_reward`, `estimated_minutes`, `teaser_video_id`, `full_video_id`, `created_at`, `updated_at`) VALUES
(12, 4, 'luat-di-duong-dong-thuan-la-gi', 'Luật đi đường - Đồng thuận là gì?', 'Tìm hiểu khái niệm đèn xanh, đèn vàng, đèn đỏ trong giao tiếp tình cảm và quy tắc đồng thuận F.R.I.E.S.', 'Bài học giúp bạn nắm bắt khái niệm về sự đồng thuận trong tình cảm, quy tắc F.R.I.E.S và kỹ năng check-in.', 9, 1, 100, 10, 'qK9DqF_Ci10', 'JBqlllo0LGs', '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(13, 4, 'lac-dau-khong-sao-ca', 'Lắc đầu không sao cả - Đối diện với từ chối', 'Học cách đối diện lành mạnh với lời từ chối, hiểu về ranh giới cá nhân và luật đồng thuận Việt Nam.', 'Bài học trang bị kỹ năng vượt qua cảm giác hụt hẫng khi bị từ chối, cách từ chối lịch sự và kiến thức pháp luật.', 10, 1, 100, 10, 'oib5aUmyqxk', '1No4K4CfidM', '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(14, 4, 'ranh-gioi-so-mang-xa-hoi', 'Ranh giới số & Mạng xã hội', 'Quản lý tính riêng tư trên không gian mạng và cách thực hành đồng thuận số (digital consent).', 'Nội dung hướng dẫn phân biệt ranh giới công khai/riêng tư, quy tắc chia sẻ hình ảnh, mật khẩu mạng xã hội và phòng tránh áp lực số.', 11, 1, 100, 10, 'KknU68Q42pQ', 'afbF-8Q5QmA', '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(15, 4, 'lam-chu-co-the-va-suc-khoe', 'Làm chủ cơ thể & Sức khỏe', 'Học cách tự chủ cơ thể, hiểu đúng kiến thức sinh học, an toàn sức khỏe và luật pháp.', 'Bài học trang bị kiến thức về quyền tự quyết cơ thể, gọi đúng tên các bộ phận sinh dục, an toàn y khoa và luật độ tuổi đồng thuận Việt Nam.', 12, 0, 100, 10, 'xuE_cSa85sU', 'DBVhFxQOMYk', '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(16, 4, 'ap-luc-ban-be-va-diem-tua-ho-tro', 'Áp lực bạn bè & Điểm tựa hỗ trợ', 'Vượt qua áp lực từ bạn bè, định hình giá trị bản thân và kết nối với mạng lưới hỗ trợ.', 'Bài học hướng dẫn nhận diện áp lực nhóm, kỹ năng nói Không khéo léo, đối thoại giá trị gia đình và tìm kiếm sự hỗ trợ khi gặp nguy hiểm.', 13, 0, 100, 10, 'NNdx-DIXj9s', 'in1T-7wnDFw', '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(17, 5, 'nen-tang-moi-quan-he-lanh-manh', 'Thế nào là mối quan hệ lành mạnh?', 'Tìm hiểu về các viên gạch nền tảng: sự tôn trọng, lòng tin, sự bình đẳng và cách giữ cá tính riêng.', 'Bài học này giới thiệu về các tiêu chí cốt lõi tạo nên một tình bạn hay tình yêu lành mạnh, giúp bạn cảm thấy được là chính mình.', 14, 1, 100, 10, 'H3o1ZAxwB9E', 'YIxKoIgLhKM', '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(18, 5, 'giao-tiep-va-giai-quyet-xung-dot', 'Giao tiếp & Giải quyết Xung đột', 'Học cách lắng nghe chủ động, dùng câu bắt đầu bằng \"Tớ\" để bày tỏ cảm xúc và giải quyết mâu thuẫn lành mạnh.', 'Bài học trang bị cho bạn kỹ năng giao tiếp hiệu quả, tránh hiểu lầm khi nhắn tin và các bước hòa giải xung đột êm thấm.', 15, 0, 100, 10, 'KXa1oWIVRps', 'SUPxdg7_H8Y', '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(19, 5, 'ranh-gioi-long-tin-va-su-ton-trong', 'Ranh giới, Lòng tin & Sự Tôn trọng', 'Tìm hiểu về ranh giới cá nhân, cách từng bước xây dựng lòng tin và tôn trọng không gian riêng tư của nhau.', 'Bài học hướng dẫn bạn cách xác định ranh giới cơ thể và cảm xúc của bản thân, xử lý tình huống bị đòi mật khẩu mạng xã hội và rèn luyện kỹ năng từ chối tự tin.', 16, 0, 100, 10, '8UyDjtUMRZQ', 'Mdhzsc0takI', '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(20, 5, 'su-gan-ket-va-gan-gui-cam-xuc', 'Sự Gắn kết & Gần gũi Cảm xúc', 'Tìm hiểu về sự thân mật cảm xúc, phân biệt tình bạn với tình yêu tuổi học trò và xây dựng gắn kết lành mạnh.', 'Bài học chia sẻ về cách thấu hiểu sự gắn kết tinh thần, xử lý áp lực khi đối phương muốn tiến xa hơn và các hình thức gần gũi phi thể xác.', 17, 0, 100, 10, 'OavNxoIknvM', 'nZdSDY1_WWI', '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(21, 5, 'dong-thuan-trong-moi-quan-he', 'Đồng thuận trong Mối quan hệ', 'Hiểu sâu về khái niệm sự đồng thuận, quy tắc F.R.I.E.S cho tuổi teen và cách check-in tinh tế.', 'Bài học trang bị cho bạn kiến thức cơ bản về sự đồng thuận tự nguyện, cách nhận biết tín hiệu đèn vàng, đèn đỏ trong tình cảm và cách tôn trọng quyền đổi ý.', 18, 0, 100, 10, 'YSEd0Np5hGg', 'EJcKvZEw0Ro', '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(22, 5, 'crush-hen-ho-va-tu-choi', 'Crush, Hẹn hò & Từ chối', 'Khám phá cảm xúc cảm nắng, cách hẹn hò an toàn và ứng xử văn minh khi đối diện lời từ chối.', 'Bài học cung cấp cho bạn cái nhìn thực tế về những cảm xúc ngượng ngùng tuổi teen, các bước chuẩn bị cho buổi hẹn hò an toàn và cách phục hồi cảm xúc sau khi bị từ chối.', 19, 0, 100, 10, 'JpSa6aMBKHQ', 'MJ2CByzc-LI', '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(23, 5, 'co-do-va-moi-quan-he-doc-hai', 'Nhận diện Cờ Đỏ & Mối Quan hệ Độc hại', 'Nhận diện các dấu hiệu cảnh báo (Red Flags) như kiểm soát, cô lập và học cách bước ra an toàn.', 'Bài học hướng dẫn bạn cách phân biệt sự quan tâm lành mạnh với sự kiểm soát độc hại, nhận biết vòng lặp bạo lực cảm xúc và cách tìm kiếm sự trợ giúp khi cần thiết.', 20, 0, 100, 10, 'uc_vPN8ZYj8', 'D4fZotU9LlA', '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(24, 6, 'quyen-rieng-tu-va-thong-tin-ca-nhan', 'Dấu Chân Số: Đừng Để Lộ \"Sơ Hở\"!', 'Hiểu về dấu chân số, cách phân loại thông tin nhạy cảm và bảo vệ tài khoản cá nhân.', 'Bài học này giúp bạn nhận biết những gì an toàn để chia sẻ trực tuyến, cách quản lý dấu chân số của mình và thiết lập bảo mật cơ bản.', 21, 1, 100, 12, 'fR51s075vY0', 'ncBVgfE0PWM', '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(25, 6, 'giao-tiep-mang-lanh-manh', 'Chat Sao Cho \"Mượt\", Bớt \"Bất Ổn\"!', 'Học cách giao tiếp tránh hiểu lầm, viết tin nhắn tôn trọng và giữ năng lượng tích cực.', 'Bài học này trang bị cho bạn cách ứng xử tinh tế khi nhắn tin, kỹ năng hạ nhiệt khi group chat bốc hỏa và lọc năng lượng tích cực.', 22, 0, 100, 12, 'ie0MQJDWCcI', 'hYUf2_kAzg4', '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(26, 6, 'ranh-gioi-thoi-cong-nghe', 'Ranh Giới Số: Vẽ Vạch Rõ, Đỡ Phiền Toái!', 'Đặt giới hạn thời gian, sự riêng tư cá nhân trực tuyến và cách nói lời từ chối không áy náy.', 'Bài học hướng dẫn bạn thiết lập các ranh giới lành mạnh về thời gian online, bảo vệ mật khẩu cá nhân và nói không với sự kiểm soát số.', 23, 0, 100, 12, 'Pb8xvg2pXo4', 'ssB0l8vXIg0', '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(27, 6, 'dong-thuan-so', 'Đồng Thuận Số: Đừng Tự Ý \"Mặc Định\"!', 'Khái niệm về đồng thuận trên mạng, nhận diện sự ép buộc và tôn trọng quyền tự quyết của người khác.', 'Bài học giúp bạn hiểu thế nào là sự đồng thuận trực tuyến thực sự, cách nhận diện áp lực từ bạn bè và thói quen hỏi ý kiến trước khi đăng bài liên quan đến người khác.', 24, 0, 100, 12, 'zN3dj5JZMqk', 'Yxa2ooaKVdk', '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(28, 6, 'sexting-va-chia-se-anh-an-toan', 'Sexting & Gửi Ảnh: Giữ Mình An Toàn Trên Sóng!', 'Tìm hiểu về sexting, rủi ro pháp lý, đối phó áp lực gửi ảnh nhạy cảm và cách xử lý sự cố.', 'Bài học cung cấp kiến thức thực tế về những rủi ro của việc gửi ảnh nhạy cảm trực tuyến, cách kiên quyết từ chối áp lực và các bước hỗ trợ khẩn cấp nếu ảnh bị phát tán trái phép.', 25, 0, 100, 12, '6U6JwT0wX0A', 'hyEH7yn_S9w', '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(29, 6, 'co-do-va-thao-tung-truc-tuyen', 'Né \"Cờ Đỏ\" & Kẻ Thao Túng Trên Mạng!', 'Nhận diện các dấu hiệu kiểm soát độc hại, cảnh giác trước kẻ lừa đảo giả mạo và cách tìm hỗ trợ.', 'Bài học hướng dẫn học sinh nhận diện cờ đỏ trong các mối quan hệ qua mạng, phòng tránh bẫy tâm lý giả mạo danh tính (catfishing), bẫy cô lập số và cách thoát ra an toàn.', 26, 0, 100, 12, 'mC2iX-3FgIQ', 'CCfcSVr99oE', '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(30, 6, 'cong-dan-so-van-minh', 'Công Dân Số Văn Minh: Lan Tỏa Vibes Lành!', 'Tìm hiểu về bạo lực mạng, cách trở thành người bảo vệ Upstander và lan tỏa văn hóa mạng tử tế.', 'Bài học cuối giúp bạn phân biệt đùa vui và bắt nạt trên mạng, trang bị kỹ năng ứng phó khi chứng kiến bạo lực mạng với vai trò người can thiệp dũng cảm, và hướng tới văn hóa số tích cực.', 27, 0, 100, 12, 'OrDhGQ2psaM', '5bc-fwcrrR4', '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(34, 10, 'day-thi-la-gi', 'Dậy Thì Là Gì? Khi Cơ Thể Rục Rịch Thay Đổi!', 'Khám phá khái niệm về dậy thì, nhịp độ phát triển của mỗi cơ thể và cách vượt qua những ngại ngùng đầu đời.', 'Bài học này giúp bạn hiểu rõ thế nào là dậy thì, giải đáp vì sao mọi người dậy thì ở thời điểm khác nhau và tìm kiếm đồng minh đáng tin cậy.', 28, 1, 100, 12, 'crJaJCED10U', 'Hvyc8_jmcYE', '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(35, 10, 'f5-dien-mao-thay-doi-the-chat', '\"F5\" Diện Mạo: Những Thay Đổi Rõ Mồn Một!', 'Tìm hiểu sự phát triển thể chất về da, tóc, lông cơ thể, mùi cơ thể và thói quen tắm rửa vệ sinh cá nhân đúng cách.', 'Bài học cung cấp kiến thức thực tế về các thay đổi bên ngoài như mụn, mùi cơ thể và lông, từ đó hướng dẫn chăm sóc cơ thể sạch sẽ.', 29, 0, 100, 12, 'ZOCpbDEhd9A', 'PvC-6koXfpM', '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(36, 10, 'den-thang-va-co-quan-sinh-san', '\"Đến Tháng\" & Chuyện Phía Trong: Hiểu Để Đỡ Lo!', 'Giải mã hoạt động của hệ sinh sản, chu kỳ kinh nguyệt, mộng tinh và cách chuẩn bị tâm lý cùng dụng cụ vệ sinh.', 'Bài học làm rõ nguyên lý sinh học bên trong, hướng dẫn chuẩn bị dụng cụ kinh nguyệt và giúp bạn bình tĩnh xử lý các sự cố tế nhị.', 30, 0, 100, 12, 'Sy7RE8MOEAU', 'WZfhwcnHsN4', '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(37, 10, 'bao-cam-xuc-tuoi-day-thi', 'Bão Cảm Xúc: Sáng Nắng Chiều Mưa, Có Sao Đâu?', 'Hiểu về hormone ảnh hưởng đến tâm trạng, sự nhạy cảm tuổi mới lớn và học kỹ năng cân bằng cảm xúc.', 'Bài học hướng dẫn bạn gọi tên cảm xúc, giải quyết bất đồng lành mạnh với bố mẹ và thiết lập các bài tập xoa dịu stress.', 31, 0, 100, 12, '3Z5fK4dvrBo', 'rfdtTGZJesE', '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(38, 10, 'yeu-lay-chiec-body', 'Yêu Lấy Chiếc Body: Đừng Để Ai \"Body Shame\"!', 'Hiểu về hình ảnh cơ thể lành mạnh, ứng phó trước phán xét ngoại hình và lọc bớt áp lực từ mạng xã hội.', 'Bài học giúp bạn xây dựng lòng tự tin bên trong, kiên định phản hồi trước những lời chê bai ngoại hình và tôn trọng sự đa dạng cơ thể.', 32, 0, 100, 12, 'qPiy_5UeVLE', 'UhfDDwsROFo', '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(39, 10, 'tu-cham-soc-ban-than-dung-dieu', 'Tự Chăm Sóc Bản Thân: Học Cách Yêu Mình Đúng Điệu!', 'Tầm quan trọng của dinh dưỡng, giấc ngủ, lắng nghe tín hiệu mệt mỏi và xây dựng thói quen tự chăm sóc hàng ngày.', 'Bài học trang bị thói quen ngủ nghỉ khoa học, cách hạn chế lướt điện thoại ban đêm và kiên nhẫn bao dung với bản thân.', 33, 0, 100, 12, 'xhuakJTxIxk', 'kOmGu0sPOrI', '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(40, 10, 'giai-ma-tin-don-tuoi-day-thi', '\"Tin Chuẩn\" Vs \"Tin Đồn\": Giải Mã Thắc Mắc Khó Nói!', 'Phân biệt tin đồn phản khoa học về chiều cao, hành vi tự khám phá cơ thể và cách tìm kiếm thông tin chính thống.', 'Bài học cuối cùng giúp giải mã các tin đồn nhảm học đường, hướng dẫn tư duy phản biện khi đọc tin và tự tin làm chủ tuổi dậy thì.', 34, 0, 100, 12, '5KyAYCeoZ9Y', 'HfLcvpWp7N4', '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(41, 11, 'thau-hieu-cam-xuc', 'Ủa, Sao Dạo Này Tâm Trạng \"Bão Bùng\" Quá?', 'Tìm hiểu về sự thay đổi tâm trạng do hormone dậy thì và học cách gọi tên cảm xúc.', 'Bài học mở đầu giúp bạn gọi tên các loại cảm xúc, làm bạn với cảm xúc khó chịu và viết nhật ký giải tỏa suy nghĩ.', 35, 1, 100, 12, '9hnfYkApRP4', '7rh0hOEi2YY', '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(42, 11, 'tu-tin-va-gia-tri-ban-than', 'Chữa Lành \"Tự Ti\": Bạn Có Giá Trị Hơn Bạn Tưởng!', 'Học cách phân biệt tự tin lành mạnh, hiểu nguồn gốc của tự ti và xây dựng lòng tự trắc ẩn.', 'Bài học hướng dẫn bạn vượt qua áp lực so sánh, đối mặt với điểm kém và tập cách nói lời tự trắc ẩn với chính mình.', 36, 0, 100, 12, 'msLrLfoN-l0', 'fMpbsYCmeys', '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(43, 11, 'co-the-va-chap-nhan-ban-than', 'Hòa Giải Với Chiếc Body: Bạn Đẹp Theo Cách Riêng!', 'Nhận diện ảnh hưởng của truyền thông đến hình ảnh cơ thể, học cách yêu thương vóc dáng và ứng phó body shaming.', 'Bài học trang bị kiến thức phân biệt filter ảo ma vs thực tế, tôn trọng sự đa dạng vóc dáng và rèn luyện kỹ năng ứng phó body shaming.', 37, 0, 100, 12, '_EI49W8C8HM', 'mVTzIhkH3AU', '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(44, 11, 'vuot-qua-stress-va-cam-xuc-kho-khan', 'Khi Áp Lực Đè Nặng: \"Giải Cứu\" Bộ Não Quá Tải!', 'Nhận biết dấu hiệu stress trên cơ thể, phân biệt các loại stress và thực hành kỹ thuật xoa dịu tâm trí.', 'Bài học hướng dẫn các phương pháp đối mặt chủ động với stress, phân bổ lịch học thi khoa học và rèn luyện kỹ thuật thở sâu.', 38, 0, 100, 12, 'G-rf7-GmJDs', 'Vzhki_xDLj0', '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(45, 11, 'rung-dong-tu-choi-va-phuc-hoi-cam-xuc', 'Khi \"Crush\" Từ Chối: Vượt Qua \"Bể Sầu\" Cực Mượt!', 'Hiểu về cảm xúc rung động tuổi teen, chấp nhận sự từ chối và xây dựng khả năng phục hồi sau thất bại tình cảm.', 'Bài học trang bị kỹ năng vượt qua mối tình đơn phương hững hờ, học cách đối mặt với sự từ chối văn minh và phục hồi niềm tin vào bản thân.', 39, 0, 100, 12, 'biLXKK_qbAg', 'Owxn-Rnngnc', '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(46, 11, 'ket-noi-lanh-manh-va-diem-tua-cam-xuc', 'Mối Quan Hệ \"Chất Lượng Cao\" Vs Độc Hại', 'Phân biệt tình bạn lành mạnh (Green Flag) và độc hại (Red Flag), nhận diện các hành vi kiểm soát cảm xúc.', 'Bài học hướng dẫn phân biệt mối quan hệ Green Flag và cờ đỏ thao túng cảm xúc, cách chia sẻ tổn thương tinh thần và xây dựng mạng lưới hỗ trợ.', 40, 0, 100, 12, 'szJ_snaHdY0', 'rU9PJWT7IrM', '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(47, 11, 'tu-cham-soc-va-phat-trien-ban-than', 'Yêu Bản Thân: Không Chỉ Là Câu Nói Bắt Trend!', 'Hiểu đúng về tự chăm sóc bản thân, học cách thiết lập ranh giới từ từ chối và hướng tới sự phát triển cá nhân bền vững.', 'Bài học cuối cùng hướng dẫn phương pháp self-care đích thực, rèn luyện kỹ năng từ chối bảo vệ năng lượng cá nhân và đặt mục tiêu thói quen nhỏ.', 41, 0, 100, 12, 'RQdRs4fGKFE', 'Us3jEGzJ65Q', '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(100, 22, 'suc-khoe-tinh-duc-la-gi-the', 'Sức Khỏe Tình Dục Là Gì Thế?', 'Tìm hiểu định nghĩa toàn diện về sức khỏe tình dục, ranh giới cơ thể và cách vượt qua sự ngại ngùng.', 'Bài học giúp bạn khám phá thế nào là sức khỏe tình dục toàn diện, cách xây dựng ranh giới cơ thể vững vàng và kỹ năng vượt qua những e ngại ban đầu.', 1, 1, 100, 8, '', '', '2026-07-04 14:19:00', '2026-07-04 14:19:00'),
(101, 22, 'ban-do-tranh-thai-bat-dau-tu-dau', 'Bản Đồ Tránh Thai - Bắt Đầu Từ Đâu?', 'Khám phá cơ chế dính bầu cơ bản và phân loại các loại vũ khí tránh thai chính.', 'Bài học giúp bạn tìm hiểu cơ chế sinh học đằng sau việc mang thai ngoài ý muốn và giới thiệu bức tranh toàn cảnh về các nhóm biện pháp tránh thai.', 2, 1, 100, 8, '', '', '2026-07-04 14:19:06', '2026-07-04 14:19:06'),
(102, 22, 'hiep-si-bao-cao-su', '\"Hiệp Sĩ\" Bao Cao Su', 'Làm chủ kỹ năng sử dụng bao cao su chuẩn chỉnh và kỹ năng thương lượng an toàn.', 'Bài học cung cấp hướng dẫn từng bước để sử dụng bao cao su nam đúng cách, đồng thời trang bị kỹ năng thương lượng sử dụng bao cao su khi gặp sự phản đối.', 3, 1, 100, 10, '', '', '2026-07-04 14:19:10', '2026-07-04 14:19:10'),
(103, 22, 'vien-thuoc-nho-be-va-noi-tiet-tranh-thai', 'Viên Thuốc Nhỏ Bé & Nội Tiết Tránh Thai', 'Hiểu sâu về cơ chế hoạt động của thuốc hàng ngày, miếng dán và vòng âm đạo.', 'Bài học cung cấp đầy đủ thông tin về các biện pháp tránh thai nội tiết chứa estrogen/progestin, hướng dẫn uống thuốc đúng cách và cách xử trí khi quên thuốc.', 4, 0, 100, 10, '', '', '2026-07-04 14:19:14', '2026-07-04 14:19:14'),
(104, 22, 'bien-phap-tranh-thai-lau-dai-va-ranh-tay', 'Biện Pháp Tránh Thai Lâu Dài & \"Rảnh Tay\"', 'Tìm hiểu về que cấy dưới da, vòng tránh thai IUD và các mũi tiêm định kỳ.', 'Bài học giúp bạn tìm hiểu các biện pháp tránh thai lâu dài có thể phục hồi (LARC) gồm que cấy, vòng tránh thai IUD và tiêm tránh thai. Đây là những biện pháp cực kỳ rảnh tay với độ hiệu quả cao nhất.', 5, 0, 100, 8, '', '', '2026-07-04 14:19:19', '2026-07-04 14:19:19'),
(105, 22, 'nut-undo-phut-chot-tranh-thai-khan-cap', 'Nút \"Undo\" Phút Chót - Tránh Thai Khẩn Cấp', 'Cách xử lý sự cố khẩn cấp bằng thuốc 72h/120h đúng quy trình y tế.', 'Bài học trang bị kiến thức y khoa thực tế về thuốc tránh thai khẩn cấp, thời gian vàng sử dụng thuốc, cách đối phó tác dụng phụ và quy tắc chia sẻ trách nhiệm.', 6, 0, 100, 10, '', '', '2026-07-04 14:19:23', '2026-07-04 14:19:23'),
(106, 22, 'xuat-tinh-ngoai-va-tinh-chu-ky', 'Xuất Tinh Ngoài & Tính Chu Kỳ - Có Thực Sự An Toàn?', 'Lật tẩy những lầm tưởng tai hại về xuất tinh ngoài, app tính chu kỳ và màng phim.', 'Bài học làm rõ cơ chế rủi ro cao của xuất tinh ngoài do pre-cum, sự không chính xác của app rụng trứng và tỷ lệ rò rỉ của màng phim tránh thai.', 7, 0, 100, 10, '', '', '2026-07-04 14:19:27', '2026-07-04 14:19:27'),
(107, 22, 'bao-ve-ban-than-khoi-sti-va-xet-nghiem', 'Bảo Vệ Bản Thân Khỏi STI & Xét Nghiệm', 'Nhận diện các bệnh lây truyền qua đường tình dục và bình thường hóa việc đi xét nghiệm.', 'Bài học hướng dẫn nhận biết các bệnh lây truyền qua đường tình dục (STI), lật đổ nỗi sợ và sự kỳ thị, hướng dẫn rủ partner đi xét nghiệm và quy trình khám an toàn.', 8, 0, 100, 8, '', '', '2026-07-04 14:19:31', '2026-07-04 14:19:31'),
(108, 22, 'dua-ra-quyet-dinh-sang-suot', 'Đưa Ra Quyết Định Sáng Suốt', 'Lắng nghe bản thân, xây dựng kế hoạch an toàn và tự tin làm chủ lựa chọn cá nhân.', 'Bài học giúp bạn rèn luyện tư duy tự chủ, kỹ năng check-in cảm xúc cá nhân, deal với áp lực yêu đương và lập kế hoạch bảo vệ an toàn cho tương lai.', 9, 0, 100, 8, '', '', '2026-07-04 14:19:35', '2026-07-04 14:19:35'),
(123, 25, 'ai-la-toi-trong-guong', 'Ai là \"tôi\" trong gương?', 'Khám phá khái niệm bản dạng cá nhân, nhận diện các mảnh ghép tạo nên sự độc bản và học cách yêu thương bản thân.', 'Bài học giúp bạn tìm hiểu thế nào là bản dạng (Identity), cách nhận diện các giá trị cá nhân và vượt qua áp lực từ kỳ vọng của người khác.', 1, 1, 100, 8, '', '', '2026-07-06 21:15:44', '2026-07-06 21:15:44'),
(124, 25, 'ban-dang-gio-ben-trong-ban-nghi-minh-la-ai', 'Bản dạng giới: Bên trong bạn nghĩ mình là ai?', 'Phân biệt giới tính sinh học với bản dạng giới, tìm hiểu về hợp giới, chuyển giới và phi nhị nguyên.', 'Bài học giúp bạn thấu hiểu sự khác biệt giữa cơ thể và tâm trí, cách xưng hô tôn trọng đại từ (Pronouns) và chấp nhận sự đa dạng giới.', 2, 1, 100, 8, '', '', '2026-07-06 21:15:49', '2026-07-06 21:15:49'),
(125, 25, 'style-va-dinh-kien-tu-do-the-hien-chinh-minh', 'Style & Định kiến: Tự do thể hiện chính mình', 'Tìm hiểu thể hiện giới và khuôn mẫu giới, vượt qua áp lực chuẩn mực và tự tin tỏa sáng.', 'Bài học phân tích sự khác biệt giữa sở thích ăn mặc và xu hướng tính dục, nhận diện khuôn mẫu giới chật chội và cách tự tin thể hiện cái tôi.', 3, 0, 100, 8, '', '', '2026-07-06 21:15:54', '2026-07-07 08:32:55'),
(126, 25, 'xu-huong-tinh-duc-trai-tim-ban-rung-dong-vi-ai', 'Xu hướng tính dục: Trái tim bạn rung động vì ai?', 'Khám phá các sắc màu tình yêu (Gay, Lesbian, Bi, Pan, Asexual) và lắng nghe nhịp điệu trái tim.', 'Bài học làm rõ sự khác biệt giữa xu hướng tình cảm và tình dục, lật mở khái niệm vô tính (Asexual) và trân trọng mọi rung động đầu đời.', 4, 0, 100, 8, '', '', '2026-07-06 21:15:58', '2026-07-07 08:35:27'),
(127, 25, 'hoi-cham-va-kham-pha-khong-can-voi-dan-nhan', 'Hỏi chấm & Khám phá: Không cần vội dán nhãn', 'Thấu hiểu trạng thái tự vấn (Questioning) và tính linh hoạt (fluidity) của cảm xúc.', 'Bài học đồng hành cùng bạn qua những mơ hồ tuổi dậy thì, giải tỏa áp lực tìm câu trả lời ngay lập tức và kỹ năng bảo vệ sức khỏe tinh thần.', 5, 0, 100, 8, '', '', '2026-07-06 21:16:02', '2026-07-07 08:35:37'),
(128, 25, 'cong-dong-cau-vong-va-thu-thach-thuc-te', 'Cộng đồng Cầu vồng & Thử thách thực tế', 'Nhận diện kỳ thị ngầm, vượt qua áp lực tinh thần và kết nối các nguồn lực hỗ trợ an toàn.', 'Bài học phân tích những thử thách thực tế về bạo lực học đường, cách đối phó với trò đùa kém duyên và xây dựng sự tự tin cho người trẻ LGBTQ+.', 6, 0, 100, 8, '', '', '2026-07-06 21:16:06', '2026-07-07 08:35:46'),
(129, 25, 'giao-tiep-van-minh-tro-thanh-dong-minh-tinh-te', 'Giao tiếp văn minh: Trở thành đồng minh tinh tế', 'Tìm hiểu về đồng minh (Ally), nhận diện tổn thương vô ý (Microaggressions) và giao tiếp tôn trọng.', 'Bài học trang bị kỹ năng ứng xử khi bạn bè come out, cách xưng hô tôn trọng danh tính và sửa sai tinh tế khi lỡ lời trong giao tiếp.', 7, 0, 100, 8, '', '', '2026-07-06 21:16:10', '2026-07-07 08:35:52'),
(137, 27, 'chiec-ra-da-co-the', 'Chiếc ra-đa cơ thể', 'Nhận diện tín hiệu bất an từ cơ thể và thấu hiểu vòng tròn khoảng cách an toàn cá nhân.', 'Bài học hướng dẫn cách lắng nghe linh cảm cơ thể, thiết lập khoảng cách an toàn và tin tưởng vào bản thân khi đối mặt với các đụng chạm uncomfy.', 1, 1, 100, 8, '', '', '2026-07-06 21:48:46', '2026-07-06 21:48:46'),
(138, 27, 'luat-choi-cua-ranh-gioi-va-dong-thuan', 'Luật chơi của Ranh giới & Sự đồng thuận', 'Thấu hiểu về ranh giới cá nhân và nguyên tắc đồng thuận tự nguyện F.R.I.E.S.', 'Bài học trang bị kỹ năng nói Không dứt khoát, vượt qua tâm lý sợ bị ghét và học cách tôn trọng ranh giới của bạn bè.', 2, 1, 100, 8, '', '', '2026-07-06 21:48:50', '2026-07-06 21:48:50'),
(139, 27, 'mat-na-cua-ke-du-do', 'Mặt nạ của kẻ dụ dỗ', 'Nhận diện hành vi dụ dỗ (Grooming) và các cờ đỏ thao túng tinh vi của kẻ xấu.', 'Bài học giúp bạn lột trần bẫy quà tặng online, vạch mặt các bí mật độc hại và bảo vệ mình khỏi sự thao túng của người quen lẫn người lạ.', 3, 0, 100, 8, '', '', '2026-07-06 21:48:53', '2026-07-07 08:28:29'),
(140, 27, 'goi-ten-nhung-tinh-huong-bat-on', 'Gọi tên những tình huống bất ổn', 'Nhận diện các hình thức xâm hại (thể chất, tinh thần, tình dục) và xâm hại đồng trang lứa (COCSA).', 'Bài học giúp bạn phân biệt quấy rối tình dục lời nói với trò đùa, vượt qua cảm giác tự trách vô lý và hiểu rõ bản thân hoàn toàn vô tội.', 4, 0, 100, 8, '', '', '2026-07-06 21:48:57', '2026-07-07 08:28:36'),
(141, 27, 'phan-ung-nhanh-khi-gap-nguy-hiem', 'Phản ứng nhanh khi gặp nguy hiểm', 'Tìm hiểu cơ chế Chiến - Biến - Đơ (Fight-Flight-Freeze) và kỹ năng thoát hiểm thực tế.', 'Bài học hướng dẫn cách kêu cứu khẩn cấp, đối phó bị bám đuôi, phá vỡ cơn đông cứng của cơ thể và bảo vệ bản thân an toàn.', 5, 0, 100, 8, '', '', '2026-07-06 21:49:01', '2026-07-07 08:28:50'),
(142, 27, 'phia-sau-con-bao-chua-lanh-va-dong-hanh', 'Phía sau cơn bão: Chữa lành & Đồng hành', 'Học cách chăm sóc tâm lý sau chấn thương, quy tắc vàng 72 giờ và hỗ trợ bạn bè tinh tế.', 'Bài học hướng dẫn kỹ năng lắng nghe không phán xét, cách trở thành đồng minh tinh tế và thấu hiểu quá trình tự chữa lành tâm lý.', 6, 0, 100, 8, '', '', '2026-07-06 21:49:04', '2026-07-07 08:29:23'),
(143, 27, 'tam-khien-bao-ve-moi-ngay', 'Tấm khiên bảo vệ mỗi ngày', 'Xây dựng Kế hoạch an toàn cá nhân, danh sách liên hệ và mật mã khẩn cấp gia đình.', 'Bài học rèn luyện kỹ năng phòng ngừa trước khi tham gia tiệc tùng, vượt qua sự e ngại với bố mẹ và ghi nhớ các kênh liên lạc khẩn cấp quốc gia.', 7, 0, 100, 8, '', '', '2026-07-06 21:49:08', '2026-07-07 08:29:40'),
(155, 33, 'thau-hieu-cam-xuc-ban-than', 'Thấu hiểu cảm xúc', 'Bản đồ cảm xúc cá nhân, cách nhận diện tín hiệu cơ thể và chấp nhận mọi cảm xúc.', 'Bài học giúp bạn học cách gọi tên cảm xúc, vượt qua sự trốn tránh cảm xúc khó chịu và xử lý cơn giận lành mạnh.', 1, 1, 100, 8, '', '', '2026-07-07 01:57:45', '2026-07-07 01:57:45'),
(156, 33, 'gia-tri-ca-nhan-va-chap-nhan-ban-than', 'Giá trị cá nhân & Chấp nhận bản thân', 'Hiểu rõ về lòng tự trọng, hình ảnh cơ thể lành mạnh và vượt qua cái bẫy so sánh.', 'Bài học rèn luyện kỹ năng tự đối thoại bằng lòng trắc ẩn, nhận biết thế mạnh bản thân và chấp nhận chính mình.', 2, 1, 100, 8, '', '', '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(157, 33, 'quan-ly-stress-va-cam-xuc-kho-khan', 'Quản lý stress & Cảm xúc khó khăn', 'Nhận diện các dấu hiệu stress quá tải, sự cô đơn lạc lõng và áp lực học đường.', 'Bài học cung cấp hộp công cụ xả stress thực tế, kỹ năng đối mặt với thất bại và tìm kiếm hỗ trợ khi không ổn.', 3, 0, 100, 8, '', '', '2026-07-07 01:57:49', '2026-07-07 08:21:51'),
(158, 33, 'ap-luc-ban-be-va-lua-chon-lanh-manh', 'Áp lực bạn bè & Lựa chọn lành mạnh', 'Thấu hiểu về áp lực nhóm trực tiếp/gián tiếp, nỗi sợ cô lập và cờ đỏ rủ rê nguy hiểm.', 'Bài học trang bị kỹ thuật từ chối áp lực bạn bè tinh tế, giúp bạn rèn luyện sự tự chủ và chịu trách nhiệm hành vi.', 4, 0, 100, 8, '', '', '2026-07-07 01:57:50', '2026-07-07 08:21:57'),
(159, 33, 'suc-manh-noi-tam-va-kha-nang-phuc-hoi', 'Sức mạnh nội tâm & Khả năng phục hồi', 'Tư duy phát triển vs cố định, sức mạnh của sự tổn thương mềm mại và vượt qua đổ vỡ.', 'Bài học rèn luyện kỹ năng coping lành mạnh, biến vấp ngã thành bài học và duy trì thói quen tiến bộ bền bỉ.', 5, 0, 100, 8, '', '', '2026-07-07 01:57:50', '2026-07-07 08:22:05'),
(160, 33, 'moi-quan-he-lanh-manh-va-mang-luoi-ho-tro', 'Mối quan hệ lành mạnh & Mạng lưới hỗ trợ', 'Định nghĩa tình bạn tốt, nhận diện cờ đỏ, và giải quyết xung đột bằng thông điệp I-message.', 'Bài học giúp bạn đối phó với sự tẩy chay cô lập, thiết lập mạng lưới an toàn và cùng nhau đồng hành phát triển.', 6, 0, 100, 8, '', '', '2026-07-07 01:57:51', '2026-07-07 08:27:34'),
(161, 33, 'yeu-thuong-ban-than-va-phat-trien-ca-nhan', 'Yêu thương bản thân & Phát triển cá nhân', 'Tự chăm sóc bản thân lành mạnh, đáp ứng giấc ngủ/dinh dưỡng, và vượt qua kiệt sức.', 'Bài học rèn luyện kỹ năng đặt ranh giới từ chối việc quá tải, nhật ký biết ơn và kiên nhẫn phát triển bản thân.', 7, 0, 100, 8, '', '', '2026-07-07 01:57:55', '2026-07-07 08:27:42'),
(169, 35, 'giai-ma-tuoi-day-thi', 'Giải mã tuổi dậy thì', 'Hiểu đúng về dậy thì, hormone sinh dục và chiếc đồng hồ sinh học phát triển riêng biệt của mỗi người.', 'Bài học cung cấp kiến thức nền tảng về tuổi dậy thì, sự biến động cảm xúc do hormone nội tiết và kỹ năng chấp nhận sự phát triển độc lập.', 1, 1, 100, 8, '', '', '2026-07-07 03:19:45', '2026-07-07 03:19:45'),
(170, 35, 'nhung-bien-doi-lon-tren-co-the', 'Những biến đổi lớn trên cơ thể', 'Khám phá các cột mốc thay đổi thể chất từ chiều cao, mùi cơ thể, vỡ giọng đến mộng tinh.', 'Bài học giúp bạn nhận diện các biến đổi thể chất tự nhiên ở tuổi dậy thì, hướng dẫn cách vệ sinh cơ thể và tự tin thích nghi với vóc dáng mới.', 2, 1, 100, 8, '', '', '2026-07-07 03:19:50', '2026-07-07 03:19:50'),
(171, 35, 'giai-phau-co-the-va-tu-nhan-thuc', 'Giải phẫu cơ thể & Sự tự nhận thức', 'Thấu hiểu cấu tạo cơ quan sinh lý nam, nữ, ranh giới đụng chạm và cách trân trọng bản thân.', 'Bài học cung cấp giải phẫu khoa học chuẩn xác về hệ sinh dục ngoài, hướng dẫn bảo vệ ranh giới cơ thể và gạt bỏ sự ngượng ngùng vô cớ.', 3, 0, 100, 8, '', '', '2026-07-07 03:19:55', '2026-07-07 08:20:50'),
(172, 35, 'chu-ky-kinh-nguyet-va-phat-trien-sinh-san', 'Chu kỳ kinh nguyệt & Phát triển sinh sản', 'Giải mã chu kỳ kinh nguyệt, cách giảm đau bụng kinh, chọn sản phẩm vệ sinh và theo dõi chu kỳ.', 'Bài học trang bị kiến thức về hành kinh, PMS, cách sử dụng các sản phẩm nguyệt san và gạt bỏ các định kiến kiêng cữ lạc hậu.', 4, 0, 100, 8, '', '', '2026-07-07 03:19:59', '2026-07-07 08:20:57'),
(173, 35, 've-sinh-ca-nhan-va-cham-soc-co-the', 'Vệ sinh cá nhân & Chăm sóc cơ thể', 'Xây dựng thói quen chăm sóc da, vệ sinh vùng kín, đảm bảo giấc ngủ, dinh dưỡng và vận động.', 'Bài học hướng dẫn xây dựng lối sống sạch sẽ khoa học, tự chăm sóc vùng kín an toàn và tối đa hóa tiềm năng phát triển thể chất.', 5, 0, 100, 8, '', '', '2026-07-07 03:20:04', '2026-07-07 08:21:06'),
(174, 35, 'ngoai-hinh-va-thoi-quen-lanh-manh', 'Ngoại hình & Thói quen lành mạnh', 'Vượt qua áp lực so sánh trên mạng xã hội, body shaming và củng cố lòng tự tin ngoại hình tự thân.', 'Bài học hướng dẫn cách thoát khỏi các tiêu chuẩn sắc đẹp ảo trên mạng, đối phó với miệt thị ngoại hình và trân trọng sự độc bản cơ thể.', 6, 0, 100, 8, '', '', '2026-07-07 03:20:08', '2026-07-07 08:21:15'),
(175, 35, 'giai-ma-lam-tuong-va-tu-cham-soc', 'Giải mã lầm tưởng & Chăm sóc bản thân', 'Nhận diện tin đồn tuổi dậy thì, tra cứu sức khỏe an toàn và lập kế hoạch tự chăm sóc (Self-care).', 'Bài học giúp bạn phân biệt lầm tưởng khoa học, vượt qua sự bối rối khi nói chuyện với người lớn và lắng nghe các tín hiệu kêu cứu của cơ thể.', 7, 0, 100, 8, '', '', '2026-07-07 03:20:12', '2026-07-07 08:21:24'),
(183, 37, 'nen-tang-giao-tiep-lanh-manh', 'Nền tảng Giao tiếp Lành mạnh', 'Định nghĩa giao tiếp lành mạnh, bình đẳng, nhận diện cờ xanh và vượt qua nỗi sợ mở lòng.', 'Bài học cung cấp kiến thức cốt lõi về giao tiếp lành mạnh, tầm quan trọng của lòng tin, cách xử lý hiểu lầm qua tin nhắn và kỹ năng mở lời đúng lúc.', 1, 1, 100, 8, '', '', '2026-07-07 05:53:40', '2026-07-07 05:53:40'),
(184, 37, 'lang-nghe-chu-dong-tu-tin-bay-to', 'Lắng nghe Chủ động & Tự tin Bày tỏ', 'Học cách lắng nghe bằng cả trái tim, sử dụng mệnh đề Tôi để bày tỏ chân thành không đổ lỗi.', 'Bài học giúp bạn rèn luyện kỹ năng lắng nghe chủ động, thấu cảm, cách vượt qua nỗi sợ bị từ chối và thực hành công thức nói mệnh đề Tôi tinh tế.', 2, 1, 100, 8, '', '', '2026-07-07 05:53:45', '2026-07-07 05:53:45'),
(185, 37, 'xay-dung-moi-quan-he-lanh-manh', 'Xây dựng Mối quan hệ Lành mạnh', 'Nhận diện sự bình đẳng, chia sẻ trách nhiệm và giữ cân bằng trong tình bạn lẫn tình yêu.', 'Bài học giúp bạn nhận diện các đặc điểm của mối quan hệ lành mạnh, vượt qua sự mất cân bằng một chiều và học cách chia sẻ trách nhiệm.', 3, 0, 100, 8, '', '', '2026-07-07 05:53:49', '2026-07-07 08:19:47'),
(186, 37, 'ranh-gioi-ton-trong-niem-tin', 'Ranh giới, Tôn trọng & Niềm tin', 'Thiết lập ranh giới riêng tư, tôn trọng giới hạn của bạn bè và bảo vệ bản thân khi nói Không.', 'Bài học trang bị kỹ năng thiết lập ranh giới thể chất, thông tin cá nhân và thời gian riêng tư mà không thấy tội lỗi áy náy vô lý.', 4, 0, 100, 8, '', '', '2026-07-07 05:53:53', '2026-07-07 08:19:58'),
(187, 37, 'ky-nang-giai-quyet-xung-dot', 'Kỹ năng Giải quyết Xung đột', 'Hạ nhiệt cơn giận để đối thoại, tránh chiến tranh lạnh độc hại và cộng tác tháo gỡ mâu thuẫn.', 'Bài học hướng dẫn quy tắc dừng lại kiểm soát cơn giận, tác hại của im lặng trừng phạt và cách đứng về một phía để giải quyết vấn đề chung.', 5, 0, 100, 8, '', '', '2026-07-07 05:53:57', '2026-07-07 08:20:05'),
(188, 37, 'vuot-qua-thu-thach-trong-moi-quan-he', 'Vượt qua Thử thách trong Mối quan hệ', 'Nhận diện cờ đỏ kiểm soát độc hại, ra quyết định dừng lại và chữa lành sau chia tay văn minh.', 'Bài học giúp bạn lột trần hành vi ghen tuông kiểm soát mật khẩu định vị, cách nói lời chia tay trực tiếp lịch sự và bảo vệ an toàn cảm xúc của mình.', 6, 0, 100, 8, '', '', '2026-07-07 05:54:01', '2026-07-07 08:20:15'),
(189, 37, 'gan-ket-ben-chat-qua-giao-tiep', 'Gắn kết Bền chặt qua Giao tiếp', 'Dũng cảm bày tỏ sự dễ tổn thương, lắng nghe thấu cảm và làm người đồng minh tinh thần tốt.', 'Bài học củng cố kết nối sâu sắc qua chia sẻ nỗi sợ hãi chân thành, đặt câu hỏi mở khơi gợi tâm sự và giữ bí mật bảo mật niềm tin.', 7, 0, 100, 8, '', '', '2026-07-07 05:54:06', '2026-07-07 08:20:24');
