(1188, 189, 'Kỹ năng: Đặt câu hỏi mở để gợi mở tâm sự', 5, '2026-07-07 05:54:08', '2026-07-07 05:54:08'),
(1189, 189, 'Bạn có người bạn nào sẵn sàng nghe mọi bí mật của mình?', 6, '2026-07-07 05:54:08', '2026-07-07 05:54:08'),
(1190, 189, 'Đúc kết: Kết nối sâu sắc bắt nguồn từ sự chân thành', 7, '2026-07-07 05:54:09', '2026-07-07 05:54:09'),
(1191, 189, 'Bài kiểm tra: Thử thách tổng kết', 99, '2026-07-07 05:54:10', '2026-07-07 05:54:10');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(75, 13, 'hook', '{\"title\": \"Bạn có bao giờ lái xe băng qua giao lộ mà không thèm nhìn đèn tín hiệu?\"}', 1, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(76, 13, 'explanation', '{\"bullets\": [\"Khi đi trên đường, tụi mình cần đèn xanh đèn đỏ để không đâm vào nhau.\", \"Trong tình cảm cũng vậy. Cơ thể và cảm xúc của mỗi người đều có những tín hiệu riêng.\", \"Muốn chạm vào ai đó hay tiến xa hơn, bạn bắt buộc phải quan sát và hỏi ý kiến đối phương.\"]}', 2, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(77, 13, 'scenario', '{\"title\": \"Nhìn tín hiệu cơ thể\", \"body\": \"Quân định bá vai Vy khi hai đứa đang ngồi học nhóm. Vy hơi rụt vai lại và mắt dán vào trang sách. Quân phân vân: Vy đang ngại hay Vy không thích mình chạm vào nhỉ?\"}', 3, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(78, 13, 'interaction', '{\"question\": \"Bạn khuyên Quân nên làm gì?\", \"choices\": [{\"text\": \"Cứ bá vai tiếp, bạn bè thân thiết ngại gì.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Dừng lại, hỏi nhẹ nhàng: Tớ để tay lên vai cậu được không?\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(79, 13, 'reflection', '{\"question\": \"Bạn có cảm thấy thoải mái khi người khác đột ngột đụng chạm mà không hỏi trước?\"}', 5, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(80, 13, 'takeaway', '{\"items\": [\"Lái xe an toàn cần nhìn biển báo. Muốn chạm vào người khác cần hỏi trước.\"]}', 6, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(81, 14, 'hook', '{\"title\": \"Một lời đồng ý gượng ép có thực sự mang lại niềm vui?\"}', 1, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(82, 14, 'explanation', '{\"bullets\": [\"Đèn xanh chỉ bật khi có sự đồng thuận rõ ràng, tự nguyện từ hai phía.\", \"Quy tắc F.R.I.E.S bao gồm: Tự nguyện (Freely given), Linh hoạt (Reversible), Đầy đủ thông tin (Informed), Hào hứng (Enthusiastic) và Cụ thể (Specific).\"]}', 2, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(83, 14, 'scenario', '{\"title\": \"Đồng ý vì nể\", \"body\": \"Nam rủ Linh vào góc tối công viên nói chuyện. Linh ngập ngừng nói: Cũng được... nếu cậu muốn. Nhưng tay Linh bấu chặt vào vạt áo, mắt nhìn xuống đất.\"}', 3, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(84, 14, 'interaction', '{\"question\": \"Lời đồng ý của Linh có phải là đồng thuận xịn không?\", \"choices\": [{\"text\": \"Có chứ, bạn ấy đã gật đầu rồi mà.\", \"correct\": false, \"emoji\": \"🚩\"}, {\"text\": \"Không. Linh đồng ý vì nể Nam và đang lo lắng, không hề hào hứng.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(85, 14, 'reflection', '{\"question\": \"Bạn từng đồng ý làm điều gì đó chỉ vì đối phương nài nỉ quá nhiều chưa?\"}', 5, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(86, 14, 'takeaway', '{\"items\": [\"Chỉ có tiếng Có hào hứng và tự nguyện mới là đèn xanh để đi tiếp.\"]}', 6, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(87, 15, 'hook', '{\"title\": \"Tại sao đôi khi tụi mình muốn nói Không nhưng họng lại nghẹn đắng?\"}', 1, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(88, 15, 'explanation', '{\"bullets\": [\"Nỗi sợ bị ghét, sợ làm hỏng bầu không khí khiến tụi mình chọn im lặng hoặc cười trừ.\", \"Không phản đối không có nghĩa là đồng ý.\", \"Khi thấy đối phương im lặng hoặc cứng đờ người (Đèn Vàng), bạn phải dừng lại và hỏi han.\"]}', 2, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(89, 15, 'scenario', '{\"title\": \"Áp lực từ bạn bè\", \"body\": \"Trong một buổi tiệc sinh nhật, nhóm bạn ép Minh uống thêm một ly nước ngọt pha cồn. Minh không thích nhưng chỉ im lặng cúi đầu và cười gượng.\"}', 3, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(90, 15, 'interaction', '{\"question\": \"Nếu bạn là bạn thân ngồi cạnh Minh, bạn sẽ làm gì?\", \"choices\": [{\"text\": \"Hùa theo nhóm bạn: Cơ hội vui mà Minh, uống đi sợ gì!\", \"correct\": false, \"emoji\": \"🚩\"}, {\"text\": \"Giúp Minh từ chối: Thôi Minh không uống được đâu, tụi mình uống nước ngọt đi.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(91, 15, 'reflection', '{\"question\": \"Bạn từng im lặng chấp nhận một điều mình ghét vì sợ người khác đánh giá chưa?\"}', 5, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(92, 15, 'takeaway', '{\"items\": [\"Im lặng không phải là đồng ý. Đó có thể là lúc đối phương đang cần bạn dừng lại.\"]}', 6, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(93, 16, 'hook', '{\"title\": \"Đồng ý lúc trước thì lúc sau có được đổi ý không?\"}', 1, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(94, 16, 'explanation', '{\"bullets\": [\"Đồng thuận có tính linh hoạt (Reversible). Bạn có quyền đổi ý bất cứ lúc nào.\", \"Giây trước thấy thích, giây sau thấy không thoải mái là chuyện hết sức bình thường.\", \"Đối phương có nghĩa vụ phải tôn trọng khi bạn nói Dừng lại.\"]}', 2, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(95, 16, 'scenario', '{\"title\": \"Quyền đổi ý giữa chừng\", \"body\": \"Trang đồng ý để Quân ôm mình. Nhưng khi Quân ôm hơi chặt và định thơm má, Trang thấy ngột ngạt và đẩy nhẹ Quân ra: Khoan đã Quân, tớ thấy hơi nhanh.\"}', 3, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(96, 16, 'interaction', '{\"question\": \"Phản ứng nào của Quân là Green Flag xịn?\", \"choices\": [{\"text\": \"Giận dỗi: Ơ hay, nãy đồng ý rồi mà giờ lại thế?\", \"correct\": false, \"emoji\": \"🙁\"}, {\"text\": \"Dừng lại ngay, nới lỏng tay: Tớ xin lỗi, tớ làm cậu khó chịu hả?\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(97, 16, 'reflection', '{\"question\": \"Bạn có dám đổi ý khi đang làm một việc gì đó với bạn bè không?\"}', 5, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(98, 16, 'takeaway', '{\"items\": [\"Bạn luôn có quyền quay xe. Cơ thể và ranh giới của bạn là của riêng bạn.\"]}', 6, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(99, 17, 'hook', '{\"title\": \"Làm thế nào để xin phép người ta mà không khiến bầu không khí bị sượng trân?\"}', 1, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(100, 17, 'explanation', '{\"bullets\": [\"Hỏi ý kiến không làm giảm đi sự lãng mạn.\", \"Hỏi han tinh tế thể hiện bạn quan tâm chân thành đến cảm giác của người ta.\", \"Hãy dùng những câu hỏi ngắn gọn, tự nhiên và ngọt ngào.\"]}', 2, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(101, 17, 'scenario', '{\"title\": \"Ý định nắm tay\", \"body\": \"Duy muốn nắm tay Linh khi hai đứa đang đi dạo công viên. Thay vì tự ý chụp lấy, Duy nhìn Linh và mỉm cười nhẹ.\"}', 3, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(102, 17, 'interaction', '{\"question\": \"Giúp Duy chọn câu hỏi mượt nhất nhé:\", \"choices\": [{\"text\": \"Đưa tay đây tớ nắm xem nào.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Tớ nắm tay cậu được không?\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(103, 17, 'reflection', '{\"question\": \"Bạn thích được hỏi ý kiến trước hay thích đối phương tự ý hành động hơn?\"}', 5, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(104, 17, 'takeaway', '{\"items\": [\"Hỏi trước khi chạm thể hiện sự tôn trọng, đó là nền tảng của sự lãng mạn.\"]}', 6, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(105, 18, 'hook', '{\"title\": \"Tình yêu có thực sự hạnh phúc nếu thiếu đi sự tự nguyện?\"}', 1, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(106, 18, 'explanation', '{\"bullets\": [\"Mối quan hệ lành mạnh mang lại niềm vui, tự do và sự tin cậy.\", \"Mọi hành vi ép buộc, nài nỉ hay thao túng tâm lý đều làm tổn thương tình cảm.\", \"Tình yêu lành mạnh không bao giờ đi kèm sự lo sợ hay cảm giác có lỗi.\"]}', 2, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(107, 18, 'scenario', '{\"title\": \"Áp lực gửi ảnh riêng tư\", \"body\": \"Cường nhắn tin năn nỉ An gửi ảnh cá nhân riêng tư cho mình, nói rằng yêu nhau thì phải tin tưởng nhau tuyệt đối. An lo sợ nếu không gửi Cường sẽ giận.\"}', 3, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(108, 18, 'interaction', '{\"question\": \"Bạn khuyên An nên nhắn gì cho Cường?\", \"choices\": [{\"text\": \"Thôi được rồi, gửi một tấm thôi nha, cậu đừng cho ai xem.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Tớ không thoải mái với việc này. Mong cậu tôn trọng ranh giới của tớ.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(109, 18, 'reflection', '{\"question\": \"Bạn có đang cố làm hài lòng người khác bằng cách bỏ qua cảm xúc của chính mình?\"}', 5, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(110, 18, 'takeaway', '{\"items\": [\"Yêu thương đi liền với sự tôn trọng, không phải sự ép buộc.\"]}', 6, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(111, 19, 'hook', '{\"title\": \"Tại sao khi người ấy từ chối, tụi mình lại thấy xấu hổ đến thế?\"}', 1, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(112, 19, 'explanation', '{\"bullets\": [\"Bị từ chối (rejection) kích hoạt cảm giác hụt hẫng, ngượng ngùng tạm thời.\", \"Đây là trải nghiệm siêu bình thường mà ai cũng phải trải qua khi trưởng thành.\", \"Lời từ chối chỉ có nghĩa mong muốn của hai bên chưa khớp nhau tại thời điểm đó.\"]}', 2, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(113, 19, 'scenario', '{\"title\": \"Lời từ chối bận rộn\", \"body\": \"Kiên rủ Vy đi ăn kem sau giờ học. Vy trả lời: Xin lỗi cậu nha, hôm nay tớ phải về dọn nhà giúp mẹ rồi. Kiên đứng thẫn thờ, đỏ mặt và tự trách mình đã rủ rê.\"}', 3, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(114, 19, 'interaction', '{\"question\": \"Kiên nên nghĩ thế nào để bớt buồn?\", \"choices\": [{\"text\": \"Chắc mình nhạt nhẽo nên bạn ấy mới lấy cớ từ chối. Sẽ không bao giờ rủ ai nữa.\", \"correct\": false, \"emoji\": \"🙁\"}, {\"text\": \"Vy bận thật mà. Hôm khác mình rủ lại hoặc rủ đám bạn thân đi ăn kem.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(115, 19, 'reflection', '{\"question\": \"Bạn đã từng bị từ chối một lời mời chưa? Cảm xúc lúc đó thế nào?\"}', 5, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(116, 19, 'takeaway', '{\"items\": [\"Bị từ chối không có nghĩa là bạn tệ. Chỉ là thời điểm chưa phù hợp thôi.\"]}', 6, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(117, 20, 'hook', '{\"title\": \"Lý do từ chối thường nằm ở phía đối phương, không phải do bạn kém cỏi.\"}', 1, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(118, 20, 'explanation', '{\"bullets\": [\"Có nhiều lý do khiến người khác lắc đầu: mệt mỏi, áp lực học tập, lo lắng chuyện gia đình.\", \"Đừng vội tự ti hay trách móc bản thân.\", \"Học cách phân loại lý do từ chối để giải tỏa tâm lý.\"]}', 2, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(119, 20, 'sorting', '{\"instruction\": \"Hãy phân loại các lý do từ chối sau đây vào đúng hộp:\", \"leftBox\": {\"title\": \"Ranh giới & Hoàn cảnh của họ\"}, \"rightBox\": {\"title\": \"Suy diễn tự ti của mình\"}, \"items\": [{\"text\": \"Tớ đang lo lắng chuyện bài vở\", \"correctBox\": \"left\"}, {\"text\": \"Tại mình xấu xí nên bạn chê\", \"correctBox\": \"right\"}, {\"text\": \"Tớ chưa sẵn sàng thân mật\", \"correctBox\": \"left\"}, {\"text\": \"Do mình nhạt nên bị từ chối\", \"correctBox\": \"right\"}]}', 3, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(120, 20, 'reflection', '{\"question\": \"Bạn có bao giờ từ chối đi chơi với bạn thân chỉ vì bạn đang mệt hay buồn ngủ chưa?\"}', 4, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(121, 20, 'takeaway', '{\"items\": [\"Họ từ chối một đề nghị, chứ không phủ nhận con người bạn.\"]}', 5, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(122, 21, 'hook', '{\"title\": \"Ứng xử thế nào sau khi bị từ chối để giữ được sự cool ngầu và lịch sự?\"}', 1, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(123, 21, 'explanation', '{\"bullets\": [\"Tuyệt đối không giận dỗi, trách móc hay im lặng cắt đứt liên lạc.\", \"Hãy mỉm cười, tôn trọng ranh giới của họ và cư xử bình thường.\", \"Điều này thể hiện sự tự tin và giúp họ nể trọng bạn hơn.\"]}', 2, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(124, 21, 'scenario', '{\"title\": \"Bị từ chối xem phim\", \"body\": \"Sơn rủ Vy đi xem phim cuối tuần. Vy nhắn tin từ chối: Cuối tuần này tớ bận đi sinh nhật họ hàng mất rồi. Sơn thấy hụt hẫng và ngượng.\"}', 3, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(125, 21, 'interaction', '{\"question\": \"Giúp Sơn nhắn lại một câu thật lịch sự nhé:\", \"choices\": [{\"text\": \"Bận suốt thế. Thôi từ sau tớ chả rủ nữa.\", \"correct\": false, \"emoji\": \"🙁\"}, {\"text\": \"Ok cậu nè, đi sinh nhật vui vẻ nha! Hẹn cậu dịp khác.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(126, 21, 'reflection', '{\"question\": \"Nếu bạn từ chối ai đó, bạn muốn nhận lại phản ứng vui vẻ hay giận dỗi từ họ?\"}', 5, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(127, 21, 'takeaway', '{\"items\": [\"Tôn trọng lời từ chối là biểu hiện của một tình bạn đẹp và trưởng thành.\"]}', 6, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(128, 22, 'hook', '{\"title\": \"Làm sao để nói Không một cách rõ ràng mà không sợ làm tổn thương người khác?\"}', 1, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(129, 22, 'explanation', '{\"bullets\": [\"Bạn không cần giải thích quá dông dài khi muốn bảo vệ ranh giới của mình.\", \"Từ chối thẳng thắn, lịch sự tốt hơn là nói dối hoặc chịu đựng.\", \"Một câu nói rõ ràng giúp cả hai giữ sự tôn trọng.\"]}', 2, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(130, 22, 'scenario', '{\"title\": \"Sự mệt mỏi sau giờ học\", \"body\": \"Lâm rủ Vy đi uống trà sữa. Vy thấy rất mệt và muốn về nhà ngủ, nhưng Vy sợ từ chối thẳng thừng sẽ khiến Lâm nghĩ mình kiêu kỳ.\"}', 3, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(131, 22, 'interaction', '{\"question\": \"Vy nên nhắn gì cho Lâm?\", \"choices\": [{\"text\": \"Tớ bận rồi.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Cảm ơn Lâm nha, nhưng hôm nay tớ hơi mệt nên muốn về nghỉ sớm. Hẹn cậu hôm khác nhé!\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(132, 22, 'reflection', '{\"question\": \"Bạn có cảm thấy khó khăn khi phải nói lời từ chối với bạn bè không?\"}', 5, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(133, 22, 'takeaway', '{\"items\": [\"Nói Không lịch sự là quyền của bạn. Người trân trọng bạn sẽ luôn thấu hiểu.\"]}', 6, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(134, 23, 'hook', '{\"title\": \"Những lần bị từ chối có thể dạy tụi mình điều gì về bản thân?\"}', 1, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(135, 23, 'explanation', '{\"bullets\": [\"Sự bền bỉ (resilience) là khả năng chấp nhận thực tế và tự hồi phục sau thất vọng.\", \"Thất bại trong tình cảm là cơ hội để học hỏi và thấu hiểu ranh giới của người khác.\", \"Tập trung vào các hoạt động tích cực giúp bạn chữa lành nhanh hơn.\"]}', 2, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(136, 23, 'scenario', '{\"title\": \"Sức mạnh của sự kiên cường\", \"body\": \"Duy tỏ tình với bạn cùng lớp và bị từ chối nhẹ nhàng. Duy buồn vài ngày, nhưng sau đó nhận ra việc dám bày tỏ đã là sự dũng cảm của mình.\"}', 3, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(137, 23, 'interaction', '{\"question\": \"Duy đã làm gì để tự vượt qua?\", \"choices\": [{\"text\": \"Tự cô lập bản thân và ghét bỏ tình bạn cũ.\", \"correct\": false, \"emoji\": \"🙁\"}, {\"text\": \"Chấp nhận, tập trung vào bóng rổ và củng cố việc học tập.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(138, 23, 'reflection', '{\"question\": \"Bạn có nghĩ rằng sau mỗi lần từ chối, chúng ta sẽ trở nên vững vàng hơn không?\"}', 5, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(139, 23, 'takeaway', '{\"items\": [\"Vết xước nhỏ trong tình cảm không làm bạn yếu đi, chúng giúp bạn trưởng thành hơn.\"]}', 6, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(140, 24, 'hook', '{\"title\": \"Đâu là sự khác biệt giữa bảng tin công khai và không gian riêng tư của bạn?\"}', 1, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(141, 24, 'explanation', '{\"bullets\": [\"Không gian mạng xã hội cũng có công viên công cộng và có phòng ngủ riêng tư.\", \"Làm lộ thông tin hoặc đăng hình ảnh quá cá nhân có thể gây hại cho bản thân.\", \"Hiểu ranh giới giúp bạn tự bảo vệ hình ảnh cá nhân và tôn trọng người khác.\"]}', 2, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(142, 24, 'scenario', '{\"title\": \"Ảnh dìm bạn thân\", \"body\": \"Vy chụp được bức ảnh dìm của bạn thân lúc ngủ gật trong lớp. Vy thấy rất vui và định đăng lên story Facebook công khai cho cả trường xem.\"}', 3, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(143, 24, 'interaction', '{\"question\": \"Vy nên làm gì để tôn trọng ranh giới riêng tư?\", \"choices\": [{\"text\": \"Vui mà, bạn bè đùa tí có sao đâu cứ đăng đi.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Gửi riêng cho bạn đó xem trước, nếu bạn đồng ý mới được đăng.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(144, 24, 'reflection', '{\"question\": \"Bạn có thấy khó chịu nếu hình ảnh lúc ngốc nghếch của mình bị đăng lên mạng mà chưa hỏi ý kiến?\"}', 5, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(145, 24, 'takeaway', '{\"items\": [\"Mạng xã hội không bao giờ quên. Hãy bảo vệ sự riêng tư của chính mình và bạn bè.\"]}', 6, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(146, 25, 'hook', '{\"title\": \"Chụp ảnh chung với người khác thì có được tự ý đăng lên mạng không?\"}', 1, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(147, 25, 'explanation', '{\"bullets\": [\"Đồng thuận số (digital consent) bắt đầu từ việc hỏi ý kiến trước khi đăng ảnh người khác.\", \"Có thể bạn thấy ảnh đẹp, nhưng người khác lại không thoải mái khi ảnh họ hiện diện trên mạng.\", \"Hãy gỡ ảnh hoặc xóa tag nếu bạn của bạn yêu cầu.\"]}', 2, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(148, 25, 'scenario', '{\"title\": \"Yêu cầu gỡ ảnh\", \"body\": \"Nam đăng ảnh chụp chung với Trang lên Instagram. Trang thấy ảnh đó mặt mình bị dìm nên nhắn tin bảo Nam gỡ xuống. Nam thấy Trang phiền phức.\"}', 3, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(149, 25, 'interaction', '{\"question\": \"Nam nên xử lý thế nào để thể hiện sự tôn trọng?\", \"choices\": [{\"text\": \"Kệ Trang: Hình đẹp thế này gỡ làm gì, cậu cứ vẽ chuyện.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Gỡ ảnh hoặc xóa tag ngay lập tức: Xin lỗi cậu nha, tớ gỡ liền nè.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(150, 25, 'reflection', '{\"question\": \"Bạn đã từng nhờ bạn bè gỡ hình chụp chung vì thấy mình không được đẹp chưa?\"}', 5, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(151, 25, 'takeaway', '{\"items\": [\"Chụp chung không có nghĩa là được tự ý share. Tôn trọng ranh giới là ưu tiên số 1.\"]}', 6, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(152, 26, 'hook', '{\"title\": \"Yêu nhau là phải đưa mật khẩu tài khoản mạng xã hội để chứng minh lòng tin?\"}', 1, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(153, 26, 'explanation', '{\"bullets\": [\"Yêu cầu đưa mật khẩu để kiểm soát tin nhắn là hành vi xâm phạm ranh giới riêng tư.\", \"Tình yêu lành mạnh dựa trên sự tin tưởng lẫn nhau, không phải kiểm soát 24/7.\", \"Mỗi người đều cần có một không gian riêng tư được tôn trọng.\"]}', 2, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(154, 26, 'scenario', '{\"title\": \"Đòi mật khẩu TikTok\", \"body\": \"Lâm yêu cầu Vy đưa mật khẩu tài khoản TikTok để kiểm tra tin nhắn. Vy thấy ngột ngạt nhưng sợ Lâm giận nên định nhượng bộ.\"}', 3, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(155, 26, 'interaction', '{\"question\": \"Vy nên nói gì với Lâm để bảo vệ ranh giới?\", \"choices\": [{\"text\": \"Đây nè, cậu cứ vào xem đi để khỏi nghi ngờ tớ nữa.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Tớ yêu cậu nhưng tớ muốn giữ không gian riêng tư. Tin tưởng nhau quan trọng hơn mật khẩu.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(156, 26, 'reflection', '{\"question\": \"Bạn có nghĩ một người thực sự tin tưởng bạn sẽ không cần giám sát tin nhắn của bạn không?\"}', 5, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(157, 26, 'takeaway', '{\"items\": [\"Mật khẩu là chìa khóa riêng tư tối thiểu. Hãy tôn trọng lòng tự trọng của nhau.\"]}', 6, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(158, 27, 'hook', '{\"title\": \"Phải làm sao khi người yêu nhắn tin đòi bạn gửi hình ảnh nhạy cảm?\"}', 1, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(159, 27, 'explanation', '{\"bullets\": [\"Gửi ảnh nhạy cảm (sexting) tiềm ẩn rủi ro cực kỳ lớn đối với học sinh.\", \"Bạn hoàn toàn có quyền từ chối. Không ai được dùng tình cảm để ép buộc bạn làm điều này.\", \"Ảnh gửi đi sẽ không còn nằm trong kiểm soát của bạn và có thể bị phát tán.\"]}', 2, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(160, 27, 'scenario', '{\"title\": \"Chứng minh tình yêu bằng ảnh\", \"body\": \"Cường nhắn tin đòi Vy gửi ảnh chụp bờ vai trần của Vy để chứng minh tình yêu. Vy sợ nếu không gửi Cường sẽ đòi chia tay.\"}', 3, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(161, 27, 'interaction', '{\"question\": \"Vy nên làm thế nào?\", \"choices\": [{\"text\": \"Gửi đại một tấm mờ mờ để xoa dịu Cường.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Từ chối dứt khoát: Tớ không làm việc này đâu. Mong cậu tôn trọng quyết định của tớ.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(162, 27, 'reflection', '{\"question\": \"Nếu một người sẵn sàng giận dỗi vì bạn từ chối gửi ảnh nhạy cảm, họ có yêu bạn thật lòng?\"}', 5, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(163, 27, 'takeaway', '{\"items\": [\"Hình ảnh đã gửi đi không thể lấy lại. Hãy bảo vệ ranh giới an toàn của mình.\"]}', 6, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(164, 28, 'hook', '{\"title\": \"Những gì bạn thấy trên mạng về tình yêu tuổi teen có giống 100% ngoài đời thực?\"}', 1, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(165, 28, 'explanation', '{\"bullets\": [\"Phim ảnh và mạng xã hội thường cường điệu hóa và lãng mạn hóa sự đụng chạm ép buộc.\", \"Năng lực đánh giá truyền thông (media literacy) giúp bạn không bị ảo tưởng bởi kỳ vọng phi thực tế.\", \"Mối quan hệ thực tế cần sự thấu hiểu, vụng về và tôn trọng ranh giới.\"]}', 2, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(166, 28, 'flashcard', '{\"front\": \"Sự đụng chạm bá đạo trên phim ảnh có phải là hình mẫu ngoài đời?\", \"back\": \"Không. Trên phim thường lãng mạn hóa việc đụng chạm không xin phép. Ngoài đời, sự đồng thuận tự nguyện và tôn trọng ranh giới mới là ưu tiên số 1.\", \"notes\": \"Cần phân biệt kịch bản điện ảnh với các mối quan hệ an toàn thực tế.\"}', 3, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(167, 28, 'reflection', '{\"question\": \"Bạn có từng mong muốn người yêu mình phải hoàn hảo hay bá đạo giống nhân vật trong phim chưa?\"}', 4, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(168, 28, 'takeaway', '{\"items\": [\"Đừng mang kịch bản phim ảnh áp vào đời thực. Sự an toàn và tôn trọng quan trọng hơn sự lãng mạn giả tạo.\"]}', 5, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(169, 29, 'hook', '{\"title\": \"Ai là người đưa ra quyết định cuối cùng đối với cơ thể của bạn?\"}', 1, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(170, 29, 'explanation', '{\"bullets\": [\"Quyền tự quyết (Agency) nghĩa là bạn có toàn quyền sở hữu cơ thể của mình.\", \"Không ai được chạm vào cơ thể bạn nếu chưa được bạn đồng ý.\", \"Bạn có quyền từ chối mọi đụng chạm mà bạn thấy không thoải mái.\"]}', 2, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(171, 29, 'scenario', '{\"title\": \"Thử thách của đám đông\", \"body\": \"Vy bị nhóm bạn thách ôm một bạn nam trong lớp mà Vy không quen thân. Nhóm bạn hò reo ép Vy làm, dù Vy thấy rất ngượng ngập và không muốn.\"}', 3, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(172, 29, 'interaction', '{\"question\": \"Vy nên ứng xử thế nào để giữ quyền tự quyết?\", \"choices\": [{\"text\": \"Nhắm mắt làm theo để không bị chê là nhát và phá cuộc vui.\", \"correct\": false, \"emoji\": \"🙁\"}, {\"text\": \"Từ chối dứt khoát: Tớ không thoải mái với thử thách này, tớ xin chịu phạt kiểu khác nhé.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(173, 29, 'reflection', '{\"question\": \"Bạn có từng ép bản thân đụng chạm với ai đó chỉ vì áp lực xung quanh chưa?\"}', 5, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(174, 29, 'takeaway', '{\"items\": [\"Cơ thể là lãnh thổ riêng của bạn. Chỉ có bạn mới quyết định ai được phép bước vào.\"]}', 6, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(175, 30, 'hook', '{\"title\": \"Tại sao tụi mình thường dùng từ lóng để nói về bộ phận nhạy cảm?\"}', 1, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(176, 30, 'explanation', '{\"bullets\": [\"Giáo dục giới tính khoa học cần gọi đúng tên các bộ phận sinh học (âm hộ, dương vật, tinh hoàn).\", \"Gọi đúng tên giúp bạn bớt ngại ngùng và tự tin chăm sóc vệ sinh.\", \"Đây là ngôn ngữ y tế chính xác để bạn giao tiếp khi gặp vấn đề sức khỏe.\"]}', 2, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(177, 30, 'flashcard', '{\"front\": \"Tại sao phải phân biệt Vulva (Âm hộ) và Vagina (Âm đạo)?\", \"back\": \"Vulva là toàn bộ cơ quan sinh dục ngoài (có thể nhìn thấy bên ngoài), còn Vagina là ống âm đạo nằm bên trong. Việc gọi tên chính xác giúp nhận diện cấu tạo sinh học và chăm sóc sức khỏe đúng cách.\", \"notes\": \"Khoa học không có sự xấu hổ.\"}', 3, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(178, 30, 'reflection', '{\"question\": \"Bạn có thấy việc dùng tên khoa học giúp các cuộc thảo luận trở nên nghiêm túc hơn không?\"}', 4, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(179, 30, 'takeaway', '{\"items\": [\"Không có gì xấu hổ khi nói về sinh học cơ thể. Gọi đúng tên là tự trọng và khoa học.\"]}', 5, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(180, 31, 'hook', '{\"title\": \"Bảo vệ an toàn cho cơ thể có phải là chuyện của riêng ai?\"}', 1, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(181, 31, 'explanation', '{\"bullets\": [\"An toàn (safety) bao gồm an toàn thể chất, ngừa thai và phòng tránh bệnh STIs.\", \"Các bạn teen cần hiểu rõ biện pháp phòng ngừa để chịu trách nhiệm bảo vệ bản thân.\", \"Hãy dựa vào kiến thức y học, đừng tin vào những lời truyền miệng thiếu căn cứ.\"]}', 2, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(182, 31, 'scenario', '{\"title\": \"Xuất tinh ngoài có an toàn?\", \"body\": \"Huy nghe các bạn kháo nhau rằng chỉ cần rút ra kịp lúc là an toàn, không cần dùng bao cao su vướng víu.\"}', 3, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(183, 31, 'interaction', '{\"question\": \"Ý kiến của các bạn Huy đúng hay sai?\", \"choices\": [{\"text\": \"Đúng, phương pháp này rất phổ biến và tiết kiệm.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Sai hoàn toàn. Phương pháp này rủi ro cao và không ngừa được bệnh STIs. Chỉ bao cao su mới an toàn.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(184, 31, 'reflection', '{\"question\": \"Bạn có tự tin mình biết cách phòng ngừa các rủi ro sức khỏe sinh sản chưa?\"}', 5, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(185, 31, 'takeaway', '{\"items\": [\"An toàn thể chất cần kiến thức y học chính xác. Đừng đánh cược sức khỏe của mình.\"]}', 6, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(186, 32, 'hook', '{\"title\": \"Bạn có biết pháp luật Việt Nam bảo vệ ranh giới tuổi teen nghiêm ngặt như thế nào?\"}', 1, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(187, 32, 'explanation', '{\"bullets\": [\"Độ tuổi đồng thuận tình dục tối thiểu ở Việt Nam là từ đủ 16 tuổi trở lên.\", \"Quan hệ tình dục với người dưới 16 tuổi là vi phạm pháp luật hình sự, kể cả tự nguyện.\", \"Luật pháp đặt ranh giới này để bảo vệ vị thành niên khỏi các tổn thương tâm lý và thể chất sớm.\"]}', 2, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(188, 32, 'scenario', '{\"title\": \"Tự nguyện dưới 16 tuổi\", \"body\": \"Tuấn (17 tuổi) và Lan (15 tuổi) yêu nhau. Tuấn muốn hai đứa tiến xa hơn vì cho rằng tự nguyện thì không sao. Lan băn khoăn về pháp luật.\"}', 3, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(189, 32, 'interaction', '{\"question\": \"Ý kiến của Tuấn có đúng luật pháp Việt Nam không?\", \"choices\": [{\"text\": \"Đúng, tự nguyện yêu nhau thì không ai can thiệp.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Sai. Lan 15 tuổi (dưới 16), việc quan hệ tình dục là phạm pháp đối với Tuấn, kể cả tự nguyện.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(190, 32, 'reflection', '{\"question\": \"Tại sao luật pháp lại cần bảo vệ các bạn dưới 16 tuổi một cách tuyệt đối như vậy?\"}', 5, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(191, 32, 'takeaway', '{\"items\": [\"Biết luật để tự bảo vệ mình và người mình yêu thương. Ranh giới pháp lý là tấm khiên vững chắc.\"]}', 6, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(192, 33, 'hook', '{\"title\": \"Có bao giờ bạn đứng trước gương và tự ti về cơ thể dậy thì đang thay đổi?\"}', 1, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(193, 33, 'explanation', '{\"bullets\": [\"Mỗi người lớn lên với tốc độ khác nhau. Mụn, giọng nói hay cân nặng thay đổi đều là bình thường.\", \"Không có một vóc dáng chuẩn nào cả. Yêu cơ thể mình là nền tảng của tự tin.\", \"Hãy kiên nhẫn với bản thân trong giai đoạn dậy thì này.\"]}', 2, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(194, 33, 'scenario', '{\"title\": \"So sánh chiều cao\", \"body\": \"Linh tự ti vì các bạn nữ trong lớp đã phổng phao và cao lớn, còn mình vẫn thấp bé như học sinh tiểu học. Linh sợ mình bị chậm phát triển.\"}', 3, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(195, 33, 'interaction', '{\"question\": \"Chọn lời khuyên giúp Linh tự tin hơn:\", \"choices\": [{\"text\": \"Tìm mua các loại thuốc tăng chiều cao hoặc ăn kiêng cấp tốc.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Cơ thể cậu đang phát triển đúng nhịp của nó. Hãy kiên nhẫn và yêu bản thân nhé.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(196, 33, 'reflection', '{\"question\": \"Bạn thích nhất điểm nào trên cơ thể mình hiện tại? Hãy dành một lời khen cho nó nhé.\"}', 5, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(197, 33, 'takeaway', '{\"items\": [\"Cơ thể bạn đang lớn lên theo cách riêng của nó. Đừng so sánh bản thân với bất kỳ ai.\"]}', 6, '2026-06-05 01:35:30', '2026-06-05 01:35:30'),
(198, 34, 'hook', '{\"title\": \"Bạn có bao giờ làm một việc nguy hiểm chỉ vì sợ bị hội bạn thân chê nhát gan?\"}', 1, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(199, 34, 'explanation', '{\"bullets\": [\"Áp lực đồng trang lứa (peer pressure) dễ khiến tụi mình làm những việc không thoải mái.\", \"Hội bạn có thể ép trốn học, thử vape hay đùa cợt thô bạo người khác.\", \"Nhận biết sự thúc ép giúp bạn bảo vệ ranh giới cá nhân kỹ càng.\"]}', 2, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(200, 34, 'scenario', '{\"title\": \"Thử thách uống bia\", \"body\": \"Trong buổi tiệc, các bạn thách Nam uống thử một hớp bia lớn để chứng minh mình đàn ông. Nam không thích nhưng sợ bị cả hội tẩy chay.\"}', 3, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(201, 34, 'interaction', '{\"question\": \"Nam nên làm thế nào?\", \"choices\": [{\"text\": \"Uống luôn cho xong để được cả nhóm khen ngầu.\", \"correct\": false, \"emoji\": \"🙁\"}, {\"text\": \"Từ chối vui vẻ: Thôi tớ xin kiếu, uống nước ngọt được rồi, tớ phải đạp xe về.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(202, 34, 'reflection', '{\"question\": \"Bạn đã từng làm việc gì đó mà mình ghét chỉ để được nhóm bạn chơi chung chấp nhận chưa?\"}', 5, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(203, 34, 'takeaway', '{\"items\": [\"Đám bạn thực sự tốt sẽ tôn trọng quyết định của bạn, chứ không ép bạn làm việc nguy hại.\"]}', 6, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(204, 35, 'hook', '{\"title\": \"Tại sao việc đi ngược lại số đông lại cần nhiều dũng khí đến thế?\"}', 1, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(205, 35, 'explanation', '{\"bullets\": [\"Teenager luôn có nỗi sợ bị cô lập, bị trêu chọc hay bị coi là lập dị trong nhóm.\", \"Hiểu được cảm xúc lo sợ này giúp bạn bớt tự trách mình khi thấy khó mở lời.\", \"Giữ vững lập trường của mình mới là biểu hiện của sự tự tin thực sự.\"]}', 2, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(206, 35, 'scenario', '{\"title\": \"Trò cô lập bạn mới\", \"body\": \"Vy thấy cả nhóm bạn thân đang hùa nhau nói xấu và cô lập một bạn nữ mới chuyển trường. Vy muốn đến bắt chuyện nhưng sợ cả nhóm quay sang tẩy chay mình.\"}', 3, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(207, 35, 'interaction', '{\"question\": \"Đâu là lựa chọn dũng khí của Vy?\", \"choices\": [{\"text\": \"Im lặng hùa theo nhóm để bảo vệ bản thân.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Đứng về phía lẽ phải: chủ động bắt chuyện với bạn mới và khuyên ngăn nhóm bạn.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(208, 35, 'reflection', '{\"question\": \"Bạn có sẵn sàng đứng về phía lẽ phải ngay cả khi chỉ có một mình không?\"}', 5, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(209, 35, 'takeaway', '{\"items\": [\"Đi ngược lại đám đông cần dũng khí, nhưng đó là cách để giữ gìn sự tự trọng của bạn.\"]}', 6, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(210, 36, 'hook', '{\"title\": \"Làm sao để từ chối lời rủ rê mà không gây rạn nứt tình bạn thân thiết?\"}', 1, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(211, 36, 'explanation', '{\"bullets\": [\"Từ chối không cần phải gay gắt hay gây chiến.\", \"Bạn có thể đưa ra lý do cá nhân hợp lý hoặc dùng sự hài hước để giảm bớt căng thẳng.\", \"Quan trọng là giọng điệu kiên định nhưng thân thiện.\"]}', 2, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(212, 36, 'scenario', '{\"title\": \"Rủ trốn học cày rank\", \"body\": \"Nhóm bạn rủ Lâm trốn học buổi chiều để đi quán net chơi game. Lâm muốn ở lại học bài chuẩn bị thi nhưng sợ bị chê là mọt sách chán ngắt.\"}', 3, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(213, 36, 'interaction', '{\"question\": \"Giúp Lâm từ chối khéo nhất nhé:\", \"choices\": [{\"text\": \"Trốn học là xấu đấy, các cậu lười biếng quá.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Chiều nay tớ phải cày nốt đống đề Toán mai thi rồi. Các đại ca đi vui vẻ nhé, mai thi xong tớ bù sau!\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(214, 36, 'reflection', '{\"question\": \"Bạn thường dùng cách nào để từ chối bạn bè khi họ rủ rê làm việc bạn không muốn?\"}', 5, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(215, 36, 'takeaway', '{\"items\": [\"Từ chối khéo léo giúp bạn giữ vững ranh giới mà vẫn duy trì tình bạn tốt đẹp.\"]}', 6, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(216, 37, 'hook', '{\"title\": \"Phải làm sao khi những giá trị bạn tin tưởng khác biệt với kỳ vọng của gia đình?\"}', 1, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(217, 37, 'explanation', '{\"bullets\": [\"Trưởng thành là quá trình định hình thế giới quan và đạo đức cá nhân riêng.\", \"Khác biệt quan điểm không phải là nổi loạn, mà là bước lớn lên tự nhiên.\", \"Hãy đối thoại chân thành và tôn trọng để tìm sự đồng cảm từ bố mẹ.\"]}', 2, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(218, 37, 'scenario', '{\"title\": \"Lệnh cấm kết bạn\", \"body\": \"Bố mẹ Vy cấm Vy không được kết bạn hay nói chuyện với bất kỳ bạn nam nào trong lớp. Vy thấy quy định quá khắt khe nhưng sợ cãi lời sẽ bị mắng hỗn láo.\"}', 3, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(219, 37, 'interaction', '{\"question\": \"Vy nên làm thế nào để đối thoại hiệu quả?\", \"choices\": [{\"text\": \"Cài lại gay gắt hoặc âm thầm nói dối, giấu giếm mối quan hệ.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Chọn lúc vui vẻ, chia sẻ về việc học nhóm chung và cam kết giữ ranh giới học tập để bố mẹ an tâm.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(220, 37, 'reflection', '{\"question\": \"Có quan điểm nào về tình bạn hay tình yêu mà bạn muốn thảo luận cởi mở với bố mẹ của mình không?\"}', 5, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(221, 37, 'takeaway', '{\"items\": [\"Tôn trọng giá trị gia đình không có nghĩa là im lặng. Đối thoại chân thành kết nối các thế hệ.\"]}', 6, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(222, 38, 'hook', '{\"title\": \"Bạn sẽ tìm đến ai khi cảm thấy ranh giới an toàn của mình đang bị đe dọa?\"}', 1, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(223, 38, 'explanation', '{\"bullets\": [\"Bạn không bao giờ phải chịu đựng hay giải quyết các rắc rối một mình.\", \"Nếu bị đe dọa, xâm hại ranh giới hoặc đụng chạm trái phép, hãy báo ngay cho bố mẹ hoặc thầy cô.\", \"Tổng đài Quốc gia Bảo vệ Trẻ em 111 hoạt động miễn phí 24/7 để lắng nghe và bảo vệ bạn.\"]}', 2, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(224, 38, 'scenario', '{\"title\": \"Lời đe dọa từ khóa trên\", \"body\": \"An bị một bạn khóa trên đe dọa sẽ đăng bức ảnh chụp trộm An lên nhóm chat của trường nếu không chịu đi chơi riêng. An vô cùng hoảng sợ.\"}', 3, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(225, 38, 'interaction', '{\"question\": \"An nên làm thế nào?\", \"choices\": [{\"text\": \"Im lặng làm theo vì quá sợ hãi lời đe dọa.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Chụp màn hình bằng chứng, báo ngay cho bố mẹ/thầy cô và gọi tổng đài can thiệp 111.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(226, 38, 'reflection', '{\"question\": \"Bạn có ghi nhớ số điện thoại 111 và số của người lớn đáng tin cậy nhất để gọi khi khẩn cấp không?\"}', 5, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(227, 38, 'takeaway', '{\"items\": [\"Tìm kiếm sự hỗ trợ không phải là yếu đuối. Đó là hành động dũng cảm để tự bảo vệ mình.\"]}', 6, '2026-06-05 01:35:31', '2026-06-05 01:35:31'),
(228, 39, 'hook', '{\"title\": \"Mối quan hệ lành mạnh không phải là một phép thuật có sẵn, mà là một ngôi nhà cần tự xây.\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(229, 39, 'explanation', '{\"bullets\": [\"Nền tảng đầu tiên là Tôn Trọng: coi trọng cảm xúc và ý kiến của nhau.\", \"Nền tảng thứ hai là Lòng Tin: tin tưởng đối phương mà không cần kiểm soát.\", \"Nền tảng thứ ba là Bình Đẳng: cả hai có quyền quyết định và đóng góp ngang nhau.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(230, 39, 'scenario', '{\"title\": \"Đi ăn đồ nướng\", \"body\": \"Vân muốn đi ăn lẩu, nhưng Huy lại muốn ăn đồ nướng. Huy cười bảo: Thôi hôm nay ăn lẩu theo ý Vân đi, tuần sau tụi mình ăn đồ nướng nha. Cả hai đều vui vẻ.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(231, 39, 'interaction', '{\"question\": \"Hành vi của Huy thể hiện điều gì?\", \"choices\": [{\"text\": \"Bình đẳng và biết nhường nhịn tôn trọng ý kiến bạn bè.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Huy quá yếu đuối, không dám giữ chính kiến của mình.\", \"correct\": false, \"emoji\": \"🚩\"}]}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(232, 39, 'reflection', '{\"question\": \"Trong mối quan hệ bạn bè của bạn, bạn cảm thấy tiếng nói của mình có được lắng nghe bình đẳng không?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(233, 39, 'takeaway', '{\"items\": [\"Tôn trọng, lòng tin và bình đẳng là ba viên gạch xây nên mối quan hệ bền vững.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(234, 40, 'hook', '{\"title\": \"Làm sao biết một mối quan hệ có tốt cho bạn hay không? Hãy hỏi cơ thể bạn.\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(235, 40, 'explanation', '{\"bullets\": [\"Mối quan hệ lành mạnh mang lại cảm giác an tâm, vui vẻ và ấm áp.\", \"Nếu bạn luôn cảm thấy hồi hộp lo lắng, sợ hãi, hoặc bồn chồn (đau bụng, căng cơ), đó là tín hiệu cảnh báo.\", \"Đừng bỏ qua cảm giác bất an bên trong cơ thể bạn.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(236, 40, 'scenario', '{\"title\": \"Mỗi lần nhận tin nhắn\", \"body\": \"Mỗi khi nhận cuộc gọi từ Lâm, tim Lan lại đập thình thịch vì sợ Lâm sẽ mắng hoặc giận dỗi vì Lan không rep tin nhắn ngay lập tức.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(237, 40, 'flashcard', '{\"front\": \"Làm sao để nhận biết cơ thể đang báo động một mối quan hệ bất ổn?\", \"back\": \"Nhận biết qua cảm xúc lo âu, bồn chồn, tim đập thình thịch sợ hãi, cơ thể căng cứng, hoặc cảm giác nơm nớp sợ đối phương mắng giận.\", \"notes\": \"Cơ thể luôn gửi tín hiệu trước khi lý trí nhận ra. Đừng bỏ qua cảm giác bất an bên trong bạn.\"}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(238, 40, 'reflection', '{\"question\": \"Bạn có từng cảm thấy sợ hãi hoặc căng thẳng trước phản ứng của một người bạn thân chưa?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(239, 40, 'takeaway', '{\"items\": [\"Mối quan hệ tốt giúp bạn thấy nhẹ lòng, chứ không phải nơm nớp lo sợ.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(240, 41, 'hook', '{\"title\": \"Liệu chúng ta có phải từ bỏ cá tính của mình để đổi lấy một tình bạn?\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(241, 41, 'explanation', '{\"bullets\": [\"Lành mạnh nghĩa là bạn được là chính mình, với cả ưu điểm và khuyết điểm.\", \"Bạn có thể thay đổi để tốt lên, nhưng không phải vì bị ép buộc hay nịnh bợ.\", \"Một người thực sự quý bạn sẽ yêu thích con người thật của bạn chứ không phải một phiên bản giả tạo.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(242, 41, 'scenario', '{\"title\": \"Mái tóc mới\", \"body\": \"Bách thích cắt tóc ngắn năng động, nhưng bạn bè trong nhóm nói tóc ngắn trông kì cục và bắt Bách phải nuôi tóc dài lại để hợp với nhóm.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(243, 41, 'interaction', '{\"question\": \"Bách nên làm gì?\", \"choices\": [{\"text\": \"Nghe theo nhóm để không bị cô lập.\", \"correct\": false, \"emoji\": \"🙁\"}, {\"text\": \"Giữ kiểu tóc mình thích và nhẹ nhàng bảo: Tớ thấy thoải mái với kiểu này nhất.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(244, 41, 'reflection', '{\"question\": \"Bạn đã bao giờ giả vờ thích một thứ chỉ để giống với nhóm bạn chưa?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(245, 41, 'takeaway', '{\"items\": [\"Người trân trọng bạn sẽ yêu quý con người thật, chứ không bắt bạn thành bản sao của họ.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(246, 42, 'hook', '{\"title\": \"Học cách từ chối áp lực từ nhóm bạn mà vẫn giữ được sự kết nối.\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(247, 42, 'explanation', '{\"bullets\": [\"Áp lực đồng trang lứa là có thật, đặc biệt là mong muốn hòa nhập nhóm.\", \"Tuy nhiên, đồng thuận và tự nguyện vẫn luôn là yếu tố quyết định.\", \"Đặt ranh giới từ chối một hoạt động không có nghĩa là bạn ghét họ.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(248, 42, 'scenario', '{\"title\": \"Chiếc áo đắt đỏ\", \"body\": \"Nhóm bạn rủ nhau mua áo nhóm có giá khá đắt. Chi không đủ tiền tiêu vặt, nhưng sợ nếu nói không mua sẽ bị xem là \'nghèo\' và bị đẩy ra rìa.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(249, 42, 'sorting', '{\"instruction\": \"Hãy phân loại các hành vi ứng phó áp lực đồng trang lứa sau:\", \"leftBox\": {\"title\": \"Ứng phó lành mạnh\"}, \"rightBox\": {\"title\": \"Áp lực bắt chước\"}, \"items\": [{\"text\": \"Nói thật về điều kiện kinh tế của mình và đề xuất giải pháp\", \"correctBox\": \"left\"}, {\"text\": \"Cố gắng vay nợ để mua bằng được món đồ đắt đỏ giống bạn\", \"correctBox\": \"right\"}, {\"text\": \"Tự tin mặc trang phục theo sở thích cá nhân\", \"correctBox\": \"left\"}, {\"text\": \"Ép bản thân làm điều mình không thích để được nhóm chấp nhận\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(250, 42, 'reflection', '{\"question\": \"Bạn đã bao giờ gặp khó khăn khi phải nói thật về hoàn cảnh hay cảm xúc của mình với bạn bè chưa?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(251, 42, 'takeaway', '{\"items\": [\"Bạn bè chân chính tôn trọng khả năng và ranh giới của bạn, chứ không ép bạn đua đòi.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(252, 43, 'hook', '{\"title\": \"Làm thế nào để vừa là một phần của nhóm, vừa là chính mình?\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(253, 43, 'explanation', '{\"bullets\": [\"Đầu tiên, xác định sở thích cá nhân của bạn.\", \"Thứ hai, cởi mở chia sẻ sự khác biệt một cách tự tin và vui vẻ.\", \"Thứ ba, tôn trọng sở thích của người khác và mong đợi sự tôn trọng ngược lại.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(254, 43, 'scenario', '{\"title\": \"Nhạc gì cũng được?\", \"body\": \"Nhóm bạn thích nghe nhạc K-pop sôi động, riêng Hoàng lại thích nghe nhạc Indie nhẹ nhàng. Khi được hỏi ý kiến, Hoàng tự tin giới thiệu bài nhạc Indie yêu thích của mình.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(255, 43, 'interaction', '{\"question\": \"Sự tự tin của Hoàng đem lại kết quả gì?\", \"choices\": [{\"text\": \"Giúp nhóm có thêm lựa chọn âm nhạc thú vị và tôn trọng cá tính riêng của Hoàng.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Hoàng sẽ bị nhóm tẩy chay vì gu âm nhạc khác biệt.\", \"correct\": false, \"emoji\": \"🙁\"}]}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(256, 43, 'reflection', '{\"question\": \"Bạn có sẵn sàng chia sẻ sở thích độc lạ của mình với bạn bè xung quanh không?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(257, 43, 'takeaway', '{\"items\": [\"Cá tính riêng làm nên sự thú vị của bạn. Hãy tự tin tỏa sáng theo cách của mình!\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(258, 44, 'hook', '{\"title\": \"Bạn có bao giờ đợi người ta nói xong chỉ để nhảy vào cãi lại?\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(259, 44, 'explanation', '{\"bullets\": [\"Lắng nghe chủ động là tập trung hiểu cảm xúc và ý kiến của đối phương.\", \"Tránh cắt ngang lời khi họ đang chia sẻ suy nghĩ.\", \"Đặt câu hỏi để làm rõ nếu bạn chưa chắc chắn: Có phải ý cậu là...?\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(260, 44, 'scenario', '{\"title\": \"Tâm sự điểm kém\", \"body\": \"Vân khóc kể với Nam về việc bị điểm kém môn Toán. Nam lập tức bảo: Ôi giời, có thế cũng khóc, lần sau học chăm lên là được chứ gì.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(261, 44, 'flashcard', '{\"front\": \"Lắng nghe chủ động (Active Listening) khi bạn bè tâm sự là gì?\", \"back\": \"Là tập trung hoàn toàn để hiểu cảm xúc đối phương, không cắt ngang hay phán xét, và đặt câu hỏi làm rõ nếu cần thiết.\", \"notes\": \"Lắng nghe là món quà tuyệt vời nhất bạn có thể trao tặng.\"}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(262, 44, 'reflection', '{\"question\": \"Bạn từng bị người khác gạt phắt đi cảm xúc khi đang cố tâm sự chưa?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(263, 44, 'takeaway', '{\"items\": [\"Lắng nghe là món quà tuyệt vời nhất bạn có thể tặng cho người đang chia sẻ.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(264, 45, 'hook', '{\"title\": \"Dùng từ ngữ khéo léo để biến một lời trách móc thành một cuộc trò chuyện cởi mở.\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(265, 45, 'explanation', '{\"bullets\": [\"Câu bắt đầu bằng \'Cậu\' dễ mang lại cảm giác đổ lỗi: Cậu lúc nào cũng..., Cậu làm hỏng... \", \"Dùng cấu trúc bắt đầu bằng \'Tớ\' để nói về cảm xúc của bạn: Tớ thấy buồn khi..., Tớ lo lắng vì...\", \"Điều này giúp đối phương bớt phòng thủ và dễ thấu hiểu hơn.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(266, 45, 'scenario', '{\"title\": \"Lỗi trễ hẹn\", \"body\": \"Duy hẹn Linh đi uống nước nhưng lại đến trễ 30 phút mà không báo trước. Linh rất giận.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(267, 45, 'sorting', '{\"instruction\": \"Hãy phân loại câu nói của bạn Linh sau đây vào đúng hộp cảm xúc:\", \"leftBox\": {\"title\": \"Bày tỏ bằng câu bắt đầu bằng Tớ\"}, \"rightBox\": {\"title\": \"Đổ lỗi bằng câu bắt đầu bằng Cậu\"}, \"items\": [{\"text\": \"Tớ thấy hơi hụt hẫng khi phải chờ lâu mà không nghe báo trước\", \"correctBox\": \"left\"}, {\"text\": \"Cậu lúc nào cũng cao su, thiếu tôn trọng giờ giấc của người khác\", \"correctBox\": \"right\"}, {\"text\": \"Tớ lo lắng khi thấy cậu đến muộn mà không gọi được điện thoại\", \"correctBox\": \"left\"}, {\"text\": \"Cậu cố tình bắt tớ leo cây để làm tớ bực mình đúng không\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(268, 45, 'reflection', '{\"question\": \"Bạn thấy bản thân có hay vô tình dùng những câu trách móc \'Cậu thế này, cậu thế nọ\' khi tức giận không?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(269, 45, 'takeaway', '{\"items\": [\"Chia sẻ cảm xúc của mình (dùng Tớ) thay vì đổ lỗi cho người khác (dùng Cậu).\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(270, 46, 'hook', '{\"title\": \"Khi cơn tức giận lên đỉnh điểm, im lặng tạm thời chính là một siêu năng lực.\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(271, 46, 'explanation', '{\"bullets\": [\"Lúc nóng giận, não bộ dễ đưa ra những lời nói sát thương gây hối hận sau này.\", \"Học cách nhận biết cơn giận: tim đập nhanh, mặt nóng lên.\", \"Chủ động xin tạm dừng: Tụi mình đang nóng, để chiều nói tiếp nha.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(272, 46, 'scenario', '{\"title\": \"Tranh cãi nhóm\", \"body\": \"Quân và Trang tranh cãi gay gắt về phân chia công việc trong nhóm. Cả hai bắt đầu to tiếng và dùng những từ ngữ xúc phạm nhau.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(273, 46, 'interaction', '{\"question\": \"Ai nên là người xin tạm dừng?\", \"choices\": [{\"text\": \"Cả hai đều có thể dừng lại và hẹn thảo luận sau khi bình tĩnh.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Trang nên chịu đựng và nghe Quân xả hết giận rồi tính tiếp.\", \"correct\": false, \"emoji\": \"🙁\"}]}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(274, 46, 'reflection', '{\"question\": \"Bạn có hay nói ra những lời hối hận khi đang nóng giận với người thân thiết không?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(275, 46, 'takeaway', '{\"items\": [\"Hạ nhiệt cơn giận trước khi tìm cách giải quyết mâu thuẫn.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(276, 47, 'hook', '{\"title\": \"Nhắn tin chữ không có cảm xúc, rất dễ khiến tình cảm sứt mẻ vì hiểu lầm.\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(277, 47, 'explanation', '{\"bullets\": [\"Tin nhắn thiếu tông giọng, nét mặt dễ bị suy diễn theo hướng tiêu cực.\", \"Hạn chế tranh cãi những chuyện nghiêm trọng qua tin nhắn chữ.\", \"Gặp mặt trực tiếp hoặc gọi điện video là cách tốt nhất để hòa giải.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(278, 47, 'scenario', '{\"title\": \"Từ \'Ừ\' lạnh lùng\", \"body\": \"Linh nhắn tin rủ Vy đi chơi, Vy chỉ rep vỏn vẹn chữ \'Ừ\'. Linh nghĩ Vy đang ghét mình nên đâm ra giận dỗi, trong khi Vy chỉ đang bận học bài.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(279, 47, 'interaction', '{\"question\": \"Linh nên xử lý thế nào cho đúng tinh thần Green Flag?\", \"choices\": [{\"text\": \"Im lặng và hủy kết bạn luôn với Vy cho bõ ghét.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Gọi điện hỏi thăm: Cậu đang bận hả? Lúc nãy thấy rep ngắn tớ cứ sợ cậu có chuyện gì.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(280, 47, 'reflection', '{\"question\": \"Bạn từng giận dỗi ai đó chỉ vì suy diễn nội dung tin nhắn chưa?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(281, 47, 'takeaway', '{\"items\": [\"Đừng suy diễn tin nhắn. Hãy hỏi trực tiếp bằng giọng nói ấm áp.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(282, 48, 'hook', '{\"title\": \"Mối quan hệ bền vững không phải không có mâu thuẫn, mà là biết cách làm hòa.\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(283, 48, 'explanation', '{\"bullets\": [\"Bước 1: Chấp nhận lỗi sai và xin lỗi chân thành, không bao biện.\", \"Bước 2: Lắng nghe cảm nhận của đối phương về lỗi sai đó.\", \"Bước 3: Cùng đưa ra giải pháp cụ thể để không lặp lại lỗi cũ.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(284, 48, 'scenario', '{\"title\": \"Lỡ miệng kể bí mật\", \"body\": \"An vô tình kể chuyện thầm kín của Bình cho nhóm bạn biết. Bình rất giận và thất vọng về An.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(285, 48, 'flashcard', '{\"front\": \"Quy tắc hòa giải mâu thuẫn gồm những bước nào?\", \"back\": \"Bước 1: Chấp nhận lỗi sai và xin lỗi chân thành; Bước 2: Lắng nghe cảm nhận đối phương; Bước 3: Cùng đưa ra giải pháp khắc phục.\", \"notes\": \"Lời xin lỗi chân thành đi kèm hành động cụ thể mới có thể chữa lành vết thương.\"}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(286, 48, 'reflection', '{\"question\": \"Bạn có thấy khó khăn khi phải nói lời xin lỗi trước với bạn bè không?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(287, 48, 'takeaway', '{\"items\": [\"Lời xin lỗi chân thành đi kèm hành động khắc phục mới có thể chữa lành vết thương.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(288, 49, 'hook', '{\"title\": \"Ranh giới cá nhân không phải là bức tường ngăn cách, mà là cánh cửa để mọi người biết cách bước vào.\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(289, 49, 'explanation', '{\"bullets\": [\"Ranh giới vật lý: quyền quyết định ai được đụng chạm vào cơ thể bạn.\", \"Ranh giới cảm xúc: quyền giữ những suy nghĩ riêng, nói không khi thấy quá tải.\", \"Mỗi người có một vòng tròn ranh giới rộng hẹp khác nhau, cần được tôn trọng.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(290, 49, 'scenario', '{\"title\": \"Những cái ôm bất ngờ\", \"body\": \"Vy thích khoác vai bạn bè, nhưng Linh lại thấy khó chịu khi bị đụng chạm đột ngột. Linh phân vân không biết có nên nói thẳng với Vy không.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(291, 49, 'flashcard', '{\"front\": \"Ranh giới cá nhân (Personal Boundaries) là gì và gồm những loại nào?\", \"back\": \"Là những giới hạn bạn đặt ra để tự bảo vệ sự thoải mái của mình. Gồm: Ranh giới cơ thể (ai được đụng chạm) và Ranh giới cảm xúc (giữ suy nghĩ riêng, biết từ chối khi thấy quá tải).\", \"notes\": \"Thiết lập ranh giới giúp mọi người biết cách tôn trọng bạn.\"}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(292, 49, 'reflection', '{\"question\": \"Bạn có ranh giới nào về mặt cơ thể hoặc không gian riêng tư mà bạn không muốn ai vượt qua không?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(293, 49, 'takeaway', '{\"items\": [\"Ranh giới của bạn là do bạn quyết định. Người thực sự quý bạn sẽ tôn trọng nó.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(294, 50, 'hook', '{\"title\": \"Lòng tin giống như một cây non, cần thời gian tưới tắm mới lớn khôn.\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(295, 50, 'explanation', '{\"bullets\": [\"Lòng tin được xây dựng từ những hành động nhỏ nhất: giữ đúng lời hứa, đi học đúng giờ.\", \"Lòng tin dễ vỡ và rất khó để lấy lại sau khi bị phản bội.\", \"Tin tưởng không có nghĩa là mù quáng bỏ qua mọi nghi ngờ.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(296, 50, 'scenario', '{\"title\": \"Giữ bí mật\", \"body\": \"Minh kể với Hoàng về việc mình đang thầm thích một bạn lớp bên, nhờ Hoàng giữ bí mật. Hôm sau, cả lớp đều xì xầm bàn tán về chuyện này.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(297, 50, 'interaction', '{\"question\": \"Hành động của Hoàng ảnh hưởng thế nào đến lòng tin?\", \"choices\": [{\"text\": \"Phá vỡ lòng tin của Minh và làm rạn nứt tình bạn giữa hai người.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Không sao cả, chuyện nhỏ nhặt này kể cho vui tai thôi mà.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(298, 50, 'reflection', '{\"question\": \"Bạn đã bao giờ hối hận vì trao lòng tin nhầm người chưa?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(299, 50, 'takeaway', '{\"items\": [\"Lòng tin cần được xây dựng qua hành động nhất quán, chứ không qua lời hứa suông.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(300, 51, 'hook', '{\"title\": \"Tôn trọng người khác bắt đầu từ việc tôn trọng sự riêng tư của họ.\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(301, 51, 'explanation', '{\"bullets\": [\"Không tự ý đọc tin nhắn, xem nhật ký hay lục lọi đồ đạc của bạn bè.\", \"Chấp nhận sự khác biệt về quan điểm, tôn giáo hay sở thích.\", \"Luôn hỏi ý kiến trước khi chia sẻ ảnh của bạn bè lên mạng xã hội.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(302, 51, 'scenario', '{\"title\": \"Bức ảnh dìm hàng\", \"body\": \"Quân tự ý đăng bức ảnh chụp lúc Vy đang ngáp ngủ lên trang cá nhân làm trò đùa. Vy thấy vô cùng xấu hổ và yêu cầu Quân gỡ xuống.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(303, 51, 'sorting', '{\"instruction\": \"Hãy phân loại hành vi sau vào hộp Tôn trọng hay Xâm phạm quyền riêng tư:\", \"leftBox\": {\"title\": \"Tôn trọng riêng tư\"}, \"rightBox\": {\"title\": \"Xâm phạm riêng tư\"}, \"items\": [{\"text\": \"Luôn hỏi ý kiến bạn trước khi chia sẻ ảnh của bạn lên mạng\", \"correctBox\": \"left\"}, {\"text\": \"Tự ý đọc trộm nhật ký hoặc tin nhắn điện thoại của bạn\", \"correctBox\": \"right\"}, {\"text\": \"Gõ cửa trước khi vào phòng riêng của người khác\", \"correctBox\": \"left\"}, {\"text\": \"Lục lọi cặp sách, ví tiền của bạn để xem có gì\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(304, 51, 'reflection', '{\"question\": \"Bạn đã bao giờ bị bạn bè chia sẻ hình ảnh hoặc bí mật cá nhân lên mạng mà chưa hỏi ý kiến chưa?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(305, 51, 'takeaway', '{\"items\": [\"Tôn trọng quyền riêng tư là thể hiện sự trưởng thành và văn minh trong mối quan hệ.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(306, 52, 'hook', '{\"title\": \"Chia sẻ mật khẩu tài khoản mạng xã hội có phải là bằng chứng của tình yêu chân chính?\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(307, 52, 'explanation', '{\"bullets\": [\"Mật khẩu cá nhân là ranh giới riêng tư tuyệt đối, bảo vệ danh tính của bạn.\", \"Đòi mật khẩu để kiểm soát tin nhắn là dấu hiệu của sự thiếu lòng tin.\", \"Yêu thương lành mạnh tôn trọng không gian cá nhân của nhau.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(308, 52, 'scenario', '{\"title\": \"Đòi mật khẩu\", \"body\": \"Nam yêu cầu Trang đưa mật khẩu Facebook để chứng minh Trang không nhắn tin với bạn nam khác. Trang thấy không thoải mái.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(309, 52, 'interaction', '{\"question\": \"Trang nên phản hồi thế nào để bảo vệ ranh giới cá nhân?\", \"choices\": [{\"text\": \"Đành đưa mật khẩu cho Nam để tránh cãi vã.\", \"correct\": false, \"emoji\": \"🙁\"}, {\"text\": \"Từ chối: Tớ yêu cậu nhưng tớ muốn giữ quyền riêng tư cá nhân. Tụi mình nên tin tưởng nhau thay vì kiểm soát mật khẩu.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(310, 52, 'reflection', '{\"question\": \"Bạn có sẵn sàng chia sẻ mật khẩu cá nhân của mình cho bạn bè hoặc người yêu không?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(311, 52, 'takeaway', '{\"items\": [\"Yêu thương không đồng nghĩa với việc từ bỏ quyền riêng tư cơ bản của bản thân.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(312, 53, 'hook', '{\"title\": \"Học cách nói \'Không\' dứt khoát nhưng không làm tổn thương mối quan hệ.\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(313, 53, 'explanation', '{\"bullets\": [\"Sử dụng ngôn ngữ cơ thể: nhìn thẳng mắt đối phương, đứng thẳng.\", \"Dùng lời nói ngắn gọn, rõ ràng: Tớ không thoải mái với điều này.\", \"Không cần phải giải thích dông dài hay xin lỗi vì đã đặt ranh giới.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(314, 53, 'scenario', '{\"title\": \"Lời rủ rê trốn học\", \"body\": \"Nhóm bạn rủ Duy trốn tiết học thêm để đi chơi game. Duy muốn ở lại ôn thi nhưng sợ bị nhóm gọi là nhát gan.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(315, 53, 'interaction', '{\"question\": \"Duy nên từ chối thế nào cho hiệu quả?\", \"choices\": [{\"text\": \"Tớ bận tí việc gia đình... chắc không đi được... xin lỗi nhé.\", \"correct\": false, \"emoji\": \"🙁\"}, {\"text\": \"Tớ cần ôn thi cho bài kiểm tra ngày mai rồi. Các cậu đi chơi vui vẻ nhé!\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(316, 53, 'reflection', '{\"question\": \"Bạn thấy bản thân có dễ dàng nói lời từ chối trước lời rủ rê của bạn thân không?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(317, 53, 'takeaway', '{\"items\": [\"Đặt ranh giới là bảo vệ chính mình, không phải là ích kỷ hay xa cách bạn bè.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(318, 54, 'hook', '{\"title\": \"Gần gũi không chỉ là đụng chạm cơ thể. Đó còn là sự kết nối giữa hai tâm hồn.\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(319, 54, 'explanation', '{\"bullets\": [\"Thân mật cảm xúc là cảm giác an toàn khi chia sẻ bí mật, ước mơ hay nỗi sợ.\", \"Được lắng nghe và thấu cảm mà không sợ bị phán xét.\", \"Xây dựng tình bạn bền chặt cũng cần sự thân mật cảm xúc này.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(320, 54, 'scenario', '{\"title\": \"Chia sẻ áp lực học tập\", \"body\": \"Vy tâm sự với Nam về nỗi sợ thi trượt cấp 3 và áp lực từ kỳ vọng của bố mẹ. Nam yên lặng lắng nghe, nắm tay động viên Vy.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(321, 54, 'flashcard', '{\"front\": \"Sự thân mật cảm xúc (Emotional Intimacy) là gì?\", \"back\": \"Là cảm giác an toàn và tin cậy tuyệt đối để mở lòng chia sẻ những bí mật, ước mơ hay nỗi sợ với người khác mà không lo sợ bị phán xét hay chế giễu.\", \"notes\": \"Thân mật cảm xúc là nền tảng bền chặt nhất cho mọi mối quan hệ.\"}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(322, 54, 'reflection', '{\"question\": \"Bạn có một người bạn thân nào sẵn sàng lắng nghe mọi tâm tư thầm kín của bạn không?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(323, 54, 'takeaway', '{\"items\": [\"Kết nối cảm xúc là chìa khóa mở cánh cửa cho một tình bạn hay tình yêu lâu dài.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(324, 55, 'hook', '{\"title\": \"Làm sao phân biệt giữa việc cực kỳ thích chơi cùng bạn thân và việc đã cảm nắng họ?\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(325, 55, 'explanation', '{\"bullets\": [\"Tình bạn thân: muốn chia sẻ niềm vui, cùng đi học, đi chơi chung cả nhóm.\", \"Tình cảm lãng mạn (Crush/Yêu): cảm xúc rạo rực, muốn ở riêng bên nhau, có sự thu hút giới tính.\", \"Sự nhầm lẫn cảm xúc ở tuổi teen là rất bình thường, hãy cho bản thân thời gian suy ngẫm.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(326, 55, 'scenario', '{\"title\": \"Cảm giác lạ\", \"body\": \"An nhận ra dạo gần đây mình hay đỏ mặt khi đứng gần Linh và luôn để ý xem Linh nhắn tin với ai. Trước đó hai đứa là đôi bạn thân từ nhỏ.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(327, 55, 'sorting', '{\"instruction\": \"Hãy phân loại cảm xúc của bạn An sau đây vào đúng hộp:\", \"leftBox\": {\"title\": \"Tình bạn thân thiết\"}, \"rightBox\": {\"title\": \"Tình cảm cảm nắng (Crush)\"}, \"items\": [{\"text\": \"Muốn học nhóm chung, đi chơi cùng nhóm bạn đông vui\", \"correctBox\": \"left\"}, {\"text\": \"Tim đập nhanh, đỏ mặt lúng túng khi đứng gần đối phương\", \"correctBox\": \"right\"}, {\"text\": \"Chia sẻ chuyện trường lớp thoải mái và tự nhiên\", \"correctBox\": \"left\"}, {\"text\": \"Hay tò mò nhìn trộm đối phương và để ý xem họ đang nhắn tin với ai\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(328, 55, 'reflection', '{\"question\": \"Bạn từng bị nhầm lẫn cảm xúc giữa một tình bạn rất thân và một tình yêu học trò chưa?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(329, 55, 'takeaway', '{\"items\": [\"Nhận diện đúng cảm xúc giúp bạn ứng xử phù hợp và bảo vệ tình bạn quý giá.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(330, 56, 'hook', '{\"title\": \"Đừng để nhịp độ của người khác ép buộc bước đi của chính bạn.\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(331, 56, 'explanation', '{\"bullets\": [\"Mỗi người có tốc độ phát triển tâm sinh lý và mức độ sẵn sàng khác nhau.\", \"Bạn có quyền từ chối các đụng chạm thân mật (ôm, hôn) nếu thấy chưa sẵn sàng.\", \"Yêu thương lành mạnh không ép buộc hay dùng tình cảm để mặc cả.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(332, 56, 'scenario', '{\"title\": \"Đòi nụ hôn đầu\", \"body\": \"Quân thúc ép Trang cho Quân hôn má để chứng minh Trang yêu Quân thực lòng. Trang thấy lo lắng và chưa muốn làm việc đó.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(333, 56, 'interaction', '{\"question\": \"Trang nên phản ứng thế nào?\", \"choices\": [{\"text\": \"Nhắm mắt cho Quân hôn một cái để Quân không giận nữa.\", \"correct\": false, \"emoji\": \"🙁\"}, {\"text\": \"Nói rõ: Tớ quý cậu nhưng tớ chưa sẵn sàng cho việc này. Tụi mình cứ từ từ nhé.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(334, 56, 'reflection', '{\"question\": \"Bạn có cảm thấy áp lực khi thấy bạn bè xung quanh đã hẹn hò hoặc có người yêu hết rồi không?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(335, 56, 'takeaway', '{\"items\": [\"Mức độ sẵn sàng của bạn là ranh giới cao nhất. Không ai có quyền thúc ép bạn.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(336, 57, 'hook', '{\"title\": \"Đột ngột đụng chạm cơ thể có thể làm hỏng khoảnh khắc lãng mạn.\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(337, 57, 'explanation', '{\"bullets\": [\"Tự ý nắm tay hay bá vai khi đối phương chưa sẵn sàng dễ gây cảm giác khó chịu.\", \"Quan sát phản ứng cơ thể của họ: có rụt tay lại, có tránh né ánh mắt?\", \"Cách an toàn nhất là hỏi han nhẹ nhàng trước khi thực hiện hành động.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(338, 57, 'scenario', '{\"title\": \"Nắm tay dạo phố\", \"body\": \"Duy và Vy đang đi dạo. Duy định đưa tay nắm lấy tay Vy nhưng nhận thấy Vy đang ôm khư khư chiếc balo trước ngực.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(339, 57, 'interaction', '{\"question\": \"Vy đang phát đi tín hiệu gì và Duy nên làm thế nào?\", \"choices\": [{\"text\": \"Vy đang muốn Duy giật lấy balo hộ. Duy nên chủ động giật balo ra rồi nắm tay.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Vy đang giữ ranh giới phòng thủ. Duy nên đi bên cạnh trò chuyện tiếp và hỏi han thoải mái.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(340, 57, 'reflection', '{\"question\": \"Bạn có từng lúng túng khi đối phương đột ngột nắm tay hoặc ôm lấy mình ở chỗ đông người chưa?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(341, 57, 'takeaway', '{\"items\": [\"Hành vi đụng chạm cần có tín hiệu đèn xanh từ cả hai phía để thực sự lãng mạn.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(342, 58, 'hook', '{\"title\": \"Có rất nhiều cách để xích lại gần nhau mà không cần chạm vào cơ thể.\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(343, 58, 'explanation', '{\"bullets\": [\"Cùng nhau làm bài tập, học nhóm hoặc tham gia hoạt động ngoại khóa.\", \"Viết thư tay chia sẻ cảm xúc, tặng những món quà handmade nhỏ xinh.\", \"Chia sẻ danh sách bài hát yêu thích, cùng xem một bộ phim hay trò chuyện sâu sắc.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(344, 58, 'scenario', '{\"title\": \"Playlist nhạc tặng bạn\", \"body\": \"Hoàng tự tay làm một playlist nhạc chứa các bài hát mang thông điệp vui tươi để tặng Vân khi biết Vân đang buồn chuyện gia đình.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(345, 58, 'flashcard', '{\"front\": \"Làm thế nào để gắn kết tình cảm phi thể xác lành mạnh?\", \"back\": \"Thông qua các hành động tinh tế như viết thư tay chia sẻ cảm xúc, tự làm playlist bài hát tặng nhau, cùng đi nhà sách học bài hoặc trao đổi những món quà handmade nhỏ.\", \"notes\": \"Có rất nhiều cách để xích lại gần nhau mà không cần đụng chạm cơ thể.\"}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(346, 58, 'reflection', '{\"question\": \"Cách bày tỏ sự quan tâm yêu thích của bạn đối với người thân thiết thường là gì?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(347, 58, 'takeaway', '{\"items\": [\"Sự thấu hiểu và sẻ chia tinh thần là chất keo bền chặt nhất gắn kết hai người.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(348, 59, 'hook', '{\"title\": \"Đồng thuận không chỉ áp dụng cho người lớn. Đó là quy tắc tôn trọng cơ bản ở mọi lứa tuổi.\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(349, 59, 'explanation', '{\"bullets\": [\"Đồng thuận là sự đồng ý tự nguyện, hào hứng và rõ ràng từ cả hai phía.\", \"Đồng ý khi bị ép buộc, đe dọa hay nài nỉ không được coi là đồng thuận.\", \"Quy tắc F.R.I.E.S: Tự nguyện, Linh hoạt, Đầy đủ thông tin, Hào hứng, Cụ thể.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(350, 59, 'scenario', '{\"title\": \"Đồng ý vì nể bạn\", \"body\": \"Nam rủ Linh vào góc tối công viên nói chuyện. Linh ngập ngừng nói: Cũng được... nếu cậu muốn. Nhưng tay Linh bấu chặt vào vạt áo, mắt nhìn xuống đất.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(351, 59, 'flashcard', '{\"front\": \"Quy tắc F.R.I.E.S biểu diễn 5 tiêu chí nào của sự đồng thuận?\", \"back\": \"F - Freely given (Tự nguyện), R - Reversible (Linh hoạt, dễ đổi ý), I - Informed (Đầy đủ thông tin), E - Enthusiastic (Hào hứng), S - Specific (Cụ thể cho từng hành vi).\", \"notes\": \"Thiếu bất kỳ yếu tố nào trong 5 từ trên đều không được coi là sự đồng thuận lành mạnh.\"}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(352, 59, 'reflection', '{\"question\": \"Bạn từng đồng ý làm điều gì đó chỉ vì đối phương nài nỉ quá nhiều chưa?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(353, 59, 'takeaway', '{\"items\": [\"Chỉ có tiếng Có hào hứng và tự nguyện mới là đèn xanh để đi tiếp.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(354, 60, 'hook', '{\"title\": \"Đôi khi sự im lặng hoặc tránh né chứa đựng câu trả lời \'Không\' khó nói.\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(355, 60, 'explanation', '{\"bullets\": [\"Tín hiệu Đèn Vàng: ngập ngừng, cười trừ, im lặng, tránh ánh mắt, người cứng đờ.\", \"Khi thấy đèn vàng, bạn có nghĩa vụ phải dừng lại và check-in cảm xúc đối phương.\", \"Tiếp tục thực hiện hành động khi đối phương có đèn vàng là vi phạm ranh giới.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(356, 60, 'scenario', '{\"title\": \"Cúi đầu tránh né\", \"body\": \"Hoàng định nắm tay Chi khi đi xem phim. Chi không gạt tay ra nhưng cúi đầu, rụt tay sát người và im lặng.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(357, 60, 'sorting', '{\"instruction\": \"Hãy phân loại tín hiệu cảm xúc của đối phương vào đúng hộp:\", \"leftBox\": {\"title\": \"Đèn Xanh (Đồng thuận xịn)\"}, \"rightBox\": {\"title\": \"Đèn Vàng (Cần dừng check-in)\"}, \"items\": [{\"text\": \"Mỉm cười rạng rỡ và chủ động tiến lại gần bạn\", \"correctBox\": \"left\"}, {\"text\": \"Im lặng tránh ánh mắt, người cứng đờ\", \"correctBox\": \"right\"}, {\"text\": \"Nói câu \'Tớ cũng muốn\' một cách hào hứng\", \"correctBox\": \"left\"}, {\"text\": \"Nói câu \'Cũng được...\' nhưng nét mặt lo âu bứt rứt\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(358, 60, 'reflection', '{\"question\": \"Bạn có bao giờ dùng sự im lặng hoặc tránh né để biểu đạt sự từ chối của mình chưa?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(359, 60, 'takeaway', '{\"items\": [\"Im lặng không phải là đồng ý. Đó có thể là lúc đối phương đang cần bạn dừng lại.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(360, 61, 'hook', '{\"title\": \"Đồng thuận không phải là một giao kèo vĩnh viễn. Bạn được quyền đổi ý bất cứ lúc nào.\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(361, 61, 'explanation', '{\"bullets\": [\"Đồng thuận có tính linh hoạt (Reversible). Giây trước nói có, giây sau nói không là hoàn toàn bình thường.\", \"Đối phương phải lập tức dừng lại khi bạn nói dừng.\", \"Bạn không bao giờ phải cảm thấy tội lỗi khi đổi ý để bảo vệ sự thoải mái của mình.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(362, 61, 'scenario', '{\"title\": \"Dừng lại giữa chừng\", \"body\": \"Trang đồng ý để Quân ôm mình. Nhưng khi Quân ôm hơi chặt, Trang thấy ngạt thở và đẩy nhẹ Quân ra: Khoan đã Quân, tớ thấy hơi nhanh.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(363, 61, 'interaction', '{\"question\": \"Phản ứng nào của Quân là Green Flag xịn?\", \"choices\": [{\"text\": \"Giận dỗi: Ơ hay, nãy đồng ý rồi mà giờ lại thế?\", \"correct\": false, \"emoji\": \"🙁\"}, {\"text\": \"Dừng lại ngay, nới lỏng tay: Tớ xin lỗi, tớ làm cậu khó chịu hả?\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(364, 61, 'reflection', '{\"question\": \"Bạn có thấy sợ hãi khi muốn thay đổi quyết định của mình trong một nhóm bạn không?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(365, 61, 'takeaway', '{\"items\": [\"Bạn luôn có quyền quay xe. Cơ thể và ranh giới của bạn là của riêng bạn.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(366, 62, 'hook', '{\"title\": \"Cưỡng hôn bất ngờ có thực sự lãng mạn như trên phim ảnh?\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(367, 62, 'explanation', '{\"bullets\": [\"Phim ảnh thường lãng mạn hóa các hành động tự ý đụng chạm thân mật.\", \"Ngoài đời thực, tự ý hôn khi chưa được cho phép dễ gây cảm giác sợ hãi và bị xúc phạm.\", \"Hỏi ý kiến trước khi hôn là tôn trọng tối thiểu đối phương.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(368, 62, 'scenario', '{\"title\": \"Nụ hôn bất chợt\", \"body\": \"Quân định cưỡng hôn Vy khi hai đứa đang ngồi nói chuyện riêng. Vy giật mình, đẩy mạnh Quân ra và tỏ vẻ giận dữ.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(369, 62, 'interaction', '{\"question\": \"Hành vi của Quân là gì?\", \"choices\": [{\"text\": \"Là thể hiện tình cảm mãnh liệt lãng mạn.\", \"correct\": false, \"emoji\": \"🙁\"}, {\"text\": \"Là xâm hại ranh giới cá nhân khi chưa có sự đồng thuận.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(370, 62, 'reflection', '{\"question\": \"Bạn có nghĩ rằng việc hỏi xin phép trước khi hôn làm mất đi sự bất ngờ lãng mạn không?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(371, 62, 'takeaway', '{\"items\": [\"Lãng mạn chỉ có giá trị khi đi kèm sự an toàn và đồng thuận tự nguyện từ hai phía.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(372, 63, 'hook', '{\"title\": \"Làm thế nào để hỏi ý kiến người ta mà không khiến bầu không khí bị sượng trân?\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(373, 63, 'explanation', '{\"bullets\": [\"Hỏi ý kiến không làm giảm đi sự ngọt ngào của khoảnh khắc.\", \"Hỏi han tinh tế thể hiện bạn quan tâm chân thành đến cảm giác của người ta.\", \"Hãy dùng những câu hỏi ngắn gọn, tự nhiên: Tớ nắm tay cậu được không?, Cậu thấy thoải mái chứ?\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(374, 63, 'scenario', '{\"title\": \"Ý định nắm tay\", \"body\": \"Duy muốn nắm tay Linh khi hai đứa đang đi dạo. Thay vì tự ý chụp lấy, Duy nhìn Linh và mỉm cười nhẹ.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(375, 63, 'interaction', '{\"question\": \"Giúp Duy chọn câu hỏi check-in mượt nhất nhé:\", \"choices\": [{\"text\": \"Đưa tay đây tớ nắm xem nào.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Tớ nắm tay cậu được không?\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(376, 63, 'reflection', '{\"question\": \"Bạn có cảm thấy tự tin hơn khi biết đối phương cũng hoàn toàn hào hứng muốn nắm tay mình?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(377, 63, 'takeaway', '{\"items\": [\"Check-in tinh tế thể hiện sự tôn trọng và tạo ra sự tin tưởng tuyệt đối giữa hai bạn.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(378, 64, 'hook', '{\"title\": \"Cảm giác crush một người có gì kỳ lạ mà khiến đầu óc bạn cứ lơ lửng trên mây?\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(379, 64, 'explanation', '{\"bullets\": [\"Crush là cảm xúc say nắng, ngưỡng mộ hoặc bị thu hút mạnh mẽ bởi ai đó.\", \"Bạn có thể đỏ mặt, ngượng ngùng hoặc hồi hộp mỗi khi nhìn thấy họ.\", \"Đây là một trải nghiệm lớn lên tự nhiên, đẹp đẽ và hết sức bình thường của tuổi teen.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(380, 64, 'scenario', '{\"title\": \"Bức thư tình giấu kín\", \"body\": \"Chi luôn lén nhìn Hoàng trong giờ ra chơi và dành hàng giờ để vẽ những hình trái tim nhỏ trong sổ tay, phân vân có nên thổ lộ không.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(381, 64, 'flashcard', '{\"front\": \"Cảm giác say nắng (Crush) một người có bình thường không?\", \"back\": \"Hoàn toàn bình thường! Đó là một trải nghiệm lớn lên tự nhiên, đẹp đẽ và hết sức tự nhiên của tuổi dậy thì.\", \"notes\": \"Bạn không cần phải cảm thấy xấu hổ hay áp lực vì cảm xúc này.\"}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(382, 64, 'reflection', '{\"question\": \"Bạn đang crush một ai đó trong trường hoặc lớp học của mình chứ?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(383, 64, 'takeaway', '{\"items\": [\"Crush là cảm xúc ngọt ngào giúp bạn nhận ra trái tim mình đã biết rung động.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(384, 65, 'hook', '{\"title\": \"Buổi hẹn đầu tiên nên chuẩn bị những gì để vừa vui vẻ vừa an toàn?\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(385, 65, 'explanation', '{\"bullets\": [\"Chọn địa điểm công cộng quen thuộc: quán trà sữa, công viên đông người.\", \"Tự chuẩn bị chi phí đi lại của mình để giữ tính chủ động.\", \"Báo trước cho một người bạn thân hoặc gia đình biết địa điểm bạn đến.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(386, 65, 'scenario', '{\"title\": \"Lời rủ rê lúc nửa đêm\", \"body\": \"Bách rủ Vy đi chơi riêng lúc 10 giờ đêm tại một bãi đất trống vắng vẻ ngoại ô thành phố.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(387, 65, 'interaction', '{\"question\": \"Vy nên làm thế nào?\", \"choices\": [{\"text\": \"Đồng ý đi luôn vì muốn chứng minh mình dũng cảm.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Từ chối và gợi ý: Giờ đó muộn rồi, chiều mai tụi mình đi uống trà sữa ở quán gần trường nha.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(388, 65, 'reflection', '{\"question\": \"Bạn thường thích chọn địa điểm nào nhất cho một buổi hẹn đi chơi với bạn bè?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(389, 65, 'takeaway', '{\"items\": [\"An toàn là điều kiện tiên quyết cho mọi cuộc hẹn hò vui vẻ.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(390, 66, 'hook', '{\"title\": \"Từ chối (Rejection) là một phần tất yếu của cuộc sống. Nó đau, nhưng nó dạy tụi mình trưởng thành.\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(391, 66, 'explanation', '{\"bullets\": [\"Bị từ chối không có nghĩa là bạn kém cỏi hay xấu xí.\", \"Mọi người đều có quyền từ chối tình cảm của người khác, giống như bạn vậy.\", \"Cho phép bản thân buồn, khóc, nhưng đừng dằn vặt hay hạ thấp giá trị bản thân.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(392, 66, 'scenario', '{\"title\": \"Lời từ chối lịch sự\", \"body\": \"Minh tỏ tình với Chi, Chi nhẹ nhàng từ chối: Tớ trân trọng tình cảm của cậu, nhưng hiện tại tớ chỉ muốn tập trung học tập thôi.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(393, 66, 'sorting', '{\"instruction\": \"Hãy phân loại cách đối xử sau khi bị từ chối vào đúng hộp:\", \"leftBox\": {\"title\": \"Green Flag (Văn minh)\"}, \"rightBox\": {\"title\": \"Red Flag (Độc hại)\"}, \"items\": [{\"text\": \"Chấp nhận, tôn trọng quyết định của họ và giữ khoảng cách lịch sự\", \"correctBox\": \"left\"}, {\"text\": \"Khóc lóc ăn vạ, liên tục nài nỉ làm phiền bắt họ đổi ý\", \"correctBox\": \"right\"}, {\"text\": \"Tâm sự nỗi buồn với bạn bè thân thiết hoặc viết nhật ký\", \"correctBox\": \"left\"}, {\"text\": \"Đi nói xấu hoặc tung tin đồn thất thiệt để trả đũa đối phương\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(394, 66, 'reflection', '{\"question\": \"Bạn đã bao giờ trải qua cảm giác bị từ chối trong học tập hoặc tình cảm chưa?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(395, 66, 'takeaway', '{\"items\": [\"Lời từ chối của người khác là ranh giới của họ. Tôn trọng ranh giới là tôn trọng chính mình.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(396, 67, 'hook', '{\"title\": \"Làm thế nào để giữ mối quan hệ bạn bè bình thường sau một lần tỏ tình thất bại?\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(397, 67, 'explanation', '{\"bullets\": [\"Đừng cố gắng tỏ ra không có chuyện gì xảy ra một cách gượng ép.\", \"Cho cả hai không gian riêng để cảm xúc bình lặng lại.\", \"Khi gặp lại, hãy cư xử lịch sự, tự nhiên, tránh trêu chọc hay làm sượng không khí.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(398, 67, 'scenario', '{\"title\": \"Cuộc chạm mặt ở hành lang\", \"body\": \"Sau khi bị Vân từ chối, Hoàng cảm thấy vô cùng sượng ngùng mỗi khi chạm mặt Vân ở hành lang lớp học.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(399, 67, 'interaction', '{\"question\": \"Hoàng nên làm thế nào khi chạm mặt Vân?\", \"choices\": [{\"text\": \"Cúi mặt đi thẳng, giả vờ như không thấy Vân.\", \"correct\": false, \"emoji\": \"🙁\"}, {\"text\": \"Gật đầu mỉm cười nhẹ nhàng chào Vân rồi bước tiếp.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(400, 67, 'reflection', '{\"question\": \"Bạn có sẵn lòng làm bạn lại với một người đã từng từ chối tình cảm của mình không?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(401, 67, 'takeaway', '{\"items\": [\"Ứng xử văn minh sau khi tỏ tình thất bại thể hiện sự tôn trọng và bản lĩnh của bạn.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(402, 68, 'hook', '{\"title\": \"Từ chối tình cảm của người khác mà không làm họ tổn thương sâu sắc.\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(403, 68, 'explanation', '{\"bullets\": [\"Nói lời cảm ơn vì họ đã trân trọng mình.\", \"Bày tỏ rõ ràng, dứt khoát quyết định của bản thân, tránh mập mờ thả thính.\", \"Dùng từ ngữ lịch sự, nhẹ nhàng nhưng không tạo ra hy vọng giả.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(404, 68, 'scenario', '{\"title\": \"Hộp quà sô-cô-la\", \"body\": \"Bình tặng sô-cô-la tỏ tình với Vy. Vy không thích Bình nhưng không muốn Bình phải xấu hổ trước lớp.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(405, 68, 'flashcard', '{\"front\": \"Làm thế nào để từ chối tình cảm của người khác một cách khéo léo?\", \"back\": \"Bước 1: Cảm ơn họ đã trân trọng mình. Bước 2: Bày tỏ rõ ràng, dứt khoát quyết định của bản thân để không tạo hy vọng giả. Bước 3: Giữ thái độ lịch sự nhẹ nhàng.\", \"notes\": \"Từ chối rõ ràng là sự tử tế cao nhất để tránh làm mất thời gian của nhau.\"}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(406, 68, 'reflection', '{\"question\": \"Bạn từng phải từ chối tình cảm của ai bao giờ chưa? Bạn thấy điều đó có khó khăn không?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(407, 68, 'takeaway', '{\"items\": [\"Từ chối rõ ràng là sự tử tế cao nhất để đối phương không phí thời gian hy vọng.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(408, 69, 'hook', '{\"title\": \"Cờ đỏ (Red Flag) là những tín hiệu cảnh báo bạn nên dừng lại và xem xét mối quan hệ.\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(409, 69, 'explanation', '{\"bullets\": [\"Kiểm soát quá mức: đòi biết mọi tin nhắn, bắt báo cáo lịch trình.\", \"Ghen tuông bệnh lý: cấm cản nói chuyện với mọi người khác giới.\", \"Hạ thấp đối phương: chê bai ngoại hình, năng lực trước đám đông.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(410, 69, 'scenario', '{\"title\": \"Bắt báo cáo lịch trình\", \"body\": \"Nam bắt Trang phải chụp ảnh gửi qua Zalo mỗi khi Trang đi chơi với bất kỳ ai để kiểm tra xem Trang có nói dối không.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(411, 69, 'sorting', '{\"instruction\": \"Hãy phân loại các hành vi ứng xử vào đúng hộp:\", \"leftBox\": {\"title\": \"Lành mạnh (Green Flag)\"}, \"rightBox\": {\"title\": \"Cờ Đỏ (Red Flag)\"}, \"items\": [{\"text\": \"Khuyên bạn đi học đúng giờ và chúc bạn làm bài tốt\", \"correctBox\": \"left\"}, {\"text\": \"Bắt bạn phải chụp hình gửi qua Zalo báo cáo vị trí liên tục\", \"correctBox\": \"right\"}, {\"text\": \"Khuyến khích bạn duy trì mối quan hệ tốt với bạn bè\", \"correctBox\": \"left\"}, {\"text\": \"Cấm đoán bạn nói chuyện hay gặp mặt tất cả những người khác giới\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(412, 69, 'reflection', '{\"question\": \"Bạn từng thấy bạn bè xung quanh bị người yêu cấm đoán đi chơi chung với nhóm bạn chưa?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(413, 69, 'takeaway', '{\"items\": [\"Yêu thương tôn trọng sự tự do cá nhân của nhau, chứ không giam lỏng bằng ghen tuông.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(414, 70, 'hook', '{\"title\": \"Tại sao nhiều người lại chấp nhận ở lại trong một mối quan hệ làm họ đau lòng hết lần này đến lần khác?\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(415, 70, 'explanation', '{\"bullets\": [\"Vòng lặp bạo lực cảm xúc: Giận dỗi/Gây hấn -> Xin lỗi/Tặng quà mật ngọt -> Bình yên giả tạo -> Tiếp tục gây hấn.\", \"Lời ngọt ngào sau cơn giận dễ khiến nạn nhân quên đi tổn thương cũ.\", \"Nhận diện vòng lặp này để tìm cách cắt đứt.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(416, 70, 'scenario', '{\"title\": \"Lời hứa ngọt ngào\", \"body\": \"Lâm vừa quát mắng Lan thậm tệ vì Lan đi học nhóm muộn. Hôm sau Lâm mua trà sữa mang đến tận lớp, khóc lóc hứa hẹn sẽ thay đổi.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(417, 70, 'flashcard', '{\"front\": \"Vòng lặp bạo lực cảm xúc (Abuse Cycle) gồm những giai đoạn nào?\", \"back\": \"Giai đoạn 1: Giận dỗi/Gây hấn ➡️ Giai đoạn 2: Xin lỗi khóc lóc/Tặng quà mật ngọt ➡️ Giai đoạn 3: Bình yên giả tạo ➡️ Tiếp tục gây hấn.\", \"notes\": \"Lời hứa ngọt ngào sau cơn giận không xóa nhòa được bạo lực cảm xúc.\"}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(418, 70, 'reflection', '{\"question\": \"Bạn có thấy quen thuộc với những người bạn cứ cãi nhau to rồi lại làm hòa ngọt ngào liên tục không?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(419, 70, 'takeaway', '{\"items\": [\"Quà cáp ngọt ngào không thể xóa nhòa sự thiếu tôn trọng và bạo lực cảm xúc.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(420, 71, 'hook', '{\"title\": \"Mối quan hệ nên là nơi nương tựa, chứ không phải một cuộc chiến mệt mỏi mỗi ngày.\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(421, 71, 'explanation', '{\"bullets\": [\"Cảm thấy kiệt sức, mất tự tin sau mỗi lần nói chuyện với họ.\", \"Luôn phải nhún nhường, bỏ qua mong muốn của bản thân để họ vui vẻ.\", \"Mối quan hệ mang lại nhiều nước mắt hơn tiếng cười là lúc cần dừng lại.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(422, 71, 'scenario', '{\"title\": \"Mất đi nụ cười\", \"body\": \"Lan nhận ra dạo gần đây mình hay cáu gắt với mọi người xung quanh và học lực sa sút kể từ khi nhận lời yêu Lâm.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(423, 71, 'interaction', '{\"question\": \"Lan nên làm gì?\", \"choices\": [{\"text\": \"Tiếp tục chịu đựng và cố gắng làm hài lòng Lâm nhiều hơn.\", \"correct\": false, \"emoji\": \"🙁\"}, {\"text\": \"Chia sẻ với bố mẹ/bạn bè và xem xét việc kết thúc mối quan hệ mệt mỏi này.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(424, 71, 'reflection', '{\"question\": \"Bạn có cảm thấy năng lượng tích cực của mình bị hút cạn bởi một người bạn độc hại nào không?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(425, 71, 'takeaway', '{\"items\": [\"Bảo vệ sức khỏe tinh thần của bạn quan trọng hơn việc giữ một mối quan hệ độc hại.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(426, 72, 'hook', '{\"title\": \"Khi người yêu muốn bạn là thế giới duy nhất của họ, hãy cẩn thận.\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(427, 72, 'explanation', '{\"bullets\": [\"Hành vi cấm cản chơi với bạn thân, cô lập bạn khỏi gia đình là dấu hiệu kiểm soát độc hại.\", \"Họ muốn bạn hoàn toàn phụ thuộc vào họ về mặt tình cảm.\", \"Mối quan hệ lành mạnh khuyến khích bạn duy trì các mối quan hệ xã hội tốt đẹp khác.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(428, 72, 'scenario', '{\"title\": \"Cấm chơi với bạn thân\", \"body\": \"Hoàng yêu cầu Vy không được đi uống nước với nhóm bạn thân cấp 2 vì Hoàng cảm thấy ghen và không thích nhóm đó.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(429, 72, 'interaction', '{\"question\": \"Vy nên làm gì?\", \"choices\": [{\"text\": \"Nghe theo Hoàng để Hoàng được an lòng, tránh cãi nhau.\", \"correct\": false, \"emoji\": \"🙁\"}, {\"text\": \"Từ chối: Tớ trân trọng tình cảm của cậu, nhưng bạn bè cũng rất quan trọng với tớ. Tớ vẫn sẽ đi chơi với họ.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(430, 72, 'reflection', '{\"question\": \"Bạn từng thấy ai đó bỏ bê hoàn toàn bạn bè xung quanh sau khi có người yêu chưa?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(431, 72, 'takeaway', '{\"items\": [\"Một người yêu thương bạn thật lòng sẽ tôn trọng các mối quan hệ xã hội lành mạnh của bạn.\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(432, 73, 'hook', '{\"title\": \"Chia tay một mối quan hệ độc hại cần sự dứt khoát và an toàn.\"}', 1, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(433, 73, 'explanation', '{\"bullets\": [\"Nói lời chia tay rõ ràng, dứt khoát ở nơi công cộng hoặc qua tin nhắn nếu sợ bị phản ứng bạo lực.\", \"Cắt đứt liên lạc, chặn tài khoản mạng xã hội để tránh bị làm phiền.\", \"Tìm kiếm sự giúp đỡ của bố mẹ, thầy cô hoặc gọi 111 nếu bị đe dọa bám đuôi.\"]}', 2, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(434, 73, 'scenario', '{\"title\": \"Lời đe dọa chia tay\", \"body\": \"Khi Lan đòi chia tay, Lâm đe dọa sẽ đăng những ảnh riêng tư của Lan lên mạng xã hội hoặc tự làm đau bản thân.\"}', 3, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(435, 73, 'flashcard', '{\"front\": \"Làm sao để bước ra an toàn khỏi mối quan hệ độc hại bị đe dọa?\", \"back\": \"Nói chia tay ở nơi công cộng hoặc qua tin nhắn nếu sợ bạo lực, cắt liên lạc (chặn tài khoản), và báo ngay cho bố mẹ/thầy cô hoặc gọi Tổng đài 111.\", \"notes\": \"Bạn không bao giờ cô đơn, luôn có sự hỗ trợ xung quanh!\"}', 4, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(436, 73, 'reflection', '{\"question\": \"Nếu một người bạn thân của bạn đang gặp nguy hiểm trong mối quan hệ, bạn sẵn sàng giúp họ tìm kiếm sự hỗ trợ chứ?\"}', 5, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(437, 73, 'takeaway', '{\"items\": [\"Bạn không bao giờ phải đối mặt với nguy hiểm một mình. Hãy mạnh dạn tìm kiếm sự trợ giúp xung quanh!\"]}', 6, '2026-06-05 10:27:59', '2026-06-05 10:27:59'),
(438, 74, 'hook', '{\"title\": \"Bạn có biết mỗi lần lướt mạng, bạn đều đang để lại một dấu chân không bao giờ biến mất?\"}', 1, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(439, 74, 'explanation', '{\"bullets\": [\"Dấu chân số (Digital Footprint) là lịch sử hoạt động của bạn trên Internet: bài đăng, lượt like, comment, và tìm kiếm.\", \"Ngay cả khi bạn bấm nút Xóa, thông tin đó vẫn có thể đã được người khác chụp màn hình hoặc lưu lại.\", \"Hãy suy nghĩ kỹ trước khi nhấn nút Đăng.\"]}', 2, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(440, 74, 'scenario', '{\"title\": \"Bức ảnh dìm biến mất?\", \"body\": \"Nam đăng một bức ảnh dìm hài hước của đứa em họ lên mạng. Dù Nam đã xóa sau 5 phút, bức ảnh đã bị một người bạn tải về và gửi vào nhóm chat của lớp.\"}', 3, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(441, 74, 'flashcard', '{\"front\": \"Liệu có thể xóa hoàn toàn một thứ gì đó trên Internet không?\", \"back\": \"Rất tiếc là KHÔNG. Khi thông tin đã lên mạng, nó có thể được lưu trữ, chụp màn hình hoặc chia sẻ lại bất kỳ lúc nào.\", \"notes\": \"Hãy luôn tự hỏi: Mình có ổn không nếu bức ảnh/dòng trạng thái này tồn tại mãi mãi?\"}', 4, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(442, 74, 'reflection', '{\"question\": \"Bạn có từng đăng thứ gì lên mạng rồi sau đó cuống cuồng xóa đi vì thấy không nên chưa?\"}', 5, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(443, 74, 'takeaway', '{\"items\": [\"Internet có trí nhớ siêu tốt. Hãy để lại những dấu chân số mà bạn tự hào nhé!\"]}', 6, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(444, 75, 'hook', '{\"title\": \"Tại sao việc chia sẻ địa chỉ nhà hay thời khóa biểu lên mạng lại là một ý tưởng tồi?\"}', 1, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(445, 75, 'explanation', '{\"bullets\": [\"Những thông tin như số điện thoại, mật khẩu, địa chỉ nhà, tên trường học và lộ trình đi lại là thông tin cá nhân nhạy cảm.\", \"Kẻ xấu có thể dùng chúng để định vị, theo dõi hoặc giả mạo danh tính của bạn.\", \"Giữ bí mật những thông tin này chính là chiếc khiên bảo vệ bạn khỏi các nguy cơ ngoài đời thực.\"]}', 2, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(446, 75, 'scenario', '{\"title\": \"Thẻ học sinh mới\", \"body\": \"Vy rất vui khi nhận được thẻ học sinh mới nên đã chụp ảnh khoe lên Story, lộ rõ họ tên, mã số học sinh và tên trường THCS đang học.\"}', 3, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(447, 75, 'interaction', '{\"question\": \"Vy đăng ảnh như vậy có an toàn không?\", \"choices\": [{\"text\": \"Không an toàn. Kẻ xấu có thể biết Vy học trường nào để tiếp cận hoặc quấy rối.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"An toàn mà, chỉ có bạn bè trên mạng mới xem được thôi.\", \"correct\": false, \"emoji\": \"🙁\"}]}', 4, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(448, 75, 'reflection', '{\"question\": \"Hãy kiểm tra lại trang cá nhân của bạn, có thông tin nào tiết lộ nơi bạn đang sinh sống hoặc học tập không?\"}', 5, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(449, 75, 'takeaway', '{\"items\": [\"Bảo mật thông tin cá nhân chính là bảo vệ sự an toàn của chính mình ngoài đời thực.\"]}', 6, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(450, 76, 'hook', '{\"title\": \"Tại sao tụi mình luôn có cảm giác thèm thuồng được đăng tất tần tật mọi thứ lên mạng?\"}', 1, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(451, 76, 'explanation', '{\"bullets\": [\"Lượt like, thả tim kích thích não bộ tiết ra dopamine, khiến tụi mình cảm thấy được quan tâm và công nhận.\", \"Áp lực từ bạn bè (ai cũng đăng thì mình cũng đăng) khiến bạn dễ chia sẻ quá đà (oversharing).\", \"Lắng nghe cảm xúc của mình trước khi đăng bài: Bạn đang thực sự muốn kết nối hay chỉ cần sự chú ý tức thời?\"]}', 2, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(452, 76, 'scenario', '{\"title\": \"Status lúc buồn\", \"body\": \"Linh cảm thấy cô đơn vì bố mẹ bận việc. Linh định đăng một status buồn bã kể chi tiết chuyện gia đình cãi nhau để nhận được sự an ủi từ bạn bè.\"}', 3, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(453, 76, 'sorting', '{\"instruction\": \"Hãy phân loại các hành vi đăng bài sau đây vào hộp phù hợp:\", \"leftBox\": {\"title\": \"Chia sẻ lành mạnh\"}, \"rightBox\": {\"title\": \"Chia sẻ quá đà\"}, \"items\": [{\"text\": \"Đăng ảnh chú mèo đáng yêu mới nuôi\", \"correctBox\": \"left\"}, {\"text\": \"Đăng ảnh chụp màn hình tin nhắn cãi nhau riêng tư với bạn thân\", \"correctBox\": \"right\"}, {\"text\": \"Đăng cảm nghĩ sau khi xem một bộ phim hay\", \"correctBox\": \"left\"}, {\"text\": \"Đăng số điện thoại của người khác để nhờ mọi người spam hộ\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(454, 76, 'reflection', '{\"question\": \"Bạn có bao giờ hối hận vì đã lỡ đăng một dòng trạng thái quá riêng tư lúc tâm trạng bất ổn không?\"}', 5, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(455, 76, 'takeaway', '{\"items\": [\"Không phải mọi cảm xúc đều cần được phơi bày trên mạng xã hội. Hãy giữ lại những khoảng riêng cho mình.\"]}', 6, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(456, 77, 'hook', '{\"title\": \"Bạn có thấy ổn khi bạn bè tự ý đăng ảnh dìm, ảnh xấu của bạn lên mạng mà không hỏi trước?\"}', 1, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(457, 77, 'explanation', '{\"bullets\": [\"Nhiều người nghĩ đăng ảnh dìm là đùa vui, nhưng đùa chỉ vui khi tất cả mọi người cùng cười.\", \"Tự ý đăng ảnh của người khác lên mạng là vi phạm quyền riêng tư của họ.\", \"Tôn trọng người khác bắt đầu từ việc hỏi ý kiến trước khi đăng ảnh có mặt họ.\"]}', 2, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(458, 77, 'scenario', '{\"title\": \"Khoảnh khắc ngáp ngủ\", \"body\": \"Trong buổi dã ngoại, Minh chụp được ảnh Khoa đang ngáp ngủ há to miệng. Minh thấy buồn cười và đăng lên mạng kèm caption trêu chọc. Khoa thấy rất xấu hổ.\"}', 3, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(459, 77, 'flashcard', '{\"front\": \"Bạn nên làm gì nếu bạn bè đăng ảnh dìm của bạn mà bạn không thích?\", \"back\": \"Hãy nói chuyện trực tiếp hoặc nhắn tin riêng một cách nhẹ nhàng nhưng rõ ràng: Cậu xóa bức ảnh đó giúp tớ nhé, tớ không thoải mái khi ảnh đó bị đăng lên mạng đâu.\", \"notes\": \"Bạn bè thực sự sẽ tôn trọng cảm xúc của bạn và xóa ảnh ngay lập tức.\"}', 4, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(460, 77, 'reflection', '{\"question\": \"Bạn đã từng tự ý đăng ảnh dìm của bạn bè chỉ vì nghĩ nó vui chưa? Họ có thực sự vui không?\"}', 5, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(461, 77, 'takeaway', '{\"items\": [\"Đùa vui chỉ thực sự vui khi người trong cuộc cảm thấy thoải mái và đồng ý.\"]}', 6, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(462, 78, 'hook', '{\"title\": \"Đã bao lâu rồi bạn chưa dọn dẹp danh sách bạn bè và cài đặt bảo mật của mình?\"}', 1, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(463, 78, 'explanation', '{\"bullets\": [\"Để tài khoản ở chế độ công khai (Public) nghĩa là bất kỳ ai, kể cả người lạ, cũng có thể xem và tải ảnh của bạn về.\", \"Hãy lọc lại danh sách bạn bè: chỉ kết bạn với những người bạn thực sự quen biết ngoài đời.\", \"Sử dụng mật khẩu mạnh và bật xác thực 2 lớp (2FA) để bảo vệ tài khoản khỏi bị hack.\"]}', 2, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(464, 78, 'scenario', '{\"title\": \"Bị lấy ảnh đi lừa đảo\", \"body\": \"Tài khoản của Mai để chế độ công khai. Một ngày nọ, Mai phát hiện có một tài khoản lạ lấy toàn bộ ảnh của mình để đi lừa đảo nạp thẻ cào.\"}', 3, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(465, 78, 'interaction', '{\"question\": \"Mai nên làm gì để tránh tình trạng này lặp lại?\", \"choices\": [{\"text\": \"Chuyển tài khoản sang chế độ riêng tư (Private) và chỉ kết bạn với người quen biết.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tiếp tục để công khai nhưng viết bài cảnh báo trên trang cá nhân.\", \"correct\": false, \"emoji\": \"🙁\"}]}', 4, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(466, 78, 'reflection', '{\"question\": \"Danh sách bạn bè trên mạng của bạn có bao nhiêu người là người lạ mà bạn chưa từng nói chuyện ngoài đời?\"}', 5, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(467, 78, 'takeaway', '{\"items\": [\"Khóa bớt cửa (bảo mật riêng tư) giúp ngôi nhà ảo của bạn an toàn hơn nhiều.\"]}', 6, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(468, 79, 'hook', '{\"title\": \"Ai mới là người có quyền tối cao quyết định những gì xuất hiện trên mạng xã hội của bạn?\"}', 1, '2026-06-05 12:18:20', '2026-06-05 12:18:20');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(469, 79, 'explanation', '{\"bullets\": [\"Bạn chính là người biên tập và quản lý cuộc sống số của mình.\", \"Bạn có quyền từ chối yêu cầu kết bạn, hủy kết bạn (unfriend) hoặc chặn (block) bất kỳ ai khiến bạn thấy không thoải mái.\", \"Bảo vệ không gian mạng của bạn không phải là ích kỷ, đó là quyền tự chăm sóc bản thân.\"]}', 2, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(470, 79, 'scenario', '{\"title\": \"Những tin nhắn thô lỗ\", \"body\": \"Một tài khoản lạ liên tục gửi tin nhắn bình phẩm thô lỗ về ngoại hình của Lan dưới các bài đăng của cô ấy.\"}', 3, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(471, 79, 'sorting', '{\"instruction\": \"Phân loại các hành động quản lý không gian số sau:\", \"leftBox\": {\"title\": \"Bảo vệ lành mạnh\"}, \"rightBox\": {\"title\": \"Cố chịu đựng\"}, \"items\": [{\"text\": \"Chặn một người liên tục nhắn tin trêu chọc thô lỗ\", \"correctBox\": \"left\"}, {\"text\": \"Vẫn rep tin nhắn của người lạ dù thấy sợ hãi vì sợ bị nói là kiêu\", \"correctBox\": \"right\"}, {\"text\": \"Hủy kết bạn với những tài khoản không còn tương tác hoặc không quen\", \"correctBox\": \"left\"}, {\"text\": \"Để người khác tự ý tag mình vào các bài viết quảng cáo độc hại\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(472, 79, 'reflection', '{\"question\": \"Bạn có cảm thấy áy náy khi phải block hoặc unfriend một ai đó mang lại năng lượng độc hại không?\"}', 5, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(473, 79, 'takeaway', '{\"items\": [\"Bạn là chủ nhân tài khoản của mình. Bạn có quyền quyết định ai được phép bước vào thế giới số của bạn.\"]}', 6, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(474, 80, 'hook', '{\"title\": \"Tại sao nói chuyện trên mạng lại dễ gây hiểu lầm hơn là gặp mặt trực tiếp?\"}', 1, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(475, 80, 'explanation', '{\"bullets\": [\"Khi nhắn tin, tụi mình thiếu đi biểu cảm gương mặt, ngôn ngữ cơ thể và tông giọng của đối phương.\", \"Một câu đùa tinh nghịch khi viết thành chữ có thể nghe như một lời mỉa mai lạnh lùng.\", \"Đọc kỹ tin nhắn và cố gắng không suy diễn tiêu cực khi chưa rõ ý người viết.\"]}', 2, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(476, 80, 'scenario', '{\"title\": \"Tin nhắn ngắn gọn\", \"body\": \"An nhắn tin rủ Bình đi chơi đá bóng. Bình đang bận làm bài tập nên nhắn lại ngắn gọn: Không đi. An nghĩ Bình đang giận dỗi mình nên cũng im lặng luôn.\"}', 3, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(477, 80, 'flashcard', '{\"front\": \"Làm sao để giảm thiểu hiểu lầm khi giao tiếp qua tin nhắn chữ?\", \"back\": \"Sử dụng thêm emoji để thể hiện cảm xúc, tránh nhắn tin cộc lốc, và nếu thấy bất an, hãy gọi điện hoặc hỏi trực tiếp để làm rõ.\", \"notes\": \"Một emoji đúng chỗ có thể cứu vãn cả một tình bạn đấy!\"}', 4, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(478, 80, 'reflection', '{\"question\": \"Bạn có từng giận dỗi ai đó chỉ vì đọc tin nhắn cộc lốc của họ chưa?\"}', 5, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(479, 80, 'takeaway', '{\"items\": [\"Chữ viết không có tông giọng. Hãy thêm một chút ấm áp bằng biểu cảm hoặc hỏi lại cho rõ nhé.\"]}', 6, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(480, 81, 'hook', '{\"title\": \"Chữ Ừ hay Ok trong tin nhắn của bạn bè có thực sự đáng sợ như bạn nghĩ?\"}', 1, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(481, 81, 'explanation', '{\"bullets\": [\"Mỗi người có phong cách nhắn tin khác nhau: có người thích viết dài kèm emoji, có người thích viết ngắn gọn.\", \"Đừng vội kết luận đối phương đang ghét mình chỉ qua một tin nhắn ngắn.\", \"Thay vì lo lắng suy diễn, hãy chủ động hỏi thăm nhẹ nhàng.\"]}', 2, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(482, 81, 'scenario', '{\"title\": \"Vy gửi bài hát\", \"body\": \"Vy gửi một bài hát yêu thích cho bạn thân. Bạn thân chỉ rep lại: Ok. Vy cảm thấy hụt hẫng và nghĩ bạn mình không còn quan tâm đến mình.\"}', 3, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(483, 81, 'interaction', '{\"question\": \"Vy nên phản ứng thế nào để giữ mối quan hệ lành mạnh?\", \"choices\": [{\"text\": \"Tự nhắc mình có thể bạn đang bận, và lúc khác sẽ hỏi cảm nhận của bạn sau.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Nhắn tin trách móc bạn hờ hững hoặc im lặng không nhắn tin nữa.\", \"correct\": false, \"emoji\": \"🙁\"}]}', 4, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(484, 81, 'reflection', '{\"question\": \"Bạn thuộc tuýp người nhắn tin cộc lốc hay thích dùng nhiều emoji/icon?\"}', 5, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(485, 81, 'takeaway', '{\"items\": [\"Mỗi người nhắn tin một kiểu. Đừng để những ký tự ngắn ngủi làm rạn nứt tình cảm.\"]}', 6, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(486, 82, 'hook', '{\"title\": \"Bạn có cảm thấy nghẹt thở khi nhìn thấy chữ Đã xem (Seen) mà đối phương không trả lời ngay?\"}', 1, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(487, 82, 'explanation', '{\"bullets\": [\"Điện thoại thông minh khiến tụi mình có cảm giác đối phương phải luôn túc trực 24/7 để rep tin nhắn.\", \"Thực tế, ai cũng có cuộc sống riêng: học tập, làm việc nhà hoặc đơn giản là cần thời gian rời xa màn hình.\", \"Tôn trọng thời gian riêng của người khác và không ép bản thân phải trả lời tin nhắn ngay lập tức nếu đang bận.\"]}', 2, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(488, 82, 'scenario', '{\"title\": \"Seen không rep\", \"body\": \"Duy gửi tin nhắn hỏi bài tập cho Tuấn. Thấy tin nhắn hiện trạng thái Đã xem nhưng 20 phút rồi chưa thấy Tuấn trả lời, Duy thấy rất bực mình.\"}', 3, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(489, 82, 'sorting', '{\"instruction\": \"Phân loại các phản ứng khi đối phương chưa trả lời tin nhắn:\", \"leftBox\": {\"title\": \"Suy nghĩ thấu cảm\"}, \"rightBox\": {\"title\": \"Suy diễn tiêu cực\"}, \"items\": [{\"text\": \"Chắc cậu ấy đang bận học hoặc không cầm điện thoại, lát sẽ rep thôi\", \"correctBox\": \"left\"}, {\"text\": \"Cố tình bơ mình đây mà, để xem ai lì hơn ai\", \"correctBox\": \"right\"}, {\"text\": \"Để điện thoại xuống và đi làm việc khác của mình\", \"correctBox\": \"left\"}, {\"text\": \"Spam liên tục hàng chục tin nhắn hỏi chấm để bắt rep bằng được\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(490, 82, 'reflection', '{\"question\": \"Bạn có thấy bồn chồn hay tội lỗi khi nhìn thấy tin nhắn chưa đọc mà chưa có thời gian rep không?\"}', 5, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(491, 82, 'takeaway', '{\"items\": [\"Ai cũng có quyền ngoại tuyến. Đừng để chế độ đã xem kiểm soát cảm xúc của bạn.\"]}', 6, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(492, 83, 'hook', '{\"title\": \"Làm gì khi cuộc thảo luận nhóm trong group chat lớp bắt đầu biến thành một trận chiến nảy lửa?\"}', 1, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(493, 83, 'explanation', '{\"bullets\": [\"Tranh cãi bằng bàn phím rất dễ leo thang vì ai cũng muốn gõ thật nhanh để tự vệ.\", \"Những từ ngữ xúc phạm viết ra rất khó thu hồi và để lại tổn thương lớn.\", \"Khi thấy group chat bắt đầu nóng lên, hãy là người chủ động kêu gọi mọi người tạm dừng để gặp nhau nói chuyện trực tiếp.\"]}', 2, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(494, 83, 'scenario', '{\"title\": \"Tranh luận bài nhóm\", \"body\": \"Trong nhóm làm bài tập văn, Linh và Nam bất đồng ý kiến về việc chọn chủ đề. Cả hai bắt đầu dùng những câu từ nặng nề công kích cá nhân nhau trước mặt các thành viên khác.\"}', 3, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(495, 83, 'flashcard', '{\"front\": \"Bạn nên làm gì nếu là thành viên chứng kiến group chat bốc hỏa?\", \"back\": \"Nhắn tin xoa dịu: Tụi mình dừng gõ một chút nha. Mai lên lớp gặp nhau nói chuyện trực tiếp 5 phút là xong ngay ấy mà.\", \"notes\": \"Gặp mặt trực tiếp giúp chúng ta nhìn thấy biểu cảm của nhau và dễ thông cảm hơn nhiều.\"}', 4, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(496, 83, 'reflection', '{\"question\": \"Bạn từng tham gia hoặc chứng kiến một trận phím chiến nào trong group chat chưa? Cảm xúc lúc đó thế nào?\"}', 5, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(497, 83, 'takeaway', '{\"items\": [\"Một lời kêu gọi tạm dừng đúng lúc trong group chat có thể ngăn chặn những rạn nứt không đáng có.\"]}', 6, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(498, 84, 'hook', '{\"title\": \"Làm sao để bày tỏ sự không đồng ý mà vẫn khiến đối phương cảm thấy được tôn trọng?\"}', 1, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(499, 84, 'explanation', '{\"bullets\": [\"Thay vì dùng câu khẳng định quy kết: Ý kiến của cậu tệ quá, hãy tập trung vào cảm nhận của bản thân.\", \"Sử dụng cấu trúc: Tớ thấy... khi... kết hợp với từ ngữ nhẹ nhàng.\", \"Lắng nghe ý kiến của họ trước khi đưa ra phản hồi của mình.\"]}', 2, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(500, 84, 'scenario', '{\"title\": \"Góp ý thiết kế slide\", \"body\": \"Minh không thích ý tưởng thiết kế slide thuyết trình của Trang vì nó quá lòe loẹt.\"}', 3, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(501, 84, 'interaction', '{\"question\": \"Minh nên nhắn tin cho Trang thế nào cho đúng tinh thần Green Flag?\", \"choices\": [{\"text\": \"Tớ thấy slide hơi nhiều màu sắc một chút, liệu tụi mình có thể thử tông màu đơn giản hơn xem sao được không Trang?\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Slide này trông trẻ con và lòe loẹt quá, cậu làm lại cái khác đơn giản hơn đi.\", \"correct\": false, \"emoji\": \"🙁\"}]}', 4, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(502, 84, 'reflection', '{\"question\": \"Bạn có thấy dễ chịu hơn khi nhận được lời góp ý nhẹ nhàng thay vì một lời chê bai thẳng thừng không?\"}', 5, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(503, 84, 'takeaway', '{\"items\": [\"Góp ý nhẹ nhàng và tôn trọng giúp công việc trôi chảy và tình bạn khăng khít hơn.\"]}', 6, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(504, 85, 'hook', '{\"title\": \"Làm sao để lướt mạng xã hội mỗi ngày mà không cảm thấy kiệt sức hay tự ti?\"}', 1, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(505, 85, 'explanation', '{\"bullets\": [\"Những gì người khác đăng lên mạng thường chỉ là những khoảnh khắc đẹp đẽ nhất, đã qua chỉnh sửa của họ.\", \"Đừng so sánh cuộc sống thường nhật của bạn với cuốn phim nổi bật của người khác.\", \"Hãy chủ động theo dõi (follow) những tài khoản truyền cảm hứng lành mạnh và nhấn hủy theo dõi các nguồn tin độc hại.\"]}', 2, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(506, 85, 'scenario', '{\"title\": \"So sánh bản thân\", \"body\": \"Hân lướt Tiktok thấy các bạn khoe đồ hiệu, đi du lịch sang chảnh rồi tự nhìn lại bản thân và thấy cuộc sống của mình thật tẻ nhạt, tầm thường.\"}', 3, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(507, 85, 'sorting', '{\"instruction\": \"Phân loại các thói quen sử dụng mạng xã hội sau:\", \"leftBox\": {\"title\": \"Nạp năng lượng tích cực\"}, \"rightBox\": {\"title\": \"Hút cạn năng lượng\"}, \"items\": [{\"text\": \"Theo dõi các trang chia sẻ mẹo học tập, vẽ tranh hoặc lối sống xanh\", \"correctBox\": \"left\"}, {\"text\": \"Liên tục lướt xem ảnh của các hot teen rồi tự ti về ngoại hình của mình\", \"correctBox\": \"right\"}, {\"text\": \"Giới hạn thời gian dùng mạng xã hội dưới 1 tiếng mỗi ngày\", \"correctBox\": \"left\"}, {\"text\": \"Đọc các bài viết drama, bóc phốt và tham gia bình luận chửi bới\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(508, 85, 'reflection', '{\"question\": \"Bạn có cảm thấy mệt mỏi sau khi lướt mạng xã hội quá lâu không?\"}', 5, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(509, 85, 'takeaway', '{\"items\": [\"Bạn là người lựa chọn nguồn năng lượng nạp vào tâm trí mình mỗi ngày qua màn hình điện thoại.\"]}', 6, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(510, 86, 'hook', '{\"title\": \"Bạn có bao giờ cảm thấy ngột ngạt vì một người bạn cứ liên tục nhắn tin hỏi bạn đang làm gì, ở đâu mọi lúc mọi nơi?\"}', 1, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(511, 86, 'explanation', '{\"bullets\": [\"Ranh giới số (Digital Boundary) là những giới hạn bạn đặt ra về thời gian, không gian và mức độ riêng tư khi sử dụng công nghệ.\", \"Nó bao gồm việc quyết định khi nào bạn online, ai được phép gọi cho bạn, và bạn muốn chia sẻ những gì.\", \"Đặt ranh giới rõ ràng giúp bạn duy trì những mối quan hệ khỏe mạnh mà không cảm thấy bị kiểm soát.\"]}', 2, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(512, 86, 'scenario', '{\"title\": \"Spam cuộc gọi\", \"body\": \"Nam thích chơi game vào buổi tối để thư giãn. Tuy nhiên, Khánh liên tục gọi video cho Nam để buôn chuyện, dù Nam đã nói là đang bận chơi game. Khánh giận dỗi bảo Nam không coi trọng bạn.\"}', 3, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(513, 86, 'flashcard', '{\"front\": \"Đặt ranh giới số có phải là ích kỷ hay làm tổn thương tình bạn không?\", \"back\": \"KHÔNG. Đặt ranh giới giúp cả hai hiểu rõ giới hạn thoải mái của nhau, từ đó tôn trọng nhau hơn và tránh những xung đột không đáng có.\", \"notes\": \"Tình bạn lành mạnh luôn đi kèm sự tôn trọng ranh giới của nhau.\"}', 4, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(514, 86, 'reflection', '{\"question\": \"Bạn đã từng cảm thấy mệt mỏi vì một người bạn liên tục đòi hỏi sự chú ý của bạn trên mạng chưa?\"}', 5, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(515, 86, 'takeaway', '{\"items\": [\"Ranh giới số không phải là bức tường ngăn cách, nó là cánh cửa giúp tình bạn thở dễ dàng hơn.\"]}', 6, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(516, 87, 'hook', '{\"title\": \"Làm sao nhận ra khi ai đó đang ngấm ngầm xâm phạm ranh giới số của bạn?\"}', 1, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(517, 87, 'explanation', '{\"bullets\": [\"Dấu hiệu bao gồm: kiểm soát danh sách bạn bè, bắt bạn chụp màn hình cuộc trò chuyện với người khác để kiểm chứng, tự ý vào đọc trộm tin nhắn.\", \"Những hành vi này thường được ngụy trang dưới danh nghĩa vì quan tâm hoặc vì yêu thương.\", \"Nhận biết sớm giúp bạn bảo vệ bản thân trước những mối quan hệ độc hại.\"]}', 2, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(518, 87, 'scenario', '{\"title\": \"Đọc trộm tin nhắn\", \"body\": \"Huy mượn điện thoại của bạn gái là Linh để tra cứu bản đồ, nhưng sau đó tự ý mở lịch sử chat Zalo của Linh với các bạn nam khác để kiểm tra xem có nhắn tin mờ ám không.\"}', 3, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(519, 87, 'interaction', '{\"question\": \"Hành vi của Huy là gì?\", \"choices\": [{\"text\": \"Xâm phạm ranh giới cá nhân và thể hiện sự thiếu tin tưởng nghiêm trọng.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Sự quan tâm đáng yêu, vì yêu nên mới ghen và muốn kiểm tra.\", \"correct\": false, \"emoji\": \"🚩\"}]}', 4, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(520, 87, 'reflection', '{\"question\": \"Bạn có cảm thấy thoải mái khi cho người khác (kể cả bạn thân hoặc người yêu) tự ý đọc tin nhắn riêng tư của mình không?\"}', 5, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(521, 87, 'takeaway', '{\"items\": [\"Yêu thương hay tình bạn không đi kèm quyền được kiểm soát và xâm phạm không gian riêng tư của nhau.\"]}', 6, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(522, 88, 'hook', '{\"title\": \"Tại sao tụi mình thường thấy rất tội lỗi khi nhấn nút từ chối một cuộc gọi hoặc không rep tin nhắn ngay?\"}', 1, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(523, 88, 'explanation', '{\"bullets\": [\"Tụi mình sợ làm người khác buồn, sợ bị đánh giá là không nhiệt tình hoặc bị tẩy chay khỏi nhóm bạn.\", \"Nhưng hãy nhớ: năng lượng của bạn là có hạn. Bạn cần nạp lại năng lượng trước khi có thể chia sẻ nó.\", \"Từ chối một yêu cầu không có nghĩa là bạn từ chối con người họ, đó chỉ là bạn đang bảo vệ sức khỏe tinh thần của mình.\"]}', 2, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(524, 88, 'scenario', '{\"title\": \"Ép bản thân online\", \"body\": \"Dù rất mệt sau buổi tập thể thao, Vy vẫn cố thức đến 11h đêm nhắn tin buôn chuyện với nhóm bạn vì sợ nếu off sớm sẽ bị nói là thiếu hòa nhập.\"}', 3, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(525, 88, 'sorting', '{\"instruction\": \"Phân loại các suy nghĩ sau khi bạn cần từ chối giao tiếp để nghỉ ngơi:\", \"leftBox\": {\"title\": \"Tự chăm sóc lành mạnh\"}, \"rightBox\": {\"title\": \"Tự trách độc hại\"}, \"items\": [{\"text\": \"Tớ cần sạc lại năng lượng cho bản thân trước, tớ sẽ nhắn lại cho bạn vào ngày mai\", \"correctBox\": \"left\"}, {\"text\": \"Mình là một đứa bạn tồi tệ vì đã không trả lời tin nhắn của cậu ấy ngay lập tức\", \"correctBox\": \"right\"}, {\"text\": \"Mình có quyền dành một buổi tối không điện thoại để đọc sách hoặc ngủ sớm\", \"correctBox\": \"left\"}, {\"text\": \"Mình phải luôn online để chứng minh mình luôn sẵn sàng vì bạn bè\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(526, 88, 'reflection', '{\"question\": \"Bạn có thường ép bản thân trò chuyện trên mạng ngay cả khi cơ thể và tâm trí đã mệt nhoài không?\"}', 5, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(527, 88, 'takeaway', '{\"items\": [\"Bạn không cần phải làm người khác vui lòng bằng cách bào mòn năng lượng và sự thoải mái của chính mình.\"]}', 6, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(528, 89, 'hook', '{\"title\": \"Nếu là bạn thân/người yêu thực sự thì phải tin tưởng chia sẻ mật khẩu tài khoản mạng xã hội cho nhau chứ? Bạn nghĩ sao?\"}', 1, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(529, 89, 'explanation', '{\"bullets\": [\"Mật khẩu tài khoản là ranh giới riêng tư tối cao của mỗi cá nhân trên không gian số.\", \"Chia sẻ mật khẩu không chứng minh lòng tin, ngược lại nó tạo ra cơ hội cho sự giám sát và nghi ngờ lẫn nhau.\", \"Tình bạn chân chính tôn trọng sự riêng tư của nhau mà không cần những bằng chứng mang tính kiểm soát.\"]}', 2, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(530, 89, 'scenario', '{\"title\": \"Instagram của ai?\", \"body\": \"Quân muốn chứng minh tình cảm với Mai nên đã hỏi xin mật khẩu tài khoản Instagram của Mai. Mai cảm thấy không thoải mái nhưng sợ Quân nghĩ mình đang giấu giếm.\"}', 3, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(531, 89, 'flashcard', '{\"front\": \"Mai nên trả lời Quân thế nào để vừa giữ được ranh giới vừa không gây rạn nứt?\", \"back\": \"Mai có thể nói: Tớ rất trân trọng tình cảm của tụi mình, nhưng tớ muốn giữ mật khẩu tài khoản làm không gian riêng tư cá nhân. Tụi mình tin tưởng nhau bằng hành động ngoài đời nhé.\", \"notes\": \"Giữ bí mật mật khẩu là nguyên tắc an toàn số cơ bản nhất, không ngoại lệ cho bất kỳ ai.\"}', 4, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(532, 89, 'reflection', '{\"question\": \"Bạn có từng chia sẻ mật khẩu tài khoản của mình cho ai chưa? Cảm xúc của bạn sau đó thế nào?\"}', 5, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(533, 89, 'takeaway', '{\"items\": [\"Tin tưởng nhau nằm ở sự tôn trọng tự nguyện, không nằm ở việc bàn giao chìa khóa cuộc sống số của mình cho người khác.\"]}', 6, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(534, 90, 'hook', '{\"title\": \"Làm thế nào để từ chối một lời đề nghị trên mạng một cách lịch sự, rõ ràng mà không phải nói dối quanh co?\"}', 1, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(535, 90, 'explanation', '{\"bullets\": [\"Nói lời từ chối trực tiếp giúp bạn đỡ mệt mỏi và tránh những hiểu lầm dây dưa về sau.\", \"Công thức từ chối: Cảm ơn/Ghi nhận + Lời từ chối rõ ràng + Đề xuất thay thế (nếu muốn).\", \"Tránh viện cớ nói dối vì khi lời nói dối bị phát hiện, mối quan hệ sẽ càng rạn nứt nghiêm trọng hơn.\"]}', 2, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(536, 90, 'scenario', '{\"title\": \"Group chat ẩn danh\", \"body\": \"Nam rủ Vy tham gia một group chat ẩn danh chuyên bàn tán chuyện đời tư của các bạn khác. Vy không muốn tham gia vì thấy điều đó không tốt.\"}', 3, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(537, 90, 'interaction', '{\"question\": \"Vy nên từ chối thế nào cho đúng tinh thần văn minh và cứng rắn?\", \"choices\": [{\"text\": \"Cảm ơn đã rủ nhé, nhưng tớ không thoải mái với việc bàn tán chuyện riêng tư của người khác nên tớ không vào nhóm đâu.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tớ đang bận ôn thi lắm, để khi khác nha (rồi im lặng né tránh).\", \"correct\": false, \"emoji\": \"🙁\"}]}', 4, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(538, 90, 'reflection', '{\"question\": \"Bạn thấy mình thường chọn cách từ chối thẳng thắn hay chọn cách nói dối để né tránh đối đầu?\"}', 5, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(539, 90, 'takeaway', '{\"items\": [\"Một lời từ chối thẳng thắn và lịch sự tốt hơn vạn lần những lời hứa hẹn quanh co làm mất thời gian của nhau.\"]}', 6, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(540, 91, 'hook', '{\"title\": \"Đặt ranh giới rõ ràng thực chất là đang giúp tình bạn kéo dài lâu hơn, bạn tin không?\"}', 1, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(541, 91, 'explanation', '{\"bullets\": [\"Khi không có ranh giới, tụi mình dễ tích tụ những bức bối, ức chế ngầm bên trong (resentment).\", \"Đến một ngày, những bức bối đó sẽ bùng phát thành một trận cãi vã lớn hủy hoại mối quan hệ.\", \"Nói rõ giới hạn của mình từ đầu giúp cả hai hiểu nhau và cư xử tinh tế với nhau hơn.\"]}', 2, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(542, 91, 'scenario', '{\"title\": \"Bất bình tích tụ\", \"body\": \"Hải liên tục mượn nick game của Tùng và đổi cài đặt trang phục mà không hỏi trước. Tùng thấy khó chịu nhưng không nói gì, dần dần Tùng bắt đầu lảng tránh và ghét chơi game chung với Hải.\"}', 3, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(543, 91, 'sorting', '{\"instruction\": \"Phân loại các hành vi thiết lập ranh giới sau:\", \"leftBox\": {\"title\": \"Giúp tình bạn bền vững\"}, \"rightBox\": {\"title\": \"Gây ức chế ngầm\"}, \"items\": [{\"text\": \"Thẳng thắn chia sẻ: Tớ không thích bị trêu về cân nặng đâu nhé\", \"correctBox\": \"left\"}, {\"text\": \"Im lặng chịu đựng khi bạn lấy đồ dùng cá nhân của mình mà không hỏi\", \"correctBox\": \"right\"}, {\"text\": \"Góp ý riêng tư khi thấy bạn có hành động khiến mình không thoải mái\", \"correctBox\": \"left\"}, {\"text\": \"Giả vờ vui vẻ bên ngoài nhưng ấm ức nói xấu sau lưng bạn với người khác\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(544, 91, 'reflection', '{\"question\": \"Bạn có mối quan hệ nào đang khiến bạn thấy ấm ức nhưng chưa dám nói thẳng giới hạn của mình không?\"}', 5, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(545, 91, 'takeaway', '{\"items\": [\"Ranh giới lành mạnh giúp chúng ta yêu quý nhau mà không làm cạn kiệt năng lượng của nhau.\"]}', 6, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(546, 92, 'hook', '{\"title\": \"Im lặng trên mạng có phải là đồng ý không? Làm sao biết đối phương thực sự muốn tham gia trò chuyện?\"}', 1, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(547, 92, 'explanation', '{\"bullets\": [\"Đồng thuận số (Digital Consent) là sự đồng ý hoàn toàn tự nguyện, hào hứng, tỉnh táo và có thể thay đổi bất kỳ lúc nào đối với các hoạt động trực tuyến.\", \"Im lặng, trả lời chậm, hoặc trả lời gượng ép (sao cũng được, ừ chắc thế) KHÔNG PHẢI là đồng thuận.\", \"Chỉ khi đối phương nói Có một cách vui vẻ và thoải mái, đó mới là đồng thuận thực sự.\"]}', 2, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(548, 92, 'scenario', '{\"title\": \"Cuộc gọi muộn\", \"body\": \"Nam nhắn tin rủ Vy gọi video nói chuyện. Vy chỉ nhắn lại: Tớ đang chuẩn bị đi ngủ... Nam nghĩ Vy nói thế tức là vẫn gọi được nên lập tức bấm nút gọi video luôn.\"}', 3, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(549, 92, 'flashcard', '{\"front\": \"Khi nào thì một lời nói hay hành động trên mạng được coi là có sự đồng thuận thực sự?\", \"back\": \"Khi đối phương bày tỏ sự đồng ý rõ ràng, hào hứng, tự nguyện, không bị ép buộc, và họ có quyền rút lại sự đồng ý đó bất kỳ lúc nào họ muốn.\", \"notes\": \"Đồng thuận phải là F.R.E.S.H (Freely given, Reversible, Informed, Enthusiastic, Specific).\"}', 4, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(550, 92, 'reflection', '{\"question\": \"Bạn đã bao giờ ép bản thân đồng ý làm điều gì đó trên mạng chỉ vì ngại từ chối chưa?\"}', 5, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(551, 92, 'takeaway', '{\"items\": [\"Đồng ý gượng ép hay im lặng không bao giờ bằng một lời đồng thuận tự nguyện, vui vẻ.\"]}', 6, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(552, 93, 'hook', '{\"title\": \"Làm sao để nhận biết khi một lời đề nghị trên mạng thực chất là một sự ép buộc tinh vi?\"}', 1, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(553, 93, 'explanation', '{\"bullets\": [\"Sự ép buộc ngầm thường đi kèm các câu nói thao túng tâm lý: Nếu cậu thực sự coi tớ là bạn thì..., Có thế mà cũng ngại à?, hoặc liên tục spam tin nhắn đòi hỏi.\", \"Đồng thuận có được từ sự nể sợ, mệt mỏi hay áp lực không bao giờ có giá trị.\", \"Lắng nghe trực giác: Nếu bạn cảm thấy nghẹn ở cổ họng hay bồn chồn ở bụng, đó là dấu hiệu bạn đang bị ép buộc.\"]}', 2, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(554, 93, 'scenario', '{\"title\": \"Đi spam acc clone\", \"body\": \"Nhóm bạn của Duy rủ nhau lập acc clone đi spam chửi bới một bạn học lớp bên cạnh. Duy từ chối, nhóm bạn liền cười cợt: Đúng là đồ nhát gan, không chơi thì từ sau đừng đi chung nhóm nữa.\"}', 3, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(555, 93, 'interaction', '{\"question\": \"Hành vi của nhóm bạn Duy thể hiện điều gì?\", \"choices\": [{\"text\": \"Sự ép buộc ngầm bằng cách đe dọa cô lập để bắt Duy đồng thuận tham gia.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Một lời đùa giỡn kích lệ tinh thần đồng đội bình thường của bạn bè.\", \"correct\": false, \"emoji\": \"🚩\"}]}', 4, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(556, 93, 'reflection', '{\"question\": \"Bạn có từng đồng ý làm một việc mình thấy sai trái trên mạng chỉ vì sợ bị bạn bè tẩy chay không?\"}', 5, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(557, 93, 'takeaway', '{\"items\": [\"Bạn có quyền nói không với bất kỳ hoạt động nào khiến bạn cảm thấy không thoải mái, bất kể áp lực từ ai.\"]}', 6, '2026-06-05 12:18:20', '2026-06-05 12:18:20'),
(558, 94, 'hook', '{\"title\": \"Tại sao việc đặt ranh giới từ chối lại trở nên cực kỳ khó khăn khi đối phương chính là crush của bạn?\"}', 1, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(559, 94, 'explanation', '{\"bullets\": [\"Chúng ta luôn muốn làm hài lòng người mình thích vì sợ họ sẽ chán mình, giận dỗi hoặc đi tìm người khác.\", \"Tuy nhiên, một người thực sự thích bạn sẽ trân trọng cảm xúc và ranh giới của bạn hơn là việc ép bạn làm điều bạn không muốn.\", \"Tình cảm chân chính được xây dựng trên sự tôn trọng lẫn nhau, không dựa trên sự thỏa hiệp mù quáng.\"]}', 2, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(560, 94, 'scenario', '{\"title\": \"Yêu cầu bật camera\", \"body\": \"Crush của Vy liên tục giận dỗi và không rep tin nhắn vì Vy không chịu bật camera phòng riêng của mình vào buổi tối khi đang mặc đồ ngủ.\"}', 3, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(561, 94, 'sorting', '{\"instruction\": \"Phân loại các phản ứng của crush khi bạn từ chối một yêu cầu trên mạng:\", \"leftBox\": {\"title\": \"Crush lành mạnh\"}, \"rightBox\": {\"title\": \"Crush thao túng\"}, \"items\": [{\"text\": \"Tớ hiểu rồi, cậu cứ nghỉ ngơi đi nhé, khi nào rảnh tụi mình nói chuyện sau\", \"correctBox\": \"left\"}, {\"text\": \"Cậu lúc nào cũng bận, chắc là cậu không thích tớ nên mới né tránh chứ gì\", \"correctBox\": \"right\"}, {\"text\": \"Tôn trọng quyết định không bật camera khi gọi video của bạn\", \"correctBox\": \"left\"}, {\"text\": \"Giận dỗi cả ngày, không rep tin nhắn vì bạn không chịu gửi ảnh selfie chụp cận mặt\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(562, 94, 'reflection', '{\"question\": \"Bạn có bao giờ lo sợ crush sẽ ghét mình nếu bạn từ chối một cuộc gọi của họ không?\"}', 5, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(563, 94, 'takeaway', '{\"items\": [\"Người thực sự trân trọng bạn sẽ lắng nghe lời từ chối của bạn với sự thấu hiểu và tôn trọng.\"]}', 6, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(564, 95, 'hook', '{\"title\": \"Tag tên bạn bè vào một bài đăng dìm hàng hoặc bài viết nhạy cảm mà không hỏi trước có thực sự vô hại?\"}', 1, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(565, 95, 'explanation', '{\"bullets\": [\"Gắn thẻ (Tag) tên ai đó đồng nghĩa với việc đưa thông tin của họ xuất hiện công khai trên dòng thời gian của họ và bạn bè họ.\", \"Điều này có thể khiến họ rơi vào những tình huống dở khóc dở cười hoặc bị người khác hiểu lầm, trêu chọc.\", \"Tôn trọng quyền tự chủ danh tính của bạn bè bằng cách hỏi ý kiến trước khi gắn thẻ họ.\"]}', 2, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(566, 95, 'scenario', '{\"title\": \"Tag tên bài viết nhạy cảm\", \"body\": \"Khanh đăng một bài viết thảo luận về học sinh hay ngủ gật trong lớp và gắn thẻ tên Hải vào bài đăng đó mà không hỏi trước, khiến Hải bị bạn bè chọc ghẹo.\"}', 3, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(567, 95, 'flashcard', '{\"front\": \"Bạn nên cư xử thế nào trước khi gắn thẻ (tag) bạn bè vào một bài viết công khai?\", \"back\": \"Hãy gửi tin nhắn riêng hỏi trước: Tớ đăng bài này có tag tên cậu được không?, hoặc sử dụng tính năng xem lại thẻ trước khi cho xuất hiện trên trang cá nhân.\", \"notes\": \"Tôn trọng danh tính trực tuyến của bạn bè là một phần của sự đồng thuận số.\"}', 4, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(568, 95, 'reflection', '{\"question\": \"Bạn có bao giờ cảm thấy bực mình vì bị tag vào những bài viết quảng cáo hoặc bài đăng dìm hàng nhạy cảm chưa?\"}', 5, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(569, 95, 'takeaway', '{\"items\": [\"Danh tiếng trực tuyến của mỗi người là tài sản riêng của họ. Hãy xin phép trước khi gắn thẻ tag nhé.\"]}', 6, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(570, 96, 'hook', '{\"title\": \"Làm sao để tạo thói quen xin phép trước khi chia sẻ hình ảnh hoặc thông tin liên quan đến người khác?\"}', 1, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(571, 96, 'explanation', '{\"bullets\": [\"Thói quen xin phép thể hiện sự tinh tế và tôn trọng sâu sắc đối với người bạn của mình.\", \"Chỉ mất vài giây nhắn tin hỏi thăm, nhưng nó giữ gìn sự tin tưởng lâu dài giữa hai bên.\", \"Quy tắc vàng: Nếu nghi ngờ, đừng đăng. Nếu muốn đăng, hãy hỏi!\"]}', 2, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(572, 96, 'scenario', '{\"title\": \"Bức ảnh dìm nhẹ\", \"body\": \"Bình chụp được bức ảnh chụp chung rất đẹp với Vân, nhưng biểu cảm của Vân trông hơi ngơ ngác một chút.\"}', 3, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(573, 96, 'interaction', '{\"question\": \"Bình nên làm gì trước khi đăng bức ảnh này lên trang cá nhân của mình?\", \"choices\": [{\"text\": \"Gửi ảnh cho Vân xem trước và hỏi: Tớ đăng ảnh này lên Instagram nhé Vân, cậu thấy tấm này ổn không?\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Cứ đăng luôn rồi tag tên Vân vào, nếu Vân không thích thì tự xóa tag sau.\", \"correct\": false, \"emoji\": \"🙁\"}]}', 4, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(574, 96, 'reflection', '{\"question\": \"Bạn có cảm thấy tin tưởng và yêu quý hơn những người bạn luôn hỏi ý kiến bạn trước khi đăng ảnh chung không?\"}', 5, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(575, 96, 'takeaway', '{\"items\": [\"Tôn trọng quyền riêng tư của bạn bè giúp mối quan hệ bền chặt và tránh được những hiểu lầm.\"]}', 6, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(576, 97, 'hook', '{\"title\": \"Nếu hôm qua bạn đồng ý gọi điện muộn, liệu điều đó có nghĩa là hôm nay bạn cũng phải đồng ý không?\"}', 1, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(577, 97, 'explanation', '{\"bullets\": [\"Đồng thuận không phải là một chiếc vé trọn đời. Việc bạn nói Có hôm nay không đồng nghĩa với việc bạn tự động nói Có vào ngày mai.\", \"Đối phương có quyền thay đổi quyết định của mình bất kỳ lúc nào họ cảm thấy mệt mỏi hoặc không thoải mái.\", \"Hãy luôn kiểm tra sự thoải mái của đối phương mỗi lần tương tác, không lấy sự đồng thuận trong quá khứ làm mặc định.\"]}', 2, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(578, 97, 'scenario', '{\"title\": \"Mượn tài khoản game\", \"body\": \"Khoa đã từng cho Hùng mượn tài khoản game tuần trước. Tuần này, Hùng tự ý đăng nhập chơi tiếp mà không nhắn tin hỏi lại Khoa.\"}', 3, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(579, 97, 'sorting', '{\"instruction\": \"Phân loại các tình huống đồng thuận sau:\", \"leftBox\": {\"title\": \"Tôn trọng ranh giới\"}, \"rightBox\": {\"title\": \"Tự ý mặc định\"}, \"items\": [{\"text\": \"Hôm qua tụi mình call nói chuyện vui quá, tối nay cậu có sẵn sàng call tiếp không?\", \"correctBox\": \"left\"}, {\"text\": \"Lần trước cậu cho mượn acc game rồi nên lần này tớ tự ý đăng nhập chơi tiếp luôn\", \"correctBox\": \"right\"}, {\"text\": \"Dừng gửi ảnh meme khi bạn nói hôm nay bạn mệt và muốn yên tĩnh\", \"correctBox\": \"left\"}, {\"text\": \"Bắt bạn phải đi chơi chung trên mạng vì lần trước bạn đã từng hứa đi\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(580, 97, 'reflection', '{\"question\": \"Bạn có bao giờ thấy khó xử khi muốn rút lại một lời đồng ý trước đó với bạn bè không?\"}', 5, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(581, 97, 'takeaway', '{\"items\": [\"Bạn luôn có quyền thay đổi quyết định. Sự đồng thuận thực sự cần được hỏi lại mỗi lần.\"]}', 6, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(582, 98, 'hook', '{\"title\": \"Bạn đã bao giờ nghe nói về việc gửi tin nhắn nhạy cảm hoặc ảnh riêng tư (sexting) chưa?\"}', 1, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(583, 98, 'explanation', '{\"bullets\": [\"Sexting là việc gửi hoặc nhận những tin nhắn, hình ảnh hoặc video có nội dung nhạy cảm, gợi dục hoặc khỏa thân qua mạng.\", \"Đối với lứa tuổi học sinh (dưới 18 tuổi), việc tạo ra, lưu trữ hoặc chia sẻ ảnh nhạy cảm của bản thân hoặc người khác là vi phạm pháp luật nghiêm trọng.\", \"Một khi bức ảnh nhạy cảm đã rời khỏi điện thoại của bạn, bạn hoàn toàn mất quyền kiểm soát nó.\"]}', 2, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(584, 98, 'scenario', '{\"title\": \"Lời hứa xem xong xóa\", \"body\": \"Một người bạn cùng khóa gửi cho Vy một tin nhắn rủ rê chụp ảnh phần cơ thể nhạy cảm gửi qua Zalo và hứa sẽ xóa đi ngay sau khi xem xong.\"}', 3, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(585, 98, 'flashcard', '{\"front\": \"Lời hứa xem xong sẽ xóa ngay trên ứng dụng chat có thực sự đáng tin cậy không?\", \"back\": \"Tuyệt đối KHÔNG. Đối phương hoàn toàn có thể dùng một điện thoại khác để chụp lại màn hình, hoặc ảnh được lưu tự động vào bộ nhớ đám mây.\", \"notes\": \"Đừng bao giờ mạo hiểm chụp và gửi những bức ảnh nhạy cảm của bản thân lên mạng.\"}', 4, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(586, 98, 'reflection', '{\"question\": \"Bạn có biết rằng ở lứa tuổi học sinh, việc gửi ảnh nhạy cảm có thể dẫn đến những rắc rối pháp lý rất lớn không?\"}', 5, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(587, 98, 'takeaway', '{\"items\": [\"Một khi ảnh nhạy cảm đã gửi đi, bạn không thể thu hồi nó khỏi thế giới Internet được nữa.\"]}', 6, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(588, 99, 'hook', '{\"title\": \"Làm sao để nhận diện và từ chối khi bị người yêu hoặc crush ép gửi ảnh nhạy cảm để chứng minh tình yêu?\"}', 1, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(589, 99, 'explanation', '{\"bullets\": [\"Kẻ ép buộc thường dùng các chiêu bài tình cảm: Nếu yêu tớ thì cậu phải gửi chứ, Tớ gửi cho cậu rồi, cậu phải gửi lại cho công bằng.\", \"Tình yêu thực sự không cần những bức ảnh khỏa thân để chứng minh lòng thủy chung.\", \"Từ chối gửi ảnh nhạy cảm chính là biểu hiện của việc biết bảo vệ bản thân và tôn trọng ranh giới cơ thể.\"]}', 2, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(590, 99, 'scenario', '{\"title\": \"Đòi ảnh để làm hòa\", \"body\": \"Bạn trai của Lan liên tục giận dỗi và dọa chia tay nếu Lan không chịu chụp ảnh mặc đồ bơi gợi cảm gửi qua tin nhắn Messenger cho anh ta xem.\"}', 3, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(591, 99, 'interaction', '{\"question\": \"Lan nên phản ứng thế nào để bảo vệ bản thân?\", \"choices\": [{\"text\": \"Kiên quyết từ chối: Tớ không thoải mái với việc chụp ảnh này đâu. Nếu cậu thực sự yêu tớ thì cậu sẽ không bắt tớ làm điều tớ thấy sợ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Chấp nhận chụp gửi một tấm mờ mờ để bạn trai không giận nữa.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(592, 99, 'reflection', '{\"question\": \"Bạn đã từng nghe về trường hợp ai đó bị người yêu cũ phát tán ảnh riêng tư lên mạng sau khi chia tay chưa?\"}', 5, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(593, 99, 'takeaway', '{\"items\": [\"Người thực sự yêu bạn sẽ bảo vệ sự an toàn của bạn, chứ không bao giờ đặt bạn vào rủi ro lộ ảnh nhạy cảm.\"]}', 6, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(594, 100, 'hook', '{\"title\": \"Tại sao nhiều bạn trẻ lại cảm thấy hối hận, lo âu tột độ ngay sau khi nhấn nút gửi đi một bức ảnh nhạy cảm?\"}', 1, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(595, 100, 'explanation', '{\"bullets\": [\"Cảm giác phấn khích nhất thời nhanh chóng bị thay thế bởi sự lo sợ lộ ảnh, sợ bị đánh giá, tống tiền hoặc bị phát tán lên các hội nhóm.\", \"Sự lo lắng nơm nớp này có thể gây căng thẳng kéo dài, ảnh hưởng nghiêm trọng đến việc học tập và tâm lý.\", \"Bảo vệ ranh giới cơ thể trực tuyến giúp bạn giữ được sự bình yên trong tâm trí.\"]}', 2, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(596, 100, 'scenario', '{\"title\": \"Nỗi lo vô hình\", \"body\": \"Huy lỡ gửi ảnh cởi trần nhạy cảm cho bạn gái mới quen qua mạng. Sau đó, Huy không thể tập trung học bài vì lúc nào cũng sợ bạn gái mang đi khoe với người khác.\"}', 3, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(597, 100, 'sorting', '{\"instruction\": \"Phân loại các hành vi tự bảo vệ bản thân trước nguy cơ lộ ảnh riêng tư:\", \"leftBox\": {\"title\": \"Bảo vệ an toàn\"}, \"rightBox\": {\"title\": \"Đặt mình vào rủi ro\"}, \"items\": [{\"text\": \"Tuyệt đối không chụp ảnh nhạy cảm lộ rõ khuôn mặt hoặc hình xăm đặc trưng\", \"correctBox\": \"left\"}, {\"text\": \"Lưu trữ ảnh nhạy cảm trong album điện thoại không cài mật khẩu khóa riêng\", \"correctBox\": \"right\"}, {\"text\": \"Kiên quyết từ chối mọi lời gạ gẫm gửi ảnh nhạy cảm từ người lạ trên mạng\", \"correctBox\": \"left\"}, {\"text\": \"Gửi ảnh nhạy cảm qua ứng dụng chat và nghĩ rằng tính năng tự xóa là an toàn\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(598, 100, 'reflection', '{\"question\": \"Bạn có cảm thấy sự bình yên trong tâm trí quan trọng hơn việc làm vừa lòng một ai đó trên mạng xã hội không?\"}', 5, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(599, 100, 'takeaway', '{\"items\": [\"Sự an toàn và bình yên tinh thần của bạn là vô giá. Đừng đánh đổi nó lấy sự hài lòng nhất thời của người khác.\"]}', 6, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(600, 101, 'hook', '{\"title\": \"Liệu gửi ảnh nhạy cảm có phải là cách để thể hiện sự gắn kết và tin tưởng tuyệt đối vào người yêu của mình?\"}', 1, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(601, 101, 'explanation', '{\"bullets\": [\"Lòng tin được xây dựng qua sự quan tâm, chia sẻ và tôn trọng ranh giới ngoài đời thực, không phụ thuộc vào những bức ảnh nhạy cảm.\", \"Người yêu của bạn dù tốt đến đâu cũng không thể kiểm soát được việc điện thoại của họ bị hack, bị mất, hoặc bị người khác tò mò đọc trộm.\", \"Giữ lại sự riêng tư cho bản thân không phải là thiếu tin tưởng đối phương, đó là hành vi tự chịu trách nhiệm thông minh.\"]}', 2, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(602, 101, 'scenario', '{\"title\": \"Lời thề thốt\", \"body\": \"Quân hứa với Mai: Tớ thề là chỉ giữ ảnh này cho riêng tớ xem thôi, tớ mà chia sẻ cho ai thì tớ làm con cún. Mai rất yêu Quân nhưng vẫn cảm thấy lo sợ.\"}', 3, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(603, 101, 'flashcard', '{\"front\": \"Mai nên làm gì trước lời thề thốt chân thành của Quân?\", \"back\": \"Mai nên giữ vững lập trường từ chối: Tớ tin cậu, nhưng tớ không tin chiếc điện thoại hay các hacker trên mạng đâu. Tụi mình yêu nhau đâu cần phải qua những bức ảnh này.\", \"notes\": \"Đừng bao giờ gửi ảnh nhạy cảm chỉ vì bị thuyết phục bởi những lời thề thốt.\"}', 4, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(604, 101, 'reflection', '{\"question\": \"Bạn có đồng ý rằng việc giữ an toàn cho bản thân chính là cách tốt nhất để bảo vệ tương lai của chính mình không?\"}', 5, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(605, 101, 'takeaway', '{\"items\": [\"Hãy tin tưởng nhau bằng hành động tử tế, đừng tin tưởng bằng cách trao đi những thông tin nhạy cảm có thể hủy hoại bạn.\"]}', 6, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(606, 102, 'hook', '{\"title\": \"Nếu không may hình ảnh riêng tư của bạn bị phát tán trái phép lên mạng, bạn cần làm gì ngay lập tức?\"}', 1, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(607, 102, 'explanation', '{\"bullets\": [\"Đầu tiên: Không tự trách bản thân. Bạn là nạn nhân của hành vi phát tán trái phép, lỗi hoàn toàn thuộc về kẻ phát tán.\", \"Thứ hai: Chụp màn hình bằng chứng và báo cáo (report) bài đăng lên nền tảng mạng xã hội để yêu cầu gỡ bỏ.\", \"Thứ ba: Chia sẻ câu chuyện với người lớn đáng tin cậy (bố mẹ, thầy cô) hoặc liên hệ Tổng đài bảo vệ trẻ em 111 để nhận trợ giúp.\"]}', 2, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(608, 102, 'scenario', '{\"title\": \"Ảnh chế trong nhóm kín\", \"body\": \"Linh phát hiện bức ảnh mặc đồ bó sát nhạy cảm mình từng gửi cho người yêu cũ bị đăng lên một hội nhóm bêu rếu trên Facebook của trường. Linh vô cùng hoảng loạn.\"}', 3, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(609, 102, 'interaction', '{\"question\": \"Linh nên làm gì đầu tiên trong tình huống này?\", \"choices\": [{\"text\": \"Chụp lại màn hình bài viết để làm bằng chứng, báo cáo bài đăng và tâm sự ngay với mẹ hoặc giáo viên chủ nhiệm.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Nhắn tin cầu xin người yêu cũ gỡ bài và khóa tài khoản mạng xã hội để trốn tránh.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(610, 102, 'reflection', '{\"question\": \"Bạn có biết số điện thoại của Tổng đài bảo vệ trẻ em 111 tại Việt Nam không? Nó hoàn toàn miễn phí và bảo mật thông tin.\"}', 5, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(611, 102, 'takeaway', '{\"items\": [\"Bạn không hề cô độc khi gặp sự cố trên mạng. Luôn có những người lớn đáng tin cậy sẵn sàng che chở và bảo vệ bạn.\"]}', 6, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(612, 103, 'hook', '{\"title\": \"Ai mới là người có tiếng nói duy nhất và tối cao đối với hình ảnh và cơ thể của bạn trên không gian số?\"}', 1, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(613, 103, 'explanation', '{\"bullets\": [\"Bạn có toàn quyền quyết định về hình ảnh cơ thể mình trên mạng.\", \"Không ai được phép chụp ảnh bạn khi chưa được sự đồng ý, và không ai được phép ép bạn phơi bày cơ thể qua camera.\", \"Tôn trọng cơ thể của chính mình và tôn trọng cơ thể của người khác chính là nền tảng của một công dân số văn minh.\"]}', 2, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(614, 103, 'scenario', '{\"title\": \"Bị ép mở camera\", \"body\": \"Dũng gọi video cho bạn gái và liên tục ép cô ấy phải kéo áo xuống cho Dũng xem vai trần, mặc dù cô ấy đã từ chối và nói rằng thấy rất ngại.\"}', 3, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(615, 103, 'sorting', '{\"instruction\": \"Phân loại các hành vi ứng xử tôn trọng quyền cơ thể sau:\", \"leftBox\": {\"title\": \"Tôn trọng quyền cơ thể\"}, \"rightBox\": {\"title\": \"Xâm phạm quyền cơ thể\"}, \"items\": [{\"text\": \"Từ chối chụp ảnh cơ thể mình dù bị người khác năn nỉ, chèo kéo\", \"correctBox\": \"left\"}, {\"text\": \"Lén lút chụp ảnh bạn bè đang thay đồ thể dục để trêu đùa trong nhóm\", \"correctBox\": \"right\"}, {\"text\": \"Báo cáo tài khoản đăng ảnh chế giễu ngoại hình của một bạn học sinh khác\", \"correctBox\": \"left\"}, {\"text\": \"Bắt người yêu phải bật camera khi đang tắm để chứng tỏ không giấu giếm\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(616, 103, 'reflection', '{\"question\": \"Bạn có luôn cảm thấy tự tin bảo vệ ranh giới cơ thể mình trước những lời đề nghị thô lỗ trên mạng không?\"}', 5, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(617, 103, 'takeaway', '{\"items\": [\"Cơ thể bạn là của bạn. Quyền quyết định chia sẻ hình ảnh hay không hoàn toàn thuộc về bạn, không ngoại lệ cho bất kỳ ai.\"]}', 6, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(618, 104, 'hook', '{\"title\": \"Làm sao nhận ra một mối quan hệ qua mạng đang chuyển từ ngọt ngào đáng yêu sang kiểm soát độc hại?\"}', 1, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(619, 104, 'explanation', '{\"bullets\": [\"Cờ đỏ (Red Flag) trên mạng là những dấu hiệu cảnh báo mối quan hệ thiếu lành mạnh: ghen tuông vô cớ, đòi kiểm tra vị trí liên tục, bắt xóa bạn bè khác giới.\", \"Những hành vi này ban đầu thường được ngụy trang dưới danh nghĩa yêu quá nên mới thế.\", \"Nhận biết cờ đỏ giúp bạn tránh xa những mối quan hệ thao túng trước khi quá muộn.\"]}', 2, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(620, 104, 'scenario', '{\"title\": \"Yêu cầu xóa bạn game\", \"body\": \"Vy quen một bạn nam qua game online. Bạn này rất chiều Vy, thường tặng quà ingame, nhưng bắt Vy phải chụp ảnh màn hình danh sách bạn bè trong game và xóa hết các bạn nam khác đi.\"}', 3, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(621, 104, 'flashcard', '{\"front\": \"Yêu cầu kiểm tra vị trí hoặc bắt xóa bạn bè khác giới trên mạng có phải là biểu hiện của tình yêu chân thành không?\", \"back\": \"Tuyệt đối KHÔNG. Đó là hành vi kiểm soát và thiếu tôn trọng không gian riêng tư của đối phương, một cờ đỏ cảnh báo mối quan hệ độc hại.\", \"notes\": \"Tình yêu lành mạnh mang lại sự tự do và lòng tin, chứ không phải sự giam cầm số.\"}', 4, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(622, 104, 'reflection', '{\"question\": \"Bạn đã từng gặp ai trên mạng có những yêu cầu kiểm soát vô lý khiến bạn thấy ngột ngạt chưa?\"}', 5, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(623, 104, 'takeaway', '{\"items\": [\"Đừng nhầm lẫn giữa sự kiểm soát độc hại và tình yêu thương chân thành trên không gian mạng.\"]}', 6, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(624, 105, 'hook', '{\"title\": \"Người bạn 15 tuổi, siêu đẹp trai, đang học trường quốc tế nói chuyện cực hợp với bạn trên mạng liệu có thực sự tồn tại ngoài đời?\"}', 1, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(625, 105, 'explanation', '{\"bullets\": [\"Catfishing (Giả mạo danh tính) là việc một người tạo tài khoản ảo với hình ảnh và thông tin của người khác để tiếp cận, làm quen và lừa gạt bạn.\", \"Mục đích của họ có thể là lừa tiền, lừa tình cảm, hoặc dụ dỗ bạn làm những việc nhạy cảm để tống tiền.\", \"Hãy luôn cảnh giác với những tài khoản không bao giờ chịu gọi video call trực tiếp hoặc luôn từ chối gặp mặt ngoài đời.\"]}', 2, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(626, 105, 'scenario', '{\"title\": \"Camera hỏng liên tục\", \"body\": \"Lan quen anh Duy qua Instagram, ảnh cá nhân của anh trông rất lãng tử và giàu có. Mỗi lần Lan rủ gọi video để nhìn mặt, anh Duy đều bảo camera bị hỏng.\"}', 3, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(627, 105, 'interaction', '{\"question\": \"Lan nên làm gì để kiểm chứng thông tin của Duy?\", \"choices\": [{\"text\": \"Đề nghị dừng nói chuyện yêu đương cho đến khi có thể gọi video call nhìn rõ mặt và xác nhận danh tính thật ngoài đời.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tiếp tục tin tưởng và gửi thẻ cào điện thoại giúp anh Duy vì anh bảo đang gặp khó khăn tạm thời.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(628, 105, 'reflection', '{\"question\": \"Bạn có thói quen kiểm tra kỹ trang cá nhân (ngày lập, lượng tương tác thật) của một người lạ trước khi kết bạn không?\"}', 5, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(629, 105, 'takeaway', '{\"items\": [\"Đừng trao trọn lòng tin cho một bức ảnh đại diện long lanh trên mạng xã hội khi chưa được kiểm chứng thực tế.\"]}', 6, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(630, 106, 'hook', '{\"title\": \"Tại sao kẻ thao túng trên mạng luôn tìm cách bắt bạn giữ bí mật mối quan hệ và không được kể cho bố mẹ hay bạn bè nghe?\"}', 1, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(631, 106, 'explanation', '{\"bullets\": [\"Cô lập bạn là bước đầu tiên để kẻ thao túng dễ dàng kiểm soát tâm lý và hành vi của bạn.\", \"Khi bạn không chia sẻ với ai khác, bạn sẽ mất đi những góc nhìn khách quan và lời khuyên tỉnh táo từ những người xung quanh.\", \"Một mối quan hệ lành mạnh không bao giờ bắt bạn phải sống trong bóng tối và che giấu tất cả mọi người.\"]}', 2, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(632, 106, 'scenario', '{\"title\": \"Yêu cầu bí mật\", \"body\": \"Một người đàn ông trung niên giả danh làm tuyển trạch viên người mẫu trẻ tuổi kết bạn với Vy và dặn cô phải tuyệt đối giữ bí mật về các buổi chụp ảnh thử.\"}', 3, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(633, 106, 'sorting', '{\"instruction\": \"Phân loại các hành vi ứng xử trước yêu cầu giữ bí mật mối quan hệ:\", \"leftBox\": {\"title\": \"Hành vi tỉnh táo\"}, \"rightBox\": {\"title\": \"Bị cô lập thao túng\"}, \"items\": [{\"text\": \"Tâm sự với bạn thân về người bạn mới quen trên mạng để nghe nhận xét\", \"correctBox\": \"left\"}, {\"text\": \"Giấu kín mọi cuộc trò chuyện với người lạ vì họ dọa nếu nói ra sẽ bị trừng phạt\", \"correctBox\": \"right\"}, {\"text\": \"Dẫn theo bạn bè đi cùng khi lần đầu tiên hẹn gặp người quen trên mạng ngoài đời\", \"correctBox\": \"left\"}, {\"text\": \"Nói dối bố mẹ đi học thêm để đến nhà riêng của một người quen qua mạng\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(634, 106, 'reflection', '{\"question\": \"Bạn có cảm thấy một mối quan hệ luôn bắt bạn phải nói dối người thân có thực sự mang lại hạnh phúc lâu dài không?\"}', 5, '2026-06-05 12:18:21', '2026-06-05 12:18:21');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(635, 106, 'takeaway', '{\"items\": [\"Ánh sáng là kẻ thù của sự thao túng. Hãy chia sẻ câu chuyện của bạn với những người yêu thương bạn ngoài đời thực.\"]}', 6, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(636, 107, 'hook', '{\"title\": \"Một game thủ VIP trên mạng tặng bạn rất nhiều trang phục đẹp và đề nghị bạn gọi video call riêng tư để nói chuyện, bạn sẽ làm gì?\"}', 1, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(637, 107, 'explanation', '{\"bullets\": [\"Không có bữa ăn nào là miễn phí, đặc biệt là từ những người lạ trên không gian mạng.\", \"Những món quà đắt tiền thường là mồi nhử để tạo ra cảm giác mắc nợ, khiến bạn thấy khó từ chối các yêu cầu nhạy cảm tiếp theo của họ.\", \"Hãy kiên quyết từ chối những món quà vô cớ từ người lạ để giữ cho mình thế chủ động và an toàn.\"]}', 2, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(638, 107, 'scenario', '{\"title\": \"Trang phục game đắt giá\", \"body\": \"Một người lạ kết bạn với Minh trong game Liên Quân và tặng Minh trang phục tướng trị giá 500k. Sau đó, người này nhắn tin yêu cầu Minh bật camera phòng riêng và cởi áo ra cho xem để cảm ơn.\"}', 3, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(639, 107, 'flashcard', '{\"front\": \"Minh nên xử lý thế nào trước yêu cầu của người lạ sau khi đã nhận quà game?\", \"back\": \"Minh nên chặn tài khoản của người đó ngay lập tức, tuyệt đối không bật camera và kể ngay sự việc cho bố mẹ nghe.\", \"notes\": \"Đừng vì tiếc một món quà ảo mà đánh đổi sự an toàn và danh dự thực tế của bản thân.\"}', 4, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(640, 107, 'reflection', '{\"question\": \"Bạn có bao giờ cảm thấy áy náy hoặc mắc nợ khi nhận được quà từ một người bạn mới quen trên mạng chưa?\"}', 5, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(641, 107, 'takeaway', '{\"items\": [\"Sự an toàn của bạn quan trọng hơn bất kỳ món quà ảo hay trang phục game đắt tiền nào trên thế giới.\"]}', 6, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(642, 108, 'hook', '{\"title\": \"Làm sao để chấm dứt một mối quan hệ trực tuyến độc hại khi đối phương liên tục đe dọa sẽ hủy hoại bạn?\"}', 1, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(643, 108, 'explanation', '{\"bullets\": [\"Kẻ thao túng thường dùng những lời đe dọa để giữ chân bạn: dọa tự tử, dọa tung ảnh riêng tư, hoặc dọa mách bố mẹ.\", \"Hãy nhớ: bạn không phải chịu trách nhiệm về hành vi tự hủy hoại của đối phương. Những lời đe dọa đó thường chỉ là chiêu trò tâm lý.\", \"Lập tức chụp bằng chứng, chặn mọi kênh liên lạc, không đôi co thêm và tìm kiếm sự hỗ trợ từ người lớn đáng tin cậy.\"]}', 2, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(644, 108, 'scenario', '{\"title\": \"Lời đe dọa tung tin nhắn\", \"body\": \"Người yêu qua mạng của Vy dọa sẽ gửi những tin nhắn tâm sự riêng tư nhạy cảm của hai người cho bố mẹ Vy xem nếu Vy đòi chia tay. Vy rất sợ hãi và cắn răng chịu đựng.\"}', 3, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(645, 108, 'interaction', '{\"question\": \"Vy nên làm gì để thoát khỏi tình cảnh bế tắc này?\", \"choices\": [{\"text\": \"Chặn toàn bộ liên lạc với người đó, chủ động kể thật câu chuyện với bố mẹ trước để nhận sự bảo vệ và hỗ trợ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tiếp tục chịu đựng và làm theo mọi yêu cầu của người đó để giữ bình yên tạm thời.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(646, 108, 'reflection', '{\"question\": \"Bạn có tin rằng việc chủ động nói thật với bố mẹ luôn tốt hơn việc để kẻ xấu dùng điều đó để khống chế bạn không?\"}', 5, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(647, 108, 'takeaway', '{\"items\": [\"Đừng để sự sợ hãi giam giữ bạn trong ngục tối số. Hãy dũng cảm cắt đứt và tìm kiếm sự che chở từ những người yêu thương bạn thực sự.\"]}', 6, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(648, 109, 'hook', '{\"title\": \"Khi trò chuyện với ai đó trên mạng mà bạn luôn cảm thấy có điều gì đó sai sai, bạn nên làm gì?\"}', 1, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(649, 109, 'explanation', '{\"bullets\": [\"Trực giác (Gut feeling) là hệ thống cảnh báo sớm của cơ thể dựa trên những chi tiết nhỏ nhặt mà lý trí chưa kịp phân tích.\", \"Nếu bạn thấy lo sợ, bất an hoặc nghi ngờ lòng tốt của đối phương, đừng cố lờ đi cảm xúc đó để tỏ ra lịch sự.\", \"Bạn luôn có quyền dừng cuộc trò chuyện và lùi lại một bước để bảo vệ sự an toàn của mình.\"]}', 2, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(650, 109, 'scenario', '{\"title\": \"Cảm giác bất an\", \"body\": \"Hùng nói chuyện với một người tự xưng là anh họ của bạn thân trên mạng. Người này liên tục hỏi Hùng bố mẹ đi làm về lúc mấy giờ, nhà có lắp camera không. Hùng thấy gai người và thấy có gì đó bất ổn.\"}', 3, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(651, 109, 'sorting', '{\"instruction\": \"Phân loại các hành dung ứng xử theo trực giác mách bảo sau:\", \"leftBox\": {\"title\": \"Lắng nghe trực giác\"}, \"rightBox\": {\"title\": \"Phớt lờ cảnh báo\"}, \"items\": [{\"text\": \"Ngừng chat khi thấy đối phương liên tục hỏi về địa chỉ phòng ngủ của mình\", \"correctBox\": \"left\"}, {\"text\": \"Cố gắng tiếp tục trò chuyện dù thấy nổi da gà trước những câu hỏi riêng tư của họ\", \"correctBox\": \"right\"}, {\"text\": \"Hỏi ý kiến chị gái khi thấy bạn quen trên mạng đòi gọi video call lúc nửa đêm\", \"correctBox\": \"left\"}, {\"text\": \"Bỏ qua cảm giác bồn chồn lo lắng để đồng ý gặp mặt riêng tư người lạ ở công viên vắng\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(652, 109, 'reflection', '{\"question\": \"Đã bao giờ trực giác mách bảo bạn tránh xa một người trên mạng và sau đó bạn phát hiện ra họ thực sự có vấn đề chưa?\"}', 5, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(653, 109, 'takeaway', '{\"items\": [\"Trực giác của bạn là người bạn đồng hành trung thực nhất. Hãy tin tưởng và lắng nghe khi nó lên tiếng cảnh báo nhé.\"]}', 6, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(654, 110, 'hook', '{\"title\": \"Bạn có nghĩ một dòng comment chê bai, chế giễu ngoại hình của người khác trên mạng chỉ là một trò đùa vô hại?\"}', 1, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(655, 110, 'explanation', '{\"bullets\": [\"Bạo lực mạng (Cyberbullying) là hành vi cố ý, lặp đi lặp lại nhằm đe dọa, hạ nhục, cô lập hoặc gây tổn thương cho người khác qua internet.\", \"Nó bao gồm việc đăng ảnh chế giễu, bình luận thóa mạ, lập group anti, hoặc chia sẻ tin đồn thất thiệt.\", \"Bạo lực mạng có thể gây ra những tổn thương tâm lý sâu sắc ngoài đời thực cho nạn nhân.\"]}', 2, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(656, 110, 'scenario', '{\"title\": \"Group chat anti\", \"body\": \"Cả lớp lập một nhóm chat riêng không có mặt Vy, chuyên đăng những bức ảnh chụp lén Vy lúc đang ăn hoặc ngủ gật để chế ảnh meme cười cợt và bình luận xúc phạm.\"}', 3, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(657, 110, 'flashcard', '{\"front\": \"Bạo lực mạng khác gì so với những tranh cãi thông thường giữa bạn bè?\", \"back\": \"Bạo lực mạng là hành vi cố ý hướng vào một cá nhân, lặp đi lặp lại nhiều lần, có tính chất hạ nhục, bắt nạt và tạo ra sự cô lập hoàn toàn.\", \"notes\": \"Đừng tham gia hoặc cổ xúy cho bất kỳ hành vi bắt nạt trực tuyến nào.\"}', 4, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(658, 110, 'reflection', '{\"question\": \"Bạn đã bao giờ chứng kiến một bạn học của mình trở thành mục tiêu chế giễu của tập thể trên mạng chưa?\"}', 5, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(659, 110, 'takeaway', '{\"items\": [\"Chữ viết trên màn hình có thể tạo ra những vết sẹo thật trong tim. Hãy suy nghĩ trước khi gõ phím.\"]}', 6, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(660, 111, 'hook', '{\"title\": \"Làm sao để phân biệt giữa một lời trêu đùa thân thiện giữa những người bạn và hành vi bắt nạt trực tuyến độc hại?\"}', 1, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(661, 111, 'explanation', '{\"bullets\": [\"Trêu đùa lành mạnh là khi cả hai bên đều thấy vui vẻ, thoải mái và có thể dừng lại ngay khi một bên cảm thấy khó chịu.\", \"Bắt nạt là khi một bên liên tục cảm thấy xấu hổ, sợ hãi nhưng bên kia vẫn tiếp tục tấn công bất chấp sự phản đối.\", \"Quy tắc đơn giản: Nếu người bị trêu không cười, đó không phải là trò đùa!\"]}', 2, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(662, 111, 'scenario', '{\"title\": \"Đùa quá trớn\", \"body\": \"Nam vẽ một bức ảnh hoạt hình hài hước trêu gu thời trang của Bình. Lần sau, Nam đăng ảnh chế Bình bị ngã xe kèm những lời lẽ chế giễu, Bình nhắn tin xin gỡ nhưng Nam bảo: Đùa tí làm gì căng thế?\"}', 3, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(663, 111, 'interaction', '{\"question\": \"Hành vi lần thứ hai của Nam là gì?\", \"choices\": [{\"text\": \"Bắt đầu chuyển thành hành vi bắt nạt trực tuyến vì phớt lờ lời yêu cầu dừng lại của bạn và gây tổn thương cho bạn.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Vẫn là trêu đùa vui vẻ bình thường, Bình quá nhạy cảm và thiếu khiếu hài hước thôi.\", \"correct\": false, \"emoji\": \"🚩\"}]}', 4, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(664, 111, 'reflection', '{\"question\": \"Bạn có bao giờ cảm thấy bị tổn thương bởi một trò đùa của bạn bè trên mạng nhưng vẫn phải giả vờ cười để không bị coi là kẻ phá đám chưa?\"}', 5, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(665, 111, 'takeaway', '{\"items\": [\"Sự thoải mái của người nghe mới là thước đo quyết định đó có phải là trò đùa vui vẻ hay không.\"]}', 6, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(666, 112, 'hook', '{\"title\": \"Bạn có bao giờ tự hỏi cảm giác của một người khi mở điện thoại ra và thấy hàng trăm bình luận chửi bới hướng vào mình sẽ như thế nào?\"}', 1, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(667, 112, 'explanation', '{\"bullets\": [\"Nạn nhân của bạo lực mạng thường trải qua cảm giác cô đơn tột cùng, bất an, sợ hãi không dám đến trường và tự trách bản thân.\", \"Sự công kích dồn dập khiến họ có cảm giác cả thế giới đang quay lưng lại với mình.\", \"Thấu hiểu và đồng cảm giúp chúng ta có trách nhiệm hơn với từng lượt tương tác của mình trên mạng.\"]}', 2, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(668, 112, 'scenario', '{\"title\": \"Áp lực dồn dập\", \"body\": \"Trang mở Facebook lên và thấy hàng chục bình luận chế giễu ngoại hình cô ấy dưới bài đăng của một trang confession trường. Trang khóc nức nở và khóa phòng kín mít.\"}', 3, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(669, 112, 'sorting', '{\"instruction\": \"Phân loại các cách ứng xử thể hiện sự đồng cảm với nạn nhân bạo lực mạng:\", \"leftBox\": {\"title\": \"Đồng cảm ấm áp\"}, \"rightBox\": {\"title\": \"Thờ ơ độc hại\"}, \"items\": [{\"text\": \"Nhắn tin riêng hỏi thăm và động viên: Tớ luôn bên cậu, cậu không cô đơn đâu\", \"correctBox\": \"left\"}, {\"text\": \"Hùa vào bình luận thả icon cười cợt dưới bài viết dìm hàng để tỏ ra hợp thời\", \"correctBox\": \"right\"}, {\"text\": \"Báo cáo bài viết xúc phạm và đề nghị mọi người không chia sẻ thêm\", \"correctBox\": \"left\"}, {\"text\": \"Nghĩ bụng: Chắc bạn đó phải làm gì sai thì mới bị mọi người ghét như vậy chứ\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(670, 112, 'reflection', '{\"question\": \"Nếu một ngày bạn bị cả nhóm bạn quay lưng nói xấu trên mạng, bạn mong muốn nhận được sự hỗ trợ như thế nào từ những người xung quanh?\"}', 5, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(671, 112, 'takeaway', '{\"items\": [\"Một lời hỏi thăm riêng tư, ấm áp của bạn có thể cứu rỗi cả một tâm hồn đang tuyệt vọng vì bạo lực mạng.\"]}', 6, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(672, 113, 'hook', '{\"title\": \"Khi chứng kiến một người khác bị bắt nạt trên mạng, việc bạn im lặng đứng nhìn có thực sự giúp bạn vô can?\"}', 1, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(673, 113, 'explanation', '{\"bullets\": [\"Kẻ đứng xem (Bystander) là người nhìn thấy hành vi bắt nạt nhưng lựa chọn im lặng, phớt lờ hoặc chia sẻ bài viết để xem trò vui.\", \"Sự im lặng của đám đông vô tình tạo ra sự cổ vũ ngầm, khiến kẻ bắt nạt càng đắc ý và nạn nhân càng cô độc.\", \"Bạn không cần phải nhảy vào tranh cãi tay đôi, nhưng bạn có thể hành động thông minh để bảo vệ nạn nhân.\"]}', 2, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(674, 113, 'scenario', '{\"title\": \"Đám đông im lặng\", \"body\": \"Trong nhóm chat lớp, một bạn nam đăng ảnh chế giễu cân nặng của bạn Vy. Cả nhóm im lặng không ai nói gì, một vài bạn thả icon cười cợt. Vy nhìn thấy và thấy vô cùng xấu hổ.\"}', 3, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(675, 113, 'flashcard', '{\"front\": \"Bạn nên làm gì để không trở thành một kẻ đứng xem vô cảm trong tình huống trên?\", \"back\": \"Bạn có thể nhắn tin riêng động viên Vy, đồng thời báo cáo tin nhắn xấu đó cho lớp trưởng hoặc giáo viên chủ nhiệm biết để can thiệp kịp thời.\", \"notes\": \"Đừng làm khán giả cho những hành vi bắt nạt trực tuyến.\"}', 4, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(676, 113, 'reflection', '{\"question\": \"Bạn đã từng im lặng đứng nhìn một hành vi bất công trên mạng vì sợ bị liên lụy chưa? Bạn cảm thấy thế nào sau đó?\"}', 5, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(677, 113, 'takeaway', '{\"items\": [\"Im lặng trước cái xấu chính là tiếp tay cho nó lan tỏa. Hãy dũng cảm hành động vì sự công bằng.\"]}', 6, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(678, 114, 'hook', '{\"title\": \"Làm thế nào để nâng cấp bản thân từ một kẻ đứng xem vô cảm thành một người bảo vệ dũng cảm (Upstander) trên mạng?\"}', 1, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(679, 114, 'explanation', '{\"bullets\": [\"Người bảo vệ (Upstander) là người chủ động hành động để ngăn chặn hành vi bắt nạt và hỗ trợ nạn nhân.\", \"Các bước hành động: Báo cáo (Report) bài viết vi phạm, Bày tỏ sự ủng hộ (Support) trực tiếp với nạn nhân, và Báo cáo cho người lớn (Refer) đáng tin cậy.\", \"Một hành động nhỏ của người bảo vệ có thể xoay chuyển hoàn toàn tình thế và mang lại hy vọng.\"]}', 2, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(680, 114, 'scenario', '{\"title\": \"Lên tiếng đúng lúc\", \"body\": \"Thấy Vy bị chế giễu cân nặng trong nhóm chat, Duy quyết định không im lặng nữa mà nhắn tin yêu cầu mọi người dừng lại.\"}', 3, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(681, 114, 'interaction', '{\"question\": \"Duy nên viết tin nhắn như thế nào trong nhóm chat lớp để thể hiện vai trò Upstander một cách văn minh?\", \"choices\": [{\"text\": \"Tớ thấy trò đùa chế ảnh này không vui chút nào đâu các bạn ơi. Tụi mình dừng lại và xóa ảnh đi nhé.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Mấy đứa vô duyên kia im miệng lại hết đi, có giỏi thì ra ngoài đời thật nói chuyện xem nào!\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(682, 114, 'reflection', '{\"question\": \"Bạn có sẵn sàng lên tiếng bảo vệ một bạn học bị bắt nạt trên mạng nếu bạn có sự đồng hành của những người bạn khác không?\"}', 5, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(683, 114, 'takeaway', '{\"items\": [\"Người bảo vệ dũng cảm không dùng bạo lực để giải quyết bạo lực, họ dùng sự kiên định và tử tế để đẩy lùi bóng tối.\"]}', 6, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(684, 115, 'hook', '{\"title\": \"Làm sao để mỗi ngày mở mạng xã hội ra, bạn đều nhận lại những nụ cười ấm áp thay vì những cuộc cãi vã mệt mỏi?\"}', 1, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(685, 115, 'explanation', '{\"bullets\": [\"Văn hóa mạng được tạo nên từ hành vi của từng cá nhân sử dụng nó.\", \"Hãy lan tỏa năng lượng tích cực bằng cách: viết những lời khen ngợi chân thành, chia sẻ những câu chuyện tử tế, và hỗ trợ bạn bè.\", \"Gieo hạt mầm tử tế trên thế giới số hôm nay, bạn sẽ gặt hái được một không gian sống chung an toàn và hạnh phúc ngày mai.\"]}', 2, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(686, 115, 'scenario', '{\"title\": \"Hạt mầm tử tế\", \"body\": \"Hồng thấy bạn cùng bàn đăng ảnh khoe bức vẽ tự tay làm quà sinh nhật cho mẹ bị một vài người chê là vẽ xấu. Hồng liền vào bình luận thả tim khen ngợi nỗ lực và ý nghĩa bức vẽ.\"}', 3, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(687, 115, 'sorting', '{\"instruction\": \"Phân loại các hành dung góp phần xây dựng văn hóa số văn minh sau:\", \"leftBox\": {\"title\": \"Gieo hạt mầm tử tế\"}, \"rightBox\": {\"title\": \"Gieo mầm độc hại\"}, \"items\": [{\"text\": \"Thả tim và chúc mừng bài viết khoe thành tích học tập của bạn cùng lớp\", \"correctBox\": \"left\"}, {\"text\": \"Bình luận móc mỉa ngoại hình của một ca sĩ nổi tiếng dưới bài báo\", \"correctBox\": \"right\"}, {\"text\": \"Chia sẻ bài viết kêu gọi quyên góp giúp đỡ hoàn cảnh khó khăn thật sự\", \"correctBox\": \"left\"}, {\"text\": \"Spam các meme tục tĩu, phản cảm vào phần bình luận của người khác\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(688, 115, 'reflection', '{\"question\": \"Ngày hôm nay, bạn đã làm được việc tốt hay gửi đi thông điệp tử tế nào trên không gian mạng chưa?\"}', 5, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(689, 115, 'takeaway', '{\"items\": [\"Một thế giới mạng văn minh, tử tế bắt đầu từ chính hành động nhỏ bé của bạn ngày hôm nay.\"]}', 6, '2026-06-05 12:18:21', '2026-06-05 12:18:21'),
(690, 118, 'hook', '{\"title\": \"Có bao giờ bạn thức dậy và cảm thấy cơ thể hay cảm xúc của mình có chút \'lạ lẫm\' hơn hôm qua không?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(691, 118, 'explanation', '{\"bullets\": [\"Dậy thì (Puberty) là giai đoạn chuyển tiếp tự nhiên từ một đứa trẻ thành một người trưởng thành về mặt sinh học.\", \"Não bộ sẽ phát tín hiệu giải phóng các hormone (kẻ kích hoạt âm thầm) để khởi động hàng loạt thay đổi về thể chất lẫn cảm xúc.\", \"Đây là hành trình bắt buộc và hoàn toàn tự nhiên mà ai trong chúng ta cũng phải đi qua.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(692, 118, 'scenario', '{\"title\": \"Giọng nói lạ lẫm\", \"body\": \"Nam dạo này thấy mình cao vọt lên, giọng nói bỗng dưng ồm ồm như người lớn khiến cậu rất ngại ngùng mỗi khi phát biểu bài trước lớp.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(693, 118, 'flashcard', '{\"front\": \"Dậy thì có phải là một \'căn bệnh\' hay điều gì bất thường không?\", \"back\": \"Tuyệt đối KHÔNG. Đó là một quá trình sinh học kỳ diệu để chuẩn bị cho cơ thể bạn trưởng thành.\", \"notes\": \"Hãy xem nó như một bản cập nhật phần mềm (software update) cực kỳ quan trọng của cơ thể.\"}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(694, 118, 'reflection', '{\"question\": \"Bạn bắt đầu nhận thấy sự thay đổi nào đầu tiên trên cơ thể mình gần đây chưa?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(695, 118, 'takeaway', '{\"items\": [\"Dậy thì chỉ là cách cơ thể thông báo: \'Bạn đang lớn lên đấy thôi!\'.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(696, 119, 'hook', '{\"title\": \"Có phải tất cả mọi người đều dậy thì vào cùng một độ tuổi không?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(697, 119, 'explanation', '{\"bullets\": [\"Độ tuổi dậy thì phổ biến là từ 8 đến 14 tuổi, nhưng mỗi người có một chiếc đồng hồ sinh học riêng.\", \"Có bạn dậy thì rất sớm, có bạn lại dậy thì muộn hơn. Cả hai điều này đều hoàn toàn bình thường!\", \"Đừng lo lắng nếu bạn thấy mình \'lớn\' nhanh hơn hoặc chậm hơn các bạn cùng lớp.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(698, 119, 'scenario', '{\"title\": \"So sánh vóc dáng\", \"body\": \"Vy thấy các bạn nữ trong lớp đều đã bắt đầu cao lên và thay đổi vóc dáng, riêng mình vẫn nhỏ bé như học sinh tiểu học khiến Vy cảm thấy rất sốt ruột.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(699, 119, 'interaction', '{\"question\": \"Vy có nên quá lo lắng vì mình chưa dậy thì giống các bạn không?\", \"choices\": [{\"text\": \"Không nên lo lắng. Chiếc đồng hồ dậy thì của mỗi người là khác nhau và Vy rồi cũng sẽ dậy thì theo nhịp độ của riêng mình.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Có chứ, nên đi mua các loại thuốc tăng trưởng uống ngay để bắt kịp các bạn.\", \"correct\": false, \"emoji\": \"🙁\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(700, 119, 'reflection', '{\"question\": \"Bạn có từng cảm thấy tự ti khi so sánh tốc độ lớn của mình với một người bạn thân chưa?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(701, 119, 'takeaway', '{\"items\": [\"Mỗi cơ thể có một lịch trình riêng. Hãy kiên nhẫn và yêu thương nhịp điệu của chính mình.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(702, 120, 'hook', '{\"title\": \"Tại sao dậy thì lại đi kèm với những lo lắng và bỡ ngỡ khó tả thành lời?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(703, 120, 'explanation', '{\"bullets\": [\"Cơ thể thay đổi quá nhanh khiến não bộ chưa kịp thích nghi, dẫn đến cảm giác bất an hoặc lạ lẫm với chính mình.\", \"Bạn có thể thấy ngại ngùng với những bộ quần áo cũ không còn vừa, hoặc lo sợ người khác soi xét ngoại hình của mình.\", \"Chấp nhận rằng cảm giác \'bất ổn\' này là bình thường giúp bạn nhẹ lòng hơn rất nhiều.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(704, 120, 'scenario', '{\"title\": \"Quần áo chật chội\", \"body\": \"Mai cảm thấy bực bội khi chiếc quần jeans yêu thích bỗng chật ních ở hông, và cô bạn bắt đầu ghét việc phải mặc đồ ôm sát người.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(705, 120, 'sorting', '{\"instruction\": \"Phân loại các phản ứng trước những thay đổi đầu đời:\", \"leftBox\": {\"title\": \"Đón nhận tích cực\"}, \"rightBox\": {\"title\": \"Lo âu quá mức\"}, \"items\": [{\"text\": \"Tự nhủ: Cơ thể mình đang lớn lên và việc thay đổi này là hoàn toàn tự nhiên\", \"correctBox\": \"left\"}, {\"text\": \"Trốn tránh không dám đi chơi với bạn bè vì sợ họ nhận ra mình cao lên\", \"correctBox\": \"right\"}, {\"text\": \"Mua quần áo mới thoải mái hơn để phù hợp với vóc dáng hiện tại\", \"correctBox\": \"left\"}, {\"text\": \"Liên tục soi gương và tự trách móc bản thân vì cơ thể không giống ngày xưa\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(706, 120, 'reflection', '{\"question\": \"Cảm xúc nào khiến bạn thấy khó khăn nhất khi nghĩ về sự trưởng thành của bản thân?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(707, 120, 'takeaway', '{\"items\": [\"Bỡ ngỡ là một phần của sự trưởng thành. Bạn đang làm rất tốt hành trình này!\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(708, 121, 'hook', '{\"title\": \"Bạn sẽ làm gì khi bạn bè xung quanh bắt đầu đem những thay đổi cơ thể của bạn ra làm trò đùa?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(709, 121, 'explanation', '{\"bullets\": [\"Ở tuổi dậy thì, bạn bè thường tò mò và đôi khi có những lời trêu chọc thiếu tinh tế về giọng nói, chiều cao hay ngực.\", \"Những lời đùa đó có thể làm bạn tổn thương, nhưng hãy nhớ: lỗi không nằm ở cơ thể bạn.\", \"Học cách thiết lập ranh giới và phản hồi kiên định trước những lời trêu chọc vô duyên.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(710, 121, 'scenario', '{\"title\": \"Giờ ra chơi ồn ào\", \"body\": \"Trong giờ ra chơi, một nhóm bạn nam cười phá lên trêu giọng nói đang vỡ bị ồm và rè của Tuấn, khiến Tuấn đỏ mặt cúi gục xuống bàn.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(711, 121, 'flashcard', '{\"front\": \"Tuấn nên ứng phó thế nào để bảo vệ lòng tự trọng của mình một cách văn minh?\", \"back\": \"Tuấn có thể nhìn thẳng vào họ và nói bình thản: Giọng tớ đang thay đổi vì tớ đang dậy thì thôi, có gì lạ đâu cậu?.\", \"notes\": \"Sự tự tin và bình thản của bạn chính là câu trả lời mạnh mẽ nhất làm tắt đài những lời trêu chọc.\"}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(712, 121, 'reflection', '{\"question\": \"Bạn đã từng chứng kiến hay trải qua việc bị trêu chọc về ngoại hình ở trường chưa? Cảm xúc lúc đó thế nào?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(713, 121, 'takeaway', '{\"items\": [\"Cơ thể bạn đang làm việc chăm chỉ để lớn lên. Không ai có quyền chế giễu nỗ lực đó của bạn.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(714, 122, 'hook', '{\"title\": \"Bạn có thấy khó khăn khi muốn mở lời tâm sự những chuyện thầm kín tuổi dậy thì với bố mẹ không?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(715, 122, 'explanation', '{\"bullets\": [\"Nhiều bạn trẻ thấy xấu hổ khi nói về mụn, mùi cơ thể, hay kinh nguyệt với người lớn.\", \"Tuy nhiên, bố mẹ hay thầy cô đều đã từng đi qua giai đoạn này và họ có rất nhiều kinh nghiệm thực tế.\", \"Chọn một thời điểm thoải mái và một người lớn bạn tin tưởng nhất để bắt đầu cuộc trò chuyện.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(716, 122, 'scenario', '{\"title\": \"Yêu cầu khó mở lời\", \"body\": \"Linh bắt đầu nhận thấy ngực mình hơi đau và nhú lên, Linh muốn xin mẹ mua cho chiếc áo lót đầu tiên nhưng ngại ngùng không biết nói sao.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(717, 122, 'interaction', '{\"question\": \"Linh nên mở lời với mẹ thế nào cho tự nhiên và đỡ ngại?\", \"choices\": [{\"text\": \"Nhắn tin riêng cho mẹ hoặc nói nhỏ: Mẹ ơi, cơ thể con dạo này đang thay đổi chút ít, cuối tuần mẹ đi mua đồ lót mới với con nha mẹ?\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Im lặng tự chịu đựng đau đớn và tự lấy tiền tiết kiệm mua đại đồ lót không vừa cỡ trên mạng.\", \"correct\": false, \"emoji\": \"🙁\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(718, 122, 'reflection', '{\"question\": \"Ai là người lớn mà bạn cảm thấy thoải mái và tin tưởng nhất để hỏi về những thay đổi cơ thể?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(719, 122, 'takeaway', '{\"items\": [\"Bạn không cần phải tự mình gánh vác mọi thắc mắc. Hãy chia sẻ để nhận được sự nâng đỡ.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(720, 123, 'hook', '{\"title\": \"Bạn có sẵn sàng đón nhận phiên bản mới của chính mình với đầy niềm vui và sự tự tin không?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(721, 123, 'explanation', '{\"bullets\": [\"Dậy thì là dấu mốc đánh dấu bạn đang bước vào một chương mới thú vị của cuộc đời.\", \"Phiên bản mới này đi kèm với nhiều quyền tự chủ hơn, nhiều khả năng mới và chiều sâu cảm xúc hơn.\", \"Hãy chào đón những thay đổi này với sự tò mò lành mạnh thay vì sợ hãi.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(722, 123, 'scenario', '{\"title\": \"Độc lập hơn\", \"body\": \"Khánh dạo này tự dọn phòng, biết tự chọn trang phục phù hợp đi chơi và bắt đầu biết quan tâm chăm sóc sức khỏe cá nhân kỹ hơn.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(723, 123, 'sorting', '{\"instruction\": \"Phân loại các suy nghĩ về hành trình dậy thì của bạn:\", \"leftBox\": {\"title\": \"Chào đón phiên bản mới\"}, \"rightBox\": {\"title\": \"Khước từ lớn lên\"}, \"items\": [{\"text\": \"Tò mò tìm hiểu kiến thức y khoa để chăm sóc bản thân tốt hơn\", \"correctBox\": \"left\"}, {\"text\": \"Luôn ước mình mãi là đứa trẻ tiểu học để không phải thay đổi\", \"correctBox\": \"right\"}, {\"text\": \"Tự hào vì mình đang cao lớn và trưởng thành hơn mỗi ngày\", \"correctBox\": \"left\"}, {\"text\": \"Ghét bỏ cơ thể vì nó bắt đầu có mùi hoặc mọc mụn\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(724, 123, 'reflection', '{\"question\": \"Bạn mong chờ điều gì nhất ở phiên bản trưởng thành của mình trong tương lai?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(725, 123, 'takeaway', '{\"items\": [\"Chào mừng bạn đến với hành trình lớn lên. Hãy tự hào về phiên bản nâng cấp của chính mình!\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(726, 124, 'hook', '{\"title\": \"Tại sao dạo này sau mỗi tiết thể dục, bạn lại ngửi thấy mùi cơ thể mình đậm hơn trước rất nhiều?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(727, 124, 'explanation', '{\"bullets\": [\"Dưới tác động của hormone, các tuyến mồ hôi đặc biệt ở nách và vùng kín bắt đầu hoạt động mạnh mẽ.\", \"Bản thân mồ hôi không có mùi, nhưng vi khuẩn trên da phân hủy mồ hôi sẽ tạo nên mùi cơ thể đặc trưng.\", \"Đây là hiện tượng sinh lý hoàn toàn bình thường, chỉ cần bạn học cách vệ sinh sạch sẽ mỗi ngày.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(728, 124, 'scenario', '{\"title\": \"Ướt đẫm nách áo\", \"body\": \"Huy nhận thấy nách áo của mình dạo này hay bị ướt và có mùi hôi sau khi đá bóng, khiến Huy rất tự ti không dám ngồi gần các bạn trong lớp.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(729, 124, 'flashcard', '{\"front\": \"Làm sao để kiểm soát mùi cơ thể tuổi dậy thì hiệu quả?\", \"back\": \"Tắm rửa xà phòng hàng ngày, thay quần áo sạch (đặc biệt là đồ lót bằng vải cotton), và có thể sử dụng thêm lăn/xịt khử mùi sau khi lau khô da.\", \"notes\": \"Đừng dùng nước hoa xịt đè lên mùi mồ hôi, nó sẽ tạo ra một hỗn hợp mùi cực kỳ đáng sợ đấy!\"}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(730, 124, 'reflection', '{\"question\": \"Bạn đã trang bị cho mình một chai lăn khử mùi hoặc nước hoa nhẹ nhàng cho những ngày nắng nóng chưa?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(731, 124, 'takeaway', '{\"items\": [\"Mùi cơ thể chỉ là tín hiệu nhắc nhở bạn: Đã đến lúc nâng cấp thói quen vệ sinh cá nhân rồi!\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(732, 125, 'hook', '{\"title\": \"Tại sao những nốt mụn đáng ghét lại chọn đúng thời điểm này để thi nhau biểu tình trên khuôn mặt bạn?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(733, 125, 'explanation', '{\"bullets\": [\"Hormone dậy thì kích thích tuyến bã nhờn sản xuất quá nhiều dầu thừa trên da mặt.\", \"Dầu thừa kết hợp với tế bào chết gây tắc nghẽn lỗ chân lông, tạo môi trường cho vi khuẩn gây mụn phát triển.\", \"Mụn là một phần trải nghiệm của hầu hết mọi thanh thiếu niên, không phải do bạn ở bẩn đâu nhé.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(734, 125, 'scenario', '{\"title\": \"Nốt mụn chụp ảnh kỷ yếu\", \"body\": \"Vy thức dậy và phát hiện một chiếc mụn bọc to tướng, đỏ chót ngay trên chóp mũi trước ngày chụp ảnh kỷ yếu của lớp. Vy muốn nặn nó ra ngay.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(735, 125, 'interaction', '{\"question\": \"Vy có nên tự ý dùng tay nặn chiếc mụn bọc đó ngay lập tức không?\", \"choices\": [{\"text\": \"Không nên. Tự nặn mụn bằng tay bẩn dễ gây nhiễm trùng sâu hơn, làm mụn sưng to và để lại sẹo thâm khó lành.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Nên nặn ngay để xẹp mụn nhanh chóng, dùng lực thật mạnh là được.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(736, 125, 'reflection', '{\"question\": \"Bạn đã xây dựng cho mình một chu trình rửa mặt đơn giản với sữa rửa mặt dịu nhẹ mỗi sáng và tối chưa?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(737, 125, 'takeaway', '{\"items\": [\"Mụn chỉ là tạm thời, vết thâm do nặn mụn bừa bãi mới là vĩnh viễn. Hãy kiên nhẫn chăm sóc làn da.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(738, 126, 'hook', '{\"title\": \"Bạn cảm thấy thế nào khi bỗng dưng nhìn thấy lông nách, lông mu hoặc ria mép xuất hiện rậm rạp trên cơ thể mình?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(739, 126, 'explanation', '{\"bullets\": [\"Lông cơ thể phát triển ở vùng nách, vùng kín, chân, tay và mặt là dấu hiệu trưởng thành sinh dục bình thường.\", \"Lông có vai trò bảo vệ các vùng da nhạy cảm khỏi ma sát và vi khuẩn.\", \"Việc giữ lại hay cạo/tẩy lông hoàn toàn là sở thích cá nhân, không có đúng hay sai về mặt đạo đức.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(740, 126, 'scenario', '{\"title\": \"Ria mép mọc rậm\", \"body\": \"Thành bắt đầu mọc ria mép sẫm màu. Bạn bè trêu Thành trông giống ông cụ, khiến Thành cảm thấy rất tự ti.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(741, 126, 'sorting', '{\"instruction\": \"Phân loại các quan điểm về lông cơ thể tuổi dậy thì:\", \"leftBox\": {\"title\": \"Tôn trọng sở thích\"}, \"rightBox\": {\"title\": \"Áp đặt định kiến\"}, \"items\": [{\"text\": \"Cơ thể mình, mình có quyền quyết định cạo hay giữ lông nách\", \"correctBox\": \"left\"}, {\"text\": \"Con gái là tuyệt đối không được có lông chân, trông rất thô và xấu\", \"correctBox\": \"right\"}, {\"text\": \"Dùng các biện pháp tẩy lông an toàn, vệ sinh sạch sẽ nếu muốn cạo\", \"correctBox\": \"left\"}, {\"text\": \"Chế giễu bạn nam cùng lớp vì chưa mọc ria mép giống mọi người\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(742, 126, 'reflection', '{\"question\": \"Bạn có cảm thấy áp lực từ bạn bè hay mạng xã hội bắt buộc bạn phải cạo sạch lông cơ thể không?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(743, 126, 'takeaway', '{\"items\": [\"Lông cơ thể là tấm khiên tự nhiên. Hãy quyết định số phận của chúng dựa trên sự thoải mái của chính bạn.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(744, 127, 'hook', '{\"title\": \"Làm sao để tự tin đến trường học tập và vui chơi khi khuôn mặt đang trong giai đoạn bùng phát mụn?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(745, 127, 'explanation', '{\"bullets\": [\"Mụn dễ làm tụi mình cảm thấy tự ti, nghĩ rằng ai cũng đang nhìn chăm chăm vào khuyết điểm của mình.\", \"Thực tế, bạn bè xung quanh cũng đang bận rộn lo lắng về khuyết điểm của chính họ.\", \"Vẻ đẹp của bạn nằm ở thần thái, nụ cười và sự tự tin, không nằm ở một làn da không tì vết.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(746, 127, 'scenario', '{\"title\": \"Tự ti che mặt\", \"body\": \"Lan có nhiều mụn thâm trên má. Khi đi học, Lan luôn cúi gầm mặt, lấy tóc xõa che kín hai bên má và từ chối phát biểu trước lớp.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(747, 127, 'flashcard', '{\"front\": \"Lan nên làm gì để lấy lại sự tự tin trước đám đông dù da đang có mụn?\", \"back\": \"Tập trung vào thế mạnh học tập, mỉm cười thân thiện, ngẩng cao đầu và tự nhắc nhở: Mọi người yêu quý mình vì tính cách và tài năng, chứ không phải vì vài nốt mụn.\", \"notes\": \"Tình bạn đích thực không đo bằng mức độ mịn màng của làn da.\"}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(748, 127, 'reflection', '{\"question\": \"Bạn có từng đánh giá hay bớt yêu quý một người bạn chỉ vì da mặt của bạn ấy có nhiều mụn không?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(749, 127, 'takeaway', '{\"items\": [\"Tự tin là lớp trang điểm đẹp nhất. Đừng để những nốt mụn nhỏ che lấp đi ánh sáng rực rỡ của bạn.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(750, 128, 'hook', '{\"title\": \"Bạn đã biết cách làm sạch cơ thể đúng điệu để luôn thơm tho và khỏe mạnh suốt cả ngày chưa?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(751, 128, 'explanation', '{\"bullets\": [\"Tắm rửa hàng ngày bằng sữa tắm dịu nhẹ, chú ý làm sạch các vùng da gấp nếp như nách, bẹn và vùng kín.\", \"Vùng kín cần được rửa nhẹ nhàng bằng nước sạch hoặc dung dịch vệ sinh phù hợp, tuyệt đối không thụt rửa sâu bên trong.\", \"Lau khô người bằng khăn sạch trước khi mặc quần áo để tránh nấm ngứa phát triển.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(752, 128, 'scenario', '{\"title\": \"Tắm lướt vội vàng\", \"body\": \"Bách thường tắm rất nhanh, chỉ dội nước qua loa và không dùng xà phòng, dẫn đến vùng lưng bắt đầu nổi nhiều mụn ngứa.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(753, 128, 'interaction', '{\"question\": \"Bách nên thay đổi thói quen tắm rửa thế nào cho đúng cách khoa học?\", \"choices\": [{\"text\": \"Tắm kỹ hơn, dùng sữa tắm dịu nhẹ chà sạch vùng lưng và lau khô cơ thể bằng khăn sạch sau khi tắm.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tiếp tục tắm nhanh nhưng xịt thật nhiều nước hoa lên người sau khi tắm để lấn át mùi.\", \"correct\": false, \"emoji\": \"🙁\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(754, 128, 'reflection', '{\"question\": \"Bạn có thói quen thay đồ lót sạch mỗi ngày sau khi tắm không? Đây là bước cực kỳ quan trọng để bảo vệ vùng kín đấy.\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(755, 128, 'takeaway', '{\"items\": [\"Chăm sóc cơ thể sạch sẽ là cách bạn thể hiện lòng trân trọng đối với ngôi nhà sinh học của mình.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(756, 129, 'hook', '{\"title\": \"Làm sao để hòa giải với những thay đổi thể chất đôi khi trông hơi kỳ cục của tuổi mới lớn?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(757, 129, 'explanation', '{\"bullets\": [\"Dậy thì có thể khiến tay chân bạn dài ra nhanh chóng trước khi thân người phát triển kịp, tạo cảm giác hơi lóng ngóng.\", \"Ngực của bạn gái có thể bên to bên nhỏ không đều, bạn trai có thể thấy hơi sưng đau ở núm vú.\", \"Trân trọng sự độc đáo của cơ thể mình thay vì ép nó phải giống một khuôn mẫu hoàn hảo nào đó.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(758, 129, 'scenario', '{\"title\": \"Cơ thể lóng ngóng\", \"body\": \"Hoàng dạo này lớn nhanh quá nên đi lại hay bị vấp ngã, ngực thì hơi sưng đau nhè nhẹ khiến cậu sợ hãi nghĩ mình bị ung thư.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(759, 129, 'sorting', '{\"instruction\": \"Phân loại các cách phản ứng với cơ thể đang thay đổi:\", \"leftBox\": {\"title\": \"Yêu thương chấp nhận\"}, \"rightBox\": {\"title\": \"Phủ nhận ghét bỏ\"}, \"items\": [{\"text\": \"Tự nhắc nhở: Sự bất cân đối cơ thể lúc dậy thì là tạm thời và bình thường\", \"correctBox\": \"left\"}, {\"text\": \"Dùng các đai nịt ngực quá chặt vì xấu hổ khi thấy ngực phát triển\", \"correctBox\": \"right\"}, {\"text\": \"Tập các bài tập giãn cơ nhẹ nhàng để thích nghi với chiều cao mới\", \"correctBox\": \"left\"}, {\"text\": \"Nhịn ăn giảm cân cực đoan vì thấy vóc dáng tròn trịa hơn trước\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(760, 129, 'reflection', '{\"question\": \"Có bộ phận nào trên cơ thể đang thay đổi khiến bạn thấy lo lắng không? Bạn có muốn tìm hiểu thêm về nó một cách khoa học?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(761, 129, 'takeaway', '{\"items\": [\"Cơ thể bạn là duy nhất và đang nỗ lực hết mình để lớn lên. Hãy kiên nhẫn đồng hành cùng nó nhé.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(762, 130, 'hook', '{\"title\": \"Bạn có biết bên trong cơ thể tụi mình đang diễn ra một cuộc tổng diễn tập âm thầm để chuẩn bị cho khả năng sinh sản không?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(763, 130, 'explanation', '{\"bullets\": [\"Ở bạn gái, buồng trứng bắt đầu rụng trứng và tử cung chuẩn bị lớp niêm mạc giàu dinh dưỡng mỗi tháng.\", \"Ở bạn trai, tinh hoàn bắt đầu sản xuất hàng triệu tinh trùng và hormone testosterone mỗi ngày.\", \"Đây là hoạt động sinh học bình thường chuẩn bị cho vai trò làm cha mẹ trong tương lai xa.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(764, 130, 'scenario', '{\"title\": \"Đau bụng nhẹ\", \"body\": \"Thảo dạo này thỉnh thoảng thấy đau nhẹ ở vùng bụng dưới vào giữa tháng, cô bé lo sợ mình bị đau ruột thừa.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(765, 130, 'flashcard', '{\"front\": \"Cơ quan sinh sản bên trong hoạt động có gây ra cảm giác đau đớn gì bình thường không?\", \"back\": \"Bạn gái có thể thấy hơi đau bụng dưới nhẹ khi rụng trứng hoặc hành kinh; bạn trai có thể thấy hơi căng tức tinh hoàn nhẹ. Nếu đau dữ dội, hãy báo ngay cho người lớn.\", \"notes\": \"Lắng nghe tín hiệu cơ thể để biết khi nào cần nghỉ ngơi.\"}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(766, 130, 'reflection', '{\"question\": \"Bạn đã từng học về cơ quan sinh sản trong môn Sinh học ở trường chưa? Bạn có câu hỏi nào chưa được giải đáp không?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(767, 130, 'takeaway', '{\"items\": [\"Hệ sinh sản thức giấc là minh chứng rõ ràng nhất cho thấy bạn đang tiến gần hơn tới thế giới của người lớn.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(768, 131, 'hook', '{\"title\": \"Làm sao để không hoảng loạn khi đột ngột thấy vệt máu trên quần chip hoặc thức dậy với chiếc quần ướt át?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(769, 131, 'explanation', '{\"bullets\": [\"Kinh nguyệt (Period) là hiện tượng lớp niêm mạc tử cung bong ra và thoát ra ngoài khi không có sự thụ tinh. Nó đánh dấu bạn gái có khả năng mang thai.\", \"Mộng tinh (Wet Dream) là hiện tượng xuất tinh tự nhiên không chủ ý khi đang ngủ ở bạn trai, giúp giải phóng lượng tinh dịch thừa.\", \"Cả hai hiện tượng này đều là cột mốc sinh lý tự nhiên bình thường đáng mừng!\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(770, 131, 'scenario', '{\"title\": \"Quần lót dính dịch\", \"body\": \"Duy thức dậy vào buổi sáng và phát hiện quần lót của mình bị ướt một khoảng lớn dính dính. Duy nghĩ mình bị bệnh nặng và vội vàng giấu chiếc quần lót đi vì xấu hổ.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(771, 131, 'interaction', '{\"question\": \"Duy nên hiểu hiện tượng này thế nào cho đúng khoa học?\", \"choices\": [{\"text\": \"Đây là hiện tượng mộng tinh hoàn toàn bình thường ở bạn trai dậy thì. Duy chỉ cần đem quần đi giặt sạch và không cần phải xấu hổ hay lo sợ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Chắc chắn Duy đã bị viêm đường tiết niệu nặng, cần phải đi mua thuốc kháng sinh tự uống ngay.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(772, 131, 'reflection', '{\"question\": \"Bạn gái đã chuẩn bị sẵn sàng tâm lý đón nhận kỳ kinh đầu tiên, và bạn trai đã hiểu về mộng tinh chưa?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(773, 131, 'takeaway', '{\"items\": [\"Kinh nguyệt hay mộng tinh là những vị khách tự nhiên của tuổi dậy thì. Hãy đón tiếp chúng một cách bình tĩnh.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(774, 132, 'hook', '{\"title\": \"Tại sao nhiều người vẫn coi kinh nguyệt hay mộng tinh là điều gì đó dơ bẩn và ngại nhắc đến công khai?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(775, 132, 'explanation', '{\"bullets\": [\"Do những định kiến cũ kỹ và thiếu kiến thức khoa học nên xã hội từng coi đây là chủ đề cấm kỵ.\", \"Thực chất, máu kinh nguyệt hay tinh dịch là những chất dịch sinh học hoàn toàn sạch sẽ, không có gì tội lỗi.\", \"Nói chuyện cởi mở và khoa học giúp xóa bỏ sự kỳ thị và giúp đỡ nhau tốt hơn khi gặp sự cố.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(776, 132, 'scenario', '{\"title\": \"Băng vệ sinh rơi ra\", \"body\": \"Một miếng băng vệ sinh chưa dùng rơi ra từ cặp sách của Hân trong lớp, các bạn nam bắt đầu chỉ trỏ trêu chọc khiến Hân xấu hổ khóc nức nở.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(777, 132, 'sorting', '{\"instruction\": \"Phân loại các cách ứng xử đối với chủ đề kinh nguyệt/mộng tinh:\", \"leftBox\": {\"title\": \"Cởi mở văn minh\"}, \"rightBox\": {\"title\": \"Kỳ thị né tránh\"}, \"items\": [{\"text\": \"Vui vẻ cho bạn mượn băng vệ sinh khi bạn gặp sự cố khẩn cấp ở lớp\", \"correctBox\": \"left\"}, {\"text\": \"Cười cợt, trêu chọc khi thấy bạn gái vô tình bị dây máu kinh ra váy\", \"correctBox\": \"right\"}, {\"text\": \"Chủ động tìm hiểu kiến thức để chăm sóc bản thân và thấu cảm với bạn khác giới\", \"correctBox\": \"left\"}, {\"text\": \"Lấy từ mộng tinh ra để làm từ ngữ chửi bới, hạ nhục bạn bè\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(778, 132, 'reflection', '{\"question\": \"Bạn có thấy ngại ngùng khi đi mua băng vệ sinh ở tiệm tạp hóa không? Tại sao tụi mình lại có cảm giác đó nhỉ?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(779, 132, 'takeaway', '{\"items\": [\"Kinh nguyệt và sinh sản là cội nguồn của sự sống. Hãy tôn trọng và tự hào về cơ thể mình.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(780, 133, 'hook', '{\"title\": \"Làm sao để xử lý thật êm đẹp và bình tĩnh khi đột ngột bị đến tháng ngay trong giờ học mà không mang theo dụng cụ dự phòng?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(781, 133, 'explanation', '{\"bullets\": [\"Đừng hoảng loạn, đây là sự cố mà hầu như bạn gái nào cũng từng trải qua ít nhất một lần.\", \"Bạn có thể tạm thời lót giấy vệ sinh sạch vào quần chip và đi tìm sự trợ giúp ngay lập tức.\", \"Tình bạn và sự hỗ trợ từ các bạn gái khác hoặc cô giáo y tế là chiếc phao cứu sinh tuyệt vời.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(782, 133, 'scenario', '{\"title\": \"Vệt đỏ sau váy\", \"body\": \"Trong tiết Toán, Trang bỗng cảm thấy bụng dưới quặn đau và có dịch ẩm tràn ra. Khi đứng dậy phát hiện váy đồng phục phía sau đã bị thấm một vệt đỏ nhỏ. Trang vô cùng xấu hổ.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(783, 133, 'flashcard', '{\"front\": \"Bạn bè xung quanh nên giúp đỡ Trang thế nào trong tình huống này?\", \"back\": \"Bạn ngồi cạnh có thể cho Trang mượn áo khoác buộc ngang hông để che vệt đỏ, đưa cho Trang một miếng băng vệ sinh dự phòng và đi cùng Trang xuống phòng y tế trường.\", \"notes\": \"Sự tinh tế và giúp đỡ kịp thời của bạn là món quà vô giá giúp bạn mình đỡ tủi thân.\"}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(784, 133, 'reflection', '{\"question\": \"Bạn luôn mang theo một miếng băng vệ sinh nhỏ trong ba lô đi học để dự phòng cho mình và bạn bè chứ?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(785, 133, 'takeaway', '{\"items\": [\"Giúp đỡ bạn bè khi gặp sự cố hành kinh là biểu hiện cao nhất của sự tinh tế và tử tế tuổi học trò.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(786, 134, 'hook', '{\"title\": \"Bạn đã biết cách lựa chọn và sử dụng băng vệ sinh đúng chuẩn để luôn khô thoáng, tự tin trong những ngày đèn đỏ chưa?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(787, 134, 'explanation', '{\"bullets\": [\"Bóc lớp giấy dán phía sau băng vệ sinh và dán chặt vào đáy quần chip, ôm khít cơ thể.\", \"Thay băng vệ sinh sau mỗi 3 đến 4 tiếng để ngăn ngừa vi khuẩn sinh sôi gây mùi và viêm nhiễm.\", \"Cuộn tròn băng vệ sinh đã dùng vào giấy gói sạch và bỏ vào thùng rác, tuyệt đối không vứt vào bồn cầu.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(788, 134, 'scenario', '{\"title\": \"Ngại thay băng vệ sinh\", \"body\": \"Mai nghĩ rằng máu kinh ra ít nên để nguyên một miếng băng vệ sinh suốt từ sáng đi học đến tối mịt mới thay, dẫn đến vùng kín bị ngứa ngáy.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(789, 134, 'interaction', '{\"question\": \"Mai đã mắc sai lầm gì trong việc sử dụng băng vệ sinh?\", \"choices\": [{\"text\": \"Mai để băng vệ sinh quá lâu không thay (quá 4 tiếng), tạo điều kiện cho vi khuẩn phát triển gây viêm nhiễm da.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Mai nên dùng nước xà phòng thụt rửa sâu bên trong âm đạo để làm sạch triệt để.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(790, 134, 'reflection', '{\"question\": \"Bạn có tự lập cho mình một chiếc túi nhỏ xinh đựng băng vệ sinh, quần chip dự phòng trong ba lô chưa?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(791, 134, 'takeaway', '{\"items\": [\"Thay băng đúng giờ giúp bạn luôn khô thoáng, sạch sẽ và tràn đầy năng lượng hoạt động.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(792, 135, 'hook', '{\"title\": \"Làm sao để sống hòa bình và yêu thương hệ sinh sản của mình thay vì coi nó là nguồn cơn của những rắc rối?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(793, 135, 'explanation', '{\"bullets\": [\"Những cơn đau bụng kinh, sự ẩm ướt của mộng tinh hay mụn nội tiết đôi khi khiến bạn thấy ghét bỏ cơ thể.\", \"Nhưng hãy nhớ, hệ sinh sản đang làm việc ngày đêm để giúp bạn phát triển toàn diện cả về thể chất lẫn nội tiết tố.\", \"Học cách lắng nghe, chăm sóc và thấu cảm với những chu kỳ sinh học của bản thân.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(794, 135, 'scenario', '{\"title\": \"Cảm giác ghét bỏ cơ thể\", \"body\": \"Mỗi lần đến tháng đau bụng nằm bẹp một chỗ, Hoa lại cáu bẳn tự trách cơ thể mình phiền phức và ước gì mình sinh ra không có tử cung.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(795, 135, 'sorting', '{\"instruction\": \"Phân loại các thói quen chăm sóc sức khỏe sinh sản:\", \"leftBox\": {\"title\": \"Chăm sóc thông thái\"}, \"rightBox\": {\"title\": \"Gây hại cơ thể\"}, \"items\": [{\"text\": \"Ghi chép ngày bắt đầu kinh nguyệt vào ứng dụng điện thoại để theo dõi chu kỳ\", \"correctBox\": \"left\"}, {\"text\": \"Uống thuốc giảm đau bụng kinh vô tội vạ mà không hỏi ý kiến bác sĩ\", \"correctBox\": \"right\"}, {\"text\": \"Chườm ấm bụng dưới và uống nước ấm để giảm nhẹ cơn đau bụng kinh\", \"correctBox\": \"left\"}, {\"text\": \"Mặc quần lót ẩm ướt sau khi vận động thể thao vì lười thay\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(796, 135, 'reflection', '{\"question\": \"Bạn có đang sử dụng ứng dụng nào trên điện thoại để theo dõi chu kỳ kinh nguyệt của mình không? Nó rất tiện lợi đấy!\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(797, 135, 'takeaway', '{\"items\": [\"Thấu hiểu chu kỳ cơ thể giúp bạn làm chủ sức khỏe và tự tin bước qua tuổi dậy thì.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(798, 136, 'hook', '{\"title\": \"Có bao giờ bạn bỗng dưng muốn khóc hoặc nổi giận đùng đùng mà chính bản thân cũng không giải thích nổi lý do không?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(799, 136, 'explanation', '{\"bullets\": [\"Tuổi dậy thì là thời kỳ nồng độ các hormone estrogen (ở nữ) và testosterone (ở nam) tăng vọt đột ngột.\", \"Những chất hóa học này tác động trực tiếp lên vùng não điều khiển cảm xúc, khiến tâm trạng của bạn biến đổi liên tục.\", \"Sự thay đổi tâm trạng này không phải do bạn hư, đó chỉ là phản ứng sinh lý tạm thời.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(800, 136, 'scenario', '{\"title\": \"Khóc vô cớ\", \"body\": \"Hạnh đang xem một chương trình hoạt hình vui nhộn bỗng dưng nước mắt trào ra dữ dội, cảm thấy buồn bã tột cùng mà không hiểu vì sao.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(801, 136, 'flashcard', '{\"front\": \"Có phải cảm xúc thất thường tuổi dậy thì là do bạn cố tình gây sự hoặc không biết kiềm chế?\", \"back\": \"KHÔNG. Đó chủ yếu là do sự xáo trộn mạnh mẽ của các hormone trong não bộ gây ra. Cảm xúc này hoàn toàn có thật và bạn cần thời gian để làm quen.\", \"notes\": \"Hãy tự nói với mình: Cảm xúc này là tạm thời, mình sẽ bình tĩnh lại sớm thôi.\"}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(802, 136, 'reflection', '{\"question\": \"Lần gần đây nhất bạn nổi cáu vô cớ với ai đó là khi nào? Bạn có nhận ra nguyên nhân lúc đó không?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(803, 136, 'takeaway', '{\"items\": [\"Cơn bão cảm xúc chỉ là phản ứng của não bộ trước bản cập nhật hormone mới. Đừng quá khắt khe với bản thân.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(804, 137, 'hook', '{\"title\": \"Làm sao để nhận diện cơn giận trước khi nó bùng phát thành hành động làm tổn thương người khác?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(805, 137, 'explanation', '{\"bullets\": [\"Cơn giận thường gửi tín hiệu trên cơ thể trước: tim đập nhanh, mặt nóng bừng, nghiến răng.\", \"Nhận biết những tín hiệu báo động này giúp bạn kịp thời phanh lại trước khi nói ra những lời hối hận.\", \"Chấp nhận cảm xúc giận dữ nhưng học cách bày tỏ nó một cách văn minh, không phá hủy mối quan hệ.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(806, 137, 'scenario', '{\"title\": \"Vở vẽ bị đổ nước\", \"body\": \"Em trai vô tình làm đổ nước vào cuốn vở vẽ của Bình. Bình thấy máu nóng dồn lên mặt, tim đập thình thịch và định lao vào đánh em.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(807, 137, 'interaction', '{\"question\": \"Bình nên làm gì ngay lúc đó để xử lý cơn giận một cách Green Flag?\", \"choices\": [{\"text\": \"Hít thở sâu 3 nhịp, đi ra chỗ khác rửa mặt bằng nước lạnh để hạ nhiệt trước khi quay lại nói chuyện với em.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Lao vào giật tóc em và ném đồ đạc để em biết thế nào là lễ độ.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(808, 137, 'reflection', '{\"question\": \"Cơ thể bạn thường báo động điều gì đầu tiên khi bạn bắt đầu chuẩn bị nổi giận?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(809, 137, 'takeaway', '{\"items\": [\"Bạn có quyền cảm thấy giận dữ, nhưng bạn không có quyền dùng cơn giận để làm tổn thương người khác.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(810, 138, 'hook', '{\"title\": \"Tại sao tuổi dậy thì tụi mình lại cực kỳ nhạy cảm và dễ suy diễn trước những ánh mắt, lời nói của người xung quanh?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(811, 138, 'explanation', '{\"bullets\": [\"Bộ não tuổi teen đang tái cấu trúc, khiến bạn có xu hướng nghĩ rằng ai cũng đang nhìn và đánh giá mình.\", \"Một lời nhận xét vô tình của bạn bè cũng có thể bị bạn phóng đại lên thành sự chỉ trích, ghét bỏ.\", \"Hãy nhớ: hầu hết mọi người chỉ đang bận tâm đến bản thân họ, họ không soi xét bạn kỹ đâu.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(812, 138, 'scenario', '{\"title\": \"Cái nhìn của bạn cùng lớp\", \"body\": \"Vy đi ngang qua nhóm bạn đang thì thầm nói chuyện, thấy một bạn nhìn mình rồi quay đi cười. Vy lập tức nghĩ họ đang nói xấu chiếc quần bị bẩn của mình.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(813, 138, 'sorting', '{\"instruction\": \"Phân loại các suy nghĩ khi đối mặt với nhận xét của người khác:\", \"leftBox\": {\"title\": \"Suy nghĩ tỉnh táo\"}, \"rightBox\": {\"title\": \"Suy diễn phóng đại\"}, \"items\": [{\"text\": \"Bạn ấy nhìn mình chắc là vì áo mình có dính vết bẩn gì thôi, cứ hỏi thử xem sao\", \"correctBox\": \"left\"}, {\"text\": \"Thầy giáo không gọi mình phát biểu chắc chắn là vì thầy ghét mình và thấy mình dốt\", \"correctBox\": \"right\"}, {\"text\": \"Lời góp ý của bạn là để slide bài tập nhóm của mình tốt hơn, không có ý chê bai cá nhân\", \"correctBox\": \"left\"}, {\"text\": \"Mọi người đang cười nói khi mình đi qua chắc chắn là họ đang bàn tán nói xấu mình\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(814, 138, 'reflection', '{\"question\": \"Bạn có từng mất ngủ cả đêm chỉ vì một câu nói đùa vô tình của một người bạn cùng lớp chưa?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(815, 138, 'takeaway', '{\"items\": [\"Đừng để chiếc kính lúp suy diễn bóp méo sự thật. Hãy nhìn mọi việc với lăng kính đơn giản hơn.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(816, 139, 'hook', '{\"title\": \"Làm sao để bày tỏ mong muốn tự lập của mình mà không biến mọi cuộc trò chuyện với bố mẹ thành một trận cãi vã?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(817, 139, 'explanation', '{\"bullets\": [\"Mong muốn tự chủ tăng lên khiến bạn dễ cảm thấy bố mẹ kiểm soát quá đà, áp đặt hoặc không thấu hiểu mình.\", \"Tuy nhiên, cãi vã, đóng sầm cửa hay chiến tranh lạnh chỉ khiến khoảng cách thế hệ càng thêm xa.\", \"Dùng kỹ năng giao tiếp tôn trọng để bày tỏ suy nghĩ của bạn một cách trưởng thành.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(818, 139, 'scenario', '{\"title\": \"Chọn trang phục đi tiệc\", \"body\": \"Mẹ muốn Vy mặc chiếc váy ren xòe đi tiệc cưới họ hàng, nhưng Vy thích mặc quần jeans năng động hơn. Mẹ bảo Vy bướng bỉnh, Vy thấy uất ức.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(819, 139, 'flashcard', '{\"front\": \"Vy nên nói chuyện với mẹ thế nào để giữ được chính kiến mà không gây hỗn hào?\", \"back\": \"Vy có thể nói nhẹ nhàng: Mẹ ơi, con mặc quần jeans này trông vẫn rất lịch sự và con thấy thoải mái nhất khi di chuyển. Mẹ tôn trọng lựa chọn này của con nha mẹ?.\", \"notes\": \"Lời nói nhẹ nhàng nhưng kiên định luôn hiệu quả hơn tiếng la hét tức giận.\"}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(820, 139, 'reflection', '{\"question\": \"Bạn có hay chọn cách la hét hay chọn cách im lặng lánh mặt khi bất đồng ý kiến với bố mẹ?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(821, 139, 'takeaway', '{\"items\": [\"Bày tỏ sự trưởng thành bằng cách giao tiếp tôn trọng, bố mẹ sẽ dễ lắng nghe tiếng nói của bạn hơn.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(822, 140, 'hook', '{\"title\": \"Bạn đã tích lũy cho mình những bí kíp siêu dễ để kéo tâm trạng lên mỗi khi cảm thấy buồn bã hoặc stress chưa?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(823, 140, 'explanation', '{\"bullets\": [\"Viết nhật ký để trút bỏ mọi suy nghĩ lộn xộn ra trang giấy.\", \"Vận động thể thao nhẹ nhàng: đi bộ, đạp xe giúp cơ thể tiết ra hormone hạnh phúc.\", \"Dành 5 phút hít thở sâu hoặc nghe một bản nhạc êm dịu không lời để xoa dịu thần kinh.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(824, 140, 'scenario', '{\"title\": \"Áp lực thi cử\", \"body\": \"Hùng cảm thấy vô cùng áp lực trước kỳ thi học kỳ, đầu óc Hùng trống rỗng và Hùng bắt đầu thấy bồn chồn đau bụng dữ dội do lo âu.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(825, 140, 'interaction', '{\"question\": \"Hùng nên dùng phương pháp nào để xoa dịu sự lo âu ngay lúc này?\", \"choices\": [{\"text\": \"Tạm dừng học 15 phút, nhắm mắt hít thở sâu theo nhịp 4-7-8 và uống một ngụm nước ấm.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tiếp tục cố ngồi học thêm 3 tiếng nữa dưới áp lực căng thẳng cao độ.\", \"correct\": false, \"emoji\": \"🙁\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(826, 140, 'reflection', '{\"question\": \"Hoạt động nào thường giúp bạn lấy lại sự bình yên và năng lượng nhanh nhất mỗi khi gặp áp lực?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(827, 140, 'takeaway', '{\"items\": [\"Chăm sóc sức khỏe tinh thần cũng quan trọng như chăm sóc thể chất. Hãy cho phép bản thân nghỉ ngơi khi cần.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(828, 141, 'hook', '{\"title\": \"Học cách coi những xáo trộn cảm xúc tuổi dậy thì là một trải nghiệm phong phú của cuộc sống, tại sao không?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(829, 141, 'explanation', '{\"bullets\": [\"Cảm xúc dù tiêu cực hay tích cực đều là những tín hiệu quý giá mách bảo về nhu cầu bên trong của bạn.\", \"Đừng cố đè nén hay phủ nhận nỗi buồn, cơn giận. Hãy gọi tên và đón nhận chúng.\", \"Đi qua những xáo trộn này sẽ giúp bạn trở thành một người trưởng thành có chiều sâu hơn.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(830, 141, 'scenario', '{\"title\": \"Đè nén giọt nước mắt\", \"body\": \"Nam cố nuốt nước mắt vào trong khi chú cún yêu quý qua đời vì sợ các bạn nam khác trêu mình là ẻo lả, yếu đuối.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(831, 141, 'sorting', '{\"instruction\": \"Phân loại các cách đối xử với cảm xúc cá nhân:\", \"leftBox\": {\"title\": \"Kết bạn cảm xúc\"}, \"rightBox\": {\"title\": \"Đè nén chối bỏ\"}, \"items\": [{\"text\": \"Khóc một trận thật to khi thấy buồn để giải tỏa hết uất ức\", \"correctBox\": \"left\"}, {\"text\": \"Cố gắng tỏ ra vui vẻ bên ngoài khi bên trong đang vô cùng đau khổ\", \"correctBox\": \"right\"}, {\"text\": \"Tự nhủ: Mình được phép buồn lúc này, ngày mai mình sẽ ổn hơn\", \"correctBox\": \"left\"}, {\"text\": \"Ghét bỏ bản thân vì thấy mình yếu đuối, dễ khóc trước mặt người khác\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(832, 141, 'reflection', '{\"question\": \"Bạn có đang cho phép mình được khóc hoặc tỏ ra yếu đuối khi thực sự mệt mỏi không?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(833, 141, 'takeaway', '{\"items\": [\"Cảm xúc của bạn là hợp lệ. Hãy ôm ấp lấy cả những ngày mưa giông trong lòng mình.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(834, 142, 'hook', '{\"title\": \"Mỗi khi nhìn vào gương, bạn nhìn thấy điều gì đầu tiên: những khuyết điểm hay nét đẹp độc đáo?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(835, 142, 'explanation', '{\"bullets\": [\"Hình ảnh cơ thể (Body Image) là cách bạn suy nghĩ, cảm nhận và hình dung về ngoại hình của chính mình.\", \"Body image lành mạnh là khi bạn chấp nhận, trân trọng và thấy thoải mái với cơ thể thật của mình.\", \"Trân trọng cơ thể vì những gì nó giúp bạn làm (chạy nhảy, ôm ấp), chứ không chỉ vì trông nó thế nào.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(836, 142, 'scenario', '{\"title\": \"Ngắm mình trong gương\", \"body\": \"Hòa dành cả tiếng đồng hồ đứng trước gương để soi những chiếc mụn nhỏ và tự hỏi tại sao chân mình không được thon dài như các mẫu ảnh.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(837, 142, 'flashcard', '{\"front\": \"Ngoại hình của bạn có quyết định giá trị con người và hạnh phúc của bạn không?\", \"back\": \"Tuyệt đối KHÔNG. Giá trị của bạn nằm ở tâm hồn, tài năng, nhân cách và cách bạn đối xử với mọi người. Cơ thể chỉ là ngôi nhà chở che bạn thôi.\", \"notes\": \"Hãy trân trọng cơ thể vì những gì nó giúp bạn làm thay vì chỉ soi xét vẻ ngoài.\"}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(838, 142, 'reflection', '{\"question\": \"Bạn thường nói những lời yêu thương hay những lời chê bai khi tự ngắm mình trong gương?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(839, 142, 'takeaway', '{\"items\": [\"Cơ thể bạn là duy nhất. Hãy trân trọng nó vì nó đang làm việc chăm chỉ để bảo vệ bạn mỗi ngày.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(840, 143, 'hook', '{\"title\": \"Những lời nhận xét có vẻ đùa vui như Dạo này béo thế! hay Cao như cái sào! thực chất là gì?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(841, 143, 'explanation', '{\"bullets\": [\"Body Shaming (Phán xét ngoại hình) là hành vi bình luận tiêu cực, chế giễu hoặc chê bai vóc dáng, ngoại hình của người khác.\", \"Nó thường được bao biện bằng câu nói: Chỉ đùa vui thôi mà làm gì căng thế?.\", \"Nhận diện sớm giúp bạn thiết lập ranh giới bảo vệ bản thân và tránh làm tổn thương người khác.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(842, 143, 'scenario', '{\"title\": \"Lời trêu chọc đùi to\", \"body\": \"Trong nhóm chat chung, một bạn đăng ảnh chụp lén Vân đang ăn bánh mì kèm chú thích: Ăn thế này bảo sao đùi to như cột đình!. Cả nhóm hùa vào thả icon cười cợt.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(843, 143, 'interaction', '{\"question\": \"Hành vi của nhóm bạn trong group chat đối với Vân là gì?\", \"choices\": [{\"text\": \"Hành vi Body Shaming gây tổn thương nghiêm trọng đến lòng tự trọng và tâm lý của Vân.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Một trò đùa vui nhộn lành mạnh giúp Vân có thêm động lực giảm cân.\", \"correct\": false, \"emoji\": \"🚩\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(844, 143, 'reflection', '{\"question\": \"Bạn có từng vô tình dùng từ ngữ chê bai ngoại hình để làm biệt danh trêu chọc một người bạn của mình chưa?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(845, 143, 'takeaway', '{\"items\": [\"Tôn trọng ngoại hình của người khác là biểu hiện cơ bản nhất của một lối sống văn minh.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(846, 144, 'hook', '{\"title\": \"Bạn có bao giờ cảm thấy tự ti khi lướt mạng xã hội nhìn thấy những bức ảnh da trắng mịn của các hot teen?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(847, 144, 'explanation', '{\"bullets\": [\"Hầu hết hình ảnh trên mạng xã hội đã qua chỉnh sửa góc chụp, ánh sáng và vô số lớp filter làm đẹp.\", \"So sánh cơ thể thật của bạn với những hình ảnh ảo đã qua chỉnh sửa là một việc vô lý.\", \"Hãy follow những trang chia sẻ về vẻ đẹp tự nhiên đa dạng và tắt thông báo các tài khoản độc hại.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(848, 144, 'scenario', '{\"title\": \"Sống ảo hoàn hảo\", \"body\": \"Khánh dành 30 phút bóp eo, làm mịn da bằng các app chỉnh ảnh trước khi đăng lên mạng xã hội, rồi ngồi lo sợ nếu các bạn gặp mình ngoài đời sẽ chê xấu.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(849, 144, 'sorting', '{\"instruction\": \"Phân loại các hành vi sử dụng mạng xã hội lành mạnh cho tâm lý:\", \"leftBox\": {\"title\": \"Bảo vệ tinh thần\"}, \"rightBox\": {\"title\": \"Rơi vào tự ti\"}, \"items\": [{\"text\": \"Tự nhắc nhở bản thân: Ảnh trên mạng chỉ là sản phẩm của góc chụp và filter\", \"correctBox\": \"left\"}, {\"text\": \"Tìm mọi cách ăn kiêng hà khắc để có được vòng eo giống idol trên mạng\", \"correctBox\": \"right\"}, {\"text\": \"Nhấn nút hủy theo dõi các tài khoản luôn khiến mình thấy tự ti về cơ thể\", \"correctBox\": \"left\"}, {\"text\": \"Liên tục sử dụng các app chỉnh ảnh bóp méo vóc dáng thật trước khi đăng bài\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(850, 144, 'reflection', '{\"question\": \"Bạn có thấy thoải mái hơn khi đăng một bức ảnh mặt mộc mỉm cười tự nhiên của mình lên mạng không?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(851, 144, 'takeaway', '{\"items\": [\"Cuộc sống thật có khuyết điểm và khuyết điểm làm nên sự độc bản đáng quý của bạn.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(852, 145, 'hook', '{\"title\": \"Làm sao để giữ vững sự tự tin khi ai đó bất ngờ chê bai ngoại hình của bạn ngay trước mặt đám đông?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(853, 145, 'explanation', '{\"bullets\": [\"Khi bị chê bai công khai, phản ứng tự nhiên của chúng ta là xấu hổ, tức giận hoặc muốn thu mình lại.\", \"Lối sống ứng xử vô duyên hay lịch sự nằm ở người nhận xét, không nằm ở cơ thể bạn.\", \"Phản hồi kiên định, lịch sự và rời khỏi cuộc trò chuyện mang lại năng lượng tiêu cực.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(854, 145, 'scenario', '{\"title\": \"Họ hàng nhận xét\", \"body\": \"Tại buổi họp gia đình, một người họ hàng nói lớn: Ơ hay dạo này Vy ăn gì béo thế con? Con gái con lứa phải biết giữ dáng chứ!. Mọi người bắt đầu cười.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(855, 145, 'flashcard', '{\"front\": \"Vy nên ứng phó thế nào trước lời nhận xét kém tinh tế của người họ hàng?\", \"back\": \"Vy có thể mỉm cười nhẹ và nói bình thản: Dạ dạo này con đang dậy thì nên cơ thể phát triển khỏe mạnh là tốt rồi ạ bác. rồi xin phép đi lấy nước để tránh đôi co.\", \"notes\": \"Tự tin bảo vệ ranh giới cơ thể mình bằng thái độ lịch sự nhưng cứng rắn.\"}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(856, 145, 'reflection', '{\"question\": \"Bạn đã từng dũng cảm lên tiếng bảo vệ bản thân khi bị người lớn hoặc bạn bè chê bai ngoại hình chưa?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(857, 145, 'takeaway', '{\"items\": [\"Giá trị của bạn không được định nghĩa bởi thước đo của người khác. Hãy tự tin tỏa sáng theo cách riêng.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(858, 146, 'hook', '{\"title\": \"Làm sao để biến những lời chê bai ngoại hình thành cơ hội để xây dựng lòng yêu thương bản thân?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(859, 146, 'explanation', '{\"bullets\": [\"Học cách lọc thông tin: chỉ lắng nghe lời khuyên y khoa lành mạnh từ chuyên gia hoặc người thực sự quan tâm đến sức khỏe.\", \"Bỏ qua các lời chỉ trích công kích mang tính hạ nhục trên mạng bằng cách chặn (block) và báo cáo (report).\", \"Thực hành viết những điều bạn yêu thích nhất về cơ thể mình để củng cố tự tin bên trong.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(860, 146, 'scenario', '{\"title\": \"Comment chế giễu chiều cao\", \"body\": \"Hùng bị một số tài khoản ảo trên mạng để lại bình luận chế giễu chiều cao khiêm tốn dưới bức ảnh chụp chung với đội bóng rổ của trường.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(861, 146, 'interaction', '{\"question\": \"Hùng nên xử lý thế nào để bảo vệ sức khỏe tinh thần của mình?\", \"choices\": [{\"text\": \"Chặn các tài khoản đó, báo cáo bình luận và tự nhắc mình: Mình chơi bóng rổ tốt bằng kỹ thuật và sự nhanh nhẹn, chiều cao không định nghĩa được tài năng.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Nhắn tin cãi nhau tay đôi với họ suốt đêm để chứng minh mình không yếu đuối.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(862, 146, 'reflection', '{\"question\": \"Bạn có thể viết ra ngay bây giờ 3 điều cơ thể bạn đã giúp bạn làm được và bạn thấy trân trọng nhất không?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(863, 146, 'takeaway', '{\"items\": [\"Chặn đi những năng lượng độc hại để nhường chỗ cho sự phát triển an lành của bản thân.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(864, 147, 'hook', '{\"title\": \"Sẽ thế nào nếu thế giới này tất cả mọi người đều có vóc dáng giống hệt như những ma-nơ-canh?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(865, 147, 'explanation', '{\"bullets\": [\"Sự đa dạng về hình dáng, màu da và kích thước chính là điều làm nên vẻ đẹp phong phú của thế giới loài người.\", \"Không có một cơ thể nào được coi là chuẩn mực duy nhất để phán xét các cơ thể khác.\", \"Tôn trọng sự đa dạng cơ thể giúp xây dựng học đường không bạo lực và đầy lòng nhân ái.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(866, 147, 'scenario', '{\"title\": \"Cô bạn cơ bắp\", \"body\": \"Một số bạn trêu chọc Hà trông như đàn ông vì Hà có bắp tay cơ bắp săn chắc do tập võ bơi lội, khiến Hà e dè không dám mặc áo ngắn tay.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(867, 147, 'sorting', '{\"instruction\": \"Phân loại các hành vi ứng xử tôn trọng sự đa dạng cơ thể:\", \"leftBox\": {\"title\": \"Tôn trọng đa dạng\"}, \"rightBox\": {\"title\": \"Áp đặt khuôn mẫu\"}, \"items\": [{\"text\": \"Khen ngợi nụ cười rạng rỡ của bạn thay vì nhận xét bạn béo hay gầy\", \"correctBox\": \"left\"}, {\"text\": \"Đánh giá một bạn nữ là không nữ tính chỉ vì bạn ấy có cơ bắp khỏe mạnh\", \"correctBox\": \"right\"}, {\"text\": \"Chào đón tất cả các bạn có vóc dáng khác nhau tham gia chơi trò chơi tập thể\", \"correctBox\": \"left\"}, {\"text\": \"Bắt người yêu phải giảm cân để có được thân hình thon gọn giống các mẫu ảnh\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(868, 147, 'reflection', '{\"question\": \"Bạn có sẵn sàng yêu thương cơ thể mình ngay cả khi nó không hoàn hảo theo tiêu chuẩn của đám đông không?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(869, 147, 'takeaway', '{\"items\": [\"Bạn là một tác phẩm nghệ thuật độc bản của tự nhiên. Hãy tự hào và trân trọng chiếc body duy nhất của mình.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(870, 148, 'hook', '{\"title\": \"Bạn có biết cơ thể bạn đang tiêu tốn nhiều năng lượng để phát triển ở tuổi dậy thì tương đương một vận động viên không?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(871, 148, 'explanation', '{\"bullets\": [\"Tuổi dậy thì đòi hỏi một lượng dinh dưỡng phong phú: đạm xây dựng cơ, canxi phát triển xương và các vitamin.\", \"Bỏ bữa, ăn kiêng cực đoan dễ khiến cơ thể bị thiếu hụt năng lượng hoặc mất cân bằng nội tiết.\", \"Hãy lắng nghe cơn đói của cơ thể và nạp năng lượng bằng những thực phẩm lành mạnh.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(872, 148, 'scenario', '{\"title\": \"Nhịn ăn giảm cân\", \"body\": \"Phương nhịn ăn trưa để mong có thân hình thon gọn như thần tượng Hàn Quốc, dẫn đến việc bị hạ đường huyết ngất xỉu trong giờ thể dục.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(873, 148, 'flashcard', '{\"front\": \"Nhịn ăn để giảm cân nhanh chóng ở tuổi dậy thì có phải là ý tưởng tốt không?\", \"back\": \"Tuyệt đối KHÔNG. Nhịn ăn làm cản trở sự phát triển chiều cao, gây mệt mỏi, suy giảm trí nhớ và xáo trộn nội tiết tố nghiêm trọng.\", \"notes\": \"Hãy chọn ăn uống đầy đủ chất dinh dưỡng kết hợp vận động thể thao để có cơ thể khỏe mạnh tự nhiên.\"}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(874, 148, 'reflection', '{\"question\": \"Bạn có hay bỏ bữa sáng vì vội đi học không? Bữa sáng chính là xăng để khởi động ngày mới của bạn đấy!\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(875, 148, 'takeaway', '{\"items\": [\"Ăn uống đủ chất là cách bạn tiếp thêm sức mạnh cho hành trình lớn lên của cơ thể.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(876, 149, 'hook', '{\"title\": \"Tại sao tụi mình thường được khuyên phải ngủ đủ 8 đến 10 tiếng mỗi đêm ở tuổi mới lớn?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(877, 149, 'explanation', '{\"bullets\": [\"Khi bạn ngủ sâu, tuyến yên trong não sẽ giải phóng hormone tăng trưởng (GH) nhiều nhất để giúp cao lớn và hồi phục.\", \"Thiếu ngủ kéo dài dẫn đến mất tập trung học tập, nổi mụn và tâm trạng dễ cáu bẳn bực dọc.\", \"Tránh xa màn hình điện thoại ít nhất 30 phút trước khi ngủ để có giấc ngủ sâu chất lượng.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(878, 149, 'scenario', '{\"title\": \"Rank game thâu đêm\", \"body\": \"Bách thường xuyên thức khuya đến 2h sáng để cày rank game. Sáng hôm sau đi học, Bách luôn trong tình trạng lờ đờ và ngủ gật trong lớp.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(879, 149, 'interaction', '{\"question\": \"Bách nên thay đổi thói quen ngủ thế nào để hỗ trợ cơ thể phát triển tốt nhất?\", \"choices\": [{\"text\": \"Thiết lập giờ ngủ cố định trước 11h đêm, để điện thoại ở xa giường và ngủ đủ 8-9 tiếng mỗi ngày.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tiếp tục thức khuya cày game, bù lại bằng cách ngủ bù 12 tiếng vào ngày chủ nhật là được.\", \"correct\": false, \"emoji\": \"🙁\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(880, 149, 'reflection', '{\"question\": \"Bạn có thói quen mang điện thoại lên giường lướt mạng trước khi đi ngủ không? Điều này có ảnh hưởng đến giấc ngủ của bạn?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(881, 149, 'takeaway', '{\"items\": [\"Giấc ngủ sâu là phòng thí nghiệm thần kỳ nơi cơ thể âm thầm sửa chữa và cao lớn lên mỗi đêm.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(882, 150, 'hook', '{\"title\": \"Làm sao để nhận biết khi cơ thể đang phát tín hiệu cầu cứu vì bị làm việc hoặc học tập quá tải?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(883, 150, 'explanation', '{\"bullets\": [\"Tín hiệu báo động bao gồm: mỏi mắt, đau đầu liên tục, uể oải chán ăn, hoặc bồn chồn lo lắng ở bụng.\", \"Nhiều bạn trẻ thường bỏ qua các tín hiệu này, cố gắng gồng mình học tập vì áp lực thành tích.\", \"Lắng nghe và cho phép cơ thể nghỉ ngơi chính là biểu hiện của sự tự chăm sóc thông thái.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(884, 150, 'scenario', '{\"title\": \"Mệt mỏi trước kỳ thi\", \"body\": \"Đầu óc nhức nhối quay cuồng trước kỳ thi học kỳ, nhưng Nam vẫn cố bấm điện thoại đọc tài liệu đến 1h sáng vì sợ trượt.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(885, 150, 'sorting', '{\"instruction\": \"Phân loại các phản ứng trước tín hiệu mệt mỏi của cơ thể:\", \"leftBox\": {\"title\": \"Lắng nghe thông thái\"}, \"rightBox\": {\"title\": \"Phớt lờ gượng ép\"}, \"items\": [{\"text\": \"Tạm dừng học, đi bộ xung quanh sân nhà 10 phút để thư giãn gân cốt\", \"correctBox\": \"left\"}, {\"text\": \"Uống thêm 1 lon nước ngọt/cafe đậm đặc để cố thức đêm cày bài dù đầu đang nhức\", \"correctBox\": \"right\"}, {\"text\": \"Nằm nghỉ ngơi thả lỏng cơ thể khi cảm thấy bụng dưới đau âm ỉ do kinh nguyệt\", \"correctBox\": \"left\"}, {\"text\": \"Cố gắng chạy bộ thêm 5km dù chân đang bị căng cơ đau nhói để đạt chỉ tiêu\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(886, 150, 'reflection', '{\"question\": \"Bạn có từng cố học tập hay làm việc đến kiệt sức chỉ vì sợ bị đánh giá là lười biếng chưa?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(887, 150, 'takeaway', '{\"items\": [\"Cơ thể là người bạn đồng hành trung thực. Hãy nghỉ ngơi khi bạn ấy lên tiếng báo động mệt mỏi nhé.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(888, 151, 'hook', '{\"title\": \"Làm sao để chiến thắng sức hấp dẫn của chiếc màn hình điện thoại rực rỡ vào lúc nửa đêm?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(889, 151, 'explanation', '{\"bullets\": [\"Ánh sáng xanh từ điện thoại ngăn cản cơ thể tiết hormone melatonin gây buồn ngủ.\", \"Lướt mạng xã hội vào ban đêm dễ kéo bạn vào những luồng suy nghĩ lo âu, so sánh tiêu cực.\", \"Thiết lập ranh giới rõ ràng với công nghệ là bước tự chăm sóc bản thân khôn ngoan nhất.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(890, 151, 'scenario', '{\"title\": \"Tiktok nửa đêm\", \"body\": \"Linh định chỉ lướt Tiktok 15 phút trước khi ngủ lúc 10h tối, nhưng các video ngắn lôi cuốn cuốn Linh đi liên tục khiến Linh thức đến 1h sáng.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(891, 151, 'flashcard', '{\"front\": \"Linh nên làm thế nào để tránh tình trạng lướt điện thoại quên giờ giấc vào ban đêm?\", \"back\": \"Bật chế độ không làm phiền (Do Not Disturb), cài đặt giới hạn thời gian sử dụng app và đặt điện thoại ngoài tầm với của tay khi đã lên giường ngủ.\", \"notes\": \"Phòng ngủ nên là thánh đường của sự nghỉ ngơi, không phải là nơi lướt mạng thâu đêm.\"}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(892, 151, 'reflection', '{\"question\": \"Bạn có sẵn sàng tắt kết nối wifi điện thoại sau 10h30 tối để dành không gian yên tĩnh cho tâm trí nghỉ ngơi không?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(893, 151, 'takeaway', '{\"items\": [\"Tắt điện thoại, mở giấc ngủ ngon. Đó là món quà tuyệt vời nhất bạn dành tặng cho sức khỏe của mình.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(894, 152, 'hook', '{\"title\": \"Làm thế nào để cân bằng giữa việc học tập bận rộn ở trường và thời gian chăm sóc bản thân mỗi ngày?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(895, 152, 'explanation', '{\"bullets\": [\"Tự chăm sóc bản thân (Self-care) không cần những việc đắt đỏ, nó là những thói quen nhỏ đều đặn.\", \"Lập một thời gian biểu có xen kẽ thời gian học tập, thời gian thể thao và khoảng thời gian không làm gì cả.\", \"Học cách nói không với các yêu cầu không quan trọng khi bạn cần ưu tiên nghỉ ngơi.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(896, 152, 'scenario', '{\"title\": \"Vy không còn thời gian vẽ\", \"body\": \"Vy có lịch học thêm dày đặc cả tuần, không có lấy một buổi tối rảnh rỗi để vẽ tranh (sở thích lớn nhất của Vy), khiến Vy thấy uể oải.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(897, 152, 'interaction', '{\"question\": \"Vy nên sắp xếp lại lịch sinh hoạt thế nào cho cân bằng cảm xúc?\", \"choices\": [{\"text\": \"Xin phép bố mẹ bớt một buổi học thêm không quá cấp thiết để dành tối thứ 7 cho sở thích vẽ tranh cá nhân.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tiếp tục cố học hết công suất, đợi đến kỳ nghỉ hè mới bắt đầu vẽ tranh lại.\", \"correct\": false, \"emoji\": \"🙁\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(898, 152, 'reflection', '{\"question\": \"Bạn có đang dành ra ít nhất 30 phút mỗi ngày cho một sở thích lành mạnh mang lại niềm vui thuần khiết không?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(899, 152, 'takeaway', '{\"items\": [\"Tự chăm sóc không phải là ích kỷ, đó là cách bạn sạc đầy pin để học tập và yêu thương cuộc sống tốt hơn.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(900, 153, 'hook', '{\"title\": \"Tự chăm sóc bản thân có phải là việc chỉ làm một lần khi thấy mệt rồi thôi không?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(901, 153, 'explanation', '{\"bullets\": [\"Tự chăm sóc là một phong cách sống bền vững, là sự cam kết lắng nghe và tôn trọng cơ thể mình mỗi ngày.\", \"Sẽ có những ngày bạn ăn uống không lành mạnh, đừng tự trách móc quá mức. Hãy bắt đầu lại vào ngày mai.\", \"Hãy kiên nhẫn và bao dung với chính mình trên hành trình học cách trưởng thành.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(902, 153, 'scenario', '{\"title\": \"Tự trách vì lười biếng\", \"body\": \"Hân tự sỉ vả mình vô dụng cả ngày vì lỡ dành cả buổi chiều thứ bảy nằm ngủ lười biếng thay vì đi học nhóm.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(903, 153, 'sorting', '{\"instruction\": \"Phân loại các quan niệm đúng đắn về hành trình tự chăm sóc bản thân:\", \"leftBox\": {\"title\": \"Lành mạnh lâu dài\"}, \"rightBox\": {\"title\": \"Sai lầm nhất thời\"}, \"items\": [{\"text\": \"Tự chăm sóc là thói quen nhỏ hàng ngày: uống đủ nước, ngủ đủ giấc\", \"correctBox\": \"left\"}, {\"text\": \"Chỉ tự chăm sóc bản thân bằng cách đi mua sắm những món đồ hiệu thật đắt tiền\", \"correctBox\": \"right\"}, {\"text\": \"Chấp nhận những ngày mình mệt mỏi và cho phép bản thân nghỉ ngơi không áy náy\", \"correctBox\": \"left\"}, {\"text\": \"Ép bản thân phải luôn vui vẻ tích cực 24/7 và không được phép buồn\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(904, 153, 'reflection', '{\"question\": \"Bạn có đang bao dung và nhẹ nhàng với chính mình mỗi khi gặp thất bại hay phạm sai lầm không?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(905, 153, 'takeaway', '{\"items\": [\"Tự chăm sóc là hành trình trọn đời. Hãy bước đi thong thả với lòng bao dung dành cho bản thân mình.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(906, 154, 'hook', '{\"title\": \"Bạn có tin vào lời đồn rằng qua tuổi dậy thì là chiều cao của bạn sẽ vĩnh viễn đứng yên không?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(907, 154, 'explanation', '{\"bullets\": [\"Chiều cao chịu ảnh hưởng di truyền, nhưng dinh dưỡng, giấc ngủ và thể thao đóng vai trò quyết định.\", \"Xương của bạn vẫn tiếp tục phát triển và chỉ thực sự đóng khớp hoàn toàn vào khoảng tuổi 20 đến 22.\", \"Đừng vội bỏ cuộc hay lo lắng, bạn vẫn còn thời gian để cải thiện chiều cao khoa học.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(908, 154, 'scenario', '{\"title\": \"Nỗi lo lùn tịt\", \"body\": \"Huy 14 tuổi nhưng lùn nhất nhóm bạn nam, cậu sợ hãi nghĩ mình sẽ lùn tịt cả đời và định mua thực phẩm chức năng tăng chiều cao cấp tốc.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(909, 154, 'flashcard', '{\"front\": \"Có phải uống sữa tăng chiều cao thần tốc trên quảng cáo là cách duy nhất để cao lên không?\", \"back\": \"KHÔNG. Không có sữa hay thuốc thần kỳ nào giúp cao vọt ngay lập tức. Cần ăn uống đủ chất, ngủ sớm trước 11h đêm và tập luyện thể thao (bơi lội, bóng rổ).\", \"notes\": \"Hãy cảnh giác với các sản phẩm tăng chiều cao thần tốc không rõ nguồn gốc.\"}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(910, 154, 'reflection', '{\"question\": \"Bạn có đang duy trì một môn thể thao vận động kéo giãn cơ thể nào đều đặn mỗi tuần không?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(911, 154, 'takeaway', '{\"items\": [\"Sự cao lớn cần thời gian và thói quen sinh hoạt lành mạnh bền bỉ, không có đường tắt nào cả.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(912, 155, 'hook', '{\"title\": \"Liệu hành vi tự khám phá cơ thể (thủ dâm) có gây ra những tác hại đáng sợ như lời đồn thổi?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(913, 155, 'explanation', '{\"bullets\": [\"Thủ dâm (Masturbation) là hành vi tự kích thích cơ quan sinh dục của mình để tìm kiếm cảm giác thư giãn.\", \"Về mặt y học, đây là hành vi sinh lý hoàn toàn bình thường, lành mạnh và an toàn để khám phá cơ thể.\", \"Nó chỉ bất ổn khi bạn làm quá thường xuyên gây ảnh hưởng cuộc sống hoặc làm ở nơi công cộng.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(914, 155, 'scenario', '{\"title\": \"Nỗi sợ vô căn cứ\", \"body\": \"Bách nghe các bạn nam rỉ tai nhau rằng thủ dâm sẽ làm suy giảm trí nhớ, gây vô sinh. Bách vô cùng hoang mang lo sợ.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(915, 155, 'interaction', '{\"question\": \"Bách nên hiểu đúng về hành vi tự khám phá cơ thể thế nào cho khoa học?\", \"choices\": [{\"text\": \"Đây là hiện tượng sinh lý bình thường của tuổi dậy thì, không gây ra các tác hại ghê gớm nếu thực hiện điều độ, kín đáo và vệ sinh sạch sẽ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Chắc chắn lời đồn là đúng, Bách nên đi khám bác sĩ tâm thần để điều trị ngay lập tức.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(916, 155, 'reflection', '{\"question\": \"Bạn có cảm thấy bớt lo lắng và tội lỗi hơn sau khi hiểu rõ góc nhìn khoa học về hành vi này chưa?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(917, 155, 'takeaway', '{\"items\": [\"Khám phá cơ thể là bình thường. Hãy thực hiện nó với thái độ tôn trọng cơ thể, kín đáo và giữ vệ sinh sạch sẽ.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(918, 156, 'hook', '{\"title\": \"Tại sao tụi mình thường chọn cách âm thầm lên Google tra cứu hoặc tin vào lời đồn hơn là hỏi trực tiếp chuyên gia?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(919, 156, 'explanation', '{\"bullets\": [\"Cảm giác xấu hổ, sợ bị người lớn phán xét, mắng mỏ khiến tụi mình ngại ngùng che giấu.\", \"Nhưng tìm kiếm thông tin không chính thống dễ dẫn đến hiểu biết sai lệch, gây ra nỗi sợ vô lý.\", \"Vượt qua sự ngại ngùng để tìm kiếm những nguồn tin khoa học chính là cách bạn tự bảo vệ mình.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(920, 156, 'scenario', '{\"title\": \"Search Google giật gân\", \"body\": \"Vy băn khoăn về khí hư có màu trắng đục, cô bé tự search Google và đọc trúng bài viết bảo mình đã bị ung thư cổ tử cung khiến Vy khóc lóc tuyệt vọng.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(921, 156, 'sorting', '{\"instruction\": \"Phân loại các nguồn tìm kiếm thông tin sức khỏe tuổi dậy thì:\", \"leftBox\": {\"title\": \"Nguồn tin tin cậy\"}, \"rightBox\": {\"title\": \"Nguồn tin rác\"}, \"items\": [{\"text\": \"Website giáo dục giới tính uy tín như Scarleteen hoặc của tổ chức WHO, UNICEF\", \"correctBox\": \"left\"}, {\"text\": \"Các video ngắn không rõ nguồn gốc, giật tít câu view trên mạng xã hội\", \"correctBox\": \"right\"}, {\"text\": \"Bác sĩ nhi khoa, chuyên gia tâm lý hoặc giáo viên sinh học tại trường\", \"correctBox\": \"left\"}, {\"text\": \"Các diễn đàn mạng ẩn danh chuyên chia sẻ các mẹo truyền miệng dân gian trị bệnh\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(922, 156, 'reflection', '{\"question\": \"Bạn có từng đọc được một thông tin sức khỏe giật gân trên mạng khiến bạn vô cùng hoảng sợ chưa?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(923, 156, 'takeaway', '{\"items\": [\"Đặt câu hỏi không có gì là xấu. Hãy tìm kiếm câu trả lời từ những nguồn tin khoa học và đáng tin cậy.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(924, 157, 'hook', '{\"title\": \"Làm sao ứng phó khi bạn bè truyền tai nhau những thông tin sai lệch về tình dục hay thủ dâm ngay tại trường học?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(925, 157, 'explanation', '{\"bullets\": [\"Áp lực đồng trang lứa và sự tò mò khiến các tin đồn nhảm tuổi dậy thì lan truyền rất nhanh ở trường học.\", \"Bạn không cần phải hùa theo đám đông để tỏ ra sành sỏi, cũng không cần tranh cãi làm mất lòng bạn bè.\", \"Giữ cho mình đầu óc tỉnh táo, tin vào kiến thức khoa học đã học.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(926, 157, 'scenario', '{\"title\": \"Rỉ tai phòng học\", \"body\": \"Trong giờ ra chơi, một nhóm bạn đang bàn tán xôn xao rằng chỉ cần ôm nhau thôi bạn gái cũng có thể mang thai. Khánh đứng bên nghe thấy lo sợ tột cùng vì hôm qua vừa ôm một bạn nữ.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(927, 157, 'flashcard', '{\"front\": \"Khánh nên xử lý nỗi sợ hãi của mình thế nào trước lời đồn của bạn bè?\", \"back\": \"Khánh nên tự trấn an: Ôm nhau không thể mang thai được. Sau đó, Khánh có thể đọc lại sách y khoa hoặc hỏi mẹ để giải tỏa hoàn toàn nỗi lo sợ ngớ ngẩn này.\", \"notes\": \"Đừng để những lời rỉ tai vô căn cứ kiểm soát tâm trạng và hành vi của bạn.\"}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(928, 157, 'reflection', '{\"question\": \"Bạn có thói quen đối chiếu lại những thông tin nghe được từ bạn bè với sách giáo khoa không?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(929, 157, 'takeaway', '{\"items\": [\"Kiến thức khoa học là chiếc la bàn tốt nhất giúp bạn vượt qua những sương mù tin đồn tuổi mới lớn.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(930, 158, 'hook', '{\"title\": \"Làm sao để rèn luyện tư duy phản biện, tự biến mình thành một bộ lọc thông tin thông thái trước biển kiến thức?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(931, 158, 'explanation', '{\"bullets\": [\"Áp dụng quy tắc kiểm chứng thông tin: Ai viết? (Nguồn uy tín?), Dựa trên cơ sở nào? (Cơ sở y khoa?), Mục đích làm gì? (Giáo dục hay bán hàng?).\", \"Tránh chia sẻ những thông tin giật gân, chưa kiểm chứng lên mạng vì dễ gây hoang mang cho người khác.\", \"Luôn giữ thái độ cởi mở nhưng tỉnh táo trước mọi thông tin mới.\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(932, 158, 'scenario', '{\"title\": \"Vy định share bài dứa\", \"body\": \"Vy đọc được bài viết trên Tiktok bảo rằng ăn nhiều dứa giúp ngày hành kinh thơm tho và không bị đau bụng, cô bé định chia sẻ ngay về trang cá nhân.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(933, 158, 'interaction', '{\"question\": \"Vy nên làm gì trước khi nhấn nút chia sẻ bài viết đó?\", \"choices\": [{\"text\": \"Tìm kiếm lại từ khóa đó trên các trang y khoa uy tín để xác nhận tính chính xác của mẹo dân gian này trước khi chia sẻ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Chia sẻ ngay lập tức vì thấy mẹo này rất thú vị và có ích cho các bạn gái khác.\", \"correct\": false, \"emoji\": \"🙁\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(934, 158, 'reflection', '{\"question\": \"Bạn có bao giờ dừng lại suy ngẫm về tính chính xác của một thông tin trước khi nhấn nút share trên mạng chưa?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(935, 158, 'takeaway', '{\"items\": [\"Hãy là một Netizen thông thái, biết lọc sạch thông tin trước khi nạp vào đầu và lan tỏa cho người khác.\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(936, 159, 'hook', '{\"title\": \"Bạn đã sẵn sàng khép lại chương học này để tự tin làm chủ hành trình dậy thì thành công của mình chưa?\"}', 1, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(937, 159, 'explanation', '{\"bullets\": [\"Dậy thì không đáng sợ khi bạn đã trang bị đầy đủ kiến thức khoa học và lòng yêu thương bản thân.\", \"Chúc mừng bạn đã hoàn thành khóa học và tích lũy được những kỹ năng quan trọng để bảo vệ, chăm sóc cơ thể cũng như cảm xúc.\", \"Hãy tiếp tục bước đi trên con đường lớn lên với sự tự tin và tràn đầy năng lượng tích cực!\"]}', 2, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(938, 159, 'scenario', '{\"title\": \"Nhìn lại hành trình\", \"body\": \"Khánh dạo này không còn hoảng hốt khi thấy da nổi mụn, biết tự giác ngủ sớm trước 11h và sẵn sàng tâm sự khó khăn sức khỏe với bố mẹ.\"}', 3, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(939, 159, 'sorting', '{\"instruction\": \"Phân loại các hành vi thể hiện sự sẵn sàng làm chủ tuổi dậy thì:\", \"leftBox\": {\"title\": \"Dậy thì thành công\"}, \"rightBox\": {\"title\": \"Chưa sẵn sàng lớn\"}, \"items\": [{\"text\": \"Tự tin chăm sóc vệ sinh cá nhân sạch sẽ và ăn uống đủ chất hàng ngày\", \"correctBox\": \"left\"}, {\"text\": \"Trốn tránh không dám nói chuyện với ai khi cơ thể gặp sự cố khó chịu\", \"correctBox\": \"right\"}, {\"text\": \"Tôn trọng sự đa dạng vóc dáng và cảm xúc thay đổi của bản thân, bạn bè\", \"correctBox\": \"left\"}, {\"text\": \"Tiếp tục tin vào những lời đồn thổi phản khoa học của bạn bè cùng lớp\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(940, 159, 'reflection', '{\"question\": \"Sau khóa học này, bạn cảm thấy mình đã tự tin hơn bao nhiêu phần trăm để đối mặt với những thay đổi của tuổi dậy thì?\"}', 5, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(941, 159, 'takeaway', '{\"items\": [\"Bạn đã sẵn sàng và đầy bản lĩnh. Hãy tự tin bước ra thế giới và tỏa sáng theo cách riêng của mình!\"]}', 6, '2026-06-05 13:58:05', '2026-06-05 13:58:05'),
(942, 160, 'hook', '{\"title\": \"Bạn có bao giờ bỗng dưng thấy muốn \'gầm rú\' hoặc khóc ngon lành chỉ vì một chuyện nhỏ xíu không?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(943, 160, 'explanation', '{\"bullets\": [\"Ở tuổi dậy thì, các hormone (như estrogen và testosterone) tăng vọt như biểu đồ chứng khoán.\", \"Chúng kích hoạt vùng hạch hạnh nhân trong não, nơi kiểm soát cảm xúc, làm bạn nhạy cảm hơn bình thường gấp nhiều lần.\", \"Đây là một phản ứng sinh học hoàn toàn tự nhiên, không phải do bạn \'khó ưa\' hay \'bất trị\' đâu nha!\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(944, 160, 'scenario', '{\"title\": \"Cơn giận vô cớ\", \"body\": \"Nam đang ngồi xem phim hoạt hình bình thường, bỗng dưng bố nhắc Nam đi đổ rác. Thế là Nam nổi đóa, quát lại bố rồi chạy vào phòng đóng sập cửa. Sau đó Nam lại thấy hối hận và tự trách mình vì phản ứng quá đà.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(945, 160, 'flashcard', '{\"front\": \"Có phải cảm xúc thất thường là dấu hiệu của việc mình đang biến thành người xấu?\", \"back\": \"Tuyệt đối không! Đó chỉ là tín hiệu bộ não và hormone của bạn đang học cách trưởng thành cùng nhau.\", \"notes\": \"Hãy xem nó giống như một bản chạy thử phần mềm mới (Beta test), thỉnh thoảng có lỗi (lag/bug) là chuyện thường.\"}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(946, 160, 'reflection', '{\"question\": \"Gần đây bạn có phản ứng thái quá với ai đó chỉ vì một chuyện nhỏ không?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(947, 160, 'takeaway', '{\"items\": [\"Cảm xúc thay đổi là chuyện bình thường của tuổi dậy thì. Hãy cho bản thân thời gian để thích nghi.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(948, 161, 'hook', '{\"title\": \"Làm thế nào để biết mình đang thực sự cảm thấy thế nào khi trong lòng là một đống hỗn độn?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(949, 161, 'explanation', '{\"bullets\": [\"Có những ngày bạn cảm thấy vừa giận, vừa buồn, vừa lo lắng đan xen lẫn nhau.\", \"Việc gọi tên chính xác cảm xúc (ví dụ: thất vọng, ghen tị, bất an) giúp não bộ hạ nhiệt ngay lập tức.\", \"Hãy thử dừng lại 3 giây và tự hỏi: \'Mình đang thuộc \'hệ\' cảm xúc nào lúc này?\'\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(950, 161, 'scenario', '{\"title\": \"Cảm giác lẫn lộn\", \"body\": \"Lan thấy bạn thân của mình đi chơi riêng với một bạn khác mà không rủ mình. Lan thấy ngực nghẹn lại, mặt nóng bừng và muốn viết một tin nhắn giận dữ. Lan không rõ mình đang giận hay đang buồn tủi.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(951, 161, 'interaction', '{\"question\": \"Trong tình huống của Lan, cảm xúc thực chất đằng sau cơn giận là gì?\", \"choices\": [{\"text\": \"Lan đang cảm thấy bị bỏ rơi và lo sợ tình bạn của mình đang bị rạn nứt.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Lan chỉ đang ghét bạn kia và muốn gây sự cho vui thôi.\", \"correct\": false, \"emoji\": \"☹️\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(952, 161, 'reflection', '{\"question\": \"Khi tức giận, bạn thường cảm thấy cơ thể mình có những biểu hiện gì đầu tiên (nóng mặt, run tay, nghẹn ngực)?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(953, 161, 'takeaway', '{\"items\": [\"Gọi tên được cảm xúc là bạn đã đi được một nửa chặng đường để làm chủ nó.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(954, 162, 'hook', '{\"title\": \"Bạn có từng cảm thấy tội lỗi hoặc cố tỏ ra vui vẻ khi trong lòng đang buồn héo úa không?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(955, 162, 'explanation', '{\"bullets\": [\"Xã hội thường bảo tụi mình phải luôn tích cực, nhưng thực tế, buồn bã, lo âu hay giận dữ cũng là những cảm xúc có ích.\", \"Nỗi buồn giúp ta biết điều gì là quan trọng; nỗi sợ giúp ta tránh nguy hiểm; cơn giận báo hiệu ranh giới của ta bị xâm phạm.\", \"Đè nén cảm xúc tiêu cực chỉ làm chúng phình to ra như quả bóng bay sắp nổ mà thôi.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(956, 162, 'scenario', '{\"title\": \"Tỏ vẻ ổn bên ngoài\", \"body\": \"Minh trượt đội tuyển bóng rổ của trường. Dù rất buồn và muốn khóc, nhưng khi gặp bạn bè, Minh vẫn cười nói hớn hở: \'Ối dào, tớ có thèm vào đâu!\'. Tối về nhà, Minh cảm thấy cô đơn và trống rỗng tột cùng.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(957, 162, 'sorting', '{\"instruction\": \"Phân loại các phản ứng với cảm xúc tiêu cực:\", \"leftBox\": {\"title\": \"Đón nhận lành mạnh\"}, \"rightBox\": {\"title\": \"Chối bỏ, đè nén\"}, \"items\": [{\"text\": \"Cho phép bản thân khóc và buồn khi gặp thất bại\", \"correctBox\": \"left\"}, {\"text\": \"Cố tỏ ra vui cười để người khác không thấy mình yếu đuối\", \"correctBox\": \"right\"}, {\"text\": \"Tự nhủ: Buồn một chút cũng được, mai mình sẽ tính tiếp\", \"correctBox\": \"left\"}, {\"text\": \"Cáu gắt với người nhà để trút bỏ sự khó chịu trong lòng\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(958, 162, 'reflection', '{\"question\": \"Bạn có từng giả vờ ổn trước mặt người khác để tránh bị coi là yếu đuối chưa?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(959, 162, 'takeaway', '{\"items\": [\"Mọi cảm xúc đều có giá trị và quyền được tồn tại. Đừng bắt bản thân phải luôn hoàn hảo.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(960, 163, 'hook', '{\"title\": \"Có những ngày ngủ dậy, bạn thấy cả thế giới bỗng nhiên xám xịt và chán ghét mọi thứ mà không hiểu vì sao?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(961, 163, 'explanation', '{\"bullets\": [\"Đôi khi tâm trạng đi xuống không cần một lý do cụ thể nào cả. Nó có thể do thiếu ngủ, thay đổi thời tiết, hoặc đơn giản là cơ thể đang quá tải.\", \"Những lúc này, việc ép mình phải làm việc hoặc vui vẻ chỉ khiến bạn thêm kiệt sức.\", \"Hãy chấp nhận rằng hôm nay là một ngày \'low-energy\' (năng lượng thấp) và đối xử nhẹ nhàng với bản thân hơn.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(962, 163, 'scenario', '{\"title\": \"Chán chường ngày cuối tuần\", \"body\": \"Hòa thức dậy vào ngày chủ nhật với cảm giác uể oải, không muốn ăn, không muốn nhắn tin với bạn bè và chỉ muốn nằm dài trên giường. Hòa tự trách mình là lười biếng và vô dụng.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(963, 163, 'flashcard', '{\"front\": \"Hòa nên làm gì để vượt qua ngày năng lượng thấp này một cách thoải mái nhất?\", \"back\": \"Cho phép bản thân nghỉ ngơi, làm những việc siêu nhỏ như uống một cốc nước ấm, nghe một bản nhạc nhẹ, và đừng tự phán xét mình.\", \"notes\": \"Điện thoại còn có lúc cần sạc pin, cơ thể và tâm trí bạn cũng vậy thôi!\"}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(964, 163, 'reflection', '{\"question\": \"Bạn thường làm gì để sạc lại năng lượng cho những ngày \'tụt mood\' không lý do?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(965, 163, 'takeaway', '{\"items\": [\"Năng lượng thấp không phải là lười biếng. Đó là tiếng nói của cơ thể cần được nghỉ ngơi.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(966, 164, 'hook', '{\"title\": \"Bạn sẽ làm gì khi cơn tức giận hoặc nỗi lo lắng ập đến như một vị khách không mời mà tới?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(967, 164, 'explanation', '{\"bullets\": [\"Thay vì cố đẩy \'vị khách\' cảm xúc khó chịu đi, hãy học cách ngồi xuống quan sát nó.\", \"Nhận biết cảm giác đó trên cơ thể: tim đập nhanh, thở nông, hay tay bóp chặt.\", \"Sử dụng các kỹ thuật như hít thở sâu, đi bộ, hoặc viết ra để giúp cảm xúc đó trôi qua một cách tự nhiên.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(968, 164, 'scenario', '{\"title\": \"Trước thềm thuyết trình\", \"body\": \"Khi chuẩn bị lên thuyết trình trước lớp, Vy cảm thấy tim đập thình thịch, tay run rẩy và đầu óc trống rỗng vì quá lo sợ. Vy muốn chạy trốn khỏi lớp học.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(969, 164, 'interaction', '{\"question\": \"Hành động nào giúp Vy bình tĩnh lại nhanh nhất lúc này?\", \"choices\": [{\"text\": \"Hít vào thật sâu bằng mũi trong 4 giây, giữ hơi 7 giây, và thở ra từ từ bằng miệng trong 8 giây.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Cố gắng uống thật nhiều nước ngọt có ga và chạy nhảy xung quanh lớp.\", \"correct\": false, \"emoji\": \"☹️\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(970, 164, 'reflection', '{\"question\": \"Mẹo nhỏ nào bạn thường dùng để giữ bình tĩnh trước các sự kiện quan trọng?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(971, 164, 'takeaway', '{\"items\": [\"Bạn không thể ngăn cơn sóng cảm xúc ập đến, nhưng bạn có thể học cách lướt sóng.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(972, 165, 'hook', '{\"title\": \"Làm thế nào để dọn dẹp đống suy nghĩ ngổn ngang trong đầu trước khi đi ngủ?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(973, 165, 'explanation', '{\"bullets\": [\"Viết ra giấy hoặc ghi chú trên điện thoại là cách tuyệt vời để \'xuất khẩu\' những lo âu ra ngoài bộ não.\", \"Bạn không cần phải viết một bài văn hay, chỉ cần viết tự do tất cả những gì đang có trong đầu.\", \"Việc này giúp bạn nhìn nhận lại mọi việc một cách khách quan và giải tỏa áp lực tinh thần cực kỳ hiệu quả.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(974, 165, 'scenario', '{\"title\": \"Ấm ức trong đêm\", \"body\": \"Tú cảm thấy ấm ức vì bị bạn bè hiểu lầm. Cả tối Tú nằm trằn trọc không ngủ được, đầu óc liên tục tua đi tua lại cuộc cãi vã và tự nghĩ ra những lời cãi cọ sắc bén hơn.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(975, 165, 'sorting', '{\"instruction\": \"Phân loại các thói quen giải tỏa suy nghĩ trước khi ngủ:\", \"leftBox\": {\"title\": \"Dọn dẹp trí óc\"}, \"rightBox\": {\"title\": \"Overthinking\"}, \"items\": [{\"text\": \"Viết hết nỗi bực bội ra giấy nháp rồi xé bỏ\", \"correctBox\": \"left\"}, {\"text\": \"Nằm tua đi tua lại cuộc cãi vã trong đầu\", \"correctBox\": \"right\"}, {\"text\": \"Liệt kê 3 điều bạn thấy biết ơn trong ngày hôm nay\", \"correctBox\": \"left\"}, {\"text\": \"Lướt mạng xã hội xem đối phương có đăng bài viết bóng gió gì không\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(976, 165, 'reflection', '{\"question\": \"Bạn đã từng thử viết ra những suy nghĩ của mình khi tức giận chưa? Cảm giác lúc đó thế nào?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(977, 165, 'takeaway', '{\"items\": [\"Đầu óc dùng để suy nghĩ chứ không phải để lưu trữ lo âu. Hãy trút bỏ chúng ra trang giấy.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(978, 166, 'hook', '{\"title\": \"Có phải tự tin là lúc nào cũng phải nói to, nổi bật và không bao giờ biết sợ hãi?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(979, 166, 'explanation', '{\"bullets\": [\"Tự tin thực sự (Self-esteem) là việc bạn chấp nhận bản thân với cả ưu điểm lẫn khuyết điểm, cảm thấy mình xứng đáng được tôn trọng.\", \"Tự tin \'fake\' là khi bạn cố gồng mình tỏ ra hoàn hảo, lấn lướt người khác để che giấu sự bất an bên trong.\", \"Người tự tin thực sự không cần phải so sánh mình với ai để cảm thấy mình có giá trị.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(980, 166, 'scenario', '{\"title\": \"Gồng mình làm trung tâm\", \"body\": \"Hoàng luôn cố gắng chen vào mọi cuộc trò chuyện, khoe khoang về những món đồ hiệu mình có và cười cợt các bạn học kém hơn để chứng tỏ mình \'đẳng cấp\'. Nhưng khi ở một mình, Hoàng luôn sợ bị các bạn tẩy chay.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(981, 166, 'flashcard', '{\"front\": \"Làm sao để nhận diện một người có lòng tự tin thực sự và lành mạnh?\", \"back\": \"Họ biết lắng nghe, sẵn sàng thừa nhận khi mình sai, tôn trọng ranh giới của người khác và không cần dìm người khác xuống để nâng mình lên.\", \"notes\": \"Tự tin là một chiếc cúp nằm trong lòng, chứ không phải cái loa phát thanh ra bên ngoài.\"}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(982, 166, 'reflection', '{\"question\": \"Bạn có bao giờ cố tỏ ra \'ngầu\' trước mặt người khác dù bên trong đang rất run không?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(983, 166, 'takeaway', '{\"items\": [\"Tự tin thực sự bắt đầu từ việc chấp nhận con người thật của chính mình.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(984, 167, 'hook', '{\"title\": \"Làm sao để chia sẻ niềm vui chiến thắng của mình mà không bị bạn bè coi là kẻ kiêu ngạo, hợm hĩnh?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(985, 167, 'explanation', '{\"bullets\": [\"Bạn hoàn toàn có quyền tự hào và ăn mừng những nỗ lực, thành quả của bản thân (Self-worth).\", \"Điểm khác biệt là: Tự hào đi kèm lòng biết ơn và sự tôn trọng người khác, còn \'flexing\' (khoe khoang) mục đích là để chứng tỏ mình giỏi hơn mọi người.\", \"Đừng ngại công nhận sự cố gắng của chính mình nhé!\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(986, 167, 'scenario', '{\"title\": \"Đăng ảnh nhận giải\", \"body\": \"Khánh vừa đạt giải nhất cuộc thi vẽ cấp trường. Khánh muốn đăng ảnh bức tranh lên mạng xã hội nhưng sợ các bạn bảo mình là kẻ hợm hĩnh, thích thể hiện.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(987, 167, 'interaction', '{\"question\": \"Khánh nên viết caption như thế nào để vừa thể hiện sự tự hào vừa văn minh, khiêm tốn?\", \"choices\": [{\"text\": \"\'Bức tranh này là kết quả của 3 tuần thức đêm vẽ liên tục của tớ. Cảm ơn thầy cô và các bạn đã cổ vũ tớ rất nhiều!\'\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"\'Cuối cùng giải nhất cũng thuộc về người xứng đáng nhất. Vẽ vời thế này thì các bạn khác chạy theo dài dài nhé!\'\", \"correct\": false, \"emoji\": \"☹️\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(988, 167, 'reflection', '{\"question\": \"Lần gần nhất bạn tự khen ngợi bản thân vì đã hoàn thành tốt một việc gì đó là khi nào?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(989, 167, 'takeaway', '{\"items\": [\"Công nhận nỗ lực của bản thân không phải là kiêu ngạo. Đó là sự tử tế tối thiểu dành cho chính mình.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(990, 168, 'hook', '{\"title\": \"Tại sao việc so sánh bản thân với người khác lại là cách nhanh nhất để hủy hoại niềm vui của bạn?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(991, 168, 'explanation', '{\"bullets\": [\"Não bộ chúng ta có xu hướng so sánh điểm yếu nhất của mình với điểm mạnh nhất của người khác.\", \"Mạng xã hội hay những lời so sánh của bố mẹ vô tình củng cố cảm giác \'mình không bao giờ đủ giỏi\'.\", \"Mỗi người có một xuất phát điểm và một lộ trình phát triển hoàn toàn khác nhau.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(992, 168, 'scenario', '{\"title\": \"Cảm giác kém cỏi\", \"body\": \"Vy lướt mạng xã hội thấy bạn cùng lớp đăng ảnh nhận học bổng tiếng Anh, đi du lịch nước ngoài cực kỳ sang chảnh. Nhìn lại mình, Vy thấy mình thật kém cỏi, vô dụng và chỉ muốn xóa app.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(993, 168, 'sorting', '{\"instruction\": \"Phân loại các suy nghĩ khi đối mặt với thành công của người khác:\", \"leftBox\": {\"title\": \"Tập trung vào mình\"}, \"rightBox\": {\"title\": \"Bẫy so sánh\"}, \"items\": [{\"text\": \"Chúc mừng bạn và tự nhủ: Mình cũng đang nỗ lực trên con đường riêng\", \"correctBox\": \"left\"}, {\"text\": \"Tự trách bản thân tại sao lười biếng và không được giỏi như bạn\", \"correctBox\": \"right\"}, {\"text\": \"Hạn chế thời gian lướt mạng xã hội khi thấy tâm trạng không tốt\", \"correctBox\": \"left\"}, {\"text\": \"Nghi ngờ năng lực của mình và bỏ cuộc không muốn học nữa\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(994, 168, 'reflection', '{\"question\": \"Bạn có đang tự so sánh mình với ai khác gần đây không?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(995, 168, 'takeaway', '{\"items\": [\"Đừng so sánh chương 1 của mình với chương 10 của người khác.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(996, 169, 'hook', '{\"title\": \"Bạn có bao giờ cảm thấy mình là một kẻ thất bại thảm hại chỉ vì nhận được một điểm số không như ý muốn?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(997, 169, 'explanation', '{\"bullets\": [\"Điểm số chỉ phản ánh mức độ hiểu bài của bạn ở một thời điểm cụ thể, chứ không đo lường được giá trị con người bạn.\", \"Thất bại hay điểm kém chỉ là thông tin phản hồi (feedback) để bạn biết mình cần cải thiện chỗ nào.\", \"Tách biệt hành vi (bị điểm kém) khỏi giá trị bản thân (mình là người kém cỏi) giúp bạn có động lực để học tập.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(998, 169, 'scenario', '{\"title\": \"Trải nghiệm điểm 4\", \"body\": \"Bình nhận bài kiểm tra Toán chỉ được 4 điểm. Cậu cảm thấy vô cùng xấu hổ, nghĩ rằng mình học dốt bẩm sinh và bố mẹ sẽ không còn yêu thương mình nữa.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(999, 169, 'flashcard', '{\"front\": \"Bình nên nói gì với bản thân để lấy lại động lực học tập thay vì tự dằn vặt?\", \"back\": \"Bài kiểm tra này mình làm chưa tốt vì chưa ôn kỹ phần hình học. Mình sẽ nhờ bạn chỉ lại bài và cố gắng hơn ở lần sau.\", \"notes\": \"Điểm số là thước đo bài làm, không phải thước đo nhân cách hay tương lai của bạn.\"}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1000, 169, 'reflection', '{\"question\": \"Khi gặp thất bại trong học tập, bạn thường tự trách móc bản thân hay tìm cách khắc phục?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1001, 169, 'takeaway', '{\"items\": [\"Điểm số thấp chỉ là tạm thời. Giá trị và khả năng học hỏi của bạn mới là vĩnh viễn.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1002, 170, 'hook', '{\"title\": \"Nếu bạn nói chuyện với bạn thân bằng giọng điệu mà bạn đang tự nói với chính mình, liệu hai người có còn chơi với nhau không?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1003, 170, 'explanation', '{\"bullets\": [\"Nhiều bạn trẻ có xu hướng tự chỉ trích bản thân rất khắc nghiệt (như: \'Mày ngốc quá\', \'Mày luôn làm hỏng mọi chuyện\').\", \"Hãy tập thói quen sử dụng lòng tự trắc ẩn (Self-compassion) - trò chuyện với bản thân như cách bạn khuyên bảo một người bạn thân.\", \"Sử dụng những câu nói nâng đỡ thay vì những lời phán xét cay độc.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1004, 170, 'scenario', '{\"title\": \"Sự cố bài tập nhóm\", \"body\": \"Mai vô tình làm đổ nước vào bài tập nhóm của cả tổ. Cô bạn bắt đầu hoảng loạn, liên tục tự chửi mình trong đầu: \'Đồ hậu đậu dốt nát, mày lúc nào cũng phá hoại mọi thứ!\'.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1005, 170, 'interaction', '{\"question\": \"Mai nên thay đổi câu độc thoại nội tâm thế nào để bình tĩnh giải quyết sự cố?\", \"choices\": [{\"text\": \"\'Mình chỉ vô tình thôi, ai cũng có lúc bất cẩn mà. Giờ mình cùng các bạn chép lại hoặc xin lỗi tổ nhé.\'\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"\'Mình đúng là quả tạ của nhóm, tốt nhất lần sau không nên tham gia làm gì nữa.\'\", \"correct\": false, \"emoji\": \"☹️\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1006, 170, 'reflection', '{\"question\": \"Lời nói khắc nghiệt nhất bạn từng tự nói với bản thân là gì?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1007, 170, 'takeaway', '{\"items\": [\"Hãy dịu dàng với bản thân. Bạn đang làm tốt nhất những gì có thể rồi.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1008, 171, 'hook', '{\"title\": \"Tại sao việc cố gắng trở nên hoàn hảo 100% trong mắt tất cả mọi người lại là một nhiệm vụ bất khả thi?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1009, 171, 'explanation', '{\"bullets\": [\"Không ai trên đời này hoàn hảo cả. Những khuyết điểm hay lỗi lầm nhỏ chính là thứ làm nên sự độc bản của bạn.\", \"Học cách chấp nhận những điều không hoàn hảo của mình (Self-acceptance) giúp bạn giải phóng một lượng lớn áp lực tinh thần.\", \"Cho phép bản thân được sai sót và lớn lên từ những sai sót đó.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1010, 171, 'scenario', '{\"title\": \"Áp lực hoàn mỹ\", \"body\": \"Hải luôn cảm thấy căng thẳng vì muốn mình phải học giỏi nhất lớp, chơi thể thao hay nhất, và luôn ăn mặc thời trang nhất. Chỉ cần một ngày bị điểm 8 hay mặc bộ quần áo hơi lỗi mốt, Hải sẽ thấy vô cùng tồi tệ.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1011, 171, 'sorting', '{\"instruction\": \"Phân loại các thái độ đối với khuyết điểm cá nhân:\", \"leftBox\": {\"title\": \"Chấp nhận bao dung\"}, \"rightBox\": {\"title\": \"Cầu toàn cực đoan\"}, \"items\": [{\"text\": \"Coi lỗi sai là cơ hội để học hỏi và rút kinh nghiệm\", \"correctBox\": \"left\"}, {\"text\": \"Mất ăn mất ngủ cả tuần chỉ vì nói vấp một câu trước đám đông\", \"correctBox\": \"right\"}, {\"text\": \"Yêu mến cả những vết sẹo hay nốt tàn nhang trên cơ thể mình\", \"correctBox\": \"left\"}, {\"text\": \"Liên tục dằn vặt bản thân vì không đạt vị trí dẫn đầu\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1012, 171, 'reflection', '{\"question\": \"Khuyết điểm nào của bản thân mà bạn đang tập cách làm quen và chấp nhận gần đây?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1013, 171, 'takeaway', '{\"items\": [\"Hoàn hảo là một ảo ảnh. Không hoàn hảo mới là cuộc sống thực tế.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1014, 172, 'hook', '{\"title\": \"Bạn có từng thấy buồn bã vì làn da của mình ngoài đời không được mịn màng, trắng sáng như những bức ảnh trên mạng xã hội?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1015, 172, 'explanation', '{\"bullets\": [\"Hầu hết hình ảnh của người nổi tiếng hoặc các hot teen trên mạng xã hội đều đã qua chỉnh sửa, sử dụng filter và góc chụp chuyên nghiệp.\", \"Việc so sánh cơ thể thật của mình với một hình ảnh đã qua chỉnh sửa kỹ thuật số là hoàn toàn không công bằng.\", \"Làn da có lỗ chân lông, mụn, hay vết rạn đều là những đặc tính sinh học tự nhiên và bình thường.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1016, 172, 'scenario', '{\"title\": \"Chụp ảnh selfie\", \"body\": \"Linh dành cả tiếng đồng hồ để chụp ảnh tự sướng, thử hàng chục filter chỉnh mặt thon, da trắng mịn mới dám đăng bài. Khi nhìn vào gương thấy những nốt mụn và làn da hơi ngăm của mình, Linh cảm thấy rất ghét bỏ khuôn mặt thật.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1017, 172, 'flashcard', '{\"front\": \"Làm thế nào để bảo vệ sức khỏe tinh thần trước những hình ảnh \'hoàn hảo\' trên mạng xã hội?\", \"back\": \"Tự nhắc nhở bản thân: Mạng xã hội là sàn diễn, đời thực mới là cuộc sống. Nhấn nút hủy theo dõi những tài khoản khiến bạn thấy tự ti về ngoại hình.\", \"notes\": \"Đừng so sánh cuộc sống thô (raw) của bạn với sản phẩm đã qua biên tập (edit) của người khác.\"}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1018, 172, 'reflection', '{\"question\": \"Bạn có hay dùng app chỉnh sửa ảnh trước khi đăng lên mạng xã hội không?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1019, 172, 'takeaway', '{\"items\": [\"Làn da thật có kết cấu và khuyết điểm. Đó mới là biểu hiện của một cơ thể đang sống.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1020, 173, 'hook', '{\"title\": \"Tại sao xã hội lại cứ phải đặt ra những tiêu chuẩn như \'con gái phải gầy, con trai phải cơ bắp\' trong khi gen của chúng ta lại hoàn toàn khác nhau?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1021, 173, 'explanation', '{\"bullets\": [\"Gen di truyền quyết định khung xương, chiều cao và phân bổ mỡ tự nhiên của mỗi người.\", \"Có những người sinh ra đã có vóc dáng đậm đà, có người lại cao gầy dù ăn uống thế nào đi nữa.\", \"Sức khỏe và sự dẻo dai quan trọng hơn rất nhiều so với việc ép cơ thể vào một size quần áo nhất định.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1022, 173, 'scenario', '{\"title\": \"Áp lực tăng cơ bắp\", \"body\": \"Đức cao 1m70 nhưng nặng chỉ 50kg, trông khá gầy. Cậu cố gắng ăn thật nhiều và tập tạ nặng quá sức để mong có cơ bắp như các idol trên mạng, dẫn đến chấn thương cơ vai.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1023, 173, 'interaction', '{\"question\": \"Đức nên thay đổi mục tiêu luyện tập thế nào để bảo vệ sức khỏe và yêu thương cơ thể?\", \"choices\": [{\"text\": \"Tập trung vào các bài tập vừa sức để tăng sự dẻo dai, bền bỉ và ăn uống đủ chất theo nhịp độ tự nhiên của cơ thể.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tiếp tục nhịn ăn hoặc uống các loại sữa tăng cơ thần tốc không rõ nguồn gốc để đạt mục tiêu nhanh nhất.\", \"correct\": false, \"emoji\": \"☹️\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1024, 173, 'reflection', '{\"question\": \"Bạn có đang yêu thích một đặc điểm khỏe mạnh nào trên cơ thể mình lúc này không?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1025, 173, 'takeaway', '{\"items\": [\"Cơ thể bạn là phương tiện để bạn trải nghiệm cuộc sống, không phải là món đồ trang trí để người khác ngắm nhìn.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1026, 174, 'hook', '{\"title\": \"Bạn có bao giờ vô tình buột miệng nhận xét \'Dạo này béo thế?\' hay \'Sao đen thế?\' với bạn bè như một lời chào hỏi thông thường chưa?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1027, 174, 'explanation', '{\"bullets\": [\"Phán xét ngoại hình người khác đôi khi bắt nguồn từ việc chúng ta tự ti về chính mình hoặc do thói quen giao tiếp thiếu tinh tế.\", \"Những câu đùa cợt vô ý về ngoại hình có thể để lại tổn thương tâm lý rất sâu sắc cho người nghe.\", \"Tập thói quen khen ngợi năng lực, tính cách thay vì tập trung vào diện mạo bên ngoài của người khác.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1028, 174, 'scenario', '{\"title\": \"Câu trêu đùa vô duyên\", \"body\": \"Trong buổi họp lớp, nhóm bạn nam cười hố hố trêu chọc Tuấn vì dạo này Tuấn mọc ria mép và trông béo ra: \'Nhìn như ông chú trung niên ấy nhỉ!\'. Tuấn chỉ biết cười trừ nhưng trong lòng thấy rất khó chịu.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1029, 174, 'sorting', '{\"instruction\": \"Phân loại các câu mở đầu cuộc trò chuyện văn minh và lịch sự:\", \"leftBox\": {\"title\": \"Nói lời tinh tế\"}, \"rightBox\": {\"title\": \"Phán xét ngoại hình\"}, \"items\": [{\"text\": \"Dạo này cậu có dự án hay sở thích gì mới không?\", \"correctBox\": \"left\"}, {\"text\": \"Kìa, sao dạo này mọc nhiều mụn thế kia?\", \"correctBox\": \"right\"}, {\"text\": \"Tớ rất thích màu áo này của cậu, trông rất năng động!\", \"correctBox\": \"left\"}, {\"text\": \"Sao dạo này gầy gò ốm yếu thế, không ăn uống gì à?\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1030, 174, 'reflection', '{\"question\": \"Bạn từng cảm thấy thế nào khi nhận được một lời nhận xét không mấy tích cực về ngoại hình của mình?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1031, 174, 'takeaway', '{\"items\": [\"Lời nói có sức nặng. Hãy dùng ngôn từ để sưởi ấm thay vì làm tổn thương ngoại hình của nhau.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1032, 175, 'hook', '{\"title\": \"Có bộ phận nào trên cơ thể khiến bạn cảm thấy không hài lòng mỗi khi nhìn vào gương không?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1033, 175, 'explanation', '{\"bullets\": [\"Việc không thích một vài điểm trên cơ thể (như mũi tẹt, đùi to, mắt một mí) là tâm lý rất phổ biến ở tuổi teen.\", \"Tuy nhiên, những đặc điểm đó không làm giảm đi sự đáng yêu và giá trị tổng thể của bạn.\", \"Thay vì cố sửa đổi bằng mọi giá, hãy thử học cách sống hòa bình với những đặc điểm \'lệch chuẩn\' đó.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1034, 175, 'scenario', '{\"title\": \"Tìm cách che khuyết điểm\", \"body\": \"Trang rất tự ti vì có chiếc mũi hơi tẹt và cánh mũi to. Mỗi lần chụp ảnh nhóm, cô bạn đều cố né tránh ống kính hoặc lấy tay che mũi vì sợ các bạn chê xấu.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1035, 175, 'flashcard', '{\"front\": \"Trang nên làm gì để bớt áp lực về chiếc mũi lệch chuẩn của mình?\", \"back\": \"Tập trung vào những nét đẹp khác như nụ cười rạng rỡ, đôi mắt sáng, và tự nhắc nhở: Chiếc mũi này thừa hưởng từ bố mẹ, nó là một phần nguồn gốc đáng tự hào của mình.\", \"notes\": \"Nụ cười tự tin chính là lớp trang điểm đẹp nhất làm mờ đi mọi khuyết điểm ngoại hình.\"}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1036, 175, 'reflection', '{\"question\": \"Bạn có thể liệt kê 3 điều bạn yêu thích về cơ thể mình lúc này không?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1037, 175, 'takeaway', '{\"items\": [\"Bạn không cần có một cơ thể hoàn hảo để sống một cuộc đời tuyệt vời.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1038, 176, 'hook', '{\"title\": \"Bạn sẽ phản ứng thế nào khi bị ai đó nhận xét khiếm nhã về ngoại hình ngay trước đám đông?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1039, 176, 'explanation', '{\"bullets\": [\"Im lặng chịu đựng hoặc tức giận cãi vã đôi khi không phải là cách giải quyết tối ưu.\", \"Bạn có quyền thiết lập ranh giới rõ ràng và thể hiện sự không thoải mái của mình một cách kiên định, lịch sự.\", \"Phản hồi bình thản giúp bạn giữ được thế chủ động và làm đối phương phải tự xem lại cách cư xử của họ.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1040, 176, 'scenario', '{\"title\": \"Nhận xét vô ý tại bàn ăn\", \"body\": \"Tại bàn ăn gia đình, một người họ hàng xa nhận xét lớn tiếng: \'Chà, con gái con lứa mà đùi to như cột đình thế kia thì sau này ai thèm yêu!\'. Cả nhà im lặng nhìn Mai.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1041, 176, 'interaction', '{\"question\": \"Mai nên phản hồi thế nào để bảo vệ ranh giới của mình một cách văn minh, tự tin?\", \"choices\": [{\"text\": \"Nhìn thẳng vào họ và nói nhẹ nhàng: \'Cháu thấy đùi cháu khỏe khoắn để tập thể thao rất tốt ạ. Chúng ta nói chuyện khác vui hơn cô nhé!\'\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Bỏ đũa xuống khóc lóc chạy lên phòng hoặc hét to: \'Cô vô duyên vừa thôi chứ!\'\", \"correct\": false, \"emoji\": \"🙁\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1042, 176, 'reflection', '{\"question\": \"Bạn đã từng thiết lập ranh giới thành công trước một lời chê bai ngoại hình chưa?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1043, 176, 'takeaway', '{\"items\": [\"Ý kiến của người khác về cơ thể bạn là việc của họ, không phải là sự thật về bạn.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1044, 177, 'hook', '{\"title\": \"Đã bao giờ bạn dừng lại để cảm ơn cơ thể mình vì đã giúp bạn hít thở, chạy nhảy và học hỏi chưa?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1045, 177, 'explanation', '{\"bullets\": [\"Cơ thể bạn không phải là một món đồ để trưng bày, nó là một cỗ máy sinh học kỳ diệu đang làm việc 24/7 để giữ bạn sống sót.\", \"Chuyển sự chú ý từ diện mạo bên ngoài (nhìn trông thế nào) sang chức năng bên trong (làm được những gì) là chìa khóa của sự tự chấp nhận.\", \"Đối xử tử tế với cơ thể bằng cách cho nó ăn ngon, ngủ đủ và vận động nhẹ nhàng.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1046, 177, 'scenario', '{\"title\": \"Phút tĩnh lặng cuối ngày\", \"body\": \"Sau một ngày học tập mệt mỏi, An nằm dài ra giường, nghe nhịp đập của tim, cảm nhận đôi chân mỏi nhừ sau buổi tập thể dục và chợt nhận ra cơ thể mình đã vất vả thế nào suốt cả ngày.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1047, 177, 'sorting', '{\"instruction\": \"Phân loại các hành động thể hiện sự trân trọng cơ thể:\", \"leftBox\": {\"title\": \"Yêu thương cơ thể\"}, \"rightBox\": {\"title\": \"Ngược đãi cơ thể\"}, \"items\": [{\"text\": \"Uống đủ nước và ngủ trước 11h đêm để các cơ quan phục hồi\", \"correctBox\": \"left\"}, {\"text\": \"Nhịn ăn bỏ bữa để ép cân nặng giảm nhanh chóng\", \"correctBox\": \"right\"}, {\"text\": \"Tập các bài yoga nhẹ nhàng giúp giãn cơ sau giờ học căng thẳng\", \"correctBox\": \"left\"}, {\"text\": \"Tiếp tục chạy bộ quá sức dù chân đang bị đau khớp sưng đỏ\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1048, 177, 'reflection', '{\"question\": \"Hôm nay, bạn muốn gửi lời cảm ơn đến bộ phận nào trên cơ thể mình nhất?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1049, 177, 'takeaway', '{\"items\": [\"Cơ thể là ngôi nhà duy nhất bạn có. Hãy yêu thương và chăm sóc nó chu đáo.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1050, 178, 'hook', '{\"title\": \"Bạn có biết stress không chỉ nằm trong đầu mà nó còn biểu hiện rất rõ ràng trên cơ thể của bạn không?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1051, 178, 'explanation', '{\"bullets\": [\"Khi bạn lo lắng hoặc gặp áp lực, não bộ sẽ giải phóng các hormone stress như cortisol và adrenaline.\", \"Các cơ của bạn sẽ căng lên, tim đập nhanh hơn, dạ dày co bóp mạnh gây đau bụng, và bạn có thể bị mất ngủ.\", \"Những triệu chứng thể chất này là tín hiệu \'SOS\' nhắc nhở bạn: Cơ thể đang quá tải rồi!\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1052, 178, 'scenario', '{\"title\": \"Áp lực thi cử\", \"body\": \"Chuẩn bị đến kỳ thi học kỳ, Khoa liên tục bị đau bụng âm ỉ, vai gáy mỏi nhừ, tối nằm trằn trọc mãi không ngủ được và sáng dậy với cảm giác mệt mỏi rã rời.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1053, 178, 'flashcard', '{\"front\": \"Làm thế nào để nhận biết cơ thể mình đang bị stress quá mức?\", \"back\": \"Các biểu hiện phổ biến: Đau đầu, đau dạ dày vô cớ, nổi mụn đột ngột, nghiến răng khi ngủ, dễ nổi cáu và khó tập trung.\", \"notes\": \"Đau bụng trước giờ kiểm tra không phải do bạn giả vờ, đó là phản ứng sinh học thực tế của stress.\"}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1054, 178, 'reflection', '{\"question\": \"Bộ phận nào trên cơ thể bạn thường \'lên tiếng\' đầu tiên mỗi khi bạn gặp áp lực lớn?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1055, 178, 'takeaway', '{\"items\": [\"Lắng nghe tín hiệu từ cơ thể. Nó đang nói với bạn khi nào cần dừng lại để nghỉ ngơi.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1056, 179, 'hook', '{\"title\": \"Có phải tất cả mọi căng thẳng đều xấu và chúng ta nên triệt tiêu stress hoàn toàn khỏi cuộc sống?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1057, 179, 'explanation', '{\"bullets\": [\"Stress tích cực (Eustress) ở mức độ vừa phải giúp bạn tập trung hơn, nhạy bén hơn để hoàn thành mục tiêu ngắn hạn (như ôn thi, thuyết trình).\", \"Stress độc hại (Distress) kéo dài liên tục mà không có thời gian nghỉ ngơi sẽ làm suy yếu hệ miễn dịch và gây kiệt quệ tinh thần.\", \"Mục tiêu là kiểm soát và cân bằng stress chứ không phải trốn tránh nó hoàn toàn.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1058, 179, 'scenario', '{\"title\": \"Hai thái cực căng thẳng\", \"body\": \"Tâm cảm thấy hơi hồi hộp trước trận đấu bóng rổ, nhưng cảm giác này giúp cậu chạy nhanh và tập trung hơn. Ngược lại, Hải lo lắng về kỳ thi suốt 3 tháng trời, không đêm nào ngủ ngon và luôn thấy kiệt sức.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1059, 179, 'interaction', '{\"question\": \"Cảm giác căng thẳng của bạn nào trong kịch bản trên là stress độc hại cần can thiệp?\", \"choices\": [{\"text\": \"Của bạn Hải, vì sự căng thẳng kéo dài liên tục gây ảnh hưởng nghiêm trọng đến giấc ngủ và thể chất.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Của bạn Tâm, vì hồi hộp trước trận đấu là biểu hiện của sự yếu đuối, nhút nhát.\", \"correct\": false, \"emoji\": \"☹️\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1060, 179, 'reflection', '{\"question\": \"Bạn đã từng trải qua khoảnh khắc nào mà sự căng thẳng giúp bạn làm việc năng suất hơn chưa?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1061, 179, 'takeaway', '{\"items\": [\"Một chút áp lực giúp ta tiến lên, nhưng quá nhiều áp lực sẽ làm ta đổ gục. Hãy biết giới hạn của mình.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1062, 180, 'hook', '{\"title\": \"Bạn thường làm gì khi gặp áp lực: Đối mặt giải quyết hay trốn vào game, mạng xã hội để quên đi thực tại?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1063, 180, 'explanation', '{\"bullets\": [\"Trốn tránh (Avoidance) bằng cách lướt điện thoại hay chơi game chỉ mang lại cảm giác dễ chịu tạm thời, nhưng vấn đề vẫn còn nguyên và stress sẽ quay lại lớn hơn.\", \"Đối mặt chủ động bằng cách chia nhỏ công việc, lên kế hoạch từng bước giúp bạn giải quyết gốc rễ của sự lo âu.\", \"Sử dụng chiến thuật \'tạm nghỉ\' để sạc pin chứ không phải để chạy trốn vĩnh viễn.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1064, 180, 'scenario', '{\"title\": \"Bẫy lảng tránh\", \"body\": \"Đức có bài tập lớn cần nộp vào ngày mai. Càng lo lắng, Đức càng không muốn làm, cậu mở điện thoại ra chơi game suốt 5 tiếng liên tục để trốn tránh cảm giác tội lỗi. Đến tối muộn, Đức càng hoảng loạn hơn.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1065, 180, 'sorting', '{\"instruction\": \"Phân loại các cách ứng phó khi gặp núi công việc áp lực:\", \"leftBox\": {\"title\": \"Đối mặt chủ động\"}, \"rightBox\": {\"title\": \"Trốn tránh thụ động\"}, \"items\": [{\"text\": \"Viết danh sách các việc cần làm và thực hiện việc nhỏ nhất trước\", \"correctBox\": \"left\"}, {\"text\": \"Nằm lướt TikTok liên tục để không phải nghĩ về đống bài tập\", \"correctBox\": \"right\"}, {\"text\": \"Nhờ bạn bè hoặc thầy cô chỉ dẫn những phần bài quá khó\", \"correctBox\": \"left\"}, {\"text\": \"Tự nhủ: Cứ để mai tính, giờ đi chơi game cho đỡ mệt đầu\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1066, 180, 'reflection', '{\"question\": \"Món đồ hay ứng dụng nào bạn thường tìm đến nhiều nhất mỗi khi muốn trốn tránh áp lực?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1067, 180, 'takeaway', '{\"items\": [\"Chia nhỏ thử thách giúp biến nỗi sợ hãi khổng lồ thành những bước đi khả thi.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1068, 181, 'hook', '{\"title\": \"Làm thế nào để sinh tồn qua những tuần lễ thi cử dồn dập mà không bị rơi vào trạng thái hoảng loạn tinh thần?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1069, 181, 'explanation', '{\"bullets\": [\"Mùa thi cử là thời điểm nhạy cảm dễ kích hoạt stress độc hại nhất ở học sinh.\", \"Quản lý thời gian học tập khoa học kết hợp nghỉ giải lao hợp lý (như phương pháp Pomodoro) giúp não bộ ghi nhớ tốt hơn.\", \"Đừng quên rằng bộ não của bạn cần oxy, nước và giấc ngủ để hoạt động, chứ không chỉ cần nhồi nhét kiến thức.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1070, 181, 'scenario', '{\"title\": \"Cố quá sức trước ngày thi\", \"body\": \"Vy ôn thi bằng cách thức trắng đêm đến 3h sáng, uống nước tăng lực liên tục và nhịn ăn sáng. Đến giờ thi, đầu óc Vy bỗng dưng trống rỗng, tay chân bủn rủn dù đã học rất nhiều.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1071, 181, 'flashcard', '{\"front\": \"Làm thế nào để ôn thi hiệu quả mà vẫn giữ được sức khỏe tinh thần ổn định?\", \"back\": \"Học 25 phút nghỉ giải lao 5 phút, uống đủ nước, ngủ ít nhất 7 tiếng trước ngày thi, và ăn sáng đầy đủ để cung cấp năng lượng cho não bộ.\", \"notes\": \"Một bộ não được nghỉ ngơi đầy đủ sẽ làm bài tốt hơn một bộ nhồi nhét mệt mỏi.\"}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1072, 181, 'reflection', '{\"question\": \"Bạn đã từng bị \'đóng băng\' đầu óc trong phòng thi vì quá căng thẳng chưa?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1073, 181, 'takeaway', '{\"items\": [\"Kết quả thi cử rất quan trọng, nhưng sức khỏe và sự bình an của bạn còn quan trọng hơn.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1074, 182, 'hook', '{\"title\": \"Bạn có muốn học một mẹo nhỏ có thể giúp bạn bình tĩnh lại ngay lập tức chỉ trong vòng 60 giây không?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1075, 182, 'explanation', '{\"bullets\": [\"Hít thở nông và nhanh khi lo lắng sẽ kích hoạt hệ thần kinh giao cảm duy trì trạng thái hoảng sợ.\", \"Kỹ thuật thở 4-7-8 giúp kích hoạt hệ thần kinh đối giao cảm, gửi tín hiệu \'an toàn\' đến não để làm chậm nhịp tim và thư giãn cơ bắp.\", \"Cách làm: Hít vào bằng mũi (4s), giữ hơi (7s), thở ra bằng miệng (8s). Lặp lại 4 lần.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1076, 182, 'scenario', '{\"title\": \"Căng thẳng thi nói\", \"body\": \"Trước khi bước vào phòng thi vấn đáp tiếng Anh, tim của Chi đập thình thịch như muốn nhảy ra ngoài, mồ hôi tay vã ra. Chi quyết định dừng lại, nhắm mắt và thực hiện 3 chu kỳ thở 4-7-8.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1077, 182, 'interaction', '{\"question\": \"Tại sao Chi lại cảm thấy bình tĩnh hơn sau khi thực hiện bài tập thở sâu?\", \"choices\": [{\"text\": \"Thở sâu làm giảm nồng độ hormone stress và báo cho bộ não biết cơ thể đang ở trạng thái an toàn.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Thở sâu chỉ là một mẹo tâm lý tự lừa bản thân chứ không có tác dụng sinh học nào.\", \"correct\": false, \"emoji\": \"☹️\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1078, 182, 'reflection', '{\"question\": \"Hãy cùng thực hành ngay một chu kỳ thở 4-7-8 lúc này. Bạn cảm thấy cơ thể nhẹ nhõm hơn không?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1079, 182, 'takeaway', '{\"items\": [\"Hơi thở là chiếc mỏ neo giúp bạn định vị bản thân giữa cơn bão lo âu.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1080, 183, 'hook', '{\"title\": \"Bạn có chuẩn bị sẵn cho mình một danh sách những hoạt động \'cứu hộ\' mỗi khi áp lực cuộc sống tăng lên quá cao không?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1081, 183, 'explanation', '{\"bullets\": [\"Giống như nồi áp suất, bộ não bạn cần một chiếc \'van xả\' để giải phóng bớt căng thẳng tích tụ.\", \"Van xả lành mạnh là những hoạt động giúp bạn ngắt kết nối với nguồn gây stress và nạp lại năng lượng (như vẽ tranh, chơi thể thao, nghe nhạc, trò chuyện).\", \"Tránh các van xả độc hại như ăn uống quá độ, thức khuya xem phim hay cáu gắt với người khác.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1082, 183, 'scenario', '{\"title\": \"Thói quen xả nhiệt\", \"body\": \"Mỗi khi cảm thấy quá tải vì bài vở, Nguyên thường đi tắm nước ấm, sau đó ra ban công ngồi nghe một bài hát yêu thích trong 10 phút trước khi quay lại bàn học.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1083, 183, 'sorting', '{\"instruction\": \"Phân loại các hoạt động xả stress:\", \"leftBox\": {\"title\": \"Van xả lành mạnh\"}, \"rightBox\": {\"title\": \"Van xả độc hại\"}, \"items\": [{\"text\": \"Vận động nhẹ nhàng hoặc đi bộ xung quanh công viên\", \"correctBox\": \"left\"}, {\"text\": \"Ăn thật nhiều đồ ngọt và đồ ăn nhanh để giải tỏa tâm trạng\", \"correctBox\": \"right\"}, {\"text\": \"Tâm sự nỗi lòng với một người bạn thân đáng tin cậy\", \"correctBox\": \"left\"}, {\"text\": \"Trút giận bằng cách quát mắng em nhỏ hoặc đập phá đồ đạc\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1084, 183, 'reflection', '{\"question\": \"Chiếc \'van xả stress\' yêu thích và lành mạnh nhất của bạn lúc này là gì?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1085, 183, 'takeaway', '{\"items\": [\"Chủ động xả áp suất trước khi bộ não của bạn bị \'chập mạch\' vì quá tải.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1086, 184, 'hook', '{\"title\": \"Tại sao hình bóng của một ai đó bỗng dưng lại chiếm sóng toàn bộ tâm trí bạn, khiến bạn vừa vui sướng vừa bồn chồn khó tả?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1087, 184, 'explanation', '{\"bullets\": [\"Rung động đầu đời (Crush) là trải nghiệm sinh lý và cảm xúc cực kỳ mạnh mẽ khi cơ thể sản xuất nhiều dopamine (hormone hạnh phúc).\", \"Bạn có thể mơ mộng về đối phương, đỏ mặt khi chạm mắt, và luôn muốn xuất hiện thật hoàn hảo trước họ.\", \"Đây là bước phát triển cảm xúc hoàn toàn tự nhiên để bạn học cách kết nối sâu sắc hơn với người khác.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1088, 184, 'scenario', '{\"title\": \"Theo dõi thầm lặng\", \"body\": \"Khánh phát hiện mình luôn lén nhìn Vy trong giờ học, tim đập thình thịch mỗi khi Vy đi qua hành lang và liên tục kiểm tra điện thoại xem Vy có đăng story mới không.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1089, 184, 'flashcard', '{\"front\": \"Làm thế nào để tận hưởng cơn \'say nắng\' một cách lành mạnh và không bị ảnh hưởng đến học tập?\", \"back\": \"Chấp nhận cảm xúc bâng khuâng đó, coi nó là động lực học tốt hơn, nhưng đừng để việc theo dõi họ làm bạn bỏ quên các mối quan hệ bạn bè và cuộc sống riêng.\", \"notes\": \"Say nắng giống như ăn một cây kem ngọt ngào, hãy thưởng thức nó chứ đừng để nó làm bạn bị tê buốt răng nhé.\"}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1090, 184, 'reflection', '{\"question\": \"Bạn có đang \'say nắng\' ai đó ở trường hoặc trên mạng lúc này không?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1091, 184, 'takeaway', '{\"items\": [\"Rung động đầu đời là một gia vị ngọt ngào của tuổi trẻ. Hãy trân trọng cảm xúc trong trẻo đó.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1092, 185, 'hook', '{\"title\": \"Làm sao để biết khi nào tình cảm của mình là đơn phương và đối phương chỉ coi mình là một người bạn xã giao?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1093, 185, 'explanation', '{\"bullets\": [\"Tình cảm lành mạnh cần sự tương tác hai chiều và sự hào hứng từ cả hai phía.\", \"Dấu hiệu tình cảm một chiều: Bạn luôn là người chủ động nhắn tin trước, câu trả lời của họ rất ngắn gọn/hờ hững, hoặc họ né tránh các buổi hẹn riêng.\", \"Nhận ra điều này sớm giúp bạn bảo vệ lòng tự trọng và tránh đầu tư quá nhiều kỳ vọng.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1094, 185, 'scenario', '{\"title\": \"Đợi chờ tin nhắn\", \"body\": \"Lan liên tục nhắn tin hỏi han Lâm mỗi ngày. Lâm thường trả lời rất muộn bằng những câu cộc lốc như \'Ừ\', \'Ok\', hoặc thả emoji. Lan tự biện hộ là Lâm đang bận học.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1095, 185, 'interaction', '{\"question\": \"Lan nên hiểu phản hồi của Lâm thế nào cho đúng thực tế?\", \"choices\": [{\"text\": \"Lâm không thực sự hào hứng và quan tâm đến cuộc trò chuyện với Lan. Lan nên dừng việc chủ động nhắn tin liên tục.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Lâm đang thử thách lòng kiên nhẫn của Lan, Lan cần nhắn tin nhiều hơn nữa để Lâm cảm động.\", \"correct\": false, \"emoji\": \"🙁\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1096, 185, 'reflection', '{\"question\": \"Bạn đã từng ở trong một mối quan hệ mà bạn luôn là người phải chủ động cố gắng chưa?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1097, 185, 'takeaway', '{\"items\": [\"Bạn xứng đáng với một tình cảm được đón nhận và trân trọng từ cả hai phía.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1098, 186, 'hook', '{\"title\": \"Tại sao cảm giác bị từ chối tình cảm lại mang đến nỗi đau thể xác thực tế ở lồng ngực như bị ai bóp nghẹt?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1099, 186, 'explanation', '{\"bullets\": [\"Nghiên cứu não bộ cho thấy, sự từ chối kích hoạt cùng một vùng não xử lý nỗi đau thể xác (vùng vỏ não đai trước).\", \"Điều này giải thích tại sao bạn cảm thấy đau nhói ở ngực, hụt hẫng và trống rỗng sau khi bị từ chối.\", \"Nỗi đau này là có thật về mặt sinh học, vì vậy đừng tự trách mình là quá nhạy cảm hay yếu đuối.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1100, 186, 'scenario', '{\"title\": \"Cảm giác hụt hẫng lớn\", \"body\": \"Hoàng bị bạn gái cùng khóa từ chối lời tỏ tình. Cậu cảm thấy lồng ngực mình đau thắt lại, chán ăn, và thấy xấu hổ như thể mình là người tồi tệ nhất thế giới.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1101, 186, 'sorting', '{\"instruction\": \"Phân loại các nhận thức đúng đắn về sự từ chối:\", \"leftBox\": {\"title\": \"Nhìn nhận lành mạnh\"}, \"rightBox\": {\"title\": \"Suy nghĩ tiêu cực\"}, \"items\": [{\"text\": \"Bị từ chối nghĩa là hai người không phù hợp ở thời điểm này\", \"correctBox\": \"left\"}, {\"text\": \"Bị từ chối chứng tỏ mình là kẻ kém cỏi, xấu xí và không ai yêu\", \"correctBox\": \"right\"}, {\"text\": \"Đối phương có quyền tự do lựa chọn tình cảm của họ\", \"correctBox\": \"left\"}, {\"text\": \"Cố gắng bám đuôi hoặc ép buộc họ phải thay đổi ý định\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1102, 186, 'reflection', '{\"question\": \"Nỗi lo sợ bị từ chối có từng ngăn cản bạn bày tỏ suy nghĩ thật của mình với ai đó không?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1103, 186, 'takeaway', '{\"items\": [\"Đau lòng khi bị từ chối là phản ứng sinh học bình thường. Hãy ôm lấy nỗi đau đó và cho nó thời gian lành lại.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1104, 187, 'hook', '{\"title\": \"Làm thế nào để giữ vững phong độ và sự tự tin khi đối phương nói lời từ chối tình cảm của bạn?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1105, 187, 'explanation', '{\"bullets\": [\"Tỏ tình là một hành động dũng cảm thể hiện bạn dám sống thật với cảm xúc của mình.\", \"Từ chối là một phần của cuộc sống, không phải là một bản án định tội giá trị của bạn.\", \"Cách bạn ứng phó với sự từ chối thể hiện mức độ trưởng thành và sự tôn trọng đối phương.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1106, 187, 'scenario', '{\"title\": \"Lời từ chối nhẹ nhàng\", \"body\": \"Tú hẹn Vy ra công viên để tặng quà và tỏ tình. Vy từ chối nhẹ nhàng: \'Tớ chỉ muốn tụi mình là bạn tốt thôi\'. Tú cảm thấy mặt nóng bừng, tai lùng bùng.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1107, 187, 'flashcard', '{\"front\": \"Tú nên ứng xử thế nào để giữ sự văn minh và tôn trọng ranh giới của Vy?\", \"back\": \"Tú có thể hít thở sâu, mỉm cười nhẹ và nói: \'Tớ hiểu rồi. Cảm ơn cậu đã chia sẻ thẳng thắn nhé. Tớ hơi buồn chút nhưng tớ tôn trọng quyết định của cậu\'.\", \"notes\": \"Cách ứng xử đẹp sau khi bị từ chối chính là biểu hiện cao nhất của sự trưởng thành.\"}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1108, 187, 'reflection', '{\"question\": \"Nếu bạn là người phải từ chối tình cảm của ai đó, bạn muốn họ phản ứng như thế nào để cả hai bớt khó xử?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1109, 187, 'takeaway', '{\"items\": [\"Từ chối không làm giảm đi giá trị của bạn. Nó chỉ mở ra hướng đi mới phù hợp hơn.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1110, 188, 'hook', '{\"title\": \"Bạn sẽ làm gì để kéo mình ra khỏi vũng lầy buồn bã và phục hồi lại năng lượng tinh thần sau một cú sốc tình cảm?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1111, 188, 'explanation', '{\"bullets\": [\"Cho phép bản thân buồn và khóc trong vài ngày đầu để giải tỏa bớt áp lực cảm xúc.\", \"Sau đó, hãy chủ động ngắt kết nối: Hạn chế vào trang cá nhân của họ, cất đi những món quà kỷ niệm gây gợi nhớ.\", \"Tập trung vào các mục tiêu cá nhân và dành thời gian bên những người bạn mang lại cho bạn tiếng cười.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1112, 188, 'scenario', '{\"title\": \"Vòng lặp buồn bã\", \"body\": \"Mai sau khi bị crush từ chối liên tục nằm trong phòng khóc lóc, nghe những bài hát thất tình và liên tục check xem cậu ấy đang online hay đi chơi với ai.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1113, 188, 'interaction', '{\"question\": \"Hành động nào giúp Mai \'F5\' lại tâm trạng hiệu quả nhất lúc này?\", \"choices\": [{\"text\": \"Cất những món quà liên quan đến crush, tắt thông báo từ tài khoản của họ và hẹn hội bạn thân đi ăn kem, xem phim.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tiếp tục đăng những status buồn bã, trách móc lên mạng xã hội để mong đối phương đọc được và hối hận.\", \"correct\": false, \"emoji\": \"☹️\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1114, 188, 'reflection', '{\"question\": \"Hoạt động nào thường giúp bạn quên đi nỗi buồn nhanh nhất mỗi khi gặp chuyện thất vọng?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1115, 188, 'takeaway', '{\"items\": [\"Đóng lại một trang sách cũ là cách duy nhất để bạn bắt đầu viết nên những chương mới tươi sáng.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1116, 189, 'hook', '{\"title\": \"Làm sao để nhận ra rằng trải nghiệm bị từ chối thực chất là một bài học đắt giá giúp bạn mạnh mẽ hơn trong tương lai?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1117, 189, 'explanation', '{\"bullets\": [\"Khả năng phục hồi cảm xúc (Resilience) được xây dựng sau mỗi lần bạn đối mặt với thất bại và tự đứng dậy.\", \"Việc bạn dám bày tỏ tình cảm đã là một chiến thắng của lòng dũng cảm.\", \"Bạn nhận ra rằng mình có thể vượt qua nỗi đau lòng và vẫn giữ nguyên giá trị bản thân.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1118, 189, 'scenario', '{\"title\": \"Thời gian chữa lành\", \"body\": \"Ba tháng sau khi bị từ chối, An nhìn lại bức tranh cũ, mỉm cười nhận ra mình không còn cảm thấy nhói lòng nữa. An thấy mình tự tin hơn, học tập tiến bộ và kết giao thêm nhiều bạn mới.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1119, 189, 'sorting', '{\"instruction\": \"Phân loại các bài học rút ra từ trải nghiệm rung động đầu đời:\", \"leftBox\": {\"title\": \"Bài học trưởng thành\"}, \"rightBox\": {\"title\": \"Tiêu cực tự ti\"}, \"items\": [{\"text\": \"Mình biết cách bày tỏ cảm xúc thật của mình một cách dũng cảm\", \"correctBox\": \"left\"}, {\"text\": \"Mình sẽ không bao giờ mở lòng yêu thương hay tin tưởng ai nữa\", \"correctBox\": \"right\"}, {\"text\": \"Mình hiểu rõ hơn về những tiêu chuẩn tình cảm mà mình mong đợi\", \"correctBox\": \"left\"}, {\"text\": \"Ngoại hình mình xấu xí nên chắc chắn cả đời này sẽ bị cô độc\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1120, 189, 'reflection', '{\"question\": \"Bạn có tự hào về lòng dũng cảm của mình sau những lần đối mặt với thử thách cảm xúc đã qua không?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1121, 189, 'takeaway', '{\"items\": [\"Những vết xước cảm xúc hôm nay chính là chất liệu tạo nên sự kiên cường của bạn ngày mai.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1122, 190, 'hook', '{\"title\": \"Bạn có bao giờ tự hỏi điều gì làm nên một tình bạn giúp bạn luôn thấy an tâm, được là chính mình thay vì phải gồng mình diễn?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1123, 190, 'explanation', '{\"bullets\": [\"Tình bạn lành mạnh (Green Flag) được xây dựng trên sự tôn trọng, lòng tin và sự bình đẳng.\", \"Bạn bè \'Green Flag\' sẽ lắng nghe không phán xét, ủng hộ ước mơ của bạn, và tôn trọng những quyết định cá nhân (ranh giới) của bạn.\", \"Họ vui mừng khi thấy bạn thành công chứ không có sự ghen tị ngầm hay nói xấu sau lưng.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1124, 190, 'scenario', '{\"title\": \"Ủng hộ ước mơ\", \"body\": \"Khi Vy chia sẻ rằng mình muốn tham gia câu lạc bộ kịch, Hà hào hứng ủng hộ: \'Cậu đóng kịch hợp lắm đó, để tớ đi xem cậu diễn thử nhé!\'. Vy cảm thấy rất ấm áp.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1125, 190, 'flashcard', '{\"front\": \"Những dấu hiệu cơ bản của một người bạn \'Green Flag\' trong giao tiếp hàng ngày là gì?\", \"back\": \"Họ giữ bí mật của bạn, biết nói lời xin lỗi khi làm bạn buồn, không ép bạn làm điều bạn ghét, và luôn sẵn sàng hỗ trợ khi bạn gặp khó khăn.\", \"notes\": \"Một người bạn tốt giống như một làn gió mát nâng đỡ bạn bay cao hơn.\"}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1126, 190, 'reflection', '{\"question\": \"Người bạn thân nhất của bạn đã từng làm điều gì khiến bạn cảm thấy được tôn trọng và yêu quý nhất?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1127, 190, 'takeaway', '{\"items\": [\"Tình bạn đích thực là nơi bạn được cởi bỏ mọi chiếc mặt nạ để sống chân thật nhất.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1128, 191, 'hook', '{\"title\": \"Có bao giờ bạn thấy mình luôn là người phải xin lỗi và cảm thấy tội lỗi trong các cuộc tranh cãi dù mình không làm gì sai?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1129, 191, 'explanation', '{\"bullets\": [\"Thao túng cảm xúc (như Gaslighting) là hành vi làm bạn nghi ngờ chính suy nghĩ, cảm xúc và trí nhớ của bản thân.\", \"Kẻ thao túng thường đổ lỗi ngược lại cho bạn: \'Cậu nhạy cảm quá rồi đấy\', \'Vì cậu nên tớ mới phải làm thế\', hoặc dùng chiến tranh lạnh im lặng để trừng phạt bạn.\", \"Nhận diện sớm cờ đỏ này để bảo vệ sức khỏe tinh thần của bản thân.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1130, 191, 'scenario', '{\"title\": \"Viện cớ kiểm soát\", \"body\": \"Lâm tự ý đọc tin nhắn điện thoại của Lan. Khi Lan phản đối, Lâm nổi giận quát: \'Vì tớ yêu cậu nên tớ mới xem chứ! Cậu có gì giấu giếm tớ đúng không?\'. Lan thấy bối rối và tự trách mình vì đã làm Lâm giận.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1131, 191, 'interaction', '{\"question\": \"Lâm đang có hành vi gì đối với Lan trong tình huống trên?\", \"choices\": [{\"text\": \"Thao túng cảm xúc và vi phạm ranh giới riêng tư của Lan dưới danh nghĩa tình yêu.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Thể hiện tình yêu thương chân thành và sự quan tâm sâu sắc đến đối phương.\", \"correct\": false, \"emoji\": \"☹️\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1132, 191, 'reflection', '{\"question\": \"Bạn có từng nghe ai nói câu: \'Nếu thực sự coi tớ là bạn, cậu phải làm việc này...\' chưa?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1133, 191, 'takeaway', '{\"items\": [\"Yêu thương không bao giờ đi kèm với sự kiểm soát và làm bạn cảm thấy tội lỗi vì đã đặt ranh giới.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(1134, 192, 'hook', '{\"title\": \"Tại sao việc mở lời tâm sự với ai đó về những lo âu, tổn thương của bản thân lại khó khăn hơn việc chia sẻ niềm vui rất nhiều?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1135, 192, 'explanation', '{\"bullets\": [\"Chia sẻ tổn thương (Vulnerability) khiến ta cảm thấy như đang cởi bỏ áo giáp, lo sợ bị đánh giá, từ chối hoặc coi là yếu đuối.\", \"Tuy nhiên, sự tổn thương chính là chiếc cầu nối mạnh mẽ nhất để xây dựng lòng tin và sự thấu cảm sâu sắc giữa người với người.\", \"Chọn lựa đối tượng đáng tin cậy để mở lòng là bước đi dũng cảm và cần thiết.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1136, 192, 'scenario', '{\"title\": \"Ngại ngùng chia sẻ\", \"body\": \"Khải gặp chuyện buồn trong gia đình. Cậu rất muốn tâm sự với bạn thân nhưng lại ngập ngừng sợ bạn sẽ nghĩ mình phiền phức, yếu đuối, nên lại thôi và giả vờ như không có chuyện gì.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1137, 192, 'sorting', '{\"instruction\": \"Phân loại các phản ứng khi bạn bè chia sẻ câu chuyện buồn thầm kín:\", \"leftBox\": {\"title\": \"Thấu cảm lắng nghe\"}, \"rightBox\": {\"title\": \"Phán xét gạt đi\"}, \"items\": [{\"text\": \"Tớ luôn ở đây sẵn sàng nghe cậu kể khi cậu thấy thoải mái nhé\", \"correctBox\": \"left\"}, {\"text\": \"Ối dào, chuyện nhỏ nhặt thế có gì đâu mà phải buồn!\", \"correctBox\": \"right\"}, {\"text\": \"Im lặng ngồi bên cạnh và ôm nhẹ để bạn biết bạn không cô đơn\", \"correctBox\": \"left\"}, {\"text\": \"Chuyển chủ đề trò chuyện sang kể về những chuyện vui của mình\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1138, 192, 'reflection', '{\"question\": \"Ai là người bạn cảm thấy an toàn nhất để khóc hoặc chia sẻ những bí mật thầm kín?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1139, 192, 'takeaway', '{\"items\": [\"Chia sẻ tổn thương không phải là yếu đuối. Đó là lòng dũng cảm để kết nối chân thật.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1140, 193, 'hook', '{\"title\": \"Bạn sẽ làm gì khi nhận ra người bạn thân lâu năm dạo gần đây bắt đầu nói xấu sau lưng và cô lập bạn khỏi tập thể?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1141, 193, 'explanation', '{\"bullets\": [\"Không phải mọi tình bạn đều kéo dài mãi mãi. Mọi người thay đổi và các mối quan hệ cũng có hạn sử dụng.\", \"Các cờ đỏ (Red Flag) trong tình bạn: Thường xuyên chê bai bạn, tiết lộ bí mật của bạn cho người khác, hoặc chỉ tìm đến bạn khi cần nhờ vả.\", \"Chấp nhận buông bỏ một tình bạn độc hại là cách bạn tự bảo vệ sự bình yên của bản thân.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1142, 193, 'scenario', '{\"title\": \"Nhóm chat nói xấu\", \"body\": \"Vy phát hiện nhóm chat riêng của hội bạn thân dạo này thường xuyên chụp ảnh dìm và nói xấu Vy một cách công khai. Khi Vy hỏi, họ bảo: \'Đùa tí cho vui thôi mà, làm gì căng thế!\'.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1143, 193, 'flashcard', '{\"front\": \"Vy nên làm gì để xử lý tình huống tình bạn độc hại này một cách dũng cảm nhất?\", \"back\": \"Thiết lập khoảng cách với nhóm bạn đó, ngừng chia sẻ thông tin cá nhân và tìm kiếm những người bạn mới tôn trọng mình hơn.\", \"notes\": \"Đùa chỉ vui khi tất cả mọi người cùng cười, nếu có một người đau lòng thì đó là bắt nạt cảm xúc.\"}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1144, 193, 'reflection', '{\"question\": \"Bạn đã từng phải đưa ra quyết định dừng chơi với một người bạn chưa?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1145, 193, 'takeaway', '{\"items\": [\"Bạn thà có một người bạn chân thành còn hơn có một nhóm bạn luôn khiến bạn thấy bất an.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1146, 194, 'hook', '{\"title\": \"Bạn có biết khi những rắc rối cảm xúc vượt quá khả năng tự giải quyết, ai sẽ là người sẵn sàng lắng nghe và nâng đỡ bạn không?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1147, 194, 'explanation', '{\"bullets\": [\"Giữ mọi gánh nặng tinh thần một mình dễ dẫn đến kiệt sức và các vấn đề tâm lý nghiêm trọng.\", \"Tìm kiếm hỗ trợ (Seeking support) là biểu hiện của sự thông thái và tự bảo vệ bản thân.\", \"Đồng minh đáng tin cậy: Bố mẹ, thầy cô y tế học đường, chuyên gia tâm lý, hoặc các tổng đài hỗ trợ trẻ em quốc gia (như Tổng đài 111).\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1148, 194, 'scenario', '{\"title\": \"Bắt nạt qua mạng\", \"body\": \"Nguyên bị một nhóm bạn trên mạng liên tục gửi tin nhắn đe dọa, xúc phạm danh dự. Cậu vô cùng hoảng sợ, không thể tập trung học tập, bị sụt cân và có những suy nghĩ tự hại mình.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1149, 194, 'interaction', '{\"question\": \"Nguyên nên thực hiện hành động khẩn cấp nào lúc này để tự bảo vệ mình?\", \"choices\": [{\"text\": \"Chụp lại bằng chứng tin nhắn, báo ngay cho bố mẹ hoặc thầy cô giáo tin cậy và liên hệ tổng đài 111 để được tư vấn bảo vệ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Im lặng tự chịu đựng, cố gắng thương lượng thỏa hiệp với nhóm bắt nạt mạng đó.\", \"correct\": false, \"emoji\": \"☹️\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1150, 194, 'reflection', '{\"question\": \"Bạn đã lưu số điện thoại khẩn cấp hoặc biết cách liên hệ với phòng tư vấn tâm lý trường mình chưa?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1151, 194, 'takeaway', '{\"items\": [\"Tìm kiếm sự giúp đỡ không phải là đầu hàng. Đó là cách bạn chọn để chiến thắng khó khăn.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1152, 195, 'hook', '{\"title\": \"Làm thế nào để tạo ra một môi trường xung quanh toàn những mối quan hệ tích cực nâng đỡ tinh thần bạn mỗi ngày?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1153, 195, 'explanation', '{\"bullets\": [\"Mạng lưới hỗ trợ (Support network) giống như một tấm đệm an toàn giúp bạn giảm chấn thương khi bị ngã trong cuộc sống.\", \"Chủ động nuôi dưỡng tình bạn tốt bằng cách lắng nghe và giúp đỡ họ trước.\", \"Đặt ra ranh giới rõ ràng với những mối quan hệ độc hại để dành không gian cho những người thực sự trân trọng bạn.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1154, 195, 'scenario', '{\"title\": \"Môi trường kết nối mới\", \"body\": \"Sau khi cắt đứt liên lạc với nhóm bạn xấu, Minh bắt đầu tham gia câu lạc bộ ghi-ta, quen được những người bạn vui vẻ, cùng tập đàn và động viên nhau học tập.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1155, 195, 'sorting', '{\"instruction\": \"Phân loại các hành động để xây dựng mạng lưới hỗ trợ an toàn:\", \"leftBox\": {\"title\": \"Nuôi dưỡng kết nối tốt\"}, \"rightBox\": {\"title\": \"Dung dưỡng độc hại\"}, \"items\": [{\"text\": \"Chủ động nhắn tin hỏi han khi thấy bạn mình có vẻ buồn bã\", \"correctBox\": \"left\"}, {\"text\": \"Chấp nhận những lời xúc phạm của bạn bè vì sợ bị cô đơn\", \"correctBox\": \"right\"}, {\"text\": \"Cùng bạn lập nhóm học tập tiến bộ, chia sẻ tài liệu hay\", \"correctBox\": \"left\"}, {\"text\": \"Bỏ qua các cảnh báo bất an trong lòng để cố hòa nhập nhóm xấu\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1156, 195, 'reflection', '{\"question\": \"Ai là những cái tên đầu tiên bạn sẽ đưa vào danh sách \'Biệt đội giải cứu cảm xúc\' của mình?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1157, 195, 'takeaway', '{\"items\": [\"Được bao quanh bởi những người tử tế là liều thuốc chữa lành tốt nhất cho tâm hồn.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1158, 196, 'hook', '{\"title\": \"Có phải tự chăm sóc bản thân chỉ đơn giản là đi mua sắm những món đồ đắt tiền, ăn uống sang chảnh hay đắp mặt nạ dưỡng da?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1159, 196, 'explanation', '{\"bullets\": [\"Tự chăm sóc (Self-care) thực chất là những thói quen nhỏ hàng ngày giúp bảo vệ sức khỏe thể chất và tinh thần của bạn.\", \"Nó bao gồm việc uống đủ nước, ngủ đủ giấc, ăn uống đủ chất, và cho phép bản thân nghỉ ngơi khi quá tải.\", \"Đôi khi, tự chăm sóc chỉ đơn giản là tắt điện thoại đi ngủ sớm sau một ngày mệt mỏi.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1160, 196, 'scenario', '{\"title\": \"Hiểu lầm về self-care\", \"body\": \"Lan nghĩ rằng self-care là phải đi spa và mua trà sữa uống mỗi ngày. Nhưng cô bạn vẫn thức khuya đến 2h sáng lướt điện thoại và luôn đi học muộn với gương mặt phờ phạc.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1161, 196, 'flashcard', '{\"front\": \"Thế nào là một hành động tự chăm sóc bản thân thực sự lành mạnh và hiệu quả?\", \"back\": \"Những hành động giúp cơ thể và tâm trí bạn khỏe mạnh lâu dài: Ngủ đúng giờ, ăn sáng đầy đủ, tập thể thao vừa sức, và đặt ranh giới bảo vệ cảm xúc.\", \"notes\": \"Self-care không phải là trốn chạy thực tại, mà là chuẩn bị năng lượng tốt nhất để đối mặt với thực tại.\"}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1162, 196, 'reflection', '{\"question\": \"Hành động tự chăm sóc bản thân đơn giản nhất bạn có thể làm ngay tối hôm nay là gì?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1163, 196, 'takeaway', '{\"items\": [\"Yêu bản thân bắt đầu từ những thói quen nhỏ nhất chăm sóc cơ thể sinh học của mình.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1164, 197, 'hook', '{\"title\": \"Làm thế nào để tạo ra một danh sách những việc siêu đơn giản có thể giúp bạn lấy lại nụ cười chỉ trong vài phút?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1165, 197, 'explanation', '{\"bullets\": [\"Chiếc \'menu sạc pin\' (Self-care menu) chứa các hoạt động nhỏ giúp kích hoạt các hormone tích cực (dopamine, serotonin).\", \"Hãy chuẩn bị sẵn các lựa chọn phù hợp với thời gian bạn có: 5 phút, 15 phút hay 1 tiếng.\", \"Đây sẽ là chiếc phao cứu sinh đắc lực mỗi khi bạn cảm thấy kiệt sức hoặc buồn chán.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1166, 197, 'scenario', '{\"title\": \"Tưới cây thư giãn\", \"body\": \"Khánh cảm thấy rất mệt mỏi sau tiết học căng thẳng. Cậu xem chiếc menu tự chế của mình và chọn hoạt động 5 phút: Ra ban công tưới cây và vươn vai hít thở sâu.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1167, 197, 'interaction', '{\"question\": \"Hoạt động nào dưới đây phù hợp nhất để đưa vào danh mục \'sạc pin nhanh 5 phút\'?\", \"choices\": [{\"text\": \"Vươn vai kéo giãn cơ thể, uống một cốc nước mát và hít thở sâu ngoài cửa sổ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Xem trọn vẹn một bộ phim điện ảnh dài tập trên điện thoại.\", \"correct\": false, \"emoji\": \"☹️\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1168, 197, 'reflection', '{\"question\": \"Nếu tự làm một chiếc menu sạc pin cho mình, bạn sẽ viết những hoạt động nào vào đó?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1169, 197, 'takeaway', '{\"items\": [\"Chuẩn bị sẵn năng lượng tích cực để chủ động cứu hộ bản thân khi cần.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1170, 198, 'hook', '{\"title\": \"Bạn có bao giờ cảm thấy cắn rứt, tội lỗi khi dành cả một buổi chiều chủ nhật chỉ để nằm lười biếng mà không học tập hay làm việc gì không?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1171, 198, 'explanation', '{\"bullets\": [\"Xã hội hiện đại luôn đề cao sự bận rộn (hustle culture), khiến chúng ta nghĩ rằng lúc nào cũng phải làm việc mới có giá trị.\", \"Nghỉ ngơi tích cực (Rest) không phải là lãng phí thời gian, nó là bước đệm cần thiết để các tế bào thần kinh tái tạo.\", \"Bạn không cần phải \'kiếm tìm\' hay \'xứng đáng\' mới được quyền nghỉ ngơi; đó là nhu cầu sinh học tối thiểu.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1172, 198, 'scenario', '{\"title\": \"Áy náy khi giải trí\", \"body\": \"Mai cảm thấy vô cùng áy náy và lo lắng khi dành ngày nghỉ để xem phim. Cô bạn liên tục nhìn đống sách vở, thấy có lỗi với bố mẹ và không thể tận hưởng trọn vẹn bộ phim.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1173, 198, 'sorting', '{\"instruction\": \"Phân loại các suy nghĩ về việc nghỉ ngơi giải lao:\", \"leftBox\": {\"title\": \"Nghỉ ngơi không tội lỗi\"}, \"rightBox\": {\"title\": \"Áy náy ép buộc\"}, \"items\": [{\"text\": \"Cho phép bản thân ngủ nướng một chút vào ngày cuối tuần để phục hồi\", \"correctBox\": \"left\"}, {\"text\": \"Vừa nằm nghỉ vừa tự trách mình lười biếng và thua kém bạn bè\", \"correctBox\": \"right\"}, {\"text\": \"Tự nhủ: Cơ thể mình đã vất vả cả tuần và xứng đáng được thư giãn\", \"correctBox\": \"left\"}, {\"text\": \"Cố học tiếp dù đầu đang đau nhức vì sợ bị điểm kém\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1174, 198, 'reflection', '{\"question\": \"Bạn có thường cảm thấy tội lỗi khi cho phép bản thân nghỉ ngơi không?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1175, 198, 'takeaway', '{\"items\": [\"Nghỉ ngơi là để tái tạo, không phải là sự lười biếng cần phải trừng phạt.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1176, 199, 'hook', '{\"title\": \"Tại sao việc từ chối lời nhờ vả của bạn bè lại khó khăn đến thế, ngay cả khi bạn đang vô cùng bận rộn và kiệt sức?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1177, 199, 'explanation', '{\"bullets\": [\"Hội chứng \'người tốt làm hài lòng tất cả\' (People-pleaser) bắt nguồn từ nỗi sợ bị ghét bỏ hoặc tẩy chay.\", \"Khi bạn luôn nói \'Có\' với yêu cầu của người khác, bạn đang gián tiếp nói \'Không\' với sự bình yên và sức khỏe của chính mình.\", \"Thiết lập ranh giới lịch sự giúp bạn bảo vệ năng lượng cá nhân và giữ gìn các mối quan hệ bền vững hơn.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1178, 199, 'scenario', '{\"title\": \"Không dám từ chối\", \"body\": \"Hải đang ngập đầu trong đống bài tập cần nộp. Tuy nhiên, khi một bạn trong lớp nhờ Hải làm hộ slide thuyết trình nhóm của bạn ấy, Hải không dám từ chối vì sợ bạn sẽ giận.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1179, 199, 'flashcard', '{\"front\": \"Hải nên từ chối lời nhờ vả của bạn thế nào để vừa lịch sự vừa giữ được ranh giới?\", \"back\": \"Hải có thể nói: \'Tớ rất muốn giúp nhưng tối nay tớ cũng có bài tập lớn cần hoàn thành gấp rồi. Để dịp khác nha cậu!\'.\", \"notes\": \"Người thực sự trân trọng bạn sẽ hiểu và tôn trọng lời từ chối của bạn.\"}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1180, 199, 'reflection', '{\"question\": \"Gần đây nhất bạn đã nói \'Có\' với ai đó trong khi lòng bạn đang vô cùng muốn từ chối là khi nào?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1181, 199, 'takeaway', '{\"items\": [\"Bạn không cần phải làm hài lòng tất cả mọi người bằng cách bỏ qua cảm xúc của chính mình.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1182, 200, 'hook', '{\"title\": \"Làm thế nào để nói lời từ chối một cách kiên định mà không gây cảm giác cộc lốc, thô lộ với người đối diện?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1183, 200, 'explanation', '{\"bullets\": [\"Từ chối lịch sự (Polite refusal) cần sự rõ ràng, dứt khoát và đi kèm một lời giải thích ngắn gọn (không cần phải dông dài bao biến).\", \"Sử dụng cấu trúc: Lời cảm ơn/ghi nhận -> Lời từ chối rõ ràng -> Đề xuất thay thế (nếu muốn).\", \"Thực hành nói \'Không\' giúp bạn tăng sự tự tin và lòng tự trọng lên rất nhiều.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1184, 200, 'scenario', '{\"title\": \"Lời rủ rê tối muộn\", \"body\": \"Hội bạn thân rủ Trang đi trà sữa vào tối muộn trước ngày thi. Trang cảm thấy mệt mỏi và muốn đi ngủ sớm để giữ sức nhưng chưa biết từ chối sao cho khéo.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1185, 200, 'interaction', '{\"question\": \"Trang nên nhắn tin từ chối nhóm bạn thế nào cho tự nhiên, Gen Z?\", \"choices\": [{\"text\": \"\'Thèm đi cùng các cậu quá nhưng tối nay tớ muốn đi ngủ sớm dưỡng sức thi mai. Chúc cả hội đi chơi vui vẻ, mai thi xong tụi mình bù nha!\'\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Im lặng không trả lời tin nhắn của nhóm, hôm sau đi thi giả vờ bị mất điện thoại.\", \"correct\": false, \"emoji\": \"☹️\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1186, 200, 'reflection', '{\"question\": \"Bạn thấy việc nói lời từ chối với bố mẹ, bạn bè hay thầy cô là khó khăn nhất?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1187, 200, 'takeaway', '{\"items\": [\"Nói \'Không\' với điều không phù hợp là cách bạn nói \'Có\' với sức khỏe tinh thần của chính mình.\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1188, 201, 'hook', '{\"title\": \"Bạn có tin rằng việc thay đổi những thói quen siêu nhỏ mỗi ngày có thể tạo nên bước ngoặt lớn cho sự phát triển của bạn sau một năm không?\"}', 1, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1189, 201, 'explanation', '{\"bullets\": [\"Phát triển bản thân (Personal growth) không phải là sự thay đổi chấn động qua một đêm, mà là sự kiên trì tích lũy.\", \"Thiết lập các mục tiêu siêu nhỏ dễ đạt được (như đọc 2 trang sách, uống thêm 1 cốc nước, ngủ sớm hơn 10 phút).\", \"Tự thưởng cho bản thân mỗi khi hoàn thành thói quen nhỏ để tạo động lực tiếp tục hành trình lớn lên đầy tự hào.\"]}', 2, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1190, 201, 'scenario', '{\"title\": \"Duy trì giấc ngủ ngon\", \"body\": \"Khải quyết định cải thiện sức khỏe bằng cách đi ngủ lúc 11h thay vì 12h đêm. Sau một tháng, cậu nhận thấy mình tỉnh táo hơn trong giờ học, da mặt bớt mụn và tinh thần luôn vui tươi.\"}', 3, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1191, 201, 'sorting', '{\"instruction\": \"Phân loại các mục tiêu thói quen thiết lập hàng ngày:\", \"leftBox\": {\"title\": \"Mục tiêu nhỏ khả thi\"}, \"rightBox\": {\"title\": \"Mục tiêu quá tải\"}, \"items\": [{\"text\": \"Đọc 2 trang sách trước khi đi ngủ mỗi tối\", \"correctBox\": \"left\"}, {\"text\": \"Ép bản thân phải học liên tục 10 tiếng không nghỉ\", \"correctBox\": \"right\"}, {\"text\": \"Tập thể dục nhẹ nhàng 10 phút sau khi thức dậy\", \"correctBox\": \"left\"}, {\"text\": \"Thay đổi toàn bộ chế độ ăn kiêng hà khắc ngay lập tức\", \"correctBox\": \"right\"}]}', 4, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1192, 201, 'reflection', '{\"question\": \"Một thói quen nhỏ, tích cực nào bạn muốn bắt đầu thiết lập ngay từ ngày mai?\"}', 5, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1193, 201, 'takeaway', '{\"items\": [\"Những bước đi nhỏ mỗi ngày sẽ đưa bạn đi được một hành trình rất xa. Hãy kiên trì nhé!\"]}', 6, '2026-06-05 15:00:15', '2026-06-05 15:00:15'),
(1204, 204, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Luật đi đường - Đồng thuận là gì?\'! Bạn có 3 mạng để vượt qua 5 thử thách cam go. Hãy sẵn sàng nhé.\"}', 1, '2026-06-11 17:03:47', '2026-06-11 17:03:47'),
(1205, 204, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Hỏi xin sự đồng thuận\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Bạn đang xem phim tại rạp cùng bạn gái mới quen. Phim đến đoạn cao trào, bạn muốn đan tay vào tay bạn ấy. Bạn ấy đang tập trung cao độ vào màn hình, hai tay ôm hộp bắp rang bơ đặt trên đùi.\",\r\n      \"choices\": [\r\n        { \"text\": \"Cứ luồn tay vào hộp bắp để chạm tay bạn ấy rồi nắm lấy, vừa tự nhiên vừa lãng mạn.\", \"nextNode\": \"fail_surprise\" },\r\n        { \"text\": \"Nói khẽ bên tai: \'Tớ nắm tay cậu được không?\'\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Chờ phim hết rồi đột ngột nắm tay khi đang đi ra.\", \"nextNode\": \"fail_passive\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Bạn ấy đỏ mặt, mỉm cười nhẹ rồi nói: \'Nắm tay thì được nè, nhưng đừng đan ngón tay chặt quá nha, tay tớ đang bị ra mồ hôi và hơi nóng\'.\",\r\n      \"choices\": [\r\n        { \"text\": \"Nghe vậy thấy cụt hứng, buông tay ra và quay đi chỗ khác: \'Thôi thế thì thôi vậy\'.\", \"nextNode\": \"fail_anger\" },\r\n        { \"text\": \"Cười nhẹ: \'Ok cậu nè!\', nắm tay nhẹ nhàng, tôn trọng yêu cầu cụ thể của bạn ấy.\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Một lát sau, bạn ấy thấy mỏi tay và khẽ rút tay ra để cầm ly nước ngọt.\",\r\n      \"choices\": [\r\n        { \"text\": \"Nắm giữ chặt lại: \'Ơ đang nắm tay vui mà, sao lại rút ra?\'\", \"nextNode\": \"fail_reversible\" },\r\n        { \"text\": \"Nới lỏng tay để bạn ấy rút ra thoải mái: \'Cậu uống nước đi nè!\'.\", \"nextNode\": \"success_end\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Hoàn toàn chính xác! Bạn đã áp dụng quy tắc F.R.I.E.S cực tốt: tôn trọng sự linh hoạt (Reversible) và tính cụ thể (Specific) của sự đồng thuận.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_surprise\": {\r\n      \"text\": \"❌ Chưa đúng rồi! Việc đụng chạm bất ngờ mà không hỏi trước có thể làm đối phương giật mình hoặc khó chịu, vi phạm ranh giới cá nhân.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_passive\": {\r\n      \"text\": \"❌ Chưa đúng. Trong mối quan hệ lành mạnh, tụi mình nên chủ động hỏi ý kiến trước khi đụng chạm cơ thể thay vì im lặng làm càn.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_anger\": {\r\n      \"text\": \"❌ Sai rồi! Giận dỗi khi đối phương thiết lập ranh giới cụ thể là hành vi thao túng cảm xúc, thiếu tôn trọng quyền tự quyết của họ.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_reversible\": {\r\n      \"text\": \"❌ Chưa chính xác. Sự đồng thuận có tính linh hoạt (Reversible) - bất cứ ai cũng có quyền rút lại lời đồng ý bất kỳ lúc nào và bạn phải tôn trọng điều đó.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 17:03:47', '2026-06-11 17:03:47'),
(1206, 204, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại các hành vi sau:\",\r\n  \"leftBox\": { \"title\": \"Lành mạnh (Green Flag)\" },\r\n  \"rightBox\": { \"title\": \"Độc hại (Red Flag)\" },\r\n  \"items\": [\r\n    { \"text\": \"Đồng ý vì nể sợ người yêu giận dỗi\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Tự nguyện đồng ý nắm tay nhưng từ chối ôm má\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Gật đầu làm theo lời dụ dỗ ngọt ngào khi đang say sưa\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Hào hứng đồng ý đi chơi xa và chuẩn bị kỹ lưỡng\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Im lặng cúi đầu chịu đựng khi đối phương bá vai\", \"correctBox\": \"right\" }\r\n  ]\r\n}', 3, '2026-06-11 17:03:47', '2026-06-11 17:03:47'),
(1207, 204, 'matching', '{\r\n  \"instruction\": \"Ghép cặp từ khóa ranh giới và định nghĩa quy tắc F.R.I.E.S sau:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Tự nguyện (Freely given)\", \"right\": \"Đồng ý không có sự ép buộc, nài nỉ hay lo sợ bị giận dỗi.\" },\r\n    { \"left\": \"Linh hoạt (Reversible)\", \"right\": \"Có quyền đổi ý và rút lại quyết định bất cứ lúc nào.\" },\r\n    { \"left\": \"Đầy đủ thông tin (Informed)\", \"right\": \"Biết rõ bản chất hành động, không bị lừa dối hay giấu giếm.\" },\r\n    { \"left\": \"Cụ thể (Specific)\", \"right\": \"Đồng ý cho việc này không đồng nghĩa với việc khác.\" }\r\n  ]\r\n}', 4, '2026-06-11 17:03:47', '2026-06-11 17:03:47'),
(1208, 204, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành định nghĩa ranh giới:\",\r\n  \"sentence\": \"Một lời [blank1] thực sự phải dựa trên sự [blank2] của bản thân, không bị áp lực [blank3] hay dụ dỗ, và có thể thay đổi bất cứ [blank4] nào.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"đồng ý\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"tự nguyện\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"ép buộc\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"lúc\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"đồng ý\", \"tự nguyện\", \"ép buộc\", \"lúc\", \"im lặng\", \"nể nang\", \"ngượng ngùng\", \"đèn đỏ\"]\r\n}', 5, '2026-06-11 17:03:47', '2026-06-11 17:03:47'),
(1209, 204, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Khi đối phương đã đồng ý ôm bạn lúc trước, nhưng sau đó đẩy nhẹ bạn ra và nói \'Tớ thấy hơi nhanh\', phản ứng nào sau đây thể hiện sự tôn trọng ranh giới tốt nhất?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Hờn dỗi: \'Nãy cậu đồng ý rồi mà giờ lại thay đổi à?\'\", \"correct\": false, \"emoji\": \"🙁\" },\r\n    { \"text\": \"Nói đùa: \'Làm gì mà căng thế, ôm tí thôi mà!\'\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Dừng lại ngay, nới lỏng tay và nhẹ nhàng hỏi han cảm nhận của đối phương.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Cứ ôm chặt thêm vài giây rồi mới buông ra.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 17:03:47', '2026-06-11 17:03:47'),
(1210, 205, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Lắc đầu không sao cả\'! Bạn có 3 mạng để vượt qua 5 thử thách thử lòng kiên cường. Sẵn sàng chưa?\"}', 1, '2026-06-11 17:12:12', '2026-06-11 17:12:12'),
(1211, 205, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Đối thoại ranh giới và ứng phó từ chối\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Bạn rủ bạn cùng lớp đi hiệu sách mua tài liệu học tập cuối tuần này. Bạn ấy ngập ngừng từ chối: \'Xin lỗi cậu nha, cuối tuần này tớ bận học thêm và dọn dẹp nhà cửa mất rồi\'. Cảm giác ngượng ngùng dâng lên trong lòng bạn.\",\r\n      \"choices\": [\r\n        { \"text\": \"Tự suy diễn: \'Chắc bạn ấy ghét mình nên mới lấy cớ từ chối\'. Quyết định không bao giờ nói chuyện nữa.\", \"nextNode\": \"fail_low_self_esteem\" },\r\n        { \"text\": \"Nài nỉ thêm: \'Học thêm tí thôi mà, đi hiệu sách nhanh lắm, đi với tớ đi!\'\", \"nextNode\": \"fail_pester\" },\r\n        { \"text\": \"Phản hồi lịch sự: \'Ok cậu nè, học tập và dọn dẹp vui vẻ nha! Hôm khác tụi mình đi cũng được\'.\", \"nextNode\": \"step2\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Thứ Hai đi học, bạn thấy bạn ấy đang cười nói vui vẻ với một nhóm bạn khác. Cơn ghen tị và hụt hẫng nhen nhóm.\",\r\n      \"choices\": [\r\n        { \"text\": \"Đến chen vào và nói mỉa mai: \'Bận dọn nhà mà nay rảnh rỗi buôn chuyện thế nhờ?\'\", \"nextNode\": \"fail_sarcasm\" },\r\n        { \"text\": \"Cư xử bình thường, chủ động chào hỏi vui vẻ và tập trung vào việc học của mình.\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Cuối tuần sau, bạn ấy chủ động nhắn tin rủ bạn đi thư viện tự học chung.\",\r\n      \"choices\": [\r\n        { \"text\": \"Từ chối thẳng thừng để trả đũa: \'Hôm trước bận thì hôm nay tớ cũng bận nhé!\'\", \"nextNode\": \"fail_revenge\" },\r\n        { \"text\": \"Vui vẻ nhận lời: \'Ý tưởng hay đó, hẹn cậu thứ Bảy ở thư viện nha!\'\", \"nextNode\": \"success_end\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Hoàn toàn chính xác! Bạn đã đặt ranh giới cá nhân một cách dứt khoát nhưng vẫn lịch sự, mềm mỏng và giữ vững lập trường của mình.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_low_self_esteem\": {\r\n      \"text\": \"❌ Chưa đúng rồi! Tự suy diễn tiêu cực chỉ làm bản thân tổn thương và xa lánh mối quan hệ, trong khi lý do từ chối thường nằm ở hoàn cảnh của họ.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_pester\": {\r\n      \"text\": \"❌ Sai rồi! Nài nỉ, ép buộc đối phương nhượng bộ khi họ đã từ chối là hành vi thiếu tôn trọng ranh giới của họ.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_sarcasm\": {\r\n      \"text\": \"❌ Chưa đúng. Lời nói mỉa mai thể hiện sự thiếu chín chắn và làm rạn nứt tình cảm bạn bè một cách không đáng có.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_revenge\": {\r\n      \"text\": \"❌ Sai rồi! Hành vi trả đũa trẻ con không giúp xây dựng tình bạn lành mạnh mà chỉ làm tăng thêm khoảng cách.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 17:12:12', '2026-06-11 17:12:12'),
(1212, 205, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại suy nghĩ sau khi bị từ chối:\",\r\n  \"leftBox\": { \"title\": \"Thực tế & Lành mạnh\" },\r\n  \"rightBox\": { \"title\": \"Tự ti & Suy diễn\" },\r\n  \"items\": [\r\n    { \"text\": \"Bạn ấy từ chối vì không muốn đi chơi với mình hôm nay\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Chắc chắn mình là kẻ thất bại, xấu xí và không ai thích\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Có thể bạn ấy thực sự bận hoặc mệt mỏi vào lúc đó\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Mình không bao giờ nên mở lời mời bất kỳ ai nữa\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Ranh giới của người khác cần được tôn trọng tuyệt đối\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 17:12:12', '2026-06-11 17:12:12'),
(1213, 205, 'matching', '{\r\n  \"instruction\": \"Ghép cặp từ khóa ranh giới và cách ứng xử sau:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Sự bền bỉ (Resilience)\", \"right\": \"Khả năng tự hồi phục sau hụt hẫng và thất vọng.\" },\r\n    { \"left\": \"Tự chủ cảm xúc\", \"right\": \"Không đổ lỗi cho bản thân hay giận dỗi đối phương.\" },\r\n    { \"left\": \"Ranh giới cá nhân\", \"right\": \"Giới hạn giúp bảo vệ không gian riêng tư của mỗi người.\" },\r\n    { \"left\": \"Từ chối lịch sự\", \"right\": \"Đưa ra lời từ chối rõ ràng kèm thái độ nhẹ nhàng, tôn trọng.\" }\r\n  ]\r\n}', 4, '2026-06-11 17:12:12', '2026-06-11 17:12:12'),
(1214, 205, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành triết lý kiên cường:\",\r\n  \"sentence\": \"Khi bị từ chối, việc [blank1] ranh giới của người khác và giữ thái độ [blank2] giúp bạn bảo vệ [blank3] của bản thân cũng như duy trì [blank4] tốt đẹp.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"tôn trọng\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"lịch sự\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"giá trị\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"mối quan hệ\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"tôn trọng\", \"lịch sự\", \"giá trị\", \"mối quan hệ\", \"tự ti\", \"giận dỗi\", \"nài nỉ\", \"trả đũa\"]\r\n}', 5, '2026-06-11 17:12:12', '2026-06-11 17:12:12'),
(1215, 205, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Nếu bạn cảm thấy mệt mỏi và không muốn đi chơi cùng bạn bè, cách từ chối nào sau đây là văn minh và rõ ràng nhất?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Lờ tin nhắn đi, giả vờ như không đọc được.\", \"correct\": false, \"emoji\": \"🥺\" },\r\n    { \"text\": \"Nói dối là nhà có việc bận đột xuất để khỏi phải giải thích.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Nói rõ rằng mình đang mệt cần nghỉ ngơi, cảm ơn lời rủ và hẹn dịp khác.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Nhắn tin cộc lốc: \'Không đi đâu, mệt lắm!\'\", \"correct\": false, \"emoji\": \"😠\" }\r\n  ]\r\n}', 6, '2026-06-11 17:12:12', '2026-06-11 17:12:12'),
(1216, 206, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Ranh giới số & Mạng xã hội\'! Bạn có 3 mạng để giải quyết các rắc rối trên không gian ảo. Tiến lên!\"}', 1, '2026-06-11 17:13:10', '2026-06-11 17:13:10'),
(1217, 206, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Ranh giới trên không gian mạng\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Bạn chụp được ảnh dìm của bạn thân ngủ gật trong lớp với dáng vẻ rất ngộ nghĩnh. Nhóm chat của lớp đang bàn tán xôn xao, bạn định đăng tấm ảnh này lên Story Instagram cá nhân.\",\r\n      \"choices\": [\r\n        { \"text\": \"Đăng lên ngay lập tức kèm caption hài hước để mọi người cùng thả tim.\", \"nextNode\": \"fail_leak\" },\r\n        { \"text\": \"Gửi riêng bức ảnh cho bạn ấy xem trước và hỏi ý kiến: \'Tớ đăng tấm này lên Story trêu tí được không?\'\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Chỉ chia sẻ trong nhóm chat kín 3 người bạn thân mà không cần hỏi bạn ấy.\", \"nextNode\": \"fail_leak_private\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Bạn ấy nhắn lại: \'Trông mặt tớ phệ quá, cậu đừng đăng lên mạng nha, tớ ngại lắm!\'\",\r\n      \"choices\": [\r\n        { \"text\": \"Nài nỉ tiếp: \'Ui dào bạn bè cả mà, story 24h tự xóa thôi, có ai để ý đâu, cho tớ đăng đi!\'\", \"nextNode\": \"fail_pester\" },\r\n        { \"text\": \"Tôn trọng bạn: \'Ok cậu nè, tớ sẽ giữ làm kỷ niệm riêng thôi, không đăng đâu!\'\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Tối hôm đó, một thành viên khác trong nhóm lớp lại tự ý đăng bức ảnh dìm đó lên nhóm Facebook chung của trường.\",\r\n      \"choices\": [\r\n        { \"text\": \"Hùa vào bình luận trêu chọc chung cho vui: \'Haha nhìn tấu hài thực sự!\'\", \"nextNode\": \"fail_cyberbullying\" },\r\n        { \"text\": \"Nhắn tin nhắc nhở bạn kia gỡ ảnh và động viên bạn thân của mình.\", \"nextNode\": \"success_end\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Hoàn hảo! Tôn trọng ranh giới số của bạn bè giúp giữ gìn tình bạn đẹp trực tuyến và thực tế.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_leak\": {\r\n      \"text\": \"❌ Sai rồi! Tự ý đăng ảnh dìm của bạn bè lên mạng xã hội khi chưa được sự đồng ý là vi phạm ranh giới số của họ.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_leak_private\": {\r\n      \"text\": \"❌ Chưa đúng. Dù là nhóm chat kín, chia sẻ ảnh dìm không có sự đồng thuận vẫn có nguy cơ rò rỉ và gây tổn thương cho bạn mình.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_pester\": {\r\n      \"text\": \"❌ Sai rồi! Nài nỉ, ép buộc đối phương nhượng bộ trên mạng xã hội vẫn là hành vi thiếu tôn trọng ranh giới của họ.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_cyberbullying\": {\r\n      \"text\": \"❌ Sai rồi! Hùa theo trêu chọc khi biết bạn không thoải mái là hành vi tiếp tay cho bắt nạt trực tuyến.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 17:13:10', '2026-06-11 17:13:10'),
(1218, 206, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại hành vi trên mạng xã hội:\",\r\n  \"leftBox\": { \"title\": \"Green Flag số\" },\r\n  \"rightBox\": { \"title\": \"Red Flag số\" },\r\n  \"items\": [\r\n    { \"text\": \"Hỏi ý kiến bạn bè trước khi đăng ảnh chung lên mạng\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Đòi người yêu cung cấp mật khẩu tài khoản để kiểm soát\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Tôn trọng yêu cầu gỡ tag hoặc xóa ảnh từ người khác\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Gửi ảnh nhạy cảm cá nhân dưới áp lực đe dọa chia tay\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Cài đặt chế độ riêng tư để bảo vệ thông tin cá nhân\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 17:13:10', '2026-06-11 17:13:10'),
(1219, 206, 'matching', '{\r\n  \"instruction\": \"Ghép cặp từ khóa ranh giới và định nghĩa an toàn số sau:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Đồng thuận số (Digital consent)\", \"right\": \"Hỏi ý kiến trước khi chia sẻ hình ảnh hoặc thông tin người khác lên mạng.\" },\r\n    { \"left\": \"Ranh giới mật khẩu\", \"right\": \"Quyền giữ bảo mật tài khoản cá nhân, không chia sẻ để chứng minh lòng tin.\" },\r\n    { \"left\": \"Bộ lọc truyền thông\", \"right\": \"Khả năng phân biệt ảo tưởng trên phim ảnh với các mối quan hệ đời thực.\" },\r\n    { \"left\": \"Bắt nạt trực tuyến\", \"right\": \"Hành vi sử dụng mạng xã hội để trêu chọc, cô lập hoặc làm nhục người khác.\" }\r\n  ]\r\n}', 4, '2026-06-11 17:13:10', '2026-06-11 17:13:10'),
(1220, 206, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành định nghĩa an toàn mạng:\",\r\n  \"sentence\": \"Mạng xã hội không bao giờ [blank1] hoàn toàn thông tin, vì vậy hãy luôn tôn trọng [blank2] số của bạn bè và tuyệt đối nói không với áp lực gửi ảnh [blank3] dù đối phương có [blank4] thế nào.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"xóa\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"ranh giới\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"nhạy cảm\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"nài nỉ\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"xóa\", \"ranh giới\", \"nhạy cảm\", \"nài nỉ\", \"công khai\", \"chia sẻ\", \"lừa dối\", \"tin tưởng\"]\r\n}', 5, '2026-06-11 17:13:10', '2026-06-11 17:13:10'),
(1221, 206, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Khi một người bạn online liên tục nhắn tin yêu cầu bạn gửi ảnh chụp riêng tư nhạy cảm của bạn, phản ứng nào sau đây bảo vệ bạn tốt nhất?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Gửi một bức ảnh chụp từ xa, che mặt để tự bảo vệ.\", \"correct\": false, \"emoji\": \"🥺\" },\r\n    { \"text\": \"Từ chối dứt khoát, chặn tài khoản đó và báo ngay với người lớn đáng tin cậy.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Thương lượng: \'Cậu gửi ảnh của cậu trước đi rồi tớ gửi sau\'.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Im lặng gửi ảnh vì sợ bị tung thông tin cá nhân lên mạng.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 17:13:10', '2026-06-11 17:13:10'),
(1222, 207, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Làm chủ cơ thể & Sức khỏe\'! Bạn có 3 mạng để thử thách kiến thức y học và pháp lý. Bắt đầu!\"}', 1, '2026-06-11 17:14:06', '2026-06-11 17:14:06'),
(1223, 207, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Quyền tự quyết cơ thể và pháp luật\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Bạn đang quen một người yêu 15 tuổi. Người yêu nói rất yêu bạn và muốn hai đứa tiến xa hơn (quan hệ tình dục) để chứng minh tình cảm sâu sắc. Bạn biết rõ quy định pháp luật Việt Nam nhưng người yêu cứ khóc lóc.\",\r\n      \"choices\": [\r\n        { \"text\": \"Đồng ý vì nghĩ cả hai tự nguyện thì pháp luật không can thiệp.\", \"nextNode\": \"fail_legal_issue\" },\r\n        { \"text\": \"Kiên quyết từ chối lịch sự, giải thích rõ ranh giới pháp lý cột mốc 16 tuổi để bảo vệ cả hai.\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Nổi giận đùng đùng, mắng mỏ người yêu là thiếu hiểu biết rồi đòi chia tay ngay.\", \"nextNode\": \"fail_anger_legal\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Người yêu giận dỗi nói: \'Cậu lấy lý do pháp luật để thoái thác đúng không? Yêu nhau mà sợ sệt đủ thứ!\'\",\r\n      \"choices\": [\r\n        { \"text\": \"Nhượng bộ vì không muốn bị nghi ngờ tình cảm chân thành.\", \"nextNode\": \"fail_legal_concede\" },\r\n        { \"text\": \"Vỗ về người yêu, khẳng định tình cảm chân thành nhưng kiên định ranh giới: \'Tớ muốn bảo vệ tương lai của cả hai đứa\'.\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Sau đó, người yêu nghe theo lời khuyên của bạn và muốn cùng bạn tìm hiểu về các biện pháp tránh thai khoa học để chuẩn bị kiến thức cho tương lai.\",\r\n      \"choices\": [\r\n        { \"text\": \"Khuyên người yêu dùng phương pháp xuất tinh ngoài vì nghe bạn bè bảo rất an toàn và tự nhiên.\", \"nextNode\": \"fail_medical_myth\" },\r\n        { \"text\": \"Đề xuất cùng tìm hiểu về bao cao su và các biện pháp tránh thai an toàn, khoa học.\", \"nextNode\": \"success_end\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Hoàn toàn chính xác! Bạn đã vừa kiên định bảo vệ bản thân và đối phương, vừa tuân thủ pháp luật Việt Nam.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_legal_issue\": {\r\n      \"text\": \"❌ Sai luật hình sự! Tại Việt Nam, mọi hành vi quan hệ tình dục với người dưới 16 tuổi là phạm pháp hình sự, kể cả có sự tự nguyện từ hai phía.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_anger_legal\": {\r\n      \"text\": \"❌ Phản ứng quá đà! Lên giọng mắng mỏ không giúp đối phương hiểu rõ bản chất vấn đề pháp lý mà chỉ làm xung đột gia tăng.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_legal_concede\": {\r\n      \"text\": \"❌ Sai rồi! Nhượng bộ áp lực tình cảm để vi phạm pháp luật hình sự là hành vi cực kỳ nguy hiểm cho cả hai.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_medical_myth\": {\r\n      \"text\": \"❌ Sai kiến thức y khoa! Xuất tinh ngoài có tỷ lệ thất bại rất cao và hoàn toàn không phòng tránh được các bệnh lây qua đường tình dục (STIs).\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 17:14:06', '2026-06-11 17:14:06'),
(1224, 207, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại kiến thức giới tính:\",\r\n  \"leftBox\": { \"title\": \"Khoa học chính xác\" },\r\n  \"rightBox\": { \"title\": \"Lời đồn nguy hại\" },\r\n  \"items\": [\r\n    { \"text\": \"Bao cao su giúp ngăn ngừa thai và hầu hết bệnh STIs\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Xuất tinh ngoài là biện pháp tránh thai tuyệt đối an toàn\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Gọi đúng tên dương vật, âm hộ để giao tiếp sức khỏe\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Quan hệ lần đầu tiên thì chắc chắn không thể mang thai\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Cơ thể dậy thì phát triển theo tốc độ riêng của mỗi người\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 17:14:06', '2026-06-11 17:14:06'),
(1225, 207, 'matching', '{\r\n  \"instruction\": \"Ghép cặp từ khóa cơ thể và định nghĩa sau:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Quyền tự quyết (Agency)\", \"right\": \"Quyền sở hữu tối cao và đưa ra quyết định đối với cơ thể của chính bạn.\" },\r\n    { \"left\": \"Độ tuổi đồng thuận\", \"right\": \"Cột mốc đủ 16 tuổi trở lên theo quy định của Luật hình sự Việt Nam.\" },\r\n    { \"left\": \"Bệnh lây qua đường tình dục\", \"right\": \"Các bệnh STIs như HIV, lậu, giang mai cần phòng tránh bằng bao cao su.\" },\r\n    { \"left\": \"Âm hộ (Vulva)\", \"right\": \"Cấu tạo sinh học bên ngoài của cơ quan sinh dục nữ cần gọi tên khoa học.\" }\r\n  ]\r\n}', 4, '2026-06-11 17:14:06', '2026-06-11 17:14:06'),
(1226, 207, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành định nghĩa pháp luật:\",\r\n  \"sentence\": \"Tại Việt Nam, mọi hành vi quan hệ tình dục với người dưới [blank1] tuổi đều vi phạm [blank2] hình sự, kể cả khi có sự [blank3] tự nguyện, nhằm bảo vệ sự phát triển [blank4] của vị thành niên.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"16\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"pháp luật\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"đồng thuận\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"lành mạnh\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"16\", \"pháp luật\", \"đồng thuận\", \"lành mạnh\", \"18\", \"dân sự\", \"im lặng\", \"ép buộc\"]\r\n}', 5, '2026-06-11 17:14:06', '2026-06-11 17:14:06'),
(1227, 207, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Phương pháp nào sau đây là duy nhất vừa giúp tránh thai hiệu quả vừa bảo vệ bạn khỏi các bệnh lây truyền qua đường tình dục (STIs)?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Sử dụng thuốc tránh thai khẩn cấp.\", \"correct\": false, \"emoji\": \"🥺\" },\r\n    { \"text\": \"Sử dụng bao cao su đúng cách trong suốt quá trình đụng chạm tình dục.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Thực hiện xuất tinh ngoài âm đạo.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Tính ngày rụng trứng theo chu kỳ kinh nguyệt.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 17:14:06', '2026-06-11 17:14:06'),
(1228, 208, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Áp lực bạn bè & Điểm tựa hỗ trợ\'! Bạn có 3 mạng để vượt qua 5 thử thách áp lực tâm lý nhóm. Khởi đầu!\"}', 1, '2026-06-11 17:14:46', '2026-06-11 17:14:46'),
(1229, 208, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Đối phó với áp lực đồng trang lứa\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Nhóm bạn thân đang tụ tập ở nhà một bạn học, lôi ra một thiết bị thuốc lá điện tử (vape) rực rỡ và rủ bạn hút thử một hơi lớn. Cả nhóm hùa vào khích tướng: \'Không hút là nhát gan, không nể mặt anh em chơi chung gì cả!\'\",\r\n      \"choices\": [\r\n        { \"text\": \"Hút thử một hơi thật sâu để chứng tỏ bản thân cool ngầu và giữ hòa khí nhóm.\", \"nextNode\": \"fail_vape_try\" },\r\n        { \"text\": \"Lớn tiếng giáo huấn cả nhóm về tác hại của vape đối với phổi.\", \"nextNode\": \"fail_lecture_group\" },\r\n        { \"text\": \"Từ chối khéo léo nhưng dứt khoát: \'Tớ xin kiếu, phổi tớ nhạy cảm lắm, ngửi khói là ho sặc sụa rồi\'.\", \"nextNode\": \"step2\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Một bạn trong nhóm bĩu môi cười cợt: \'Yếu đuối thế, thử một tí có chết ai đâu mà sợ!\'\",\r\n      \"choices\": [\r\n        { \"text\": \"Cảm thấy tự ái, giật lấy vape để hút chứng minh mình không yếu.\", \"nextNode\": \"fail_pride\" },\r\n        { \"text\": \"Kiên định cười vui: \'Tớ yếu thật mà, tớ chỉ mạnh môn bóng rổ thôi! Các cậu cứ chơi đi, tớ ra phòng khách xem tivi nha\'.\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Sau đó, một bạn trong nhóm đột ngột khóa cửa phòng lại và đe dọa không cho bạn ra ngoài nếu bạn không chịu uống cạn cốc nước ngọt đã pha cồn.\",\r\n      \"choices\": [\r\n        { \"text\": \"Sợ hãi nhắm mắt uống hết cốc nước để được thả ra.\", \"nextNode\": \"fail_alcohol\" },\r\n        { \"text\": \"Chụp lại hình ảnh phòng khóa, kiên quyết yêu cầu mở cửa, đồng thời nhắn tin báo cho bố mẹ hoặc gọi tổng đài 111 hỗ trợ nếu tình hình căng thẳng.\", \"nextNode\": \"success_end\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Xuất sắc! Bạn đã từ chối áp lực nhóm thành công bằng thái độ kiên định, vui vẻ và bảo vệ sức khỏe của mình.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_vape_try\": {\r\n      \"text\": \"❌ Sai rồi! Làm việc gây hại cho sức khỏe chỉ vì sợ đám đông tẩy chay là tự đánh mất ranh giới cá nhân.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_lecture_group\": {\r\n      \"text\": \"❌ Chưa khéo. Lên giọng dạy đời bạn bè khi họ đang hưng phấn chỉ khiến họ phản kháng, cô lập bạn nhanh hơn thay vì có tính xây dựng.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_pride\": {\r\n      \"text\": \"❌ Sai rồi! Nhượng bộ ranh giới sức khỏe chỉ vì lời thách thức hay khích tướng trẻ con là thiếu tự chủ.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_alcohol\": {\r\n      \"text\": \"❌ Sai rồi! Uống đồ uống chứa chất kích thích/cồn dưới sự đe dọa cưỡng bức là vi phạm ranh giới an toàn của bạn. Hãy tìm kiếm sự hỗ trợ ngay lập tức.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 17:14:46', '2026-06-11 17:14:46'),
(1230, 208, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại hành vi sau:\",\r\n  \"leftBox\": { \"title\": \"Áp lực nhóm độc hại\" },\r\n  \"rightBox\": { \"title\": \"Điểm tựa an toàn\" },\r\n  \"items\": [\r\n    { \"text\": \"Rủ rê thử vape hoặc chất kích thích để chứng tỏ bản thân\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Chia sẻ khó khăn với bố mẹ hoặc thầy cô giáo đáng tin\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Ép buộc bạn bè cô lập, nói xấu một học sinh mới\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Gọi điện đến Tổng đài Quốc gia 111 để tìm sự giúp đỡ\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Đe dọa phát tán thông tin riêng tư nếu không làm theo lời thách\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 17:14:46', '2026-06-11 17:14:46'),
(1231, 208, 'matching', '{\r\n  \"instruction\": \"Ghép cặp từ khóa ranh giới và định nghĩa an toàn sau:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Áp lực đồng trang lứa\", \"right\": \"Sự thúc ép từ nhóm bạn khiến bạn làm điều nguy hiểm hoặc không muốn.\" },\r\n    { \"left\": \"Tổng đài 111\", \"right\": \"Đường dây nóng quốc gia hỗ trợ, tư vấn bảo vệ trẻ em miễn phí 24/7.\" },\r\n    { \"left\": \"Dũng khí đi ngược\", \"right\": \"Khả năng nói không và giữ vững lập trường trước đám đông thúc ép.\" },\r\n    { \"left\": \"Điểm tựa hỗ trợ\", \"right\": \"Những người lớn đáng tin cậy giúp bạn giải quyết các tình huống nguy hiểm.\" }\r\n  ]\r\n}', 4, '2026-06-11 17:14:46', '2026-06-11 17:14:46');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(1232, 208, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành định nghĩa ranh giới điểm tựa:\",\r\n  \"sentence\": \"Khi đối mặt với sự [blank1] từ bạn bè để làm điều sai trái, hãy kiên định [blank2], và nếu cảm thấy an toàn bị [blank3], hãy liên hệ ngay với người lớn đáng tin cậy hoặc gọi tổng đài [blank4].\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"thúc ép\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"từ chối\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"đe dọa\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"111\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"thúc ép\", \"từ chối\", \"đe dọa\", \"111\", \"đồng ý\", \"im lặng\", \"hùa theo\", \"bạn bè\"]\r\n}', 5, '2026-06-11 17:14:46', '2026-06-11 17:14:46'),
(1233, 208, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Khi ranh giới cơ thể của bạn bị xâm hại hoặc bạn bị đe dọa cưỡng ép trực tuyến, hành động nào sau đây là dũng cảm và chính xác nhất?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Im lặng chịu đựng, tự giải quyết một mình vì sợ bố mẹ mắng.\", \"correct\": false, \"emoji\": \"🥺\" },\r\n    { \"text\": \"Nhượng bộ và làm theo yêu cầu của đối phương để họ không đe dọa nữa.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Thu thập bằng chứng, chia sẻ ngay với người lớn đáng tin cậy và liên hệ tổng đài 111 để được hỗ trợ kịp thời.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Đe dọa hoặc dùng bạo lực trả đũa lại đối phương.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 17:14:46', '2026-06-11 17:14:46'),
(1234, 209, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Dấu Chân Số: Đừng Để Lộ Sơ Hở\'! Bạn có 3 mạng để vượt qua 5 thử thách cam go nhằm bảo vệ thông tin cá nhân. Sẵn sàng chưa?\"}', 1, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1235, 209, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Bảo vệ thông tin cá nhân\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Bạn vừa đỗ thủ khoa kỳ thi học sinh giỏi cấp thành phố và nhận được giấy khen kèm thẻ học sinh mới cứng. Bạn rất muốn khoe tin vui này lên Story Instagram để nhận lời chúc từ bạn bè.\",\r\n      \"choices\": [\r\n        { \"text\": \"Chụp ảnh rõ nét toàn bộ giấy khen và thẻ học sinh có hiện họ tên, mã số, trường học và ngày sinh rồi đăng lên.\", \"nextNode\": \"fail_leak\" },\r\n        { \"text\": \"Dùng nhãn dán (sticker) che mờ các thông tin nhạy cảm như mã số học sinh, số điện thoại, địa chỉ nhà rồi mới đăng.\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Chỉ chụp ảnh chiếc cúp học sinh giỏi kèm caption thông báo tin vui mà không đăng hình ảnh thẻ hay giấy tờ gì.\", \"nextNode\": \"step2\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Một tài khoản lạ nhắn tin chúc mừng bạn rất nhiệt tình, tự xưng là cựu học sinh trường bạn và hỏi xin số điện thoại để \'tặng tài liệu ôn thi đặc biệt\'.\",\r\n      \"choices\": [\r\n        { \"text\": \"Đưa số điện thoại ngay vì nghĩ cựu học sinh trường mình thì chắc chắn đáng tin.\", \"nextNode\": \"fail_stranger\" },\r\n        { \"text\": \"Cảm ơn lịch sự và nói: \'Tớ chỉ nhận tài liệu qua email học tập thôi nhé!\' hoặc từ chối cung cấp thông tin cá nhân.\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Sau đó, bạn thấy một tài khoản Facebook lấy ảnh cá nhân của bạn và lập tài khoản clone giả danh bạn để đi vay tiền bạn bè trong danh sách.\",\r\n      \"choices\": [\r\n        { \"text\": \"Lờ đi vì nghĩ bạn bè mình sẽ tự biết cảnh giác.\", \"nextNode\": \"fail_ignore\" },\r\n        { \"text\": \"Đăng status cảnh báo bạn bè trên trang cá nhân chính thức, đồng thời báo cáo (report) tài khoản giả mạo đó.\", \"nextNode\": \"success_end\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Hoàn toàn chính xác! Bạn đã xử lý sự cố rò rỉ thông tin một cách dũng cảm, thông minh và có trách nhiệm bảo vệ bạn bè xung quanh.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_leak\": {\r\n      \"text\": \"❌ Sai rồi! Đăng ảnh thẻ học sinh hoặc giấy khen lộ rõ thông tin cá nhân là rủi ro lớn, kẻ xấu có thể dùng để định vị hoặc lừa đảo mạo danh bạn.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_stranger\": {\r\n      \"text\": \"❌ Chưa đúng! Kẻ xấu trên mạng thường giả dạng cựu học sinh, người quen để lấy số điện thoại hoặc thông tin cá nhân của bạn.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_ignore\": {\r\n      \"text\": \"❌ Sai rồi! Im lặng khi bị mạo danh có thể khiến bạn bè bạn bị lừa gạt tiền bạc và làm mất uy tín cá nhân của bạn.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1236, 209, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại các hành vi sau:\",\r\n  \"leftBox\": { \"title\": \"Chia sẻ an toàn\" },\r\n  \"rightBox\": { \"title\": \"Chia sẻ quá đà\" },\r\n  \"items\": [\r\n    { \"text\": \"Đăng ảnh chú mèo đáng yêu mới nuôi\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Đăng ảnh chụp căn cước công dân hoặc thẻ học sinh\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Khoe ảnh chụp cổng nhà có ghi rõ số nhà, tên đường\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Đăng review cảm nghĩ sau khi xem một cuốn sách hay\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Đăng thời khóa biểu lớp học chi tiết hàng tuần\", \"correctBox\": \"right\" }\r\n  ]\r\n}', 3, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1237, 209, 'matching', '{\r\n  \"instruction\": \"Ghép cặp từ khóa ranh giới và định nghĩa dấu chân số sau:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Dấu chân số chủ động\", \"right\": \"Những thông tin bạn tự ý đăng lên mạng xã hội (status, ảnh).\" },\r\n    { \"left\": \"Dấu chân số bị động\", \"right\": \"Dữ liệu được thu thập tự động khi bạn lướt web (cookies, lịch sử).\" },\r\n    { \"left\": \"Thông tin nhạy cảm\", \"right\": \"Địa chỉ nhà, số điện thoại, thẻ học sinh, thời khóa biểu.\" },\r\n    { \"left\": \"Quyền kiểm soát số\", \"right\": \"Quyền quyết định những ai được xem và tương tác với bài đăng của bạn.\" }\r\n  ]\r\n}', 4, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1238, 209, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành định nghĩa dấu chân số:\",\r\n  \"sentence\": \"Những gì đã đăng lên internet sẽ rất khó [blank1] hoàn toàn và tạo nên [blank2] số của bạn. Vì vậy, hãy bảo mật [blank3] cá nhân và hạn chế chia sẻ thông tin [blank4] lên mạng.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"xóa\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"dấu chân\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"tài khoản\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"nhạy cảm\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"xóa\", \"dấu chân\", \"tài khoản\", \"nhạy cảm\", \"lưu trữ\", \"công khai\", \"hình ảnh\", \"riêng tư\"]\r\n}', 5, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1239, 209, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Khi bạn xóa một bức ảnh dìm bạn bè trên Story sau 5 phút đăng tải, điều gì có thể xảy ra với bức ảnh đó?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Bức ảnh đã biến mất hoàn toàn trên mạng và không ai có thể xem lại.\", \"correct\": false, \"emoji\": \"🙁\" },\r\n    { \"text\": \"Kẻ xấu hoặc bạn bè có thể đã chụp màn hình hoặc tải về trước khi bạn xóa, và nó vẫn tiếp tục tồn tại.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Bức ảnh chỉ bị lưu trong bộ nhớ tạm của điện thoại bạn.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Chỉ những người đã thả tim mới lưu lại được bức ảnh.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1240, 210, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Chat Sao Cho Mượt, Bớt Bất Ổn\'! Bạn có 3 mạng để ứng xử văn minh trong các cuộc trò chuyện trực tuyến.\"}', 1, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1241, 210, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Giải quyết hiểu lầm tin nhắn\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Bạn nhắn tin rủ bạn thân đi đá bóng cuối tuần. Bạn thân chỉ rep lại đúng một chữ ngắn ngủn: \'Ừ\'. Cảm giác hụt hẫng và lo lắng dâng lên, bạn nghĩ bạn ấy đang giận mình.\",\r\n      \"choices\": [\r\n        { \"text\": \"Nhắn lại mỉa mai: \'Ừ cái gì mà ừ, bận làm tổng thống hay sao mà rep cộc lốc thế?\'\", \"nextNode\": \"fail_sarcasm\" },\r\n        { \"text\": \"Tạm dừng, suy nghĩ thấu cảm rằng bạn ấy có thể đang bận học hoặc mệt mỏi, rồi nhắn hỏi han nhẹ nhàng sau.\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Lờ đi luôn, tự ái quyết định không bao giờ rủ bạn ấy đi đá bóng nữa.\", \"nextNode\": \"fail_passive_aggressive\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Buổi tối, bạn thân nhắn lại giải thích: \'Xin lỗi cậu nha, lúc chiều tớ đang đạp xe vội nên chỉ bấm rep nhanh được vậy thôi\'. Bạn thấy nhẹ nhõm. Hai đứa tiếp tục làm slide thuyết trình nhóm. Bạn thấy slide bạn ấy làm bị lòe loẹt và chưa đẹp mắt.\",\r\n      \"choices\": [\r\n        { \"text\": \"Chê thẳng thừng trong nhóm chat chung: \'Slide xấu thế cậu, màu sắc lòe loẹt nhìn đau mắt quá!\'\", \"nextNode\": \"fail_harsh\" },\r\n        { \"text\": \"Góp ý riêng bằng tin nhắn Green Flag: \'Slide cậu làm bố cục rất rõ ràng nè! Tớ nghĩ nếu tụi mình đổi sang tông màu xanh mint thì nhìn sẽ dịu và hiện đại hơn đó\'.\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Khi thảo luận bài nhóm trong group chat lớp, hai bạn khác bất đồng ý kiến dữ dội và bắt đầu dùng lời lẽ nặng nề công kích cá nhân nhau, khiến bầu không khí bốc hỏa.\",\r\n      \"choices\": [\r\n        { \"text\": \"Hùa vào bình luận thêm dầu vào lửa để xem drama cho vui.\", \"nextNode\": \"fail_drama\" },\r\n        { \"text\": \"Lên tiếng xoa dịu: \'Tụi mình bình tĩnh lại đi nè, mai lên lớp thảo luận trực tiếp sẽ dễ hiểu nhau hơn nha!\'\", \"nextNode\": \"success_end\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Hoàn toàn chính xác! Bạn đã xử lý và góp ý giao tiếp một cách văn minh, tinh tế, giữ năng lượng tích cực cho mối quan hệ.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_sarcasm\": {\r\n      \"text\": \"❌ Chưa đúng! Lập tức dùng lời mỉa mai cộc lốc dễ làm xung đột bùng phát vì những phỏng đoán sai lầm.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_passive_aggressive\": {\r\n      \"text\": \"❌ Chưa đúng! Giận dỗi thầm lặng không giúp giải quyết hiểu lầm mà chỉ làm tăng khoảng cách và phá hỏng tình bạn.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_harsh\": {\r\n      \"text\": \"❌ Sai rồi! Chê bai thẳng thừng trước đám đông làm tổn thương lòng tự trọng của bạn mình, hãy chọn cách góp ý riêng tư tinh tế.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_drama\": {\r\n      \"text\": \"❌ Sai rồi! Tiếp tay cho xung đột làm rạn nứt tập thể và vi phạm văn hóa số văn minh.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1242, 210, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại các thói quen nhắn tin:\",\r\n  \"leftBox\": { \"title\": \"Green Flag giao tiếp\" },\r\n  \"rightBox\": { \"title\": \"Red Flag giao tiếp\" },\r\n  \"items\": [\r\n    { \"text\": \"Góp ý riêng tư một cách nhẹ nhàng, xây dựng\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Spam hàng chục dấu chấm hỏi khi đối phương chưa kịp rep\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Dùng chữ viết hoa toàn bộ (UPPERCASE) để thể hiện sự giận dữ\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Hỏi han nhẹ nhàng khi thấy tin nhắn rep ngắn gọn cộc lốc\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Chửi bới, mỉa mai đối phương ngay trong group chat chung\", \"correctBox\": \"right\" }\r\n  ]\r\n}', 3, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1243, 210, 'matching', '{\r\n  \"instruction\": \"Ghép cặp từ khóa ranh giới và định nghĩa giao tiếp số sau:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Tin nhắn Green Flag\", \"right\": \"Lời nhắn góp ý xây dựng bắt đầu bằng lời khen ngợi chân thành.\" },\r\n    { \"left\": \"Suy nghĩ thấu cảm\", \"right\": \"Hiểu rằng đối phương chưa rep vì họ đang bận học hoặc nghỉ ngơi.\" },\r\n    { \"left\": \"Hạ nhiệt group chat\", \"right\": \"Đề xuất gặp mặt trực tiếp thay vì cãi vã căng thẳng trên mạng.\" },\r\n    { \"left\": \"Năng lượng tích cực\", \"right\": \"Chủ động theo dõi các trang chia sẻ kiến thức, kỹ năng sống bổ ích.\" }\r\n  ]\r\n}', 4, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1244, 210, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành định nghĩa giao tiếp:\",\r\n  \"sentence\": \"Giao tiếp qua màn hình rất dễ gây [blank1] vì thiếu đi tông giọng và nét mặt. Hãy sử dụng tin nhắn [blank2] để góp ý, tránh [blank3] liên tục bắt đối phương trả lời ngay, và luôn giữ thái độ [blank4] trực tuyến.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"hiểu lầm\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"xây dựng\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"spam\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"tôn trọng\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"hiểu lầm\", \"xây dựng\", \"spam\", \"tôn trọng\", \"đồng ý\", \"tức giận\", \"im lặng\", \"mỉa mai\"]\r\n}', 5, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1245, 210, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Khi bạn nhìn thấy trạng thái Đã xem (Seen) nhưng đối phương chưa trả lời tin nhắn của bạn suốt 30 phút, phản ứng nào sau đây thể hiện bạn là người có EQ cao?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Liên tục gọi điện và gửi tin nhắn phẫn nộ: \'Sao xem rồi mà không rep?\'\", \"correct\": false, \"emoji\": \"😠\" },\r\n    { \"text\": \"Tự suy diễn rằng đối phương ghét mình rồi block họ luôn.\", \"correct\": false, \"emoji\": \"🥺\" },\r\n    { \"text\": \"Đặt điện thoại xuống, làm việc khác và hiểu rằng họ sẽ rep khi rảnh rỗi hoặc sẵn sàng.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Đăng status ám chỉ đối phương sống giả tạo.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1246, 211, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Ranh Giới Số: Vẽ Vạch Rõ, Đỡ Phiền Toái\'! Bạn có 3 mạng để tự chủ thiết lập ranh giới bảo vệ bản thân.\"}', 1, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1247, 211, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Thiết lập ranh giới cá nhân số\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Bạn đang học bài căng thẳng để chuẩn bị cho bài thi ngày mai. Một người bạn thân liên tục nhắn tin, gọi video rủ bạn vào game cày rank cùng nhóm. Bạn đã nhắn tin bảo bận nhưng bạn ấy vẫn spam cuộc gọi liên tục.\",\r\n      \"choices\": [\r\n        { \"text\": \"Chịu đựng tắt tiếng điện thoại rồi ấm ức học tiếp, không dám từ chối vì sợ mất lòng.\", \"nextNode\": \"fail_passive\" },\r\n        { \"text\": \"Bật chế độ \'Không làm phiền\' trên điện thoại, tập trung ôn thi và sẽ nhắn lại giải thích rõ vào ngày mai.\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Nổi khùng lên game chửi bạn thân phiền phức rồi block luôn.\", \"nextNode\": \"fail_aggressive\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Hôm sau, bạn thân gặp bạn và giận dỗi: \'Yêu cầu mật khẩu tài khoản game của cậu để tớ vào cày hộ, thân nhau thế mà tối qua gọi chả thèm nghe\'. Bạn thấy không thoải mái khi đưa mật khẩu.\",\r\n      \"choices\": [\r\n        { \"text\": \"Đưa luôn mật khẩu game cho bạn ấy để chuộc lỗi tối qua.\", \"nextNode\": \"fail_pass_leak\" },\r\n        { \"text\": \"Từ chối khéo nhưng kiên quyết: \'Mật khẩu tớ tự quản lý nha. Cuối tuần tụi mình cùng leo rank chung sau nhé!\'\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Một người bạn khác kéo bạn vào một group chat ẩn danh chuyên bóc phốt, nói xấu thầy cô giáo và các bạn học sinh trong trường.\",\r\n      \"choices\": [\r\n        { \"text\": \"Cứ ở lại group để hóng tin tức nhưng không bình luận gì.\", \"nextNode\": \"fail_silent_stander\" },\r\n        { \"text\": \"Chủ động rời khỏi nhóm chat ẩn danh và nói với bạn: \'Tớ không thoải mái với việc nói xấu người khác nên tớ out nha\'.\", \"nextNode\": \"success_end\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Tuyệt vời! Bạn đã kiên định thiết lập ranh giới số rõ ràng, bảo vệ tài khoản cá nhân và né tránh những không gian ảo độc hại.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_passive\": {\r\n      \"text\": \"❌ Chưa đúng! Chịu đựng ngầm tích tụ bực bội không giải quyết được vấn đề, mà còn dễ làm hỏng tình bạn về lâu dài.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_aggressive\": {\r\n      \"text\": \"❌ Chưa đúng! Phản ứng quá khích làm tổn hại mối quan hệ thay vì thiết lập ranh giới một cách chín chắn.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_pass_leak\": {\r\n      \"text\": \"❌ Sai rồi! Mật khẩu cá nhân là ranh giới an toàn tối thiểu, không nên chia sẻ cho bất kỳ ai để tránh rủi ro mất tài khoản.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_silent_stander\": {\r\n      \"text\": \"❌ Sai rồi! Ở lại group chat bóc phốt độc hại là gián tiếp tiếp tay cho môi trường mạng thiếu văn minh.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1248, 211, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại hành vi ranh giới số:\",\r\n  \"leftBox\": { \"title\": \"Tôn trọng ranh giới\" },\r\n  \"rightBox\": { \"title\": \"Xâm phạm ranh giới\" },\r\n  \"items\": [\r\n    { \"text\": \"Từ chối chia sẻ mật khẩu tài khoản cá nhân cho bạn bè\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Tự ý xem lịch sử tin nhắn của người khác khi mượn máy\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Gọi điện spam liên tục lúc nửa đêm mặc dù bạn đã nói bận\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Đặt giới hạn thời gian lướt mạng xã hội mỗi ngày\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Ép bạn bè phải online nói chuyện khi họ đang mệt\", \"correctBox\": \"right\" }\r\n  ]\r\n}', 3, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1249, 211, 'matching', '{\r\n  \"instruction\": \"Ghép cặp từ khóa ranh giới và định nghĩa ranh giới số sau:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Ranh giới thời gian\", \"right\": \"Quyết định thời lượng sử dụng thiết bị và thời điểm offline nghỉ ngơi.\" },\r\n    { \"left\": \"Ranh giới bảo mật\", \"right\": \"Giữ kín mật khẩu tài khoản cá nhân trước mọi người, kể cả bạn thân.\" },\r\n    { \"left\": \"Ức chế ngầm (Resentment)\", \"right\": \"Sự ấm ức tích tụ bên trong khi liên tục phải chịu đựng việc bị lấn lướt.\" },\r\n    { \"left\": \"Từ chối thẳng thắn\", \"right\": \"Nói Không lịch sự nhưng rõ ràng, không vòng vo nói dối.\" }\r\n  ]\r\n}', 4, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1250, 211, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành định nghĩa ranh giới:\",\r\n  \"sentence\": \"Thiết lập ranh giới số giúp bạn bảo vệ [blank1] riêng tư và tránh những [blank2] ngầm tích tụ. Bạn luôn có quyền từ chối chia sẻ [blank3] cá nhân và nói không với các hội nhóm [blank4].\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"không gian\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"ức chế\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"mật khẩu\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"độc hại\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"không gian\", \"ức chế\", \"mật khẩu\", \"độc hại\", \"đồng ý\", \"hình ảnh\", \"bạn bè\", \"chia sẻ\"]\r\n}', 5, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1251, 211, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Khi bạn mượn điện thoại của bạn bè để chụp ảnh, hành động nào sau đây là tôn trọng ranh giới số nhất?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Tiện tay mở mục nhắn tin Messenger xem có gì mới.\", \"correct\": false, \"emoji\": \"🥺\" },\r\n    { \"text\": \"Chỉ mở đúng ứng dụng camera để chụp, không tự ý bấm vào bất kỳ ứng dụng nào khác.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Lướt xem thử album ảnh riêng tư của họ.\", \"correct\": false, \"emoji\": \"🛑\" },\r\n    { \"text\": \"Vào phần cài đặt để kiểm tra thông số máy.\", \"correct\": false, \"emoji\": \"😐\" }\r\n  ]\r\n}', 6, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1252, 212, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Đồng Thuận Số: Đừng Tự Ý Mặc Định\'! Bạn có 3 mạng để thực hành sự đồng thuận số văn minh trực tuyến.\"}', 1, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1253, 212, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Tôn trọng sự đồng thuận trực tuyến\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Bạn chụp được ảnh dìm của bạn thân đang ngủ gật trong lớp trông rất ngộ nghĩnh. Bạn thấy rất vui và định đăng lên Story Instagram để trêu bạn bè.\",\r\n      \"choices\": [\r\n        { \"text\": \"Cứ đăng lên luôn vì bạn bè thân thiết đùa chút có sao đâu.\", \"nextNode\": \"fail_leak\" },\r\n        { \"text\": \"Gửi tin nhắn riêng hỏi bạn ấy: \'Tớ đăng tấm này lên Story trêu tí nha cậu, cậu thấy ok không?\'\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Đăng lên nhóm chat kín của lớp mà không cần hỏi bạn thân.\", \"nextNode\": \"fail_leak_group\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Bạn ấy nhắn lại: \'Mặt tớ phệ quá nhìn ghê chết, đừng đăng lên mạng nha cậu, tớ ngại lắm!\'\",\r\n      \"choices\": [\r\n        { \"text\": \"Nài nỉ tiếp: \'Vui thôi mà, story tự xóa sau 24h thôi, cho đăng đi nha!\'\", \"nextNode\": \"fail_pester\" },\r\n        { \"text\": \"Tôn trọng quyết định của bạn: \'Ok cậu nè, tớ xóa tấm này đi nhé, chọn tấm khác đẹp hơn nha!\'\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Sau đó, một bạn nam trong lớp rủ bạn chụp ảnh chung. Bạn đồng ý chụp. Nhưng sau đó bạn nam định đăng bức ảnh lên kèm caption ghép đôi yêu đương. Bạn thấy không thoải mái.\",\r\n      \"choices\": [\r\n        { \"text\": \"Im lặng chịu đựng vì nghĩ nãy mình đã đồng ý chụp ảnh thì giờ họ có quyền đăng.\", \"nextNode\": \"fail_reversible\" },\r\n        { \"text\": \"Nói rõ ranh giới: \'Tớ đồng ý chụp ảnh chung chứ không đồng ý đăng bài ghép đôi đâu nha, mong cậu tôn trọng\'.\", \"nextNode\": \"success_end\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Hoàn hảo! Bạn đã tôn trọng và thực hành quy tắc đồng thuận trực tuyến, hiểu rõ rằng đồng ý việc này không có nghĩa là đồng ý việc khác.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_leak\": {\r\n      \"text\": \"❌ Sai rồi! Tự ý đăng tải hình ảnh riêng tư của bạn bè lên mạng xã hội khi chưa được sự đồng ý là vi phạm ranh giới số của họ.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_leak_group\": {\r\n      \"text\": \"❌ Chưa đúng! Nhóm chat kín vẫn có nguy cơ bị chụp màn hình hoặc chia sẻ ra ngoài, gây tổn thương lòng tự trọng của bạn mình.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_pester\": {\r\n      \"text\": \"❌ Sai rồi! Nài nỉ, lấn lướt ranh giới số khi đối phương đã từ chối là hành vi thiếu tôn trọng sự đồng thuận trực tuyến.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_reversible\": {\r\n      \"text\": \"❌ Sai rồi! Sự đồng thuận có tính chất linh hoạt và cụ thể - việc bạn đồng ý chụp chung không có nghĩa là bạn cho phép họ đăng bài ghép đôi tùy ý.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1254, 212, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại các hành vi đồng thuận số:\",\r\n  \"leftBox\": { \"title\": \"Tôn trọng đồng thuận\" },\r\n  \"rightBox\": { \"title\": \"Tự ý mặc định\" },\r\n  \"items\": [\r\n    { \"text\": \"Hỏi ý kiến bạn bè trước khi tag họ vào bài viết công khai\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Lần trước cậu cho mượn acc rồi nên lần này tớ tự ý dùng tiếp\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Dừng gửi ảnh meme khi bạn nói hôm nay bạn mệt và muốn yên tĩnh\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Đăng ảnh chụp dìm bạn bè lên mạng làm trò cười khi họ chưa đồng ý\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Kiểm tra sự thoải mái của đối phương trước khi rủ call video\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1255, 212, 'matching', '{\r\n  \"instruction\": \"Ghép cặp từ khóa ranh giới và định nghĩa đồng thuận số sau:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Đồng thuận trực tuyến\", \"right\": \"Sự đồng ý tự nguyện, hào hứng, cụ thể và có thể rút lại trên mạng.\" },\r\n    { \"left\": \"Không mặc định\", \"right\": \"Việc đối phương đồng ý lần trước không có nghĩa là tự động đồng ý lần này.\" },\r\n    { \"left\": \"Tính cụ thể (Specific)\", \"right\": \"Đồng ý chụp ảnh chung không đồng nghĩa với đồng ý đăng ảnh ghép đôi.\" },\r\n    { \"left\": \"Nài nỉ số\", \"right\": \"Hành vi lấn lướt, ép buộc đối phương phải nhượng bộ ranh giới trên mạng.\" }\r\n  ]\r\n}', 4, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1256, 212, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành định nghĩa đồng thuận số:\",\r\n  \"sentence\": \"Sự đồng thuận số phải được đưa ra một cách [blank1] và hào hứng. Đồng ý lúc trước không có nghĩa là [blank2] cho lần sau, và bạn luôn có quyền [blank3] quyết định của mình bất cứ [blank4] nào.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"tự nguyện\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"mặc định\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"thay đổi\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"lúc\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"tự nguyện\", \"mặc định\", \"thay đổi\", \"lúc\", \"im lặng\", \"ép buộc\", \"nài nỉ\", \"đồng ý\"]\r\n}', 5, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1257, 212, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Nếu bạn của bạn đã đồng ý cho bạn mượn tài khoản Netflix tuần trước để xem phim, hành động nào sau đây là tôn trọng sự đồng thuận số nhất vào tuần này?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Tự ý đăng nhập xem tiếp mà không cần hỏi vì tài khoản đã lưu trên máy.\", \"correct\": false, \"emoji\": \"🥺\" },\r\n    { \"text\": \"Nhắn tin hỏi lại bạn trước khi đăng nhập: \'Tớ vào Netflix xem nốt tập phim hôm trước nhé cậu?\'\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Đưa tài khoản đó cho một người bạn khác mượn dùng chung.\", \"correct\": false, \"emoji\": \"🛑\" },\r\n    { \"text\": \"Đổi mật khẩu tài khoản đó để xem một mình.\", \"correct\": false, \"emoji\": \"😐\" }\r\n  ]\r\n}', 6, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1258, 213, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Sexting & Gửi Ảnh: Giữ Mình An Toàn Trên Sóng\'! Bạn có 3 mạng để bảo vệ ranh giới hình ảnh cơ thể.\"}', 1, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1259, 213, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Đối phó với áp lực gửi ảnh nhạy cảm\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Người yêu qua mạng nhắn tin năn nỉ bạn gửi ảnh mặc áo trễ vai hở ngực hoặc ảnh nhạy cảm cá nhân, nói rằng \'Yêu nhau thì phải tin tưởng và chia sẻ hình ảnh cơ thể cho nhau\'. Bạn thấy lo sợ và không thoải mái.\",\r\n      \"choices\": [\r\n        { \"text\": \"Gửi đại một bức ảnh mờ mờ hoặc che mặt để xoa dịu đối phương.\", \"nextNode\": \"fail_leak_risk\" },\r\n        { \"text\": \"Từ chối dứt khoát: \'Tớ không thoải mái với việc này. Mong cậu tôn trọng quyết định của tớ\'.\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Nói dối là điện thoại hỏng camera để né tránh tạm thời.\", \"nextNode\": \"fail_avoid\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Người đó giận dỗi, đe dọa: \'Nếu không gửi thì chứng tỏ không yêu thật lòng, tụi mình chia tay đi!\'\",\r\n      \"choices\": [\r\n        { \"text\": \"Nhượng bộ gửi ảnh vì quá sợ chia tay.\", \"nextNode\": \"fail_concede\" },\r\n        { \"text\": \"Kiên định ranh giới: \'Nếu cậu muốn chia tay chỉ vì tớ bảo vệ ranh giới cơ thể mình, thì tớ chấp nhận chia tay\'.\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Sau đó, người đó chụp ảnh màn hình các cuộc trò chuyện riêng tư của hai đứa và đe dọa sẽ tung lên nhóm lớp nếu bạn không chịu làm theo yêu cầu của họ.\",\r\n      \"choices\": [\r\n        { \"text\": \"Im lặng làm theo mọi yêu cầu của họ để giữ bình yên.\", \"nextNode\": \"fail_blackmail\" },\r\n        { \"text\": \"Chụp lại bằng chứng đe dọa, báo ngay cho bố mẹ hoặc thầy cô giáo đáng tin cậy và gọi tổng đài 111.\", \"nextNode\": \"success_end\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Hoàn toàn chính xác! Bạn đã vừa kiên định bảo vệ bản thân, vừa tìm kiếm sự hỗ trợ kịp thời để dập tắt hành vi tống tiền số.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_leak_risk\": {\r\n      \"text\": \"❌ Sai rồi! Ảnh nhạy cảm khi đã gửi đi sẽ nằm ngoài kiểm soát và hoàn toàn có nguy cơ bị phát tán hoặc dùng để tống tiền.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_avoid\": {\r\n      \"text\": \"❌ Chưa đúng! Viện lý do giả vờ hỏng camera không giải quyết được gốc rễ áp lực, đối phương sẽ tiếp tục đòi hỏi khi có cơ hội.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_concede\": {\r\n      \"text\": \"❌ Sai rồi! Nhượng bộ đe dọa gửi ảnh nhạy cảm chỉ khiến kẻ xấu nắm thóp và khống chế bạn nhiều hơn trong tương lai.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_blackmail\": {\r\n      \"text\": \"❌ Sai rồi! Chịu đựng kẻ tống tiền không bao giờ mang lại an toàn. Bạn cần chụp bằng chứng và báo ngay người lớn.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1260, 213, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại hành vi quyền cơ thể số:\",\r\n  \"leftBox\": { \"title\": \"Bảo vệ quyền cơ thể\" },\r\n  \"rightBox\": { \"title\": \"Xâm phạm quyền cơ thể\" },\r\n  \"items\": [\r\n    { \"text\": \"Kiên quyết từ chối gửi ảnh nhạy cảm dù bị ép buộc\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Lên chụp ảnh bạn bè trong nhà vệ sinh để làm trò đùa\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Báo cáo tài khoản đăng ảnh bôi nhọ ngoại hình của bạn học\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Yêu cầu đối phương bật camera phơi bày cơ thể khi chat video\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Xóa tag và yêu cầu gỡ ảnh dìm khi bản thân thấy ngại\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1261, 213, 'matching', '{\r\n  \"instruction\": \"Ghép cặp từ khóa ranh giới và định nghĩa an toàn hình ảnh sau:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Sexting\", \"right\": \"Hành vi nhắn tin hoặc chia sẻ hình ảnh nhạy cảm, cơ thể trực tuyến.\" },\r\n    { \"left\": \"Quyền kiểm soát cơ thể\", \"right\": \"Quyền quyết định tối cao của bạn đối với hình ảnh thân thể của chính mình.\" },\r\n    { \"left\": \"Tổng đài 111\", \"right\": \"Đường dây nóng quốc gia tiếp nhận hỗ trợ, tư vấn bảo vệ trẻ em 24/7.\" },\r\n    { \"left\": \"Thao túng tình cảm\", \"right\": \"Dùng lời đe dọa chia tay để ép buộc đối phương gửi ảnh nhạy cảm.\" }\r\n  ]\r\n}', 4, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1262, 213, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành định nghĩa an toàn hình ảnh:\",\r\n  \"sentence\": \"Hình ảnh nhạy cảm đã gửi lên internet sẽ không thể [blank1] hoàn toàn. Việc ép buộc đối phương gửi ảnh cơ thể là vi phạm [blank2] cá nhân. Khi gặp sự cố đe dọa phát tán ảnh, hãy tìm điểm tựa [blank3] và gọi tổng đài [blank4].\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"thu hồi\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"ranh giới\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"an toàn\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"111\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"thu hồi\", \"ranh giới\", \"an toàn\", \"111\", \"đồng ý\", \"công khai\", \"chia sẻ\", \"nài nỉ\"]\r\n}', 5, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1263, 213, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Khi một người bạn online đe dọa sẽ đăng bức ảnh riêng tư của bạn lên mạng nếu bạn không chịu đi chơi riêng, hành động nào sau đây giúp bạn bảo vệ mình hiệu quả nhất?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Im lặng làm theo để họ không đăng ảnh.\", \"correct\": false, \"emoji\": \"🥺\" },\r\n    { \"text\": \"Chụp màn hình bằng chứng, báo ngay cho người lớn đáng tin cậy và gọi tổng đài 111.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Nhờ bạn bè đến đe dọa, đánh trả đũa đối phương.\", \"correct\": false, \"emoji\": \"🛑\" },\r\n    { \"text\": \"Thương lượng đưa tiền cho đối phương để họ xóa ảnh.\", \"correct\": false, \"emoji\": \"😐\" }\r\n  ]\r\n}', 6, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1264, 214, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Né Cờ Đỏ & Kẻ Thao Túng Trên Mạng\'! Bạn có 3 mạng để nhận diện và phòng tránh cờ đỏ độc hại trực tuyến.\"}', 1, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1265, 214, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Đối phó với kẻ thao túng\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Bạn nói chuyện với một người bạn rất hợp gu trên mạng. Người này tự nhận là học sinh trường bên cạnh nhưng tuyệt đối không chịu gọi video call hay gặp mặt trực tiếp, và bắt đầu hỏi xin địa chỉ nhà chi tiết cùng lịch sinh hoạt của bố mẹ bạn. Trực giác bạn thấy có điều gì đó sai sai và bất ổn.\",\r\n      \"choices\": [\r\n        { \"text\": \"Bỏ qua cảm giác lo lắng, cung cấp thông tin vì nghĩ bạn bè trò chuyện thân thiết bấy lâu nay đáng tin.\", \"nextNode\": \"fail_leak\" },\r\n        { \"text\": \"Tin vào trực giác bồn chồn của mình, từ chối chia sẻ thông tin nhạy cảm và tạm dừng trò chuyện để xác minh.\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Chửi bới đối phương là kẻ lừa đảo rồi đi bêu rếu họ trên trang cá nhân.\", \"nextNode\": \"fail_aggressive\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Người đó nhắn tin trách móc, khóc lóc nói bạn nghi ngờ tình bạn chân thành và đe dọa sẽ tự làm đau bản thân nếu bạn không chịu chia sẻ thông tin để chứng minh lòng tin.\",\r\n      \"choices\": [\r\n        { \"text\": \"Nhượng bộ và đưa thông tin vì quá lo lắng đối phương sẽ tự làm hại mình.\", \"nextNode\": \"fail_guilt_concede\" },\r\n        { \"text\": \"Nhận diện đây là hành vi thao túng cảm xúc độc hại (Red Flag), từ chối kiên quyết và báo với bố mẹ hoặc người lớn đáng tin.\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Sau đó, người này đe dọa sẽ tung các tin nhắn tâm sự riêng tư trước đây của bạn lên mạng xã hội để bôi nhọ danh dự của bạn.\",\r\n      \"choices\": [\r\n        { \"text\": \"Im lặng chịu đựng và chấp nhận bị khống chế.\", \"nextNode\": \"fail_blackmail\" },\r\n        { \"text\": \"Chụp bằng chứng đe dọa, chặn tài khoản đó, chia sẻ thật với bố mẹ và thầy cô để cùng tìm phương án giải quyết.\", \"nextNode\": \"success_end\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Hoàn toàn chính xác! Bạn đã bình tĩnh, tin dưỡng trực giác và chủ động tìm kiếm trợ giúp từ gia đình để vô hiệu hóa bẫy thao túng số.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_leak\": {\r\n      \"text\": \"❌ Sai rồi! Cung cấp địa chỉ nhà chi tiết và lịch đi làm của bố mẹ cho người lạ trên mạng là cực kỳ nguy hiểm, mở đường cho trộm cắp hoặc bắt cóc.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_aggressive\": {\r\n      \"text\": \"❌ Chưa đúng! Phản ứng nóng giận chửi bới công khai không bảo vệ an toàn cho bạn mà còn có nguy cơ tạo ra xung đột lớn hơn.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_guilt_concede\": {\r\n      \"text\": \"❌ Sai rồi! Việc đe dọa tự làm đau để ép buộc đối phương là chiêu trò thao túng tâm lý độc hại. Nhượng bộ chỉ khiến bạn lún sâu hơn.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_blackmail\": {\r\n      \"text\": \"❌ Sai rồi! Im lặng thỏa hiệp với kẻ đe dọa bôi nhọ không giải quyết được vấn đề. Bạn cần báo ngay với người lớn để nhận sự bảo vệ.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1266, 214, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại các hành vi ứng xử theo trực giác mách bảo sau:\",\r\n  \"leftBox\": { \"title\": \"Lắng nghe trực giác\" },\r\n  \"rightBox\": { \"title\": \"Phớt lờ cảnh báo\" },\r\n  \"items\": [\r\n    { \"text\": \"Ngừng trò chuyện khi thấy đối phương liên tục hỏi về địa chỉ phòng ngủ\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Cố nhắn tin tiếp dù thấy lo sợ trước câu hỏi riêng tư của họ\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Hỏi ý kiến chị gái khi thấy bạn online đòi gọi video call lúc nửa đêm\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Đồng ý gặp mặt riêng tư người lạ ở công viên vắng dù thấy bồn chồn\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Từ chối cung cấp lịch đi làm của bố mẹ cho tài khoản lạ trên mạng\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1267, 214, 'matching', '{\r\n  \"instruction\": \"Ghép cặp từ khóa ranh giới và định nghĩa dấu hiệu cờ đỏ trực tuyến sau:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Giả mạo danh tính (Catfishing)\", \"right\": \"Lập tài khoản ảo, dùng ảnh người khác để tiếp cận và lừa đảo tình cảm.\" },\r\n    { \"left\": \"Thao túng cảm xúc\", \"right\": \"Đe dọa tự tử hoặc tự làm đau để bắt đối phương nhượng bộ ranh giới.\" },\r\n    { \"left\": \"Kiểm soát số\", \"right\": \"Đòi đọc tin nhắn riêng tư, kiểm tra định vị 24/7 để quản lý.\" },\r\n    { \"left\": \"Trực giác (Gut feeling)\", \"right\": \"Hệ thống cảnh báo sớm của cơ thể khi cảm thấy bất an, sai sai.\" }\r\n  ]\r\n}', 4, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1268, 214, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành định nghĩa cờ đỏ:\",\r\n  \"sentence\": \"Kẻ thao túng trực tuyến thường dùng bẫy [blank1] để bắt bạn nhượng bộ. Hãy luôn tin tưởng vào [blank2] của bản thân. Khi phát hiện các dấu hiệu [blank3], hãy dứt khoát chặn liên lạc và tìm sự [blank4] từ người thân.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"cảm xúc\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"trực giác\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"cờ đỏ\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"hỗ trợ\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"cảm xúc\", \"trực giác\", \"cờ đỏ\", \"hỗ trợ\", \"đồng ý\", \"nài nỉ\", \"giúp đỡ\", \"tin tưởng\"]\r\n}', 5, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1269, 214, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Dấu hiệu nào sau đây là một \'Cờ Đỏ\' rõ ràng nhất của một kẻ muốn lừa đảo hoặc thao túng bạn trên mạng?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Họ trả lời tin nhắn của bạn chậm vì bận học.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Họ vẽ tranh tặng bạn nhân ngày sinh nhật.\", \"correct\": false, \"emoji\": \"💚\" },\r\n    { \"text\": \"Họ liên tục tặng quà ảo giá trị lớn, đòi gửi ảnh cơ thể để chứng minh tình cảm và cấm bạn kể với người khác về họ.\", \"correct\": true, \"emoji\": \"😎\" },\r\n    { \"text\": \"Họ từ chối tham gia các group chat ẩn danh bôi nhọ người khác.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1270, 215, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Công Dân Số Văn Minh: Lan Tỏa Vibes Lành\'! Bạn có 3 mạng để trở thành một Upstander dũng cảm và lan tỏa sự tử tế trực tuyến.\"}', 1, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1271, 215, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Trở thành người bảo vệ Upstander\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Trong group chat chung của lớp học, một nhóm bạn đang đăng ảnh dìm chế giễu cân nặng và ngoại hình của Vy bằng những lời lẽ rất thô lỗ và độc ác. Vy nhắn tin khóc lóc cầu xin mọi người dừng lại nhưng nhóm bạn vẫn tiếp tục chế ảnh cười cợt.\",\r\n      \"choices\": [\r\n        { \"text\": \"Im lặng lờ đi vì sợ lên tiếng sẽ bị cả nhóm quay sang bắt nạt lây.\", \"nextNode\": \"fail_silent\" },\r\n        { \"text\": \"Chủ động nhắn tin vào group lớp yêu cầu mọi người dừng lại một cách lịch sự nhưng kiên quyết.\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Nhảy vào bình luận chửi bới thậm tệ nhóm bạn kia để bênh vực Vy.\", \"nextNode\": \"fail_aggressive\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Nhóm bạn bắt nạt quay sang chế giễu bạn: \'Có mỗi thế cũng căng, đúng là mọt sách thích dạy đời!\'. Vy thấy rất tủi thân và tuyệt vọng.\",\r\n      \"choices\": [\r\n        { \"text\": \"Thấy ngượng và sợ hãi nên im lặng rút lui khỏi cuộc trò chuyện.\", \"nextNode\": \"fail_retreat\" },\r\n        { \"text\": \"Báo cáo bài đăng vi phạm, nhắn tin riêng động viên Vy và báo cáo sự việc cho cô giáo chủ nhiệm.\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Hôm sau, cô giáo gặp nhóm bạn kia và xử lý kỷ luật nghiêm túc. Vy gửi lời cảm ơn bạn vì đã dũng cảm bảo vệ Vy. Bạn muốn cùng Vy lan tỏa văn hóa mạng tích cực trong lớp.\",\r\n      \"choices\": [\r\n        { \"text\": \"Rủ cả lớp cùng lập chiến dịch đăng status chia sẻ các bài vẽ, lời chúc tử tế, tag tên nhau để đẩy lùi drama.\", \"nextNode\": \"success_end\" },\r\n        { \"text\": \"Cùng Vy lập group chat mới loại bỏ nhóm bắt nạt kia ra để nói xấu trả đũa họ.\", \"nextNode\": \"fail_revenge\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Xuất sắc! Bạn đã thực hành vai trò của một công dân số văn minh, dũng cảm lên tiếng đẩy lùi bạo lực mạng và gieo hạt mầm tử tế.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_silent\": {\r\n      \"text\": \"❌ Sai rồi! Im lặng đứng nhìn chính là hành vi gián tiếp dung túng cho bắt nạt trực tuyến và cô lập nạn nhân.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_aggressive\": {\r\n      \"text\": \"❌ Sai rồi! Dùng bạo lực ngôn từ đối đầu với bạo lực mạng chỉ khiến xung đột leo thang và biến chính bạn thành kẻ bắt nạt.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_retreat\": {\r\n      \"text\": \"❌ Sai rồi! Bỏ cuộc giữa chừng dưới áp lực chọc ghẹo của nhóm bắt nạt sẽ làm nạn nhân càng cảm thấy cô đơn, bất lực.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_revenge\": {\r\n      \"text\": \"❌ Sai rồi! Việc lập nhóm nói xấu trả đũa không xây dựng được văn hóa số lành mạnh mà tiếp tục duy trì vòng lặp bắt nạt độc hại.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1272, 215, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại hành vi ứng xử số:\",\r\n  \"leftBox\": { \"title\": \"Gieo hạt mầm tử tế\" },\r\n  \"rightBox\": { \"title\": \"Gieo mầm độc hại\" },\r\n  \"items\": [\r\n    { \"text\": \"Thả tim và bình luận khen ngợi nỗ lực vẽ tranh của bạn cùng lớp\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Móc mỉa, bình phẩm thô lỗ về ngoại hình của người khác dưới bài viết\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Chia sẻ bài viết kêu gọi quyên góp từ thiện có kiểm chứng rõ ràng\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Spam bình luận tục tĩu vào fanpage trường học để câu view\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Nhắn tin hỏi han, động viên khi thấy bạn bè đăng status buồn bã\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1273, 215, 'matching', '{\r\n  \"instruction\": \"Ghép cặp từ khóa ranh giới và định nghĩa công dân số sau:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Bắt nạt trực tuyến\", \"right\": \"Hành vi lặp đi lặp lại nhằm trêu chọc, đe dọa hoặc làm nhục người khác trên mạng.\" },\r\n    { \"left\": \"Người đứng xem (Bystander)\", \"right\": \"Người chứng kiến bạo lực mạng nhưng chọn cách im lặng hoặc hùa theo.\" },\r\n    { \"left\": \"Người bảo vệ (Upstander)\", \"right\": \"Người dũng cảm lên tiếng bảo vệ nạn nhân và báo cáo hành vi bắt nạt.\" },\r\n    { \"left\": \"Văn hóa số lành mạnh\", \"right\": \"Lan tỏa những vibes tích cực, lời nhắn tử tế và hỗ trợ lẫn nhau trực tuyến.\" }\r\n  ]\r\n}', 4, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1274, 215, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành định nghĩa công dân số:\",\r\n  \"sentence\": \"Một công dân số văn minh sẽ không chọn cách làm [blank1] đứng nhìn khi thấy bạn bè bị [blank2] trên mạng. Hãy chủ động [blank3] bài viết vi phạm và lan tỏa sự [blank4] trực tuyến.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"người đứng xem\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"bắt nạt\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"báo cáo\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"tử tế\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"người đứng xem\", \"bắt nạt\", \"báo cáo\", \"tử tế\", \"hùa theo\", \"im lặng\", \"người bảo vệ\", \"đồng ý\"]\r\n}', 5, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1275, 215, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Khi bạn chứng kiến một bạn học cùng lớp bị một nhóm học sinh trường khác đăng bài xúc phạm chế giễu danh dự công khai trên Facebook, hành động nào sau đây thể hiện bạn là một Upstander văn minh?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Chia sẻ bài viết đó về trang cá nhân của mình để mọi người cùng xem.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Nhắn tin riêng động viên bạn học, chụp bằng chứng và báo ngay cho giáo viên hoặc tổng đài 111 để can thiệp.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Nhảy vào phần bình luận thách thức, cãi nhau tay đôi với nhóm bắt nạt.\", \"correct\": false, \"emoji\": \"🛑\" },\r\n    { \"text\": \"Lờ đi coi như không biết vì không phải việc của mình.\", \"correct\": false, \"emoji\": \"🥺\" }\r\n  ]\r\n}', 6, '2026-06-11 17:41:37', '2026-06-11 17:41:37'),
(1276, 216, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Ủa, Sao Dạo Này Tâm Trạng Bão Bùng Quá?\'! Bạn có 3 mạng để đón nhận cảm xúc và làm hòa với ngày low-energy.\"}', 1, '2026-06-11 18:14:46', '2026-06-11 18:14:46');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(1277, 216, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Đón nhận cảm xúc và làm hòa với ngày low-energy\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Vy đi học về trong trạng thái mệt mỏi, uể oải rã rời (low-energy day) sau một tuần thi cử căng thẳng. Vừa bước chân vào nhà, mẹ Vy đã cằn nhằn: \'Sao đi học về không dọn ngay phòng đi, bừa bộn như cái ổ gà!\'. Vy thấy lồng ngực nghẹn lại, cơn giận dữ và bất bình bỗng dưng dâng lên cuồn cuộn.\",\r\n      \"choices\": [\r\n        { \"text\": \"Nổi đóa, hét lên với mẹ: \'Con mệt lắm rồi, mẹ suốt ngày chỉ biết cằn nhằn thôi!\' rồi chạy vào phòng đóng sập cửa.\", \"nextNode\": \"fail_explode\" },\r\n        { \"text\": \"Dừng lại thở sâu 3 giây để hạ nhiệt hạch hạnh nhân, nói nhẹ nhàng: \'Mẹ ơi, hôm nay con đi học về mệt quá. Mẹ cho con nằm nghỉ 30 phút rồi con dậy dọn phòng sạch sẽ nha mẹ!\'.\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Cố kìm nén cơn giận, lẳng lặng đi dọn phòng ngay lập tức với thái độ ấm ức, vừa dọn vừa khóc vì tủi thân.\", \"nextNode\": \"fail_suppress\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Mẹ Vy lắng nghe giọng nói bình tĩnh của bạn, liền dịu giọng xuống và đồng ý: \'Ừ, thế vào nghỉ ngơi đi con\'. Vy vào phòng nằm nghỉ, nhưng trong lòng vẫn còn những suy nghĩ ngổn ngang, bứt rứt vì bài kiểm tra tiếng Anh đạt điểm không như ý.\",\r\n      \"choices\": [\r\n        { \"text\": \"Mở điện thoại lướt mạng xã hội liên tục để trốn tránh cảm giác khó chịu và xem các bạn khác có đăng bài khoe điểm không.\", \"nextNode\": \"fail_avoid\" },\r\n        { \"text\": \"Lấy một cuốn sổ nhỏ, viết tự do tất cả những lo lắng, ấm ức trong đầu ra trang giấy mà không cần câu cú hoàn chỉnh (journaling).\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Sau khi viết nhật ký, Vy thấy đầu óc nhẹ nhõm hẳn. Tuy nhiên, Vy tự hỏi liệu ngày hôm nay năng lượng thấp và buồn bã vô cớ như vậy có phải là mình đang trở nên yếu đuối và tệ hại đi không?\",\r\n      \"choices\": [\r\n        { \"text\": \"Tự nhủ: \'Một ngày low-energy là tín hiệu cơ thể cần sạc pin. Cảm xúc đi xuống cũng bình thường, mình không cần phải luôn hoàn hảo\'.\", \"nextNode\": \"success_end\" },\r\n        { \"text\": \"Tự trách: \'Chắc chắn do mình lười biếng và kém cỏi hơn các bạn nên mới tụt mood thế này, phải cố vui lên mới được!\'.\", \"nextNode\": \"fail_self_blame\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Tuyệt vời! Bạn đã gọi tên cảm xúc thành công, biết cách sạc lại năng lượng cho ngày low-energy và trút bỏ overthinking lành mạnh qua trang viết.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_explode\": {\r\n      \"text\": \"❌ Chưa đúng! Cơn giận bộc phát khiến bạn mất kiểm soát, làm tổn thương mẹ và để lại cảm giác tội lỗi, dằn vặt sau đó.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_suppress\": {\r\n      \"text\": \"❌ Chưa đúng! Đè nén cảm xúc khó chịu và ép bản thân làm việc khi kiệt sức chỉ khiến quả bóng cảm xúc tiêu cực phình to và dễ nổ tung sau đó.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_avoid\": {\r\n      \"text\": \"❌ Sai rồi! Trốn tránh bằng mạng xã hội chỉ mang lại sự xao nhãng tạm thời, nhưng việc so sánh điểm số trên mạng lại dễ kích hoạt overthinking sâu sắc hơn.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_self_blame\": {\r\n      \"text\": \"❌ Sai rồi! Gán nhãn toxic cho nỗi buồn và ép mình luôn tích cực chỉ làm gia tăng sự căng thẳng và từ chối nhu cầu tự nhiên của cơ thể.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1278, 216, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại các phản ứng với cảm xúc tiêu cực:\",\r\n  \"leftBox\": { \"title\": \"Đón nhận cảm xúc lành mạnh\" },\r\n  \"rightBox\": { \"title\": \"Chối bỏ, đè nén hoặc trút giận\" },\r\n  \"items\": [\r\n    { \"text\": \"Cho phép bản thân khóc và buồn khi gặp thất bại\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Cố tỏ ra vui cười, giả vờ ổn để người khác không thấy mình yếu đuối\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Tự viết nhật ký trút hết nỗi tức giận ra giấy rồi xé bỏ\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Cáu gắt và quát mắng em nhỏ để trút bỏ sự bực bội trong lòng\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Tự nhủ: Cảm xúc này là bình thường và nó sẽ trôi qua sau khi mình nghỉ ngơi\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1279, 216, 'matching', '{\r\n  \"instruction\": \"Ghép cặp các khái niệm cảm xúc dậy thì và định nghĩa tương ứng:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Hormone tuổi dậy thì\", \"right\": \"Chất hóa học tăng vọt kích hoạt cảm xúc thất thường như biểu đồ hình sin.\" },\r\n    { \"left\": \"Hạch hạnh nhân - Amygdala\", \"right\": \"Vùng não kiểm soát cảm xúc, hoạt động cực nhạy bén ở tuổi teen.\" },\r\n    { \"left\": \"Nhật ký tự do\", \"right\": \"Nơi trút bầu tâm sự, viết ra mọi suy nghĩ ngổn ngang để dọn dẹp bộ não.\" },\r\n    { \"left\": \"Low-energy days\", \"right\": \"Những ngày năng lượng thấp, cơ thể phát tín hiệu cần được nghỉ ngơi sạc pin.\" }\r\n  ]\r\n}', 4, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1280, 216, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành đoạn văn về cách làm bạn với cảm xúc:\",\r\n  \"sentence\": \"Ở tuổi dậy thì, các [blank1] tăng vọt kích hoạt vùng [blank2] làm bạn nhạy cảm hơn. Khi gặp ngày ít năng lượng, đừng gán nhãn [blank3] cho nỗi buồn, hãy viết [blank4] để giải tỏa overthinking.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"hormone\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"hạch hạnh nhân\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"toxic\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"nhật ký\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"hormone\", \"hạch hạnh nhân\", \"toxic\", \"nhật ký\", \"lười biếng\", \"bất trị\", \"game\", \"tuyệt vọng\"]\r\n}', 5, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1281, 216, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Tại sao việc gọi tên chính xác cảm xúc (ví dụ: \'tớ đang bất an\', \'tớ đang thất vọng\') lại giúp bạn bình tĩnh hơn?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Vì gọi tên cảm xúc sẽ giúp bạn chứng tỏ mình là người am hiểu tâm lý học.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Vì nó gửi tín hiệu giúp não bộ (vùng vỏ não trước trán) kích hoạt khả năng kiểm soát và xoa dịu hạch hạnh nhân ngay lập tức.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Vì nó làm cho cảm xúc tiêu cực biến mất vĩnh viễn không bao giờ quay lại.\", \"correct\": false, \"emoji\": \"🙁\" },\r\n    { \"text\": \"Vì khi nói ra, mọi người xung quanh sẽ lập tức làm theo ý bạn.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1282, 217, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Chữa Lành Tự Ti: Bạn Có Giá Trị Hơn Bạn Tưởng\'! Bạn có 3 mạng để vượt qua bẫy so sánh và xây dựng sự tự tin.\"}', 1, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1283, 217, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Vượt qua bẫy tự ti\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Bạn nhận kết quả kiểm tra Toán giữa kỳ được 3 điểm, trong khi bạn thân ngồi cạnh đạt điểm 9 tuyệt đối. Cảm giác xấu hổ, thất vọng và tự ti dâng tràn. Bạn bắt đầu nghi ngờ năng lực học tập của chính mình.\",\r\n      \"choices\": [\r\n        { \"text\": \"Tự dằn vặt mình: \'Mình là kẻ dốt nát bẩm sinh, học mấy cũng vô dụng thôi!\' rồi ném bài kiểm tra vào góc bàn.\", \"nextNode\": \"fail_self_blame\" },\r\n        { \"text\": \"Nhìn nhận bài thi như một phản hồi (feedback), chúc mừng bạn thân và tự nhủ: \'Lần này mình làm chưa tốt phần hình học, mình sẽ nhờ bạn chỉ bài giúp\'.\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Tỏ vẻ không quan tâm, nói mỉa mai bạn: \'Học giỏi thế sau này đi làm tổng thống à?\' rồi cộc lốc im lặng.\", \"nextNode\": \"fail_sarcasm\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Tối về nhà, bố mẹ lướt xem nhóm Zalo lớp thấy danh sách điểm số và lập tức so sánh: \'Con nhà người ta học hành giỏi giang thế, sao con chỉ được 3 điểm?\'. Cảm giác nghẹn ngực quay lại.\",\r\n      \"choices\": [\r\n        { \"text\": \"Cãi nhau tay đôi với bố mẹ: \'Thế bố mẹ đi mà nhận bạn đó làm con!\' rồi đóng cửa bỏ bữa tối.\", \"nextNode\": \"fail_clash\" },\r\n        { \"text\": \"Lắng nghe với lòng tự trắc ẩn, giải thích lịch sự: \'Con xin lỗi bố mẹ. Bài này con ôn tập chưa kỹ, con đã nhận ra lỗi sai và đang nhờ bạn kèm thêm để thi cuối kỳ tốt hơn ạ\'.\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Vy lướt mạng xã hội Instagram và thấy một người bạn khác liên tục đăng ảnh nhận học bổng tiếng Anh và flexing cuộc sống du lịch sang chảnh. Sự so sánh xã hội trỗi dậy làm bạn thấy tự ti.\",\r\n      \"choices\": [\r\n        { \"text\": \"Tự ti về ngoại hình và hoàn cảnh của mình, quyết định nhịn ăn hoặc trốn tránh không muốn đi học.\", \"nextNode\": \"fail_avoidance\" },\r\n        { \"text\": \"Nhận thức rằng mạng xã hội chỉ là cuốn phim nổi bật của họ, tắt ứng dụng điện thoại và tập trung vào các mục tiêu nhỏ của bản thân.\", \"nextNode\": \"success_end\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Xuất sắc! Bạn đã xây dựng được lòng tự trắc ẩn vững vàng, tách biệt điểm số khỏi giá trị bản thân và vượt qua bẫy so sánh xã hội thông minh.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_self_blame\": {\r\n      \"text\": \"❌ Chưa đúng! Tự dằn vặt bản thân làm triệt tiêu động lực học tập, khiến bạn lún sâu vào chiếc bẫy tự ti độc hại.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_sarcasm\": {\r\n      \"text\": \"❌ Chưa đúng! Mỉa mai thành công của bạn bè chỉ thể hiện sự ghen tị ngầm và làm tổn thương mối quan hệ tốt đẹp.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_clash\": {\r\n      \"text\": \"❌ Sai rồi! Cãi cọ gay gắt với bố mẹ chỉ làm tăng khoảng cách gia đình và khiến tâm trạng của bạn tệ hơn rất nhiều.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_avoidance\": {\r\n      \"text\": \"❌ Sai rồi! Nhịn ăn hoặc bỏ học trốn tránh không giải quyết được vấn đề thực tế, mà còn gây hại nghiêm trọng cho sức khỏe của bạn.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1284, 217, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại các thái độ với bản thân:\",\r\n  \"leftBox\": { \"title\": \"Tự tin lành mạnh\" },\r\n  \"rightBox\": { \"title\": \"Tự ti / Cầu toàn thái quá\" },\r\n  \"items\": [\r\n    { \"text\": \"Chấp nhận bản thân có cả điểm mạnh và điểm yếu\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Mất ngủ cả tuần chỉ vì nói vấp một câu trước lớp\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Coi lỗi sai là cơ hội để học hỏi và rút kinh nghiệm\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Nâng mình lên bằng cách dìm các bạn học kém hơn xuống\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Chào mừng thành công của bạn bè mà không ghen tị\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1285, 217, 'matching', '{\r\n  \"instruction\": \"Ghép cặp từ khóa giá trị bản thân và định nghĩa phù hợp:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Tự tin thực sự\", \"right\": \"Chấp nhận bản thân, không cần lấn lướt hay so sánh với ai.\" },\r\n    { \"left\": \"Lòng tự trắc ẩn\", \"right\": \"Trò chuyện bao dung với chính mình khi gặp thất bại hay sai lầm.\" },\r\n    { \"left\": \"Bẫy so sánh\", \"right\": \"So sánh điểm yếu nhất của mình với điểm mạnh nhất của người khác.\" },\r\n    { \"left\": \"Sự cầu toàn cực đoan\", \"right\": \"Ép buộc bản thân phải hoàn mỹ 100% trong mọi lĩnh vực.\" }\r\n  ]\r\n}', 4, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1286, 217, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành định nghĩa lòng tự trọng:\",\r\n  \"sentence\": \"Điểm số chỉ phản ánh năng lực ở một [blank1], không định nghĩa [blank2] con người bạn. Hãy dùng lời nói [blank3] để trò chuyện với bản thân và tránh chiếc bẫy [blank4] xã hội độc hại.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"thời điểm\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"giá trị\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"bao dung\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"so sánh\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"thời điểm\", \"giá trị\", \"bao dung\", \"so sánh\", \"hoàn hảo\", \"điểm số\", \"tự ti\", \"flexing\"]\r\n}', 5, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1287, 217, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Mục đích thực chất đằng sau hành vi \'flexing\' (khoe khoang) quá đà trên mạng xã hội của một người thường là gì?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Họ thực sự quá hoàn hảo và không có bất kỳ nỗi lo lắng nào.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Họ muốn nhận được sự công nhận từ bên ngoài để khỏa lấp sự bất an, tự ti bên trong.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Họ đang muốn giúp đỡ bạn bè học tập tốt hơn.\", \"correct\": false, \"emoji\": \"🙁\" },\r\n    { \"text\": \"Họ thích thể hiện phong cách sống giản dị, khiêm tốn.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1288, 218, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Hòa Giải Với Chiếc Body: Bạn Đẹp Theo Cách Riêng!\'! Bạn có 3 mạng để tự tin ứng phó body shaming và trân trọng ngoại hình độc bản.\"}', 1, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1289, 218, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Tự tin ứng phó body shaming và yêu thương vóc dáng\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Đức đăng một bức ảnh chụp lúc chơi bóng rổ cùng lớp lên Facebook. Phía dưới phần bình luận, một bạn lớp bên cạnh viết: \'Trông như bộ xương di động/nhái bén ấy nhỉ, học bóng rổ làm gì cho tốn thời gian!\'. Đức thấy mặt nóng bừng, lồng ngực thắt lại vì xấu hổ và tức giận.\",\r\n      \"choices\": [\r\n        { \"text\": \"Bình luận chửi bới lại bạn đó một cách gay gắt để xả giận: \'Nhìn lại gương đi xem mình có ra gì không mà nói người khác!\'.\", \"nextNode\": \"fail_fight\" },\r\n        { \"text\": \"Chụp lại màn hình làm bằng chứng, sau đó ẩn hoặc xóa bình luận khiếm nhã kia đi để bảo vệ không gian cá nhân, tự nhủ: Mình chơi bóng rổ vì sức khỏe của mình chứ không phải để làm vừa mắt họ.\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"U uất xóa luôn bức ảnh bóng rổ, quyết định không đi tập bóng rổ nữa vì sợ bị mọi người chê cười ngoại hình.\", \"nextNode\": \"fail_withdraw\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Mọi việc dần trôi qua, nhưng tuần sau đó, khi cả lớp tập trung ở hành lang, bạn đó lại tiếp tục trêu chọc trực tiếp trước mặt đông người: \'Kìa, bộ xương di động kìa!\'. Mọi người xung quanh đổ dồn ánh mắt vào Đức.\",\r\n      \"choices\": [\r\n        { \"text\": \"Im lặng, cúi gục đầu đi chỗ khác, cố nén nước mắt để không ai thấy mình đang khóc.\", \"nextNode\": \"fail_silent\" },\r\n        { \"text\": \"Nhìn thẳng vào bạn đó, trả lời bình tĩnh và kiên định: \'Tớ tự hào vì cơ thể khỏe mạnh của tớ giúp tớ chạy nhanh và chơi bóng rổ tốt. Tớ mong cậu tôn trọng và không nhận xét ngoại hình của tớ nữa nhé!\'.\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Sau khi Đức thiết lập ranh giới rõ ràng, bạn kia ngượng ngùng im lặng bỏ đi. Cuối ngày, Đức đứng trước gương và nhìn ngắm cơ thể gầy gò của mình, suy nghĩ về việc thay đổi vóc dáng.\",\r\n      \"choices\": [\r\n        { \"text\": \"Quyết định nhịn ăn sáng và uống sữa tăng cơ thần tốc không rõ nguồn gốc để đạt mục tiêu tăng cân nhanh nhất.\", \"nextNode\": \"fail_unhealthy\" },\r\n        { \"text\": \"Tập trung vào chế độ ăn uống đủ chất, tập luyện thể thao vừa sức theo nhịp độ tự nhiên của cơ thể để tăng sự dẻo dai.\", \"nextNode\": \"success_end\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Xuất sắc! Bạn đã bảo vệ bản thân thành công trước body shaming bằng ranh giới kiên định và trân trọng cơ thể theo cách lành mạnh nhất.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_fight\": {\r\n      \"text\": \"❌ Chưa đúng! Cãi vã gay gắt trên mạng chỉ tạo ra một cuộc khẩu chiến toxic, hạ thấp hình ảnh của chính bạn và không giải quyết được vấn đề.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_withdraw\": {\r\n      \"text\": \"❌ Chưa đúng! Bỏ cuộc vì lời chê bai của người khác là bạn đang nhượng bộ kẻ bắt nạt và từ bỏ sở thích lành mạnh giúp cơ thể khỏe mạnh.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_silent\": {\r\n      \"text\": \"❌ Sai rồi! Im lặng cam chịu không giúp thiết lập ranh giới, kẻ trêu chọc sẽ nghĩ bạn dễ bắt nạt và có thể tiếp tục hành vi body shaming này.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_unhealthy\": {\r\n      \"text\": \"❌ Sai rồi! Sử dụng các biện pháp tăng cơ/giảm cân cực đoan gây hại nghiêm trọng cho các cơ quan nội tạng và sự phát triển sinh học của tuổi dậy thì.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1290, 218, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại các thái độ đối với vóc dáng cơ thể:\",\r\n  \"leftBox\": { \"title\": \"Yêu thương cơ thể\" },\r\n  \"rightBox\": { \"title\": \"Ngược đãi hoặc phán xét\" },\r\n  \"items\": [\r\n    { \"text\": \"Uống đủ nước và vận động vừa sức giúp cơ thể dẻo dai\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Nhịn ăn bỏ bữa để nhanh chóng có vòng eo con kiến\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Tự nhủ: Chiếc mũi tẹt thừa hưởng từ bố mẹ là nét độc bản đáng yêu\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Soi gương liên tục và dằn vặt bản thân vì không có cơ bắp vạm vỡ\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Nhận xét khiếm nhã về cân nặng của bạn học dưới danh nghĩa đùa vui\", \"correctBox\": \"right\" }\r\n  ]\r\n}', 3, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1291, 218, 'matching', '{\r\n  \"instruction\": \"Ghép cặp từ khóa về ngoại hình và định nghĩa phù hợp:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Filter ảo ma\", \"right\": \"Hình ảnh chỉnh sửa kỹ thuật số tạo nên tiêu chuẩn sắc đẹp phi thực tế.\" },\r\n    { \"left\": \"Body shaming\", \"right\": \"Hành vi chê bai, giễu cợt ngoại hình gây tổn thương tinh thần người khác.\" },\r\n    { \"left\": \"Đa dạng vóc dáng\", \"right\": \"Sự thật sinh học rằng gen quyết định mỗi cơ thể có cấu trúc khác nhau.\" },\r\n    { \"left\": \"Lòng biết ơn cơ thể\", \"right\": \"Trân trọng chức năng sinh học giữ cho ta sống khỏe mạnh 24/7.\" }\r\n  ]\r\n}', 4, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1292, 218, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành định nghĩa yêu thương cơ thể:\",\r\n  \"sentence\": \"Mạng xã hội thường trưng bày những hình ảnh đã qua [blank1], hãy trân trọng cơ thể thực của mình. Khi bị [blank2] ngoại hình, hãy kiên định thiết lập [blank3] và tập trung nuôi dưỡng cơ thể [blank4] thay vì chạy theo khuôn mẫu.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"chỉnh sửa\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"chê bai\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"ranh giới\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"khỏe mạnh\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"chỉnh sửa\", \"chê bai\", \"ranh giới\", \"khỏe mạnh\", \"filter\", \"nhịn ăn\", \"chất lượng\", \"cụt ngủn\"]\r\n}', 5, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1293, 218, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Tại sao việc so sánh ngoại hình của bạn với các hot teen trên mạng xã hội lại không công bằng?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Vì họ ở thành phố lớn còn bạn ở nông thôn hoặc tỉnh lẻ.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Vì hình ảnh của họ đã được chọn lọc từ hàng trăm tấm, chỉnh sửa góc sáng, kéo chân và dùng filter ảo ma, khác xa thực tế.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Vì họ được trả tiền để chụp ảnh đẹp còn bạn thì không.\", \"correct\": false, \"emoji\": \"🙁\" },\r\n    { \"text\": \"Vì cơ thể của họ được cấu tạo từ các tế bào sinh học đặc biệt hơn bạn.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1294, 219, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Khi Áp Lực Đè Nặng: Giải Cứu Bộ Não Quá Tải\'! Bạn có 3 mạng để vượt qua stress thi cử và quản lý lo âu hiệu quả.\"}', 1, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1295, 219, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Giải cứu bộ não quá tải\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Tuần tới bạn có 3 bài thi học kỳ dồn dập. Bạn bắt đầu thấy đau bụng âm ỉ, mỏi vai gáy và tối nằm trằn trọc mãi không ngủ được. Sự lo lắng khổng lồ đè nặng khiến bạn không muốn chạm tay vào sách vở.\",\r\n      \"choices\": [\r\n        { \"text\": \"Mở game cày rank hoặc lướt TikTok suốt 5 tiếng liên tục để tạm quên đi đống bài tập cần học.\", \"nextNode\": \"fail_avoid\" },\r\n        { \"text\": \"Chấp nhận đây là stress thi cử, viết danh sách bài vở cần học, chia nhỏ nhiệm vụ và học theo phương pháp Pomodoro.\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Thức xuyên đêm đến 4h sáng nhồi nhét hết kiến thức và uống liên tiếp 2 lon nước tăng lực.\", \"nextNode\": \"fail_overwork\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Sáng ngày thi, vừa bước vào phòng thi, bạn thấy tim đập thình thịch, tay run rẩy, mồ hôi vã ra và đầu óc bỗng dưng trống rỗng, đóng băng hoàn toàn trước đề bài.\",\r\n      \"choices\": [\r\n        { \"text\": \"Hoảng loạn gục mặt xuống bàn tự trách mình học nhiều mà vẫn vô dụng.\", \"nextNode\": \"fail_freeze\" },\r\n        { \"text\": \"Nhắm mắt lại, đặt tay lên bụng, thực hiện 3 chu kỳ thở sâu 4-7-8 để làm chậm nhịp tim và sạc oxy cho não.\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Sau khi thi xong, mặc dù bài thi làm khá tốt nhưng bạn vẫn thấy căng thẳng tích tụ. Bạn cần mở chiếc \'van xả stress\' để phục hồi năng lượng.\",\r\n      \"choices\": [\r\n        { \"text\": \"Ăn một lúc 3 gói mì cay và uống nước ngọt có ga cho bõ tức.\", \"nextNode\": \"fail_unhealthy_vent\" },\r\n        { \"text\": \"Đi tắm nước ấm, vận động nhẹ nhàng ngoài công viên hoặc nghe một bản nhạc nhẹ yêu thích để xả bớt áp suất.\", \"nextNode\": \"success_end\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Hoàn toàn chính xác! Bạn đã đối mặt với stress chủ động, bình tĩnh vượt qua khoảnh khắc đóng băng bằng kỹ thuật thở 4-7-8 và xả stress lành mạnh.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_avoid\": {\r\n      \"text\": \"❌ Chưa đúng! Lảng tránh thụ động bằng game chỉ mang lại cảm giác an tâm tạm thời, nhưng vấn đề vẫn còn nguyên và stress sẽ dội lại mạnh mẽ hơn.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_overwork\": {\r\n      \"text\": \"❌ Chưa đúng! Thức trắng đêm nhồi nhét kết hợp lạm dụng nước tăng lực sẽ tàn phá thể chất, khiến bộ não dễ bị \'đóng băng\' khi thi.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_freeze\": {\r\n      \"text\": \"❌ Sai rồi! Hoảng loạn tinh thần chỉ làm gián đoạn hệ tư duy của não bộ. Bạn cần bài tập thở sâu vật lý để lập tức hạ nhiệt.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_unhealthy_vent\": {\r\n      \"text\": \"❌ Sai rồi! Xả stress bằng đồ ăn cay nóng, đồ ăn nhanh chỉ làm quá tải hệ tiêu hóa và không giải quyết được căng thẳng tinh thần.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1296, 219, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại các phản ứng ứng phó áp lực:\",\r\n  \"leftBox\": { \"title\": \"Đối mặt chủ động\" },\r\n  \"rightBox\": { \"title\": \"Trốn tránh thụ động\" },\r\n  \"items\": [\r\n    { \"text\": \"Viết danh sách các việc cần làm và thực hiện việc nhỏ trước\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Nằm lướt TikTok liên tục để không phải nghĩ về bài tập\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Nhờ bạn bè hoặc giáo viên chỉ dẫn phần bài tập quá khó\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Cố học tiếp dù đầu đang nhức búa bổ vì sợ điểm kém\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Dành 10 phút đi bộ thư giãn ngoài vườn sạc pin tâm hồn\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1297, 219, 'matching', '{\r\n  \"instruction\": \"Ghép cặp từ khóa stress và định nghĩa phù hợp:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Adrenaline & Cortisol\", \"right\": \"Hormone được giải phóng khi cơ thể gặp trạng thái căng thẳng, lo âu.\" },\r\n    { \"left\": \"Stress tích cực (Eustress)\", \"right\": \"Áp lực vừa phải giúp tập trung hơn để hoàn thành mục tiêu ngắn hạn.\" },\r\n    { \"left\": \"Stress độc hại (Distress)\", \"right\": \"Sự căng thẳng kéo dài liên tục gây kiệt quệ tinh thần và thể chất.\" },\r\n    { \"left\": \"Kỹ thuật thở 4-7-8\", \"right\": \"Bài tập điều hòa nhịp thở kích hoạt hệ thần kinh đối giao cảm làm dịu não bộ.\" }\r\n  ]\r\n}', 4, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1298, 219, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành định nghĩa ứng phó stress:\",\r\n  \"sentence\": \"Stress không chỉ ở trong đầu mà còn biểu hiện qua các tín hiệu [blank1] của cơ thể. Đừng lảng tránh bằng game, hãy [blank2] chia nhỏ công việc và sử dụng những chiếc [blank3] lành mạnh để [blank4] bớt áp lực.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"thể chất\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"chủ động\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"van xả\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"giải phóng\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"thể chất\", \"chủ động\", \"van xả\", \"giải phóng\", \"lơ đi\", \"im lặng\", \"nước ngọt\", \"lười biếng\"]\r\n}', 5, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1299, 219, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Tại sao việc sử dụng nước tăng lực và thức xuyên đêm ôn thi là cờ đỏ nguy hiểm cho kết quả thi cử?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Vì nó làm cho bạn thông minh hơn đột xuất và gây ra kiêu ngạo.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Vì nó gây thiếu ngủ nghiêm trọng và làm tăng nồng độ cortisol, khiến bộ não dễ bị trống rỗng khi vào phòng thi.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Vì nó khiến bạn làm bài thi quá nhanh mà không kịp soát lỗi.\", \"correct\": false, \"emoji\": \"🙁\" },\r\n    { \"text\": \"Vì giáo viên sẽ trừ điểm nếu phát hiện học sinh thức khuya.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1300, 220, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Khi Crush Từ Chối: Vượt Qua Bể Sầu Cực Mượt\'! Bạn có 3 mạng để tôi luyện sức bật cảm xúc sau thất bại tình cảm.\"}', 1, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1301, 220, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Vượt qua bể sầu tỏ tình\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Bạn lấy hết dũng khí tỏ tình với crush bằng một món quà nhỏ ở công viên. Đối phương ngập ngừng rồi nói lời từ chối: \'Cảm ơn cậu, nhưng tớ chỉ muốn tụi mình là bạn tốt thôi!\'. Mặt bạn nóng bừng, tai lùng bùng và lồng ngực đau nhói thực tế.\",\r\n      \"choices\": [\r\n        { \"text\": \"Nài nỉ tiếp: \'Cho tớ cơ hội đi, tớ sẽ làm mọi thứ vì cậu mà!\'\", \"nextNode\": \"fail_beg\" },\r\n        { \"text\": \"Mỉm cười nhẹ, chấp nhận ranh giới: \'Tớ hiểu rồi, cảm ơn cậu đã chia sẻ thẳng thắn nhé. Tớ hơi buồn chút nhưng tớ tôn trọng quyết định của cậu\'.\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Nổi giận đùng đùng, ném món quà đi và mắng: \'Cậu sống lạnh lùng thế, sau này đừng chơi với nhau nữa!\'\", \"nextNode\": \"fail_furious\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Tối về nhà, cảm giác thất tình làm bạn buồn bã tột cùng. Bạn thấy mình liên tục muốn mở trang cá nhân của họ lên xem họ có đăng bài viết mới nào không, lòng cồn cào bất an.\",\r\n      \"choices\": [\r\n        { \"text\": \"Tiếp tục ẩn danh theo dõi từng lượt like, thả tim của họ trên Instagram để tìm kiếm manh mối.\", \"nextNode\": \"fail_stalk\" },\r\n        { \"text\": \"Ẩn tạm thời trang cá nhân của họ, cất các món quà gợi nhớ và rủ hội bạn thân đi ăn kem, xem phim để F5 tâm trạng.\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Ba tháng sau, bạn nhìn thấy crush cũ đang đi chơi vui vẻ với một người bạn khác. Cảm xúc nhói nhẹ trỗi dậy, bạn tự hỏi trải nghiệm này có ý nghĩa gì với con người bạn.\",\r\n      \"choices\": [\r\n        { \"text\": \"Tự dằn vặt: \'Chắc chắn do mình xấu xí và kém cỏi nên mới bị bỏ rơi. Mình sẽ không bao giờ mở lòng nữa!\'\", \"nextNode\": \"fail_cynical\" },\r\n        { \"text\": \"Nhận ra đây là trải nghiệm dũng cảm giúp mình biết cách bày tỏ cảm xúc, tôn trọng ranh giới và vững vàng đứng lên.\", \"nextNode\": \"success_end\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Hoàn toàn chính xác! Bạn đã phục hồi cảm xúc cực kỳ kiên cường, ứng xử văn minh khi bị từ chối và khơi dậy lòng dũng cảm tự hào.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_beg\": {\r\n      \"text\": \"❌ Chưa đúng! Nài nỉ bám đuôi khi đối phương đã từ chối là thiếu tôn trọng ranh giới của họ và hạ thấp lòng tự trọng của chính bạn.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_furious\": {\r\n      \"text\": \"❌ Chưa đúng! Nổi giận chửi bới đối phương khi bị từ chối chỉ thể hiện sự ích kỷ và thiếu chín chắn trong kiểm soát cảm xúc.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_stalk\": {\r\n      \"text\": \"❌ Sai rồi! Việc âm thầm theo dõi (stalk) trang cá nhân liên tục chỉ làm kéo dài nỗi đau thất tình và khiến bạn khó phục hồi.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_cynical\": {\r\n      \"text\": \"❌ Sai rồi! Trải nghiệm từ chối chỉ chứng minh hai người chưa phù hợp, không làm giảm đi giá trị tổng thể của con người bạn.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1302, 220, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại các suy nghĩ phục hồi sau thất tình:\",\r\n  \"leftBox\": { \"title\": \"Bài học trưởng thành\" },\r\n  \"rightBox\": { \"title\": \"Tiêu cực tự ti\" },\r\n  \"items\": [\r\n    { \"text\": \"Bị từ chối nghĩa là hai người chưa phù hợp ở thời điểm này\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Bị từ chối chứng tỏ mình là kẻ kém cỏi và không ai yêu\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Đối phương có quyền tự do lựa chọn tình cảm của họ\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Mình sẽ không bao giờ mở lòng yêu thương hay tin tưởng ai nữa\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Mình biết cách bày tỏ cảm xúc thật của mình một cách dũng cảm\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1303, 220, 'matching', '{\r\n  \"instruction\": \"Ghép cặp từ khóa phục hồi cảm xúc và định nghĩa phù hợp:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Resilience (Sức bật)\", \"right\": \"Khả năng đối mặt với thất bại cảm xúc và tự chữa lành đứng dậy.\" },\r\n    { \"left\": \"Dopamine\", \"right\": \"Hormone tạo cảm giác phấn khích, cồn cào khi say nắng crush.\" },\r\n    { \"left\": \"Tình cảm một chiều\", \"right\": \"Tình cảm chỉ xuất phát từ một phía, thiếu sự tương tác hai chiều.\" },\r\n    { \"left\": \"Từ chối văn minh\", \"right\": \"Chia sẻ thẳng thắn sự từ chối đi kèm sự tôn trọng cảm xúc đối phương.\" }\r\n  ]\r\n}', 4, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1304, 220, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành định nghĩa phục hồi sau từ chối:\",\r\n  \"sentence\": \"Sự từ chối kích hoạt vùng não xử lý nỗi đau [blank1] thực tế. Hãy tập cách chấp nhận và [blank2] ranh giới của họ. Cất đi những món quà cũ giúp bạn [blank3] tâm trạng và rèn luyện sức bật [blank4] cảm xúc kiên cường.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"thể xác\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"tôn trọng\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"F5\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"cảm xúc\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"thể xác\", \"tôn trọng\", \"F5\", \"cảm xúc\", \"nài nỉ\", \"stalk\", \"lo sợ\", \"tự ti\"]\r\n}', 5, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1305, 220, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Hành động nào sau đây giúp bạn phục hồi nhanh nhất sau khi bị crush từ chối lời tỏ tình?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Đăng những bài viết buồn bã, oán trách lấp lửng để crush thấy tội lỗi.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Chấp nhận nỗi buồn trong vài ngày, ẩn thông báo từ crush, cất kỷ vật cũ và tập trung vào các thói quen tốt cùng bạn bè thân thiết.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Lập tức tìm một người khác thế chỗ để chứng minh mình vẫn có giá trị.\", \"correct\": false, \"emoji\": \"🙁\" },\r\n    { \"text\": \"Ngồi học liên tục 12 tiếng để không còn thời gian suy nghĩ.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1306, 221, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Mối Quan Hệ Chất Lượng Cao Vs Độc Hại\'! Bạn có 3 mạng để nhận diện cờ đỏ thao túng và bảo vệ ranh giới tình bạn.\"}', 1, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1307, 221, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Nhận diện và thoát khỏi thao túng\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Bạn mượn điện thoại của bạn thân để gọi nhờ. Khi bạn trả lại, bạn thân nổi giận đùng đùng, giật lấy máy và quát: \'Sao cậu lại mở Zalo đọc tin nhắn của tớ? Cậu tò mò quá đáng thế!\'. Dù bạn hoàn toàn không đọc gì, đối phương liên tục dùng \'chiến tranh lạnh\' bắt bạn xin lỗi.\",\r\n      \"choices\": [\r\n        { \"text\": \"Chấp nhận nhận lỗi và liên tục xin lỗi để xoa dịu cơn giận của bạn: \'Tớ xin lỗi, tớ hứa lần sau sẽ không chạm vào máy cậu nữa\'.\", \"nextNode\": \"fail_accept_guilt\" },\r\n        { \"text\": \"Bình tĩnh khẳng định ranh giới: \'Tớ chỉ dùng máy gọi điện và không hề mở tin nhắn. Tớ tôn trọng sự riêng tư của cậu và mong cậu cũng tin tưởng tớ\'.\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Nổi khùng mắng lại bạn thân là kẻ đa nghi, ích kỷ rồi đi nói xấu họ với các bạn khác trong lớp.\", \"nextNode\": \"fail_aggressive\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Hôm sau, bạn thân đòi bạn phải chia sẻ mật khẩu tài khoản Instagram để chứng minh lòng trung thực và bắt bạn xóa bớt danh sách bạn bè khác giới đi vì \'yêu thương và lo lắng cho bạn\'.\",\r\n      \"choices\": [\r\n        { \"text\": \"Nhượng bộ đưa mật khẩu và xóa bạn bè vì sợ bị cô lập khỏi nhóm bạn chơi chung.\", \"nextNode\": \"fail_concede\" },\r\n        { \"text\": \"Nhận diện đây là cờ đỏ kiểm soát số, kiên quyết từ chối: \'Tớ muốn giữ mật khẩu và bạn bè làm không gian riêng tư. Tụi mình tin tưởng nhau bằng hành động nhé!\'.\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Sau đó, nhóm bạn thân bắt đầu lập nhóm chat riêng để cô lập, đăng ảnh chế giễu bạn và nhắn tin đe dọa tung các bí mật cá nhân của hai đứa trước đây lên diễn đàn trường. Bạn thấy quá tải cảm xúc và lo sợ tột cùng.\",\r\n      \"choices\": [\r\n        { \"text\": \"Im lặng chịu đựng, cắn răng làm theo các yêu cầu nhạy cảm của họ để giữ bí mật.\", \"nextNode\": \"fail_blackmail\" },\r\n        { \"text\": \"Chụp màn hình bằng chứng, báo ngay cho bố mẹ hoặc thầy cô giáo y tế học đường, và gọi tổng đài 111 để nhận sự che chở pháp lý.\", \"nextNode\": \"success_end\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Xuất sắc! Bạn đã dũng cảm nhận diện cờ đỏ thao túng cảm xúc, kiên định bảo vệ ranh giới số và tìm kiếm sự hỗ trợ khẩn cấp từ người lớn kịp thời.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_accept_guilt\": {\r\n      \"text\": \"❌ Chưa đúng! Nhận tội khống để xoa dịu kẻ thao túng (gaslighting) chỉ khiến họ tiếp tục kiểm soát tâm lý và lấn lướt ranh giới của bạn trong tương lai.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_aggressive\": {\r\n      \"text\": \"❌ Chưa đúng! Công kích lại đối phương và đi nói xấu sau lưng không giải quyết được mâu thuẫn mà còn biến bạn thành kẻ bắt nạt cảm xúc.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_concede\": {\r\n      \"text\": \"❌ Sai rồi! Bàn giao mật khẩu cá nhân và xóa bạn bè theo yêu cầu vô lý là tự nguyện chui vào bẫy kiểm soát độc hại.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_blackmail\": {\r\n      \"text\": \"❌ Sai rồi! Thỏa hiệp với kẻ tống tiền bôi nhọ không mang lại sự an toàn. Hãy chụp bằng chứng và báo cáo ngay cho người lớn.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1308, 221, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại các cờ hiệu tình bạn:\",\r\n  \"leftBox\": { \"title\": \"Cờ xanh Green Flag\" },\r\n  \"rightBox\": { \"title\": \"Cờ đỏ Red Flag\" },\r\n  \"items\": [\r\n    { \"text\": \"Lắng nghe không phán xét, tôn trọng ranh giới cá nhân\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Dùng sự im lặng, chiến tranh lạnh để trừng phạt khi bạn làm trái ý\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Biết nói lời xin lỗi chân thành khi làm tổn thương bạn\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Thường xuyên chê bai ngoại hình và nói xấu sau lưng bạn\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Vui mừng và ủng hộ ước mơ, thành công của bạn\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1309, 221, 'matching', '{\r\n  \"instruction\": \"Ghép cặp từ khóa mối quan hệ và định nghĩa phù hợp:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Gaslighting (Thao túng)\", \"right\": \"Hành vi làm đối phương nghi ngờ suy nghĩ, cảm xúc và trí nhớ của chính mình.\" },\r\n    { \"left\": \"Vulnerability (Tổn thương)\", \"right\": \"Dũng khí cởi bỏ áo giáp để chia sẻ thật lòng lo âu với người đáng tin.\" },\r\n    { \"left\": \"Mạng lưới hỗ trợ\", \"right\": \"Tấm đệm an toàn gồm gia đình, thầy cô, chuyên gia giúp giảm chấn thương cuộc sống.\" },\r\n    { \"left\": \"Tổng đài 111\", \"right\": \"Đường dây nóng quốc gia hỗ trợ, tư vấn và bảo vệ trẻ em Việt Nam 24/7.\" }\r\n  ]\r\n}', 4, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1310, 221, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành định nghĩa mối quan hệ lành mạnh:\",\r\n  \"sentence\": \"Tình bạn lành mạnh tôn trọng ranh giới và không bắt bạn phải [blank1] gánh vác mọi lo âu. Khi gặp kẻ [blank2] cảm xúc, hãy dũng cảm thiết lập khoảng cách và tìm kiếm sự giúp đỡ từ những [blank3] đáng tin cậy hoặc gọi tổng đài [blank4].\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"âm thầm\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"thao túng\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"đồng minh\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"111\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"âm thầm\", \"thao túng\", \"đồng minh\", \"111\", \"xin lỗi\", \"im lặng\", \"nể sợ\", \"bạn thân\"]\r\n}', 5, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1311, 221, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Khi bạn thân của bạn liên tục dùng chiêu trò \'chiến tranh lạnh\' (im lặng không rep tin nhắn) để ép bạn phải đi chơi chung khi bạn đang mệt, phản ứng nào thể hiện sự tự chủ nhất?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Nhắn tin năn nỉ, xin lỗi dồn dập để họ hết giận.\", \"correct\": false, \"emoji\": \"🥺\" },\r\n    { \"text\": \"Giữ vững ranh giới: \'Tớ mệt cần nghỉ ngơi. Khi nào cậu sẵn sàng nói chuyện bình thường thì tụi mình chat nhé\' và không nhắn tin ép họ.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Lập tức chặn liên lạc và unfriend họ vĩnh viễn.\", \"correct\": false, \"emoji\": \"🛑\" },\r\n    { \"text\": \"Nhờ các bạn khác vào group chat để nói móc mỉa họ.\", \"correct\": false, \"emoji\": \"😐\" }\r\n  ]\r\n}', 6, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1312, 222, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Yêu Bản Thân: Không Chỉ Là Câu Nói Bắt Trend\'! Bạn có 3 mạng để thực hành tự chăm sóc lành mạnh và thiết lập ranh giới nói không.\"}', 1, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1313, 222, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Thực hành self-care và nói Không\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Tối muộn trước ngày thi học kỳ quan trọng, bạn đã rất mệt và muốn đi ngủ sớm lúc 10h30 để giữ sức khỏe. Bỗng nhiên, nhóm bạn thân liên tục gọi điện, nhắn tin trong group chat lớp rủ bạn vào game cày rank cùng để lấy thành tích chung.\",\r\n      \"choices\": [\r\n        { \"text\": \"Nể bạn bè, cố online chơi cùng đến 1h sáng dù mắt nhắm mắt mở mệt mỏi.\", \"nextNode\": \"fail_pleaser\" },\r\n        { \"text\": \"Nhắn tin từ chối lịch sự, kiên định: \'Tớ thèm chơi cùng quá nhưng tối nay tớ muốn ngủ sớm để mai làm bài tốt. Thi xong tụi mình cày bù nhé!\' rồi off điện thoại đi ngủ.\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Tắt nguồn điện thoại đi ngủ mà không nói một lời nào với nhóm bạn.\", \"nextNode\": \"fail_silent_cut\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Sáng hôm sau đi thi, bạn làm bài rất tỉnh táo. Tuy nhiên, buổi trưa lúc ăn cơm, nhóm bạn giận dỗi trách móc: \'Có mỗi thế cũng từ chối, đúng là đồ phá đám mất hết cả hứng của nhóm!\'. Bạn thấy trong lòng dâng lên cảm giác có lỗi và áy náy.\",\r\n      \"choices\": [\r\n        { \"text\": \"Vội vàng hứa hẹn bù đắp: \'Tối nay tớ hứa sẽ online chơi bù cùng các cậu suốt đêm nhé!\' để họ hết giận.\", \"nextNode\": \"fail_compromise\" },\r\n        { \"text\": \"Chấp nhận cảm giác áy náy ngắn hạn, tự giải thích nhẹ nhàng: \'Tớ tôn trọng việc leo rank nhưng sức khỏe ngày thi quan trọng hơn với tớ mà. Mong các cậu thông cảm nha!\'\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Cuối tuần đến, bạn muốn thực hành tự chăm sóc (self-care) tâm hồn. Bạn muốn lập một kế hoạch thói quen nhỏ khả thi lâu dài để nâng cấp cuộc sống.\",\r\n      \"choices\": [\r\n        { \"text\": \"Đặt mục tiêu mỗi tối đọc 2 trang sách và đi ngủ trước 11h đêm đều đặn mỗi ngày.\", \"nextNode\": \"success_end\" },\r\n        { \"text\": \"Lập lịch trình học tập hà khắc liên tục 12 tiếng một ngày và nhịn ăn tối để giảm cân ngay lập tức.\", \"nextNode\": \"fail_unrealistic\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Hoàn toàn chính xác! Bạn đã thực hành nghệ thuật từ chối kiên định để bảo vệ năng lượng bản thân, vượt qua áp lực làm hài lòng đám đông và thiết lập thói quen nhỏ bền vững.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_pleaser\": {\r\n      \"text\": \"❌ Chưa đúng! Nhượng bộ áp lực nhóm (people-pleasing) làm tổn hại nghiêm trọng đến giấc ngủ và kết quả thi cử của bạn ngày hôm sau.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_silent_cut\": {\r\n      \"text\": \"❌ Chưa đúng! Im lặng cắt đứt liên lạc đột ngột dễ gây hiểu lầm là bạn khinh khỉnh hoặc vô trách nhiệm. Một lời từ chối thẳng thắn, rõ ràng luôn tốt hơn.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_compromise\": {\r\n      \"text\": \"❌ Sai rồi! Nhượng bộ thức đêm cày bù chỉ làm kiệt quệ thể chất và chứng tỏ bạn không tôn trọng ranh giới sức khỏe của chính mình.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_unrealistic\": {\r\n      \"text\": \"❌ Sai rồi! Lập kế hoạch quá tải, hà khắc đột ngột chỉ khiến bộ não phản kháng và bỏ cuộc nhanh chóng, không đem lại sự phát triển bền vững.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1314, 222, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại các hoạt động tự chăm sóc:\",\r\n  \"leftBox\": { \"title\": \"Self-care đích thực\" },\r\n  \"rightBox\": { \"title\": \"Shopping / Trốn chạy nhất thời\" },\r\n  \"items\": [\r\n    { \"text\": \"Ngủ đúng giờ và uống đủ nước mỗi ngày\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Nạp thật nhiều trà sữa và thức ăn nhanh để xoa dịu nỗi buồn\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Đọc 2 trang sách hoặc đi bộ 10 phút sạc pin tinh thần\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Đi mua sắm vô tội vạ những món đồ đắt tiền để giải tỏa áp lực\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Từ chối lời rủ rê đi chơi muộn khi cơ thể đang kiệt sức\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1315, 222, 'matching', '{\r\n  \"instruction\": \"Ghép cặp từ khóa tự chăm sóc và định nghĩa phù hợp:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Self-care (Tự chăm sóc)\", \"right\": \"Những thói quen nhỏ giúp bảo vệ sức khỏe sinh học và tinh thần lâu dài.\" },\r\n    { \"left\": \"People-pleasing\", \"right\": \"Hội chứng luôn cố nói Có để làm hài lòng người khác vì sợ bị ghét.\" },\r\n    { \"left\": \"Nghỉ ngơi tích cực\", \"right\": \"Nhu cầu sinh học tối thiểu giúp các tế bào thần kinh phục hồi và tái tạo.\" },\r\n    { \"left\": \"Thói quen siêu nhỏ\", \"right\": \"Cải tiến 1% mỗi ngày giúp vượt qua sự phản kháng của não bộ.\" }\r\n  ]\r\n}', 4, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1316, 222, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành định nghĩa tự yêu thương:\",\r\n  \"sentence\": \"Tự chăm sóc bản thân không phải là hành vi [blank1], nó là nhu cầu sinh học tối thiểu. Hãy học cách nói [blank2] với người khác để nói [blank3] với sức khỏe của mình, và kiên trì rèn luyện các thói quen [blank4] mỗi ngày.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"ích kỷ\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"Không\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"Có\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"siêu nhỏ\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"ích kỷ\", \"Không\", \"Có\", \"siêu nhỏ\", \"lười biếng\", \"shopping\", \"ép buộc\", \"im lặng\"]\r\n}', 5, '2026-06-11 18:14:46', '2026-06-11 18:14:46'),
(1317, 222, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Tại sao các mục tiêu thói quen siêu nhỏ (như đọc 2 trang sách, tập thể dục 5 phút) lại đem lại sự phát triển bền vững hơn các kế hoạch thay đổi to lớn?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Vì mục tiêu nhỏ giúp bạn nhận được nhiều lời khen ngợi từ mọi người.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Vì chúng dễ dàng thực hiện, không kích hoạt hệ thống phản kháng của bộ não và giúp xây dựng đường liên kết thần kinh bền vững.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Vì các thói quen lớn tốn quá ít thời gian của bạn.\", \"correct\": false, \"emoji\": \"🙁\" },\r\n    { \"text\": \"Vì thói quen nhỏ không đòi hỏi bạn phải đầu tư bất kỳ nỗ lực nào.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 18:14:46', '2026-06-11 18:14:46');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(1318, 223, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Dậy Thì Là Gì? Khi Cơ Thể Rục Rịch Thay Đổi!\'! Bạn có 3 mạng để tự tin khám phá những thay đổi cơ thể đầu đời.\"}', 1, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1319, 223, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Tự tin bước qua những bỡ ngỡ dậy thì\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Linh bắt đầu nhận thấy vùng ngực của mình hơi nhức và nhú nhọn lên dưới lớp áo phông đồng phục. Đi học, Linh cảm giác như một vài bạn nam đang nhìn chằm chằm và thì thầm trêu chọc mình, khiến cô bé vô cùng ngại ngùng, bối rối và chỉ muốn khóc.\",\r\n      \"choices\": [\r\n        { \"text\": \"Nhượng bộ sự xấu hổ, im lặng chịu đựng cơn đau và mặc các áo rộng thùng thình để che giấu cơ thể.\", \"nextNode\": \"fail_suppress\" },\r\n        { \"text\": \"Nhắn tin nhỏ cho mẹ hoặc nói chuyện riêng: \'Mẹ ơi, ngực con dạo này hơi đau và nhú lên rồi. Mẹ mua giúp con chiếc áo lót đầu tiên nha mẹ!\'\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Tự ý lấy tiền tiết kiệm mua đại áo ngực chật ních trên mạng không vừa kích cỡ về mặc mà không hỏi ý kiến ai.\", \"nextNode\": \"fail_uninformed\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Mẹ Linh mỉm cười xoa đầu dắt Linh đi mua chiếc áo lót phù hợp. Tuần sau đó, trong giờ ra chơi ở lớp, một nhóm bạn nam trêu chọc giọng nói ồm ồm đang vỡ của Tuấn, khiến cậu đỏ bừng mặt và cúi gục xuống bàn.\",\r\n      \"choices\": [\r\n        { \"text\": \"Hùa theo nhóm bạn nam trêu Tuấn để chứng tỏ mình hòa đồng và sành sỏi.\", \"nextNode\": \"fail_peer\" },\r\n        { \"text\": \"Thể hiện vai trò đồng minh đáng tin cậy, nói với nhóm bạn nam: \'Giọng Tuấn đang vỡ vì dậy thì thôi mà, tụi mình ai rồi cũng thế, trêu thế không vui đâu!\'.\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Linh nhận thấy cơ thể mình cao lớn và đầy đặn hơn trước khá nhiều, nhưng so với cô bạn thân dậy thì sớm, Linh thấy mình vẫn thấp bé và chậm chạp hơn hẳn. Sự sốt ruột và lo âu trỗi dậy trong lòng.\",\r\n      \"choices\": [\r\n        { \"text\": \"Tự nhủ: \'Đồng hồ sinh học của mỗi người là độc bản. Mình cứ kiên nhẫn ăn uống đủ chất, tập luyện và yêu thương cơ thể theo nhịp độ riêng của mình\'.\", \"nextNode\": \"success_end\" },\r\n        { \"text\": \"Lo lắng thái quá, đòi mẹ mua thuốc kích thích tăng trưởng chiều cao cấp tốc trên mạng về uống.\", \"nextNode\": \"fail_growth\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Tuyệt vời! Bạn đã vượt qua những bỡ ngỡ đầu dậy thì, biết cách tìm kiếm đồng minh và thấu hiểu lịch trình phát triển độc bản của cơ thể mình.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_suppress\": {\r\n      \"text\": \"❌ Chưa đúng! Việc chịu đựng và cố gắng trốn tránh bằng quần áo rộng không giải quyết được cảm giác khó chịu và sự phát triển sinh học tự nhiên.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_uninformed\": {\r\n      \"text\": \"❌ Chưa đúng! Sử dụng áo lót không đúng kích cỡ ở tuổi phát triển dễ gây cản trở lưu thông máu và ảnh hưởng không tốt đến sự phát triển của bầu ngực.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_peer\": {\r\n      \"text\": \"❌ Sai rồi! Hùa theo trêu chọc bạn bè chỉ làm gia tăng vấn đề bắt nạt học đường và gây tổn thương tinh thần cho bạn học.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_growth\": {\r\n      \"text\": \"❌ Sai rồi! Tự ý dùng các sản phẩm tăng chiều cao cấp tốc không rõ nguồn gốc rất nguy hiểm cho hormone tự nhiên và sức khỏe lâu dài.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1320, 223, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại các thái độ đối với cơ thể dậy thì:\",\r\n  \"leftBox\": { \"title\": \"Đón nhận tích cực\" },\r\n  \"rightBox\": { \"title\": \"Lo âu quá mức / Né tránh\" },\r\n  \"items\": [\r\n    { \"text\": \"Tự nhủ: Việc thay đổi giọng nói, vóc dáng là sinh lý hoàn toàn tự nhiên\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Trốn tránh không dám đi chơi với bạn bè vì thấy mình cao vọt lên nhanh quá\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Lựa chọn trang phục thoải mái, vừa vặn để thích nghi với vóc dáng mới\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Liên tục soi gương dằn vặt và tự trách bản thân vì cơ thể không giống ngày xưa\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Mở lòng trò chuyện với bố mẹ để xin hỗ trợ mua đồ dùng cá nhân phù hợp\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1321, 223, 'matching', '{\r\n  \"instruction\": \"Ghép cặp các khái niệm dậy thì cơ bản và định nghĩa tương ứng:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Dậy thì - Puberty\", \"right\": \"Giai đoạn chuyển tiếp tự nhiên từ một đứa trẻ thành người trưởng thành về sinh học.\" },\r\n    { \"left\": \"Hormone dậy thì\", \"right\": \"Những kẻ kích hoạt âm thầm phát tín hiệu khởi động thay đổi thể chất.\" },\r\n    { \"left\": \"Lịch trình riêng\", \"right\": \"Sự thật là mỗi người dậy thì ở thời điểm khác nhau từ 8 đến 14 tuổi.\" },\r\n    { \"left\": \"Đồng minh đáng tin\", \"right\": \"Người lớn như bố mẹ, thầy cô giúp bạn giải đáp khúc mắc thầm kín.\" }\r\n  ]\r\n}', 4, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1322, 223, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành đoạn văn về khái niệm dậy thì:\",\r\n  \"sentence\": \"Dậy thì là giai đoạn chuyển tiếp tự nhiên do các [blank1] kích hoạt. Mỗi người có một chiếc đồng hồ [blank2] riêng, vì thế đừng sốt ruột. Khi gặp khó khăn, hãy tìm kiếm sự giúp đỡ từ những người lớn [blank3] để nhận [blank4] kịp thời.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"hormone\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"sinh học\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"tin cậy\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"nâng đỡ\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"hormone\", \"sinh học\", \"tin cậy\", \"nâng đỡ\", \"bệnh lý\", \"sành sỏi\", \"thuốc tăng\", \"trốn tránh\"]\r\n}', 5, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1323, 223, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Tại sao việc so sánh vóc dáng và tốc độ lớn của mình với các bạn cùng lớp lại không cần thiết?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Vì mỗi cơ thể đều được lập trình một đồng hồ sinh học dậy thì độc lập, ai rồi cũng sẽ lớn lên theo lịch trình riêng phù hợp nhất.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Vì các bạn trong lớp chắc chắn dậy thì nhanh hơn do uống nhiều sữa hơn bạn.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Vì dậy thì trễ là biểu hiện của cơ thể khỏe mạnh hơn nhiều so với dậy thì sớm.\", \"correct\": false, \"emoji\": \"🙁\" },\r\n    { \"text\": \"Vì lớn chậm giúp bạn giữ được sự dễ thương lâu dài hơn.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1324, 224, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'F5 Diện Mạo: Những Thay Đổi Rõ Mồn Một\'! Bạn có 3 mạng để tự tin thiết lập thói quen vệ sinh và ứng phó với thay đổi diện mạo.\"}', 1, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1325, 224, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Tự tin làm chủ diện mạo mới\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Huy nhận thấy nách áo dạo này hay bị ướt sũng mồ hôi và tỏa mùi khá nồng sau mỗi tiết thể dục ngoài trời, khiến Huy vô cùng tự ti, không dám ngồi gần hay giơ tay phát biểu bài trước lớp.\",\r\n      \"choices\": [\r\n        { \"text\": \"Xịt thật nhiều nước hoa đậm đặc đè trực tiếp lên lớp mồ hôi cũ rồi đi học tiếp.\", \"nextNode\": \"fail_perfume\" },\r\n        { \"text\": \"Tắm rửa xà phòng sạch sẽ hàng ngày, chú ý làm khô nách và sử dụng lăn hoặc xịt khử mùi dịu nhẹ.\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Nhất quyết nhịn và trốn tránh không tham gia các hoạt động thể thao đá bóng yêu thích nữa.\", \"nextNode\": \"fail_avoid\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Huy cảm thấy thơm tho, tự tin trở lại. Một buổi sáng thức dậy, Huy phát hiện trên trán xuất hiện vài nốt mụn bọc sưng đỏ. Cậu thấy rất khó chịu và muốn dùng tay nặn phăng chúng đi trước khi đi học.\",\r\n      \"choices\": [\r\n        { \"text\": \"Dùng tay bẩn nặn thật mạnh để nhân mụn trào ra nhanh chóng.\", \"nextNode\": \"fail_pop\" },\r\n        { \"text\": \"Không nặn mụn bọc, giữ da sạch bằng sữa rửa mặt dịu nhẹ sáng tối và bôi kem mụn y khoa phù hợp.\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Cơ thể Huy tiếp tục phát triển rậm lông ở nách và vùng kín, ria mép cũng mọc đen hơn. Huy nghe các bạn nam rỉ tai nhau rằng cạo lông nách sẽ làm cơ thể mất đi vẻ nam tính, khiến cậu lo lắng phân vân.\",\r\n      \"choices\": [\r\n        { \"text\": \"Tự tin quyết định giữ lại hoặc dọn dẹp vệ sinh lông cơ thể an toàn dựa hoàn toàn trên sự thoải mái và sạch sử của chính mình.\", \"nextNode\": \"success_end\" },\r\n        { \"text\": \"Bị ảnh hưởng bởi định kiến, chịu đựng sự ngứa ngáy nóng bức và không dám cắt tỉa vệ sinh.\", \"nextNode\": \"fail_prejudice\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Hoàn hảo! Bạn đã kiểm soát tốt mùi cơ thể, biết cách chăm sóc làn da mụn thông thái và làm chủ các thói quen vệ sinh cá nhân văn minh.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_perfume\": {\r\n      \"text\": \"❌ Chưa đúng! Xịt nước hoa chồng lên mồ hôi chỉ tạo ra hỗn hợp mùi hỗn loạn, gây khó chịu hơn cho những người xung quanh.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_avoid\": {\r\n      \"text\": \"❌ Chưa đúng! Trốn tránh thể thao không giải quyết được vấn đề vệ sinh sinh học, ngược lại còn làm bạn mất đi cơ hội rèn luyện sức khỏe.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_pop\": {\r\n      \"text\": \"❌ Sai rồi! Tự ý dùng tay nặn mụn bọc sưng đỏ dễ gây nhiễm trùng máu, để lại sẹo lõm và vết thâm vĩnh viễn trên da mặt.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_prejudice\": {\r\n      \"text\": \"❌ Sai rồi! Quyết định dọn dẹp hay giữ lông cơ thể hoàn toàn là lựa chọn cá nhân hướng tới sự sạch sẽ, không phản ánh giới tính hay nhân cách của bạn.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1326, 224, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại các quan niệm về chăm sóc diện mạo dậy thì:\",\r\n  \"leftBox\": { \"title\": \"Chăm sóc lành mạnh\" },\r\n  \"rightBox\": { \"title\": \"Ngược đãi da / Gây hại\" },\r\n  \"items\": [\r\n    { \"text\": \"Rửa mặt nhẹ nhàng bằng sữa rửa mặt dịu nhẹ 2 lần mỗi ngày\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Dùng cồn hoặc xà phòng chà sát thật mạnh lên vết mụn để diệt khuẩn\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Mặc đồ lót bằng vải cotton thoáng khí và thay giặt sạch sẽ hàng ngày\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Tự ý nặn mụn bọc sưng đỏ khi nhân mụn chưa chín bằng tay chưa rửa\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Sử dụng lăn/xịt khử mùi sau khi đã tắm sạch và lau khô cơ thể\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1327, 224, 'matching', '{\r\n  \"instruction\": \"Ghép cặp từ khóa thay đổi thể chất dậy thì và định nghĩa tương ứng:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Tuyến bã nhờn\", \"right\": \"Tuyến hoạt động mạnh giải phóng dầu thừa gây tắc nghẽn lỗ chân lông tuổi dậy thì.\" },\r\n    { \"left\": \"Tuyến mồ hôi đặc biệt\", \"right\": \"Tuyến tiết dịch ở nách và vùng kín, dễ gây mùi đặc trưng khi bị vi khuẩn phân hủy.\" },\r\n    { \"left\": \"Lông cơ thể\", \"right\": \"Tấm khiên tự nhiên giúp bảo vệ các vùng da nhạy cảm khỏi ma sát.\" },\r\n    { \"left\": \"Mụn bọc\", \"right\": \"Nốt mụn sưng đỏ, cần được chăm sóc y khoa thay vì tự ý nặn tay.\" }\r\n  ]\r\n}', 4, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1328, 224, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành đoạn văn về vệ sinh diện mạo dậy thì:\",\r\n  \"sentence\": \"Hormone tăng trưởng kích thích tuyến [blank1] hoạt động mạnh gây ra mụn. Hãy vệ sinh da mặt bằng sữa rửa mặt [blank2] và tuyệt đối không tự ý [blank3] mụn. Bên cạnh đó, hãy tắm rửa hàng ngày để kiểm soát [blank4] cơ thể phát sinh.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"bã nhờn\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"dịu nhẹ\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"nặn\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"mùi\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"bã nhờn\", \"dịu nhẹ\", \"nặn\", \"mùi\", \"đồ lót\", \"nước hoa\", \"cạo sạch\", \"lo âu\"]\r\n}', 5, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1329, 224, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Tại sao mồ hôi lúc đá bóng của bạn dạo này lại có mùi đậm hơn lúc nhỏ rất nhiều?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Vì mồ hôi của bạn dạo này chứa nhiều vi khuẩn tự nhiên có hại hơn trước.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Vì hormone dậy thì kích hoạt tuyến mồ hôi đặc biệt ở nách và vùng kín hoạt động, chất dịch này khi bị vi khuẩn trên da phân hủy sẽ tạo ra mùi cơ thể đặc trưng.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Vì bạn không chịu tắm rửa bằng các loại xà phòng sát khuẩn liều cao.\", \"correct\": false, \"emoji\": \"🙁\" },\r\n    { \"text\": \"Vì quần áo thể thao của bạn hấp thụ quá nhiều ánh sáng mặt trời.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1330, 225, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Đến Tháng & Chuyện Phía Trong: Hiểu Để Đỡ Lo!\'! Bạn có 3 mạng để tự tin đối phó với các sự cố sinh học tuổi dậy thì.\"}', 1, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1331, 225, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Tự tin ứng phó sự cố hành kinh và mộng tinh\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Trong tiết Toán, Trang bỗng cảm thấy đau quặn ở bụng dưới và có dịch ẩm tràn ra quần lót. Khi đứng dậy lên bảng, Trang phát hiện váy đồng phục phía sau đã bị thấm một vệt đỏ nhỏ. Các bạn xung quanh bắt đầu nhận ra và thì thầm.\",\r\n      \"choices\": [\r\n        { \"text\": \"Xấu hổ khóc lóc và lập tức bỏ chạy thẳng ra khỏi cổng trường để về nhà.\", \"nextNode\": \"fail_escape\" },\r\n        { \"text\": \"Bình tĩnh dùng áo khoác buộc ngang hông che vệt đỏ, mượn bạn một miếng băng vệ sinh dự phòng và xin phép xuống phòng y tế trường.\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Ngồi im chịu trận tại chỗ suốt các tiết học tiếp theo đến tối mịt mới về nhà thay quần áo.\", \"nextNode\": \"fail_stay\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Trang được cô giáo y tế hướng dẫn thay băng vệ sinh và cho nghỉ ngơi. Tối hôm đó, cậu bạn Duy thức dậy và phát hiện quần lót của mình bị ướt dính một khoảng lớn. Duy hoang mang nghĩ mình bị bệnh tiết niệu nặng.\",\r\n      \"choices\": [\r\n        { \"text\": \"Giấu kỹ chiếc quần lót bẩn vào góc tủ vì xấu hổ và tự mua thuốc kháng sinh tự uống.\", \"nextNode\": \"fail_hide\" },\r\n        { \"text\": \"Hiểu rằng đây là hiện tượng mộng tinh sinh lý hoàn toàn bình thường ở bạn trai, đem quần lót đi giặt sạch sẽ.\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Duy và Trang đi học trở lại. Trong giờ ra chơi, một nhóm bạn nam nhặt được miếng băng vệ sinh chưa dùng rơi ra từ cặp của bạn khác và cười cợt làm trò đùa giễu cợt trước lớp.\",\r\n      \"choices\": [\r\n        { \"text\": \"Thẳng thắn nhắc nhở: \'Băng vệ sinh là dụng cụ y tế cá nhân sạch sẽ giúp bạn gái bảo vệ sức khỏe, có gì để cười cợt đâu các cậu?\'\", \"nextNode\": \"success_end\" },\r\n        { \"text\": \"Tránh phiền phức, im lặng bỏ qua coi như không thấy gì để không bị ghét.\", \"nextNode\": \"fail_bypass\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Chúc mừng! Bạn đã xử lý sự cố hành kinh thông minh, thấu hiểu hiện tượng mộng tinh và có tư duy văn minh xóa bỏ định kiến về sức khỏe sinh sản.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_escape\": {\r\n      \"text\": \"❌ Chưa đúng! Bỏ học chạy trốn không giải quyết được vệt đỏ trên váy mà còn khiến bạn bị mất bài học và vi phạm kỷ luật trường.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_stay\": {\r\n      \"text\": \"❌ Chưa đúng! Ngồi im mặc đồ ẩm ướt dính máu kinh suốt nhiều tiếng liên tục rất mất vệ sinh, gây mùi khó chịu và tăng nguy cơ viêm nhiễm nặng.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_hide\": {\r\n      \"text\": \"❌ Sai rồi! Giấu quần lót bẩn gây mùi hôi mốc, và việc tự ý uống kháng sinh bừa bãi cực kỳ gây hại cho sức khỏe gan thận của bạn.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_bypass\": {\r\n      \"text\": \"❌ Sai rồi! Sự im lặng đồng lõa với trò đùa vô duyên khiến các bạn gái tiếp tục bị tổn thương và duy trì định kiến xấu về chu kỳ sinh học tự nhiên.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1332, 225, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại các hành vi chăm sóc sức khỏe sinh sản:\",\r\n  \"leftBox\": { \"title\": \"Chăm sóc thông thái\" },\r\n  \"rightBox\": { \"title\": \"Gây hại hoặc kỳ thị\" },\r\n  \"items\": [\r\n    { \"text\": \"Chườm ấm bụng dưới và uống nước ấm khi bị đau bụng kinh nhẹ\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Thụt rửa sâu vào bên trong âm đạo bằng nước xà phòng sát khuẩn\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Thay băng vệ sinh đúng giờ sau mỗi 3 đến 4 tiếng hành kinh\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Để nguyên một miếng băng vệ sinh suốt cả ngày để tiết kiệm\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Ghi chú ngày bắt đầu kinh nguyệt vào lịch để theo dõi chu kỳ sinh học\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1333, 225, 'matching', '{\r\n  \"instruction\": \"Ghép cặp các khái niệm sức khỏe sinh sản và định nghĩa tương ứng:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Kinh nguyệt - Period\", \"right\": \"Hiện tượng lớp niêm mạc tử cung bong ra và thoát ra ngoài khi trứng không thụ tinh.\" },\r\n    { \"left\": \"Mộng tinh - Wet Dream\", \"right\": \"Sự xuất tinh tự nhiên không chủ ý khi đang ngủ ở bạn trai dậy thì.\" },\r\n    { \"left\": \"Băng vệ sinh\", \"right\": \"Dụng cụ thấm hút máu kinh dùng một lần, cần được gói gọn vứt sọt rác.\" },\r\n    { \"left\": \"Chu kỳ kinh nguyệt\", \"right\": \"Thời gian tính từ ngày đầu hành kinh tháng này đến ngày đầu hành kinh tháng sau.\" }\r\n  ]\r\n}', 4, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1334, 225, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành đoạn văn về chu kỳ sinh sản:\",\r\n  \"sentence\": \"Kinh nguyệt và mộng tinh là các cột mốc [blank1] tự nhiên chứng tỏ bạn đang lớn. Khi hành kinh, cần thay [blank2] đúng giờ để tránh [blank3]. Hãy cởi mở chia sẻ khoa học và xóa bỏ sự [blank4] vô căn cứ.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"sinh lý\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"băng vệ sinh\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"viêm nhiễm\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"kỳ thị\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"sinh lý\", \"băng vệ sinh\", \"viêm nhiễm\", \"kỳ thị\", \"xấu hổ\", \"vô sinh\", \"dơ bẩn\", \"thụt rửa\"]\r\n}', 5, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1335, 225, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Tại sao bạn gái tuyệt đối không nên tự ý thụt rửa sâu bên trong âm đạo khi tắm rửa vệ sinh ngày đèn đỏ?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Vì thụt rửa sâu làm mất cân bằng độ pH tự nhiên của âm đạo, tiêu diệt vi khuẩn có lợi và đẩy vi khuẩn bên ngoài vào sâu gây viêm nhiễm đường sinh sản.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Vì âm đạo có thể tự co bóp đẩy hết nước rửa ra ngoài gây lãng phí xà phòng.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Vì việc này làm cản trở quá trình rụng trứng ở buồng trứng của bạn gái.\", \"correct\": false, \"emoji\": \"🙁\" },\r\n    { \"text\": \"Vì nước xà phòng sẽ làm phai màu niêm mạc cơ quan sinh dục.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1336, 226, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Bão Cảm Xúc: Sáng Nắng Chiều Mưa, Có Sao Đâu?\'! Bạn có 3 mạng để tự tin đối phó và làm chủ cơn bão cảm xúc tuổi dậy thì.\"}', 1, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1337, 226, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Làm chủ cơn bão cảm xúc và giao tiếp lành mạnh\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Bình đang rất hào hứng hoàn thành bức tranh vẽ dự thi của mình. Em trai Bình vô tình chạy nô đùa làm đổ cả cốc nước lọc lên bức tranh khiến màu nhòe nhoẹt, hỏng hoàn toàn. Bình cảm thấy máu nóng dồn lên mặt, tim đập thình thịch và muốn lao vào đánh em.\",\r\n      \"choices\": [\r\n        { \"text\": \"Lao vào đánh em một trận lôi đình để trút giận: \'Mày làm hỏng hết bài của tao rồi!\' và ném đồ đạc.\", \"nextNode\": \"fail_explode\" },\r\n        { \"text\": \"Hít thở sâu 3 nhịp, nói to: \'Em đi ra ngoài đi!\' rồi vào nhà tắm rửa mặt bằng nước lạnh để bình tĩnh lại trước khi dọn dẹp.\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Cố chịu đựng ấm ức, im lặng nhặt bức tranh hỏng lên rồi chạy vào phòng đóng sập cửa, nằm khóc dằn vặt bản thân cả đêm.\", \"nextNode\": \"fail_suppress\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Sau khi rửa mặt hạ nhiệt, Bình thấy bình tĩnh hơn. Tối hôm đó, lúc ăn cơm, bố mẹ so sánh: \'Bằng tuổi con, con nhà cô Lan đã biết phụ giúp việc nhà và học giỏi, sao con chỉ biết vẽ vời vô ích!\'. Cảm giác ức chế lại dâng lên.\",\r\n      \"choices\": [\r\n        { \"text\": \"Gào khóc cãi lại: \'Bố mẹ lúc nào cũng con nhà người ta, con ghét bố mẹ!\' rồi bỏ bữa cơm.\", \"nextNode\": \"fail_clash\" },\r\n        { \"text\": \"Hít sâu giữ bình tĩnh, trả lời lịch sự: \'Bố mẹ ơi, con vẽ tranh là sở thích lành mạnh và con vẫn cố gắng hoàn thành việc học mà. Con mong bố mẹ động viên con thay vì so sánh ạ\'.\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Mặc dù đã đối thoại tốt, Bình vẫn thấy trong lòng còn bứt rứt, lo lắng dồn nén trước kỳ thi học kỳ sắp tới. Cậu muốn tìm cách bình ổn lại tâm lý của mình.\",\r\n      \"choices\": [\r\n        { \"text\": \"Tạm dừng học 15 phút, tắt điện thoại, thực hiện kỹ thuật thở 4-7-8 điều hòa nhịp tim và nghe một bản nhạc nhẹ.\", \"nextNode\": \"success_end\" },\r\n        { \"text\": \"Cố ngồi nhồi nhét tài liệu liên tục 4 tiếng nữa dưới áp lực đau đầu dữ dội.\", \"nextNode\": \"fail_overwork\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Xuất sắc! Bạn đã kiểm soát tốt cơn giận bộc phát, giao tiếp văn minh với gia đình và biết cách chăm sóc tinh thần khi quá tải.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_explode\": {\r\n      \"text\": \"❌ Chưa đúng! Hành động bộc phát bạo lực làm tổn thương em trai, gây rạn nứt gia đình và khiến bạn dằn vặt dằn vặt sau đó.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_suppress\": {\r\n      \"text\": \"❌ Chưa đúng! Đè nén uất ức một mình mà không giải tỏa lành mạnh chỉ làm quả bóng cảm xúc thêm phình to và dễ phát nổ sau này.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_clash\": {\r\n      \"text\": \"❌ Sai rồi! La hét phản kháng hỗn hào chỉ làm tăng mâu thuẫn gia đình và khiến bố mẹ có ấn tượng xấu về sự trưởng thành của bạn.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_overwork\": {\r\n      \"text\": \"❌ Sai rồi! Ép bộ não làm việc khi đang kiệt sức dưới áp lực cao độ chỉ gây phản tác dụng, làm giảm trí nhớ và tăng triệu chứng stress thể chất.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1338, 226, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại các cách đối xử với bão cảm xúc dậy thì:\",\r\n  \"leftBox\": { \"title\": \"Kết bạn cảm xúc\" },\r\n  \"rightBox\": { \"title\": \"Chối bỏ hoặc Trút giận\" },\r\n  \"items\": [\r\n    { \"text\": \"Cho phép bản thân khóc khi buồn để giải tỏa bớt năng lượng tiêu cực\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Cố tỏ ra vui cười hớn hở bên ngoài khi trong lòng đang tan nát\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Tự viết nhật ký trút bỏ mọi suy nghĩ bực bội ra giấy rồi xé bỏ\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Quát mắng em nhỏ hoặc đập phá đồ đạc để hạ hỏa cơn cáu giận\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Tự nhủ: Cảm xúc lo lắng này là hợp lệ, mình sẽ đối diện và vượt qua\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1339, 226, 'matching', '{\r\n  \"instruction\": \"Ghép cặp các khái niệm xáo trộn cảm xúc và định nghĩa tương ứng:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Estrogen & Testosterone\", \"right\": \"Các hormone sinh học tăng vọt tuổi dậy thì làm biến động tâm trạng.\" },\r\n    { \"left\": \"Kính lúp suy diễn\", \"right\": \"Bẫy tâm lý phóng đại một lời nhận xét hay ánh mắt thành chỉ trích cá nhân.\" },\r\n    { \"left\": \"Bất đồng thế hệ\", \"right\": \"Mâu thuẫn nảy sinh khi nhu cầu tự lập của con va chạm với sự bảo bọc của bố mẹ.\" },\r\n    { \"left\": \"Kỹ thuật thở 4-7-8\", \"right\": \"Bài tập hít thở vật lý giúp kích hoạt hệ thần kinh đối giao cảm làm dịu não bộ.\" }\r\n  ]\r\n}', 4, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1340, 226, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành đoạn văn về điều tiết cảm xúc:\",\r\n  \"sentence\": \"Sự thay đổi tâm trạng tuổi dậy thì là do tác động của [blank1]. Đừng rơi vào bẫy kính lúp [blank2] mọi chuyện. Hãy trò chuyện [blank3] với bố mẹ và sử dụng các công cụ [blank4] cảm xúc để giữ bình tĩnh.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"hormone\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"suy diễn\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"tôn trọng\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"bình ổn\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"hormone\", \"suy diễn\", \"tôn trọng\", \"bình ổn\", \"hỗn hào\", \"chối bỏ\", \"trốn tránh\", \"game\"]\r\n}', 5, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1341, 226, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Tại sao việc gọi tên chính xác cảm xúc của mình lúc giận dữ (ví dụ: \'con đang rất uất ức vì bị so sánh\') lại giúp hạ nhiệt cơn giận?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Vì gọi tên cảm xúc chuyển hướng hoạt động từ hạch hạnh nhân (trung tâm cảm xúc) sang vỏ não trước trán (trung tâm tư duy lô-gíc), giúp não bộ lấy lại quyền kiểm soát hành vi.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Vì nói ra sẽ làm cho đối phương lập tức sợ hãi và nhượng bộ bạn.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Vì nó làm cho hormone testosterone bị biến mất khỏi cơ thể ngay lập tức.\", \"correct\": false, \"emoji\": \"🙁\" },\r\n    { \"text\": \"Vì đó là câu thần chú tự động làm mát nhiệt độ phòng học.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1342, 227, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Yêu Lấy Chiếc Body: Đừng Để Ai Body Shame\'! Bạn có 3 mạng để tự tin bảo vệ ranh giới hình ảnh cơ thể.\"}', 1, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1343, 227, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Tự tin bảo vệ vóc dáng trước phán xét ngoại hình\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Trong nhóm chat chung của lớp, một bạn nam đăng ảnh chụp lén Vân đang ăn bánh mì ở góc sân trường kèm chú thích trêu cợt: \'Ăn thế này bảo sao đùi to như cột đình!\'. Cả nhóm hùa vào thả icon cười cợt, làm Vân vô cùng xấu hổ và tổn thương.\",\r\n      \"choices\": [\r\n        { \"text\": \"Nhắn tin chửi bới dữ dội và dọa gặp bạn nam đó ở cổng trường để giải quyết bằng bạo lực.\", \"nextNode\": \"fail_violence\" },\r\n        { \"text\": \"Chụp màn hình làm bằng chứng, rời khỏi nhóm chat toxic, tự trấn an bản thân và chia sẻ sự việc với thầy cô hoặc bố mẹ.\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"U uất buồn bã, quyết định nhịn ăn bỏ bữa trưa và bữa tối để nhanh chóng giảm cân.\", \"nextNode\": \"fail_starve\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Được thầy cô can thiệp, nhóm bạn đã xin lỗi Vân. Cuối tuần đó, tại bữa cơm gia đình có họ hàng xa đến chơi, một người lớn nhận xét oang oang trước mọi người: \'Ơ hay dạo này Vy ăn gì béo thế con? Con gái phải biết giữ dáng chứ!\'. Vy thấy ngực nghẹn lại.\",\r\n      \"choices\": [\r\n        { \"text\": \"Cúi đầu khóc thút thít, bỏ đũa chạy thẳng lên phòng khóa cửa lại uất ức.\", \"nextNode\": \"fail_cry\" },\r\n        { \"text\": \"Mỉm cười nhẹ, trả lời kiên định và lịch sự: \'Dạ dạo này con đang dậy thì nên cơ thể phát triển khỏe mạnh là tốt rồi ạ bác!\' rồi chuyển chủ đề ôn hòa.\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Mọi người gật gù đồng ý và nể phục sự tự tin của Vy. Tối đến, Vy lướt Instagram thấy các hot teen đăng ảnh có vòng eo con kiến mịn màng ảo diệu, sự so sánh xã hội trỗi dậy làm Vy thấy tự ti.\",\r\n      \"choices\": [\r\n        { \"text\": \"Nhận thức rõ mạng xã hội chỉ là sản phẩm của filter và góc chụp, tắt điện thoại đi ngủ và tập trung vào sức khỏe thực tế của mình.\", \"nextNode\": \"success_end\" },\r\n        { \"text\": \"Tiếp tục lướt suốt đêm để tìm các bài viết hướng dẫn ăn kiêng cực đoan.\", \"nextNode\": \"fail_diet\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Tuyệt vời! Bạn đã bảo vệ bản thân thành công trước body shaming mạng xã hội và gia đình, đồng thời có tư duy lành mạnh về vẻ đẹp cơ thể.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_violence\": {\r\n      \"text\": \"❌ Chưa đúng! Sử dụng bạo lực hoặc chửi bới chỉ làm mâu thuẫn leo thang và biến bạn thành người sai trước pháp luật học đường.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_starve\": {\r\n      \"text\": \"❌ Chưa đúng! Nhịn ăn cực đoan gây hại nghiêm trọng cho hệ tiêu hóa và làm suy nhược cơ thể đang tuổi lớn.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_cry\": {\r\n      \"text\": \"❌ Sai rồi! Khóc lóc bỏ chạy chỉ làm cho không khí gia đình căng thẳng và chứng tỏ bạn đang hoàn toàn bị lời chê bai đó đánh gục.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_diet\": {\r\n      \"text\": \"❌ Sai rồi! Tìm kiếm chế độ ăn kiêng cực đoan thâu đêm làm bạn kiệt sức, lún sâu vào bẫy tự ti ảo trên mạng.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1344, 227, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại các hành vi ứng xử đối với vóc dáng cơ thể:\",\r\n  \"leftBox\": { \"title\": \"Tôn trọng cơ thể\" },\r\n  \"rightBox\": { \"title\": \"Body Shaming / Phán xét\" },\r\n  \"items\": [\r\n    { \"text\": \"Khen ngợi nụ cười rạng rỡ hoặc tính cách dễ mến của bạn học\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Trêu chọc chiều cao khiêm tốn của bạn cùng lớp để mua vui\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Tự nhủ: Cơ bắp khỏe khoắn giúp mình vận động dẻo dai tốt\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Nhận xét bạn gái trông thô kệch chỉ vì bạn ấy có bắp tay săn chắc\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Bỏ theo dõi những trang MXH chuyên đăng ảnh tiêu chuẩn vóc dáng phi thực tế\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1345, 227, 'matching', '{\r\n  \"instruction\": \"Ghép cặp từ khóa về hình ảnh cơ thể dậy thì và định nghĩa phù hợp:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Hình ảnh cơ thể\", \"right\": \"Cách bạn suy nghĩ, cảm nhận và hình dung về ngoại hình của chính mình.\" },\r\n    { \"left\": \"Body Shaming\", \"right\": \"Hành vi bình luận tiêu cực, giễu cợt hoặc chê bai vóc dáng người khác.\" },\r\n    { \"left\": \"Cạm bẫy filter\", \"right\": \"Hình ảnh ảo đã qua chỉnh sửa bóp eo, mịn da tạo tiêu chuẩn phi thực tế.\" },\r\n    { \"left\": \"Đa dạng cơ thể\", \"right\": \"Sự thật sinh học rằng mỗi gen quy định chiều cao và khung xương khác nhau.\" }\r\n  ]\r\n}', 4, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1346, 227, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành định nghĩa yêu thương cơ thể:\",\r\n  \"sentence\": \"Hình ảnh cơ thể lành mạnh bắt nguồn từ sự [blank1]. Khi bị phán xét ngoại hình, hãy kiên định thiết lập [blank2] bảo vệ mình. Tránh xa chiếc bẫy so sánh [blank3] và trân trọng vẻ đẹp [blank4] của bản thân.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"tự chấp nhận\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"ranh giới\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"mạng xã hội\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"độc bản\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"tự chấp nhận\", \"ranh giới\", \"mạng xã hội\", \"độc bản\", \"ăn kiêng\", \"chê bai\", \"hoàn hảo\", \"sống ảo\"]\r\n}', 5, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1347, 227, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Ý kiến hoặc lời phán xét tiêu cực của người khác về cơ thể bạn phản ánh điều gì?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Nó chỉ phản ánh thế giới quan và mức độ lịch sự/thiếu tế nhị của chính họ, chứ không định nghĩa được giá trị thật sự hay vẻ đẹp của con người bạn.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Nó phản ánh chính xác 100% những khiếm khuyết mà bạn bắt buộc phải sửa đổi ngay lập tức.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Nó phản ánh việc bạn đang không biết cách ăn mặc hợp thời trang.\", \"correct\": false, \"emoji\": \"🙁\" },\r\n    { \"text\": \"Nó phản ánh việc bố mẹ đã nuôi dạy bạn không đúng cách.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1348, 228, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Tự Chăm Sóc Bản Thân: Học Cách Yêu Mình Đúng Điệu!\'! Bạn có 3 mạng để xây dựng lối sống lành mạnh.\"}', 1, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1349, 228, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Xây dựng thói quen tự chăm sóc khoa học\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Linh định chỉ lướt điện thoại 15 phút trước khi đi ngủ lúc 10h tối để F5 tinh thần. Tuy nhiên, các video ngắn lôi cuốn trên Tiktok liên tục kéo Linh đi hết clip này sang clip khác khiến cô bé thức đến 1h sáng. Ngày hôm sau, Linh thức dậy mỏi mệt, uể oải và đi học muộn.\",\r\n      \"choices\": [\r\n        { \"text\": \"Tiếp tục mang điện thoại lên giường ngủ hàng đêm và lướt đến khi nào ngủ quên thì thôi.\", \"nextNode\": \"fail_phone\" },\r\n        { \"text\": \"Bật chế độ không làm phiền sau 10h30 tối, để điện thoại ngoài tầm với của giường ngủ và ngủ đủ 8-9 tiếng mỗi ngày.\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Thức khuya học bù và cày game tiếp, uống 2 lon nước tăng lực để lấy lại tỉnh táo ban ngày.\", \"nextNode\": \"fail_energy\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Nhờ ngủ sớm, Linh cảm thấy cơ thể khỏe mạnh, da dẻ bớt mụn hẳn. Một buổi trưa, Linh cảm thấy mắt mỏi rã rời, vai gáy căng nhức sau 5 tiết học căng thẳng trên lớp, nhưng chiều lại có buổi tập thể dục chạy bền.\",\r\n      \"choices\": [\r\n        { \"text\": \"Bất chấp mệt mỏi, cố gắng chạy hết công suất 5km để đạt chỉ tiêu thành tích cao nhất.\", \"nextNode\": \"fail_overwork\" },\r\n        { \"text\": \"Lắng nghe tín hiệu cơ thể, xin phép thầy giáo thể dục cho chạy vừa sức và dành thời gian kéo giãn cơ nhẹ nhàng.\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Sau tiết thể dục, Linh thấy thoải mái. Cô bé muốn thiết lập kế hoạch ăn uống và lối sống tự chăm sóc bản thân lành mạnh lâu dài.\",\r\n      \"choices\": [\r\n        { \"text\": \"Nhịn bữa trưa và ăn kiêng hà khắc để ép cân nặng giảm thật nhanh giống như các người mẫu trên mạng.\", \"nextNode\": \"fail_diet\" },\r\n        { \"text\": \"Ăn uống đủ chất đạm, canxi, vitamin và tự thưởng cho mình một khoảng thời gian nghỉ ngơi thư giãn 30 phút mỗi ngày.\", \"nextNode\": \"success_end\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Hoàn hảo! Bạn đã xây dựng được thói quen ngủ sớm bảo vệ sức khỏe, biết lắng nghe tín hiệu mệt mỏi của cơ thể và thiết lập chế độ sinh hoạt tự chăm sóc bản thân thông thái.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_phone\": {\r\n      \"text\": \"❌ Chưa đúng! Thức khuya cày điện thoại ngăn cản cơ thể tiết melatonin, làm gián đoạn nhịp sinh học tự nhiên và gây kiệt quệ thể chất.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_energy\": {\r\n      \"text\": \"❌ Chưa đúng! Lạm dụng nước tăng lực ép cơ thể làm việc quá sức sẽ tàn phá hệ tim mạch và làm suy nhược thần kinh nghiêm trọng.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_overwork\": {\r\n      \"text\": \"❌ Sai rồi! Phớt lờ tín hiệu mệt mỏi thể chất để cố quá sức dễ gây chấn thương xương khớp và khiến cơ thể bị suy nhược sâu sắc.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_diet\": {\r\n      \"text\": \"❌ Sai rồi! Nhịn ăn ép cân cực đoan ở tuổi dậy thì sẽ cản trở nghiêm trọng quá trình phát triển chiều cao, gây hạ đường huyết nguy hiểm.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1350, 228, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại các hành vi lắng nghe cơ thể:\",\r\n  \"leftBox\": { \"title\": \"Lắng nghe thông thái\" },\r\n  \"rightBox\": { \"title\": \"Phớt lờ gượng ép\" },\r\n  \"items\": [\r\n    { \"text\": \"Tạm dừng học bài, đi bộ thư giãn ngoài sân 10 phút khi thấy mỏi mắt\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Uống ly cafe đậm đặc để thức thâu đêm ôn thi dù đầu đang nhức búa bổ\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Nằm nghỉ ngơi thư giãn khi cảm thấy bụng dưới đau âm ỉ ngày hành kinh\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Tiếp tục chạy bộ gắng sức dù chân đang bị căng cơ sưng đỏ\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Dành ra 30 phút vẽ tranh hoặc chơi nhạc cụ giải tỏa lo âu mỗi tối\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1351, 228, 'matching', '{\r\n  \"instruction\": \"Ghép cặp từ khóa tự chăm sóc và định nghĩa tương ứng:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Hormone GH\", \"right\": \"Hormone tăng trưởng được giải phóng nhiều nhất khi cơ thể ngủ sâu trước 11h đêm.\" },\r\n    { \"left\": \"Melatonin\", \"right\": \"Hormone kích thích giấc ngủ ngon, bị ngăn cản bởi ánh sáng xanh điện thoại.\" },\r\n    { \"left\": \"Self-care\", \"right\": \"Phong cách sống lắng nghe nhu cầu sinh học và tinh thần để tự sạc pin bản thân.\" },\r\n    { \"left\": \"Thói quen nhỏ\", \"right\": \"Những bước đi dễ dàng như uống thêm nước giúp bộ não không bị quá tải phản kháng.\" }\r\n  ]\r\n}', 4, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1352, 228, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành đoạn văn về tự chăm sóc bản thân:\",\r\n  \"sentence\": \"Tự chăm sóc bản thân là một hành trình [blank1] đòi hỏi sự kiên nhẫn. Hãy ngủ sâu trước 11h đêm để giải phóng [blank2] tăng trưởng và ăn uống đủ [blank3] thay vì nhịn ăn. Đừng quên [blank4] cơ thể khi mệt mỏi.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"lâu dài\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"hormone\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"dinh dưỡng\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"lắng nghe\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"lâu dài\", \"hormone\", \"dinh dưỡng\", \"lắng nghe\", \"nhất thời\", \"thuốc bổ\", \"nhịn ăn\", \"phớt lờ\"]\r\n}', 5, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1353, 228, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Tại sao giấc ngủ từ 10h tối đến 6h sáng lại được coi là thời gian vàng để phát triển chiều cao?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Vì trong khoảng từ 11h đêm đến 1h sáng, tuyến yên giải phóng hormone tăng trưởng (GH) nhiều gấp 4 lần bình thường nếu cơ thể đã ngủ sâu giấc.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Vì ngủ ban đêm giúp kéo giãn các khớp xương một cách vật lý khi nằm ngang.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Vì ban đêm cơ thể không phải nạp thêm thức ăn và tiêu hóa năng lượng.\", \"correct\": false, \"emoji\": \"🙁\" },\r\n    { \"text\": \"Vì ngủ ban đêm giúp bạn tránh được ánh nắng mặt trời có hại cho chiều cao.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1354, 229, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Tin Chuẩn Vs Tin Đồn: Giải Mã Thắc Mắc Khó Nói!\'! Bạn có 3 mạng để phân biệt kiến thức khoa học dậy thì.\"}', 1, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1355, 229, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Trở thành bộ lọc thông tin thông thái\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Vy đọc được một bài viết trên TikTok được chia sẻ rầm rộ bảo rằng ăn thật nhiều dứa thay cơm trong ngày hành kinh giúp cơ thể thơm tho và giảm hoàn toàn 100% cơn đau bụng kinh. Vy thấy mẹo này rất thú vị và định chia sẻ ngay về trang cá nhân của mình.\",\r\n      \"choices\": [\r\n        { \"text\": \"Nhấn nút chia sẻ ngay lập tức về trang cá nhân để bạn bè cùng biết.\", \"nextNode\": \"fail_share\" },\r\n        { \"text\": \"Tìm kiếm lại từ khóa đó trên các trang y khoa hoặc hỏi mẹ để xác nhận tính chính xác của mẹo dân gian này trước khi share.\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Tự thực hành thí nghiệm ăn 3 quả dứa thay cơm cả ngày để tự kiểm chứng.\", \"nextNode\": \"fail_experiment\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Mẹ Vy giải thích rằng dứa có enzyme bromelain giúp giãn cơ tử cung nhẹ nhưng ăn quá nhiều thay cơm gây loét dạ dày. Hôm sau ở lớp, bạn Duy lo sợ tột cùng kể với Khánh rằng hôm qua Duy vô tình ôm một bạn nữ, và Duy nghe đồn là ôm nhau có thể làm bạn gái mang thai.\",\r\n      \"choices\": [\r\n        { \"text\": \"Rỉ tai đồn tiếp với các bạn nam khác để cùng cười cợt chọc ghẹo Duy.\", \"nextNode\": \"fail_spread\" },\r\n        { \"text\": \"Trấn an Duy: \'Ôm nhau không thể mang thai được đâu cậu ơi. Cần có sự gặp gỡ trực tiếp của tinh trùng và trứng cơ, cậu yên tâm nhé!\'\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Duy thở phào nhẹ nhõm. Cuối ngày, bạn Bách băn khoăn khi nghe các bạn rỉ tai nhau rằng hành vi tự khám phá cơ thể (thủ dâm) sẽ làm suy giảm trí nhớ, vô sinh và hỏng thận.\",\r\n      \"choices\": [\r\n        { \"text\": \"Bách hoang mang tin sái cổ và đi mua thuốc bổ thận tráng dương tự uống.\", \"nextNode\": \"fail_myth\" },\r\n        { \"text\": \"Bách hiểu đúng khoa học: Đây là hành vi sinh lý bình thường nếu thực hiện điều độ, kín đáo và giữ vệ sinh sạch sẽ.\", \"nextNode\": \"success_end\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Xuất sắc! Bạn đã có tư duy phản biện xuất sắc, biết chọn lọc nguồn tin y khoa chuẩn xác và dũng cảm xóa bỏ các tin đồn nhảm học đường.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_share\": {\r\n      \"text\": \"❌ Chưa đúng! Chia sẻ thông tin giật gân, chưa kiểm chứng góp phần lan truyền tin đồn nhảm và làm giảm uy tín cá nhân của bạn.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_experiment\": {\r\n      \"text\": \"❌ Chưa đúng! Ăn dứa thay cơm cả ngày tàn phá niêm mạc dạ dày do lượng axit cao, gây hại lớn cho hệ tiêu hóa.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_spread\": {\r\n      \"text\": \"❌ Sai rồi! Lan truyền tin đồn sai lệch về mang thai gây hoang mang dư luận học đường và thể hiện sự thiếu hiểu biết giáo dục giới tính.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_myth\": {\r\n      \"text\": \"❌ Sai rồi! Tin vào tin đồn thiếu khoa học làm bạn sống trong cảm giác tội lỗi, sợ hãi vô lý và việc tự uống thuốc bừa bãi có hại cho gan thận.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1356, 229, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại các nguồn tìm kiếm kiến thức sức khỏe dậy thì:\",\r\n  \"leftBox\": { \"title\": \"Nguồn tin cậy khoa học\" },\r\n  \"rightBox\": { \"title\": \"Nguồn tin rác / Tin đồn\" },\r\n  \"items\": [\r\n    { \"text\": \"Website của Tổ chức Y tế Thế giới WHO, UNICEF hoặc Bộ Y tế Việt Nam\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Các video ngắn giật tít câu view của các tiktoker không có chuyên môn y khoa\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Sách giáo khoa Sinh học hoặc phòng tư vấn tâm lý học đường của trường\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Các lời rỉ tai truyền miệng của hội bạn thân trong phòng vệ sinh học đường\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Bác sĩ chuyên khoa tại các bệnh viện nhi hoặc trung tâm y tế uy tín\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1357, 229, 'matching', '{\r\n  \"instruction\": \"Ghép cặp các khái niệm giải mã thắc mắc dậy thì và định nghĩa tương ứng:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Thủ dâm - Masturbation\", \"right\": \"Hành vi tự kích thích cơ quan sinh dục tìm cảm giác thư giãn, bình thường về sinh lý.\" },\r\n    { \"left\": \"Tư duy phản biện\", \"right\": \"Kỹ năng đặt câu hỏi kiểm chứng nguồn tin trước khi tin hoặc chia sẻ.\" },\r\n    { \"left\": \"Sụn tăng trưởng đóng khớp\", \"right\": \"Hiện tượng đầu xương hóa cốt hoàn toàn vào khoảng tuổi 20-22 làm ngừng tăng chiều cao.\" },\r\n    { \"left\": \"Giáo dục giới tính\", \"right\": \"Kiến thức khoa học giúp thấu hiểu cơ thể, cảm xúc và các mối quan hệ an toàn.\" }\r\n  ]\r\n}', 4, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1358, 229, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành đoạn văn về giải mã tin đồn dậy thì:\",\r\n  \"sentence\": \"Đừng vội tin vào các tin đồn học đường, hãy rèn luyện tư duy [blank1]. Tự khám phá cơ thể là hành vi [blank2] bình thường nếu điều độ. Chiều cao chỉ dừng lại khi [blank3] đóng khớp hoàn toàn. Hãy hỏi [blank4] khi gặp băn khoăn.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"phản biện\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"sinh lý\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"xương\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"chuyên gia\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"phản biện\", \"sinh lý\", \"xương\", \"chuyên gia\", \"bệnh hoạn\", \"vô sinh\", \"Google\", \"nhịn ăn\"]\r\n}', 5, '2026-06-11 18:23:49', '2026-06-11 18:23:49');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(1359, 229, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Làm thế nào để cải thiện chiều cao tối ưu ở giai đoạn cuối tuổi dậy thì một cách khoa học?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Duy trì chế độ dinh dưỡng giàu canxi/protein, đi ngủ sớm trước 11h đêm để giải phóng hormone tăng trưởng và tích cực chơi thể thao kéo giãn xương.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Uống các loại thuốc tăng chiều cao siêu tốc và ăn thật nhiều đồ ngọt.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Nằm im một chỗ cả ngày trên giường để xương không bị đè nén.\", \"correct\": false, \"emoji\": \"🙁\" },\r\n    { \"text\": \"Nhịn ăn giảm cân và chỉ uống sữa thay cơm hàng ngày.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 18:23:49', '2026-06-11 18:23:49'),
(1360, 230, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Thế nào là mối quan hệ lành mạnh?\'! Bạn có 3 mạng để tự tin bảo vệ ranh giới bản thân.\"}', 1, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1361, 230, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Đặt ranh giới và giữ vững bình đẳng trong nhóm bạn\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Bạn cùng bàn (Huy) thường tự ý quyết định mọi thứ trong nhóm học tập. Hôm nay, Huy tự ý đổi lịch họp nhóm sang ngày chủ nhật mà không hỏi ý kiến ai. Lịch này trùng với ca học thêm tiếng Anh rất quan trọng của bạn.\",\r\n      \"choices\": [\r\n        { \"text\": \"Im lặng và chấp nhận lịch họp để giữ hòa khí, chấp nhận trốn học tiếng Anh.\", \"nextNode\": \"fail_compromise\" },\r\n        { \"text\": \"Nhẹ nhàng nhưng thẳng thắn nhắn tin: \'Chủ nhật tớ bận học tiếng Anh rồi. Tụi mình bình đẳng đóng góp ý kiến nên tớ đề xuất chuyển lịch sang chiều thứ bảy hoặc tối thứ sáu nhé.\'\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Tức giận rời khỏi nhóm chat học tập chung và nhắn tin mắng Huy là kẻ ích kỷ.\", \"nextNode\": \"fail_rage\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Huy bất ngờ và cằn nhằn trong nhóm: \'Mọi lần tớ quyết có sao đâu, cậu khó tính thế, làm cả nhóm mất công đổi lịch!\'. Cả nhóm đang im lặng chờ phản ứng của bạn.\",\r\n      \"choices\": [\r\n        { \"text\": \"Thấy áy náy nên vội vàng nhắn xin lỗi cả nhóm và chấp nhận đi học nhóm ngày chủ nhật.\", \"nextNode\": \"fail_guilt\" },\r\n        { \"text\": \"Kiên định lập trường, nhắn rõ ràng: \'Mối quan hệ lành mạnh cần có sự bình đẳng và tôn trọng ý kiến cả hai phía. Tớ muốn tụi mình cùng thảo luận lịch rảnh chung để mọi người đều thấy thoải mái.\'\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Huy nhận ra mình hơi quá đà nên đồng ý đổi lịch sang chiều thứ bảy. Buổi họp nhóm diễn ra vui vẻ. Tối đó, một bạn trong nhóm rủ bạn mua áo nhóm siêu đắt để thể hiện \'sự gắn kết\'. Bạn không đủ tiền tiêu vặt.\",\r\n      \"choices\": [\r\n        { \"text\": \"Nói thật về điều kiện kinh tế của mình và đề xuất chọn mẫu áo khác có giá cả phù hợp hơn cho tất cả mọi người.\", \"nextNode\": \"success_end\" },\r\n        { \"text\": \"Vay mượn nợ nần hoặc nói dối bố mẹ xin tiền học thêm để mua bằng được để tránh bị coi là \'kém cỏi\' so với các bạn.\", \"nextNode\": \"fail_starve\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Hoàn toàn chính xác! Bạn đã đặt ranh giới cá nhân rõ ràng, bảo vệ quyền bình đẳng của mình trong nhóm và biết cách ứng phó lành mạnh trước áp lực bạn bè.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_compromise\": {\r\n      \"text\": \"❌ Sai rồi! Hy sinh việc học tập quan trọng chỉ để nịnh bợ hay chiều lòng người khác là tự xóa bỏ ranh giới và tính bình đẳng trong mối quan hệ.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_rage\": {\r\n      \"text\": \"❌ Chưa đúng! Phản ứng nóng nảy và mắng mỏ chỉ làm mâu thuẫn leo thang và phá vỡ sự kết nối lành mạnh. Hãy chọn cách giao tiếp thẳng thắn trước.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_guilt\": {\r\n      \"text\": \"❌ Sai rồi! Cảm giác tội lỗi không có cơ sở và nhượng bộ trước sự ích kỷ của người khác không phải là biểu hiện của một mối quan hệ lành mạnh.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_starve\": {\r\n      \"text\": \"❌ Chưa đúng! Chạy theo những món đồ đắt đỏ vượt quá khả năng chỉ vì áp lực đồng trang lứa là đánh mất sự tự chủ của bản thân.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1362, 230, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại các hành vi trong mối quan hệ:\",\r\n  \"leftBox\": { \"title\": \"Lành mạnh (Green Flag)\" },\r\n  \"rightBox\": { \"title\": \"Bất ổn (Red/Amber Flag)\" },\r\n  \"items\": [\r\n    { \"text\": \"Tôn trọng sở thích cá nhân và gu thời trang khác biệt của bạn bè\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Ép bạn bè phải thay đổi kiểu tóc, trang phục theo ý thích của mình\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Cảm thấy an tâm, vui vẻ và được tự do bày tỏ ý kiến cá nhân\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Luôn cảm thấy nơm nớp lo sợ đối phương giận dỗi khi mình không rep tin nhắn ngay\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Thẳng thắn trao đổi, chia sẻ chi phí khi cùng đi uống nước ăn uống\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1363, 230, 'matching', '{\r\n  \"instruction\": \"Ghép cặp các viên gạch nền tảng của mối quan hệ lành mạnh với định nghĩa phù hợp:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Tôn trọng (Respect)\", \"right\": \"Coi trọng cảm xúc, ý kiến và ranh giới cá nhân của nhau.\" },\r\n    { \"left\": \"Lòng tin (Trust)\", \"right\": \"Tin tưởng đối phương mà không cần kiểm soát hay theo dõi.\" },\r\n    { \"left\": \"Bình đẳng (Equality)\", \"right\": \"Cả hai có quyền đóng góp và quyết định ngang nhau trong mối quan hệ.\" },\r\n    { \"left\": \"Sự tự chủ (Autonomy)\", \"right\": \"Giữ vững cá tính riêng và sở thích độc lập của bản thân.\" }\r\n  ]\r\n}', 4, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1364, 230, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành triết lý về mối quan hệ lành mạnh:\",\r\n  \"sentence\": \"Mối quan hệ lành mạnh bắt nguồn từ sự [blank1] và tôn trọng lẫn nhau. Hãy biết lắng nghe [blank2] khi cảm thấy bất an hay lo âu. Giữ vững [blank3] riêng và tự tin từ chối áp lực [blank4] từ nhóm bạn.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"bình đẳng\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"cơ thể\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"cá tính\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"bắt chước\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"bình đẳng\", \"cơ thể\", \"cá tính\", \"bắt chước\", \"kiểm soát\", \"im lặng\", \"giả vờ\", \"áp đặt\"]\r\n}', 5, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1365, 230, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Khi bạn liên tục cảm thấy tim đập nhanh, cơ thể co cứng, và lo sợ mỗi khi nhận cuộc gọi hay tin nhắn từ một người bạn bè, điều này có ý nghĩa gì?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Đó là tín hiệu cảnh báo của cơ thể cho thấy mối quan hệ này đang có vấn đề bất ổn và thiếu an toàn.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Bạn đang quá nhạy cảm và yếu đuối, cần tập cách chịu đựng và bỏ qua cảm giác đó.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Người bạn đó rất yêu quý bạn và đang muốn thu hút sự chú ý đặc biệt từ bạn.\", \"correct\": false, \"emoji\": \"🙁\" },\r\n    { \"text\": \"Cơ thể bạn đang bị kiệt sức do học tập quá tải, không liên quan gì đến bạn bè.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1366, 231, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Giao tiếp & Giải quyết Xung đột\'! Hãy dùng kỹ năng giao tiếp mượt mà để hạ hỏa các mâu thuẫn.\"}', 1, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1367, 231, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Giao tiếp thông thái và hòa giải xung đột\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Bạn và bạn cùng nhóm (Duy) đang tranh cãi gay gắt về phân chia công việc trong nhóm. Duy làm sai và chậm tiến độ khiến bạn rất bực mình. Bạn cảm thấy mặt nóng bừng lên và chuẩn bị to tiếng.\",\r\n      \"choices\": [\r\n        { \"text\": \"Nhận biết cơn giận, hít sâu 3 nhịp và chủ động đề xuất: \'Tụi mình đang hơi nóng, để chiều bình tĩnh rồi nói tiếp nha.\' để tránh to tiếng.\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Quát lớn vào mặt Duy: \'Lúc nào cậu cũng vô trách nhiệm như vậy, làm hỏng hết bài của cả nhóm!\' rồi đập bàn bỏ đi.\", \"nextNode\": \"fail_anger\" },\r\n        { \"text\": \"Im lặng tỏ vẻ khinh bỉ, tự lấy bài về làm một mình và không nói chuyện với Duy nữa.\", \"nextNode\": \"fail_silent\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Chiều đến, khi cả hai đã bình tĩnh hơn, Duy cố gắng giải thích lý do làm chậm nhưng giọng điệu có vẻ vẫn tự ái. Bạn muốn bày tỏ sự khó chịu của mình một cách lành mạnh.\",\r\n      \"choices\": [\r\n        { \"text\": \"Cắt ngang lời Duy: \'Cậu đừng bao biện nữa. Cậu lúc nào cũng cẩu thả và bắt người khác gánh việc!\'\", \"nextNode\": \"fail_blame\" },\r\n        { \"text\": \"Dùng câu bắt đầu bằng \'Tớ\': \'Tớ cảm thấy hơi hụt hẫng và lo lắng khi phần bài của cậu bị trễ vì nó ảnh hưởng trực tiếp đến điểm số của cả nhóm.\' và lắng nghe Duy chia sẻ.\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Duy nghe xong thấy bớt phòng thủ và chủ động xin lỗi. Tuy nhiên, tối đó Duy nhắn tin giải thích thêm nhưng chỉ rep lại vỏn vẹn chữ \'Ừ\' khiến bạn hoang mang lo sợ Duy vẫn ghét mình.\",\r\n      \"choices\": [\r\n        { \"text\": \"Không suy diễn tiêu cực, gọi điện trực tiếp hỏi thăm: \'Duy ơi, lúc nãy thấy nhắn ngắn tớ sợ cậu còn bận hay có chuyện gì. Tụi mình thống nhất cách sửa bài nhé!\'\", \"nextNode\": \"success_end\" },\r\n        { \"text\": \"Lập tức hủy kết bạn và viết status bóng gió chửi Duy là kẻ hai mặt trên trang cá nhân.\", \"nextNode\": \"fail_toxic_status\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Tuyệt vời! Bạn đã nhận diện cơn giận tốt, biết cách dùng câu bắt đầu bằng \'Tớ\' để nói về cảm xúc và không rơi vào cạm bẫy suy diễn tin nhắn chữ.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_anger\": {\r\n      \"text\": \"❌ Chưa đúng! Trút giận bằng cách to tiếng, xúc phạm người khác chỉ làm tổn thương mối quan hệ và không giải quyết được vấn đề công việc.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_silent\": {\r\n      \"text\": \"❌ Sai rồi! \'Chiến tranh lạnh\' và tự gánh việc làm một mình chỉ tích tụ sự ức chế bên trong và phá hỏng tinh thần làm việc nhóm.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_blame\": {\r\n      \"text\": \"❌ Sai rồi! Sử dụng những câu bắt đầu bằng \'Cậu\' kèm theo các từ cực đoan (luôn luôn, lúc nào cũng) sẽ kích hoạt chế độ phòng thủ của đối phương.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_toxic_status\": {\r\n      \"text\": \"❌ Chưa đúng! Suy diễn nội dung tin nhắn rep ngắn và mang mâu thuẫn lên mạng xã hội để trả đũa là hành vi vô cùng độc hại.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1368, 231, 'sorting', '{\r\n  \"instruction\": \"Hãy phân loại câu nói/hành vi giao tiếp sau đây:\",\r\n  \"leftBox\": { \"title\": \"Bày tỏ cảm xúc lành mạnh\" },\r\n  \"rightBox\": { \"title\": \"Đổ lỗi/Trách móc độc hại\" },\r\n  \"items\": [\r\n    { \"text\": \"Tớ thấy hơi buồn khi cậu quên cuộc hẹn của tụi mình hôm qua\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Cậu lúc nào cũng cao su, không bao giờ tôn trọng giờ giấc của ai cả\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Tớ lo lắng khi thấy cậu tắt máy ngang xương mà không báo trước\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Cậu cố tình phớt lờ tin nhắn của tớ để chọc tức tớ đúng không\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Tớ cảm thấy quá tải khi phải gánh toàn bộ phần thuyết trình của nhóm\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1369, 231, 'matching', '{\r\n  \"instruction\": \"Ghép cặp các quy tắc giao tiếp và giải quyết xung đột sau:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Lắng nghe chủ động\", \"right\": \"Tập trung thấu hiểu cảm xúc đối phương, không ngắt lời hay phán xét.\" },\r\n    { \"left\": \"Hòa giải bước 1\", \"right\": \"Chấp nhận lỗi sai và xin lỗi chân thành, không tìm lý do bao biện.\" },\r\n    { \"left\": \"Hòa giải bước 2\", \"right\": \"Lắng nghe cảm nhận của đối phương về tổn thương mà mình đã gây ra.\" },\r\n    { \"left\": \"Hòa giải bước 3\", \"right\": \"Cùng nhau thảo luận đưa ra giải pháp cụ thể để không lặp lại lỗi cũ.\" }\r\n  ]\r\n}', 4, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1370, 231, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành đoạn văn về giải quyết xung đột:\",\r\n  \"sentence\": \"Giao tiếp lành mạnh đòi hỏi sự lắng nghe [blank1] thay vì nghe để cãi. Khi bày tỏ sự bất mãn, hãy dùng cấu trúc bắt đầu bằng từ [blank2] để tránh đổ lỗi. Nếu cơn giận bùng phát, hãy chủ động xin [blank3] để hạ nhiệt. Hãy giải quyết xung đột bằng các hành động [blank4] cụ thể.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"chủ động\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"Tớ\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"tạm dừng\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"khắc phục\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"chủ động\", \"Tớ\", \"tạm dừng\", \"khắc phục\", \"Cậu\", \"im lặng\", \"tranh cãi\", \"đối phó\"]\r\n}', 5, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1371, 231, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Tại sao chúng ta nên hạn chế tối đa việc giải quyết các mâu thuẫn lớn hoặc nhạy cảm thông qua tin nhắn chữ?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Vì tin nhắn chữ thiếu tông giọng, nét mặt, rất dễ khiến người đọc suy diễn tiêu cực và hiểu lầm nghiêm trọng.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Vì nhắn tin chữ tốn nhiều tiền cước mạng điện thoại và làm tốn thời gian gõ bàn phím.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Vì tin nhắn chữ không thể hiện hết được sự giận dữ mãnh liệt của bạn để dằn mặt đối phương.\", \"correct\": false, \"emoji\": \"🙁\" },\r\n    { \"text\": \"Vì đối phương có thể chụp màn hình tin nhắn của bạn để gửi cho giáo viên hoặc phụ huynh.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1372, 232, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Ranh giới, Lòng tin & Sự Tôn trọng\'! Bạn có 3 mạng để bảo vệ vương quốc riêng tư của mình.\"}', 1, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1373, 232, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Tự tin thiết lập ranh giới cá nhân trước sự kiểm soát\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Bạn phát hiện bạn thân hoặc người yêu của mình tự ý cầm điện thoại đọc tin nhắn Zalo lúc bạn đi rửa tay. Khi bị hỏi, đối phương thản nhiên nói: \'Yêu nhau/Chơi thân thì phải cởi mở, không giấu giếm gì nhau mới là tin tưởng, sao phải giữ mật khẩu làm gì?\'.\",\r\n      \"choices\": [\r\n        { \"text\": \"Đưa mật khẩu và cho phép đối phương đọc thoải mái để chứng minh mình trong sạch.\", \"nextNode\": \"fail_submit\" },\r\n        { \"text\": \"Lấy lại điện thoại, đặt mật khẩu mới và nói: \'Tớ yêu quý cậu nhưng tin nhắn là không gian cá nhân của tớ. Tụi mình cần lòng tin thực sự chứ không phải sự kiểm soát điện thoại.\'\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Giật phắt điện thoại, mắng mỏ đối phương thậm tệ rồi đập vỡ điện thoại ngay tại chỗ.\", \"nextNode\": \"fail_violence\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Đối phương tỏ vẻ giận dỗi, im lặng suốt cả buổi và nhắn tin bảo rằng bạn đã thay đổi, không còn coi họ là quan trọng nữa.\",\r\n      \"choices\": [\r\n        { \"text\": \"Mủi lòng và cảm thấy tội lỗi, quyết định gửi mật khẩu điện thoại qua tin nhắn để làm hòa.\", \"nextNode\": \"fail_guilt\" },\r\n        { \"text\": \"Kiên định ranh giới, cho đối phương thời gian bình tĩnh và nhắn: \'Tôn trọng quyền riêng tư là nguyên tắc cơ bản giúp mối quan hệ bền vững. Khi nào cậu bình tĩnh, tụi mình nói chuyện tiếp nhé.\'\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Đối phương nhận ra lỗi sai và xin lỗi bạn. Ngày hôm sau, nhóm bạn thân rủ bạn trốn học thêm để đi net chơi game, dọa rằng: \'Không đi thì từ sau đừng chơi chung với nhóm nữa!\'.\",\r\n      \"choices\": [\r\n        { \"text\": \"Từ chối dứt khoát: \'Tớ cần ôn bài cho bài kiểm tra ngày mai rồi. Các cậu đi chơi vui nhé!\' mà không giải thích vòng vo.\", \"nextNode\": \"success_end\" },\r\n        { \"text\": \"Lo sợ bị cô lập nên chấp nhận trốn học đi theo nhóm bạn để giữ tình bạn.\", \"nextNode\": \"fail_peer_pressure\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Hoàn toàn chính xác! Bạn đã bảo vệ xuất sắc ranh giới riêng tư, không nhượng bộ trước sự thao túng cảm xúc và tự tin từ chối áp lực từ nhóm bạn.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_submit\": {\r\n      \"text\": \"❌ Sai rồi! Đồng ý chia sẻ mật khẩu cá nhân chỉ để chiều lòng sự kiểm soát của đối phương là bạn đang tự hủy hoại ranh giới riêng tư cần thiết của mình.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_violence\": {\r\n      \"text\": \"❌ Chưa đúng! Hành vi bạo lực hoặc tức giận thái quá không giải quyết được mâu thuẫn ranh giới mà còn biến bạn thành người sai trước.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_guilt\": {\r\n      \"text\": \"❌ Sai rồi! Nhượng bộ chỉ vì cảm thấy áy náy trước sự giận dỗi vô lý sẽ tạo tiền lệ xấu cho sự lấn lướt ranh giới sau này.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_peer_pressure\": {\r\n      \"text\": \"❌ Chưa đúng! Trốn học chỉ vì sợ nhóm bạn tẩy chay chứng tỏ bạn chưa biết cách đặt ranh giới cứng rắn để bảo vệ tương lai của chính mình.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1374, 232, 'sorting', '{\r\n  \"instruction\": \"Hãy phân loại các hành vi ứng xử sau đây:\",\r\n  \"leftBox\": { \"title\": \"Tôn trọng ranh giới\" },\r\n  \"rightBox\": { \"title\": \"Xâm phạm ranh giới\" },\r\n  \"items\": [\r\n    { \"text\": \"Gõ cửa trước khi vào phòng riêng của người khác\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Đòi mật khẩu mạng xã hội để kiểm tra tin nhắn của người yêu\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Luôn hỏi ý kiến bạn bè trước khi đăng ảnh dìm hàng họ lên mạng\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Tự ý lục cặp sách hoặc ví tiền của bạn học khi họ ra chơi\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Chấp nhận lời từ chối và không nài nỉ khi bạn nói không muốn đi chơi\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1375, 232, 'matching', '{\r\n  \"instruction\": \"Ghép cặp các khái niệm ranh giới và định nghĩa phù hợp:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Ranh giới vật lý\", \"right\": \"Quyền quyết định ai được phép đụng chạm vào cơ thể của bạn.\" },\r\n    { \"left\": \"Ranh giới cảm xúc\", \"right\": \"Quyền giữ suy nghĩ riêng tư, nói không khi cảm thấy quá tải.\" },\r\n    { \"left\": \"Lòng tin (Trust)\", \"right\": \"Sự tin cậy được xây dựng từ những hành động nhỏ, nhất quán.\" },\r\n    { \"left\": \"Tôn trọng riêng tư\", \"right\": \"Không tò mò lục lọi đồ đạc, tin nhắn cá nhân khi chưa được cho phép.\" }\r\n  ]\r\n}', 4, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1376, 232, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành đoạn văn về ranh giới cá nhân:\",\r\n  \"sentence\": \"Ranh giới cá nhân giúp bảo vệ sự [blank1] của bạn. Lòng tin không tự nhiên có mà cần được xây dựng qua [blank2] nhất quán. Tôn trọng ranh giới nghĩa là không xâm phạm quyền [blank3] của nhau. Hãy dứt khoát nói [blank4] trước những lời rủ rê vi phạm nguyên tắc sống của bạn.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"thoải mái\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"hành động\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"riêng tư\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"không\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"thoải mái\", \"hành động\", \"riêng tư\", \"không\", \"kiểm soát\", \"mật khẩu\", \"giữ bí mật\", \"thỏa hiệp\"]\r\n}', 5, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1377, 232, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Khi đối phương đòi hỏi mật khẩu các tài khoản mạng xã hội của bạn để \'chứng minh tình cảm chân thành\', hành động này phản ánh điều gì?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Đó là dấu hiệu của sự kiểm soát độc hại và thiếu lòng tin, vi phạm nghiêm trọng ranh giới cá nhân.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Đó là biểu hiện của một tình yêu sâu sắc, sẵn sàng chia sẻ mọi bí mật riêng tư với nhau.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Đó là hành vi bình thường giúp cả hai bảo mật tài khoản tốt hơn trước các hacker.\", \"correct\": false, \"emoji\": \"🙁\" },\r\n    { \"text\": \"Đó là dấu hiệu cho thấy đối phương đang muốn giúp bạn quản lý hộp thư để tránh tin nhắn rác.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1378, 233, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Sự Gắn kết & Gần gũi Cảm xúc\'! Bạn có 3 mạng để hiểu đúng về tình cảm tuổi học trò.\"}', 1, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1379, 233, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Kết nối cảm xúc và tôn trọng tốc độ của đối phương\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Bạn (An) nhận ra dạo gần đây mình hay đỏ mặt khi đi bên cạnh Vy - người bạn thân từ thuở nhỏ. Bạn luôn để ý xem Vy nói chuyện với ai và thấy hơi ghen tuông. Bạn nhận ra mình đã cảm nắng Vy.\",\r\n      \"choices\": [\r\n        { \"text\": \"Tránh mặt Vy hoàn toàn để không phải đối mặt với cảm xúc ngượng ngùng này.\", \"nextNode\": \"fail_avoidance\" },\r\n        { \"text\": \"Chấp nhận cảm xúc tự nhiên, cho bản thân thời gian suy ngẫm để phân biệt giữa tình bạn thân thiết và cảm lãng mạn thực sự.\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Tỏ tình dồn dập ngay hôm sau, bắt Vy phải trả lời đồng ý làm người yêu ngay lập tức.\", \"nextNode\": \"fail_pressure\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Sau một thời gian, hai bạn chính thức hẹn hò. Trong một buổi đi chơi riêng, Vy định nắm tay bạn, nhưng nhận thấy bạn đang khoác chặt hai tay vào chiếc balo trước ngực.\",\r\n      \"choices\": [\r\n        { \"text\": \"Vy tinh tế nhận ra tín hiệu phòng thủ, tiếp tục đi bên cạnh trò chuyện tự nhiên và tôn trọng tốc độ sẵn sàng của bạn.\", \"nextNode\": \"step3\" },\r\n        { \"text\": \"Vy cố tình giật balo ra và chủ động nắm tay bạn bằng được vì nghĩ yêu nhau là phải nắm tay mới lãng mạn.\", \"nextNode\": \"fail_touch\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Bạn vô cùng cảm kích sự tinh tế của Vy. Tuy nhiên, Vy lại nghe đám bạn xung quanh thúc giục: \'Yêu nhau là phải ôm hôn tiến xa hơn, chứ cứ nắm tay thôi thì nhạt nhẽo lắm!\'. Vy cảm thấy áp lực lớn.\",\r\n      \"choices\": [\r\n        { \"text\": \"Ép bản thân thực hiện các đụng chạm thân mật dù chưa thấy sẵn sàng để chiều lòng nhóm bạn.\", \"nextNode\": \"fail_peer\" },\r\n        { \"text\": \"Vy giữ vững ranh giới và cùng bạn tập trung xây dựng sự gắn kết phi thể xác (viết thư tay, cùng đi nhà sách học bài, làm playlist nhạc tặng nhau).\", \"nextNode\": \"success_end\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Tuyệt vời! Bạn đã phân biệt đúng cảm xúc bản thân, tôn trọng ranh giới đụng chạm và biết cách xây dựng sự gắn kết cảm xúc phi thể xác lành mạnh.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_avoidance\": {\r\n      \"text\": \"❌ Chưa phù hợp! Đột ngột tránh mặt bạn thân mà không giải thích chỉ làm rạn nứt mối quan hệ tốt đẹp sẵn có một cách vô lý.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_pressure\": {\r\n      \"text\": \"❌ Sai rồi! Tỏ tình dồn dập và ép buộc câu trả lời sẽ khiến đối phương sợ hãi và làm căng thẳng tình bạn.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_touch\": {\r\n      \"text\": \"❌ Sai rồi! Phớt lờ tín hiệu cơ thể phòng thủ của đối phương và ép buộc đụng chạm là hành vi thiếu tôn trọng ranh giới cá nhân.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_peer\": {\r\n      \"text\": \"❌ Chưa đúng! Thực hiện các hành vi thân mật thể xác chỉ vì áp lực đồng trang lứa là vi phạm ranh giới cơ thể và thiếu tự chủ.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1380, 233, 'sorting', '{\r\n  \"instruction\": \"Hãy phân loại các cảm xúc/hành vi sau đây vào đúng hộp:\",\r\n  \"leftBox\": { \"title\": \"Tình bạn thân thiết\" },\r\n  \"rightBox\": { \"title\": \"Tình cảm say nắng (Crush)\" },\r\n  \"items\": [\r\n    { \"text\": \"Muốn đi chơi chung cả nhóm bạn đông vui và thoải mái tếu táo\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Tim đập nhanh, đỏ mặt lúng túng khi đứng gần đối phương\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Thoải mái chia sẻ chuyện học hành, trường lớp tự nhiên không ngần ngại\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Hay nhìn trộm đối phương và để ý xem họ đang nói chuyện với bạn khác giới nào\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Mong muốn có những buổi đi chơi riêng chỉ có hai người bên nhau\", \"correctBox\": \"right\" }\r\n  ]\r\n}', 3, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1381, 233, 'matching', '{\r\n  \"instruction\": \"Ghép cặp các khái niệm về sự gắn kết lãng mạn dậy thì sau:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Thân mật cảm xúc\", \"right\": \"Cảm giác an toàn tuyệt đối khi chia sẻ ước mơ, nỗi sợ mà không bị phán xét.\" },\r\n    { \"left\": \"Tín hiệu đèn xanh\", \"right\": \"Thái độ cởi mở (như mỉm cười, hướng người về phía bạn, sẵn lòng tương tác).\" },\r\n    { \"left\": \"Tín hiệu phòng thủ\", \"right\": \"Hành vi tránh né đụng chạm (như ôm balo trước ngực, rụt tay lại, lảng tránh ánh mắt).\" },\r\n    { \"left\": \"Gắn kết phi thể xác\", \"right\": \"Kết nối cảm xúc qua việc tự làm playlist nhạc tặng nhau, viết thư tay chia sẻ.\" }\r\n  ]\r\n}', 4, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1382, 233, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành đoạn văn sau về sự gắn kết:\",\r\n  \"sentence\": \"Sự thân mật cảm xúc mang lại cảm giác [blank1] để mở lòng. Cần phân biệt rõ tình bạn thân thiết với cảm xúc [blank2] lãng mạn. Hãy tôn trọng [blank3] sẵn sàng đụng chạm của đối phương. Gắn kết tình cảm bằng sự thấu hiểu [blank4] là chất keo bền chặt nhất.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"an toàn\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"say nắng\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"mức độ\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"tinh thần\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"an toàn\", \"say nắng\", \"mức độ\", \"tinh thần\", \"áp lực\", \"thể xác\", \"nghi ngờ\", \"vật lý\"]\r\n}', 5, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1383, 233, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Khi đối phương có phản ứng co người lại, tránh né ánh mắt hoặc ôm chặt balo trước ngực khi bạn tiến lại gần, bạn nên ứng phó như thế nào?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Hãy dừng lại và tôn trọng không gian cá nhân của họ, đó là tín hiệu phòng thủ cảnh báo họ chưa sẵn sàng cho đụng chạm thể xác.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Tiếp tục tiến tới nắm tay hoặc bá vai để giúp họ giải tỏa sự ngượng ngùng nhanh hơn.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Tỏ thái độ giận dỗi và trách móc họ ích kỷ, không thực sự yêu quý hay trân trọng bạn.\", \"correct\": false, \"emoji\": \"🙁\" },\r\n    { \"text\": \"Cắt đứt liên lạc ngay lập tức vì cho rằng họ ghét bỏ hoặc coi thường mình.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1384, 234, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Đồng thuận trong Mối quan hệ\'! Bạn có 3 mạng để thực hành sự đồng thuận thông thái.\"}', 1, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1385, 234, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Làm chủ sự đồng thuận tự nguyện và check-in cảm xúc\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Bạn (Trang) đang ngồi nói chuyện riêng với Nam trong công viên. Nam ghé sát lại định hôn bạn, nhưng bạn cảm thấy ngột ngạt và đẩy nhẹ Nam ra: \'Khoan đã Nam, tớ thấy hơi nhanh\'. Nam đứng khựng lại vẻ mặt hụt hẫng.\",\r\n      \"choices\": [\r\n        { \"text\": \"Nhắm mắt chịu đựng cho Nam hôn một cái để Nam không bị quê và giận dỗi.\", \"nextNode\": \"fail_guilt\" },\r\n        { \"text\": \"Dứt khoát giữ khoảng cách và bày tỏ rõ ràng: \'Tớ quý cậu nhưng tớ chưa sẵn sàng cho việc này. Tụi mình nói chuyện tiếp nhé!\'\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Hét lớn tố cáo Nam biến thái rồi tát mạnh vào mặt Nam trước đám đông.\", \"nextNode\": \"fail_violence\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Nam im lặng một lúc rồi cằn nhằn: \'Lần trước cậu đồng ý nắm tay rồi, sao giờ ôm hôn lại từ chối? Cậu làm tớ tụt cả cảm hứng!\'. Bạn cảm thấy áy náy vô cùng.\",\r\n      \"choices\": [\r\n        { \"text\": \"Cảm thấy tội lỗi vì làm người yêu buồn, đành gật đầu chấp nhận quay xe đồng ý hôn Nam.\", \"nextNode\": \"fail_revert\" },\r\n        { \"text\": \"Kiên định giải thích quy tắc ranh giới: \'Đồng ý việc này không có nghĩa là đồng ý việc kia, và tớ được quyền đổi ý bất cứ lúc nào tớ thấy không thoải mái. Cậu nên tôn trọng cảm giác của tớ chứ!\'\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Nam nhận ra mình sai và xin lỗi Trang. Hôm sau, Duy muốn nắm tay Linh lúc đi dạo phố. Thay vì đột ngột chụp lấy tay Linh, Duy nhìn Linh mỉm cười nhẹ và muốn check-in đồng thuận.\",\r\n      \"choices\": [\r\n        { \"text\": \"Duy hỏi nhẹ nhàng: \'Tớ nắm tay cậu được không?\' và chờ đợi phản hồi hào hứng từ Linh.\", \"nextNode\": \"success_end\" },\r\n        { \"text\": \"Duy đột ngột giật lấy tay Linh bỏ vào túi áo của mình để chứng tỏ sự chủ động lãng mạn.\", \"nextNode\": \"fail_grab\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Hoàn toàn chính xác! Bạn đã hiểu sâu sắc quyền đổi ý (Reversible), bảo vệ ranh giới cơ thể và biết cách thực hành check-in đồng thuận mượt mà lịch sự.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_guilt\": {\r\n      \"text\": \"❌ Sai rồi! Chấp nhận đụng chạm thể xác chỉ vì nể nang hoặc sợ đối phương giận dỗi là vi phạm ranh giới cơ thể và không có sự đồng thuận tự nguyện.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_violence\": {\r\n      \"text\": \"❌ Chưa phù hợp! Phản ứng bạo lực khi chưa có hành vi đe dọa nguy hiểm là không cần thiết và làm phức tạp hóa vấn đề giao tiếp ranh giới.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_revert\": {\r\n      \"text\": \"❌ Sai rồi! Nhượng bộ trước sự giận dỗi ép buộc của đối phương sẽ khiến bạn mất quyền kiểm soát ranh giới cơ thể của chính mình.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_grab\": {\r\n      \"text\": \"❌ Chưa đúng! Tự ý chụp lấy tay đối phương khi chưa hỏi ý kiến dễ gây cảm giác khó chịu và vi phạm ranh giới cá nhân đột ngột.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1386, 234, 'sorting', '{\r\n  \"instruction\": \"Hãy phân loại các tín hiệu cảm xúc của đối phương:\",\r\n  \"leftBox\": { \"title\": \"Đèn Xanh (Đồng thuận xịn)\" },\r\n  \"rightBox\": { \"title\": \"Đèn Vàng (Cần dừng check-in)\" },\r\n  \"items\": [\r\n    { \"text\": \"Nói câu \'Tớ cũng muốn\' kèm nụ cười rạng rỡ và chủ động tiến lại gần\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Im lặng tránh né ánh mắt, người hơi co cứng lại\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Vui vẻ chủ động đưa tay ra nắm lấy tay bạn trước\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Nói câu \'Cũng được...\' nhưng nét mặt lo âu, bứt rứt bấu vạt áo\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Trả lời ngập ngừng \'Để tớ nghĩ đã...\' rồi cười trừ tránh né\", \"correctBox\": \"right\" }\r\n  ]\r\n}', 3, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1387, 234, 'matching', '{\r\n  \"instruction\": \"Ghép cặp các tiêu chí trong quy tắc đồng thuận F.R.I.E.S sau:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Freely given (Tự nguyện)\", \"right\": \"Đồng ý không do bị nài nỉ, ép buộc, đe dọa hay nịnh bợ.\" },\r\n    { \"left\": \"Reversible (Linh hoạt)\", \"right\": \"Quyền được thay đổi quyết định, quay xe bất cứ lúc nào.\" },\r\n    { \"left\": \"Informed (Đầy đủ thông tin)\", \"right\": \"Biết rõ mình đang đồng ý thực hiện hành vi gì và với ai.\" },\r\n    { \"left\": \"Enthusiastic (Hào hứng)\", \"right\": \"Chỉ làm những việc mà cả hai thực sự muốn và vui vẻ.\" }\r\n  ]\r\n}', 4, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1388, 234, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành đoạn văn về sự đồng thuận:\",\r\n  \"sentence\": \"Đồng thuận là sự đồng ý [blank1], hào hứng từ cả hai phía. Bạn luôn có quyền [blank2] đổi ý bất cứ lúc nào mà không cần cảm thấy tội lỗi. Sự im lặng hay cười trừ là tín hiệu [blank3] đòi hỏi bạn phải dừng lại. Hãy thực hành [blank4] mượt mà để thể hiện sự tôn trọng đối phương.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"tự nguyện\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"quay xe\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"đèn vàng\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"check-in\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"tự nguyện\", \"quay xe\", \"đèn vàng\", \"check-in\", \"bắt buộc\", \"im lặng\", \"áp đặt\", \"nài nỉ\"]\r\n}', 5, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1389, 234, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Ý nghĩa thực sự của chữ R - Reversible (Linh hoạt/Dễ đổi ý) trong quy tắc đồng thuận F.R.I.E.S là gì?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Bạn có quyền rút lại sự đồng ý và dừng hành động lại bất cứ lúc nào, kể cả khi trước đó bạn đã nói Có.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Bạn chỉ được phép đổi ý trước khi buổi hẹn hò bắt đầu, sau đó thì bắt buộc phải thực hiện.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Đối phương có quyền bắt bạn thực hiện nếu bạn đã lỡ đồng ý một lần trước đó.\", \"correct\": false, \"emoji\": \"🙁\" },\r\n    { \"text\": \"Sự đồng ý có giá trị vĩnh viễn và không thể thay đổi trong suốt mối quan hệ.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1390, 235, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Crush, Hẹn hò & Từ chối\'! Bạn có 3 mạng để thể hiện ứng xử văn minh và bảo vệ sự an toàn.\"}', 1, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1391, 235, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Đối diện với từ chối và hẹn hò an toàn\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Bạn (Minh) lấy hết dũng khí viết thư tỏ tình với bạn cùng lớp (Chi). Chi nhẹ nhàng từ chối vì muốn tập trung học tập. Bạn cảm thấy vô cùng buồn bã, thất vọng và tự ái dồn dập.\",\r\n      \"choices\": [\r\n        { \"text\": \"Liên tục nhắn tin nài nỉ làm phiền, đòi Chi giải thích lý do cụ thể và khóc lóc ăn vạ.\", \"nextNode\": \"fail_pester\" },\r\n        { \"text\": \"Chấp nhận nỗi buồn, tôn trọng quyết định của Chi và tâm sự với bạn thân hoặc viết nhật ký để giải tỏa cảm xúc.\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Tức giận đi nói xấu Chi kiêu căng, chảnh chọe trên nhóm chat khác để trả đũa.\", \"nextNode\": \"fail_revenge\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Sau một tuần, khi đi trên hành lang lớp học, bạn vô tình chạm mặt Chi đi ngược chiều. Cả hai đều có vẻ ngượng ngùng.\",\r\n      \"choices\": [\r\n        { \"text\": \"Cúi gằm mặt xuống đất, giả vờ như không nhìn thấy Chi và đi thẳng thật nhanh qua chỗ khác.\", \"nextNode\": \"fail_avoid\" },\r\n        { \"text\": \"Chủ động gật đầu mỉm cười nhẹ nhàng chào Chi rồi bước tiếp để giữ sự tự nhiên lịch sự.\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Chi mỉm cười chào lại, giúp không khí bớt sượng trân. Tối đó, một bạn nam khác rủ bạn đi chơi lúc 10 giờ đêm tại một bãi đất trống vắng vẻ ngoại ô thành phố.\",\r\n      \"choices\": [\r\n        { \"text\": \"Từ chối lịch sự và gợi ý địa điểm an toàn hơn: \'Giờ đó muộn rồi, chiều mai tụi mình đi uống trà sữa ở quán gần trường nha!\'\", \"nextNode\": \"success_end\" },\r\n        { \"text\": \"Đồng ý đi luôn vì muốn chứng tỏ mình dũng cảm, sành điệu và tin tưởng đối phương tuyệt đối.\", \"nextNode\": \"fail_danger\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Hoàn hảo! Bạn đã vượt qua nỗi buồn bị từ chối một cách văn minh, ứng xử tự nhiên lịch sự và biết cách bảo vệ sự an toàn cho bản thân khi hẹn hò.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_pester\": {\r\n      \"text\": \"❌ Sai rồi! Liên tục nài nỉ và làm phiền chỉ làm đối phương khó chịu và vi phạm ranh giới từ chối của họ.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_revenge\": {\r\n      \"text\": \"❌ Sai rồi! Nói xấu trả đũa sau khi bị từ chối là hành vi cờ đỏ độc hại và thiếu tôn trọng đối phương.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_avoid\": {\r\n      \"text\": \"❌ Chưa phù hợp! Trốn né gượng ép chỉ làm tăng thêm sự sượng sùng lâu dài trong mối quan hệ bạn học bè sau này.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_danger\": {\r\n      \"text\": \"❌ Chưa đúng! Hẹn hò lúc khuya muộn tại nơi vắng vẻ là hành vi thiếu an toàn, đẩy bản thân vào nguy cơ gặp nguy hiểm thể xác.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1392, 235, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại các hành vi ứng xử sau:\",\r\n  \"leftBox\": { \"title\": \"Green Flag (Văn minh)\" },\r\n  \"rightBox\": { \"title\": \"Red Flag (Độc hại)\" },\r\n  \"items\": [\r\n    { \"text\": \"Chấp nhận, tôn trọng quyết định từ chối và giữ khoảng cách lịch sự\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Khóc lóc ăn vạ, liên tục nài nỉ làm phiền bắt họ đổi ý\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Tâm sự nỗi buồn với bạn thân hoặc viết nhật ký giải tỏa\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Đi nói xấu hoặc tung tin đồn thất thiệt để trả đũa đối phương\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Từ chối tình cảm rõ ràng, dứt khoát và khéo léo không mập mờ thả thính\", \"correctBox\": \"left\" }\r\n  ]\r\n}', 3, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1393, 235, 'matching', '{\r\n  \"instruction\": \"Ghép cặp các khái niệm hẹn hò và từ chối với định nghĩa tương ứng:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Crush (Say nắng)\", \"right\": \"Cảm xúc rung động, ngưỡng mộ tự nhiên tuổi dậy thì.\" },\r\n    { \"left\": \"Hẹn hò an toàn\", \"right\": \"Chọn địa điểm công cộng, tự chủ đi lại và báo cho người thân.\" },\r\n    { \"left\": \"Từ chối rõ ràng\", \"right\": \"Sự tử tế cao nhất để tránh làm mất thời gian hy vọng giả của nhau.\" },\r\n    { \"left\": \"Bền bỉ cảm xúc\", \"right\": \"Khả năng chấp nhận thực tế và tự phục hồi sau khi bị từ chối.\" }\r\n  ]\r\n}', 4, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1394, 235, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành triết lý hẹn hò văn minh:\",\r\n  \"sentence\": \"Cảm giác say nắng một người là trải nghiệm [blank1] tuổi mới lớn. Khi hẹn hò, hãy luôn đặt sự [blank2] lên hàng đầu. Đối diện với lời từ chối bằng thái độ [blank3] và tôn trọng ranh giới của họ. Từ chối tình cảm của người khác một cách dứt khoát và [blank4] để không tạo hy vọng giả.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"tự nhiên\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"an toàn\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"văn minh\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"khéo léo\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"tự nhiên\", \"an toàn\", \"văn minh\", \"khéo léo\", \"xấu hổ\", \"bí mật\", \"độc hại\", \"mập mờ\"]\r\n}', 5, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1395, 235, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Khi bạn muốn từ chối tình cảm của một người bạn một cách khéo léo, cách ứng xử nào dưới đây là tử tế nhất?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Cảm ơn tình cảm của họ, bày tỏ dứt khoát và rõ ràng quyết định của mình để không tạo ra hy vọng giả.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Im lặng hoàn toàn, chặn liên lạc và giả vờ như không biết để họ tự hiểu và chán nản bỏ cuộc.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Nhận lời yêu thử một thời gian xem thế nào để tránh làm tổn thương tình cảm của họ ngay lập tức.\", \"correct\": false, \"emoji\": \"🙁\" },\r\n    { \"text\": \"Tỏ thái độ khinh miệt và trêu chọc họ trước mặt đông bạn bè khác trong lớp để họ bỏ cuộc.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 19:08:08', '2026-06-11 19:08:08'),
(1396, 236, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Nhận diện Cờ Đỏ & Mối Quan hệ Độc hại\'! Hãy dũng cảm bảo vệ sức khỏe tinh thần và sự an toàn của mình.\"}', 1, '2026-06-11 19:08:09', '2026-06-11 19:08:09'),
(1397, 236, 'scenario-choice', '{\r\n  \"title\": \"Cuộc phiêu lưu: Nhận diện vòng lặp độc hại và bước ra an toàn\",\r\n  \"startNode\": \"step1\",\r\n  \"nodes\": {\r\n    \"step1\": {\r\n      \"text\": \"Bạn (Vy) nhận thấy dạo gần đây người yêu (Lâm) hay quát mắng bạn thậm tệ mỗi khi bạn đi học nhóm muộn. Nhưng ngay hôm sau, Lâm lại mua trà sữa mang đến lớp, khóc lóc hứa hẹn sẽ thay đổi. Bạn cảm thấy kiệt sức và sa sút học tập.\",\r\n      \"choices\": [\r\n        { \"text\": \"Tiếp tục tha thứ và cố gắng làm hài lòng Lâm nhiều hơn để tránh cãi vã.\", \"nextNode\": \"fail_cycle\" },\r\n        { \"text\": \"Nhận diện vòng lặp bạo lực cảm xúc, chia sẻ câu chuyện với bố mẹ hoặc bạn thân để xin lời khuyên và xem xét chia tay.\", \"nextNode\": \"step2\" },\r\n        { \"text\": \"Tự làm đau bản thân để Lâm cảm thấy hối hận và đối xử tốt với mình hơn.\", \"nextNode\": \"fail_self_harm\" }\r\n      ]\r\n    },\r\n    \"step2\": {\r\n      \"text\": \"Được mọi người động viên, bạn nhắn tin chia tay Lâm. Lâm lập tức đe dọa sẽ đăng những hình ảnh chụp chung riêng tư của bạn lên mạng xã hội nếu bạn dám bỏ rơi Lâm.\",\r\n      \"choices\": [\r\n        { \"text\": \"Sợ hãi nên đành quay lại và chấp nhận mọi yêu cầu kiểm soát của Lâm để giữ bí mật.\", \"nextNode\": \"fail_submit_threat\" },\r\n        { \"text\": \"Chụp màn hình đe dọa làm bằng chứng, cắt đứt liên lạc (chặn tài khoản) và báo ngay cho bố mẹ, thầy cô hoặc gọi Tổng đài 111 để được bảo vệ kịp thời.\", \"nextNode\": \"step3\" }\r\n      ]\r\n    },\r\n    \"step3\": {\r\n      \"text\": \"Nhờ sự can thiệp của gia đình và nhà trường, Lâm đã bị xử lý và dừng hành vi đe dọa. Bạn lấy lại sự tự tin. Ngày hôm sau, bạn thấy cô bạn thân đang bị người yêu cấm chơi với nhóm bạn của mình.\",\r\n      \"choices\": [\r\n        { \"text\": \"Khuyên bạn thân mạnh dạn đặt ranh giới và chỉ ra rằng sự cấm đoán, cô lập là một Cờ Đỏ nghiêm trọng.\", \"nextNode\": \"success_end\" },\r\n        { \"text\": \"Khuyên bạn nên nghe lời người yêu để giữ gìn hòa khí và hạnh phúc lứa đôi.\", \"nextNode\": \"fail_support_isolation\" }\r\n      ]\r\n    },\r\n    \"success_end\": {\r\n      \"text\": \"🎉 Tuyệt vời! Bạn đã nhận diện cờ đỏ chính xác, dũng cảm bước ra khỏi vòng lặp độc hại an toàn, biết cách xử lý khi bị đe dọa và hỗ trợ bạn bè đúng cách.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": true\r\n    },\r\n    \"fail_cycle\": {\r\n      \"text\": \"❌ Sai rồi! Liên tục chấp nhận và tha thứ chỉ khiến bạn lún sâu vào vòng lặp bạo lực cảm xúc (gây hấn -> xin lỗi mật ngọt -> gây hấn).\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_self_harm\": {\r\n      \"text\": \"❌ Sai rồi! Tự làm hại bản thân là hành vi cực đoan gây hại nghiêm trọng cho sức khỏe tinh thần và thể chất, không giải quyết được gốc rễ vấn đề.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_submit_threat\": {\r\n      \"text\": \"❌ Chưa đúng! Nhượng bộ trước đe dọa sẽ khiến đối phương lấn lướt ranh giới hơn và tiếp tục kiểm soát bạn bằng các chiêu trò bạo lực tinh thần khác.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    },\r\n    \"fail_support_isolation\": {\r\n      \"text\": \"❌ Chưa đúng! Ủng hộ việc cô lập bạn bè khỏi các mối quan hệ xã hội là dung túng cho hành vi kiểm soát độc hại của đối phương.\",\r\n      \"isEnd\": true,\r\n      \"isSuccess\": false\r\n    }\r\n  }\r\n}', 2, '2026-06-11 19:08:09', '2026-06-11 19:08:09'),
(1398, 236, 'sorting', '{\r\n  \"instruction\": \"Hãy kéo thẻ hoặc click phân loại các hành vi sau đây:\",\r\n  \"leftBox\": { \"title\": \"Lành mạnh (Green Flag)\" },\r\n  \"rightBox\": { \"title\": \"Cờ Đỏ (Red Flag)\" },\r\n  \"items\": [\r\n    { \"text\": \"Khuyến khích bạn duy trì các mối quan hệ xã hội lành mạnh với bạn bè, gia đình\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Bắt bạn phải chụp hình gửi Zalo báo cáo vị trí liên tục để kiểm tra xem có nói dối không\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Chúc bạn làm bài đạt điểm cao và khuyên bạn nên đi học đúng giờ\", \"correctBox\": \"left\" },\r\n    { \"text\": \"Cấm đoán bạn nói chuyện hay gặp mặt tất cả những người khác giới\", \"correctBox\": \"right\" },\r\n    { \"text\": \"Đe dọa sẽ tự tử hoặc tung ảnh riêng tư của bạn lên mạng nếu bạn đòi chia tay\", \"correctBox\": \"right\" }\r\n  ]\r\n}', 3, '2026-06-11 19:08:09', '2026-06-11 19:08:09'),
(1399, 236, 'matching', '{\r\n  \"instruction\": \"Ghép cặp các khái niệm về mối quan hệ độc hại dậy thì sau:\",\r\n  \"pairs\": [\r\n    { \"left\": \"Vòng lặp độc hại\", \"right\": \"Chu kỳ: Gây hấn ➡️ Tặng quà mật ngọt ➡️ Bình yên giả tạo ➡️ Gây hấn.\" },\r\n    { \"left\": \"Sự cô lập\", \"right\": \"Hành vi cấm đoán đối phương chơi với bạn bè hoặc gặp gỡ gia đình.\" },\r\n    { \"left\": \"Kiểm soát quá mức\", \"right\": \"Đòi kiểm tra mọi tin nhắn, bắt báo cáo lịch trình sinh hoạt hàng ngày.\" },\r\n    { \"left\": \"Bước ra an toàn\", \"right\": \"Chia tay ở nơi công cộng/tin nhắn, chặn liên lạc và tìm sự trợ giúp.\" }\r\n  ]\r\n}', 4, '2026-06-11 19:08:09', '2026-06-11 19:08:09');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(1400, 236, 'fill-blank', '{\r\n  \"instruction\": \"Điền các từ thích hợp để hoàn thành đoạn văn về nhận diện cờ đỏ:\",\r\n  \"sentence\": \"Cờ đỏ là những dấu hiệu cảnh báo mối quan hệ [blank1]. Vòng lặp bạo lực cảm xúc bắt đầu từ việc gây hấn đến những lời hứa [blank2] giả tạo. Một mối quan hệ mang lại nhiều mệt mỏi hơn [blank3] là lúc cần dừng lại. Hãy mạnh dạn tìm kiếm sự [blank4] từ người lớn đáng tin cậy hoặc Tổng đài 111.\",\r\n  \"blanks\": {\r\n    \"blank1\": { \"correct\": \"độc hại\", \"placeholder\": \"...\" },\r\n    \"blank2\": { \"correct\": \"ngọt ngào\", \"placeholder\": \"...\" },\r\n    \"blank3\": { \"correct\": \"vui vẻ\", \"placeholder\": \"...\" },\r\n    \"blank4\": { \"correct\": \"trợ giúp\", \"placeholder\": \"...\" }\r\n  },\r\n  \"words\": [\"độc hại\", \"ngọt ngào\", \"vui vẻ\", \"trợ giúp\", \"bền vững\", \"cay đắng\", \"khó khăn\", \"lắng nghe\"]\r\n}', 5, '2026-06-11 19:08:09', '2026-06-11 19:08:09'),
(1401, 236, 'interaction', '{\r\n  \"question\": \"Thử thách trắc nghiệm: Khi bị đối phương đe dọa phát tán hình ảnh riêng tư hoặc tự làm đau bản thân nếu bạn chia tay, cách xử lý nào dưới đây là an toàn nhất?\",\r\n  \"enableLives\": true,\r\n  \"choices\": [\r\n    { \"text\": \"Lưu giữ bằng chứng đe dọa, cắt đứt liên lạc (chặn tài khoản) và báo ngay cho bố mẹ, thầy cô hoặc gọi Tổng đài 111 để được bảo vệ kịp thời.\", \"correct\": true, \"emoji\": \"💚\" },\r\n    { \"text\": \"Im lặng chịu đựng và chấp nhận tiếp tục mối quan hệ để bảo vệ hình ảnh cá nhân và tính mạng của đối phương.\", \"correct\": false, \"emoji\": \"😐\" },\r\n    { \"text\": \"Thách thức đối phương đăng ảnh lên mạng xã hội để chứng minh mình không sợ bị đe dọa.\", \"correct\": false, \"emoji\": \"🙁\" },\r\n    { \"text\": \"Liên hệ với nhóm bạn thân khác để lập kế hoạch đến gặp đánh dằn mặt đối phương.\", \"correct\": false, \"emoji\": \"🛑\" }\r\n  ]\r\n}', 6, '2026-06-11 19:08:09', '2026-06-11 19:08:09'),
(3154, 534, 'hook', '{\"title\": \"Bạn nghĩ sức khỏe tình dục chỉ là chuyện đi khám bệnh hay phòng tránh thai?\"}', 1, '2026-07-04 14:19:01', '2026-07-04 14:19:01'),
(3155, 534, 'explanation', '{\"bullets\": [\"Sức khỏe tình dục là sự khỏe mạnh về thể chất, cảm xúc và tinh thần liên quan đến tình dục.\", \"Nó đi kèm sự tự tôn, tôn trọng đối phương và khả năng giao tiếp cởi mở.\", \"Tìm hiểu về cơ thể mình là bước đầu tiên để bảo vệ bản thân và đưa ra quyết định đúng đắn.\"]}', 2, '2026-07-04 14:19:01', '2026-07-04 14:19:01'),
(3156, 534, 'scenario', '{\"title\": \"Nỗi lo thầm kín\", \"body\": \"Nam cảm thấy lo lắng khi cơ thể có nhiều thay đổi và có những thắc mắc thầm kín nhưng không dám hỏi ai vì sợ bị bạn bè hay bố mẹ coi là \'hư hỏng\'.\"}', 3, '2026-07-04 14:19:01', '2026-07-04 14:19:01'),
(3157, 534, 'interaction', '{\"question\": \"Bạn khuyên Nam nên làm gì?\", \"choices\": [{\"text\": \"Hỏi người lớn đáng tin hoặc dùng app EDUCare để tìm hiểu khoa học.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tự mò mẫm xem các video trên web đen để bắt chước theo.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:01', '2026-07-04 14:19:01'),
(3158, 534, 'reflection', '{\"question\": \"Bạn có từng cảm thấy ngượng ngùng khi có thắc mắc về cơ thể mình chưa?\"}', 5, '2026-07-04 14:19:01', '2026-07-04 14:19:01'),
(3159, 534, 'takeaway', '{\"items\": [\"Sức khỏe tình dục bắt đầu từ việc hiểu, trân trọng và yêu thương cơ thể của chính mình.\"]}', 6, '2026-07-04 14:19:01', '2026-07-04 14:19:01'),
(3160, 535, 'hook', '{\"title\": \"Bạn có biết mình hoàn toàn có quyền quyết định ai được chạm vào người mình và chạm ở mức nào không?\"}', 1, '2026-07-04 14:19:01', '2026-07-04 14:19:01'),
(3161, 535, 'explanation', '{\"bullets\": [\"Ranh giới cơ thể là giới hạn mà bạn đặt ra để bản thân cảm thấy an toàn và thoải mái.\", \"Không một ai, kể cả người yêu hay bạn thân, được phép chạm vào bạn nếu chưa được bạn đồng ý.\", \"Nói \'Không\' với những đụng chạm không mong muốn là quyền cơ bản của mỗi người.\"]}', 2, '2026-07-04 14:19:02', '2026-07-04 14:19:02'),
(3162, 535, 'scenario', '{\"title\": \"Bá vai khó chịu\", \"body\": \"Trong buổi liên hoan lớp, một bạn nam cứ liên tục bá vai ôm cổ làm Vy cảm thấy rất khó chịu. Vy muốn đẩy tay bạn ra nhưng sợ làm không khí lớp bị mất vui.\"}', 3, '2026-07-04 14:19:02', '2026-07-04 14:19:02'),
(3163, 535, 'interaction', '{\"question\": \"Vy nên làm gì để bảo vệ ranh giới của mình?\", \"choices\": [{\"text\": \"Nói rõ ràng và lịch sự: \'Tớ thấy hơi nóng, cậu bỏ tay ra nhé\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Cố gắng cười trừ chịu đựng để giữ không khí vui vẻ cho cả lớp.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-04 14:19:02', '2026-07-04 14:19:02'),
(3164, 535, 'reflection', '{\"question\": \"Bạn đã từng cảm thấy khó chịu vì một đụng chạm của ai đó chưa?\"}', 5, '2026-07-04 14:19:02', '2026-07-04 14:19:02'),
(3165, 535, 'takeaway', '{\"items\": [\"Cơ thể của bạn là tài sản riêng của bạn. Hãy kiên quyết bảo vệ ranh giới của mình!\"]}', 6, '2026-07-04 14:19:02', '2026-07-04 14:19:02'),
(3166, 536, 'hook', '{\"title\": \"Tại sao người lớn thường né tránh và tụi mình cũng thấy đỏ mặt khi nhắc đến hai chữ \'tình dục\'?\"}', 1, '2026-07-04 14:19:02', '2026-07-04 14:19:02'),
(3167, 536, 'explanation', '{\"bullets\": [\"Cảm giác ngại ngùng là phản ứng tâm lý tự nhiên do giáo dục và văn hóa phương Đông.\", \"Tuy nhiên, né tránh không giúp tụi mình an toàn hơn, trái lại còn dễ dẫn đến hành vi thiếu chuẩn bị.\", \"Tìm hiểu về giới tính và tình dục một cách khoa học là biểu hiện của sự chín chắn và trưởng thành.\"]}', 2, '2026-07-04 14:19:02', '2026-07-04 14:19:02'),
(3168, 536, 'scenario', '{\"title\": \"Không khí sượng trân\", \"body\": \"Khi lớp học đến tiết sinh học về hệ sinh sản, cả lớp bắt đầu cười ồ lên và xì xào bàn tán làm giáo viên phải dừng lại. Không khí trong lớp trở nên rất sượng trân.\"}', 3, '2026-07-04 14:19:02', '2026-07-04 14:19:02'),
(3169, 536, 'interaction', '{\"question\": \"Thái độ nào thể hiện sự chín chắn khi học về giới tính?\", \"choices\": [{\"text\": \"Tập trung lắng nghe, đặt câu hỏi khoa học và nghiêm túc tìm hiểu.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Hùa theo cười đùa, bàn tán bằng những từ ngữ thô tục với bạn bè.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:02', '2026-07-04 14:19:02'),
(3170, 536, 'reflection', '{\"question\": \"Bạn có cảm thấy thoải mái khi nói chuyện giới tính với bố mẹ hay thầy cô không?\"}', 5, '2026-07-04 14:19:02', '2026-07-04 14:19:02'),
(3171, 536, 'takeaway', '{\"items\": [\"Tìm hiểu về giới tính một cách khoa học là quyền lợi và là sự tự trọng của mỗi bạn trẻ.\"]}', 6, '2026-07-04 14:19:02', '2026-07-04 14:19:02'),
(3172, 537, 'hook', '{\"title\": \"Bạn có quyền từ chối chạm vào người khác ngay cả khi đó là người bạn cực kỳ quý mến không?\"}', 1, '2026-07-04 14:19:03', '2026-07-04 14:19:03'),
(3173, 537, 'explanation', '{\"bullets\": [\"Đồng thuận đụng chạm phải luôn luôn đến từ hai phía một cách tự nguyện và hào hứng.\", \"Bị ép buộc chạm hoặc đồng ý chỉ vì nể, vì sợ bị ghét đều không phải là đồng thuận xịn.\", \"Bạn luôn có quyền từ chối hoặc đổi ý bất kỳ lúc nào.\"]}', 2, '2026-07-04 14:19:03', '2026-07-04 14:19:03'),
(3174, 537, 'scenario', '{\"title\": \"Mặc cả tình cảm\", \"body\": \"Người yêu nài nỉ An: \'Yêu nhau thì phải cho chạm vào người chứ, em không tin tưởng anh à?\'. An chưa sẵn sàng nhưng sợ nếu từ chối sẽ bị người yêu giận dỗi đòi chia tay.\"}', 3, '2026-07-04 14:19:03', '2026-07-04 14:19:03'),
(3175, 537, 'interaction', '{\"question\": \"An nên ứng xử thế nào để thể hiện ranh giới cá nhân?\", \"choices\": [{\"text\": \"Kiên quyết giữ ranh giới: \'Em yêu anh nhưng em chưa sẵn sàng đụng chạm. Mong anh tôn trọng cảm xúc của em\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Thỏa hiệp đồng ý đụng chạm để làm người yêu vui lòng và giữ gìn mối quan hệ.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:03', '2026-07-04 14:19:03'),
(3176, 537, 'reflection', '{\"question\": \"Bạn từng thỏa hiệp đồng ý làm điều gì đó chỉ vì sợ người yêu giận dỗi chưa?\"}', 5, '2026-07-04 14:19:03', '2026-07-04 14:19:03'),
(3177, 537, 'takeaway', '{\"items\": [\"Tình yêu lành mạnh không bao giờ đi kèm sự ép buộc hay cảm giác tội lỗi khi đặt ranh giới Extralarge.\"]}', 6, '2026-07-04 14:19:03', '2026-07-04 14:19:03'),
(3178, 538, 'hook', '{\"title\": \"Làm sao để hỏi ý kiến đối phương trước khi đụng chạm mà không làm bầu không khí bị sượng trân?\"}', 1, '2026-07-04 14:19:03', '2026-07-04 14:19:03'),
(3179, 538, 'explanation', '{\"bullets\": [\"Hỏi trước khi chạm không làm mất đi vẻ lãng mạn mà thể hiện sự tôn trọng chân thành.\", \"Dùng những câu hỏi ngắn gọn và ngọt ngào như: \'Tớ nắm tay cậu nhé?\', \'Cậu có thoải mái không?\'.\", \"Luôn chú ý quan sát tín hiệu cơ thể: im lặng hay lảng tránh mắt là dấu hiệu họ chưa thoải mái.\"]}', 2, '2026-07-04 14:19:04', '2026-07-04 14:19:04'),
(3180, 538, 'scenario', '{\"title\": \"Lắng nghe tín hiệu cơ thể\", \"body\": \"Duy muốn nắm tay Linh khi hai đứa đi dạo. Duy băn khoăn không biết Linh có thích không vì Linh đang ôm balo trước ngực và mắt nhìn đi chỗ khác.\"}', 3, '2026-07-04 14:19:04', '2026-07-04 14:19:04'),
(3181, 538, 'interaction', '{\"question\": \"Duy nên xử lý tình huống này thế nào?\", \"choices\": [{\"text\": \"Dừng lại, đi bên cạnh Linh nói chuyện vui vẻ và chờ dịp thuận tiện khác hỏi ý kiến Linh.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Cứ tự ý luồn tay vào nắm chặt tay Linh để tạo bất ngờ lãng mạn.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-04 14:19:04', '2026-07-04 14:19:04'),
(3182, 538, 'reflection', '{\"question\": \"Bạn thích đối phương hỏi ý kiến trước khi chạm vào mình hay thích họ tự ý hành động hơn?\"}', 5, '2026-07-04 14:19:04', '2026-07-04 14:19:04'),
(3183, 538, 'takeaway', '{\"items\": [\"Hỏi ý kiến trước khi đụng chạm là Green Flag xịn nhất thể hiện sự tinh tế và tôn trọng đối phương.\"]}', 6, '2026-07-04 14:19:04', '2026-07-04 14:19:04'),
(3184, 539, 'hook', '{\"title\": \"Làm sao biết mình đã đủ lớn và sẵn sàng cho một mối quan hệ gần gũi hay tiến xa hơn?\"}', 1, '2026-07-04 14:19:04', '2026-07-04 14:19:04'),
(3185, 539, 'explanation', '{\"bullets\": [\"Sẵn sàng nghĩa là bạn hiểu rõ ranh giới, biết cách tự bảo vệ mình và hoàn toàn tự nguyện.\", \"Không có một độ tuổi chuẩn xác nào cho tất cả mọi người, mỗi người có nhịp độ phát triển riêng.\", \"Đừng tiến xa chỉ vì bạn bè xung quanh đã làm thế hoặc để chứng tỏ bản thân.\"]}', 2, '2026-07-04 14:19:04', '2026-07-04 14:19:04'),
(3186, 539, 'scenario', '{\"title\": \"Áp lực từ xung quanh\", \"body\": \"Đám bạn trong nhóm của Minh đều khoe đã có người yêu và bắt đầu đụng chạm thân mật. Minh cảm thấy rất sốt ruột và lạc loài dù thực lòng Minh chưa muốn yêu vào lúc này.\"}', 3, '2026-07-04 14:19:04', '2026-07-04 14:19:04'),
(3187, 539, 'interaction', '{\"question\": \"Bạn khuyên Minh nên làm gì?\", \"choices\": [{\"text\": \"Tôn trọng cảm xúc của bản thân, tập trung vào học tập và các sở thích cá nhân.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Cố tìm đại một bạn để yêu và tỏ ra sành điệu giống đám bạn thân.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:05', '2026-07-04 14:19:05'),
(3188, 539, 'reflection', '{\"question\": \"Bạn có đang cảm thấy áp lực phải tiến nhanh giống như bạn bè xung quanh mình không?\"}', 5, '2026-07-04 14:19:05', '2026-07-04 14:19:05'),
(3189, 539, 'takeaway', '{\"items\": [\"Mỗi người có một nhịp độ phát triển riêng. Hãy tôn trọng và bảo vệ chính tốc độ của bản thân mình.\"]}', 6, '2026-07-04 14:19:05', '2026-07-04 14:19:05'),
(3190, 540, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Sức Khỏe Tình Dục Là Gì Thế\'! Hãy cùng check-in ranh giới nhé.\"}', 1, '2026-07-04 14:19:05', '2026-07-04 14:19:05'),
(3191, 540, 'scenario-choice', '{\"title\": \"Cuộc phiêu lưu: Bảo vệ ranh giới cá nhân\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn đang đi chơi riêng cùng người yêu mới. Người yêu xích lại gần định khoác vai bạn, nhưng bạn đang cảm thấy ngượng ngùng và chưa thoải mái.\", \"choices\": [{\"text\": \"Cố gắng chịu đựng để người yêu vui lòng.\", \"nextNode\": \"fail_submit\"}, {\"text\": \"Khẽ né vai ra một chút và nói nhẹ nhàng: \'Tớ thấy hơi nóng, tụi mình đi dạo tiếp nhé\'.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Người yêu bạn tỏ vẻ hơi buồn và hỏi: \'Cậu không thích tớ à? Sao cứ giữ khoảng cách hoài vậy?\'. Bạn cảm thấy áy náy.\", \"choices\": [{\"text\": \"Đồng ý cho khoác vai để chuộc lỗi.\", \"nextNode\": \"fail_guilt\"}, {\"text\": \"Giải thích thẳng thắn: \'Tớ rất quý cậu nhưng tớ thích tụi mình tiến từ từ để tớ thấy thoải mái hơn\'.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành thử thách! Bạn đã kiên định bảo vệ ranh giới cơ thể của mình và biết cách giao tiếp lịch sự tôn trọng mối quan hệ.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_submit\": {\"text\": \"❌ Thất bại! Thỏa hiệp đụng chạm thể xác khi chưa thực sự thoải mái làm mờ ranh giới cá nhân của bạn.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_guilt\": {\"text\": \"❌ Thất bại! Nhượng bộ chỉ vì cảm thấy áy nay hay tội lỗi sẽ khiến bạn mất quyền làm chủ cơ thể mình.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-04 14:19:05', '2026-07-04 14:19:05'),
(3192, 540, 'sorting', '{\"instruction\": \"Hãy phân loại các hành vi đụng chạm sau vào đúng hộp cảm xúc:\", \"leftBox\": {\"title\": \"Đồng thuận xịn (Green Flag)\"}, \"rightBox\": {\"title\": \"Vi phạm ranh giới (Red Flag)\"}, \"items\": [{\"text\": \"Hỏi trước khi chạm: \'Tớ nắm tay cậu được không?\'\", \"correctBox\": \"left\"}, {\"text\": \"Liên tục nài nỉ đụng chạm khi đối phương im lặng\", \"correctBox\": \"right\"}, {\"text\": \"Tự ý ôm từ phía sau khi đối phương đang tập trung làm việc\", \"correctBox\": \"right\"}, {\"text\": \"Tôn trọng khi đối phương nói \'Khoan đã, tớ thấy hơi nhanh\'\", \"correctBox\": \"left\"}, {\"text\": \"Nói dỗi \'Yêu nhau thì phải cho chạm\' để ép đối phương\", \"correctBox\": \"right\"}]}', 3, '2026-07-04 14:19:05', '2026-07-04 14:19:05'),
(3193, 540, 'matching', '{\"instruction\": \"Ghép cặp các khái niệm về ranh giới cá nhân sau:\", \"pairs\": [{\"left\": \"Ranh giới cơ thể\", \"right\": \"Giới hạn giúp bạn thấy an toàn và được tôn trọng đụng chạm.\"}, {\"left\": \"Đồng thuận xịn\", \"right\": \"Sự đồng ý tự nguyện, đầy đủ thông tin và hào hứng từ cả hai.\"}, {\"left\": \"Tín hiệu phòng thủ\", \"right\": \"Các biểu hiện co người, ôm balo, tránh né ánh mắt.\"}, {\"left\": \"Check-in ranh giới\", \"right\": \"Hành động tinh tế hỏi ý kiến đối phương trước khi chạm.\"}]}', 4, '2026-07-04 14:19:05', '2026-07-04 14:19:05'),
(3194, 540, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về ranh giới cơ thể:\", \"sentence\": \"Cơ thể của bạn là của riêng [blank1]. Không ai được quyền [blank2] vào bạn nếu không được bạn đồng ý. Khi cảm thấy chưa sẵn sàng, bạn hoàn toàn có quyền nói [blank3]. Tình yêu lành mạnh phải dựa trên sự [blank4] ranh giới của nhau.\", \"blanks\": {\"blank1\": {\"correct\": \"bạn\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"chạm\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"không\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"tôn trọng\", \"placeholder\": \"...\"}}, \"words\": [\"bạn\", \"chạm\", \"không\", \"tôn trọng\", \"bố mẹ\", \"ép buộc\", \"có\", \"nghi ngờ\"]}', 5, '2026-07-04 14:19:05', '2026-07-04 14:19:05'),
(3195, 540, 'interaction', '{\"question\": \"Nếu đối phương có tín hiệu co người lại hoặc tránh né ánh mắt khi bạn tiến lại gần, phản ứng tinh tế nhất của bạn là gì?\", \"enableLives\": true, \"choices\": [{\"text\": \"Dừng lại, giữ khoảng cách và nói chuyện thoải mái tự nhiên.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tiếp tục tiến tới nắm tay để giúp họ bớt e ngại.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Tỏ thái độ giận dỗi vì nghĩ họ ghét mình.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-04 14:19:05', '2026-07-04 14:19:05'),
(3196, 541, 'hook', '{\"title\": \"Làm thế nào mà việc gần gũi thân mật lại có thể dẫn đến sự hình thành của một em bé?\"}', 1, '2026-07-04 14:19:06', '2026-07-04 14:19:06'),
(3197, 541, 'explanation', '{\"bullets\": [\"Mang thai diễn ra khi tinh trùng của bạn nam gặp và thụ tinh với trứng của bạn nữ.\", \"Sau đó, trứng đã thụ tinh di chuyển vào làm tổ tại tử cung để phát triển thành thai nhi.\", \"Để tránh thai, tụi mình cần chặn trứng rụng, chặn tinh trùng bơi vào gặp trứng, hoặc chặn làm tổ.\"]}', 2, '2026-07-04 14:19:06', '2026-07-04 14:19:06'),
(3198, 541, 'scenario', '{\"title\": \"Lầm tưởng ngây thơ\", \"body\": \"Hòa tin vào lời đồn trên mạng rằng quan hệ lần đầu tiên thì không thể dính bầu, hoặc nhảy lên nhảy xuống sau quan hệ sẽ làm trôi tinh trùng ra ngoài.\"}', 3, '2026-07-04 14:19:06', '2026-07-04 14:19:06'),
(3199, 541, 'interaction', '{\"question\": \"Quan niệm quan hệ lần đầu không dính bầu là đúng hay sai?\", \"choices\": [{\"text\": \"Sai hoàn toàn. Cơ thể luôn sẵn sàng thụ thai nếu có sự gặp gỡ của trứng và tinh trùng.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Đúng thế, lần đầu tử cung chưa mở nên an toàn.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:06', '2026-07-04 14:19:06'),
(3200, 541, 'reflection', '{\"question\": \"Bạn đã từng nghe hoặc tin vào lời đồn tránh thai kỳ lạ nào chưa?\"}', 5, '2026-07-04 14:19:06', '2026-07-04 14:19:06'),
(3201, 541, 'takeaway', '{\"items\": [\"Khoa học sinh sản không phân biệt lần đầu hay lần sau. Gần gũi không bảo vệ đều có nguy cơ dính bầu!\"]}', 6, '2026-07-04 14:19:06', '2026-07-04 14:19:06'),
(3202, 542, 'hook', '{\"title\": \"Thế giới tránh thai vô cùng đa dạng, làm sao để phân biệt được các loại vũ khí bảo vệ này?\"}', 1, '2026-07-04 14:19:06', '2026-07-04 14:19:06'),
(3203, 542, 'explanation', '{\"bullets\": [\"Nhóm rào chắn: Chặn tiếp xúc trực tiếp (ví dụ: Bao cao su, bao nữ).\", \"Nhóm nội tiết: Dùng hormone ngăn buồng trứng rụng trứng (ví dụ: Thuốc hàng ngày, miếng dán, vòng âm đạo).\", \"Nhóm lâu dài LARC: Set-and-forget, kéo dài 3-10 năm (que cấy, vòng tránh thai IUD).\"]}', 2, '2026-07-04 14:19:07', '2026-07-04 14:19:07'),
(3204, 542, 'scenario', '{\"title\": \"Hoa mắt trước lựa chọn\", \"body\": \"Mai lướt web tìm kiếm biện pháp tránh thai và thấy hàng chục loại khác nhau: que cấy, vòng, bao, miếng dán... Mai không biết phân nhóm chúng như thế nào để dễ tìm hiểu.\"}', 3, '2026-07-04 14:19:07', '2026-07-04 14:19:07'),
(3205, 542, 'interaction', '{\"question\": \"Biện pháp tránh thai nào vừa ngừa thai vừa ngăn được bệnh lây qua đường tình dục (STI)?\", \"choices\": [{\"text\": \"Bao cao su (Nhóm rào chắn).\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Que cấy tránh thai dưới da hoặc vòng tránh thai (Nhóm LARC).\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-04 14:19:07', '2026-07-04 14:19:07'),
(3206, 542, 'reflection', '{\"question\": \"Bạn thấy nhóm tránh thai nào có vẻ phù hợp nhất với thói quen sinh hoạt của mình?\"}', 5, '2026-07-04 14:19:07', '2026-07-04 14:19:07'),
(3207, 542, 'takeaway', '{\"items\": [\"Bao cao su là biện pháp duy nhất thuộc nhóm rào chắn bảo vệ bạn 2-trong-1 khỏi cả thai ngoài ý muốn và STI.\"]}', 6, '2026-07-04 14:19:07', '2026-07-04 14:19:07'),
(3208, 543, 'hook', '{\"title\": \"Tại sao gánh nặng tránh thai thường mặc định đè nặng lên vai bạn nữ, điều này có công bằng không?\"}', 1, '2026-07-04 14:19:07', '2026-07-04 14:19:07'),
(3209, 543, 'explanation', '{\"bullets\": [\"Nỗi sợ dính bầu ngoài ý muốn thường khiến bạn nữ lo lắng hơn vì trực tiếp mang thai.\", \"Tuy nhiên, an toàn tình dục là trách nhiệm chung của cả hai phía.\", \"Bạn nam chủ động chia sẻ gánh nặng bằng việc chuẩn bị bao cao su hoặc đồng hành tìm hiểu biện pháp.\"]}', 2, '2026-07-04 14:19:07', '2026-07-04 14:19:07'),
(3210, 543, 'scenario', '{\"title\": \"Nỗi lo cô độc\", \"body\": \"Vy liên tục mất ăn mất ngủ lo sợ dính bầu sau khi quan hệ không an toàn. Trong khi đó, người yêu Vy thản nhiên nói: \'Dính thì cùng lắm là cưới thôi có gì mà phải lo lắng dữ vậy\'.\"}', 3, '2026-07-04 14:19:07', '2026-07-04 14:19:07'),
(3211, 543, 'interaction', '{\"question\": \"Hành vi của người yêu Vy thể hiện điều gì?\", \"choices\": [{\"text\": \"Red flag! Vô trách nhiệm và thiếu thấu hiểu gánh nặng tâm lý và thể chất của bạn nữ.\", \"correct\": true, \"emoji\": \"🚩\"}, {\"text\": \"Sự lạc quan, mạnh mẽ giúp giải tỏa tâm lý lo sợ cho Vy.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-04 14:19:07', '2026-07-04 14:19:07'),
(3212, 543, 'reflection', '{\"question\": \"Bạn nghĩ bạn nam nên đồng hành cùng bạn nữ thế nào trong việc tránh thai?\"}', 5, '2026-07-04 14:19:07', '2026-07-04 14:19:07'),
(3213, 543, 'takeaway', '{\"items\": [\"An toàn tình dục là câu chuyện của hai người. Hãy cùng nhau gánh vác trách nhiệm bảo vệ!\"]}', 6, '2026-07-04 14:19:08', '2026-07-04 14:19:08'),
(3214, 544, 'hook', '{\"title\": \"Tại sao có những biện pháp được quảng cáo hiệu quả 99% nhưng thực tế vẫn có nhiều người dính bầu?\"}', 1, '2026-07-04 14:19:08', '2026-07-04 14:19:08'),
(3215, 544, 'explanation', '{\"bullets\": [\"Hiệu quả lý thuyết (Perfect Use): Đạt được khi sử dụng hoàn hảo tuyệt đối không sai sót.\", \"Hiệu quả thực tế (Typical Use): Thấp hơn do lỗi từ người dùng (quên thuốc, bao rách, rút không kịp).\", \"Để tăng độ an toàn, hãy chọn biện pháp ít phụ thuộc vào trí nhớ hoặc kết hợp bảo vệ kép.\"]}', 2, '2026-07-04 14:19:08', '2026-07-04 14:19:08'),
(3216, 544, 'scenario', '{\"title\": \"Con số và thực tế\", \"body\": \"Nam đọc thấy bao cao su hiệu quả 98% nên tự tin dùng bừa bãi (xé bằng răng, đeo muộn, dùng dầu dừa làm chất bôi trơn). Kết quả là bạn gái Nam trễ kinh.\"}', 3, '2026-07-04 14:19:08', '2026-07-04 14:19:08'),
(3217, 544, 'interaction', '{\"question\": \"Lý do hiệu quả thực tế của bao cao su bị giảm sút là gì?\", \"choices\": [{\"text\": \"Do người dùng sử dụng sai kỹ thuật, làm rách hoặc tuột bao.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Do nhà sản xuất luôn khai khống số liệu quảng cáo.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:08', '2026-07-04 14:19:08'),
(3218, 544, 'reflection', '{\"question\": \"Bạn có sẵn sàng học kỹ thuật sử dụng đúng cách để đạt hiệu quả ngừa thai tối đa không?\"}', 5, '2026-07-04 14:19:08', '2026-07-04 14:19:08'),
(3219, 544, 'takeaway', '{\"items\": [\"Vũ khí tốt đến mấy cũng vô dụng nếu dùng sai cách. Hãy nắm chắc kỹ năng sử dụng!\"]}', 6, '2026-07-04 14:19:08', '2026-07-04 14:19:08'),
(3220, 545, 'hook', '{\"title\": \"Làm thế nào để khơi gợi cuộc trò chuyện về tránh thai với người yêu mà không gây mất hứng?\"}', 1, '2026-07-04 14:19:08', '2026-07-04 14:19:08'),
(3221, 545, 'explanation', '{\"bullets\": [\"Trò chuyện về tránh thai trước khi quan hệ là biểu hiện của sự tôn trọng và nghiêm túc.\", \"Hãy bắt đầu lúc cả hai đang tỉnh táo, thư giãn (không phải lúc chuẩn bị lâm trận).\", \"Dùng câu mở đầu đơn giản: \'Tớ muốn tụi mình nói chuyện về cách bảo vệ để cả hai cùng an tâm\'.\"]}', 2, '2026-07-04 14:19:08', '2026-07-04 14:19:08'),
(3222, 545, 'scenario', '{\"title\": \"Cuộc nói chuyện ngập ngừng\", \"body\": \"Trang muốn bàn với người yêu về việc dùng bao cao su cho lần đi chơi xa sắp tới. Nhưng Trang e ngại người yêu sẽ nghĩ mình là người thích kiểm soát và quá tính toán.\"}', 3, '2026-07-04 14:19:08', '2026-07-04 14:19:08'),
(3223, 545, 'interaction', '{\"question\": \"Trang nên bắt đầu cuộc nói chuyện thế nào?\", \"choices\": [{\"text\": \"Bày tỏ rõ ràng: \'Tớ muốn tụi mình an tâm tận hưởng chuyến đi, nên tớ muốn bàn trước về chuyện bảo vệ nhé\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Im lặng chờ đến lúc đi chơi rồi mới lôi bao cao su ra ép người yêu dùng.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-04 14:19:08', '2026-07-04 14:19:08'),
(3224, 545, 'reflection', '{\"question\": \"Bạn có cảm thấy tự tin khi bàn bạc thẳng thắn về tránh thai với partner của mình không?\"}', 5, '2026-07-04 14:19:09', '2026-07-04 14:19:09'),
(3225, 545, 'takeaway', '{\"items\": [\"Trò chuyện thẳng thắn về bảo vệ là chất xúc tác giúp mối quan hệ bền vững và an toàn hơn.\"]}', 6, '2026-07-04 14:19:09', '2026-07-04 14:19:09'),
(3226, 546, 'hook', '{\"title\": \"Không có biện pháp tránh thai nào là tốt nhất, chỉ có biện pháp hợp nhất với bạn. Bạn dựa vào đâu để chọn?\"}', 1, '2026-07-04 14:19:09', '2026-07-04 14:19:09'),
(3227, 546, 'explanation', '{\"bullets\": [\"Dựa vào thói quen sinh hoạt (bạn có nhớ uống thuốc mỗi ngày đúng giờ không?).\", \"Dựa vào tình trạng sức khỏe (bạn có bị dị ứng cao su hay chống chỉ định hormone không?).\", \"Dựa vào mức độ riêng tư và tài chính của bản thân để đưa ra lựa chọn lâu dài.\"]}', 2, '2026-07-04 14:19:09', '2026-07-04 14:19:09'),
(3228, 546, 'scenario', '{\"title\": \"Lựa chọn cho riêng mình\", \"body\": \"Linh băn khoăn giữa uống thuốc tránh thai hàng ngày và dùng bao cao su. Linh là người hay quên lịch và cũng rất e ngại nếu bị gia đình nhìn thấy vỉ thuốc.\"}', 3, '2026-07-04 14:19:09', '2026-07-04 14:19:09'),
(3229, 546, 'interaction', '{\"question\": \"Phương án nào an toàn và tiện lợi nhất cho Linh lúc này?\", \"choices\": [{\"text\": \"Dùng bao cao su mỗi lần quan hệ, kết hợp mang theo ví riêng tư.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Uống thuốc hàng ngày và đặt chuông báo thức, chấp nhận rủi ro bị phát hiện.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-04 14:19:09', '2026-07-04 14:19:09'),
(3230, 546, 'reflection', '{\"question\": \"Bạn nghĩ yếu tố nào quan trọng nhất với bạn khi chọn phương pháp tránh thai?\"}', 5, '2026-07-04 14:19:09', '2026-07-04 14:19:09'),
(3231, 546, 'takeaway', '{\"items\": [\"Hãy thấu hiểu bản thân và lối sống của mình để đưa ra lựa chọn bảo vệ thông thái nhất.\"]}', 6, '2026-07-04 14:19:09', '2026-07-04 14:19:09'),
(3232, 547, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Bản Đồ Tránh Thai\'! Hãy cùng tìm kiếm vũ khí phù hợp nhé.\"}', 1, '2026-07-04 14:19:09', '2026-07-04 14:19:09'),
(3233, 547, 'scenario-choice', '{\"title\": \"Cuộc phiêu lưu: Bản đồ tránh thai\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn muốn lựa chọn một biện pháp tránh thai chủ động cho mối quan hệ của mình. Bạn bắt đầu từ việc thu thập thông tin.\", \"choices\": [{\"text\": \"Tin vào lời đồn quan hệ lần đầu thì không thể mang thai để khỏi phải chuẩn bị gì.\", \"nextNode\": \"fail_myth\"}, {\"text\": \"Tìm hiểu khoa học để phân loại các nhóm biện pháp: Rào chắn, Nội tiết, LARC.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Bạn nhận ra mình là người rất hay quên và có thói quen sinh hoạt không cố định giờ giấc.\", \"choices\": [{\"text\": \"Chọn uống thuốc tránh thai hàng ngày vì nghe nói hiệu quả 99% lý thuyết.\", \"nextNode\": \"fail_forget\"}, {\"text\": \"Chọn dùng bao cao su mỗi khi quan hệ hoặc cân nhắc que cấy tránh thai rảnh tay.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Chúc mừng! Bạn đã phân loại đúng các nhóm tránh thai và chọn được phương pháp phù hợp nhất với thói quen của bản thân.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_myth\": {\"text\": \"❌ Thất bại! Cơ thể sinh học luôn sẵn sàng thụ thai nếu có sự gặp gỡ giữa trứng và tinh trùng, không phân biệt số lần quan hệ.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_forget\": {\"text\": \"❌ Thất bại! Người hay quên lịch uống thuốc hàng ngày rất dễ gặp sự cố vỡ kế hoạch do nồng độ hormone không được duy trì đều đặn.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-04 14:19:10', '2026-07-04 14:19:10'),
(3234, 547, 'sorting', '{\"instruction\": \"Hãy phân loại các biện pháp tránh thai sau vào đúng nhóm kỹ thuật:\", \"leftBox\": {\"title\": \"Nhóm Nội tiết & Lâu dài\"}, \"rightBox\": {\"title\": \"Nhóm Rào chắn & Tự nhiên\"}, \"items\": [{\"text\": \"Thuốc tránh thai hàng ngày vỉ 28 viên\", \"correctBox\": \"left\"}, {\"text\": \"Bao cao su nam làm bằng latex\", \"correctBox\": \"right\"}, {\"text\": \"Que cấy tránh thai dưới da cánh tay\", \"correctBox\": \"left\"}, {\"text\": \"Xuất tinh ngoài trước khi xuất tinh\", \"correctBox\": \"right\"}, {\"text\": \"Vòng tránh thai nội tiết IUD\", \"correctBox\": \"left\"}]}', 3, '2026-07-04 14:19:10', '2026-07-04 14:19:10'),
(3235, 547, 'matching', '{\"instruction\": \"Ghép cặp các phương pháp tránh thai với hiệu quả của chúng:\", \"pairs\": [{\"left\": \"Perfect Use\", \"right\": \"Hiệu quả tránh thai đạt được khi sử dụng hoàn hảo không lỗi.\"}, {\"left\": \"Typical Use\", \"right\": \"Hiệu quả thực tế bị giảm do quên thuốc hoặc dùng sai cách.\"}, {\"left\": \"Bao cao su\", \"right\": \"Biện pháp rào chắn duy nhất bảo vệ kép ngừa cả thai và STI.\"}, {\"left\": \"LARC\", \"right\": \"Các biện pháp tránh thai lâu dài rảnh tay kéo dài 3-10 năm.\"}]}', 4, '2026-07-04 14:19:10', '2026-07-04 14:19:10'),
(3236, 547, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về hiệu quả tránh thai:\", \"sentence\": \"Có sự khác biệt lớn giữa hiệu quả [blank1] và hiệu quả thực tế của biện pháp tránh thai. Sự chênh lệch này là do lỗi [blank2] của người dùng. Để bảo vệ an toàn kép, bạn nên dùng [blank3] để ngăn ngừa cả [blank4].\", \"blanks\": {\"blank1\": {\"correct\": \"lý thuyết\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"sử dụng\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"bao cao su\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"bệnh STI\", \"placeholder\": \"...\"}}, \"words\": [\"lý thuyết\", \"sử dụng\", \"bao cao su\", \"bệnh STI\", \"thực tế\", \"nhà sản xuất\", \"thuốc khẩn cấp\", \"chu kỳ\"]}', 5, '2026-07-04 14:19:10', '2026-07-04 14:19:10'),
(3237, 547, 'interaction', '{\"question\": \"Ai là người chịu trách nhiệm chuẩn bị và thực hành các biện pháp tránh thai chủ động?\", \"enableLives\": true, \"choices\": [{\"text\": \"Cả hai bạn cùng thảo luận và chia sẻ trách nhiệm bảo vệ lẫn nhau.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Mặc định thuộc về bạn nữ vì bạn nữ là người có nguy cơ mang thai.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Chỉ thuộc về bạn nam vì bạn nam là người chủ động đụng chạm.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-04 14:19:10', '2026-07-04 14:19:10'),
(3238, 548, 'hook', '{\"title\": \"Bạn có biết loại \'áo giáp\' nào vừa ngăn mang thai ngoài ý muốn, vừa chặn đứng các bệnh lây qua đường tình dục (STI) không?\"}', 1, '2026-07-04 14:19:11', '2026-07-04 14:19:11'),
(3239, 548, 'explanation', '{\"bullets\": [\"Bao cao su (BCS) chính là \'hiệp sĩ\' đa năng nhất trong thế giới tránh thai.\", \"Hoạt động như một bức tường ngăn không cho tinh dịch tiếp xúc với cơ thể đối phương.\", \"Nhờ đó, tinh trùng không gặp được trứng, và vi khuẩn/virus cũng không có đường lây lan.\"]}', 2, '2026-07-04 14:19:11', '2026-07-04 14:19:11'),
(3240, 548, 'scenario', '{\"title\": \"Ý định bất ngờ\", \"body\": \"Huy và Mai đang ôm nhau xem phim. Không khí bắt đầu nóng lên. Huy thầm nghĩ: \'Mình chưa chuẩn bị gì cả, nhưng chắc không sao đâu nhỉ?\'. Mai thì lo lắng vì cả hai chưa ai dùng biện pháp bảo vệ nào.\"}', 3, '2026-07-04 14:19:11', '2026-07-04 14:19:11'),
(3241, 548, 'interaction', '{\"question\": \"Bạn khuyên Mai nên nhắn hoặc trả lời thế nào?\", \"choices\": [{\"text\": \"Dạ... tùy cậu á.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Phải có bao cao su mới đi tiếp được nha cậu ơi! An toàn là trên hết.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-04 14:19:11', '2026-07-04 14:19:11'),
(3242, 548, 'reflection', '{\"question\": \"Bạn từng ngại ngùng khi nghĩ đến việc yêu cầu đối phương dùng bao cao su chưa?\"}', 5, '2026-07-04 14:19:11', '2026-07-04 14:19:11'),
(3243, 548, 'takeaway', '{\"items\": [\"Bao cao su là cách duy nhất bảo vệ bạn khỏi cả hai mối lo: mang thai ngoài ý muốn và các bệnh STI.\"]}', 6, '2026-07-04 14:19:11', '2026-07-04 14:19:11'),
(3244, 549, 'hook', '{\"title\": \"Dùng bao cao su thì dễ, nhưng dùng đúng cách để không bị rách hay tuột thì bạn đã chắc chắn chưa?\"}', 1, '2026-07-04 14:19:11', '2026-07-04 14:19:11'),
(3245, 549, 'explanation', '{\"bullets\": [\"Bước 1: Check hạn sử dụng & vỏ bao phải còn phồng hơi.\", \"Bước 2: Xé vỏ bằng tay theo đường răng cưa, tránh dùng răng hay kéo.\", \"Bước 3: Xác định đúng chiều vành bao hướng ra ngoài.\", \"Bước 4: Bóp nhẹ đầu bao để đuổi hết không khí thừa trước khi vuốt.\", \"Bước 5: Vuốt bao phủ kín cậu bé từ đầu đến gốc khi đang cương cứng.\"]}', 2, '2026-07-04 14:19:11', '2026-07-04 14:19:11'),
(3246, 549, 'scenario', '{\"title\": \"Xé bao vội vã\", \"body\": \"Trong bóng tối, Nam cuống cuồng xé vỏ bao cao su bằng răng vì không tìm thấy kéo. Kết quả là bao bị xước nhẹ một vết nhỏ mà Nam không hề hay biết.\"}', 3, '2026-07-04 14:19:11', '2026-07-04 14:19:11'),
(3247, 549, 'interaction', '{\"question\": \"Hành động xé bao bằng răng của Nam là đúng hay sai?\", \"choices\": [{\"text\": \"Đúng chứ, nhanh gọn lẹ là tốt mà.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Sai hoàn toàn. Chỉ dùng tay xé nhẹ theo đường răng cưa trên vỏ bao thôi.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-04 14:19:11', '2026-07-04 14:19:11'),
(3248, 549, 'reflection', '{\"question\": \"Bạn có tự tin mình có thể hướng dẫn lại cho người khác cách dùng bao cao su đúng chuẩn không?\"}', 5, '2026-07-04 14:19:11', '2026-07-04 14:19:11'),
(3249, 549, 'takeaway', '{\"items\": [\"Một lỗi nhỏ khi dùng bao cũng có thể làm mất đi tác dụng bảo vệ. Hãy cẩn thận từng bước nhé!\"]}', 6, '2026-07-04 14:19:11', '2026-07-04 14:19:11'),
(3250, 550, 'hook', '{\"title\": \"Bạn đã bao giờ đứng trước cửa hàng tiện lợi 15 phút, giả vờ mua chai nước chỉ vì không dám với tay lấy hộp bao cao su?\"}', 1, '2026-07-04 14:19:12', '2026-07-04 14:19:12'),
(3251, 550, 'explanation', '{\"bullets\": [\"Cảm giác ngượng ngùng sợ bị đánh giá là hoàn toàn bình thường ở tuổi teen.\", \"Thực tế, nhân viên bán hàng coi đây là một mặt hàng sức khỏe bình thường như khẩu trang hay băng cá nhân.\", \"Mua bao cao su chứng tỏ bạn là người trưởng thành, văn minh và biết tự chịu trách nhiệm.\"]}', 2, '2026-07-04 14:19:12', '2026-07-04 14:19:12'),
(3252, 550, 'scenario', '{\"title\": \"Đỏ mặt trước quầy\", \"body\": \"Linh muốn mua bao cao su để sẵn trong ví cho an toàn. Nhưng khi đứng trước quầy thu ngân có vài người lớn đang xếp hàng, Linh đỏ mặt và tim đập thình thịch, định bỏ chạy ra ngoài.\"}', 3, '2026-07-04 14:19:12', '2026-07-04 14:19:12'),
(3253, 550, 'interaction', '{\"question\": \"Mẹo nào giúp Linh vượt qua nỗi ngại này hiệu quả nhất?\", \"choices\": [{\"text\": \"Mua online qua các app giao hàng hoặc tự nhủ mình đang làm việc cực kỳ trách nhiệm.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Nhờ một đứa bạn thân đi mua hộ rồi đứng ngoài chờ.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-04 14:19:12', '2026-07-04 14:19:12'),
(3254, 550, 'reflection', '{\"question\": \"Bạn nghĩ sao về việc một bạn nữ chủ động đi mua và chuẩn bị bao cao su?\"}', 5, '2026-07-04 14:19:12', '2026-07-04 14:19:12'),
(3255, 550, 'takeaway', '{\"items\": [\"Mua bao cao su không có gì là xấu hổ. Đó là biểu hiện của một người có trách nhiệm và biết tự chủ.\"]}', 6, '2026-07-04 14:19:12', '2026-07-04 14:19:12'),
(3256, 551, 'hook', '{\"title\": \"Bạn sẽ làm gì nếu đối phương thầm thì: \'Dùng bao mất cảm giác lắm, lần này không dùng nha, tớ hứa sẽ cẩn thận\'?\"}', 1, '2026-07-04 14:19:12', '2026-07-04 14:19:12'),
(3257, 551, 'explanation', '{\"bullets\": [\"Ép buộc hoặc nài nỉ từ bỏ bao cao su là hành vi vi phạm ranh giới an toàn của bạn.\", \"Không có lời hứa \'cẩn thận\' hay \'rút kịp\' nào đảm bảo an toàn 100%.\", \"Cảm xúc thăng hoa nhất chỉ có được khi cả hai hoàn toàn yên tâm và tin tưởng lẫn nhau.\"]}', 2, '2026-07-04 14:19:12', '2026-07-04 14:19:12'),
(3258, 551, 'scenario', '{\"title\": \"Lựa chọn khó xử\", \"body\": \"Hoàng nói với Vy: \'Anh yêu em mà, em không tin tưởng anh sao mà bắt dùng bao? Anh hứa sẽ rút ra đúng lúc\'. Vy thấy khó xử, sợ Hoàng giận nhưng trong lòng đầy lo lắng và bất an.\"}', 3, '2026-07-04 14:19:12', '2026-07-04 14:19:12'),
(3259, 551, 'interaction', '{\"question\": \"Giúp Vy gửi tin nhắn từ chối kiên quyết nhưng vẫn mượt mà:\", \"choices\": [{\"text\": \"Nếu anh thực sự yêu và tôn trọng em, anh sẽ cùng em dùng bao cao su để cả hai cùng an tâm.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Thôi được rồi, chỉ lần này thôi đó nha...\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:12', '2026-07-04 14:19:12'),
(3260, 551, 'reflection', '{\"question\": \"Bạn đã từng đồng ý làm một việc mình không thoải mái chỉ vì sợ người yêu giận chưa?\"}', 5, '2026-07-04 14:19:12', '2026-07-04 14:19:12'),
(3261, 551, 'takeaway', '{\"items\": [\"Không có bao cao su = Không đi tiếp. Người thực sự yêu bạn sẽ luôn đặt sự an toàn của bạn lên trên hết.\"]}', 6, '2026-07-04 14:19:12', '2026-07-04 14:19:12'),
(3262, 552, 'hook', '{\"title\": \"Chuyện gì sẽ xảy ra nếu đang giữa cuộc vui mà chiếc bao đột ngột bị rách hoặc tuột ra ngoài?\"}', 1, '2026-07-04 14:19:13', '2026-07-04 14:19:13'),
(3263, 552, 'explanation', '{\"bullets\": [\"Đừng hoảng loạn! Dừng cuộc chơi ngay lập tức.\", \"Nhẹ nhàng rút bao ra ngoài nếu bị kẹt.\", \"Tuyệt đối không thụt rửa sâu âm đạo vì hành động này đẩy tinh dịch vào trong nhanh hơn.\", \"Mua và uống thuốc tránh thai khẩn cấp càng sớm càng tốt trong vòng 72 giờ.\"]}', 2, '2026-07-04 14:19:13', '2026-07-04 14:19:13'),
(3264, 552, 'scenario', '{\"title\": \"Sự cố bất ngờ\", \"body\": \"Sau khi quan hệ, Minh phát hiện bao cao su đã bị tuột và nằm lại bên trong cơ thể An. Cả hai mặt cắt không còn một giọt máu, An định chạy đi tắm và thụt rửa thật mạnh.\"}', 3, '2026-07-04 14:19:13', '2026-07-04 14:19:13'),
(3265, 552, 'interaction', '{\"question\": \"Bạn khuyên An nên làm gì lúc này?\", \"choices\": [{\"text\": \"Bình tĩnh lấy bao ra ngoài và đi mua ngay thuốc tránh thai khẩn cấp để uống.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tắm rửa ngay lập tức và dùng vòi xịt thụt rửa thật sâu để trôi tinh dịch.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:13', '2026-07-04 14:19:13'),
(3266, 552, 'reflection', '{\"question\": \"Bạn có biết hiệu thuốc gần nhà mình nhất nằm ở đâu để phòng trường hợp khẩn cấp không?\"}', 5, '2026-07-04 14:19:13', '2026-07-04 14:19:13'),
(3267, 552, 'takeaway', '{\"items\": [\"Sự cố xảy ra cần hành động nhanh và đúng cách. Uống thuốc tránh thai khẩn cấp là cứu cánh tốt nhất lúc này.\"]}', 6, '2026-07-04 14:19:13', '2026-07-04 14:19:13'),
(3268, 553, 'hook', '{\"title\": \"Việc chuẩn bị sẵn bao cao su trong ví hay túi xách có làm bạn trông giống như \'đang tìm kiếm chuyện ấy\'?\"}', 1, '2026-07-04 14:19:13', '2026-07-04 14:19:13'),
(3269, 553, 'explanation', '{\"bullets\": [\"Nhiều người nghĩ chuẩn bị sẵn bao cao su nghĩa là lăng nhăng hoặc luôn muốn làm chuyện đó.\", \"Thực tế, đó là biểu hiện của sự chín chắn, có trách nhiệm và tôn trọng cơ thể mình.\", \"Yêu an toàn đòi hỏi sự chuẩn bị, và người có sự chuẩn bị là người làm chủ cuộc chơi.\"]}', 2, '2026-07-04 14:19:13', '2026-07-04 14:19:13'),
(3270, 553, 'scenario', '{\"title\": \"Ngăn nhỏ ví trang điểm\", \"body\": \"Chi muốn để một chiếc bao cao su vào ngăn nhỏ của ví trang điểm. Nhưng Chi sợ nếu mẹ hoặc bạn bè vô tình nhìn thấy, họ sẽ nghĩ Chi là cô gái \'không ngoan\'.\"}', 3, '2026-07-04 14:19:13', '2026-07-04 14:19:13'),
(3271, 553, 'interaction', '{\"question\": \"Quan niệm nào sau đây là văn minh và chín chắn nhất?\", \"choices\": [{\"text\": \"Chủ động chuẩn bị bao cao su là tự bảo vệ sức khỏe và tương lai của chính mình.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Chỉ có bạn nam mới cần chuẩn bị bao cao su, bạn nữ chuẩn bị trông rất kỳ cục.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-04 14:19:13', '2026-07-04 14:19:13'),
(3272, 553, 'reflection', '{\"question\": \"Bạn có cảm thấy tôn trọng một người bạn tình luôn chủ động chuẩn bị biện pháp an toàn không?\"}', 5, '2026-07-04 14:19:13', '2026-07-04 14:19:13'),
(3273, 553, 'takeaway', '{\"items\": [\"Chuẩn bị trước bao cao su không phải là hư hỏng, đó là cách bạn tự làm chủ sự an toàn của cuộc đời mình.\"]}', 6, '2026-07-04 14:19:13', '2026-07-04 14:19:13'),
(3274, 554, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Hiệp Sĩ Bao Cao Su\'! Bạn có 3 mạng để chứng minh mình là Bậc thầy Bảo vệ.\"}', 1, '2026-07-04 14:19:14', '2026-07-04 14:19:14'),
(3275, 554, 'scenario-choice', '{\"title\": \"Cuộc phiêu lưu: Đồng hành cùng bao cao su\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn và partner đang chuẩn bị thân mật. Bạn muốn sử dụng bao cao su để bảo vệ cả hai. Bạn lục tìm trong túi đồ và thấy hai lựa chọn.\", \"choices\": [{\"text\": \"Dùng chiếc bao cao su đã để dưới đáy ví da của bạn gần một năm nay.\", \"nextNode\": \"fail_wallet\"}, {\"text\": \"Lấy một chiếc bao cao su mới từ hộp cất trong tủ, kiểm tra hạn sử dụng và thấy vỏ bao còn phồng khí.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Bạn chuẩn bị mở vỏ bao ra. Do không tìm thấy kéo, partner đề xuất dùng răng xé cho nhanh.\", \"choices\": [{\"text\": \"Đồng ý dùng răng xé để không làm gián đoạn cuộc vui.\", \"nextNode\": \"fail_teeth\"}, {\"text\": \"Từ chối và dùng đầu ngón tay xé nhẹ theo mép đường răng cưa của vỏ bao.\", \"nextNode\": \"step3\"}]}, \"step3\": {\"text\": \"Trong quá trình quan hệ, bạn bỗng phát hiện bao cao su bị rách. Đối phương hốt hoảng định chạy đi thụt rửa âm đạo bằng xà phòng.\", \"choices\": [{\"text\": \"Ủng hộ đi thụt rửa ngay lập tức để trôi hết tinh dịch ra ngoài.\", \"nextNode\": \"fail_panic\"}, {\"text\": \"Dừng lại ngay, tháo bao ra và đi mua thuốc tránh thai khẩn cấp để uống càng sớm càng tốt.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Tuyệt vời! Bạn đã vượt qua thử thách một cách bình tĩnh và nắm chắc các bước sử dụng bao cao su an toàn.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_wallet\": {\"text\": \"❌ Thất bại! Bao cao su để trong ví lâu ngày chịu nhiệt độ cao và ma sát dễ bị giòn, rách và mất tác dụng bảo vệ.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_teeth\": {\"text\": \"❌ Thất bại! Dùng răng xé bao cao su rất dễ tạo ra các vết rách cực nhỏ trên cao su mà mắt thường không nhìn thấy được.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_panic\": {\"text\": \"❌ Thất bại! Thụt rửa âm đạo không những không ngừa được thai mà còn đẩy tinh trùng vào sâu hơn và gây viêm nhiễm phụ khoa.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-04 14:19:14', '2026-07-04 14:19:14'),
(3276, 554, 'sorting', '{\"instruction\": \"Hãy phân loại các hành động sử dụng bao cao su sau đây vào đúng hộp:\", \"leftBox\": {\"title\": \"Sử dụng đúng\"}, \"rightBox\": {\"title\": \"Sai lầm nguy hiểm\"}, \"items\": [{\"text\": \"Bóp nhẹ đầu bao để đuổi không khí ra ngoài trước khi đeo\", \"correctBox\": \"left\"}, {\"text\": \"Dùng chung hai bao cao su cùng lúc để tăng gấp đôi độ an toàn\", \"correctBox\": \"right\"}, {\"text\": \"Tái sử dụng bao cao su sau khi đã rửa sạch bằng nước ấm\", \"correctBox\": \"right\"}, {\"text\": \"Xé vỏ bao nhẹ nhàng bằng tay theo đường răng cưa\", \"correctBox\": \"left\"}, {\"text\": \"Dùng chất bôi trơn dạng dầu (như vaseline) chung với bao cao su latex\", \"correctBox\": \"right\"}]}', 3, '2026-07-04 14:19:14', '2026-07-04 14:19:14'),
(3277, 554, 'matching', '{\"instruction\": \"Ghép cặp các quy tắc kỹ thuật khi dùng bao cao su sau:\", \"pairs\": [{\"left\": \"Xé vỏ bằng tay\", \"right\": \"Tránh làm trầy xước hoặc rách bao cao su bên trong.\"}, {\"left\": \"Bóp nhẹ đầu bao\", \"right\": \"Loại bỏ không khí thừa để tránh bao bị nổ khi sử dụng.\"}, {\"left\": \"Bao cao su hết hạn\", \"right\": \"Lớp cao su bị khô và dễ rách, mất tính đàn hồi.\"}, {\"left\": \"Chất bôi trơn gốc nước\", \"right\": \"An toàn và không làm hỏng cấu trúc bao cao su latex.\"}]}', 4, '2026-07-04 14:19:14', '2026-07-04 14:19:14'),
(3278, 554, 'fill-blank', '{\"instruction\": \"Điền các từ thích hợp để hoàn thành đoạn văn về bao cao su:\", \"sentence\": \"Bao cao su là biện pháp duy nhất vừa giúp ngừa [blank1] vừa ngăn chặn các bệnh [blank2]. Khi gặp sự cố rách bao, bạn cần [blank3] cuộc vui ngay lập tức và sử dụng thuốc tránh thai [blank4] trong vòng 72 giờ.\", \"blanks\": {\"blank1\": {\"correct\": \"mang thai\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"lây qua đường tình dục\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"dừng\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"khẩn cấp\", \"placeholder\": \"...\"}}, \"words\": [\"mang thai\", \"lây qua đường tình dục\", \"dừng\", \"khẩn cấp\", \"tiếp tục\", \"hàng ngày\", \"rửa sạch\", \"nài nỉ\"]}', 5, '2026-07-04 14:19:14', '2026-07-04 14:19:14'),
(3279, 554, 'interaction', '{\"question\": \"Nếu đối phương từ chối dùng bao cao su vì cho rằng \'mất cảm giác\', phản ứng nào thể hiện ranh giới thông thái của bạn?\", \"enableLives\": true, \"choices\": [{\"text\": \"Tặc lưỡi đồng ý vì không muốn làm cụt hứng.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Kiên quyết từ chối: Không dùng bao thì dừng lại. An toàn của cả hai là trên hết.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Giận dỗi bỏ về và chặn liên lạc ngay lập tức.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-04 14:19:14', '2026-07-04 14:19:14'),
(3280, 555, 'hook', '{\"title\": \"Làm sao một viên thuốc nhỏ xíu lại có thể ngăn cản quá trình mang thai một cách kỳ diệu như vậy?\"}', 1, '2026-07-04 14:19:15', '2026-07-04 14:19:15'),
(3281, 555, 'explanation', '{\"bullets\": [\"Thuốc tránh thai chứa các hormone (estrogen và progestin) tương tự hormone tự nhiên trong cơ thể bạn.\", \"Chúng hoạt động bằng cách ngăn cản quá trình rụng trứng hàng tháng của buồng trứng.\", \"Đồng thời làm dày chất nhầy cổ tử cung để ngăn không cho tinh trùng bơi vào gặp trứng.\"]}', 2, '2026-07-04 14:19:15', '2026-07-04 14:19:15'),
(3282, 555, 'scenario', '{\"title\": \"Lời đồn đáng sợ\", \"body\": \"Vy nghe các chị trên mạng xã hội nói rằng uống thuốc tránh thai hàng ngày sẽ gây vô sinh vĩnh viễn, làm buồng trứng bị teo đi. Vy hoang mang cực độ.\"}', 3, '2026-07-04 14:19:15', '2026-07-04 14:19:15'),
(3283, 555, 'interaction', '{\"question\": \"Lời đồn thuốc tránh thai gây vô sinh vĩnh viễn là đúng hay sai?\", \"choices\": [{\"text\": \"Đúng vậy, rất nguy hiểm.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Sai bét. Khả năng mang thai sẽ hồi phục bình thường sau khi ngừng thuốc.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-04 14:19:15', '2026-07-04 14:19:15'),
(3284, 555, 'reflection', '{\"question\": \"Bạn đã từng nghe những lời đồn thổi đáng sợ nào về thuốc tránh thai chưa?\"}', 5, '2026-07-04 14:19:15', '2026-07-04 14:19:15'),
(3285, 555, 'takeaway', '{\"items\": [\"Thuốc tránh thai nội tiết chỉ tạm thời cho buồng trứng \'nghỉ ngơi\' và hoàn toàn không gây vô sinh vĩnh viễn.\"]}', 6, '2026-07-04 14:19:15', '2026-07-04 14:19:15'),
(3286, 556, 'hook', '{\"title\": \"Thuốc tránh thai hàng ngày có hiệu quả ngừa thai lên tới 99%, nhưng tại sao thực tế tỷ lệ thất bại vẫn xảy ra?\"}', 1, '2026-07-04 14:19:15', '2026-07-04 14:19:15'),
(3287, 556, 'explanation', '{\"bullets\": [\"Chìa khóa nằm ở tính kỷ luật: Bạn phải uống đều đặn mỗi ngày 1 viên vào cùng một khung giờ.\", \"Vỉ 21 viên: Uống hết nghỉ 7 ngày rồi uống vỉ mới.\", \"Vỉ 28 viên: Uống liên tục không nghỉ (7 viên cuối là giả dược chứa sắt/vitamin giúp duy trì thói quen).\"]}', 2, '2026-07-04 14:19:16', '2026-07-04 14:19:16'),
(3288, 556, 'scenario', '{\"title\": \"Tiệc vui quên thuốc\", \"body\": \"Trang đặt lịch uống thuốc vào lúc 9h tối. Tuy nhiên hôm nay đi sinh nhật bạn thân, Trang mải vui chơi đến tận 2h sáng mới về nhà và quên béng uống thuốc.\"}', 3, '2026-07-04 14:19:16', '2026-07-04 14:19:16'),
(3289, 556, 'interaction', '{\"question\": \"Trang phát hiện quên thuốc trễ khoảng 5 tiếng, Trang nên làm gì?\", \"choices\": [{\"text\": \"Uống ngay viên thuốc đã quên khi nhớ ra, viên tiếp theo uống đúng giờ cũ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Bỏ qua viên đó, đợi tối hôm sau uống 2 viên một lúc.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:16', '2026-07-04 14:19:16'),
(3290, 556, 'reflection', '{\"question\": \"Bạn có phải là người có tính kỷ luật tự giác cao trong sinh hoạt hàng ngày không?\"}', 5, '2026-07-04 14:19:16', '2026-07-04 14:19:16'),
(3291, 556, 'takeaway', '{\"items\": [\"Chìa khóa vàng của thuốc tránh thai hàng ngày là: Đúng giờ - Đều đặn - Không ngắt quãng.\"]}', 6, '2026-07-04 14:19:16', '2026-07-04 14:19:16'),
(3292, 557, 'hook', '{\"title\": \"Nếu bạn là một người \'não cá vàng\' ghét việc phải uống thuốc mỗi ngày, liệu có phương án nội tiết nào rảnh tay hơn?\"}', 1, '2026-07-04 14:19:16', '2026-07-04 14:19:16'),
(3293, 557, 'explanation', '{\"bullets\": [\"Miếng dán tránh thai (Patch): Nhỏ gọn dán lên da (tay, lưng). Thay miếng mới mỗi tuần một lần.\", \"Vòng âm đạo (Vaginal Ring): Vòng silicon dẻo tự đặt vào âm đạo, để nguyên 3 tuần, tháo ra 1 tuần nghỉ.\", \"Hormone được giải phóng trực tiếp qua da/niêm mạc đi thẳng vào máu, không cần qua dạ dày.\"]}', 2, '2026-07-04 14:19:16', '2026-07-04 14:19:16'),
(3294, 557, 'scenario', '{\"title\": \"Lo ngại quyền riêng tư\", \"body\": \"An không muốn để vỉ thuốc tránh thai trong phòng vì sợ bố mẹ vô tình nhìn thấy và hiểu lầm. An muốn tìm kiếm một biện pháp tránh thai nội tiết kín đáo hơn.\"}', 3, '2026-07-04 14:19:17', '2026-07-04 14:19:17'),
(3295, 557, 'interaction', '{\"question\": \"Phương pháp nào đáp ứng tốt nhất yêu cầu kín đáo và không cần nhớ uống mỗi ngày cho An?\", \"choices\": [{\"text\": \"Vòng âm đạo: Đặt ẩn bên trong cơ thể, chỉ cần nhớ thay 1 tháng 1 lần.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Thuốc tránh thai hàng ngày: Uống xong giấu kỹ dưới đáy hòm đồ cá nhân.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-04 14:19:17', '2026-07-04 14:19:17');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(3296, 557, 'reflection', '{\"question\": \"Bạn ưu tiên sự kín đáo, riêng tư hay sự quen thuộc, dễ dùng khi chọn biện pháp bảo vệ?\"}', 5, '2026-07-04 14:19:17', '2026-07-04 14:19:17'),
(3297, 557, 'takeaway', '{\"items\": [\"Miếng dán và Vòng âm đạo là sự thay thế hoàn hảo cho những ai bận rộn hoặc lo ngại tính riêng tư.\"]}', 6, '2026-07-04 14:19:17', '2026-07-04 14:19:17'),
(3298, 558, 'hook', '{\"title\": \"Thuốc tránh thai có làm bạn bị nổi mụn, tăng cân hay bỗng dưng buồn bã muốn khóc nhè không?\"}', 1, '2026-07-04 14:19:17', '2026-07-04 14:19:17'),
(3299, 558, 'explanation', '{\"bullets\": [\"Cơ thể cần từ 2-3 tháng thích nghi khi bạn mới nạp một lượng hormone tránh thai từ ngoài vào.\", \"Bạn có thể bị đau đầu nhẹ, căng ngực hoặc thay đổi tâm trạng sương sương.\", \"Những triệu chứng này thường tự biến mất khi cơ thể đã cân bằng nội tiết.\"]}', 2, '2026-07-04 14:19:17', '2026-07-04 14:19:17'),
(3300, 558, 'scenario', '{\"title\": \"Bỏ cuộc giữa chừng\", \"body\": \"Mai bắt đầu uống thuốc tránh thai được 1 tuần thì thấy hơi nhức đầu nhẹ và buồn nôn nhẹ vào sáng sớm. Mai lập tức vứt vỉ thuốc đi vì sợ thuốc gây hại.\"}', 3, '2026-07-04 14:19:17', '2026-07-04 14:19:17'),
(3301, 558, 'interaction', '{\"question\": \"Bạn khuyên Mai nên làm gì để đối phó với tác dụng phụ ban đầu?\", \"choices\": [{\"text\": \"Kiên trì thêm, chuyển thời gian uống thuốc sang ngay trước khi đi ngủ để giảm buồn nôn.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Ngừng uống ngay lập tức và chuyển sang phương pháp dân gian khác.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:17', '2026-07-04 14:19:17'),
(3302, 558, 'reflection', '{\"question\": \"Bạn có sẵn sàng chịu đựng một chút bất tiện nhỏ ban đầu để có được sự an tâm lâu dài?\"}', 5, '2026-07-04 14:19:17', '2026-07-04 14:19:17'),
(3303, 558, 'takeaway', '{\"items\": [\"Tác dụng phụ ban đầu thường nhẹ và tạm thời. Hãy lắng nghe và cho cơ thể thời gian thích nghi.\"]}', 6, '2026-07-04 14:19:17', '2026-07-04 14:19:17'),
(3304, 559, 'hook', '{\"title\": \"Sáng thức dậy bỗng phát hiện tối qua quên uống thuốc tránh thai. Bạn có nên hoảng loạn uống bù ngay?\"}', 1, '2026-07-04 14:19:17', '2026-07-04 14:19:17'),
(3305, 559, 'explanation', '{\"bullets\": [\"Nếu quên 1 viên (dưới 24h): Uống ngay viên đó khi nhớ ra, viên tiếp theo uống đúng giờ cũ. Hiệu quả ngừa thai được bảo toàn.\", \"Nếu quên từ 2 viên (trên 48h): Uống bù viên gần nhất, tiếp tục uống đúng giờ. Nhưng bắt buộc phải dùng bao cao su trong 7 ngày tiếp theo.\"]}', 2, '2026-07-04 14:19:17', '2026-07-04 14:19:17'),
(3306, 559, 'scenario', '{\"title\": \"Quên thuốc ngày đi phượt\", \"body\": \"Lan đi phượt 3 ngày và quên mang theo vỉ thuốc tránh thai hàng ngày. Trong chuyến đi, Lan có quan hệ với người yêu và nghĩ về nhà uống bù dồn 3 viên là xong.\"}', 3, '2026-07-04 14:19:18', '2026-07-04 14:19:18'),
(3307, 559, 'interaction', '{\"question\": \"Giải pháp an toàn nhất cho Lan lúc này là gì?\", \"choices\": [{\"text\": \"Uống ngay thuốc khẩn cấp vì đã quên thuốc quá 48 tiếng và quan hệ không dùng bao.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Đợi về nhà uống dồn 3 viên một lúc để bù lại những ngày đã quên.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:18', '2026-07-04 14:19:18'),
(3308, 559, 'reflection', '{\"question\": \"Bạn đã lập chuông báo thức hay cài app nhắc nhở uống thuốc tránh thai hàng ngày chưa?\"}', 5, '2026-07-04 14:19:18', '2026-07-04 14:19:18'),
(3309, 559, 'takeaway', '{\"items\": [\"Quên 1 viên uống bù ngay. Quên từ 2 viên trở lên bắt buộc dùng thêm bao cao su hỗ trợ bảo vệ.\"]}', 6, '2026-07-04 14:19:18', '2026-07-04 14:19:18'),
(3310, 560, 'hook', '{\"title\": \"Làm thế nào để biết cơ thể mình có thực sự phù hợp với các phương pháp tránh thai chứa hormone?\"}', 1, '2026-07-04 14:19:18', '2026-07-04 14:19:18'),
(3311, 560, 'explanation', '{\"bullets\": [\"Không có biện pháp tránh thai nào tốt nhất cho tất cả mọi người, chỉ có biện pháp hợp nhất với cơ thể bạn.\", \"Một số bệnh lý nền như huyết áp cao, đau nửa đầu nghiêm trọng không nên dùng hormone estrogen.\", \"Cách an toàn nhất là thăm khám và nhận tư vấn trực tiếp từ bác sĩ sản phụ khoa.\"]}', 2, '2026-07-04 14:19:18', '2026-07-04 14:19:18'),
(3312, 560, 'scenario', '{\"title\": \"Nghe lời khuyên bạn thân\", \"body\": \"Hoa có tiền sử bệnh đau nửa đầu nghiêm trọng nhưng muốn uống thuốc hàng ngày. Bạn thân Hoa bảo cứ mua về uống đại đi vì \'tớ uống suốt có sao đâu\'.\"}', 3, '2026-07-04 14:19:18', '2026-07-04 14:19:18'),
(3313, 560, 'interaction', '{\"question\": \"Hoa có nên tự ý mua thuốc về uống không?\", \"choices\": [{\"text\": \"Không nên. Tự ý uống khi có bệnh lý chống chỉ định có thể gây biến chứng sức khỏe nguy hiểm.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Có chứ, thuốc tránh thai bán tự do ở mọi nhà thuốc Tây mà.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-04 14:19:18', '2026-07-04 14:19:18'),
(3314, 560, 'reflection', '{\"question\": \"Bạn đã từng đi khám sức khỏe sinh sản lần nào chưa, hay chỉ nghe tư vấn từ bạn bè?\"}', 5, '2026-07-04 14:19:18', '2026-07-04 14:19:18'),
(3315, 560, 'takeaway', '{\"items\": [\"Hãy tôn trọng cơ thể mình bằng cách đi khám bác sĩ trước khi đưa bất kỳ loại hormone nào vào người.\"]}', 6, '2026-07-04 14:19:18', '2026-07-04 14:19:18'),
(3316, 561, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Viên Thuốc Nhỏ Bé & Nội Tiết Tránh Thai\'! Hãy chứng minh bạn đã nắm vững cách kiểm soát hormone.\"}', 1, '2026-07-04 14:19:19', '2026-07-04 14:19:19'),
(3317, 561, 'scenario-choice', '{\"title\": \"Cuộc phiêu lưu: Đồng hành cùng thuốc nội tiết\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn quyết định chọn thuốc tránh thai hàng ngày làm biện pháp bảo vệ chính của mình.\", \"choices\": [{\"text\": \"Uống bất kỳ lúc nào rảnh trong ngày, nhớ lúc nào uống lúc đó.\", \"nextNode\": \"fail_inconsistent\"}, {\"text\": \"Đặt một khung giờ cố định lúc 9h tối và cài chuông báo nhắc nhở mỗi ngày.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Hôm nay bạn đi chơi về muộn và quên uống thuốc đúng giờ, trễ khoảng 8 tiếng.\", \"choices\": [{\"text\": \"Uống bù viên đã quên ngay khi nhớ ra, và uống viên tiếp theo đúng giờ cũ.\", \"nextNode\": \"step3\"}, {\"text\": \"Bỏ qua viên đó và tối hôm sau uống 2 viên một lúc.\", \"nextNode\": \"fail_double\"}]}, \"step3\": {\"text\": \"Bạn đi du lịch xa 3 ngày nhưng quên mang vỉ thuốc theo. Trong thời gian này bạn có quan hệ tình dục không bảo vệ.\", \"choices\": [{\"text\": \"Mua thuốc tránh thai khẩn cấp uống ngay vì đã quên thuốc quá 48 tiếng.\", \"nextNode\": \"success_end\"}, {\"text\": \"Đợi về nhà rồi uống bù 3 viên cùng lúc để cơ thể hấp thụ lại.\", \"nextNode\": \"fail_catchup\"}]}, \"success_end\": {\"text\": \"🎉 Chính xác! Bạn đã xử lý quên thuốc vô cùng khoa học, bình tĩnh và an toàn.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_inconsistent\": {\"text\": \"❌ Thất bại! Thuốc tránh thai hàng ngày đòi hỏi nồng độ hormone ổn định. Uống lệch giờ quá nhiều làm giảm đáng kể hiệu quả bảo vệ.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_double\": {\"text\": \"❌ Thất bại! Uống dồn dập 2 viên một lúc khi trễ ít giờ có thể gây nôn ói và rối loạn nội tiết nhẹ không đáng có.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_catchup\": {\"text\": \"❌ Thất bại! Thuốc hàng ngày quên quá 48h mất hẳn tác dụng. Uống bù dồn dập sau nhiều ngày không có tác dụng ngừa thai ngược lại quá khứ.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-04 14:19:19', '2026-07-04 14:19:19'),
(3318, 561, 'sorting', '{\"instruction\": \"Hãy phân loại các quan điểm về tránh thai nội tiết sau đây:\", \"leftBox\": {\"title\": \"Khoa học & Đúng chuẩn\"}, \"rightBox\": {\"title\": \"Sai lầm & Tin đồn\"}, \"items\": [{\"text\": \"Uống thuốc hàng ngày đều đặn vào một khung giờ cố định mỗi ngày\", \"correctBox\": \"left\"}, {\"text\": \"Thuốc tránh thai hàng ngày gây vô sinh vĩnh viễn cho bạn nữ\", \"correctBox\": \"right\"}, {\"text\": \"Uống bù ngay 1 viên khi phát hiện quên trễ dưới 12 tiếng\", \"correctBox\": \"left\"}, {\"text\": \"Thuốc tránh thai hàng ngày bảo vệ bạn khỏi các bệnh STI\", \"correctBox\": \"right\"}, {\"text\": \"Thay miếng dán tránh thai mới mỗi tuần một lần đúng lịch\", \"correctBox\": \"left\"}]}', 3, '2026-07-04 14:19:19', '2026-07-04 14:19:19'),
(3319, 561, 'matching', '{\"instruction\": \"Ghép cặp đúng các phương pháp nội tiết với đặc tính của chúng:\", \"pairs\": [{\"left\": \"Vỉ thuốc 28 viên\", \"right\": \"Có 7 viên giả dược chứa vitamin/sắt để duy trì thói quen uống liên tục.\"}, {\"left\": \"Miếng dán tránh thai\", \"right\": \"Dán lên da (tay, vai) và giải phóng hormone qua da mỗi tuần.\"}, {\"left\": \"Vòng âm đạo\", \"right\": \"Đặt sâu vào âm đạo, để nguyên 3 tuần để giải phóng hormone tại chỗ.\"}, {\"left\": \"Estrogen & Progestin\", \"right\": \"Hai loại hormone chính ngăn cản buồng trứng rụng trứng hàng tháng.\"}]}', 4, '2026-07-04 14:19:19', '2026-07-04 14:19:19'),
(3320, 561, 'fill-blank', '{\"instruction\": \"Điền các từ thích hợp để hoàn thành đoạn văn về tránh thai nội tiết:\", \"sentence\": \"Thuốc tránh thai hàng ngày hoạt động bằng cách ngăn cản sự [blank1] của trứng. Nếu lỡ quên uống thuốc dưới [blank2] tiếng, bạn cần uống bù ngay lập tức. Hãy nhớ rằng các biện pháp nội tiết [blank3] ngăn ngừa được các bệnh [blank4].\", \"blanks\": {\"blank1\": {\"correct\": \"rụng\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"12\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"không thể\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"lây qua đường tình dục\", \"placeholder\": \"...\"}}, \"words\": [\"rụng\", \"12\", \"không thể\", \"lây qua đường tình dục\", \"thụ tinh\", \"24\", \"có thể\", \"ngoài ý muốn\"]}', 5, '2026-07-04 14:19:19', '2026-07-04 14:19:19'),
(3321, 561, 'interaction', '{\"question\": \"Khi gặp tác dụng phụ nhẹ như buồn nôn hoặc căng ngực trong 1-2 tuần đầu dùng thuốc tránh thai nội tiết, bạn nên làm gì?\", \"enableLives\": true, \"choices\": [{\"text\": \"Ngừng thuốc ngay lập tức để bảo vệ cơ thể.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Kiên trì dùng tiếp từ 2-3 tháng vì cơ thể đang tự thích nghi. Có thể đổi giờ uống sang trước khi đi ngủ để đỡ buồn nôn.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tự ý tăng gấp đôi liều lượng uống mỗi ngày để cơ thể nhanh thích nghi.\", \"correct\": false, \"emoji\": \"😐\"}]}', 6, '2026-07-04 14:19:19', '2026-07-04 14:19:19'),
(3322, 562, 'hook', '{\"title\": \"LARC là gì và tại sao chúng được gọi là biện pháp tránh thai \'nhàn hạ\' nhất?\"}', 1, '2026-07-04 14:19:19', '2026-07-04 14:19:19'),
(3323, 562, 'explanation', '{\"bullets\": [\"LARC viết tắt của Long-Acting Reversible Contraception (Tránh thai lâu dài có thể phục hồi).\", \"Các biện pháp này được thực hiện bởi nhân viên y tế một lần duy nhất và bảo vệ bạn từ 3 đến 10 năm.\", \"Ưu điểm lớn nhất là bạn không cần nhớ lịch hàng ngày, hàng tuần, loại bỏ hoàn toàn lỗi quên từ người dùng.\"]}', 2, '2026-07-04 14:19:19', '2026-07-04 14:19:19'),
(3324, 562, 'scenario', '{\"title\": \"Lười và an toàn\", \"body\": \"Thảo luôn sợ dính bầu nhưng cũng cực kỳ ghét việc phải mang bao cao su hay uống thuốc mỗi ngày. Thảo ước gì có giải pháp cắm một lần xài được vài năm.\"}', 3, '2026-07-04 14:19:20', '2026-07-04 14:19:20'),
(3325, 562, 'interaction', '{\"question\": \"LARC phù hợp với ai nhất?\", \"choices\": [{\"text\": \"Người bận rộn, hay quên và mong muốn ngừa thai lâu dài, an toàn tuyệt đối.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Người có quan hệ tần suất rất ít, chỉ vài tháng 1 lần.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-04 14:19:20', '2026-07-04 14:19:20'),
(3326, 562, 'reflection', '{\"question\": \"Bạn có thích một phương pháp tránh thai cấy/đặt một lần dùng được nhiều năm không?\"}', 5, '2026-07-04 14:19:20', '2026-07-04 14:19:20'),
(3327, 562, 'takeaway', '{\"items\": [\"LARC là nhóm tránh thai rảnh tay và hiệu quả thực tế cao nhất nhờ loại trừ hoàn toàn yếu tố quên lịch.\"]}', 6, '2026-07-04 14:19:20', '2026-07-04 14:19:20'),
(3328, 563, 'hook', '{\"title\": \"Một chiếc que nhựa nhỏ xíu cấy vào cánh tay có thể ngăn chặn mang thai suốt 3 năm ra sao?\"}', 1, '2026-07-04 14:19:20', '2026-07-04 14:19:20'),
(3329, 563, 'explanation', '{\"bullets\": [\"Que cấy (Implant) là một thanh nhựa dẻo nhỏ bằng que diêm được cấy dưới da bắp tay của bạn nữ.\", \"Giải phóng liên tục lượng progestin cực nhỏ để ngăn buồng trứng rụng trứng.\", \"Hiệu lực bảo vệ kéo dài 3 năm với hiệu quả ngừa thai vượt trội lên tới 99.9%.\"]}', 2, '2026-07-04 14:19:20', '2026-07-04 14:19:20'),
(3330, 563, 'scenario', '{\"title\": \"Chiếc que vô hình\", \"body\": \"An đi cấy que tránh thai về. An sợ bạn bè phát hiện ra và cười nhạo, nhưng khi chạm vào bắp tay, que nằm ẩn sâu dưới da hoàn toàn không thể nhìn thấy bằng mắt thường.\"}', 3, '2026-07-04 14:19:20', '2026-07-04 14:19:20'),
(3331, 563, 'interaction', '{\"question\": \"Que cấy tránh thai được thực hiện ở đâu?\", \"choices\": [{\"text\": \"Bắt buộc phải thực hiện bởi bác sĩ/nhân viên y tế tại bệnh viện phụ sản hoặc phòng khám uy tín.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tự mua que về nhà cấy vào tay theo hướng dẫn trên Youtube.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:20', '2026-07-04 14:19:20'),
(3332, 563, 'reflection', '{\"question\": \"Bạn có thấy que cấy dưới da là một biện pháp công nghệ cao thú vị không?\"}', 5, '2026-07-04 14:19:20', '2026-07-04 14:19:20'),
(3333, 563, 'takeaway', '{\"items\": [\"Que cấy tránh thai là vũ khí rảnh tay tuyệt vời, kín đáo và hiệu quả hàng đầu hiện nay.\"]}', 6, '2026-07-04 14:19:20', '2026-07-04 14:19:20'),
(3334, 564, 'hook', '{\"title\": \"Làm thế nào một chiếc dụng cụ nhỏ hình chữ T đặt trong tử cung lại bảo vệ bạn lên tới 10 năm?\"}', 1, '2026-07-04 14:19:21', '2026-07-04 14:19:21'),
(3335, 564, 'explanation', '{\"bullets\": [\"Vòng tránh thai IUD là thiết bị hình chữ T nhỏ bằng nhựa được bác sĩ đặt vào lòng tử cung.\", \"IUD Đồng: Không hormone, đồng làm thay đổi môi trường tử cung ngăn tinh trùng thụ tinh, hạn dùng 5-10 năm.\", \"IUD Nội tiết: Tiết progestin làm dày dịch cổ tử cung, giảm đau bụng kinh và rong kinh, hạn dùng 3-5 năm.\"]}', 2, '2026-07-04 14:19:21', '2026-07-04 14:19:21'),
(3336, 564, 'scenario', '{\"title\": \"Nỗi sợ vòng đồng\", \"body\": \"Lan nghe nói vòng tránh thai chữ T bằng đồng sẽ gây rong kinh và đau bụng kinh nhiều hơn nên rất lo lắng. Bác sĩ tư vấn Lan nên chuyển sang dùng loại vòng nội tiết Mirena.\"}', 3, '2026-07-04 14:19:21', '2026-07-04 14:19:21'),
(3337, 564, 'interaction', '{\"question\": \"Đặc điểm nổi bật của vòng tránh thai nội tiết là gì?\", \"choices\": [{\"text\": \"Vừa ngừa thai hiệu quả vừa giúp giảm lượng máu kinh và đau bụng kinh.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Hoàn toàn không có hormone nên không ảnh hưởng chu kỳ kinh.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-04 14:19:21', '2026-07-04 14:19:21'),
(3338, 564, 'reflection', '{\"question\": \"Nếu phải chọn IUD, bạn sẽ ưu tiên loại không hormone (đồng) hay loại giảm đau bụng (nội tiết)?\"}', 5, '2026-07-04 14:19:21', '2026-07-04 14:19:21'),
(3339, 564, 'takeaway', '{\"items\": [\"Vòng tránh thai IUD là biện pháp ngừa thai lâu đời, hiệu quả cao và cực kỳ bền bỉ.\"]}', 6, '2026-07-04 14:19:21', '2026-07-04 14:19:21'),
(3340, 565, 'hook', '{\"title\": \"Ý nghĩ đặt một vật lạ vào trong cơ thể có làm bạn cảm thấy rùng mình và lo sợ?\"}', 1, '2026-07-04 14:19:21', '2026-07-04 14:19:21'),
(3341, 565, 'explanation', '{\"bullets\": [\"Cảm giác e ngại dị vật hay sợ đau khi đặt vòng/que cấy là phản ứng tự nhiên rất phổ biến.\", \"Thực tế, quá trình đặt que cấy diễn ra trong 2-3 phút, bác sĩ sẽ gây tê tại chỗ nên bạn hoàn toàn không đau.\", \"Vật liệu làm que cấy và vòng IUD hoàn toàn tương thích sinh học, không gây đào thải hay khó chịu.\"]}', 2, '2026-07-04 14:19:21', '2026-07-04 14:19:21'),
(3342, 565, 'scenario', '{\"title\": \"Vượt qua nỗi sợ\", \"body\": \"Vy muốn đặt vòng tránh thai IUD nhưng cứ tưởng tượng bác sĩ luồn thiết bị vào người là Vy toát mồ hôi hột. Vy quyết định đi khám tư vấn và được bác sĩ giải thích quy trình rất nhẹ nhàng.\"}', 3, '2026-07-04 14:19:21', '2026-07-04 14:19:21'),
(3343, 565, 'interaction', '{\"question\": \"Làm sao để giảm bớt lo lắng trước khi thực hiện LARC?\", \"choices\": [{\"text\": \"Đến gặp bác sĩ phụ khoa uy tín để được giải thích quy trình và tư vấn giảm đau phù hợp.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Uống thuốc ngủ trước khi đi khám để không cảm thấy gì.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:21', '2026-07-04 14:19:21'),
(3344, 565, 'reflection', '{\"question\": \"Bạn có nghĩ việc chuẩn bị tâm lý và thông tin trước giúp giảm 80% cảm giác đau khi đi khám không?\"}', 5, '2026-07-04 14:19:21', '2026-07-04 14:19:21'),
(3345, 565, 'takeaway', '{\"items\": [\"Nỗi sợ thường lớn hơn thực tế. Hãy chọn bác sĩ chuyên nghiệp để quy trình diễn ra nhẹ nhàng nhất.\"]}', 6, '2026-07-04 14:19:21', '2026-07-04 14:19:21'),
(3346, 566, 'hook', '{\"title\": \"Lần đầu đi khám phụ khoa cần chuẩn bị những gì để không bị bối rối và sượng sùng?\"}', 1, '2026-07-04 14:19:22', '2026-07-04 14:19:22'),
(3347, 566, 'explanation', '{\"bullets\": [\"Chọn thời điểm sạch kinh (sau khi hết kinh 2-3 ngày) là tốt nhất để thăm khám.\", \"Vệ sinh vùng kín nhẹ nhàng bằng nước sạch, tuyệt đối không thụt rửa sâu.\", \"Chuẩn bị sẵn thông tin về chu kỳ kinh nguyệt gần nhất và các thắc mắc để hỏi bác sĩ.\"]}', 2, '2026-07-04 14:19:22', '2026-07-04 14:19:22'),
(3348, 566, 'scenario', '{\"title\": \"Cuộc hẹn đầu tiên\", \"body\": \"Hạnh lần đầu tiên đi khám phụ khoa để cấy que tránh thai. Hạnh mặc váy dài thoải mái để tiện cho quá trình khám và chuẩn bị sẵn một danh sách các câu hỏi ghi trong điện thoại.\"}', 3, '2026-07-04 14:19:22', '2026-07-04 14:19:22'),
(3349, 566, 'interaction', '{\"question\": \"Hành động chuẩn bị của Hạnh là đúng hay sai?\", \"choices\": [{\"text\": \"Rất đúng chuẩn! Mặc váy rộng rãi và ghi sẵn câu hỏi giúp cuộc khám diễn ra mượt mà.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Sai rồi, nên mặc quần jeans bó sát để lịch sự hơn.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:22', '2026-07-04 14:19:22'),
(3350, 566, 'reflection', '{\"question\": \"Bạn có sẵn sàng ghi chú lại các câu hỏi thầm kín của mình trước khi đi gặp bác sĩ không?\"}', 5, '2026-07-04 14:19:22', '2026-07-04 14:19:22'),
(3351, 566, 'takeaway', '{\"items\": [\"Khám phụ khoa là việc chăm sóc sức khỏe bình thường. Hãy chuẩn bị chu đáo để an tâm nhất.\"]}', 6, '2026-07-04 14:19:22', '2026-07-04 14:19:22'),
(3352, 567, 'hook', '{\"title\": \"Một ca cấy que hay đặt vòng Mirena có giá tiền triệu, liệu có xứng đáng để đầu tư?\"}', 1, '2026-07-04 14:19:22', '2026-07-04 14:19:22'),
(3353, 567, 'explanation', '{\"bullets\": [\"Chi phí ban đầu của LARC khá cao so với mua bao cao su hay vỉ thuốc tránh thai hàng tháng.\", \"Tuy nhiên, nếu chia nhỏ chi phí cho 3-10 năm bảo vệ, đây lại là khoản đầu tư vô cùng tiết kiệm.\", \"Quan trọng nhất, sự an tâm tuyệt đối và việc giải phóng trí não khỏi nỗi sợ quên thuốc là vô giá.\"]}', 2, '2026-07-04 14:19:22', '2026-07-04 14:19:22'),
(3354, 567, 'scenario', '{\"title\": \"Bài toán kinh tế\", \"body\": \"Hồng phân vân vì que cấy tránh thai có giá khá cao so với túi tiền học sinh. Khi làm phép tính chia nhỏ chi phí cho 36 tháng sử dụng, Hồng nhận ra mỗi ngày chỉ mất vài nghìn đồng.\"}', 3, '2026-07-04 14:19:22', '2026-07-04 14:19:22'),
(3355, 567, 'interaction', '{\"question\": \"Đánh giá về chi phí của biện pháp LARC:\", \"choices\": [{\"text\": \"Chi phí ban đầu cao nhưng tính dài hạn lại vô cùng tiết kiệm và hiệu quả ngừa thai cực cao.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Quá đắt đỏ và lãng phí, chỉ nên dùng bao cao su rẻ tiền.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-04 14:19:22', '2026-07-04 14:19:22'),
(3356, 567, 'reflection', '{\"question\": \"Bạn có đồng ý rằng sự an tâm không lo lắng dính bầu ngoài ý muốn đáng giá hơn chi phí bỏ ra?\"}', 5, '2026-07-04 14:19:23', '2026-07-04 14:19:23'),
(3357, 567, 'takeaway', '{\"items\": [\"Hãy nhìn nhận việc tránh thai lâu dài như một khoản đầu tư bền vững cho tương lai của bạn.\"]}', 6, '2026-07-04 14:19:23', '2026-07-04 14:19:23'),
(3358, 568, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Biện Pháp Lâu Dài & Rảnh Tay\'! Hãy kiểm tra kiến thức nhé.\"}', 1, '2026-07-04 14:19:23', '2026-07-04 14:19:23'),
(3359, 568, 'scenario-choice', '{\"title\": \"Cuộc phiêu lưu: Lựa chọn LARC\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn muốn chọn một phương án tránh thai rảnh tay hiệu quả cao và không phụ thuộc vào trí nhớ hàng ngày.\", \"choices\": [{\"text\": \"Chọn uống thuốc tránh thai khẩn cấp sau mỗi lần quan hệ cho tiện.\", \"nextNode\": \"fail_emergency\"}, {\"text\": \"Đến phòng khám phụ khoa để tìm hiểu về các biện pháp lâu dài LARC.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Bác sĩ giới thiệu hai giải pháp: Que cấy dưới da cánh tay (3 năm) và Vòng tránh thai IUD (5-10 năm). Bạn lo sợ đặt dị vật sẽ rất đau.\", \"choices\": [{\"text\": \"Sợ đau nên bỏ về không khám nữa.\", \"nextNode\": \"fail_fear\"}, {\"text\": \"Lắng nghe bác sĩ giải thích quy trình gây tê tại chỗ nhanh gọn, đồng ý tiến hành cấy que.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành thử thách! Bạn đã hiểu đúng về LARC, vượt qua nỗi sợ tâm lý để có giải pháp bảo vệ lâu dài cực kỳ an toàn.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_emergency\": {\"text\": \"❌ Thất bại! Thuốc khẩn cấp không phải là biện pháp lâu dài, lạm dụng gây hại lớn cho nội tiết và hiệu quả ngừa thai thấp.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_fear\": {\"text\": \"❌ Thất bại! Trốn tránh vì nỗi sợ tưởng tượng khiến bạn mất đi cơ hội tiếp cận phương pháp bảo vệ tốt nhất.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-04 14:19:23', '2026-07-04 14:19:23'),
(3360, 568, 'sorting', '{\"instruction\": \"Hãy phân loại các đặc điểm sau vào đúng biện pháp tránh thai lâu dài:\", \"leftBox\": {\"title\": \"Que cấy tránh thai (Implant)\"}, \"rightBox\": {\"title\": \"Vòng tránh thai (IUD)\"}, \"items\": [{\"text\": \"Một thanh nhựa dẻo nhỏ cấy dưới da bắp tay của bạn nữ\", \"correctBox\": \"left\"}, {\"text\": \"Thiết bị hình chữ T đặt vào bên trong lòng tử cung\", \"correctBox\": \"right\"}, {\"text\": \"Có hiệu lực bảo vệ ngừa thai kéo dài 3 năm liên tục\", \"correctBox\": \"left\"}, {\"text\": \"Loại bằng đồng không chứa hormone có hạn dùng lên tới 10 năm\", \"correctBox\": \"right\"}, {\"text\": \"Loại nội tiết giúp giảm đau bụng kinh và giảm lượng máu kinh\", \"correctBox\": \"right\"}]}', 3, '2026-07-04 14:19:23', '2026-07-04 14:19:23'),
(3361, 568, 'matching', '{\"instruction\": \"Ghép cặp đúng các khái niệm y tế liên quan đến LARC:\", \"pairs\": [{\"left\": \"LARC\", \"right\": \"Nhóm tránh thai lâu dài có thể đảo ngược hiệu quả cực cao.\"}, {\"left\": \"Gây tê tại chỗ\", \"right\": \"Thủ thuật y tế giúp quá trình cấy que tránh thai hoàn toàn không đau.\"}, {\"left\": \"Dị vật tương thích\", \"right\": \"Vật liệu an toàn không gây phản ứng đào thải của cơ thể.\"}, {\"left\": \"Bác sĩ phụ khoa\", \"right\": \"Người duy nhất được quyền thực hiện đặt vòng hoặc cấy que tránh thai.\"}]}', 4, '2026-07-04 14:19:23', '2026-07-04 14:19:23'),
(3362, 568, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về tránh thai lâu dài:\", \"sentence\": \"Các biện pháp tránh thai lâu dài LARC có độ hiệu quả ngừa thai thực tế lên tới [blank1] do loại bỏ hoàn toàn yếu tố [blank2] của người dùng. Quá trình cấy que diễn ra rất [blank3] nhờ thủ thuật gây tê. Hãy luôn thực hiện tại [blank4] uy tín để đảm bảo an toàn.\", \"blanks\": {\"blank1\": {\"correct\": \"99%\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"hay quên\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"nhẹ nhàng\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"bệnh viện\", \"placeholder\": \"...\"}}, \"words\": [\"99%\", \"hay quên\", \"nhẹ nhàng\", \"bệnh viện\", \"50%\", \"tự làm\", \"đau đớn\", \"hiệu thuốc\"]}', 5, '2026-07-04 14:19:23', '2026-07-04 14:19:23'),
(3363, 568, 'interaction', '{\"question\": \"Mặc dù que cấy và vòng tránh thai ngừa thai cực tốt, chúng có ngăn ngừa được bệnh lây qua đường tình dục (STI) không?\", \"enableLives\": true, \"choices\": [{\"text\": \"Hoàn toàn không. Bạn vẫn cần sử dụng bao cao su để phòng tránh STI khi quan hệ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Có chứ, cơ chế hormone diệt sạch mọi vi khuẩn đường tình dục.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Có, màng tử cung dày lên sẽ chặn đứng mọi virus.\", \"correct\": false, \"emoji\": \"😐\"}]}', 6, '2026-07-04 14:19:23', '2026-07-04 14:19:23'),
(3364, 569, 'hook', '{\"title\": \"Bạn sẽ làm gì nếu bao cao su bị rách giữa chừng hoặc bạn lỡ \'vượt ranh giới\' mà hoàn toàn không bảo vệ?\"}', 1, '2026-07-04 14:19:23', '2026-07-04 14:19:23'),
(3365, 569, 'explanation', '{\"bullets\": [\"Đừng hoảng sợ hay tự trách móc bản thân, sự cố là điều không ai mong muốn.\", \"Thuốc tránh thai khẩn cấp (thuốc ngày hôm sau) hoạt động như một nút Undo tạm thời.\", \"Thuốc trì hoãn việc rụng trứng để ngăn tinh trùng gặp trứng, ngăn cản thụ thai.\"]}', 2, '2026-07-04 14:19:23', '2026-07-04 14:19:23'),
(3366, 569, 'scenario', '{\"title\": \"Khủng hoảng rách bao\", \"body\": \"Lần đầu tiên làm chuyện ấy, Hùng và Linh gặp sự cố rách bao cao su. Linh khóc nức nở vì lo sợ có thai, Hùng hoang mang tột độ không biết làm sao.\"}', 3, '2026-07-04 14:19:23', '2026-07-04 14:19:23'),
(3367, 569, 'interaction', '{\"question\": \"Bạn khuyên Hùng nhắn tin an ủi Linh và giải quyết tình huống thế nào?\", \"choices\": [{\"text\": \"Đừng khóc nữa cậu ơi, giờ tụi mình đi mua thuốc tránh thai khẩn cấp uống ngay nhé, vẫn còn kịp mà.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tớ cũng sợ quá, hay cậu đi tắm rồi nhảy lên nhảy xuống thật mạnh xem sao...\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:24', '2026-07-04 14:19:24'),
(3368, 569, 'reflection', '{\"question\": \"Bạn có từng rơi vào trạng thái hoảng loạn vì lo sợ mang thai ngoài ý muốn chưa?\"}', 5, '2026-07-04 14:19:24', '2026-07-04 14:19:24'),
(3369, 569, 'takeaway', '{\"items\": [\"Sự cố xảy ra là điều không ai muốn, nhưng bạn luôn có nút Undo khẩn cấp trong vòng 72-120 giờ.\"]}', 6, '2026-07-04 14:19:24', '2026-07-04 14:19:24'),
(3370, 570, 'hook', '{\"title\": \"Thuốc tránh thai khẩn cấp có phải cứ uống lúc nào cũng được, hay có một \'thời hạn vàng\' bắt buộc?\"}', 1, '2026-07-04 14:19:24', '2026-07-04 14:19:24'),
(3371, 570, 'explanation', '{\"bullets\": [\"Loại chứa Levonorgestrel (Postinor, Mifestad...): Hiệu quả cao nhất trong vòng 72 giờ (3 ngày) sau quan hệ.\", \"Loại chứa Ulipristal acetate (Ella...): Hiệu lực kéo dài lên đến 120 giờ (5 ngày).\", \"Hãy nhớ: Thuốc khẩn cấp không có tác dụng phá thai nếu trứng đã làm tổ thành công.\"]}', 2, '2026-07-04 14:19:24', '2026-07-04 14:19:24'),
(3372, 570, 'scenario', '{\"title\": \"Sự cố cuối tuần\", \"body\": \"Vy gặp sự cố vào tối thứ Sáu. Vì ngại đi mua vào cuối tuần, Vy đợi đến chiều thứ Hai (sau khoảng 68 tiếng) mới ra hiệu thuốc mua thuốc loại 72h uống.\"}', 3, '2026-07-04 14:19:24', '2026-07-04 14:19:24'),
(3373, 570, 'interaction', '{\"question\": \"Đánh giá hiệu quả thuốc uống lúc này của Vy:\", \"choices\": [{\"text\": \"Hiệu quả đã giảm đi rất nhiều. Vy nên uống càng sớm càng tốt sau sự cố.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Uống lúc nào trong vòng 72 giờ hiệu quả cũng y hệt nhau nên không sao.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:24', '2026-07-04 14:19:24'),
(3374, 570, 'reflection', '{\"question\": \"If gặp sự cố, bạn có sẵn sàng đi mua thuốc uống ngay lập tức không hay sẽ chần chừ?\"}', 5, '2026-07-04 14:19:24', '2026-07-04 14:19:24'),
(3375, 570, 'takeaway', '{\"items\": [\"Uống càng sớm, hiệu quả càng cao. Tốt nhất là trong vòng 24 giờ đầu tiên sau khi gặp sự cố.\"]}', 6, '2026-07-04 14:19:24', '2026-07-04 14:19:24'),
(3376, 571, 'hook', '{\"title\": \"Tại sao sau khi uống thuốc tránh thai khẩn cấp, nhiều bạn trẻ vẫn cảm thấy vô cùng tội lỗi và lo sợ tột cùng?\"}', 1, '2026-07-04 14:19:24', '2026-07-04 14:19:24'),
(3377, 571, 'explanation', '{\"bullets\": [\"Thay đổi hormone đột ngột cùng áp lực lo sợ làm phát sinh nhiều cảm xúc tiêu cực.\", \"Bình tĩnh lại: Bạn đã hành động đúng đắn và kịp thời để bảo vệ bản thân.\", \"Hãy nhẹ nhàng vỗ về cảm xúc của mình thay vì dằn vặt tự trách.\"]}', 2, '2026-07-04 14:19:25', '2026-07-04 14:19:25'),
(3378, 571, 'scenario', '{\"title\": \"Dằn vặt suốt đêm\", \"body\": \"Sau khi uống thuốc khẩn cấp, Hoa liên tục tự dằn vặt: \'Sao mình lại dại dột thế nhỉ? Bố mẹ mà biết chắc mình chết mất\'. Hoa khóc suốt đêm và không dám nói chuyện với bạn trai.\"}', 3, '2026-07-04 14:19:25', '2026-07-04 14:19:25'),
(3379, 571, 'interaction', '{\"question\": \"Hãy chọn một thông điệp vỗ về bản thân mà Hoa cần nghe lúc này?\", \"choices\": [{\"text\": \"Mình đã xử lý sự cố một cách thông minh và kịp thời. Mình có quyền tự bảo vệ mình.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Mình thật tệ hại và đáng xấu hổ vì để chuyện này xảy ra.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:25', '2026-07-04 14:19:25'),
(3380, 571, 'reflection', '{\"question\": \"Bạn thường làm gì để tự trấn an bản thân khi gặp chuyện cực kỳ căng thẳng?\"}', 5, '2026-07-04 14:19:25', '2026-07-04 14:19:25'),
(3381, 571, 'takeaway', '{\"items\": [\"Uống thuốc khẩn cấp là hành động tự chịu trách nhiệm, không phải điều đáng hổ thẹn. Hãy dịu dàng với bản thân!\"]}', 6, '2026-07-04 14:19:25', '2026-07-04 14:19:25'),
(3382, 572, 'hook', '{\"title\": \"Việc uống thuốc tránh thai khẩn cấp chỉ là việc của bạn nữ, bạn nam hoàn toàn đứng ngoài cuộc sao?\"}', 1, '2026-07-04 14:19:25', '2026-07-04 14:19:25'),
(3383, 572, 'explanation', '{\"bullets\": [\"Quan hệ tình dục là sự đồng thuận từ hai phía, trách nhiệm xử lý sự cố cũng phải thuộc về cả hai.\", \"Thuốc khẩn cấp có lượng hormone cực cao, có thể gây buồn nôn, trễ kinh và đau bụng cho bạn nữ.\", \"Bạn nam cần chủ động đi mua thuốc, hỗ trợ tài chính và chăm sóc cảm xúc cho bạn nữ.\"]}', 2, '2026-07-04 14:19:25', '2026-07-04 14:19:25'),
(3384, 572, 'scenario', '{\"title\": \"Lời thoái thác\", \"body\": \"Sau khi bao cao su bị rách, Quân nói với Mai: \'Mai tự ra tiệm thuốc mua uống nha, anh con trai đi mua mấy cái này ngại lắm\'. Mai tủi thân lủi thủi đi mua một mình dưới mưa.\"}', 3, '2026-07-04 14:19:25', '2026-07-04 14:19:25'),
(3385, 572, 'interaction', '{\"question\": \"Hành vi của Quân thể hiện điều gì?\", \"choices\": [{\"text\": \"Red flag! Trốn tránh trách nhiệm và thiếu sự quan tâm tối thiểu đối với partner.\", \"correct\": true, \"emoji\": \"🚩\"}, {\"text\": \"Bình thường, con trai ngại mua đồ nhạy cảm là dễ hiểu.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-04 14:19:25', '2026-07-04 14:19:25'),
(3386, 572, 'reflection', '{\"question\": \"Nếu là bạn nam, bạn có sẵn sàng chủ động đi mua thuốc tránh thai khẩn cấp cho người yêu mình không?\"}', 5, '2026-07-04 14:19:25', '2026-07-04 14:19:25'),
(3387, 572, 'takeaway', '{\"items\": [\"Cùng nhau tận hưởng thì hãy cùng nhau gánh vác trách nhiệm. Sự quan tâm lúc hoạn nạn là Green Flag xịn nhất.\"]}', 6, '2026-07-04 14:19:25', '2026-07-04 14:19:25'),
(3388, 573, 'hook', '{\"title\": \"Bạn đã biết cách mua và uống thuốc tránh thai khẩn cấp đúng chuẩn để đạt hiệu quả cao nhất chưa?\"}', 1, '2026-07-04 14:19:26', '2026-07-04 14:19:26'),
(3389, 573, 'explanation', '{\"bullets\": [\"Không cần đơn thuốc của bác sĩ, hãy ra nhà thuốc Tây hỏi thẳng: \'Bán cho em thuốc tránh thai khẩn cấp\'.\", \"Nếu bị nôn trong vòng 2 giờ đầu sau khi uống thuốc, bạn bắt buộc phải uống bù viên khác.\", \"Theo dõi kinh nguyệt. Nếu trễ kinh quá 1 tuần, hãy mua ngay que thử thai để kiểm tra.\"]}', 2, '2026-07-04 14:19:26', '2026-07-04 14:19:26'),
(3390, 573, 'scenario', '{\"title\": \"Cơ thể nhạy cảm\", \"body\": \"Linh uống thuốc khẩn cấp được 45 phút thì bị nôn sạch do dạ dày nhạy cảm. Linh nghĩ thuốc đã trôi xuống ruột rồi nên không cần uống lại nữa.\"}', 3, '2026-07-04 14:19:26', '2026-07-04 14:19:26'),
(3391, 573, 'interaction', '{\"question\": \"Linh nên làm gì tiếp theo?\", \"choices\": [{\"text\": \"Mua uống bù ngay một viên khác vì thuốc chưa kịp hấp thụ đã bị nôn ra ngoài.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Cứ kệ vậy đi, thuốc ngấm nhanh lắm lo gì.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:26', '2026-07-04 14:19:26'),
(3392, 573, 'reflection', '{\"question\": \"Bạn có cảm thấy e ngại khi phải nói chuyện trực tiếp với dược sĩ ở tiệm thuốc không?\"}', 5, '2026-07-04 14:19:26', '2026-07-04 14:19:26'),
(3393, 573, 'takeaway', '{\"items\": [\"Uống thuốc sớm, uống nhiều nước và nhớ uống bù nếu bị nôn trong vòng 2 tiếng nhé!\"]}', 6, '2026-07-04 14:19:26', '2026-07-04 14:19:26'),
(3394, 574, 'hook', '{\"title\": \"Tại sao các bác sĩ luôn khuyến cáo không nên uống thuốc tránh thai khẩn cấp quá 2 lần trong một tháng?\"}', 1, '2026-07-04 14:19:26', '2026-07-04 14:19:26'),
(3395, 574, 'explanation', '{\"bullets\": [\"Thuốc khẩn cấp chứa lượng hormone cực kỳ cao (gấp nhiều lần thuốc hàng ngày) để ép cơ thể dừng rụng trứng.\", \"Lạm dụng thuốc sẽ làm rối loạn nội tiết nặng nề, gây rong kinh, kinh nguyệt không đều và giảm hẳn hiệu quả của thuốc ở những lần sau.\", \"Nhớ kỹ: Thuốc khẩn cấp chỉ là phương án B dự phòng, không phải phương án A hàng ngày.\"]}', 2, '2026-07-04 14:19:26', '2026-07-04 14:19:26'),
(3396, 574, 'scenario', '{\"title\": \"Chủ quan vì có thuốc\", \"body\": \"Cường và Vy không dùng bao cao su vì Vy nghĩ: \'Cứ quan hệ xong uống viên khẩn cấp là an tâm, tháng này mình mới uống có 3 lần thôi mà\'. Vy thấy chu kỳ kinh nguyệt của mình biến mất luôn.\"}', 3, '2026-07-04 14:19:26', '2026-07-04 14:19:26'),
(3397, 574, 'interaction', '{\"question\": \"Số lần tối đa nên dùng thuốc khẩn cấp trong 1 tháng là bao nhiêu?\", \"choices\": [{\"text\": \"Tối đa 1-2 lần, chỉ dùng khi thực sự gặp sự cố khẩn cấp.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Uống thoải mái mỗi khi quan hệ không dùng bao cao su.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:26', '2026-07-04 14:19:26'),
(3398, 574, 'reflection', '{\"question\": \"Bạn có đang lạm dụng thuốc khẩn cấp thay vì sử dụng các biện pháp tránh thai chủ động khác không?\"}', 5, '2026-07-04 14:19:26', '2026-07-04 14:19:26'),
(3399, 574, 'takeaway', '{\"items\": [\"Thuốc khẩn cấp là chiếc phao cứu sinh, không phải là chiếc thuyền để bạn đi hàng ngày.\"]}', 6, '2026-07-04 14:19:26', '2026-07-04 14:19:26'),
(3400, 575, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Nút Undo Phút Chót\'! Bạn có 3 mạng để xử lý khủng hoảng một cách an toàn nhất.\"}', 1, '2026-07-04 14:19:27', '2026-07-04 14:19:27'),
(3401, 575, 'scenario-choice', '{\"title\": \"Cuộc phiêu lưu: Xử lý sự cố rách bao\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn gặp sự cố rách bao cao su khi đang quan hệ. Cả hai đều rất lo lắng.\", \"choices\": [{\"text\": \"Chạy đi thụt rửa âm đạo ngay lập tức để đẩy sạch tinh trùng ra ngoài.\", \"nextNode\": \"fail_douch\"}, {\"text\": \"Giữ bình tĩnh, từ bỏ ý định thụt rửa và đi đến hiệu thuốc mua thuốc khẩn cấp.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Đã trôi qua 36 tiếng kể từ khi gặp sự cố, bạn chuẩn bị chọn thuốc khẩn cấp.\", \"choices\": [{\"text\": \"Uống loại Levonorgestrel 72h ngay lập tức, hiểu rằng hiệu lực có giảm nhẹ nhưng vẫn hiệu quả.\", \"nextNode\": \"step3\"}, {\"text\": \"Chờ thêm một ngày nữa để đi khám bác sĩ cho chắc chắn rồi mới uống.\", \"nextNode\": \"fail_wait\"}]}, \"step3\": {\"text\": \"Uống thuốc được 1 tiếng, dạ dày của bạn nhạy cảm và bạn nôn ra hết.\", \"choices\": [{\"text\": \"Bỏ qua vì nghĩ thuốc đã kịp ngấm vào máu rồi.\", \"nextNode\": \"fail_vomit\"}, {\"text\": \"Ra hiệu thuốc mua và uống bù ngay một viên khác.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã bảo vệ bản thân thành công nhờ hành động nhanh và cực kỳ đúng khoa học.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_douch\": {\"text\": \"❌ Thất bại! Thụt rửa âm đạo không có tác dụng ngừa thai, trái lại đẩy tinh dịch vào trong sâu hơn và làm tổn thương niêm mạc.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_wait\": {\"text\": \"❌ Thất bại! Đối với thuốc tránh thai khẩn cấp, thời gian là vàng. Chờ đợi quá lâu làm mất đi thời gian hiệu lực tốt nhất của thuốc.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_vomit\": {\"text\": \"❌ Thất bại! Nôn dưới 2 tiếng nghĩa là cơ thể chưa kịp hấp thụ thuốc. Bạn bắt buộc phải uống bù viên khác.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-04 14:19:27', '2026-07-04 14:19:27'),
(3402, 575, 'sorting', '{\"instruction\": \"Hãy phân loại các hành động xử lý khẩn cấp sau:\", \"leftBox\": {\"title\": \"Nên làm\"}, \"rightBox\": {\"title\": \"Tránh xa\"}, \"items\": [{\"text\": \"Uống thuốc khẩn cấp càng sớm càng tốt trong vòng 24 giờ đầu sau sự cố\", \"correctBox\": \"left\"}, {\"text\": \"Sử dụng thuốc tránh thai khẩn cấp mỗi tuần thay thế bao cao su\", \"correctBox\": \"right\"}, {\"text\": \"Uống bù viên khác nếu bị nôn trong vòng 2 giờ sau khi uống\", \"correctBox\": \"left\"}, {\"text\": \"Thụt rửa âm đạo bằng nước rửa phụ khoa thật sâu để làm sạch tinh dịch\", \"correctBox\": \"right\"}, {\"text\": \"Mua que thử thai kiểm tra nếu trễ kinh nguyệt quá 1 tuần\", \"correctBox\": \"left\"}]}', 3, '2026-07-04 14:19:27', '2026-07-04 14:19:27'),
(3403, 575, 'matching', '{\"instruction\": \"Ghép cặp các khái niệm về tránh thai khẩn cấp dưới đây:\", \"pairs\": [{\"left\": \"Levonorgestrel\", \"right\": \"Thuốc khẩn cấp loại 72 giờ, hiệu quả tốt nhất trong 24 giờ đầu.\"}, {\"left\": \"Ulipristal acetate (Ella)\", \"right\": \"Thuốc khẩn cấp loại 120 giờ, hiệu lực tốt hơn khi uống muộn.\"}, {\"left\": \"Nôn dưới 2 tiếng\", \"right\": \"Trường hợp bắt buộc phải uống bù viên khác để đảm bảo hiệu quả.\"}, {\"left\": \"Lạm dụng thuốc khẩn cấp\", \"right\": \"Gây rối loạn nội tiết nặng nề, rong kinh và làm giảm hiệu lực thuốc.\"}]}', 4, '2026-07-04 14:19:27', '2026-07-04 14:19:27'),
(3404, 575, 'fill-blank', '{\"instruction\": \"Điền các từ thích hợp để hoàn thành đoạn văn sau về tránh thai khẩn cấp:\", \"sentence\": \"Thuốc tránh thai khẩn cấp hoạt động bằng cách [blank1] sự rụng trứng tạm thời. Đây chỉ là phương án [blank2], không được lạm dụng như kẹo. Nếu bị trễ kinh quá [blank3] tuần, bạn cần sử dụng [blank4] để kiểm tra.\", \"blanks\": {\"blank1\": {\"correct\": \"trì hoãn\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"dự phòng\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"1\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"que thử thai\", \"placeholder\": \"...\"}}, \"words\": [\"trì hoãn\", \"dự phòng\", \"1\", \"que thử thai\", \"kích thích\", \"thường xuyên\", \"3\", \"bao cao su\"]}', 5, '2026-07-04 14:19:27', '2026-07-04 14:19:27'),
(3405, 575, 'interaction', '{\"question\": \"Bạn trai nói: \'Đã uống thuốc khẩn cấp rồi thì không cần lo lắng hay đi mua bao cao su cho những lần sau nữa\'. Bạn phản ứng thế nào?\", \"enableLives\": true, \"choices\": [{\"text\": \"Đồng ý vì thuốc khẩn cấp bảo vệ được cả tháng.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Không đồng ý. Thuốc khẩn cấp chỉ bảo vệ cho lần quan hệ sự cố trước đó, không ngừa được mang thai tương lai và không ngừa được STI.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Lờ đi và làm theo ý bạn trai.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-04 14:19:27', '2026-07-04 14:19:27'),
(3406, 576, 'hook', '{\"title\": \"\'Tớ sẽ rút ra kịp thời mà, đừng lo!\' - Lời hứa này liệu có đáng tin cậy 100% như bạn nghĩ?\"}', 1, '2026-07-04 14:19:27', '2026-07-04 14:19:27'),
(3407, 576, 'explanation', '{\"bullets\": [\"Trước khi thực sự xuất tinh, cơ thể bạn nam đã tiết ra dịch nhờn (pre-cum) để bôi trơn.\", \"Dịch nhờn pre-cum hoàn toàn có thể chứa hàng triệu tinh trùng khỏe mạnh.\", \"Chỉ cần một giọt nhỏ chạm vào rìa ngoài âm đạo, khả năng dính bầu vẫn xảy ra.\"]}', 2, '2026-07-04 14:19:27', '2026-07-04 14:19:27'),
(3408, 576, 'scenario', '{\"title\": \"Lời hứa tự tin\", \"body\": \"Lâm quả quyết với bạn gái: \'Tớ kiểm tra được mà, yên tâm không sao đâu\'. Bạn gái Lâm lo lắng nhưng đành gật đầu vì tin vào \'kỹ năng rút kịp\' của Lâm.\"}', 3, '2026-07-04 14:19:27', '2026-07-04 14:19:27'),
(3409, 576, 'interaction', '{\"question\": \"Dịch nhờn pre-cum tiết ra trước khi xuất tinh có chứa tinh trùng không?\", \"choices\": [{\"text\": \"Hoàn toàn không có, chỉ bôi trơn thôi.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Có thể chứa tinh trùng khỏe mạnh và gây mang thai ngoài ý muốn.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-04 14:19:27', '2026-07-04 14:19:27'),
(3410, 576, 'reflection', '{\"question\": \"Bạn từng tin rằng xuất tinh ngoài là một biện pháp tránh thai an toàn chưa?\"}', 5, '2026-07-04 14:19:28', '2026-07-04 14:19:28'),
(3411, 576, 'takeaway', '{\"items\": [\"Xuất tinh ngoài giống như chơi xổ số với tương lai của bạn. Đừng giao sự an toàn cho dịch nhờn pre-cum!\"]}', 6, '2026-07-04 14:19:28', '2026-07-04 14:19:28'),
(3412, 577, 'hook', '{\"title\": \"Bạn có tự tin giao phó sự an toàn của mình cho một chiếc app tính ngày rụng trứng trên điện thoại?\"}', 1, '2026-07-04 14:19:28', '2026-07-04 14:19:28'),
(3413, 577, 'explanation', '{\"bullets\": [\"Cơ thể con người không phải là một cỗ máy lập trình sẵn.\", \"Stress, thức khuya, thi cử căng thẳng hay thay đổi sinh hoạt đều có thể làm trứng rụng sớm hoặc muộn bất thường.\", \"App chỉ tính toán dựa trên thuật toán trung bình của quá khứ, không phản ánh chính xác 100% thời gian rụng trứng.\"]}', 2, '2026-07-04 14:19:28', '2026-07-04 14:19:28'),
(3414, 577, 'scenario', '{\"title\": \"Màu xanh lá trên màn hình\", \"body\": \"Mai mở app theo dõi kinh nguyệt thấy hiển thị hôm nay là \'Ngày an toàn (Màu xanh)\'. Mai đồng ý quan hệ không dùng bao vì nghĩ app thông minh thế thì không bao giờ sai.\"}', 3, '2026-07-04 14:19:28', '2026-07-04 14:19:28'),
(3415, 577, 'interaction', '{\"question\": \"Đánh giá quyết định tin tưởng vào app của Mai:\", \"choices\": [{\"text\": \"Red flag! Chu kỳ tuổi dậy thì biến động rất lớn, tin app để quan hệ không an toàn rất dễ dính bầu.\", \"correct\": true, \"emoji\": \"🚩\"}, {\"text\": \"Green flag, thời đại số tin tưởng app là đúng đắn.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-04 14:19:28', '2026-07-04 14:19:28'),
(3416, 577, 'reflection', '{\"question\": \"Bạn có nhận thấy chu kỳ kinh nguyệt của mình thỉnh thoảng bị trễ hay đến sớm do thi cử căng thẳng không?\"}', 5, '2026-07-04 14:19:28', '2026-07-04 14:19:28'),
(3417, 577, 'takeaway', '{\"items\": [\"Cơ thể bạn không hoạt động theo thuật toán của app. Đừng dùng \'ngày an toàn\' để đánh cược!\"]}', 6, '2026-07-04 14:19:28', '2026-07-04 14:19:28'),
(3418, 578, 'hook', '{\"title\": \"Màng phim tránh thai VCF hay chất diệt tinh trùng nghe thật hiện đại, nhưng liệu chúng có đủ sức bảo vệ bạn một mình?\"}', 1, '2026-07-04 14:19:28', '2026-07-04 14:19:28'),
(3419, 578, 'explanation', '{\"bullets\": [\"Chất diệt tinh trùng (Spermicides) làm bất động tinh trùng nhưng có tỷ lệ thất bại thực tế lên tới 28% nếu dùng đơn độc.\", \"Lớp màng có thể tan không đều hoặc đặt sai vị trí dẫn đến tinh trùng lọt qua.\", \"Chất này chỉ hoạt động tốt nhất khi dùng làm đồng đội hỗ trợ cho bao cao su.\"]}', 2, '2026-07-04 14:19:28', '2026-07-04 14:19:28'),
(3420, 578, 'scenario', '{\"title\": \"Tự tin quảng cáo\", \"body\": \"Vy mua màng phim tránh thai VCF về dùng vì nghe quảng cáo \'tự nhiên như không dùng gì\'. Vy hoàn toàn không dùng bao cao su đi kèm vì nghĩ màng phim đã diệt sạch tinh trùng.\"}', 3, '2026-07-04 14:19:28', '2026-07-04 14:19:28'),
(3421, 578, 'interaction', '{\"question\": \"Đánh giá mức độ rủi ro mang thai của Vy lúc này:\", \"choices\": [{\"text\": \"Rất cao. Màng phim VCF dùng một mình có tỷ lệ ngừa thai thực tế khá thấp.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Rất thấp, màng phim diệt tinh trùng cực đỉnh rồi.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:28', '2026-07-04 14:19:28'),
(3422, 578, 'reflection', '{\"question\": \"Bạn có xu hướng dễ dàng tin vào các lời quảng cáo thần kỳ trên mạng xã hội về các sản phẩm tránh thai không?\"}', 5, '2026-07-04 14:19:28', '2026-07-04 14:19:28'),
(3423, 578, 'takeaway', '{\"items\": [\"Chất diệt tinh trùng chỉ là đồng đội hỗ trợ, tuyệt đối không được giao nhiệm vụ bảo vệ chính một mình.\"]}', 6, '2026-07-04 14:19:28', '2026-07-04 14:19:28'),
(3424, 579, 'hook', '{\"title\": \"Làm thế nào để nói \'Không\' khi đối phương dỗi: \'Không dùng bao mới chứng tỏ cậu tin tưởng tớ chứ\'?\"}', 1, '2026-07-04 14:19:29', '2026-07-04 14:19:29'),
(3425, 579, 'explanation', '{\"bullets\": [\"Đây là một dạng thao túng tâm lý (guilt-tripping) đánh vào tình cảm của bạn.\", \"Tin tưởng không đồng nghĩa với việc mạo hiểm sức khỏe, ranh giới cơ thể và tương lai của bản thân.\", \"Một mối quan hệ lành mạnh phải tôn trọng sự an toàn và cảm giác thoải mái của nhau.\"]}', 2, '2026-07-04 14:19:29', '2026-07-04 14:19:29'),
(3426, 579, 'scenario', '{\"title\": \"Mặc cả niềm tin\", \"body\": \"Duy nài nỉ Vy: \'Dùng bao ngột ngạt lắm, tớ hứa sẽ xuất ngoài. Cậu không tin tớ à?\'. Vy sợ Duy nghĩ mình không yêu Duy nên phân vân có nên đồng ý.\"}', 3, '2026-07-04 14:19:29', '2026-07-04 14:19:29'),
(3427, 579, 'interaction', '{\"question\": \"Giúp Vy gửi tin nhắn từ chối kiên quyết nhưng vẫn mượt mà:\", \"choices\": [{\"text\": \"Tớ yêu cậu, nhưng tớ yêu bản thân mình trước. Tớ chỉ quan hệ khi có bao cao su để cả hai cùng an tâm.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Ừm... vậy cậu nhớ cẩn thận nha, tớ lo lắm á.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:29', '2026-07-04 14:19:29'),
(3428, 579, 'reflection', '{\"question\": \"Bạn có sợ bị người yêu giận hay chia tay nếu bạn kiên quyết bảo vệ ranh giới của mình không?\"}', 5, '2026-07-04 14:19:29', '2026-07-04 14:19:29'),
(3429, 579, 'takeaway', '{\"items\": [\"Tình yêu đích thực không bao giờ đòi hỏi bạn phải đánh đổi sự an toàn của bản thân để chứng minh lòng tin.\"]}', 6, '2026-07-04 14:19:29', '2026-07-04 14:19:29'),
(3430, 580, 'hook', '{\"title\": \"Làm thế nào để từ chối các đề xuất nguy hiểm như xuất tinh ngoài một cách nhanh gọn, dứt khoát mà không làm sứt mẻ tình cảm?\"}', 1, '2026-07-04 14:19:29', '2026-07-04 14:19:29'),
(3431, 580, 'explanation', '{\"bullets\": [\"Chuẩn bị sẵn kịch bản từ chối trong đầu để tránh bị bất ngờ, bối rối.\", \"Sử dụng cấu trúc \'Tớ cảm thấy... nên tớ muốn...\' để tập trung vào cảm xúc cá nhân.\", \"Đưa ra giải pháp thay thế an toàn ngay lập tức để chuyển hướng cuộc hội thoại sang hướng tích cực.\"]}', 2, '2026-07-04 14:19:29', '2026-07-04 14:19:29'),
(3432, 580, 'scenario', '{\"title\": \"Kịch bản từ chối\", \"body\": \"Trong lúc ôm nhau, Nam định không dùng bao cao su và bảo: \'Tớ rút kịp mà\'. Vy khựng lại, Vy muốn dừng lại để nói chuyện nghiêm túc.\"}', 3, '2026-07-04 14:19:30', '2026-07-04 14:19:30'),
(3433, 580, 'interaction', '{\"question\": \"Vy nên chọn kịch bản từ chối nào lịch sự và kiên quyết nhất?\", \"choices\": [{\"text\": \"Tớ thấy lo lắng nếu tụi mình xuất tinh ngoài vì tỷ lệ mang thai vẫn rất cao. Tớ muốn tụi mình dùng bao cao su để cả hai đều thoải mái.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Cậu bị điên à, xuất tinh ngoài thế để dính bầu chết à? Nghỉ đi!\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:30', '2026-07-04 14:19:30'),
(3434, 580, 'reflection', '{\"question\": \"Bạn đã bao giờ luyện tập trước một câu từ chối để tự bảo vệ mình chưa?\"}', 5, '2026-07-04 14:19:30', '2026-07-04 14:19:30'),
(3435, 580, 'takeaway', '{\"items\": [\"Từ chối rõ ràng và đưa ra giải pháp an toàn là cách bảo vệ cả bạn và mối quan hệ của hai người.\"]}', 6, '2026-07-04 14:19:30', '2026-07-04 14:19:30'),
(3436, 581, 'hook', '{\"title\": \"Bạn có sẵn sàng chịu đựng những tháng ngày mất ăn mất ngủ vì trễ kinh chỉ để đổi lấy vài phút chủ quan?\"}', 1, '2026-07-04 14:19:30', '2026-07-04 14:19:30'),
(3437, 581, 'explanation', '{\"bullets\": [\"Hãy tự hỏi: Nếu chuyện tồi tệ nhất xảy ra, mình và đối phương có đủ khả năng tự chịu trách nhiệm chưa?\", \"Ở tuổi 12-15, việc đi học và tương lai phát triển bản thân là ưu tiên cao nhất.\", \"Lựa chọn biện pháp an toàn tuyệt đối là cách thông minh nhất để bạn bảo vệ ước mơ của mình.\"]}', 2, '2026-07-04 14:19:30', '2026-07-04 14:19:30'),
(3438, 581, 'scenario', '{\"title\": \"Tháng ngày lo sợ\", \"body\": \"An trễ kinh 5 ngày sau khi quan hệ xuất tinh ngoài với người yêu. Mỗi ngày trôi qua với An đều là địa ngục, An không thể tập trung học bài, khóc lóc trong nhà tắm vì sợ hãi.\"}', 3, '2026-07-04 14:19:30', '2026-07-04 14:19:30'),
(3439, 581, 'interaction', '{\"question\": \"Điều gì đáng sợ nhất đối với học sinh tuổi teen khi mang thai ngoài ý muốn?\", \"choices\": [{\"text\": \"Phải đối mặt với việc dang dở học hành, sự thất vọng của gia đình và áp lực tương lai quá lớn.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Chỉ là trễ kinh thôi, không có gì đáng lo sợ cả.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:30', '2026-07-04 14:19:30'),
(3440, 581, 'reflection', '{\"question\": \"Bạn cảm thấy thế nào khi nhìn thấy những người bạn cùng trang lứa phải đối mặt với hậu quả của việc mang thai ngoài ý muốn?\"}', 5, '2026-07-04 14:19:30', '2026-07-04 14:19:30'),
(3441, 581, 'takeaway', '{\"items\": [\"Yên tâm học tập và tận hưởng tuổi trẻ có giá trị hơn rất nhiều so với những rủi ro do sự thiếu chuẩn bị mang lại.\"]}', 6, '2026-07-04 14:19:30', '2026-07-04 14:19:30');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(3442, 582, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Xuất tinh ngoài & Tính chu kỳ\'! Hãy chứng minh bạn biết cách né tránh những trò chơi may rủi.\"}', 1, '2026-07-04 14:19:30', '2026-07-04 14:19:30'),
(3443, 582, 'scenario-choice', '{\"title\": \"Cuộc phiêu lưu: Đối mặt với các đề xuất rủi ro\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn trai đề nghị quan hệ không dùng bao cao su và hứa hẹn: \'Yên tâm tớ sẽ xuất tinh ngoài kịp thời\'.\", \"choices\": [{\"text\": \"Tin tưởng lời hứa và đồng ý quan hệ xuất tinh ngoài.\", \"nextNode\": \"fail_precum\"}, {\"text\": \"Từ chối thẳng thắn: \'Pre-cum vẫn chứa tinh trùng, tụi mình bắt buộc phải dùng bao cao su\'.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Bạn trai tiếp tục thuyết phục: \'Hôm nay là ngày an toàn hiển thị màu xanh trên app của cậu mà, không cần dùng bao đâu!\'\", \"choices\": [{\"text\": \"Tin vào thuật toán của app và đồng ý không dùng bao cao su.\", \"nextNode\": \"fail_app\"}, {\"text\": \"Giải thích: \'Stress hay sinh hoạt thay đổi có thể làm trứng rụng bất thường. App chỉ để tham khảo thôi\'.\", \"nextNode\": \"step3\"}]}, \"step3\": {\"text\": \"Bạn trai đưa ra một miếng dán phim VCF và bảo đặt cái này là đủ tự nhiên rồi, không cần bao cao su ngột ngạt.\", \"choices\": [{\"text\": \"Đồng ý dùng màng phim VCF đơn độc vì nghe quảng cáo rất khoa học.\", \"nextNode\": \"fail_vcf\"}, {\"text\": \"Kiên quyết: \'Màng phim VCF dùng một mình có tỷ lệ thất bại thực tế 28%, tụi mình phải dùng bao cao su\'.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc thử thách! Bạn đã kiên định bảo vệ bản thân trước mọi phương pháp tránh thai rủi ro cao.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_precum\": {\"text\": \"❌ Thất bại! Dịch nhờn pre-cum tiết ra trước khi xuất tinh vẫn có chứa tinh trùng và gây dính bầu như thường.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_app\": {\"text\": \"❌ Thất bại! Chu kỳ tuổi dậy thì thường xuyên thay đổi do biến động sinh lý. Tính ngày an toàn theo app rất dễ dính bầu.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_vcf\": {\"text\": \"❌ Thất bại! Chất diệt tinh trùng/màng phim VCF dùng một mình có tỷ lệ rò rỉ rất lớn, không đủ làm lá chắn độc lập.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-04 14:19:31', '2026-07-04 14:19:31'),
(3444, 582, 'sorting', '{\"instruction\": \"Hãy phân loại các phương pháp tránh thai sau đây vào đúng hộp hiệu quả:\", \"leftBox\": {\"title\": \"Khoa học & An toàn cao\"}, \"rightBox\": {\"title\": \"May rủi & Rủi ro lớn\"}, \"items\": [{\"text\": \"Sử dụng bao cao su đúng cách từ đầu đến cuối\", \"correctBox\": \"left\"}, {\"text\": \"Xuất tinh ngoài (Pulling out) trước khi xuất tinh\", \"correctBox\": \"right\"}, {\"text\": \"Uống thuốc tránh thai hàng ngày đúng giờ cố định\", \"correctBox\": \"left\"}, {\"text\": \"Tính ngày an toàn dựa theo app điện thoại\", \"correctBox\": \"right\"}, {\"text\": \"Dùng màng phim tránh thai VCF đơn độc\", \"correctBox\": \"right\"}]}', 3, '2026-07-04 14:19:31', '2026-07-04 14:19:31'),
(3445, 582, 'matching', '{\"instruction\": \"Ghép cặp đúng các khái niệm rủi ro tránh thai sau:\", \"pairs\": [{\"left\": \"Dịch nhờn Pre-cum\", \"right\": \"Chất bôi trơn tự nhiên chứa tinh trùng gây mang thai ngoài ý muốn.\"}, {\"left\": \"App tính chu kỳ\", \"right\": \"Chỉ dùng theo dõi sức khỏe, không dùng làm biện pháp ngừa thai chính.\"}, {\"left\": \"Màng phim VCF\", \"right\": \"Chất diệt tinh trùng, có tỷ lệ thất bại thực tế 28% nếu đi một mình.\"}, {\"left\": \"Rút ra kịp thời\", \"right\": \"Lời hứa không an toàn vì khó kiểm soát phản xạ xuất tinh khi thăng hoa.\"}]}', 4, '2026-07-04 14:19:31', '2026-07-04 14:19:31'),
(3446, 582, 'fill-blank', '{\"instruction\": \"Điền các từ thích hợp để hoàn thành đoạn văn sau về các rủi ro tránh thai:\", \"sentence\": \"Xuất tinh ngoài là phương pháp ngừa thai có độ [blank1] vô cùng cao. Dịch nhờn tiết ra trước khi xuất tinh vẫn có chứa [blank2]. Việc tính ngày an toàn bằng app rất dễ sai lệch do chu kỳ của teen thường biến động vì [blank3]. Biện pháp bảo vệ tốt nhất vẫn là sử dụng [blank4] chuẩn chỉnh.\", \"blanks\": {\"blank1\": {\"correct\": \"rủi ro\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"tinh trùng\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"stress\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"bao cao su\", \"placeholder\": \"...\"}}, \"words\": [\"rủi ro\", \"tinh trùng\", \"stress\", \"bao cao su\", \"an toàn\", \"nước tiểu\", \"thời tiết\", \"thuốc khẩn cấp\"]}', 5, '2026-07-04 14:19:31', '2026-07-04 14:19:31'),
(3447, 582, 'interaction', '{\"question\": \"Đối phương nói: \'Nếu cậu bắt dùng bao cao su thì chứng tỏ cậu không tin tưởng tớ và không thực sự yêu tớ\'. Câu trả lời thể hiện sự tự tôn của bạn?\", \"enableLives\": true, \"choices\": [{\"text\": \"Xin lỗi cậu nha, vậy lần này tụi mình cứ... tự nhiên nhé.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Yêu thương và tin tưởng nhau là phải cùng nhau bảo vệ sức khỏe và tương lai của nhau. Không có bao cao su thì tớ từ chối.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tức giận quát mắng và chặn liên lạc của đối phương.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-04 14:19:31', '2026-07-04 14:19:31'),
(3448, 583, 'hook', '{\"title\": \"Bệnh lây truyền qua đường tình dục (STI) có phải là thứ gì đó xa xôi, chỉ người lớn mới bị?\"}', 1, '2026-07-04 14:19:31', '2026-07-04 14:19:31'),
(3449, 583, 'explanation', '{\"bullets\": [\"STI viết tắt của Sexually Transmitted Infections. Rất phổ biến ở mọi lứa tuổi có quan hệ.\", \"Lây nhiễm thông qua trao đổi dịch sinh dục hoặc tiếp xúc trực tiếp da kề da khu vực nhạy cảm.\", \"Bất kỳ ai bắt đầu đụng chạm vùng kín đều có khả năng tiếp xúc với tác nhân gây bệnh.\"]}', 2, '2026-07-04 14:19:31', '2026-07-04 14:19:31'),
(3450, 583, 'scenario', '{\"title\": \"Suy nghĩ ngây thơ\", \"body\": \"Huy nghĩ chỉ có những người có lối sống \'buông thả\' mới bị bệnh, còn bạn bè học sinh chăm ngoan như tụi mình thì không bao giờ có thể bị lây STI.\"}', 3, '2026-07-04 14:19:31', '2026-07-04 14:19:31'),
(3451, 583, 'interaction', '{\"question\": \"Nhận định của Huy có đúng không?\", \"choices\": [{\"text\": \"Sai rồi. Vi khuẩn và virus không phân biệt lối sống, chỉ cần tiếp xúc không an toàn là lây.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Đúng thế, học sinh ngoan có sức đề kháng tốt nên khó bị lây.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:31', '2026-07-04 14:19:31'),
(3452, 583, 'reflection', '{\"question\": \"Bạn đã từng có định kiến xấu về những người mắc bệnh lây truyền qua đường tình dục chưa?\"}', 5, '2026-07-04 14:19:31', '2026-07-04 14:19:31'),
(3453, 583, 'takeaway', '{\"items\": [\"STI là vấn đề sức khỏe bình thường, bất kỳ ai cũng có thể bị lây nhiễm nếu không bảo vệ.\"]}', 6, '2026-07-04 14:19:31', '2026-07-04 14:19:31'),
(3454, 584, 'hook', '{\"title\": \"Làm sao biết cơ thể đang nhiễm STI khi nhìn bên ngoài hoàn toàn khỏe mạnh, không triệu chứng?\"}', 1, '2026-07-04 14:19:32', '2026-07-04 14:19:32'),
(3455, 584, 'explanation', '{\"bullets\": [\"Rất nhiều bệnh STI (như chlamydia, lậu) diễn ra hoàn toàn thầm lặng không có biểu hiện rõ ràng.\", \"Bạn không thể biết đối phương có bệnh hay không chỉ bằng cách quan sát ngoại hình.\", \"Triệu chứng có thể là: dịch tiết bất thường, ngứa ngáy, tiểu buốt hoặc các vết loét nhỏ.\"]}', 2, '2026-07-04 14:19:32', '2026-07-04 14:19:32'),
(3456, 584, 'scenario', '{\"title\": \"Bề ngoài khỏe mạnh\", \"body\": \"Vy quan sát người yêu thấy rất sạch sẽ, điển trai và tự tin. Vy nghĩ anh ấy chắc chắn 100% là người sạch bệnh nên không cần dùng biện pháp bảo vệ.\"}', 3, '2026-07-04 14:19:32', '2026-07-04 14:19:32'),
(3457, 584, 'interaction', '{\"question\": \"Có thể nhận biết bệnh STI bằng mắt thường không?\", \"choices\": [{\"text\": \"Không thể. Nhiều bệnh STI hoàn toàn không có triệu chứng ban đầu.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Có thể, người nhiễm STI thường da dẻ nhợt nhạt và có vết loét lộ rõ.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:32', '2026-07-04 14:19:32'),
(3458, 584, 'reflection', '{\"question\": \"Bạn có hiểu tại sao xét nghiệm định kỳ là cách duy nhất để khẳng định có bệnh hay không?\"}', 5, '2026-07-04 14:19:32', '2026-07-04 14:19:32'),
(3459, 584, 'takeaway', '{\"items\": [\"Bề ngoài sạch sẽ không đảm bảo bên trong không có mầm bệnh. Hãy luôn dùng bao cao su bảo vệ!\"]}', 6, '2026-07-04 14:19:32', '2026-07-04 14:19:32'),
(3460, 585, 'hook', '{\"title\": \"Tại sao việc thừa nhận mắc bệnh STI lại đáng sợ hơn chính căn bệnh đó đối với nhiều người?\"}', 1, '2026-07-04 14:19:32', '2026-07-04 14:19:32'),
(3461, 585, 'explanation', '{\"bullets\": [\"Sự phán xét xã hội biến các bệnh lây nhiễm thành sự xấu hổ về nhân cách.\", \"Mắc STI đơn thuần là một tai nạn sức khỏe, giống như bạn bị cảm cúm hay đau mắt hột.\", \"Phát hiện sớm và chữa trị kịp thời là cách tự bảo vệ mình và có trách nhiệm xã hội.\"]}', 2, '2026-07-04 14:19:32', '2026-07-04 14:19:32'),
(3462, 585, 'scenario', '{\"title\": \"Nỗi lo phán xét\", \"body\": \"Minh phát hiện vùng kín nổi vài nốt mụn lạ ngứa ngáy. Minh vô cùng sợ hãi, khóc suốt và không dám đi khám vì sợ bác sĩ và người lớn nghĩ mình là đứa hư hỏng.\"}', 3, '2026-07-04 14:19:32', '2026-07-04 14:19:32'),
(3463, 585, 'interaction', '{\"question\": \"Khuyên Minh hành động thế nào là đúng đắn nhất?\", \"choices\": [{\"text\": \"Bình tĩnh, đặt lịch khám tại trung tâm da liễu hoặc sức khỏe sinh sản uy tín để bác sĩ điều trị sớm.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Im lặng tự mua thuốc bôi trên mạng để giấu kín sự việc.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:32', '2026-07-04 14:19:32'),
(3464, 585, 'reflection', '{\"question\": \"Bạn có sẵn sàng cảm thông và hỗ trợ bạn bè đi khám nếu họ chia sẻ thắc mắc thầm kín với bạn?\"}', 5, '2026-07-04 14:19:32', '2026-07-04 14:19:32'),
(3465, 585, 'takeaway', '{\"items\": [\"Bệnh tật không định nghĩa nhân cách của bạn. Đi khám và chữa trị sớm là sự dũng cảm và trách nhiệm.\"]}', 6, '2026-07-04 14:19:33', '2026-07-04 14:19:33'),
(3466, 586, 'hook', '{\"title\": \"Làm sao rủ người yêu đi xét nghiệm STI chung mà không khiến họ nghĩ mình đang nghi ngờ họ lăng nhăng?\"}', 1, '2026-07-04 14:19:33', '2026-07-04 14:19:33'),
(3467, 586, 'explanation', '{\"bullets\": [\"Đặt câu hỏi dưới góc độ chăm sóc lẫn nhau chứ không phải buộc tội.\", \"Sử dụng ngôn ngữ tích cực: \'Tớ muốn tụi mình cùng đi xét nghiệm để chắc chắn cả hai đều an toàn và khỏe mạnh\'.\", \"Biến buổi đi khám thành một hoạt động chăm sóc đôi lứa bình thường.\"]}', 2, '2026-07-04 14:19:33', '2026-07-04 14:19:33'),
(3468, 586, 'scenario', '{\"title\": \"Rủ rê tinh tế\", \"body\": \"Trang muốn cùng người yêu đi xét nghiệm STI trước khi quyết định dừng dùng bao cao su. Trang sợ người yêu tự ái nghĩ Trang coi thường mình.\"}', 3, '2026-07-04 14:19:33', '2026-07-04 14:19:33'),
(3469, 586, 'interaction', '{\"question\": \"Trang nên nói thế nào cho khéo léo?\", \"choices\": [{\"text\": \"\'Để cả hai cùng yên tâm và có trách nhiệm với nhau, tụi mình cùng đi kiểm tra sức khỏe sinh sản định kỳ nhé\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"\'Anh đi xét nghiệm đi, em thấy anh dạo này hay đi chơi riêng nghi ngờ lắm\'.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:33', '2026-07-04 14:19:33'),
(3470, 586, 'reflection', '{\"question\": \"Bạn có thấy một partner chủ động rủ đi xét nghiệm STI là người vô cùng đáng tin cậy không?\"}', 5, '2026-07-04 14:19:33', '2026-07-04 14:19:33'),
(3471, 586, 'takeaway', '{\"items\": [\"Xét nghiệm STI không phải nghi ngờ, đó là cam kết bảo vệ sức khỏe cho nhau.\"]}', 6, '2026-07-04 14:19:33', '2026-07-04 14:19:33'),
(3472, 587, 'hook', '{\"title\": \"Bạn có tò mò quy trình đi xét nghiệm bệnh tình dục diễn ra thế nào tại các cơ sở y tế?\"}', 1, '2026-07-04 14:19:33', '2026-07-04 14:19:33'),
(3473, 587, 'explanation', '{\"bullets\": [\"Bác sĩ sẽ hỏi sơ lược về lịch sử sức khỏe của bạn trong không gian riêng tư bảo mật.\", \"Thực hiện lấy mẫu dịch nhầy nhạy cảm bằng tăm bông chuyên dụng, hoặc lấy mẫu máu/nước tiểu.\", \"Quá trình lấy mẫu diễn ra nhanh chóng, không gây đau đớn, kết quả thường có sau vài giờ đến vài ngày.\"]}', 2, '2026-07-04 14:19:33', '2026-07-04 14:19:33'),
(3474, 587, 'scenario', '{\"title\": \"Tại phòng khám\", \"body\": \"Hòa đến trung tâm y tế xét nghiệm. Hòa lo lắng phòng khám sẽ công khai thông tin cho trường học hoặc bố mẹ biết. Bác sĩ cam đoan mọi kết quả đều được bảo mật tuyệt đối theo luật y tế.\"}', 3, '2026-07-04 14:19:33', '2026-07-04 14:19:33'),
(3475, 587, 'interaction', '{\"question\": \"Quyền riêng tư của bạn khi đi xét nghiệm được bảo vệ ra sao?\", \"choices\": [{\"text\": \"Thông tin cá nhân và kết quả xét nghiệm được bảo mật tuyệt đối giữa bạn và bác sĩ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Bệnh viện có quyền gửi báo cáo kết quả về nhà trường để giáo dục.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:33', '2026-07-04 14:19:33'),
(3476, 587, 'reflection', '{\"question\": \"Hiểu rõ quy trình bảo mật y tế có giúp bạn tự tin đi khám hơn không?\"}', 5, '2026-07-04 14:19:33', '2026-07-04 14:19:33'),
(3477, 587, 'takeaway', '{\"items\": [\"Bảo mật thông tin là luật y tế bắt buộc. Hãy yên tâm đi khám tại các trung tâm chính quy!\"]}', 6, '2026-07-04 14:19:33', '2026-07-04 14:19:33'),
(3478, 588, 'hook', '{\"title\": \"Nỗi sợ lớn nhất của bạn khi nghĩ về việc đi xét nghiệm STI là gì?\"}', 1, '2026-07-04 14:19:34', '2026-07-04 14:19:34'),
(3479, 588, 'explanation', '{\"bullets\": [\"Nỗi sợ kim tiêm, sợ đau hay sợ đối mặt với kết quả dương tính là điều dễ hiểu.\", \"Tuy nhiên, hầu hết các bệnh STI (như lậu, sùi mào gà, giang mai) đều chữa khỏi hoàn toàn nếu phát hiện sớm.\", \"Ngay cả HIV cũng có thuốc kiểm soát hiệu quả giúp người bệnh sống khỏe mạnh bình thường.\"]}', 2, '2026-07-04 14:19:34', '2026-07-04 14:19:34'),
(3480, 588, 'scenario', '{\"title\": \"Đối mặt kết quả\", \"body\": \"Hạnh nhận kết quả xét nghiệm dương tính với Chlamydia. Hạnh lo sợ mình sắp chết. Bác sĩ mỉm cười nhẹ giải thích bệnh này chỉ cần uống thuốc kháng sinh 1 tuần là khỏi hoàn toàn.\"}', 3, '2026-07-04 14:19:34', '2026-07-04 14:19:34'),
(3481, 588, 'interaction', '{\"question\": \"Hầu hết các bệnh STI chữa trị thế nào nếu phát hiện sớm?\", \"choices\": [{\"text\": \"Có thể chữa khỏi hoàn toàn bằng thuốc kháng sinh hoặc các phác đồ y tế đơn giản.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Là bệnh nan y không thể cứu chữa, người bệnh sẽ chịu biến chứng suốt đời.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:34', '2026-07-04 14:19:34'),
(3482, 588, 'reflection', '{\"question\": \"Bạn có đồng ý rằng phát hiện sớm để chữa trị tốt hơn là trốn tránh để bệnh tiến triển nặng?\"}', 5, '2026-07-04 14:19:34', '2026-07-04 14:19:34'),
(3483, 588, 'takeaway', '{\"items\": [\"Xét nghiệm giúp bạn nắm quyền chủ động kiểm soát sức khỏe. Đừng để nỗi sợ làm chậm trễ!\"]}', 6, '2026-07-04 14:19:34', '2026-07-04 14:19:34'),
(3484, 589, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Bảo vệ Khỏi STI\'! Hãy cùng dẹp tan những virus đáng ghét.\"}', 1, '2026-07-04 14:19:34', '2026-07-04 14:19:34'),
(3485, 589, 'scenario-choice', '{\"title\": \"Cuộc phiêu lưu: Đối phó với STI\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn phát hiện vùng kín của mình dạo gần đây có biểu hiện ngứa rát lạ và tiết dịch bất thường.\", \"choices\": [{\"text\": \"Lên các hội nhóm ẩn danh hỏi mua thuốc nam gia truyền về tự bôi.\", \"nextNode\": \"fail_selfmed\"}, {\"text\": \"Đặt lịch khám tại khoa da liễu bệnh viện uy tín để xét nghiệm kiểm tra.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Bác sĩ xác nhận bạn nhiễm một loại STI thông thường và cho đơn thuốc. Bạn lo lắng không biết nói với partner thế nào để họ cùng đi khám.\", \"choices\": [{\"text\": \"Im lặng tự uống thuốc một mình, tiếp tục quan hệ không bảo vệ.\", \"nextNode\": \"fail_silent\"}, {\"text\": \"Trò chuyện thẳng thắn với partner để họ cùng đi kiểm tra điều trị dứt điểm cho cả hai.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Tuyệt vời! Bạn đã vượt qua nỗi sợ để đi khám kịp thời và có giải pháp ứng xử trách nhiệm bảo vệ cả hai.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_selfmed\": {\"text\": \"❌ Thất bại! Tự ý dùng thuốc không rõ nguồn gốc làm bệnh biến chứng nặng nề và khó điều trị hơn.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_silent\": {\"text\": \"❌ Thất bại! Không điều trị cho partner dẫn đến việc lây nhiễm chéo liên tục (hiệu ứng ping-pong) khiến bệnh tái phát.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-04 14:19:34', '2026-07-04 14:19:34'),
(3486, 589, 'sorting', '{\"instruction\": \"Hãy phân loại các đường lây truyền và ngăn ngừa STI sau:\", \"leftBox\": {\"title\": \"Đường lây nhiễm STI\"}, \"rightBox\": {\"title\": \"Cách ngừa & Phòng chống\"}, \"items\": [{\"text\": \"Tiếp xúc da kề da khu vực vùng kín bị loét\", \"correctBox\": \"left\"}, {\"text\": \"Sử dụng bao cao su đều đặn từ đầu đến cuối\", \"correctBox\": \"right\"}, {\"text\": \"Dùng chung đồ chơi tình dục chưa được khử trùng\", \"correctBox\": \"left\"}, {\"text\": \"Đi xét nghiệm STI định kỳ cùng partner\", \"correctBox\": \"right\"}, {\"text\": \"Quan hệ tình dục xâm nhập không có lá chắn bảo vệ\", \"correctBox\": \"left\"}]}', 3, '2026-07-04 14:19:34', '2026-07-04 14:19:34'),
(3487, 589, 'matching', '{\"instruction\": \"Ghép cặp đúng các loại bệnh STI với cơ chế của chúng:\", \"pairs\": [{\"left\": \"Chlamydia\", \"right\": \"Bệnh nhiễm khuẩn thầm lặng thường không có triệu chứng ban đầu.\"}, {\"left\": \"Bảo mật y tế\", \"right\": \"Quy tắc giữ kín tuyệt đối thông tin bệnh án của người khám bệnh.\"}, {\"left\": \"Hiệu ứng Ping-pong\", \"right\": \"Hiện tượng lây nhiễm qua lại liên tục do chỉ điều trị 1 bên.\"}, {\"left\": \"Bao cao su latex\", \"right\": \"Rào chắn hiệu quả chặn vi khuẩn/virus tiếp xúc niêm mạc.\"}]}', 4, '2026-07-04 14:19:34', '2026-07-04 14:19:34'),
(3488, 589, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về STI:\", \"sentence\": \"Bệnh lây truyền qua đường tình dục STI có thể diễn ra vô cùng [blank1]. Cách duy nhất để phát hiện là đi [blank2] y khoa. Hầu hết các bệnh này đều có thể [blank3] hoàn toàn nếu phát hiện sớm. Tuyệt đối đừng tự ý [blank4] thuốc tại nhà.\", \"blanks\": {\"blank1\": {\"correct\": \"thầm lặng\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"xét nghiệm\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"chữa khỏi\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"mua\", \"placeholder\": \"...\"}}, \"words\": [\"thầm lặng\", \"xét nghiệm\", \"chữa khỏi\", \"mua\", \"rầm rộ\", \"bỏ qua\", \"lây nhiễm\", \"giấu\"]}', 5, '2026-07-04 14:19:34', '2026-07-04 14:19:34'),
(3489, 589, 'interaction', '{\"question\": \"Bạn nghĩ việc ôm hôn xã giao thông thường có lây truyền phần lớn các bệnh STI nghiêm trọng (như HIV, chlamydia) không?\", \"enableLives\": true, \"choices\": [{\"text\": \"Hoàn toàn không. Những tiếp xúc thông thường như ôm, nắm tay, dùng chung nhà vệ sinh không lây nhiễm bệnh.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Có chứ, các bệnh đó lây cực mạnh qua không khí.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Có lây nếu đứng quá gần người bệnh.\", \"correct\": false, \"emoji\": \"😐\"}]}', 6, '2026-07-04 14:19:35', '2026-07-04 14:19:35'),
(3490, 590, 'hook', '{\"title\": \"Làm sao để biết bạn đưa ra quyết định vì thực sự muốn thế hay chỉ vì muốn làm hài lòng người khác?\"}', 1, '2026-07-04 14:19:35', '2026-07-04 14:19:35'),
(3491, 590, 'explanation', '{\"bullets\": [\"Tự chủ (Autonomy) nghĩa là bạn có quyền lực tối cao với cơ thể và cuộc đời mình.\", \"Mọi quyết định gần gũi thân mật phải xuất phát từ mong muốn tự nguyện sâu bên trong bạn.\", \"Nếu bạn cảm thấy bồn chồn lo lắng, đó là tín hiệu cơ thể cảnh báo bạn chưa sẵn sàng.\"]}', 2, '2026-07-04 14:19:35', '2026-07-04 14:19:35'),
(3492, 590, 'scenario', '{\"title\": \"Mất phương hướng\", \"body\": \"Dũng đồng ý đi xa qua đêm cùng bạn gái vì bạn gái bảo: \'Bạn bè xung quanh ai cũng đi chung như thế cả rồi\'. Dũng trong lòng lo sợ và không thoải mái.\"}', 3, '2026-07-04 14:19:35', '2026-07-04 14:19:35'),
(3493, 590, 'interaction', '{\"question\": \"Quyết định của Dũng có thực sự tự chủ không?\", \"choices\": [{\"text\": \"Không, Dũng đồng ý vì áp lực muốn giống bạn bè xung quanh.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Có, Dũng tự chọn đi theo đám đông mà.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-04 14:19:35', '2026-07-04 14:19:35'),
(3494, 590, 'reflection', '{\"question\": \"Bạn có bao giờ làm điều gì đó chỉ vì sợ bị coi là \'lạc loài\' so với nhóm bạn chưa?\"}', 5, '2026-07-04 14:19:35', '2026-07-04 14:19:35'),
(3495, 590, 'takeaway', '{\"items\": [\"Cơ thể và tương lai của bạn là của bạn. Hãy đưa ra quyết định vì chính bạn đầu tiên!\"]}', 6, '2026-07-04 14:19:35', '2026-07-04 14:19:35'),
(3496, 591, 'hook', '{\"title\": \"Trước khi gật đầu đồng ý tiến xa hơn với ai đó, hãy tự hỏi bản thân 3 câu hỏi này nhé!\"}', 1, '2026-07-04 14:19:35', '2026-07-04 14:19:35'),
(3497, 591, 'explanation', '{\"bullets\": [\"Câu hỏi 1: \'Mình có thực sự THÍCH và muốn làm việc này lúc này không?\'\", \"Câu hỏi 2: \'Mình có sẵn sàng chịu trách nhiệm và biết cách BẢO VỆ an toàn chưa?\'\", \"Câu hỏi 3: \'Mối quan hệ này có TÔN TRỌNG ranh giới của mình không?\'\"]}', 2, '2026-07-04 14:19:36', '2026-07-04 14:19:36'),
(3498, 591, 'scenario', '{\"title\": \"3 câu hỏi vàng\", \"body\": \"Hạnh chuẩn bị đồng ý đi chơi riêng tại nhà bạn trai. Hạnh mở điện thoại tự check-in 3 câu hỏi trên. Hạnh nhận ra mình chưa chuẩn bị bao cao su ngừa thai.\"}', 3, '2026-07-04 14:19:36', '2026-07-04 14:19:36'),
(3499, 591, 'interaction', '{\"question\": \"Hạnh nên làm gì tiếp theo?\", \"choices\": [{\"text\": \"Dừng lại, yêu cầu chuẩn bị biện pháp bảo vệ trước khi đồng ý đi.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Cứ đi đi, đến nơi rồi tính sau lo gì.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:36', '2026-07-04 14:19:36'),
(3500, 591, 'reflection', '{\"question\": \"Bạn nghĩ câu hỏi check-in nào trong 3 câu hỏi trên là khó trả lời nhất đối với bạn?\"}', 5, '2026-07-04 14:19:36', '2026-07-04 14:19:36'),
(3501, 591, 'takeaway', '{\"items\": [\"Luôn check-in bản thân trước khi trả lời đối phương. Sự cẩn thận giúp bạn làm chủ mọi tình huống!\"]}', 6, '2026-07-04 14:19:36', '2026-07-04 14:19:36'),
(3502, 592, 'hook', '{\"title\": \"Bạn có sẵn sàng đánh đổi sự an toàn của mình chỉ để đổi lấy nụ cười và sự vui lòng của đối phương?\"}', 1, '2026-07-04 14:19:36', '2026-07-04 14:19:36'),
(3503, 592, 'explanation', '{\"bullets\": [\"Nhiều bạn trẻ chọn nhượng bộ ranh giới vì sợ người yêu giận dỗi, lạnh nhạt hoặc đòi chia tay.\", \"Tuy nhiên, sự hy sinh một chiều chỉ tạo ra mối quan hệ bất bình đẳng và độc hại.\", \"Người thực sự yêu thương bạn sẽ trân trọng ranh giới của bạn và kiên nhẫn chờ đợi.\"]}', 2, '2026-07-04 14:19:36', '2026-07-04 14:19:36'),
(3504, 592, 'scenario', '{\"title\": \"Hy sinh thầm lặng\", \"body\": \"Bình lo sợ nếu mình từ chối đụng chạm, người yêu sẽ đi tìm bạn gái khác sành điệu hơn. Bình nhắm mắt đồng ý dù trong lòng đầy bất an.\"}', 3, '2026-07-04 14:19:36', '2026-07-04 14:19:36'),
(3505, 592, 'interaction', '{\"question\": \"Mối quan hệ của Bình có lành mạnh không?\", \"choices\": [{\"text\": \"Không lành mạnh. Bình đang bị áp lực thao túng tâm lý và bỏ qua ranh giới của mình.\", \"correct\": true, \"emoji\": \"🚩\"}, {\"text\": \"Có lành mạnh, yêu là phải biết hy sinh vì nhau.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-04 14:19:36', '2026-07-04 14:19:36'),
(3506, 592, 'reflection', '{\"question\": \"Bạn có nghĩ một người yêu sẵn sàng chia tay vì bạn giữ ranh giới có đáng để tiếp tục yêu không?\"}', 5, '2026-07-04 14:19:36', '2026-07-04 14:19:36'),
(3507, 592, 'takeaway', '{\"items\": [\"Bạn không cần phải làm hài lòng người khác bằng cách bỏ qua cảm xúc của chính mình.\"]}', 6, '2026-07-04 14:19:36', '2026-07-04 14:19:36'),
(3508, 593, 'hook', '{\"title\": \"Làm sao đối thoại thẳng thắn với partner về những giới hạn của bản thân mà không làm sứt mẻ tình cảm?\"}', 1, '2026-07-04 14:19:36', '2026-07-04 14:19:36'),
(3509, 593, 'explanation', '{\"bullets\": [\"Chọn thời điểm thích hợp và dùng ngôn ngữ \'Tớ thấy... nên tớ muốn...\'.\", \"Nói rõ những điều bạn sẵn sàng làm và những giới hạn tuyệt đối bạn chưa muốn vượt qua.\", \"Lắng nghe phản hồi từ đối phương để xem họ có thực sự thấu hiểu và tôn trọng bạn không.\"]}', 2, '2026-07-04 14:19:36', '2026-07-04 14:19:36'),
(3510, 593, 'scenario', '{\"title\": \"Bày tỏ giới hạn\", \"body\": \"Trước buổi tối đi xem phim riêng, Vy nói với người yêu: \'Tớ thích được ôm và nắm tay cậu, nhưng tớ chưa sẵn sàng cho đụng chạm xa hơn. Cậu tôn trọng tớ nhé\'.\"}', 3, '2026-07-04 14:19:36', '2026-07-04 14:19:36'),
(3511, 593, 'interaction', '{\"question\": \"Phản ứng nào của người yêu Vy là Green Flag?\", \"choices\": [{\"text\": \"Mỉm cười: \'Tớ hiểu rồi, cậu thoải mái là được. Tụi mình cứ từ từ nhé\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Dỗi: \'Cậu kỹ tính quá vậy, làm gì mà nghiêm trọng hóa vấn đề thế\'.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:36', '2026-07-04 14:19:36'),
(3512, 593, 'reflection', '{\"question\": \"Bạn có tự tin mình có thể bày tỏ rõ ràng giới hạn của mình với partner không?\"}', 5, '2026-07-04 14:19:37', '2026-07-04 14:19:37'),
(3513, 593, 'takeaway', '{\"items\": [\"Đối thoại thẳng thắn giúp loại bỏ mọi hiểu lầm và thắt chặt kết nối tin cậy giữa hai người.\"]}', 6, '2026-07-04 14:19:37', '2026-07-04 14:19:37'),
(3514, 594, 'hook', '{\"title\": \"Làm sao để các chuyến đi phượt hay đi chơi xa với người yêu luôn vui vẻ và hoàn toàn an toàn?\"}', 1, '2026-07-04 14:19:37', '2026-07-04 14:19:37'),
(3515, 594, 'explanation', '{\"bullets\": [\"Luôn chủ động mang theo bao cao su hoặc chuẩn bị sẵn sàng biện pháp tránh thai nội tiết.\", \"Tìm hiểu trước địa chỉ các nhà thuốc hoặc cơ sở y tế gần nơi đến phòng trường hợp khẩn cấp.\", \"Luôn giữ liên lạc với một người bạn thân đáng tin cậy để phòng sự cố ngoài kiểm soát.\"]}', 2, '2026-07-04 14:19:37', '2026-07-04 14:19:37'),
(3516, 594, 'scenario', '{\"title\": \"Kế hoạch đi phượt\", \"body\": \"Huy và An cùng lên kế hoạch đi du lịch. An chủ động mang theo vỉ thuốc tránh thai hàng ngày, Huy chuẩn bị một hộp bao cao su mới và cả hai cùng thống nhất ranh giới.\"}', 3, '2026-07-04 14:19:37', '2026-07-04 14:19:37'),
(3517, 594, 'interaction', '{\"question\": \"Kế hoạch của Huy và An thể hiện điều gì?\", \"choices\": [{\"text\": \"Sự chín chắn, có sự chuẩn bị chu đáo thể hiện tình yêu văn minh và trách nhiệm.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Sự lo xa thái quá làm mất đi tính lãng mạn bất ngờ của chuyến đi.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-04 14:19:37', '2026-07-04 14:19:37'),
(3518, 594, 'reflection', '{\"question\": \"Bạn có sẵn sàng chuẩn bị kế hoạch an toàn trước mọi chuyến đi xa không?\"}', 5, '2026-07-04 14:19:37', '2026-07-04 14:19:37'),
(3519, 594, 'takeaway', '{\"items\": [\"Sự chuẩn bị kỹ lưỡng là lá chắn vững chắc giúp bạn tận hưởng trọn vẹn niềm vui tuổi trẻ.\"]}', 6, '2026-07-04 14:19:37', '2026-07-04 14:19:37'),
(3520, 595, 'hook', '{\"title\": \"Làm sao để cân bằng giữa cảm xúc yêu đương mãnh liệt và lý trí bảo vệ bản thân?\"}', 1, '2026-07-04 14:19:37', '2026-07-04 14:19:37'),
(3521, 595, 'explanation', '{\"bullets\": [\"Yêu thương là cảm xúc tuyệt vời, nhưng lý trí giúp bạn đi đường dài một cách an toàn.\", \"Đừng để sự thăng hoa nhất thời che mờ các nguyên tắc an toàn sức khỏe và ranh giới cá nhân.\", \"Nếu trái tim nói \'Muốn\' nhưng lý trí nói \'Nguy hiểm\', hãy luôn phanh gấp lại để suy nghĩ.\"]}', 2, '2026-07-04 14:19:37', '2026-07-04 14:19:37'),
(3522, 595, 'scenario', '{\"title\": \"Phanh gấp đúng lúc\", \"body\": \"Trong không gian lãng mạn, Duy định tiến xa hơn với Vy. Vy thấy rất thích Duy nhưng sực nhớ ra cả hai chưa có biện pháp bảo vệ nào. Vy quyết định dừng lại.\"}', 3, '2026-07-04 14:19:37', '2026-07-04 14:19:37'),
(3523, 595, 'interaction', '{\"question\": \"Hành động của Vy thể hiện điều gì?\", \"choices\": [{\"text\": \"Vy là người có lý trí mạnh mẽ, biết làm chủ bản thân để bảo vệ tương lai.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Vy là người lạnh lùng, thiếu cảm xúc yêu thương nồng cháy.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-04 14:19:37', '2026-07-04 14:19:37'),
(3524, 595, 'reflection', '{\"question\": \"Bạn nghĩ mình có đủ bản lĩnh để phanh gấp khi cảm xúc đang thăng hoa không?\"}', 5, '2026-07-04 14:19:37', '2026-07-04 14:19:37'),
(3525, 595, 'takeaway', '{\"items\": [\"Lý trí không làm mất đi tình yêu, nó giữ cho tình yêu của bạn luôn đẹp đẽ và an toàn.\"]}', 6, '2026-07-04 14:19:38', '2026-07-04 14:19:38'),
(3526, 596, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Quyết Định Sáng Suốt\'! Hãy khẳng định bản lĩnh của bạn.\"}', 1, '2026-07-04 14:19:38', '2026-07-04 14:19:38'),
(3527, 596, 'scenario-choice', '{\"title\": \"Cuộc phiêu lưu: Làm chủ lựa chọn\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn và người yêu đang đi du lịch chung. Tối đến trong phòng riêng, người yêu ôm chặt và muốn tiến xa hơn.\", \"choices\": [{\"text\": \"Đồng ý ngay lập tức vì không muốn người yêu giận dỗi làm hỏng chuyến đi.\", \"nextNode\": \"fail_peer\"}, {\"text\": \"Tự hỏi bản thân 3 câu hỏi check-in xem mình thực sự sẵn sàng và có biện pháp bảo vệ chưa.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Bạn nhận ra mình chưa chuẩn bị bao cao su. Người yêu bảo: \'Một lần thôi có sao đâu, anh rút kịp mà\'.\", \"choices\": [{\"text\": \"Tặc lưỡi đồng ý vì tin vào lời hứa của đối phương.\", \"nextNode\": \"fail_withdrawal\"}, {\"text\": \"Kiên quyết từ chối: \'Tớ rất quý cậu nhưng không có bảo vệ thì không đi tiếp. Tụi mình nói chuyện tiếp nhé\'.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Chúc mừng! Bạn đã đưa ra quyết định cực kỳ sáng suốt, tôn trọng bản thân và làm chủ ranh giới an toàn.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_peer\": {\"text\": \"❌ Thất bại! Bạn đồng ý vì áp lực muốn chiều lòng người khác chứ không phải mong muốn tự nguyện thực sự của bản thân.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_withdrawal\": {\"text\": \"❌ Thất bại! Bạn đã thỏa hiệp với biện pháp rủi ro cao, đặt bản thân vào nguy cơ mang thai ngoài ý muốn.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-04 14:19:38', '2026-07-04 14:19:38'),
(3528, 596, 'sorting', '{\"instruction\": \"Hãy phân loại các hành vi đưa ra quyết định sau:\", \"leftBox\": {\"title\": \"Quyết định Tự chủ (Green)\"}, \"rightBox\": {\"title\": \"Thỏa hiệp, Nhượng bộ (Red)\"}, \"items\": [{\"text\": \"Tự check-in 3 câu hỏi trước khi gật đầu đồng ý tiến xa\", \"correctBox\": \"left\"}, {\"text\": \"Đồng ý đụng chạm vì sợ đối phương giận đòi chia tay\", \"correctBox\": \"right\"}, {\"text\": \"Thẳng thắn bày tỏ giới hạn ranh giới trước khi đi chơi xa\", \"correctBox\": \"left\"}, {\"text\": \"Làm chuyện ấy chỉ vì bạn bè xung quanh ai cũng làm rồi\", \"correctBox\": \"right\"}, {\"text\": \"Dừng lại ngay lập tức khi phát hiện không có bao cao su bảo vệ\", \"correctBox\": \"left\"}]}', 3, '2026-07-04 14:19:38', '2026-07-04 14:19:38'),
(3529, 596, 'matching', '{\"instruction\": \"Ghép cặp đúng các nguyên tắc đưa ra quyết định an toàn sau:\", \"pairs\": [{\"left\": \"Tự chủ\", \"right\": \"Quyền lực tối cao tự định đoạt cơ thể và cuộc đời của riêng bạn.\"}, {\"left\": \"3 câu hỏi vàng\", \"right\": \"Bộ công cụ tự vấn bản thân về sự thích, sự sẵn sàng và sự bảo vệ.\"}, {\"left\": \"Thao túng tâm lý\", \"right\": \"Hành vi dùng lời dỗi hờn, mặc cả lòng tin để ép đụng chạm.\"}, {\"left\": \"Lập kế hoạch an toàn\", \"right\": \"Chủ động chuẩn bị biện pháp bảo vệ và tìm hiểu hiệu thuốc trước khi đi xa.\"}]}', 4, '2026-07-04 14:19:38', '2026-07-04 14:19:38'),
(3530, 596, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về quyết định sáng suốt:\", \"sentence\": \"Quyết định gần gũi thân mật phải là sự [blank1] tự nguyện của riêng bạn. Tuyệt đối không thỏa hiệp vì [blank2] đồng trang lứa. Hãy chuẩn bị [blank3] trước khi tiến xa. Sự sáng suốt của [blank4] sẽ bảo vệ ước mơ của bạn.\", \"blanks\": {\"blank1\": {\"correct\": \"lựa chọn\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"áp lực\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"kế hoạch an toàn\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"lý trí\", \"placeholder\": \"...\"}}, \"words\": [\"lựa chọn\", \"áp lực\", \"kế hoạch an toàn\", \"lý trí\", \"bắt buộc\", \"gia đình\", \"tự phát\", \"con tim\"]}', 5, '2026-07-04 14:19:38', '2026-07-04 14:19:38'),
(3531, 596, 'interaction', '{\"question\": \"Khi partner dỗi: \'Cậu lo xa tính toán thế này làm mất hết cả hứng của tớ rồi\', phản ứng nào là tự tin và bản lĩnh nhất?\", \"enableLives\": true, \"choices\": [{\"text\": \"\'An tâm thì mới vui vẻ trọn vẹn được chứ cậu. Tụi mình cùng có trách nhiệm với nhau nha\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"\'Xin lỗi cậu nhé, tớ sẽ không nói chuyện này nữa đâu\'.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"\'Cậu ích kỷ quá, chỉ biết nghĩ cho bản thân cậu thôi à\'.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-04 14:19:38', '2026-07-04 14:19:38'),
(4162, 702, 'hook', '{\"title\": \"Bạn có bao giờ tự hỏi: \'Ủa rốt cuộc mình là ai giữa cái vũ trụ này?\"}', 1, '2026-07-06 21:15:45', '2026-07-06 21:15:45'),
(4163, 702, 'explanation', '{\"bullets\": [\"Khi giới thiệu về bản thân, bạn thường nói gì? Tên, tuổi, lớp học?\", \"Nhưng bản thân bạn rộng lớn hơn thế nhiều!\", \"\\\"Bản dạng\\\" (Identity) chính là tập hợp tất cả những gì tạo nên bạn.\", \"Nó giống như một bức tranh ghép hình (puzzle) khổng lồ, mỗi mảnh ghép là một phần câu chuyện của bạn.\"]}', 2, '2026-07-06 21:15:45', '2026-07-06 21:15:45'),
(4164, 702, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Nam ngồi thẫn thờ trước tờ giấy viết bài tự giới thiệu bản thân đầu năm học. Nam chỉ biết viết: *\\\"Tôi tên Nam, 14 tuổi, thích đá bóng\\\"*. Nam cảm thấy hình như thế là chưa đủ, cậu ấy còn thích vẽ anime, hay khóc khi xem phim cảm động, và cực kỳ ghét tiếng ồn. Nam tự hỏi: *\\\"Liệu những phần tính cách này có được tính là \'mình\' không?\\\"*\"}', 3, '2026-07-06 21:15:45', '2026-07-06 21:15:45'),
(4165, 702, 'interaction', '{\"question\": \"Hãy chọn mảnh ghép mà bạn nghĩ cũng thuộc về \\\"bản dạng\\\" của một người:\", \"choices\": [{\"text\": \"A. Màu sắc yêu thích và phong cách ăn mặc.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"B. Nhóm nhạc bạn cuồng nhiệt đu trend.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"C. Cách bạn phản ứng khi buồn hoặc giận.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"D. Tất cả các ý trên đều tạo nên bạn.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:15:45', '2026-07-06 21:15:45'),
(4166, 702, 'reflection', '{\"question\": \"Mảnh ghép nào về bản thân khiến bạn cảm thấy tự hào nhất lúc này?\"}', 5, '2026-07-06 21:15:45', '2026-07-06 21:15:45'),
(4167, 702, 'takeaway', '{\"items\": [\"Bạn là một bản thể độc bản, không có phiên bản copy thứ hai trên đời.\"]}', 6, '2026-07-06 21:15:45', '2026-07-06 21:15:45'),
(4168, 703, 'hook', '{\"title\": \"Thử nghĩ xem, điều gì đang tạo nên \'thương hiệu cá nhân\' của riêng bạn?\"}', 1, '2026-07-06 21:15:45', '2026-07-06 21:15:45'),
(4169, 703, 'explanation', '{\"bullets\": [\"Bản dạng của chúng ta không chỉ có một màu.\", \"Nó được cấu thành từ: Bản dạng xã hội (như gia đình, quê quán), Bản dạng giới (cách bạn cảm nhận về giới tính của mình), và Bản dạng cá nhân (sở thích, niềm tin).\", \"Mỗi mảnh ghép lại có một vai trò riêng giúp bạn tự tin bước ra thế giới.\"]}', 2, '2026-07-06 21:15:46', '2026-07-06 21:15:46'),
(4170, 703, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Vy cảm thấy bối rối khi đi chơi với nhóm bạn thân. Các bạn đều thích trang điểm, mặc váy điệu đà, còn Vy chỉ thích mặc đồ oversize và chơi skateboard. Vy tự hỏi liệu mình có đang \\\"lệch sóng\\\" và không biết mình có thực sự thuộc về nhóm bạn này hay không.\"}', 3, '2026-07-06 21:15:46', '2026-07-06 21:15:46'),
(4171, 703, 'interaction', '{\"question\": \"Nếu là Vy, bạn sẽ làm gì để cân bằng giữa việc \'hòa nhập\' và \'là chính mình\'?\", \"choices\": [{\"text\": \"Cố gắng mặc váy giống các bạn dù thấy cực kỳ uncomfy\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Tự tin mặc đồ rộng, trượt ván đến chỗ hẹn và chia sẻ niềm vui đó với bạn bè.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:15:46', '2026-07-06 21:15:46'),
(4172, 703, 'reflection', '{\"question\": \"Có mảnh ghép nào của bản thân mà bạn từng giấu đi vì sợ người khác đánh giá không?\"}', 5, '2026-07-06 21:15:46', '2026-07-06 21:15:46'),
(4173, 703, 'takeaway', '{\"items\": [\"Hòa nhập không có nghĩa là phải hòa tan bản sắc của chính mình.\"]}', 6, '2026-07-06 21:15:46', '2026-07-06 21:15:46'),
(4174, 704, 'hook', '{\"title\": \"Có bao giờ bạn thấy áp lực khi mọi người xung quanh dường như đều biết rõ họ muốn gì, còn bạn thì không?\"}', 1, '2026-07-06 21:15:46', '2026-07-06 21:15:46'),
(4175, 704, 'explanation', '{\"bullets\": [\"Tuổi dậy thì là lúc cơ thể và bộ não thay đổi với tốc độ chóng mặt.\", \"Việc bạn thấy hôm nay thích cái này, mai thích cái khác, hay băn khoăn về tương lai là cực kỳ bình thường.\", \"Bộ não của bạn vẫn đang trong quá trình hoàn thiện các kết nối thần kinh (như một công trường đang xây dựng vậy!).\"]}', 2, '2026-07-06 21:15:46', '2026-07-06 21:15:46'),
(4176, 704, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Minh (15 tuổi) cảm thấy khủng hoảng khi thầy cô yêu cầu viết định hướng nghề nghiệp và tính cách tương lai. Minh thấy mình trống rỗng, không biết mình thực sự giỏi gì hay thích gì. Nhìn các bạn xung quanh nộp bài rôm rả, Minh chỉ muốn chui vào một góc.\"}', 3, '2026-07-06 21:15:46', '2026-07-06 21:15:46'),
(4177, 704, 'interaction', '{\"question\": \"Hãy chọn một lời nhắn gửi đến Minh để cậu ấy bớt áp lực:\", \"choices\": [{\"text\": \"\\\"Nhanh lên Minh ơi, không chọn nhanh là tụt hậu đấy!\\\"\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"\\\"Bình tĩnh nè Minh, tuổi 15 là để thử và sai, chưa biết mình là ai cũng hoàn toàn OK!\\\"\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:15:46', '2026-07-06 21:15:46'),
(4178, 704, 'reflection', '{\"question\": \"Bạn có cảm thấy thoải mái khi cho phép bản thân có những ngày \'chưa cần biết câu trả lời\' không?\"}', 5, '2026-07-06 21:15:46', '2026-07-06 21:15:46'),
(4179, 704, 'takeaway', '{\"items\": [\"Chưa định vị được bản thân không phải là lạc đường, đó là bạn đang bắt đầu hành trình khám phá.\"]}', 6, '2026-07-06 21:15:46', '2026-07-06 21:15:46'),
(4180, 705, 'hook', '{\"title\": \"Khi bố mẹ muốn bạn làm một \'phiên bản hoàn hảo\', còn bạn chỉ muốn là chính mình...\"}', 1, '2026-07-06 21:15:47', '2026-07-06 21:15:47'),
(4181, 705, 'explanation', '{\"bullets\": [\"Chúng ta thường vô tình nhìn vào kỳ vọng của cha mẹ, thầy cô, bạn bè để tự định nghĩa bản thân.\", \"Việc muốn làm người khác vui lòng là tâm lý tự nhiên.\", \"Nhưng nếu luôn sống theo kịch bản của người khác, bạn sẽ đánh mất chính mình.\"]}', 2, '2026-07-06 21:15:47', '2026-07-06 21:15:47'),
(4182, 705, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Khang rất thích nấu ăn và mơ ước trở thành đầu bếp, nhưng bố Khang luôn muốn cậu phải thi chuyên Toán để sau này làm kỹ sư công nghệ. Mỗi lần vào bếp, Khang lại cảm thấy tội lỗi (guilty) vì nghĩ mình đang làm bố thất vọng.\"}', 3, '2026-07-06 21:15:47', '2026-07-06 21:15:47'),
(4183, 705, 'interaction', '{\"question\": \"Nếu là Khang, bạn sẽ chọn bước đi nào để giải tỏa cảm xúc này?\", \"choices\": [{\"text\": \"Từ bỏ đam mê nấu ăn, cắm đầu vào học Toán để bố vui lòng.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Nấu một món thật ngon cho bố ăn thử, rồi nhẹ nhàng chia sẻ niềm vui của mình khi làm bếp.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:15:47', '2026-07-06 21:15:47'),
(4184, 705, 'reflection', '{\"question\": \"Bạn có đang gánh vác kỳ vọng nào của người khác khiến bạn thấy mệt mỏi không?\"}', 5, '2026-07-06 21:15:47', '2026-07-06 21:15:47'),
(4185, 705, 'takeaway', '{\"items\": [\"Bạn không cần phải làm người khác vui bằng cách bỏ qua cảm xúc của chính mình.\"]}', 6, '2026-07-06 21:15:47', '2026-07-06 21:15:47'),
(4186, 706, 'hook', '{\"title\": \"Làm thế nào để yêu thương cả những vết sẹo hay tính cách bị coi là \'kỳ quặc\' của mình?\"}', 1, '2026-07-06 21:15:47', '2026-07-06 21:15:47'),
(4187, 706, 'explanation', '{\"bullets\": [\"Ai cũng có những góc khuất, những đặc điểm không giống ai.\", \"Thay vì tìm cách giấu nhẹm hay tự ti, hãy thử xem chúng như những nét vẽ đặc biệt tạo nên bức tranh cá nhân của bạn.\", \"Chấp nhận bản thân (Self-acceptance) là bước đầu tiên để xây dựng sự tự tin vững chắc.\"]}', 2, '2026-07-06 21:15:47', '2026-07-06 21:15:47'),
(4188, 706, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Linh có một vết chàm nhỏ trên má và giọng nói hơi khàn. Linh luôn đeo khẩu trang khi đến lớp và rất ngại phát biểu vì sợ các bạn trêu chọc. Một ngày nọ, cô giáo yêu cầu cả lớp thuyết trình nhóm, Linh bắt buộc phải tháo khẩu trang ra.\"}', 3, '2026-07-06 21:15:47', '2026-07-06 21:15:47'),
(4189, 706, 'interaction', '{\"question\": \"Bạn sẽ gửi lời khích lệ nào để Linh tự tin bước lên bục giảng?\", \"choices\": [{\"text\": \"\\\"Cứ tự tin lên Linh ơi, giọng khàn của bạn nghe rất cuốn hút và đặc biệt mà!\\\"\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"\\\"Đeo khẩu trang thuyết trình cũng được mà, đỡ ngại.\\\"\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:15:47', '2026-07-06 21:15:47'),
(4190, 706, 'reflection', '{\"question\": \"Một điều \'khác biệt\' ở cơ thể hoặc tính cách mà bạn đã dần học cách chấp nhận là gì?\"}', 5, '2026-07-06 21:15:48', '2026-07-06 21:15:48'),
(4191, 706, 'takeaway', '{\"items\": [\"Sự hoàn hảo là một ảo ảnh, chính những vết nứt mới là nơi ánh sáng đi vào.\"]}', 6, '2026-07-06 21:15:48', '2026-07-06 21:15:48'),
(4192, 707, 'hook', '{\"title\": \"Nếu được tự chấm điểm mức độ hiểu rõ bản thân ở hiện tại, bạn sẽ cho mình điểm mấy?\"}', 1, '2026-07-06 21:15:48', '2026-07-06 21:15:48'),
(4193, 707, 'explanation', '{\"bullets\": [\"Việc tự đánh giá giúp bạn nhận ra mình đang ở đâu trên bản đồ cảm xúc.\", \"Dù là 3/10 hay 9/10, con số đó không nói lên bạn giỏi hay kém.\", \"Đó chỉ là cột mốc phản ánh trạng thái hiện tại của bạn mà thôi.\"]}', 2, '2026-07-06 21:15:48', '2026-07-06 21:15:48'),
(4194, 707, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Trang thấy các bạn viết nhật ký, phân tích tính cách MBTI hay cung hoàng đạo rất vanh vách. Trang thử làm nhưng thấy kết quả lúc đúng lúc sai, Trang tự hỏi không biết mình có bị \\\"mất kết nối\\\" với bản thân không.\"}', 3, '2026-07-06 21:15:48', '2026-07-06 21:15:48'),
(4195, 707, 'interaction', '{\"question\": \"Chọn biểu cảm mô tả đúng nhất cảm xúc của bạn khi nghĩ về bản thân hiện tại:\", \"choices\": [{\"text\": \"🔍\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"🌀\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"😎\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"😶\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:15:48', '2026-07-06 21:15:48'),
(4196, 707, 'reflection', '{\"question\": \"Điều gì về bản thân mà bạn muốn khám phá sâu hơn trong thời gian tới?\"}', 5, '2026-07-06 21:15:48', '2026-07-06 21:15:48'),
(4197, 707, 'takeaway', '{\"items\": [\"Hiểu mình là một cuộc marathon, không phải là một cuộc chạy bứt tốc.\"]}', 6, '2026-07-06 21:15:48', '2026-07-06 21:15:48'),
(4198, 708, 'hook', '{\"title\": \"Bạn có biết bản dạng của mình không phải là một khối bê tông cố định?\"}', 1, '2026-07-06 21:15:48', '2026-07-06 21:15:48'),
(4199, 708, 'explanation', '{\"bullets\": [\"Bạn của năm 10 tuổi chắc chắn rất khác bạn của năm 14 tuổi, và sẽ còn khác nữa khi bạn 20 tuổi.\", \"Bản dạng là một dòng chảy liên tục (fluidity).\", \"Hãy cho phép mình thay đổi sở thích, thay đổi góc nhìn, và thậm chí thay đổi cách tự định nghĩa bản thân khi bạn lớn lên.\"]}', 2, '2026-07-06 21:15:48', '2026-07-06 21:15:48'),
(4200, 708, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Hải trước đây cực kỳ ghét các môn nghệ thuật và chỉ thích chơi game. Nhưng dạo gần đây Hải bỗng nhiên thích nghe nhạc cổ điển và tập tành viết thơ. Bạn bè trêu Hải là \\\"bày đặt làm màu\\\", làm Hải thấy ngại ngùng và định vứt bỏ cuốn sổ thơ.\"}', 3, '2026-07-06 21:15:48', '2026-07-06 21:15:48'),
(4201, 708, 'interaction', '{\"question\": \"Bạn sẽ khuyên Hải điều gì trước phản ứng của bạn bè?\", \"choices\": [{\"text\": \"Hãy cất cuốn sổ thơ đi và quay lại chơi game để không bị trêu nữa.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Cứ tiếp tục viết thơ và tận hưởng sở thích mới, vì con người ai rồi cũng thay đổi mà!\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:15:48', '2026-07-06 21:15:48'),
(4202, 708, 'reflection', '{\"question\": \"Hãy nghĩ về một điều bạn từng ghét cay ghét đắng nhưng giờ lại cực kỳ thích?\"}', 5, '2026-07-06 21:15:48', '2026-07-06 21:15:48'),
(4203, 708, 'takeaway', '{\"items\": [\"Thay đổi là dấu hiệu cho thấy bạn đang lớn lên và trải nghiệm cuộc sống.\"]}', 6, '2026-07-06 21:15:49', '2026-07-06 21:15:49'),
(4204, 709, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Ai là tôi trong gương\'! Hãy cùng kiểm tra lại xem mình đã hiểu rõ về bản dạng chưa nhé.\"}', 1, '2026-07-06 21:15:49', '2026-07-06 21:15:49'),
(4205, 709, 'scenario-choice', '{\"title\": \"Cuộc phiêu lưu: Lắng nghe bản thân\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn được đề nghị làm trưởng ban kỹ thuật của lớp vì mọi người nghĩ con trai giỏi công nghệ hơn, nhưng bạn lại chỉ thích vẽ poster trang trí.\", \"choices\": [{\"text\": \"Nhận lời làm kỹ thuật để không bị coi là lạc loài.\", \"nextNode\": \"fail_submit\"}, {\"text\": \"Tự tin chia sẻ sở thích vẽ poster và nhường ban kỹ thuật cho bạn học khác giỏi hơn.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Bạn cùng nhóm trang trí poster nhưng các bạn cười chê ý tưởng của bạn là \'quá mơ mộng và kỳ quặc\'.\", \"choices\": [{\"text\": \"Xóa đi vẽ lại theo ý các bạn cho yên chuyện.\", \"nextNode\": \"fail_guilt\"}, {\"text\": \"Giải thích ý tưởng sáng tạo của mình và đề xuất cùng thảo luận để giữ lại nét độc bản.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành thử thách! Bạn đã dũng cảm sống thật với sở thích của mình và biết cách tôn trọng sự độc bản của bản thân.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_submit\": {\"text\": \"❌ Thất bại! Ép mình làm việc không thích chỉ để giống kỳ vọng của người khác sẽ làm bạn mệt mỏi.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_guilt\": {\"text\": \"❌ Thất bại! Từ bỏ sự sáng tạo của mình vì sợ bị trêu chọc sẽ làm bạn đánh mất cái tôi độc bản.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-06 21:15:49', '2026-07-06 21:15:49'),
(4206, 709, 'sorting', '{\"instruction\": \"Hãy phân loại các mảnh ghép Bản dạng sau:\", \"leftBox\": {\"title\": \"Mảnh ghép cá nhân (Sở thích/Cảm xúc)\"}, \"rightBox\": {\"title\": \"Nhãn dán xã hội (Kỳ vọng áp đặt)\"}, \"items\": [{\"text\": \"Thích vẽ anime và viết nhật ký thầm kín\", \"correctBox\": \"left\"}, {\"text\": \"Phải thi chuyên Toán để bố mẹ vui lòng\", \"correctBox\": \"right\"}, {\"text\": \"Mặc quần áo rộng vì thấy thoải mái nhất\", \"correctBox\": \"left\"}, {\"text\": \"Phải cư xử thật mạnh mẽ để không bị trêu\", \"correctBox\": \"right\"}]}', 3, '2026-07-06 21:15:49', '2026-07-06 21:15:49'),
(4207, 709, 'matching', '{\"instruction\": \"Ghép cặp các khái niệm về bản dạng cá nhân sau:\", \"pairs\": [{\"left\": \"Bản dạng\", \"right\": \"Tổng hòa các mảnh ghép tạo nên bạn\"}, {\"left\": \"Tính linh hoạt\", \"right\": \"Sự thay đổi tự nhiên của sở thích theo thời gian\"}, {\"left\": \"Chấp nhận bản thân\", \"right\": \"Yêu cả những nét khác biệt của riêng mình\"}, {\"left\": \"Áp lực nhãn dán\", \"right\": \"Kỳ vọng của người khác áp lên vai bạn\"}]}', 4, '2026-07-06 21:15:49', '2026-07-06 21:15:49'),
(4208, 709, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về bản dạng cơ bản:\", \"sentence\": \"Bản dạng của bạn giống như một bức tranh [blank1] khổng lồ. Hãy nhớ rằng bản dạng không phải là khối bê tông cố định mà là một dòng [blank2] liên tục. Bạn hoàn toàn có quyền thay đổi sở thích và cách tự định nghĩa mình để [blank3] lên mỗi ngày.\", \"blanks\": {\"blank1\": {\"correct\": \"ghép hình\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"chảy\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"lớn\", \"placeholder\": \"...\"}}, \"words\": [\"ghép hình\", \"chảy\", \"lớn\", \"bê tông\", \"dừng\", \"nhỏ\"]}', 5, '2026-07-06 21:15:49', '2026-07-06 21:15:49'),
(4209, 709, 'interaction', '{\"question\": \"Khi bạn thấy mình chưa định vị được bản thân ở tuổi 14, phản ứng nào là lành mạnh nhất?\", \"choices\": [{\"text\": \"Bình tĩnh đón nhận, tiếp tục trải nghiệm và thử thách những điều mới mẻ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Hoang mang lo lắng, vội vàng chọn một nhãn dán bất kỳ để giống bạn bè.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-06 21:15:49', '2026-07-06 21:15:49'),
(4210, 710, 'hook', '{\"title\": \"Ủa, cơ thể là nam/nữ thì suy nghĩ bên trong cũng bắt buộc phải tương tự sao?\"}', 1, '2026-07-06 21:15:50', '2026-07-06 21:15:50');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(4211, 710, 'explanation', '{\"bullets\": [\"Giới tính sinh học (Sex) là các đặc điểm cơ thể như NST, hormone, cơ quan sinh học được chỉ định lúc sinh ra.\", \"Bản dạng giới (Gender Identity) là cảm nhận sâu kín bên trong của bạn về giới tính của mình.\", \"Hai khái niệm này không nhất thiết lúc nào cũng đi đôi với nhau.\"]}', 2, '2026-07-06 21:15:50', '2026-07-06 21:15:50'),
(4212, 710, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Tú sinh ra với cơ thể là nữ, nhưng từ nhỏ Tú đã luôn cảm thấy mình là một cậu con trai. Mỗi lần mặc váy hay được gọi là \\\"con gái ngoan của mẹ\\\", Tú lại cảm thấy có một sự lệch nhịp, uncomfy cực kỳ mà không biết giải thích với ai.\"}', 3, '2026-07-06 21:15:50', '2026-07-06 21:15:50'),
(4213, 710, 'interaction', '{\"question\": \"Hãy điền vào chỗ trống:* Giới tính sinh học là do ________ quyết định khi sinh ra, còn bản dạng giới là do ________ cảm nhận.\", \"choices\": [{\"text\": \"Cơ thể / Suy nghĩ bên trong\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Suy nghĩ bên trong / Cơ thể\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:15:50', '2026-07-06 21:15:50'),
(4214, 710, 'reflection', '{\"question\": \"Bạn có bao giờ cảm thấy những kỳ vọng dành cho giới tính sinh học của mình quá gò bó không?\"}', 5, '2026-07-06 21:15:50', '2026-07-06 21:15:50'),
(4215, 710, 'takeaway', '{\"items\": [\"Cơ thể thể hiện sinh học của bạn, nhưng chính tâm trí mới định nghĩa bạn là ai.\"]}', 6, '2026-07-06 21:15:50', '2026-07-06 21:15:50'),
(4216, 711, 'hook', '{\"title\": \"Bạn có từng nghe đến từ \'Hợp giới\' và \'Chuyển giới\' trên mạng xã hội?\"}', 1, '2026-07-06 21:15:50', '2026-07-06 21:15:50'),
(4217, 711, 'explanation', '{\"bullets\": [\"Hợp giới (Cisgender) là khi bản dạng giới trùng khớp hoàn toàn với giới tính sinh học được chỉ định lúc sinh ra.\", \"Chuyển giới (Transgender) là khi bản dạng giới khác biệt so với giới tính sinh học lúc sinh ra.\", \"Đây chỉ là sự đa dạng tự nhiên của con người, không có gì là kỳ lạ cả.\"]}', 2, '2026-07-06 21:15:50', '2026-07-06 21:15:50'),
(4218, 711, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Trong giờ sinh hoạt lớp, một bạn nam thắc mắc: *\\\"Thế tụi mình sinh ra là nam, thấy mình là nam thì gọi là gì?\\\"* Cả lớp ngơ ngác nhìn nhau vì trước giờ chỉ nghe từ \\\"Chuyển giới\\\" chứ chưa nghe từ mô tả chiều ngược lại.\"}', 3, '2026-07-06 21:15:50', '2026-07-06 21:15:50'),
(4219, 711, 'interaction', '{\"question\": \"Theo bạn, từ nào dùng để mô tả một người có bản dạng giới TRÙNG KHỚP với giới tính sinh học lúc sinh ra?\", \"choices\": [{\"text\": \"Transgender\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Cisgender\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:15:50', '2026-07-06 21:15:50'),
(4220, 711, 'reflection', '{\"question\": \"Bạn cảm thấy thế nào khi lần đầu tiên nghe về khái niệm Hợp giới (Cisgender)?\"}', 5, '2026-07-06 21:15:50', '2026-07-06 21:15:50'),
(4221, 711, 'takeaway', '{\"items\": [\"Dù là hợp giới hay chuyển giới, trải nghiệm của bạn đều hoàn toàn hợp lệ.\"]}', 6, '2026-07-06 21:15:50', '2026-07-06 21:15:50'),
(4222, 712, 'hook', '{\"title\": \"Nếu giới tính không chỉ là hai sự lựa chọn Nam hoặc Nữ, thì nó là gì?\"}', 1, '2026-07-06 21:15:51', '2026-07-06 21:15:51'),
(4223, 712, 'explanation', '{\"bullets\": [\"Phi nhị nguyên giới (Non-binary) là khái niệm chỉ những người có bản dạng giới không nằm gọn trong hệ nhị nguyên Nam hoặc Nữ.\", \"Họ có thể cảm thấy mình là sự kết hợp của cả hai, ở giữa dải phổ, hoặc hoàn toàn không thuộc về giới nào (vô giới).\", \"Giới là một dải phổ màu sắc (spectrum) thay vì chỉ có hai màu đen và trắng.\"]}', 2, '2026-07-06 21:15:51', '2026-07-06 21:15:51'),
(4224, 712, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Mây (15 tuổi) không cảm thấy mình là con gái, nhưng cũng không muốn làm con trai. Mây thích để tóc ngắn, mặc đồ trung tính và cảm thấy dễ chịu nhất khi được là chính mình mà không bị gắn với bất kỳ nhãn giới nào.\"}', 3, '2026-07-06 21:15:51', '2026-07-06 21:15:51'),
(4225, 712, 'interaction', '{\"question\": \"Hãy chọn hình ảnh so sánh đúng nhất về bản dạng giới:\", \"choices\": [{\"text\": \"A. Hai chiếc công tắc chỉ có Bật\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"B. Một bảng pha màu với vô số sắc độ khác nhau.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:15:51', '2026-07-06 21:15:51'),
(4226, 712, 'reflection', '{\"question\": \"Bạn có nghĩ việc chia mọi thứ thành \'chỉ nam hoặc nữ\' đôi khi làm giới hạn sự sáng tạo của con người không?\"}', 5, '2026-07-06 21:15:51', '2026-07-06 21:15:51'),
(4227, 712, 'takeaway', '{\"items\": [\"Thế giới muôn màu, và giới tính cũng là một bức tranh đa sắc.\"]}', 6, '2026-07-06 21:15:51', '2026-07-06 21:15:51'),
(4228, 713, 'hook', '{\"title\": \"Bạn có từng cảm thấy bức bối khi cơ thể thay đổi theo hướng mình hoàn toàn không mong muốn?\"}', 1, '2026-07-06 21:15:51', '2026-07-06 21:15:51'),
(4229, 713, 'explanation', '{\"bullets\": [\"Tuổi dậy thì mang đến những biến đổi cơ thể rất lớn (vỡ giọng, ngực phát triển, mọc lông...).\", \"Với những bạn Chuyển giới hoặc Phi nhị nguyên, các thay đổi này có thể tạo ra sự bất an giới (gender dysphoria) - cảm giác lạc lõng, chối bỏ cơ thể.\", \"Hiểu và gọi tên được cảm xúc này giúp xoa dịu đi sự cô độc và sợ hãi.\"]}', 2, '2026-07-06 21:15:51', '2026-07-06 21:15:51'),
(4230, 713, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Kỳ (sinh ra là nữ) bắt đầu thấy ngực mình phát triển ở tuổi 13. Kỳ cảm thấy vô cùng sợ hãi, ghét nhìn mình trong gương và luôn tìm cách mặc áo bó sát để che giấu ngực. Kỳ cảm thấy mình bất thường và luôn sống trong tâm trạng u uất.\"}', 3, '2026-07-06 21:15:51', '2026-07-06 21:15:51'),
(4231, 713, 'interaction', '{\"question\": \"Nếu Kỳ tâm sự với bạn nỗi lòng này, phản ứng nào của bạn sẽ giúp ích cho Kỳ nhất?\", \"choices\": [{\"text\": \"\\\"Con gái ai dậy thì chả thế, điệu đà lên tí đi Kỳ!\\\"\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"\\\"Tớ hiểu cảm giác của bạn lúc này chắc chắn rất khó khăn. Tớ luôn ở đây lắng nghe bạn.\\\"\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:15:51', '2026-07-06 21:15:51'),
(4232, 713, 'reflection', '{\"question\": \"Làm thế nào chúng ta có thể tạo ra một môi trường học đường thân thiện hơn cho những bạn đang trải qua sự bất an giới?\"}', 5, '2026-07-06 21:15:51', '2026-07-06 21:15:51'),
(4233, 713, 'takeaway', '{\"items\": [\"Cảm xúc của bạn là thật, và bạn có quyền được lắng nghe và tôn trọng.\"]}', 6, '2026-07-06 21:15:52', '2026-07-06 21:15:52'),
(4234, 714, 'hook', '{\"title\": \"Tại sao một từ xưng hô nhỏ xíu lại có sức mạnh làm thay đổi cả ngày của ai đó?\"}', 1, '2026-07-06 21:15:52', '2026-07-06 21:15:52'),
(4235, 714, 'explanation', '{\"bullets\": [\"Đại từ xưng hô (Pronouns) là các từ dùng để gọi một người thay cho tên riêng (ông/bà, bạn/cậu, anh/chị, hoặc xưng tên).\", \"Gọi đúng cách xưng hô mong muốn là cách thể hiện sự tôn trọng tối thiểu đối với bản dạng của họ.\", \"Nếu chưa chắc chắn, cách tốt nhất là hỏi một cách lịch sự thay vì đoán bừa.\"]}', 2, '2026-07-06 21:15:52', '2026-07-06 21:15:52'),
(4236, 714, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Lan mới chuyển đến lớp, để tóc tém rất ngầu. Mọi người liên tục gọi Lan là \\\"anh chàng mới\\\" hoặc dùng từ xưng hô của nam. Lan cảm thấy rất uncomfy vì dù cắt tóc ngắn nhưng Lan vẫn thấy mình là nữ và muốn được gọi bằng bạn/cậu hoặc xưng tên.\"}', 3, '2026-07-06 21:15:52', '2026-07-06 21:15:52'),
(4237, 714, 'interaction', '{\"question\": \"Cách hỏi tế nhị nhất về đại từ xưng hô của một người bạn mới gặp là gì?\", \"choices\": [{\"text\": \"\\\"Này, cậu là nam hay nữ thế để tớ biết đường xưng hô?\\\"\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"\\\"Tớ xưng hô là \'cậu - tớ\' hoặc gọi tên bạn nhé, hay bạn thích cách xưng hô nào khác không?\\\"\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:15:52', '2026-07-06 21:15:52'),
(4238, 714, 'reflection', '{\"question\": \"Cách xưng hô nào khiến bạn cảm thấy thoải mái và được tôn trọng nhất khi người khác gọi mình?\"}', 5, '2026-07-06 21:15:52', '2026-07-06 21:15:52'),
(4239, 714, 'takeaway', '{\"items\": [\"Tôn trọng cách xưng hô của một người chính là tôn trọng sự tồn tại của họ.\"]}', 6, '2026-07-06 21:15:52', '2026-07-06 21:15:52'),
(4240, 715, 'hook', '{\"title\": \"Bạn có dám dành ra 1 phút tĩnh lặng để lắng nghe tiếng nói thật từ cơ thể và tâm trí mình?\"}', 1, '2026-07-06 21:15:52', '2026-07-06 21:15:52'),
(4241, 715, 'explanation', '{\"bullets\": [\"Những ồn ào và phán xét từ môi trường bên ngoài đôi khi khiến bạn mất kết nối với bản thân.\", \"Bản dạng giới không cần bạn phải chứng minh cho bất cứ ai xem.\", \"Đó là cuộc đối thoại và thấu hiểu riêng tư giữa bạn và chính bạn.\"]}', 2, '2026-07-06 21:15:52', '2026-07-06 21:15:52'),
(4242, 715, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Hải thường xuyên xem các video về chủ đề LGBT+ trên TikTok và thấy mình có những nét tương đồng với các bạn chuyển giới nam. Tuy nhiên, Hải vẫn thấy rất hoang mang và không biết cảm nhận này có thực sự lâu dài hay chỉ là nhất thời.\"}', 3, '2026-07-06 21:15:52', '2026-07-06 21:15:52'),
(4243, 715, 'interaction', '{\"question\": \"Kéo thanh trượt để biểu thị cảm xúc của bạn khi tự đối thoại với bản thân về giới tính:\", \"choices\": [{\"text\": \"😐\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"🙁\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"😊\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:15:52', '2026-07-06 21:15:52'),
(4244, 715, 'reflection', '{\"question\": \"Nếu không có bất kỳ định kiến hay kỳ vọng nào từ xã hội, bạn muốn mình là ai?\"}', 5, '2026-07-06 21:15:52', '2026-07-06 21:15:52'),
(4245, 715, 'takeaway', '{\"items\": [\"Bạn không cần phải có câu trả lời hoàn hảo ngay hôm nay. Hãy cứ dịu dàng với chính mình.\"]}', 6, '2026-07-06 21:15:53', '2026-07-06 21:15:53'),
(4246, 716, 'hook', '{\"title\": \"Không có một \'công thức\' chuẩn nào cho việc làm nam, làm nữ hay làm chính mình.\"}', 1, '2026-07-06 21:15:53', '2026-07-06 21:15:53'),
(4247, 716, 'explanation', '{\"bullets\": [\"Không ai có quyền định đoạt giới tính của bạn thay bạn.\", \"Bản dạng giới của bạn hoàn toàn hợp lệ bất kể cơ thể bạn thế nào hay bạn ăn mặc ra sao.\", \"Bạn xứng đáng được tự hào vì đã dũng cảm đi tìm câu trả lời cho bản thân.\"]}', 2, '2026-07-06 21:15:53', '2026-07-06 21:15:53'),
(4248, 716, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Bảo (phi nhị nguyên giới) quyết định chia sẻ bản dạng của mình với nhóm bạn thân. Mặc dù rất run, nhưng khi thấy các bạn gật đầu bảo *\\\"Bọn tớ chơi với Bảo vì Bảo là Bảo thôi, không quan trọng nhãn dán đâu\\\"*, Bảo cảm thấy như trút bỏ được tảng đá đè nặng trong lòng bấy lâu nay.\"}', 3, '2026-07-06 21:15:53', '2026-07-06 21:15:53'),
(4249, 716, 'interaction', '{\"question\": \"Hành động nào thể hiện sự ủng hộ tốt nhất dành cho một người bạn vừa công khai bản dạng giới?\", \"choices\": [{\"text\": \"Hỏi dồn dập các câu hỏi tò mò về cơ thể và chuyện phẫu thuật.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Lắng nghe chân thành, cảm ơn bạn đã tin tưởng chia sẻ và tiếp tục đối xử bình thường như trước.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:15:53', '2026-07-06 21:15:53'),
(4250, 716, 'reflection', '{\"question\": \"Bạn có muốn trở thành một điểm tựa an toàn để bạn bè có thể thoải mái chia sẻ những bí mật thầm kín của họ?\"}', 5, '2026-07-06 21:15:53', '2026-07-06 21:15:53'),
(4251, 716, 'takeaway', '{\"items\": [\"Bản dạng của bạn là duy nhất và luôn xứng đáng được tôn trọng.\"]}', 6, '2026-07-06 21:15:53', '2026-07-06 21:15:53'),
(4252, 717, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Bản dạng giới\'! Sẵn sàng check-in kiến thức về cơ thể và tâm trí chưa nào?\"}', 1, '2026-07-06 21:15:53', '2026-07-06 21:15:53'),
(4253, 717, 'scenario-choice', '{\"title\": \"Cuộc phiêu lưu: Tôn trọng bản dạng\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn gặp một người bạn mới tự giới thiệu tên là Nam nhưng xưng hô bằng từ \'cậu/tớ\' và muốn được coi là phi nhị nguyên giới.\", \"choices\": [{\"text\": \"Gặng hỏi xem bạn ấy thực chất là nam hay nữ sinh học.\", \"nextNode\": \"fail_submit\"}, {\"text\": \"Vui vẻ chào bạn và xưng hô bằng \'cậu - tớ\' như bạn ấy mong muốn.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Một người bạn khác kéo bạn ra một góc nói xấu: \'Nhìn đứa đó bất thường quá, chơi cùng làm gì\'.\", \"choices\": [{\"text\": \"Hùa theo để không bị cô lập khỏi nhóm.\", \"nextNode\": \"fail_guilt\"}, {\"text\": \"Nhắc nhở bạn ấy rằng mỗi người có một bản dạng riêng và tiếp tục chơi với bạn mới.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành thử thách! Bạn đã trở thành một đồng minh tôn trọng bản dạng giới và đại từ xưng hô của người khác.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_submit\": {\"text\": \"❌ Thất bại! Tò mò quá mức về giới tính sinh học làm đối phương thấy bị săm soi và thiếu tôn trọng.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_guilt\": {\"text\": \"❌ Thất bại! Đồng lõa với sự kỳ thị ngầm làm tổn thương người khác và đánh mất đi sự tử tế.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-06 21:15:53', '2026-07-06 21:15:53'),
(4254, 717, 'sorting', '{\"instruction\": \"Hãy phân loại các trải nghiệm sau:\", \"leftBox\": {\"title\": \"Cisgender (Hợp giới)\"}, \"rightBox\": {\"title\": \"Transgender (Chuyển giới)\"}, \"items\": [{\"text\": \"Sinh ra là nữ, lớn lên thấy mình là con gái\", \"correctBox\": \"left\"}, {\"text\": \"Sinh ra là nam, lớn lên thấy mình là con gái\", \"correctBox\": \"right\"}, {\"text\": \"Sinh ra là nữ, lớn lên cảm thấy mình là con trai\", \"correctBox\": \"right\"}, {\"text\": \"Sinh ra là nam, lớn lên thấy mình là con trai\", \"correctBox\": \"left\"}]}', 3, '2026-07-06 21:15:53', '2026-07-06 21:15:53'),
(4255, 717, 'matching', '{\"instruction\": \"Ghép cặp các khái niệm về giới tính cơ bản sau:\", \"pairs\": [{\"left\": \"Giới tính sinh học\", \"right\": \"Đặc điểm cơ thể được chỉ định khi sinh ra\"}, {\"left\": \"Bản dạng giới\", \"right\": \"Cảm nhận sâu sắc bên trong đầu và trái tim về giới của mình\"}, {\"left\": \"Phi nhị nguyên\", \"right\": \"Bản dạng giới không nằm gọn trong hộp Nam hoặc Nữ\"}, {\"left\": \"Đại từ xưng hô\", \"right\": \"Cách gọi tôn trọng danh tính tự định hình\"}]}', 4, '2026-07-06 21:15:53', '2026-07-06 21:15:53'),
(4256, 717, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về giới tính sinh học:\", \"sentence\": \"Giới tính [blank1] là do đặc điểm cơ thể quyết định khi sinh ra, trong khi bản dạng [blank2] là cảm nhận sâu kín bên trong của bạn. Những người có bản dạng giới khác với giới tính sinh học được gọi là người [blank3].\", \"blanks\": {\"blank1\": {\"correct\": \"sinh học\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"giới\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"chuyển giới\", \"placeholder\": \"...\"}}, \"words\": [\"sinh học\", \"giới\", \"chuyển giới\", \"xã hội\", \"hợp giới\", \"tự nhiên\"]}', 5, '2026-07-06 21:15:53', '2026-07-06 21:15:53'),
(4257, 717, 'interaction', '{\"question\": \"Đâu là cách ứng xử tinh tế nhất khi bạn lỡ xưng hô sai giới tính của một bạn chuyển giới?\", \"choices\": [{\"text\": \"Xin lỗi nhanh gọn, sửa lại từ xưng hô đúng và tiếp tục câu chuyện bình thường.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Giải thích dài dòng về việc mình quen miệng, nhắc lại quá khứ của bạn ấy.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-06 21:15:54', '2026-07-06 21:15:54'),
(4258, 718, 'hook', '{\"title\": \"Ủa, mặc đồ gì, để tóc ngắn hay dài có quyết định bạn là nam hay nữ không?\"}', 1, '2026-07-06 21:15:54', '2026-07-06 21:15:54'),
(4259, 718, 'explanation', '{\"bullets\": [\"**Thể hiện giới (Gender Expression):** Là cách bạn thể hiện giới tính ra bên ngoài qua quần áo, kiểu tóc, cử chỉ, giọng nói hay cách trang điểm.\", \"Bản dạng giới là suy nghĩ sâu thẳm bên trong đầu, còn thể hiện giới là phong cách trưng ra bên ngoài.\", \"Hai yếu tố này không bắt buộc phải đóng khung theo khuôn mẫu xã hội.\"]}', 2, '2026-07-06 21:15:54', '2026-07-06 21:15:54'),
(4260, 718, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Khoa (14 tuổi) thích để tóc dài ngang vai và thường xuyên buộc chỏm tỏi rất cute. Một vài bác hàng xóm nói *\\\"Con trai gì mà tóc tai bù xù như con gái thế kia\\\"*, làm Khoa thấy bực bội và tự hỏi sao mọi người lại quan trọng chuyện tóc tai đến vậy.\"}', 3, '2026-07-06 21:15:54', '2026-07-06 21:15:54'),
(4261, 718, 'interaction', '{\"question\": \"Nếu gặp Khoa, bạn sẽ nhắn nhủ điều gì?\", \"choices\": [{\"text\": \"\\\"Cắt tóc đi Khoa ơi, đỡ bị nói.\\\"\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"\\\"Tóc buộc chỏm tỏi trông rất cool và hợp với Khoa luôn á!\\\"\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:15:54', '2026-07-06 21:15:54'),
(4262, 718, 'reflection', '{\"question\": \"Bạn thích thể hiện phong cách của mình qua món đồ hay phụ kiện nào nhất?\"}', 5, '2026-07-06 21:15:54', '2026-07-06 21:15:54'),
(4263, 718, 'takeaway', '{\"items\": [\"Thời trang và kiểu tóc là để thể hiện cá tính, không phải để định nghĩa giới tính.\"]}', 6, '2026-07-06 21:15:54', '2026-07-06 21:15:54'),
(4264, 719, 'hook', '{\"title\": \"Ai bảo con trai không được khóc và con gái không được chơi siêu nhân?\"}', 1, '2026-07-06 21:15:54', '2026-07-06 21:15:54'),
(4265, 719, 'explanation', '{\"bullets\": [\"**Khuôn mẫu giới (Gender Roles):** Là những kỳ vọng, quy tắc ngầm của xã hội về cách cư xử của nam và nữ.\", \"Ví dụ: Con trai phải mạnh mẽ, làm kỹ thuật; con gái phải dịu dàng, khéo tay, làm bếp.\", \"Những khuôn mẫu này giống như những chiếc hộp chật chội khiến chúng ta mất đi tự do được phát triển bản thân.\"]}', 2, '2026-07-06 21:15:54', '2026-07-06 21:15:54'),
(4266, 719, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Hân rất thích tháo lắp, sửa chữa xe đạp và đồ điện tử trong nhà. Mỗi lần Hân cầm tô vít, mẹ Hân lại cản: *\\\"Tránh ra cho anh làm, con gái con lứa suốt ngày nghịch đồ kim khí rỉ sét\\\"*. Hân thấy rất ức chế vì Hân làm tốt hơn cả anh trai mình.\"}', 3, '2026-07-06 21:15:55', '2026-07-06 21:15:55'),
(4267, 719, 'interaction', '{\"question\": \"Hãy chọn ý kiến đúng nhất về khuôn mẫu giới:\", \"choices\": [{\"text\": \"A. Khuôn mẫu giới giúp xã hội ổn định, nam ra nam, nữ ra nữ.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"B. Khuôn mẫu giới là do con người tự tạo ra và hoàn toàn có thể thay đổi.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:15:55', '2026-07-06 21:15:55'),
(4268, 719, 'reflection', '{\"question\": \"Bạn từng bị cấm làm điều gì chỉ vì \'con trai/con gái ai lại làm thế\' chưa?\"}', 5, '2026-07-06 21:15:55', '2026-07-06 21:15:55'),
(4269, 719, 'takeaway', '{\"items\": [\"Khả năng và ước mơ của bạn không có giới tính.\"]}', 6, '2026-07-06 21:15:55', '2026-07-06 21:15:55'),
(4270, 720, 'hook', '{\"title\": \"Tại sao nhiều bạn nam cảm thấy \'tội lỗi\' khi thích những thứ nhẹ nhàng, hay bạn nữ thấy áp lực khi không giỏi nữ công gia chánh?\"}', 1, '2026-07-06 21:15:55', '2026-07-06 21:15:55'),
(4271, 720, 'explanation', '{\"bullets\": [\"Việc cố gắng gồng mình để khớp vào khuôn mẫu giới tạo ra áp lực tâm lý vô hình rất lớn.\", \"Nó khiến chúng ta che giấu cảm xúc thật, giả vờ là người khác để được bạn bè chấp nhận.\", \"Học cách phá vỡ áp lực này giúp chúng ta sống thoải mái và hạnh phúc hơn.\"]}', 2, '2026-07-06 21:15:55', '2026-07-06 21:15:55'),
(4272, 720, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Hải (15 tuổi) rất thích thêu thùa và may vá. Cậu tự thêu những hình rất xinh lên ba lô của mình. Khi bạn bè phát hiện, một nhóm bạn nam đã cười cợt và gọi cậu là *\\\"ẻo lả\\\"*, làm Hải rất xấu hổ và vứt luôn chiếc ba lô thêu.\"}', 3, '2026-07-06 21:15:55', '2026-07-06 21:15:55'),
(4273, 720, 'interaction', '{\"question\": \"Bạn sẽ phản ứng thế nào nếu chứng kiến Hải bị các bạn trêu chọc?\", \"choices\": [{\"text\": \"Hùa theo cười đùa để không bị coi là lạc loài.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Lại gần khen nét thêu của Hải và bảo *\\\"Thêu đẹp thế này khối đứa muốn học theo đấy!\\\"*.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:15:55', '2026-07-06 21:15:55'),
(4274, 720, 'reflection', '{\"question\": \"Bạn có thấy thoải mái khi thể hiện những mặt \'mềm yếu\' hoặc \'mạnh mẽ\' của mình ra ngoài không?\"}', 5, '2026-07-06 21:15:55', '2026-07-06 21:15:55'),
(4275, 720, 'takeaway', '{\"items\": [\"Mạnh mẽ nhất là khi bạn dám sống thật với cảm xúc và sở thích của mình.\"]}', 6, '2026-07-06 21:15:55', '2026-07-06 21:15:55'),
(4276, 721, 'hook', '{\"title\": \"Có bao giờ bạn bị người khác phán xét xu hướng tính dục chỉ qua bộ quần áo bạn đang mặc?\"}', 1, '2026-07-06 21:15:55', '2026-07-06 21:15:55'),
(4277, 721, 'explanation', '{\"bullets\": [\"Nhiều người hay nhìn phong cách ăn mặc để đoán một người là gay, les hay thẳng.\", \"Nhưng thể hiện giới (quần áo) và xu hướng tính dục (trái tim rung động vì ai) là hai chuyện hoàn toàn khác nhau.\", \"Đừng nhầm lẫn giữa sở thích thời trang và định hướng tình yêu.\"]}', 2, '2026-07-06 21:15:56', '2026-07-06 21:15:56'),
(4278, 721, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"My thích mặc đồ da, đi boot hầm hố, cắt tóc undercut. Các bạn trong lớp xì xào *\\\"Nhìn My men thế chắc chắn là tomboy/les rồi\\\"*. Thực tế, My chỉ đơn giản là thích phong cách thời trang cá tính này, và bạn ấy thích con trai.\"}', 3, '2026-07-06 21:15:56', '2026-07-06 21:15:56'),
(4279, 721, 'interaction', '{\"question\": \"Phát biểu nào sau đây là đúng khoa học?\", \"choices\": [{\"text\": \"Nhìn cách ăn mặc là biết ngay một người thuộc xu hướng tính dục nào.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Thể hiện giới bên ngoài không phản ánh xu hướng tính dục bên trong.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:15:56', '2026-07-06 21:15:56'),
(4280, 721, 'reflection', '{\"question\": \"Bạn đã từng phán xét ai đó qua vẻ bề ngoài của họ chưa?\"}', 5, '2026-07-06 21:15:56', '2026-07-06 21:15:56'),
(4281, 721, 'takeaway', '{\"items\": [\"Đừng dùng quần áo để đọc vị trái tim người khác.\"]}', 6, '2026-07-06 21:15:56', '2026-07-06 21:15:56'),
(4282, 722, 'hook', '{\"title\": \"Làm thế nào để mặc kệ những lời xầm xì và tự tin tỏa sáng với phong cách của riêng mình?\"}', 1, '2026-07-06 21:15:56', '2026-07-06 21:15:56'),
(4283, 722, 'explanation', '{\"bullets\": [\"Để vượt qua định kiến, hãy tìm kiếm những người bạn hoặc nhóm hỗ trợ tôn trọng sở thích của bạn.\", \"Tự nhắc nhở bản thân: bạn mặc đồ cho sự thoải mái và tự hào của bản thân, không phải để làm vừa lòng người khác.\", \"Tập bắt đầu với những thay đổi nhỏ khiến bạn cảm thấy tự tin và tự chủ nhất.\"]}', 2, '2026-07-06 21:15:56', '2026-07-06 21:15:56'),
(4284, 722, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Dương rất muốn mặc chiếc áo thun màu hồng pastel mà mình yêu thích đi học thêm, nhưng sợ các bạn nam khác cười chê là \\\"nữ tính\\\". Dương cứ đứng trước tủ đồ ngập ngừng mãi.\"}', 3, '2026-07-06 21:15:56', '2026-07-06 21:15:56'),
(4285, 722, 'interaction', '{\"question\": \"Hãy giúp Dương đưa ra quyết định tự tin nhất:\", \"choices\": [{\"text\": \"Cất áo hồng đi, mặc áo đen cho an toàn.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Mặc áo hồng phối với chiếc quần jeans năng động và tự tin bước ra đường.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:15:56', '2026-07-06 21:15:56'),
(4286, 722, 'reflection', '{\"question\": \"Bạn có một món đồ yêu thích nào nhưng chưa dám mặc ra đường không?\"}', 5, '2026-07-06 21:15:56', '2026-07-06 21:15:56'),
(4287, 722, 'takeaway', '{\"items\": [\"Màu sắc không có giới tính, mặc gì mình thấy vui và tự tin là được.\"]}', 6, '2026-07-06 21:15:56', '2026-07-06 21:15:56'),
(4288, 723, 'hook', '{\"title\": \"Nếu không có bất kỳ ai phán xét, phong cách lý tưởng mà bạn muốn thử nghiệm nhất là gì?\"}', 1, '2026-07-06 21:15:56', '2026-07-06 21:15:56'),
(4289, 723, 'explanation', '{\"bullets\": [\"Hãy tưởng tượng một thế giới lý tưởng không có định kiến và phán xét giới.\", \"Việc chọn quần áo, đầu tóc, hay cử chỉ hoàn toàn phản chiếu con người thật của bạn.\", \"Nghĩ về điều này giúp bạn tháo gỡ những rào cản tâm lý tích tụ lâu nay.\"]}', 2, '2026-07-06 21:15:56', '2026-07-06 21:15:56'),
(4290, 723, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"An thích trang điểm nhẹ nhàng, kẻ mắt mèo nhẹ khi đi chơi. Nhưng An luôn sợ bố mẹ mắng là *\\\"học đòi làm đỏm\\\"*. An thường phải lén lút trang điểm ở nhà vệ sinh công cộng trước khi gặp bạn bè.\"}', 3, '2026-07-06 21:15:56', '2026-07-06 21:15:56'),
(4291, 723, 'interaction', '{\"question\": \"Theo bạn, việc thử nghiệm trang điểm hay thay đổi phong cách ở tuổi dậy thì là:\", \"choices\": [{\"text\": \"Sự nổi loạn, ăn chơi đua đòi.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Nhu cầu làm đẹp và thể hiện cái tôi bình thường của mỗi người.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:15:56', '2026-07-06 21:15:56'),
(4292, 723, 'reflection', '{\"question\": \"Phong cách ăn mặc hiện tại của bạn đã phản ánh được bao nhiêu phần trăm con người thật của bạn rồi?\"}', 5, '2026-07-06 21:15:57', '2026-07-06 21:15:57'),
(4293, 723, 'takeaway', '{\"items\": [\"Thể hiện bản thân là một nghệ thuật, và bạn chính là nghệ sĩ.\"]}', 6, '2026-07-06 21:15:57', '2026-07-06 21:15:57'),
(4294, 724, 'hook', '{\"title\": \"Cuối cùng thì, bạn sinh ra để là chính mình, không phải là bản sao của bất kỳ khuôn mẫu nào.\"}', 1, '2026-07-06 21:15:57', '2026-07-06 21:15:57'),
(4295, 724, 'explanation', '{\"bullets\": [\"Thể hiện giới và khuôn mẫu giới chỉ là những định dạng do xã hội tự tạo ra theo thời gian.\", \"Bạn không cần ép bản thân vào chiếc hộp khuôn mẫu để được coi là \\\"hợp lệ\\\".\", \"Tôn trọng phong cách khác biệt của mọi người xung quanh là biểu hiện của một Gen Z văn minh.\"]}', 2, '2026-07-06 21:15:57', '2026-07-06 21:15:57'),
(4296, 724, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Cả lớp tổ chức một buổi trình diễn thời trang tái chế. Thay vì chia cặp nam nữ mặc đồ cưới truyền thống, lớp quyết định cho phép mọi người tự do chọn trang phục họ muốn trình diễn. Buổi diễn thành công rực rỡ với những sáng tạo không giới hạn.\"}', 3, '2026-07-06 21:15:57', '2026-07-06 21:15:57'),
(4297, 724, 'interaction', '{\"question\": \"Hãy chọn thông điệp ý nghĩa nhất mà khóa học muốn gửi gắm qua bài học này:\", \"choices\": [{\"text\": \"\\\"Hãy mặc những gì xã hội muốn bạn mặc.\\\"\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"\\\"Sự tự tin và tôn trọng sự khác biệt chính là bộ trang phục đẹp nhất của bạn.\\\"\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:15:57', '2026-07-06 21:15:57'),
(4298, 724, 'reflection', '{\"question\": \"Bạn sẽ làm gì để giúp những người xung quanh bạn cảm thấy tự tin thể hiện phong cách của họ?\"}', 5, '2026-07-06 21:15:57', '2026-07-06 21:15:57'),
(4299, 724, 'takeaway', '{\"items\": [\"Thời trang có thể mua được, nhưng sự tự do thể hiện chính mình là vô giá.\"]}', 6, '2026-07-06 21:15:57', '2026-07-06 21:15:57'),
(4300, 725, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Style & Định kiến\'! Hãy đập tan chiếc hộp khuôn mẫu giới.\"}', 1, '2026-07-06 21:15:57', '2026-07-06 21:15:57'),
(4301, 725, 'scenario-choice', '{\"title\": \"Cuộc phiêu lưu: Tự tin tỏa sáng\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn là nam, rất thích vẽ móng tay bằng các hình nghệ thuật vẽ tay. Bạn học cùng lớp trêu chọc bạn là \'ẻo lả\'.\", \"choices\": [{\"text\": \"Xóa sơn móng tay ngay lập tức để không bị nói.\", \"nextNode\": \"fail_submit\"}, {\"text\": \"Giữ lớp sơn móng tay, giải thích nhẹ nhàng đó là nghệ thuật vẽ.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Bố bạn thấy lớp sơn móng tay và mắng: \'Con trai phải ra con trai, cấm vẽ vời vớ vẩn\'.\", \"choices\": [{\"text\": \"Cãi lại bố và đóng sầm cửa.\", \"nextNode\": \"fail_guilt\"}, {\"text\": \"Giải thích cho bố hiểu đây chỉ là sở thích nghệ thuật làm đẹp cá nhân, không ảnh hưởng học tập.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành thử thách! Bạn đã kiên định với phong cách cá nhân của mình và xử lý xung đột một cách chín chắn.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_submit\": {\"text\": \"❌ Thất bại! Từ bỏ sở thích cá nhân chỉ vì định kiến làm bạn đánh mất niềm vui của mình.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_guilt\": {\"text\": \"❌ Thất bại! Cãi vã giận dỗi chỉ làm tăng xung đột mà không giải quyết được định kiến.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-06 21:15:57', '2026-07-06 21:15:57'),
(4302, 725, 'sorting', '{\"instruction\": \"Hãy phân loại các đặc điểm sau:\", \"leftBox\": {\"title\": \"Thể hiện giới (Bên ngoài)\"}, \"rightBox\": {\"title\": \"Xu hướng tính dục (Trái tim)\"}, \"items\": [{\"text\": \"Mặc quần jeans rộng và cắt tóc undercut\", \"correctBox\": \"left\"}, {\"text\": \"Cảm thấy rung động trước một bạn cùng giới\", \"correctBox\": \"right\"}, {\"text\": \"Trang điểm nhẹ nhàng khi đi chơi cùng bạn\", \"correctBox\": \"left\"}, {\"text\": \"Chỉ muốn gắn kết tình cảm với người vô tính\", \"correctBox\": \"right\"}]}', 3, '2026-07-06 21:15:57', '2026-07-06 21:15:57'),
(4303, 725, 'matching', '{\"instruction\": \"Ghép cặp các khái niệm về thể hiện giới sau:\", \"pairs\": [{\"left\": \"Thể hiện giới\", \"right\": \"Cách bộc lộ cá tính qua trang phục, tóc tai\"}, {\"left\": \"Khuôn mẫu giới\", \"right\": \"Kỳ vọng gò bó của xã hội lên nam và nữ\"}, {\"left\": \"Áp lực chuẩn men\", \"right\": \"Gồng mình che giấu cảm xúc thật của con trai\"}, {\"left\": \"Màu sắc thời trang\", \"right\": \"Không có giới tính, mặc gì mình thấy tự tin\"}]}', 4, '2026-07-06 21:15:58', '2026-07-06 21:15:58'),
(4304, 725, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về khuôn mẫu giới:\", \"sentence\": \"Khuôn mẫu giới giống như những chiếc [blank1] chật chội làm giới hạn khả năng phát triển của chúng ta. Hãy nhớ rằng cách [blank2] giới bên ngoài không phản ánh xu hướng tính dục bên trong của một người. Bạn có quyền tự do lựa chọn trang phục để làm [blank3] chính mình.\", \"blanks\": {\"blank1\": {\"correct\": \"hộp\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"thể hiện\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"vui\", \"placeholder\": \"...\"}}, \"words\": [\"hộp\", \"thể hiện\", \"vui\", \"lồng\", \"áp đặt\", \"đẹp\"]}', 5, '2026-07-06 21:15:58', '2026-07-06 21:15:58'),
(4305, 725, 'interaction', '{\"question\": \"Đâu là nhận định văn minh nhất về trang phục và giới tính?\", \"choices\": [{\"text\": \"Trang phục và màu sắc không có giới tính, mặc gì thoải mái và tự tin là được.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Con trai tuyệt đối không được mặc màu hồng, con gái không được cắt tóc undercut.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-06 21:15:58', '2026-07-06 21:15:58'),
(4306, 726, 'hook', '{\"title\": \"Bạn có biết trái tim rung động và cơ thể muốn gần gũi là hai cảm xúc hoàn toàn có thể tách biệt?\"}', 1, '2026-07-06 21:15:58', '2026-07-06 21:15:58'),
(4307, 726, 'explanation', '{\"bullets\": [\"**Xu hướng tính dục (Sexual Orientation):** Là sự thu hút về mặt thể xác/tình dục đối với người khác.\", \"**Xu hướng tình cảm (Romantic Orientation):** Là sự thu hút về mặt tình cảm, tâm hồn, mong muốn gắn kết yêu thương sâu sắc.\", \"Với nhiều người, hai xu hướng này trùng khớp nhau, nhưng có những người chúng lại rẽ theo hai hướng khác nhau.\"]}', 2, '2026-07-06 21:15:58', '2026-07-06 21:15:58'),
(4308, 726, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Hòa (14 tuổi) rất thích được trò chuyện, đi dạo và nắm tay bạn cùng lớp là Tuấn. Hòa cảm thấy một tình yêu trong sáng, lãng mạn vô cùng, nhưng cậu không hề có cảm giác muốn tiến xa hơn về mặt đụng chạm thể xác. Hòa băn khoăn liệu mình có bị \\\"lỗi cảm xúc\\\" không.\"}', 3, '2026-07-06 21:15:58', '2026-07-06 21:15:58'),
(4309, 726, 'interaction', '{\"question\": \"Bạn nghĩ gì về trường hợp của Hòa?\", \"choices\": [{\"text\": \"Hòa chỉ đang ngộ nhận, tình yêu thì bắt buộc phải đi kèm ham muốn thể xác.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Trải nghiệm của Hòa rất bình thường, tình cảm\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:15:58', '2026-07-06 21:15:58'),
(4310, 726, 'reflection', '{\"question\": \"Rung động lãng mạn đầu đời của bạn thường bắt nguồn từ tâm hồn hay vẻ bề ngoài của đối phương?\"}', 5, '2026-07-06 21:15:58', '2026-07-06 21:15:58'),
(4311, 726, 'takeaway', '{\"items\": [\"Trái tim và cơ thể có nhịp đập riêng, hãy tôn trọng cả hai cảm xúc đó.\"]}', 6, '2026-07-06 21:15:58', '2026-07-06 21:15:58'),
(4312, 727, 'hook', '{\"title\": \"Gay, Lesbian, Bi, Pan... các thuật ngữ này thực chất có ý nghĩa là gì?\"}', 1, '2026-07-06 21:15:59', '2026-07-06 21:15:59'),
(4313, 727, 'explanation', '{\"bullets\": [\"**Heterosexual (Dị tính):** Rung động với người có giới tính khác mình (thường gọi là \\\"thẳng\\\").\", \"**Gay/Lesbian (Đồng tính nam/nữ):** Rung động với người cùng giới với mình.\", \"**Bisexual (Song tính):** Rung động với cả hai giới nam và nữ.\", \"**Pansexual (Toàn tính):** Rung động với một người bất kể giới tính của họ là gì (\\\"yêu bằng tâm hồn\\\").\"]}', 2, '2026-07-06 21:15:59', '2026-07-06 21:15:59'),
(4314, 727, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Lâm thấy mình vừa có cảm tình với một bạn nữ cùng lớp, nhưng dạo gần đây cũng thấy tim đập thình thịch khi một bạn nam khóa trên mỉm cười với mình. Lâm hoang mang: *\\\"Ủa mình là gay hay thẳng đây? Sao kỳ cục vậy?\\\"*\"}', 3, '2026-07-06 21:15:59', '2026-07-06 21:15:59'),
(4315, 727, 'interaction', '{\"question\": \"Thuật ngữ nào mô tả đúng nhất cảm xúc của Lâm (rung động với cả nam và nữ)?\", \"choices\": [{\"text\": \"Heterosexual\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Bisexual\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:15:59', '2026-07-06 21:15:59'),
(4316, 727, 'reflection', '{\"question\": \"Bạn có cảm thấy thoải mái khi trò chuyện về các xu hướng tính dục khác nhau với bạn bè của mình?\"}', 5, '2026-07-06 21:15:59', '2026-07-06 21:15:59'),
(4317, 727, 'takeaway', '{\"items\": [\"Tình yêu không giới hạn ở một công thức duy nhất, mọi sắc màu đều đáng trân trọng.\"]}', 6, '2026-07-06 21:15:59', '2026-07-06 21:15:59'),
(4318, 728, 'hook', '{\"title\": \"Nếu bạn chẳng cảm thấy bị thu hút về mặt thể xác bởi bất kỳ ai, liệu bạn có bị bất thường?\"}', 1, '2026-07-06 21:15:59', '2026-07-06 21:15:59'),
(4319, 728, 'explanation', '{\"bullets\": [\"**Vô tính (Asexual/Ace):** Là những người ít hoặc không cảm thấy hấp dẫn về mặt tình dục với người khác.\", \"Họ vẫn có thể yêu thương, có xu hướng tình cảm (romantic) sâu sắc và muốn kết hôn, chỉ là họ không hứng thú với chuyện tình dục.\", \"Đây là một xu hướng tính dục tự nhiên và hoàn toàn lành mạnh, không phải là bệnh lý hay \'lãnh cảm\'.\"]}', 2, '2026-07-06 21:15:59', '2026-07-06 21:15:59'),
(4320, 728, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Ngân (15 tuổi) nghe các bạn trong nhóm bàn tán xôn xao về việc crush bạn này bạn kia trông quyến rũ thế nào, muốn ôm hôn ra sao. Ngân thấy mình hoàn toàn lạc lõng vì cô chỉ thích đọc truyện, đi uống trà sữa và trò chuyện chứ không hề có cảm xúc đụng chạm thể chất với ai. Ngân lo sợ mình bị \\\"thiếu hormone\\\".\"}', 3, '2026-07-06 21:15:59', '2026-07-06 21:15:59'),
(4321, 728, 'interaction', '{\"question\": \"Đâu là nhận thức đúng về người Vô tính (Asexual)?\", \"choices\": [{\"text\": \"Họ là những người bị bệnh sinh lý hoặc ghét con người.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Họ hoàn toàn có thể yêu và có những mối quan hệ lãng mạn hạnh phúc.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:15:59', '2026-07-06 21:15:59'),
(4322, 728, 'reflection', '{\"question\": \"Bạn có đồng ý rằng một tình yêu đẹp không nhất thiết phải có tình dục?\"}', 5, '2026-07-06 21:15:59', '2026-07-06 21:15:59'),
(4323, 728, 'takeaway', '{\"items\": [\"Không có ham muốn thể xác không có nghĩa là bạn thiếu khả năng yêu thương.\"]}', 6, '2026-07-06 21:15:59', '2026-07-06 21:15:59'),
(4324, 729, 'hook', '{\"title\": \"Sẽ thế nào khi bạn bỗng dưng \'crush\' một người cùng giới ở trường học?\"}', 1, '2026-07-06 21:15:59', '2026-07-06 21:15:59'),
(4325, 729, 'explanation', '{\"bullets\": [\"Cơn cảm nắng đầu đời luôn mang lại cảm xúc ngọt ngào xen lẫn bối rối.\", \"Khi đó là một người cùng giới, cảm xúc bối rối có thể nhân lên gấp bội vì lo lắng về phản ứng của bạn bè và gia đình.\", \"Hãy cho phép bản thân cảm nhận tình cảm đó một cách tự nhiên trước khi lo lắng về các nhãn dán.\"]}', 2, '2026-07-06 21:15:59', '2026-07-06 21:15:59'),
(4326, 729, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Phương (14 tuổi) nhận ra mình luôn tìm kiếm ánh mắt của Vy mỗi khi đến lớp. Khi Vy nói chuyện với bạn khác, Phương thấy lồng ngực thắt lại vì ghen. Phương chưa từng cảm thấy thế với bất kỳ bạn nam nào. Phương sợ hãi nghĩ: *\\\"Mình bị lệch lạc rồi sao?\\\"*\"}', 3, '2026-07-06 21:15:59', '2026-07-06 21:15:59'),
(4327, 729, 'interaction', '{\"question\": \"Nếu Phương tâm sự với bạn, bạn sẽ nói gì để xoa dịu nỗi sợ của bạn ấy?\", \"choices\": [{\"text\": \"\\\"Kinh thế, coi chừng người ta xa lánh đấy!\\\"\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"\\\"Rung động trước cái đẹp và sự đáng yêu là bình thường mà Phương. Tình cảm của cậu rất đẹp, đừng sợ nha.\\\"\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:16:00', '2026-07-06 21:16:00'),
(4328, 729, 'reflection', '{\"question\": \"Bạn đã từng trải qua cảm giác bối rối khi cảm nắng một ai đó chưa? Bạn đã đối diện với nó thế nào?\"}', 5, '2026-07-06 21:16:00', '2026-07-06 21:16:00'),
(4329, 729, 'takeaway', '{\"items\": [\"Cơn cảm nắng nào cũng đáng yêu và đáng trân trọng, dù đối phương là ai.\"]}', 6, '2026-07-06 21:16:00', '2026-07-06 21:16:00'),
(4330, 730, 'hook', '{\"title\": \"Làm sao để phân biệt giữa sự ngưỡng mộ bạn bè đơn thuần và một tình cảm lãng mạn thực sự?\"}', 1, '2026-07-06 21:16:00', '2026-07-06 21:16:00'),
(4331, 730, 'explanation', '{\"bullets\": [\"Đôi khi chúng ta nhầm lẫn giữa việc muốn \'trở thành\' giống ai đó (ngưỡng mộ phong cách của họ) và việc muốn \'ở bên cạnh\' họ (yêu thích họ).\", \"Hãy dành thời gian quan sát: Bạn có muốn nắm tay họ không? Có hay nghĩ về họ trước khi ngủ không?\", \"Đừng vội vàng ép mình phải có câu trả lời ngay lập tức.\"]}', 2, '2026-07-06 21:16:00', '2026-07-06 21:16:00'),
(4332, 730, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Kỳ luôn muốn đi chơi riêng với Nam, thấy nhớ Nam khi cuối tuần không gặp và cảm thấy ghen khi Nam thân thiết với người khác. Kỳ tự hỏi đây là tình bạn thân thiết hay mình đã thực sự yêu Nam rồi.\"}', 3, '2026-07-06 21:16:00', '2026-07-06 21:16:00'),
(4333, 730, 'interaction', '{\"question\": \"Cách tốt nhất để Kỳ xác định tình cảm của mình là gì?\", \"choices\": [{\"text\": \"Tỏ tình ngay lập tức để thử phản ứng.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Cho bản thân thêm thời gian, viết nhật ký cảm xúc hàng ngày để tự thấu hiểu lòng mình.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:16:00', '2026-07-06 21:16:00'),
(4334, 730, 'reflection', '{\"question\": \"Theo bạn, ranh giới giữa bạn thân và người yêu là gì?\"}', 5, '2026-07-06 21:16:00', '2026-07-06 21:16:00'),
(4335, 730, 'takeaway', '{\"items\": [\"Hãy để trái tim bạn tự viết nên câu chuyện của nó, không cần phải vội vã biên dịch.\"]}', 6, '2026-07-06 21:16:00', '2026-07-06 21:16:00'),
(4336, 731, 'hook', '{\"title\": \"Bạn có nhớ khoảnh khắc đầu tiên tim mình lỡ nhịp vì một ánh mắt hay nụ cười của ai đó?\"}', 1, '2026-07-06 21:16:01', '2026-07-06 21:16:01'),
(4337, 731, 'explanation', '{\"bullets\": [\"Những rung động đầu đời giống như những nốt nhạc đầu tiên trong bản nhạc cuộc đời.\", \"Nó có thể ngây ngô, có thể thoáng qua, nhưng nó dạy cho chúng ta biết thế nào là yêu thương và quan tâm đến một người.\", \"Trân trọng những xúc cảm này giúp tâm hồn bạn trở nên phong phú hơn.\"]}', 2, '2026-07-06 21:16:01', '2026-07-06 21:16:01'),
(4338, 731, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Hân (15 tuổi) ngồi trong lớp học bài nhưng mắt cứ nhìn ra cửa sổ, nơi có bạn lớp trưởng đang chơi bóng rổ. Mỗi lần bạn ấy ghi bàn và cười, tim Hân lại đập loạn nhịp. Hân viết vội tên bạn ấy vào góc vở rồi lại đỏ mặt xóa đi.\"}', 3, '2026-07-06 21:16:01', '2026-07-06 21:16:01'),
(4339, 731, 'interaction', '{\"question\": \"Cảm xúc của Hân trong tình huống trên là gì?\", \"choices\": [{\"text\": \"Sự xao nhãng học hành đáng trách.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Rung động ngây thơ, đáng yêu tuổi học trò.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:16:01', '2026-07-06 21:16:01'),
(4340, 731, 'reflection', '{\"question\": \"Nếu có thể gửi một lời nhắn ẩn danh cho người bạn từng crush, bạn sẽ viết gì?\"}', 5, '2026-07-06 21:16:01', '2026-07-06 21:16:01'),
(4341, 731, 'takeaway', '{\"items\": [\"Rung động tuổi học trò là món quà ngọt ngào của thời gian.\"]}', 6, '2026-07-06 21:16:01', '2026-07-06 21:16:01'),
(4342, 732, 'hook', '{\"title\": \"Cuối cùng, tình yêu chỉ đơn giản là tình yêu, không có ranh giới hay định kiến nào có thể ngăn cản.\"}', 1, '2026-07-06 21:16:01', '2026-07-06 21:16:01'),
(4343, 732, 'explanation', '{\"bullets\": [\"Mọi xu hướng tính dục và xu hướng tình cảm đều bình đẳng và xứng đáng được tôn trọng.\", \"Không có tình yêu nào là \'cao quý hơn\' hay \'thấp kém hơn\'.\", \"Một xã hội văn minh là nơi ai cũng được tự do yêu và được yêu một cách an toàn, hạnh phúc.\"]}', 2, '2026-07-06 21:16:01', '2026-07-06 21:16:01'),
(4344, 732, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Nhóm bạn tổ chức buổi picnic cuối tuần. Có cặp đôi dị tính, có cặp đôi đồng tính, và có cả những bạn đi một mình (vô tính/độc thân). Tất cả đều vui vẻ nướng thịt, ca hát và tôn trọng không gian riêng của nhau mà không hề có sự phân biệt đối xử nào.\"}', 3, '2026-07-06 21:16:01', '2026-07-06 21:16:01'),
(4345, 732, 'interaction', '{\"question\": \"Điều gì tạo nên một tình yêu lành mạnh?\", \"choices\": [{\"text\": \"A. Phải là tình yêu giữa nam và nữ theo đúng truyền thống.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"B. Sự tôn trọng, thấu hiểu, chân thành và tin tưởng lẫn nhau giữa hai người.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:16:01', '2026-07-06 21:16:01'),
(4346, 732, 'reflection', '{\"question\": \"Bạn mong muốn một mối quan hệ trong tương lai của mình sẽ có những giá trị cốt lõi nào?\"}', 5, '2026-07-06 21:16:01', '2026-07-06 21:16:01'),
(4347, 732, 'takeaway', '{\"items\": [\"Tình yêu đích thực được đo bằng sự tôn trọng và chân thành, chứ không phải bằng giới tính.\"]}', 6, '2026-07-06 21:16:01', '2026-07-06 21:16:01'),
(4348, 733, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Xu hướng tính dục\'! Hãy lắng nghe những thanh âm đa sắc của trái tim.\"}', 1, '2026-07-06 21:16:02', '2026-07-06 21:16:02'),
(4349, 733, 'scenario-choice', '{\"title\": \"Cuộc phiêu lưu: Đón nhận rung động\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn bỗng dưng cảm nắng một bạn học cùng giới. Bạn cảm thấy vô cùng bối rối và sợ bị coi là \'lệch lạc\'.\", \"choices\": [{\"text\": \"Cố ép bản thân phải crush một bạn khác giới để che giấu cảm xúc.\", \"nextNode\": \"fail_submit\"}, {\"text\": \"Chấp nhận cảm xúc này như một rung cảm tự nhiên, viết nhật ký để thấu hiểu mình.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Bạn muốn tâm sự với bạn thân để giải tỏa cảm xúc, nhưng sợ bạn ấy sẽ xa lánh mình.\", \"choices\": [{\"text\": \"Im lặng chịu đựng, giấu kín bí mật cho riêng mình.\", \"nextNode\": \"fail_guilt\"}, {\"text\": \"Thử mở lòng chia sẻ xem phản ứng của bạn ấy thế nào, nếu bạn ấy là đồng minh.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành thử thách! Bạn đã dũng cảm đối diện với tình cảm của mình và tìm thấy điểm tựa tinh thần an toàn.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_submit\": {\"text\": \"❌ Thất bại! Phủ nhận tình cảm thật chỉ làm bạn thấy ngột ngạt và tổn thương thêm.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_guilt\": {\"text\": \"❌ Thất bại! Gặm nhấm nỗi cô đơn một mình có thể gây ảnh hưởng xấu tới sức khỏe tinh thần.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-06 21:16:02', '2026-07-06 21:16:02'),
(4350, 733, 'sorting', '{\"instruction\": \"Hãy phân loại các xu hướng sau vào đúng hộp cảm xúc:\", \"leftBox\": {\"title\": \"Rung động đa giới (Bisexual/Pansexual)\"}, \"rightBox\": {\"title\": \"Rung động đơn giới (Straight/Gay/Lesbian)\"}, \"items\": [{\"text\": \"Cảm nắng cả bạn nam lẫn bạn nữ trong lớp\", \"correctBox\": \"left\"}, {\"text\": \"Chỉ yêu thương và muốn gắn kết với người cùng giới\", \"correctBox\": \"right\"}, {\"text\": \"Yêu một người vì tâm hồn bất kể giới tính của họ\", \"correctBox\": \"left\"}, {\"text\": \"Chỉ rung động với những người khác giới với mình\", \"correctBox\": \"right\"}]}', 3, '2026-07-06 21:16:02', '2026-07-06 21:16:02'),
(4351, 733, 'matching', '{\"instruction\": \"Ghép cặp các khái niệm về xu hướng tính dục sau:\", \"pairs\": [{\"left\": \"Dị tính\", \"right\": \"Rung động trước người khác giới\"}, {\"left\": \"Song tính\", \"right\": \"Rung động trước cả hai giới nam và nữ\"}, {\"left\": \"Toàn tính\", \"right\": \"Yêu bằng tâm hồn, bất kể giới tính đối phương\"}, {\"left\": \"Vô tính\", \"right\": \"Không hoặc ít có ham muốn thể xác, vẫn yêu tâm hồn\"}]}', 4, '2026-07-06 21:16:02', '2026-07-06 21:16:02'),
(4352, 733, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về xu hướng tình cảm:\", \"sentence\": \"Xu hướng tính dục là sự hấp dẫn về [blank1], còn xu hướng tình cảm là sự gắn kết về [blank2]. Người vô tính vẫn có thể yêu thương và có mối quan hệ [blank3] hạnh phúc sâu sắc.\", \"blanks\": {\"blank1\": {\"correct\": \"thể xác\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"tâm hồn\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"lãng mạn\", \"placeholder\": \"...\"}}, \"words\": [\"thể xác\", \"tâm hồn\", \"lãng mạn\", \"giới tính\", \"thể chất\", \"tình dục\"]}', 5, '2026-07-06 21:16:02', '2026-07-06 21:16:02'),
(4353, 733, 'interaction', '{\"question\": \"Khi bạn của bạn chia sẻ họ là người vô tính (Asexual), phản ứng nào là phù hợp nhất?\", \"choices\": [{\"text\": \"Tôn trọng cảm xúc của họ, hiểu rằng họ vẫn có nhu cầu yêu thương về tâm hồn.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Khuyên họ đi khám bác sĩ vì cho rằng họ bị thiếu hụt hormone sinh lý.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-06 21:16:02', '2026-07-06 21:16:02'),
(4354, 734, 'hook', '{\"title\": \"Bạn có thấy ổn khi cảm thấy mình không thuộc về bất cứ định nghĩa giới hay tính dục nào ở thời điểm này?\"}', 1, '2026-07-06 21:16:02', '2026-07-06 21:16:02'),
(4355, 734, 'explanation', '{\"bullets\": [\"**Questioning (Đang tự vấn):** Là trạng thái của một người đang trong quá trình tìm hiểu, khám phá, đặt câu hỏi về bản dạng giới hoặc xu hướng tính dục của mình.\", \"Đây không phải là sự \\\"lập lờ\\\" hay \\\"học đòi\\\", mà là một giai đoạn nhận thức hết sức tự nhiên.\", \"Rất nhiều người từng trải qua giai đoạn này trước khi tìm thấy nhãn dán phù hợp, hoặc chọn không dán nhãn luôn.\"]}', 2, '2026-07-06 21:16:02', '2026-07-06 21:16:02'),
(4356, 734, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Tâm (13 tuổi) cảm thấy mình không có sự thu hút rõ ràng nào với bạn nam hay bạn nữ nào. Đôi khi Tâm thấy mình giống con gái, đôi khi lại muốn ăn mặc giống con trai. Tâm cảm thấy cực kỳ mơ hồ và tự đặt câu hỏi: *\\\"Rốt cuộc mình là cái gì thế nhỉ?\\\"*\"}', 3, '2026-07-06 21:16:02', '2026-07-06 21:16:02'),
(4357, 734, 'interaction', '{\"question\": \"Hãy chọn thái độ phù hợp nhất với giai đoạn Questioning:\", \"choices\": [{\"text\": \"Cảm thấy lo lắng, tội lỗi và bắt buộc phải tìm ra câu trả lời ngay.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Đón nhận sự mơ hồ này như một hành trình khám phá thú vị và không tự tạo áp lực.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:16:02', '2026-07-06 21:16:02'),
(4358, 734, 'reflection', '{\"question\": \"Bạn có từng cảm thấy băn khoăn về một khía cạnh nào đó của bản thân mà chưa có câu trả lời rõ ràng chưa?\"}', 5, '2026-07-06 21:16:02', '2026-07-06 21:16:02'),
(4359, 734, 'takeaway', '{\"items\": [\"Mơ hồ không phải là lạc lối, đó là bạn đang cho phép mình tìm tòi.\"]}', 6, '2026-07-06 21:16:03', '2026-07-06 21:16:03'),
(4360, 735, 'hook', '{\"title\": \"Nhãn dán là để giúp bạn hiểu mình hơn, chứ không phải để tự nhốt mình vào một chiếc lồng kính.\"}', 1, '2026-07-06 21:16:03', '2026-07-06 21:16:03'),
(4361, 735, 'explanation', '{\"bullets\": [\"Xã hội thường thích dán nhãn mọi thứ để dễ phân loại.\", \"Nhưng con người là một thực thể phức tạp và linh hoạt.\", \"Việc vội vã chọn một nhãn dán (như gay, les, trans) khi chưa thực sự hiểu rõ có thể khiến bạn thấy gò bó sau này.\", \"Bạn hoàn toàn có quyền nói: *\\\"Tớ chưa biết, tớ vẫn đang tìm hiểu\\\"*.\"]}', 2, '2026-07-06 21:16:03', '2026-07-06 21:16:03'),
(4362, 735, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Vy (14 tuổi) kể với bạn thân rằng mình thích một bạn nữ khóa trên. Bạn thân liền hỏi ngay: *\\\"Thế Vy là lesbian à?\\\"*. Vy thấy giật mình và ngập ngừng vì thực tế Vy vẫn thấy con trai thu hút, Vy chưa biết chắc mình là song tính hay đồng tính.\"}', 3, '2026-07-06 21:16:03', '2026-07-06 21:16:03');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(4363, 735, 'interaction', '{\"question\": \"Lời khuyên nào tốt nhất cho Vy lúc này?\", \"choices\": [{\"text\": \"Vy nên thừa nhận đại một nhãn để các bạn không thắc mắc nữa.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Vy cứ bảo các bạn là \'Vy chỉ đang cảm nắng bạn ấy thôi, chưa cần dán nhãn gì đâu\'.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:16:03', '2026-07-06 21:16:03'),
(4364, 735, 'reflection', '{\"question\": \"Bạn có cảm thấy áp lực khi người khác liên tục hỏi bạn về \'gu\' hay \'nhãn dán\' của bạn không?\"}', 5, '2026-07-06 21:16:03', '2026-07-06 21:16:03'),
(4365, 735, 'takeaway', '{\"items\": [\"Bạn là một cuốn sách đang viết, không cần phải dán nhãn bìa quá sớm.\"]}', 6, '2026-07-06 21:16:03', '2026-07-06 21:16:03'),
(4366, 736, 'hook', '{\"title\": \"Nỗi sợ \'không biết mình là ai\' đôi khi còn đáng sợ hơn cả sự phán xét từ bên ngoài.\"}', 1, '2026-07-06 21:16:03', '2026-07-06 21:16:03'),
(4367, 736, 'explanation', '{\"bullets\": [\"Nhu cầu xác định danh tính để cảm thấy an toàn và thuộc về một nhóm là tâm lý rất tự nhiên.\", \"Khi không tìm ra câu trả lời ngay, bạn dễ rơi vào trạng thái bồn chồn, lo âu.\", \"Hãy nhớ rằng bộ não của bạn đang lớn, hormone đang thay đổi, và việc cảm xúc xáo trộn là điều bình thường.\"]}', 2, '2026-07-06 21:16:03', '2026-07-06 21:16:03'),
(4368, 736, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Huy lướt TikTok thấy các bạn trẻ chia sẻ hành trình tìm thấy bản thân rất tự tin và rõ ràng. Huy nhìn lại mình thì vẫn thấy mọi thứ mông lung như một trò đùa. Huy bắt đầu mất ngủ và lo lắng mình bị \\\"lệch nhịp phát triển\\\".\"}', 3, '2026-07-06 21:16:03', '2026-07-06 21:16:03'),
(4369, 736, 'interaction', '{\"question\": \"Khi thấy lo lắng vì chưa rõ bản thân, hành động nào sẽ giúp bạn bình tĩnh lại?\", \"choices\": [{\"text\": \"Tiếp tục lướt mạng xã hội và so sánh mình với người khác.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Tập trung vào những sở thích hiện tại\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:16:04', '2026-07-06 21:16:04'),
(4370, 736, 'reflection', '{\"question\": \"Bạn sẽ làm gì để vỗ về bản thân những lúc thấy hoang mang nhất?\"}', 5, '2026-07-06 21:16:04', '2026-07-06 21:16:04'),
(4371, 736, 'takeaway', '{\"items\": [\"Mọi câu trả lời đúng đều cần có thời gian để tự hoàn thiện.\"]}', 6, '2026-07-06 21:16:04', '2026-07-06 21:16:04'),
(4372, 737, 'hook', '{\"title\": \"Liệu có kỳ lạ không khi năm ngoái bạn nghĩ mình là thẳng, nhưng năm nay lại thấy mình là song tính?\"}', 1, '2026-07-06 21:16:04', '2026-07-06 21:16:04'),
(4373, 737, 'explanation', '{\"bullets\": [\"**Tính linh hoạt (Fluidity):** Là khái niệm chỉ sự thay đổi tự nhiên của bản dạng giới hoặc xu hướng tính dục theo thời gian và trải nghiệm cuộc sống.\", \"Con người không phải là một bức tượng đá. Chúng ta học hỏi, trải nghiệm và tiến hóa.\", \"Sự thay đổi này không có nghĩa là bạn nói dối hay giả tạo trước đây, nó chỉ là bạn đã lớn lên.\"]}', 2, '2026-07-06 21:16:04', '2026-07-06 21:16:04'),
(4374, 737, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Dũng (15 tuổi) từng công khai với nhóm bạn mình là Gay vào năm ngoái. Nhưng gần đây Dũng lại nhận ra mình có cảm tình đặc biệt với một bạn nữ cùng lớp vẽ. Dũng vô cùng hoảng sợ vì nghĩ các bạn sẽ bảo mình là *\\\"kẻ nói dối, làm màu\\\"*.\"}', 3, '2026-07-06 21:16:04', '2026-07-06 21:16:04'),
(4375, 737, 'interaction', '{\"question\": \"Nếu Dũng chia sẻ điều này với bạn, bạn sẽ phản hồi thế nào?\", \"choices\": [{\"text\": \"\\\"Ủa sao đổi xoành xoạch thế, làm vậy mất uy tín nha Dũng!\\\"\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"\\\"Không sao cả Dũng ơi, cảm xúc có quyền thay đổi mà. Bọn tớ luôn ủng hộ cậu!\\\"\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:16:04', '2026-07-06 21:16:04'),
(4376, 737, 'reflection', '{\"question\": \"Bạn có sẵn sàng chấp nhận nếu một người bạn thân thiết thay đổi cách họ tự định nghĩa bản thân không?\"}', 5, '2026-07-06 21:16:04', '2026-07-06 21:16:04'),
(4377, 737, 'takeaway', '{\"items\": [\"Hãy để bản thân trôi chảy như một dòng sông, thay vì đóng băng trong một định kiến.\"]}', 6, '2026-07-06 21:16:04', '2026-07-06 21:16:04'),
(4378, 738, 'hook', '{\"title\": \"Làm thế nào để giữ cho đầu óc không bị quá tải giữa hàng tá thông tin và nhãn dán trên mạng?\"}', 1, '2026-07-06 21:16:05', '2026-07-06 21:16:05'),
(4379, 738, 'explanation', '{\"bullets\": [\"**Detox mạng xã hội:** Hãy hạn chế xem các video so sánh hoặc các bài viết ép buộc bạn phải chọn phe, chọn nhãn.\", \"**Viết nhật ký cảm xúc:** Chỉ ghi lại những gì bạn thấy thực sự thoải mái ngày hôm nay mà không cần kết luận.\", \"**Tìm người tin cậy:** Trò chuyện với chuyên gia tâm lý học đường hoặc người lớn cởi mở để được lắng nghe an toàn.\"]}', 2, '2026-07-06 21:16:05', '2026-07-06 21:16:05'),
(4380, 738, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Phương cảm thấy đau đầu vì các hội nhóm trên mạng tranh cãi nảy lửa về việc thế nào mới là *\\\"chuyển giới chuẩn\\\"* hay *\\\"vô tính thực sự\\\"*. Phương thấy mình không khớp hoàn toàn vào định nghĩa nào và bắt đầu tự trách móc bản thân.\"}', 3, '2026-07-06 21:16:05', '2026-07-06 21:16:05'),
(4381, 738, 'interaction', '{\"question\": \"Bước đi nào thông minh nhất giúp Phương thoát khỏi sự độc hại tinh thần này?\", \"choices\": [{\"text\": \"Tham gia tranh luận để chứng minh mình đúng.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Tắt điện thoại, đi dạo hoặc trò chuyện với một người bạn thân hiểu mình ngoài đời thực.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:16:05', '2026-07-06 21:16:05'),
(4382, 738, 'reflection', '{\"question\": \"Mạng xã hội đã bao giờ làm bạn thấy nghi ngờ bản thân chưa?\"}', 5, '2026-07-06 21:16:05', '2026-07-06 21:16:05'),
(4383, 738, 'takeaway', '{\"items\": [\"Bạn không cần phải vừa vặn với bất kỳ định nghĩa sách vở nào để được công nhận.\"]}', 6, '2026-07-06 21:16:05', '2026-07-06 21:16:05'),
(4384, 739, 'hook', '{\"title\": \"Bạn có dám chấp nhận sống chung với câu hỏi chưa có lời đáp như một phần thú vị của cuộc sống?\"}', 1, '2026-07-06 21:16:05', '2026-07-06 21:16:05'),
(4385, 739, 'explanation', '{\"bullets\": [\"Cuộc sống không phải lúc nào cũng là các câu hỏi trắc nghiệm A, B, C có sẵn đáp án đúng ở cuối trang.\", \"Đôi khi, việc giữ câu hỏi mở giúp bạn khám phá ra nhiều điều tuyệt vời hơn về thế giới xung quanh.\", \"Học cách chấp nhận sự không chắc chắn là kỹ năng sống quan trọng giúp bạn trưởng thành.\"]}', 2, '2026-07-06 21:16:05', '2026-07-06 21:16:05'),
(4386, 739, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Bảo tự hứa với bản thân sẽ không ép mình phải tìm ra xu hướng tính dục của mình trước năm 18 tuổi. Bảo quyết định tập trung vào việc học guitar, tham gia câu lạc bộ thiện nguyện và tận hưởng những năm tháng cấp 3 vui vẻ cùng bạn bè.\"}', 3, '2026-07-06 21:16:05', '2026-07-06 21:16:05'),
(4387, 739, 'interaction', '{\"question\": \"Bạn đánh giá thế nào về quyết định của Bảo?\", \"choices\": [{\"text\": \"Trốn tránh thực tế, không dũng cảm đối diện.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Lựa chọn khôn ngoan để bảo vệ năng lượng tích cực của bản thân.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:16:05', '2026-07-06 21:16:05'),
(4388, 739, 'reflection', '{\"question\": \"Việc chưa biết rõ tương lai có làm bạn sợ hãi, hay nó kích thích sự tò mò của bạn?\"}', 5, '2026-07-06 21:16:05', '2026-07-06 21:16:05'),
(4389, 739, 'takeaway', '{\"items\": [\"Chấp nhận sự mông lung là bước đầu tiên để chào đón những khám phá bất ngờ.\"]}', 6, '2026-07-06 21:16:05', '2026-07-06 21:16:05'),
(4390, 740, 'hook', '{\"title\": \"Bạn không cần phải tìm ra mọi câu trả lời vào năm 15 tuổi.\"}', 1, '2026-07-06 21:16:05', '2026-07-06 21:16:05'),
(4391, 740, 'explanation', '{\"bullets\": [\"Hành trình khám phá bản thân kéo dài suốt cuộc đời mỗi con người.\", \"Mọi trải nghiệm, dù là nhầm lẫn hay đúng đắn, đều có giá trị giúp bạn hiểu rõ mình hơn.\", \"Hãy cứ tò mò, cứ trải nghiệm, và trên hết là hãy yêu thương bản thân trên từng chặng hành trình.\"]}', 2, '2026-07-06 21:16:05', '2026-07-06 21:16:05'),
(4392, 740, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Trong buổi lễ tốt nghiệp cấp 2, cô giáo chủ nhiệm nhắn nhủ cả lớp: *\\\"Các em hãy cứ tự tin bước ra thế giới, thử những điều mới, sai và sửa sai. Đừng vội đóng khung bản thân vào bất cứ định kiến nào.\\\"* Cả lớp vỗ tay rầm rộ, trong đó có những bạn đang vô cùng nhẹ nhõm.\"}', 3, '2026-07-06 21:16:05', '2026-07-06 21:16:05'),
(4393, 740, 'interaction', '{\"question\": \"Hãy chọn cam kết mà bạn muốn tự hứa với bản thân sau bài học này:\", \"choices\": [{\"text\": \"\\\"Tôi sẽ luôn dịu dàng và kiên nhẫn với hành trình lớn lên của mình.\\\"\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"\\\"Tôi sẽ ép mình phải hoàn hảo như mong đợi của người khác.\\\"\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:16:05', '2026-07-06 21:16:05'),
(4394, 740, 'reflection', '{\"question\": \"Hôm nay, bạn đã học được cách bao dung hơn với những khía cạnh chưa hoàn hảo của mình chưa?\"}', 5, '2026-07-06 21:16:05', '2026-07-06 21:16:05'),
(4395, 740, 'takeaway', '{\"items\": [\"Bản đồ cuộc đời không có điểm kết thúc cố định, hãy tận hưởng từng bước đi.\"]}', 6, '2026-07-06 21:16:06', '2026-07-06 21:16:06'),
(4396, 741, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Hỏi chấm & Khám phá\'! Cho phép bản thân có những khoảng lặng đáng yêu.\"}', 1, '2026-07-06 21:16:06', '2026-07-06 21:16:06'),
(4397, 741, 'scenario-choice', '{\"title\": \"Cuộc phiêu lưu: Đón nhận sự mông lung\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn thấy mông lung về giới tính của mình, lúc thấy giống nam lúc giống nữ. Bạn bè giục bạn: \'Chọn đại một nhãn đi xem nào\'.\", \"choices\": [{\"text\": \"Chọn bừa một nhãn LGBT+ để tỏ ra hợp thời đại.\", \"nextNode\": \"fail_submit\"}, {\"text\": \"Bảo với bạn bè: \'Tớ chưa biết, tớ vẫn đang khám phá bản thân\'.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Bạn thấy lo âu mất ngủ vì đọc quá nhiều tranh cãi về các định nghĩa giới tính trên mạng.\", \"choices\": [{\"text\": \"Tham gia cãi cọ để chứng minh quan điểm cá nhân trên diễn đàn mạng.\", \"nextNode\": \"fail_guilt\"}, {\"text\": \"Tắt mạng xã hội, đi chơi thể thao và trò chuyện trực tiếp với người bạn tin cậy.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành thử thách! Bạn đã biết cách bảo vệ sức khỏe tinh thần và kiên nhẫn với hành trình lớn lên của mình.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_submit\": {\"text\": \"❌ Thất bại! Vội vã gắn nhãn chỉ làm bạn thấy gò bó và áp lực sau này.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_guilt\": {\"text\": \"❌ Thất bại! Cuộc chiến bàn phím chỉ làm bạn cạn kiệt năng lượng tinh thần.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-06 21:16:06', '2026-07-06 21:16:06'),
(4398, 741, 'sorting', '{\"instruction\": \"Hãy phân loại các thái độ sau:\", \"leftBox\": {\"title\": \"Green Flag (Tích cực)\"}, \"rightBox\": {\"title\": \"Red Flag (Tiêu cực)\"}, \"items\": [{\"text\": \"Viết nhật ký ghi lại cảm xúc thật mỗi ngày\", \"correctBox\": \"left\"}, {\"text\": \"Ép bản thân phải có câu trả lời ngay lập tức\", \"correctBox\": \"right\"}, {\"text\": \"Cho phép bản thân thay đổi sở thích theo thời gian\", \"correctBox\": \"left\"}, {\"text\": \"So sánh mình với các KOLs tự tin trên mạng\", \"correctBox\": \"right\"}]}', 3, '2026-07-06 21:16:06', '2026-07-06 21:16:06'),
(4399, 741, 'matching', '{\"instruction\": \"Ghép cặp các thuật ngữ về quá trình phát hiện bản thân sau:\", \"pairs\": [{\"left\": \"Questioning\", \"right\": \"Trạng thái tự vấn, đặt câu hỏi về bản thân\"}, {\"left\": \"Fluidity\", \"right\": \"Tính linh hoạt của cảm xúc theo thời gian\"}, {\"left\": \"Detox mạng xã hội\", \"right\": \"Hạn chế lướt tin tức độc hại để bảo vệ tinh thần\"}, {\"left\": \"Đồng hành tâm lý\", \"right\": \"Trò chuyện cùng chuyên gia hoặc người tin cậy\"}]}', 4, '2026-07-06 21:16:06', '2026-07-06 21:16:06'),
(4400, 741, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về tự vấn giới tính:\", \"sentence\": \"Giai đoạn [blank1] là cơ hội tuyệt vời để bạn tìm tòi và thấu hiểu chính mình. Bạn không cần phải vội vã chọn một [blank2] cố định vào năm 15 tuổi. Hãy kiên nhẫn và luôn [blank3] với hành trình trưởng thành của bản thân.\", \"blanks\": {\"blank1\": {\"correct\": \"tự vấn\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"nhãn dán\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"dịu dàng\", \"placeholder\": \"...\"}}, \"words\": [\"tự vấn\", \"nhãn dán\", \"dịu dàng\", \"lo âu\", \"quyết định\", \"khắt khe\"]}', 5, '2026-07-06 21:16:06', '2026-07-06 21:16:06'),
(4401, 741, 'interaction', '{\"question\": \"Khi cảm xúc của bạn thay đổi so với năm ngoái, bạn nên nghĩ thế nào?\", \"choices\": [{\"text\": \"Đây là tính linh hoạt tự nhiên, cho thấy tôi đang lớn lên và có nhiều trải nghiệm.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tôi là một kẻ giả tạo, nói dối bạn bè và không có lập trường.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-06 21:16:06', '2026-07-06 21:16:06'),
(4402, 742, 'hook', '{\"title\": \"Các chữ cái L-G-B-T-Q-A+ thực chất là viết tắt của những từ nào?\"}', 1, '2026-07-06 21:16:06', '2026-07-06 21:16:06'),
(4403, 742, 'explanation', '{\"bullets\": [\"**L (Lesbian):** Đồng tính nữ.\", \"**G (Gay):** Đồng tính nam.\", \"**B (Bisexual):** Song tính.\", \"**T (Transgender):** Chuyển giới.\", \"**Q (Queer/Questioning):** Có bản dạng/xu hướng khác biệt hoặc đang tự vấn.\", \"**A (Asexual/Ally):** Vô tính hoặc Đồng minh.\", \"Dấu **+** đại diện cho rất nhiều bản dạng và xu hướng đa dạng khác vẫn đang được tiếp tục gọi tên.\"]}', 2, '2026-07-06 21:16:06', '2026-07-06 21:16:06'),
(4404, 742, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Một nhóm bạn học sinh thấy lá cờ lục sắc treo ở quán cà phê gần trường. Một bạn hỏi: *\\\"Sao cờ có nhiều màu thế nhỉ?\\\"*. Bạn khác trả lời: *\\\"Mỗi màu sắc tượng trưng cho một nhóm người trong cộng đồng, thể hiện sự hòa hợp và đa dạng của nhân loại đó.\\\"*\"}', 3, '2026-07-06 21:16:06', '2026-07-06 21:16:06'),
(4405, 742, 'interaction', '{\"question\": \"Dấu cộng (+) trong cụm từ LGBTQ+ có ý nghĩa gì?\", \"choices\": [{\"text\": \"Chỉ là ký tự viết cho đẹp mắt, không có ý nghĩa gì.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Đại diện cho sự cởi mở, sẵn sàng chào đón các bản dạng và xu hướng đa dạng khác.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:16:07', '2026-07-06 21:16:07'),
(4406, 742, 'reflection', '{\"question\": \"Màu sắc nào trên lá cờ cầu vồng làm bạn cảm thấy ấn tượng nhất?\"}', 5, '2026-07-06 21:16:07', '2026-07-06 21:16:07'),
(4407, 742, 'takeaway', '{\"items\": [\"Cầu vồng đẹp là vì có nhiều dải màu cùng tỏa sáng bên nhau.\"]}', 6, '2026-07-06 21:16:07', '2026-07-06 21:16:07'),
(4408, 743, 'hook', '{\"title\": \"Một lời nói đùa bỡn cợt ở hành lang lớp học có thể để lại vết sẹo tâm lý sâu sắc thế nào?\"}', 1, '2026-07-06 21:16:07', '2026-07-06 21:16:07'),
(4409, 743, 'explanation', '{\"bullets\": [\"**Kỳ thị ngầm:** Là những thái độ, lời nói trêu chọc gián tiếp nhắm vào người LGBTQ+ (ví dụ: dùng từ \\\"pê-đê\\\", \\\"bóng\\\" để làm tính từ chế giễu).\", \"**Bạo lực học đường:** Không chỉ là đánh nhau, mà còn là việc cô lập, tung tin đồn, chế giễu ngoại hình hay giới tính của bạn học.\", \"Nhận diện được những hành vi này là bước đầu để xây dựng môi trường học đường văn minh.\"]}', 2, '2026-07-06 21:16:07', '2026-07-06 21:16:07'),
(4410, 743, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Trong giờ ra chơi, một nhóm bạn nam chọc ghẹo bạn Nam: *\\\"Mày đi đứng nhẹ nhàng thế, hay là bị bê đê rồi?\\\"*. Nam cúi mặt đi nhanh ra chỗ khác, lồng ngực thắt lại vì xấu hổ và tức giận mặc dù cậu chỉ đang đi đứng bình thường.\"}', 3, '2026-07-06 21:16:07', '2026-07-06 21:16:07'),
(4411, 743, 'interaction', '{\"question\": \"Nếu là bạn học cùng lớp chứng kiến cảnh đó, bạn sẽ làm gì?\", \"choices\": [{\"text\": \"Hùa theo cười đùa để nhóm bạn nam thấy mình cũng \'cool\'.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Lên tiếng ngăn cản: \'Đùa thế không vui đâu các bạn ơi\' và rủ Nam ra chỗ khác chơi.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:16:07', '2026-07-06 21:16:07'),
(4412, 743, 'reflection', '{\"question\": \"Bạn có từng vô tình dùng những từ ngữ nhạy cảm về giới để trêu chọc ai đó chưa?\"}', 5, '2026-07-06 21:16:07', '2026-07-06 21:16:07'),
(4413, 743, 'takeaway', '{\"items\": [\"Tôn trọng sự khác biệt của bạn học là thước đo của sự văn minh học đường.\"]}', 6, '2026-07-06 21:16:07', '2026-07-06 21:16:07'),
(4414, 744, 'hook', '{\"title\": \"Nỗi sợ lớn nhất của một bạn trẻ LGBTQ+ thường không phải là xã hội, mà là cảm giác bị gia đình chối bỏ.\"}', 1, '2026-07-06 21:16:07', '2026-07-06 21:16:07'),
(4415, 744, 'explanation', '{\"bullets\": [\"Nhiều bạn trẻ LGBTQ+ phải sống trong sự lo âu thường trực rằng nếu công khai con người thật, bố mẹ sẽ thất vọng, mắng chửi hoặc đuổi ra khỏi nhà.\", \"Áp lực này dẫn đến stress kéo dài, trầm cảm và suy giảm kết quả học tập.\", \"Việc tìm kiếm một không gian an toàn để chia sẻ cảm xúc là cực kỳ quan trọng đối với sức khỏe tinh thần.\"]}', 2, '2026-07-06 21:16:07', '2026-07-06 21:16:07'),
(4416, 744, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"An (14 tuổi) nghe bố mẹ xem tivi và bình luận gay gắt về những người chuyển giới trên bản tin. An cúi đầu ăn cơm trong im lặng, nước mắt chực trào vì An biết mình cũng là người chuyển giới nam. Cậu cảm thấy ngôi nhà vốn an toàn giờ trở nên thật xa lạ.\"}', 3, '2026-07-06 21:16:08', '2026-07-06 21:16:08'),
(4417, 744, 'interaction', '{\"question\": \"Theo bạn, An nên làm gì lúc này để giải tỏa áp lực tinh thần một cách an toàn?\", \"choices\": [{\"text\": \"Công khai ngay lập tức để thách thức bố mẹ.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Tìm đến chuyên gia tâm lý học đường hoặc các đường dây nóng hỗ trợ trẻ em để được tư vấn tâm lý trước.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:16:08', '2026-07-06 21:16:08'),
(4418, 744, 'reflection', '{\"question\": \"Bạn sẽ làm gì để ngôi nhà của mình luôn là nơi an toàn cho tất cả mọi người?\"}', 5, '2026-07-06 21:16:08', '2026-07-06 21:16:08'),
(4419, 744, 'takeaway', '{\"items\": [\"Cảm xúc của bạn luôn xứng đáng có một không gian an toàn để bày tỏ.\"]}', 6, '2026-07-06 21:16:08', '2026-07-06 21:16:08'),
(4420, 745, 'hook', '{\"title\": \"Khi một câu nói đùa làm bạn uncomfy, đó không phải là do bạn \'quá nhạy cảm\', đó là do trò đùa đó kém duyên!\"}', 1, '2026-07-06 21:16:08', '2026-07-06 21:16:08'),
(4421, 745, 'explanation', '{\"bullets\": [\"Ranh giới giữa đùa vui và quấy rối tinh thần rất mong manh.\", \"Nếu trò đùa dựa trên xu hướng tính dục, ngoại hình hay giới tính của một người để gây cười, đó là trò đùa kỳ thị.\", \"Bạn hoàn toàn có quyền phản kháng và bảo vệ ranh giới cá nhân của mình.\"]}', 2, '2026-07-06 21:16:08', '2026-07-06 21:16:08'),
(4422, 745, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Tại buổi tiệc sinh nhật lớp, một bạn nam giả giọng điệu đà, ẻo lả để bắt chước một ca sĩ nổi tiếng đồng tính, khiến cả lớp cười ồ lên. Vy thấy trò đùa này vô duyên và làm tổn thương các bạn LGBT+ trong lớp, nhưng mọi người lại bảo *\\\"Vui thôi mà, nhạy cảm quá thế\\\"*.\"}', 3, '2026-07-06 21:16:08', '2026-07-06 21:16:08'),
(4423, 745, 'interaction', '{\"question\": \"Vy nên phản ứng thế nào để thể hiện quan điểm một cách lịch sự nhưng cứng rắn?\", \"choices\": [{\"text\": \"Hùa theo cười gượng gạo để không làm mất bầu không khí vui vẻ.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Không cười, nhẹ nhàng nói: \'Tớ thấy trò đùa này hơi kém duyên và không hài hước chút nào\'.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:16:08', '2026-07-06 21:16:08'),
(4424, 745, 'reflection', '{\"question\": \"Bạn đã bao giờ dũng cảm lên tiếng khi thấy ai đó bị làm trò đùa cho đám đông chưa?\"}', 5, '2026-07-06 21:16:08', '2026-07-06 21:16:08'),
(4425, 745, 'takeaway', '{\"items\": [\"Tôn trọng người khác quan trọng hơn việc tìm kiếm tiếng cười dễ dãi.\"]}', 6, '2026-07-06 21:16:08', '2026-07-06 21:16:08'),
(4426, 746, 'hook', '{\"title\": \"Khi bão giông ập đến, bạn có biết bên cạnh mình luôn có những chiếc phao cứu sinh an toàn?\"}', 1, '2026-07-06 21:16:08', '2026-07-06 21:16:08'),
(4427, 746, 'explanation', '{\"bullets\": [\"Đừng bao giờ chịu đựng sự bắt nạt hay trầm cảm một mình.\", \"Bạn có thể tìm kiếm sự giúp đỡ từ: Chuyên gia tâm lý học đường, thầy cô giáo tin cậy, các tổ chức bảo vệ trẻ em (như Tổng đài Quốc gia 111), hoặc các tổ chức phi chính phủ uy tín về LGBTQ+ tại Việt Nam.\", \"Tìm kiếm sự hỗ trợ là biểu hiện của sự dũng cảm và chủ động bảo vệ bản thân.\"]}', 2, '2026-07-06 21:16:09', '2026-07-06 21:16:09'),
(4428, 746, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Hải thường xuyên bị nhắn tin đe dọa, cô lập trên Facebook chỉ vì công khai xu hướng song tính của mình. Hải hoảng sợ, không dám đi học và có ý định tự hại. Hải giam mình trong phòng và khóc suốt nhiều ngày.\"}', 3, '2026-07-06 21:16:09', '2026-07-06 21:16:09'),
(4429, 746, 'interaction', '{\"question\": \"Hành động nào giúp Hải thoát khỏi nguy hiểm khẩn cấp này?\", \"choices\": [{\"text\": \"Chụp lại các tin nhắn đe dọa làm bằng chứng, chia sẻ ngay với thầy cô tin cậy hoặc gọi tổng đài 111 để được can thiệp bảo vệ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Im lặng chịu đựng và hy vọng kẻ bắt nạt sẽ tự chán rồi bỏ qua.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-06 21:16:09', '2026-07-06 21:16:09'),
(4430, 746, 'reflection', '{\"question\": \"Bạn có biết số điện thoại của ít nhất một người lớn đáng tin cậy mà bạn có thể gọi bất cứ lúc nào gặp nguy hiểm không?\"}', 5, '2026-07-06 21:16:09', '2026-07-06 21:16:09'),
(4431, 746, 'takeaway', '{\"items\": [\"Yêu cầu sự trợ giúp không phải là yếu đuối, đó là sức mạnh để tự bảo vệ.\"]}', 6, '2026-07-06 21:16:09', '2026-07-06 21:16:09'),
(4432, 747, 'hook', '{\"title\": \"Trường học đối với bạn là một sân chơi đầy tiếng cười, hay là nơi bạn phải gồng mình đề phòng mỗi ngày?\"}', 1, '2026-07-06 21:16:09', '2026-07-06 21:16:09'),
(4433, 747, 'explanation', '{\"bullets\": [\"Một trường học an toàn là nơi mọi học sinh đều có quyền được học tập mà không lo sợ bị phân biệt đối xử hay bắt nạt.\", \"Tự đánh giá mức độ an toàn của môi trường xung quanh giúp bạn chủ động đưa ra các quyết định bảo vệ bản thân và bạn bè.\", \"Sự thay đổi bắt đầu từ những hành động nhỏ của chính học sinh chúng ta.\"]}', 2, '2026-07-06 21:16:09', '2026-07-06 21:16:09'),
(4434, 747, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Nhóm bạn thân của An quyết định ký vào bản cam kết \'Lớp học không bạo lực giới\', tự hứa sẽ không sử dụng các từ ngữ miệt thị giới tính trong lớp học và sẵn sàng bảo vệ bạn học bị cô lập.\"}', 3, '2026-07-06 21:16:09', '2026-07-06 21:16:09'),
(4435, 747, 'interaction', '{\"question\": \"Bạn nghĩ sao về sáng kiến của nhóm bạn của An?\", \"choices\": [{\"text\": \"Làm màu, không có tác dụng thực tế.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Rất ý nghĩa! Nó tạo ra một làn sóng cam kết văn minh và lan tỏa năng lượng tích cực đến cả lớp.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:16:09', '2026-07-06 21:16:09'),
(4436, 747, 'reflection', '{\"question\": \"Bạn có thể làm gì hôm nay để giúp một bạn học đang bị cô lập cảm thấy ấm áp hơn?\"}', 5, '2026-07-06 21:16:09', '2026-07-06 21:16:09'),
(4437, 747, 'takeaway', '{\"items\": [\"Ngôi trường hạnh phúc được xây dựng từ những hành động tử tế nhỏ nhất của mỗi chúng ta.\"]}', 6, '2026-07-06 21:16:09', '2026-07-06 21:16:09'),
(4438, 748, 'hook', '{\"title\": \"Bất kể bạn đang ở đâu trên thế giới, luôn có một cộng đồng sẵn sàng ôm bạn vào lòng vì chính con người thật của bạn.\"}', 1, '2026-07-06 21:16:10', '2026-07-06 21:16:10'),
(4439, 748, 'explanation', '{\"bullets\": [\"Trên thế giới và tại Việt Nam, có hàng triệu người trẻ và người trưởng thành thuộc cộng đồng LGBTQ+ đang sống hạnh phúc, cống hiến và yêu thương.\", \"Sự khác biệt của bạn là một phần của sự đa dạng tuyệt vời của tự nhiên.\", \"Hãy vững tin rằng bạn luôn có quyền được sống hạnh phúc và tự hào về bản thân.\"]}', 2, '2026-07-06 21:16:10', '2026-07-06 21:16:10'),
(4440, 748, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Khang tham gia một buổi workshop giao lưu thanh thiếu niên đa dạng giới do một tổ chức cộng đồng thực hiện. Nhìn thấy các anh chị lớn thành công, tự tin chia sẻ câu chuyện của mình, Khang thấy tràn đầy hy vọng vào tương lai tươi sáng của chính mình.\"}', 3, '2026-07-06 21:16:10', '2026-07-06 21:16:10'),
(4441, 748, 'interaction', '{\"question\": \"Hãy chọn thông điệp tiếp thêm sức mạnh cho bạn ngày hôm nay:\", \"choices\": [{\"text\": \"\\\"Tôi tự hào vì tôi là chính tôi, độc bản và xứng đáng được yêu thương.\\\"\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"\\\"Tôi sẽ cố gắng thay đổi để vừa lòng tất cả mọi người.\\\"\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:16:10', '2026-07-06 21:16:10'),
(4442, 748, 'reflection', '{\"question\": \"Điều gì tiếp thêm cho bạn nhiều động lực nhất để tự tin sống thật với chính mình lúc này?\"}', 5, '2026-07-06 21:16:10', '2026-07-06 21:16:10'),
(4443, 748, 'takeaway', '{\"items\": [\"Bạn là một mảnh ghép quý giá của thế giới đa sắc này.\"]}', 6, '2026-07-06 21:16:10', '2026-07-06 21:16:10'),
(4444, 749, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Cộng đồng Cầu vồng\'! Cùng nhau xây dựng lá chắn học đường an toàn.\"}', 1, '2026-07-06 21:16:10', '2026-07-06 21:16:10'),
(4445, 749, 'scenario-choice', '{\"title\": \"Cuộc phiêu lưu: Lên tiếng chống bắt nạt\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Ở hành lang lớp học, bạn thấy một nhóm bạn đang chế giễu ngoại hình và giới tính của một bạn học. Bạn ấy đang khóc.\", \"choices\": [{\"text\": \"Đi qua chỗ khác để tránh rắc rối.\", \"nextNode\": \"fail_submit\"}, {\"text\": \"Bước lại gần hỏi thăm bạn đang khóc và rủ bạn ấy lên văn phòng đoàn.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Nhóm bắt nạt đe dọa bạn: \'Lo chuyện bao đồng là tụi tao xử luôn mày đó nha!\'.\", \"choices\": [{\"text\": \"Hoảng sợ và hứa sẽ không can thiệp nữa.\", \"nextNode\": \"fail_guilt\"}, {\"text\": \"Báo cáo sự việc kèm bằng chứng tin nhắn cho thầy cô chủ nhiệm hoặc tổng đài 111.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành thử thách! Bạn đã dũng cảm bảo vệ bạn học và biết cách tìm kiếm sự hỗ trợ chuyên nghiệp để giải quyết bạo lực.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_submit\": {\"text\": \"❌ Thất bại! Sự im lặng vô tình tiếp tay cho bạo lực học đường tiếp tục diễn ra.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_guilt\": {\"text\": \"❌ Thất bại! Nhượng bộ trước đe dọa sẽ khiến kẻ bắt nạt lấn tới.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-06 21:16:10', '2026-07-06 21:16:10'),
(4446, 749, 'sorting', '{\"instruction\": \"Hãy phân loại các hành vi học đường sau:\", \"leftBox\": {\"title\": \"Văn minh (Inclusion)\"}, \"rightBox\": {\"title\": \"Độc hại (Exclusion)\"}, \"items\": [{\"text\": \"Lắng nghe và chia sẻ chân thành với bạn học LGBTQ+\", \"correctBox\": \"left\"}, {\"text\": \"Dùng từ ngữ giới tính để làm tính từ chế giễu\", \"correctBox\": \"right\"}, {\"text\": \"Lập quy ước lớp học không miệt thị ranh giới cơ thể\", \"correctBox\": \"left\"}, {\"text\": \"Cô lập bạn học vì họ có phong cách ăn mặc khác biệt\", \"correctBox\": \"right\"}]}', 3, '2026-07-06 21:16:10', '2026-07-06 21:16:10'),
(4447, 749, 'matching', '{\"instruction\": \"Ghép cặp các định nghĩa về bạo lực học đường sau:\", \"pairs\": [{\"left\": \"Kỳ thị ngầm\", \"right\": \"Những lời đùa cợt ẩn ý làm tổn thương người khác\"}, {\"left\": \"Bạo lực học đường\", \"right\": \"Hành vi cô lập, đe dọa tinh thần bạn học\"}, {\"left\": \"Tổng đài 111\", \"right\": \"Phao cứu sinh khẩn cấp bảo vệ trẻ em Việt Nam\"}, {\"left\": \"Cộng đồng LGBTQ+\", \"right\": \"Bức tranh đa sắc màu của tình yêu và giới tính\"}]}', 4, '2026-07-06 21:16:10', '2026-07-06 21:16:10'),
(4448, 749, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về an toàn học đường:\", \"sentence\": \"Một ngôi trường an toàn là nơi không có sự [blank1] đối xử. Khi chứng kiến bạo lực học đường, việc [blank2] tiếng bảo vệ là vô cùng quan trọng. Hãy nhớ rằng bạn không bao giờ đơn độc, luôn có [blank3] và các nguồn lực hỗ trợ bên bạn.\", \"blanks\": {\"blank1\": {\"correct\": \"phân biệt\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"lên\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"cộng đồng\", \"placeholder\": \"...\"}}, \"words\": [\"phân biệt\", \"lên\", \"cộng đồng\", \"hòa nhập\", \"im\", \"gia đình\"]}', 5, '2026-07-06 21:16:10', '2026-07-06 21:16:10'),
(4449, 749, 'interaction', '{\"question\": \"Đâu là hành động đúng đắn nhất khi bạn nhận được tin nhắn đe dọa trực tuyến từ kẻ bắt nạt giới?\", \"choices\": [{\"text\": \"Chụp màn hình làm bằng chứng, chặn tài khoản đó và báo ngay cho người lớn đáng tin.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Nhắn tin cãi cọ tay đôi với họ hoặc tự ý hẹn gặp mặt để giải quyết.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-06 21:16:10', '2026-07-06 21:16:10'),
(4450, 750, 'hook', '{\"title\": \"Bạn không cần phải thuộc cộng đồng LGBTQ+ để trở thành người bảo vệ và yêu thương họ.\"}', 1, '2026-07-06 21:16:11', '2026-07-06 21:16:11'),
(4451, 750, 'explanation', '{\"bullets\": [\"**Đồng minh (Ally):** Là người dị tính, hợp giới tự nguyện lên tiếng ủng hộ, tôn trọng và bảo vệ quyền lợi của những người thuộc cộng đồng LGBTQ+.\", \"Làm đồng minh không khó, nó bắt đầu từ việc lắng nghe chân thành và từ chối tham gia vào các hành vi trêu chọc kỳ thị.\", \"Sự hỗ trợ từ những người đồng minh giúp thế giới của người trẻ LGBTQ+ bớt đi sự cô độc.\"]}', 2, '2026-07-06 21:16:11', '2026-07-06 21:16:11'),
(4452, 750, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Tuấn (15 tuổi, thẳng) thấy các bạn nam trong lớp cười cợt chế giễu một bạn nam khác vì bạn ấy thích vẽ tranh hoa lá. Tuấn bước lại gần, khoác vai bạn học bị trêu và rủ bạn ấy cùng thảo luận bài tập nhóm, khiến đám đông trêu chọc tự giải tán.\"}', 3, '2026-07-06 21:16:11', '2026-07-06 21:16:11'),
(4453, 750, 'interaction', '{\"question\": \"Hành động của Tuấn thể hiện điều gì?\", \"choices\": [{\"text\": \"Sự xen vào chuyện người khác không cần thiết.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Vai trò của một người đồng minh dũng cảm và tinh tế.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:16:11', '2026-07-06 21:16:11'),
(4454, 750, 'reflection', '{\"question\": \"Bạn đã bao giờ nhận được sự giúp đỡ từ một người bạn không cùng nhóm hay sở thích với mình chưa? Cảm giác lúc đó thế nào?\"}', 5, '2026-07-06 21:16:11', '2026-07-06 21:16:11'),
(4455, 750, 'takeaway', '{\"items\": [\"Đồng minh là người dùng sự thấu hiểu để xóa nhòa khoảng cách định kiến.\"]}', 6, '2026-07-06 21:16:11', '2026-07-06 21:16:11'),
(4456, 751, 'hook', '{\"title\": \"Những câu hỏi \'hỏi thăm\' tưởng như vô hại nhưng lại có thể khiến người khác nhói lòng là gì?\"}', 1, '2026-07-06 21:16:11', '2026-07-06 21:16:11'),
(4457, 751, 'explanation', '{\"bullets\": [\"**Tổn thương vô ý (Microaggressions):** Là những lời nhận xét, câu hỏi ngắn hàng ngày vô tình chứa đựng định kiến giới hoặc kỳ thị (ví dụ: *\\\"Nhìn em xinh thế này mà lại là chuyển giới á?\\\"*, hoặc *\\\"Trong hai đứa thì đứa nào là chồng, đứa nào là vợ?\\\"*).\", \"Dù người hỏi không có ý xấu, nhưng những câu hỏi này vô tình biến người nghe thành *\\\"kẻ khác biệt, bất thường\\\"*.\", \"Học cách giao tiếp tinh tế giúp bạn tránh được những lỗi vô ý gây tổn thương này.\"]}', 2, '2026-07-06 21:16:11', '2026-07-06 21:16:11'),
(4458, 751, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Tại bàn ăn lớp, một bạn hỏi Lâm (người song tính): *\\\"Cậu thích cả nam lẫn nữ thế thì chắc là dễ thay lòng đổi dạ lắm nhỉ?\\\"*. Lâm cười gượng gạo nhưng trong lòng thấy rất khó chịu vì bị quy chụp là không chung thủy chỉ vì xu hướng tính dục của mình.\"}', 3, '2026-07-06 21:16:11', '2026-07-06 21:16:11'),
(4459, 751, 'interaction', '{\"question\": \"Tại sao câu hỏi trên lại là một tổn thương vô ý (microaggression)?\", \"choices\": [{\"text\": \"Vì nó quy chụp xu hướng tính dục với nhân cách, tạo ra định kiến sai lệch.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Vì bạn Lâm quá nhạy cảm với câu đùa của bạn bè.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:16:11', '2026-07-06 21:16:11'),
(4460, 751, 'reflection', '{\"question\": \"Bạn có từng nghe hoặc nói câu nào vô tình làm người khác thấy uncomfy chưa?\"}', 5, '2026-07-06 21:16:11', '2026-07-06 21:16:11'),
(4461, 751, 'takeaway', '{\"items\": [\"Lời nói là mũi tên, hãy ngắm nghía sự tôn trọng trước khi bắn ra.\"]}', 6, '2026-07-06 21:16:11', '2026-07-06 21:16:11'),
(4462, 752, 'hook', '{\"title\": \"Tại sao việc gọi đúng tên mới, đúng giới tính mong muốn của một người lại có ý nghĩa sống còn với họ?\"}', 1, '2026-07-06 21:16:11', '2026-07-06 21:16:11'),
(4463, 752, 'explanation', '{\"bullets\": [\"Với nhiều người chuyển giới hoặc phi nhị nguyên, việc được gọi bằng cái tên phù hợp với bản dạng (Chosen name) thay vì tên cũ trên giấy khai sinh (Deadname) là một sự công nhận vô cùng lớn.\", \"Nó giúp họ giảm bớt cảm giác lo âu, bất an giới và cảm nhận được sự tôn trọng từ xung quanh.\", \"Giao tiếp văn minh là tôn trọng danh tính mà đối phương tự định hình cho chính họ.\"]}', 2, '2026-07-06 21:16:12', '2026-07-06 21:16:12'),
(4464, 752, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Minh (chuyển giới nam) đã đổi tên gọi ở lớp từ \'Mai\' sang \'Minh\'. Cô giáo và các bạn học trong lớp đều chủ động gọi cậu là Minh và xưng hô bằng từ \'cậu/bạn\', giúp Minh thấy mỗi ngày đến trường đều tràn ngập niềm vui và sự an tâm học tập.\"}', 3, '2026-07-06 21:16:12', '2026-07-06 21:16:12'),
(4465, 752, 'interaction', '{\"question\": \"Nếu một người bạn nhờ bạn gọi họ bằng một cái tên mới phù hợp với giới tính của họ, bạn sẽ làm gì?\", \"choices\": [{\"text\": \"Cố tình gọi bằng tên cũ vì quen miệng và thấy tên cũ hay hơn.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Vui vẻ đồng ý, tập gọi tên mới và nhắc nhở bản thân để không bị nhầm lẫn.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:16:12', '2026-07-06 21:16:12'),
(4466, 752, 'reflection', '{\"question\": \"Nếu ai đó liên tục gọi sai tên bạn bằng một cái tên bạn cực ghét, bạn sẽ cảm thấy thế nào?\"}', 5, '2026-07-06 21:16:12', '2026-07-06 21:16:12'),
(4467, 752, 'takeaway', '{\"items\": [\"Cái tên là tiếng gọi đầu tiên của danh tính, hãy gọi nhau bằng sự tôn trọng.\"]}', 6, '2026-07-06 21:16:12', '2026-07-06 21:16:12'),
(4468, 753, 'hook', '{\"title\": \"Bạn sẽ phản ứng thế nào khi một người bạn thân run rẩy nắm tay bạn và nói: \'Tớ nghĩ tớ là người đồng tính\'?\"}', 1, '2026-07-06 21:16:12', '2026-07-06 21:16:12'),
(4469, 753, 'explanation', '{\"bullets\": [\"**Come out (Công khai):** Là quá trình một người chia sẻ bản dạng giới hoặc xu hướng tính dục của mình với người khác.\", \"Đây là khoảnh khắc cực kỳ nhạy cảm và đòi hỏi sự dũng cảm vô cùng lớn từ người bạn đó.\", \"Phản ứng đầu tiên của bạn quyết định mức độ tin tưởng và sự an toàn của mối quan hệ giữa hai người.\"]}', 2, '2026-07-06 21:16:12', '2026-07-06 21:16:12'),
(4470, 753, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Hải hẹn Nam ra quán nước sau giờ học. Hải ngập ngừng mãi mới dám nói: *\\\"Nam ơi, thực ra tớ thích con trai\\\"*. Nam giật mình mất 3 giây, nhưng rồi cậu mỉm cười, vỗ vai Hải: *\\\"Cảm ơn cậu đã tin tưởng kể với tớ. Cậu vẫn là bạn thân của tớ, không có gì thay đổi cả!\\\"*. Hải thở phào nhẹ nhõm, mắt rơm rớm nước mắt vì hạnh phúc.\"}', 3, '2026-07-06 21:16:12', '2026-07-06 21:16:12'),
(4471, 753, 'interaction', '{\"question\": \"Phản ứng nào dưới đây là văn minh và ấm áp nhất khi bạn của bạn come out?\", \"choices\": [{\"text\": \"\\\"Đùa à? Trông cậu bình thường thế mà!\\\"\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"\\\"Cảm ơn cậu đã chia sẻ với tớ. Tớ rất trân trọng tình bạn của tụi mình.\\\"\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:16:12', '2026-07-06 21:16:12'),
(4472, 753, 'reflection', '{\"question\": \"Nếu bạn cần công khai một bí mật lớn về bản thân, bạn mong muốn nhận được phản ứng thế nào từ người nghe?\"}', 5, '2026-07-06 21:16:12', '2026-07-06 21:16:12'),
(4473, 753, 'takeaway', '{\"items\": [\"Come out là trao đi sự tin tưởng, hãy đón nhận nó bằng cả trái tim tôn trọng.\"]}', 6, '2026-07-06 21:16:12', '2026-07-06 21:16:12'),
(4474, 754, 'hook', '{\"title\": \"Ai cũng có lúc lỡ lời xưng hô sai hoặc hỏi câu ngớ ngẩn. Làm sao để xin lỗi một cách tinh tế mà không làm mọi chuyện rối thêm?\"}', 1, '2026-07-06 21:16:13', '2026-07-06 21:16:13'),
(4475, 754, 'explanation', '{\"bullets\": [\"Khi bạn lỡ gọi sai tên cũ (deadname) hoặc dùng sai đại từ xưng hô của bạn học chuyển giới, việc cuống cuồng giải thích hay phân bua dài dòng đôi khi làm đối phương thấy khó xử hơn.\", \"Kỹ năng sửa sai: Xin lỗi nhanh gọn, sửa lại ngay từ đúng, và tiếp tục câu chuyện mà không làm quá vấn đề.\", \"Quan trọng nhất là bạn chủ động rút kinh nghiệm cho những lần giao tiếp sau.\"]}', 2, '2026-07-06 21:16:13', '2026-07-06 21:16:13'),
(4476, 754, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Trong buổi thảo luận nhóm, Lan lỡ lời gọi Lâm (đã chuyển giới nam) là *\\\"bạn ấy\\\"* (bằng từ chỉ nữ). Phát hiện ra mình sai, Lan lập tức nói: *\\\"À xin lỗi cậu, Lâm, cậu có thể trình bày tiếp phần này...\\\"*. Lâm mỉm cười gật đầu và tiếp tục nói mà không thấy bị sượng sùng.\"}', 3, '2026-07-06 21:16:13', '2026-07-06 21:16:13'),
(4477, 754, 'interaction', '{\"question\": \"Cách xin lỗi và sửa sai tốt nhất khi lỡ xưng hô sai là gì?\", \"choices\": [{\"text\": \"\\\"Ôi tớ xin lỗi nhiều lắm, tớ ngốc quá, tại trước đây cậu là con gái nên tớ quen...\\\"\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"\\\"Xin lỗi cậu, [từ xưng hô đúng]...\\\" rồi tiếp tục câu chuyện một cách bình thường.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:16:13', '2026-07-06 21:16:13'),
(4478, 754, 'reflection', '{\"question\": \"Bạn cảm thấy thế nào khi một người chủ động sửa sai ngay lập tức sau khi lỡ làm bạn buồn?\"}', 5, '2026-07-06 21:16:13', '2026-07-06 21:16:13'),
(4479, 754, 'takeaway', '{\"items\": [\"Sửa sai nhanh gọn và tôn trọng là biểu hiện của một người giao tiếp thông minh.\"]}', 6, '2026-07-06 21:16:13', '2026-07-06 21:16:13'),
(4480, 755, 'hook', '{\"title\": \"Bạn có đang góp phần xây dựng một \'vùng an toàn\' để bạn bè xung quanh thoải mái là chính họ?\"}', 1, '2026-07-06 21:16:13', '2026-07-06 21:16:13'),
(4481, 755, 'explanation', '{\"bullets\": [\"Một không gian an toàn không tự nhiên sinh ra, nó được kiến tạo bởi thái độ cởi mở của mỗi cá nhân trong đó.\", \"Khi bạn thể hiện sự không phán xét, tôn trọng sự khác biệt, bạn đang vô tình tạo ra một điểm tựa tinh thần vững chắc cho những người xung quanh.\", \"Sự tử tế của bạn có thể cứu rỗi tâm hồn của một ai đó đang chới với.\"]}', 2, '2026-07-06 21:16:13', '2026-07-06 21:16:13'),
(4482, 755, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Nhóm học thêm của Ly luôn nổi tiếng là năng động và cởi mở. Các bạn tự đặt ra quy định: không bình luận khiếm nhã về ngoại hình, phong cách hay giới tính của bất kỳ ai trong lớp. Mọi học sinh mới vào nhóm đều cảm thấy cực kỳ chill và tự tin học tập.\"}', 3, '2026-07-06 21:16:13', '2026-07-06 21:16:13'),
(4483, 755, 'interaction', '{\"question\": \"Hành động nào giúp củng cố vùng an toàn trong nhóm của bạn?\", \"choices\": [{\"text\": \"Im lặng khi thấy bạn khác bị trêu chọc để giữ hòa khí nhóm.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Chủ động bắt chuyện, tôn trọng ý kiến và cởi mở với những nét tính cách khác biệt của các thành viên.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:16:13', '2026-07-06 21:16:13'),
(4484, 755, 'reflection', '{\"question\": \"Trong nhóm bạn của bạn, ai là người khiến bạn cảm thấy thoải mái và an toàn nhất khi ở bên?\"}', 5, '2026-07-06 21:16:13', '2026-07-06 21:16:13'),
(4485, 755, 'takeaway', '{\"items\": [\"Tử tế là ngôn ngữ duy nhất mà người mù có thể thấy và người điếc có thể nghe.\"]}', 6, '2026-07-06 21:16:13', '2026-07-06 21:16:13'),
(4486, 756, 'hook', '{\"title\": \"Cuối cùng, sự tôn trọng chính là chiếc chìa khóa vạn năng mở ra cánh cửa của sự thấu hiểu và hòa hợp.\"}', 1, '2026-07-06 21:16:13', '2026-07-06 21:16:13'),
(4487, 756, 'explanation', '{\"bullets\": [\"Khóa học của chúng ta đã đi qua nhiều khái niệm từ bản dạng, giới, xu hướng tính dục đến đồng minh.\", \"Tất cả những kiến thức này đều quy về một giá trị cốt lõi duy nhất: Tôn trọng sự độc bản của mỗi con người.\", \"Hãy mang theo hành trang thấu hiểu này để bước vào đời và thắp sáng thế giới xung quanh bằng sự tử tế của bạn.\"]}', 2, '2026-07-06 21:16:13', '2026-07-06 21:16:13'),
(4488, 756, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Buổi tổng kết khóa học trực tuyến. Hàng ngàn bạn học sinh từ khắp mọi miền đất nước cùng gửi lên bảng tin ảo những lời chúc, những sticker trái tim cầu vồng và những thông điệp tự hào về hành trình thấu hiểu bản thân của mình.\"}', 3, '2026-07-06 21:16:14', '2026-07-06 21:16:14'),
(4489, 756, 'interaction', '{\"question\": \"Hãy chọn cam kết cuối cùng của bạn khi hoàn thành khóa học này:\", \"choices\": [{\"text\": \"\\\"Tôi cam kết luôn lắng nghe, tôn trọng và đồng hành cùng sự đa dạng xung quanh mình.\\\"\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"\\\"Tôi học xong chỉ để biết thế thôi, không thay đổi thái độ gì cả.\\\"\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-06 21:16:14', '2026-07-06 21:16:14'),
(4490, 756, 'reflection', '{\"question\": \"Một điều tâm đắc nhất mà bạn sẽ mang theo sau khi kết thúc khóa học này là gì?\"}', 5, '2026-07-06 21:16:14', '2026-07-06 21:16:14'),
(4491, 756, 'takeaway', '{\"items\": [\"Tôn trọng người khác là cách tốt nhất để tôn trọng chính con người mình.\"]}', 6, '2026-07-06 21:16:14', '2026-07-06 21:16:14'),
(4492, 757, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Giao tiếp văn minh\'! Trở thành đồng minh tinh tế trong mọi câu nói.\"}', 1, '2026-07-06 21:16:14', '2026-07-06 21:16:14'),
(4493, 757, 'scenario-choice', '{\"title\": \"Cuộc phiêu lưu: Đồng minh tinh tế\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Một người bạn thân come out với bạn rằng bạn ấy thích người cùng giới.\", \"choices\": [{\"text\": \"Hỏi dồn dập: \'Từ bao giờ thế? Bố mẹ biết chưa? Sao trông thẳng đuột thế?\'.\", \"nextNode\": \"fail_submit\"}, {\"text\": \"Ôm bạn ấy và nói: \'Cảm ơn cậu đã tin tưởng tớ. Cậu vẫn luôn là bạn tốt của tớ!\'.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Trong cuộc trò chuyện nhóm sau đó, bạn lỡ miệng dùng đại từ xưng hô cũ để gọi bạn ấy trước mặt mọi người. Bạn ấy thoáng buồn.\", \"choices\": [{\"text\": \"Giải thích huyên thuyên: \'Ui tớ quen miệng quá, tại trước đây gọi thế suốt...\'.\", \"nextNode\": \"fail_guilt\"}, {\"text\": \"Nói nhanh: \'À xin lỗi cậu, [từ xưng hô mới]...\' rồi tiếp tục câu chuyện.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành thử thách! Bạn đã ứng xử vô cùng tinh tế, thể hiện sự đồng cảm sâu sắc và tôn trọng danh tính của bạn mình.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_submit\": {\"text\": \"❌ Thất bại! Sự tò mò dồn dập làm bạn ấy thấy ngột ngạt và cảm giác bị thẩm vấn.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_guilt\": {\"text\": \"❌ Thất bại! Giải thích dài dòng làm mọi người chú ý và bạn ấy thêm khó xử.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-06 21:16:14', '2026-07-06 21:16:14'),
(4494, 757, 'sorting', '{\"instruction\": \"Hãy phân loại các câu nói sau:\", \"leftBox\": {\"title\": \"Đồng minh xịn (Ally)\"}, \"rightBox\": {\"title\": \"Tổn thương vô ý (Microaggression)\"}, \"items\": [{\"text\": \"Cậu muốn tớ xưng hô thế nào để cậu thấy thoải mái nhất?\", \"correctBox\": \"left\"}, {\"text\": \"Nhìn cậu men thế này mà lại thích con trai á?\", \"correctBox\": \"right\"}, {\"text\": \"Tớ luôn tôn trọng và ủng hộ sự lựa chọn của cậu\", \"correctBox\": \"left\"}, {\"text\": \"Trong hai đứa cậu thì ai làm chồng, ai làm vợ thế?\", \"correctBox\": \"right\"}]}', 3, '2026-07-06 21:16:14', '2026-07-06 21:16:14'),
(4495, 757, 'matching', '{\"instruction\": \"Ghép cặp các khái niệm giao tiếp tôn trọng sau:\", \"pairs\": [{\"left\": \"Đồng minh (Ally)\", \"right\": \"Người thẳng/hợp giới lên tiếng bảo vệ cộng đồng LGBTQ+\"}, {\"left\": \"Tổn thương vô ý\", \"right\": \"Những câu hỏi tò mò mang tính định kiến ngầm\"}, {\"left\": \"Chosen name\", \"right\": \"Cái tên mới phù hợp với bản dạng giới của một người\"}, {\"left\": \"Sự tử tế\", \"right\": \"Cơ sở cốt lõi để xây dựng mọi mối quan hệ giao tiếp\"}]}', 4, '2026-07-06 21:16:14', '2026-07-06 21:16:14'),
(4496, 757, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về đồng minh tinh tế:\", \"sentence\": \"Trở thành đồng minh tinh tế bắt đầu từ việc [blank1] chân thành. Hãy luôn tôn trọng cách xưng hô và [blank2] mới của bạn bè. Sự tử tế của bạn trong giao tiếp chính là chiếc [blank3] vạn năng mở ra sự thấu hiểu.\", \"blanks\": {\"blank1\": {\"correct\": \"lắng nghe\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"tên gọi\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"chìa khóa\", \"placeholder\": \"...\"}}, \"words\": [\"lắng nghe\", \"tên gọi\", \"chìa khóa\", \"phán xét\", \"quá khứ\", \"ổ khóa\"]}', 5, '2026-07-06 21:16:14', '2026-07-06 21:16:14'),
(4497, 757, 'interaction', '{\"question\": \"Khi bạn vô tình nghe thấy ai đó sử dụng những từ ngữ xúc phạm giới tính làm trò đùa, phản ứng văn minh nhất của bạn là gì?\", \"choices\": [{\"text\": \"Không cười hùa theo, nhẹ nhàng góp ý: \'Tớ thấy cách dùng từ này không được tôn trọng lắm đâu\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Hùa theo cười đùa để giữ không khí vui vẻ cho đám đông.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-06 21:16:14', '2026-07-06 21:16:14'),
(4834, 814, 'hook', '{\"title\": \"Bạn có bao giờ bỗng dưng thấy lạnh gáy hay nổi da gà khi đứng cạnh một ai đó chưa?\"}', 1, '2026-07-06 21:48:46', '2026-07-06 21:48:46'),
(4835, 814, 'explanation', '{\"bullets\": [\"Cơ thể của chúng ta cực kỳ thông minh! Nó có một chiếc ra-đa cảnh báo nguy hiểm tự động.\", \"Khi gặp tình huống bất ổn, não bộ sẽ gửi tín hiệu qua các phản ứng vật lý: tim đập nhanh, đổ mồ hôi tay, nghẹn ở cổ hoặc cồn cào ruột gan.\", \"Đó không phải là suy nghĩ vớ vẩn, đó là cơ thể đang nói với bạn: \\\"Có gì đó không ổn ở đây!\\\"\"]}', 2, '2026-07-06 21:48:46', '2026-07-06 21:48:46'),
(4836, 814, 'scenario', '{\"title\": \"Tình huống bất ổn\", \"body\": \"Vy đang đứng đợi thang máy ở chung cư thì một chú hàng xóm bước vào. Chú nhìn Vy chằm chằm và đứng sát lại gần. Vy bỗng thấy tim mình đập thình thịch, da gà nổi lên khắp cánh tay dù trời không hề lạnh. Vy tự hỏi liệu mình có đang quá nhạy cảm và bất lịch sự nếu bước ra ngoài hay không.\"}', 3, '2026-07-06 21:48:46', '2026-07-06 21:48:46'),
(4837, 814, 'interaction', '{\"question\": \"Hãy chọn phản ứng phù hợp nhất để bảo vệ bản thân khi có linh cảm bất an:\", \"choices\": [{\"text\": \"Cố nhịn đứng im trong thang máy vì sợ chú hàng xóm nghĩ mình bất lịch sự.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Giả vờ bấm điện thoại, nói to \'Ôi cháu quên đồ rồi!\' và bước ngay ra khỏi thang máy.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:48:46', '2026-07-06 21:48:46'),
(4838, 814, 'reflection', '{\"question\": \"Lần gần nhất cơ thể bạn gửi tín hiệu cảnh báo \'bất ổn\' là khi nào?\"}', 5, '2026-07-06 21:48:46', '2026-07-06 21:48:46'),
(4839, 814, 'takeaway', '{\"items\": [\"Hãy tin vào chiếc ra-đa của cơ thể bạn, nó sinh ra để bảo vệ bạn.\"]}', 6, '2026-07-06 21:48:46', '2026-07-06 21:48:46'),
(4840, 815, 'hook', '{\"title\": \"Ai là người được phép bước vào không gian riêng tư của bạn?\"}', 1, '2026-07-06 21:48:47', '2026-07-06 21:48:47'),
(4841, 815, 'explanation', '{\"bullets\": [\"Mỗi chúng ta đều có một \'vòng tròn cá nhân\' xung quanh cơ thể.\", \"Khoảng cách dưới 0.5 mét thường chỉ dành cho những người cực kỳ thân thiết và khi bạn cho phép.\", \"Người lạ hoặc người quen xã giao cần giữ khoảng cách lịch sự từ 1 mét trở lên để bạn thấy an toàn.\"]}', 2, '2026-07-06 21:48:47', '2026-07-06 21:48:47'),
(4842, 815, 'scenario', '{\"title\": \"Tình huống khó xử\", \"body\": \"Nam đang ngồi ôn bài ở thư viện trường thì một bạn học cùng khóa (nhưng chưa từng nói chuyện) đến ngồi sát bên cạnh, ghé sát mặt vào xem Nam đang viết gì. Nam thấy vô cùng ngột ngạt và uncomfy nhưng ngại không dám đẩy ghế ra xa.\"}', 3, '2026-07-06 21:48:47', '2026-07-06 21:48:47'),
(4843, 815, 'interaction', '{\"question\": \"Nam nên làm gì để thiết lập lại vòng tròn an toàn của mình?\", \"choices\": [{\"text\": \"Ngồi im chịu đựng và cố gắng viết thật nhanh để đi về.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Thu dọn đồ đạc, đứng lên nói lịch sự: \'Xin lỗi, tớ cần không gian rộng hơn để viết\' và chuyển sang bàn khác.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:48:47', '2026-07-06 21:48:47'),
(4844, 815, 'reflection', '{\"question\": \"Bạn cảm thấy khoảng cách bao nhiêu là thoải mái nhất khi trò chuyện với người mới quen?\"}', 5, '2026-07-06 21:48:47', '2026-07-06 21:48:47'),
(4845, 815, 'takeaway', '{\"items\": [\"Bạn là chủ nhân của vòng tròn an toàn xung quanh cơ thể mình.\"]}', 6, '2026-07-06 21:48:47', '2026-07-06 21:48:47');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(4846, 816, 'hook', '{\"title\": \"Bạn có từng tự bảo mình: \'Chắc không sao đâu, mình chỉ đang nghĩ nhiều thôi\'?\"}', 1, '2026-07-06 21:48:47', '2026-07-06 21:48:47'),
(4847, 816, 'explanation', '{\"bullets\": [\"Gaslight (thao túng tâm lý) chính mình là khi bạn cố tình phớt lờ hoặc phủ nhận những linh cảm bất an.\", \"Chúng ta thường làm vậy vì muốn tin vào lòng tốt của người khác hoặc sợ rắc rối.\", \"Nhưng việc cố hợp lý hóa hành vi đáng ngờ của đối phương có thể khiến bạn rơi vào tình thế nguy hiểm.\"]}', 2, '2026-07-06 21:48:47', '2026-07-06 21:48:47'),
(4848, 816, 'scenario', '{\"title\": \"Tình huống nghi ngờ\", \"body\": \"Trong buổi họp gia đình, một người họ hàng xa cứ liên tục vỗ đùi và ôm eo Linh mỗi khi khen cô bé học giỏi. Linh cảm thấy rất khó chịu và muốn tránh ra, nhưng mẹ Linh lại bảo: \\\"Chú quý chú mới ôm thế chứ có gì đâu con!\\\". Linh bắt đầu tự trách mình là đứa trẻ ích kỷ và đa nghi.\"}', 3, '2026-07-06 21:48:47', '2026-07-06 21:48:47'),
(4849, 816, 'interaction', '{\"question\": \"Linh nên tin vào điều gì trong tình huống này?\", \"choices\": [{\"text\": \"Tin vào lời mẹ và tiếp tục chịu đựng đụng chạm của người chú.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Tin vào cảm giác uncomfy của chính mình, tìm cớ xuống bếp hoặc đi vệ sinh để tránh người chú.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:48:47', '2026-07-06 21:48:47'),
(4850, 816, 'reflection', '{\"question\": \"Bạn có từng bỏ qua linh cảm bất an của mình để rồi sau đó hối hận không?\"}', 5, '2026-07-06 21:48:47', '2026-07-06 21:48:47'),
(4851, 816, 'takeaway', '{\"items\": [\"Nếu bạn cảm thấy có gì đó sai sai, thì chắc chắn là có gì đó không ổn.\"]}', 6, '2026-07-06 21:48:47', '2026-07-06 21:48:47'),
(4852, 817, 'hook', '{\"title\": \"Bạn có bắt buộc phải ôm hay hôn má người khác chỉ vì người lớn yêu cầu?\"}', 1, '2026-07-06 21:48:47', '2026-07-06 21:48:47'),
(4853, 817, 'explanation', '{\"bullets\": [\"Ở Việt Nam, chúng ta thường được dạy phải lễ phép và vâng lời người lớn.\", \"Tuy nhiên, lễ phép không đồng nghĩa với việc nhượng bộ quyền kiểm soát cơ thể mình.\", \"Bạn hoàn toàn có quyền từ chối các đụng chạm thân mật và thay thế bằng những cử chỉ lịch sự khác.\"]}', 2, '2026-07-06 21:48:47', '2026-07-06 21:48:47'),
(4854, 817, 'scenario', '{\"title\": \"Tình huống chào hỏi\", \"body\": \"Bố mẹ dắt Khánh đến chơi nhà một người bạn của gia đình. Khi chuẩn bị về, bác chủ nhà muốn ôm hôn má Khánh tạm biệt. Khánh thấy rất ngượng ngùng và không thích, nhưng bố mẹ cứ giục: \\\"Kìa con, ôm bác một cái đi chứ!\\\".\"}', 3, '2026-07-06 21:48:48', '2026-07-06 21:48:48'),
(4855, 817, 'interaction', '{\"question\": \"Khánh có thể ứng xử thế nào để vừa lễ phép vừa bảo vệ được ranh giới cơ thể?\", \"choices\": [{\"text\": \"Cúi đầu chào lễ phép, chủ động đưa tay ra bắt tay và nói: \'Cháu chào bác cháu về ạ!\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Miễn cưỡng chịu đựng cái ôm để bố mẹ không bị mất mặt trước bạn bè.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:48:48', '2026-07-06 21:48:48'),
(4856, 817, 'reflection', '{\"question\": \"Bạn đã bao giờ thấy khó từ chối một đụng chạm cơ thể vì sợ bị đánh giá là vô lễ chưa?\"}', 5, '2026-07-06 21:48:48', '2026-07-06 21:48:48'),
(4857, 817, 'takeaway', '{\"items\": [\"Cơ thể bạn là của bạn, bạn quyết định ai được chạm vào nó.\"]}', 6, '2026-07-06 21:48:48', '2026-07-06 21:48:48'),
(4858, 818, 'hook', '{\"title\": \"Làm thế nào để tạo ra một khoảng trống an toàn khi ai đó cố tình tiến quá gần bạn?\"}', 1, '2026-07-06 21:48:48', '2026-07-06 21:48:48'),
(4859, 818, 'explanation', '{\"bullets\": [\"Kỹ năng tạo khoảng cách vật lý là bước đầu tiên để tự bảo vệ.\", \"Sử dụng ngôn ngữ cơ thể: đứng thẳng, lùi lại một bước, đặt chướng ngại vật (như balo, bàn ghế) ở giữa.\", \"Ánh mắt kiên định và giọng nói rõ ràng sẽ gửi thông điệp mạnh mẽ rằng bạn không dễ bị lấn lướt.\"]}', 2, '2026-07-06 21:48:48', '2026-07-06 21:48:48'),
(4860, 818, 'scenario', '{\"title\": \"Tình huống trên xe bus\", \"body\": \"Trên chuyến xe bus đông đúc đi học về, một người đàn ông liên tục đứng sát và cố tình cọ sát vào người Mai. Mai cảm thấy vô cùng hoảng sợ và bối rối, không biết phải trốn đi đâu trong không gian chật hẹp này.\"}', 3, '2026-07-06 21:48:48', '2026-07-06 21:48:48'),
(4861, 818, 'interaction', '{\"question\": \"Hành động nào giúp Mai kích hoạt khoảng cách an toàn hiệu quả nhất lúc này?\", \"choices\": [{\"text\": \"Đứng im chịu đựng và hy vọng người đó sẽ tự động dừng lại hoặc xuống xe trước.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Xoay người lại, lấy balo chắn phía trước, nhìn thẳng vào người đó và di chuyển sang khu vực gần bác tài xế.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:48:48', '2026-07-06 21:48:48'),
(4862, 818, 'reflection', '{\"question\": \"Bạn có mang theo vật dụng gì hàng ngày (như balo, ô) có thể dùng làm \'lá chắn\' ranh giới không?\"}', 5, '2026-07-06 21:48:48', '2026-07-06 21:48:48'),
(4863, 818, 'takeaway', '{\"items\": [\"Chủ động tạo khoảng cách là quyền tự vệ cơ bản của bạn.\"]}', 6, '2026-07-06 21:48:48', '2026-07-06 21:48:48'),
(4864, 819, 'hook', '{\"title\": \"Bạn có tự tin rằng mình biết cách nhận diện và bảo vệ an toàn cho bản thân?\"}', 1, '2026-07-06 21:48:48', '2026-07-06 21:48:48'),
(4865, 819, 'explanation', '{\"bullets\": [\"Tự đánh giá mức độ nhạy bén của bản thân giúp bạn nhận ra những điểm mình cần cải thiện.\", \"An toàn không phải là sự sợ hãi thế giới xung quanh, mà là sự tự tin vì mình có kiến thức.\", \"Hãy trung thực với cảm xúc của mình để biết khi nào cần nâng cao cảnh giác.\"]}', 2, '2026-07-06 21:48:48', '2026-07-06 21:48:48'),
(4866, 819, 'scenario', '{\"title\": \"Tình huống tự hỏi\", \"body\": \"Vy đọc được một bài viết về ranh giới cá nhân trên mạng xã hội. Vy nhận ra trước giờ mình rất hay nể bạn bè, ai mượn đồ dùng cá nhân cũng cho dù thấy uncomfy, ai trêu đùa quá đà cũng chỉ cười trừ. Vy băn khoăn liệu mình có đang quá yếu đuối.\"}', 3, '2026-07-06 21:48:48', '2026-07-06 21:48:48'),
(4867, 819, 'interaction', '{\"question\": \"Hãy chọn trạng thái mô tả đúng nhất cảm xúc của bạn khi phải bảo vệ ranh giới cá nhân:\", \"choices\": [{\"text\": \"Rất e ngại, thà chịu ấm ức còn hơn làm người khác mất lòng.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Bình thường, tùy trường hợp mới lên tiếng.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Khá tự tin, sẵn sàng lên tiếng bảo vệ sự thoải mái của mình.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:48:48', '2026-07-06 21:48:48'),
(4868, 819, 'reflection', '{\"question\": \"Điều gì cản trở bạn lên tiếng bảo vệ ranh giới cá nhân của mình nhiều nhất?\"}', 5, '2026-07-06 21:48:48', '2026-07-06 21:48:48'),
(4869, 819, 'takeaway', '{\"items\": [\"Hiểu rõ bản thân là bước đầu tiên để xây dựng tấm khiên bảo vệ vững chắc.\"]}', 6, '2026-07-06 21:48:48', '2026-07-06 21:48:48'),
(4870, 820, 'hook', '{\"title\": \"Bạn có biết rằng định nghĩa về sự an toàn của bạn có thể thay đổi khi bạn lớn lên?\"}', 1, '2026-07-06 21:48:49', '2026-07-06 21:48:49'),
(4871, 820, 'explanation', '{\"bullets\": [\"Khi còn nhỏ, an toàn là nghe lời bố mẹ và không đi theo người lạ.\", \"Khi bước vào tuổi dậy thì, an toàn phức tạp hơn: ranh giới cơ thể, bảo mật trên mạng, và các mối quan hệ tình cảm.\", \"Hãy liên tục cập nhật và điều chỉnh các quy tắc an toàn phù hợp với từng giai đoạn lớn lên của mình.\"]}', 2, '2026-07-06 21:48:49', '2026-07-06 21:48:49'),
(4872, 820, 'scenario', '{\"title\": \"Tình huống thay đổi\", \"body\": \"An (15 tuổi) bắt đầu tham gia các hoạt động ngoại khóa ngoài trường học và tự đi xe máy điện. An nhận ra những quy tắc an toàn trước đây bố mẹ dạy không còn đủ để bảo vệ An trước các tình huống ngoài xã hội.\"}', 3, '2026-07-06 21:48:49', '2026-07-06 21:48:49'),
(4873, 820, 'interaction', '{\"question\": \"An nên làm gì để nâng cấp \'hệ thống an toàn\' của mình?\", \"choices\": [{\"text\": \"Chủ động thảo luận với bố mẹ và tìm hiểu thêm kiến thức tự vệ trên các trang web uy tín như Scarleteen.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Bỏ qua vì nghĩ mình đã lớn và có thể tự lo mọi thứ mà không cần chuẩn bị.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-06 21:48:49', '2026-07-06 21:48:49'),
(4874, 820, 'reflection', '{\"question\": \"So với 2 năm trước, ranh giới cá nhân của bạn hiện tại đã thay đổi như thế nào?\"}', 5, '2026-07-06 21:48:49', '2026-07-06 21:48:49'),
(4875, 820, 'takeaway', '{\"items\": [\"Lớn lên nghĩa là bạn có nhiều tự do hơn, và cũng cần nhiều kỹ năng tự bảo vệ hơn.\"]}', 6, '2026-07-06 21:48:49', '2026-07-06 21:48:49'),
(4876, 821, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Chiếc ra-đa cơ thể\'! Hãy cùng chứng minh sự nhạy bén của các giác quan nhé.\"}', 1, '2026-07-06 21:48:49', '2026-07-06 21:48:49'),
(4877, 821, 'scenario-choice', '{\"title\": \"Cuộc đối thoại lúc chiều muộn\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn ở lại trường làm báo tường muộn, một bác bảo vệ đi qua bảo: \'Phòng bảo vệ có trà sữa ngon lắm, vào đây bác cho uống rồi chở về nhà\'. Cơ thể bạn bỗng thấy ớn lạnh và muốn lùi lại.\", \"choices\": [{\"text\": \"Nghe theo bác bảo vệ vì bác là nhân viên trường học, chắc không sao đâu.\", \"nextNode\": \"fail_submit\"}, {\"text\": \"Từ chối khéo: \'Dạ thôi cháu sắp có mẹ đón rồi ạ\' và đi ngay ra khu vực cổng trường có người qua lại.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Chờ ở cổng trường 15 phút chưa thấy mẹ đâu, một người đàn ông lạ đi xe máy dừng lại bảo mẹ nhờ chở về.\", \"choices\": [{\"text\": \"Lên xe về luôn vì trời đã tối và bạn thấy hơi sợ.\", \"nextNode\": \"fail_guilt\"}, {\"text\": \"Từ chối: \'Cháu cảm ơn nhưng cháu tự gọi điện cho mẹ ạ\' và bước vào văn phòng hiệu bộ còn sáng đèn để gọi điện.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã lắng nghe ra-đa cơ thể đúng lúc và tìm nơi trú ẩn an toàn cực kỳ khôn ngoan.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_submit\": {\"text\": \"❌ Thất bại! Bỏ qua linh cảm bất an và bước vào không gian kín với người lạ là cực kỳ mạo hiểm.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_guilt\": {\"text\": \"❌ Thất bại! Lên xe người lạ khi chưa xác nhận với bố mẹ là cờ đỏ rất nguy hiểm.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-06 21:48:49', '2026-07-06 21:48:49'),
(4878, 821, 'sorting', '{\"instruction\": \"Hãy phân loại các tín hiệu phản ứng của cơ thể:\", \"leftBox\": {\"title\": \"Linh cảm bất an (Cần tránh xa)\"}, \"rightBox\": {\"title\": \"Cảm giác bình yên (An toàn)\"}, \"items\": [{\"text\": \"Tim đập thình thịch, nổi da gà\", \"correctBox\": \"left\"}, {\"text\": \"Cảm giác thư giãn, thoải mái nói cười\", \"correctBox\": \"right\"}, {\"text\": \"Cổ họng nghẹn ứ, bụng cồn cào\", \"correctBox\": \"left\"}, {\"text\": \"Thả lỏng cơ mặt, giữ khoảng cách dễ chịu\", \"correctBox\": \"right\"}]}', 3, '2026-07-06 21:48:49', '2026-07-06 21:48:49'),
(4879, 821, 'matching', '{\"instruction\": \"Ghép cặp các khái niệm an toàn cơ bản sau:\", \"pairs\": [{\"left\": \"Linh cảm cơ thể\", \"right\": \"Ra-đa tự động cảnh báo nguy hiểm\"}, {\"left\": \"Gaslight chính mình\", \"right\": \"Cố phớt lờ cảm giác bất an của bản thân\"}, {\"left\": \"Vòng tròn cá nhân\", \"right\": \"Không gian riêng tư xung quanh cơ thể\"}, {\"left\": \"Lùi lại một bước\", \"right\": \"Cách tạo khoảng cách vật lý tinh tế\"}]}', 4, '2026-07-06 21:48:49', '2026-07-06 21:48:49'),
(4880, 821, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về linh cảm cơ thể:\", \"sentence\": \"Cơ thể của chúng ta có một chiếc [blank1] tự động rất thông minh. Khi gặp tình huống bất ổn, hãy luôn [blank2] linh cảm của mình thay vì tự [blank3] bản thân.\", \"blanks\": {\"blank1\": {\"correct\": \"ra-đa\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"tin tưởng\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"gaslight\", \"placeholder\": \"...\"}}, \"words\": [\"ra-đa\", \"tin tưởng\", \"gaslight\", \"bỏ qua\", \"nghi ngờ\", \"camera\"]}', 5, '2026-07-06 21:48:49', '2026-07-06 21:48:49'),
(4881, 821, 'interaction', '{\"question\": \"Khi có người cố tình đứng sát vào bạn ở nơi công cộng làm bạn thấy khó chịu, phản ứng nào là đúng đắn nhất?\", \"choices\": [{\"text\": \"Chủ động lùi lại hoặc di chuyển sang vị trí khác ngay lập tức, lấy balo làm lá chắn.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Đứng im chịu đựng vì sợ người khác nghĩ mình làm quá vấn đề.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-06 21:48:49', '2026-07-06 21:48:49'),
(4882, 822, 'hook', '{\"title\": \"Bạn có cho phép người khác chạm vào ví tiền hay điện thoại của mình mà không hỏi trước?\"}', 1, '2026-07-06 21:48:50', '2026-07-06 21:48:50'),
(4883, 822, 'explanation', '{\"bullets\": [\"Nếu đồ vật cá nhân cần được tôn trọng, thì cơ thể và cảm xúc của bạn lại càng cần như thế!\", \"Ranh giới cá nhân giống như một vạch kẻ sơn vô hình bảo vệ không gian riêng tư của bạn.\", \"Nó giúp xác định rõ hành vi nào là chấp nhận được và hành vi nào làm bạn thấy uncomfy.\"]}', 2, '2026-07-06 21:48:50', '2026-07-06 21:48:50'),
(4884, 822, 'scenario', '{\"title\": \"Tình huống mượn đồ\", \"body\": \"Trong giờ kiểm tra, Hoa tự ý thò tay vào balo của Trang lấy hộp bút mà không hề hỏi trước. Trang cảm thấy khó chịu vì Hoa chạm vào đồ riêng tư của mình, nhưng sợ Hoa giận nên Trang im lặng không nói gì.\"}', 3, '2026-07-06 21:48:50', '2026-07-06 21:48:50'),
(4885, 822, 'interaction', '{\"question\": \"Trang nên phản ứng thế nào để Hoa hiểu về ranh giới của mình?\", \"choices\": [{\"text\": \"Nói khéo sau giờ học: \'Lần sau cậu mượn bút thì bảo tớ một tiếng nhé, tớ không thích người khác tự ý lục balo đâu\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Giật lại hộp bút và mắng Hoa là đồ ăn cắp trước mặt cả lớp.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:48:50', '2026-07-06 21:48:50'),
(4886, 822, 'reflection', '{\"question\": \"Đâu là giới hạn riêng tư lớn nhất mà bạn không muốn ai (kể cả bạn thân) bước qua?\"}', 5, '2026-07-06 21:48:50', '2026-07-06 21:48:50'),
(4887, 822, 'takeaway', '{\"items\": [\"Ranh giới của bạn là do bạn vẽ ra, và người khác có nghĩa vụ phải tôn trọng nó.\"]}', 6, '2026-07-06 21:48:50', '2026-07-06 21:48:50'),
(4888, 823, 'hook', '{\"title\": \"Im lặng hay cười trừ có nghĩa là \'đồng ý\' không?\"}', 1, '2026-07-06 21:48:50', '2026-07-06 21:48:50'),
(4889, 823, 'explanation', '{\"bullets\": [\"Sự đồng thuận (Consent) phải đáp ứng quy tắc F.R.I.E.S: Tự nguyện (Freely given), Có thể rút lại (Reversible), Có hiểu biết (Informed), Cụ thể (Enthusiastic), và Tỉnh táo (Specific).\", \"Đồng ý một lần không có nghĩa là đồng ý mãi mãi.\", \"Nếu đối phương tỏ ra do dự, gượng gạo hoặc im lặng, đó là \\\"Không\\\", tuyệt đối không phải là \\\"Có\\\".\"]}', 2, '2026-07-06 21:48:50', '2026-07-06 21:48:50'),
(4890, 823, 'scenario', '{\"title\": \"Tình huống chơi game\", \"body\": \"Khoa rủ nhóm bạn chơi trò vật tay. Minh ngập ngừng bảo: \\\"Tớ hơi mỏi tay...\\\" nhưng Khoa vẫn kéo tay Minh ra bàn và bảo: \\\"Chơi tí cho vui làm gì ghê thế!\\\". Minh đành bấm bụng chơi tiếp dù rất đau.\"}', 3, '2026-07-06 21:48:50', '2026-07-06 21:48:50'),
(4891, 823, 'interaction', '{\"question\": \"Trong tình huống này, Khoa đã vi phạm điều gì trong luật chơi đồng thuận?\", \"choices\": [{\"text\": \"Khoa đã ép buộc khi Minh tỏ ra do dự và không hề có sự đồng thuận tự nguyện.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Khoa không sai vì đây chỉ là trò chơi giải trí bình thường giữa con trai với nhau.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:48:50', '2026-07-06 21:48:50'),
(4892, 823, 'reflection', '{\"question\": \"Bạn đã bao giờ gật đầu đồng ý làm điều gì đó chỉ vì áp lực đám đông chưa?\"}', 5, '2026-07-06 21:48:50', '2026-07-06 21:48:50'),
(4893, 823, 'takeaway', '{\"items\": [\"Chỉ có câu trả lời \'Có\' rõ ràng và hào hứng mới là sự đồng thuận.\"]}', 6, '2026-07-06 21:48:50', '2026-07-06 21:48:50'),
(4894, 824, 'hook', '{\"title\": \"Bạn có sợ người khác ghét mình nếu bạn từ chối lời đề nghị của họ?\"}', 1, '2026-07-06 21:48:51', '2026-07-06 21:48:51'),
(4895, 824, 'explanation', '{\"bullets\": [\"Tâm lý sợ bị cô lập, sợ làm mất lòng người khác (people-pleasing) là rào cản lớn nhất khiến ta khó nói \\\"Không\\\".\", \"Kẻ xấu thường lợi dụng nỗi sợ này để ép bạn phá vỡ ranh giới của chính mình.\", \"Hãy nhớ rằng: Từ chối một hành động không có nghĩa là bạn ghét người đó, bạn chỉ đang bảo vệ năng lượng của mình.\"]}', 2, '2026-07-06 21:48:51', '2026-07-06 21:48:51'),
(4896, 824, 'scenario', '{\"title\": \"Tình huống nể bạn\", \"body\": \"Vy được bạn thân rủ đi trốn học đi chơi game net vào giờ học thêm. Vy không muốn vì sợ bố mẹ mắng, nhưng bạn thân bảo: \\\"Không đi thì từ sau nghỉ chơi luôn nhé!\\\". Vy vô cùng áp lực và sợ bị tẩy chay.\"}', 3, '2026-07-06 21:48:51', '2026-07-06 21:48:51'),
(4897, 824, 'interaction', '{\"question\": \"Vy nên đối diện với lời đe dọa của bạn thân thế nào?\", \"choices\": [{\"text\": \"Đi theo bạn để giữ gìn tình bạn dù trong lòng vô cùng lo lắng, bất an.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Kiên định từ chối: \'Tớ không đi đâu. Nếu cậu vì chuyện này mà nghỉ chơi thì tớ cũng đành chịu vậy\'.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:48:51', '2026-07-06 21:48:51'),
(4898, 824, 'reflection', '{\"question\": \"Bạn có cảm thấy áy náy khi đặt sự thoải mái của bản thân lên trên cảm xúc của người khác không?\"}', 5, '2026-07-06 21:48:51', '2026-07-06 21:48:51'),
(4899, 824, 'takeaway', '{\"items\": [\"Bạn không có trách nhiệm phải làm hài lòng tất cả mọi người bằng cách làm tổn thương chính mình.\"]}', 6, '2026-07-06 21:48:51', '2026-07-06 21:48:51'),
(4900, 825, 'hook', '{\"title\": \"Có phải mọi thứ gắn mác \'đùa cho vui\' đều vô hại?\"}', 1, '2026-07-06 21:48:51', '2026-07-06 21:48:51'),
(4901, 825, 'explanation', '{\"bullets\": [\"Trêu chọc, giật tóc, vỗ mông, hay đụng chạm cơ thể rồi cười xòa nói: \\\"Đùa tí thôi mà\\\" là những hành vi vi phạm ranh giới rất nghiêm trọng.\", \"Một trò đùa chỉ vui khi **tất cả mọi người cùng cười**.\", \"Nếu có ít nhất một người cảm thấy khó chịu hoặc bị xúc phạm, đó là hành vi quấy rối, không phải trò đùa.\"]}', 2, '2026-07-06 21:48:51', '2026-07-06 21:48:51'),
(4902, 825, 'scenario', '{\"title\": \"Tình huống đùa dai\", \"body\": \"Trong giờ ra chơi, Hùng và Nam xông vào giữ chặt tay chân của Tuấn để cù lét dù Tuấn liên tục la hét: \\\"Thôi đi, tớ xin đấy, dừng lại đi!\\\". Các bạn xung quanh đứng cười cổ vũ vì nghĩ đây chỉ là trò đùa vô hại giữa con trai với nhau.\"}', 3, '2026-07-06 21:48:51', '2026-07-06 21:48:51'),
(4903, 825, 'interaction', '{\"question\": \"Phân tích hành vi của Hùng và Nam trong tình huống này:\", \"choices\": [{\"text\": \"Đây là hành vi vi phạm ranh giới cơ thể vì Tuấn đã yêu cầu dừng lại rõ ràng nhưng không được tôn trọng.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Chỉ là các bạn đùa vui quá trớn tí thôi, Tuấn không nên quá nhạy cảm như vậy.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:48:51', '2026-07-06 21:48:51'),
(4904, 825, 'reflection', '{\"question\": \"Bạn đã từng phải cười gượng gạo trước một trò đùa đụng chạm làm bạn thấy khó chịu chưa?\"}', 5, '2026-07-06 21:48:51', '2026-07-06 21:48:51'),
(4905, 825, 'takeaway', '{\"items\": [\"Tôn trọng cảm xúc của người khác quan trọng hơn việc tạo ra tiếng cười vô duyên.\"]}', 6, '2026-07-06 21:48:51', '2026-07-06 21:48:51'),
(4906, 826, 'hook', '{\"title\": \"Làm sao để từ chối một lời đề nghị khó xử mà không gây cãi vã?\"}', 1, '2026-07-06 21:48:51', '2026-07-06 21:48:51'),
(4907, 826, 'explanation', '{\"bullets\": [\"Hãy bỏ túi ngay **Công thức 3 bước** cực kỳ tinh tế và hiệu quả:\", \"1. **Ghi nhận:** Xác nhận lời đề nghị (để tỏ ra lịch sự).\", \"2. **Nói Không rõ ràng:** Từ chối thẳng thắn, không giải thích dài dòng hay đổ lỗi.\", \"3. **Đề xuất giải pháp thay thế** (nếu muốn) hoặc dừng câu chuyện.\", \"Sự dứt khoát trong giọng điệu và ánh mắt là vũ khí mạnh nhất của bạn.\"]}', 2, '2026-07-06 21:48:51', '2026-07-06 21:48:51'),
(4908, 826, 'scenario', '{\"title\": \"Tình huống từ chối\", \"body\": \"Nam được một bạn cùng lớp rủ hút thử thuốc lá điện tử (pod) sau trường. Bạn ấy bảo: \\\"Thử tí đi, không hút là nhát gan, không phải đàn ông!\\\". Nam thực sự không thích khói thuốc và muốn từ chối dứt khoát.\"}', 3, '2026-07-06 21:48:51', '2026-07-06 21:48:51'),
(4909, 826, 'interaction', '{\"question\": \"Áp dụng công thức 3 bước, Nam nên nói thế nào?\", \"choices\": [{\"text\": \"\'Cảm ơn cậu đã rủ nhé. Nhưng tớ không thích hút pod đâu. Tụi mình ra canteen mua nước uống đi!\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"\'Để tớ xem đã, hôm nay tớ hơi đau họng, hẹn cậu hôm khác nhé\'.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:48:51', '2026-07-06 21:48:51'),
(4910, 826, 'reflection', '{\"question\": \"Lần gần nhất bạn từ chối ai đó thành công là nhờ cách nói như thế nào?\"}', 5, '2026-07-06 21:48:52', '2026-07-06 21:48:52'),
(4911, 826, 'takeaway', '{\"items\": [\"Nói Không là cách bạn định hình giá trị và bảo vệ bản thân trước những áp lực độc hại.\"]}', 6, '2026-07-06 21:48:52', '2026-07-06 21:48:52'),
(4912, 827, 'hook', '{\"title\": \"Bạn có cảm thấy kiệt sức vì luôn phải gật đầu trước mọi yêu cầu của mọi người?\"}', 1, '2026-07-06 21:48:52', '2026-07-06 21:48:52'),
(4913, 827, 'explanation', '{\"bullets\": [\"Trạng thái \\\"Luôn đồng ý\\\" (People-pleasing) khiến bạn bỏ quên mong muốn của bản thân để làm hài lòng người khác.\", \"Đây là một thói quen nguy hiểm, khiến ranh giới cá nhân của bạn ngày càng mờ nhạt và dễ bị xâm phạm.\", \"Học cách ưu tiên cảm xúc của mình trước không phải là ích kỷ, đó là sự tự tôn cần thiết.\"]}', 2, '2026-07-06 21:48:52', '2026-07-06 21:48:52'),
(4914, 827, 'scenario', '{\"title\": \"Tình huống quá tải\", \"body\": \"Vy luôn là người nhận làm hết phần slide thuyết trình cho nhóm vì các bạn khác than bận. Vy thấy rất mệt mỏi và ức chế, nhưng mỗi khi định từ chối, Vy lại lo sợ các bạn sẽ ghét mình và không chơi với mình nữa.\"}', 3, '2026-07-06 21:48:52', '2026-07-06 21:48:52'),
(4915, 827, 'interaction', '{\"question\": \"Vy nên bắt đầu thay đổi từ hành động nhỏ nào dưới đây?\", \"choices\": [{\"text\": \"Tiếp tục làm hộ để giữ hòa khí trong nhóm, tự nhủ thôi cố nốt lần này.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Nói rõ trong group nhóm: \'Phần slide tớ đã làm 2 lần rồi. Lần này tớ sẽ phụ trách phần nội dung, bạn khác làm slide nhé\'.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:48:52', '2026-07-06 21:48:52'),
(4916, 827, 'reflection', '{\"question\": \"Bạn có sợ cảm giác bị ghét hơn là cảm giác bị lợi dụng không?\"}', 5, '2026-07-06 21:48:52', '2026-07-06 21:48:52'),
(4917, 827, 'takeaway', '{\"items\": [\"Bạn không cần phải làm người khác vui bằng cách bỏ qua cảm xúc của chính mình.\"]}', 6, '2026-07-06 21:48:52', '2026-07-06 21:48:52'),
(4918, 828, 'hook', '{\"title\": \"Bạn sẽ phản ứng thế nào khi ai đó nói \'Không\' với bạn?\"}', 1, '2026-07-06 21:48:52', '2026-07-06 21:48:52'),
(4919, 828, 'explanation', '{\"bullets\": [\"Đồng thuận là con đường hai chiều. Tôn trọng ranh giới của mình thì cũng phải tôn trọng ranh giới của người khác.\", \"Khi bị từ chối, cảm thấy hụt hẫng hay buồn là bình thường, nhưng cố chấp nài nỉ hay giận dỗi là hành vi thiếu văn minh.\", \"Hãy lắng nghe lời từ chối với thái độ cởi mở và dừng ngay hành vi làm phiền đối phương.\"]}', 2, '2026-07-06 21:48:52', '2026-07-06 21:48:52'),
(4920, 828, 'scenario', '{\"title\": \"Tình huống bị từ chối\", \"body\": \"Nam muốn mượn chiếc tai nghe mới của Khoa để nghe nhạc. Khoa bảo: \\\"Tớ không thích người khác dùng chung tai nghe vì lý do vệ sinh đâu\\\". Nam cảm thấy hơi tự ái và định giận dỗi không chơi với Khoa nữa.\"}', 3, '2026-07-06 21:48:52', '2026-07-06 21:48:52'),
(4921, 828, 'interaction', '{\"question\": \"Nếu là Nam, cách cư xử văn minh nhất lúc này là gì?\", \"choices\": [{\"text\": \"Nói: \'À tớ hiểu rồi, không sao đâu\' và chủ động đổi sang chủ đề khác.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Trêu Khoa: \'Gớm, làm gì mà kiệt xỉ thế, bạn bè chơi với nhau bao lâu rồi mà tiếc\'.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:48:52', '2026-07-06 21:48:52'),
(4922, 828, 'reflection', '{\"question\": \"Lần gần nhất bạn chấp nhận lời từ chối từ người khác một cách vui vẻ là khi nào?\"}', 5, '2026-07-06 21:48:53', '2026-07-06 21:48:53'),
(4923, 828, 'takeaway', '{\"items\": [\"Tôn trọng ranh giới của người khác là cách nhanh nhất để nhận lại sự tôn trọng.\"]}', 6, '2026-07-06 21:48:53', '2026-07-06 21:48:53'),
(4924, 829, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Ranh giới & Sự đồng thuận\'! Đã đến lúc học cách bảo vệ vạch kẻ sơn của riêng mình.\"}', 1, '2026-07-06 21:48:53', '2026-07-06 21:48:53'),
(4925, 829, 'scenario-choice', '{\"title\": \"Áp lực từ nhóm bạn thân\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Nhóm bạn thân rủ bạn quay một video nhảy TikTok gợi cảm. Bạn thấy không thoải mái (uncomfy) và không muốn tham gia, nhưng các bạn trêu: \'Yếu thế, không nhảy là kích ra khỏi nhóm nhé!\'.\", \"choices\": [{\"text\": \"Nhắm mắt nhảy theo để không bị tẩy chay khỏi nhóm.\", \"nextNode\": \"fail_submit\"}, {\"text\": \"Nói rõ: \'Tớ không thích quay kiểu này đâu. Tớ đứng quay phim cho các cậu được không?\'\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Các bạn đồng ý cho bạn quay phim, nhưng một bạn giật điện thoại của bạn định đăng hình chụp dìm hàng nhạy cảm của bạn lên mạng xã hội.\", \"choices\": [{\"text\": \"Cười trừ và bảo: \'Thôi đừng đăng nha cậu\' nhưng không giật lại điện thoại.\", \"nextNode\": \"fail_guilt\"}, {\"text\": \"Giành lại điện thoại nghiêm túc: \'Xóa ngay đi, tớ không cho phép đăng ảnh riêng tư của tớ đâu\'.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã biết cách từ chối áp lực đám đông và kiên định bảo vệ ranh giới hình ảnh cá nhân.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_submit\": {\"text\": \"❌ Thất bại! Ép bản thân làm điều uncomfy chỉ để vừa lòng bạn bè sẽ làm bạn mất đi sự tự tôn.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_guilt\": {\"text\": \"❌ Thất bại! Cười trừ trước hành vi xâm phạm ranh giới thông tin sẽ khiến người khác lấn tới.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-06 21:48:53', '2026-07-06 21:48:53'),
(4926, 829, 'sorting', '{\"instruction\": \"Hãy phân loại các hành vi giao tiếp ranh giới sau:\", \"leftBox\": {\"title\": \"Green Flag (Tôn trọng)\"}, \"rightBox\": {\"title\": \"Red Flag (Vi phạm)\"}, \"items\": [{\"text\": \"Hỏi ý kiến trước khi ôm hoặc đụng chạm bạn bè\", \"correctBox\": \"left\"}, {\"text\": \"Ép bạn uống thử nước ngọt lạ bằng cách nói khích\", \"correctBox\": \"right\"}, {\"text\": \"Dừng lại ngay khi đối phương tỏ ra ngập ngừng\", \"correctBox\": \"left\"}, {\"text\": \"Tự ý lục balo, đọc tin nhắn điện thoại của bạn\", \"correctBox\": \"right\"}]}', 3, '2026-07-06 21:48:53', '2026-07-06 21:48:53'),
(4927, 829, 'matching', '{\"instruction\": \"Ghép cặp các quy tắc đồng thuận sau:\", \"pairs\": [{\"left\": \"Tự nguyện\", \"right\": \"Được đưa ra hoàn toàn thoải mái, không ép buộc\"}, {\"left\": \"Có thể rút lại\", \"right\": \"Được quyền đổi ý bất cứ lúc nào dù đã Say Yes\"}, {\"left\": \"Tỉnh táo\", \"right\": \"Đồng thuận khi tỉnh táo, không bị say xỉn\"}, {\"left\": \"Cụ thể\", \"right\": \"Đồng ý việc này không có nghĩa là đồng ý việc khác\"}]}', 4, '2026-07-06 21:48:53', '2026-07-06 21:48:53'),
(4928, 829, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về ranh giới cá nhân:\", \"sentence\": \"Sự đồng thuận phải là sự đồng ý [blank1] và hào hứng từ cả hai phía. Hãy nhớ rằng im lặng hay [blank2] không bao giờ có nghĩa là đồng ý. Bạn luôn có quyền nói [blank3] để tự bảo vệ mình.\", \"blanks\": {\"blank1\": {\"correct\": \"tự nguyện\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"cười trừ\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"không\", \"placeholder\": \"...\"}}, \"words\": [\"tự nguyện\", \"cười trừ\", \"không\", \"ép buộc\", \"có\", \"giận dỗi\"]}', 5, '2026-07-06 21:48:53', '2026-07-06 21:48:53'),
(4929, 829, 'interaction', '{\"question\": \"Khi bạn của bạn nói \'Không\' trước một trò đùa vật lý, phản ứng văn minh nhất của bạn là gì?\", \"choices\": [{\"text\": \"Dừng ngay trò đùa lại, tôn trọng ranh giới của bạn mà không giận dỗi hay trêu chọc thêm.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Nài nỉ chơi tiếp và bảo bạn: \'Gớm, đùa tí thôi làm gì mà khó tính thế\'.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-06 21:48:53', '2026-07-06 21:48:53'),
(4930, 830, 'hook', '{\"title\": \"Bạn có tin một người mới quen lại tặng bạn những món quà đắt tiền vô điều kiện?\"}', 1, '2026-07-06 21:48:53', '2026-07-06 21:48:53'),
(4931, 830, 'explanation', '{\"bullets\": [\"**Grooming** (Dụ dỗ, lấy lòng) là hành vi tiếp cận tinh vi của kẻ xấu nhằm xây dựng mối quan hệ thân thiết và lòng tin với người trẻ.\", \"Mục tiêu của họ không phải là làm bạn tốt, mà là để dễ dàng xâm hại hoặc thao túng bạn sau này.\", \"Họ thường ngụy trang dưới vẻ ngoài cực kỳ tốt bụng, tâm lý và hào phóng.\"]}', 2, '2026-07-06 21:48:53', '2026-07-06 21:48:53'),
(4932, 830, 'scenario', '{\"title\": \"Tình huống làm quen\", \"body\": \"Vy tham gia một group vẽ tranh trên Facebook và quen một anh họa sĩ tự do 24 tuổi. Anh ấy thường xuyên nhắn tin khen tranh của Vy đẹp, hứa sẽ dạy Vy vẽ miễn phí và gửi tặng Vy một bộ màu nước chuyên nghiệp trị giá cả triệu đồng. Vy thấy rất vui và nghĩ mình đã gặp được một người anh khóa trên lý tưởng.\"}', 3, '2026-07-06 21:48:53', '2026-07-06 21:48:53'),
(4933, 830, 'interaction', '{\"question\": \"Vy nên cảnh giác với điều gì trong mối quan hệ này?\", \"choices\": [{\"text\": \"Cảnh giác vì một người lớn lạ mặt đột nhiên đầu tư nhiều tiền bạc và sự chú ý vào một học sinh 14 tuổi mà không rõ lý do.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Không cần cảnh giác vì anh ấy chỉ đang nâng đỡ tài năng trẻ nhiệt tình thôi.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-06 21:48:53', '2026-07-06 21:48:53'),
(4934, 830, 'reflection', '{\"question\": \"Bạn có bao giờ nhận được món quà nào làm bạn thấy hơi ngần ngại hoặc áy náy khi nhận không?\"}', 5, '2026-07-06 21:48:53', '2026-07-06 21:48:53'),
(4935, 830, 'takeaway', '{\"items\": [\"Kẻ dụ dỗ luôn dùng sự ngọt ngào làm mồi nhử để phá vỡ ranh giới phòng thủ của bạn.\"]}', 6, '2026-07-06 21:48:53', '2026-07-06 21:48:53'),
(4936, 831, 'hook', '{\"title\": \"Làm sao nhận diện một cái bẫy đang khép lại từ từ xung quanh bạn?\"}', 1, '2026-07-06 21:48:54', '2026-07-06 21:48:54'),
(4937, 831, 'explanation', '{\"bullets\": [\"Quá trình Grooming thường diễn ra qua 4 giai đoạn:\", \"1. **Nhắm mục tiêu & Làm quen:** Chọn người trẻ đang cô đơn hoặc cần sự chú ý.\", \"2. **Xây dựng lòng tin:** Tặng quà, lắng nghe tâm sự, tỏ ra thấu hiểu.\", \"3. **Cô lập:** Khuyên bạn không nên nghe lời bố mẹ, tách bạn ra khỏi bạn bè.\", \"4. **Bí mật & Xâm hại:** Tạo ra các bí mật riêng tư và bắt đầu thực hiện hành vi xâm hại.\"]}', 2, '2026-07-06 21:48:54', '2026-07-06 21:48:54'),
(4938, 831, 'scenario', '{\"title\": \"Tình huống dụ dỗ\", \"body\": \"Một thầy giáo dạy cờ vua sau giờ học thường xuyên cho Minh ăn bánh ngọt, chở Minh đi chơi và bảo: \\\"Minh là học trò cưng duy nhất của thầy. Chuyện thầy trò mình đi chơi riêng đừng kể cho bố mẹ nghe nhé, họ không hiểu được sự đặc biệt của con đâu\\\". Minh bắt đầu thấy hơi xa cách với bố mẹ.\"}', 3, '2026-07-06 21:48:54', '2026-07-06 21:48:54'),
(4939, 831, 'interaction', '{\"question\": \"Hành vi nào của người thầy là \'Red Flag\' (Cờ đỏ) nguy hiểm nhất?\", \"choices\": [{\"text\": \"Yêu cầu Minh giữ bí mật và tìm cách chia rẽ, cô lập Minh khỏi bố mẹ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Việc thầy tặng bánh ngọt và khen Minh là học trò giỏi nhất.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:48:54', '2026-07-06 21:48:54'),
(4940, 831, 'reflection', '{\"question\": \"Bạn có đang giữ một bí mật nào với gia đình chỉ vì có ai đó yêu cầu bạn phải giữ kín không?\"}', 5, '2026-07-06 21:48:54', '2026-07-06 21:48:54'),
(4941, 831, 'takeaway', '{\"items\": [\"Nếu ai đó bảo bạn phải giấu bố mẹ về mối quan hệ giữa hai người, đó chắc chắn là một cái bẫy.\"]}', 6, '2026-07-06 21:48:54', '2026-07-06 21:48:54'),
(4942, 832, 'hook', '{\"title\": \"Tại sao chúng ta rất khó tin rằng người quen lại có thể là kẻ xấu?\"}', 1, '2026-07-06 21:48:55', '2026-07-06 21:48:55'),
(4943, 832, 'explanation', '{\"bullets\": [\"Hơn 80% các vụ xâm hại người trẻ tuổi đến từ người quen biết (họ hàng, hàng xóm, thầy cô, bạn bè của gia đình).\", \"Chúng ta thường có xu hướng tin tưởng tuyệt đối vào những người có uy tín hoặc quyền lực xung quanh mình.\", \"Việc nhận diện \\\"cờ đỏ\\\" ở người quen làm bạn thấy bối rối, tội lỗi và sợ hãi không dám nói ra vì sợ làm rạn nứt gia đình.\"]}', 2, '2026-07-06 21:48:55', '2026-07-06 21:48:55'),
(4944, 832, 'scenario', '{\"title\": \"Tình huống khó nói\", \"body\": \"Chú ruột của An (người thường xuyên mua đồ chơi và đưa An đi học) dạo gần đây thường xuyên vuốt ve đùi An và bảo An cho xem vùng kín. An thấy sợ hãi và kinh tởm, nhưng lo sợ nếu nói ra sẽ làm bố mẹ cãi nhau với chú và làm hỏng bầu không khí gia đình.\"}', 3, '2026-07-06 21:48:55', '2026-07-06 21:48:55'),
(4945, 832, 'interaction', '{\"question\": \"An nên giải quyết nỗi sợ hãi này như thế nào?\", \"choices\": [{\"text\": \"Cố gắng chịu đựng và lảng tránh chú mỗi khi gặp mặt để gia đình được yên ổn.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Dũng cảm chia sẻ ngay lập tức với bố mẹ hoặc gọi Tổng đài 111 để được hướng dẫn bảo vệ.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:48:55', '2026-07-06 21:48:55'),
(4946, 832, 'reflection', '{\"question\": \"Bạn có cảm thấy khó khăn nếu phải nói lời từ chối hoặc tố cáo một người lớn tuổi mà bạn quen biết không?\"}', 5, '2026-07-06 21:48:55', '2026-07-06 21:48:55'),
(4947, 832, 'takeaway', '{\"items\": [\"Một mối quan hệ tôn trọng sẽ không bao giờ bắt bạn phải hy sinh sự an toàn của bản thân.\"]}', 6, '2026-07-06 21:48:55', '2026-07-06 21:48:55'),
(4948, 833, 'hook', '{\"title\": \"Bạn có từng nhận được tin nhắn đề nghị nạp thẻ game hoặc tặng quà VIP từ một người lạ trên mạng?\"}', 1, '2026-07-06 21:48:55', '2026-07-06 21:48:55'),
(4949, 833, 'explanation', '{\"bullets\": [\"**Online Grooming** (Dụ dỗ trực tuyến) đang cực kỳ phổ biến thông qua các tựa game online hoặc mạng xã hội.\", \"Kẻ xấu sẽ chủ động kết bạn, tặng vật phẩm game hoặc chuyển tiền để làm thân với bạn.\", \"Sau đó, chúng sẽ yêu cầu bạn gửi ảnh cá nhân, bật camera riêng tư hoặc thậm chí tống tiền bằng hình ảnh nhạy cảm (Sextortion).\"]}', 2, '2026-07-06 21:48:55', '2026-07-06 21:48:55'),
(4950, 833, 'scenario', '{\"title\": \"Tình huống chơi game\", \"body\": \"Hải (13 tuổi) quen một tài khoản VIP trên game Roblox. Người này đã tặng Hải rất nhiều Robux để mua đồ. Một ngày nọ, người đó nhắn tin: \\\"Anh đã tặng em rất nhiều quà rồi. Bây giờ em chụp ảnh không mặc áo gửi qua Zalo cho anh xem nhé, nếu không anh sẽ khóa tài khoản game của em đấy\\\".\"}', 3, '2026-07-06 21:48:55', '2026-07-06 21:48:55'),
(4951, 833, 'interaction', '{\"question\": \"Hải nên xử lý yêu cầu tống tiền này như thế nào?\", \"choices\": [{\"text\": \"Tuyệt đối không chụp ảnh, chặn ngay tài khoản đó và báo cáo sự việc cho bố mẹ hoặc người lớn đáng tin cậy.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Chụp một tấm ảnh gửi qua để giữ lại tài khoản game vì nghĩ chắc không sao.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:48:55', '2026-07-06 21:48:55'),
(4952, 833, 'reflection', '{\"question\": \"Bạn có quy tắc nào khi tương tác với những người bạn chỉ quen biết qua mạng không?\"}', 5, '2026-07-06 21:48:55', '2026-07-06 21:48:55'),
(4953, 833, 'takeaway', '{\"items\": [\"Không có Robux hay món quà mạng nào xứng đáng để bạn đánh đổi bằng sự an toàn cơ thể.\"]}', 6, '2026-07-06 21:48:55', '2026-07-06 21:48:55'),
(4954, 834, 'hook', '{\"title\": \"Sự khác biệt giữa một bí mật vui vẻ và một bí mật độc hại là gì?\"}', 1, '2026-07-06 21:48:56', '2026-07-06 21:48:56'),
(4955, 834, 'explanation', '{\"bullets\": [\"Bí mật vui vẻ (như chuẩn bị quà sinh nhật bất ngờ) làm bạn thấy vui, háo hức và không gây hại cho ai.\", \"Bí mật độc hại (như giấu bố mẹ về đụng chạm cơ thể) làm bạn thấy lo âu, nặng nề, sợ hãi và có cảm giác tội lỗi.\", \"Kẻ dụ dỗ rất sợ ánh sáng của sự thật. Việc vạch trần bí mật độc hại sẽ tước đi sức mạnh của chúng.\"]}', 2, '2026-07-06 21:48:56', '2026-07-06 21:48:56'),
(4956, 834, 'scenario', '{\"title\": \"Tình huống bí mật\", \"body\": \"Người anh họ lớn tuổi rủ Vy chơi trò đụng chạm nhạy cảm và dặn: \\\"Đây là bí mật giữa hai anh em mình nhé. Nếu em kể cho bố mẹ nghe, họ sẽ ghét em và đuổi em ra khỏi nhà đấy\\\". Vy vô cùng hoảng sợ và hàng đêm đều gặp ác mộng nhưng không dám hé răng nửa lời.\"}', 3, '2026-07-06 21:48:56', '2026-07-06 21:48:56'),
(4957, 834, 'interaction', '{\"question\": \"Vy nên phân loại bí mật này như thế nào và hành động ra sao?\", \"choices\": [{\"text\": \"Đây là bí mật độc hại. Vy cần nói ngay với mẹ hoặc gọi Tổng đài 111 để được bảo vệ an toàn.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Đây là bí mật gia đình nên Vy phải giữ kín để không làm ảnh hưởng đến tình cảm họ hàng.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-06 21:48:56', '2026-07-06 21:48:56'),
(4958, 834, 'reflection', '{\"question\": \"Bạn đang có bí mật nào làm bạn thấy nặng nề trong lòng mỗi khi nghĩ về nó không?\"}', 5, '2026-07-06 21:48:56', '2026-07-06 21:48:56'),
(4959, 834, 'takeaway', '{\"items\": [\"Bí mật độc hại giống như một gánh nặng, hãy chia sẻ nó với người lớn tin cậy để vứt bỏ gánh nặng đó đi.\"]}', 6, '2026-07-06 21:48:56', '2026-07-06 21:48:56'),
(4960, 835, 'hook', '{\"title\": \"Bạn có bao giờ cảm thấy mình mắc nợ ai đó chỉ vì nhận từ họ một sự giúp đỡ nhỏ?\"}', 1, '2026-07-06 21:48:56', '2026-07-06 21:48:56'),
(4961, 835, 'explanation', '{\"bullets\": [\"Kẻ thao túng thường gieo vào đầu bạn tâm lý mắc nợ bằng cách chiều chuộng, bao che lỗi lầm hoặc tặng quà cho bạn.\", \"Khi bạn đã quen với việc nhận lợi ích, chúng sẽ bắt đầu đòi hỏi bạn phải đáp ứng những yêu cầu vô lý.\", \"Hãy học cách từ chối những món quà từ người lạ hoặc những sự giúp đỡ đi kèm yêu cầu giữ bí mật.\"]}', 2, '2026-07-06 21:48:56', '2026-07-06 21:48:56'),
(4962, 835, 'scenario', '{\"title\": \"Tình huống nhận quà\", \"body\": \"Minh trốn học đi chơi net và bị một anh khóa trên phát hiện. Anh ấy không mách cô giáo, lại còn trả tiền nét hộ Minh và bảo: \\\"Anh em mình cùng hội cùng thuyền, anh bao che cho chú thì chú cũng phải biết điều nhé\\\". Hôm sau, anh ấy yêu cầu Minh mang hộ một gói đồ lạ đến địa điểm khác.\"}', 3, '2026-07-06 21:48:56', '2026-07-06 21:48:56'),
(4963, 835, 'interaction', '{\"question\": \"Minh nên ứng phó thế nào trước yêu cầu của anh khóa trên?\", \"choices\": [{\"text\": \"Nhận lời mang đồ hộ vì lỡ mang ơn anh ấy đã bao che và trả tiền nét hộ mình.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Từ chối thẳng thắn, tự nhận lỗi trốn học với cô giáo và chấm dứt liên lạc với anh khóa trên.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:48:56', '2026-07-06 21:48:56'),
(4964, 835, 'reflection', '{\"question\": \"Bạn có nghĩ rằng việc tự nhận lỗi lầm của mình đôi khi lại là cách tốt nhất để không bị người khác tống tiền không?\"}', 5, '2026-07-06 21:48:56', '2026-07-06 21:48:56'),
(4965, 835, 'takeaway', '{\"items\": [\"Đừng để lòng tốt giả tạo biến bạn thành con rối trong tay kẻ thao túng.\"]}', 6, '2026-07-06 21:48:56', '2026-07-06 21:48:56'),
(4966, 836, 'hook', '{\"title\": \"Làm sao để phân biệt một người tốt thực sự và một kẻ đang cố dụ dỗ bạn?\"}', 1, '2026-07-06 21:48:56', '2026-07-06 21:48:56'),
(4967, 836, 'explanation', '{\"bullets\": [\"Người tốt thực sự sẽ tôn trọng ranh giới của bạn, không bắt bạn làm điều uncomfy, và không yêu cầu bạn giữ bí mật độc hại.\", \"Kẻ dụ dỗ luôn muốn lấn dần ranh giới của bạn và bắt bạn phải đánh đổi bằng sự riêng tư hoặc cơ thể của mình.\", \"Hãy giữ sự tỉnh táo và luôn nhớ rằng: Bạn không nợ bất cứ ai sự đụng chạm hay đính ước cơ thể nào cả.\"]}', 2, '2026-07-06 21:48:56', '2026-07-06 21:48:56'),
(4968, 836, 'scenario', '{\"title\": \"Tình huống so sánh\", \"body\": \"Vy có hai người anh họ. Anh Sơn thường dạy Vy học bài, mỗi khi Vy mệt anh đều bảo Vy nghỉ ngơi và nhắc Vy kể chuyện học tập cho bố mẹ nghe. Anh Lâm thì thường rủ Vy vào phòng riêng chơi game, hay khóa cửa lại và bảo Vy đừng kể cho ai biết hai anh em chơi gì.\"}', 3, '2026-07-06 21:48:56', '2026-07-06 21:48:56'),
(4969, 836, 'interaction', '{\"question\": \"Ai là người đang thể hiện những hành vi đáng ngờ (Red Flags) cần cảnh giác?\", \"choices\": [{\"text\": \"Anh Lâm, vì anh ấy tạo không gian kín và bắt giữ bí mật, đây là các dấu hiệu của giai đoạn cô lập trong Grooming.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Anh Sơn, vì anh ấy bắt học bài mệt mỏi quá.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-06 21:48:57', '2026-07-06 21:48:57'),
(4970, 836, 'reflection', '{\"question\": \"Xung quanh bạn có ai luôn khuyến khích bạn cởi mở và chia sẻ mọi thứ với bố mẹ không?\"}', 5, '2026-07-06 21:48:57', '2026-07-06 21:48:57'),
(4971, 836, 'takeaway', '{\"items\": [\"Người yêu thương bạn thật lòng sẽ luôn bảo vệ sự an toàn và sự minh bạch của bạn.\"]}', 6, '2026-07-06 21:48:57', '2026-07-06 21:48:57'),
(4972, 837, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Mặt nạ của kẻ dụ dỗ\'! Hãy cùng lột mặt nạ các hành vi thao túng tinh vi nhé.\"}', 1, '2026-07-06 21:48:57', '2026-07-06 21:48:57'),
(4973, 837, 'scenario-choice', '{\"title\": \"Bẫy Robux trên mạng\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Một người bạn quen trên game Discord tặng bạn rất nhiều vật phẩm VIP và Robux. Sau đó, anh ấy nhắn tin: \'Anh tặng quà em rồi, giờ em bật cam phòng ngủ lên cho anh xem em thay quần áo nhé\'.\", \"choices\": [{\"text\": \"Bật cam làm theo vì sợ anh ấy đòi lại quà và khóa nick game.\", \"nextNode\": \"fail_submit\"}, {\"text\": \"Từ chối thẳng thừng, tắt camera và chặn ngay tài khoản đó.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Kẻ xấu dùng một tài khoản clone khác gửi ảnh avatar của bạn và đe dọa: \'Tao biết mặt mày rồi, không gửi ảnh nudes tao sẽ đăng lên group trường\'.\", \"choices\": [{\"text\": \"Hoảng sợ gửi ảnh sang để xoa dịu kẻ tống tiền.\", \"nextNode\": \"fail_guilt\"}, {\"text\": \"Chụp màn hình làm bằng chứng, báo ngay với bố mẹ hoặc gọi Tổng đài 111 cứu trợ.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã dũng cảm chặn đứng hành vi online grooming và tìm kiếm sự bảo vệ đúng cách từ người lớn.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_submit\": {\"text\": \"❌ Thất bại! Nhượng bộ yêu cầu nhạy cảm vì vật phẩm ảo sẽ đưa bạn vào bẫy xâm hại trực tuyến cực kỳ nguy hiểm.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_guilt\": {\"text\": \"❌ Thất bại! Gửi ảnh nhạy cảm khi bị đe dọa chỉ khiến kẻ xấu có thêm bằng chứng để tống tiền bạn nặng nề hơn.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-06 21:48:57', '2026-07-06 21:48:57'),
(4974, 837, 'sorting', '{\"instruction\": \"Hãy phân loại các hành vi sau của đối phương:\", \"leftBox\": {\"title\": \"Lòng tốt lành mạnh (Green Flag)\"}, \"rightBox\": {\"title\": \"Dấu hiệu dụ dỗ (Red Flag)\"}, \"items\": [{\"text\": \"Hỏi han việc học tập và khuyên chia sẻ với bố mẹ\", \"correctBox\": \"left\"}, {\"text\": \"Tặng quà đắt tiền và bắt giữ bí mật giữa hai người\", \"correctBox\": \"right\"}, {\"text\": \"Tôn trọng khi bạn từ chối một cuộc hẹn riêng tư\", \"correctBox\": \"left\"}, {\"text\": \"Nói xấu bố mẹ bạn để khuyên bạn không nghe lời họ\", \"correctBox\": \"right\"}]}', 3, '2026-07-06 21:48:57', '2026-07-06 21:48:57'),
(4975, 837, 'matching', '{\"instruction\": \"Ghép cặp các khái niệm về hành vi dụ dỗ sau:\", \"pairs\": [{\"left\": \"Grooming\", \"right\": \"Quá trình xây dựng lòng tin giả tạo để xâm hại\"}, {\"left\": \"Cô lập\", \"right\": \"Tách người trẻ ra khỏi gia đình và bạn bè\"}, {\"left\": \"Sextortion\", \"right\": \"Tống tiền bằng hình ảnh nhạy cảm thu thập được\"}, {\"left\": \"Bí mật độc hại\", \"right\": \"Bí mật làm bạn lo âu, nặng nề, sợ hãi\"}]}', 4, '2026-07-06 21:48:57', '2026-07-06 21:48:57'),
(4976, 837, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về online grooming:\", \"sentence\": \"Kẻ dụ dỗ trực tuyến thường dùng [blank1] game hoặc quà tặng làm mồi nhử. Chúng luôn yêu cầu bạn giữ [blank2] về mối quan hệ. Khi gặp nguy hiểm, hãy lập tức [blank3] tài khoản và báo cho người lớn tin cậy.\", \"blanks\": {\"blank1\": {\"correct\": \"thẻ nạp\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"bí mật\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"chặn\", \"placeholder\": \"...\"}}, \"words\": [\"thẻ nạp\", \"bí mật\", \"chặn\", \"công khai\", \"đồng ý\", \"kết bạn\"]}', 5, '2026-07-06 21:48:57', '2026-07-06 21:48:57'),
(4977, 837, 'interaction', '{\"question\": \"Đâu là nhận định chính xác nhất về các bí mật trong các mối quan hệ?\", \"choices\": [{\"text\": \"Bí mật làm bạn cảm thấy lo âu, tội lỗi và sợ kể với bố mẹ luôn là bí mật độc hại cần được vạch trần.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Đã là bí mật thì phải giữ trọn lời hứa, kể cả khi nó làm mình thấy sợ hãi hay uncomfy.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-06 21:48:57', '2026-07-06 21:48:57'),
(4978, 838, 'hook', '{\"title\": \"Bạn có nghĩ xâm hại chỉ xảy ra khi có bạo lực thể xác?\"}', 1, '2026-07-06 21:48:57', '2026-07-06 21:48:57'),
(4979, 838, 'explanation', '{\"bullets\": [\"Xâm hại (Abuse) là bất kỳ hành vi nào gây tổn thương cố ý cho người khác, tồn tại dưới nhiều hình thức:\", \"**Thể chất:** Đánh đập, giật tóc, tát tai.\", \"**Tinh thần:** Chửi bới, miệt thị, cô lập, đe dọa tâm lý.\", \"**Tình dục:** Đụng chạm vùng kín, nhìn trộm, ép xem ảnh/phim nhạy cảm.\", \"Tất cả các hình thức xâm hại đều để lại những vết thương lòng sâu sắc và cần được ngăn chặn.\"]}', 2, '2026-07-06 21:48:57', '2026-07-06 21:48:57'),
(4980, 838, 'scenario', '{\"title\": \"Tình huống bắt nạt\", \"body\": \"Mỗi ngày đến lớp, Linh đều bị một nhóm bạn cùng lớp gọi bằng những biệt danh xúc phạm ngoại hình và giới tính. Các bạn còn lập nhóm chat riêng để đăng ảnh chế giễu Linh. Linh cảm thấy vô cùng trầm uất, sợ hãi mỗi khi tiếng trống trường vang lên.\"}', 3, '2026-07-06 21:48:57', '2026-07-06 21:48:57'),
(4981, 838, 'interaction', '{\"question\": \"Hành vi của nhóm bạn cùng lớp đối với Linh được xếp vào loại xâm hại nào?\", \"choices\": [{\"text\": \"Xâm hại tinh thần và bắt nạt học đường.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Chỉ là đùa nghịch học sinh trêu nhau bình thường, không có gì nghiêm trọng.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:48:58', '2026-07-06 21:48:58'),
(4982, 838, 'reflection', '{\"question\": \"Bạn đã bao giờ chứng kiến ai đó bị cô lập hoặc chế giễu liên tục ở trường chưa?\"}', 5, '2026-07-06 21:48:58', '2026-07-06 21:48:58'),
(4983, 838, 'takeaway', '{\"items\": [\"Tổn thương tinh thần cũng đau đớn như tổn thương thể chất, và không ai có quyền gây ra nó cho bạn.\"]}', 6, '2026-07-06 21:48:58', '2026-07-06 21:48:58'),
(4984, 839, 'hook', '{\"title\": \"Liệu những người bằng tuổi chúng ta có thể gây ra xâm hại tình dục cho nhau không?\"}', 1, '2026-07-06 21:48:58', '2026-07-06 21:48:58'),
(4985, 839, 'explanation', '{\"bullets\": [\"**COCSA** (Child-on-child sexual abuse - Xâm hại tình dục giữa trẻ em với nhau) là một thực tế có xảy ra.\", \"Nhiều bạn trẻ lầm tưởng rằng chỉ người lớn mới có thể xâm hại trẻ em.\", \"Bạn bè cùng tuổi ép buộc bạn đụng chạm vùng kín, ép xem nội dung người lớn hoặc phát tán ảnh riêng tư của bạn đều là hành vi xâm hại nghiêm trọng.\"]}', 2, '2026-07-06 21:48:58', '2026-07-06 21:48:58'),
(4986, 839, 'scenario', '{\"title\": \"Tình huống trong trại hè\", \"body\": \"Trong phòng ngủ tập thể nam của trại hè, một nhóm học sinh lớp 8 ép Khánh (lớp 7) phải cởi quần áo để tụi nó quay video TikTok đùa nghịch. Khánh khóc lóc van xin nhưng nhóm bạn vẫn cười cợt và khóa cửa phòng lại.\"}', 3, '2026-07-06 21:48:58', '2026-07-06 21:48:58'),
(4987, 839, 'interaction', '{\"question\": \"Khánh nên làm gì ngay sau khi thoát khỏi phòng ngủ đó?\", \"choices\": [{\"text\": \"Im lặng chịu đựng vì sợ bị nhóm bạn đó tẩy chay và trả thù ở trường.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Báo ngay lập tức với thầy cô quản lý trại hè hoặc bố mẹ để yêu cầu xóa video và xử lý hành vi bắt nạt.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:48:58', '2026-07-06 21:48:58'),
(4988, 839, 'reflection', '{\"question\": \"Bạn có nghĩ rằng việc giữ im lặng khi thấy bạn bè bị bắt nạt tình dục là đang vô tình tiếp tay cho kẻ xấu?\"}', 5, '2026-07-06 21:48:58', '2026-07-06 21:48:58'),
(4989, 839, 'takeaway', '{\"items\": [\"Dù bằng tuổi hay lớn tuổi, không ai có quyền ép buộc bạn làm những trò đụng chạm nhạy cảm.\"]}', 6, '2026-07-06 21:48:58', '2026-07-06 21:48:58'),
(4990, 840, 'hook', '{\"title\": \"Bạn có từng nghĩ: \'Chắc tại mình ăn mặc như vậy/đi chơi muộn nên mới bị sàm sỡ\'?\"}', 1, '2026-07-06 21:48:58', '2026-07-06 21:48:58'),
(4991, 840, 'explanation', '{\"bullets\": [\"Tự trách bản thân (Self-blame) là phản ứng tâm lý cực kỳ phổ biến của nạn nhân sau khi bị xâm hại.\", \"Xã hội đôi khi cũng vô tình phán xét nạn nhân (Victim-blaming) làm tăng thêm nỗi đau của họ.\", \"Hãy nhớ rõ nguyên tắc tối cao: **Lỗi luôn thuộc về kẻ thực hiện hành vi xâm hại, 100%.**\", \"Không có cách ăn mặc, hành vi hay địa điểm nào có thể hợp thức hóa hành vi xâm hại của kẻ xấu.\"]}', 2, '2026-07-06 21:48:58', '2026-07-06 21:48:58');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(4992, 840, 'scenario', '{\"title\": \"Tình huống tự trách\", \"body\": \"Vy đi học nhóm về muộn lúc 8 giờ tối và mặc một chiếc váy ngắn. Trên đường vắng, Vy bị một gã say rượu chạy xe qua sàm sỡ vòng 1. Vy về nhà khóc nức nở và tự dằn vặt: \\\"Tại mình mặc váy ngắn đi chơi muộn, mình hư hỏng nên mới bị như vậy\\\".\"}', 3, '2026-07-06 21:48:58', '2026-07-06 21:48:58'),
(4993, 840, 'interaction', '{\"question\": \"Nếu Vy là bạn thân của bạn và tâm sự điều này, bạn sẽ nói gì với Vy?\", \"choices\": [{\"text\": \"\'Cậu không có lỗi gì cả. Lỗi hoàn toàn thuộc về gã sàm sỡ kia. Việc cậu mặc váy đi học về muộn là hoàn toàn bình thường\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"\'Thôi từ sau nhớ mặc quần dài đi học nhé, con gái mặc thế nguy hiểm là phải\'.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:48:58', '2026-07-06 21:48:58'),
(4994, 840, 'reflection', '{\"question\": \"Bạn nghĩ gì về những ý kiến cho rằng nạn nhân bị xâm hại là do lỗi ăn mặc của họ?\"}', 5, '2026-07-06 21:48:58', '2026-07-06 21:48:58'),
(4995, 840, 'takeaway', '{\"items\": [\"Bạn xứng đáng được an toàn trong mọi trang phục, ở mọi thời điểm. Lỗi không bao giờ ở phía bạn.\"]}', 6, '2026-07-06 21:48:59', '2026-07-06 21:48:59'),
(4996, 841, 'hook', '{\"title\": \"Khi một câu đùa làm bạn thấy nhột nhạt và xấu hổ, đó có thực sự là một trò đùa?\"}', 1, '2026-07-06 21:48:59', '2026-07-06 21:48:59'),
(4997, 841, 'explanation', '{\"bullets\": [\"Nhiều bạn trẻ dùng các từ ngữ nhạy cảm, trêu chọc về vòng 1, vòng 3 hoặc kích thước cơ thể của bạn bè để làm trò đùa.\", \"Đây được gọi là quấy rối tình dục bằng lời nói (Verbal harassment).\", \"Bạn hoàn toàn có quyền phản đối và yêu cầu dừng lại ngay lập tức mà không cần phải giả vờ cười hùa theo.\"]}', 2, '2026-07-06 21:48:59', '2026-07-06 21:48:59'),
(4998, 841, 'scenario', '{\"title\": \"Tình huống ở lớp\", \"body\": \"Trong giờ thể dục, Nam nhảy lên đập bóng thì bị tuột áo ngoài. Một nhóm bạn nam đứng cười rú lên và trêu chọc về cơ thể Nam bằng những từ ngữ rất thô tục. Nam thấy đỏ mặt xấu hổ và chỉ muốn chui xuống đất.\"}', 3, '2026-07-06 21:48:59', '2026-07-06 21:48:59'),
(4999, 841, 'interaction', '{\"question\": \"Nam nên làm gì để phản đối trò đùa kém duyên này?\", \"choices\": [{\"text\": \"Nhìn thẳng vào nhóm bạn, nói giọng nghiêm túc: \'Trò này không vui đâu, dừng lại đi\' rồi mặc áo vào đi chỗ khác.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Cười hùa theo các bạn để tỏ ra mình là người phóng khoáng, dễ tính.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:48:59', '2026-07-06 21:48:59'),
(5000, 841, 'reflection', '{\"question\": \"Bạn đã bao giờ vô ý hùa theo một câu đùa nhạy cảm làm tổn thương bạn học chưa?\"}', 5, '2026-07-06 21:48:59', '2026-07-06 21:48:59'),
(5001, 841, 'takeaway', '{\"items\": [\"Đùa vui chỉ có giá trị khi nó tôn trọng sự tự tôn và ranh giới của tất cả mọi người.\"]}', 6, '2026-07-06 21:48:59', '2026-07-06 21:48:59'),
(5002, 842, 'hook', '{\"title\": \"Tại sao kẻ xâm hại luôn muốn bạn phải giữ im lặng?\"}', 1, '2026-07-06 21:48:59', '2026-07-06 21:48:59'),
(5003, 842, 'explanation', '{\"bullets\": [\"Kẻ xấu sử dụng nỗi sợ hãi, sự xấu hổ và những lời đe dọa để bắt nạn nhân im lặng.\", \"Sự im lặng chính là lá chắn bảo vệ tốt nhất của kẻ xâm hại để chúng tiếp tục làm hại người khác.\", \"Lên tiếng chia sẻ với người lớn đáng tin cậy là cách bạn đập tan lá chắn đó và bảo vệ bản thân lẫn bạn bè xung quanh.\"]}', 2, '2026-07-06 21:48:59', '2026-07-06 21:48:59'),
(5004, 842, 'scenario', '{\"title\": \"Tình huống đe dọa\", \"body\": \"Một bạn học sinh cá biệt lớp 9 ép Minh (lớp 7) phải nộp tiền tiêu vặt hàng tuần, nếu không sẽ bị chặn đường đánh sau giờ học. Bạn ấy dọa: \\\"Mày mà mách cô giáo hay bố mẹ thì tao sẽ xử đẹp cả nhà mày!\\\". Minh vô cùng lo sợ và định âm thầm chịu đựng.\"}', 3, '2026-07-06 21:48:59', '2026-07-06 21:48:59'),
(5005, 842, 'interaction', '{\"question\": \"Minh nên làm gì trước lời đe dọa này?\", \"choices\": [{\"text\": \"Bí mật kể ngay sự việc cho bố mẹ hoặc thầy cô chủ nhiệm để nhận sự bảo vệ an toàn.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tiếp tục trộm tiền của bố mẹ nộp cho bạn kia để gia đình không bị ảnh hưởng.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-06 21:48:59', '2026-07-06 21:48:59'),
(5006, 842, 'reflection', '{\"question\": \"Nếu bạn phát hiện bạn thân của mình đang bị đe dọa giữ im lặng, bạn sẽ giúp bạn ấy thế nào?\"}', 5, '2026-07-06 21:48:59', '2026-07-06 21:48:59'),
(5007, 842, 'takeaway', '{\"items\": [\"Lên tiếng không phải là mách lẻo, đó là sự dũng cảm để bảo vệ công lý và sự an toàn.\"]}', 6, '2026-07-06 21:48:59', '2026-07-06 21:48:59'),
(5008, 843, 'hook', '{\"title\": \"Bạn có chắc ranh giới cá nhân của mình đang được thiết lập đúng cách?\"}', 1, '2026-07-06 21:49:00', '2026-07-06 21:49:00'),
(5009, 843, 'explanation', '{\"bullets\": [\"Đôi khi ranh giới của chúng ta quá lỏng lẻo (dễ bị người khác ép buộc) hoặc quá cứng nhắc (cô lập bản thân).\", \"Tự soi ranh giới giúp bạn nhận ra những mối quan hệ nào đang làm bạn thấy mệt mỏi và bất an.\", \"Hãy lắng nghe cảm xúc của mình sau mỗi cuộc giao tiếp để điều chỉnh ranh giới cho phù hợp.\"]}', 2, '2026-07-06 21:49:00', '2026-07-06 21:49:00'),
(5010, 843, 'scenario', '{\"title\": \"Tình huống tự vấn\", \"body\": \"Vy nhận thấy mỗi lần đi chơi với nhóm bạn, Vy đều phải trả tiền nước hộ cho cả nhóm vì các bạn hay nói: \\\"Vy giàu thế, trả hộ tụi mình đi!\\\". Vy thấy rất bất công và tiếc tiền tiêu vặt, nhưng sợ nếu từ chối sẽ bị nhóm bạn tẩy chay không rủ đi chơi nữa.\"}', 3, '2026-07-06 21:49:00', '2026-07-06 21:49:00'),
(5011, 843, 'interaction', '{\"question\": \"Vy đang gặp vấn đề gì với ranh giới của mình?\", \"choices\": [{\"text\": \"Vy đang có ranh giới quá lỏng lẻo vì sợ bị ghét mà chấp nhận để người khác lợi dụng tài chính.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Vy đang quá ích kỷ, bạn bè đi chơi với nhau không nên tính toán chi li vài đồng bạc.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:49:00', '2026-07-06 21:49:00'),
(5012, 843, 'reflection', '{\"question\": \"Bạn có mối quan hệ nào đang làm bạn cảm thấy mệt mỏi vì phải nhượng bộ ranh giới liên tục không?\"}', 5, '2026-07-06 21:49:00', '2026-07-06 21:49:00'),
(5013, 843, 'takeaway', '{\"items\": [\"Bảo vệ ranh giới của mình không phải là ích kỷ, đó là cách bạn dạy người khác cách tôn trọng bạn.\"]}', 6, '2026-07-06 21:49:00', '2026-07-06 21:49:00'),
(5014, 844, 'hook', '{\"title\": \"Dù chuyện gì xảy ra đi nữa, bạn có tin mình luôn xứng đáng được bảo vệ?\"}', 1, '2026-07-06 21:49:00', '2026-07-06 21:49:00'),
(5015, 844, 'explanation', '{\"bullets\": [\"Kẻ xấu thường đổ lỗi cho nạn nhân để trốn trách nhiệm pháp luật và đạo đức.\", \"Dù bạn có lỡ tin người, lỡ đi chơi muộn, hay lỡ nhận quà, hành vi xâm hại của kẻ xấu vẫn là hoàn toàn sai trái.\", \"Bạn không bao giờ phải chịu trách nhiệm cho hành vi độc hại của người khác. Bạn hoàn toàn vô tội.\"]}', 2, '2026-07-06 21:49:00', '2026-07-06 21:49:00'),
(5016, 844, 'scenario', '{\"title\": \"Tình huống chia sẻ\", \"body\": \"Sau khi dũng cảm kể cho mẹ nghe việc bị chú họ sàm sỡ, mẹ An lại thở dài mắng: \\\"Tại con cứ hay mặc quần đùi chạy loăng quăng trước mặt chú đấy chứ!\\\". An sụp đổ hoàn toàn và nghĩ mình thực sự là đứa trẻ tội lỗi.\"}', 3, '2026-07-06 21:49:00', '2026-07-06 21:49:00'),
(5017, 844, 'interaction', '{\"question\": \"An nên làm gì để tìm kiếm sự khẳng định đúng đắn cho bản thân lúc này?\", \"choices\": [{\"text\": \"Gọi ngay đến Tổng đài Quốc gia Bảo vệ Trẻ em 111 để được các chuyên gia lắng nghe, tư vấn và bảo vệ tâm lý một cách khoa học, khách quan.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tin vào lời mẹ mắng và chấp nhận việc bị chú sàm sỡ như một hình phạt cho lỗi lầm của mình.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-06 21:49:00', '2026-07-06 21:49:00'),
(5018, 844, 'reflection', '{\"question\": \"Làm thế nào để chúng ta giúp bạn bè của mình rũ bỏ cảm giác tự trách sau khi gặp chuyện không hay?\"}', 5, '2026-07-06 21:49:00', '2026-07-06 21:49:00'),
(5019, 844, 'takeaway', '{\"items\": [\"Linh hồn và cơ thể bạn là thánh đường, kẻ xâm phạm thánh đường đó mới là kẻ có tội.\"]}', 6, '2026-07-06 21:49:00', '2026-07-06 21:49:00'),
(5020, 845, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Gọi tên những tình huống bất ổn\'! Hãy cùng đập tan chiếc hộp im lặng độc hại.\"}', 1, '2026-07-06 21:49:01', '2026-07-06 21:49:01'),
(5021, 845, 'scenario-choice', '{\"title\": \"Lời đồn thổi độc hại\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn phát hiện một bạn nam lớp bên chụp lén bạn lúc học thể dục rồi đăng lên group chat nam sinh kèm những lời bình phẩm khiếm nhã về cơ thể bạn.\", \"choices\": [{\"text\": \"Im lặng chịu đựng, tự trách mình vì hôm đó mặc quần hơi ngắn.\", \"nextNode\": \"fail_submit\"}, {\"text\": \"Chụp màn hình bằng chứng, rủ một bạn học đi cùng lên báo cáo với thầy cô Ban giám hiệu.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Bạn nam chụp lén nhắn tin đe dọa: \'Liệu thần hồn, mày mách thầy cô tao sẽ bảo cả trường tẩy chay mày là đồ méo mó\'.\", \"choices\": [{\"text\": \"Hoảng sợ rút lại báo cáo và xin lỗi bạn nam kia.\", \"nextNode\": \"fail_guilt\"}, {\"text\": \"Kiên định giữ nguyên báo cáo, gửi tin nhắn đe dọa mới cho thầy cô giáo xử lý hành vi bắt nạt.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã biết cách tự bảo vệ trước quấy rối tình dục học đường và không để sự đổ lỗi hay đe dọa làm chùn bước.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_submit\": {\"text\": \"❌ Thất bại! Tự đổ lỗi cho bản thân (self-blame) chỉ tiếp tay cho kẻ quấy rối tiếp tục hành vi sai trái.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_guilt\": {\"text\": \"❌ Thất bại! Nhượng bộ trước đe dọa tẩy chay học đường sẽ làm bạn tiếp tục bị bắt nạt lâu dài.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-06 21:49:01', '2026-07-06 21:49:01'),
(5022, 845, 'sorting', '{\"instruction\": \"Hãy phân loại các hành vi học đường sau:\", \"leftBox\": {\"title\": \"Xâm hại/Bắt nạt\"}, \"rightBox\": {\"title\": \"Trêu đùa lành mạnh\"}, \"items\": [{\"text\": \"Ép bạn xem phim nhạy cảm trên điện thoại\", \"correctBox\": \"left\"}, {\"text\": \"Khen kiểu tóc mới của bạn một cách lịch sự\", \"correctBox\": \"right\"}, {\"text\": \"Lập nhóm tẩy chay, miệt thị giới tính bạn học\", \"correctBox\": \"left\"}, {\"text\": \"Cùng cười đùa vui vẻ về một meme mèo ngộ nghĩnh\", \"correctBox\": \"right\"}]}', 3, '2026-07-06 21:49:01', '2026-07-06 21:49:01'),
(5023, 845, 'matching', '{\"instruction\": \"Ghép cặp các hình thức xâm hại sau với biểu hiện của chúng:\", \"pairs\": [{\"left\": \"Xâm hại Thể chất\", \"right\": \"Đánh đập, xô đẩy gây thương tích cho cơ thể\"}, {\"left\": \"Xâm hại Tinh thần\", \"right\": \"Cô lập, chửi bới, đe dọa làm tổn thương tâm lý\"}, {\"left\": \"Xâm hại Tình dục\", \"right\": \"Đụng chạm vùng nhạy cảm, ép xem ảnh khiêu dâm\"}, {\"left\": \"COCSA\", \"right\": \"Xâm hại tình dục xảy ra giữa trẻ em với nhau\"}]}', 4, '2026-07-06 21:49:01', '2026-07-06 21:49:01'),
(5024, 845, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về trách nhiệm trong xâm hại:\", \"sentence\": \"Khi xảy ra hành vi xâm hại, lỗi luôn thuộc về kẻ [blank1] 100%. Nạn nhân hoàn toàn [blank2]. Việc [blank3] tiếng chia sẻ sẽ giúp bảo vệ chính bạn và cộng đồng.\", \"blanks\": {\"blank1\": {\"correct\": \"xâm hại\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"vô tội\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"lên\", \"placeholder\": \"...\"}}, \"words\": [\"xâm hại\", \"vô tội\", \"lên\", \"nạn nhân\", \"im lặng\", \"có lỗi\"]}', 5, '2026-07-06 21:49:01', '2026-07-06 21:49:01'),
(5025, 845, 'interaction', '{\"question\": \"Khi chứng kiến một bạn học đang bị nhóm học sinh khác ép đụng chạm nhạy cảm dưới nhà xe, hành động văn minh nhất của bạn là gì?\", \"choices\": [{\"text\": \"Không cười hùa theo, lập tức chạy đi gọi thầy cô giám thị hoặc người lớn gần đó cứu trợ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Đứng xem, dùng điện thoại quay clip lại để đăng lên mạng xã hội câu like.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-06 21:49:01', '2026-07-06 21:49:01'),
(5026, 846, 'hook', '{\"title\": \"Tại sao khi gặp nguy hiểm, có người lại đứng chôn chân một chỗ không thể động đậy?\"}', 1, '2026-07-06 21:49:01', '2026-07-06 21:49:01'),
(5027, 846, 'explanation', '{\"bullets\": [\"Khi đối mặt với đe dọa cực độ, não bộ sẽ tự động kích hoạt hệ thống phòng vệ khẩn cấp:\", \"**Chiến (Fight):** Chống trả quyết liệt (hét to, đẩy ra, đánh trả).\", \"**Biến (Flight):** Chạy trốn thật nhanh đến nơi an toàn.\", \"**Đơ (Freeze):** Cơ thể tê cứng, đầu óc trống rỗng, không thể phát ra tiếng động.\", \"Đây là những phản ứng sinh học tự nhiên, không phải là sự hèn nhát hay đồng ý.\"]}', 2, '2026-07-06 21:49:01', '2026-07-06 21:49:01'),
(5028, 846, 'scenario', '{\"title\": \"Tình huống bất ngờ\", \"body\": \"Vy đang đi bộ trong ngõ tối thì một người đàn ông lạ mặt lao ra ôm chặt lấy cô bé từ phía sau và sờ soạng. Vy muốn hét lên kêu cứu và vùng vẫy chạy trốn, nhưng toàn thân cô bé bỗng tê cứng, miệng không thể mở ra, nước mắt chỉ chực trào ra.\"}', 3, '2026-07-06 21:49:01', '2026-07-06 21:49:01'),
(5029, 846, 'interaction', '{\"question\": \"Vy đang trải qua phản ứng sinh học nào của não bộ trong tình huống nguy hiểm này?\", \"choices\": [{\"text\": \"Phản ứng \'Đơ\'\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Vy đang đồng ý và muốn hợp tác với gã lạ mặt nên mới không chống trả.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:49:01', '2026-07-06 21:49:01'),
(5030, 846, 'reflection', '{\"question\": \"Khi gặp một tình huống giật mình sợ hãi, cơ thể bạn thường phản ứng theo xu hướng nào?\"}', 5, '2026-07-06 21:49:01', '2026-07-06 21:49:01'),
(5031, 846, 'takeaway', '{\"items\": [\"Dù cơ thể phản ứng theo cách nào, hãy nhớ rằng đó là cơ chế tự bảo vệ tự động của não bộ.\"]}', 6, '2026-07-06 21:49:01', '2026-07-06 21:49:01'),
(5032, 847, 'hook', '{\"title\": \"Nếu một người không chống cự khi bị xâm hại, liệu đó có được coi là họ đã đồng thuận?\"}', 1, '2026-07-06 21:49:01', '2026-07-06 21:49:01'),
(5033, 847, 'explanation', '{\"bullets\": [\"Kẻ xấu thường bào chữa: \\\"Nó có phản đối hay kêu cứu gì đâu nên tôi tưởng nó thích\\\".\", \"Trong luật pháp và khoa học hành vi, phản ứng \\\"Đơ\\\" (Freeze) tuyệt đối không bao giờ được coi là sự đồng thuận.\", \"Sự im lặng do hoảng sợ khác hoàn toàn với sự đồng ý tự nguyện và hào hứng.\"]}', 2, '2026-07-06 21:49:02', '2026-07-06 21:49:02'),
(5034, 847, 'scenario', '{\"title\": \"Tình huống tự bào chữa\", \"body\": \"Trong buổi thảo luận nhóm, một bạn nam phát biểu: \\\"Tớ thấy mấy bạn nữ bị sàm sỡ trên xe bus mà cứ đứng im re thì chắc cũng thích chứ có gì đâu phải làm quá lên\\\". Cả lớp im lặng ngơ ngác trước phát ngôn của bạn.\"}', 3, '2026-07-06 21:49:02', '2026-07-06 21:49:02'),
(5035, 847, 'interaction', '{\"question\": \"Bạn sẽ phản biện lại ý kiến của bạn nam đó như thế nào cho thuyết phục?\", \"choices\": [{\"text\": \"Giải thích về phản ứng \'Đơ\'\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Mắng bạn ấy là đồ tồi và cấm bạn ấy không được phát biểu linh tinh nữa.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:49:02', '2026-07-06 21:49:02'),
(5036, 847, 'reflection', '{\"question\": \"Làm thế nào để phổ biến kiến thức về phản ứng \'Đơ\' (Freeze) rộng rãi hơn trong trường học?\"}', 5, '2026-07-06 21:49:02', '2026-07-06 21:49:02'),
(5037, 847, 'takeaway', '{\"items\": [\"Im lặng vì sợ hãi là tiếng hét câm lặng của sự từ chối.\"]}', 6, '2026-07-06 21:49:02', '2026-07-06 21:49:02'),
(5038, 848, 'hook', '{\"title\": \"Bạn có dám tố cáo kẻ xấu khi chúng đe dọa sẽ làm hại gia đình bạn nếu bạn nói ra?\"}', 1, '2026-07-06 21:49:02', '2026-07-06 21:49:02'),
(5039, 848, 'explanation', '{\"bullets\": [\"Đe dọa trả thù là vũ khí tâm lý mạnh nhất của kẻ xâm hại để ép bạn im lặng.\", \"Chúng muốn bạn tin rằng chúng có quyền lực tuyệt đối và không ai có thể bảo vệ bạn.\", \"Nhưng thực tế, kẻ xấu luôn sợ hãi pháp luật và sự can thiệp của người lớn. Khi bạn lên tiếng đúng chỗ, chúng sẽ mất đi quyền lực thao túng.\"]}', 2, '2026-07-06 21:49:02', '2026-07-06 21:49:02'),
(5040, 848, 'scenario', '{\"title\": \"Tình huống đe dọa\", \"body\": \"Minh bị một nhóm học sinh cá biệt lớp bên bắt nộp tiền bảo kê. Nhóm này dọa: \\\"Nếu mày hé răng với thầy cô, tụi tao sẽ chặn đường đánh gãy chân mày và đến phá nhà mày luôn!\\\". Minh vô cùng hoảng sợ và không dám đi học nữa.\"}', 3, '2026-07-06 21:49:02', '2026-07-06 21:49:02'),
(5041, 848, 'interaction', '{\"question\": \"Minh nên tin vào điều gì để vượt qua nỗi sợ hãi này?\", \"choices\": [{\"text\": \"Tin rằng nhà trường và lực lượng công an, gia đình hoàn toàn có đủ khả năng bảo vệ Minh an toàn trước nhóm bắt nạt nếu Minh lên tiếng.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tin lời đe dọa của nhóm kia và tiếp tục trốn học ở nhà để tự bảo vệ.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-06 21:49:02', '2026-07-06 21:49:02'),
(5042, 848, 'reflection', '{\"question\": \"Bạn nghĩ ai là người có đủ thẩm quyền và năng lực bảo vệ bạn tốt nhất khi bạn bị đe dọa?\"}', 5, '2026-07-06 21:49:02', '2026-07-06 21:49:02'),
(5043, 848, 'takeaway', '{\"items\": [\"Sự dũng cảm của bạn kết hợp với sự bảo vệ của pháp luật là khắc tinh của mọi kẻ bắt nạt.\"]}', 6, '2026-07-06 21:49:02', '2026-07-06 21:49:02'),
(5044, 849, 'hook', '{\"title\": \"Bạn sẽ làm gì nếu nhận ra có một kẻ lạ mặt đang lặng lẽ đi theo mình qua nhiều con phố?\"}', 1, '2026-07-06 21:49:02', '2026-07-06 21:49:02'),
(5045, 849, 'explanation', '{\"bullets\": [\"Khi nhận ra mình bị bám đuôi, hãy giữ bình tĩnh và áp dụng ngay các quy tắc sống còn:\", \"**Không đi về nhà:** Tránh để kẻ xấu biết địa chỉ nhà bạn nếu xung quanh vắng vẻ.\", \"**Tìm nơi đông người:** Ghé ngay vào đồn công an, cửa hàng tiện lợi, siêu thị hoặc quán ăn đông khách.\", \"**Tạo sự chú ý:** Gọi điện cho người thân, nói to như thể bạn sắp gặp họ, hoặc hét to nhờ trợ giúp.\"]}', 2, '2026-07-06 21:49:02', '2026-07-06 21:49:02'),
(5046, 849, 'scenario', '{\"title\": \"Tình huống bám đuôi\", \"body\": \"Trên đường đi học thêm về lúc 9 giờ tối, Mai nhận ra một người đàn ông đi xe máy tắt đèn đang từ từ bám theo mình qua các ngõ vắng. Đường về nhà Mai còn khoảng 500m nữa nhưng rất tối và ít nhà mở cửa.\"}', 3, '2026-07-06 21:49:02', '2026-07-06 21:49:02'),
(5047, 849, 'interaction', '{\"question\": \"Mai nên chọn hướng di chuyển nào an toàn nhất lúc này?\", \"choices\": [{\"text\": \"Ghé ngay vào một cửa hàng tạp hóa sáng đèn có đông người đứng mua hàng bên đường, gọi điện cho bố ra đón.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Cố gắng chạy thật nhanh về nhà mình dù ngõ tối và vắng người.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-06 21:49:02', '2026-07-06 21:49:02'),
(5048, 849, 'reflection', '{\"question\": \"Trên lộ trình đi học hàng ngày của bạn, đâu là những \'điểm sáng an toàn\' mà bạn có thể ghé vào nếu gặp nguy hiểm?\"}', 5, '2026-07-06 21:49:02', '2026-07-06 21:49:02'),
(5049, 849, 'takeaway', '{\"items\": [\"Khi bị bám đuôi, hãy hướng về phía ánh sáng và đám đông.\"]}', 6, '2026-07-06 21:49:03', '2026-07-06 21:49:03'),
(5050, 850, 'hook', '{\"title\": \"Hét \'Cứu tôi với!\' ở nơi đông người có thực sự mang lại sự trợ giúp tốt nhất?\"}', 1, '2026-07-06 21:49:03', '2026-07-06 21:49:03'),
(5051, 850, 'explanation', '{\"bullets\": [\"Khi bạn gặp nguy hiểm ở nơi công cộng, đám đông thường có tâm lý e ngại can thiệp vào \\\"việc riêng\\\" của người khác (hiệu ứng người ngoài cuộc).\", \"Để phá vỡ hiệu ứng này, hãy kêu cứu một cách cụ thể: chỉ đích danh một người, hoặc hét to những từ khóa gây chú ý mạnh như: \\\"Cháy!\\\" hoặc \\\"Bắt cóc!\\\" hoặc \\\"Tôi không quen người này!\\\".\"]}', 2, '2026-07-06 21:49:03', '2026-07-06 21:49:03'),
(5052, 850, 'scenario', '{\"title\": \"Tình huống quấy rối\", \"body\": \"Tại trạm xe buýt đông người, một gã đàn ông nắm chặt cổ tay An và kéo đi, vờ quát mắng: \\\"Vợ chồng cãi nhau chút thôi, đi về nhà ngay!\\\". Mọi người xung quanh nhìn vào tưởng là cặp đôi cãi nhau nên không ai can thiệp. An vô cùng hoảng loạn.\"}', 3, '2026-07-06 21:49:03', '2026-07-06 21:49:03'),
(5053, 850, 'interaction', '{\"question\": \"An nên hét lớn câu nào để nhận được sự trợ giúp từ mọi người xung quanh hiệu quả nhất?\", \"choices\": [{\"text\": \"\'Cứu tôi với! Bỏ tôi ra!\'.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"\'Tôi không quen người này! Kẻ cướp! Bắt cóc! Chú áo xanh kia ơi cứu cháu với!\'.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-06 21:49:03', '2026-07-06 21:49:03'),
(5054, 850, 'reflection', '{\"question\": \"Bạn có tự tin mình có thể phát ra một tiếng hét thật lớn khi gặp tình huống khẩn cấp không?\"}', 5, '2026-07-06 21:49:03', '2026-07-06 21:49:03'),
(5055, 850, 'takeaway', '{\"items\": [\"Kêu cứu thông minh là phải làm rõ mối nguy hiểm và chỉ đích danh sự trợ giúp.\"]}', 6, '2026-07-06 21:49:03', '2026-07-06 21:49:03'),
(5056, 851, 'hook', '{\"title\": \"Làm sao để thoát khỏi trạng thái tê liệt toàn thân khi nỗi sợ hãi ập đến bất ngờ?\"}', 1, '2026-07-06 21:49:03', '2026-07-06 21:49:03'),
(5057, 851, 'explanation', '{\"bullets\": [\"Phản ứng \\\"Đơ\\\" (Freeze) xảy ra khi hormone cortisol và adrenaline tràn ngập bộ não làm tê liệt hệ thần kinh vận động.\", \"Để phá vỡ trạng thái này, hãy tập trung vào các hành động vật lý nhỏ nhất: chớp mắt liên tục, ngọ nguậy ngón chân, hoặc hít một hơi thật sâu để kích hoạt lại hệ thần kinh.\", \"Chỉ cần một cử động nhỏ được thực hiện, cơ thể bạn sẽ dần lấy lại quyền kiểm soát để hành động.\"]}', 2, '2026-07-06 21:49:03', '2026-07-06 21:49:03'),
(5058, 851, 'scenario', '{\"title\": \"Tình huống đứng hình\", \"body\": \"Nam đang ngồi trong rạp chiếu phim tối thì phát hiện người ngồi ghế bên cạnh đang luồn tay qua khe ghế để sờ đùi mình. Nam bị sốc nặng, toàn thân cứng đờ, không thể đẩy tay gã đó ra hay đứng lên chuyển ghế.\"}', 3, '2026-07-06 21:49:03', '2026-07-06 21:49:03'),
(5059, 851, 'interaction', '{\"question\": \"Nam nên làm gì đầu tiên để tự giải thoát mình khỏi trạng thái đông cứng này?\", \"choices\": [{\"text\": \"Cố gắng hít một hơi thật sâu, bấm mạnh ngón tay vào lòng bàn tay để lấy lại cảm giác, rồi đứng bật dậy di chuyển ra chỗ nhân viên rạp.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tiếp tục nhắm mắt chịu đựng và cầu nguyện cho bộ phim nhanh kết thúc.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-06 21:49:03', '2026-07-06 21:49:03'),
(5060, 851, 'reflection', '{\"question\": \"Bạn đã bao giờ trải qua cảm giác muốn nói gì đó nhưng cổ họng nghẹn ứ lại không thể phát ra tiếng chưa?\"}', 5, '2026-07-06 21:49:03', '2026-07-06 21:49:03'),
(5061, 851, 'takeaway', '{\"items\": [\"Một cử động nhỏ nhất cũng có thể đánh thức cơ thể bạn khỏi cơn đông cứng của nỗi sợ.\"]}', 6, '2026-07-06 21:49:03', '2026-07-06 21:49:03'),
(5062, 852, 'hook', '{\"title\": \"Bạn có sẵn sàng mang tiếng là \'kẻ bất lịch sự\' để bảo vệ bản thân khỏi nguy hiểm?\"}', 1, '2026-07-06 21:49:04', '2026-07-06 21:49:04'),
(5063, 852, 'explanation', '{\"bullets\": [\"Chúng ta thường được dạy phải luôn tỏ ra lịch sự, nhẹ nhàng và tôn trọng người lớn tuổi.\", \"Nhưng trong những tình huống ranh giới bị đe dọa, sự lịch sự có thể trở thành cái bẫy hại bạn.\", \"Hãy nhớ rõ: **Bạn có quyền bất lịch sự, nói to, đẩy người khác ra hoặc bỏ chạy** khi cảm thấy bất an.\", \"Sự an toàn của bạn luôn là ưu tiên số một, không có ngoại lệ.\"]}', 2, '2026-07-06 21:49:04', '2026-07-06 21:49:04'),
(5064, 852, 'scenario', '{\"title\": \"Tình huống tiễn khách\", \"body\": \"Một người bạn của bố mẹ đến chơi nhà và xin phép vào phòng riêng của Linh để xem máy tính. Khi vào phòng, chú đóng cửa lại và có những lời khen ngợi cơ thể Linh một cách nhạy cảm. Linh thấy sợ và muốn đuổi chú ra ngoài nhưng sợ bố mẹ mắng là vô lễ.\"}', 3, '2026-07-06 21:49:04', '2026-07-06 21:49:04'),
(5065, 852, 'interaction', '{\"question\": \"Linh nên hành xử thế nào để bảo vệ bản thân hiệu quả nhất?\", \"choices\": [{\"text\": \"Mở toang cửa phòng, nói to: \'Cháu xin lỗi, cháu cần dọn phòng để học bài ạ!\' rồi chủ động bước ra phòng khách với bố mẹ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Ngồi im trả lời gượng gạo để giữ lịch sự cho khách của bố mẹ.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-06 21:49:04', '2026-07-06 21:49:04'),
(5066, 852, 'reflection', '{\"question\": \"Bạn có sẵn sàng la hét hoặc đẩy một người lớn ra nếu họ cố tình đụng chạm vào vùng nhạy cảm của bạn không?\"}', 5, '2026-07-06 21:49:04', '2026-07-06 21:49:04'),
(5067, 852, 'takeaway', '{\"items\": [\"Khi ranh giới bị xâm phạm, hãy vứt bỏ sự lịch sự và kích hoạt lá chắn tự vệ.\"]}', 6, '2026-07-06 21:49:04', '2026-07-06 21:49:04'),
(5068, 853, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Phản ứng nhanh khi gặp nguy\'! Cùng thực hành phản xạ tự vệ khẩn cấp nào.\"}', 1, '2026-07-06 21:49:04', '2026-07-06 21:49:04'),
(5069, 853, 'scenario-choice', '{\"title\": \"Gặp kẻ quấy rối ở ngõ vắng\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn đang đi bộ trong ngõ vắng thì một gã đàn ông lạ đi bộ ngược chiều đột ngột lao đến ôm chầm lấy bạn và sàm sỡ. Toàn thân bạn bỗng đông cứng (Freeze) không thể di chuyển hay hét lên.\", \"choices\": [{\"text\": \"Cố chịu đựng vì nghĩ cơ thể mình đã bất lực rồi.\", \"nextNode\": \"fail_submit\"}, {\"text\": \"Tập trung nhúc nhích ngón chân, hít sâu để phá vỡ cơn đơ, dùng hết sức bấm mạnh vào người gã sàm sỡ để thoát ra.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Bạn thoát ra được và gã kia bắt đầu đuổi theo. Phía trước có một ngã ba: bên trái là ngõ tối dẫn về nhà bạn, bên phải là đường lộ lớn sáng đèn có quán ăn đêm.\", \"choices\": [{\"text\": \"Chạy vào ngõ tối bên trái để về nhà cho nhanh.\", \"nextNode\": \"fail_guilt\"}, {\"text\": \"Chạy sang bên phải ra đường lớn đông người, hét to \'Cháy nhà! Bắt cóc!\' để mọi người chú ý giúp đỡ.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã phá vỡ phản ứng đơ thành công, chọn hướng chạy thoát thông minh và kêu cứu hiệu quả.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_submit\": {\"text\": \"❌ Thất bại! Đầu hàng phản ứng đơ sinh học sẽ khiến bạn gặp nguy hiểm lớn. Hãy tập trung đánh thức cơ thể bằng hành động nhỏ.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_guilt\": {\"text\": \"❌ Thất bại! Chạy vào ngõ tối vắng vẻ khi bị đuổi theo sẽ khiến bạn mất đi cơ hội nhận sự trợ giúp của đám đông.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-06 21:49:04', '2026-07-06 21:49:04'),
(5070, 853, 'sorting', '{\"instruction\": \"Hãy phân loại các phản ứng sinh học khẩn cấp của cơ thể:\", \"leftBox\": {\"title\": \"Phản ứng chủ động (Fight / Flight)\"}, \"rightBox\": {\"title\": \"Phản ứng đông cứng (Freeze)\"}, \"items\": [{\"text\": \"Chạy thật nhanh ra chỗ đông người kêu cứu\", \"correctBox\": \"left\"}, {\"text\": \"Toàn thân tê cứng, miệng nghẹn cứng không nói được\", \"correctBox\": \"right\"}, {\"text\": \"Dùng balo đập mạnh vào kẻ xấu để thoát thân\", \"correctBox\": \"left\"}, {\"text\": \"Đầu óc trống rỗng, chôn chân tại chỗ vì sốc\", \"correctBox\": \"right\"}]}', 3, '2026-07-06 21:49:04', '2026-07-06 21:49:04'),
(5071, 853, 'matching', '{\"instruction\": \"Ghép cặp các phương án ứng phó khẩn cấp sau:\", \"pairs\": [{\"left\": \"Bị bám đuôi\", \"right\": \"Di chuyển ngay vào cửa hàng tạp hóa đông người\"}, {\"left\": \"Bị sàm sỡ nơi đông người\", \"right\": \"Hét to \'Tôi không quen người này\' để chỉ rõ mối nguy\"}, {\"left\": \"Cơ thể bị đông cứng\", \"right\": \"Hít sâu, bấm ngón tay để lấy lại vận động\"}, {\"left\": \"Kẻ xấu dọa trả thù\", \"right\": \"Không sợ hãi, báo ngay cho người lớn tin cậy\"}]}', 4, '2026-07-06 21:49:04', '2026-07-06 21:49:04'),
(5072, 853, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về kêu cứu khẩn cấp:\", \"sentence\": \"Khi gặp hiểm họa nơi đông người, hãy hét lớn những từ nhạy cảm như [blank1] để phá vỡ sự e ngại của đám đông. Luôn nhớ rằng an toàn của bạn quan trọng hơn sự [blank2] xã giao. Hãy [blank3] thoát bằng mọi giá.\", \"blanks\": {\"blank1\": {\"correct\": \"bắt cóc\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"lịch sự\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"chạy\", \"placeholder\": \"...\"}}, \"words\": [\"bắt cóc\", \"lịch sự\", \"chạy\", \"cưới xin\", \"im lặng\", \"đứng yên\"]}', 5, '2026-07-06 21:49:04', '2026-07-06 21:49:04'),
(5073, 853, 'interaction', '{\"question\": \"Nếu bị kẻ lạ sàm sỡ trên xe bus đông đúc, phản ứng nào giúp bạn an toàn nhất?\", \"choices\": [{\"text\": \"Quay lại nói to: \'Chú bỏ tay ra, cháu không cho phép chú đụng vào cháu!\' rồi di chuyển lại gần tài xế.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Âm thầm chịu đựng vì ngại mọi người đổ dồn ánh mắt về phía mình.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-06 21:49:04', '2026-07-06 21:49:04'),
(5074, 854, 'hook', '{\"title\": \"Tại sao sau khi thoát khỏi tình huống nguy hiểm, chúng ta lại cảm thấy trống rỗng hoặc khóc lóc vô cớ?\"}', 1, '2026-07-06 21:49:05', '2026-07-06 21:49:05'),
(5075, 854, 'explanation', '{\"bullets\": [\"Trải qua một vụ xâm hại hoặc bắt nạt giống như việc bạn vừa đi qua một cơn bão lớn.\", \"Cảm xúc của bạn sau đó sẽ rất hỗn loạn: giận dữ, xấu hổ, buồn bã, sợ hãi, hoặc trống rỗng (tê liệt cảm xúc).\", \"Tất cả những phản ứng này đều hoàn toàn bình thường và hợp lệ. Cơ thể và tâm trí bạn cần thời gian để tiêu hóa chấn thương.\"]}', 2, '2026-07-06 21:49:05', '2026-07-06 21:49:05'),
(5076, 854, 'scenario', '{\"title\": \"Tình huống sau sự cố\", \"body\": \"Sau khi bị một nhóm bạn trêu chọc và đụng chạm thô bạo ở trường, An đã về nhà an toàn. Tuy nhiên, suốt cả tuần sau đó, An không thể tập trung học, hay cáu gắt với bố mẹ và bỗng dưng bật khóc nức nở khi đang ăn cơm. Bố mẹ trách An dạo này bướng bỉnh, khó chiều.\"}', 3, '2026-07-06 21:49:05', '2026-07-06 21:49:05'),
(5077, 854, 'interaction', '{\"question\": \"Bạn nhận định thế nào về trạng thái tâm lý của An lúc này?\", \"choices\": [{\"text\": \"An đang trải qua những phản ứng tâm lý bình thường sau chấn thương\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"An đang làm quá lên để thu hút sự chú ý của mọi người.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:49:05', '2026-07-06 21:49:05'),
(5078, 854, 'reflection', '{\"question\": \"Khi tâm trạng cực kỳ tồi tệ, điều gì hoặc ai có thể giúp bạn thấy bình yên trở lại?\"}', 5, '2026-07-06 21:49:05', '2026-07-06 21:49:05'),
(5079, 854, 'takeaway', '{\"items\": [\"Cảm xúc hỗn loạn là dấu hiệu cho thấy tâm hồn bạn đang tự tìm cách chữa lành.\"]}', 6, '2026-07-06 21:49:05', '2026-07-06 21:49:05'),
(5080, 855, 'hook', '{\"title\": \"Nếu ranh giới cơ thể bị xâm phạm nghiêm trọng (xâm hại tình dục), hành động y tế khẩn cấp nào cần được thực hiện ngay?\"}', 1, '2026-07-06 21:49:05', '2026-07-06 21:49:05'),
(5081, 855, 'explanation', '{\"bullets\": [\"Trong trường hợp bị xâm hại tình dục nghiêm trọng, việc tìm kiếm sự hỗ trợ y tế trong vòng **72 giờ đầu tiên** là cực kỳ quan trọng (Quy tắc vàng).\", \"Điều này giúp:\", \"Ngăn ngừa mang thai ngoài ý muốn bằng thuốc tránh thai khẩn cấp.\", \"Điều trị dự phòng phơi nhiễm HIV (PEP) và các bệnh lây truyền qua đường tình dục (STIs).\", \"Thu thập bằng chứng pháp y để bảo vệ bạn trước pháp luật.\", \"Hãy đến ngay bệnh viện hoặc trung tâm y tế gần nhất cùng một người lớn đáng tin cậy.\"]}', 2, '2026-07-06 21:49:05', '2026-07-06 21:49:05'),
(5082, 855, 'scenario', '{\"title\": \"Tình huống khẩn cấp\", \"body\": \"Vy bị một kẻ xấu xâm hại tình dục trên đường đi học thêm về. Vy vô cùng hoảng sơ, về nhà tắm rửa sạch sẽ và trùm chăn khóc vì xấu hổ. Bạn thân của Vy biết chuyện và khuyên Vy nên đi khám bác sĩ ngay, nhưng Vy sợ mọi người biết chuyện sẽ dị nghị.\"}', 3, '2026-07-06 21:49:05', '2026-07-06 21:49:05'),
(5083, 855, 'interaction', '{\"question\": \"Lời khuyên nào dưới đây là khoa học và giúp bảo vệ Vy tốt nhất lúc này?\", \"choices\": [{\"text\": \"Vy cần vượt qua nỗi sợ, cùng người thân đến bệnh viện sản phụ khoa hoặc trung tâm y tế trong vòng 72 giờ để uống thuốc tránh thai khẩn cấp và điều trị dự phòng phơi nhiễm.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Vy cứ ở nhà nghỉ ngơi, tắm rửa thật sạch là mọi chuyện sẽ tự ổn thỏa.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:49:05', '2026-07-06 21:49:05'),
(5084, 855, 'reflection', '{\"question\": \"Bạn có biết địa chỉ của bệnh viện hoặc trung tâm y tế quận/huyện nơi mình đang sinh sống không?\"}', 5, '2026-07-06 21:49:05', '2026-07-06 21:49:05'),
(5085, 855, 'takeaway', '{\"items\": [\"Sức khỏe thể chất của bạn là vô giá, hãy hành động nhanh chóng để bảo vệ nó trong mọi tình huống.\"]}', 6, '2026-07-06 21:49:05', '2026-07-06 21:49:05'),
(5086, 856, 'hook', '{\"title\": \"Tại sao nhiều người trẻ chọn cách im lặng gặm nhấm nỗi đau thay vì kể cho người thân nghe?\"}', 1, '2026-07-06 21:49:05', '2026-07-06 21:49:05'),
(5087, 856, 'explanation', '{\"bullets\": [\"Nỗi sợ hãi lớn nhất của nạn nhân là: sợ bị đổ lỗi (Victim-blaming), sợ làm gia đình thất vọng, sợ bị trả thù, hoặc xấu hổ vì nghĩ mình không còn \\\"sạch sẽ\\\".\", \"Việc mở lời kể lại một trải nghiệm tồi tệ yêu cầu một sự dũng cảm phi thường.\", \"Hãy tạo ra một môi trường không phán xét để những người xung quanh bạn cảm thấy an tâm khi chia sẻ.\"]}', 2, '2026-07-06 21:49:05', '2026-07-06 21:49:05'),
(5088, 856, 'scenario', '{\"title\": \"Tình huống e ngại\", \"body\": \"Linh bị một thầy giáo dạy thêm đụng chạm vòng 1. Linh muốn kể cho mẹ nghe nhưng nhớ lại lần trước mẹ từng mắng một chị hàng xóm bị sàm sỡ là: \\\"Chắc do ăn mặc lăng loàn nên nó mới làm thế\\\". Linh sợ mẹ cũng sẽ nói mình như vậy nên quyết định giấu kín.\"}', 3, '2026-07-06 21:49:06', '2026-07-06 21:49:06'),
(5089, 856, 'interaction', '{\"question\": \"Điều gì đã cản trở Linh chia sẻ sự việc với mẹ?\", \"choices\": [{\"text\": \"Nỗi sợ bị mẹ đổ lỗi và phán xét dựa trên những định kiến cũ của mẹ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Linh không muốn kể vì thực chất Linh cũng thích hành vi của thầy giáo.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:49:06', '2026-07-06 21:49:06'),
(5090, 856, 'reflection', '{\"question\": \"Nếu một người bạn thân tìm đến kể cho bạn một bí mật khủng khiếp, bạn sẽ phản ứng thế nào đầu tiên?\"}', 5, '2026-07-06 21:49:06', '2026-07-06 21:49:06'),
(5091, 856, 'takeaway', '{\"items\": [\"Lắng nghe không phán xét là món quà quý giá nhất bạn có thể tặng cho một tâm hồn đang bị tổn thương.\"]}', 6, '2026-07-06 21:49:06', '2026-07-06 21:49:06'),
(5092, 857, 'hook', '{\"title\": \"Bạn sẽ làm gì khi một người bạn khóc nức nở và nói: \'Tớ vừa bị người ta sàm sỡ\'?\"}', 1, '2026-07-06 21:49:06', '2026-07-06 21:49:06'),
(5093, 857, 'explanation', '{\"bullets\": [\"Khi bạn bè chọn bạn để tâm sự chuyện bị xâm hại, đó là vì họ cực kỳ tin tưởng bạn.\", \"Nhiệm vụ của bạn không phải là làm thám tử điều tra, cũng không phải đưa ra những lời khuyên đao to búa lớn.\", \"Việc quan trọng nhất là **khẳng định sự an toàn của bạn**, lắng nghe và đồng cảm.\"]}', 2, '2026-07-06 21:49:06', '2026-07-06 21:49:06'),
(5094, 857, 'scenario', '{\"title\": \"Tình huống bạn thân\", \"body\": \"Vy hẹn Trang ra quán trà sữa, Vy khóc nấc lên và kể việc bị một người anh họ ép đụng chạm vùng kín. Vy run rẩy nói: \\\"Tớ sợ lắm, tớ không dám nói với ai đâu, cậu đừng kể cho ai nhé\\\". Trang thấy rất bối rối và lo lắng cho Vy.\"}', 3, '2026-07-06 21:49:06', '2026-07-06 21:49:06'),
(5095, 857, 'interaction', '{\"question\": \"Trang nên phản ứng thế nào để giúp Vy tốt nhất lúc này?\", \"choices\": [{\"text\": \"Ôm Vy, nói: \'Tớ luôn ở đây với cậu. Đó hoàn toàn không phải lỗi của cậu. Chúng mình cùng tìm cách giải quyết nhé\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Hỏi dồn dập: \'Ở đâu? Lúc nào? Sao cậu không hét lên? Cậu có tự nguyện không đấy?\'.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:49:06', '2026-07-06 21:49:06'),
(5096, 857, 'reflection', '{\"question\": \"Bạn có sẵn sàng làm một bờ vai im lặng lắng nghe bạn bè khóc mà không ngắt lời họ không?\"}', 5, '2026-07-06 21:49:06', '2026-07-06 21:49:06'),
(5097, 857, 'takeaway', '{\"items\": [\"Bạn không cần phải có mọi câu trả lời, chỉ cần sự hiện diện ấm áp của bạn là đủ.\"]}', 6, '2026-07-06 21:49:06', '2026-07-06 21:49:06'),
(5098, 858, 'hook', '{\"title\": \"Làm sao để lắng nghe một cách văn minh mà không vô tình sát muối vào vết thương của đối phương?\"}', 1, '2026-07-06 21:49:06', '2026-07-06 21:49:06'),
(5099, 858, 'explanation', '{\"bullets\": [\"Hãy áp dụng nguyên tắc **3 KHÔNG** khi lắng nghe nạn nhân của xâm hại:\", \"**Không đổ lỗi:** Tuyệt đối không hỏi những câu hỏi bắt đầu bằng \\\"Tại sao bạn không...\\\" (Tại sao không chạy? Tại sao mặc váy đó?).\", \"**Không đánh giá cảm xúc:** Không nói những câu như \\\"Có gì đâu mà khóc mãi thế\\\" hay \\\"Phải mạnh mẽ lên chứ\\\".\", \"**Không tự ý hành động:** Không tự ý đi trả thù hay phát tán câu chuyện của bạn khi chưa có sự đồng ý của họ.\"]}', 2, '2026-07-06 21:49:07', '2026-07-06 21:49:07'),
(5100, 858, 'scenario', '{\"title\": \"Tình huống lắng nghe\", \"body\": \"Nam tâm sự với Khoa việc mình bị một nhóm anh khóa trên trấn lột tiền và bắt quỳ gối xin lỗi ở nhà vệ sinh. Nam thấy rất nhục nhã và yếu đuối. Khoa nghe xong liền bảo: \\\"Sao yếu thế? Đàn ông con trai phải đấm lại tụi nó chứ, quỳ thế hèn lắm!\\\". Nam lầm lũi bỏ về và quyết định từ nay không kể gì với Khoa nữa.\"}', 3, '2026-07-06 21:49:07', '2026-07-06 21:49:07'),
(5101, 858, 'interaction', '{\"question\": \"Khoa đã mắc sai lầm gì trong kỹ năng lắng nghe ở đây?\", \"choices\": [{\"text\": \"Khoa đã đánh giá cảm xúc và áp đặt khuôn mẫu giới\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Khoa không sai vì Khoa đang muốn khuyên Nam dũng cảm tự vệ bảo vệ bản thân thôi.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:49:07', '2026-07-06 21:49:07'),
(5102, 858, 'reflection', '{\"question\": \"Bạn đã từng vô tình đưa ra một lời khuyên có tính chất phán xét cảm xúc của người khác chưa?\"}', 5, '2026-07-06 21:49:07', '2026-07-06 21:49:07'),
(5103, 858, 'takeaway', '{\"items\": [\"Lắng nghe không phán xét là chấp nhận cảm xúc của đối phương như nó vốn có, không cố sửa chữa hay đánh giá.\"]}', 6, '2026-07-06 21:49:07', '2026-07-06 21:49:07'),
(5104, 859, 'hook', '{\"title\": \"Bạn có sẵn sàng lên tiếng bảo vệ một bạn học đang bị đồn thổi ác ý về chuyện nhạy cảm?\"}', 1, '2026-07-06 21:49:07', '2026-07-06 21:49:07'),
(5105, 859, 'explanation', '{\"bullets\": [\"Trở thành đồng minh (Ally) sau xâm hại nghĩa là bạn đứng về phía nạn nhân, giúp họ chống lại những lời đồn thổi ác ý và sự cô lập của đám đông.\", \"Đồng minh tinh tế không cần làm những việc quá to tát, chỉ cần từ chối tham gia vào các cuộc bàn tán, chặn các tin đồn phát tán, và rủ bạn ấy cùng tham gia các hoạt động bình thường.\"]}', 2, '2026-07-06 21:49:07', '2026-07-06 21:49:07'),
(5106, 859, 'scenario', '{\"title\": \"Tình huống đồn thổi\", \"body\": \"Trong trường rộ lên tin đồn Vy bị một người đàn ông lạ mặt sàm sỡ ở công viên và có những bình luận chế giễu Vy trên group chat lớp. Vy đi học với khuôn mặt cúi gằm, không ai dám ngồi cạnh hay nói chuyện với Vy vì sợ bị liên lụy.\"}', 3, '2026-07-06 21:49:07', '2026-07-06 21:49:07'),
(5107, 859, 'interaction', '{\"question\": \"Là một người bạn học văn minh, bạn nên hành động thế nào để làm đồng minh của Vy?\", \"choices\": [{\"text\": \"Chủ động xuống ngồi cạnh Vy trong giờ học, rủ Vy đi ăn trưa và nhắn tin nhắc nhở các bạn trong group chat dừng việc đùa cợt vô duyên lại.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tránh xa Vy ra để không bị các bạn khác hiểu lầm là mình cũng đồng lõa hoặc có liên quan.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:49:07', '2026-07-06 21:49:07'),
(5108, 859, 'reflection', '{\"question\": \"Bạn có dám đứng lên phản đối một trò đùa độc hại của nhóm bạn thân để bảo vệ một bạn học khác không?\"}', 5, '2026-07-06 21:49:07', '2026-07-06 21:49:07'),
(5109, 859, 'takeaway', '{\"items\": [\"Một đồng minh dũng cảm là người dám dùng sự tử tế để đẩy lùi sự kỳ thị của đám đông.\"]}', 6, '2026-07-06 21:49:07', '2026-07-06 21:49:07'),
(5110, 860, 'hook', '{\"title\": \"Bạn có nghĩ chấn thương tâm lý sẽ biến mất hoàn toàn sau một đêm?\"}', 1, '2026-07-06 21:49:07', '2026-07-06 21:49:07'),
(5111, 860, 'explanation', '{\"bullets\": [\"Hành trình chữa lành (Healing) không phải là một đường thẳng đi lên, mà là một dòng chảy có lúc thăng lúc trầm.\", \"Có những ngày bạn thấy rất ổn, nhưng đột nhiên một mùi hương, một âm thanh hay một hình ảnh quen thuộc có thể kích hoạt lại nỗi sợ hãi (Trigger).\", \"Hãy dịu dàng với bản thân, cho phép mình có những ngày yếu đuối và tiếp tục kiên nhẫn bước đi. Bạn đang tốt lên mỗi ngày.\"]}', 2, '2026-07-06 21:49:07', '2026-07-06 21:49:07'),
(5112, 860, 'scenario', '{\"title\": \"Tình huống tái phát\", \"body\": \"Đã 3 tháng kể từ ngày bị kẻ xấu quấy rối ở ngõ tối, Linh tưởng mình đã hoàn toàn bình thường. Nhưng hôm nay, khi đi học về gặp một người đàn ông mặc áo khoác đen giống kẻ quấy rối năm xưa, Linh bỗng thấy tim đập nghẹt thở, chân tay bủn rủn và bật khóc nức nở ngay giữa đường. Linh thấy thất vọng về bản thân vì nghĩ mình vẫn yếu đuối.\"}', 3, '2026-07-06 21:49:07', '2026-07-06 21:49:07'),
(5113, 860, 'interaction', '{\"question\": \"Linh nên nghĩ thế nào về phản ứng này của cơ thể mình?\", \"choices\": [{\"text\": \"Đây là phản ứng kích hoạt chấn thương\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Linh thực sự là kẻ yếu đuối vô dụng, đã 3 tháng rồi mà vẫn không thể vượt qua được chuyện nhỏ nhặt đó.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-06 21:49:07', '2026-07-06 21:49:07'),
(5114, 860, 'reflection', '{\"question\": \"Có điều gì trong quá khứ từng làm bạn rất đau lòng nhưng giờ bạn đã có thể mỉm cười kể lại không?\"}', 5, '2026-07-06 21:49:08', '2026-07-06 21:49:08'),
(5115, 860, 'takeaway', '{\"items\": [\"Chữa lành cần thời gian, và mỗi vết sẹo đều là huy chương của sự kiên cường trong bạn.\"]}', 6, '2026-07-06 21:49:08', '2026-07-06 21:49:08'),
(5116, 861, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Chữa lành & Đồng hành\'! Hãy cùng sưởi ấm những trái tim tổn thương bằng sự tử tế.\"}', 1, '2026-07-06 21:49:08', '2026-07-06 21:49:08'),
(5117, 861, 'scenario-choice', '{\"title\": \"Bờ vai của bạn thân\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn thân gặp bạn khóc nức nở kể việc bị một người anh họ ép đụng chạm nhạy cảm. Bạn ấy sợ hãi cầu xin: \'Cậu đừng kể cho ai nhé, tớ sợ bố mẹ mắng lắm\'.\", \"choices\": [{\"text\": \"Hứa tuyệt đối giữ bí mật và bảo bạn: \'Thôi coi như tai nạn, quên nó đi cậu\'.\", \"nextNode\": \"fail_submit\"}, {\"text\": \"Ôm bạn an ủi: \'Tớ luôn ở đây với cậu. Nhưng chuyện này rất nguy hiểm, tớ và cậu cùng tìm một người lớn đáng tin giúp đỡ nhé\'.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Bạn đồng ý nhưng không muốn nói với bố mẹ bạn ấy. Bạn đề xuất nói với cô giáo tâm lý học đường.\", \"choices\": [{\"text\": \"Tự ý gọi điện mách bố mẹ bạn ấy ngay lập tức để trốn trách nhiệm.\", \"nextNode\": \"fail_guilt\"}, {\"text\": \"Đồng hành cùng bạn đến gặp cô giáo tâm lý trường, giữ đúng lời hứa không tự ý phát tán câu chuyện.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã trở thành một đồng minh vô cùng tinh tế, biết cách xoa dịu chấn thương và tìm sự hỗ trợ chuyên nghiệp an toàn.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_submit\": {\"text\": \"❌ Thất bại! Giữ im lặng trước hành vi xâm hại tình dục liên tục sẽ khiến bạn của bạn tiếp tục bị lạm dụng trong tương lai.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_guilt\": {\"text\": \"❌ Thất bại! Tự ý phá vỡ thỏa thuận chia sẻ của bạn mà không có sự chuẩn bị sẽ làm mất lòng tin và khiến bạn ấy hoảng loạn cô độc.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-06 21:49:08', '2026-07-06 21:49:08'),
(5118, 861, 'sorting', '{\"instruction\": \"Hãy phân loại thái độ ứng xử khi lắng nghe nạn nhân xâm hại:\", \"leftBox\": {\"title\": \"Xoa dịu (Đồng minh xịn)\"}, \"rightBox\": {\"title\": \"Sát muối (Độc hại)\"}, \"items\": [{\"text\": \"Khẳng định: \'Đó hoàn toàn không phải lỗi của cậu đâu\'\", \"correctBox\": \"left\"}, {\"text\": \"Gặng hỏi: \'Tại sao lúc đó cậu không hét lên hay đẩy ra?\'\", \"correctBox\": \"right\"}, {\"text\": \"Lắng nghe yên lặng, nắm tay hoặc ôm an ủi bạn\", \"correctBox\": \"left\"}, {\"text\": \"Nhận xét: \'Con gái con lứa đi chơi muộn thế bị thế là phải\'\", \"correctBox\": \"right\"}]}', 3, '2026-07-06 21:49:08', '2026-07-06 21:49:08'),
(5119, 861, 'matching', '{\"instruction\": \"Ghép cặp các cột mốc quan trọng trong quá trình phục hồi sau xâm hại:\", \"pairs\": [{\"left\": \"72 giờ đầu\", \"right\": \"Quy tắc vàng để điều trị y tế khẩn cấp, ngừa PEP/STIs\"}, {\"left\": \"Tránh tắm rửa/thay đồ\", \"right\": \"Cách giữ lại dấu vết pháp y quan trọng khi bị tấn công\"}, {\"left\": \"Trigger cảm xúc\", \"right\": \"Phản ứng sợ hãi đột ngột khi gặp hình ảnh gợi nhớ chấn thương\"}, {\"left\": \"Tổng đài 111\", \"right\": \"Kênh tư vấn tâm lý và bảo vệ trẻ em miễn phí 24/7\"}]}', 4, '2026-07-06 21:49:08', '2026-07-06 21:49:08'),
(5120, 861, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về chữa lành tâm lý:\", \"sentence\": \"Hành trình chữa lành sau xâm hại cần nhiều [blank1]. Hãy học cách [blank2] cảm xúc của bản thân và tìm kiếm sự đồng hành từ [blank3] tâm lý hoặc y tế.\", \"blanks\": {\"blank1\": {\"correct\": \"thời gian\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"chấp nhận\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"chuyên gia\", \"placeholder\": \"...\"}}, \"words\": [\"thời gian\", \"chấp nhận\", \"chuyên gia\", \"vội vã\", \"chối bỏ\", \"bạn bè\"]}', 5, '2026-07-06 21:49:08', '2026-07-06 21:49:08'),
(5121, 861, 'interaction', '{\"question\": \"Khi lỡ lời khuyên bạn mình một câu mang tính đổ lỗi (\'tại cậu đi chơi muộn\'), cách sửa sai văn minh nhất của bạn là gì?\", \"choices\": [{\"text\": \"Xin lỗi chân thành: \'Tớ xin lỗi, tớ đã nói một câu ngớ ngẩn. Lỗi hoàn toàn không ở cậu, tớ luôn ủng hộ cậu\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Lờ đi coi như chưa nói gì, rủ bạn đi chơi game để đổi không khí.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-06 21:49:08', '2026-07-06 21:49:08'),
(5122, 862, 'hook', '{\"title\": \"Bạn có sẵn sàng một phương án B cho bản thân khi mọi chuyện đột ngột đi chệch hướng?\"}', 1, '2026-07-06 21:49:08', '2026-07-06 21:49:08'),
(5123, 862, 'explanation', '{\"bullets\": [\"Kế hoạch an toàn (Safety Plan) là một danh sách các hành động cụ thể được chuẩn bị trước để sử dụng khi bạn thấy bất an hoặc gặp nguy hiểm.\", \"Nó bao gồm: danh sách số điện thoại khẩn cấp, địa điểm lánh nạn an toàn, mật mã khẩn cấp và các bước thoát hiểm nhanh.\", \"Có một kế hoạch an toàn giúp bạn làm chủ tình huống và không bị hoảng loạn khi có sự cố xảy ra.\"]}', 2, '2026-07-06 21:49:09', '2026-07-06 21:49:09'),
(5124, 862, 'scenario', '{\"title\": \"Tình huống chuẩn bị\", \"body\": \"An chuẩn bị đi dự một bữa tiệc sinh nhật ở nhà một người bạn mới quen ở quận khác. Bố mẹ An lo lắng vì An chưa từng đi xa một mình vào buổi tối. An quyết định tự lập một bản kế hoạch an toàn nhỏ trước khi đi.\"}', 3, '2026-07-06 21:49:09', '2026-07-06 21:49:09'),
(5125, 862, 'interaction', '{\"question\": \"Đâu là những yếu tố cần có trong kế hoạch an toàn của An?\", \"choices\": [{\"text\": \"Số điện thoại của bố mẹ và taxi, sạc dự phòng đầy pin, địa chỉ nhà bạn, và một mật mã khẩn cấp gửi cho bạn thân nếu cần cứu viện.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Cứ đi thôi, đến đâu hay đến đó, bạn bè đông thế lo gì nguy hiểm.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-06 21:49:09', '2026-07-06 21:49:09'),
(5126, 862, 'reflection', '{\"question\": \"Bạn đã bao giờ tự lên một kế hoạch dự phòng trước khi đi đến một nơi xa lạ chưa?\"}', 5, '2026-07-06 21:49:09', '2026-07-06 21:49:09'),
(5127, 862, 'takeaway', '{\"items\": [\"Chuẩn bị trước phương án an toàn không phải là nhát gan, đó là biểu hiện của sự chủ động khôn ngoan.\"]}', 6, '2026-07-06 21:49:09', '2026-07-06 21:49:09'),
(5128, 863, 'hook', '{\"title\": \"Ai là người lớn đầu tiên bạn sẽ gọi điện cầu cứu khi gặp rắc rối nghiêm trọng?\"}', 1, '2026-07-06 21:49:09', '2026-07-06 21:49:09'),
(5129, 863, 'explanation', '{\"bullets\": [\"Người lớn tin cậy (Trusted Adult) là người trưởng thành có khả năng lắng nghe, thấu hiểu, tôn trọng ranh giới của bạn và có năng lực pháp lý/vật lý để bảo vệ bạn.\", \"Đó có thể là bố mẹ, thầy cô giáo, anh chị lớn, hoặc cô chú họ hàng, bác tổ trưởng dân phố.\", \"Hãy thiết lập sẵn một danh sách từ **2 đến 3 người lớn tin cậy** trong danh bạ điện thoại của mình.\"]}', 2, '2026-07-06 21:49:09', '2026-07-06 21:49:09'),
(5130, 863, 'scenario', '{\"title\": \"Tình huống chọn người giúp\", \"body\": \"Vy bị một tài khoản trên mạng xã hội tống tiền bằng ảnh riêng tư. Vy vô cùng hoảng sợ và muốn tìm người lớn giúp đỡ. Bố Vy vốn rất nghiêm khắc và hay mắng mỏ, còn cô giáo chủ nhiệm thì rất tâm lý và thường lắng nghe học sinh.\"}', 3, '2026-07-06 21:49:09', '2026-07-06 21:49:09'),
(5131, 863, 'interaction', '{\"question\": \"Vy nên ưu tiên chia sẻ sự việc với ai trước để nhận sự trợ giúp an toàn?\", \"choices\": [{\"text\": \"Cô giáo chủ nhiệm hoặc liên hệ trực tiếp Tổng đài 111 để được hướng dẫn xử lý trước khi cùng cô giáo trò chuyện với bố mẹ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Im lặng tự giải quyết vì nghĩ không có người lớn nào đáng tin cậy cả.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-06 21:49:09', '2026-07-06 21:49:09');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(5132, 863, 'reflection', '{\"question\": \"Hãy nhắm mắt lại và nghĩ về 3 người lớn xung quanh làm bạn cảm thấy an tâm và được tôn trọng nhất khi trò chuyện?\"}', 5, '2026-07-06 21:49:09', '2026-07-06 21:49:09'),
(5133, 863, 'takeaway', '{\"items\": [\"Bạn luôn có quyền tìm kiếm sự trợ giúp từ những người lớn tin cậy, bạn không cần phải tự gánh vác mọi rắc rối một mình.\"]}', 6, '2026-07-06 21:49:09', '2026-07-06 21:49:09'),
(5134, 864, 'hook', '{\"title\": \"Tại sao chúng ta thường thấy ngượng chín mặt khi định nói chuyện ranh giới hay an toàn tình dục với bố mẹ?\"}', 1, '2026-07-06 21:49:09', '2026-07-06 21:49:09'),
(5135, 864, 'explanation', '{\"bullets\": [\"Sự khác biệt thế hệ và văn hóa Á Đông khiến chủ đề ranh giới cơ thể và xâm hại trở thành điều cấm kỵ trong nhiều gia đình Việt Nam.\", \"Bố mẹ đôi khi cũng ngượng ngùng hoặc không biết cách bắt đầu câu chuyện với bạn.\", \"Hãy chủ động phá vỡ tảng băng bằng cách chia sẻ những câu chuyện thực tế hoặc bài học bạn đọc được trên trường lớp để dò hỏi ý kiến của bố mẹ.\"]}', 2, '2026-07-06 21:49:09', '2026-07-06 21:49:09'),
(5136, 864, 'scenario', '{\"title\": \"Tình huống bắt đầu\", \"body\": \"Linh muốn xin bố mẹ cài đặt ứng dụng định vị trên điện thoại để phòng hờ khi đi học về muộn, nhưng sợ bố mẹ nghĩ mình đang làm quá hoặc tò mò chuyện yêu đương. Linh ngập ngừng mãi trước cửa phòng bố mẹ.\"}', 3, '2026-07-06 21:49:09', '2026-07-06 21:49:09'),
(5137, 864, 'interaction', '{\"question\": \"Linh nên mở đầu câu chuyện thế nào để bố mẹ dễ tiếp nhận nhất?\", \"choices\": [{\"text\": \"\'Bố mẹ ơi, hôm nay lớp con học về kỹ năng tự bảo vệ, thầy cô khuyên nên thiết lập Kế hoạch an toàn gia đình. Con muốn thảo luận với bố mẹ về việc này ạ!\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"\'Bố mẹ cài định vị đi, dạo này ngoài đường nhiều biến thái lắm con sợ\'.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:49:09', '2026-07-06 21:49:09'),
(5138, 864, 'reflection', '{\"question\": \"Bạn đã bao giờ thử nói chuyện với bố mẹ về một vụ việc bắt nạt học đường xảy ra trên báo chí chưa?\"}', 5, '2026-07-06 21:49:10', '2026-07-06 21:49:10'),
(5139, 864, 'takeaway', '{\"items\": [\"Chủ động chia sẻ về an toàn là cách bạn chứng minh với bố mẹ rằng mình đã trưởng thành và có trách nhiệm.\"]}', 6, '2026-07-06 21:49:10', '2026-07-06 21:49:10'),
(5140, 865, 'hook', '{\"title\": \"Bạn có chắc mình sẽ an toàn 100% tại một bữa tiệc sinh nhật có uống đồ uống có cồn của nhóm bạn mới?\"}', 1, '2026-07-06 21:49:10', '2026-07-06 21:49:10'),
(5141, 865, 'explanation', '{\"bullets\": [\"Các bữa tiệc là không gian tuyệt vời để kết bạn, nhưng cũng tiềm ẩn nhiều rủi ro về xâm phạm ranh giới.\", \"Hãy luôn áp dụng quy tắc an toàn đồ uống:\", \"Tự rót đồ uống của mình.\", \"Không uống đồ uống lạ từ người khác đưa.\", \"**Luôn giữ ly nước trong tầm mắt của mình**.\", \"Luôn đi cùng một người bạn thân để canh chừng cho nhau.\"]}', 2, '2026-07-06 21:49:10', '2026-07-06 21:49:10'),
(5142, 865, 'scenario', '{\"title\": \"Tình huống tại bữa tiệc\", \"body\": \"Nam đi sinh nhật một bạn cùng khóa học thêm. Tại bữa tiệc, một anh lớn tuổi hơn đưa cho Nam một ly nước ngọt màu xanh lá rất đẹp mắt và bảo: \\\"Uống đi em, nước trái cây pha chế đặc biệt của quán đấy, không say đâu!\\\". Nam nhận ra ly nước không còn nguyên nắp và anh kia cứ liên tục giục Nam uống cạn.\"}', 3, '2026-07-06 21:49:10', '2026-07-06 21:49:10'),
(5143, 865, 'interaction', '{\"question\": \"Nam nên xử lý ly nước này thế nào để bảo vệ bản thân?\", \"choices\": [{\"text\": \"Cảm ơn và lịch sự đặt ly nước xuống bàn, sau đó tự đi lấy một chai nước suối còn nguyên nắp để uống.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Uống cạn ly nước để thể hiện sự tôn trọng và hòa đồng với mọi người trong bữa tiệc.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-06 21:49:10', '2026-07-06 21:49:10'),
(5144, 865, 'reflection', '{\"question\": \"Bạn có quy ước \'mật mã đi về\' nào với bạn thân khi đi dự tiệc cùng nhau không?\"}', 5, '2026-07-06 21:49:10', '2026-07-06 21:49:10'),
(5145, 865, 'takeaway', '{\"items\": [\"Trong mọi cuộc vui, sự tỉnh táo và cảnh giác của bạn là người bảo vệ trung thành nhất.\"]}', 6, '2026-07-06 21:49:10', '2026-07-06 21:49:10'),
(5146, 866, 'hook', '{\"title\": \"Làm sao để gọi cứu trợ từ bố mẹ ngay trước mặt kẻ xấu mà không làm chúng nghi ngờ?\"}', 1, '2026-07-06 21:49:10', '2026-07-06 21:49:10'),
(5147, 866, 'explanation', '{\"bullets\": [\"**Mật mã khẩn cấp (Safety word)** là một từ hoặc cụm từ tưởng chừng rất bình thường nhưng đã được bạn và gia đình quy ước trước với nhau.\", \"Khi bạn nói hoặc nhắn cụm từ này, người nhận sẽ hiểu ngay rằng bạn đang gặp nguy hiểm và sẽ lập tức đến đón hoặc gọi công an giúp bạn.\", \"Hãy chọn một từ dễ nhớ nhưng ít khi xuất hiện trong giao tiếp hàng ngày (ví dụ: \\\"Mèo mun\\\", \\\"Bánh tráng trộn\\\").\"]}', 2, '2026-07-06 21:49:10', '2026-07-06 21:49:10'),
(5148, 866, 'scenario', '{\"title\": \"Tình huống mật mã\", \"body\": \"Vy đi chơi nhóm và bị các bạn ép ở lại qua đêm tại một nhà nghỉ ngoại thành. Vy thấy rất bất an và muốn về nhà, nhưng các bạn đang vây quanh giễu cợt. Vy muốn gọi bố đến đón nhưng sợ các bạn nghe thấy sẽ bảo Vy là con nít và cô lập Vy.\"}', 3, '2026-07-06 21:49:10', '2026-07-06 21:49:10'),
(5149, 866, 'interaction', '{\"question\": \"Nếu Vy đã quy ước mật mã khẩn cấp là \'Mèo mun\' với mẹ từ trước, Vy nên nhắn tin thế nào?\", \"choices\": [{\"text\": \"Nhắn tin cho mẹ: \'Mẹ ơi, con mèo mun nhà mình ăn cơm chưa mẹ?\'. Mẹ đọc được tin nhắn sẽ hiểu ngay con đang gặp nguy hiểm và chủ động gọi lại yêu cầu Vy về gấp hoặc định vị đến đón.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Nhắn tin: \'Mẹ ơi cứu con với, các bạn ép con ở lại nhà nghỉ con sợ quá\'.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:49:10', '2026-07-06 21:49:10'),
(5150, 866, 'reflection', '{\"question\": \"Bạn muốn chọn từ khóa nào làm mật mã khẩn cấp giữa bạn và người lớn tin cậy nhất?\"}', 5, '2026-07-06 21:49:10', '2026-07-06 21:49:10'),
(5151, 866, 'takeaway', '{\"items\": [\"Một mật mã khẩn cấp nhỏ bé có thể là chiếc phao cứu sinh cứu bạn thoát khỏi những tình huống hiểm nghèo nhất.\"]}', 6, '2026-07-06 21:49:10', '2026-07-06 21:49:10'),
(5152, 867, 'hook', '{\"title\": \"Bạn có thuộc lòng số điện thoại của người thân khi điện thoại của bạn đột ngột bị mất hoặc hết pin?\"}', 1, '2026-07-06 21:49:11', '2026-07-06 21:49:11'),
(5153, 867, 'explanation', '{\"bullets\": [\"Trong thời đại công nghệ, chúng ta thường phó mặc danh bạ cho điện thoại thông minh.\", \"Tuy nhiên, khi gặp sự cố (mất máy, hết pin, rơi xuống nước), việc thuộc lòng **ít nhất 2 số điện thoại quan trọng** là kỹ năng sống còn.\", \"Ngoài ra, hãy luôn nhớ số điện thoại khẩn cấp quốc gia: **111** (Tổng đài Quốc gia Bảo vệ Trẻ em) và **113** (Cảnh sát phản ứng nhanh).\"]}', 2, '2026-07-06 21:49:11', '2026-07-06 21:49:11'),
(5154, 867, 'scenario', '{\"title\": \"Tình huống mất nguồn\", \"body\": \"Nam đi dã ngoại cùng trường và lỡ chân ngã xuống suối làm ướt sũng điện thoại. Điện thoại bị sập nguồn hoàn toàn. Nam bị lạc khỏi đoàn và trời bắt đầu tối. Nam gặp một bác tiều phu tốt bụng cho mượn điện thoại bàn để gọi điện nhờ người thân đến đón.\"}', 3, '2026-07-06 21:49:11', '2026-07-06 21:49:11'),
(5155, 867, 'interaction', '{\"question\": \"Hành động nào giúp Nam giải quyết tình huống này nhanh nhất?\", \"choices\": [{\"text\": \"Đọc và quay số điện thoại của mẹ mà Nam đã ghi nhớ nằm lòng trong đầu để báo vị trí của mình.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Đứng khóc lóc và cố gắng tìm cách bật lại chiếc điện thoại ướt nước.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-06 21:49:11', '2026-07-06 21:49:11'),
(5156, 867, 'reflection', '{\"question\": \"Ngay bây giờ, bạn có thể viết ra giấy 2 số điện thoại của người thân mà không cần nhìn vào danh bạ điện thoại của mình không?\"}', 5, '2026-07-06 21:49:11', '2026-07-06 21:49:11'),
(5157, 867, 'takeaway', '{\"items\": [\"Kiến thức nằm trong đầu và số điện thoại nằm trong tim là những thứ không bao giờ bị mất nguồn pin.\"]}', 6, '2026-07-06 21:49:11', '2026-07-06 21:49:11'),
(5158, 868, 'hook', '{\"title\": \"Bạn có nghĩ việc luôn đề phòng an toàn sẽ làm cuộc sống của bạn trở nên nhàm chán và gò bó?\"}', 1, '2026-07-06 21:49:11', '2026-07-06 21:49:11'),
(5159, 868, 'explanation', '{\"bullets\": [\"Nhiều bạn trẻ nghĩ rằng người trang bị kỹ năng tự vệ là người nhút nhát, luôn sợ hãi thế giới.\", \"Thực chất hoàn toàn ngược lại! Khi bạn có kiến thức và sự chuẩn bị kỹ càng, bạn sẽ tự tin khám phá thế giới, tham gia các hoạt động mới mà không lo sợ.\", \"Chủ động bảo vệ ranh giới cá nhân giúp bạn có được sự tự do thực sự và xây dựng những mối quan hệ lành mạnh, bền vững.\"]}', 2, '2026-07-06 21:49:11', '2026-07-06 21:49:11'),
(5160, 868, 'scenario', '{\"title\": \"Tình huống tự tin\", \"body\": \"Vy và nhóm bạn thân rủ nhau đi phượt cắm trại cuối tuần. Trong khi các bạn khác chỉ lo chuẩn bị quần áo đẹp để chụp ảnh check-in, Vy đã chủ động mang theo hộp sơ cứu y tế, sạc dự phòng, còi báo động và học trước bản đồ offline của khu vực cắm trại. Các bạn trêu Vy là \\\"bà cụ non lo xa\\\".\"}', 3, '2026-07-06 21:49:11', '2026-07-06 21:49:11'),
(5161, 868, 'interaction', '{\"question\": \"Sự chuẩn bị của Vy mang lại giá trị gì cho cả nhóm trong chuyến đi?\", \"choices\": [{\"text\": \"Giúp cả nhóm chủ động xử lý các tình huống trầy xước, lạc đường, hết pin thiết bị và đảm bảo chuyến đi cắm trại an toàn, trọn vẹn niềm vui.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Làm cho chuyến đi mất vui và gò bó vì mọi người cứ phải nghe theo các quy tắc an toàn của Vy.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-06 21:49:11', '2026-07-06 21:49:11'),
(5162, 868, 'reflection', '{\"question\": \"Sau khi hoàn thành khóa học này, bạn cảm thấy mình đã tự tin hơn bao nhiêu phần trăm để tự bảo vệ bản thân?\"}', 5, '2026-07-06 21:49:11', '2026-07-06 21:49:11'),
(5163, 868, 'takeaway', '{\"items\": [\"Tấm khiên kỹ năng không làm bạn nặng nề hơn, nó giúp bạn tự tin bay cao và bay xa hơn trên hành trình lớn lên.\"]}', 6, '2026-07-06 21:49:11', '2026-07-06 21:49:11'),
(5164, 869, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Kỹ năng an toàn mỗi ngày\'! Cùng hoàn thiện tấm khiên bảo vệ bản thân nào.\"}', 1, '2026-07-06 21:49:12', '2026-07-06 21:49:12'),
(5165, 869, 'scenario-choice', '{\"title\": \"Chuyến cắm trại xa nhà\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn cùng lớp rủ đi cắm trại qua đêm ở một khu đồi ngoại thành. Đây là nhóm bạn mới chơi, bố mẹ bạn lo lắng không muốn cho đi.\", \"choices\": [{\"text\": \"Trốn bố mẹ đi chơi vì nghĩ mình lớn rồi, tự lo được.\", \"nextNode\": \"fail_submit\"}, {\"text\": \"Ngồi lại lập bản Kế hoạch an toàn (Safety Plan) chi tiết để thuyết phục bố mẹ.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Tại buổi cắm trại, một bạn nam rót ly nước ngọt lạ đưa cho bạn uống. Bạn để ý thấy nắp chai đã mở sẵn từ trước.\", \"choices\": [{\"text\": \"Uống cạn vì sợ các bạn bảo mình kỹ tính làm mất vui.\", \"nextNode\": \"fail_guilt\"}, {\"text\": \"Đặt ly nước xuống, tự lấy một lon coca còn nguyên seal để khui uống, nhắn mật mã khẩn cấp cho bố mẹ để hẹn giờ đón.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã biến kỹ năng an toàn thành lá chắn thường nhật giúp bạn tự tin trải nghiệm cuộc sống tự do.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_submit\": {\"text\": \"❌ Thất bại! Đi chơi xa qua đêm với nhóm bạn mới mà không có sự chuẩn bị hay thông báo cho gia đình là cờ đỏ cực kỳ nguy hiểm.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_guilt\": {\"text\": \"❌ Thất bại! Uống nước không rõ nguồn gốc mở sẵn nắp ở nơi vắng vẻ có thể khiến bạn bị bỏ thuốc mê xâm hại.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-06 21:49:12', '2026-07-06 21:49:12'),
(5166, 869, 'sorting', '{\"instruction\": \"Hãy phân loại các việc cần làm trong kế hoạch an toàn cá nhân:\", \"leftBox\": {\"title\": \"Việc nên làm chuẩn bị (Green Flag)\"}, \"rightBox\": {\"title\": \"Lỗi chủ quan (Red Flag)\"}, \"items\": [{\"text\": \"Thuộc lòng 2 số điện thoại của người lớn đáng tin\", \"correctBox\": \"left\"}, {\"text\": \"Cố uống cạn đồ uống người lạ đưa để tỏ ra hòa đồng\", \"correctBox\": \"right\"}, {\"text\": \"Quy ước mật mã khẩn cấp (safe word) với mẹ\", \"correctBox\": \"left\"}, {\"text\": \"Tắt định vị điện thoại khi đi chơi xa một mình\", \"correctBox\": \"right\"}]}', 3, '2026-07-06 21:49:12', '2026-07-06 21:49:12'),
(5167, 869, 'matching', '{\"instruction\": \"Ghép cặp các số điện thoại khẩn cấp sau với cơ quan tương ứng tại Việt Nam:\", \"pairs\": [{\"left\": \"Tổng đài 111\", \"right\": \"Tổng đài Quốc gia Bảo vệ Trẻ em, tư vấn miễn phí\"}, {\"left\": \"Đường dây 113\", \"right\": \"Cảnh sát phản ứng nhanh hỗ trợ an ninh trật tự\"}, {\"left\": \"Đường dây 114\", \"right\": \"Cứu hỏa và cứu nạn cứu hộ khẩn cấp\"}, {\"left\": \"Đường dây 115\", \"right\": \"Cấp cứu y tế khẩn cấp\"}]}', 4, '2026-07-06 21:49:12', '2026-07-06 21:49:12'),
(5168, 869, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về mật mã khẩn cấp:\", \"sentence\": \"Sử dụng [blank1] khẩn cấp giúp bạn gọi cứu trợ từ gia đình mà không gây nghi ngờ cho kẻ xấu. Hãy thiết lập một danh sách những [blank2] đáng tin cậy. Sự chuẩn bị kỹ càng chính là chìa khóa mở ra sự [blank3] thực sự.\", \"blanks\": {\"blank1\": {\"correct\": \"mật mã\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"người lớn\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"tự do\", \"placeholder\": \"...\"}}, \"words\": [\"mật mã\", \"người lớn\", \"tự do\", \"bí mật\", \"bạn bè\", \"gò bó\"]}', 5, '2026-07-06 21:49:12', '2026-07-06 21:49:12'),
(5169, 869, 'interaction', '{\"question\": \"Khi bạn đi taxi hoặc grab một mình vào buổi tối, hành động nào giúp bảo vệ an toàn cho bạn tốt nhất?\", \"choices\": [{\"text\": \"Chụp biển số xe, thông tin tài xế gửi cho bố mẹ và bật định vị chia sẻ hành trình trực tiếp suốt chuyến đi.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Bấm điện thoại chơi game, đeo tai nghe chống ồn ngủ một giấc cho đến khi tới nơi.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-06 21:49:12', '2026-07-06 21:49:12'),
(5506, 926, 'hook', '{\"title\": \"Bạn có từng cảm thấy đầu óc mình như một mớ bòng bong không thể gọi tên?\"}', 1, '2026-07-07 01:57:46', '2026-07-07 01:57:46'),
(5507, 926, 'explanation', '{\"bullets\": [\"Cảm xúc giống như thời tiết vậy, luôn thay đổi và có đủ loại sắc thái.\", \"Bản đồ cảm xúc của chúng ta không chỉ có vui hay buồn mà còn có lo âu, thất vọng, phấn khích, đố kỵ và cả sự bối rối.\", \"Học cách gọi tên cảm xúc chính là bước đầu tiên để làm chủ thế giới nội tâm của bạn.\"]}', 2, '2026-07-07 01:57:46', '2026-07-07 01:57:46'),
(5508, 926, 'scenario', '{\"title\": \"Tình huống bối rối\", \"body\": \"Nam bước vào lớp và thấy hai người bạn thân đang ghé tai nói thầm điều gì đó rồi nhìn về phía mình cười. Nam bỗng thấy ngực thắt lại, một cảm giác khó chịu dâng lên, vừa giận vừa lo sợ các bạn đang nói xấu mình.\"}', 3, '2026-07-07 01:57:46', '2026-07-07 01:57:46'),
(5509, 926, 'interaction', '{\"question\": \"Nam đang trải qua những cảm xúc gì trong tình huống này?\", \"choices\": [{\"text\": \"Chỉ là tò mò bình thường thôi, không có gì to tát cả.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Một hỗn hợp giữa sự bất an, lo lắng bị bỏ rơi và một chút giận dữ.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 01:57:46', '2026-07-07 01:57:46'),
(5510, 926, 'reflection', '{\"question\": \"Cảm xúc nào bạn thường thấy khó gọi tên nhất khi nó xuất hiện?\"}', 5, '2026-07-07 01:57:46', '2026-07-07 01:57:46'),
(5511, 926, 'takeaway', '{\"items\": [\"Gọi tên được cảm xúc là bạn đã đi được nửa đường trong việc làm dịu nó.\"]}', 6, '2026-07-07 01:57:46', '2026-07-07 01:57:46'),
(5512, 927, 'hook', '{\"title\": \"Bạn có biết cơ thể bạn chính là một chiếc loa phát thanh báo hiệu cảm xúc?\"}', 1, '2026-07-07 01:57:46', '2026-07-07 01:57:46'),
(5513, 927, 'explanation', '{\"bullets\": [\"Trước khi não bộ kịp nhận ra, cơ thể đã phản ứng với cảm xúc rồi.\", \"Sự tức giận có thể làm nóng mặt và nắm chặt tay; nỗi sợ làm tim đập thình thịch; lo âu làm bụng cồn cào.\", \"Lắng nghe những phản ứng vật lý này giúp bạn nhận diện cảm xúc sớm để không bị nó cuốn đi.\"]}', 2, '2026-07-07 01:57:46', '2026-07-07 01:57:46'),
(5514, 927, 'scenario', '{\"title\": \"Tình huống báo động\", \"body\": \"Trước giờ kiểm tra Toán, Vy thấy tay mình lạnh toát, mồ hôi rịn ra ở lòng bàn tay, và cổ họng cứ nghẹn ứ lại như không thở nổi. Vy nghĩ mình sắp bị ốm nặng.\"}', 3, '2026-07-07 01:57:46', '2026-07-07 01:57:46'),
(5515, 927, 'interaction', '{\"question\": \"Vy nên hiểu những biểu hiện trên cơ thể mình như thế nào?\", \"choices\": [{\"text\": \"Đó là dấu hiệu cơ thể đang phản ứng với stress và lo lắng, không phải bị ốm đâu.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Chắc chắn là Vy bị ốm rồi, nên xin xuống phòng y tế trốn thi thôi.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:46', '2026-07-07 01:57:46'),
(5516, 927, 'reflection', '{\"question\": \"Mỗi khi lo lắng, bộ phận nào trên cơ thể bạn phát tín hiệu rõ ràng nhất?\"}', 5, '2026-07-07 01:57:46', '2026-07-07 01:57:46'),
(5517, 927, 'takeaway', '{\"items\": [\"Cơ thể không bao giờ nói dối về cảm xúc của bạn.\"]}', 6, '2026-07-07 01:57:46', '2026-07-07 01:57:46'),
(5518, 928, 'hook', '{\"title\": \"Bạn có từng nghe ai đó bảo: Đừng buồn nữa, có gì đâu mà phải khóc?\"}', 1, '2026-07-07 01:57:47', '2026-07-07 01:57:47'),
(5519, 928, 'explanation', '{\"bullets\":[\"Chúng ta thường bị dạy rằng buồn bã, tức giận hay sợ hãi là cảm xúc tiêu cực và cần phải dẹp bỏ ngay.\",\"Việc cố đè nén cảm xúc giống như việc giữ một chiếc lò xo bị nén chặt, sớm muộn gì nó cũng sẽ bung ra mạnh mẽ hơn.\",\"Cảm xúc khó chịu không phải là kẻ thù, chúng chỉ là những tín hiệu cho biết nhu cầu của bạn chưa được đáp ứng.\"]}', 2, '2026-07-07 01:57:47', '2026-07-07 01:58:35'),
(5520, 928, 'scenario', '{\"title\": \"Tình huống đè nén\", \"body\": \"Minh thi trượt đội tuyển học sinh giỏi trường. Rất buồn và muốn khóc, nhưng Minh tự nhủ: \\\"Mình là con trai, khóc lóc thật yếu đuối\\\". Minh cố cười nói bình thường với các bạn, nhưng tối về lại thấy tức giận vô cớ và quát mắng em gái.\"}', 3, '2026-07-07 01:57:47', '2026-07-07 01:57:47'),
(5521, 928, 'interaction', '{\"question\": \"Minh có thể làm gì thay vì đè nén cảm xúc của mình?\", \"choices\": [{\"text\": \"Tìm một góc riêng tư để khóc hoặc viết nhật ký thừa nhận rằng mình đang rất thất vọng.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tiếp tục cố gắng tỏ ra mạnh mẽ và chơi game thâu đêm để quên đi nỗi buồn.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:47', '2026-07-07 01:57:47'),
(5522, 928, 'reflection', '{\"question\": \"Bạn có thường cảm thấy tội lỗi hoặc xấu hổ khi mình lỡ nổi giận hoặc khóc không?\"}', 5, '2026-07-07 01:57:47', '2026-07-07 01:57:47'),
(5523, 928, 'takeaway', '{\"items\": [\"Cho phép bản thân không ổn cũng là một loại sức mạnh.\"]}', 6, '2026-07-07 01:57:47', '2026-07-07 01:57:47'),
(5524, 929, 'hook', '{\"title\": \"Làm sao để không làm tổn thương người khác khi ngọn lửa giận dữ bùng lên?\"}', 1, '2026-07-07 01:57:47', '2026-07-07 01:57:47'),
(5525, 929, 'explanation', '{\"bullets\": [\"Cơn giận dữ dâng lên rất nhanh, giống như một cơn bão bất chợt càn quét lý trí của bạn.\", \"Khi giận, vùng não cảm xúc chiếm quyền kiểm soát, khiến bạn dễ nói hoặc làm những việc gây hối hận sau này.\", \"Bí quyết không phải là dập tắt cơn giận ngay lập tức, mà là tạo ra một khoảng dừng an toàn trước khi phản ứng.\"]}', 2, '2026-07-07 01:57:47', '2026-07-07 01:57:47'),
(5526, 929, 'scenario', '{\"title\": \"Tình huống bốc hỏa\", \"body\": \"Trong giờ làm bài nhóm, bạn cùng nhóm lỡ tay xóa mất slide thuyết trình mà An đã mất cả đêm để thiết kế. An thấy máu dồn lên não, mặt nóng bừng và muốn hét to vào mặt bạn để trút giận.\"}', 3, '2026-07-07 01:57:47', '2026-07-07 01:57:47'),
(5527, 929, 'interaction', '{\"question\": \"Khoảng dừng an toàn tốt nhất dành cho An lúc này là gì?\", \"choices\": [{\"text\": \"Hít một hơi thật sâu, đếm chậm từ 1 đến 10 và nói: \'Tớ đang rất giận, tụi mình dừng 5 phút rồi nói chuyện tiếp\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Ngay lập tức mắng bạn một trận lôi đình để họ biết lỗi và sợ lần sau không dám thế nữa.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 01:57:47', '2026-07-07 01:57:47'),
(5528, 929, 'reflection', '{\"question\": \"Bạn thường làm gì để hạ hỏa mỗi khi cơn giận ập đến?\"}', 5, '2026-07-07 01:57:47', '2026-07-07 01:57:47'),
(5529, 929, 'takeaway', '{\"items\": [\"Giữa kích thích và phản ứng có một khoảng trống. Khoảng trống đó là tự do của bạn.\"]}', 6, '2026-07-07 01:57:47', '2026-07-07 01:57:47'),
(5530, 930, 'hook', '{\"title\": \"Bạn có biết kỹ thuật Name it to tame it giúp xoa dịu bộ não đang nổi giận như thế nào không?\"}', 1, '2026-07-07 01:57:48', '2026-07-07 01:57:48'),
(5531, 930, 'explanation', '{\"bullets\": [\"Khi bạn gọi tên chính xác cảm xúc của mình bằng lời nói (ví dụ: \\\"Tớ đang thấy thất vọng\\\"), bạn đang kích hoạt vỏ não trước trán.\", \"Vỏ não trước trán sẽ gửi tín hiệu làm dịu hạch hạnh nhân (vùng não xử lý cảm xúc mạnh).\", \"Nói ra cảm xúc giúp giảm bớt cường độ của nó mà không cần bạn phải cố gắng kiềm chế hay đè nén.\"]}', 2, '2026-07-07 01:57:48', '2026-07-07 01:57:48'),
(5532, 930, 'scenario', '{\"title\": \"Tình huống tự thoại\", \"body\": \"Chi bị điểm kém môn Văn và thấy vô cùng khó chịu, bực bội với mọi thứ xung quanh. Thay vì cáu gắt với mọi người, Chi ngồi xuống và tự nói thầm với chính mình: \\\"Mình đang thấy vừa buồn vừa tự ái vì bài làm không được đánh giá đúng\\\".\"}', 3, '2026-07-07 01:57:48', '2026-07-07 01:57:48'),
(5533, 930, 'interaction', '{\"question\": \"Hành động tự gọi tên cảm xúc của Chi có tác dụng gì?\", \"choices\": [{\"text\": \"Giúp giải tỏa bớt áp lực cảm xúc, giúp Chi lấy lại sự bình tĩnh nhanh hơn.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Làm Chi thêm buồn chán và tự ti hơn vì cứ tập trung vào điểm yếu của mình.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 01:57:48', '2026-07-07 01:57:48'),
(5534, 930, 'reflection', '{\"question\": \"Khi gặp chuyện buồn, bạn có thói quen tự trò chuyện và gọi tên cảm xúc của mình không?\"}', 5, '2026-07-07 01:57:48', '2026-07-07 01:57:48'),
(5535, 930, 'takeaway', '{\"items\": [\"Khi bạn gọi tên được cảm xúc, bạn bắt đầu làm chủ được nó.\"]}', 6, '2026-07-07 01:57:48', '2026-07-07 01:57:48'),
(5536, 931, 'hook', '{\"title\": \"Làm sao để biết cảm xúc của bạn đang muốn gửi gắm thông điệp gì?\"}', 1, '2026-07-07 01:57:48', '2026-07-07 01:57:48'),
(5537, 931, 'explanation', '{\"bullets\": [\"Mỗi cảm xúc xuất hiện đều mang một thông điệp ẩn ý riêng để bảo vệ bạn.\", \"Nỗi sợ báo hiệu sự nguy hiểm; sự giận dữ cho biết ranh giới của bạn bị xâm phạm; sự buồn bã cho biết bạn vừa mất đi điều gì đó quý giá.\", \"Đặt câu hỏi cho cảm xúc thay vì phán xét nó sẽ giúp bạn hiểu sâu hơn về nhu cầu của bản thân.\"]}', 2, '2026-07-07 01:57:48', '2026-07-07 01:57:48'),
(5538, 931, 'scenario', '{\"title\": \"Tình huống tự vấn\", \"body\": \"Phương thấy rất đố kỵ khi đứa bạn thân khoe chiếc điện thoại mới tinh. Phương thấy xấu hổ vì sự ích kỷ của mình và cố xua suy nghĩ đó đi, nhưng cảm giác đố kỵ vẫn âm ỉ khiến Phương khó chịu cả ngày.\"}', 3, '2026-07-07 01:57:48', '2026-07-07 01:57:48'),
(5539, 931, 'interaction', '{\"question\": \"Phương nên đối thoại thế nào với sự đố kỵ của mình để hiểu bản thân hơn?\", \"choices\": [{\"text\": \"Tự hỏi: \'Sự đố kỵ này đang cho thấy mình đang khao khát điều gì? Có phải mình cũng muốn được ghi nhận và có đồ mới không?\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tự trách mình: \'Sao mình lại là đứa bạn tồi tệ và ích kỷ như vậy chứ!\' rồi ép mình phải vui vẻ chúc mừng bạn.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:48', '2026-07-07 01:57:48'),
(5540, 931, 'reflection', '{\"question\": \"Cơn giận gần nhất của bạn đang cố gắng bảo vệ ranh giới nào của bạn vậy?\"}', 5, '2026-07-07 01:57:48', '2026-07-07 01:57:48'),
(5541, 931, 'takeaway', '{\"items\": [\"Cảm xúc là những người đưa thư, đừng bắn người đưa thư, hãy đọc bức thư.\"]}', 6, '2026-07-07 01:57:48', '2026-07-07 01:57:48'),
(5542, 932, 'hook', '{\"title\": \"Bạn có biết bí quyết của sự bình yên nội tâm là gì không?\"}', 1, '2026-07-07 01:57:48', '2026-07-07 01:57:48'),
(5543, 932, 'explanation', '{\"bullets\": [\"Bình yên nội tâm không phải là lúc nào cũng vui vẻ, mà là khi bạn chấp nhận mọi cảm xúc đến và đi mà không phán xét chúng.\", \"Cảm xúc giống như những làn sóng ngoài đại dương, chúng dâng lên, đạt đỉnh rồi tự động rút đi nếu bạn không cố gắng níu giữ hay chống lại chúng.\", \"Tất cả cảm xúc của bạn đều hợp lệ và xứng đáng được tôn trọng.\"]}', 2, '2026-07-07 01:57:48', '2026-07-07 01:57:48'),
(5544, 932, 'scenario', '{\"title\": \"Tình huống chấp nhận\", \"body\": \"Trâm cảm thấy trống rỗng và buồn bã suốt cả ngày chủ nhật mà không rõ lý do. Thay vì ép mình phải đi chơi hoặc làm việc gì đó cho bận rộn để quên đi, Trâm quyết định nằm nghỉ ngơi và tự nhủ: \\\"Hôm nay mình buồn một chút cũng không sao cả\\\".\"}', 3, '2026-07-07 01:57:48', '2026-07-07 01:57:48'),
(5545, 932, 'interaction', '{\"question\": \"Thái độ của Trâm đối với ngày chủ nhật buồn bã của mình là:\", \"choices\": [{\"text\": \"Sự tự trắc ẩn và chấp nhận lành mạnh thế giới cảm xúc tự nhiên của mình.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Sự lười biếng và thiếu tích cực, đáng ra Trâm nên cố gắng làm gì đó vui vẻ hơn.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 01:57:48', '2026-07-07 01:57:48'),
(5546, 932, 'reflection', '{\"question\": \"Bạn có sẵn lòng ôm lấy cả những ngày buồn bã hay lo âu của mình không?\"}', 5, '2026-07-07 01:57:48', '2026-07-07 01:57:48'),
(5547, 932, 'takeaway', '{\"items\": [\"Bạn không phải là cảm xúc của bạn. Bạn là bầu trời rộng lớn chứa đựng những đám mây cảm xúc đó.\"]}', 6, '2026-07-07 01:57:48', '2026-07-07 01:57:48'),
(5548, 933, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Thấu hiểu cảm xúc\'! Hãy cùng kiểm tra xem bạn đã sẵn sàng làm chủ thế giới nội tâm của mình chưa nhé.\"}', 1, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5549, 933, 'scenario-choice', '{\"title\": \"Cơn giận dữ bùng nổ\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Đứa bạn cùng bàn lỡ làm đổ nước ngọt vào cuốn vở ghi chép bài học yêu thích của bạn. Bạn cảm thấy mặt mình nóng bừng, tim đập nhanh và muốn giật vở ném đi.\", \"choices\": [{\"text\": \"Mắng bạn một trận lôi đình: \'Cậu đi đứng kiểu gì thế hả, phá hoại vừa thôi chứ!\'.\", \"nextNode\": \"fail_submit\"}, {\"text\": \"Nhắm mắt lại, hít thở sâu 3 nhịp và nói: \'Tớ đang rất giận đấy, cậu lau giúp tớ đi rồi tụi mình nói chuyện tiếp\'.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Bạn của bạn cuống cuồng lau dọn và rối rít xin lỗi, nhưng sau đó bạn ấy tự ái bảo: \'Có cuốn vở thôi mà làm gì căng thẳng thế\'.\", \"choices\": [{\"text\": \"Bỏ qua lời kích động, tự nhủ: \'Mình đã kiểm soát cơn giận tốt, không cần cãi nhau tay đôi làm gì\' và im lặng cất vở đi học tiếp.\", \"nextNode\": \"success_end\"}, {\"text\": \"Tiếp tục nổi khùng lên: \'Cậu làm hỏng đồ của người khác mà nói giọng đó à!\' và cãi cọ ầm ĩ.\", \"nextNode\": \"fail_guilt\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã kiểm soát cơn bão giận dữ thành công, bảo vệ được cuốn vở và không để lời kích động làm hỏng mối quan hệ.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_submit\": {\"text\": \"❌ Thất bại! Trút giận lập tức bằng lời mắng mỏ chỉ làm leo thang mâu thuẫn và khiến mối quan hệ bè bạn bị tổn hại nghiêm trọng.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_guilt\": {\"text\": \"❌ Thất bại! Nhượng bộ trước lời kích thích ở bước hai sẽ làm nỗ lực kìm chế cơn giận trước đó của bạn đổ sông đổ bể.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5550, 933, 'sorting', '{\"instruction\": \"Hãy phân loại các biểu hiện của cảm xúc trên cơ thể:\", \"leftBox\": {\"title\": \"Phản ứng khi lo âu/sợ hãi (Cảnh báo đỏ)\"}, \"rightBox\": {\"title\": \"Phản ứng khi bình yên/vui vẻ (Cảnh báo xanh)\"}, \"items\": [{\"text\": \"Tim đập thình thịch, tay đổ mồ hôi\", \"correctBox\": \"left\"}, {\"text\": \"Cơ mặt thả lỏng, hơi thở đều đặn\", \"correctBox\": \"right\"}, {\"text\": \"Cổ họng nghẹn ứ, bụng cồn cào\", \"correctBox\": \"left\"}, {\"text\": \"Cơ bắp thư giãn, nụ cười tự nhiên\", \"correctBox\": \"right\"}]}', 3, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5551, 933, 'matching', '{\"instruction\": \"Ghép cặp các khái niệm về cảm xúc cơ bản sau:\", \"pairs\": [{\"left\": \"Name it to tame it\", \"right\": \"Kỹ thuật gọi tên để làm dịu cảm xúc\"}, {\"left\": \"Hạch hạnh nhân\", \"right\": \"Vùng não xử lý các cảm xúc mạnh mẽ\"}, {\"left\": \"Đè nén cảm xúc\", \"right\": \"Việc tích tụ áp lực giống chiếc lò xo bị nén\"}, {\"left\": \"Thông điệp cảm xúc\", \"right\": \"Tín hiệu cho biết nhu cầu của bản thân\"}]}', 4, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5552, 933, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về cảm xúc:\", \"sentence\": \"Cảm xúc của chúng ta giống như [blank1] luôn thay đổi. Thay vì cố gắng [blank2] những cảm xúc khó chịu, hãy học cách chấp nhận và [blank3] tên chúng để bộ não được làm dịu.\", \"blanks\": {\"blank1\": {\"correct\": \"thời tiết\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"đè nén\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"gọi\", \"placeholder\": \"...\"}}, \"words\": [\"thời tiết\", \"đè nén\", \"gọi\", \"cố định\", \"trốn tránh\", \"phán xét\"]}', 5, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5553, 933, 'interaction', '{\"question\": \"Đâu là nhận định chính xác nhất về các cảm xúc khó chịu như buồn bã hay sợ hãi?\", \"choices\": [{\"text\": \"Chúng là những cảm xúc hoàn toàn tự nhiên và mang thông điệp báo hiệu nhu cầu của cơ thể bạn.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Chúng là những biểu hiện của sự yếu đuối, cần phải gạt bỏ ngay lập tức để tỏ ra mạnh mẽ.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5554, 934, 'hook', '{\"title\": \"Giá trị của bạn được định nghĩa bởi điều gì?\"}', 1, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5555, 934, 'explanation', '{\"bullets\": [\"Giá trị cá nhân (Self-Esteem) là sự đánh giá và niềm tin của chính bạn về giá trị của bản thân mình.\", \"Nó không phụ thuộc vào điểm số, ngoại hình, số lượt like trên mạng xã hội hay lời khen chê của người khác.\", \"Giá trị cá nhân bền vững đến từ việc bạn hiểu rõ bản thân, tôn trọng các giá trị của mình và biết rằng mình xứng đáng được yêu thương.\"]}', 2, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5556, 934, 'scenario', '{\"title\": \"Tình huống định giá\", \"body\": \"Huy thấy rất buồn vì bài đăng facebook của mình chỉ được lẹt đẹt vài lượt tương tác, trong khi bài của cậu bạn cùng lớp được hàng trăm like và bình luận tung hô. Huy bắt đầu nghi ngờ bản thân có phải là kẻ mờ nhạt và kém cỏi.\"}', 3, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5557, 934, 'interaction', '{\"question\": \"Huy nên nhắc nhở bản thân điều gì để bảo vệ giá trị cá nhân của mình?\", \"choices\": [{\"text\": \"Lượt like trên mạng xã hội chỉ là ảo và không phản ánh đúng giá trị thực sự hay năng lực của mình.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Mình cần phải chụp ảnh đẹp hơn, nói những câu giật gân hơn để thu hút sự chú ý của mọi người bằng mọi giá.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5558, 934, 'reflection', '{\"question\": \"Điều gì ở bản thân khiến bạn cảm thấy tự hào nhất mà không cần ai phải khen ngợi?\"}', 5, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5559, 934, 'takeaway', '{\"items\": [\"Giá trị của bạn là do bạn định đoạt, không phải do thế giới quyết định.\"]}', 6, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5560, 935, 'hook', '{\"title\": \"Bạn có đang nhìn cơ thể mình qua một chiếc kính lúp phóng đại khuyết điểm?\"}', 1, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5561, 935, 'explanation', '{\"bullets\": [\"Hình ảnh cơ thể (Body Image) là cách bạn cảm nhận và suy nghĩ về ngoại hình của chính mình.\", \"Ở tuổi dậy thì, cơ thể thay đổi rất nhanh và đôi khi không giống với những hình mẫu hoàn hảo trên truyền thông hay mạng xã hội.\", \"Sự tự ti về ngoại hình thường bắt nguồn từ việc so sánh bản thân với những tiêu chuẩn phi thực tế.\"]}', 2, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5562, 935, 'scenario', '{\"title\": \"Tình huống soi gương\", \"body\": \"Linh đứng trước gương hàng giờ liền để săm soi những vết mụn trên mặt và vòng hai không được thon gọn. Linh thấy ghét cơ thể mình và không muốn đi dự tiệc sinh nhật của bạn thân vì sợ bị mọi người chê xấu.\"}', 3, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5563, 935, 'interaction', '{\"question\": \"Linh có thể thay đổi góc nhìn của mình như thế nào để thấy thoải mái hơn?\", \"choices\": [{\"text\": \"Tập trung vào những gì cơ thể đã làm được cho mình: giúp mình chạy nhảy, vẽ tranh, và ôm người thân yêu.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Ở nhà, ăn kiêng nghiêm ngặt và trang điểm thật đậm để che hết mọi khuyết điểm trước khi dám ra đường.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5564, 935, 'reflection', '{\"question\": \"Bạn có từng cảm thấy tự ti về một bộ phận nào đó trên cơ thể mình chưa? Bạn đã làm hòa với nó như thế nào?\"}', 5, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5565, 935, 'takeaway', '{\"items\": [\"Cơ thể bạn là ngôi nhà của bạn, hãy đối xử với nó bằng sự tử tế thay vì phán xét.\"]}', 6, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5566, 936, 'hook', '{\"title\": \"Mạng xã hội đang trưng bày những khoảnh khắc đẹp nhất, hay cuộc sống thực tế?\"}', 1, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5567, 936, 'explanation', '{\"bullets\": [\"Hầu hết mọi người chỉ đăng tải những hình ảnh lung linh nhất, những chuyến đi chơi vui vẻ hay những thành tích xuất sắc của họ lên mạng.\", \"So sánh cuộc sống thường nhật đầy rẫy những lo toan của bạn với highlight reel (những thước phim nổi bật) của người khác là một sự khập khiễng lớn.\", \"Cái bẫy này khiến bạn luôn cảm thấy mình thiếu thốn, kém cỏi và không bao giờ là đủ.\"]}', 2, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5568, 936, 'scenario', '{\"title\": \"Tình huống lướt feed\", \"body\": \"Hân nằm lướt TikTok và thấy các bạn cùng tuổi chia sẻ về cuộc sống sang chảnh, quần áo hàng hiệu và những thành tích học tập khủng. Hân nhìn lại căn phòng nhỏ của mình và thấy cuộc sống của mình thật tẻ nhạt, vô vị.\"}', 3, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5569, 936, 'interaction', '{\"question\": \"Hân nên phản ứng thế nào để thoát khỏi cái bẫy so sánh này?\", \"choices\": [{\"text\": \"Nhắc nhở bản thân rằng đó chỉ là phần nổi của tảng băng chìm, tắt điện thoại và đi làm việc mình yêu thích.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Đăng ảnh sống ảo mượn đồ của người khác để tỏ ra mình cũng có cuộc sống sang chảnh không kém cạnh.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5570, 936, 'reflection', '{\"question\": \"Mạng xã hội có bao giờ làm bạn thấy mình kém cỏi hơn không? Bạn đã làm gì lúc đó?\"}', 5, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5571, 936, 'takeaway', '{\"items\": [\"Đừng so sánh chương một của bạn với chương mười của người khác.\"]}', 6, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5572, 937, 'hook', '{\"title\": \"Bạn sẽ làm gì khi lời nói của người khác làm tổn thương sự tự tin của bạn?\"}', 1, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5573, 937, 'explanation', '{\"bullets\": [\"Những lời nhận xét tiêu cực, chê bai ngoại hình hay năng lực từ người khác giống như những mũi tên bắn vào sự tự tin của bạn.\", \"Tuy nhiên, lời chê bai phản ánh thế giới nội tâm và định kiến của người nói nhiều hơn là phản ánh giá trị thực sự của bạn.\", \"Bạn không thể ngăn người khác nói, nhưng bạn hoàn toàn có quyền quyết định có nhận lấy lời nói đó vào lòng hay không.\"]}', 2, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5574, 937, 'scenario', '{\"title\": \"Tình huống bị trêu\", \"body\": \"Trong giờ thể dục, khi Nam nhảy xà không qua, một nhóm bạn nam đã cười lớn và trêu: \\\"Yếu như sên thế kia thì làm được tích sự gì!\\\". Nam thấy mặt nóng bừng, xấu hổ và muốn bỏ học môn này luôn.\"}', 3, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5575, 937, 'interaction', '{\"question\": \"Nam nên phản ứng thế nào trước lời trêu chọc của nhóm bạn?\", \"choices\": [{\"text\": \"Tự nhủ: \'Họ trêu chỉ để gây chú ý, năng lực của mình không bị quyết định bởi một cú nhảy xà\' và tiếp tục tập luyện.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Xông vào cãi nhau tay đôi với nhóm bạn hoặc tự trách mình thật sự yếu đuối, kém cỏi.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5576, 937, 'reflection', '{\"question\": \"Một lời chê bai nào từng làm bạn đau lòng nhất? Bây giờ bạn nhìn nhận lại lời nói đó thế nào?\"}', 5, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5577, 937, 'takeaway', '{\"items\": [\"Không ai có thể làm bạn thấy kém cỏi nếu không có sự đồng ý của bạn.\"]}', 6, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5578, 938, 'hook', '{\"title\": \"Bạn có đang tự trò chuyện với mình như một người bạn thân, hay một thẩm phán nghiêm khắc?\"}', 1, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5579, 938, 'explanation', '{\"bullets\": [\"Tiếng nói nội tâm (Self-talk) có sức ảnh hưởng rất lớn đến lòng tự trọng của bạn.\", \"Khi làm sai, chúng ta thường tự mắng mình là đồ ngốc, kẻ thất bại - điều mà ta sẽ không bao giờ nói với bạn thân của mình.\", \"Thực hành lòng trắc ẩn với bản thân (Self-compassion) là học cách trò chuyện với chính mình bằng sự dịu dàng, thấu hiểu và tha thứ khi gặp khó khăn.\"]}', 2, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5580, 938, 'scenario', '{\"title\": \"Tình huống tự trách\", \"body\": \"Trang làm hỏng bài thuyết trình trước lớp vì quên lời. Khi về chỗ ngồi, đầu óc Trang liên tục tua lại khoảnh khắc đó kèm những lời tự trách: \\\"Mày thật tệ hại, mọi người chắc đang cười nhạo mày lắm\\\". Trang thấy nghẹn ngào muốn khóc.\"}', 3, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5581, 938, 'interaction', '{\"question\": \"Trang nên viết lại cuộc tự thoại này như thế nào bằng lòng trắc ẩn với bản thân?\", \"choices\": [{\"text\": \"Tự nói: \'Ai cũng có lúc run và quên bài. Mình đã chuẩn bị rất kỹ, lần sau mình sẽ tập thở sâu hơn để bình tĩnh. Mình đã làm tốt nhất có thể rồi\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tự ép mình không được nghĩ đến chuyện đó nữa và bắt bản thân phải hoàn hảo trong mọi bài thuyết trình sau này.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5582, 938, 'reflection', '{\"question\": \"Nếu bạn thân của bạn làm hỏng một việc, bạn sẽ khuyên họ thế nào? Bạn có đối xử với mình tương tự không?\"}', 5, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5583, 938, 'takeaway', '{\"items\": [\"Bạn xứng đáng nhận được sự tử tế từ chính mình trước tiên.\"]}', 6, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5584, 939, 'hook', '{\"title\": \"Bạn có đang tìm kiếm sự công nhận từ bên ngoài để lấp đầy khoảng trống bên trong?\"}', 1, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5585, 939, 'explanation', '{\"bullets\": [\"Mỗi người đều có một bộ kỹ năng, sở thích và điểm mạnh độc bản tạo nên giá trị riêng.\", \"Có bạn giỏi Toán, có bạn vẽ đẹp, có bạn lại là người lắng nghe tuyệt vời hoặc rất biết cách chăm sóc động vật.\", \"Tập trung và phát triển những điểm mạnh của riêng mình giúp bạn xây dựng lòng tự trọng vững chắc từ bên trong, không bị lung lay bởi ý kiến của người khác.\"]}', 2, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5586, 939, 'scenario', '{\"title\": \"Tình huống lạc lõng\", \"body\": \"Quân không giỏi thể thao và cũng không học xuất sắc các môn tự nhiên như các bạn nam khác trong lớp. Quân thích nấu ăn và làm đồ thủ công, nhưng luôn giấu kín vì sợ bị trêu là không nam tính. Quân thấy mình thật lạc lõng và vô dụng.\"}', 3, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5587, 939, 'interaction', '{\"question\": \"Quân nên làm gì để trân trọng điểm mạnh riêng của mình?\", \"choices\": [{\"text\": \"Tự tin theo đuổi đam mê nấu ăn, chia sẻ thành quả với những người trân trọng mình và tự hào về sự khéo tay của bản thân.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Cố gắng ép mình đi học đá bóng dù ghét cay ghét đắng để trông có vẻ giống các bạn nam khác.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5588, 939, 'reflection', '{\"question\": \"Một tài năng hoặc sở thích thầm kín nào của bạn làm bạn thấy vui vẻ nhất mỗi khi thực hiện?\"}', 5, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5589, 939, 'takeaway', '{\"items\": [\"Hãy là phiên bản chính mình tốt nhất, thay vì là bản sao hạng hai của người khác.\"]}', 6, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5590, 940, 'hook', '{\"title\": \"Bạn có sẵn sàng ký một bản cam kết hòa bình với chính bản thân mình?\"}', 1, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5591, 940, 'explanation', '{\"bullets\": [\"Chấp nhận bản thân (Self-acceptance) là việc ôm lấy toàn bộ con người bạn: cả những điểm mạnh, điểm yếu, những thành công và cả những vết sẹo lỗi lầm.\", \"Đó không phải là sự tự mãn chịu đầu hàng không chịu tiến bộ, mà là điểm tựa an toàn để từ đó bạn phát triển lành mạnh.\", \"Bạn không cần phải hoàn hảo để xứng đáng được yêu thương và tôn trọng.\"]}', 2, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5592, 940, 'scenario', '{\"title\": \"Tình huống làm hòa\", \"body\": \"Vân nhận ra mình rất hay quên và vụng về trong các công việc chân tay. Thay vì dằn vặt bản thân mỗi khi làm rơi đồ, Vân tự cười xòa và ghi chép mọi việc vào một cuốn sổ nhỏ để khắc phục, đồng thời chấp nhận tính hay quên như một phần tính cách của mình.\"}', 3, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5593, 940, 'interaction', '{\"question\": \"Thái độ tự chấp nhận của Vân mang lại lợi ích gì?\", \"choices\": [{\"text\": \"Giúp Vân giảm bớt áp lực tinh thần, vui vẻ hơn và tìm ra giải pháp thực tế để cải thiện cuộc sống.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Khiến Vân ngày càng cẩu thả và không bao giờ sửa được tính hay quên của mình.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5594, 940, 'reflection', '{\"question\": \"Một khuyết điểm nào ở bản thân mà hôm nay bạn sẵn lòng bao dung và chấp nhận nó?\"}', 5, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5595, 940, 'takeaway', '{\"items\": [\"Bạn là một tác phẩm nghệ thuật đang trong quá trình hoàn thiện, hãy kiên nhẫn với chính mình.\"]}', 6, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5596, 941, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Giá trị cá nhân & Chấp nhận bản thân\'! Hãy cùng bảo vệ lòng tự trọng vững chắc nhé.\"}', 1, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5597, 941, 'scenario-choice', '{\"title\": \"So tài trên mạng xã hội\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn đăng ảnh vẽ tranh đam mê của mình lên Facebook nhưng bị một tài khoản ảo nhảy vào chê bai: \'Vẽ xấu thế này cũng đòi khoe, rác mắt\'. Bạn thấy buồn và nghi ngờ tài năng của mình.\", \"choices\": [{\"text\": \"Xóa ngay bài đăng và tự nhủ mình không bao giờ cầm cọ vẽ nữa.\", \"nextNode\": \"fail_submit\"}, {\"text\": \"Giữ nguyên bài đăng, tự nhủ: \'Năng lực vẽ của mình lớn lên từng ngày, ý kiến anti-fan không định nghĩa giá trị của mình\'\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Nhóm bạn thân khuyên bạn nên vẽ những bức tranh câu view hở hang để thu hút tương tác nổi tiếng nhanh hơn.\", \"choices\": [{\"text\": \"Nghe theo bạn vẽ tranh câu view dù trong lòng thấy vô cùng ngượng ngùng và vi phạm đạo đức cá nhân.\", \"nextNode\": \"fail_guilt\"}, {\"text\": \"Từ chối lịch sự: \'Tớ chỉ muốn vẽ những gì tớ yêu thích thôi. Tớ sẽ trung thành với phong cách của mình\'.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã bảo vệ được đam mê độc bản và giữ vững ranh giới giá trị cá nhân trước sự lôi kéo của đám đông.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_submit\": {\"text\": \"❌ Thất bại! Để một lời chê bai ác ý cướp đi đam mê của mình là bạn đang giao quyền định đoạt cuộc sống cho người lạ rồi.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_guilt\": {\"text\": \"❌ Thất bại! Đánh đổi giá trị đạo đức cá nhân để lấy những lượt tương tác ảo trên mạng xã hội chỉ đem lại sự hối hận lâu dài.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5598, 941, 'sorting', '{\"instruction\": \"Hãy phân loại tiếng nói nội tâm của bạn:\", \"leftBox\": {\"title\": \"Lòng trắc ẩn với bản thân (Tử tế)\"}, \"rightBox\": {\"title\": \"Sự tự chỉ trích khắt khe (Nghiêm khắc)\"}, \"items\": [{\"text\": \"Mình đã làm tốt nhất có thể, sai sót này là bài học\", \"correctBox\": \"left\"}, {\"text\": \"Mày thật là đồ vô dụng, việc nhỏ thế cũng làm hỏng\", \"correctBox\": \"right\"}, {\"text\": \"Ai cũng có lúc run, lần sau mình sẽ chuẩn bị tốt hơn\", \"correctBox\": \"left\"}, {\"text\": \"Mọi người chắc đang cười nhạo và coi thường mày lắm\", \"correctBox\": \"right\"}]}', 3, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5599, 941, 'matching', '{\"instruction\": \"Ghép cặp các khái niệm về giá trị cá nhân sau:\", \"pairs\": [{\"left\": \"Giá trị cá nhân\", \"right\": \"Niềm tin vững chắc về giá trị tự thân\"}, {\"left\": \"Hình ảnh cơ thể\", \"right\": \"Cách cảm nhận và suy nghĩ về ngoại hình\"}, {\"left\": \"Highlight reel\", \"right\": \"Những thước phim lung linh nhất trên mạng\"}, {\"left\": \"Chấp nhận bản thân\", \"right\": \"Ôm lấy cả điểm mạnh lẫn khuyết điểm riêng\"}]}', 4, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5600, 941, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về lòng tự trọng:\", \"sentence\": \"Đừng so sánh cuộc sống của bạn với những thước phim [blank1] trên mạng xã hội. Hãy đối xử tử tế với chính mình bằng lòng [blank2] bản thân và tự hào vì mình là phiên bản [blank3] duy nhất.\", \"blanks\": {\"blank1\": {\"correct\": \"lung linh\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"trắc ẩn\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"độc bản\", \"placeholder\": \"...\"}}, \"words\": [\"lung linh\", \"trắc ẩn\", \"độc bản\", \"méo mó\", \"khắt khe\", \"hoàn hảo\"]}', 5, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5601, 941, 'interaction', '{\"question\": \"Đâu là thái độ đúng đắn nhất đối với những khuyết điểm hay sai lầm của bản thân?\", \"choices\": [{\"text\": \"Chấp nhận chúng như một phần con người mình và kiên nhẫn tìm cách cải thiện dần dần.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Liên tục săm soi, chỉ trích bản thân để bắt buộc mình phải hoàn hảo bằng mọi giá.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5602, 942, 'hook', '{\"title\": \"Bạn có cảm thấy mình như một lò hơi đang bị tăng áp suất quá mức?\"}', 1, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5603, 942, 'explanation', '{\"bullets\": [\"Stress (căng thẳng) là phản ứng tự nhiên của cơ thể khi đối mặt với các áp lực, thử thách trong cuộc sống.\", \"Ở tuổi teen, stress có thể đến từ việc học tập, thi cử, kỳ vọng của cha mẹ, mâu thuẫn bạn bè hay sự thay đổi của cơ thể.\", \"Một lượng stress vừa phải có thể giúp bạn tập trung, nhưng stress kéo dài sẽ làm cạn kiệt năng lượng tinh thần và thể chất của bạn.\"]}', 2, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5604, 942, 'scenario', '{\"title\": \"Tình huống quá tải\", \"body\": \"Kỳ thi học kỳ đang đến gần. Khang vừa phải hoàn thành đống bài tập về nhà, vừa phải đi học thêm tối ngày, lại chịu thêm áp lực phải lọt vào top 5 của lớp theo yêu cầu của bố. Khang bắt đầu thấy đau đầu âm ỉ và không thể tập trung học bài.\"}', 3, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5605, 942, 'interaction', '{\"question\": \"Khang nên nhận diện tình trạng của mình lúc này như thế nào?\", \"choices\": [{\"text\": \"Đây là tín hiệu cảnh báo stress của cơ thể, Khang cần nghỉ ngơi ngắn để tái tạo năng lượng thay vì cố học tiếp.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Khang chỉ đang lười biếng và thiếu quyết tâm, cần uống thêm cà phê để thức đêm học cho xong bài.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5606, 942, 'reflection', '{\"question\": \"Nguồn gây stress lớn nhất của bạn trong tuần này là gì?\"}', 5, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5607, 942, 'takeaway', '{\"items\": [\"Stress không phải là thứ xảy ra với bạn, nó là cách bạn phản ứng với những gì xảy ra.\"]}', 6, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5608, 943, 'hook', '{\"title\": \"Làm sao để biết cơ thể bạn đang kêu cứu vì kiệt sức?\"}', 1, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5609, 943, 'explanation', '{\"bullets\": [\"Khi stress vượt quá giới hạn chịu đựng, cơ thể và tâm trí sẽ phát ra các tín hiệu quá tải rõ rệt.\", \"Về thể chất: mất ngủ, rụng tóc, đau dạ dày, uể oải.\", \"Về tinh thần: dễ nổi cáu, khóc lóc vô cớ, lo âu thường trực, hoặc muốn thu mình lại trốn tránh thế giới.\"]}', 2, '2026-07-07 01:57:49', '2026-07-07 01:57:49');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(5610, 943, 'scenario', '{\"title\": \"Tình huống nhạy cảm\", \"body\": \"Dạo gần đây, Vy thấy mình rất dễ nổi giận. Chỉ cần mẹ hỏi han nhẹ nhàng hay em trai mượn cục tẩy là Vy đã hét toáng lên cáu gắt. Đêm đến Vy lại nằm trằn trọc không ngủ được, đầu óc quay cuồng nghĩ về đống deadline học tập.\"}', 3, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5611, 943, 'interaction', '{\"question\": \"Sự cáu gắt và mất ngủ của Vy là biểu hiện của điều gì?\", \"choices\": [{\"text\": \"Đó là các tín hiệu quá tải do stress tích tụ lâu ngày, Vy cần tìm cách giải tỏa căng thẳng.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Vy đang trở thành một đứa con hư, tính khí thất thường và cần phải tự chấn chỉnh lại đạo đức.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5612, 943, 'reflection', '{\"question\": \"Khi bị quá tải, phản ứng đầu tiên của bạn là cáu gắt ra bên ngoài hay thu mình vào bên trong?\"}', 5, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5613, 943, 'takeaway', '{\"items\": [\"Hãy lắng nghe cơ thể khi nó thì thầm, để không phải nghe nó hét lên khi đổ bệnh.\"]}', 6, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5614, 944, 'hook', '{\"title\": \"Bạn có từng thấy cô độc ngay cả khi đang đứng giữa sân trường đông đúc?\"}', 1, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5615, 944, 'explanation', '{\"bullets\": [\"Cô đơn không phải là khi bạn ở một mình, mà là cảm giác ngắt kết nối - thấy không ai hiểu hoặc quan tâm đến mình.\", \"Ở tuổi teen, sự thay đổi tâm sinh lý và áp lực định hình bản thân dễ khiến bạn thấy lạc lõng, cảm giác như mình là kẻ đứng ngoài cuộc chơi.\", \"Đây là một trải nghiệm cảm xúc bình thường, và hầu hết bạn bè xung quanh đôi lúc cũng có cảm giác giống hệt bạn.\"]}', 2, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5616, 944, 'scenario', '{\"title\": \"Tình huống lạc lõng\", \"body\": \"Nam ngồi ở góc canteen trường lướt điện thoại, nhìn nhóm bạn bàn bên cười nói rôm rả. Nam thấy lồng ngực trống rỗng, tủi thân nghĩ rằng mình không có những người bạn thực sự và nếu mình biến mất thì cũng không ai hay biết.\"}', 3, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5617, 944, 'interaction', '{\"question\": \"Nam nên làm gì để đối phó với cảm giác cô đơn này một cách lành mạnh?\", \"choices\": [{\"text\": \"Chủ động cất điện thoại, lại gần hỏi han một bạn cũng đang ngồi một mình hoặc tham gia một câu lạc bộ sở thích.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tiếp tục ngồi im gặm nhấm nỗi buồn và đăng một status tâm trạng lên mạng xã hội để chờ người khác đến dỗ dành.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5618, 944, 'reflection', '{\"question\": \"Bạn thường làm gì để tự an ủi bản thân mỗi khi cảm giác cô đơn ập đến?\"}', 5, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5619, 944, 'takeaway', '{\"items\": [\"Cô đơn là một cảm giác, không phải là sự thật về giá trị hay vị trí của bạn trong lòng mọi người.\"]}', 6, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5620, 945, 'hook', '{\"title\": \"Điểm số có quyết định tương lai và giá trị con người bạn?\"}', 1, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5621, 945, 'explanation', '{\"bullets\": [\"Mùa thi cử là một trong những giai đoạn gây stress kinh khủng nhất đối với học sinh Việt Nam.\", \"Sự kỳ vọng lớn từ bố mẹ cộng với tâm lý sợ thất bại khiến bạn luôn sống trong trạng thái lo âu, hoảng loạn.\", \"Hãy nhớ rằng: Bài thi chỉ đánh giá kiến thức của bạn tại một thời điểm, nó không bao giờ định nghĩa được trí tuệ, sự tử tế hay giá trị cả đời của bạn.\"]}', 2, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5622, 945, 'scenario', '{\"title\": \"Tình huống phòng thi\", \"body\": \"Mai cầm tờ đề thi Toán lên và thấy đầu óc trống rỗng hoàn toàn, tim đập thình thịch như muốn nhảy ra ngoài, tay run bần bật không viết nổi chữ nào dù tối qua đã ôn bài rất kỹ. Mai hoảng loạn nghĩ mình sẽ trượt và làm bố mẹ thất vọng tràn trề.\"}', 3, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5623, 945, 'interaction', '{\"question\": \"Mai nên làm gì ngay lập tức để lấy lại sự bình tĩnh trong phòng thi?\", \"choices\": [{\"text\": \"Buông bút, nhắm mắt lại, hít vào thật sâu 4 giây và thở ra chậm 8 giây trong 3 nhịp để nhịp tim ổn định lại.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Cố gắng cắm đầu vào viết đại đáp án bất kỳ dù đầu óc đang hoảng loạn để không bị lãng phí thời gian làm bài.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5624, 945, 'reflection', '{\"question\": \"Bố mẹ thường nói gì trước mỗi kỳ thi khiến bạn thấy áp lực hoặc thoải mái nhất?\"}', 5, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5625, 945, 'takeaway', '{\"items\": [\"Một bài thi không tốt chỉ là một bài học kinh nghiệm, không phải là dấu chấm hết cho tương lai của bạn.\"]}', 6, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5626, 946, 'hook', '{\"title\": \"Bạn đã xây dựng hộp công cụ giải cứu tinh thần cho riêng mình chưa?\"}', 1, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5627, 946, 'explanation', '{\"bullets\": [\"Stress cần được giải phóng ra khỏi cơ thể một cách vật lý, không thể chỉ dùng suy nghĩ để kiểm soát.\", \"Hãy trang bị cho mình những công cụ xả stress đơn giản mà hiệu quả:\", \"1. **Vận động:** Chạy bộ, nhảy dây, nhảy tự do theo nhạc để đốt cháy hormone stress cortisol.\", \"2. **Hơi thở:** Kỹ thuật thở hộp (box breathing) hoặc thở bụng chậm.\", \"3. **Viết lách:** Viết xả giận (brain dump) - viết hết mọi suy nghĩ lộn xộn ra giấy rồi xé đi.\"]}', 2, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5628, 946, 'scenario', '{\"title\": \"Tình huống xả áp\", \"body\": \"Sau một ngày học tập mệt mỏi và cãi nhau với bạn bè, Chi thấy đầu óc như muốn nổ tung. Thay vì nằm lướt điện thoại tiếp, Chi bật một bản nhạc sôi động lên và tự do nhảy múa, đấm đá vào không trung trong phòng riêng suốt 10 phút.\"}', 3, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5629, 946, 'interaction', '{\"question\": \"Hành động của Chi có tác dụng gì đối với lượng stress trong cơ thể?\", \"choices\": [{\"text\": \"Giúp giải phóng hormone endorphin để cải thiện tâm trạng và đào thải bớt cortisol gây căng thẳng.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Chỉ là hành động kỳ quặc làm mất thời gian, Chi nên ngồi im suy nghĩ để giải quyết mâu thuẫn với bạn thì hơn.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5630, 946, 'reflection', '{\"question\": \"Phương pháp xả stress nào hiệu quả nhất với bạn từ trước đến nay?\"}', 5, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5631, 946, 'takeaway', '{\"items\": [\"Đừng giữ stress trong người, hãy cho nó một lối thoát vật lý lành mạnh.\"]}', 6, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5632, 947, 'hook', '{\"title\": \"Thất bại là một đòn đánh gục lòng tự trọng, hay là một ngã rẽ học tập?\"}', 1, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5633, 947, 'explanation', '{\"bullets\": [\"Bị từ chối (tỏ tình thất bại, trượt câu lạc bộ) hay thất bại (điểm kém, thua cuộc thi) là những trải nghiệm đau đớn.\", \"Phản ứng tự nhiên là tự trách mình kém cỏi hoặc giận dữ đổ lỗi cho hoàn cảnh.\", \"Sự phục hồi đến từ việc bạn chấp nhận nỗi buồn của thất bại, nhưng không để thất bại đó định nghĩa năng lực lâu dài của bản thân.\"]}', 2, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5634, 947, 'scenario', '{\"title\": \"Tình huống trượt tuyển\", \"body\": \"Đức rất muốn tham gia câu lạc bộ bóng rổ của trường nhưng bị loại ở vòng tuyển chọn cuối cùng. Đức thấy xấu hổ với bạn bè và tự nhủ: \\\"Mình thật vô dụng, từ nay sẽ không bao giờ đụng vào quả bóng rổ nữa\\\".\"}', 3, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5635, 947, 'interaction', '{\"question\": \"Đức nên thay đổi cách nhìn nhận về thất bại này như thế nào để kiên cường hơn?\", \"choices\": [{\"text\": \"Nhìn nhận: \'Bị loại lần này chỉ có nghĩa là kỹ năng hiện tại của mình chưa đủ, mình sẽ tiếp tục tập luyện để năm sau thử lại\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Cho rằng ban giám khảo thiên vị và ghét bỏ mình, tìm cách nói xấu câu lạc bộ bóng rổ với người khác.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:49', '2026-07-07 01:57:49'),
(5636, 947, 'reflection', '{\"question\": \"Một lần thất bại nào trong quá khứ đã giúp bạn học được một bài học quý giá nhất?\"}', 5, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5637, 947, 'takeaway', '{\"items\": [\"Thất bại chỉ là một sự kiện, nó không bao giờ là một con người.\"]}', 6, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5638, 948, 'hook', '{\"title\": \"Tại sao chúng ta phải cố tỏ ra mạnh mẽ khi bên trong đang vỡ vụn?\"}', 1, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5639, 948, 'explanation', '{\"bullets\": [\"Áp lực từ xã hội thường bắt chúng ta phải luôn tích cực, vui vẻ và thành công.\", \"Nhưng việc thừa nhận rằng \\\"Hôm nay mình rất tệ và mình cần sự giúp đỡ\\\" là một hành động dũng cảm, không phải sự yếu đuối.\", \"Khi cảm xúc khó khăn kéo dài quá 2 tuần và ảnh hưởng đến cuộc sống, đã đến lúc bạn cần tìm kiếm sự hỗ trợ từ chuyên gia hoặc người lớn tin cậy.\"]}', 2, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5640, 948, 'scenario', '{\"title\": \"Tình huống cầu cứu\", \"body\": \"Bảo cảm thấy buồn bã, mất ngủ và chán ăn suốt một tháng nay sau khi bố mẹ ly hôn. Bảo không dám nói với ai vì sợ mọi người nghĩ mình là đứa trẻ rắc rối, ủy mị. Bảo cảm thấy mình như đang chìm xuống một cái hố sâu không đáy.\"}', 3, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5641, 948, 'interaction', '{\"question\": \"Hành động đúng đắn và dũng cảm nhất Bảo nên làm lúc này là gì?\", \"choices\": [{\"text\": \"Chủ động tìm gặp cô giáo tâm lý trường hoặc chia sẻ thật lòng tình trạng của mình với mẹ để được đưa đi tham vấn chuyên khoa.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tiếp tục chịu đựng âm thầm, hy vọng thời gian sẽ tự động xóa nhòa mọi vết thương lòng của mình.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5642, 948, 'reflection', '{\"question\": \"Ai là người đầu tiên bạn sẽ tìm đến khi cảm thấy thế giới của mình đang sụp đổ?\"}', 5, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5643, 948, 'takeaway', '{\"items\": [\"Yêu cầu sự giúp đỡ không phải là đầu hàng, đó là từ chối đầu hàng trước khó khăn.\"]}', 6, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5644, 949, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Quản lý stress & Cảm xúc khó khăn\'! Cùng nạp năng lượng để dập tắt ngọn lửa quá tải nhé.\"}', 1, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5645, 949, 'scenario-choice', '{\"title\": \"Vượt qua khủng hoảng học đường\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn cảm thấy lo âu, mất ngủ và đau dạ dày liên tục suốt 3 tuần nay sau khi chuyển sang lớp học mới có áp lực cạnh tranh điểm số cao.\", \"choices\": [{\"text\": \"Tiếp tục cố gắng chịu đựng, giấu kín cảm xúc vì sợ bố mẹ mắng là yếu đuối.\", \"nextNode\": \"fail_submit\"}, {\"text\": \"Thừa nhận rằng mình đang bị quá tải, chia sẻ thật lòng tình trạng của mình với mẹ để được giúp đỡ.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Mẹ lắng nghe và đề xuất đưa bạn đến gặp chuyên gia tư vấn tâm lý học đường, nhưng bạn lo sợ các bạn cùng lớp sẽ biết và trêu chọc bạn là kẻ chập mạch.\", \"choices\": [{\"text\": \"Từ chối đi gặp chuyên gia để bảo vệ thể diện trước bạn bè.\", \"nextNode\": \"fail_guilt\"}, {\"text\": \"Vượt qua nỗi sợ, đi gặp chuyên gia vì hiểu rằng sức khỏe tinh thần của mình là quan trọng nhất.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã dũng cảm đối diện với stress quá tải, tìm kiếm sự hỗ trợ chuyên nghiệp đúng lúc để bảo vệ bản thân.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_submit\": {\"text\": \"❌ Thất bại! Im lặng chịu đựng tình trạng quá tải tinh thần kéo dài sẽ tàn phá cả thể chất lẫn tâm lý của bạn nghiêm trọng.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_guilt\": {\"text\": \"❌ Thất bại! Đánh đổi sức khỏe tâm lý lấy sự đánh giá hời hợt của bạn bè xung quanh là một lựa chọn cực kỳ sai lầm.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5646, 949, 'sorting', '{\"instruction\": \"Hãy phân loại các nguồn gây áp lực lên cuộc sống của bạn:\", \"leftBox\": {\"title\": \"Áp lực kiểm soát được (Tập trung nỗ lực)\"}, \"rightBox\": {\"title\": \"Áp lực không kiểm soát được (Nên buông bỏ)\"}, \"items\": [{\"text\": \"Phương pháp ôn tập bài thi của bản thân\", \"correctBox\": \"left\"}, {\"text\": \"Ý kiến hay sự đánh giá của bạn bè cùng lớp\", \"correctBox\": \"right\"}, {\"text\": \"Thời gian phân bổ cho việc nghỉ ngơi hợp lý\", \"correctBox\": \"left\"}, {\"text\": \"Đề thi học kỳ chính thức khó hay dễ\", \"correctBox\": \"right\"}]}', 3, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5647, 949, 'matching', '{\"instruction\": \"Ghép cặp các phương pháp xả stress sau với tác dụng tương ứng:\", \"pairs\": [{\"left\": \"Thở 4-7-8\", \"right\": \"Làm dịu nhanh nhịp tim và hệ thần kinh lo âu\"}, {\"left\": \"Vận động mạnh\", \"right\": \"Đốt cháy bớt hormone stress cortisol dư thừa\"}, {\"left\": \"Viết brain dump\", \"right\": \"Xả hết mọi suy nghĩ lộn xộn trong đầu ra giấy\"}, {\"left\": \"Tự xoa dịu\", \"right\": \"Thực hành tắm nước ấm, nghe nhạc nhẹ hồi sức\"}]}', 4, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5648, 949, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về cách quản lý stress:\", \"sentence\": \"Stress kéo dài sẽ khiến cơ thể rơi vào tình trạng [blank1]. Đừng cố gắng [blank2] cảm xúc một mình. Hãy tìm cách chia sẻ với một người lớn [blank3] để tìm kiếm lối thoát an toàn.\", \"blanks\": {\"blank1\": {\"correct\": \"quải tải\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"gánh vác\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"tin cậy\", \"placeholder\": \"...\"}}, \"words\": [\"quá tải\", \"gánh vác\", \"tin cậy\", \"thoải mái\", \"đè nén\", \"xa lạ\"]}', 5, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5649, 949, 'interaction', '{\"question\": \"Đâu là nhận định chính xác nhất về việc tìm kiếm sự trợ giúp tâm lý khi bị quá tải?\", \"choices\": [{\"text\": \"Yêu cầu sự giúp đỡ là biểu hiện của sự dũng cảm và ý thức tự chịu trách nhiệm cao với bản thân.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Chỉ những đứa trẻ yếu đuối, ủy mị mới cần người khác nâng đỡ cảm xúc.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5650, 950, 'hook', '{\"title\": \"Bạn có từng làm một việc mình không thích chỉ vì sợ bị coi là kẻ lạc loài trong nhóm?\"}', 1, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5651, 950, 'explanation', '{\"bullets\": [\"Áp lực bạn bè (Peer Pressure) là sự ảnh hưởng từ nhóm bạn học lên suy nghĩ, hành vi và lựa chọn của bạn.\", \"Nó có thể là áp lực tích cực (rủ nhau học nhóm, tập thể thao) hoặc áp lực tiêu cực (rủ cúp học, nói xấu người khác, thử chất kích thích).\", \"Áp lực này cực kỳ mạnh mẽ vì nhu cầu được thuộc về một tập thể và nỗi sợ bị cô lập ở tuổi dậy thì là rất lớn.\"]}', 2, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5652, 950, 'scenario', '{\"title\": \"Tình huống bắt chước\", \"body\": \"Cả nhóm bạn thân của Huy đều bắt đầu đi xe máy phân khối lớn đi học dù chưa đủ tuổi và chưa có bằng lái. Các bạn liên tục rủ Huy tham gia hội đua xe mini sau giờ học. Huy thấy rất sợ tai nạn nhưng cũng sợ bị các bạn kích ra khỏi nhóm.\"}', 3, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5653, 950, 'interaction', '{\"question\": \"Áp lực mà Huy đang trải qua thuộc loại nào?\", \"choices\": [{\"text\": \"Áp lực nhóm tiêu cực, thúc đẩy hành vi nguy hiểm vi phạm pháp luật và đe dọa an toàn thể chất.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Trò chơi giao lưu bạn bè bình thường giúp tăng tính gắn kết tập thể của tuổi học trò.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5654, 950, 'reflection', '{\"question\": \"Bạn đã bao giờ thay đổi phong cách ăn mặc hay cách nói chuyện chỉ để được một nhóm bạn chấp nhận chưa?\"}', 5, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5655, 950, 'takeaway', '{\"items\": [\"Một tình bạn thực sự sẽ tôn trọng lựa chọn cá nhân của bạn, không ép bạn phải giống hệt họ.\"]}', 6, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5656, 951, 'hook', '{\"title\": \"Làm sao để vạch mặt những lời khích tướng ngọt ngào của áp lực bạn bè?\"}', 1, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5657, 951, 'explanation', '{\"bullets\": [\"Áp lực nhóm tiêu cực không phải lúc nào cũng biểu hiện bằng sự đe dọa thô bạo. Nó thường ẩn mình dưới các chiêu thức tinh vi:\", \"1. **Khích tướng:** Bạn nhát thế, không chơi là không phải đàn ông/đứa cá tính.\", \"2. **Bình thường hóa:** Ai chả làm thế, cả trường này đứa nào chả thử rồi.\", \"3. **Tẩy chay ngầm:** Lờ đi không rủ đi chơi chung, không trả lời tin nhắn trong group nếu không nghe lời.\"]}', 2, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5658, 951, 'scenario', '{\"title\": \"Tình huống khích tướng\", \"body\": \"Tại buổi tụ tập sinh nhật, nhóm bạn ép Vy uống thử một ly bia. Khi Vy từ chối, một bạn bĩu môi nói: \\\"Tiểu thư thế cậu, uống một hớp có chết ai đâu, cả bọn uống hết rồi kìa. Hay sợ về bị mẹ phạt?\\\". Mọi người xung quanh nhìn Vy cười cợt.\"}', 3, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5659, 951, 'interaction', '{\"question\": \"Chiêu thức áp lực bạn bè nào đang được áp dụng lên Vy?\", \"choices\": [{\"text\": \"Sự khích tướng và bình thường hóa hành vi tiêu cực để ép Vy phá vỡ ranh giới cá nhân.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Sự quan tâm chân thành muốn Vy vui vẻ hòa nhập cùng buổi tiệc sinh nhật.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5660, 951, 'reflection', '{\"question\": \"Bạn đã từng nghe câu nói khích tướng nào từ bạn bè khiến bạn thấy khó từ chối nhất?\"}', 5, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5661, 951, 'takeaway', '{\"items\": [\"Khi họ khích tướng bạn, thực chất họ đang sợ hãi việc phải làm điều đó một mình.\"]}', 6, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5662, 952, 'hook', '{\"title\": \"Nỗi sợ bị tẩy chay có thực sự tồi tệ như một cơn đau thể xác?\"}', 1, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5663, 952, 'explanation', '{\"bullets\": [\"Các nghiên cứu khoa học cho thấy vùng não xử lý nỗi đau bị xã hội cô lập trùng khớp với vùng não xử lý cơn đau vật lý.\", \"Vì vậy, sợ làm \\\"kẻ lập dị\\\", sợ bị tẩy chay hay không thuộc về nhóm là một bản năng sinh tồn mạnh mẽ của con người.\", \"Tuy nhiên, việc đánh đổi ranh giới an toàn và giá trị của bản thân để đổi lấy sự chấp nhận giả tạo từ một nhóm bạn độc hại sẽ chỉ mang lại sự đau khổ lâu dài.\"]}', 2, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5664, 952, 'scenario', '{\"title\": \"Tình huống sợ lạc loài\", \"body\": \"Nam phát hiện nhóm bạn thân của mình đang lập nhóm bắt nạt một bạn học yếu thế trong lớp. Nam thấy việc này là sai trái và rất thương bạn kia, nhưng sợ rằng nếu lên tiếng can ngăn thì chính mình sẽ bị cả nhóm quay lưng tẩy chay.\"}', 3, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5665, 952, 'interaction', '{\"question\": \"Nỗi sợ bị tẩy chay đang cản trở Nam làm điều gì?\", \"choices\": [{\"text\": \"Cản trở Nam đứng lên bảo vệ lẽ phải và sống đúng với giá trị nhân ái của chính mình.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Giúp Nam giữ được sự an toàn và hòa đồng cần thiết để tồn tại trong môi trường học đường nhiều rắc rối.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5666, 952, 'reflection', '{\"question\": \"Bạn có sẵn lòng đứng một mình để bảo vệ điều bạn tin là đúng không?\"}', 5, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5667, 952, 'takeaway', '{\"items\": [\"Chấp nhận đứng một mình còn hơn đi chung đường với những kẻ bắt bạn phải đánh mất chính mình.\"]}', 6, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5668, 953, 'hook', '{\"title\": \"Bạn sẽ làm gì khi lời rủ rê đi kèm với cái mác: Trải nghiệm tuổi trẻ?\"}', 1, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5669, 953, 'explanation', '{\"bullets\": [\"Tuổi trẻ thường đi liền với sự tò mò và khát khao thử nghiệm những điều mới mẻ.\", \"Kẻ xấu hoặc bạn bè không tốt thường lợi dụng điều này để rủ rê bạn thử các hành vi mạo hiểm: hút pod, cúp học đi net, thử chất kích thích hoặc gửi ảnh nhạy cảm.\", \"Ranh giới giữa \\\"trải nghiệm khám phá\\\" và \\\"hành vi hủy hoại bản thân\\\" là sự an toàn và quyền tự do lựa chọn không bị ép buộc.\"]}', 2, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5670, 953, 'scenario', '{\"title\": \"Tình huống pod\", \"body\": \"Tại nhà vệ sinh trường, hai bạn cùng lớp kéo Lâm vào góc và đưa cho Lâm một chiếc pod (thuốc lá điện tử) bảo: \\\"Hút thử đi, vị dâu thơm lắm, không nghiện đâu mà sợ. Cả lớp này ai chả hút rồi\\\". Lâm thực sự e ngại tác hại của khói thuốc lên phổi của mình.\"}', 3, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5671, 953, 'interaction', '{\"question\": \"Lâm nên ứng phó thế nào trước lời rủ rê này?\", \"choices\": [{\"text\": \"Kiên định từ chối: \'Tớ không thích khói thuốc đâu, ngửi mùi đã thấy ho rồi\' và chủ động bước ra khỏi nhà vệ sinh.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Hút thử một hơi cho biết vị và để các bạn không trêu mình là nhát gan, sau đó nhổ ra ngay.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5672, 953, 'reflection', '{\"question\": \"Bạn đã bao giờ đứng trước một lời rủ rê mạo hiểm chưa? Quyết định lúc đó của bạn thế nào?\"}', 5, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5673, 953, 'takeaway', '{\"items\": [\"Trải nghiệm thực sự là khi bạn tự do khám phá thế giới trong sự an toàn, không phải là tự đưa mình vào bẫy.\"]}', 6, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5674, 954, 'hook', '{\"title\": \"Làm sao để nói Không dứt khoát với bạn bè mà không làm rạn nứt mối quan hệ?\"}', 1, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5675, 954, 'explanation', '{\"bullets\": [\"Từ chối bạn bè là một nghệ thuật giao tiếp cần sự luyện tập. Bạn có thể áp dụng 3 kỹ thuật từ chối tinh tế sau:\", \"1. **Dùng lý do khách quan vững chắc:** Tớ bị dị ứng mùi này, hoặc tớ có hẹn với mẹ rồi.\", \"2. **Kỹ thuật đĩa hát hỏng:** Lặp đi lặp lại một câu từ chối ngắn gọn mà không giải thích thêm (ví dụ: \'Tớ không đi đâu. Ừ, tớ không đi được thật mà\').\", \"3. **Chuyển hướng chủ đề:** Đề xuất một hoạt động lành mạnh khác thay thế (ví dụ: \'Tớ không uống bia đâu, tí tụi mình đi trà chanh đi!\').\"]}', 2, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5676, 954, 'scenario', '{\"title\": \"Tình huống cúp học\", \"body\": \"Chiều thứ Bảy, nhóm bạn rủ Trang cúp tiết học thêm Toán để đi xem phim rạp. Các bạn giục giã: \\\"Đi đi, buổi này cô giáo không điểm danh đâu mà lo\\\". Trang muốn học để chuẩn bị cho bài kiểm tra tuần sau nhưng sợ các bạn giận.\"}', 3, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5677, 954, 'interaction', '{\"question\": \"Trang nên áp dụng kỹ thuật từ chối nào để từ chối nhóm bạn tinh tế nhất?\", \"choices\": [{\"text\": \"Sử dụng kỹ thuật chuyển hướng: \'Tớ không cúp học được đâu vì bài tuần sau rất khó. Tối tụi mình đi ăn ốc sau giờ học nhé!\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Nói dối vòng vo: \'Tớ thấy hơi đau bụng để tớ xin phép mẹ đã...\' rồi im lặng trốn luôn không trả lời tin nhắn.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5678, 954, 'reflection', '{\"question\": \"Bạn cảm thấy thoải mái nhất với kỹ thuật từ chối nào trong 3 cách trên?\"}', 5, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5679, 954, 'takeaway', '{\"items\": [\"Nói Không với người khác là cách bạn nói Có với những ưu tiên và giá trị của chính mình.\"]}', 6, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5680, 955, 'hook', '{\"title\": \"Bạn có dám là người cầm lái cuộc đời mình, hay để đám đông định đoạt hướng đi?\"}', 1, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5681, 955, 'explanation', '{\"bullets\": [\"Việc đi theo đám đông mang lại cảm giác an toàn và nhàn nhã vì bạn không phải suy nghĩ hay chịu trách nhiệm cho các lựa chọn của mình.\", \"Nhưng đứng độc lập (Autonomy) - tự đưa ra quyết định dựa trên hệ giá trị riêng - mới là chìa khóa giúp bạn trưởng thành và tự tin thực sự.\", \"Mỗi lựa chọn nhỏ hôm nay (chọn học bài thay vì đi chơi game, chọn không hùa theo trò đùa ác ý) đều đang định hình con người tương lai của bạn.\"]}', 2, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5682, 955, 'scenario', '{\"title\": \"Tình huống định hướng\", \"body\": \"Cả lớp của An đang phong trào tẩy chay một bạn học mới chuyển trường đến vì bạn ấy ăn mặc lỗi thời và nói giọng địa phương. An thấy bạn ấy rất hiền lành và muốn kết bạn, nhưng sợ cả lớp sẽ quay sang tẩy chay luôn cả mình.\"}', 3, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5683, 955, 'interaction', '{\"question\": \"Quyết định tự chủ và dũng cảm nhất của An lúc này là gì?\", \"choices\": [{\"text\": \"Chủ động lại gần bắt chuyện, cho bạn mới mượn sách và rủ bạn cùng ăn trưa bất chấp sự xì xào của cả lớp.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Nghe theo đám đông, cũng lờ bạn mới đi để bảo vệ vị trí an toàn của mình trong lớp học.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5684, 955, 'reflection', '{\"question\": \"Bạn đã bao giờ đi ngược lại số đông để bảo vệ một quyết định cá nhân chưa? Cảm giác lúc đó thế nào?\"}', 5, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5685, 955, 'takeaway', '{\"items\": [\"Đám đông có thể mang lại sự an toàn tạm thời, nhưng tự chủ mới mang lại sự tự do đích thực.\"]}', 6, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5686, 956, 'hook', '{\"title\": \"Ai mới thực sự là người chịu trách nhiệm cho cuộc đời bạn sau này?\"}', 1, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5687, 956, 'explanation', '{\"bullets\": [\"Khi bạn làm theo áp lực bạn bè và gặp rắc rối, những người ép buộc bạn sẽ không đứng ra chịu trách nhiệm thay bạn.\", \"Quyền kiểm soát cơ thể, thời gian và tương lai hoàn toàn nằm trong tay bạn.\", \"Tôn trọng ranhới của bản thân và kiên định với những lựa chọn lành mạnh là tấm khiên vững chắc nhất bảo vệ cuộc sống của bạn.\"]}', 2, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5688, 956, 'scenario', '{\"title\": \"Tình huống chịu hậu quả\", \"body\": \"Sau khi bị các bạn khích tướng cúp học đi chơi net, Huy bị nhà trường phát hiện, gửi thông báo đình chỉ học về gia đình. Nhóm bạn rủ Huy hôm trước lập tức lảng tránh và bảo: \\\"Tại Huy đen thôi chứ tụi này đi suốt có sao đâu\\\". Huy thấy vô cùng ân hận và bất lực.\"}', 3, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5689, 956, 'interaction', '{\"question\": \"Huy rút ra bài học gì sâu sắc nhất sau sự việc này?\", \"choices\": [{\"text\": \"Hiểu rõ rằng mình mới là người chịu trách nhiệm cuối cùng cho mọi hành vi của mình, từ nay sẽ tự quyết định không nghe lời khích tướng.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Trách móc nhóm bạn tồi tệ và tìm cách trả đũa họ vì đã lừa mình vào tình thế rắc rối.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5690, 956, 'reflection', '{\"question\": \"Hôm nay, bạn muốn nói Có với điều gì và nói Không với điều gì để bảo vệ tương lai của mình?\"}', 5, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5691, 956, 'takeaway', '{\"items\": [\"Bạn là thuyền trưởng của con tàu cuộc đời bạn. Đừng để người khác cầm lái thay bạn.\"]}', 6, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5692, 957, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Áp lực bạn bè & Lựa chọn lành mạnh\'! Hãy chứng minh bản lĩnh vững vàng cầm lái cuộc đời mình nhé.\"}', 1, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5693, 957, 'scenario-choice', '{\"title\": \"Lời mời thử thách pod\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Trong buổi dã ngoại trường, nhóm bạn lôi ra một cây thuốc lá điện tử và ép bạn hút thử. Bạn từ chối thì bạn thân khích tướng: \'Không hút thì cút ra ngoài, tụi này không chơi với đứa nhát gan\'.\", \"choices\": [{\"text\": \"Tặc lưỡi hút thử một hơi để được ở lại chơi chung với nhóm bạn thân.\", \"nextNode\": \"fail_submit\"}, {\"text\": \"Kiên định từ chối: \'Tớ không thích khói thuốc đâu. Nếu các cậu vì chuyện này mà không chơi với tớ thì chịu vậy\' và đi ra chỗ khác.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Các bạn thấy bạn dứt khoát thì bắt đầu dịu giọng bảo: \'Đùa tí thôi làm gì căng, vào đây chơi tiếp đi\' nhưng lại đưa điện thoại chụp trộm khoảnh khắc bạn bị cô lập định đăng lên nhóm lớp.\", \"choices\": [{\"text\": \"Im lặng để các bạn chụp ảnh và đăng lên vì sợ cãi nhau lần nữa.\", \"nextNode\": \"fail_guilt\"}, {\"text\": \"Nghiêm túc nói: \'Xóa ngay đi, tớ không cho phép các cậu đăng hình ảnh riêng tư của tớ lên mạng đâu\'.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã thể hiện bản lĩnh tự chủ tuyệt vời, bảo vệ được sức khỏe và ranh giới hình ảnh cá nhân trước sự thao túng nhóm.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_submit\": {\"text\": \"❌ Thất bại! Nhượng bộ hút thuốc lá điện tử dưới áp lực nhóm sẽ mở đường cho các hành vi mạo hiểm nguy hại hơn trong tương lai.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_guilt\": {\"text\": \"❌ Thất bại! Chấp nhận để các bạn chụp ảnh dìm hàng cô lập mình lên nhóm lớp là bạn đang tiếp tay cho hành vi bắt nạt học đường tiếp diễn.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5694, 957, 'sorting', '{\"instruction\": \"Hãy phân loại các hình thức tác động của bạn bè xung quanh:\", \"leftBox\": {\"title\": \"Áp lực nhóm tiêu cực (Cần tránh xa)\"}, \"rightBox\": {\"title\": \"Ảnh hưởng nhóm tích cực (Nên phát huy)\"}, \"items\": [{\"text\": \"Khích tướng thử chất kích thích để chứng tỏ bản thân\", \"correctBox\": \"left\"}, {\"text\": \"Rủ nhau đăng ký lớp học kỹ năng mềm vào dịp hè\", \"correctBox\": \"right\"}, {\"text\": \"Tẩy chay ngầm vì bạn không chịu cúp học đi net\", \"correctBox\": \"left\"}, {\"text\": \"Cổ vũ bạn tập luyện bóng rổ nâng cao sức khỏe\", \"correctBox\": \"right\"}]}', 3, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5695, 957, 'matching', '{\"instruction\": \"Ghép cặp các kỹ thuật từ chối áp lực bạn bè sau:\", \"pairs\": [{\"left\": \"Đĩa hát hỏng\", \"right\": \"Lặp đi lặp lại một câu từ chối ngắn gọn dứt khoát\"}, {\"left\": \"Chuyển hướng chủ đề\", \"right\": \"Từ chối và đề xuất một hoạt động lành mạnh khác\"}, {\"left\": \"Lý do khách quan\", \"right\": \"Đưa ra một lý do thực tế không thể thương lượng\"}, {\"left\": \"Sự tự chủ\", \"right\": \"Quyết định dựa trên giá trị riêng của bản thân\"}]}', 4, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5696, 957, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về áp lực bạn bè:\", \"sentence\": \"Nhu cầu được [blank1] vào nhóm ở tuổi dậy thì rất lớn, làm bạn dễ thỏa hiệp. Khi gặp lời rủ rê nguy hiểm, hãy dùng kỹ thuật từ chối [blank2] và kiên quyết bước ra khỏi không gian ép buộc để bảo vệ quyền [blank3] của mình.\", \"blanks\": {\"blank1\": {\"correct\": \"thuộc\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"tinh tế\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"lựa chọn\", \"placeholder\": \"...\"}}, \"words\": [\"thuộc\", \"tinh tế\", \"lựa chọn\", \"tách\", \"thô bạo\", \"áp đặt\"]}', 5, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5697, 957, 'interaction', '{\"question\": \"Một tình bạn lành mạnh, chất lượng cao được định nghĩa bởi điều gì?\", \"choices\": [{\"text\": \"Tôn trọng ranh giới, tự do lựa chọn cá nhân và ủng hộ sự phát triển của nhau.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Luôn bắt buộc phải giống hệt nhau trong mọi suy nghĩ, hành động và sở thích.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5698, 958, 'hook', '{\"title\": \"Bạn giống như một miếng kính dễ vỡ khi va chạm, hay một quả bóng cao su nảy lên sau khi rơi?\"}', 1, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5699, 958, 'explanation', '{\"bullets\": [\"Khả năng phục hồi (Resilience) là năng lực vượt qua khó khăn, nghịch cảnh và đứng dậy mạnh mẽ hơn sau mỗi lần vấp ngã.\", \"Nó không có nghĩa là bạn không biết đau, biết buồn hay không bao giờ thất bại.\", \"Người kiên cường biết cách chấp nhận những cảm xúc đau đớn đó, tìm cách thích nghi và tiếp tục bước đi với những bài học mới.\"]}', 2, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5700, 958, 'scenario', '{\"title\": \"Tình huống đối diện\", \"body\": \"Nhạc và Khánh cùng bị trượt kỳ thi chuyển cấp vào trường chuyên. Nhạc suy sụp hoàn toàn, nằm bẹp ở nhà khóc lóc và tự dằn vặt mình suốt cả tháng. Khánh cũng rất buồn, nhưng sau một tuần, cậu lau nước mắt, ngồi lại bàn học lập kế hoạch ôn tập cho trường công lập gần nhà.\"}', 3, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5701, 958, 'interaction', '{\"question\": \"Ai là người đang thể hiện rõ khả năng phục hồi cảm xúc (resilience)?\", \"choices\": [{\"text\": \"Khánh, vì cậu biết chấp nhận thực tế buồn bã và chủ động tìm hướng đi mới thay vì dằn vặt bản thân lâu dài.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Nhạc, vì phản ứng suy sụp cho thấy cậu là người có trách nhiệm và đặt nhiều kỳ vọng vào học tập hơn.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5702, 958, 'reflection', '{\"question\": \"Bạn tự đánh giá khả năng phục hồi của mình sau mỗi lần thất bại là bao nhiêu điểm (thang điểm 1-10)?\"}', 5, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5703, 958, 'takeaway', '{\"items\": [\"Kiên cường không phải là không bao giờ ngã, mà là việc đứng dậy sau mỗi lần ngã.\"]}', 6, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5704, 959, 'hook', '{\"title\": \"Bạn nghĩ trí thông minh và tài năng của mình là cố định, hay có thể lớn lên?\"}', 1, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5705, 959, 'explanation', '{\"bullets\": [\"Cách bạn nhìn nhận về năng lực của mình quyết định rất lớn đến cách bạn đối mặt với khó khăn:\", \"**Tư duy cố định (Fixed Mindset):** Tin rằng tài năng là bẩm sinh. Khi thất bại tức là mình dốt, nên bỏ cuộc sớm để đỡ xấu hổ.\", \"**Tư duy phát triển (Growth Mindset):** Tin rằng năng lực có thể rèn luyện qua nỗ lực và học hỏi. Thất bại chỉ là bài học để nâng cấp bản thân.\"]}', 2, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5706, 959, 'scenario', '{\"title\": \"Tình huống học vẽ\", \"body\": \"Tại lớp học vẽ, khi bài vẽ của Vy bị thầy giáo nhận xét là bố cục chưa tốt và cần sửa lại rất nhiều. Vy nghĩ: \\\"Mình không có năng khiếu vẽ, mình nên bỏ học lớp này thôi\\\". Trong khi đó, Minh vui vẻ xin thầy hướng dẫn cách dựng lại khung hình để sửa bài.\"}', 3, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5707, 959, 'interaction', '{\"question\": \"Thái độ của Vy phản ánh loại tư duy nào?\", \"choices\": [{\"text\": \"Tư duy cố định, quy kết thất bại tạm thời vào năng lực bẩm sinh và muốn bỏ cuộc sớm.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tư duy phát triển thực tế, biết lượng sức mình để tránh lãng phí thời gian vào việc không có khiếu.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5708, 959, 'reflection', '{\"question\": \"Môn học hoặc kỹ năng nào bạn đang nghĩ mình không có khiếu? Bạn có sẵn lòng thử học lại với tư duy phát triển không?\"}', 5, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5709, 959, 'takeaway', '{\"items\": [\"Sai lầm chỉ là bằng chứng cho thấy bạn đang cố gắng và học hỏi.\"]}', 6, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5710, 960, 'hook', '{\"title\": \"Có phải lúc nào cũng tỏ ra cứng rắn mới là mạnh mẽ?\"}', 1, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5711, 960, 'explanation', '{\"bullets\": [\"Nhiều người nghĩ mạnh mẽ là phải gồng mình chịu đựng, không được khóc, không được chia sẻ sự tổn thương (Vulnerability).\", \"Thực chất, sự gồng mình cứng nhắc dễ khiến bạn bị gãy đổ khi gặp áp lực cực lớn (giống như một cành cây khô trước bão).\", \"Mạnh mẽ thực sự là sự mềm mại (Soften yourself) - dám thừa nhận sự sợ hãi, tổn thương của mình, chấp nhận cảm xúc và tìm kiếm sự nâng đỡ từ người khác (giống như nhành cỏ mềm dẻo trước gió bão).\"]}', 2, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5712, 960, 'scenario', '{\"title\": \"Tình huống gồng mình\", \"body\": \"Bố của An đột ngột qua đời. An cố giữ gương mặt không cảm xúc, không khóc trước mặt gia đình để làm chỗ dựa cho mẹ và em. Nhưng sau vài tuần, An thấy lồng ngực mình luôn đau nhói, mất ngủ triền miên và dễ nổi cáu vô cớ.\"}', 3, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5713, 960, 'interaction', '{\"question\": \"An nên làm gì để chăm sóc sức khỏe tinh thần của mình một cách mềm mại hơn?\", \"choices\": [{\"text\": \"Cho phép mình được khóc thật to, chia sẻ nỗi nhớ bố với mẹ và chấp nhận rằng mình đang rất đau lòng.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tiếp tục gồng mình tỏ ra cứng cỏi, giấu kín cảm xúc buồn bã để mọi người trong nhà không bị buồn theo.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5714, 960, 'reflection', '{\"question\": \"Khi gặp chuyện đau lòng, bạn có dám khóc và chia sẻ sự yếu đuối của mình với người khác không?\"}', 5, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5715, 960, 'takeaway', '{\"items\": [\"Dám thừa nhận mình đang bị tổn thương là biểu hiện của một lòng dũng cảm phi thường.\"]}', 6, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5716, 961, 'hook', '{\"title\": \"Bạn làm thế nào để vượt qua nỗi đau khi một mối quan hệ thân thiết đột ngột tan vỡ?\"}', 1, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5717, 961, 'explanation', '{\"bullets\": [\"Mất đi một người bạn thân (bị tẩy chay, chuyển trường) hay chia tay tình yêu đầu đời là những cú sốc cảm xúc cực kỳ đau đớn ở tuổi teen.\", \"Quá trình vượt qua mất mát thường trải qua các giai đoạn: chối bỏ, tức giận, dằn vặt, buồn bã và cuối cùng là chấp nhận.\", \"Đừng vội vã bắt mình phải quên ngay, hãy cho phép cảm xúc của bạn được trôi qua các giai đoạn này một cách tự nhiên.\"]}', 2, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5718, 961, 'scenario', '{\"title\": \"Tình huống chia tay bạn\", \"body\": \"Vân và người bạn chơi thân từ tiểu học bỗng dưng nghỉ chơi vì một hiểu lầm nhỏ. Người bạn kia nhanh chóng kết thân với nhóm khác và lờ Vân đi. Vân thấy vô cùng trống trải, hụt hẫng và tối nào cũng nằm khóc vì nhớ những kỷ niệm cũ.\"}', 3, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5719, 961, 'interaction', '{\"question\": \"Vân nên đối diện với cảm xúc của mình thế nào trong giai đoạn này?\", \"choices\": [{\"text\": \"Chấp nhận nỗi buồn như một phản ứng tự nhiên sau mất mát, viết nhật ký để giải tỏa và tự nhủ thời gian sẽ giúp mình nguôi ngoai.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Ép mình phải ghét bạn kia, tìm cớ nói xấu bạn với người khác để tỏ ra mình không hề quan tâm hay đau buồn.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5720, 961, 'reflection', '{\"question\": \"Bạn đã từng trải qua cuộc chia ly bạn bè nào chưa? Điều gì đã giúp bạn vượt qua giai đoạn khó khăn đó?\"}', 5, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5721, 961, 'takeaway', '{\"items\": [\"Một cánh cửa khép lại là để bạn có cơ hội mở ra những kết nối mới phù hợp hơn.\"]}', 6, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5722, 962, 'hook', '{\"title\": \"Làm sao để rèn luyện sự kiên cường của não bộ mỗi ngày như tập thể dục?\"}', 1, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5723, 962, 'explanation', '{\"bullets\": [\"Khả năng phục hồi không phải là một món quà bẩm sinh, nó giống như một nhóm cơ cần được rèn luyện hàng ngày.\", \"Bạn có thể xây dựng cơ bắp tinh thần bằng cách:\", \"1. **Tập trung vào thứ kiểm soát được:** Phân biệt rõ việc gì mình sửa được (nỗ lực học bài) và việc gì không kiểm soát được (đề thi khó, ý kiến của người khác).\", \"2. **Tập trung vào tiến bộ nhỏ:** Ghi nhận sự nỗ lực của bản thân mỗi ngày thay vì chỉ nhìn vào đích đến cuối cùng.\", \"3. **Tự xoa dịu (Self-soothing):** Thực hành những thói quen lành mạnh đem lại sự bình yên: tắm nước ấm, uống trà, nghe nhạc nhẹ.\"]}', 2, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5724, 962, 'scenario', '{\"title\": \"Tình huống kiểm soát\", \"body\": \"Kỳ thi thử của Huy kết quả không như ý. Huy thấy lo lắng vô cùng. Để lấy lại thăng bằng, Huy ngồi xuống viết ra hai cột: cột \'Thứ mình kiểm soát được\' (Thời gian học, cách ôn bài) và cột \'Thứ mình không kiểm soát được\' (Đề thi chính thức, điểm của các bạn khác).\"}', 3, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5725, 962, 'interaction', '{\"question\": \"Việc phân loại của Huy giúp ích gì cho tâm trí cậu ấy lúc này?\", \"choices\": [{\"text\": \"Giúp Huy giảm bớt lo âu vô ích về những thứ nằm ngoài tầm tay, tập trung tối đa năng lượng vào những việc có thể cải thiện.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Khiến Huy trở nên thụ động và phó mặc kết quả thi cử cho số phận định đoạt.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5726, 962, 'reflection', '{\"question\": \"Một việc nào đang làm bạn lo lắng tuần này? Nó thuộc vùng kiểm soát được hay không kiểm soát được của bạn?\"}', 5, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5727, 962, 'takeaway', '{\"items\": [\"Đừng lãng phí năng lượng để cố gắng thay đổi hướng gió, hãy tập trung điều chỉnh cánh buồm của bạn.\"]}', 6, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5728, 963, 'hook', '{\"title\": \"Làm sao để biến những trải nghiệm tồi tệ thành chất dinh dưỡng cho sự trưởng thành?\"}', 1, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5729, 963, 'explanation', '{\"bullets\": [\"Mỗi khó khăn, sai lầm hay vấp ngã bạn trải qua đều chứa đựng một bài học kinh nghiệm quý giá.\", \"Thay vì chôn vùi sai lầm dưới sự xấu hổ và tự trách, hãy dũng cảm ngồi lại, phân tích xem chuyện gì đã xảy ra và mình có thể làm gì khác đi trong lần tới.\", \"Đây là cách bạn biến những vết thương lòng thành những huân chương danh dự của sự trưởng thành.\"]}', 2, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5730, 963, 'scenario', '{\"title\": \"Tình huống rút kinh nghiệm\", \"body\": \"Nam lỡ lời nói xấu một người bạn trong nhóm để lấy lòng các bạn khác, dẫn đến việc bị bạn phát hiện và cãi vã lớn. Nam thấy rất xấu hổ và hối hận. Thay vì trốn tránh, Nam nhắn tin xin lỗi bạn chân thành và tự hứa từ nay sẽ không bao giờ bàn tán sau lưng người khác nữa.\"}', 3, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5731, 963, 'interaction', '{\"question\": \"Hành động của Nam thể hiện điều gì?\", \"choices\": [{\"text\": \"Tinh thần dám đối diện sai lầm, rút ra bài học kinh nghiệm và chủ động sửa sai để trưởng thành hơn.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Sự hèn nhát vì phải hạ mình xin lỗi trước mặt người khác để giữ gìn mối quan hệ.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5732, 963, 'reflection', '{\"question\": \"Một sai lầm nào trong quá khứ đã giúp bạn trở nên chín chắn và cẩn thận hơn ở hiện tại?\"}', 5, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5733, 963, 'takeaway', '{\"items\": [\"Vấp ngã không phải là ngõ cụt, đó là cơ hội để bạn học cách bước đi vững vàng hơn.\"]}', 6, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5734, 964, 'hook', '{\"title\": \"Sức mạnh nội tâm thực sự nằm ở đâu khi bạn thấy muốn bỏ cuộc?\"}', 1, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5735, 964, 'explanation', '{\"bullets\": [\"Sức mạnh nội tâm không phải là một cú bùng nổ năng lượng chốc lát, nó là sự kiên trì bền bỉ (Grit) - tiếp tục bước từng bước nhỏ tiến về phía trước ngay cả khi chán nản hay mệt mỏi nhất.\", \"Khi gặp khó khăn lớn, hãy chia nhỏ mục tiêu của bạn ra thành từng ngày, từng giờ.\", \"Bạn chỉ cần tốt hơn chính mình ngày hôm qua 1% thôi, sự tích lũy nhỏ sẽ tạo nên sự thay đổi khổng lồ.\"]}', 2, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5736, 964, 'scenario', '{\"title\": \"Tình huống kiên trì\", \"body\": \"Vy học môn Tiếng Anh rất đuối và liên tục bị điểm kém. Vy thấy nản lòng và muốn buông xuôi. Nhưng rồi Vy quyết định mỗi ngày chỉ dành đúng 15 phút học 5 từ vựng mới và nghe một bài hát tiếng Anh. Sau 3 tháng, Vy thấy mình đã có thể tự tin hiểu được các đoạn hội thoại ngắn trên lớp.\"}', 3, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5737, 964, 'interaction', '{\"question\": \"Vy đã ứng dụng bí quyết gì để phát triển sức mạnh nội tâm?\", \"choices\": [{\"text\": \"Chia nhỏ mục tiêu và duy trì sự bền bỉ hàng ngày bằng những hành động nhỏ, kiên nhẫn với tiến trình của bản thân.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Nhờ bạn học giỏi làm bài hộ để cải thiện điểm số nhanh chóng trước khi tự mình cố gắng.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5738, 964, 'reflection', '{\"question\": \"Một thói quen nhỏ lành mạnh nào bạn sẵn lòng duy trì đều đặn 10 phút mỗi ngày từ hôm nay?\"}', 5, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5739, 964, 'takeaway', '{\"items\": [\"Không quan trọng bạn đi chậm thế nào, miễn là bạn không dừng lại.\"]}', 6, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5740, 965, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Sức mạnh nội tâm & Khả năng phục hồi\'! Cùng rèn luyện cơ bắp tinh thần kiên cường nhé.\"}', 1, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5741, 965, 'scenario-choice', '{\"title\": \"Vết nứt học tập\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn trượt bài thi học sinh giỏi cấp trường mà bạn đã dành rất nhiều thời gian ôn luyện. Bạn thấy buồn bã rã rời và muốn vứt bỏ toàn bộ sách vở môn học đó.\", \"choices\": [{\"text\": \"Tự trách mình dốt nát không có năng khiếu và tuyên bố bỏ cuộc vĩnh viễn.\", \"nextNode\": \"fail_submit\"}, {\"text\": \"Chấp nhận nỗi buồn trượt tuyển, tự nhủ đây chỉ là thử thách tạm thời để mình nâng cấp cách học bài.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Bố mẹ tỏ vẻ thất vọng và liên tục so sánh bạn với con nhà người ta học giỏi hơn. Bạn thấy lòng tự trọng tổn thương sâu sắc.\", \"choices\": [{\"text\": \"Gồng mình cãi cọ gay gắt với bố mẹ để chứng minh mình không kém cỏi.\", \"nextNode\": \"fail_guilt\"}, {\"text\": \"Tập trung vào vùng mình kiểm soát được, tự xoa dịu bản thân và tiếp tục kiên trì học tập theo nhịp độ riêng.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã biến vấp ngã thành bài học, giữ vững tư duy phát triển và kiên cường bước tiếp theo đuổi mục tiêu cá nhân.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_submit\": {\"text\": \"❌ Thất bại! Chấp nhận tư duy cố định và từ bỏ đam mê sau một lần vấp ngã sẽ ngăn bạn khai phá tiềm năng vô hạn của bản thân.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_guilt\": {\"text\": \"❌ Thất bại! Phản ứng tức giận gồng mình cãi vã chỉ làm mối quan hệ gia đình thêm căng thẳng và vắt kiệt năng lượng tinh thần của bạn.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5742, 965, 'sorting', '{\"instruction\": \"Hãy phân loại các thái độ đối diện với cuộc sống:\", \"leftBox\": {\"title\": \"Tư duy phát triển (Growth Mindset)\"}, \"rightBox\": {\"title\": \"Tư duy cố định (Fixed Mindset)\"}, \"items\": [{\"text\": \"Sai lầm chỉ là cơ hội để học hỏi và sửa chữa\", \"correctBox\": \"left\"}, {\"text\": \"Mình dốt sẵn rồi, có cố gắng cũng không làm được đâu\", \"correctBox\": \"right\"}, {\"text\": \"Kỹ năng vẽ có thể cải thiện nhờ chăm chỉ rèn luyện\", \"correctBox\": \"left\"}, {\"text\": \"Không qua được vòng tuyển chọn tức là mình không có khiếu\", \"correctBox\": \"right\"}]}', 3, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5743, 965, 'matching', '{\"instruction\": \"Ghép cặp các khái niệm về khả năng phục hồi sau:\", \"pairs\": [{\"left\": \"Khả năng phục hồi\", \"right\": \"Năng lực đứng dậy mạnh mẽ sau vấp ngã\"}, {\"left\": \"Mềm mại tự thân\", \"right\": \"Dám thừa nhận sự tổn thương và chia sẻ cảm xúc\"}, {\"left\": \"Tư duy phát triển\", \"right\": \"Tin tưởng năng lực có thể phát triển qua nỗ lực\"}, {\"left\": \"Tự xoa dịu\", \"right\": \"Thói quen tắm nước ấm, nghe nhạc thư giãn tinh thần\"}]}', 4, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5744, 965, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về sự kiên cường:\", \"sentence\": \"Sự kiên cường giống như nhóm cơ cần được [blank1] mỗi ngày. Hãy tập trung vào những việc bạn [blank2] được thay vì lo lắng vô ích về hướng gió để tự tin [blank3] tiếp.\", \"blanks\": {\"blank1\": {\"correct\": \"rèn luyện\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"kiểm soát\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"bước\", \"placeholder\": \"...\"}}, \"words\": [\"rèn luyện\", \"kiểm soát\", \"bước\", \"sinh ra\", \"phó mặc\", \"dừng\"]}', 5, '2026-07-07 01:57:50', '2026-07-07 01:57:50'),
(5745, 965, 'interaction', '{\"question\": \"Đâu là nhận định chính xác về mối quan hệ giữa khóc lóc và sức mạnh nội tâm?\", \"choices\": [{\"text\": \"Cho phép bản thân khóc và chia sẻ sự tổn thương là biểu hiện của lòng dũng cảm và sự mềm mại mạnh mẽ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Khóc lóc chứng tỏ bạn là kẻ yếu đuối, cần phải gồng mình cứng rắn để vượt qua nghịch cảnh.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-07 01:57:50', '2026-07-07 01:57:50');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(5746, 966, 'hook', '{\"title\": \"Làm sao để biết một tình bạn đang nâng đỡ bạn, hay đang kéo ghì bạn xuống?\"}', 1, '2026-07-07 01:57:51', '2026-07-07 01:57:51'),
(5747, 966, 'explanation', '{\"bullets\": [\"Một mối quan hệ lành mạnh (tình bạn hay tình cảm tuổi học trò) cần được xây dựng trên 4 cột trụ cốt lõi:\", \"1. **Tôn trọng:** Tôn trọng ranh giới, sở thích và sự khác biệt của nhau.\", \"2. **Tin cậy:** Tin tưởng và trung thực, không soi mói hay ghen tuông vô cớ.\", \"3. **Ủng hộ:** Cùng nhau tiến bộ, vui mừng trước thành công của nhau.\", \"4. **An toàn:** Bạn cảm thấy thoải mái là chính mình khi ở bên cạnh họ.\"]}', 2, '2026-07-07 01:57:51', '2026-07-07 01:57:51'),
(5748, 966, 'scenario', '{\"title\": \"Tình huống tình bạn xịn\", \"body\": \"Mỗi khi Phương có điểm thi cao, Linh đều chạy lại ôm chúc mừng và rủ Phương đi trà sữa ăn mừng. Ngược lại, khi Linh buồn chuyện gia đình, Phương sẵn sàng ngồi yên lặng lắng nghe Linh khóc suốt cả tiếng đồng hồ mà không phán xét.\"}', 3, '2026-07-07 01:57:51', '2026-07-07 01:57:51'),
(5749, 966, 'interaction', '{\"question\": \"Mối quan hệ giữa Phương và Linh có đặc điểm gì nổi bật của sự lành mạnh?\", \"choices\": [{\"text\": \"Sự ủng hộ chân thành và an toàn cảm xúc, đôi bên đều cảm thấy được trân trọng và lắng nghe.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Sự phụ thuộc lẫn nhau quá mức, khiến đôi bên không có không gian riêng tư để phát triển cá nhân.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:51', '2026-07-07 01:57:51'),
(5750, 966, 'reflection', '{\"question\": \"Người bạn nào làm bạn thấy an toàn và thoải mái là chính mình nhất khi ở cạnh?\"}', 5, '2026-07-07 01:57:51', '2026-07-07 01:57:51'),
(5751, 966, 'takeaway', '{\"items\": [\"Tình bạn lành mạnh là khi bạn được là chính mình mà không sợ bị phán xét.\"]}', 6, '2026-07-07 01:57:51', '2026-07-07 01:57:51'),
(5752, 967, 'hook', '{\"title\": \"Bạn có đang phớt lờ những dấu hiệu cảnh báo nguy hiểm trong mối quan hệ vì tiếc nuối tình bạn?\"}', 1, '2026-07-07 01:57:52', '2026-07-07 01:57:52'),
(5753, 967, 'explanation', '{\"bullets\": [\"Cờ đỏ (Red Flags) là những dấu hiệu cảnh báo hành vi toxic, kiểm soát hoặc lạm dụng trong mối quan hệ.\", \"Hãy cảnh giác với các cờ đỏ phổ biến sau:\", \"1. **Kiểm soát:** Muốn biết mật khẩu điện thoại, cấm chơi với bạn bè khác.\", \"2. **Hạ thấp:** Thường xuyên chê bai, lấy khuyết điểm của bạn ra làm trò đùa trước đám đông.\", \"3. **Gaslight:** Làm sai nhưng luôn đổ lỗi tại bạn quá nhạy cảm hay đa nghi.\"]}', 2, '2026-07-07 01:57:52', '2026-07-07 01:57:52'),
(5754, 967, 'scenario', '{\"title\": \"Tình huống cờ đỏ\", \"body\": \"Bạn trai của Vy yêu cầu Vy phải chụp ảnh báo cáo vị trí mỗi khi đi chơi và cấm Vy nói chuyện với bất kỳ bạn nam nào khác trong lớp. Khi Vy tỏ ý khó chịu, bạn trai bảo: \\\"Vì yêu và sợ mất Vy nên tớ mới làm thế, Vy không hiểu cho tớ gì cả\\\".\"}', 3, '2026-07-07 01:57:52', '2026-07-07 01:57:52'),
(5755, 967, 'interaction', '{\"question\": \"Hành vi của bạn trai Vy phản ánh điều gì?\", \"choices\": [{\"text\": \"Cờ đỏ kiểm soát nghiêm trọng dưới danh nghĩa tình yêu, vi phạm quyền tự do và ranh giới cá nhân của Vy.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Sự quan tâm ngọt ngào và lãng mạn giúp giữ gìn tình yêu bền chặt tuổi học trò.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:52', '2026-07-07 01:57:52'),
(5756, 967, 'reflection', '{\"question\": \"Bạn đã bao giờ phát hiện một cờ đỏ nào ở bạn bè hoặc người yêu chưa? Bạn đã xử lý thế nào?\"}', 5, '2026-07-07 01:57:52', '2026-07-07 01:57:52'),
(5757, 967, 'takeaway', '{\"items\": [\"Yêu thương thực sự không bao giờ đi kèm với sự kiểm soát hay làm bạn thấy ngột ngạt.\"]}', 6, '2026-07-07 01:57:52', '2026-07-07 01:57:52'),
(5758, 968, 'hook', '{\"title\": \"Liệu một mối quan hệ không bao giờ cãi vã mới là mối quan hệ hoàn hảo?\"}', 1, '2026-07-07 01:57:52', '2026-07-07 01:57:52'),
(5759, 968, 'explanation', '{\"bullets\": [\"Xung đột, mâu thuẫn là chuyện hoàn toàn bình thường và không thể tránh khỏi trong bất kỳ mối quan hệ nào.\", \"Sự khác biệt về tính cách, sở thích hay quan điểm đương nhiên sẽ dẫn đến va chạm.\", \"Điều quyết định mối quan hệ bền vững hay rạn nứt không phải là việc có xung đột hay không, mà là **cách bạn giải quyết xung đột** đó như thế nào.\"]}', 2, '2026-07-07 01:57:52', '2026-07-07 01:57:52'),
(5760, 968, 'scenario', '{\"title\": \"Tình huống bất đồng\", \"body\": \"Nam và Đức thiết kế chung một tấm poster cho lớp. Nam muốn dùng tông màu xanh lá, Đức lại thích màu cam. Hai bên tranh cãi gay gắt, Nam giận dữ bỏ về và nghĩ rằng tình bạn giữa hai người sắp tan vỡ hoàn toàn.\"}', 3, '2026-07-07 01:57:52', '2026-07-07 01:57:52'),
(5761, 968, 'interaction', '{\"question\": \"Nam và Đức nên nhìn nhận xung đột này thế nào để bảo vệ tình bạn?\", \"choices\": [{\"text\": \"Xem đây là cơ hội học cách lắng nghe quan điểm của bạn, cùng thảo luận tìm phương án dung hòa\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Nam quyết định nhượng bộ hoàn toàn để giữ hòa khí, chấp nhận ấm ức trong lòng để không cãi nhau nữa.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:52', '2026-07-07 01:57:52'),
(5762, 968, 'reflection', '{\"question\": \"Cách bạn thường giải quyết mâu thuẫn với bạn thân là gì: im lặng trốn tránh, tranh cãi nảy lửa hay ngồi lại đối thoại?\"}', 5, '2026-07-07 01:57:52', '2026-07-07 01:57:52'),
(5763, 968, 'takeaway', '{\"items\": [\"Xung đột là một phần của sự trưởng thành chung, miễn là bạn tấn công vào vấn đề, không tấn công vào con người.\"]}', 6, '2026-07-07 01:57:52', '2026-07-07 01:57:52'),
(5764, 969, 'hook', '{\"title\": \"Bạn làm gì để sống sót qua chiến tranh lạnh hoặc sự cô lập ngầm từ nhóm bạn?\"}', 1, '2026-07-07 01:57:53', '2026-07-07 01:57:53'),
(5765, 969, 'explanation', '{\"bullets\": [\"Việc bị nhóm bạn đột ngột giận dỗi, lờ đi hoặc lập nhóm chat riêng để nói xấu (Silent Treatment / Exiling) là một hình thức bắt nạt tâm lý rất đau đớn.\", \"Kẻ cô lập thường muốn dùng nỗi sợ bị tẩy chay để buộc bạn phải phục tùng hoặc nhận lỗi dù bạn không làm gì sai.\", \"Sự tỉnh táo lúc này là không để hành vi toxic của họ làm bạn nghi ngờ giá trị của bản thân.\"]}', 2, '2026-07-07 01:57:53', '2026-07-07 01:57:53'),
(5766, 969, 'scenario', '{\"title\": \"Tình huống tẩy chay\", \"body\": \"Chỉ vì Vân không đồng ý cho bạn chép bài thi học kỳ, nhóm bạn chơi chung đột ngột lờ Vân đi, cự tuyệt nói chuyện và không rủ Vân đi ăn trưa cùng như mọi khi. Vân thấy vô cùng cô độc, ấm ức và muốn khóc giữa lớp.\"}', 3, '2026-07-07 01:57:53', '2026-07-07 01:57:53'),
(5767, 969, 'interaction', '{\"question\": \"Vân nên đối diện với sự cô lập của nhóm bạn thế nào?\", \"choices\": [{\"text\": \"Tự nói: \'Mình đã làm đúng quy chế thi. Hành vi cô lập của các bạn là không lành mạnh\' và chủ động kết bạn với các bạn học khác trong lớp.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Đến khóc lóc cầu xin sự tha thứ của nhóm bạn và hứa lần sau sẽ cho chép bài để được chơi chung lại.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:53', '2026-07-07 01:57:53'),
(5768, 969, 'reflection', '{\"question\": \"Bạn đã bao giờ chứng kiến hay trải qua sự cô lập học đường chưa? Bạn cảm thấy thế nào về hành vi đó?\"}', 5, '2026-07-07 01:57:53', '2026-07-07 01:57:53'),
(5769, 969, 'takeaway', '{\"items\": [\"Họ cô lập bạn không phải vì bạn kém cỏi, mà vì họ không thể kiểm soát được bạn.\"]}', 6, '2026-07-07 01:57:53', '2026-07-07 01:57:53'),
(5770, 970, 'hook', '{\"title\": \"Bạn có muốn học công thức gửi thông điệp Tớ giúp giải quyết mọi hiểu lầm hiệu quả?\"}', 1, '2026-07-07 01:57:53', '2026-07-07 01:57:53'),
(5771, 970, 'explanation', '{\"bullets\": [\"Khi xảy ra mâu thuẫn, chúng ta thường có xu hướng đổ lỗi bằng thông điệp \\\"Cậu\\\" (You-messages) làm đối phương phòng thủ (ví dụ: \'Cậu luôn trễ hẹn, cậu không tôn trọng tớ\').\", \"Hãy thay thế bằng **Thông điệp Tớ (I-messages)**: tập trung vào cảm xúc và nhu cầu của bạn mà không phán xét đối phương:\", \"1. **Mô tả sự việc khách quan:** Khi cậu đến muộn 30 phút...\", \"2. **Nói rõ cảm xúc của bạn:** Tớ thấy rất buồn và lo lắng...\", \"3. **Đề xuất mong muốn:** Lần sau nếu muộn cậu nhắn tin trước cho tớ nhé.\"]}', 2, '2026-07-07 01:57:53', '2026-07-07 01:57:53'),
(5772, 970, 'scenario', '{\"title\": \"Tình huống lỡ hẹn\", \"body\": \"Hùng lỡ hẹn đi chơi bóng rổ với Đức vì ngủ quên, khiến Đức phải đứng chờ dưới nắng cả tiếng đồng hồ. Đức rất giận dữ và muốn nhắn tin mắng Hùng là kẻ tồi tệ, vô trách nhiệm.\"}', 3, '2026-07-07 01:57:53', '2026-07-07 01:57:53'),
(5773, 970, 'interaction', '{\"question\": \"Áp dụng công thức Thông điệp Tớ, Đức nên nhắn tin cho Hùng thế nào để giải quyết mâu thuẫn văn minh nhất?\", \"choices\": [{\"text\": \"\'Tớ thấy rất mệt và buồn khi phải chờ cả tiếng dưới nắng mà không thấy cậu. Lần sau nếu bận hay ngủ quên cậu báo tớ sớm nhé!\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"\'Cậu là đồ tồi tệ, vô trách nhiệm, bắt tớ chờ cả tiếng dưới nắng thế này. Từ sau nghỉ chơi đi nhé!\'.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 01:57:53', '2026-07-07 01:57:53'),
(5774, 970, 'reflection', '{\"question\": \"Lần gần nhất bạn tranh cãi với ai đó, bạn có lỡ dùng những câu nói mang tính đổ lỗi đối phương không?\"}', 5, '2026-07-07 01:57:54', '2026-07-07 01:57:54'),
(5775, 970, 'takeaway', '{\"items\": [\"Giao tiếp văn minh là nói ra cảm xúc của mình để đối phương thấu hiểu, không phải dùng lời nói làm vũ khí tổn thương họ.\"]}', 6, '2026-07-07 01:57:54', '2026-07-07 01:57:54'),
(5776, 971, 'hook', '{\"title\": \"Khi mọi thứ vượt quá sức chịu đựng, ai sẽ là tấm lưới an toàn đỡ lấy bạn?\"}', 1, '2026-07-07 01:57:54', '2026-07-07 01:57:54'),
(5777, 971, 'explanation', '{\"bullets\": [\"Mạng lưới hỗ trợ (Support Network) là danh sách những người bạn tin cậy, sẵn sàng lắng nghe, thấu hiểu và giúp đỡ bạn khi bạn gặp khó khăn.\", \"Mạng lưới này không cần số lượng nhiều, chỉ cần chất lượng. Đó có thể là:\", \"Bạn thân thiết tôn trọng bạn.\", \"Người lớn đáng tin cậy (bố mẹ, cô giáo tâm lý, anh chị em họ).\", \"Các tổng đài hỗ trợ quốc gia hoặc chuyên gia tâm lý.\"]}', 2, '2026-07-07 01:57:54', '2026-07-07 01:57:54'),
(5778, 971, 'scenario', '{\"title\": \"Tình huống tìm người giúp\", \"body\": \"Vy đang gặp khủng hoảng tâm lý nặng nề vì bị một nhóm bạn trên mạng bắt nạt mạng (cyberbullying). Vy thấy sợ hãi, bế tắc và muốn tự làm đau bản thân. Vy quyết định ngồi xuống viết ra danh sách 3 người mình tin cậy nhất để gọi điện chia sẻ.\"}', 3, '2026-07-07 01:57:54', '2026-07-07 01:57:54'),
(5779, 971, 'interaction', '{\"question\": \"Hành động thiết lập mạng lưới hỗ trợ của Vy có tác dụng gì?\", \"choices\": [{\"text\": \"Giúp Vy nhanh chóng nhận được sự nâng đỡ cảm xúc và can thiệp bảo vệ kịp thời từ những người có khả năng giúp đỡ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Chỉ làm phiền và gây thêm lo lắng không cần thiết cho những người xung quanh, Vy nên tự giải quyết vấn đề của mình.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 01:57:54', '2026-07-07 01:57:54'),
(5780, 971, 'reflection', '{\"question\": \"Hãy nhẩm nhanh trong đầu: Đâu là 3 cái tên bạn sẽ lập tức gọi điện khi gặp tình huống khẩn cấp nhất?\"}', 5, '2026-07-07 01:57:54', '2026-07-07 01:57:54'),
(5781, 971, 'takeaway', '{\"items\": [\"Tìm kiếm sự giúp đỡ là biểu hiện của việc bạn đang chủ động chọn cách đứng dậy mạnh mẽ.\"]}', 6, '2026-07-07 01:57:54', '2026-07-07 01:57:54'),
(5782, 972, 'hook', '{\"title\": \"Làm sao để cùng những người bạn của mình tạo nên một môi trường an toàn và tích cực?\"}', 1, '2026-07-07 01:57:54', '2026-07-07 01:57:54'),
(5783, 972, 'explanation', '{\"bullets\": [\"Một nhóm bạn tốt giống như một khu vườn xanh mát, nơi mỗi người đều được tự do lớn lên và nở hoa theo cách của mình.\", \"Để cùng nhau phát triển lành mạnh, hãy:\", \"1. **Khuyến khích:** Cổ vũ đam mê và nỗ lực của bạn bè.\", \"2. **Lên tiếng:** Nhắc nhở văn minh nếu thấy bạn mình có những hành vi cờ đỏ nguy hiểm.\", \"3. **Bao dung:** Chấp nhận sự khác biệt và tha thứ cho những lỗi lầm nhỏ khi bạn đã sửa sai.\"]}', 2, '2026-07-07 01:57:54', '2026-07-07 01:57:54'),
(5784, 972, 'scenario', '{\"title\": \"Tình huống đồng hành\", \"body\": \"Nhóm bạn của Nam rủ nhau đăng ký lớp học đàn guitar vào dịp hè. Trong nhóm có Đức học rất chậm và hay đánh sai nhạc. Thay vì trêu chọc, Nam và các bạn đã kiên nhẫn tập cùng Đức, cổ vũ Đức mỗi khi cậu đánh đúng một đoạn nhạc ngắn.\"}', 3, '2026-07-07 01:57:54', '2026-07-07 01:57:54'),
(5785, 972, 'interaction', '{\"question\": \"Thái độ của Nam và nhóm bạn mang lại giá trị gì cho Đức?\", \"choices\": [{\"text\": \"Tạo động lực tinh thần to lớn giúp Đức tự tin luyện tập và cảm thấy ấm áp trong tình bạn lành mạnh.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Làm Đức ỷ lại vào các bạn và không có ý thức tự lực cánh sinh để nâng cao kỹ năng của mình.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 01:57:54', '2026-07-07 01:57:54'),
(5786, 972, 'reflection', '{\"question\": \"Bạn đã bao giờ cảm ơn người bạn thân của mình vì sự hiện diện và ủng hộ của họ chưa? Hôm nay hãy nhắn cho họ một tin nhắn nhé!\"}', 5, '2026-07-07 01:57:54', '2026-07-07 01:57:54'),
(5787, 972, 'takeaway', '{\"items\": [\"Tình bạn đẹp là khi hai người đứng độc lập nhưng luôn sẵn sàng tựa vai nâng đỡ nhau bước tiếp.\"]}', 6, '2026-07-07 01:57:54', '2026-07-07 01:57:54'),
(5788, 973, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Mối quan hệ lành mạnh & Mạng lưới hỗ trợ\'! Cùng gieo mầm những kết nối xanh tươi ấm áp nhé.\"}', 1, '2026-07-07 01:57:55', '2026-07-07 01:57:55'),
(5789, 973, 'scenario-choice', '{\"title\": \"Giải cứu khỏi tình bạn độc hại\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn thân của bạn bắt đầu có những hành vi cờ đỏ kiểm soát: yêu cầu bạn báo cáo tin nhắn điện thoại và giận dỗi tẩy chay bạn mỗi khi bạn đi chơi với nhóm bạn khác.\", \"choices\": [{\"text\": \"Nhường bộ cho bạn xem tin nhắn và ngừng chơi với các bạn khác để giữ tình bạn.\", \"nextNode\": \"fail_submit\"}, {\"text\": \"Áp dụng Thông điệp Tớ để nói chuyện: \'Tớ thấy rất ngột ngạt khi cậu kiểm soát tin nhắn của tớ. Tình bạn cần sự tin tưởng\'.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Bạn thân của bạn tức giận rủ cả nhóm bạn tẩy chay, phớt lờ bạn trong giờ ra chơi. Bạn thấy vô cùng đơn độc và tủi thân giữa lớp học.\", \"choices\": [{\"text\": \"Đến xin lỗi bạn thân và hứa làm theo mọi yêu cầu để được chơi chung lại.\", \"nextNode\": \"fail_guilt\"}, {\"text\": \"Kiên định với ranh giới đúng đắn, tìm cớ bắt chuyện và chủ động kết bạn với những người bạn tốt bụng khác.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã dũng cảm bảo vệ ranh giới cá nhân trước sự thao túng cô lập, chọn cách cư xử văn minh và xây dựng mối quan hệ lành mạnh.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_submit\": {\"text\": \"❌ Thất bại! Thỏa hiệp với sự kiểm soát độc hại chỉ khiến ranh giới cá nhân của bạn bị chà đạp và làm bạn kiệt quệ cảm xúc.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_guilt\": {\"text\": \"❌ Thất bại! Nhượng bộ sự bắt nạt cô lập ngầm sẽ khiến nhóm bắt nạt nắm được thóp của bạn và tiếp tục bắt nạt bạn lâu dài.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-07 01:57:55', '2026-07-07 01:57:55'),
(5790, 973, 'sorting', '{\"instruction\": \"Hãy phân loại các biểu hiện trong mối quan hệ bè bạn:\", \"leftBox\": {\"title\": \"Dấu hiệu an toàn (Green Flag)\"}, \"rightBox\": {\"title\": \"Dấu hiệu độc hại (Red Flag)\"}, \"items\": [{\"text\": \"Tôn trọng ranh giới và ủng hộ sở thích riêng của nhau\", \"correctBox\": \"left\"}, {\"text\": \"Kiểm soát mật khẩu điện thoại và cấm đoán kết bạn\", \"correctBox\": \"right\"}, {\"text\": \"Lắng nghe chân thành, không phán xét khi bạn buồn\", \"correctBox\": \"left\"}, {\"text\": \"Thường xuyên chê bai ngoại hình làm trò đùa trước lớp\", \"correctBox\": \"right\"}]}', 3, '2026-07-07 01:57:55', '2026-07-07 01:57:55'),
(5791, 973, 'matching', '{\"instruction\": \"Ghép cặp các khái niệm về giao tiếp và quan hệ sau:\", \"pairs\": [{\"left\": \"Thông điệp Tớ\", \"right\": \"Cách giao tiếp tập trung vào cảm xúc, nhu cầu cá nhân\"}, {\"left\": \"Mạng lưới hỗ trợ\", \"right\": \"Nhóm người tin cậy ở bên cạnh nâng đỡ khi khó khăn\"}, {\"left\": \"Chiến tranh lạnh\", \"right\": \"Hành vi lờ đi, cô lập ngầm mang tính bắt nạt\"}, {\"left\": \"Xung đột xây dựng\", \"right\": \"Tranh luận tập trung giải quyết vấn đề, giữ hòa khí\"}]}', 4, '2026-07-07 01:57:55', '2026-07-07 01:57:55'),
(5792, 973, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về giao tiếp I-message:\", \"sentence\": \"Khi xảy ra mâu thuẫn, thay vì dùng câu nói mang tính [blank1] đối phương, hãy áp dụng thông điệp [blank2] để bày tỏ cảm xúc và đề xuất mong muốn một cách [blank3] để giữ gìn tình bạn.\", \"blanks\": {\"blank1\": {\"correct\": \"đổ lỗi\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"tớ\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"văn minh\", \"placeholder\": \"...\"}}, \"words\": [\"đổ lỗi\", \"tớ\", \"văn minh\", \"khen ngợi\", \"cậu\", \"thô bạo\"]}', 5, '2026-07-07 01:57:55', '2026-07-07 01:57:55'),
(5793, 973, 'interaction', '{\"question\": \"Khi chứng kiến bạn thân của mình đang bị một bạn học khác liên tục chê bai, xúc phạm ngoại hình, hành động văn minh nhất của bạn là gì?\", \"choices\": [{\"text\": \"Lên tiếng bảo vệ bạn: \'Ý kiến chê bai của bạn rất vô duyên, dừng lại đi!\' rồi nắm tay kéo bạn thân đi chỗ khác.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Đứng cười hùa theo để không khí đỡ bị căng thẳng, gượng gạo.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-07 01:57:55', '2026-07-07 01:57:55'),
(5794, 974, 'hook', '{\"title\": \"Bạn có đang chăm sóc tất cả mọi người xung quanh nhưng bỏ quên chính mình?\"}', 1, '2026-07-07 01:57:55', '2026-07-07 01:57:55'),
(5795, 974, 'explanation', '{\"bullets\": [\"Yêu thương bản thân (Self-Care) là việc chủ động thực hiện các hành động chăm sóc sức khỏe thể chất, tinh thần và cảm xúc của chính bạn.\", \"Nhiều người nghĩ tự chăm sóc mình là ích kỷ hay lười biếng.\", \"Nhưng thực tế, giống như việc bạn phải đeo mặt nạ oxy cho mình trước khi giúp đỡ người khác trên máy bay, bạn phải ổn thì mới có thể giúp đỡ hay yêu thương người xung quanh một cách trọn vẹn.\"]}', 2, '2026-07-07 01:57:55', '2026-07-07 01:57:55'),
(5796, 974, 'scenario', '{\"title\": \"Tình huống kiệt sức\", \"body\": \"Lan luôn nhận lời giúp các bạn làm bài tập, dọn dẹp lớp học, nghe các bạn kể lể than thở cả ngày dù bản thân đang rất đau đầu và mệt mỏi. Lan sợ rằng nếu từ chối, mọi người sẽ ghét mình và bảo mình là đứa ích kỷ.\"}', 3, '2026-07-07 01:57:55', '2026-07-07 01:57:55'),
(5797, 974, 'interaction', '{\"question\": \"Lan nên thay đổi nhận thức như thế nào về việc tự chăm sóc bản thân?\", \"choices\": [{\"text\": \"Thừa nhận rằng tự chăm sóc mình và biết từ chối khi kiệt sức là cần thiết để bảo vệ năng lượng tinh thần của bản thân.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tiếp tục cố gắng chịu đựng để duy trì hình ảnh một người bạn tốt bụng, hoàn hảo trong mắt mọi người.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:55', '2026-07-07 01:57:55'),
(5798, 974, 'reflection', '{\"question\": \"Bạn đã dành bao nhiêu thời gian trong ngày hôm nay chỉ để làm một việc giúp bản thân thấy thư giãn và hạnh phúc?\"}', 5, '2026-07-07 01:57:55', '2026-07-07 01:57:55'),
(5799, 974, 'takeaway', '{\"items\": [\"Chăm sóc bản thân là cách bạn sạc pin cho tâm hồn mình. Đừng để pin cạn kiệt hoàn toàn.\"]}', 6, '2026-07-07 01:57:55', '2026-07-07 01:57:55'),
(5800, 975, 'hook', '{\"title\": \"Cơ thể bạn đang gửi tin nhắn khẩn cấp nào mà bạn đang bỏ qua?\"}', 1, '2026-07-07 01:57:56', '2026-07-07 01:57:56'),
(5801, 975, 'explanation', '{\"bullets\": [\"Sức khỏe tinh thần liên kết chặt chẽ với sức khỏe thể chất. Nhu cầu cơ bản của cơ thể cần được đáp ứng đầy đủ:\", \"1. **Giấc ngủ:** Tuổi teen cần ngủ từ 8-10 tiếng mỗi đêm để não bộ thải độc và củng cố trí nhớ.\", \"2. **Dinh dưỡng:** Ăn đủ bữa, giảm đồ ăn nhanh và nước ngọt nhiều đường.\", \"3. **Nước:** Uống đủ nước giúp não bộ hoạt động trơn tru, giảm đau đầu mệt mỏi.\"]}', 2, '2026-07-07 01:57:56', '2026-07-07 01:57:56'),
(5802, 975, 'scenario', '{\"title\": \"Tình huống thói quen\", \"body\": \"Đức có thói quen thức đêm chơi game và lướt mạng xã hội đến 2-3 giờ sáng, sau đó dậy lúc 6 giờ để đi học. Đức thường xuyên bỏ bữa sáng vì muộn giờ. Dạo gần đây, Đức thấy mình cực kỳ dễ nổi cáu, kết quả học tập sút giảm và luôn thấy đau đầu uể oải.\"}', 3, '2026-07-07 01:57:56', '2026-07-07 01:57:56'),
(5803, 975, 'interaction', '{\"question\": \"Nguyên nhân chính dẫn đến sự cáu gắt và sa sút của Đức là gì?\", \"choices\": [{\"text\": \"Do sự thiếu hụt giấc ngủ trầm trọng và bỏ bê nhu cầu cơ bản của cơ thể, làm suy giảm chức năng não bộ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Do áp lực học tập trên lớp quá nặng nề và thầy cô cho quá nhiều bài tập về nhà.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:56', '2026-07-07 01:57:56'),
(5804, 975, 'reflection', '{\"question\": \"Trung bình mỗi đêm bạn ngủ được bao nhiêu tiếng? Bạn có thấy sự khác biệt của tâm trạng vào hôm sau không?\"}', 5, '2026-07-07 01:57:56', '2026-07-07 01:57:56'),
(5805, 975, 'takeaway', '{\"items\": [\"Một giấc ngủ ngon là liều thuốc chữa lành tự nhiên và mạnh mẽ nhất cho tâm trí bạn.\"]}', 6, '2026-07-07 01:57:56', '2026-07-07 01:57:56'),
(5806, 976, 'hook', '{\"title\": \"Bạn có đang bị cuốn vào vòng xoáy bận rộn và áp lực thành tích đến mức bỏ quên bản thân?\"}', 1, '2026-07-07 01:57:56', '2026-07-07 01:57:56'),
(5807, 976, 'explanation', '{\"bullets\": [\"Áp lực từ kỳ vọng học tập, các lớp học thêm dày đặc và sự so sánh đồng trang lứa khiến ta luôn sống trong trạng thái vội vã.\", \"Chúng ta thường tự nhủ: \\\"Để thi xong rồi nghỉ\\\", hoặc \\\"Bận thế này thời gian đâu mà chăm sóc bản thân\\\".\", \"Nhưng việc trì hoãn tự chăm sóc giống như việc lái một chiếc xe sắp hết xăng, bạn có thể cố đi thêm một đoạn ngắn nhưng sớm muộn gì xe cũng sẽ chết máy giữa đường.\"]}', 2, '2026-07-07 01:57:56', '2026-07-07 01:57:56'),
(5808, 976, 'scenario', '{\"title\": \"Tình huống burnout\", \"body\": \"Để chuẩn bị cho kỳ thi học sinh giỏi, Vy đã hủy hết các buổi đi chơi với bạn bè, ngừng tập đàn guitar yêu thích và nhịn cả bữa tối để có thêm thời gian giải đề Toán. Sau một tháng gồng mình, Vy thấy mình kiệt quệ, sợ nhìn thấy đống sách vở và chỉ muốn nằm khóc cả ngày.\"}', 3, '2026-07-07 01:57:56', '2026-07-07 01:57:56'),
(5809, 976, 'interaction', '{\"question\": \"Vy đang trải qua trạng thái nào của việc bỏ bê bản thân?\", \"choices\": [{\"text\": \"Trạng thái burnout\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Trạng thái quyết tâm cao độ, đây là sự hy sinh cần thiết tạm thời để gặt hái thành quả học tập lớn lao.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:56', '2026-07-07 01:57:56'),
(5810, 976, 'reflection', '{\"question\": \"Hoạt động yêu thích nào của bạn đã bị bạn bỏ quên lâu nhất vì bận rộn học tập?\"}', 5, '2026-07-07 01:57:56', '2026-07-07 01:57:56'),
(5811, 976, 'takeaway', '{\"items\": [\"Chăm sóc bản thân không phải là phần thưởng sau khi hoàn thành công việc, đó là điều kiện cần để bạn làm việc hiệu quả.\"]}', 6, '2026-07-07 01:57:57', '2026-07-07 01:57:57'),
(5812, 977, 'hook', '{\"title\": \"Làm thế nào để ứng phó khẩn cấp khi bạn thấy năng lượng của mình chạm mức âm?\"}', 1, '2026-07-07 01:57:57', '2026-07-07 01:57:57'),
(5813, 977, 'explanation', '{\"bullets\": [\"Sẽ có những ngày bạn thức dậy và thấy hoàn toàn trống rỗng, uể oải, không muốn làm bất cứ việc gì (Burnout day).\", \"Thay vì tự trách mình lười biếng, hãy chấp nhận đây là tín hiệu cơ thể yêu cầu bạn dừng lại nghỉ ngơi thực sự.\", \"Áp dụng ngay kế hoạch ứng phó khẩn cấp: giảm tối đa lịch trình không bắt buộc, cho phép bản thân làm những việc nhẹ nhàng nhất, và đi ngủ sớm.\"]}', 2, '2026-07-07 01:57:57', '2026-07-07 01:57:57'),
(5814, 977, 'scenario', '{\"title\": \"Tình huống kiệt quệ\", \"body\": \"Sáng thứ Hai, sau một tuần học tập căng thẳng và cãi vã gia đình, Huy thấy toàn thân nặng trĩu, đầu óc quay cuồng và không thể tập trung nghe giảng trên lớp. Huy thấy vô cùng lo sợ mình sẽ bị tụt lại phía sau nếu không cố gắng tiếp tục.\"}', 3, '2026-07-07 01:57:57', '2026-07-07 01:57:57'),
(5815, 977, 'interaction', '{\"question\": \"Huy nên đối phó với ngày kiệt quệ này thế nào để phục hồi tốt nhất?\", \"choices\": [{\"text\": \"Cho phép mình giảm bớt áp lực: học nhẹ nhàng trên lớp, tối về xin phép bố mẹ nghỉ học thêm một buổi để đi ngủ sớm phục hồi.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Cố uống nước tăng lực để tỉnh táo học tiếp bài và ép mình phải hoàn thành đầy đủ đống bài tập về nhà ngay trong đêm.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:57', '2026-07-07 01:57:57'),
(5816, 977, 'reflection', '{\"question\": \"Bạn thường làm gì đầu tiên để cứu vãn một ngày cảm thấy hoàn toàn kiệt quệ năng lượng?\"}', 5, '2026-07-07 01:57:57', '2026-07-07 01:57:57'),
(5817, 977, 'takeaway', '{\"items\": [\"Khi bạn thấy mệt mỏi, hãy học cách nghỉ ngơi, đừng học cách bỏ cuộc.\"]}', 6, '2026-07-07 01:57:57', '2026-07-07 01:57:57'),
(5818, 978, 'hook', '{\"title\": \"Nói Không với người khác có phải là đang nói Có với sự bình yên của chính mình?\"}', 1, '2026-07-07 01:57:57', '2026-07-07 01:57:57'),
(5819, 978, 'explanation', '{\"bullets\": [\"Thiết lập ranh giới (Setting Boundaries) là việc bạn xác định rõ những việc gì bạn sẵn sàng làm và việc gì vượt quá khả năng hoặc sự thoải mái của bạn.\", \"Bạn không có nghĩa vụ phải đồng ý giúp đỡ mọi người nếu việc đó làm cạn kiệt năng lượng của bạn.\", \"Đặt ranh giới rõ ràng giúp bạn bảo vệ thời gian, năng lượng và sức khỏe tinh thần của chính mình.\"]}', 2, '2026-07-07 01:57:57', '2026-07-07 01:57:57'),
(5820, 978, 'scenario', '{\"title\": \"Tình huống đặt ranh giới\", \"body\": \"Vào tối Chủ nhật, khi Vân đang chuẩn bị đi ngủ sớm để lấy lại sức cho tuần học mới thì bạn cùng lớp nhắn tin nhờ Vân làm hộ phần slide thuyết trình nhóm của bạn ấy vì bạn bận đi chơi. Vân thấy mệt mỏi nhưng ngại từ chối.\"}', 3, '2026-07-07 01:57:57', '2026-07-07 01:57:57'),
(5821, 978, 'interaction', '{\"question\": \"Vân nên nhắn tin từ chối bạn thế nào để thiết lập ranh giới an toàn cho mình?\", \"choices\": [{\"text\": \"\'Xin lỗi cậu, tối nay tớ cần đi ngủ sớm để mai đi học nên không làm hộ được đâu. Cậu cố gắng tự hoàn thành nhé!\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"\'Ừm... để tớ xem đã... tớ cũng hơi mệt nhưng nếu cậu bận quá thì để tớ cố thức làm giúp cậu vậy\'.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:57', '2026-07-07 01:57:57'),
(5822, 978, 'reflection', '{\"question\": \"Bạn thấy khó khăn nhất khi thiết lập ranh giới với ai: bạn bè, bố mẹ hay thầy cô?\"}', 5, '2026-07-07 01:57:58', '2026-07-07 01:57:58'),
(5823, 978, 'takeaway', '{\"items\": [\"Ranh giới của bạn không phải là những bức tường để ngăn cách, chúng là những cánh cửa để chỉ cho phép những điều lành mạnh bước vào.\"]}', 6, '2026-07-07 01:57:58', '2026-07-07 01:57:58'),
(5824, 979, 'hook', '{\"title\": \"Bạn có muốn học một thói quen nhỏ 3 phút mỗi ngày giúp não bộ tự động tập trung vào điều tích cực?\"}', 1, '2026-07-07 01:57:58', '2026-07-07 01:57:58'),
(5825, 979, 'explanation', '{\"bullets\": [\"Bộ não con người có xu hướng bẩm sinh là chú ý đến những điều tiêu cực (định kiến tiêu cực) để sinh tồn.\", \"Viết nhật ký biết ơn (Gratitude Journal) là việc ghi lại 3 điều nhỏ bé tốt đẹp xảy ra trong ngày mà bạn thấy trân trọng (ví dụ: một bữa ăn ngon, một nụ cười của bạn bè, một ngày nắng đẹp).\", \"Thói quen nhỏ này giúp huấn luyện bộ não nhận diện những điều hạnh phúc nhỏ bé xung quanh, giúp giảm lo âu và cải thiện tâm trạng rõ rệt.\"]}', 2, '2026-07-07 01:57:58', '2026-07-07 01:57:58'),
(5826, 979, 'scenario', '{\"title\": \"Tình huống viết nhật ký\", \"body\": \"Cuối ngày học mệt mỏi, thay vì nằm lướt mạng xã hội nghĩ về những lời chê bai của bạn bè, Mai lấy một cuốn sổ nhỏ ra viết: \'1. Hôm nay thời tiết rất mát mẻ. 2. Bạn Hân đã cho mình mượn bút viết. 3. Mình đã tự nấu được một bát mì ngon\'. Mai thấy lòng nhẹ nhõm hẳn đi trước khi ngủ.\"}', 3, '2026-07-07 01:57:58', '2026-07-07 01:57:58'),
(5827, 979, 'interaction', '{\"question\": \"Thói quen viết nhật ký biết ơn của Mai giúp ích gì cho não bộ của cô bé?\", \"choices\": [{\"text\": \"Giúp hướng sự tập trung của não bộ vào những điều tốt đẹp thực tế, giảm thiểu suy nghĩ tiêu cực quay cuồng và mang lại giấc ngủ ngon.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Chỉ là sự tự lừa dối bản thân để cố trốn tránh thực tại khó khăn, mệt mỏi của việc học tập.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 01:57:58', '2026-07-07 01:57:58'),
(5828, 979, 'reflection', '{\"question\": \"Hãy nhẩm nhanh trong đầu: Đâu là 3 điều tốt đẹp nhỏ bé nhất đã xảy ra với bạn trong ngày hôm nay?\"}', 5, '2026-07-07 01:57:58', '2026-07-07 01:57:58'),
(5829, 979, 'takeaway', '{\"items\": [\"Hạnh phúc không phải là có tất cả mọi thứ, mà là trân trọng những gì bạn đang có.\"]}', 6, '2026-07-07 01:57:58', '2026-07-07 01:57:58'),
(5830, 980, 'hook', '{\"title\": \"Hành trình phát triển cá nhân thực sự bắt đầu từ đâu?\"}', 1, '2026-07-07 01:57:58', '2026-07-07 01:57:58'),
(5831, 980, 'explanation', '{\"bullets\": [\"Phát triển cá nhân (Personal Growth) không phải là cuộc đua để trở thành người xuất sắc nhất lớp, mà là hành trình tự vượt qua chính mình ngày hôm qua.\", \"Sự tiến bộ bền vững đến từ việc bạn yêu thương bản thân đủ để muốn thay đổi những thói quen xấu, rèn luyện những kỹ năng mới trong sự kiên nhẫn.\", \"Hãy tự hào về mỗi bước chân nhỏ bạn đi, vì sự kiên trì hôm nay là nền móng vững chắc cho con người trưởng thành, hạnh phúc và kiên cường của bạn mai sau.\"]}', 2, '2026-07-07 01:57:58', '2026-07-07 01:57:58'),
(5832, 980, 'scenario', '{\"title\": \"Tình huống nhìn lại\", \"body\": \"Tròn một năm kể từ khi tham gia lớp học kỹ năng, Nam nhìn lại mình trong gương. Cậu nhận ra mình đã bớt nóng nảy hơn, biết cách hít thở sâu mỗi khi giận dữ, biết từ chối những lời rủ rê cúp học và có những người bạn thực sự trân trọng mình. Nam mỉm cười tự hào về sự trưởng thành của bản thân.\"}', 3, '2026-07-07 01:57:58', '2026-07-07 01:57:58'),
(5833, 980, 'interaction', '{\"question\": \"Sự nhìn nhận của Nam mang lại bài học gì về phát triển cá nhân?\", \"choices\": [{\"text\": \"Ghi nhận và tự hào về hành trình trưởng thành, hiểu rằng phát triển cá nhân là một quá trình liên tục trong sự tự trắc ẩn.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tự mãn và thỏa mãn sớm với những gì đạt được, khiến bản thân không còn động lực phấn đấu trong tương lai.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 01:57:59', '2026-07-07 01:57:59'),
(5834, 980, 'reflection', '{\"question\": \"Bạn cảm thấy mình đã chín chắn và vững vàng hơn 1 năm trước ở điểm nào nhất?\"}', 5, '2026-07-07 01:57:59', '2026-07-07 01:57:59'),
(5835, 980, 'takeaway', '{\"items\": [\"Trưởng thành là một hành trình, không phải là một đích đến. Hãy tận hưởng từng bước đi của bạn.\"]}', 6, '2026-07-07 01:57:59', '2026-07-07 01:57:59'),
(5836, 981, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Yêu thương bản thân & Phát triển cá nhân\'! Hãy cùng sạc đầy năng lượng cho hành trình phát triển nhé.\"}', 1, '2026-07-07 01:57:59', '2026-07-07 01:57:59'),
(5837, 981, 'scenario-choice', '{\"title\": \"Vượt qua cơn bão kiệt sức\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bài thi học kỳ đang đến gần, bạn vừa học trên lớp, vừa học thêm dày đặc, nhịn cả ăn tối và thức đến 2 giờ sáng học bài. Cơ thể bạn kiệt quệ, luôn thấy đau đầu và buồn nôn.\", \"choices\": [{\"text\": \"Uống nước tăng lực, cố gồng mình thức khuya học tiếp để không bị tụt lại.\", \"nextNode\": \"fail_submit\"}, {\"text\": \"Nhận ra tín hiệu cơ thể kêu cứu, quyết định nghỉ ngơi, ăn uống đầy đủ và đi ngủ sớm.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Một người bạn nhắn tin nhờ bạn làm hộ toàn bộ bài tập lớn nhóm phần của bạn ấy vì bạn ấy bận đi xem ca nhạc vào tối Chủ nhật. Bạn đang rất mệt mỏi và cần nghỉ ngơi.\", \"choices\": [{\"text\": \"Tặc lưỡi đồng ý làm hộ vì sợ bạn giận dỗi và tẩy chay mình.\", \"nextNode\": \"fail_guilt\"}, {\"text\": \"Thiết lập ranh giới: \'Tớ đang mệt và cần đi ngủ sớm để lấy lại sức. Cậu tự hoàn thành phần của mình nhé!\'.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã biết lắng nghe nhu cầu cơ thể đúng lúc, dũng cảm thiết lập ranh giới cá nhân và ưu tiên chăm sóc bản thân lành mạnh.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_submit\": {\"text\": \"❌ Thất bại! Bỏ bê giấc ngủ và dinh dưỡng kéo dài sẽ đẩy cơ thể vào trạng thái suy kiệt (burnout) nghiêm trọng và giảm sút hiệu quả học tập.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_guilt\": {\"text\": \"❌ Thất bại! Chấp nhận gánh vác trách nhiệm hộ người khác khi cơ thể đã cạn kiệt năng lượng chỉ khiến bạn kiệt sức nặng nề hơn.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-07 01:57:59', '2026-07-07 01:57:59'),
(5838, 981, 'sorting', '{\"instruction\": \"Hãy phân loại các hành vi chăm sóc cuộc sống của bạn:\", \"leftBox\": {\"title\": \"Tự chăm sóc bản thân (Self-care xịn)\"}, \"rightBox\": {\"title\": \"Bỏ bê bản thân (Độc hại)\"}, \"items\": [{\"text\": \"Ngủ đủ 8-10 tiếng mỗi đêm để phục hồi não bộ\", \"correctBox\": \"left\"}, {\"text\": \"Thức thâu đêm lướt TikTok và bỏ bữa sáng vì dậy muộn\", \"correctBox\": \"right\"}, {\"text\": \"Viết nhật ký biết ơn ghi chép 3 điều tốt đẹp mỗi ngày\", \"correctBox\": \"left\"}, {\"text\": \"Ép mình nhận lời giúp mọi việc vì sợ người khác ghét\", \"correctBox\": \"right\"}]}', 3, '2026-07-07 01:57:59', '2026-07-07 01:57:59'),
(5839, 981, 'matching', '{\"instruction\": \"Ghép cặp các khái niệm về yêu thương bản thân sau:\", \"pairs\": [{\"left\": \"Yêu thương bản thân\", \"right\": \"Hành động chăm sóc sức khỏe thể chất và tinh thần tự thân\"}, {\"left\": \"Trạng thái Burnout\", \"right\": \"Sự kiệt quệ năng lượng do căng thẳng gồng mình quá mức\"}, {\"left\": \"Thiết lập ranh giới\", \"right\": \"Xác định giới hạn việc sẵn sàng làm và từ chối\"}, {\"left\": \"Nhật ký biết ơn\", \"right\": \"Ghi chép điều nhỏ bé tích cực để rèn luyện tư duy hạnh phúc\"}]}', 4, '2026-07-07 01:57:59', '2026-07-07 01:57:59'),
(5840, 981, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp để hoàn thành đoạn văn về tự chăm sóc bản thân:\", \"sentence\": \"Yêu thương bản thân không phải là sự [blank1]. Hãy học cách lắng nghe [blank2] của cơ thể để kịp thời nghỉ ngơi tái tạo năng lượng, giúp bạn trở thành phiên bản [blank3] hơn mỗi ngày.\", \"blanks\": {\"blank1\": {\"correct\": \"ích kỷ\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"nhu cầu\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"tốt\", \"placeholder\": \"...\"}}, \"words\": [\"ích kỷ\", \"nhu cầu\", \"tốt\", \"tự mãn\", \"mong muốn\", \"xấu\"]}', 5, '2026-07-07 01:57:59', '2026-07-07 01:57:59'),
(5841, 981, 'interaction', '{\"question\": \"Đâu là hành vi thể hiện lòng tự trắc ẩn lành mạnh khi làm hỏng một việc gì đó?\", \"choices\": [{\"text\": \"Tự an ủi, rút ra bài học kinh nghiệm và tự nhủ lần sau mình sẽ làm tốt hơn.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tự dằn vặt, mắng mỏ mình là kẻ bất tài, ngu ngốc trước mặt mọi người.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 6, '2026-07-07 01:57:59', '2026-07-07 01:57:59'),
(5842, 928, 'explanation', '{}', 7, '2026-07-07 02:14:07', '2026-07-07 02:14:07'),
(6151, 1031, 'hook', '{\"title\": \"Bạn có cảm giác cơ thể và tâm trạng của mình dạo này thay đổi nhanh như thời tiết không?\"}', 1, '2026-07-07 03:19:46', '2026-07-07 03:19:46'),
(6152, 1031, 'explanation', '{\"bullets\": [\"Dậy thì là giai đoạn chuyển tiếp kỳ diệu từ một đứa trẻ để trở thành một người trưởng thành về mặt sinh học.\", \"Đây là lúc cơ thể bắt đầu sản sinh ra các hormone sinh dục, kích hoạt một loạt thay đổi lớn từ chiều cao, vóc dáng đến cảm xúc.\", \"Quá trình này diễn ra hoàn toàn tự nhiên và ai cũng phải bước qua để lớn lên.\"]}', 2, '2026-07-07 03:19:46', '2026-07-07 03:19:46'),
(6153, 1031, 'scenario', '{\"title\": \"Tình huống bất ngờ\", \"body\": \"Linh bỗng nhận ra chiếc quần jeans yêu thích mặc tháng trước hôm nay đã ngắn cũn cỡn. Cùng lúc đó, Linh cảm thấy mình dễ xúc động và bực bội hơn chỉ vì những lý do nhỏ nhặt trong nhà. Linh lo lắng không biết mình có bị làm sao không.\"}', 3, '2026-07-07 03:19:46', '2026-07-07 03:19:46'),
(6154, 1031, 'interaction', '{\"question\": \"Linh nên hiểu những thay đổi này như thế nào?\", \"choices\": [{\"text\": \"Chắc chắn là cơ thể mình đang có vấn đề bất thường rồi, cần đi khám bác sĩ gấp.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Đây là dấu hiệu cho thấy nút dậy thì của mình đã được kích hoạt, mọi thứ đang tiến triển tự nhiên.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 03:19:46', '2026-07-07 03:19:46'),
(6155, 1031, 'reflection', '{\"question\": \"Bạn có nhận ra sự thay đổi lớn nhất nào của bản thân trong vài tháng qua không?\"}', 5, '2026-07-07 03:19:46', '2026-07-07 03:19:46'),
(6156, 1031, 'takeaway', '{\"items\": [\"Dậy thì không phải là một căn bệnh, đó là hành trình trưởng thành của cơ thể bạn.\"]}', 6, '2026-07-07 03:19:46', '2026-07-07 03:19:46'),
(6157, 1032, 'hook', '{\"title\": \"Bạn có biết một vùng não nhỏ xíu chính là tổng chỉ huy đứng sau toàn bộ cơn bão dậy thì?\"}', 1, '2026-07-07 03:19:46', '2026-07-07 03:19:46'),
(6158, 1032, 'explanation', '{\"bullets\": [\"Hệ thống nội tiết của bạn, dẫn đầu bởi vùng hạ đồi và tuyến yên trong não, phát tín hiệu đánh thức cơ thể.\", \"Chúng giải phóng các hormone hướng sinh dục, thúc đẩy tinh hoàn ở nam sản xuất testosterone và buồng trứng ở nữ sản xuất estrogen.\", \"Các hormone này chính là những sứ giả hóa học đi khắp cơ thể để tạo nên những thay đổi đặc trưng.\"]}', 2, '2026-07-07 03:19:47', '2026-07-07 03:19:47'),
(6159, 1032, 'scenario', '{\"title\": \"Tình huống cọc cằn\", \"body\": \"Nam bỗng dưng cảm thấy nóng nảy, muốn quát tháo khi mẹ nhắc nhở dọn dẹp phòng, dù bình thường Nam rất nghe lời. Nam tự trách mình dạo này biến thành đứa con tồi tệ.\"}', 3, '2026-07-07 03:19:47', '2026-07-07 03:19:47'),
(6160, 1032, 'interaction', '{\"question\": \"Theo bạn, hành vi dễ cọc cằn đột ngột của Nam do đâu?\", \"choices\": [{\"text\": \"Do tính cách của Nam đã thay đổi tiêu cực và Nam không còn tôn trọng bố mẹ nữa.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Do hormone sinh dục dâng cao kích thích vùng não cảm xúc nhạy cảm hơn bình thường.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 03:19:47', '2026-07-07 03:19:47'),
(6161, 1032, 'reflection', '{\"question\": \"Gần đây bạn có từng cảm thấy cảm xúc của mình bị đẩy lên quá mức chỉ vì một chuyện nhỏ không?\"}', 5, '2026-07-07 03:19:47', '2026-07-07 03:19:47'),
(6162, 1032, 'takeaway', '{\"items\": [\"Hormone đang làm việc của chúng, việc của bạn là học cách làm bạn với chúng.\"]}', 6, '2026-07-07 03:19:47', '2026-07-07 03:19:47'),
(6163, 1033, 'hook', '{\"title\": \"Tại sao đứa bạn cùng bàn đã cao lớn vổng lên trong khi mình vẫn lẹt đẹt như học sinh tiểu học?\"}', 1, '2026-07-07 03:19:47', '2026-07-07 03:19:47'),
(6164, 1033, 'explanation', '{\"bullets\": [\"Không có một lịch trình dậy thì chung áp dụng cho tất cả mọi người.\", \"Dậy thì thường bắt đầu trong khoảng từ 8 đến 14 tuổi đối với nữ, và từ 9 đến 15 tuổi đối với nam.\", \"Tốc độ dậy thì nhanh hay chậm phụ thuộc rất lớn vào gen di truyền, dinh dưỡng và môi trường sống của mỗi người.\"]}', 2, '2026-07-07 03:19:47', '2026-07-07 03:19:47'),
(6165, 1033, 'scenario', '{\"title\": \"Tình huống so sánh\", \"body\": \"Đức thấy lo lắng và tự ti vô cùng khi các bạn nam trong lớp đều đã vỡ giọng và cao trên 1m65, còn mình vẫn mang giọng trẻ con và thấp bé nhất lớp. Đức nghĩ mình sẽ mãi không lớn được.\"}', 3, '2026-07-07 03:19:47', '2026-07-07 03:19:47'),
(6166, 1033, 'interaction', '{\"question\": \"Đức nên tự nhủ điều gì để giảm bớt sự lo âu về tốc độ phát triển của mình?\", \"choices\": [{\"text\": \"Mọi người có chiếc đồng hồ sinh học riêng, sớm hay muộn thì mình cũng sẽ bước vào giai đoạn tăng tốc thôi.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Chắc do mình lười vận động nên mới còi cọc thế, phải uống thật nhiều thực phẩm chức năng tăng chiều cao ngay.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 03:19:47', '2026-07-07 03:19:47'),
(6167, 1033, 'reflection', '{\"question\": \"Bạn có từng cảm thấy áp lực khi so sánh tốc độ lớn của mình với các bạn xung quanh chưa?\"}', 5, '2026-07-07 03:19:47', '2026-07-07 03:19:47'),
(6168, 1033, 'takeaway', '{\"items\": [\"Cơ thể bạn không chạy đua với ai cả, hãy để nó lớn lên theo nhịp điệu tự nhiên của riêng mình.\"]}', 6, '2026-07-07 03:19:47', '2026-07-07 03:19:47'),
(6169, 1034, 'hook', '{\"title\": \"Bạn sẽ đối phó thế nào với cơn giận dữ hay sự nhạy cảm quá đà xuất hiện bất thình lình?\"}', 1, '2026-07-07 03:19:48', '2026-07-07 03:19:48'),
(6170, 1034, 'explanation', '{\"bullets\": [\"Dậy thì không chỉ biến đổi thể xác mà còn tạm thời tái cấu trúc lại bộ não của bạn.\", \"Vùng hạch hạnh nhân (xử lý cảm xúc) phát triển nhanh hơn vỏ não trước trán (kiểm soát hành vi và suy nghĩ logic).\", \"Điều này giải thích tại sao bạn dễ cảm thấy yếu đuối, nhạy cảm hay tức giận vô cớ.\"]}', 2, '2026-07-07 03:19:48', '2026-07-07 03:19:48'),
(6171, 1034, 'scenario', '{\"title\": \"Tình huống bùng nổ\", \"body\": \"Vy đang làm bài tập thì bị em trai vô tình làm xáo trộn đống tài liệu. Vy bỗng thấy ngực nghẹn lại, nổi giận lôi đình và quát mắng em thậm tệ. Sau đó Vy ngồi thụp xuống khóc nức nở vì thấy hối hận.\"}', 3, '2026-07-07 03:19:48', '2026-07-07 03:19:48'),
(6172, 1034, 'interaction', '{\"question\": \"Vy nên làm gì để xoa dịu bản thân sau cơn bùng nổ cảm xúc đó?\", \"choices\": [{\"text\": \"Nhận ra cảm xúc quá đà là do biến động hormone, hít thở sâu, xin lỗi em trai và tự ôm lấy chính mình.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tự trách móc mình là một người chị tồi tệ và nhốt mình trong phòng kín cả ngày để suy nghĩ tiêu cực.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:19:48', '2026-07-07 03:19:48'),
(6173, 1034, 'reflection', '{\"question\": \"Lần gần nhất bạn giận dữ vô cớ là khi nào? Bạn có nhận ra tín hiệu báo trước của cơ thể không?\"}', 5, '2026-07-07 03:19:48', '2026-07-07 03:19:48'),
(6174, 1034, 'takeaway', '{\"items\": [\"Cảm xúc mạnh mẽ giống như một cơn sóng, hãy học cách lướt sóng thay vì để nó nhấn chìm.\"]}', 6, '2026-07-07 03:19:48', '2026-07-07 03:19:48'),
(6175, 1035, 'hook', '{\"title\": \"Bạn có muốn sở hữu chiếc chìa khóa vạn năng giúp vượt qua những bỡ ngỡ tuổi dậy thì?\"}', 1, '2026-07-07 03:19:48', '2026-07-07 03:19:48'),
(6176, 1035, 'explanation', '{\"bullets\": [\"Chìa khóa lớn nhất để đi qua tuổi dậy thì một cách an lành chính là sự trang bị kiến thức và tự tin chia sẻ.\", \"Việc tìm hiểu trước các thay đổi giúp bạn không bị hoang mang khi chúng thực sự xảy ra.\", \"Nói chuyện với một người lớn đáng tin cậy hoặc chuyên gia sức khỏe giúp bạn gỡ rối những thắc mắc thầm kín.\"]}', 2, '2026-07-07 03:19:48', '2026-07-07 03:19:48'),
(6177, 1035, 'scenario', '{\"title\": \"Tình huống ngượng ngùng\", \"body\": \"Khoa bắt đầu mọc những sợi râu tơ đầu tiên và giọng nói trở nên khàn khàn khó nghe. Khoa thấy ngượng ngùng, không dám mở miệng phát biểu bài trên lớp và cũng không dám hỏi bố cách cạo râu.\"}', 3, '2026-07-07 03:19:48', '2026-07-07 03:19:48'),
(6178, 1035, 'interaction', '{\"question\": \"Khoa nên làm gì để vượt qua sự ngại ngùng này?\", \"choices\": [{\"text\": \"Chủ động mở lời với bố: \'Bố ơi, râu con mọc nhiều rồi, bố chỉ con cách dùng dao cạo an toàn nhé!\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tìm cách tự lấy kéo cắt râu lén lút vì sợ bố cười chê mình nứt mắt đã đòi làm người lớn.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 03:19:48', '2026-07-07 03:19:48'),
(6179, 1035, 'reflection', '{\"question\": \"Ai là người lớn đáng tin cậy nhất mà bạn có thể thoải mái chia sẻ những rắc rối tuổi dậy thì?\"}', 5, '2026-07-07 03:19:48', '2026-07-07 03:19:48'),
(6180, 1035, 'takeaway', '{\"items\": [\"Yêu cầu sự giúp đỡ hay hướng dẫn là bước đi đầu tiên của sự tự lập.\"]}', 6, '2026-07-07 03:19:48', '2026-07-07 03:19:48'),
(6181, 1036, 'hook', '{\"title\": \"Bạn có sẵn sàng gửi một lời cảm ơn đến cơ thể đang nỗ lực lớn lên mỗi ngày của mình?\"}', 1, '2026-07-07 03:19:49', '2026-07-07 03:19:49'),
(6182, 1036, 'explanation', '{\"bullets\": [\"Dậy thì là một quá trình tốn nhiều năng lượng của cơ thể.\", \"Cơ thể bạn đang phải làm việc cật lực để phân chia tế bào, kéo dài xương và điều hòa các tuyến hormone mới.\", \"Lắng nghe, thấu cảm và kiên nhẫn với chính mình là thái độ yêu thương bản thân tốt nhất lúc này.\"]}', 2, '2026-07-07 03:19:49', '2026-07-07 03:19:49'),
(6183, 1036, 'scenario', '{\"title\": \"Tình huống mệt mỏi\", \"body\": \"Mai cảm thấy cơ thể luôn trong trạng thái buồn ngủ, uể oải dù ngủ đủ 8 tiếng. Mai tự trách mình lười biếng và ép bản thân thức khuya học bài để bù lại thời gian.\"}', 3, '2026-07-07 03:19:49', '2026-07-07 03:19:49'),
(6184, 1036, 'interaction', '{\"question\": \"Mai nên đối xử với cơ thể uể oải của mình như thế nào?\", \"choices\": [{\"text\": \"Lắng nghe tín hiệu cơ thể, sắp xếp nghỉ ngơi xen kẽ và tự nhủ: \'Cơ thể mình đang bận lớn, mệt mỏi chút là bình thường\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Uống thật nhiều nước tăng lực để ép bộ não tỉnh táo làm việc công suất cao liên tục.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:19:49', '2026-07-07 03:19:49'),
(6185, 1036, 'reflection', '{\"question\": \"Hôm nay, bạn muốn dành sự bao dung nào cho những khuyết điểm hay sự mệt mỏi của bản thân?\"}', 5, '2026-07-07 03:19:49', '2026-07-07 03:19:49'),
(6186, 1036, 'takeaway', '{\"items\": [\"Kiên nhẫn với sự phát triển của chính mình là biểu hiện của lòng trắc ẩn sâu sắc.\"]}', 6, '2026-07-07 03:19:49', '2026-07-07 03:19:49'),
(6187, 1037, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Giải mã tuổi dậy thì\'! Hãy bình tĩnh vượt qua các thử thách về phát triển thể chất và tinh thần để tự tin làm chủ cơ thể.\"}', 1, '2026-07-07 03:19:49', '2026-07-07 03:19:49');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(6188, 1037, 'scenario-choice', '{\"title\": \"Hành trình tự tin và ứng phó áp lực tăng trưởng\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Vy hoang mang vì chiều cao chững lại không tăng thêm trong 3 tháng qua, bạn bè khuyên Vy uống thuốc hormone tăng chiều cao thần tốc mua trên mạng để mau đuổi kịp các bạn.\", \"choices\": [{\"text\": \"Tin bạn, đặt mua ngay lọ thuốc hormone tăng chiều cao trôi nổi về tự uống.\", \"nextNode\": \"fail_drugs\"}, {\"text\": \"Tìm hiểu thông tin khoa học, nhận thức chiều cao phát triển theo đợt tự nhiên và kiên nhẫn theo dõi tiếp.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Vy bắt đầu chú ý ăn uống đầy đủ chất và tập thể thao lành mạnh. Tuy nhiên, một bạn nam cùng lớp chế giễu gọi Vy là \\\"nấm lùn di động\\\" trước cả lớp.\", \"choices\": [{\"text\": \"Xấu hổ cúi đầu chịu đựng, quyết định nhịn ăn sáng để cơ thể gầy thon thả hơn cho đỡ lộ chiều cao thấp.\", \"nextNode\": \"fail_diet\"}, {\"text\": \"Nhìn thẳng bạn đó, bình tĩnh đáp: \\\"Chiều cao của tớ lớn theo nhịp tự nhiên của tớ, mong cậu tôn trọng ngoại hình người khác\\\" rồi tiếp tục đi bộ.\", \"nextNode\": \"step3\"}]}, \"step3\": {\"text\": \"Vy tập luyện kiên trì nhưng mẹ Vy sốt ruột tự ý mua cho Vy các loại thực phẩm chức năng kích thích hormone tăng trưởng do một người quen giới thiệu.\", \"choices\": [{\"text\": \"Nghe lời mẹ uống thuốc kích thích hormone tăng trưởng không nhãn mác y tế.\", \"nextNode\": \"fail_unverified\"}, {\"text\": \"Khuyên mẹ đưa mình đi khám bác sĩ dinh dưỡng hoặc nội tiết để đo tuổi xương và nhận tư vấn y khoa chính thống.\", \"nextNode\": \"step4\"}]}, \"step4\": {\"text\": \"Sau khi đi khám và được bác sĩ khuyên tập thể dục nhẹ nhàng, Vy băn khoăn nên chọn môn thể thao nào thích hợp nhất để phát triển hệ xương.\", \"choices\": [{\"text\": \"Đăng ký các bài tập tạ cực nặng quá sức tại phòng gym để ép xương phát triển nhanh.\", \"nextNode\": \"fail_heavy\"}, {\"text\": \"Tham gia bơi lội, đạp xe hoặc nhảy dây điều độ 30-45 phút mỗi ngày.\", \"nextNode\": \"step5\"}]}, \"step5\": {\"text\": \"Vy thấy một quảng cáo trên mạng cam kết tăng 5cm trong 1 tháng bằng phương pháp bẻ khớp nắn xương vật lý trị liệu dậy thì.\", \"choices\": [{\"text\": \"Bỏ qua quảng cáo lừa đảo, kiên trì tập luyện và sinh hoạt lành mạnh theo khoa học.\", \"nextNode\": \"success_end\"}, {\"text\": \"Đòi mẹ đưa đến trung tâm nắn xương không có chứng chỉ y tế để thực hiện bẻ khớp.\", \"nextNode\": \"fail_bone\"}]}, \"success_end\": {\"text\": \"🎉 Xuất sắc! Bạn đã biết cách tôn trọng nhịp độ phát triển của cơ thể, kiên định trước lời trêu chọc và tìm nguồn tư vấn y khoa chính xác khi cần.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_drugs\": {\"text\": \"❌ Chưa đúng! Tự ý uống các thuốc hormone trôi nổi cực kỳ nguy hiểm, có thể làm đóng sụn xương sớm khiến bạn lùn vĩnh viễn, đồng thời gây hại nghiêm trọng cho gan và thận.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_diet\": {\"text\": \"❌ Chưa đúng! Nhịn ăn sáng làm cơ thể thiếu hụt trầm trọng dưỡng chất để phát triển xương, cản trở trực tiếp đến sự tăng trưởng chiều cao.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_unverified\": {\"text\": \"❌ Sai rồi! Sử dụng thực phẩm chức năng kích thích hormone không rõ nguồn gốc có thể gây rối loạn nội tiết tố tuổi dậy thì và dẫn đến các bệnh lý nguy hiểm.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_heavy\": {\"text\": \"❌ Sai rồi! Tập tạ quá nặng khi xương chưa phát triển hoàn thiện dễ gây tổn thương đĩa sụn, chấn thương cột sống và kìm hãm chiều cao.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_bone\": {\"text\": \"❌ Sai rồi! Bẻ khớp nắn xương vô học có thể dẫn đến chấn thương cột sống nghiêm trọng và rạn nứt xương vĩnh viễn.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-07 03:19:49', '2026-07-07 03:19:49'),
(6189, 1037, 'sorting', '{\"instruction\": \"Hãy phân loại các biểu hiện và hành vi dậy thì sau:\", \"leftBox\": {\"title\": \"Tự nhiên & Bình thường\"}, \"rightBox\": {\"title\": \"Lầm tưởng / Có hại\"}, \"items\": [{\"text\": \"Cơ thể tăng cân và nở hông/vai\", \"correctBox\": \"left\"}, {\"text\": \"Uống thuốc hormone tăng chiều cao thần tốc\", \"correctBox\": \"right\"}, {\"text\": \"Cảm xúc nhạy cảm, dễ khóc dễ giận vô cớ\", \"correctBox\": \"left\"}, {\"text\": \"Nhịn ăn sáng để kìm hãm phát triển cơ thể\", \"correctBox\": \"right\"}, {\"text\": \"Vỡ giọng khàn khàn ở các bạn trai\", \"correctBox\": \"left\"}, {\"text\": \"Nịt ngực thật chặt để giấu dáng ngực nữ\", \"correctBox\": \"right\"}, {\"text\": \"Mọc lông tơ trên các vùng cơ thể\", \"correctBox\": \"left\"}, {\"text\": \"Tự bôi kem chứa testosterone mua lậu để dậy thì nhanh\", \"correctBox\": \"right\"}, {\"text\": \"Xuất hiện khí hư màu trắng trong không mùi\", \"correctBox\": \"left\"}, {\"text\": \"Nhịn gội đầu tắm rửa trong suốt kỳ hành kinh\", \"correctBox\": \"right\"}]}', 3, '2026-07-07 03:19:50', '2026-07-07 03:19:50'),
(6190, 1037, 'matching', '{\"instruction\": \"Ghép cặp các cột mốc dậy thì với cơ chế sinh học tương ứng:\", \"pairs\": [{\"left\": \"Tuyến yên\", \"right\": \"Tổng chỉ huy kích hoạt các hormone sinh dục\"}, {\"left\": \"Estrogen\", \"right\": \"Hormone điều hòa sự phát triển nữ tính\"}, {\"left\": \"Testosterone\", \"right\": \"Hormone thúc đẩy cơ bắp và vỡ giọng nam\"}, {\"left\": \"Đồng hồ sinh học\", \"right\": \"Nhịp độ dậy thì riêng biệt của mỗi cơ thể\"}, {\"left\": \"Hạch hạnh nhân\", \"right\": \"Vùng não kiểm soát cảm xúc nhạy cảm\"}, {\"left\": \"Vỏ não trước trán\", \"right\": \"Vùng não kiểm soát hành vi và suy nghĩ logic\"}, {\"left\": \"Dậy thì muộn\", \"right\": \"Chưa có dấu hiệu dậy thì sau tuổi 15-16 cần khám y khoa\"}, {\"left\": \"Áp lực đồng trang lứa\", \"right\": \"Cảm giác bồn chồn muốn thay đổi ngoại hình giống bạn bè\"}]}', 4, '2026-07-07 03:19:50', '2026-07-07 03:19:50'),
(6191, 1037, 'fill-blank', '{\"instruction\": \"Đoạn 1: Điền từ thích hợp về cơ chế sinh học của tuổi dậy thì:\", \"sentence\": \"Dậy thì là hành trình [blank1] tự nhiên dưới sự điều khiển của hệ nội tiết. Tuyến yên sẽ tiết ra hormone kích thích buồng trứng và tinh hoàn sản xuất [blank2] và testosterone. Những chất này đi theo dòng máu, làm thay đổi [blank3] và kích hoạt sự phát triển của xương, cơ bắp. Đừng lo lắng nếu thấy cơ thể lớn lên theo một nhịp độ [blank4] so với các bạn khác, bởi mỗi người đều có một chiếc [blank5] sinh học riêng.\", \"blanks\": {\"blank1\": {\"correct\": \"trưởng thành\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"estrogen\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"vóc dáng\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"khác biệt\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"đồng hồ\", \"placeholder\": \"...\"}}, \"words\": [\"trưởng thành\", \"estrogen\", \"vóc dáng\", \"khác biệt\", \"đồng hồ\", \"nhanh chóng\", \"bất trị\", \"đột biến\", \"giữ nguyên\", \"gan thận\"]}', 5, '2026-07-07 03:19:50', '2026-07-07 03:19:50'),
(6192, 1037, 'fill-blank', '{\"instruction\": \"Đoạn 2: Điền từ thích hợp về sự biến động cảm xúc tuổi dậy thì:\", \"sentence\": \"Ở tuổi dậy thì, sự gia tăng hormone làm tăng độ nhạy cảm của hạch [blank1], vùng não kiểm soát cảm xúc. Do đó, bạn dễ cảm thấy [blank2] hoặc tức giận vô cớ. Tuy nhiên, vỏ não trước trán chịu trách nhiệm [blank3] hành vi vẫn đang trong quá trình hoàn thiện. Để kiểm soát cảm xúc, hãy học cách dừng lại, [blank4] sâu và đặt tên cho cảm giác của mình. Bố mẹ và thầy cô chính là [blank5] tin cậy giúp bạn định hướng hành vi.\", \"blanks\": {\"blank1\": {\"correct\": \"hạnh nhân\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"nhạy cảm\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"kiểm soát\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"hít thở\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"điểm tựa\", \"placeholder\": \"...\"}}, \"words\": [\"hạnh nhân\", \"nhạy cảm\", \"kiểm soát\", \"hít thở\", \"điểm tựa\", \"vỏ não\", \"vui vẻ\", \"kìm nén\", \"trốn chạy\", \"đồng phạm\"]}', 6, '2026-07-07 03:19:50', '2026-07-07 03:19:50'),
(6193, 1037, 'interaction', '{\"question\": \"Khi nhận thấy mình dậy thì muộn hơn các bạn cùng lớp rất nhiều, hành động nào là đúng đắn và an toàn nhất?\", \"choices\": [{\"text\": \"Kiên nhẫn theo dõi, duy trì lối sống lành mạnh và đi khám bác sĩ nội tiết nếu sau 15-16 tuổi vẫn chưa có dấu hiệu dậy thì.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tự ý mua các loại kem bôi hoặc thuốc uống chứa hormone sinh dục ngoài tiệm thuốc để kích thích cơ thể dậy thì nhanh hơn.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 7, '2026-07-07 03:19:50', '2026-07-07 03:19:50'),
(6194, 1037, 'interaction', '{\"question\": \"Bạn có cảm xúc giận dữ bộc phát và cãi nhau với bố mẹ chỉ vì một việc nhỏ. Cách xoa dịu vùng hạch hạnh nhân hiệu quả nhất lúc này là gì?\", \"choices\": [{\"text\": \"Dừng lại, hít thở sâu 3 nhịp, gọi tên cảm xúc (\\\"mình đang giận\\\") để vỏ não trước trán kích hoạt kiểm soát.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Đóng sập cửa phòng, viết status tức tối bêu riếu bố mẹ trên mạng xã hội để giải tỏa năng lượng tiêu cực.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 8, '2026-07-07 03:19:50', '2026-07-07 03:19:50'),
(6195, 1037, 'interaction', '{\"question\": \"Hormone sinh dục tăng vọt ở tuổi dậy thì thực chất có vai trò như thế nào đối với tâm trạng của học sinh?\", \"choices\": [{\"text\": \"Chúng kích hoạt vùng não cảm xúc làm tăng độ nhạy cảm tự nhiên, không phải do bạn \\\"hư hỏng\\\" hay \\\"bất trị\\\".\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Chúng trực tiếp điều khiển khiến bạn trở nên độc ác, nổi loạn và thích gây gổ với mọi người xung quanh.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 9, '2026-07-07 03:19:50', '2026-07-07 03:19:50'),
(6196, 1037, 'interaction', '{\"question\": \"Nếu thấy bạn bè trong lớp phát triển nhanh hơn hẳn về vóc dáng và chiều cao, thái độ nào là thông thái nhất?\", \"choices\": [{\"text\": \"Chấp nhận nhịp độ sinh học riêng biệt của bản thân, không so sánh và tập trung rèn luyện cơ thể.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Nhịn ăn sáng và mua thuốc bôi kích thích hormone để đuổi kịp tốc độ của các bạn.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 10, '2026-07-07 03:19:50', '2026-07-07 03:19:50'),
(6197, 1037, 'interaction', '{\"question\": \"Vùng não nào đóng vai trò \'tổng phanh\' kiểm soát hành vi bốc đồng nhưng lại hoàn thiện muộn nhất ở tuổi dậy thì?\", \"choices\": [{\"text\": \"Vỏ não trước trán.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Hạch hạnh nhân.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 11, '2026-07-07 03:19:50', '2026-07-07 03:19:50'),
(6198, 1038, 'hook', '{\"title\": \"Bạn có nhận ra đôi giày thể thao yêu thích bỗng chốc trở nên chật ních chỉ sau một kỳ nghỉ hè?\"}', 1, '2026-07-07 03:19:50', '2026-07-07 03:19:50'),
(6199, 1038, 'explanation', '{\"bullets\": [\"Tuổi dậy thì chứng kiến đợt bứt phá chiều cao (growth spurt) lớn thứ hai trong đời, chỉ sau giai đoạn sơ sinh.\", \"Xương tay, xương chân kéo dài nhanh chóng, đi kèm với sự phát triển của các nhóm cơ và sự phân bố lại lượng mỡ cơ thể.\", \"Vóc dáng của bạn thay đổi rõ rệt để chuẩn bị cho cơ thể của người trưởng thành.\"]}', 2, '2026-07-07 03:19:51', '2026-07-07 03:19:51'),
(6200, 1038, 'scenario', '{\"title\": \"Tình huống tăng cân\", \"body\": \"Trang thấy rất hoang mang khi cân nặng tăng vọt 4kg trong vòng nửa năm, trong khi vùng hông và đùi trở nên tròn trịa hơn. Trang lo sợ mình đang bị béo phì và định nhịn ăn tinh bột.\"}', 3, '2026-07-07 03:19:51', '2026-07-07 03:19:51'),
(6201, 1038, 'interaction', '{\"question\": \"Trang nên nhìn nhận sự thay đổi cân nặng này như thế nào?\", \"choices\": [{\"text\": \"Đây là sự phân bố mỡ tự nhiên ở nữ giới để phát triển các cơ quan sinh sản bình thường.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Cân nặng tăng là dấu hiệu xấu, cần phải ăn kiêng khắt khe ngay để giữ dáng thon thả.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 03:19:51', '2026-07-07 03:19:51'),
(6202, 1038, 'reflection', '{\"question\": \"Bạn có thấy cơ thể mình thay đổi hình dáng rõ rệt nhất ở bộ phận nào gần đây?\"}', 5, '2026-07-07 03:19:51', '2026-07-07 03:19:51'),
(6203, 1038, 'takeaway', '{\"items\": [\"Tăng cân và nở hông/vai là dấu hiệu cơ thể bạn đang tích lũy năng lượng để trưởng thành.\"]}', 6, '2026-07-07 03:19:51', '2026-07-07 03:19:51'),
(6204, 1039, 'hook', '{\"title\": \"Bạn có từng giật mình khi thấy một nốt mụn đỏ lòm xuất hiện ngay giữa trán trước ngày chụp ảnh lớp?\"}', 1, '2026-07-07 03:19:51', '2026-07-07 03:19:51'),
(6205, 1039, 'explanation', '{\"bullets\": [\"Các hormone dậy thì kích thích tuyến bã nhờn (sebaceous glands) hoạt động mạnh mẽ, làm da mặt dễ bị dầu và bít tắc lỗ chân lông gây mụn.\", \"Đồng thời, các tuyến mồ hôi hoạt động mạnh hơn, kết hợp với vi khuẩn trên da tạo nên mùi cơ thể đặc trưng.\", \"Đây là những hiện tượng sinh lý hết sức bình thường và hoàn toàn có thể quản lý được bằng vệ sinh đúng cách.\"]}', 2, '2026-07-07 03:19:51', '2026-07-07 03:19:51'),
(6206, 1039, 'scenario', '{\"title\": \"Tình huống tự ti\", \"body\": \"Huy thấy nách mình ra nhiều mồ hôi và có mùi khó chịu sau mỗi tiết thể dục. Huy xấu hổ, không dám giơ tay phát biểu hay đứng gần các bạn vì sợ bị phát hiện mùi.\"}', 3, '2026-07-07 03:19:51', '2026-07-07 03:19:51'),
(6207, 1039, 'interaction', '{\"question\": \"Huy nên xử lý tình huống mùi cơ thể này như thế nào để tự tin hơn?\", \"choices\": [{\"text\": \"Tắm rửa sạch sẽ hàng ngày, sử dụng lăn khử mùi sau khi tắm và mặc áo cotton thông thoáng.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Dùng nước hoa thật đậm xịt đè lên vùng mồ hôi nách để lấp liếm mùi khó chịu.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 03:19:51', '2026-07-07 03:19:51'),
(6208, 1039, 'reflection', '{\"question\": \"Bạn đã xây dựng thói quen chăm sóc da mặt và cơ thể của mình như thế nào để đối phó với mụn và mồ hôi?\"}', 5, '2026-07-07 03:19:51', '2026-07-07 03:19:51'),
(6209, 1039, 'takeaway', '{\"items\": [\"Mụn hay mùi cơ thể chỉ là những lag nhẹ của hệ thống sinh học, dọn dẹp sạch sẽ là ổn ngay!\"]}', 6, '2026-07-07 03:19:51', '2026-07-07 03:19:51'),
(6210, 1040, 'hook', '{\"title\": \"Có bao giờ bạn muốn giấu mình trong những chiếc áo hoodie rộng thùng lình để không ai nhìn thấy cơ thể mình thay đổi?\"}', 1, '2026-07-07 03:19:51', '2026-07-07 03:19:51'),
(6211, 1040, 'explanation', '{\"bullets\": [\"Sự phát triển của ngực ở nữ hay vỡ giọng, mọc lông ở nam thường đi kèm với cảm giác ngượng ngùng, lúng túng.\", \"Bạn bắt đầu ý thức cực kỳ rõ về việc cơ thể mình trông như thế nào trong mắt người khác.\", \"So sánh sự phát triển của mình với các bạn xung quanh hoặc các hình mẫu trên mạng chỉ làm tăng thêm lo âu vô ích.\"]}', 2, '2026-07-07 03:19:52', '2026-07-07 03:19:52'),
(6212, 1040, 'scenario', '{\"title\": \"Tình huống giấu dáng\", \"body\": \"Vy bắt đầu phát triển ngực và cảm thấy vô cùng bối rối khi vòng một nhô lên rõ rệt dưới lớp áo đồng phục. Vy luôn khom lưng khi đi lại và mặc thêm áo khoác dày cộp dù trời nóng bức để che giấu.\"}', 3, '2026-07-07 03:19:52', '2026-07-07 03:19:52'),
(6213, 1040, 'interaction', '{\"question\": \"Vy nên làm gì để cảm thấy thoải mái và tự tin hơn với sự phát triển này?\", \"choices\": [{\"text\": \"Trò chuyện với mẹ để chọn mua loại áo lá hoặc áo ngực học sinh mềm mại, vừa vặn để nâng đỡ nhẹ nhàng.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tiếp tục khom lưng giấu dáng vì nghĩ đây là chuyện xấu hổ, không nên cho ai biết.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:19:52', '2026-07-07 03:19:52'),
(6214, 1040, 'reflection', '{\"question\": \"Bạn có từng cảm thấy ngượng ngùng vì một thay đổi thể chất nào đó trên cơ thể mình chưa?\"}', 5, '2026-07-07 03:19:52', '2026-07-07 03:19:52'),
(6215, 1040, 'takeaway', '{\"items\": [\"Thay đổi cơ thể là huy hiệu của sự trưởng thành, không phải là điều cần che giấu.\"]}', 6, '2026-07-07 03:19:52', '2026-07-07 03:19:52'),
(6216, 1041, 'hook', '{\"title\": \"Bạn có lo lắng khi nhận ra những sợi lông mảnh dẻ bắt đầu xuất hiện ở những vùng nhạy cảm trên cơ thể?\"}', 1, '2026-07-07 03:19:52', '2026-07-07 03:19:52'),
(6217, 1041, 'explanation', '{\"bullets\": [\"Mọc lông mu (vùng kín) và lông nách là một trong những cột mốc phát triển sinh dục ngoài quan trọng ở cả hai giới.\", \"Lông vùng nhạy cảm đóng vai trò bảo vệ da, giảm ma sát và ngăn ngừa vi khuẩn xâm nhập vào cơ quan sinh dục.\", \"Màu sắc, độ rậm rạp của lông phụ thuộc vào gen di truyền và hoàn toàn bình thường cho dù có khác biệt với người khác.\"]}', 2, '2026-07-07 03:19:52', '2026-07-07 03:19:52'),
(6218, 1041, 'scenario', '{\"title\": \"Tình huống hoang mang\", \"body\": \"Minh thấy vùng kín của mình bắt đầu mọc lông rậm rạp và sẫm màu. Minh lo sợ mình bị biến đổi dị thường vì các bạn trong nhóm chưa ai kể về chuyện này.\"}', 3, '2026-07-07 03:19:52', '2026-07-07 03:19:52'),
(6219, 1041, 'interaction', '{\"question\": \"Minh nên hiểu về sự phát triển lông cơ thể này như thế nào?\", \"choices\": [{\"text\": \"Đây là hiện tượng sinh lý hoàn toàn bình thường báo hiệu hệ sinh dục ngoài đang hoàn thiện.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Chắc chắn do mình bị rối loạn hormone rồi, phải tìm cách cạo sạch ngay lập tức để trông sạch sẽ.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 03:19:52', '2026-07-07 03:19:52'),
(6220, 1041, 'reflection', '{\"question\": \"Bạn có biết cách giữ vệ sinh và chăm sóc các vùng nhạy cảm khi lông cơ thể bắt đầu phát triển không?\"}', 5, '2026-07-07 03:19:52', '2026-07-07 03:19:52'),
(6221, 1041, 'takeaway', '{\"items\": [\"Mỗi sợi lông mọc lên đều mang nhiệm vụ bảo vệ cơ thể bạn.\"]}', 6, '2026-07-07 03:19:52', '2026-07-07 03:19:52'),
(6222, 1042, 'hook', '{\"title\": \"Bạn có từng giật mình vì giọng nói của mình bỗng khàn đặc như vịt đực hay thức dậy với một bãi ướt trên quần?\"}', 1, '2026-07-07 03:19:53', '2026-07-07 03:19:53'),
(6223, 1042, 'explanation', '{\"bullets\": [\"Ở nam giới, testosterone làm thanh quản rộng ra và dây thanh đới dày lên, gây ra hiện tượng vỡ giọng (voice cracking).\", \"Đồng thời, tinh hoàn bắt đầu sản xuất tinh trùng. Hiện tượng xuất tinh tự nhiên ban đêm khi ngủ được gọi là mộng tinh (wet dream).\", \"Cả vỡ giọng và mộng tinh đều là những dấu hiệu tự nhiên cho thấy cơ quan sinh sản nam đang hoạt động khỏe mạnh.\"]}', 2, '2026-07-07 03:19:53', '2026-07-07 03:19:53'),
(6224, 1042, 'scenario', '{\"title\": \"Tình huống ngượng ngùng\", \"body\": \"Hoàng thức dậy và phát hiện quần lót mình bị ướt và dính nhớp một chất dịch màu trắng đục. Hoàng vô cùng lo sợ, nghĩ rằng mình đã làm chuyện bậy bạ hoặc bị bệnh nam khoa nặng.\"}', 3, '2026-07-07 03:19:53', '2026-07-07 03:19:53'),
(6225, 1042, 'interaction', '{\"question\": \"Hoàng nên ứng phó với tình huống mộng tinh này như thế nào?\", \"choices\": [{\"text\": \"Thay quần lót sạch, giặt ga trải giường, tự nhủ: \'Đây là mộng tinh tự nhiên, cơ thể mình đang sản xuất tinh dịch bình thường\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Giấu nhẹm chiếc quần bẩn vào góc tủ vì xấu hổ và tự dằn vặt bản thân là kẻ biến thái đầu óc đen tối.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:19:53', '2026-07-07 03:19:53'),
(6226, 1042, 'reflection', '{\"question\": \"Bạn đã chuẩn bị tâm lý thế nào cho những thay đổi sinh lý đặc trưng của giới tính mình chưa?\"}', 5, '2026-07-07 03:19:53', '2026-07-07 03:19:53'),
(6227, 1042, 'takeaway', '{\"items\": [\"Mộng tinh là cơ chế tự giải phóng tinh dịch dư thừa của cơ thể nam giới khỏe mạnh.\"]}', 6, '2026-07-07 03:19:53', '2026-07-07 03:19:53'),
(6228, 1043, 'hook', '{\"title\": \"Bạn có sẵn lòng ký hiệp ước hòa bình với những thay đổi thể chất đang diễn ra trên cơ thể mình?\"}', 1, '2026-07-07 03:19:53', '2026-07-07 03:19:53'),
(6229, 1043, 'explanation', '{\"bullets\": [\"Quá trình dậy thì có thể khiến cơ thể bạn tạm thời mất cân đối (tay chân quá dài, da nhiều dầu, giọng khàn).\", \"Đây chỉ là giai đoạn đệm trước khi cơ thể đạt được trạng thái hài hòa, ổn định của người trưởng thành.\", \"Học cách trân trọng chức năng hoạt động của cơ thể thay vì chỉ săm soi khuyết điểm ngoại hình giúp bạn tự tin hơn.\"]}', 2, '2026-07-07 03:19:53', '2026-07-07 03:19:53'),
(6230, 1043, 'scenario', '{\"title\": \"Tình huống tự ti\", \"body\": \"Lan cảm thấy ghét đôi chân dài ngoằng khòng khoeo của mình và luôn mặc quần ống rộng quét đất để che giấu. Lan nghĩ cơ thể mình thật kỳ dị và xấu xí.\"}', 3, '2026-07-07 03:19:54', '2026-07-07 03:19:54'),
(6231, 1043, 'interaction', '{\"question\": \"Lan nên viết lại suy nghĩ tự ti của mình như thế nào để cảm thấy bao dung hơn với bản thân?\", \"choices\": [{\"text\": \"Đôi chân dài giúp mình đi lại nhanh nhẹn, đạp xe và giúp mình cao ráo hơn. Cơ thể đang nỗ lực lớn lên, mình cần kiên nhẫn.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Mình phải tìm cách đi giày cao gót hoặc mặc đồ bó sát để ép cơ thể trông cân đối hơn bằng mọi giá.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:19:54', '2026-07-07 03:19:54'),
(6232, 1043, 'reflection', '{\"question\": \"Một thay đổi cơ thể nào gần đây khiến bạn thấy lúng túng nhất? Bạn có thể chấp nhận nó thế nào?\"}', 5, '2026-07-07 03:19:54', '2026-07-07 03:19:54'),
(6233, 1043, 'takeaway', '{\"items\": [\"Cơ thể bạn không phải là một món đồ trang trí, đó là phương tiện giúp bạn khám phá thế giới.\"]}', 6, '2026-07-07 03:19:54', '2026-07-07 03:19:54'),
(6234, 1044, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Những biến đổi lớn trên cơ thể\'! Hãy kiểm tra kiến thức về giọng nói, mùi cơ thể và các tuyến tiết sinh lý nhé.\"}', 1, '2026-07-07 03:19:54', '2026-07-07 03:19:54'),
(6235, 1044, 'scenario-choice', '{\"title\": \"Chăm sóc cơ thể khi vỡ giọng và mọc lông\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Đức bị vỡ giọng khàn khàn, bạn bè trêu chọc Đức phát ra âm thanh giống vịt đực. Đức thấy vô cùng tự ti và muốn làm giọng mình trong trẻo trở lại.\", \"choices\": [{\"text\": \"Cố gắng nhịn nói chuyện tối đa, giả vờ đau họng để không phải phát biểu.\", \"nextNode\": \"fail_silent\"}, {\"text\": \"Chấp nhận đây là hiện tượng sinh lý tự nhiên, nói chuyện với âm lượng vừa phải và uống nước ấm.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Một bạn mách Đức nên uống các loại nước lá thảo mộc truyền miệng tự chế ở nhà để chữa khản tiếng nhanh chóng.\", \"choices\": [{\"text\": \"Tự mua các loại lá thảo mộc không rõ nguồn gốc về đun uống bừa bãi.\", \"nextNode\": \"fail_herbs\"}, {\"text\": \"Tìm hiểu khoa học, nhận thấy vỡ giọng do dây thanh âm dày lên dưới tác động của hormone nam, không thể chữa bằng mẹo nam y.\", \"nextNode\": \"step3\"}]}, \"step3\": {\"text\": \"Đức phát hiện cơ thể bắt đầu mọc lông mu và lông nách dày hơn. Đức cảm thấy ngứa ngáy và muốn dùng dao cạo râu cũ của bố để cạo sạch chúng.\", \"choices\": [{\"text\": \"Dùng dao cạo cũ cạo khô lông nách và lông mu để sạch sẽ nhanh chóng.\", \"nextNode\": \"fail_shave\"}, {\"text\": \"Giữ vệ sinh sạch sẽ bằng nước ấm, chỉ dùng kéo sạch cắt tỉa gọn gàng nếu quá ngứa ngáy, tránh cạo sát da.\", \"nextNode\": \"step4\"}]}, \"step4\": {\"text\": \"Đức phát hiện nách bắt đầu đổ nhiều mồ hôi và phát ra mùi hôi chua sau mỗi lần tập bóng rổ. Bạn mách Đức dùng cồn y tế lau nách để diệt khuẩn triệt để.\", \"choices\": [{\"text\": \"Bôi cồn y tế 90 độ trực tiếp lên nách để sát trùng mạnh.\", \"nextNode\": \"fail_alcohol\"}, {\"text\": \"Tắm rửa xà phòng trung tính, lau khô và dùng sản phẩm lăn nách dịu nhẹ.\", \"nextNode\": \"step5\"}]}, \"step5\": {\"text\": \"Sau một đêm ngủ dậy, Đức thấy quần lót và ga giường có vệt dịch ẩm ướt kèm mùi lạ. Đức sợ hãi nghĩ mình bị bệnh thận bẩm sinh.\", \"choices\": [{\"text\": \"Bình tĩnh nhận diện đây là hiện tượng mộng tinh bình thường, đem ga giường đi giặt sạch sẽ.\", \"nextNode\": \"success_end\"}, {\"text\": \"Giấu chăn gối đi, âm thầm uống các loại thực phẩm chức năng bổ thận tráng dương tự mua.\", \"nextNode\": \"fail_kidney\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã biết cách bảo vệ dây thanh âm đúng khoa học, xử lý lông cơ thể và vệ sinh mồ hôi, mộng tinh an toàn.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_silent\": {\"text\": \"❌ Chưa đúng! Nhịn nói không giúp dây thanh âm nhỏ lại mà chỉ làm bạn tự cô lập bản thân và mất đi sự tự tin giao tiếp.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_herbs\": {\"text\": \"❌ Chưa đúng! Các bài thuốc truyền miệng tự chế không rõ liều lượng có thể gây dị ứng hoặc nhiễm khuẩn, làm viêm thanh quản nặng thêm.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_shave\": {\"text\": \"❌ Sai rồi! Cạo lông bằng dao cạo cũ bẩn dễ gây trầy xước da, dẫn đến viêm nang lông và lông mọc ngược đau rát.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_alcohol\": {\"text\": \"❌ Sai rồi! Cồn nồng độ cao làm khô da nghiêm trọng, gây bỏng rát và tăng tiết mồ hôi bù trừ nặng hơn ở vùng nách.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_kidney\": {\"text\": \"❌ Sai rồi! Mộng tinh là hiện tượng sinh lý giải phóng tinh trùng thừa tự nhiên, tự uống thuốc bổ thận khi dậy thì cực kỳ hại gan.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-07 03:19:54', '2026-07-07 03:19:54'),
(6236, 1044, 'sorting', '{\"instruction\": \"Hãy phân loại các phương pháp chăm sóc cơ thể dậy thì sau:\", \"leftBox\": {\"title\": \"Chăm sóc an toàn\"}, \"rightBox\": {\"title\": \"Có hại / Phản khoa học\"}, \"items\": [{\"text\": \"Uống nước ấm và hạn chế hét to khi vỡ giọng\", \"correctBox\": \"left\"}, {\"text\": \"Tự cạo khô lông nách bằng dao cạo râu cũ\", \"correctBox\": \"right\"}, {\"text\": \"Dùng kéo sạch tỉa bớt lông mu nếu quá ngứa\", \"correctBox\": \"left\"}, {\"text\": \"Uống nước thảo mộc tự đun để chữa vỡ giọng\", \"correctBox\": \"right\"}, {\"text\": \"Mặc quần lót chất liệu cotton thoáng mát\", \"correctBox\": \"left\"}, {\"text\": \"Giấu kín không thay ga giường sau khi mộng tinh\", \"correctBox\": \"right\"}, {\"text\": \"Tắm rửa xà phòng dịu nhẹ sau khi tập thể thao\", \"correctBox\": \"left\"}, {\"text\": \"Bôi cồn 90 độ lên nách để khử trùng mồ hôi\", \"correctBox\": \"right\"}, {\"text\": \"Giặt đồ lót và phơi dưới ánh nắng mặt trời\", \"correctBox\": \"left\"}, {\"text\": \"Uống thuốc bổ thận tự mua để chữa mộng tinh\", \"correctBox\": \"right\"}]}', 3, '2026-07-07 03:19:54', '2026-07-07 03:19:54'),
(6237, 1044, 'matching', '{\"instruction\": \"Ghép cặp các biến đổi cơ thể với cách chăm sóc tương ứng:\", \"pairs\": [{\"left\": \"Vỡ giọng\", \"right\": \"Hiện tượng dây thanh âm dày và dài ra ở bạn trai\"}, {\"left\": \"Lông cơ thể\", \"right\": \"Lớp rào chắn bảo vệ da khỏi cọ xát và vi khuẩn\"}, {\"left\": \"Viêm nang lông\", \"right\": \"Nguy cơ khi cạo lông không đúng cách bằng dao cạo bẩn\"}, {\"left\": \"Mộng tinh\", \"right\": \"Cơ chế tự giải phóng tinh dịch thừa khi ngủ ở nam\"}, {\"left\": \"Tắm rửa hàng ngày\", \"right\": \"Biện pháp làm sạch chất nhờn và mồ hôi dậy thì\"}, {\"left\": \"Giặt ga trải giường\", \"right\": \"Hành động vệ sinh cần làm ngay sau khi mộng tinh\"}, {\"left\": \"Bao quy đầu\", \"right\": \"Nơi bám bẩn bựa sinh dục cần kéo nhẹ để rửa sạch\"}, {\"left\": \"Dây thanh âm\", \"right\": \"Cơ quan phát âm cần tránh la hét quá to khi đang vỡ giọng\"}]}', 4, '2026-07-07 03:19:54', '2026-07-07 03:19:54'),
(6238, 1044, 'fill-blank', '{\"instruction\": \"Đoạn 1: Điền từ thích hợp về sự biến đổi thanh âm và cách chăm sóc:\", \"sentence\": \"Hiện tượng vỡ giọng xảy ra khi hormone nam thúc đẩy dây thanh âm [blank1] và dài ra. Tiếng nói của bạn trai sẽ trở nên [blank2] và đôi lúc bị hụt hơi. Đây là một sự chuyển đổi sinh lý [blank3], không phải là bệnh lý nên không cần dùng các loại nước lá [blank4] không rõ nguồn gốc. Hãy bảo vệ giọng nói bằng cách uống [blank5] ấm và hạn chế la hét quá lớn.\", \"blanks\": {\"blank1\": {\"correct\": \"dày lên\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"trầm khàn\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"tự nhiên\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"truyền miệng\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"nước\", \"placeholder\": \"...\"}}, \"words\": [\"dày lên\", \"trầm khàn\", \"tự nhiên\", \"truyền miệng\", \"nước\", \"mỏng đi\", \"trong trẻo\", \"đột ngột\", \"tự chế\", \"nước đá\"]}', 5, '2026-07-07 03:19:54', '2026-07-07 03:19:54'),
(6239, 1044, 'fill-blank', '{\"instruction\": \"Đoạn 2: Điền từ thích hợp về sự phát triển tuyến mồ hôi và lông cơ thể:\", \"sentence\": \"Tuyến mồ hôi và bã nhờn hoạt động mạnh dễ gây ra [blank1] cơ thể dậy thì. Để vệ sinh sạch sẽ, bạn nên tắm rửa hàng ngày và mặc quần lót [blank2] thoáng khí. Sự xuất hiện của lông mu giúp giảm [blank3] và bảo vệ niêm mạc nhạy cảm. Ngoài ra, hiện tượng [blank4] là cơ chế tự giải phóng tinh dịch thừa của bạn trai khi ngủ. Hãy chủ động [blank5] ga giường và quần lót sạch sau khi gặp hiện tượng này.\", \"blanks\": {\"blank1\": {\"correct\": \"mùi\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"cotton\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"cọ xát\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"mộng tinh\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"thay giặt\", \"placeholder\": \"...\"}}, \"words\": [\"mùi\", \"cotton\", \"cọ xát\", \"mộng tinh\", \"thay giặt\", \"mụn\", \"nilon\", \"ngứa ngáy\", \"di tinh\", \"giấu kín\"]}', 6, '2026-07-07 03:19:54', '2026-07-07 03:19:54'),
(6240, 1044, 'interaction', '{\"question\": \"Khi bạn trai thức dậy phát hiện ga giường bị vấy bẩn do mộng tinh lần đầu, hành động nào là đúng đắn và văn minh nhất?\", \"choices\": [{\"text\": \"Bình tĩnh thay quần lót mới, đem ga giường đi giặt sạch sẽ và hiểu rằng đây là hiện tượng sinh lý bình thường.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Hoảng sợ lo lắng nghĩ mình bị bệnh thận, âm thầm úp chăn lên vệt bẩn để giấu bố mẹ vì xấu hổ.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 7, '2026-07-07 03:19:54', '2026-07-07 03:19:54'),
(6241, 1044, 'interaction', '{\"question\": \"Hành động nào sau đây giúp hạn chế tối đa nguy cơ viêm thanh quản trong giai đoạn bạn trai đang vỡ giọng?\", \"choices\": [{\"text\": \"Hạn chế la hét quá lớn, uống đủ nước ấm và tránh uống nước đá quá lạnh liên tục.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tập luyện nói giọng trầm cố ép giọng để nghe nam tính hơn từ sớm.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 8, '2026-07-07 03:19:54', '2026-07-07 03:19:54'),
(6242, 1044, 'interaction', '{\"question\": \"Tại sao việc dùng kéo cắt tỉa lông vùng kín lại an toàn hơn việc dùng dao cạo sát da?\", \"choices\": [{\"text\": \"Vì cạo sát da dễ làm tổn thương lớp biểu bì nhạy cảm, gây trầy xước và viêm nang lông vùng nhạy cảm.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Vì lông vùng kín có chức năng giữ nhiệt nên cạo sạch sẽ làm cơ thể bị nhiễm lạnh.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 9, '2026-07-07 03:19:54', '2026-07-07 03:19:54'),
(6243, 1044, 'interaction', '{\"question\": \"Bản chất sinh học của hiện tượng mộng tinh ở bạn trai dậy thì là gì?\", \"choices\": [{\"text\": \"Cơ chế tự đào thải tự nhiên của cơ thể để giải phóng lượng tinh dịch dư thừa khi nằm ngủ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Hiện tượng cơ thể bị thiếu hụt hormone nam trầm trọng dẫn đến rò rỉ tinh chất.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 10, '2026-07-07 03:19:55', '2026-07-07 03:19:55'),
(6244, 1044, 'interaction', '{\"question\": \"Mùi chua nồng nặc ở vùng nách tuổi dậy thì chủ yếu do nguyên nhân nào gây ra?\", \"choices\": [{\"text\": \"Mồ hôi từ tuyến đầu hủy (apocrine) tương tác với vi khuẩn cư trú trên bề mặt da.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Độc tố tích tụ từ gan thải ra trực tiếp qua da nách do ăn quá nhiều đồ cay nóng.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 11, '2026-07-07 03:19:55', '2026-07-07 03:19:55'),
(6245, 1045, 'hook', '{\"title\": \"Bạn có từng cảm thấy ngượng ngùng khi nghe ai đó nhắc đến những từ như âm đạo hay tinh hoàn?\"}', 1, '2026-07-07 03:19:55', '2026-07-07 03:19:55'),
(6246, 1045, 'explanation', '{\"bullets\": [\"Cơ quan sinh sản (reproductive system) là một phần tự nhiên của giải phẫu cơ thể người, có chức năng duy trì nòi giống và cảm nhận khoái cảm.\", \"Sử dụng đúng thuật ngữ khoa học (như dương vật, âm hộ, tử cung) giúp chúng ta giao tiếp văn minh, rõ ràng về sức khỏe.\", \"Không có bộ phận nào trên cơ thể là dơ bẩn hay xấu hổ; tất cả đều có cấu tạo và nhiệm vụ sinh học quý giá.\"]}', 2, '2026-07-07 03:19:55', '2026-07-07 03:19:55'),
(6247, 1045, 'scenario', '{\"title\": \"Tình huống ngượng ngùng\", \"body\": \"Trong giờ Sinh học, thầy giáo giảng về cấu tạo cơ quan sinh dục. Cả lớp bỗng xầm xì, khúc khích cười và cúi gầm mặt xuống bàn vì thấy đỏ mặt ngại ngùng.\"}', 3, '2026-07-07 03:19:55', '2026-07-07 03:19:55'),
(6248, 1045, 'interaction', '{\"question\": \"Thái độ đúng đắn và văn minh nhất của bạn trong giờ học này là gì?\", \"choices\": [{\"text\": \"Lắng nghe nghiêm túc, ghi chép khoa học vì đây là kiến thức y sinh học cơ bản cần biết để bảo vệ sức khỏe.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Cười đùa hùa theo các bạn hoặc lấy điện thoại ra nhắn tin đùa cợt thô tục về các bộ phận nhạy cảm.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:19:55', '2026-07-07 03:19:55'),
(6249, 1045, 'reflection', '{\"question\": \"Bạn có cảm thấy thoải mái khi sử dụng các thuật ngữ giải phẫu khoa học để nói về sức khỏe của mình không?\"}', 5, '2026-07-07 03:19:55', '2026-07-07 03:19:55'),
(6250, 1045, 'takeaway', '{\"items\": [\"Gọi tên đúng các bộ phận là bước đầu tiên để chăm sóc sức khỏe khoa học.\"]}', 6, '2026-07-07 03:19:55', '2026-07-07 03:19:55'),
(6251, 1046, 'hook', '{\"title\": \"Bạn có biết âm hộ và âm đạo thực ra là hai bộ phận hoàn toàn khác nhau của cơ thể nữ giới?\"}', 1, '2026-07-07 03:19:55', '2026-07-07 03:19:55'),
(6252, 1046, 'explanation', '{\"bullets\": [\"**Âm hộ (vulva)** là toàn bộ cơ quan sinh dục ngoài có thể nhìn thấy, bao gồm môi lớn, môi bé và âm vật (clitoris - cơ quan nhạy cảm chứa nhiều đầu dây thần kinh).\", \"**Âm đạo (vagina)** là ống cơ co giãn dẫn từ âm hộ vào tử cung bên trong cơ thể, nơi máu kinh nguyệt thoát ra ngoài.\", \"Hiểu đúng cấu tạo giúp bạn gái biết cách vệ sinh và chăm sóc cơ thể an toàn.\"]}', 2, '2026-07-07 03:19:56', '2026-07-07 03:19:56'),
(6253, 1046, 'scenario', '{\"title\": \"Tình huống hoang mang\", \"body\": \"Vy muốn thử dùng cốc nguyệt san hoặc tampon nhưng lo sợ nó sẽ bị tụt sâu vào tận ổ bụng và biến mất vĩnh viễn vì âm đạo quá sâu.\"}', 3, '2026-07-07 03:19:56', '2026-07-07 03:19:56'),
(6254, 1046, 'interaction', '{\"question\": \"Vy nên hiểu cấu tạo âm đạo như thế nào để bớt lo lắng?\", \"choices\": [{\"text\": \"Âm đạo là một đường ống khép kín ở phía cuối, được ngăn cách với tử cung bằng cổ tử cung nhỏ hẹp, nên đồ vật không thể đi sâu vào ổ bụng.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Âm đạo thông thẳng vào toàn bộ cơ thể bên trong, nên tuyệt đối không được đưa bất cứ vật gì vào.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 03:19:56', '2026-07-07 03:19:56'),
(6255, 1046, 'reflection', '{\"question\": \"Bạn đã bao giờ tự tìm hiểu về cấu tạo sinh học của cơ thể mình qua các nguồn thông tin y khoa chính thống chưa?\"}', 5, '2026-07-07 03:19:56', '2026-07-07 03:19:56'),
(6256, 1046, 'takeaway', '{\"items\": [\"Hiểu biết về cơ thể giúp bạn đưa ra những quyết định chăm sóc sức khỏe thông thái.\"]}', 6, '2026-07-07 03:19:56', '2026-07-07 03:19:56'),
(6257, 1047, 'hook', '{\"title\": \"Bạn có biết dương vật và tinh hoàn của nam giới hoạt động như một nhà máy sản xuất tự động 24/7?\"}', 1, '2026-07-07 03:19:56', '2026-07-07 03:19:56'),
(6258, 1047, 'explanation', '{\"bullets\": [\"**Dương vật (penis)** gồm thân dương vật và quy đầu nhạy cảm, chứa các mô xốp có thể cương cứng khi có kích thích hoặc tự động cương vào buổi sáng.\", \"**Tinh hoàn (testicles)** nằm trong bìu, đóng vai trò sản xuất tinh trùng và hormone testosterone.\", \"Bao quy đầu (foreskin) là lớp da bảo vệ đầu dương vật, cần được chú ý vệ sinh sạch sẽ mỗi ngày.\"]}', 2, '2026-07-07 03:19:56', '2026-07-07 03:19:56'),
(6259, 1047, 'scenario', '{\"title\": \"Tình huống bối rối\", \"body\": \"Khang thức dậy chuẩn bị đi học thì thấy dương vật của mình tự nhiên cương cứng ngắc mà không hề có suy nghĩ nhạy cảm nào. Khang thấy vô cùng ngượng và sợ bị phát hiện.\"}', 3, '2026-07-07 03:19:56', '2026-07-07 03:19:56'),
(6260, 1047, 'interaction', '{\"question\": \"Khang nên nhìn nhận hiện tượng cương cứng buổi sáng này như thế nào?\", \"choices\": [{\"text\": \"Đây là hiện tượng cương cứng tự nhiên\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Chắc chắn do đầu óc mình có vấn đề đen tối nên cơ thể mới phản ứng như vậy, cần tự kiểm điểm bản thân.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:19:56', '2026-07-07 03:19:56'),
(6261, 1047, 'reflection', '{\"question\": \"Bạn có biết cách làm vệ sinh bao quy đầu đúng cách khi tắm rửa hàng ngày không?\"}', 5, '2026-07-07 03:19:56', '2026-07-07 03:19:56'),
(6262, 1047, 'takeaway', '{\"items\": [\"Cương cứng tự nhiên là tín hiệu hệ mạch máu và thần kinh nam giới đang hoạt động tốt.\"]}', 6, '2026-07-07 03:19:56', '2026-07-07 03:19:56'),
(6263, 1048, 'hook', '{\"title\": \"Có phải việc tò mò khám phá cơ thể của chính mình là hành vi dơ bẩn hay có lỗi?\"}', 1, '2026-07-07 03:19:56', '2026-07-07 03:19:56'),
(6264, 1048, 'explanation', '{\"bullets\": [\"Sự tò mò về cơ thể và cảm giác nhạy cảm ở vùng kín là phản ứng sinh học hoàn toàn tự nhiên khi hormone dậy thì dâng cao.\", \"Tự kích thích hay tự khám phá cơ thể (masturbation) là hành vi riêng tư phổ biến, giúp giải tỏa áp lực sinh lý và hiểu rõ phản xạ cơ thể.\", \"Hành vi này chỉ không lành mạnh nếu nó gây nghiện, ảnh hưởng đến học tập hoặc diễn ra ở nơi công cộng xâm phạm ranh giới người khác.\"]}', 2, '2026-07-07 03:19:57', '2026-07-07 03:19:57'),
(6265, 1048, 'scenario', '{\"title\": \"Tình huống tội lỗi\", \"body\": \"Huy lỡ tay chạm vào vùng kín và thấy có cảm giác dễ chịu. Sau đó Huy vô cùng hoảng sợ và dằn vặt, nghĩ rằng mình là kẻ tội lỗi, đồi trụy và sẽ bị suy giảm trí nhớ.\"}', 3, '2026-07-07 03:19:57', '2026-07-07 03:19:57'),
(6266, 1048, 'interaction', '{\"question\": \"Huy nên hiểu đúng về cảm xúc tội lỗi của mình như thế nào?\", \"choices\": [{\"text\": \"Khám phá cơ thể là bình thường, không gây hại sức khỏe nếu giữ vệ sinh và thực hiện ở không gian riêng tư.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Lời đồn là đúng, tự khám phá sẽ hủy hoại tương lai nên phải tự trừng phạt bản thân để chừa.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:19:57', '2026-07-07 03:19:57'),
(6267, 1048, 'reflection', '{\"question\": \"Bạn đã bao giờ nghe những tin đồn đáng sợ nào về việc tự khám phá cơ thể chưa? Bạn đối phó với nó thế nào?\"}', 5, '2026-07-07 03:19:57', '2026-07-07 03:19:57'),
(6268, 1048, 'takeaway', '{\"items\": [\"Cơ thể là của bạn, tìm hiểu nó một cách tôn trọng và an toàn là quyền của bạn.\"]}', 6, '2026-07-07 03:19:57', '2026-07-07 03:19:57'),
(6269, 1049, 'hook', '{\"title\": \"Làm sao để bảo vệ vùng nhạy cảm của mình trước những đụng chạm không mong muốn từ người khác?\"}', 1, '2026-07-07 03:19:57', '2026-07-07 03:19:57'),
(6270, 1049, 'explanation', '{\"bullets\": [\"Quy tắc đồ bơi (swimsuit rule) chỉ ra rằng bất kỳ ai cũng không được phép đụng chạm vào vùng cơ thể được che bởi đồ bơi của bạn.\", \"Cơ thể bạn thuộc quyền sở hữu của riêng bạn. Bạn có quyền từ chối bất kỳ đụng chạm nào khiến bạn thấy uncomfy hay sợ hãi.\", \"Hãy tin vào linh cảm cơ thể (gut feeling) - nếu thấy có cờ đỏ, hãy lên tiếng hoặc rời đi ngay lập tức.\"]}', 2, '2026-07-07 03:19:57', '2026-07-07 03:19:57'),
(6271, 1049, 'scenario', '{\"title\": \"Tình huống nhạy cảm\", \"body\": \"Trong chuyến xe bus đông đúc, một người đàn ông lạ cố tình đứng sát và để tay chạm vào vùng mông của Hân. Hân thấy sợ hãi, run rẩy và đông cứng người, không dám phản kháng vì sợ mọi người nhìn.\"}', 3, '2026-07-07 03:19:57', '2026-07-07 03:19:57'),
(6272, 1049, 'interaction', '{\"question\": \"Hân nên phản xạ nhanh như thế nào để bảo vệ bản thân trong tình huống này?\", \"choices\": [{\"text\": \"Tránh ra chỗ khác ngay lập tức, hoặc nói to: \'Chú tránh xa cháu ra!\' để thu hút sự chú ý của mọi người xung quanh giúp đỡ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Im lặng chịu đựng, cố nhắm mắt cho qua vì nghĩ chắc họ chỉ vô tình đụng phải do xe bus đông.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 03:19:57', '2026-07-07 03:19:57'),
(6273, 1049, 'reflection', '{\"question\": \"Bạn đã bao giờ rơi vào tình huống bị đụng chạm khiến bạn thấy khó chịu chưa? Bạn đã phản ứng thế nào?\"}', 5, '2026-07-07 03:19:57', '2026-07-07 03:19:57'),
(6274, 1049, 'takeaway', '{\"items\": [\"Cơ thể bạn là thánh địa của riêng bạn, bạn có toàn quyền nói \'Không\'.\"]}', 6, '2026-07-07 03:19:58', '2026-07-07 03:19:58'),
(6275, 1050, 'hook', '{\"title\": \"Bạn có sẵn lòng hứa sẽ luôn trân trọng và bảo vệ cơ thể độc nhất vô nhị của mình không?\"}', 1, '2026-07-07 03:19:58', '2026-07-07 03:19:58'),
(6276, 1050, 'explanation', '{\"bullets\": [\"Tôn trọng cơ thể (body respect) là nền tảng của sự tự tin và sức khỏe tinh thần vững chắc.\", \"Điều này bao gồm việc chăm sóc vệ sinh, ăn uống đủ chất, nghỉ ngơi khoa học và không cho phép ai xâm phạm ranh giới cá nhân.\", \"Khi bạn trân trọng cơ thể mình, bạn cũng sẽ biết cách tôn trọng cơ thể và ranh giới của bạn bè xung quanh.\"]}', 2, '2026-07-07 03:19:58', '2026-07-07 03:19:58'),
(6277, 1050, 'scenario', '{\"title\": \"Tình huống đùa cợt\", \"body\": \"Nhóm bạn thân rủ nhau đùa nghịch, kéo quần hoặc đụng chạm vùng kín của một bạn nam khác trong lớp để làm trò đùa tiêu khiển. Bạn nam kia tỏ rõ sự khó chịu nhưng nhóm bạn vẫn cười hùa vui vẻ.\"}', 3, '2026-07-07 03:19:58', '2026-07-07 03:19:58'),
(6278, 1050, 'interaction', '{\"question\": \"Hành động đùa nghịch đụng chạm nhạy cảm của nhóm bạn nên được nhìn nhận thế nào?\", \"choices\": [{\"text\": \"Đây là hành vi xâm hại ranh giới cơ thể nghiêm trọng dưới danh nghĩa trò đùa, cần lên tiếng ngăn chặn ngay.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Chỉ là đùa giỡn tuổi học trò cho vui thôi, bạn nam kia nhạy cảm quá đà mới thấy khó chịu.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:19:58', '2026-07-07 03:19:58'),
(6279, 1050, 'reflection', '{\"question\": \"Bạn đã từng lên tiếng bảo vệ ranh giới cơ thể của mình hoặc của bạn bè khi bị đùa cợt khiếm nhã chưa?\"}', 5, '2026-07-07 03:19:58', '2026-07-07 03:19:58'),
(6280, 1050, 'takeaway', '{\"items\": [\"Tôn trọng cơ thể người khác cũng quan trọng như việc bảo vệ cơ thể của chính mình.\"]}', 6, '2026-07-07 03:19:58', '2026-07-07 03:19:58'),
(6281, 1051, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Giải phẫu cơ thể & Sự tự nhận thức\'! Cùng củng cố kiến thức bảo vệ hệ sinh dục và tôn trọng ranh giới cơ thể.\"}', 1, '2026-07-07 03:19:58', '2026-07-07 03:19:58'),
(6282, 1051, 'scenario-choice', '{\"title\": \"Bảo vệ tinh hoàn và ứng phó cương cứng bất ngờ\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Nam phát hiện vùng tinh hoàn của mình bị đau tức nhẹ sau một trận va chạm bóng đá ở trường. Nam thấy rất ngượng ngùng và lo lắng.\", \"choices\": [{\"text\": \"Giấu kín vì xấu hổ, tự ra tiệm thuốc tây mua thuốc giảm đau liều mạnh về tự uống.\", \"nextNode\": \"fail_silent\"}, {\"text\": \"Bình tĩnh tự kiểm tra vùng bìu tinh hoàn xem có sưng đỏ không và chia sẻ thẳng thắn với bố hoặc người lớn tin cậy.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Cơn đau tức tinh hoàn không giảm sau 2 tiếng, bạn cùng lớp khuyên Nam cứ nằm nghỉ chịu đau qua đêm là tự khỏi, không cần đi bệnh viện.\", \"choices\": [{\"text\": \"Nghe bạn nằm chịu đau ở nhà để tránh việc phải cởi đồ cho bác sĩ kiểm tra vùng nhạy cảm.\", \"nextNode\": \"fail_wait\"}, {\"text\": \"Cương quyết nhờ bố đưa đi bệnh viện khám nam khoa/ngoại khoa ngay vì nghi ngờ nguy cơ xoắn tinh hoàn.\", \"nextNode\": \"step3\"}]}, \"step3\": {\"text\": \"Khi đang đứng phát biểu bài trước lớp học, dương vật của Nam bỗng nhiên cương cứng bất ngờ (hiện tượng sinh lý bình thường) làm Nam đỏ bừng mặt.\", \"choices\": [{\"text\": \"Hoảng loạn khóc lóc và chạy ngay ra khỏi lớp học để trốn tránh các bạn.\", \"nextNode\": \"fail_panic\"}, {\"text\": \"Bình tĩnh đặt cuốn sách hoặc hộp bút che phía trước quần, hít thở sâu để phân tán suy nghĩ và đợi dương vật tự xẹp xuống.\", \"nextNode\": \"step4\"}]}, \"step4\": {\"text\": \"Sau giờ học, một bạn học đùa dai chạy đến túm quần cố tình kéo tụt quần Nam xuống trước mặt các bạn khác để trêu đùa.\", \"choices\": [{\"text\": \"Không làm gì cả, cố cười trừ xem như trò đùa vô hại để giữ hòa khí.\", \"nextNode\": \"fail_laugh\"}, {\"text\": \"Kéo quần lên ngay lập tức, nhìn thẳng bạn đó và nói rõ: \\\"Đây là đùa cợt thô lỗ xâm phạm cơ thể tớ, tớ yêu cầu cậu không được lặp lại.\\\"\", \"nextNode\": \"step5\"}]}, \"step5\": {\"text\": \"Bạn đó vẫn tiếp tục cười cợt và rủ các bạn khác tham gia đùa giỡn, đe dọa sẽ tụt quần Nam lần nữa vào ngày mai.\", \"choices\": [{\"text\": \"Báo cáo ngay sự việc với giáo viên chủ nhiệm hoặc ban giám hiệu nhà trường để được can thiệp bảo vệ.\", \"nextNode\": \"success_end\"}, {\"text\": \"Âm thầm chịu đựng và quyết định trốn học ngày mai để tránh bị quấy rối.\", \"nextNode\": \"fail_run\"}]}, \"success_end\": {\"text\": \"🎉 Xuất sắc! Bạn đã bảo vệ bản thân thông thái trước các nguy cơ nam khoa nguy hiểm, xử lý cương cứng bất ngờ và thiết lập ranh giới cơ thể vững chắc.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_silent\": {\"text\": \"❌ Chưa đúng! Giấu đau tinh hoàn và tự uống thuốc giảm đau có thể che lấp triệu chứng nguy cấp của bệnh xoắn tinh hoàn gây hoại tử.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_wait\": {\"text\": \"❌ Chưa đúng! Xoắn tinh hoàn là ca cấp cứu y khoa khẩn cấp, nếu chậm trễ quá 6 tiếng có thể phải cắt bỏ tinh hoàn dẫn đến vô sinh nam.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_panic\": {\"text\": \"❌ Sai rồi! Cương cứng bất ngờ là phản xạ sinh học hoàn toàn tự nhiên của bạn trai dậy thì, hoảng loạn bỏ chạy chỉ khiến mọi người chú ý hơn.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_laugh\": {\"text\": \"❌ Sai rồi! Chấp nhận trò đùa thô bạo sẽ khiến đối phương nghĩ bạn đồng thuận, làm lu mờ ranh giới cá nhân của bạn.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_run\": {\"text\": \"❌ Sai rồi! Trốn học không giải quyết được vấn đề mà làm bạn bị gián đoạn học tập, hãy tìm kiếm sự bảo vệ từ nhà trường và bố mẹ.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-07 03:19:58', '2026-07-07 03:19:58'),
(6283, 1051, 'sorting', '{\"instruction\": \"Hãy phân loại các hành vi ứng xử với cơ thể dưới đây:\", \"leftBox\": {\"title\": \"Tự chăm sóc đúng\"}, \"rightBox\": {\"title\": \"Nguy hiểm / Sai lệch\"}, \"items\": [{\"text\": \"Khám nam khoa ngay khi bị đau tức tinh hoàn\", \"correctBox\": \"left\"}, {\"text\": \"Tự ý mua thuốc giảm đau khi đau tinh hoàn\", \"correctBox\": \"right\"}, {\"text\": \"Thực hiện tự khám tinh hoàn hàng tháng\", \"correctBox\": \"left\"}, {\"text\": \"Đùa cợt khiếm nhã kéo quần bạn cùng lớp\", \"correctBox\": \"right\"}, {\"text\": \"Giữ bình tĩnh khi cương cứng bất ngờ\", \"correctBox\": \"left\"}, {\"text\": \"Thụt rửa sâu vào trong âm đạo bạn gái\", \"correctBox\": \"right\"}, {\"text\": \"Lau rửa bộ phận sinh dục ngoài bằng nước ấm\", \"correctBox\": \"left\"}, {\"text\": \"Chọc ghẹo bình phẩm khiếm nhã về ngực bạn gái\", \"correctBox\": \"right\"}, {\"text\": \"Từ chối thẳng thắn đụng chạm không mong muốn\", \"correctBox\": \"left\"}, {\"text\": \"Cố nằm im chịu đựng đau bìu dữ dội qua đêm\", \"correctBox\": \"right\"}]}', 3, '2026-07-07 03:19:58', '2026-07-07 03:19:58'),
(6284, 1051, 'matching', '{\"instruction\": \"Ghép cặp các bộ phận giải phẫu với định nghĩa y khoa tương ứng:\", \"pairs\": [{\"left\": \"Tinh hoàn\", \"right\": \"Cơ quan sản xuất tinh trùng và hormone nam\"}, {\"left\": \"Bao quy đầu\", \"right\": \"Lớp da bao bọc bảo vệ đầu dương vật\"}, {\"left\": \"Xoắn tinh hoàn\", \"right\": \"Cấp cứu y khoa khẩn cấp cần phẫu thuật tháo xoắn sớm\"}, {\"left\": \"Cương cứng bất ngờ\", \"right\": \"Phản xạ sinh học tự nhiên khi máu dồn về dương vật\"}, {\"left\": \"Tự khám tinh hoàn\", \"right\": \"Hành động sờ nắn tìm cục u lạ hàng tháng tại nhà\"}, {\"left\": \"Quy tắc đồ bơi\", \"right\": \"Quy ước bảo vệ tuyệt đối không ai được chạm vào vùng nhạy cảm\"}, {\"left\": \"Âm đạo\", \"right\": \"Kênh cơ nối cổ tử cung ra phía ngoài cơ thể nữ\"}, {\"left\": \"Ranh giới cá nhân\", \"right\": \"Khoảng cách an toàn về thể chất và cảm xúc do bạn quyết định\"}]}', 4, '2026-07-07 03:19:58', '2026-07-07 03:19:58'),
(6285, 1051, 'fill-blank', '{\"instruction\": \"Đoạn 1: Điền từ thích hợp về bảo vệ sức khỏe hệ sinh dục nam:\", \"sentence\": \"Tinh hoàn của bạn trai nằm trong bìu, có nhiệm vụ sản xuất tinh trùng và [blank1]. Nếu gặp chấn thương khi chơi thể thao dẫn đến đau tức bìu dữ dội kèm [blank2], bạn cần được đưa đi [blank3] ngay lập tức để loại trừ xoắn tinh hoàn. Việc tự ý uống thuốc [blank4] hoặc chịu đựng đau quá 6 tiếng có thể dẫn đến hoại tử tinh hoàn. Hãy dũng cảm [blank5] với bố mẹ hoặc người lớn tin cậy để cấp cứu kịp thời.\", \"blanks\": {\"blank1\": {\"correct\": \"testosterone\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"buồn nôn\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"cấp cứu\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"giảm đau\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"chia sẻ\", \"placeholder\": \"...\"}}, \"words\": [\"testosterone\", \"buồn nôn\", \"cấp cứu\", \"giảm đau\", \"chia sẻ\", \"estrogen\", \"sốt nhẹ\", \"khám da\", \"bổ thận\", \"giấu kín\"]}', 5, '2026-07-07 03:19:59', '2026-07-07 03:19:59');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(6286, 1051, 'fill-blank', '{\"instruction\": \"Đoạn 2: Điền từ thích hợp về quy tắc bảo vệ ranh giới cơ thể:\", \"sentence\": \"Quy tắc đồ bơi quy định rằng bất kỳ ai cũng không được [blank1] vào vùng cơ thể nhạy cảm của bạn. Bạn có quyền từ chối [blank2] mọi đụng chạm khiến bản thân thấy khó chịu hoặc sợ hãi. Nếu có người cố tình vi phạm ranh giới đó, hãy hét lớn, [blank3] khỏi nơi đó và báo ngay cho người lớn. Đừng giữ bí mật vì cảm thấy [blank4] hay tội lỗi. Sự an toàn và [blank5] cơ thể của bạn là trên hết.\", \"blanks\": {\"blank1\": {\"correct\": \"chạm\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"dứt khoát\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"chạy thoát\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"xấu hổ\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"quyền tự chủ\", \"placeholder\": \"...\"}}, \"words\": [\"chạm\", \"dứt khoát\", \"chạy thoát\", \"xấu hổ\", \"quyền tự chủ\", \"nhìn\", \"ngập ngừng\", \"nằm im\", \"tự hào\", \"sở thích\"]}', 6, '2026-07-07 03:19:59', '2026-07-07 03:19:59'),
(6287, 1051, 'interaction', '{\"question\": \"Khi bị đau tức tinh hoàn cấp tính kèm buồn nôn sau khi va chạm thể thao, hành động nào là đúng?\", \"choices\": [{\"text\": \"Đến ngay cơ sở y tế gần nhất trong vòng 6 giờ đầu để kiểm tra loại trừ xoắn tinh hoàn.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Chườm đá lạnh và nằm im một chỗ chờ 2-3 ngày xem cơn đau có tự biến mất không.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 7, '2026-07-07 03:19:59', '2026-07-07 03:19:59'),
(6288, 1051, 'interaction', '{\"question\": \"Thao tác tự kiểm tra tinh hoàn hàng tháng tại nhà giúp bạn trai phát hiện sớm điều gì?\", \"choices\": [{\"text\": \"Các cục u nhỏ, sưng tấy hoặc thay đổi kích thước bất thường nghi ngờ ung thư tinh hoàn.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Số lượng tinh trùng nhiều hay ít để đánh giá khả năng sinh sản trực quan của bản thân.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 8, '2026-07-07 03:19:59', '2026-07-07 03:19:59'),
(6289, 1051, 'interaction', '{\"question\": \"Tại sao việc đùa cợt tụt quần bạn khác trong trường lại bị coi là hành vi xâm hại ranh giới nghiêm trọng?\", \"choices\": [{\"text\": \"Vì nó vi phạm quy tắc đồ bơi, quấy rối tình dục và gây tổn thương lòng tự trọng của bạn.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Vì hành động này làm bạn bị nhiễm lạnh đột ngột ảnh hưởng đến sức khỏe thể chất.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 9, '2026-07-07 03:19:59', '2026-07-07 03:19:59'),
(6290, 1051, 'interaction', '{\"question\": \"Khi một người cố gắng đụng chạm vùng kín của bạn và hăm dọa không được nói với ai, bạn nên làm gì?\", \"choices\": [{\"text\": \"Từ chối quyết liệt, chạy thoát và báo ngay với bố mẹ hoặc thầy cô giáo tin cậy.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Âm thầm chịu đựng và giấu kín chuyện này vì nghĩ mình có lỗi.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 10, '2026-07-07 03:19:59', '2026-07-07 03:19:59'),
(6291, 1051, 'interaction', '{\"question\": \"Hiện tượng dương vật cương cứng bất ngờ vào ban ngày không đi kèm suy nghĩ kích thích ở tuổi dậy thì là do đâu?\", \"choices\": [{\"text\": \"Phản xạ sinh lý tự nhiên khi hormone sinh dục tăng cao và điều hòa mạch máu.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Dấu hiệu cảnh báo bệnh rối loạn chức năng sinh lý cần phẫu thuật gấp.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 11, '2026-07-07 03:19:59', '2026-07-07 03:19:59'),
(6292, 1052, 'hook', '{\"title\": \"Bạn có hoang mang nếu một ngày phát hiện một vệt máu đỏ tươi xuất hiện trên chiếc quần lót của mình?\"}', 1, '2026-07-07 03:19:59', '2026-07-07 03:19:59'),
(6293, 1052, 'explanation', '{\"bullets\": [\"Kinh nguyệt đầu tiên (menarche) là dấu hiệu sinh lý tự nhiên khẳng định buồng trứng của bạn gái đã bắt đầu hoạt động.\", \"Mỗi tháng, tử cung chuẩn bị một lớp niêm mạc êm ái để đón trứng thụ tinh. Nếu trứng không được thụ tinh, lớp niêm mạc này sẽ bong ra và thoát ra ngoài qua âm đạo dưới dạng máu kinh.\", \"Đây hoàn toàn là máu sạch của cơ thể, không phải là chất bẩn dơ độc như các quan niệm cổ hủ.\"]}', 2, '2026-07-07 03:20:00', '2026-07-07 03:20:00'),
(6294, 1052, 'scenario', '{\"title\": \"Tình huống hoảng loạn\", \"body\": \"Trong giờ học thể dục, Lan bỗng thấy vùng kín ẩm ướt. Khi vào nhà vệ sinh, Lan phát hiện quần mình dính đầy máu. Lan khóc nức nở vì nghĩ mình bị chấn thương chảy máu bên trong sắp chết.\"}', 3, '2026-07-07 03:20:00', '2026-07-07 03:20:00'),
(6295, 1052, 'interaction', '{\"question\": \"Nếu là bạn học đi cùng Lan vào nhà vệ sinh lúc đó, bạn nên hỗ trợ Lan như thế nào?\", \"choices\": [{\"text\": \"Ôm trấn an bạn: \'Cậu không sao đâu, đây là kinh nguyệt đầu tiên thôi!\', hướng dẫn bạn dùng băng vệ sinh và xin cô giáo cho nghỉ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Hoảng sợ chạy đi gọi xe cấp cứu y tế hoặc đứng cười trêu chọc bạn làm bạn thêm hoảng loạn.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:20:00', '2026-07-07 03:20:00'),
(6296, 1052, 'reflection', '{\"question\": \"Bạn đã chuẩn bị những kiến thức và sản phẩm vệ sinh cần thiết cho kỳ kinh nguyệt đầu tiên của mình chưa?\"}', 5, '2026-07-07 03:20:00', '2026-07-07 03:20:00'),
(6297, 1052, 'takeaway', '{\"items\": [\"Kinh nguyệt là tín hiệu cơ thể bạn đang bước vào hành trình làm mẹ kỳ diệu trong tương lai.\"]}', 6, '2026-07-07 03:20:00', '2026-07-07 03:20:00'),
(6298, 1053, 'hook', '{\"title\": \"Bạn có biết chu kỳ kinh nguyệt thực ra hoạt động như một vòng tuần hoàn của bốn mùa trong tháng?\"}', 1, '2026-07-07 03:20:00', '2026-07-07 03:20:00'),
(6299, 1053, 'explanation', '{\"bullets\": [\"Một chu kỳ kinh nguyệt chuẩn tính từ ngày đầu tiên ra máu của kỳ này đến ngày đầu tiên ra máu của kỳ tiếp theo, thường kéo dài từ 21 đến 35 ngày.\", \"Chu kỳ gồm 4 giai đoạn: Giai đoạn hành kinh (mùa đông), Giai đoạn trước rụng trứng (mùa xuân), Giai đoạn rụng trứng (mùa hè) và Giai đoạn sau rụng trứng (mùa thu).\", \"Hormone estrogen và progesterone biến động liên tục trong các giai đoạn này tạo nên sự thay đổi về năng lượng và tâm trạng.\"]}', 2, '2026-07-07 03:20:00', '2026-07-07 03:20:00'),
(6300, 1053, 'scenario', '{\"title\": \"Tình huống ẩm ương\", \"body\": \"Vy thấy tuần trước mình tràn đầy năng lượng, vui vẻ chơi đùa, nhưng tuần này bỗng thấy sụt giảm năng lượng, dễ buồn khóc vô cớ và thèm ăn đồ ngọt liên tục dù chưa đến ngày hành kinh.\"}', 3, '2026-07-07 03:20:00', '2026-07-07 03:20:00'),
(6301, 1053, 'interaction', '{\"question\": \"Sự biến đổi tâm trạng và năng lượng đột ngột của Vy do đâu?\", \"choices\": [{\"text\": \"Do hội chứng tiền kinh nguyệt\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Do Vy lười biếng và thiếu kỷ luật bản thân nên mới để cảm xúc chi phối cuộc sống.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:20:00', '2026-07-07 03:20:00'),
(6302, 1053, 'reflection', '{\"question\": \"Bạn có thói quen theo dõi ngày hành kinh của mình để nhận diện các giai đoạn thay đổi năng lượng không?\"}', 5, '2026-07-07 03:20:00', '2026-07-07 03:20:00'),
(6303, 1053, 'takeaway', '{\"items\": [\"Lắng nghe chu kỳ giúp bạn làm chủ nhịp điệu sinh học của chính mình.\"]}', 6, '2026-07-07 03:20:00', '2026-07-07 03:20:00'),
(6304, 1054, 'hook', '{\"title\": \"Làm sao để dập tắt cơn đau bụng âm ỉ như bị bóp nghẹt mỗi khi kỳ kinh nguyệt ghé thăm?\"}', 1, '2026-07-07 03:20:01', '2026-07-07 03:20:01'),
(6305, 1054, 'explanation', '{\"bullets\": [\"Cơn đau bụng kinh (cramps) xảy ra do tử cung co thắt để đẩy lớp niêm mạc ra ngoài dưới tác động của chất prostaglandins.\", \"Đau bụng âm ỉ, đau lưng nhẹ hay mỏi đùi là những hiện tượng phổ biến và có thể thuyên giảm bằng các biện pháp tự chăm sóc ấm áp.\", \"Tuy nhiên, nếu cơn đau dữ dội làm bạn ngất xỉu, nôn mửa hoặc không thể đi học, đó có thể là cờ đỏ y khoa cần đi khám chuyên khoa.\"]}', 2, '2026-07-07 03:20:01', '2026-07-07 03:20:01'),
(6306, 1054, 'scenario', '{\"title\": \"Tình huống đau đớn\", \"body\": \"Linh bị đau quặn bụng dưới trong ngày đầu tiên của kỳ kinh. Cơn đau khiến Linh toát mồ hôi hột, chỉ muốn nằm co quắp trên giường và không thể tập trung học bài.\"}', 3, '2026-07-07 03:20:01', '2026-07-07 03:20:01'),
(6307, 1054, 'interaction', '{\"question\": \"Linh nên dùng phương pháp tự nhiên nào để làm dịu cơn co thắt bụng kinh hiệu quả?\", \"choices\": [{\"text\": \"Uống nước ấm, chườm ấm vùng bụng dưới và thực hiện các động tác yoga nhẹ nhàng thư giãn cơ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Cố gồng mình chịu đựng, nhịn uống nước và uống ngay 3 viên thuốc giảm đau liều mạnh khi chưa ăn gì.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 03:20:01', '2026-07-07 03:20:01'),
(6308, 1054, 'reflection', '{\"question\": \"Bạn thường áp dụng phương pháp nào để chăm sóc cơ thể và giảm bớt khó chịu trong những ngày đèn đỏ?\"}', 5, '2026-07-07 03:20:01', '2026-07-07 03:20:01'),
(6309, 1054, 'takeaway', '{\"items\": [\"Chườm ấm và nghỉ ngơi là liều thuốc dịu dàng nhất cho tử cung của bạn.\"]}', 6, '2026-07-07 03:20:01', '2026-07-07 03:20:01'),
(6310, 1055, 'hook', '{\"title\": \"Bạn có hoa mắt trước hàng tá loại sản phẩm nguyệt san từ băng vệ sinh, tampon cho đến cốc nguyệt san?\"}', 1, '2026-07-07 03:20:01', '2026-07-07 03:20:01'),
(6311, 1055, 'explanation', '{\"bullets\": [\"Mỗi sản phẩm vệ sinh đều có ưu, nhược điểm riêng phù hợp với từng nhu cầu vận động và cơ địa.\", \"**Băng vệ sinh (pads)**: Dễ dùng, an toàn bên ngoài, cần thay sau mỗi 3-4 tiếng để tránh vi khuẩn sinh sôi.\", \"**Tampon** và **Cốc nguyệt san (menstrual cup)**: Dùng đặt trong âm đạo, giúp thoải mái vận động dưới nước, đòi hỏi kỹ năng vệ sinh tay và cách đặt chuẩn xác.\"]}', 2, '2026-07-07 03:20:02', '2026-07-07 03:20:02'),
(6312, 1055, 'scenario', '{\"title\": \"Tình huống đi bơi\", \"body\": \"Mai chuẩn bị tham gia hội thao bơi lội của trường thì kỳ kinh nguyệt đột ngột ghé thăm. Mai vô cùng thất vọng và định xin rút lui khỏi giải bơi yêu thích.\"}', 3, '2026-07-07 03:20:02', '2026-07-07 03:20:02'),
(6313, 1055, 'interaction', '{\"question\": \"Giải pháp nào giúp Mai vẫn có thể tham gia thi bơi lội an toàn và thoải mái?\", \"choices\": [{\"text\": \"Tìm hiểu cách sử dụng tampon hoặc cốc nguyệt san phù hợp dưới sự hướng dẫn y khoa hoặc người lớn đáng tin.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Dán băng vệ sinh thông thường loại dày nhất và mặc quần bơi thật chặt để đi bơi tiếp.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:20:02', '2026-07-07 03:20:02'),
(6314, 1055, 'reflection', '{\"question\": \"Bạn đã tự tin biết cách thay và xử lý băng vệ sinh đã qua sử dụng một cách văn minh và sạch sẽ chưa?\"}', 5, '2026-07-07 03:20:02', '2026-07-07 03:20:02'),
(6315, 1055, 'takeaway', '{\"items\": [\"Sản phẩm tốt nhất là sản phẩm khiến bạn cảm thấy thoải mái và an toàn nhất.\"]}', 6, '2026-07-07 03:20:02', '2026-07-07 03:20:02'),
(6316, 1056, 'hook', '{\"title\": \"Làm sao để không bao giờ bị rơi vào tình thế dở khóc dở cười khi kỳ kinh nguyệt đột ngột xuất hiện không báo trước?\"}', 1, '2026-07-07 03:20:02', '2026-07-07 03:20:02'),
(6317, 1056, 'explanation', '{\"bullets\": [\"Kinh nguyệt tuổi dậy thì thường không đều trong 1-2 năm đầu do hệ hormone chưa ổn định.\", \"Việc ghi chép và theo dõi chu kỳ giúp bạn dự đoán tương đối ngày đèn đỏ tiếp theo để chủ động chuẩn bị đồ dùng vệ sinh.\", \"Các ứng dụng công nghệ (Period tracker apps) hoặc lịch giấy nhỏ là công cụ đắc lực hỗ trợ bạn ghi chép dễ dàng.\"]}', 2, '2026-07-07 03:20:02', '2026-07-07 03:20:02'),
(6318, 1056, 'scenario', '{\"title\": \"Tình huống bất ngờ\", \"body\": \"Vy đang đi cắm trại cùng lớp thì kỳ kinh nguyệt đột ngột ghé thăm làm bẩn quần jean trắng của Vy. Vy không mang theo băng vệ sinh dự phòng và thấy vô cùng bối rối, khóc lóc muốn đi về.\"}', 3, '2026-07-07 03:20:02', '2026-07-07 03:20:02'),
(6319, 1056, 'interaction', '{\"question\": \"Thói quen chủ động nào dưới đây giúp Vy tránh được sự cố dở khóc dở cười này trong các chuyến đi sau?\", \"choices\": [{\"text\": \"Sử dụng app theo dõi chu kỳ, luôn mang theo một túi nguyệt san nhỏ dự phòng trong ba lô bất kể ngày nào.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Không đi cắm trại hay tham gia các hoạt động dã ngoại ngoài trời nữa để đảm bảo an toàn tuyệt đối.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:20:02', '2026-07-07 03:20:02'),
(6320, 1056, 'reflection', '{\"question\": \"Bạn có đang sử dụng ứng dụng hoặc cuốn sổ nào để theo dõi chu kỳ nguyệt san của mình không?\"}', 5, '2026-07-07 03:20:02', '2026-07-07 03:20:02'),
(6321, 1056, 'takeaway', '{\"items\": [\"Ghi chép chu kỳ là cách bạn trò chuyện và thấu hiểu lịch trình sinh học của cơ thể.\"]}', 6, '2026-07-07 03:20:02', '2026-07-07 03:20:02'),
(6322, 1057, 'hook', '{\"title\": \"Bạn có từng nghe ai đó bảo con gái đến ngày đèn đỏ thì không được tắm gội hay chạm vào cây cối vì sẽ làm cây chết héo?\"}', 1, '2026-07-07 03:20:02', '2026-07-07 03:20:02'),
(6323, 1057, 'explanation', '{\"bullets\": [\"Có rất nhiều quan niệm sai lầm, cổ hủ xung quanh kỳ kinh nguyệt do thiếu kiến thức khoa học.\", \"Thực tế: Bạn hoàn toàn có thể tắm rửa, gội đầu sạch sẽ bằng nước ấm (giúp giảm đau), vận động thể thao nhẹ nhàng và sinh hoạt hoàn toàn bình thường.\", \"Kinh nguyệt là hiện tượng sinh lý sạch sẽ, lành mạnh, không có gì là dơ bẩn, xui xẻo hay phải giấu giếm như một tội lỗi.\"]}', 2, '2026-07-07 03:20:02', '2026-07-07 03:20:02'),
(6324, 1057, 'scenario', '{\"title\": \"Tình huống kiêng cữ\", \"body\": \"Bà nội bảo Lan đến ngày kinh nguyệt thì tuyệt đối không được gội đầu hay tắm rửa trong suốt 5 ngày vì sẽ bị nhiễm lạnh vào tận xương tủy sau này. Lan thấy cơ thể ngứa ngáy, bẩn thỉu và rất khó chịu.\"}', 3, '2026-07-07 03:20:03', '2026-07-07 03:20:03'),
(6325, 1057, 'interaction', '{\"question\": \"Lan nên cư xử thế nào trước lời khuyên kiêng cữ của bà nội?\", \"choices\": [{\"text\": \"Giải thích nhẹ nhàng với bà dựa trên kiến thức khoa học mới, vẫn giữ vệ sinh tắm gội bằng nước ấm sạch sẽ để cơ thể thoải mái.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Ngoan ngoãn nghe lời bà nhịn tắm gội hoàn toàn trong 5 ngày dù ngứa ngáy và bốc mùi khó chịu.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:20:03', '2026-07-07 03:20:03'),
(6326, 1057, 'reflection', '{\"question\": \"Gia đình hoặc nơi bạn sống có những quan niệm kiêng cữ nào về ngày đèn đỏ mà bạn thấy vô lý không?\"}', 5, '2026-07-07 03:20:03', '2026-07-07 03:20:03'),
(6327, 1057, 'takeaway', '{\"items\": [\"Kinh nguyệt là tự nhiên và khoa học, hãy tắm gội sạch sẽ để cơ thể được yêu thương.\"]}', 6, '2026-07-07 03:20:03', '2026-07-07 03:20:03'),
(6328, 1058, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Chu kỳ kinh nguyệt & Phát triển sinh sản\'! Cùng nâng cao kỹ năng xử lý nguyệt san và bảo vệ sức khỏe phụ khoa.\"}', 1, '2026-07-07 03:20:03', '2026-07-07 03:20:03'),
(6329, 1058, 'scenario-choice', '{\"title\": \"Ứng phó trễ kinh và đau bụng kinh nguy cấp\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Vy bị trễ kinh 2 tháng nay dù trước đó chu kỳ khá đều. Vy rất lo sợ và chia sẻ với bạn cùng nhóm chat.\", \"choices\": [{\"text\": \"Tự ý mua các loại thuốc nội tiết tố trên mạng về uống để kích thích ra kinh.\", \"nextNode\": \"fail_meds\"}, {\"text\": \"Tìm hiểu thông tin khoa học, nhận thấy chu kỳ kinh nguyệt những năm đầu dậy thì chưa ổn định và theo dõi tiếp.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Bạn cùng nhóm mách Vy nên ăn thật nhiều dứa và uống nước dừa liên tục cả ngày để kinh nguyệt lập tức xuất hiện.\", \"choices\": [{\"text\": \"Ăn dứa thay cơm và uống nước dừa dồn dập suốt cả ngày.\", \"nextNode\": \"fail_pineapple\"}, {\"text\": \"Duy trì ăn uống đủ chất, ghi chép chu kỳ bằng ứng dụng và tiếp tục theo dõi.\", \"nextNode\": \"step3\"}]}, \"step3\": {\"text\": \"Kỳ kinh nguyệt đến, lần này Vy bị đau bụng kinh dữ dội kèm theo sốt cao 38.5 độ và chóng mặt.\", \"choices\": [{\"text\": \"Nghĩ là đau bụng kinh thông thường, tự ý uống 3 viên thuốc giảm đau liều mạnh rồi nằm ngủ.\", \"nextNode\": \"fail_fever\"}, {\"text\": \"Báo ngay cho mẹ để được đưa đi khám bác sĩ chuyên khoa phụ sản vì đau bụng kinh không đi kèm sốt cao.\", \"nextNode\": \"step4\"}]}, \"step4\": {\"text\": \"Tại bệnh viện, Vy được kê đơn kháng sinh điều trị viêm nhiễm và hướng dẫn tần suất thay băng vệ sinh.\", \"choices\": [{\"text\": \"Chỉ thay băng vệ sinh 1 lần mỗi ngày khi thấy lượng máu kinh ra ít để tiết kiệm băng.\", \"nextNode\": \"fail_hygiene\"}, {\"text\": \"Tuân thủ thay băng vệ sinh sau mỗi 3-4 tiếng kể cả khi máu kinh ra ít để ngăn vi khuẩn tích tụ.\", \"nextNode\": \"step5\"}]}, \"step5\": {\"text\": \"Khi tắm rửa trong những ngày hành kinh, Vy thấy trên mạng khuyên nên dùng vòi xịt nước áp lực mạnh để thụt rửa sâu bên trong cho hết máu bẩn.\", \"choices\": [{\"text\": \"Thụt rửa sâu âm đạo bằng vòi nước mạnh để làm sạch sâu.\", \"nextNode\": \"fail_douching\"}, {\"text\": \"Chỉ rửa nhẹ nhàng vùng âm hộ bên ngoài bằng nước sạch hoặc dung dịch vệ sinh phù hợp.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã biết cách quản lý chu kỳ nguyệt san khoa học, nhận biết triệu chứng nguy hiểm, vệ sinh vùng kín an toàn.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_meds\": {\"text\": \"❌ Chưa đúng! Tự ý uống thuốc nội tiết tố rất nguy hiểm, có thể gây rối loạn chu kỳ nặng hơn và hại buồng trứng.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_pineapple\": {\"text\": \"❌ Chưa đúng! Ăn quá nhiều dứa khi đói làm dạ dày bị cồn cào, loét niêm mạc do axit cao mà không giúp kích thích ra kinh.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_fever\": {\"text\": \"❌ Sai rồi! Đau bụng kinh thông thường không bao giờ kèm sốt cao. Đây là tín hiệu cấp cứu y tế, tự uống thuốc giảm đau liều mạnh sẽ che giấu bệnh nguy hiểm.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_hygiene\": {\"text\": \"❌ Sai rồi! Để băng vệ sinh quá lâu làm tích tụ vi khuẩn gây mùi và dẫn đến nhiễm trùng ngược dòng nguy hiểm.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_douching\": {\"text\": \"❌ Sai rồi! Thụt rửa sâu âm đạo phá hủy hệ lợi khuẩn âm đạo, tạo điều kiện cho vi sinh vật có hại phát triển gây viêm nhiễm nặng nề.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-07 03:20:03', '2026-07-07 03:20:03'),
(6330, 1058, 'sorting', '{\"instruction\": \"Hãy phân loại các thói quen chăm sóc nguyệt san dưới đây:\", \"leftBox\": {\"title\": \"Nên làm (Lành mạnh)\"}, \"rightBox\": {\"title\": \"Tránh làm (Có hại)\"}, \"items\": [{\"text\": \"Thay băng vệ sinh sau mỗi 3-4 tiếng\", \"correctBox\": \"left\"}, {\"text\": \"Nhịn gội đầu tắm rửa suốt cả kỳ kinh\", \"correctBox\": \"right\"}, {\"text\": \"Ghi chép lịch kinh nguyệt bằng ứng dụng di động\", \"correctBox\": \"left\"}, {\"text\": \"Ăn dứa thay cơm để kích thích kinh ra nhanh\", \"correctBox\": \"right\"}, {\"text\": \"Chườm ấm bụng dưới khi bị đau bụng kinh nhẹ\", \"correctBox\": \"left\"}, {\"text\": \"Tự ý uống thuốc nội tiết tố khi bị trễ kinh\", \"correctBox\": \"right\"}, {\"text\": \"Rửa tay sạch trước và sau khi thay băng vệ sinh\", \"correctBox\": \"left\"}, {\"text\": \"Thụt rửa sâu âm đạo bằng vòi nước áp lực mạnh\", \"correctBox\": \"right\"}, {\"text\": \"Mặc quần lót sạch làm bằng chất liệu cotton\", \"correctBox\": \"left\"}, {\"text\": \"Dùng sữa tắm chà xát thật sâu vào âm hộ\", \"correctBox\": \"right\"}]}', 3, '2026-07-07 03:20:03', '2026-07-07 03:20:03'),
(6331, 1058, 'matching', '{\"instruction\": \"Ghép cặp các khái niệm y khoa với đặc điểm tương ứng:\", \"pairs\": [{\"left\": \"Băng vệ sinh\", \"right\": \"Sản phẩm dùng bên ngoài âm hộ, dễ thay nhất\"}, {\"left\": \"Tampon\", \"right\": \"Băng vệ sinh dạng que nén đặt trong âm đạo\"}, {\"left\": \"Cốc nguyệt san\", \"right\": \"Cốc silicon thu thập dịch kinh thân thiện môi trường\"}, {\"left\": \"Đau bụng kinh kèm sốt\", \"right\": \"Triệu chứng nguy cấp cần đi bệnh viện khám ngay\"}, {\"left\": \"Hội chứng tiền kinh nguyệt\", \"right\": \"Các triệu chứng mệt mỏi, nhạy cảm trước kỳ kinh\"}, {\"left\": \"Chườm ấm bụng\", \"right\": \"Biện pháp nhiệt vật lý giúp giãn cơ tử cung\"}, {\"left\": \"Thụt rửa âm đạo\", \"right\": \"Hành vi có hại làm mất cân bằng độ pH vùng kín\"}, {\"left\": \"Niêm mạc tử cung\", \"right\": \"Lớp màng bong ra tạo thành dịch kinh nguyệt\"}]}', 4, '2026-07-07 03:20:03', '2026-07-07 03:20:03'),
(6332, 1058, 'fill-blank', '{\"instruction\": \"Đoạn 1: Điền từ thích hợp về chu kỳ kinh nguyệt và theo dõi sức khỏe:\", \"sentence\": \"Kinh nguyệt là sự bong tróc lớp niêm mạc tử cung khi không có sự [blank1]. Những năm đầu dậy thì, chu kỳ kinh nguyệt thường [blank2] do hoạt động hormone chưa ổn định. Bạn gái nên sử dụng ứng dụng để [blank3] ngày bắt đầu và kết thúc kỳ kinh. Nếu gặp tình trạng đau bụng kinh dữ dội kèm [blank4] cao hoặc khí hư có mùi tanh, bạn cần đi khám [blank5] ngay.\", \"blanks\": {\"blank1\": {\"correct\": \"thụ tinh\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"thất thường\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"theo dõi\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"sốt\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"phụ khoa\", \"placeholder\": \"...\"}}, \"words\": [\"thụ tinh\", \"thất thường\", \"theo dõi\", \"sốt\", \"phụ khoa\", \"rụng trứng\", \"đều đặn\", \"bỏ qua\", \"lạnh bụng\", \"da liễu\"]}', 5, '2026-07-07 03:20:03', '2026-07-07 03:20:03'),
(6333, 1058, 'fill-blank', '{\"instruction\": \"Đoạn 2: Điền từ thích hợp về cách vệ sinh vùng kín ngày đèn đỏ:\", \"sentence\": \"Trong những ngày hành kinh, việc thay băng vệ sinh sau mỗi [blank1] tiếng là cực kỳ cần thiết để ngăn ngừa vi khuẩn sinh sôi. Kể cả khi lượng máu kinh ra [blank2], bạn vẫn không nên để băng quá lâu. Khi sử dụng các sản phẩm đặt trong như tampon hay cốc nguyệt san, hãy nhớ vệ sinh [blank3] thật sạch trước khi thao tác. Tránh thụt rửa sâu vào trong [blank4] vì việc này làm xáo trộn độ pH tự nhiên, tăng nguy cơ [blank5] phụ khoa.\", \"blanks\": {\"blank1\": {\"correct\": \"3 đến 4\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"rất ít\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"bàn tay\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"âm đạo\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"nhiễm trùng\", \"placeholder\": \"...\"}}, \"words\": [\"3 đến 4\", \"rất ít\", \"bàn tay\", \"âm đạo\", \"nhiễm trùng\", \"8 đến 10\", \"nhiều\", \"dụng cụ\", \"tử cung\", \"vô sinh\"]}', 6, '2026-07-07 03:20:03', '2026-07-07 03:20:03'),
(6334, 1058, 'interaction', '{\"question\": \"Khi bị đau bụng kinh kèm sốt cao trên 38.5 độ và khí hư có mùi hôi tanh nồng nặc, bạn nên làm gì?\", \"choices\": [{\"text\": \"Báo ngay cho bố mẹ để đi khám bác sĩ chuyên khoa phụ sản vì có nguy cơ nhiễm trùng phụ khoa.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tự mua thuốc giảm đau uống và xông hơi vùng kín bằng nước lá trầu không tại nhà.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 7, '2026-07-07 03:20:03', '2026-07-07 03:20:03'),
(6335, 1058, 'interaction', '{\"question\": \"Tại sao việc thay băng vệ sinh sau mỗi 3-4 tiếng lại bắt buộc ngay cả khi lượng máu kinh ra rất ít?\", \"choices\": [{\"text\": \"Vì máu kinh ẩm ướt kết hợp nhiệt độ cơ thể tạo môi trường lý tưởng cho vi khuẩn sinh sôi cực nhanh sau 4 tiếng.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Vì băng vệ sinh sẽ tự động phân hủy sau 4 tiếng gây hại cho làn da nhạy cảm.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 8, '2026-07-07 03:20:03', '2026-07-07 03:20:03'),
(6336, 1058, 'interaction', '{\"question\": \"Hiện tượng trễ kinh hoặc chu kỳ kinh không đều ở các bạn gái trong 1-2 năm đầu dậy thì thường do nguyên nhân gì?\", \"choices\": [{\"text\": \"Do hệ trục não bộ - tuyến yên - buồng trứng chưa phát triển hoàn thiện, hoạt động hormone chưa ổn định.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Do bạn đã bị vô sinh hoặc mắc các bệnh phụ khoa mãn tính nguy hiểm.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 9, '2026-07-07 03:20:03', '2026-07-07 03:20:03'),
(6337, 1058, 'interaction', '{\"question\": \"Dùng xà phòng tắm thông thường có tính kiềm cao chà rửa sâu bên trong âm hộ bạn gái có thể gây hại như thế nào?\", \"choices\": [{\"text\": \"Tiêu diệt hệ lợi khuẩn âm đạo Lactobacilli và gây kích ứng khô rát niêm mạc vùng kín.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Khiến nước xà phòng ngấm vào mạch máu tử cung gây ngộ độc hệ sinh sản.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 10, '2026-07-07 03:20:03', '2026-07-07 03:20:03'),
(6338, 1058, 'interaction', '{\"question\": \"Cách sử dụng băng vệ sinh hàng ngày (loại nhỏ) an toàn cho sức khỏe bạn gái là gì?\", \"choices\": [{\"text\": \"Chỉ dùng khi ra khí hư nhiều hoặc cuối chu kỳ và phải thay sau mỗi 3-4 tiếng để tránh nhiễm khuẩn ngược dòng.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Dán liên tục từ sáng đến tối mà không cần thay vì lượng dịch ra rất ít.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 11, '2026-07-07 03:20:04', '2026-07-07 03:20:04'),
(6339, 1059, 'hook', '{\"title\": \"Tại sao thói quen vệ sinh trước đây của bạn bỗng trở nên không đủ sạch khi bước vào tuổi dậy thì?\"}', 1, '2026-07-07 03:20:04', '2026-07-07 03:20:04'),
(6340, 1059, 'explanation', '{\"bullets\": [\"Tuyến mồ hôi và tuyến bã nhờn hoạt động với công suất gấp đôi ở tuổi dậy thì, tạo môi trường thuận lợi cho vi khuẩn phát sinh.\", \"Vệ sinh cá nhân không chỉ giúp cơ thể thơm tho, phòng ngừa các bệnh ngoài da mà còn mang lại sự tự tin giao tiếp xã hội.\", \"Xây dựng thói quen tắm rửa, giặt giũ quần áo hàng ngày là bước đệm cơ bản của lối sống tự lập.\"]}', 2, '2026-07-07 03:20:04', '2026-07-07 03:20:04'),
(6341, 1059, 'scenario', '{\"title\": \"Tình huống lười biếng\", \"body\": \"Nam đi học về mệt mỏi, nằm ườn ra giường chơi game và đi ngủ luôn mà không tắm rửa hay thay quần áo vì nghĩ: \\\"Trời mát mẻ có ra mồ hôi đâu mà bẩn\\\". Sáng hôm sau, Nam thấy cơ thể ngứa ngáy khó chịu.\"}', 3, '2026-07-07 03:20:04', '2026-07-07 03:20:04'),
(6342, 1059, 'interaction', '{\"question\": \"Hành vi lười tắm rửa của Nam kéo dài sẽ dẫn tới hậu quả gì?\", \"choices\": [{\"text\": \"Mồ hôi và tế bào chết tích tụ gây mùi hôi nách, ngứa ngáy và viêm da dị ứng.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Không sao cả, chỉ cần xịt thêm nước hoa vào buổi sáng là cơ thể lại thơm tho đi học tiếp.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:20:04', '2026-07-07 03:20:04'),
(6343, 1059, 'reflection', '{\"question\": \"Bạn có đang duy trì thói quen tắm rửa và thay quần lót sạch sẽ đều đặn mỗi ngày không?\"}', 5, '2026-07-07 03:20:04', '2026-07-07 03:20:04'),
(6344, 1059, 'takeaway', '{\"items\": [\"Sạch sẽ là tấm áo giáp đầu tiên bảo vệ sức khỏe và sự tự tin của bạn.\"]}', 6, '2026-07-07 03:20:04', '2026-07-07 03:20:04'),
(6345, 1060, 'hook', '{\"title\": \"Làm sao để đối phó với làn da bỗng dưng nổi loạn đầy dầu nhờn và mụn bọc?\"}', 1, '2026-07-07 03:20:04', '2026-07-07 03:20:04'),
(6346, 1060, 'explanation', '{\"bullets\": [\"Làn da tuổi dậy thì cực kỳ nhạy cảm do sự xáo trộn hormone kích thích dầu thừa.\", \"Quy trình chăm sóc da cơ bản gồm 3 bước đơn giản: Làm sạch nhẹ nhàng (Cleansing), Dưỡng ẩm dịu nhẹ (Moisturizing) và Bảo vệ chống nắng (Sunscreen).\", \"Tránh tự ý nặn mụn bằng tay bẩn hoặc dùng các sản phẩm kem trộn tàn phá hàng rào bảo vệ da.\"]}', 2, '2026-07-07 03:20:05', '2026-07-07 03:20:05'),
(6347, 1060, 'scenario', '{\"title\": \"Tình huống nặn mụn\", \"body\": \"Linh thấy xuất hiện vài nốt mụn trứng cá trên má. Linh thấy ngứa ngáy khó chịu, liên tục dùng tay cậy, nặn mụn trước gương. Kết quả là các nốt mụn bị sưng tấy đỏ lòm và loét rộng ra.\"}', 3, '2026-07-07 03:20:05', '2026-07-07 03:20:05'),
(6348, 1060, 'interaction', '{\"question\": \"Linh nên thay đổi thói quen chăm sóc mụn này như thế nào để da nhanh lành?\", \"choices\": [{\"text\": \"Rửa mặt bằng sữa rửa mặt dịu nhẹ, giữ tay sạch không chạm lên mặt và chấm thuốc trị mụn y khoa phù hợp.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Mua ngay kem trị mụn siêu tốc không rõ nguồn gốc trên mạng để bôi thật dày lên toàn bộ khuân mặt.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 03:20:05', '2026-07-07 03:20:05'),
(6349, 1060, 'reflection', '{\"question\": \"Bạn có đang sử dụng sản phẩm làm sạch da mặt nào hàng ngày không? Nó có khiến da bạn bị khô căng sau khi rửa không?\"}', 5, '2026-07-07 03:20:05', '2026-07-07 03:20:05'),
(6350, 1060, 'takeaway', '{\"items\": [\"Làn da cần sự dịu dàng và kiên nhẫn chăm sóc, đừng trừng phạt nó bằng cách cậy nặn thô bạo.\"]}', 6, '2026-07-07 03:20:05', '2026-07-07 03:20:05'),
(6351, 1061, 'hook', '{\"title\": \"Bạn có biết vùng kín của cơ thể đòi hỏi một chế độ làm sạch đặc biệt tinh tế và cẩn thận?\"}', 1, '2026-07-07 03:20:05', '2026-07-07 03:20:05'),
(6352, 1061, 'explanation', '{\"bullets\": [\"Vùng nhạy cảm có độ pH tự nhiên cân bằng để tự bảo vệ trước nấm và vi khuẩn có hại.\", \"**Quy tắc làm sạch**: Đối với nữ, chỉ rửa sạch bên ngoài âm hộ bằng nước sạch hoặc dung dịch vệ sinh dịu nhẹ, tuyệt đối không thụt rửa sâu vào âm đạo. Đối với nam, cần nhẹ nhàng kéo bao quy đầu để làm sạch bựa sinh dục tích tụ bên dưới.\", \"Luôn lau khô vùng kín từ trước ra sau (đối với nữ) sau khi đi vệ sinh để tránh lây nhiễm vi khuẩn từ hậu môn.\"]}', 2, '2026-07-07 03:20:05', '2026-07-07 03:20:05'),
(6353, 1061, 'scenario', '{\"title\": \"Tình huống viêm nhiễm\", \"body\": \"Vy thấy vùng kín ngứa ngáy và ra khí hư màu trắng đục. Nghĩ rằng do mình chưa rửa sạch, Vy dùng xà bông tắm chà xát thật mạnh và thụt vòi sen rửa sâu vào trong âm đạo. Kết quả là Vy thấy rát buốt và ngứa nặng hơn.\"}', 3, '2026-07-07 03:20:05', '2026-07-07 03:20:05'),
(6354, 1061, 'interaction', '{\"question\": \"Hành động thụt rửa bằng xà bông của Vy sai lầm ở điểm nào?\", \"choices\": [{\"text\": \"Xà bông tắm và việc thụt rửa sâu đã phá vỡ sự cân bằng pH và tiêu diệt các lợi khuẩn bảo vệ âm đạo.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Vy dùng chưa đủ lượng xà bông sát khuẩn mạnh, cần ngâm rửa bằng nước muối đặc hoặc cồn y tế để diệt trùng.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:20:05', '2026-07-07 03:20:05'),
(6355, 1061, 'reflection', '{\"question\": \"Bạn đã nắm rõ quy trình vệ sinh vùng nhạy cảm an toàn hàng ngày cho bản thân chưa?\"}', 5, '2026-07-07 03:20:05', '2026-07-07 03:20:05'),
(6356, 1061, 'takeaway', '{\"items\": [\"Vùng kín có cơ chế tự làm sạch tuyệt vời, hãy đối xử với nó bằng sự nhẹ nhàng nhất.\"]}', 6, '2026-07-07 03:20:05', '2026-07-07 03:20:05'),
(6357, 1062, 'hook', '{\"title\": \"Tại sao bộ não của bạn lại cần đến 9 tiếng ngủ mỗi đêm để dọn dẹp các mảnh rác thông tin?\"}', 1, '2026-07-07 03:20:06', '2026-07-07 03:20:06'),
(6358, 1062, 'explanation', '{\"bullets\": [\"Trong lúc ngủ, cơ thể sản sinh ra hormone tăng trưởng (growth hormone) mạnh mẽ nhất giúp phát triển xương và cơ bắp.\", \"Bộ não tuổi dậy thì đang trong giai đoạn tái cấu trúc, rất cần giấc ngủ sâu để củng cố trí nhớ và ổn định cảm xúc.\", \"Thiếu ngủ kéo dài (dưới 8 tiếng) sẽ dẫn tới mất tập trung, dễ cáu gắt, suy giảm hệ miễn dịch và còi cọc chiều cao.\"]}', 2, '2026-07-07 03:20:06', '2026-07-07 03:20:06'),
(6359, 1062, 'scenario', '{\"title\": \"Tình huống cú đêm\", \"body\": \"Hoàng có thói quen thức đến 1-2 giờ sáng để lướt TikTok và chơi game cùng nhóm bạn. Sáng hôm sau Hoàng thức dậy trong trạng thái đầu óc mụ mị, ngủ gật trong giờ học và luôn thấy bực bội vô cớ.\"}', 3, '2026-07-07 03:20:06', '2026-07-07 03:20:06'),
(6360, 1062, 'interaction', '{\"question\": \"Hoàng nên thay đổi thói quen giấc ngủ thế nào để lấy lại năng lượng học tập?\", \"choices\": [{\"text\": \"Thiết lập ranh giới ngủ: Cất điện thoại khỏi giường trước khi ngủ 30 phút, cố gắng ngủ đủ 8-9 tiếng mỗi đêm.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tiếp tục thức khuya chơi game, bù lại bằng cách ngủ nướng đến trưa vào ngày cuối tuần.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 03:20:06', '2026-07-07 03:20:06'),
(6361, 1062, 'reflection', '{\"question\": \"Giờ ngủ trung bình hàng đêm của bạn là mấy giờ? Bạn có cảm thấy sảng khoái khi thức dậy vào buổi sáng không?\"}', 5, '2026-07-07 03:20:06', '2026-07-07 03:20:06'),
(6362, 1062, 'takeaway', '{\"items\": [\"Giấc ngủ là chiếc sạc pin tự nhiên và miễn phí tốt nhất dành cho sức khỏe của bạn.\"]}', 6, '2026-07-07 03:20:06', '2026-07-07 03:20:06'),
(6363, 1063, 'hook', '{\"title\": \"Bạn có biết cơ thể bạn đang cần những khối gạch xây dựng nào để bứt phá chiều cao tuổi dậy thì?\"}', 1, '2026-07-07 03:20:06', '2026-07-07 03:20:06'),
(6364, 1063, 'explanation', '{\"bullets\": [\"Dinh dưỡng tuổi dậy thì cần ưu tiên bổ sung đầy đủ protein (thịt, cá, trứng), canxi (sữa, rau xanh) để xây dựng hệ xương vững chắc.\", \"Uống đủ nước (khoảng 1.5 - 2 lít mỗi ngày) giúp thanh lọc cơ thể, làm da ẩm mượt và giảm mụn trứng cá.\", \"Hạn chế các đồ ăn nhanh nhiều dầu mỡ, nước ngọt có ga vì chúng làm tăng nguy cơ béo phì và cản trở hấp thụ canxi.\"]}', 2, '2026-07-07 03:20:06', '2026-07-07 03:20:06'),
(6365, 1063, 'scenario', '{\"title\": \"Tình huống bỏ bữa\", \"body\": \"Vy thường xuyên bỏ bữa sáng vì dậy muộn, bữa trưa chỉ ăn mì tôm hoặc trà sữa trân châu kèm khoai tây chiên giòn vì thấy ngon miệng. Vy thấy tóc mình rụng nhiều và móng tay rất dễ gãy.\"}', 3, '2026-07-07 03:20:06', '2026-07-07 03:20:06'),
(6366, 1063, 'interaction', '{\"question\": \"Chế độ ăn của Vy đang thiếu hụt những dưỡng chất quan trọng nào cho sự phát triển?\", \"choices\": [{\"text\": \"Thiếu protein, vitamin và các vi chất\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Không thiếu gì cả, trà sữa đã có sữa cung cấp canxi và mì tôm đã có tinh bột cung cấp năng lượng đầy đủ.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:20:06', '2026-07-07 03:20:06'),
(6367, 1063, 'reflection', '{\"question\": \"Hôm nay bạn đã uống đủ nước và ăn loại rau quả tươi xanh nào chưa?\"}', 5, '2026-07-07 03:20:06', '2026-07-07 03:20:06'),
(6368, 1063, 'takeaway', '{\"items\": [\"Bạn chính là những gì bạn ăn, hãy cung cấp nguyên liệu tốt nhất để cơ thể xây dựng vóc dáng tương lai.\"]}', 6, '2026-07-07 03:20:06', '2026-07-07 03:20:06'),
(6369, 1064, 'hook', '{\"title\": \"Làm sao để giải phóng năng lượng dư thừa và dập tắt những suy nghĩ căng thẳng, ủ dột trong đầu?\"}', 1, '2026-07-07 03:20:07', '2026-07-07 03:20:07'),
(6370, 1064, 'explanation', '{\"bullets\": [\"Vận động thể chất kích thích não bộ tiết ra endorphins - hormone hạnh phúc giúp giảm stress và cải thiện tâm trạng cực nhanh.\", \"Tập thể thao (như bơi lội, bóng rổ, chạy bộ, nhảy hiện đại) giúp kéo dài xương, săn chắc cơ bắp và nâng cao sức bền.\", \"Chỉ cần 30-45 phút vận động mỗi ngày là bạn đã giúp cơ thể phát triển tối đa tiềm năng chiều cao của mình.\"]}', 2, '2026-07-07 03:20:07', '2026-07-07 03:20:07'),
(6371, 1064, 'scenario', '{\"title\": \"Tình huống ủ dột\", \"body\": \"An thấy tâm trạng uể oải, lo lắng trước kỳ thi học kỳ. An chọn cách nằm dài trên giường lướt mạng xã hội liên tục 4 tiếng. Kết quả là An thấy đầu óc càng thêm mệt mỏi và đau ê ẩm vai gáy.\"}', 3, '2026-07-07 03:20:07', '2026-07-07 03:20:07'),
(6372, 1064, 'interaction', '{\"question\": \"An nên làm gì thay vì nằm lướt điện thoại để giải tỏa căng thẳng hiệu quả?\", \"choices\": [{\"text\": \"Xỏ giày đi bộ công viên, đạp xe hoặc tham gia một trận bóng rổ ngắn cùng các bạn hàng xóm.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tiếp tục nằm lướt điện thoại để tìm các bài viết chia sẻ mẹo giảm stress trên mạng xã hội.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:20:07', '2026-07-07 03:20:07'),
(6373, 1064, 'reflection', '{\"question\": \"Môn thể thao hoặc hoạt động vận động nào khiến bạn cảm thấy sảng khoái và tràn đầy năng lượng nhất?\"}', 5, '2026-07-07 03:20:07', '2026-07-07 03:20:07'),
(6374, 1064, 'takeaway', '{\"items\": [\"Vận động cơ thể là cách tuyệt vời nhất để dọn dẹp đống lộn xộn trong tâm trí.\"]}', 6, '2026-07-07 03:20:07', '2026-07-07 03:20:07'),
(6375, 1065, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Vệ sinh cá nhân & Chăm sóc cơ thể\'! Cùng nâng cao kỹ năng vệ sinh và thiết lập thói quen sinh hoạt khoa học.\"}', 1, '2026-07-07 03:20:07', '2026-07-07 03:20:07'),
(6376, 1065, 'scenario-choice', '{\"title\": \"Khử mùi hôi nách và xử lý kích ứng da\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Đức bị mùi cơ thể khá nặng sau mỗi buổi tập bóng rổ. Bạn bè bắt đầu xì xào làm Đức rất xấu hổ. Đức muốn khử mùi nách nhanh chóng.\", \"choices\": [{\"text\": \"Dùng chanh tươi chà xát thật mạnh lên nách liên tục nhiều lần mỗi ngày.\", \"nextNode\": \"fail_lemon\"}, {\"text\": \"Tắm rửa sạch sẽ bằng xà phòng dịu nhẹ sau khi chơi thể thao, lau khô nách.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Nách Đức vẫn đổ nhiều mồ hôi ẩm ướt. Đức băn khoăn nên chọn sản phẩm nào để kiểm soát mồ hôi nách.\", \"choices\": [{\"text\": \"Dùng nước hoa xịt đè trực tiếp lên vùng da nách đang ướt đẫm mồ hôi.\", \"nextNode\": \"fail_perfume\"}, {\"text\": \"Phân biệt rõ loại lăn khử mùi (deodorant) và lăn ngăn mồ hôi (antiperspirant) để thoa lên nách khô ráo.\", \"nextNode\": \"step3\"}]}, \"step3\": {\"text\": \"Đức phát hiện vùng da dưới cánh tay bị mẩn đỏ và ngứa rát dữ dội sau khi dùng một loại lăn ngăn mồ hôi mới mua trên mạng.\", \"choices\": [{\"text\": \"Nghĩ là phản ứng bình thường, tiếp tục lăn đè lên vết đỏ để khử mùi.\", \"nextNode\": \"fail_allergy\"}, {\"text\": \"Ngưng sử dụng ngay lập tức, rửa sạch nách bằng nước ấm và để nách thông thoáng phục hồi.\", \"nextNode\": \"step4\"}]}, \"step4\": {\"text\": \"Đức thường thức khuya lướt mạng xã hội đến 1 giờ sáng để thư giãn, dẫn đến sáng ngủ dậy rất mệt mỏi và nách đổ nhiều mồ hôi hơn.\", \"choices\": [{\"text\": \"Thiết lập lịch ngủ sớm trước 11 giờ tối để hồi phục năng lượng và điều hòa hệ nội tiết.\", \"nextNode\": \"step5\"}, {\"text\": \"Uống cà phê đậm đặc vào sáng sớm để duy trì sự tỉnh táo mà không cần thay đổi lịch ngủ.\", \"nextNode\": \"fail_coffee\"}]}, \"step5\": {\"text\": \"Khi đi tắm, Đức thấy bao quy đầu của mình có bám cặn trắng (bựa sinh dục) có mùi hôi. Bạn mách Đức dùng xà phòng tắm chà rửa mạnh vào đầu dương vật.\", \"choices\": [{\"text\": \"Dùng xà phòng tắm chứa chất tẩy rửa mạnh chà xát thật lực để sạch bựa sinh dục.\", \"nextNode\": \"fail_soap\"}, {\"text\": \"Nhẹ nhàng kéo bao quy đầu về phía sau, rửa sạch bựa sinh dục bằng nước ấm và lau khô.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã biết cách khử mùi cơ thể khoa học, xử lý kích ứng da, ngủ nghỉ điều độ và vệ sinh bao quy đầu đúng cách.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_lemon\": {\"text\": \"❌ Chưa đúng! Axit citric trong chanh chà xát trực tiếp lên nách làm bào mòn da, gây kích ứng, rát đỏ và thâm đen vùng nách.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_perfume\": {\"text\": \"❌ Chưa đúng! Xịt nước hoa đè lên mồ hôi tạo ra hỗn hợp mùi chua nồng rất khó chịu cho mọi người xung quanh.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_allergy\": {\"text\": \"❌ Sai rồi! Tiếp tục dùng sản phẩm gây kích ứng có thể làm nách bị viêm da tiếp xúc, lở loét và nhiễm trùng nặng.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_coffee\": {\"text\": \"❌ Sai rồi! Uống cà phê ép não hoạt động khi thiếu ngủ làm tăng tiết cortisol (stress hormone) khiến nách đổ mồ hôi nặng mùi hơn.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_soap\": {\"text\": \"❌ Sai rồi! Da đầu dương vật và bao quy đầu cực kỳ nhạy cảm, chà rửa bằng xà phòng kiềm mạnh gây rát bỏng và viêm nhiễm đầu dương vật.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-07 03:20:07', '2026-07-07 03:20:07'),
(6377, 1065, 'sorting', '{\"instruction\": \"Hãy phân loại các thói quen chăm sóc sức khỏe dậy thì sau:\", \"leftBox\": {\"title\": \"Thói quen tốt (Green Flag)\"}, \"rightBox\": {\"title\": \"Thói quen xấu (Red Flag)\"}, \"items\": [{\"text\": \"Tắm rửa lau khô sau khi chơi thể thao\", \"correctBox\": \"left\"}, {\"text\": \"Chà xát chanh tươi trực tiếp lên nách\", \"correctBox\": \"right\"}, {\"text\": \"Chọn lăn ngăn mồ hôi khi nách đổ dầu nhiều\", \"correctBox\": \"left\"}, {\"text\": \"Dùng nước hoa xịt thẳng lên mồ hôi ướt\", \"correctBox\": \"right\"}, {\"text\": \"Giặt sạch đồ lót mỗi ngày sau khi tắm\", \"correctBox\": \"left\"}, {\"text\": \"Mặc lại quần áo thể thao đẫm mồ hôi hôm qua\", \"correctBox\": \"right\"}, {\"text\": \"Rửa đầu dương vật nhẹ nhàng bằng nước ấm\", \"correctBox\": \"left\"}, {\"text\": \"Lăn khử mùi đè trực tiếp lên da nách đang viêm loét\", \"correctBox\": \"right\"}, {\"text\": \"Đi ngủ sớm trước 11 giờ tối để phát triển chiều cao\", \"correctBox\": \"left\"}, {\"text\": \"Thức khuya lướt điện thoại đến 2 giờ sáng\", \"correctBox\": \"right\"}]}', 3, '2026-07-07 03:20:07', '2026-07-07 03:20:07'),
(6378, 1065, 'matching', '{\"instruction\": \"Ghép cặp các phương pháp vệ sinh vùng nhạy cảm đúng khoa học:\", \"pairs\": [{\"left\": \"Deodorant\", \"right\": \"Sản phẩm chứa chất diệt khuẩn giúp khử mùi hôi nách\"}, {\"left\": \"Antiperspirant\", \"right\": \"Lăn ngăn mồ hôi chứa muối nhôm tạm khóa tuyến mồ hôi\"}, {\"left\": \"Dị ứng lăn nách\", \"right\": \"Triệu chứng mẩn đỏ, ngứa rát cần ngưng dùng ngay\"}, {\"left\": \"Bao quy đầu\", \"right\": \"Cần kéo nhẹ để rửa sạch bựa sinh dục bên dưới bằng nước ấm\"}, {\"left\": \"Vệ sinh vùng nữ\", \"right\": \"Chỉ rửa nhẹ nhàng âm hộ bên ngoài, không thụt rửa sâu\"}, {\"left\": \"Sấy khô vùng kín\", \"right\": \"Dùng khăn mềm thấm khô trước khi mặc quần lót sạch\"}, {\"left\": \"Bựa sinh dục\", \"right\": \"Chất cặn trắng đọng ở rãnh quy đầu nếu vệ sinh kém\"}, {\"left\": \"Hormone tăng trưởng\", \"right\": \"Chất kích thích chiều cao tiết ra nhiều nhất khi ngủ sâu\"}]}', 4, '2026-07-07 03:20:07', '2026-07-07 03:20:07'),
(6379, 1065, 'fill-blank', '{\"instruction\": \"Đoạn 1: Điền từ thích hợp về cơ chế khử mùi cơ thể tuổi dậy thì:\", \"sentence\": \"Mùi cơ thể phát sinh khi mồ hôi tương tác với vi khuẩn trên da. Lăn khử mùi (deodorant) chứa chất [blank1] để khử mùi hôi, còn lăn ngăn mồ hôi (antiperspirant) chứa muối [blank2] giúp khóa tuyến mồ hôi tạm thời. Bạn nên thoa các sản phẩm này lên vùng da nách đã được lau [blank3]. Nếu vùng da nách bị [blank4] đỏ và ngứa rát, hãy ngưng sử dụng ngay lập tức. Đừng lạm dụng nước hoa để [blank5] lên mồ hôi ướt vì sẽ tạo ra mùi chua nồng khó chịu.\", \"blanks\": {\"blank1\": {\"correct\": \"diệt khuẩn\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"nhôm\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"khô ráo\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"mẩn\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"xịt đè\", \"placeholder\": \"...\"}}, \"words\": [\"diệt khuẩn\", \"nhôm\", \"khô ráo\", \"mẩn\", \"xịt đè\", \"tạo mùi\", \"sắt\", \"ẩm ướt\", \"tróc\", \"pha loãng\"]}', 5, '2026-07-07 03:20:07', '2026-07-07 03:20:07'),
(6380, 1065, 'fill-blank', '{\"instruction\": \"Đoạn 2: Điền từ thích hợp về vệ sinh vùng kín và giấc ngủ dậy thì:\", \"sentence\": \"Cơ quan sinh dục cần được vệ sinh hàng ngày bằng nước sạch hoặc dung dịch vệ sinh có [blank1] phù hợp. Bạn trai chưa cắt bao quy đầu cần nhẹ nhàng [blank2] lớp da để làm sạch bựa sinh dục tích tụ bên trong. Bên cạnh vệ sinh, giấc ngủ sâu trước [blank3] là thời điểm cơ thể tiết ra [blank4] tăng trưởng mạnh nhất. Thiếu ngủ liên tục sẽ làm suy giảm [blank5] và cản trở sự phát triển chiều cao tự nhiên.\", \"blanks\": {\"blank1\": {\"correct\": \"độ pH\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"kéo ngược\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"11 giờ tối\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"hormone\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"sự tập trung\", \"placeholder\": \"...\"}}, \"words\": [\"độ pH\", \"kéo ngược\", \"11 giờ tối\", \"hormone\", \"sự tập trung\", \"hóa chất\", \"cắt bỏ\", \"1 giờ sáng\", \"độc tố\", \"chiều cao\"]}', 6, '2026-07-07 03:20:07', '2026-07-07 03:20:07'),
(6381, 1065, 'interaction', '{\"question\": \"Khi bị ngứa ngáy mẩn đỏ và rát nách sau khi dùng lăn khử mùi mới, hành động nào là đúng?\", \"choices\": [{\"text\": \"Ngưng dùng ngay lập tức, rửa nách bằng nước ấm sạch và để da phục hồi tự nhiên.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tiếp tục dùng lăn khử mùi đó kết hợp bôi cồn sát trùng nách cho hết vi khuẩn.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 7, '2026-07-07 03:20:07', '2026-07-07 03:20:07'),
(6382, 1065, 'interaction', '{\"question\": \"Sự khác biệt cốt lõi giữa lăn khử mùi (deodorant) và lăn ngăn mồ hôi (antiperspirant) là gì?\", \"choices\": [{\"text\": \"Deodorant diệt khuẩn chống mùi hôi; Antiperspirant giảm tiết mồ hôi giữ nách khô ráo.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Deodorant chỉ dùng cho bạn gái; Antiperspirant chỉ dùng cho bạn trai thể thao.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 8, '2026-07-07 03:20:07', '2026-07-07 03:20:07'),
(6383, 1065, 'interaction', '{\"question\": \"Thói quen vệ sinh vùng kín của bạn trai chưa cắt bao quy đầu chuẩn khoa học là như thế nào?\", \"choices\": [{\"text\": \"Nhẹ nhàng kéo bao quy đầu về phía sau, rửa đầu dương vật bằng nước ấm sạch mỗi ngày.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Dùng xà phòng tắm chứa hương liệu chà xát thật mạnh vào bao quy đầu để sát khuẩn.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 9, '2026-07-07 03:20:07', '2026-07-07 03:20:07'),
(6384, 1065, 'interaction', '{\"question\": \"Cận trắng (bựa sinh dục) đọng lâu ngày dưới lớp da bao quy đầu bạn trai do lười vệ sinh có thể gây ra hậu quả gì?\", \"choices\": [{\"text\": \"Kích ứng, gây mùi hôi nồng nặc và tăng nguy cơ viêm nhiễm quy đầu dương vật.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Gây teo tinh hoàn và ngăn cản sự sản xuất tinh dịch vĩnh viễn.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 10, '2026-07-07 03:20:07', '2026-07-07 03:20:07'),
(6385, 1065, 'interaction', '{\"question\": \"Thời điểm lý tưởng nhất để cơ thể tiết ra hormone tăng trưởng tối đa thúc đẩy chiều cao là lúc nào?\", \"choices\": [{\"text\": \"Khi bạn đang ngủ thật sâu trong khoảng từ 11 giờ tối đến 2 giờ sáng.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Khi bạn đang tập luyện thể thao cường độ mạnh vào ban ngày.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 11, '2026-07-07 03:20:08', '2026-07-07 03:20:08'),
(6386, 1066, 'hook', '{\"title\": \"Bạn nhìn nhận cơ thể mình bằng con mắt yêu thương, hay bằng ống kính săm soi của người khác?\"}', 1, '2026-07-07 03:20:08', '2026-07-07 03:20:08'),
(6387, 1066, 'explanation', '{\"bullets\": [\"Nhận thức ngoại hình (Body Image) là tổng hợp những cảm xúc, suy nghĩ và thái độ của bạn về vẻ bề ngoài của chính mình.\", \"Body image có thể tích cực (yêu quý, trân trọng cơ thể) hoặc tiêu cực (luôn thấy tự ti, xấu hổ, muốn thay đổi phẫu thuật).\", \"Một body image tích cực giúp bạn tự tin thể hiện bản thân và có sức khỏe tinh thần vững vàng trước áp lực xung quanh.\"]}', 2, '2026-07-07 03:20:08', '2026-07-07 03:20:08'),
(6388, 1066, 'scenario', '{\"title\": \"Tình huống tự ti\", \"body\": \"Linh luôn thấy mình có đùi to và da ngăm đen. Linh từ chối đi dã ngoại cùng lớp vì sợ phải mặc quần shorts ngắn lộ khuyết điểm. Linh luôn nghĩ mọi người sẽ cười nhạo chân mình.\"}', 3, '2026-07-07 03:20:08', '2026-07-07 03:20:08'),
(6389, 1066, 'interaction', '{\"question\": \"Linh nên thay đổi góc nhìn về đôi chân của mình như thế nào để thấy thoải mái hơn?\", \"choices\": [{\"text\": \"Trân trọng việc đôi chân khỏe mạnh đã giúp mình đi lại, chạy nhảy, chơi cầu lông và khám phá nhiều nơi.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Nhịn ăn và tìm cách bôi kem làm trắng siêu tốc để chân thon nhỏ và trắng trẻo bằng mọi giá trước khi dám ra đường.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 03:20:08', '2026-07-07 03:20:08'),
(6390, 1066, 'reflection', '{\"question\": \"Bạn có thường cảm thấy tự ti về một bộ phận nào đó trên cơ thể mình không? Bạn có muốn làm hòa với nó không?\"}', 5, '2026-07-07 03:20:08', '2026-07-07 03:20:08'),
(6391, 1066, 'takeaway', '{\"items\": [\"Ngoại hình chỉ là vỏ bọc, năng lực và tâm hồn mới là thứ tạo nên sức hút thực sự của bạn.\"]}', 6, '2026-07-07 03:20:08', '2026-07-07 03:20:08'),
(6392, 1067, 'hook', '{\"title\": \"Bạn có biết đằng sau những bức ảnh eo thon, da trắng không tì vết trên mạng là gì không?\"}', 1, '2026-07-07 03:20:08', '2026-07-07 03:20:08'),
(6393, 1067, 'explanation', '{\"bullets\": [\"Hầu hết hình ảnh trên mạng xã hội đều đã qua chỉnh sửa bằng filter bóp dáng, photoshop mịn da và chọn góc chụp ánh sáng hoàn hảo.\", \"Việc liên tục xem những hình mẫu phi thực tế này tạo nên tiêu chuẩn sắc đẹp ảo, khiến bạn ảo tưởng và tự ti về cơ thể tự nhiên của mình.\", \"Hãy tập thói quen thanh lọc mạng xã hội (digital detox), ngưng theo dõi những tài khoản độc hại làm bạn thấy tệ hại.\"]}', 2, '2026-07-07 03:20:08', '2026-07-07 03:20:08'),
(6394, 1067, 'scenario', '{\"title\": \"Tình huống lướt mạng\", \"body\": \"Hân nằm xem Instagram và thấy các hot girl khoe eo thon phẳng lì không một nếp gấp khi ngồi. Hân nhìn xuống bụng mình khi ngồi thấy có một ngấn mỡ nhỏ và thấy vô cùng thất vọng, ghét bỏ bản thân.\"}', 3, '2026-07-07 03:20:09', '2026-07-07 03:20:09'),
(6395, 1067, 'interaction', '{\"question\": \"Hân nên nhắc nhở bản thân điều gì để tránh bị thao túng bởi hình ảnh eo thon trên mạng?\", \"choices\": [{\"text\": \"Khi ngồi, da và mỡ bụng co lại tạo nếp gấp là phản ứng vật lý tự nhiên của mọi cơ thể sống để bảo vệ nội tạng.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Chắc chắn do mình béo quá rồi, phải mua đai nịt bụng nén chặt lại suốt 24h để eo thon phẳng lì như họ.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:20:09', '2026-07-07 03:20:09');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(6396, 1067, 'reflection', '{\"question\": \"Mạng xã hội có bao giờ làm bạn thấy nghi ngờ hay ghét bỏ vẻ bề ngoài tự nhiên của mình không?\"}', 5, '2026-07-07 03:20:09', '2026-07-07 03:20:09'),
(6397, 1067, 'takeaway', '{\"items\": [\"Đừng so sánh cơ thể thực tế của bạn với những tác phẩm chỉnh sửa kỹ thuật số trên mạng.\"]}', 6, '2026-07-07 03:20:09', '2026-07-07 03:20:09'),
(6398, 1068, 'hook', '{\"title\": \"Bạn sẽ làm gì khi những lời trêu chọc ác ý vô duyên nhắm thẳng vào cân nặng hay chiều cao của bạn?\"}', 1, '2026-07-07 03:20:09', '2026-07-07 03:20:09'),
(6399, 1068, 'explanation', '{\"bullets\": [\"Miệt thị ngoại hình (body shaming) là hành vi dùng lời nói chê bai, giễu cợt ngoại hình của người khác làm trò cười.\", \"Lời chê bai phản ánh định kiến hẹp hòi và sự kém tinh tế của người nói, hoàn toàn không định nghĩa giá trị thực tế của bạn.\", \"Hãy thiết lập ranh giới dứt khoát, không cười hùa theo những trò đùa khiếm nhã làm tổn hại lòng tự trọng.\"]}', 2, '2026-07-07 03:20:09', '2026-07-07 03:20:09'),
(6400, 1068, 'scenario', '{\"title\": \"Tình huống bị trêu\", \"body\": \"Trong giờ ra chơi, Nam bị một nhóm bạn nam cười cợt và gọi là \\\"thằng lùn tịt\\\" hay \\\"nấm độc\\\" trước mặt cả lớp. Nam thấy xấu hổ, tức giận muốn khóc và muốn bỏ về nhà ngay lập tức.\"}', 3, '2026-07-07 03:20:09', '2026-07-07 03:20:09'),
(6401, 1068, 'interaction', '{\"question\": \"Nam nên phản ứng dứt khoát như thế nào để bảo vệ bản thân trước nhóm bạn body shaming?\", \"choices\": [{\"text\": \"Nhìn thẳng vào họ, nói nghiêm túc: \'Tớ không thích cách các cậu trêu chọc chiều cao của tớ đâu. Dừng lại đi!\' rồi đi chỗ khác.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Cố cười gượng gạo hùa theo để mọi người thấy mình là người cởi mở, không chấp nhặt đùa vui.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 03:20:09', '2026-07-07 03:20:09'),
(6402, 1068, 'reflection', '{\"question\": \"Bạn có từng vô tình trêu chọc ngoại hình của ai đó để làm trò đùa chưa? Bạn nghĩ họ sẽ cảm thấy thế nào?\"}', 5, '2026-07-07 03:20:09', '2026-07-07 03:20:09'),
(6403, 1068, 'takeaway', '{\"items\": [\"Lời chê bai của người khác không định nghĩa bạn là ai, cách bạn phản ứng mới thể hiện bản lĩnh của bạn.\"]}', 6, '2026-07-07 03:20:09', '2026-07-07 03:20:09'),
(6404, 1069, 'hook', '{\"title\": \"Có phải việc sở hữu một cơ thể gầy gò xương xẩu mới được coi là đẹp và khỏe mạnh?\"}', 1, '2026-07-07 03:20:10', '2026-07-07 03:20:10'),
(6405, 1069, 'explanation', '{\"bullets\": [\"Ám ảnh cân nặng có thể dẫn đến các rối loạn ăn uống (eating disorders) nguy hiểm như chán ăn tâm thần hoặc cuồng ăn vô độ.\", \"Cơ thể khỏe mạnh có nhiều hình dáng, kích thước khác nhau (đậm người, mình dây, cơ bắp) tùy thuộc vào cơ địa.\", \"Mục tiêu đúng đắn là hướng tới sự khỏe mạnh, dẻo dai bên trong thông qua thói quen ăn uống, vận động khoa học thay vì chỉ số cân nặng.\"]}', 2, '2026-07-07 03:20:10', '2026-07-07 03:20:10'),
(6406, 1069, 'scenario', '{\"title\": \"Tình huống nhịn ăn\", \"body\": \"Vân muốn có thân hình mảnh mai như người mẫu nên quyết định nhịn ăn bữa tối hoàn toàn và chỉ uống nước lọc. Sau 2 tuần, Vân thấy chóng mặt, rụng tóc và không thể tập trung học bài được.\"}', 3, '2026-07-07 03:20:10', '2026-07-07 03:20:10'),
(6407, 1069, 'interaction', '{\"question\": \"Thói quen ăn uống của Vân đang gây ra tác hại gì cho cơ thể?\", \"choices\": [{\"text\": \"Nhịn ăn làm cơ thể thiếu năng lượng nuôi não bộ, suy dinh dưỡng và cản trở sự phát triển chiều cao tuổi dậy thì.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Không sao cả, đây là quá trình thanh lọc cơ thể cần thiết để đào thải mỡ thừa, giúp Vân có vóc dáng thon thả nhanh chóng.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:20:10', '2026-07-07 03:20:10'),
(6408, 1069, 'reflection', '{\"question\": \"Bạn có đang đánh giá sức khỏe của mình dựa trên con số hiển thị trên chiếc cân mỗi ngày không?\"}', 5, '2026-07-07 03:20:10', '2026-07-07 03:20:10'),
(6409, 1069, 'takeaway', '{\"items\": [\"Cân nặng chỉ là một con số, sự dẻo dai và tràn đầy năng lượng mới là thước đo sức khỏe thực sự.\"]}', 6, '2026-07-07 03:20:10', '2026-07-07 03:20:10'),
(6410, 1070, 'hook', '{\"title\": \"Bạn có sẵn lòng ký bản thỏa thuận hòa bình và chấp nhận cơ thể độc nhất vô nhị của chính mình?\"}', 1, '2026-07-07 03:20:10', '2026-07-07 03:20:10'),
(6411, 1070, 'explanation', '{\"bullets\": [\"Chấp nhận cơ thể (body acceptance) là học cách sống hòa bình với những khía cạnh ngoại hình không thể thay đổi (như chiều cao, màu da, dáng xương).\", \"Bạn không cần phải hoàn hảo để xứng đáng được yêu quý và tôn trọng.\", \"Sự độc bản (uniqueness) chính là nét quyến rũ riêng biệt của bạn; thế giới sẽ thật tẻ nhạt nếu ai cũng giống hệt nhau.\"]}', 2, '2026-07-07 03:20:10', '2026-07-07 03:20:10'),
(6412, 1070, 'scenario', '{\"title\": \"Tình huống làm hòa\", \"body\": \"Hoa có nụ cười răng khểnh và một vài vết tàn nhang trên má. Thay vì cố gắng đi tẩy tàn nhang hay giấu nụ cười, Hoa tự tin cười rạng rỡ và coi răng khểnh là nét duyên dáng riêng của mình.\"}', 3, '2026-07-07 03:20:10', '2026-07-07 03:20:10'),
(6413, 1070, 'interaction', '{\"question\": \"Thái độ tự chấp nhận của Hoa mang lại lợi ích gì cho bạn ấy?\", \"choices\": [{\"text\": \"Giúp Hoa luôn vui vẻ, tự tin giao tiếp và tỏa ra năng lượng tích cực lôi cuốn mọi người xung quanh.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Làm Hoa thiếu ý chí phấn đấu hoàn thiện vẻ đẹp ngoại hình để trở nên hoàn hảo hơn.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:20:10', '2026-07-07 03:20:10'),
(6414, 1070, 'reflection', '{\"question\": \"Một khuyết điểm ngoại hình nào mà hôm nay bạn sẵn lòng mỉm cười bao dung và chấp nhận nó như nét riêng của mình?\"}', 5, '2026-07-07 03:20:10', '2026-07-07 03:20:10'),
(6415, 1070, 'takeaway', '{\"items\": [\"Bạn là duy nhất trên thế giới này, hãy trân trọng sự độc bản đó như một món quà.\"]}', 6, '2026-07-07 03:20:10', '2026-07-07 03:20:10'),
(6416, 1071, 'hook', '{\"title\": \"Làm sao để duy trì sự tự tin ngoại hình vững vàng trước những biến động dư luận xung quanh?\"}', 1, '2026-07-07 03:20:11', '2026-07-07 03:20:11'),
(6417, 1071, 'explanation', '{\"bullets\": [\"Tự tin bền vững đến từ việc bạn thấu hiểu giá trị bên trong của mình và xây dựng thói quen chăm sóc sức khỏe khoa học.\", \"Tập trung vào những việc bạn kiểm soát được (chăm sóc vệ sinh, ăn uống đủ chất, rèn luyện kỹ năng) thay vì lo lắng về những việc ngoài tầm tay.\", \"Hãy bao dung và trò chuyện với chính mình bằng sự dịu dàng như cách bạn đối xử với người bạn thân yêu.\"]}', 2, '2026-07-07 03:20:11', '2026-07-07 03:20:11'),
(6418, 1071, 'scenario', '{\"title\": \"Tình huống tự thoại\", \"body\": \"Minh thi trượt cuộc thi hát của trường và bị một số bạn chê giọng khàn tai trâu. Minh buồn bã, nhưng tự nói với mình: \\\"Giọng mình đang dậy thì vỡ tiếng nên khàn chút là bình thường. Mình hát vì yêu thích âm nhạc, ý kiến chê bai không làm mình từ bỏ đam mê\\\".\"}', 3, '2026-07-07 03:20:11', '2026-07-07 03:20:11'),
(6419, 1071, 'interaction', '{\"question\": \"Cách tự đối thoại bằng lòng trắc ẩn của Minh giúp bạn ấy điều gì?\", \"choices\": [{\"text\": \"Bảo vệ lòng tự trọng tinh thần, xoa dịu nỗi buồn thất bại và tiếp tục kiên trì theo đuổi đam mê lành mạnh.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Khiến Minh tự mãn, ảo tưởng về giọng hát của mình và không chịu tiếp thu ý kiến đóng góp tiến bộ.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:20:11', '2026-07-07 03:20:11'),
(6420, 1071, 'reflection', '{\"question\": \"Bạn thường tự động viên bản thân bằng câu nói ấm áp nào mỗi khi gặp chuyện buồn lòng hoặc thất bại?\"}', 5, '2026-07-07 03:20:11', '2026-07-07 03:20:11'),
(6421, 1071, 'takeaway', '{\"items\": [\"Sự tự tin rực rỡ nhất là sự tự tin bắt nguồn từ lòng bao dung và trân trọng chính mình.\"]}', 6, '2026-07-07 03:20:11', '2026-07-07 03:20:11'),
(6422, 1072, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Ngoại hình & Thói quen lành mạnh\'! Cùng xây dựng hàng rào bảo vệ làn da mụn dậy thì và chấp nhận ngoại hình.\"}', 1, '2026-07-07 03:20:11', '2026-07-07 03:20:11'),
(6423, 1072, 'scenario-choice', '{\"title\": \"Skincare trị mụn trứng cá dậy thì\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Da mặt Vy nổi cơn lốc mụn trứng cá sưng đỏ trước thềm lễ bế giảng. Vy tự ti vô cùng và lên mạng tìm kiếm cách trị mụn cấp tốc.\", \"choices\": [{\"text\": \"Đặt mua hũ kem trộn trị mụn thần tốc 3 ngày được quảng cáo trên Facebook.\", \"nextNode\": \"fail_cream\"}, {\"text\": \"Tìm hiểu khoa học, nhận thấy mụn dậy thì do bã nhờn kết hợp vi khuẩn, cần chăm sóc da kiên trì.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Vy có một nốt mụn bọc sưng viêm lớn và đau nhức trên má. Bạn khuyên Vy dùng tay nặn nó ra ngay cho nhanh hết sưng.\", \"choices\": [{\"text\": \"Dùng hai đầu ngón tay chưa rửa sạch cố nặn thật mạnh nốt mụn bọc sưng đỏ.\", \"nextNode\": \"fail_squeeze\"}, {\"text\": \"Tuyệt đối không nặn, giữ da mặt sạch bằng sữa rửa mặt dịu nhẹ và chấm gel trị mụn chứa acid salicylic.\", \"nextNode\": \"step3\"}]}, \"step3\": {\"text\": \"Vy kiên trì skincare nhưng một tuần sau da Vy bỗng tróc vảy đỏ và nóng rát do thoa quá nhiều loại serum trị mụn cùng lúc.\", \"choices\": [{\"text\": \"Tiếp tục thoa đè các loại serum trị mụn liều mạnh để mụn mau xẹp.\", \"nextNode\": \"fail_overuse\"}, {\"text\": \"Tạm ngưng các serum đặc trị, chỉ duy trì sữa rửa mặt dịu nhẹ và kem dưỡng ẩm phục hồi da lành tính.\", \"nextNode\": \"step4\"}]}, \"step4\": {\"text\": \"Da mặt Vy đã bớt rát đỏ nhưng một số bạn cùng lớp xì xào chê da Vy nhiều sẹo thâm, khuyên Vy bôi kem đánh răng lên vết thâm mụn để làm trắng nhanh.\", \"choices\": [{\"text\": \"Bôi một lớp kem đánh răng dày lên các vết thâm mụn suốt cả đêm.\", \"nextNode\": \"fail_toothpaste\"}, {\"text\": \"Bôi kem chống nắng đầy đủ mỗi khi ra ngoài và kiên nhẫn để da tự phục hồi.\", \"nextNode\": \"step5\"}]}, \"step5\": {\"text\": \"Một người bạn khác mách Vy nên mua thuốc nam gia truyền rượu rễ cây để bôi lên mặt giúp \'thải độc da\' bong tróc mụn cũ tái tạo da mới láng mịn.\", \"choices\": [{\"text\": \"Bỏ qua lời khuyên phản khoa học, kiên trì chu trình dưỡng ẩm phục hồi đơn giản.\", \"nextNode\": \"success_end\"}, {\"text\": \"Mua rượu thuốc rễ cây bôi lên mặt chờ da sưng tấy bong tróc thải độc.\", \"nextNode\": \"fail_alcohol_skin\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã vượt qua bẫy kem trộn trị mụn cấp tốc, biết cách xử lý mụn bọc sưng viêm, phục hồi da và bảo vệ da an toàn.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_cream\": {\"text\": \"❌ Chưa đúng! Các loại kem trộn cấp tốc chứa corticoid làm tàn phá hàng rào bảo vệ da, gây teo da và nổi mụn bùng phát nhiễm trùng.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_squeeze\": {\"text\": \"❌ Chưa đúng! Tự nặn mụn bọc sưng viêm bằng tay bẩn làm đẩy vi khuẩn vào sâu trong da, gây nhiễm trùng huyết và sẹo rỗ vĩnh viễn.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_overuse\": {\"text\": \"❌ Sai rồi! Dùng quá nhiều chất đặc trị liều cao làm da bị quá tải, bỏng hóa chất nhẹ và suy yếu hàng rào bảo vệ da.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_toothpaste\": {\"text\": \"❌ Sai rồi! Florua và các chất làm trắng trong kem đánh răng cực kỳ kích ứng da mặt, gây bỏng rát nhẹ và làm thâm sẹo mụn đậm hơn.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_alcohol_skin\": {\"text\": \"❌ Sai rồi! Rượu thuốc tự chế phá hủy hoàn toàn hàng rào bảo vệ da, gây dị ứng nặng, bỏng cồn và sẹo rỗ nhiễm trùng nặng nề trên mặt.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-07 03:20:11', '2026-07-07 03:20:11'),
(6424, 1072, 'sorting', '{\"instruction\": \"Hãy phân loại các hành động ứng xử với làn da và ngoại hình sau:\", \"leftBox\": {\"title\": \"Nên làm (Skincare chuẩn)\"}, \"rightBox\": {\"title\": \"Tránh làm (Gây hại da)\"}, \"items\": [{\"text\": \"Rửa mặt sạch bằng nước ấm nhẹ nhàng\", \"correctBox\": \"left\"}, {\"text\": \"Nặn mụn bọc sưng đỏ bằng tay bẩn\", \"correctBox\": \"right\"}, {\"text\": \"Thoa kem chống nắng mỗi khi ra ngoài\", \"correctBox\": \"left\"}, {\"text\": \"Dùng kem trộn trị mụn cấp tốc 3 ngày\", \"correctBox\": \"right\"}, {\"text\": \"Ngưng đặc trị khi da bị rát đỏ, tróc vảy\", \"correctBox\": \"left\"}, {\"text\": \"Thoa kem đánh răng lên mụn cho mau xẹp\", \"correctBox\": \"right\"}, {\"text\": \"Sử dụng miếng dán hút mụn cho mụn có cồi chín\", \"correctBox\": \"left\"}, {\"text\": \"Thoa rượu thuốc rễ cây để bong tróc da mặt\", \"correctBox\": \"right\"}, {\"text\": \"Bao dung và dịu dàng với khuyết điểm cơ thể\", \"correctBox\": \"left\"}, {\"text\": \"Nhịn ăn bỏ bữa để ép cân theo tiêu chuẩn thần tượng\", \"correctBox\": \"right\"}]}', 3, '2026-07-07 03:20:11', '2026-07-07 03:20:11'),
(6425, 1072, 'matching', '{\"instruction\": \"Ghép cặp các khái niệm về nhận thức ngoại hình và skincare:\", \"pairs\": [{\"left\": \"Sữa rửa mặt dịu nhẹ\", \"right\": \"Sản phẩm làm sạch bã nhờn mà không gây khô da\"}, {\"left\": \"Nặn mụn bọc\", \"right\": \"Hành vi gây nhiễm trùng sâu và để lại sẹo rỗ\"}, {\"left\": \"Kem trộn\", \"right\": \"Sản phẩm chứa corticoid gây teo da và giãn mạch máu\"}, {\"left\": \"Kem chống nắng\", \"right\": \"Lớp màng bảo vệ da khỏi tia UV ngăn thâm mụn\"}, {\"left\": \"Bã nhờn\", \"right\": \"Chất dầu tự nhiên do tuyến bã nhờn tiết ra tuổi dậy thì\"}, {\"left\": \"Phục hồi da\", \"right\": \"Quá trình dưỡng ẩm đơn giản khi da bị kích ứng rát đỏ\"}, {\"left\": \"Corticoid\", \"right\": \"Dược chất gây nghiện da và bào mòn da trong kem trộn\"}, {\"left\": \"Lòng tự trắc ẩn\", \"right\": \"Thái độ chấp nhận và yêu thương cơ thể bất toàn của mình\"}]}', 4, '2026-07-07 03:20:11', '2026-07-07 03:20:11'),
(6426, 1072, 'fill-blank', '{\"instruction\": \"Đoạn 1: Điền từ thích hợp về nguyên nhân và cách chăm sóc mụn trứng cá:\", \"sentence\": \"Mụn trứng cá tuổi dậy thì hình thành do sự bùng nổ hormone kích thích tuyến [blank1] hoạt động mạnh gây tắc nghẽn lỗ chân lông. Để chăm sóc da mụn, bạn nên rửa mặt bằng sữa rửa mặt [blank2] tối đa 2 lần mỗi ngày. Tuyệt đối không tự ý [blank3] mụn bọc bằng tay bẩn vì dễ gây nhiễm trùng sâu và để lại sẹo rỗ. Tránh xa các loại [blank4] trị mụn cấp tốc chứa corticoid vì chúng tàn phá hàng rào bảo vệ da và gây [blank5] mạch máu.\", \"blanks\": {\"blank1\": {\"correct\": \"bã nhờn\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"dịu nhẹ\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"nặn\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"kem trộn\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"giãn\", \"placeholder\": \"...\"}}, \"words\": [\"bã nhờn\", \"dịu nhẹ\", \"nặn\", \"kem trộn\", \"giãn\", \"mồ hôi\", \"tẩy mạnh\", \"gãi\", \"thuốc bắc\", \"co\"]}', 5, '2026-07-07 03:20:11', '2026-07-07 03:20:11'),
(6427, 1072, 'fill-blank', '{\"instruction\": \"Đoạn 2: Điền từ thích hợp về cách vượt qua áp lực tự ti ngoại hình:\", \"sentence\": \"Áp lực đồng trang lứa và truyền thông thường khiến thanh thiếu niên cảm thấy [blank1] về vóc dáng của mình. Hãy nhớ rằng các hình ảnh trên mạng xã hội thường sử dụng [blank2] chỉnh sửa không thực tế. Thay vì khắt khe so sánh bản thân, hãy học cách đối xử với mình bằng sự [blank3]. Giá trị đích thực của một con người nằm ở phẩm chất bên trong, không nằm ở [blank4] hay lời chê bai ngoại hình từ người khác. Hãy tự tin làm chủ sự [blank5] độc bản của chính mình.\", \"blanks\": {\"blank1\": {\"correct\": \"tự ti\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"filter\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"dịu dàng\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"cân nặng\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"phát triển\", \"placeholder\": \"...\"}}, \"words\": [\"tự ti\", \"filter\", \"dịu dàng\", \"cân nặng\", \"phát triển\", \"tự hào\", \"máy ảnh\", \"nghiêm khắc\", \"chiều cao\", \"suy thoái\"]}', 6, '2026-07-07 03:20:11', '2026-07-07 03:20:11'),
(6428, 1072, 'interaction', '{\"question\": \"Khi da mặt nổi mụn bọc sưng viêm to và đau nhức, hành động nào sau đây là chuẩn y khoa nhất?\", \"choices\": [{\"text\": \"Không chạm tay lên mụn, giữ da sạch và dùng miếng dán hút mụn hoặc chấm gel trị mụn dịu nhẹ.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Dùng kim khọc nhân mụn ra rồi bôi cồn đỏ sát trùng trực tiếp lên vết thương.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 7, '2026-07-07 03:20:12', '2026-07-07 03:20:12'),
(6429, 1072, 'interaction', '{\"question\": \"Tại sao việc dùng kem đánh răng bôi lên nốt mụn trứng cá lại là cờ đỏ phản khoa học?\", \"choices\": [{\"text\": \"Vì chất florua và chất tẩy trong kem đánh răng làm bỏng rát và thâm đen vùng da bị mụn.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Vì kem đánh răng chứa tinh dầu bạc hà sẽ thu hút vi khuẩn gây mụn đến nhiều hơn.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 8, '2026-07-07 03:20:12', '2026-07-07 03:20:12'),
(6430, 1072, 'interaction', '{\"question\": \"Thói quen rửa mặt bằng sữa rửa mặt bao nhiêu lần mỗi ngày là phù hợp nhất cho làn da dậy thì?\", \"choices\": [{\"text\": \"Tối đa 2 lần mỗi ngày (sáng và tối) để làm sạch bã nhờn mà không làm mất đi độ ẩm tự nhiên của da.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Rửa mặt liên tục 5-6 lần mỗi ngày mỗi khi thấy mặt đổ dầu để giữ da khô thoáng tuyệt đối.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 9, '2026-07-07 03:20:12', '2026-07-07 03:20:12'),
(6431, 1072, 'interaction', '{\"question\": \"Chất độc hại nào thường có trong các hũ \'kem trộn\' trị mụn thần tốc gây teo da và nổi mụn bùng phát khi ngưng dùng?\", \"choices\": [{\"text\": \"Corticoid.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Acid Salicylic.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 10, '2026-07-07 03:20:12', '2026-07-07 03:20:12'),
(6432, 1072, 'interaction', '{\"question\": \"Thế nào là thái độ \'lòng tự trắc ẩn\' với ngoại hình dậy thì của bản thân?\", \"choices\": [{\"text\": \"Chấp nhận sự biến đổi tự nhiên của cơ thể và trò chuyện với bản thân bằng lời động viên nhẹ nhàng.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Ép buộc bản thân phải ăn kiêng nghiêm ngặt để có số đo cơ thể giống hệt các hình ảnh đã qua filter.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 11, '2026-07-07 03:20:12', '2026-07-07 03:20:12'),
(6433, 1073, 'hook', '{\"title\": \"Bạn có từng nghe những lời khuyên kỳ quặc về tuổi dậy thì khiến bạn nửa tin nửa ngờ?\"}', 1, '2026-07-07 03:20:12', '2026-07-07 03:20:12'),
(6434, 1073, 'explanation', '{\"bullets\": [\"Tuổi dậy thì là chủ đề nhạy cảm, dễ phát sinh nhiều tin đồn dân gian thiếu căn cứ khoa học do sự ngại ngùng chia sẻ.\", \"Ví dụ: Con trai cạo râu càng nhiều râu sẽ mọc càng cứng; con gái đến ngày kinh nguyệt thì không được ăn đồ chua.\", \"Việc tin vào những lầm tưởng này có thể gây lo âu vô cớ hoặc dẫn tới các hành vi chăm sóc cơ thể sai lệch, gây hại.\"]}', 2, '2026-07-07 03:20:12', '2026-07-07 03:20:12'),
(6435, 1073, 'scenario', '{\"title\": \"Tình huống kiêng ăn\", \"body\": \"Vy đến ngày đèn đỏ và thèm ăn một quả xoài chua. Bạn thân ngăn cản gay gắt: \\\"Ăn chua lúc này máu kinh sẽ bị đông cứng lại trong bụng gây ung thư đấy!\\\". Vy sợ hãi bỏ quả xoài đi dù rất thèm.\"}', 3, '2026-07-07 03:20:12', '2026-07-07 03:20:12'),
(6436, 1073, 'interaction', '{\"question\": \"Lời cảnh báo của bạn Vy có đúng cơ sở khoa học y khoa hay không?\", \"choices\": [{\"text\": \"Sai hoàn toàn! Ăn chua hay đồ ăn có vị chua không hề ảnh hưởng đến cơ chế đông máu hay co bóp tử cung trong kỳ kinh.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Đúng rồi, đồ chua có tính axit mạnh sẽ làm biến đổi cấu trúc máu kinh nguyệt bên trong cơ thể ngay lập tức.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:20:12', '2026-07-07 03:20:12'),
(6437, 1073, 'reflection', '{\"question\": \"Một lời khuyên kiêng cữ hay tin đồn tuổi dậy thì nào mà bạn từng nghe thấy vô lý nhất?\"}', 5, '2026-07-07 03:20:13', '2026-07-07 03:20:13'),
(6438, 1073, 'takeaway', '{\"items\": [\"Kiến thức khoa học là ánh sáng dập tắt nỗi sợ hãi từ những tin đồn truyền miệng vô căn cứ.\"]}', 6, '2026-07-07 03:20:13', '2026-07-07 03:20:13'),
(6439, 1074, 'hook', '{\"title\": \"Làm sao để tìm kiếm lời giải đáp cho những thắc mắc thầm kín về cơ thể giữa một rừng thông tin lộn xộn trên mạng?\"}', 1, '2026-07-07 03:20:13', '2026-07-07 03:20:13'),
(6440, 1074, 'explanation', '{\"bullets\": [\"Internet có rất nhiều thông tin hữu ích nhưng cũng đầy rẫy những nội dung sai lệch, giật gân hoặc quảng cáo sản phẩm độc hại.\", \"**Nguyên tắc tra cứu an toàn**: Ưu tiên tìm kiếm từ các nguồn chính thống (như WHO, UNICEF, các trang web bệnh viện uy tín, các bài viết của Scarleteen).\", \"Tránh tự chẩn đoán bệnh qua các bài chia sẻ giật gân không có kiểm chứng từ các tài khoản ẩn danh trên mạng xã hội.\"]}', 2, '2026-07-07 03:20:13', '2026-07-07 03:20:13'),
(6441, 1074, 'scenario', '{\"title\": \"Tình huống tra cứu\", \"body\": \"Khang thấy vùng kín mình nổi một nốt đỏ nhỏ. Khang lên Google tìm kiếm và đọc được bài viết cảnh báo: \\\"Nổi nốt đỏ là dấu hiệu của bệnh ung thư giai đoạn cuối\\\". Khang hoảng sợ mất ăn mất ngủ suốt 3 ngày.\"}', 3, '2026-07-07 03:20:13', '2026-07-07 03:20:13'),
(6442, 1074, 'interaction', '{\"question\": \"Sai lầm của Khang khi tự tra cứu thông tin sức khỏe trên mạng là gì?\", \"choices\": [{\"text\": \"Quá tin vào các bài viết giật gân câu view và tự chẩn đoán bệnh một cách vội vã gây stress nặng.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Khang tra cứu chưa đủ nhiều, đáng ra Khang nên vào các hội nhóm ẩn danh trên Facebook để hỏi ý kiến mọi người.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 03:20:13', '2026-07-07 03:20:13'),
(6443, 1074, 'reflection', '{\"question\": \"Bạn thường truy cập trang web hoặc nguồn thông tin nào mỗi khi có thắc mắc thầm kín về sức khỏe?\"}', 5, '2026-07-07 03:20:13', '2026-07-07 03:20:13'),
(6444, 1074, 'takeaway', '{\"items\": [\"Google có thể cung cấp hàng triệu câu trả lời, nhưng chỉ có chuyên gia y tế mới cho bạn giải pháp chính xác nhất.\"]}', 6, '2026-07-07 03:20:13', '2026-07-07 03:20:13'),
(6445, 1075, 'hook', '{\"title\": \"Tại sao việc mở lời hỏi bố mẹ về những thay đổi nhạy cảm trên cơ thể lại khó khăn như leo một ngọn núi?\"}', 1, '2026-07-07 03:20:13', '2026-07-07 03:20:13'),
(6446, 1075, 'explanation', '{\"bullets\": [\"Sự ngại ngùng, sợ bị đánh giá hay trêu chọc là rào cản tâm lý phổ biến khiến teen khép kín trước người thân.\", \"Thực tế: Bố mẹ hay người lớn đều đã từng đi qua tuổi dậy thì và họ hoàn toàn thấu hiểu những bỡ ngỡ của bạn.\", \"Chủ động mở lời bằng những câu hỏi đơn giản, trực diện sẽ giúp phá vỡ bầu không khí gượng gạo ban đầu.\"]}', 2, '2026-07-07 03:20:14', '2026-07-07 03:20:14'),
(6447, 1075, 'scenario', '{\"title\": \"Tình huống khó nói\", \"body\": \"Nam bắt đầu mọc nhiều mụn trứng cá viêm đau trên mặt. Nam muốn xin mẹ mua sữa rửa mặt trị mụn nhưng cứ chần chừ, đứng trước cửa phòng mẹ mãi mà không dám gõ cửa mở lời vì ngại.\"}', 3, '2026-07-07 03:20:14', '2026-07-07 03:20:14'),
(6448, 1075, 'interaction', '{\"question\": \"Cách mở lời tự nhiên và hiệu quả nhất giúp Nam vượt qua sự bối rối là gì?\", \"choices\": [{\"text\": \"Mở lời trực tiếp: \'Mẹ ơi, dạo này mặt con nổi nhiều mụn viêm đau quá. Mẹ hướng dẫn con cách chăm sóc da hoặc dẫn con đi khám da liễu nhé!\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Nhờ em trai sang nói hộ hoặc tự lấy tiền tiết kiệm mua kem trộn trị mụn trên mạng dùng thử.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:20:14', '2026-07-07 03:20:14'),
(6449, 1075, 'reflection', '{\"question\": \"Bạn đã bao giờ chủ động trò chuyện với bố hoặc mẹ về một thay đổi cơ thể nào chưa? Cảm giác của bạn lúc đó thế nào?\"}', 5, '2026-07-07 03:20:14', '2026-07-07 03:20:14'),
(6450, 1075, 'takeaway', '{\"items\": [\"Bố mẹ chính là đồng minh lớn nhất sẵn sàng bảo vệ và chăm sóc bạn trên hành trình trưởng thành.\"]}', 6, '2026-07-07 03:20:14', '2026-07-07 03:20:14'),
(6451, 1076, 'hook', '{\"title\": \"Bạn có muốn thiết kế một tấm khiên tự chăm sóc (Self-care plan) độc bản để bảo vệ sức khỏe thể chất lẫn tinh thần của mình?\"}', 1, '2026-07-07 03:20:14', '2026-07-07 03:20:14'),
(6452, 1076, 'explanation', '{\"bullets\": [\"Bản kế hoạch tự chăm sóc là tập hợp các thói quen lành mạnh hàng ngày được thiết kế phù hợp với nhịp sinh học của riêng bạn.\", \"Thói quen lành mạnh gồm: ngủ đủ 8-9 tiếng, ăn uống cân bằng đủ chất, vận động 30 phút và dành thời gian thư giãn đầu óc không màn hình điện thoại.\", \"Một kế hoạch cụ thể giúp bạn duy trì năng lượng tích cực ổn định và giảm thiểu tối đa stress áp lực học đường.\"]}', 2, '2026-07-07 03:20:14', '2026-07-07 03:20:14'),
(6453, 1076, 'scenario', '{\"title\": \"Tình huống kiệt sức\", \"body\": \"Mai cảm thấy kiệt sức, đầu óc quay cuồng và luôn thấy buồn nôn trước kỳ thi học kỳ do nhịn ăn tối và thức đêm học bài liên tục suốt 1 tuần.\"}', 3, '2026-07-07 03:20:14', '2026-07-07 03:20:14'),
(6454, 1076, 'interaction', '{\"question\": \"Mai nên điều chỉnh lối sống của mình như thế nào trong bản kế hoạch tự chăm sóc bản thân?\", \"choices\": [{\"text\": \"Sắp xếp thời gian biểu học tập khoa học, đi ngủ trước 11h đêm, ăn uống đủ bữa và dành 15 phút đi bộ thư giãn nạp lại năng lượng.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tiếp tục cố gắng gồng mình học bài xuyên đêm, uống thêm cà phê đậm đặc để ép bộ não hoạt động công suất cao.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:20:14', '2026-07-07 03:20:14'),
(6455, 1076, 'reflection', '{\"question\": \"Một thói quen tự chăm sóc bản thân nào mà bạn sẵn lòng thực hiện ngay từ ngày hôm nay để nâng cao sức khỏe?\"}', 5, '2026-07-07 03:20:14', '2026-07-07 03:20:14'),
(6456, 1076, 'takeaway', '{\"items\": [\"Tự chăm sóc bản thân không phải là ích kỷ, đó là trách nhiệm đầu tiên của bạn với chính cuộc đời mình.\"]}', 6, '2026-07-07 03:20:14', '2026-07-07 03:20:14'),
(6457, 1077, 'hook', '{\"title\": \"Làm sao để nhận biết cơ thể bạn đang phát đi những tín hiệu SOS cầu cứu khẩn cấp?\"}', 1, '2026-07-07 03:20:14', '2026-07-07 03:20:14'),
(6458, 1077, 'explanation', '{\"bullets\": [\"Cơ thể luôn giao tiếp với bạn qua các biểu hiện vật lý: đau đầu, rụng tóc nhiều, mệt mỏi kéo dài, đau quặn bụng dưới hay tâm trạng u uất trốn tránh giao tiếp.\", \"Đừng bao giờ phớt lờ hay coi nhẹ những tín hiệu này; chúng là tiếng kêu cứu cho thấy hệ thống sinh học bên trong đang bị quá tải hoặc gặp trục trặc.\", \"Chủ động tìm kiếm sự trợ giúp y tế hoặc tư vấn tâm lý đúng lúc là hành động dũng cảm tự chịu trách nhiệm với bản thân.\"]}', 2, '2026-07-07 03:20:14', '2026-07-07 03:20:14'),
(6459, 1077, 'scenario', '{\"title\": \"Tình huống SOS\", \"body\": \"Vy phát hiện vùng kín của mình bị ngứa rát dữ dội, khí hư ra nhiều có mùi hôi và đi tiểu buốt liên tục suốt 5 ngày nay. Vy sợ hãi giấu kín, không dám nói với ai vì nghĩ mình mắc bệnh xấu xa.\"}', 3, '2026-07-07 03:20:14', '2026-07-07 03:20:14'),
(6460, 1077, 'interaction', '{\"question\": \"Vy nên hành động như thế nào trước những tín hiệu kêu cứu này của cơ thể?\", \"choices\": [{\"text\": \"Vượt qua sự ngượng ngùng, chia sẻ thật lòng với mẹ để được đưa đi khám bác sĩ phụ sản khoa sớm để điều trị.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tiếp tục im lặng chịu đựng, tự mua các loại nước lá về ngâm rửa theo mẹo truyền miệng trên mạng xã hội.\", \"correct\": false, \"emoji\": \"😐\"}]}', 4, '2026-07-07 03:20:15', '2026-07-07 03:20:15'),
(6461, 1077, 'reflection', '{\"question\": \"Bạn có đang phớt lờ một cơn đau hay tín hiệu mệt mỏi bất thường nào trên cơ thể mình dạo gần đây không?\"}', 5, '2026-07-07 03:20:15', '2026-07-07 03:20:15'),
(6462, 1077, 'takeaway', '{\"items\": [\"Lắng nghe cơ thể kêu cứu và đi khám y khoa kịp thời là biểu hiện cao nhất của sự trưởng thành.\"]}', 6, '2026-07-07 03:20:15', '2026-07-07 03:20:15'),
(6463, 1078, 'hook', '{\"title\": \"Bạn đã sẵn sàng bước tiếp trên hành trình trưởng thành đầy thú vị với một cơ thể khỏe mạnh và tâm hồn tự tin chưa?\"}', 1, '2026-07-07 03:20:15', '2026-07-07 03:20:15'),
(6464, 1078, 'explanation', '{\"bullets\": [\"Tuổi dậy thì là cánh cửa mở ra một chương mới đầy sắc màu và thử thách trong cuộc đời của bạn.\", \"Đi qua những bỡ ngỡ, lúng túng ban đầu, bạn sẽ dần làm chủ được những thay đổi sinh học và xây dựng bản sắc cá nhân vững chắc.\", \"Hãy luôn duy trì sự tò mò khoa học, trân trọng bản thân và đối xử tử tế bao dung với cơ thể độc bản của mình.\"]}', 2, '2026-07-07 03:20:15', '2026-07-07 03:20:15'),
(6465, 1078, 'scenario', '{\"title\": \"Tình huống trưởng thành\", \"body\": \"Đức nhìn lại hành trình 1 năm dậy thì của mình: từ một cậu bé thấp còi, hay e thẹn ngượng ngùng nay đã cao lớn khỏe mạnh, tự tin tham gia câu lạc bộ ghi-ta trường và biết tự cạo râu vệ sinh sạch sẽ. Đức thấy tự hào về bản thân.\"}', 3, '2026-07-07 03:20:15', '2026-07-07 03:20:15'),
(6466, 1078, 'interaction', '{\"question\": \"Sự tự hào và tự tin của Đức có được nhờ yếu tố cốt lõi nào?\", \"choices\": [{\"text\": \"Nhờ sự kiên nhẫn lắng nghe cơ thể, trang bị kiến thức khoa học và chủ động học tập thói quen lành mạnh.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Nhờ may mắn tự nhiên lớn lên mà không cần phải quan tâm chăm sóc hay học hỏi bất kỳ kỹ năng nào.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 03:20:15', '2026-07-07 03:20:15'),
(6467, 1078, 'reflection', '{\"question\": \"Một mục tiêu lớn nhất nào về sức khỏe hay sự phát triển bản thân mà bạn muốn đặt ra cho mình trong năm nay?\"}', 5, '2026-07-07 03:20:15', '2026-07-07 03:20:15'),
(6468, 1078, 'takeaway', '{\"items\": [\"Trưởng thành là một đặc ân, hãy bước đi trên hành trình đó với cái đầu ngẩng cao và lòng trắc ẩn ấm áp.\"]}', 6, '2026-07-07 03:20:15', '2026-07-07 03:20:15'),
(6469, 1079, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Giải mã lầm tưởng & Chăm sóc bản thân\'! Hãy hoàn thành chặng cuối để gạt bỏ tin đồn nhảm học đường.\"}', 1, '2026-07-07 03:20:15', '2026-07-07 03:20:15'),
(6470, 1079, 'scenario-choice', '{\"title\": \"Tự bảo vệ sức khỏe và gạt bỏ lầm tưởng\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Khánh nghe các bạn rỉ tai nhau rằng hành vi tự khám phá cơ thể (thủ dâm) sẽ làm suy giảm trí nhớ, hỏng thận và gây vô sinh nam. Khánh hoang mang.\", \"choices\": [{\"text\": \"Âm thầm mua các loại thuốc bổ thận tráng dương trên mạng về tự uống để cứu vãn sức khỏe.\", \"nextNode\": \"fail_pills\"}, {\"text\": \"Tìm kiếm thông tin khoa học tại các nguồn kiểm chứng uy tín để hiểu đúng bản chất vấn đề.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Khánh hiểu ra thủ dâm là bình thường, nhưng lo sợ khi phát hiện vùng kín của mình bị ngứa ngáy và mẩn đỏ sau khi thực hiện hành vi đó.\", \"choices\": [{\"text\": \"Sử dụng xà phòng giặt hoặc sữa tắm hương liệu mạnh để chà rửa thật kỹ cho sạch vi khuẩn.\", \"nextNode\": \"fail_wash\"}, {\"text\": \"Vệ sinh vùng nhạy cảm bằng nước ấm sạch, lau khô bằng khăn mềm thoáng mát và mặc đồ lót cotton sạch.\", \"nextNode\": \"step3\"}]}, \"step3\": {\"text\": \"Vùng nhạy cảm của Khánh tiếp tục ngứa rát dữ dội và nổi vài mụn nước nhỏ. Khánh thấy rất ngượng ngùng, xấu hổ không biết nói với ai.\", \"choices\": [{\"text\": \"Giấu kín bệnh tình vì sợ bị coi là hư hỏng, tự tìm các bài thuốc lá truyền miệng đắp lên nốt mụn nước.\", \"nextNode\": \"fail_shame\"}, {\"text\": \"Vượt qua sự ngượng ngùng, chia sẻ thẳng thắn với bố mẹ hoặc bác sĩ y tế học đường để được đi khám da liễu kịp thời.\", \"nextNode\": \"step4\"}]}, \"step4\": {\"text\": \"Khánh được bác sĩ kết luận bị viêm da tiếp xúc và kê đơn kem bôi. Trên đường về, Khánh gặp một bài đăng Facebook của tài khoản ẩn danh chia sẻ rằng thuốc bôi tây y chứa độc, khuyên đắp lá nha đam tự nhiên tốt hơn.\", \"choices\": [{\"text\": \"Tự ý đắp lá nha đam chưa qua tiệt trùng trực tiếp lên các mụn nước vùng kín.\", \"nextNode\": \"fail_aloe\"}, {\"text\": \"Tuân thủ bôi thuốc đúng liều lượng chỉ dẫn của bác sĩ chuyên khoa da liễu.\", \"nextNode\": \"step5\"}]}, \"step5\": {\"text\": \"Khánh lo lắng không biết làm thế nào để xây dựng lại một lối sống lành mạnh, cân bằng để cải thiện sức khỏe toàn diện sau đợt viêm nhiễm này.\", \"choices\": [{\"text\": \"Lập kế hoạch Self-care cân đối ăn uống, ngủ trước 11 giờ đêm và chơi thể thao.\", \"nextNode\": \"success_end\"}, {\"text\": \"Lên mạng tìm mua các thực phẩm chức năng thải độc cơ thể siêu tốc 7 ngày.\", \"nextNode\": \"fail_detox\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã gạt bỏ nỗi sợ hãi vô lý từ tin đồn nhảm, thực hành vệ sinh an toàn, tuân thủ điều trị y khoa và thiết lập lối sống Self-care.\", \"isEnd\": true, \"isSuccess\": true}, \"fail_pills\": {\"text\": \"❌ Chưa đúng! Sử dụng thuốc bổ thận tráng dương trôi nổi cực kỳ hại gan thận của tuổi dậy thì và không giải quyết được lo âu tâm lý.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_wash\": {\"text\": \"❌ Chưa đúng! Chà rửa bằng xà phòng tẩy rửa mạnh làm rách niêm mạc da mỏng vùng kín, gây viêm nhiễm da tiếp xúc nặng.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_shame\": {\"text\": \"❌ Sai rồi! Các bệnh lý da liễu vùng kín nếu không khám y khoa sớm có thể chuyển biến nặng thành nhiễm trùng lan rộng nguy hiểm.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_aloe\": {\"text\": \"❌ Sai rồi! Nhựa nha đam tươi chứa chất gây ngứa mạnh và đắp lá bẩn trực tiếp lên vết thương hở vùng kín gây nhiễm trùng sâu cực kỳ nguy hại.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_detox\": {\"text\": \"❌ Sai rồi! Các sản phẩm thải độc siêu tốc không có căn cứ khoa học, dễ gây tiêu chảy và mất nước, làm suy kiệt cơ thể dậy thì.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-07 03:20:15', '2026-07-07 03:20:15'),
(6471, 1079, 'sorting', '{\"instruction\": \"Hãy phân loại các nguồn thông tin và hành vi ứng xử với sức khỏe dậy thì:\", \"leftBox\": {\"title\": \"Nguồn tin cậy / Lành mạnh\"}, \"rightBox\": {\"title\": \"Tin đồn / Có hại\"}, \"items\": [{\"text\": \"Trang thông tin y tế của WHO hoặc UNICEF\", \"correctBox\": \"left\"}, {\"text\": \"Bài chia sẻ của tài khoản TikTok ẩn danh quảng cáo thuốc\", \"correctBox\": \"right\"}, {\"text\": \"Website y khoa của bệnh viện lớn chính thống\", \"correctBox\": \"left\"}, {\"text\": \"Uống thuốc bổ thận để chữa lo âu do thủ dâm\", \"correctBox\": \"right\"}, {\"text\": \"Hỏi ý kiến bác sĩ chuyên khoa hoặc giáo viên y tế trường\", \"correctBox\": \"left\"}, {\"text\": \"Dùng xà phòng giặt đồ chà rửa để khử trùng vùng kín\", \"correctBox\": \"right\"}, {\"text\": \"Tuân thủ đơn thuốc bôi của bác sĩ da liễu\", \"correctBox\": \"left\"}, {\"text\": \"Đắp lá nha đam tươi trực tiếp lên mụn nước vùng kín\", \"correctBox\": \"right\"}, {\"text\": \"Xây dựng thời gian biểu cân bằng học tập và nghỉ ngơi\", \"correctBox\": \"left\"}, {\"text\": \"Uống nước ép thải độc detox cấp tốc thay bữa ăn chính\", \"correctBox\": \"right\"}]}', 3, '2026-07-07 03:20:16', '2026-07-07 03:20:16'),
(6472, 1079, 'matching', '{\"instruction\": \"Ghép cặp các phương pháp chăm sóc bản thân lành mạnh với bản chất tương ứng:\", \"pairs\": [{\"left\": \"Thủ dâm\", \"right\": \"Hành vi sinh lý bình thường nếu điều độ và kín đáo\"}, {\"left\": \"Khám da liễu\", \"right\": \"Giải pháp cần làm khi vùng kín nổi mụn nước ngứa rát\"}, {\"left\": \"WHO / UNICEF\", \"right\": \"Các tổ chức y tế và trẻ em uy tín toàn cầu\"}, {\"left\": \"Dung dịch vệ sinh\", \"right\": \"Nước rửa chuyên dụng dịu nhẹ có độ pH phù hợp\"}, {\"left\": \"Khí hư bất thường\", \"right\": \"Tín hiệu cảnh báo viêm nhiễm phụ khoa ở bạn gái\"}, {\"left\": \"Lập Self-care plan\", \"right\": \"Kế hoạch cân bằng học tập, giấc ngủ và thể thao\"}, {\"left\": \"Rượu thuốc rễ cây\", \"right\": \"Bài thuốc phản khoa học gây bỏng da mặt nghiêm trọng\"}, {\"left\": \"Nhiễm trùng ngược dòng\", \"right\": \"Nguy cơ khi để băng vệ sinh ẩm ướt quá 4 tiếng\"}]}', 4, '2026-07-07 03:20:16', '2026-07-07 03:20:16'),
(6473, 1079, 'fill-blank', '{\"instruction\": \"Đoạn 1: Điền từ thích hợp về sự thật khoa học của hành vi tự khám phá cơ thể:\", \"sentence\": \"Thủ dâm hay hành vi tự khám phá cơ thể là một hoạt động sinh lý [blank1] của tuổi dậy thì khi nhu cầu sinh lý tăng cao. Khoa học chứng minh hành vi này không gây vô sinh hay [blank2] như các tin đồn nhảm truyền tai. Tuy nhiên, bạn cần thực hiện điều độ, kín đáo và đảm bảo vệ sinh [blank3] trước và sau khi thực hiện. Nếu vùng kín có dấu hiệu nổi [blank4] nước hoặc ngứa rát kéo dài, bạn cần vượt qua xấu hổ để đi khám [blank5] ngay.\", \"blanks\": {\"blank1\": {\"correct\": \"bình thường\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"hỏng thận\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"bàn tay\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"mụn\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"da liễu\", \"placeholder\": \"...\"}}, \"words\": [\"bình thường\", \"hỏng thận\", \"bàn tay\", \"mụn\", \"da liễu\", \"dị thường\", \"yếu sinh lý\", \"dụng cụ\", \"mẩn\", \"nam khoa\"]}', 5, '2026-07-07 03:20:16', '2026-07-07 03:20:16'),
(6474, 1079, 'fill-blank', '{\"instruction\": \"Đoạn 2: Điền từ thích hợp về kỹ năng tìm kiếm nguồn thông tin y khoa đáng tin cậy:\", \"sentence\": \"Khi gặp các vấn đề sức khỏe khó nói, bạn trẻ thường có xu hướng tra cứu thông tin trên [blank1]. Hãy cẩn thận trước các tài khoản mạng xã hội [blank2] chia sẻ mẹo vặt y khoa phản khoa học để bán thuốc. Hãy ưu tiên các nguồn tin chính thống từ các bệnh viện lớn hoặc tổ chức y tế như [blank3]. Việc lập một kế hoạch [blank4] cân bằng giữa học tập, ngủ nghỉ và thể thao là chìa khóa vàng bảo vệ sức khỏe. Đừng [blank5] các tín hiệu cảnh báo mỏi mệt của cơ thể.\", \"blanks\": {\"blank1\": {\"correct\": \"internet\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"ẩn danh\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"WHO\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"self-care\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"phớt lờ\", \"placeholder\": \"...\"}}, \"words\": [\"internet\", \"ẩn danh\", \"WHO\", \"self-care\", \"phớt lờ\", \"sách vở\", \"bác sĩ\", \"UNICEF\", \"học tập\", \"chăm sóc\"]}', 6, '2026-07-07 03:20:16', '2026-07-07 03:20:16'),
(6475, 1079, 'interaction', '{\"question\": \"Khi vùng nhạy cảm nổi các nốt mụn lạ hoặc ngứa rát dữ dội kéo dài, thái độ nào là khoa học và an toàn nhất?\", \"choices\": [{\"text\": \"Chủ động chia sẻ với bố mẹ và đi khám chuyên khoa da liễu hoặc sản phụ khoa sớm.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Mua kem bôi chứa corticoid liều mạnh ngoài tiệm thuốc tự thoa lên vết ngứa rát.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 7, '2026-07-07 03:20:16', '2026-07-07 03:20:16'),
(6476, 1079, 'interaction', '{\"question\": \"Đâu là sự thật khoa học về hành vi tự khám phá cơ thể (thủ dâm) ở tuổi dậy thì?\", \"choices\": [{\"text\": \"Là hành vi sinh lý bình thường, không gây hại cho sức khỏe nếu điều độ và kín đáo.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Là cờ đỏ nguy hiểm gây teo não, vô sinh và suy nhược cơ thể vĩnh viễn.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 8, '2026-07-07 03:20:16', '2026-07-07 03:20:16'),
(6477, 1079, 'interaction', '{\"question\": \"Tại sao việc thụt rửa sâu vào trong âm đạo của bạn gái lại bị các bác sĩ sản phụ khoa cấm tuyệt đối?\", \"choices\": [{\"text\": \"Vì nó tàn phá hệ vi sinh vật có lợi Lactobacillus và làm thay đổi độ pH tự nhiên, gây viêm nhiễm.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Vì nước rửa sẽ tràn vào dạ dày gây ngộ độc đường tiêu hóa bên trong.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 9, '2026-07-07 03:20:16', '2026-07-07 03:20:16'),
(6478, 1079, 'interaction', '{\"question\": \"Tự đắp các loại lá tươi hoặc nha đam tươi trực tiếp lên các nốt mụn ngứa ở cơ quan sinh dục có thể gây ra tai họa gì?\", \"choices\": [{\"text\": \"Gây dị ứng da nghiêm trọng, bỏng nhựa thực vật và nhiễm trùng loét sâu nguy hiểm.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Ngay lập tức gây vô sinh thứ phát ở cả bạn nam và bạn nữ dậy thì.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 10, '2026-07-07 03:20:16', '2026-07-07 03:20:16'),
(6479, 1079, 'interaction', '{\"question\": \"Đâu là bản chất thực sự của các loại thuốc/trà có nhãn \'Thải độc cơ thể detox cấp tốc trong 7 ngày\'?\", \"choices\": [{\"text\": \"Hầu hết là quảng cáo quá lời không có kiểm chứng y khoa, có thể gây mất nước, tiêu chảy hoặc tổn hại dạ dày.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Giải pháp khoa học tiên tiến giúp loại bỏ 100% độc tố và tăng chiều cao tối đa.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 11, '2026-07-07 03:20:16', '2026-07-07 03:20:16'),
(6851, 1136, 'hook', '{\"title\": \"Giao tiếp có phải chỉ là nói cho sướng mồm?\"}', 1, '2026-07-07 05:53:40', '2026-07-07 05:53:40'),
(6852, 1136, 'explanation', '{\"bullets\": [\"Giao tiếp không chỉ là phát ra âm thanh, mà là cách chúng ta kết nối tâm hồn.\", \"Nhiều lúc tụi mình cứ nghĩ nói nhiều là giỏi, nhưng thực chất lắng nghe mới là đỉnh chóp.\", \"Giao tiếp lành mạnh giúp xây dựng lòng tin và làm mối quan hệ bền vững hơn.\"]}', 2, '2026-07-07 05:53:40', '2026-07-07 05:53:40'),
(6853, 1136, 'scenario', '{\"title\": \"Tình huống bất ổn\", \"body\": \"Vy đang cố kể cho Nam nghe về điểm số tệ hại của mình, nhưng Nam chỉ cắm mặt vào điện thoại và ừ hử cho qua chuyện.\"}', 3, '2026-07-07 05:53:40', '2026-07-07 05:53:40'),
(6854, 1136, 'interaction', '{\"question\": \"Nếu là Vy, bạn sẽ làm gì để bày tỏ cảm xúc lúc này?\", \"choices\": [{\"text\": \"Bực bội bỏ đi và im lặng suốt cả tuần để Nam tự biết lỗi.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Nhẹ nhàng bảo Nam cất điện thoại đi và lắng nghe mình một chút.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:40', '2026-07-07 05:53:40'),
(6855, 1136, 'reflection', '{\"question\": \"Bạn có từng cảm thấy bị phớt lờ khi đang chia sẻ câu chuyện của mình không?\"}', 5, '2026-07-07 05:53:40', '2026-07-07 05:53:40'),
(6856, 1136, 'takeaway', '{\"items\": [\"Giao tiếp bắt đầu từ việc tôn trọng và hiện diện cùng nhau.\"]}', 6, '2026-07-07 05:53:40', '2026-07-07 05:53:40'),
(6857, 1137, 'hook', '{\"title\": \"Làm sao biết cuộc trò chuyện của hai bạn là \\\"healthy\\\"?\"}', 1, '2026-07-07 05:53:41', '2026-07-07 05:53:41'),
(6858, 1137, 'explanation', '{\"bullets\": [\"\\\"Cờ xanh\\\" là những dấu hiệu cho thấy cuộc giao tiếp mang lại sự an toàn và tôn trọng.\", \"Cả hai đều được nói, được lắng nghe và không ai áp đặt ai.\", \"Cảm thấy nhẹ lòng và thoải mái sau khi nói chuyện là tín hiệu cực tốt.\"]}', 2, '2026-07-07 05:53:41', '2026-07-07 05:53:41'),
(6859, 1137, 'scenario', '{\"title\": \"Tình huống tích cực\", \"body\": \"Khi Minh kể về sở thích anime có phần kỳ lạ của mình, Hoa không cười cợt mà tò mò hỏi thêm về nhân vật Minh thích.\"}', 3, '2026-07-07 05:53:41', '2026-07-07 05:53:41'),
(6860, 1137, 'interaction', '{\"question\": \"Hành động nào của Hoa thể hiện \\\"cờ xanh\\\" rõ nhất?\", \"choices\": [{\"text\": \"Hoa lập tức chuyển chủ đề sang sở thích của mình.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Hoa lắng nghe với thái độ cởi mở và tôn trọng sự khác biệt.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:41', '2026-07-07 05:53:41'),
(6861, 1137, 'reflection', '{\"question\": \"Mối quan hệ nào hiện tại mang lại cho bạn cảm giác an toàn nhất khi trò chuyện?\"}', 5, '2026-07-07 05:53:41', '2026-07-07 05:53:41'),
(6862, 1137, 'takeaway', '{\"items\": [\"Giao tiếp lành mạnh khiến bạn cảm thấy được tôn trọng vì là chính mình.\"]}', 6, '2026-07-07 05:53:41', '2026-07-07 05:53:41'),
(6863, 1138, 'hook', '{\"title\": \"Tại sao việc nói ra suy nghĩ thật lòng lại khó đến vậy?\"}', 1, '2026-07-07 05:53:41', '2026-07-07 05:53:41'),
(6864, 1138, 'explanation', '{\"bullets\": [\"Tụi mình thường sợ bị từ chối, sợ làm người khác buồn hoặc bị đánh giá.\", \"Nỗi sợ này khiến chúng ta chọn cách im lặng hoặc nói dối lòng mình.\", \"Nhưng giữ mọi thứ trong lòng chỉ làm tích tụ ấm ức và hiểu lầm.\"]}', 2, '2026-07-07 05:53:41', '2026-07-07 05:53:41'),
(6865, 1138, 'scenario', '{\"title\": \"Tình huống khó xử\", \"body\": \"Linh không thích đi xem phim kinh dị nhưng nhóm bạn thân lại rủ đi. Linh sợ từ chối sẽ bị coi là kẻ phá bĩnh.\"}', 3, '2026-07-07 05:53:41', '2026-07-07 05:53:41'),
(6866, 1138, 'interaction', '{\"question\": \"Linh nên làm gì để vừa thật lòng vừa giữ hòa khí?\", \"choices\": [{\"text\": \"Cứ đi xem rồi chịu đựng nỗi sợ hãi suốt buổi chiếu.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Thẳng thắn chia sẻ là mình không hợp phim kinh dị và hẹn các bạn ở quán nước sau đó.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:41', '2026-07-07 05:53:41'),
(6867, 1138, 'reflection', '{\"question\": \"Bạn từng gật đầu đồng ý một việc chỉ vì sợ bị ghét chưa?\"}', 5, '2026-07-07 05:53:41', '2026-07-07 05:53:41'),
(6868, 1138, 'takeaway', '{\"items\": [\"Nói thật cần dũng khí, nhưng nó bảo vệ năng lượng và cảm xúc của bạn.\"]}', 6, '2026-07-07 05:53:41', '2026-07-07 05:53:41'),
(6869, 1139, 'hook', '{\"title\": \"Đọc vị một tin nhắn không icon thế nào cho đúng?\"}', 1, '2026-07-07 05:53:42', '2026-07-07 05:53:42'),
(6870, 1139, 'explanation', '{\"bullets\": [\"Giao tiếp qua tin nhắn thường thiếu đi giọng điệu và nét mặt, rất dễ gây hiểu lầm.\", \"Một chữ \\\"Ừ\\\" cụt lủn có thể làm đối phương mất ngủ cả đêm để suy diễn.\", \"Đừng vội suy diễn tiêu cực khi chưa xác nhận lại thông tin rõ ràng.\"]}', 2, '2026-07-07 05:53:42', '2026-07-07 05:53:42'),
(6871, 1139, 'scenario', '{\"title\": \"Tình huống hiểu lầm\", \"body\": \"Vy nhắn tin kể chuyện vui cho Nam nhưng Nam chỉ trả lời: \\\"Ừ thế à\\\". Vy lập tức nghĩ Nam đang giận mình.\"}', 3, '2026-07-07 05:53:42', '2026-07-07 05:53:42'),
(6872, 1139, 'interaction', '{\"question\": \"Vy nên phản ứng thế nào là khôn ngoan nhất?\", \"choices\": [{\"text\": \"Nhắn tin chất vấn dồn dập hỏi Nam vì sao thái độ lạnh nhạt.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Chờ hôm sau gặp trực tiếp hoặc gọi điện hỏi han nhẹ nhàng xem Nam có mệt không.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:42', '2026-07-07 05:53:42'),
(6873, 1139, 'reflection', '{\"question\": \"Bạn từng giận dỗi ai đó chỉ vì hiểu lầm nội dung tin nhắn chat chưa?\"}', 5, '2026-07-07 05:53:42', '2026-07-07 05:53:42'),
(6874, 1139, 'takeaway', '{\"items\": [\"Tin nhắn chữ không nói lên toàn bộ cảm xúc, hãy hỏi lại trước khi suy diễn.\"]}', 6, '2026-07-07 05:53:42', '2026-07-07 05:53:42'),
(6875, 1140, 'hook', '{\"title\": \"Làm thế nào để khởi động một cuộc trò chuyện chất lượng?\"}', 1, '2026-07-07 05:53:42', '2026-07-07 05:53:42'),
(6876, 1140, 'explanation', '{\"bullets\": [\"Hãy chọn thời điểm cả hai đều thoải mái, không bận rộn hay mệt mỏi.\", \"Bắt đầu bằng thái độ cầu thị, muốn lắng nghe thay vì muốn phân bua.\", \"Giao tiếp mắt và gật đầu nhẹ để thể hiện bạn đang hoàn toàn hiện diện.\"]}', 2, '2026-07-07 05:53:42', '2026-07-07 05:53:42'),
(6877, 1140, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Tuấn muốn nói chuyện với bố về việc chọn khối học, nhưng bố vừa đi làm về trông rất mệt mỏi và đang xem tivi.\"}', 3, '2026-07-07 05:53:42', '2026-07-07 05:53:42'),
(6878, 1140, 'interaction', '{\"question\": \"Tuấn nên bắt đầu cuộc nói chuyện khi nào?\", \"choices\": [{\"text\": \"Lập tức vào đề ngay vì chuyện này rất quan trọng với Tuấn.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Đợi bố nghỉ ngơi ăn tối xong, hỏi xem bố có rảnh không rồi mới xin phép trò chuyện.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:42', '2026-07-07 05:53:42'),
(6879, 1140, 'reflection', '{\"question\": \"Bạn thường chọn cách nào để mở lời khi muốn nói chuyện nghiêm túc với ai đó?\"}', 5, '2026-07-07 05:53:42', '2026-07-07 05:53:42'),
(6880, 1140, 'takeaway', '{\"items\": [\"Thời điểm giao tiếp cũng quan trọng như nội dung bạn muốn truyền tải.\"]}', 6, '2026-07-07 05:53:42', '2026-07-07 05:53:42'),
(6881, 1141, 'hook', '{\"title\": \"Im lặng là vàng hay là ngòi nổ cho chiến tranh lạnh?\"}', 1, '2026-07-07 05:53:43', '2026-07-07 05:53:43'),
(6882, 1141, 'explanation', '{\"bullets\": [\"Nhiều người dùng sự im lặng để trừng phạt đối phương hoặc né tránh xung đột.\", \"Chiến tranh lạnh không giúp giải quyết vấn đề mà chỉ làm rạn nứt lòng tin.\", \"Nếu chưa sẵn sàng nói, hãy xin phép tạm dừng thay vì đột ngột biến mất.\"]}', 2, '2026-07-07 05:53:43', '2026-07-07 05:53:43'),
(6883, 1141, 'scenario', '{\"title\": \"Tình huống căng thẳng\", \"body\": \"Sau khi tranh cãi về bài tập nhóm, Trang chặn liên lạc của Quân và im lặng suốt ba ngày liền.\"}', 3, '2026-07-07 05:53:43', '2026-07-07 05:53:43'),
(6884, 1141, 'interaction', '{\"question\": \"Cách xử lý nào của Trang lành mạnh hơn?\", \"choices\": [{\"text\": \"Tiếp tục im lặng cho đến khi Quân tự tìm đến xin lỗi.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Nhắn tin bảo cần thời gian bình tĩnh và hẹn ngày mai cùng thảo luận lại.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:43', '2026-07-07 05:53:43'),
(6885, 1141, 'reflection', '{\"question\": \"Khi giận dỗi, bạn thường chọn im lặng hay nói ra ngay lập tức?\"}', 5, '2026-07-07 05:53:43', '2026-07-07 05:53:43'),
(6886, 1141, 'takeaway', '{\"items\": [\"Im lặng chỉ là giải pháp tạm thời, đối thoại mới là chìa khóa tháo gỡ.\"]}', 6, '2026-07-07 05:53:43', '2026-07-07 05:53:43'),
(6887, 1142, 'hook', '{\"title\": \"Mục tiêu cuối cùng của giao tiếp là gì?\"}', 1, '2026-07-07 05:53:43', '2026-07-07 05:53:43'),
(6888, 1142, 'explanation', '{\"bullets\": [\"Giao tiếp không phải là một trận chiến có người thắng kẻ thua.\", \"Mục tiêu là thấu hiểu cảm xúc của nhau và cùng nhau xây dựng kết nối.\", \"Thắng một cuộc tranh cãi nhưng làm tổn thương đối phương là một thất bại.\"]}', 2, '2026-07-07 05:53:44', '2026-07-07 05:53:44');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(6889, 1142, 'scenario', '{\"title\": \"Tình huống đúc kết\", \"body\": \"Đức chứng minh được mình đúng trong vụ tranh cãi, khiến Mai khóc và bỏ về. Đức cảm thấy đắc thắng nhưng mối quan hệ trở nên lạnh nhạt.\"}', 3, '2026-07-07 05:53:44', '2026-07-07 05:53:44'),
(6890, 1142, 'interaction', '{\"question\": \"Hành động nào thể hiện Đức hiểu ý nghĩa thực sự của giao tiếp?\", \"choices\": [{\"text\": \"Đức tiếp tục tự đắc vì mình đã thắng cuộc tranh luận.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Đức chủ động nhắn tin xin lỗi vì thái độ gay gắt và hỏi han cảm xúc của Mai.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:44', '2026-07-07 05:53:44'),
(6891, 1142, 'reflection', '{\"question\": \"Bạn có sẵn sàng nhường bước trong một cuộc tranh cãi để bảo vệ mối quan hệ không?\"}', 5, '2026-07-07 05:53:44', '2026-07-07 05:53:44'),
(6892, 1142, 'takeaway', '{\"items\": [\"Trong giao tiếp lành mạnh, sự thấu hiểu và kết nối luôn đứng trên cái tôi cá nhân.\"]}', 6, '2026-07-07 05:53:44', '2026-07-07 05:53:44'),
(6893, 1143, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Nền tảng Giao tiếp Lành mạnh\'! Hãy chứng tỏ khả năng thấu hiểu của bạn qua các game tương tác sau.\"}', 1, '2026-07-07 05:53:44', '2026-07-07 05:53:44'),
(6894, 1143, 'scenario-choice', '{\"title\": \"Họp nhóm sóng gió\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn tham gia bài tập nhóm. Một bạn trong nhóm nói: \'Slide này thiết kế xấu quá, làm lại đi\'. Lòng bạn thấy nhói đau và tự ái.\", \"choices\": [{\"text\": \"Nói gay gắt lại: \'Cậu giỏi thì tự đi mà làm!\'.\", \"nextNode\": \"fail_step1\"}, {\"text\": \"Bình tĩnh phản hồi: \'Cậu thấy chỗ nào chưa ổn thì chỉ rõ để tụi mình cùng sửa nhé?\'.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Bạn đó tiếp tục chê: \'Tất cả đều không ổn, đặc biệt là phần chữ\'. Bạn cảm thấy rất tức giận.\", \"choices\": [{\"text\": \"Im lặng bỏ họp và quyết định rút khỏi nhóm.\", \"nextNode\": \"fail_step2\"}, {\"text\": \"Áp dụng mệnh đề Tôi: \'Mình cảm thấy hơi buồn khi bạn nhận xét chung chung như vậy. Bạn chỉ rõ bố cục hay màu sắc chưa hợp được không?\'.\", \"nextNode\": \"step3\"}]}, \"step3\": {\"text\": \"Bạn đó ngớ người rồi chỉ ra màu sắc hơi tối. Cả nhóm đang căng thẳng.\", \"choices\": [{\"text\": \"Cố cãi bằng được là màu này rất đẹp để chiến thắng.\", \"nextNode\": \"fail_step3\"}, {\"text\": \"Lắng nghe và đề xuất cả nhóm bỏ phiếu chọn bảng màu mới.\", \"nextNode\": \"step4\"}]}, \"step4\": {\"text\": \"Nhóm đồng ý bỏ phiếu và chọn được màu mới. Nhưng bạn đó lại nói: \'Thôi làm nhanh lên mệt quá\'.\", \"choices\": [{\"text\": \"Quát to bảo bạn đó câm miệng lại.\", \"nextNode\": \"fail_step4\"}, {\"text\": \"Giao tiếp mắt ôn hòa, bảo: \'Tụi mình sắp xong rồi, cùng cố gắng thêm chút nha\'.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã giải quyết xung đột nhóm cực kỳ khôn ngoan và thấu cảm!\", \"isEnd\": true, \"isSuccess\": true}, \"fail_step1\": {\"text\": \"❌ Thất bại! Thái độ gay gắt lập tức kích hoạt sự tự vệ của đối phương và làm hỏng buổi làm việc.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_step2\": {\"text\": \"❌ Thất bại! Im lặng trốn chạy chỉ kéo dài sự bực bội và làm bài nhóm trễ hạn.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_step3\": {\"text\": \"❌ Thất bại! Coi trọng thắng thua cá nhân hơn công việc chung làm sứt mẻ tình đồng đội.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_step4\": {\"text\": \"❌ Thất bại! Lớn tiếng quát tháo làm cuộc xung đột bùng phát nghiêm trọng hơn.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-07 05:53:44', '2026-07-07 05:53:44'),
(6895, 1143, 'sorting', '{\"instruction\": \"Kéo các thẻ hành vi vào đúng hộp Giao tiếp Lành mạnh hoặc Độc hại.\", \"leftBox\": {\"title\": \"Green Flag (Lành mạnh)\"}, \"rightBox\": {\"title\": \"Red Flag (Độc hại)\"}, \"items\": [{\"text\": \"Lắng nghe không ngắt lời khi bạn đang nói.\", \"correctBox\": \"left\"}, {\"text\": \"Chỉ trích xúc phạm cá nhân khi không vừa ý.\", \"correctBox\": \"right\"}, {\"text\": \"Dùng mệnh đề Tôi để bày tỏ cảm xúc.\", \"correctBox\": \"left\"}, {\"text\": \"Im lặng chiến tranh lạnh để trừng phạt bạn.\", \"correctBox\": \"right\"}, {\"text\": \"Đặt câu hỏi mở để thấu hiểu câu chuyện.\", \"correctBox\": \"left\"}, {\"text\": \"Đọc lén tin nhắn riêng tư của đối phương.\", \"correctBox\": \"right\"}, {\"text\": \"Tôn trọng ranh giới từ chối của bạn bè.\", \"correctBox\": \"left\"}, {\"text\": \"Đổ lỗi dồn dập bắt đầu bằng mệnh đề Bạn.\", \"correctBox\": \"right\"}, {\"text\": \"Giao tiếp mắt thân thiện khi nói chuyện.\", \"correctBox\": \"left\"}, {\"text\": \"Thao túng tâm lý bắt đối phương nhận lỗi.\", \"correctBox\": \"right\"}]}', 3, '2026-07-07 05:53:44', '2026-07-07 05:53:44'),
(6896, 1143, 'matching', '{\"instruction\": \"Ghép cặp các thuật ngữ giao tiếp với định nghĩa chính xác.\", \"pairs\": [{\"left\": \"Lắng nghe chủ động\", \"right\": \"Tập trung hoàn toàn vào người nói và thấu cảm.\"}, {\"left\": \"Mệnh đề Tôi\", \"right\": \"Cách diễn đạt cảm xúc không mang tính đổ lỗi.\"}, {\"left\": \"Ranh giới cá nhân\", \"right\": \"Giới hạn đỏ về cảm xúc và không gian thoải mái.\"}, {\"left\": \"Chiến tranh lạnh\", \"right\": \"Hành vi im lặng trừng phạt gây độc hại.\"}, {\"left\": \"Đồng thuận\", \"right\": \"Sự đồng ý tự nguyện và có thể thay đổi.\"}, {\"left\": \"Cờ xanh giao tiếp\", \"right\": \"Tín hiệu an toàn và tôn trọng lẫn nhau.\"}, {\"left\": \"Hạch hạnh nhân\", \"right\": \"Phần não cảm xúc dễ kích hoạt khi nóng giận.\"}, {\"left\": \"Đối thoại\", \"right\": \"Cách thảo luận ôn hòa để tìm giải pháp chung.\"}]}', 4, '2026-07-07 05:53:44', '2026-07-07 05:53:44'),
(6897, 1143, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp vào chỗ trống trong đoạn văn sau.\", \"sentence\": \"Giao tiếp lành mạnh đòi hỏi sự [blank1] và cởi mở từ cả hai phía. Khi đối thoại, việc lắng nghe [blank2] giúp chúng ta thấu hiểu cảm xúc của đối phương thay vì vội vàng phán xét. Sử dụng mệnh đề [blank3] là một kỹ năng tuyệt vời để bày tỏ suy nghĩ cá nhân mà không gây cảm giác đổ lỗi. Ngoài ra, việc duy trì sự hiện [blank4] trọn vẹn bằng ánh mắt và ngôn ngữ cơ thể sẽ tiếp thêm năng lượng tích cực cho cuộc trò chuyện. Hãy nhớ rằng mục tiêu của giao tiếp là thấu hiểu chứ không phải để giành chiến [blank5].\", \"blanks\": {\"blank1\": {\"correct\": \"tôn trọng\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"chủ động\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"Tôi\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"diện\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"thắng\", \"placeholder\": \"...\"}}, \"words\": [\"tôn trọng\", \"chủ động\", \"Tôi\", \"diện\", \"thắng\", \"Bạn\", \"thua\", \"thụ động\", \"phán xét\", \"im lặng\"]}', 5, '2026-07-07 05:53:44', '2026-07-07 05:53:44'),
(6898, 1143, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp vào chỗ trống trong đoạn văn sau.\", \"sentence\": \"Khi gặp bất đồng ý kiến, cơn nóng giận dễ khiến phần não cảm xúc hay còn gọi là hạch [blank1] kiểm soát hành vi của bạn. Trong trạng thái này, chúng ta rất dễ nói ra những lời gây tổn [blank2] sâu sắc đến người khác. Thay vì chọn phong cách đối đầu gay gắt hoặc im lặng chiến tranh [blank3] độc hại, tụi mình nên thực hiện khoảng nghỉ để hạ nhiệt. Việc ngồi lại cùng nhau đối thoại ôn hòa sẽ giúp tìm ra giải pháp cộng [blank4] mang lại lợi ích cho cả hai bên. Hãy nhớ đặt sự an toàn cảm [blank5] làm ưu tiên hàng đầu trong mọi mối quan hệ.\", \"blanks\": {\"blank1\": {\"correct\": \"hạnh nhân\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"thương\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"lạnh\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"tác\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"xúc\", \"placeholder\": \"...\"}}, \"words\": [\"hạnh nhân\", \"thương\", \"lạnh\", \"tác\", \"xúc\", \"phóng\", \"nóng\", \"nhân tạo\", \"hại\", \"thắng\"]}', 6, '2026-07-07 05:53:44', '2026-07-07 05:53:44'),
(6899, 1143, 'interaction', '{\"question\": \"Khi bạn thân chia sẻ chuyện buồn, câu trả lời nào thể hiện sự lắng nghe thấu cảm nhất?\", \"choices\": [{\"text\": \"Có thế mà cũng buồn, nín đi tớ chở đi ăn.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Tớ hiểu cậu đang buồn, tớ sẽ luôn ở đây nghe cậu nói.\", \"correct\": true, \"emoji\": \"💚\"}]}', 7, '2026-07-07 05:53:44', '2026-07-07 05:53:44'),
(6900, 1143, 'interaction', '{\"question\": \"Cách tốt nhất để đối phó với một tin nhắn không có icon dễ gây hiểu lầm là gì?\", \"choices\": [{\"text\": \"Gọi điện hỏi trực tiếp hoặc gặp gỡ trực tiếp để làm rõ ngữ cảnh.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Nhắn tin chiến tranh lạnh lại để bạn tự biết lỗi.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 8, '2026-07-07 05:53:44', '2026-07-07 05:53:44'),
(6901, 1143, 'interaction', '{\"question\": \"Mệnh đề Tôi hoạt động hiệu quả vì lý do gì?\", \"choices\": [{\"text\": \"Giúp bạn trút bỏ mọi tức giận lên đầu đối phương một cách công khai.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Tập trung bày tỏ cảm xúc cá nhân giúp giảm thiểu sự tự vệ của đối phương.\", \"correct\": true, \"emoji\": \"💚\"}]}', 9, '2026-07-07 05:53:44', '2026-07-07 05:53:44'),
(6902, 1143, 'interaction', '{\"question\": \"Cờ xanh rõ ràng nhất trong một tình bạn lành mạnh là gì?\", \"choices\": [{\"text\": \"Bạn bè luôn tôn trọng ranh giới cá nhân và ủng hộ sở thích của bạn.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Bạn bè yêu cầu bạn chia sẻ 100% mật khẩu các tài khoản.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 10, '2026-07-07 05:53:44', '2026-07-07 05:53:44'),
(6903, 1143, 'interaction', '{\"question\": \"Khi cuộc tranh cãi nhóm đi quá xa và bắt đầu lớn tiếng quát tháo, hành động nào là đúng?\", \"choices\": [{\"text\": \"Đề xuất tạm dừng cuộc họp 15 phút để hạ nhiệt cơn nóng giận.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Cố gắng quát to hơn để áp đặt ý kiến của mình thắng cuộc.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 11, '2026-07-07 05:53:44', '2026-07-07 05:53:44'),
(6904, 1144, 'hook', '{\"title\": \"Nghe và lắng nghe khác nhau thế nào?\"}', 1, '2026-07-07 05:53:45', '2026-07-07 05:53:45'),
(6905, 1144, 'explanation', '{\"bullets\": [\"Nghe chỉ là phản xạ vật lý, còn lắng nghe chủ động là hướng sự chú ý hoàn toàn vào người nói.\", \"Không cắt lời, không nghĩ sẵn câu phản bác trong đầu khi người khác đang nói.\", \"Thể hiện sự thấu hiểu qua ánh mắt và những cái gật đầu đồng cảm.\"]}', 2, '2026-07-07 05:53:45', '2026-07-07 05:53:45'),
(6906, 1144, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Vy đang khóc kể chuyện chú cún cưng bị ốm, Nam ngồi nghe nhưng mắt vẫn liếc nhìn màn hình game trên máy tính.\"}', 3, '2026-07-07 05:53:45', '2026-07-07 05:53:45'),
(6907, 1144, 'interaction', '{\"question\": \"Nam nên làm gì để thể hiện sự lắng nghe chủ động?\", \"choices\": [{\"text\": \"Bảo Vy nín đi và tiếp tục chơi game vì game sắp vào trận.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Tắt máy tính, quay sang nhìn Vy và đưa khăn giấy cho bạn.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:45', '2026-07-07 05:53:45'),
(6908, 1144, 'reflection', '{\"question\": \"Đã bao giờ bạn cảm nhận được ai đó đang lắng nghe mình bằng cả sự chân thành chưa?\"}', 5, '2026-07-07 05:53:45', '2026-07-07 05:53:45'),
(6909, 1144, 'takeaway', '{\"items\": [\"Món quà tuyệt vời nhất bạn có thể trao cho người khác là sự hiện diện trọn vẹn của mình.\"]}', 6, '2026-07-07 05:53:45', '2026-07-07 05:53:45'),
(6910, 1145, 'hook', '{\"title\": \"Làm thế nào để xác nhận mình không hiểu sai ý người khác?\"}', 1, '2026-07-07 05:53:45', '2026-07-07 05:53:45'),
(6911, 1145, 'explanation', '{\"bullets\": [\"Hãy lặp lại hoặc tóm tắt lại ý của họ bằng ngôn ngữ của bạn (Paraphrasing).\", \"Hỏi những câu làm rõ như: \\\"Ý bạn là... đúng không?\\\" để tránh suy diễn lung tung.\", \"Điều này giúp người nói cảm thấy họ thực sự được lắng nghe và thấu hiểu.\"]}', 2, '2026-07-07 05:53:45', '2026-07-07 05:53:45'),
(6912, 1145, 'scenario', '{\"title\": \"Tình huống giao tiếp\", \"body\": \"Lan nhắn: \\\"Tớ mệt mỏi với bài tập nhóm này quá\\\". Mai lập tức nghĩ Lan đang trách mình làm việc kém hiệu quả.\"}', 3, '2026-07-07 05:53:46', '2026-07-07 05:53:46'),
(6913, 1145, 'interaction', '{\"question\": \"Mai nên phản hồi thế nào để xác nhận lại thông tin?\", \"choices\": [{\"text\": \"Nhắn tin tự ái: \\\"Cậu bảo tớ làm tệ chứ gì?\\\".\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Hỏi lại nhẹ nhàng: \\\"Có phải bài tập nhiều quá làm cậu bị quá tải không?\\\".\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:46', '2026-07-07 05:53:46'),
(6914, 1145, 'reflection', '{\"question\": \"Bạn từng hiểu lầm ý của bạn bè vì không hỏi lại rõ ràng chưa?\"}', 5, '2026-07-07 05:53:46', '2026-07-07 05:53:46'),
(6915, 1145, 'takeaway', '{\"items\": [\"Hỏi lại để làm rõ là cách tốt nhất để triệt tiêu những hiểu lầm vô lý.\"]}', 6, '2026-07-07 05:53:46', '2026-07-07 05:53:46'),
(6916, 1146, 'hook', '{\"title\": \"Tại sao mở lòng nói về điểm yếu của mình lại đáng sợ?\"}', 1, '2026-07-07 05:53:46', '2026-07-07 05:53:46'),
(6917, 1146, 'explanation', '{\"bullets\": [\"Tụi mình sợ người khác thấy khuyết điểm của mình sẽ không còn yêu quý mình nữa.\", \"Nhưng sự dễ tổn thương (vulnerability) thực chất lại là chất keo gắn kết.\", \"Chia sẻ thật lòng giúp đối phương hiểu và có cơ hội hỗ trợ bạn tốt hơn.\"]}', 2, '2026-07-07 05:53:46', '2026-07-07 05:53:46'),
(6918, 1146, 'scenario', '{\"title\": \"Tình huống tâm lý\", \"body\": \"Sơn cảm thấy vô cùng áp lực với kỳ thi học sinh giỏi nhưng không dám nói với bố mẹ vì sợ bố mẹ thất vọng.\"}', 3, '2026-07-07 05:53:46', '2026-07-07 05:53:46'),
(6919, 1146, 'interaction', '{\"question\": \"Sơn nên làm gì để giải tỏa cảm xúc này?\", \"choices\": [{\"text\": \"Tiếp tục cắn răng chịu đựng áp lực một mình cho đến khi kiệt sức.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:46', '2026-07-07 05:53:46'),
(6920, 1146, 'reflection', '{\"question\": \"Ai là người bạn cảm thấy an tâm nhất để chia sẻ những nỗi sợ thầm kín?\"}', 5, '2026-07-07 05:53:46', '2026-07-07 05:53:46'),
(6921, 1146, 'takeaway', '{\"items\": [\"Bày tỏ sự yếu đuối không phải là yếu đuối, đó là sự dũng cảm để kết nối.\"]}', 6, '2026-07-07 05:53:46', '2026-07-07 05:53:46'),
(6922, 1147, 'hook', '{\"title\": \"Làm gì khi buổi trò chuyện rơi vào im lặng đáng sợ?\"}', 1, '2026-07-07 05:53:46', '2026-07-07 05:53:46'),
(6923, 1147, 'explanation', '{\"bullets\": [\"Những khoảng lặng trong cuộc trò chuyện là hoàn toàn bình thường, đừng quá hoảng hốt.\", \"Thay vì cố nói những chuyện nhạt nhẽo, hãy đặt câu hỏi mở gợi sự chia sẻ.\", \"Hoặc đơn giản là cùng nhau tận hưởng sự im lặng thoải mái mà không thấy áp lực.\"]}', 2, '2026-07-07 05:53:47', '2026-07-07 05:53:47'),
(6924, 1147, 'scenario', '{\"title\": \"Tình huống gượng gạo\", \"body\": \"Trong lần đầu đi chơi riêng, Huy và Trang bỗng dưng hết chuyện để nói. Cả hai đều cắm mặt vào cốc nước và cảm thấy vô cùng ngột ngạt.\"}', 3, '2026-07-07 05:53:47', '2026-07-07 05:53:47'),
(6925, 1147, 'interaction', '{\"question\": \"Huy nên làm gì để phá vỡ bầu không khí gượng gạo này?\", \"choices\": [{\"text\": \"Cố gắng tìm điện thoại ra lướt Facebook để đỡ ngượng.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Đặt một câu hỏi mở vui vẻ như: \\\"Gần đây cậu có xem bộ phim hay nghe bài hát nào thú vị không?\\\".\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:47', '2026-07-07 05:53:47'),
(6926, 1147, 'reflection', '{\"question\": \"Bạn có cảm thấy thoải mái khi im lặng bên cạnh người bạn thân của mình không?\"}', 5, '2026-07-07 05:53:47', '2026-07-07 05:53:47'),
(6927, 1147, 'takeaway', '{\"items\": [\"Khoảng lặng không đáng sợ, cách tụi mình phản ứng với nó mới quyết định bầu không khí.\"]}', 6, '2026-07-07 05:53:47', '2026-07-07 05:53:47'),
(6928, 1148, 'hook', '{\"title\": \"Làm sao để góp ý mà không khiến đối phương tự vệ xù lông?\"}', 1, '2026-07-07 05:53:47', '2026-07-07 05:53:47'),
(6929, 1148, 'explanation', '{\"bullets\": [\"Thay vì chỉ trích bắt đầu bằng \\\"Bạn\\\" (\\\"Bạn luôn đi muộn!\\\"), hãy dùng mệnh đề \\\"Tôi\\\".\", \"Công thức: \\\"Tôi cảm thấy [cảm xúc] khi [hành động xảy ra] vì [lý do]\\\".\", \"Cách nói này tập trung bày tỏ cảm xúc cá nhân thay vì tấn công hay quy kết lỗi lầm.\"]}', 2, '2026-07-07 05:53:47', '2026-07-07 05:53:47'),
(6930, 1148, 'scenario', '{\"title\": \"Tình huống góp ý\", \"body\": \"Nam thường xuyên trễ hẹn khiến Vy phải chờ đợi dưới nắng nóng. Vy rất tức giận.\"}', 3, '2026-07-07 05:53:47', '2026-07-07 05:53:47'),
(6931, 1148, 'interaction', '{\"question\": \"Vy nên dùng câu nào theo công thức mệnh đề \\\"Tôi\\\" để góp ý cho Nam?\", \"choices\": [{\"text\": \"\\\"Cậu lúc nào cũng đi muộn, chẳng tôn trọng thời gian của tớ gì cả!\\\".\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"\\\"Mình cảm thấy hơi buồn và mệt khi phải đợi lâu dưới nắng, lần sau cậu cố gắng đi đúng giờ nhé.\\\".\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:47', '2026-07-07 05:53:47'),
(6932, 1148, 'reflection', '{\"question\": \"Lần gần nhất bạn góp ý với ai đó, bạn đã dùng cách nói chỉ trích hay bày tỏ cảm xúc của mình?\"}', 5, '2026-07-07 05:53:47', '2026-07-07 05:53:47'),
(6933, 1148, 'takeaway', '{\"items\": [\"Bày tỏ cảm xúc của bản thân hiệu quả hơn việc chỉ ra lỗi lầm của người khác.\"]}', 6, '2026-07-07 05:53:47', '2026-07-07 05:53:47'),
(6934, 1149, 'hook', '{\"title\": \"Giữ bí mật có thực sự an sau?\"}', 1, '2026-07-07 05:53:47', '2026-07-07 05:53:47'),
(6935, 1149, 'explanation', '{\"bullets\": [\"Việc chọn lọc thông tin chia sẻ để bảo vệ quyền riêng tư là hoàn toàn đúng đắn.\", \"Nhưng nếu bạn giấu kín những tổn thương, lo lắng hay ấm ức thì lại là chuyện khác.\", \"Tìm kiếm sự giúp đỡ từ người đáng tin cậy là bước quan trọng để bảo vệ bản thân.\"]}', 2, '2026-07-07 05:53:47', '2026-07-07 05:53:47'),
(6936, 1149, 'scenario', '{\"title\": \"Tình huống tâm sự\", \"body\": \"Vân bị một nhóm bạn lớp bên bắt nạt qua mạng. Vân rất sợ hãi nhưng chọn cách âm thầm chịu đựng một mình.\"}', 3, '2026-07-07 05:53:47', '2026-07-07 05:53:47'),
(6937, 1149, 'interaction', '{\"question\": \"Vân nên làm gì để thoát khỏi tình cảnh này?\", \"choices\": [{\"text\": \"Tiếp tục khóa tài khoản và chịu đựng nỗi lo sợ âm thầm.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Chia sẻ sự việc với bố mẹ hoặc giáo viên chủ nhiệm để nhận sự hỗ trợ pháp lý và tinh thần.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:47', '2026-07-07 05:53:47'),
(6938, 1149, 'reflection', '{\"question\": \"Khi gặp khó khăn lớn, ai là người đầu tiên bạn nghĩ đến để tìm kiếm sự giúp đỡ?\"}', 5, '2026-07-07 05:53:47', '2026-07-07 05:53:47'),
(6939, 1149, 'takeaway', '{\"items\": [\"Bạn không cần phải chịu đựng mọi khó khăn một mình, chia sẻ là sức mạnh.\"]}', 6, '2026-07-07 05:53:47', '2026-07-07 05:53:47'),
(6940, 1150, 'hook', '{\"title\": \"Làm sao để đưa mối quan hệ lên một nấc thang mới?\"}', 1, '2026-07-07 05:53:48', '2026-07-07 05:53:48'),
(6941, 1150, 'explanation', '{\"bullets\": [\"Sự thân mật và gắn kết không tự nhiên sinh ra, nó cần sự vun đắp từ hai phía.\", \"Lắng nghe chủ động kết hợp với tự tin bày tỏ chân thành tạo nên sợi dây liên kết bền chặt.\", \"Hãy dũng cảm mở lòng để thấu hiểu và được thấu hiểu.\"]}', 2, '2026-07-07 05:53:48', '2026-07-07 05:53:48'),
(6942, 1150, 'scenario', '{\"title\": \"Tình huống đúc kết\", \"body\": \"Sau nhiều lần trò chuyện cởi mở và cùng vượt qua những hiểu lầm, Huy và Trang cảm thấy tin tưởng và gắn bó với nhau hơn trước rất nhiều.\"}', 3, '2026-07-07 05:53:48', '2026-07-07 05:53:48'),
(6943, 1150, 'interaction', '{\"question\": \"Yếu tố nào đóng vai trò quan trọng nhất trong sự gắn kết của Huy và Trang?\", \"choices\": [{\"text\": \"Sự im lặng và né tránh những chủ đề nhạy cảm.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Sự chân thành trong việc lắng nghe và dũng cảm bày tỏ cảm xúc của mình.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:48', '2026-07-07 05:53:48'),
(6944, 1150, 'reflection', '{\"question\": \"Bạn đã sẵn sàng để mở lòng hơn với những người xung quanh chưa?\"}', 5, '2026-07-07 05:53:48', '2026-07-07 05:53:48'),
(6945, 1150, 'takeaway', '{\"items\": [\"Kết nối đích thực chỉ được xây dựng trên nền tảng của sự chân thành và thấu hiểu.\"]}', 6, '2026-07-07 05:53:48', '2026-07-07 05:53:48'),
(6946, 1151, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Lắng nghe Chủ động & Tự tin Bày tỏ\'! Cùng thực hành kỹ năng lắng nghe và nói mệnh đề Tôi qua thử thách sau.\"}', 1, '2026-07-07 05:53:48', '2026-07-07 05:53:48'),
(6947, 1151, 'scenario-choice', '{\"title\": \"Khi hai ta cùng im lặng\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn thân kể: \'Tớ vừa cãi nhau với mẹ, mệt mỏi quá\'. Bạn nên nói thế nào?\", \"choices\": [{\"text\": \"\'Mẹ cậu khó tính thế, mẹ tớ thì dễ lắm\'.\", \"nextNode\": \"fail_step1\"}, {\"text\": \"\'Cậu có muốn nói thêm về chuyện đó không?\'.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Bạn thân nói: \'Mẹ cấm tớ đi dã ngoại vì điểm kém\'.\", \"choices\": [{\"text\": \"\'Thôi lo học đi chứ điểm kém đi làm gì!\'.\", \"nextNode\": \"fail_step2\"}, {\"text\": \"\'Cậu cảm thấy thế nào lúc mẹ nói câu đó?\'.\", \"nextNode\": \"step3\"}]}, \"step3\": {\"text\": \"Bạn khóc: \'Tớ thấy áp lực kinh khủng, như bị bỏ rơi\'.\", \"choices\": [{\"text\": \"\'Nín đi, khóc lóc làm gì, yếu đuối thế!\'.\", \"nextNode\": \"fail_step3\"}, {\"text\": \"Im lặng lắng nghe, đưa khăn giấy cho bạn.\", \"nextNode\": \"step4\"}]}, \"step4\": {\"text\": \"Bạn bình tĩnh lại và hỏi: \'Tớ có nên xin lỗi mẹ không?\'.\", \"choices\": [{\"text\": \"\'Cứ mặc kệ đi, chiến tranh lạnh vài ngày mẹ sẽ tự nguôi\'.\", \"nextNode\": \"fail_step4\"}, {\"text\": \"\'Mẹ cũng lo cho cậu thôi. Thử dùng mệnh đề Tôi giải thích áp lực của cậu xem?\'.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã thể hiện kỹ năng lắng nghe chủ động đỉnh cao!\", \"isEnd\": true, \"isSuccess\": true}, \"fail_step1\": {\"text\": \"❌ Thất bại! Cướp lời và so sánh trải nghiệm của mình làm đối phương khép lòng.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_step2\": {\"text\": \"❌ Thất bại! Đưa ra lời khuyên phán xét làm gia tăng áp lực cho bạn.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_step3\": {\"text\": \"❌ Thất bại! Phủ nhận và chê bai cảm xúc khiến bạn thấy tổn thương.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_step4\": {\"text\": \"❌ Thất bại! Xui bạn chiến tranh lạnh chỉ làm mâu thuẫn gia đình trầm trọng hơn.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-07 05:53:48', '2026-07-07 05:53:48'),
(6948, 1151, 'sorting', '{\"instruction\": \"Kéo các thẻ hành vi lắng nghe vào đúng hộp Lắng nghe chủ động hoặc Lắng nghe hời hợt.\", \"leftBox\": {\"title\": \"Lắng nghe chủ động\"}, \"rightBox\": {\"title\": \"Lắng nghe hời hợt\"}, \"items\": [{\"text\": \"Tập trung mắt nhìn bạn khi nói chuyện.\", \"correctBox\": \"left\"}, {\"text\": \"Vừa nghe vừa lướt mạng xã hội.\", \"correctBox\": \"right\"}, {\"text\": \"Đặt câu hỏi mở để làm rõ câu chuyện.\", \"correctBox\": \"left\"}, {\"text\": \"Nghĩ sẵn câu phản bác trong đầu khi bạn chưa nói xong.\", \"correctBox\": \"right\"}, {\"text\": \"Gật đầu nhẹ tỏ ý đồng cảm.\", \"correctBox\": \"left\"}, {\"text\": \"Ngắt lời bạn để kể câu chuyện của mình.\", \"correctBox\": \"right\"}, {\"text\": \"Tóm tắt lại ý bạn vừa nói để xác nhận thông tin.\", \"correctBox\": \"left\"}, {\"text\": \"Xem tivi khi bạn đang khóc.\", \"correctBox\": \"right\"}, {\"text\": \"Giữ không gian yên tĩnh khi lắng nghe.\", \"correctBox\": \"left\"}, {\"text\": \"Nói \'Có thế mà cũng khóc\' để giễu cợt.\", \"correctBox\": \"right\"}]}', 3, '2026-07-07 05:53:48', '2026-07-07 05:53:48'),
(6949, 1151, 'matching', '{\"instruction\": \"Ghép cặp các khái niệm với định nghĩa chính xác.\", \"pairs\": [{\"left\": \"Tóm tắt lại\", \"right\": \"Diễn đạt lại ý của người khác để xác nhận.\"}, {\"left\": \"Lắng nghe chủ động\", \"right\": \"Lắng nghe bằng cả sự hiện diện và trái tim.\"}, {\"left\": \"Mệnh đề Tôi\", \"right\": \"Công thức nói bày tỏ cảm xúc không đổ lỗi.\"}, {\"left\": \"Sự dễ tổn thương\", \"right\": \"Sự dễ tổn thương giúp xây dựng lòng tin sâu.\"}, {\"left\": \"Câu hỏi mở\", \"right\": \"Câu hỏi giúp đối phương chia sẻ nhiều thông tin.\"}, {\"left\": \"Câu hỏi đóng\", \"right\": \"Câu hỏi chỉ có đáp án Có hoặc Không.\"}, {\"left\": \"Cướp lời\", \"right\": \"Hành vi ngắt lời người khác để giành phần nói.\"}, {\"left\": \"Hiện diện\", \"right\": \"Tập trung hoàn toàn không bị xao nhãng bởi điện thoại.\"}]}', 4, '2026-07-07 05:53:48', '2026-07-07 05:53:48'),
(6950, 1151, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp vào chỗ trống trong đoạn văn sau.\", \"sentence\": \"Lắng nghe chủ động không chỉ là việc tiếp nhận [blank1] mà là việc thấu hiểu cảm xúc của đối phương. Để người nói cảm thấy an tâm, chúng ta nên tránh hành vi cướp [blank2] hoặc làm việc riêng khi trò chuyện. Việc đặt câu hỏi [blank3] như \'Cậu cảm thấy thế nào?\' giúp gợi mở câu chuyện một cách tự nhiên. Khi muốn góp ý kiến, việc áp dụng mệnh đề [blank4] là giải pháp tuyệt vời để tránh đối đầu. Cuối cùng, việc dũng cảm mở lòng chia sẻ điểm yếu thể hiện sự dễ tổn [blank5] lành mạnh để củng cố mối quan hệ.\", \"blanks\": {\"blank1\": {\"correct\": \"thông tin\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"lời\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"mở\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"Tôi\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"thương\", \"placeholder\": \"...\"}}, \"words\": [\"thông tin\", \"lời\", \"mở\", \"Tôi\", \"thương\", \"dữ liệu\", \"quyền\", \"đóng\", \"Bạn\", \"hại\"]}', 5, '2026-07-07 05:53:48', '2026-07-07 05:53:48'),
(6951, 1151, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp vào chỗ trống trong đoạn văn sau.\", \"sentence\": \"Để xác nhận bản thân không hiểu sai ý người khác, kỹ thuật [blank1] hay diễn đạt lại là vô cùng cần thiết. Nó giúp triệt tiêu những hiểu [blank2] không đáng có từ tin nhắn chữ. Khi đối phương gặp áp lực lớn, một lời khuyên vội vã thường không hiệu quả bằng việc lắng nghe thấu [blank3]. Sự chia sẻ chân thành sẽ tạo nên không gian an [blank4] giúp giải tỏa căng thẳng tinh thần. Hãy nhớ rằng sự hiện diện trọn vẹn chính là món quà lớn nhất bạn có thể trao tặng cho người [blank5] của mình.\", \"blanks\": {\"blank1\": {\"correct\": \"tóm tắt\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"lầm\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"cảm\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"toàn\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"bạn\", \"placeholder\": \"...\"}}, \"words\": [\"tóm tắt\", \"lầm\", \"cảm\", \"toàn\", \"bạn\", \"chi tiết\", \"đúng\", \"hại\", \"nguy\", \"yêu\"]}', 6, '2026-07-07 05:53:48', '2026-07-07 05:53:48'),
(6952, 1151, 'interaction', '{\"question\": \"Khi bạn đang khóc vì trượt bài kiểm tra, câu nào sau đây là thấu cảm nhất?\", \"choices\": [{\"text\": \"Có mỗi bài kiểm tra thôi mà, lần sau học bù.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Tớ biết cậu đã cố gắng rất nhiều. Tớ sẽ ở đây cùng cậu nhé.\", \"correct\": true, \"emoji\": \"💚\"}]}', 7, '2026-07-07 05:53:49', '2026-07-07 05:53:49'),
(6953, 1151, 'interaction', '{\"question\": \"Tại sao câu hỏi mở lại được khuyên dùng khi muốn gợi mở tâm sự?\", \"choices\": [{\"text\": \"Vì nó giúp người nghe dễ dàng phán xét câu chuyện hơn.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Vì nó không giới hạn câu trả lời, giúp đối phương tự do chia sẻ cảm xúc.\", \"correct\": true, \"emoji\": \"💚\"}]}', 8, '2026-07-07 05:53:49', '2026-07-07 05:53:49'),
(6954, 1151, 'interaction', '{\"question\": \"Lợi ích lớn nhất của mệnh đề Tôi trong giao tiếp là gì?\", \"choices\": [{\"text\": \"Giúp đối phương cảm thấy bớt bị tấn công và cởi mở đối thoại hơn.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Giúp bạn chứng minh mình hoàn toàn đúng và thắng cuộc cãi vã.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 9, '2026-07-07 05:53:49', '2026-07-07 05:53:49'),
(6955, 1151, 'interaction', '{\"question\": \"Hành động nào của bạn thân cho thấy họ đang lắng nghe chủ động?\", \"choices\": [{\"text\": \"Nhìn thẳng vào mắt bạn, cất điện thoại và gật đầu đồng cảm.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Ngồi lướt Facebook và ừ hử mỗi khi bạn nói chuyện.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 10, '2026-07-07 05:53:49', '2026-07-07 05:53:49'),
(6956, 1151, 'interaction', '{\"question\": \"Khi buổi trò chuyện rơi vào khoảng lặng ngượng ngùng, cách xử lý nào tinh tế?\", \"choices\": [{\"text\": \"Đặt một câu hỏi mở nhẹ nhàng về sở thích hoặc chủ đề thú vị mới.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Lập tức lấy điện thoại ra chơi để đỡ ngượng.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 11, '2026-07-07 05:53:49', '2026-07-07 05:53:49'),
(6957, 1152, 'hook', '{\"title\": \"Thế nào là một mối quan hệ \\\"chất lượng cao\\\"?\"}', 1, '2026-07-07 05:53:49', '2026-07-07 05:53:49'),
(6958, 1152, 'explanation', '{\"bullets\": [\"Một mối quan hệ lành mạnh mang lại cho bạn cảm giác an toàn, vui vẻ và tự do là chính mình.\", \"Các đặc điểm cốt lõi gồm: Tôn trọng, Tin tưởng, Bình đẳng, và Giao tiếp cởi mở.\", \"Bạn cảm thấy được tiếp thêm năng lượng tích cực thay vì kiệt sức.\"]}', 2, '2026-07-07 05:53:49', '2026-07-07 05:53:49'),
(6959, 1152, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Hoa thích vẽ tranh cổ động, Đức luôn khích lệ bạn tham gia các cuộc thi và giúp Hoa dọn dẹp màu vẽ sau mỗi buổi học.\"}', 3, '2026-07-07 05:53:49', '2026-07-07 05:53:49'),
(6960, 1152, 'interaction', '{\"question\": \"Hành động của Đức thể hiện đặc điểm nào của mối quan hệ lành mạnh?\", \"choices\": [{\"text\": \"Sự kiểm soát và quản lý thời gian của Hoa.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Sự tôn trọng sở thích cá nhân và khích lệ bạn phát triển bản thân.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:50', '2026-07-07 05:53:50'),
(6961, 1152, 'reflection', '{\"question\": \"Mối quan hệ hiện tại của bạn có mang lại cho bạn nhiều năng lượng tích cực không?\"}', 5, '2026-07-07 05:53:50', '2026-07-07 05:53:50'),
(6962, 1152, 'takeaway', '{\"items\": [\"Mối quan hệ lành mạnh nâng đỡ bạn lên chứ không kéo bạn xuống.\"]}', 6, '2026-07-07 05:53:50', '2026-07-07 05:53:50'),
(6963, 1153, 'hook', '{\"title\": \"Bình đẳng trong tình bạn/tình yêu là như thế nào?\"}', 1, '2026-07-07 05:53:50', '2026-07-07 05:53:50'),
(6964, 1153, 'explanation', '{\"bullets\": [\"Bình đẳng nghĩa là tiếng nói của hai bên có giá trị ngang nhau trong các quyết định chung.\", \"Không có ai là \\\"sếp\\\" chỉ tay năm ngón, cũng không có ai luôn phải nhún nhường.\", \"Quyết định đi đâu, làm gì đều dựa trên sự đồng thuận vui vẻ của cả hai.\"]}', 2, '2026-07-07 05:53:50', '2026-07-07 05:53:50'),
(6965, 1153, 'scenario', '{\"title\": \"Tình huống quyết định\", \"body\": \"Nam muốn đi ăn pizza, Hoa lại thích ăn đồ Hàn Quốc. Cả hai cùng thảo luận và quyết định hôm nay ăn pizza, tuần sau sẽ ăn đồ Hàn Quốc.\"}', 3, '2026-07-07 05:53:50', '2026-07-07 05:53:50'),
(6966, 1153, 'interaction', '{\"question\": \"Cách giải quyết của Nam và Hoa thể hiện điều gì?\", \"choices\": [{\"text\": \"Sự thỏa hiệp gượng ép từ một phía.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Sự bình đẳng và tôn trọng ý kiến của nhau trong các quyết định chung.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:50', '2026-07-07 05:53:50'),
(6967, 1153, 'reflection', '{\"question\": \"Trong nhóm bạn của bạn, các quyết định đi chơi có được đưa ra một cách bình đẳng không?\"}', 5, '2026-07-07 05:53:50', '2026-07-07 05:53:50'),
(6968, 1153, 'takeaway', '{\"items\": [\"Bình đẳng là khi cả hai đều cảm thấy tiếng nói của mình có trọng lượng như nhau.\"]}', 6, '2026-07-07 05:53:50', '2026-07-07 05:53:50'),
(6969, 1154, 'hook', '{\"title\": \"Làm sao biết mối quan hệ của bạn đang bị \\\"lệch\\\"?\"}', 1, '2026-07-07 05:53:50', '2026-07-07 05:53:50'),
(6970, 1154, 'explanation', '{\"bullets\": [\"Mất cân bằng xảy ra khi một người luôn cho đi (quan tâm, nhường nhịn) còn người kia chỉ biết nhận.\", \"Cảm thấy mệt mỏi, ấm ức hoặc có cảm giác mình đang bị lợi dụng là tín hiệu cảnh báo.\", \"Mối quan hệ bền vững cần sự vun đắp và nỗ lực tương xứng từ cả hai phía.\"]}', 2, '2026-07-07 05:53:50', '2026-07-07 05:53:50'),
(6971, 1154, 'scenario', '{\"title\": \"Tình huống bất ổn\", \"body\": \"Vy luôn là người chủ động nhắn tin, hỏi han và làm bài tập hộ Nam, trong khi Nam hiếm khi chủ động nhắn tin trước hay giúp đỡ Vy chuyện gì.\"}', 3, '2026-07-07 05:53:50', '2026-07-07 05:53:50'),
(6972, 1154, 'interaction', '{\"question\": \"Vy nên làm gì để cân bằng lại mối quan hệ này?\", \"choices\": [{\"text\": \"Tiếp tục chiều chuộng Nam nhiều hơn nữa để hy vọng Nam sẽ thay đổi.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Gặp gỡ và chia sẻ thẳng thắn với Nam về cảm xúc của mình và mong muốn sự chủ động từ Nam.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:50', '2026-07-07 05:53:50'),
(6973, 1154, 'reflection', '{\"question\": \"Bạn có cảm thấy mình đang là người duy nhất cố gắng níu giữ một tình bạn nào đó không?\"}', 5, '2026-07-07 05:53:51', '2026-07-07 05:53:51'),
(6974, 1154, 'takeaway', '{\"items\": [\"Mối quan hệ một chiều giống như đi xe đạp một bánh, rất mệt mỏi và dễ ngã.\"]}', 6, '2026-07-07 05:53:51', '2026-07-07 05:53:51'),
(6975, 1155, 'hook', '{\"title\": \"Nhượng bộ quá nhiều có phải là cách giữ hòa khí thông minh?\"}', 1, '2026-07-07 05:53:51', '2026-07-07 05:53:51'),
(6976, 1155, 'explanation', '{\"bullets\": [\"Nhiều bạn chọn cách nhường nhịn vô điều kiện để tránh cãi vã.\", \"Nhưng nhượng bộ liên tục sẽ khiến bạn đánh mất ranh giới cá nhân và tích tụ ấm ức.\", \"Giao tiếp lành mạnh cho phép sự bất đồng quan điểm được thảo luận một cách tôn trọng.\"]}', 2, '2026-07-07 05:53:51', '2026-07-07 05:53:51'),
(6977, 1155, 'scenario', '{\"title\": \"Tình huống nhượng bộ\", \"body\": \"Sơn thích chơi bóng rổ, nhưng bạn thân là Lâm luôn bắt Sơn đi chơi game net cùng. Sơn luôn đồng ý vì sợ Lâm giận dỗi.\"}', 3, '2026-07-07 05:53:51', '2026-07-07 05:53:51'),
(6978, 1155, 'interaction', '{\"question\": \"Sơn nên thay đổi cách ứng xử thế nào để bảo vệ sở thích cá nhân?\", \"choices\": [{\"text\": \"Tiếp tục đi chơi game cùng Lâm và âm thầm ghét bỏ sở thích của Lâm.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Đề xuất thẳng thắn: \\\"Hôm nay tụi mình chơi bóng rổ nhé, mai tớ sẽ đi chơi game cùng cậu.\\\".\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:51', '2026-07-07 05:53:51'),
(6979, 1155, 'reflection', '{\"question\": \"Bạn từng từ bỏ sở thích của mình chỉ để làm vui lòng một người bạn chưa?\"}', 5, '2026-07-07 05:53:51', '2026-07-07 05:53:51'),
(6980, 1155, 'takeaway', '{\"items\": [\"Bạn không cần phải đánh mất chính mình để giữ chân một người bạn.\"]}', 6, '2026-07-07 05:53:51', '2026-07-07 05:53:51'),
(6981, 1156, 'hook', '{\"title\": \"Làm sao để cùng nhau gánh vác trách nhiệm trong mối quan hệ?\"}', 1, '2026-07-07 05:53:51', '2026-07-07 05:53:51'),
(6982, 1156, 'explanation', '{\"bullets\": [\"Trách nhiệm chia sẻ (Shared responsibility) giúp giảm tải áp lực cho cả hai.\", \"Từ việc lên kế hoạch bài tập nhóm đến chuẩn bị quà sinh nhật cho bạn bè.\", \"Hãy cùng thảo luận rõ ràng ai làm việc gì để tránh tị nạnh hay quá tải.\"]}', 2, '2026-07-07 05:53:51', '2026-07-07 05:53:51'),
(6983, 1156, 'scenario', '{\"title\": \"Tình huống làm nhóm\", \"body\": \"Trong bài tập thuyết trình, Hoa làm toàn bộ từ nội dung đến thiết kế slide, còn Tuấn chỉ nhận phần lên thuyết trình vài câu cuối.\"}', 3, '2026-07-07 05:53:51', '2026-07-07 05:53:51'),
(6984, 1156, 'interaction', '{\"question\": \"Hoa nên làm gì để phân chia lại công việc công bằng hơn?\", \"choices\": [{\"text\": \"Im lặng làm hết rồi sau đó lên lớp ấm ức nói xấu Tuấn với các bạn khác.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Họp nhóm lại và phân chia rõ ràng: Hoa phụ trách nội dung, Tuấn thiết kế slide và cả hai cùng thuyết trình.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:51', '2026-07-07 05:53:51'),
(6985, 1156, 'reflection', '{\"question\": \"Bạn có thường nhận hết phần việc nặng về mình vì sợ người khác làm không đúng ý không?\"}', 5, '2026-07-07 05:53:51', '2026-07-07 05:53:51'),
(6986, 1156, 'takeaway', '{\"items\": [\"Chia sẻ trách nhiệm là biểu hiện của sự tôn trọng năng lực và thời gian của nhau.\"]}', 6, '2026-07-07 05:53:51', '2026-07-07 05:53:51'),
(6987, 1157, 'hook', '{\"title\": \"Tự kiểm tra độ \\\"bình đẳng\\\" trong mối quan hệ của bạn!\"}', 1, '2026-07-07 05:53:52', '2026-07-07 05:53:52'),
(6988, 1157, 'explanation', '{\"bullets\": [\"Hãy tự hỏi bản thân những câu hỏi đơn giản để đánh giá mối quan hệ.\", \"Bạn có dám nói \\\"Không\\\" mà không sợ bị giận dỗi dai dẳng không?\", \"Tiếng nói của bạn có thực sự được lắng nghe khi cả hai bất đồng quan điểm?\", \"Sự thật lòng là thước đo chính xác nhất cho độ bình đẳng.\"]}', 2, '2026-07-07 05:53:52', '2026-07-07 05:53:52'),
(6989, 1157, 'scenario', '{\"title\": \"Tình huống tự kiểm tra\", \"body\": \"Mỗi lần Vy bận học không đi chơi được, Nam đều nhắn tin trách móc và chiến tranh lạnh suốt nhiều ngày khiến Vy vô cùng căng thẳng.\"}', 3, '2026-07-07 05:53:52', '2026-07-07 05:53:52'),
(6990, 1157, 'interaction', '{\"question\": \"Mối quan hệ của Vy và Nam có đang bình đẳng không?\", \"choices\": [{\"text\": \"Có, vì Nam thể hiện sự nhớ nhung và muốn gặp Vy thường xuyên.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Không, vì Nam đang dùng sự giận dỗi để áp đặt mong muốn của mình lên Vy.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:52', '2026-07-07 05:53:52'),
(6991, 1157, 'reflection', '{\"question\": \"Có ranh giới nào của bạn đang bị đối phương thường xuyên bỏ qua không?\"}', 5, '2026-07-07 05:53:52', '2026-07-07 05:53:52'),
(6992, 1157, 'takeaway', '{\"items\": [\"Bình đẳng nghĩa là tôn trọng tự do cá nhân và ranh giới của đối phương.\"]}', 6, '2026-07-07 05:53:52', '2026-07-07 05:53:52'),
(6993, 1158, 'hook', '{\"title\": \"Bí quyết để duy trì mối quan hệ lâu dài là gì?\"}', 1, '2026-07-07 05:53:52', '2026-07-07 05:53:52'),
(6994, 1158, 'explanation', '{\"bullets\": [\"Một mối quan hệ bền vững giống như một điệu nhảy đôi nhịp nhàng.\", \"Cần sự tiến lui, cho đi và nhận lại cân bằng từ cả hai phía.\", \"Hãy luôn trân trọng, lắng nghe và cùng nhau điều chỉnh khi có dấu hiệu lệch nhịp.\"]}', 2, '2026-07-07 05:53:52', '2026-07-07 05:53:52'),
(6995, 1158, 'scenario', '{\"title\": \"Tình huống đúc kết\", \"body\": \"Sau khi thống nhất lại cách phân chia thời gian và tôn trọng không gian riêng tư của nhau, tình bạn của Linh và Vy trở nên khăng khít và thoải mái hơn rất nhiều.\"}', 3, '2026-07-07 05:53:52', '2026-07-07 05:53:52'),
(6996, 1158, 'interaction', '{\"question\": \"Yếu tố nào giúp mối quan hệ của Linh và Vy bền vững hơn?\", \"choices\": [{\"text\": \"Sự im lặng chịu đựng để giữ hòa khí bề nổi.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Sự đối thoại chân thành để tìm điểm cân bằng giữa nhu cầu của cả hai.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:52', '2026-07-07 05:53:52'),
(6997, 1158, 'reflection', '{\"question\": \"Bạn sẽ làm gì hôm nay để thể hiện sự trân trọng đối với một mối quan hệ lành mạnh của mình?\"}', 5, '2026-07-07 05:53:52', '2026-07-07 05:53:52'),
(6998, 1158, 'takeaway', '{\"items\": [\"Sự cân bằng và tôn trọng lẫn nhau là nền móng của mọi mối quan hệ bền vững.\"]}', 6, '2026-07-07 05:53:52', '2026-07-07 05:53:52'),
(6999, 1159, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Xây dựng Mối quan hệ Lành mạnh\'! Hãy chứng tỏ khả năng nhận diện bình đẳng trong mối quan hệ.\"}', 1, '2026-07-07 05:53:53', '2026-07-07 05:53:53'),
(7000, 1159, 'scenario-choice', '{\"title\": \"Khi tình bạn rạn nứt\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn thân rủ bạn trốn học đi xem phim, bảo: \'Thân nhau thì phải đi chứ!\'. Bạn làm thế nào?\", \"choices\": [{\"text\": \"Đồng ý đi cùng vì sợ bạn giận dỗi.\", \"nextNode\": \"fail_step1\"}, {\"text\": \"Từ từ từ chối lịch sự và hẹn bạn cuối tuần đi cùng.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Bạn thân tức giận bảo: \'Cậu coi trọng học hành hơn tớ rồi!\'.\", \"choices\": [{\"text\": \"Tức giận cãi lại và tuyên bố nghỉ chơi.\", \"nextNode\": \"fail_step2\"}, {\"text\": \"Bày tỏ mệnh đề Tôi: \'Tớ buồn khi cậu nói thế. Tớ muốn học tốt nhưng vẫn trân trọng tình bạn này\'.\", \"nextNode\": \"step3\"}]}, \"step3\": {\"text\": \"Bạn thân im lặng một lúc rồi bảo: \'Vậy cuối tuần đi ăn kem nữa nhé?\'.\", \"choices\": [{\"text\": \"\'Không, tớ bận rồi\' để trả đũa.\", \"nextNode\": \"fail_step3\"}, {\"text\": \"\'Đồng ý luôn! Tớ sẽ bao chầu kem này\'.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã giữ được tình bạn mà vẫn bảo vệ được rèn luyện học tập!\", \"isEnd\": true, \"isSuccess\": true}, \"fail_step1\": {\"text\": \"❌ Thất bại! Nhượng bộ ranh giới học tập làm hại chính kết quả của bạn.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_step2\": {\"text\": \"❌ Thất bại! Nóng giận đối đầu lập tức làm rạn nứt tình bạn.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_step3\": {\"text\": \"❌ Thất bại! Trả đũa vụn vặt làm mất đi cơ hội làm hòa.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-07 05:53:53', '2026-07-07 05:53:53'),
(7001, 1159, 'sorting', '{\"instruction\": \"Kéo các hành vi vào đúng hộp Mối quan hệ lành mạnh hoặc độc hại.\", \"leftBox\": {\"title\": \"Mối quan hệ lành mạnh\"}, \"rightBox\": {\"title\": \"Mối quan hệ độc hại\"}, \"items\": [{\"text\": \"Khích lệ bạn tham gia câu lạc bộ yêu thích.\", \"correctBox\": \"left\"}, {\"text\": \"Cấm đoán bạn chơi với các bạn khác giới.\", \"correctBox\": \"right\"}, {\"text\": \"Lắng nghe và tôn trọng ý kiến khác biệt.\", \"correctBox\": \"left\"}, {\"text\": \"Thường xuyên dằn vặt lỗi lầm cũ của bạn.\", \"correctBox\": \"right\"}, {\"text\": \"Cùng nhau chia sẻ trách nhiệm bài tập nhóm.\", \"correctBox\": \"left\"}, {\"text\": \"Chỉ trích ngoại hình và chê bai bạn.\", \"correctBox\": \"right\"}, {\"text\": \"Tôn trọng thời gian riêng tư của nhau.\", \"correctBox\": \"left\"}, {\"text\": \"Đe dọa chia tay/nghỉ chơi để ép bạn nghe lời.\", \"correctBox\": \"right\"}, {\"text\": \"Sẵn sàng xin lỗi khi nhận ra mình sai.\", \"correctBox\": \"left\"}, {\"text\": \"Bắt bạn chịu tiền cho mọi buổi đi chơi.\", \"correctBox\": \"right\"}]}', 3, '2026-07-07 05:53:53', '2026-07-07 05:53:53'),
(7002, 1159, 'matching', '{\"instruction\": \"Ghép cặp các từ khóa với định nghĩa chính xác.\", \"pairs\": [{\"left\": \"Tôn trọng\", \"right\": \"Chấp nhận sự khác biệt và không áp đặt nhau.\"}, {\"left\": \"Tin tưởng\", \"right\": \"An tâm về lòng trung thực của đối phương.\"}, {\"left\": \"Bình đẳng\", \"right\": \"Tiếng nói của hai bên có giá trị ngang nhau.\"}, {\"left\": \"Kiểm soát\", \"right\": \"Hành vi gò bó, bắt đối phương theo ý mình.\"}, {\"left\": \"Thỏa hiệp\", \"right\": \"Tìm giải pháp trung hòa đáp ứng cả hai bên.\"}, {\"left\": \"Cho và nhận\", \"right\": \"Sự vun đắp tương xứng từ hai phía.\"}, {\"left\": \"Độc lập\", \"right\": \"Giữ không gian và sở thích riêng ngoài mối quan hệ.\"}, {\"left\": \"Giao tiếp cởi mở\", \"right\": \"Chia sẻ chân thành mọi vướng mắc tinh thần.\"}]}', 4, '2026-07-07 05:53:53', '2026-07-07 05:53:53'),
(7003, 1159, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp vào chỗ trống trong đoạn văn sau.\", \"sentence\": \"Một mối quan hệ lành mạnh luôn được xây dựng trên nền tảng của sự [blank1] lẫn nhau. Trong tình bạn hay tình yêu, sự [blank2] đóng vai trò quan trọng khi tiếng nói của cả hai đều có giá trị ngang nhau trong mọi quyết định. Hãy cảnh giác với những hành vi [blank3] độc hại núp bóng sự lo lắng quá mức. Việc chia sẻ [blank4] trong công việc chung sẽ giúp mối quan hệ phát triển bền vững. Đừng vì sợ mất lòng mà luôn chọn cách [blank5] ranh giới cá nhân của mình.\", \"blanks\": {\"blank1\": {\"correct\": \"tôn trọng\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"bình đẳng\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"kiểm soát\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"trách nhiệm\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"nhượng bộ\", \"placeholder\": \"...\"}}, \"words\": [\"tôn trọng\", \"bình đẳng\", \"kiểm soát\", \"trách nhiệm\", \"nhượng bộ\", \"xúc phạm\", \"lợi ích\", \"trốn chạy\", \"chơi bời\", \"bỏ cuộc\"]}', 5, '2026-07-07 05:53:53', '2026-07-07 05:53:53'),
(7004, 1159, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp vào chỗ trống trong đoạn văn sau.\", \"sentence\": \"Khi mối quan hệ rơi vào trạng thái mất [blank1], một người sẽ cảm thấy kiệt sức vì luôn phải vun đắp một mình. Để hàn gắn, cả hai cần ngồi lại thực hiện đối thoại [blank2] thay vì chọn cách im lặng trừng phạt. Việc khích lệ đối phương giữ vững sự [blank3] cá nhân là cờ xanh cực kỳ chất lượng. Sự tin [blank4] sâu sắc chỉ xuất hiện khi ranh giới của mỗi người được tôn trọng. Hãy luôn nuôi dưỡng tình cảm bằng năng lượng tích [blank5] mỗi ngày.\", \"blanks\": {\"blank1\": {\"correct\": \"cân bằng\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"chân thành\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"độc lập\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"cậy\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"cực\", \"placeholder\": \"...\"}}, \"words\": [\"cân bằng\", \"chân thành\", \"độc lập\", \"cậy\", \"cực\", \"độc hại\", \"giả tạo\", \"phụ thuộc\", \"nghi ngờ\", \"sợ\"]}', 6, '2026-07-07 05:53:53', '2026-07-07 05:53:53'),
(7005, 1159, 'interaction', '{\"question\": \"Dấu hiệu nào rõ nhất của một mối quan hệ mất cân bằng?\", \"choices\": [{\"text\": \"Một người luôn phải nhún nhường và làm bài hộ đối phương để giữ hòa khí.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Cả hai cùng chia sẻ công việc làm slide thuyết trình nhóm.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 7, '2026-07-07 05:53:53', '2026-07-07 05:53:53'),
(7006, 1159, 'interaction', '{\"question\": \"Bạn nên phản ứng thế nào khi thấy tình bạn đang trở thành một chiều?\", \"choices\": [{\"text\": \"Chia sẻ thẳng thắn với bạn về cảm giác của mình và mong muốn sự cố gắng từ hai phía.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tự trách bản thân mình chưa làm đủ tốt và tiếp tục chiều chuộng bạn.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 8, '2026-07-07 05:53:53', '2026-07-07 05:53:53'),
(7007, 1159, 'interaction', '{\"question\": \"\'Cờ xanh\' chất lượng nhất trong tình yêu tuổi học trò là gì?\", \"choices\": [{\"text\": \"Khích lệ nhau cùng tiến bộ trong học tập và tôn trọng các bạn bè khác.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Yêu cầu người yêu ngắt kết nối với tất cả bạn bè cũ.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 9, '2026-07-07 05:53:53', '2026-07-07 05:53:53'),
(7008, 1159, 'interaction', '{\"question\": \"Tại sao nhượng bộ ranh giới liên tục lại nguy hiểm?\", \"choices\": [{\"text\": \"Vì nó làm bạn tích tụ ấm ức và đánh mất đi giá trị riêng của mình.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Vì nó giúp mối quan hệ luôn êm ấm không bao giờ cãi vã.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 10, '2026-07-07 05:53:53', '2026-07-07 05:53:53'),
(7009, 1159, 'interaction', '{\"question\": \"Đích đến của sự bình đẳng trong mối quan hệ là gì?\", \"choices\": [{\"text\": \"Cả hai đều thấy mình được tôn trọng và an tâm là chính mình.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Một người được quyền quyết định đi chơi ở đâu mọi lúc.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 11, '2026-07-07 05:53:53', '2026-07-07 05:53:53'),
(7010, 1160, 'hook', '{\"title\": \"Ranh giới cá nhân có phải là bức tường ngăn cách mọi người?\"}', 1, '2026-07-07 05:53:53', '2026-07-07 05:53:53'),
(7011, 1160, 'explanation', '{\"bullets\": [\"Ranh giới cá nhân không phải là bức tường xây lên để cô lập bản thân.\", \"Đó là đường biên giới vô hình chỉ ra điều gì khiến bạn thấy thoải mái và điều gì thì không.\", \"Ranh giới có thể ở nhiều khía cạnh: Thể chất, Thời gian, Cảm xúc, hay Thông tin riêng tư.\"]}', 2, '2026-07-07 05:53:53', '2026-07-07 05:53:53'),
(7012, 1160, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Vy không thích người khác tự ý dùng đồ trang điểm của mình. Khi bạn cùng phòng tự tiện lấy son của Vy dùng, Vy cảm thấy rất khó chịu.\"}', 3, '2026-07-07 05:53:53', '2026-07-07 05:53:53'),
(7013, 1160, 'interaction', '{\"question\": \"Hành động tự ý dùng son của bạn cùng phòng đã chạm vào ranh giới nào của Vy?\", \"choices\": [{\"text\": \"Ranh giới về mặt thời gian và công việc của Vy.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Ranh giới về mặt sở hữu tài sản cá nhân và không gian riêng tư của Vy.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:54', '2026-07-07 05:53:54'),
(7014, 1160, 'reflection', '{\"question\": \"Ranh giới cá nhân nào là quan trọng nhất đối với bạn ở thời điểm hiện tại?\"}', 5, '2026-07-07 05:53:54', '2026-07-07 05:53:54'),
(7015, 1160, 'takeaway', '{\"items\": [\"Ranh giới cá nhân giúp người khác hiểu cách đối xử tôn trọng đối với bạn.\"]}', 6, '2026-07-07 05:53:54', '2026-07-07 05:53:54'),
(7016, 1161, 'hook', '{\"title\": \"Làm thế nào để không vô tình trở thành kẻ xâm phạm ranh giới?\"}', 1, '2026-07-07 05:53:54', '2026-07-07 05:53:54');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(7017, 1161, 'explanation', '{\"bullets\": [\"Đừng tự suy diễn rằng đối phương thoải mái với những gì bạn làm.\", \"Hãy quan sát ngôn ngữ cơ thể (né tránh ánh mắt, lùi lại, cười gượng) hoặc hỏi trực tiếp.\", \"Câu hỏi thần chú: \\\"Tớ làm thế này cậu có thấy thoải mái không?\\\".\"]}', 2, '2026-07-07 05:53:54', '2026-07-07 05:53:54'),
(7018, 1161, 'scenario', '{\"title\": \"Tình huống giao tiếp\", \"body\": \"Nam muốn khoác vai Mai khi hai bạn đang đi dạo, nhưng thấy Mai hơi co vai lại và bước lùi sang một bên.\"}', 3, '2026-07-07 05:53:54', '2026-07-07 05:53:54'),
(7019, 1161, 'interaction', '{\"question\": \"Nam nên phản ứng thế nào trước tín hiệu từ cơ thể của Mai?\", \"choices\": [{\"text\": \"Tiếp tục khoác vai mạnh hơn vì nghĩ Mai chỉ đang ngượng ngùng.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Thu tay lại lịch sự và hỏi nhẹ nhàng xem Mai có thấy thoải mái không.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:54', '2026-07-07 05:53:54'),
(7020, 1161, 'reflection', '{\"question\": \"Bạn từng vô tình làm ai đó khó chịu vì đùa nghịch quá trớn chưa?\"}', 5, '2026-07-07 05:53:54', '2026-07-07 05:53:54'),
(7021, 1161, 'takeaway', '{\"items\": [\"Tôn trọng ranh giới của người khác bắt đầu từ việc lắng nghe và quan sát tinh tế.\"]}', 6, '2026-07-07 05:53:54', '2026-07-07 05:53:54'),
(7022, 1162, 'hook', '{\"title\": \"Tại sao nói \\\"Không\\\" lại khiến tụi mình thấy cắn rứt lương tâm?\"}', 1, '2026-07-07 05:53:54', '2026-07-07 05:53:54'),
(7023, 1162, 'explanation', '{\"bullets\": [\"Chúng ta thường được dạy phải luôn chia sẻ, giúp đỡ và làm người khác vui lòng.\", \"Tâm lý sợ bị coi là ích kỷ hay làm rạn nứt tình cảm khiến việc từ chối trở nên khó khăn.\", \"Hãy nhớ: Đặt ranh giới là bạn đang bảo vệ năng lượng của mình để có thể yêu thương lành mạnh.\"]}', 2, '2026-07-07 05:53:54', '2026-07-07 05:53:54'),
(7024, 1162, 'scenario', '{\"title\": \"Tình huống lý thú\", \"body\": \"Hoa rất mệt sau buổi học và muốn về nhà nghỉ ngơi, nhưng bạn thân lại năn nỉ đi mua sắm cùng. Hoa thấy rất áy náy nếu từ chối.\"}', 3, '2026-07-07 05:53:55', '2026-07-07 05:53:55'),
(7025, 1162, 'interaction', '{\"question\": \"Hoa nên nghĩ thế nào để vượt qua cảm giác tội lỗi vô lý này?\", \"choices\": [{\"text\": \"Tự trách mình là một người bạn tồi tệ vì không đi chơi cùng bạn thân.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Hiểu rằng nghỉ ngơi khi cơ thể mệt mỏi là quyền cơ bản và cần thiết để tái tạo năng lượng.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:55', '2026-07-07 05:53:55'),
(7026, 1162, 'reflection', '{\"question\": \"Bạn có thường cảm thấy áy náy khi phải từ chối lời nhờ vả của bạn bè không?\"}', 5, '2026-07-07 05:53:55', '2026-07-07 05:53:55'),
(7027, 1162, 'takeaway', '{\"items\": [\"Bạn không có trách nhiệm phải làm hài lòng tất cả mọi người bằng cách bỏ qua cảm xúc của chính mình.\"]}', 6, '2026-07-07 05:53:55', '2026-07-07 05:53:55'),
(7028, 1163, 'hook', '{\"title\": \"Bạn thân có quyền biết tất cả bí mật của bạn?\"}', 1, '2026-07-07 05:53:55', '2026-07-07 05:53:55'),
(7029, 1163, 'explanation', '{\"bullets\": [\"Tình bạn thân thiết không đồng nghĩa với việc chia sẻ 100% không gian riêng tư.\", \"Tin nhắn chat, nhật ký, tài khoản mạng xã hội là ranh giới thông tin cá nhân.\", \"Bạn hoàn toàn có quyền giữ lại những khoảng không gian riêng tư cho riêng mình.\"]}', 2, '2026-07-07 05:53:55', '2026-07-07 05:53:55'),
(7030, 1163, 'scenario', '{\"title\": \"Tình huống ranh giới\", \"body\": \"Lâm giật điện thoại của Sơn đòi đọc tin nhắn chat của Sơn với một bạn nữ cùng lớp, bảo rằng: \\\"Thân nhau thế mà lại giấu à?\\\".\"}', 3, '2026-07-07 05:53:55', '2026-07-07 05:53:55'),
(7031, 1163, 'interaction', '{\"question\": \"Sơn nên bảo vệ ranh giới của mình thế nào?\", \"choices\": [{\"text\": \"Để Lâm đọc hết vì sợ Lâm giận dỗi và bảo mình không tin tưởng bạn.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Lấy lại điện thoại ôn hòa nhưng dứt khoát: \\\"Tụi mình thân nhau nhưng chuyện tin nhắn này là riêng tư của tớ, mong cậu tôn trọng nhé.\\\".\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 05:53:55', '2026-07-07 05:53:55'),
(7032, 1163, 'reflection', '{\"question\": \"Có giới hạn riêng tư nào bạn tuyệt đối không muốn bạn bè chạm vào không?\"}', 5, '2026-07-07 05:53:55', '2026-07-07 05:53:55'),
(7033, 1163, 'takeaway', '{\"items\": [\"Tin tưởng nhau không nghĩa là phải phơi bày toàn bộ cuộc sống riêng tư của mình.\"]}', 6, '2026-07-07 05:53:55', '2026-07-07 05:53:55'),
(7034, 1164, 'hook', '{\"title\": \"Làm sao để đặt ranh giới mà không gây gổ cãi vã?\"}', 1, '2026-07-07 05:53:55', '2026-07-07 05:53:55'),
(7035, 1164, 'explanation', '{\"bullets\": [\"Dùng công thức 3 bước: Thừa nhận mối quan hệ + Bày tỏ ranh giới rõ ràng + Đề xuất giải pháp thay thế.\", \"Giọng điệu bình tĩnh, ôn hòa nhưng biểu cảm dứt khoát, không ngập ngừng áy náy.\", \"Thực hành nhiều lần sẽ giúp bạn nói \\\"Không\\\" một cách tự tin hơn.\"]}', 2, '2026-07-07 05:53:55', '2026-07-07 05:53:55'),
(7036, 1164, 'scenario', '{\"title\": \"Tình huống thực hành\", \"body\": \"Bạn rủ bạn trốn tiết đi chơi game, nhưng bạn muốn ở lại ôn thi học kỳ.\"}', 3, '2026-07-07 05:53:55', '2026-07-07 05:53:55'),
(7037, 1164, 'interaction', '{\"question\": \"Câu nói nào áp dụng đúng kỹ năng thiết lập giới hạn lành mạnh nhất?\", \"choices\": [{\"text\": \"\\\"Thôi đi làm gì, học đi chứ lười thế!\\\".\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"\\\"Tớ rất muốn đi chơi với cậu, nhưng tuần này tớ cần tập trung ôn thi học kỳ. Thi xong tụi mình cùng đi nhé!\\\".\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:55', '2026-07-07 05:53:55'),
(7038, 1164, 'reflection', '{\"question\": \"Lần gần nhất bạn từ chối thành công một việc mà vẫn giữ được tình cảm là khi nào?\"}', 5, '2026-07-07 05:53:55', '2026-07-07 05:53:55'),
(7039, 1164, 'takeaway', '{\"items\": [\"Đặt ranh giới rõ ràng là biểu hiện của việc bạn coi trọng mối quan hệ lâu dài.\"]}', 6, '2026-07-07 05:53:55', '2026-07-07 05:53:55'),
(7040, 1165, 'hook', '{\"title\": \"Nói \\\"Không\\\" có làm bạn trở thành người ích kỷ?\"}', 1, '2026-07-07 05:53:56', '2026-07-07 05:53:56'),
(7041, 1165, 'explanation', '{\"bullets\": [\"Hãy từ bỏ suy nghĩ nói \\\"Không\\\" là ích kỷ hay từ chối tình cảm của đối phương.\", \"Thực chất, nói \\\"Không\\\" với những điều bạn không muốn giúp bạn nói \\\"Có\\\" đầy nhiệt huyết với những điều bạn thực sự trân trọng.\", \"Ranh giới rõ ràng tạo nên sự tôn trọng lành mạnh giữa hai bên.\"]}', 2, '2026-07-07 05:53:56', '2026-07-07 05:53:56'),
(7042, 1165, 'scenario', '{\"title\": \"Tình huống suy ngẫm\", \"body\": \"Vy đồng ý làm bài tập hộ Nam dù cô đang rất bận ôn thi, chỉ vì sợ Nam sẽ nghĩ mình ích kỷ. Sau đó Vy thi trượt vì thiếu thời gian ôn bài.\"}', 3, '2026-07-07 05:53:56', '2026-07-07 05:53:56'),
(7043, 1165, 'interaction', '{\"question\": \"Hậu quả của việc Vy không dám nói \\\"Không\\\" là gì?\", \"choices\": [{\"text\": \"Vy được Nam yêu quý hơn và mối quan hệ trở nên vô cùng tốt đẹp.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Vy tự gây tổn hại đến kết quả học tập và năng lượng của chính mình.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 05:53:56', '2026-07-07 05:53:56'),
(7044, 1165, 'reflection', '{\"question\": \"Bạn có cảm thấy mệt mỏi khi luôn phải gật đầu đồng ý với mọi yêu cầu của bạn bè không?\"}', 5, '2026-07-07 05:53:56', '2026-07-07 05:53:56'),
(7045, 1165, 'takeaway', '{\"items\": [\"Nói \\\"Không\\\" khi cần thiết là cách bạn tự bảo vệ và trân trọng giá trị của bản thân.\"]}', 6, '2026-07-07 05:53:56', '2026-07-07 05:53:56'),
(7046, 1166, 'hook', '{\"title\": \"Lợi ích lớn nhất của ranh giới cá nhân là gì?\"}', 1, '2026-07-07 05:53:56', '2026-07-07 05:53:56'),
(7047, 1166, 'explanation', '{\"bullets\": [\"Ranh giới cá nhân rõ ràng giúp loại bỏ những hiểu lầm, ấm ức và tị nạnh ngầm.\", \"Khi cả hai đều biết giới hạn của nhau, tụi mình sẽ hành xử tôn trọng và an tâm hơn.\", \"Niềm tin sâu sắc chỉ được xây dựng khi ranh giới của mỗi người được tôn trọng tuyệt đối.\"]}', 2, '2026-07-07 05:53:56', '2026-07-07 05:53:56'),
(7048, 1166, 'scenario', '{\"title\": \"Tình huống đúc kết\", \"body\": \"Sau khi thống nhất rõ ràng về thời gian riêng tư và ranh giới đồ đạc cá nhân, tình bạn giữa Hoa và Vy trở nên bền vững và thoải mái hơn bao giờ hết.\"}', 3, '2026-07-07 05:53:56', '2026-07-07 05:53:56'),
(7049, 1166, 'interaction', '{\"question\": \"Chìa khóa giúp tình bạn của Hoa và Vy thăng hoa là gì?\", \"choices\": [{\"text\": \"Sự nhường nhịn mù quáng và không bao giờ nói ra những khó chịu của mình.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Sự thiết lập và tôn trọng ranh giới cá nhân rõ ràng từ cả hai phía.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:56', '2026-07-07 05:53:56'),
(7050, 1166, 'reflection', '{\"question\": \"Bạn sẽ thảo luận ranh giới cá nhân nào với người bạn thân của mình trong tuần này?\"}', 5, '2026-07-07 05:53:56', '2026-07-07 05:53:56'),
(7051, 1166, 'takeaway', '{\"items\": [\"Ranh giới rõ ràng tạo nên sự tôn trọng bền vững và nuôi dưỡng tình bạn đích thực.\"]}', 6, '2026-07-07 05:53:56', '2026-07-07 05:53:56'),
(7052, 1167, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Ranh giới, Tôn trọng & Niềm tin\'! Hãy cùng bảo vệ ranh giới cá nhân nhé.\"}', 1, '2026-07-07 05:53:57', '2026-07-07 05:53:57'),
(7053, 1167, 'scenario-choice', '{\"title\": \"Đường biên giới vô hình\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn thân đột ngột lấy trộm nhật ký của bạn đọc trộm rồi cười: \'Thân nhau có gì phải giấu!\'. Bạn làm sao?\", \"choices\": [{\"text\": \"Cười trừ cho qua chuyện vì ngại làm bạn buồn.\", \"nextNode\": \"fail_step1\"}, {\"text\": \"Dứt khoát lấy lại nhật ký và bảo vệ ranh giới riêng tư.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Bạn thân giận dỗi bảo: \'Cậu ích kỷ thế, có tí nhật ký cũng giấu\'.\", \"choices\": [{\"text\": \"Cãi nhau lớn tiếng bảo bạn là kẻ vô giáo dục.\", \"nextNode\": \"fail_step2\"}, {\"text\": \"Giải thích ôn hòa: \'Tớ rất quý cậu, nhưng nhật ký là không gian riêng tư của tớ. Tớ cần cậu tôn trọng điều đó\'.\", \"nextNode\": \"step3\"}]}, \"step3\": {\"text\": \"Bạn thân vẫn lầm bầm tức giận và không nói chuyện suốt cả buổi học.\", \"choices\": [{\"text\": \"Sợ quá nên đưa nhật ký cho bạn đọc để xin lỗi.\", \"nextNode\": \"fail_step3\"}, {\"text\": \"Cho bạn thời gian suy nghĩ, kiên định giữ vững ranh giới.\", \"nextNode\": \"step4\"}]}, \"step4\": {\"text\": \"Hôm sau bạn thân nguôi giận và chủ động xin lỗi vì đã lục lọi đồ riêng của bạn.\", \"choices\": [{\"text\": \"Tiếp tục giận dỗi để trả đũa bạn.\", \"nextNode\": \"fail_step4\"}, {\"text\": \"Mở lòng tha thứ và khẳng định lại tình bạn bền vững.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã bảo vệ thành công ranh giới riêng tư mà vẫn giữ được sự tôn trọng!\", \"isEnd\": true, \"isSuccess\": true}, \"fail_step1\": {\"text\": \"❌ Thất bại! Để bạn lục lọi đồ riêng tư làm mất ranh giới cá nhân.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_step2\": {\"text\": \"❌ Thất bại! Xúc phạm cá nhân chỉ làm mâu thuẫn bùng phát dữ dội.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_step3\": {\"text\": \"❌ Thất bại! Nhượng bộ phút chót làm mất đi giá trị ranh giới bạn vừa đặt ra.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_step4\": {\"text\": \"❌ Thất bại! Trả đũa làm hỏng cơ hội làm hòa quý giá.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-07 05:53:57', '2026-07-07 05:53:57'),
(7054, 1167, 'sorting', '{\"instruction\": \"Phân loại các hành vi vào đúng hộp Tôn trọng ranh giới hoặc Xâm phạm ranh giới.\", \"leftBox\": {\"title\": \"Tôn trọng ranh giới\"}, \"rightBox\": {\"title\": \"Xâm phạm ranh giới\"}, \"items\": [{\"text\": \"Hỏi ý kiến trước khi chạm vào tóc hay vai bạn.\", \"correctBox\": \"left\"}, {\"text\": \"Tự tiện lục lọi cặp sách của bạn để lấy bút.\", \"correctBox\": \"right\"}, {\"text\": \"Nhấp nhận lời từ chối đi chơi của bạn một cách vui vẻ.\", \"correctBox\": \"left\"}, {\"text\": \"Giật điện thoại của bạn đòi xem tin nhắn riêng tư.\", \"correctBox\": \"right\"}, {\"text\": \"Gõ cửa trước khi vào phòng riêng của bạn.\", \"correctBox\": \"left\"}, {\"text\": \"Ép buộc bạn phải chia sẻ mật khẩu tài khoản mạng xã hội.\", \"correctBox\": \"right\"}, {\"text\": \"Tôn trọng sở thích ăn uống khác biệt của bạn.\", \"correctBox\": \"left\"}, {\"text\": \"Ôm chầm lấy bạn khi thấy bạn đang co vai né tránh.\", \"correctBox\": \"right\"}, {\"text\": \"Giữ khoảng cách giao tiếp lịch sự nơi công cộng.\", \"correctBox\": \"left\"}, {\"text\": \"Nói xấu bạn sau lưng khi bị bạn từ chối.\", \"correctBox\": \"right\"}]}', 3, '2026-07-07 05:53:57', '2026-07-07 05:53:57'),
(7055, 1167, 'matching', '{\"instruction\": \"Ghép cặp ranh giới và định nghĩa phù hợp.\", \"pairs\": [{\"left\": \"Ranh giới thể chất\", \"right\": \"Giới hạn về đụng chạm cơ thể và khoảng cách an toàn.\"}, {\"left\": \"Ranh giới thông tin\", \"right\": \"Quyền bảo mật tin nhắn, nhật ký và tài khoản.\"}, {\"left\": \"Ranh giới thời gian\", \"right\": \"Giới hạn về lịch trình học tập và nghỉ ngơi riêng.\"}, {\"left\": \"Nói Không\", \"right\": \"Quyền từ chối những điều khiến bản thân uncomfy.\"}, {\"left\": \"Linh cảm\", \"right\": \"Chiếc ra-đa báo động cơ thể khi ranh giới bị đe dọa.\"}, {\"left\": \"Đồng thuận F.R.I.E.S\", \"right\": \"Nguyên tắc đồng ý tự nguyện và có thể thay đổi.\"}, {\"left\": \"Sự tôn trọng\", \"right\": \"Việc thừa nhận quyền tự do cá nhân của đối phương.\"}, {\"left\": \"Lòng tin\", \"right\": \"Sự an tâm được xây dựng từ việc tôn trọng giới hạn.\"}]}', 4, '2026-07-07 05:53:57', '2026-07-07 05:53:57'),
(7056, 1167, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp vào chỗ trống trong đoạn văn sau.\", \"sentence\": \"Ranh giới cá nhân là giới hạn đỏ giúp bạn bảo vệ sự an [blank1] của chính mình. Thiết lập ranh giới không phải là hành vi ích kỷ, mà là cách giúp người khác hiểu cách [blank2] bạn. Khi ai đó tự ý đụng chạm cơ thể hoặc lục lọi đồ riêng tư, cơ thể bạn sẽ phát đi tín hiệu báo [blank3] qua linh cảm. Hãy kiên định nói lời từ [blank4] dứt khoát trước những hành vi gây uncomfy. Tôn trọng ranh giới của đối phương là bước đầu tiên để xây dựng lòng [blank5] sâu sắc.\", \"blanks\": {\"blank1\": {\"correct\": \"toàn\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"tôn trọng\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"động\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"chối\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"tin\", \"placeholder\": \"...\"}}, \"words\": [\"toàn\", \"tôn trọng\", \"động\", \"chối\", \"tin\", \"hại\", \"thường\", \"nghi ngờ\", \"nhượng bộ\", \"chấp nhận\"]}', 5, '2026-07-07 05:53:57', '2026-07-07 05:53:57'),
(7057, 1167, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp vào chỗ trống trong đoạn văn sau.\", \"sentence\": \"Trong tình bạn thân thiết, việc giữ lại khoảng không gian riêng [blank1] là quyền chính đáng của mỗi người. Việc đòi hỏi xem tin nhắn hay chia sẻ [blank2] tài khoản thể hiện sự thiếu tin tưởng độc hại. Bạn hoàn toàn có quyền nói không mà không cần cảm thấy [blank3] lỗi vô lý. Sự đồng ý hay đồng [blank4] phải luôn dựa trên tinh thần tự nguyện và có thể thay đổi bất cứ lúc nào. Một tình bạn bền vững chỉ tồn tại khi ranh giới của nhau được giữ [blank5].\", \"blanks\": {\"blank1\": {\"correct\": \"tư\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"mật khẩu\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"tội\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"thuận\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"vững\", \"placeholder\": \"...\"}}, \"words\": [\"tư\", \"mật khẩu\", \"tội\", \"thuận\", \"vững\", \"chung\", \"hình ảnh\", \"án\", \"phá\", \"lỏng\"]}', 6, '2026-07-07 05:53:57', '2026-07-07 05:53:57'),
(7058, 1167, 'interaction', '{\"question\": \"Khi bạn thân muốn xem nhật ký cá nhân của bạn, cách xử lý nào đúng đắn?\", \"choices\": [{\"text\": \"Nhẹ nhàng từ chối và giải thích nhật ký là không gian riêng tư của bạn.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Đưa cho bạn đọc vì sợ bạn nghĩ mình giấu giếm chuyện xấu.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 7, '2026-07-07 05:53:57', '2026-07-07 05:53:57'),
(7059, 1167, 'interaction', '{\"question\": \"Tại sao đặt ranh giới cá nhân lại giúp tình bạn bền vững hơn?\", \"choices\": [{\"text\": \"Vì nó giúp hai bạn hiểu rõ giới hạn của nhau để tránh gây tổn thương.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Vì nó tạo ra khoảng cách lớn khiến hai bạn ít cãi nhau hơn.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 8, '2026-07-07 05:53:57', '2026-07-07 05:53:57'),
(7060, 1167, 'interaction', '{\"question\": \"Biểu hiện nào là cờ xanh tôn trọng ranh giới thể chất?\", \"choices\": [{\"text\": \"Luôn hỏi ý kiến trước khi ôm hoặc khoác vai bạn bè.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Ôm chặt bạn khi bạn đang cố đẩy ra để trêu đùa.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 9, '2026-07-07 05:53:57', '2026-07-07 05:53:57'),
(7061, 1167, 'interaction', '{\"question\": \"Bạn nên làm gì nếu cảm thấy áy náy khi nói \'Không\' với lời nhờ vả quá sức?\", \"choices\": [{\"text\": \"Hiểu rằng từ chối khi quá tải là tự bảo vệ sức khỏe và năng lượng cá nhân.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Cố gắng làm hộ bạn rồi ấm ức đổ bệnh.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 10, '2026-07-07 05:53:57', '2026-07-07 05:53:57'),
(7062, 1167, 'interaction', '{\"question\": \"Nguyên tắc F.R.I.E.S của đồng thuận nhấn mạnh điều gì?\", \"choices\": [{\"text\": \"Sự đồng ý phải tự nguyện, tỉnh táo, rõ ràng và có thể rút lại bất cứ lúc nào.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Sự đồng ý một lần sẽ có giá trị mãi mãi trong mọi trường hợp sau này.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 11, '2026-07-07 05:53:57', '2026-07-07 05:53:57'),
(7063, 1168, 'hook', '{\"title\": \"Cãi nhau có phải là dấu hiệu của việc sắp chia tay/nghỉ chơi?\"}', 1, '2026-07-07 05:53:58', '2026-07-07 05:53:58'),
(7064, 1168, 'explanation', '{\"bullets\": [\"Bất đồng quan điểm là hoàn toàn tự nhiên khi hai người có cá tính khác nhau ở cạnh nhau.\", \"Không phải cứ cãi nhau là mối quan hệ tồi tệ.\", \"Quan trọng là cách tụi mình đối mặt và giải quyết bất đồng đó như thế nào.\"]}', 2, '2026-07-07 05:53:58', '2026-07-07 05:53:58'),
(7065, 1168, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Vy và Hoa cãi nhau nảy lửa chỉ vì bất đồng ý kiến về địa điểm đi dã ngoại cuối tuần của lớp. Cả hai đều rất tức giận.\"}', 3, '2026-07-07 05:53:58', '2026-07-07 05:53:58'),
(7066, 1168, 'interaction', '{\"question\": \"Bất đồng này nên được nhìn nhận thế nào cho lành mạnh?\", \"choices\": [{\"text\": \"Là dấu hiệu cho thấy tình bạn của hai người đã đến hồi kết thúc.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Là cơ hội để cả hai cùng lắng nghe quan điểm khác biệt và tìm điểm chung.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:58', '2026-07-07 05:53:58'),
(7067, 1168, 'reflection', '{\"question\": \"Lần gần nhất bạn cãi nhau với bạn thân là về chuyện gì và hai bạn đã làm hòa thế nào?\"}', 5, '2026-07-07 05:53:58', '2026-07-07 05:53:58'),
(7068, 1168, 'takeaway', '{\"items\": [\"Xung đột là bình thường, cách tụi mình ứng xử trước xung đột mới quyết định mối quan hệ.\"]}', 6, '2026-07-07 05:53:58', '2026-07-07 05:53:58'),
(7069, 1169, 'hook', '{\"title\": \"Bạn là \\\"chiến thần đối đầu\\\" hay \\\"kẻ trốn chạy\\\" khi có cự cãi?\"}', 1, '2026-07-07 05:53:58', '2026-07-07 05:53:58'),
(7070, 1169, 'explanation', '{\"bullets\": [\"Có người lập tức xù lông tranh cãi để giành phần thắng (Phong cách Đối đầu).\", \"Có người chọn cách im lặng, né tránh hoặc chặn liên lạc (Phong cách Né tránh).\", \"Giao tiếp lành mạnh hướng tới phong cách Cộng tác: Cùng ngồi lại tìm giải pháp chung.\"]}', 2, '2026-07-07 05:53:58', '2026-07-07 05:53:58'),
(7071, 1169, 'scenario', '{\"title\": \"Tình huống ứng xử\", \"body\": \"Khi Quân góp ý về việc Huy làm bài tập nhóm muộn, Huy lập tức lớn tiếng quát tháo và bỏ về giữa chừng.\"}', 3, '2026-07-07 05:53:58', '2026-07-07 05:53:58'),
(7072, 1169, 'interaction', '{\"question\": \"Huy đang thể hiện phong cách giải quyết xung đột nào?\", \"choices\": [{\"text\": \"Phong cách Cộng tác và tìm kiếm giải pháp thắng - thắng.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Phong cách Đối đầu tiêu cực và né tránh giải quyết vấn đề trực diện.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:58', '2026-07-07 05:53:58'),
(7073, 1169, 'reflection', '{\"question\": \"Khi có mâu thuẫn, phản xạ tự nhiên đầu tiên của bạn là gì?\"}', 5, '2026-07-07 05:53:58', '2026-07-07 05:53:58'),
(7074, 1169, 'takeaway', '{\"items\": [\"Nhận diện phản xạ của bản thân là bước đầu tiên để rèn luyện kỹ năng kiểm soát cơn giận.\"]}', 6, '2026-07-07 05:53:58', '2026-07-07 05:53:58'),
(7075, 1170, 'hook', '{\"title\": \"Tại sao tụi mình thường nói những câu gây tổn thương sâu sắc khi giận dữ?\"}', 1, '2026-07-07 05:53:59', '2026-07-07 05:53:59'),
(7076, 1170, 'explanation', '{\"bullets\": [\"Khi tức giận, phần não cảm xúc (hạch hạnh nhân) sẽ tạm thời kiểm soát não bộ, khóa chặt lý trí.\", \"Mọi lời nói phát ra lúc này thường mang tính tấn công và hủy hoại mối quan hệ.\", \"Đừng bao giờ giải quyết xung đột hay đưa ra quyết định khi cơn giận đang ở đỉnh điểm.\"]}', 2, '2026-07-07 05:53:59', '2026-07-07 05:53:59'),
(7077, 1170, 'scenario', '{\"title\": \"Tình huống căng thẳng\", \"body\": \"Vy phát hiện Nam quên hẹn đi chơi phim. Trong cơn giận dữ tột độ, Vy nhắn tin sỉ nhục Nam là kẻ vô tích sự và tồi tệ.\"}', 3, '2026-07-07 05:53:59', '2026-07-07 05:53:59'),
(7078, 1170, 'interaction', '{\"question\": \"Hậu quả của việc Vy nhắn tin trong cơn giận dữ là gì?\", \"choices\": [{\"text\": \"Giúp Nam nhận ra lỗi lầm và lập tức sửa đổi một cách vui vẻ.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Gây tổn thương nghiêm trọng đến lòng tự trọng của Nam và làm rạn nứt mối quan hệ.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:59', '2026-07-07 05:53:59'),
(7079, 1170, 'reflection', '{\"question\": \"Bạn từng nói lời hối hận nào trong một cơn giận dữ chưa?\"}', 5, '2026-07-07 05:53:59', '2026-07-07 05:53:59'),
(7080, 1170, 'takeaway', '{\"items\": [\"Cơn giận chỉ kéo dài vài phút, nhưng lời nói lúc giận có thể gây tổn thương cả đời.\"]}', 6, '2026-07-07 05:53:59', '2026-07-07 05:53:59'),
(7081, 1171, 'hook', '{\"title\": \"Làm sao để dập tắt ngọn lửa tranh cãi khi câu chuyện bắt đầu đi quá xa?\"}', 1, '2026-07-07 05:53:59', '2026-07-07 05:53:59'),
(7082, 1171, 'explanation', '{\"bullets\": [\"Khi thấy cuộc nói chuyện bắt đầu xuất hiện tiếng quát tháo hay chỉ trích cá nhân.\", \"Hãy chủ động đề xuất tạm dừng: \\\"Tụi mình đều đang nóng giận, hãy nghỉ 15 phút rồi nói tiếp nhé\\\".\", \"Khoảng nghỉ giúp phần não lý trí hoạt động trở lại để tìm giải pháp ôn hòa.\"]}', 2, '2026-07-07 05:53:59', '2026-07-07 05:53:59'),
(7083, 1171, 'scenario', '{\"title\": \"Tình huống mâu thuẫn\", \"body\": \"Trong buổi thảo luận nhóm, Linh và Tuấn liên tục cướp lời và lớn tiếng chỉ trích ý kiến của nhau trước mặt cả nhóm.\"}', 3, '2026-07-07 05:53:59', '2026-07-07 05:53:59'),
(7084, 1171, 'interaction', '{\"question\": \"Hành động nào của nhóm trưởng là sáng suốt nhất lúc này?\", \"choices\": [{\"text\": \"Để hai bạn tiếp tục cãi nhau xem ai là người lý lẽ hơn.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Yêu cầu cả hai tạm dừng thảo luận, nghỉ giải lao 10 phút để uống nước và bình tĩnh lại.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:53:59', '2026-07-07 05:53:59'),
(7085, 1171, 'reflection', '{\"question\": \"Bạn có dám là người đầu tiên nói câu \\\"Hãy tạm dừng một chút\\\" khi thấy cuộc cãi vã căng thẳng không?\"}', 5, '2026-07-07 05:53:59', '2026-07-07 05:53:59'),
(7086, 1171, 'takeaway', '{\"items\": [\"Tạm dừng cuộc cãi vã khi nóng giận là biểu hiện của sự thông minh và trưởng thành.\"]}', 6, '2026-07-07 05:53:59', '2026-07-07 05:53:59'),
(7087, 1172, 'hook', '{\"title\": \"Làm thế nào để kiểm soát con quái vật giận dữ bên trong bạn?\"}', 1, '2026-07-07 05:53:59', '2026-07-07 05:53:59'),
(7088, 1172, 'explanation', '{\"bullets\": [\"Bước 1: **Dừng lại** - Không nói, không nhắn tin, hít thở sâu 3 nhịp.\", \"Bước 2: **Gọi tên cảm xúc** - Tự nhủ: \\\"Mình đang rất giận dữ vì việc này\\\".\", \"Bước 3: **Chuyển hướng** - Đi rửa mặt bằng nước lạnh hoặc đi dạo vài phút trước khi nói chuyện.\", \"Thực hiện đúng 3 bước này giúp bạn giành lại quyền kiểm soát hành vi từ cơn giận.\"]}', 2, '2026-07-07 05:54:00', '2026-07-07 05:54:00'),
(7089, 1172, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Sơn phát hiện bạn thân tự ý mượn xe đạp của mình mà không hỏi trước. Sơn cảm thấy máu nóng bốc lên mặt và muốn đấm bạn.\"}', 3, '2026-07-07 05:54:00', '2026-07-07 05:54:00'),
(7090, 1172, 'interaction', '{\"question\": \"Sơn nên thực hiện kỹ năng nào để xử lý cơn giận lành mạnh?\", \"choices\": [{\"text\": \"Lao vào quát mắng và đẩy ngã bạn để đòi lại xe ngay lập tức.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Dừng lại, hít thở sâu, tự nhủ mình đang giận, đi rửa mặt rồi mới ra hỏi chuyện bạn một cách bình tĩnh.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:54:00', '2026-07-07 05:54:00'),
(7091, 1172, 'reflection', '{\"question\": \"Kỹ thuật nào giúp bạn bình tĩnh lại nhanh nhất khi cảm thấy tức giận?\"}', 5, '2026-07-07 05:54:00', '2026-07-07 05:54:00'),
(7092, 1172, 'takeaway', '{\"items\": [\"Kiểm soát cơn giận là cách bạn làm chủ bản thân, không để cảm xúc nhất thời dẫn dắt hành vi.\"]}', 6, '2026-07-07 05:54:00', '2026-07-07 05:54:00'),
(7093, 1173, 'hook', '{\"title\": \"Hành vi giận dỗi của bạn có đang vô tình gây độc hại?\"}', 1, '2026-07-07 05:54:00', '2026-07-07 05:54:00'),
(7094, 1173, 'explanation', '{\"bullets\": [\"Hãy trung thực đánh giá cách bạn ứng xử khi giận dỗi bạn bè hay người thân.\", \"Có phải bạn thường chặn Facebook, hủy kết bạn, hoặc im lặng phớt lờ họ không?\", \"Những hành vi này là biểu hiện của sự thiếu chín chắn và làm tổn thương lòng tin.\", \"Hãy học cách nói thẳng cảm xúc của mình thay vì dùng chiêu trò trừng phạt cảm xúc.\"]}', 2, '2026-07-07 05:54:00', '2026-07-07 05:54:00'),
(7095, 1173, 'scenario', '{\"title\": \"Tình huống suy ngẫm\", \"body\": \"Hoa giận Lâm nên đã lập tức hủy kết bạn, chặn số điện thoại và đăng status ẩn ý nói xấu Lâm trên trang cá nhân.\"}', 3, '2026-07-07 05:54:00', '2026-07-07 05:54:00'),
(7096, 1173, 'interaction', '{\"question\": \"Hành động của Hoa có giúp giải quyết mâu thuẫn không?\", \"choices\": [{\"text\": \"Có, vì nó bắt Lâm phải nhận ra lỗi lầm và đi tìm Hoa xin lỗi.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Không, nó chỉ đẩy mâu thuẫn đi xa hơn và chặn đứng cơ hội đối thoại ôn hòa.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 05:54:00', '2026-07-07 05:54:00'),
(7097, 1173, 'reflection', '{\"question\": \"Bạn từng dùng sự im lặng hay mạng xã hội để trừng phạt cảm xúc của ai đó chưa?\"}', 5, '2026-07-07 05:54:00', '2026-07-07 05:54:00'),
(7098, 1173, 'takeaway', '{\"items\": [\"Giao tiếp trực diện, chân thành là cách duy nhất để tháo gỡ mâu thuẫn tận gốc.\"]}', 6, '2026-07-07 05:54:00', '2026-07-07 05:54:00'),
(7099, 1174, 'hook', '{\"title\": \"Làm thế nào để cùng nhau vượt qua giông bão mâu thuẫn?\"}', 1, '2026-07-07 05:54:00', '2026-07-07 05:54:00'),
(7100, 1174, 'explanation', '{\"bullets\": [\"Hãy nhớ công thức: **Bạn + Đối phương vs. Vấn đề**, không phải **Bạn vs. Đối phương**.\", \"Xung đột được giải quyết triệt để khi cả hai cùng đứng về một phía để giải quyết vấn đề chung.\", \"Tôn trọng, lắng nghe và cùng thỏa hiệp là chìa khóa tháo gỡ mọi nút thắt.\"]}', 2, '2026-07-07 05:54:00', '2026-07-07 05:54:00'),
(7101, 1174, 'scenario', '{\"title\": \"Tình huống đúc kết\", \"body\": \"Sau khi cùng ngồi lại, lắng nghe khó khăn của nhau và thống nhất phương án làm bài tập nhóm mới, tình bạn của Đức và Mai đã khôi phục và bền chặt hơn trước.\"}', 3, '2026-07-07 05:54:01', '2026-07-07 05:54:01'),
(7102, 1174, 'interaction', '{\"question\": \"Tư duy đúng đắn giúp Đức và Mai giải quyết mâu thuẫn thành công là gì?\", \"choices\": [{\"text\": \"Đức cố gắng chứng minh lỗi hoàn toàn thuộc về Mai.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Cả hai cùng đứng về một phía, coi mâu thuẫn là vấn đề chung cần cùng nhau giải quyết.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:54:01', '2026-07-07 05:54:01'),
(7103, 1174, 'reflection', '{\"question\": \"Bạn sẽ áp dụng tư duy \\\"cùng giải quyết vấn đề\\\" này vào mâu thuẫn nào của mình trong tuần này?\"}', 5, '2026-07-07 05:54:01', '2026-07-07 05:54:01'),
(7104, 1174, 'takeaway', '{\"items\": [\"Đối thoại tôn trọng và tư duy cộng tác biến xung đột thành cơ hội để thấu hiểu nhau hơn.\"]}', 6, '2026-07-07 05:54:01', '2026-07-07 05:54:01'),
(7105, 1175, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Kỹ năng Giải quyết Xung đột\'! Cùng tháo gỡ mâu thuẫn bằng tư duy cộng tác nhé.\"}', 1, '2026-07-07 05:54:01', '2026-07-07 05:54:01'),
(7106, 1175, 'scenario-choice', '{\"title\": \"Hạ nhiệt cơn giận\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn phát hiện bạn cùng nhóm quên làm phần thuyết trình khiến nhóm bị điểm kém. Bạn rất muốn mắng bạn. Bạn làm sao?\", \"choices\": [{\"text\": \"Lập tức gọi điện quát mắng bạn là kẻ lười biếng, vô trách nhiệm.\", \"nextNode\": \"fail_step1\"}, {\"text\": \"Áp dụng quy tắc dừng lại, hít thở sâu 3 nhịp để bình tĩnh.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Sau khi bình tĩnh, bạn gọi điện hỏi lý do một cách ôn hòa. Bạn đó bảo: \'Tớ bị ốm nằm viện suốt 3 ngày\'.\", \"choices\": [{\"text\": \"Tiếp tục trách móc: \'Ốm thì cũng phải nhắn tin một câu chứ!\'.\", \"nextNode\": \"fail_step2\"}, {\"text\": \"Thấu cảm: \'Ôi vậy hả, cậu đỡ hơn chưa? Sức khỏe quan trọng hơn, bài nhóm để tụi mình tính sau\'.\", \"nextNode\": \"step3\"}]}, \"step3\": {\"text\": \"Bạn đó cảm động và đề xuất xin thầy giáo cho nộp bù vào ngày mai và bạn ấy sẽ tự làm slide chỉnh sửa.\", \"choices\": [{\"text\": \"Từ chối nộp bù và bắt bạn ấy chịu điểm kém một mình.\", \"nextNode\": \"fail_step3\"}, {\"text\": \"Đồng ý cùng nộp bù và phân công lại công việc hợp lý.\", \"nextNode\": \"step4\"}]}, \"step4\": {\"text\": \"Thầy giáo đồng ý cho nộp bù. Nhưng bạn đó lại lo lắng slide thiết kế chưa đẹp.\", \"choices\": [{\"text\": \"Bảo: \'Đã ốm rồi thì làm slide làm gì cho xấu ra\'.\", \"nextNode\": \"fail_step4\"}, {\"text\": \"\'Cậu cứ làm nội dung đi, tớ hỗ trợ chỉnh sửa slide cho đẹp\'.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã giải quyết xung đột bằng sự thấu cảm và cộng tác tuyệt vời!\", \"isEnd\": true, \"isSuccess\": true}, \"fail_step1\": {\"text\": \"❌ Thất bại! Quát mắng trong cơn giận làm tổn thương người bạn đang ốm nặng.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_step2\": {\"text\": \"❌ Thất bại! Thiếu thấu cảm trước bệnh tật của bạn làm rạn nứt tình bạn nghiêm trọng.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_step3\": {\"text\": \"❌ Thất bại! Trừng phạt điểm số làm mất đi cơ hội sửa sai và giải quyết bài nhóm.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_step4\": {\"text\": \"❌ Thất bại! Chê bai năng lực của bạn lúc khó khăn làm mất đi tinh thần đồng đội.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-07 05:54:01', '2026-07-07 05:54:01'),
(7107, 1175, 'sorting', '{\"instruction\": \"Kéo các hành vi giải quyết xung đột vào đúng hộp Lành mạnh hoặc Độc hại.\", \"leftBox\": {\"title\": \"Lành mạnh (Green Flag)\"}, \"rightBox\": {\"title\": \"Độc hại (Red Flag)\"}, \"items\": [{\"text\": \"Đề xuất tạm dừng cuộc họp để hạ nhiệt cơn giận.\", \"correctBox\": \"left\"}, {\"text\": \"Quát to tiếng át tiếng nói của đối phương.\", \"correctBox\": \"right\"}, {\"text\": \"Lắng nghe toàn bộ lý lẽ của bạn trước khi phản hồi.\", \"correctBox\": \"left\"}, {\"text\": \"Hủy kết bạn và chặn liên lạc mạng xã hội.\", \"correctBox\": \"right\"}, {\"text\": \"Tập trung giải quyết vấn đề chung của nhóm.\", \"correctBox\": \"left\"}, {\"text\": \"Chỉ trích lỗi lầm cũ không liên quan.\", \"correctBox\": \"right\"}, {\"text\": \"Sử dụng mệnh đề Tôi để bày tỏ bức xúc.\", \"correctBox\": \"left\"}, {\"text\": \"Xúc phạm danh dự cá nhân của đối phương.\", \"correctBox\": \"right\"}, {\"text\": \"Sẵn sàng thỏa hiệp để tìm giải pháp chung.\", \"correctBox\": \"left\"}, {\"text\": \"Đăng status ẩn ý nói xấu bạn trên trang cá nhân.\", \"correctBox\": \"right\"}]}', 3, '2026-07-07 05:54:01', '2026-07-07 05:54:01'),
(7108, 1175, 'matching', '{\"instruction\": \"Ghép cặp các cơ chế giải quyết mâu thuẫn.\", \"pairs\": [{\"left\": \"Hạch hạnh nhân\", \"right\": \"Phần não cảm xúc dễ kích động khi tức giận.\"}, {\"left\": \"Khoảng nghỉ\", \"right\": \"Việc tạm dừng cuộc trò chuyện để hạ nhiệt cơn nóng.\"}, {\"left\": \"Phong cách cộng tác\", \"right\": \"Tư duy cùng nhau đứng về một phía để xử lý vấn đề.\"}, {\"left\": \"Phong cách đối đầu\", \"right\": \"Cố gắng quát tháo để giành phần thắng về mình.\"}, {\"left\": \"Phong cách né tránh\", \"right\": \"Im lặng phớt lờ mâu thuẫn thay vì nói chuyện.\"}, {\"left\": \"Hít thở sâu\", \"right\": \"Phản xạ sinh học giúp đưa lý trí quay trở lại.\"}, {\"left\": \"Lời xin lỗi\", \"right\": \"Hành động xoa dịu tổn thương thể hiện sự tôn trọng.\"}, {\"left\": \"Giải pháp win-win\", \"right\": \"Kết quả thỏa hiệp mang lại sự hài lòng cho cả hai.\"}]}', 4, '2026-07-07 05:54:01', '2026-07-07 05:54:01'),
(7109, 1175, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp vào chỗ trống trong đoạn văn sau.\", \"sentence\": \"Xung đột trong các mối quan hệ là điều hoàn toàn [blank1]. Khi có bất đồng, cơn giận dễ kích hoạt hạch [blank2] trong não bộ, khiến chúng ta hành xử nóng nảy thiếu lý trí. Để tránh nói ra những lời gây tổn thương, kỹ năng đề xuất tạm [blank3] là cực kỳ quan trọng. Hãy hít thở sâu để đưa lý trí quay trở lại kiểm soát hành vi. Khi cả hai đã bình tĩnh, đối thoại ôn hòa sẽ mở đường cho phong cách cộng [blank4] hiệu quả. Mục tiêu cuối cùng là tìm ra giải pháp chung mang lại sự hài [blank5] cho cả hai.\", \"blanks\": {\"blank1\": {\"correct\": \"tự nhiên\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"hạnh nhân\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"dừng\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"tác\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"lòng\", \"placeholder\": \"...\"}}, \"words\": [\"tự nhiên\", \"hạnh nhân\", \"dừng\", \"tác\", \"lòng\", \"nhân tạo\", \"tránh\", \"hại\", \"thắng\", \"lo\"]}', 5, '2026-07-07 05:54:01', '2026-07-07 05:54:01'),
(7110, 1175, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp vào chỗ trống trong đoạn văn sau.\", \"sentence\": \"Hành vi im lặng chiến tranh [blank1] là cách giải quyết xung đột vô cùng độc hại. Nó không giúp tháo gỡ vấn đề mà chỉ làm xói mòn lòng [blank2] giữa bạn bè. Thay vì chỉ trích bắt đầu bằng từ \'Bạn\', hãy rèn luyện công thức mệnh đề [blank3] để bày tỏ bức xúc cá nhân. Lời xin [blank4] chân thành thể hiện bạn coi trọng mối quan hệ hơn cái tôi của mình. Hãy nhớ công thức vàng: Bạn và đối phương cùng đứng về một phía để giải quyết [blank5] chung.\", \"blanks\": {\"blank1\": {\"correct\": \"lạnh\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"tin\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"Tôi\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"lỗi\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"vấn đề\", \"placeholder\": \"...\"}}, \"words\": [\"lạnh\", \"tin\", \"Tôi\", \"lỗi\", \"vấn đề\", \"nóng\", \"nghi ngờ\", \"Bạn\", \"hại\", \"xung đột\"]}', 6, '2026-07-07 05:54:01', '2026-07-07 05:54:01'),
(7111, 1175, 'interaction', '{\"question\": \"Khi bạn thân làm mất cuốn truyện tranh yêu thích của bạn, phản ứng nào lành mạnh?\", \"choices\": [{\"text\": \"Nói: \'Tớ rất buồn vì mất cuốn truyện đó. Cậu cùng tớ tìm hoặc mua lại cuốn khác nhé.\'.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Quát: \'Cậu là đồ vô trách nhiệm, không bao giờ tớ cho mượn cái gì nữa!\'.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 7, '2026-07-07 05:54:01', '2026-07-07 05:54:01'),
(7112, 1175, 'interaction', '{\"question\": \"Tại sao chúng ta cần tạm dừng cuộc cãi vã khi thấy tim đập nhanh và nóng mặt?\", \"choices\": [{\"text\": \"Để tránh nói ra những lời cay độc do phần não cảm xúc đang kiểm soát.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Để đối phương nghĩ rằng mình khinh bỉ không thèm nói chuyện.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 8, '2026-07-07 05:54:01', '2026-07-07 05:54:01'),
(7113, 1175, 'interaction', '{\"question\": \"Tư duy đúng đắn nhất khi giải quyết xung đột nhóm là gì?\", \"choices\": [{\"text\": \"Coi xung đột là vấn đề chung của nhóm cần hợp tác giải quyết.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tìm xem ai là người làm sai để đổ toàn bộ lỗi lầm lên đầu họ.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 9, '2026-07-07 05:54:01', '2026-07-07 05:54:01'),
(7114, 1175, 'interaction', '{\"question\": \"Biểu hiện nào là phong cách giải quyết xung đột né tránh độc hại?\", \"choices\": [{\"text\": \"Chặn Facebook, im lặng không nói chuyện và phớt lờ bạn suốt cả tuần.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Cùng ngồi lại thảo luận để tìm ra điểm chung thỏa hiệp.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 10, '2026-07-07 05:54:01', '2026-07-07 05:54:01'),
(7115, 1175, 'interaction', '{\"question\": \"Lời xin lỗi chân thành có ý nghĩa gì lớn nhất?\", \"choices\": [{\"text\": \"Thể hiện sự tôn trọng mối quan hệ và mong muốn khôi phục lòng tin của đối phương.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Thể hiện bạn thừa nhận mình hoàn toàn ngu dại và thua cuộc.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 11, '2026-07-07 05:54:01', '2026-07-07 05:54:01'),
(7116, 1176, 'hook', '{\"title\": \"Khi sự quan tâm biến thành chiếc lồng giam cầm cảm xúc?\"}', 1, '2026-07-07 05:54:02', '2026-07-07 05:54:02'),
(7117, 1176, 'explanation', '{\"bullets\": [\"Nhiều hành vi kiểm soát độc hại thường được ngụy trang dưới vỏ bọc \\\"vì yêu thương, vì lo lắng\\\".\", \"Các cờ đỏ bao gồm: Yêu cầu báo cáo định vị liên tục, đọc tin nhắn riêng tư, cô lập bạn khỏi bạn bè hoặc bắt lỗi dằn vặt liên tục.\", \"Nếu mối quan hệ khiến bạn cảm thấy ngột ngạt, sợ hãi hoặc tội lỗi vô cớ, đó là dấu hiệu bất ổn.\"]}', 2, '2026-07-07 05:54:02', '2026-07-07 05:54:02'),
(7118, 1176, 'scenario', '{\"title\": \"Tình huống cờ đỏ\", \"body\": \"Nam yêu cầu Vy phải gửi ảnh chụp khuôn mặt và vị trí hiện tại mỗi khi đi chơi cùng bạn bè để \\\"đảm bảo Vy được an toàn\\\". Nam sẽ giận dữ nếu Vy phản hồi chậm.\"}', 3, '2026-07-07 05:54:02', '2026-07-07 05:54:02'),
(7119, 1176, 'interaction', '{\"question\": \"Hành vi của Nam là biểu hiện của điều gì?\", \"choices\": [{\"text\": \"Sự lo lắng và chăm sóc chu đáo dành cho người yêu.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Sự kiểm soát độc hại dưới danh nghĩa quan tâm lo lắng.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:54:02', '2026-07-07 05:54:02'),
(7120, 1176, 'reflection', '{\"question\": \"Bạn từng cảm thấy ngột ngạt trong một mối quan hệ vì sự kiểm soát quá mức chưa?\"}', 5, '2026-07-07 05:54:02', '2026-07-07 05:54:02'),
(7121, 1176, 'takeaway', '{\"items\": [\"Yêu thương chân thành mang lại tự do và tin tưởng, không phải sự kiểm soát và giam cầm cảm xúc.\"]}', 6, '2026-07-07 05:54:02', '2026-07-07 05:54:02'),
(7122, 1177, 'hook', '{\"title\": \"Làm sao biết tình bạn/tình yêu của hai bạn đã chạm vạch giới hạn?\"}', 1, '2026-07-07 05:54:02', '2026-07-07 05:54:02'),
(7123, 1177, 'explanation', '{\"bullets\": [\"Một mối quan hệ rơi vào bế tắc khi mọi nỗ lực đối thoại đều thất bại, cãi vã lặp đi lặp lại.\", \"Cảm thấy kiệt sức, lo âu hoặc trầm cảm mỗi khi nghĩ đến việc gặp gỡ đối phương.\", \"Sự im lặng lạnh nhạt kéo dài và cả hai đều không còn muốn cố gắng hàn gắn.\"]}', 2, '2026-07-07 05:54:02', '2026-07-07 05:54:02'),
(7124, 1177, 'scenario', '{\"title\": \"Tình huống bế tắc\", \"body\": \"Mỗi lần gặp nhau, Lâm và Hoa đều cãi vã vì những lý do vụn vặt. Sau đó là chuỗi ngày im lặng lạnh lùng. Cả hai đều thấy vô cùng mệt mỏi và chán nản.\"}', 3, '2026-07-07 05:54:02', '2026-07-07 05:54:02'),
(7125, 1177, 'interaction', '{\"question\": \"Hoa và Lâm nên đối mặt với tình cảnh này thế nào?\", \"choices\": [{\"text\": \"Tiếp tục chịu đựng và hy vọng mọi chuyện sẽ tự động tốt lên mà không cần làm gì.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Cùng ngồi lại đối thoại nghiêm túc để đánh giá xem mối quan hệ này có nên tiếp tục hay dừng lại.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:54:03', '2026-07-07 05:54:03'),
(7126, 1177, 'reflection', '{\"question\": \"Có mối quan hệ nào đang khiến bạn cảm thấy kiệt sức hơn là vui vẻ không?\"}', 5, '2026-07-07 05:54:03', '2026-07-07 05:54:03'),
(7127, 1177, 'takeaway', '{\"items\": [\"Chắp nhận sự bế tắc là bước đầu tiên để đưa ra những quyết định dũng cảm bảo vệ bản thân.\"]}', 6, '2026-07-07 05:54:03', '2026-07-07 05:54:03'),
(7128, 1178, 'hook', '{\"title\": \"Tại sao tụi mình thường chọn ở lại trong một chiếc lồng giam độc hại?\"}', 1, '2026-07-07 05:54:03', '2026-07-07 05:54:03'),
(7129, 1178, 'explanation', '{\"bullets\": [\"Sự quen thuộc và nỗi sợ cô đơn, sợ không tìm được ai khác tốt hơn khiến chúng ta chần chừ.\", \"Nhiều bạn bị thao túng tâm lý (gaslighting) dẫn đến việc tự nghi ngờ cảm xúc của chính mình.\", \"Hãy hiểu rằng: Rời đi là hành động dũng cảm để tự cứu lấy sự an toàn cảm xúc của bản thân.\"]}', 2, '2026-07-07 05:54:03', '2026-07-07 05:54:03'),
(7130, 1178, 'scenario', '{\"title\": \"Tình huống tâm lý\", \"body\": \"Vy bị Nam sỉ nhục nhiều lần, nhưng mỗi lần Vy muốn chia tay Nam đều khóc lóc cầu xin và Vy lại mủi lòng tha thứ vì sợ cô đơn.\"}', 3, '2026-07-07 05:54:03', '2026-07-07 05:54:03'),
(7131, 1178, 'interaction', '{\"question\": \"Vy nên làm gì để thoát khỏi vòng lặp độc hại này?\", \"choices\": [{\"text\": \"Tiếp tục tin lời hứa và tha thứ thêm nhiều lần nữa.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Kiên định cắt đứt mối quan hệ độc hại và tìm kiếm sự hỗ trợ tinh thần từ bạn bè, gia đình.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:54:03', '2026-07-07 05:54:03'),
(7132, 1178, 'reflection', '{\"question\": \"Bạn có từng chần chừ không dám chấm dứt một tình bạn tồi tệ vì sợ cô đơn không?\"}', 5, '2026-07-07 05:54:03', '2026-07-07 05:54:03'),
(7133, 1178, 'takeaway', '{\"items\": [\"Bạn xứng đáng được đối xử bằng sự tôn trọng và yêu thương chân thành, không phải bằng sự thao túng.\"]}', 6, '2026-07-07 05:54:03', '2026-07-07 05:54:03'),
(7134, 1179, 'hook', '{\"title\": \"Trao mật khẩu có phải là minh chứng cho tình yêu đích thực?\"}', 1, '2026-07-07 05:54:03', '2026-07-07 05:54:03'),
(7135, 1179, 'explanation', '{\"bullets\": [\"Mật khẩu tài khoản cá nhân là ranh giới riêng tư tuyệt đối của mỗi người.\", \"Đòi hỏi mật khẩu thể hiện sự thiếu tin tưởng và muốn kiểm soát đối phương.\", \"Một mối quan hệ lành mạnh được xây dựng trên sự tin cậy, không phải trên sự giám sát.\"]}', 2, '2026-07-07 05:54:03', '2026-07-07 05:54:03'),
(7136, 1179, 'scenario', '{\"title\": \"Tình huống đòi mật khẩu\", \"body\": \"Nam yêu cầu Vy đưa mật khẩu Facebook của cô để \\\"chứng minh Vy không nhắn tin mờ ám với bạn nam khác\\\". Nam bảo yêu nhau thì không nên có bí mật.\"}', 3, '2026-07-07 05:54:04', '2026-07-07 05:54:04'),
(7137, 1179, 'interaction', '{\"question\": \"Vy nên ứng xử thế nào trước yêu cầu của Nam?\", \"choices\": [{\"text\": \"Đưa mật khẩu ngay để Nam vui lòng và chứng minh sự trong sạch của mình.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Từ chối thẳng thắn: \\\"Tớ yêu cậu nhưng tài khoản cá nhân là không gian riêng tư của tớ, tụi mình cần tin tưởng nhau thay vì kiểm tra mật khẩu.\\\".\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:54:04', '2026-07-07 05:54:04'),
(7138, 1179, 'reflection', '{\"question\": \"Bạn có nghĩ việc giữ không gian riêng tư là cần thiết trong tình yêu không?\"}', 5, '2026-07-07 05:54:04', '2026-07-07 05:54:04'),
(7139, 1179, 'takeaway', '{\"items\": [\"Tình yêu lành mạnh cần sự tin tưởng tự nguyện, không phải sự giám sát và kiểm soát tài khoản của nhau.\"]}', 6, '2026-07-07 05:54:04', '2026-07-07 05:54:04'),
(7140, 1180, 'hook', '{\"title\": \"Làm sao để nói lời chia tay/nghỉ chơi mà không gây tổn thương hay thù hận?\"}', 1, '2026-07-07 05:54:04', '2026-07-07 05:54:04'),
(7141, 1180, 'explanation', '{\"bullets\": [\"Hãy chọn một địa điểm yên tĩnh, trực tiếp trò chuyện (tránh nhắn tin chia tay qua SMS).\", \"Bày tỏ rõ ràng quyết định của bạn tập trung vào cảm xúc cá nhân bằng mệnh đề \\\"Tôi\\\".\", \"Tôn trọng quá khứ, không nói lời sỉ nhục hay đổ lỗi dồn dập cho đối phương.\", \"Ranh giới sau chia tay rõ ràng để cả hai cùng có thời gian tự chữa lành.\"]}', 2, '2026-07-07 05:54:04', '2026-07-07 05:54:04'),
(7142, 1180, 'scenario', '{\"title\": \"Tình huống chia tay\", \"body\": \"Hoa cảm thấy tình bạn với Lâm không còn lành mạnh nữa và muốn dừng lại. Cô băn khoăn không biết nên làm thế nào.\"}', 3, '2026-07-07 05:54:04', '2026-07-07 05:54:04'),
(7143, 1180, 'interaction', '{\"question\": \"Hoa nên thực hiện hành động nào văn minh nhất?\", \"choices\": [{\"text\": \"Nhắn tin chặn số đột ngột và đi rêu rao nói xấu Lâm với cả lớp.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Gặp mặt trực tiếp, chia sẻ thẳng thắn rằng cảm thấy cả hai không còn hợp nhau nữa và xin phép tạm dừng mối quan hệ.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:54:04', '2026-07-07 05:54:04'),
(7144, 1180, 'reflection', '{\"question\": \"Lần gần nhất bạn kết thúc một mối quan hệ (tình bạn hoặc tình yêu), bạn có hài lòng với cách mình rời đi không?\"}', 5, '2026-07-07 05:54:04', '2026-07-07 05:54:04'),
(7145, 1180, 'takeaway', '{\"items\": [\"Rời đi văn minh là cách bạn tôn trọng những kỷ niệm đẹp đã qua và tự mở ra cơ hội mới cho chính mình.\"]}', 6, '2026-07-07 05:54:04', '2026-07-07 05:54:04'),
(7146, 1181, 'hook', '{\"title\": \"Nhận diện cảm xúc của bản thân khi bị kiểm soát!\"}', 1, '2026-07-07 05:54:04', '2026-07-07 05:54:04'),
(7147, 1181, 'explanation', '{\"bullets\": [\"Cảm xúc của bạn là chiếc la bàn chính xác nhất.\", \"Bạn có thấy lo sợ mỗi khi chuông điện thoại reo vì tin nhắn của người đó?\", \"Bạn có phải liên tục giải thích, xin lỗi vì những chuyện nhỏ nhặt không đáng có?\", \"Hãy lắng nghe tiếng nói bên trong cơ thể bạn để nhận diện sự bất ổn kịp thời.\"]}', 2, '2026-07-07 05:54:04', '2026-07-07 05:54:04'),
(7148, 1181, 'scenario', '{\"title\": \"Tình huống suy ngẫm\", \"body\": \"Vy nhận ra mình luôn cảm thấy hồi hộp, tim đập nhanh và lo sợ mỗi khi Nam gọi điện thoại vì lo sợ sẽ bị Nam quát mắng hay bắt lỗi chuyện gì đó.\"}', 3, '2026-07-07 05:54:04', '2026-07-07 05:54:04'),
(7149, 1181, 'interaction', '{\"question\": \"Cơ thể của Vy đang gửi đi tín hiệu gì?\", \"choices\": [{\"text\": \"Tín hiệu của sự nhớ nhung da diết và tình yêu nồng cháy.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Tín hiệu báo động của sự căng thẳng và bất an trong mối quan hệ.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:54:04', '2026-07-07 05:54:04'),
(7150, 1181, 'reflection', '{\"question\": \"Có mối quan hệ nào khiến bạn cảm thấy bất an hay lo sợ mỗi khi liên lạc không?\"}', 5, '2026-07-07 05:54:05', '2026-07-07 05:54:05'),
(7151, 1181, 'takeaway', '{\"items\": [\"Mối quan hệ lành mạnh mang lại sự bình yên, không phải sự lo âu và căng thẳng triền miên.\"]}', 6, '2026-07-07 05:54:05', '2026-07-07 05:54:05'),
(7152, 1182, 'hook', '{\"title\": \"Điều gì quan trọng hơn việc giữ chân một người bên cạnh bạn?\"}', 1, '2026-07-07 05:54:05', '2026-07-07 05:54:05'),
(7153, 1182, 'explanation', '{\"bullets\": [\"Không có mối quan hệ nào đáng giá để bạn phải đánh đổi sự an toàn cảm xúc của bản thân.\", \"Dũng cảm từ bỏ mối quan hệ độc hại là cách bạn tự trân trọng giá trị của mình.\", \"Hãy luôn đặt sức khỏe tinh thần và sự an tâm của bạn lên vị trí ưu tiên hàng đầu.\"]}', 2, '2026-07-07 05:54:05', '2026-07-07 05:54:05'),
(7154, 1182, 'scenario', '{\"title\": \"Tình huống đúc kết\", \"body\": \"Sau khi kiên quyết chia tay Nam và tập trung vào học tập, Vy cảm thấy cuộc sống trở lại trạng thái nhẹ nhàng, vui vẻ và tự tin hơn trước rất nhiều.\"}', 3, '2026-07-07 05:54:05', '2026-07-07 05:54:05'),
(7155, 1182, 'interaction', '{\"question\": \"Quyết định chia tay của Vy mang lại kết quả gì lớn nhất cho cô?\", \"choices\": [{\"text\": \"Khiến Vy cô đơn suốt đời và không có bạn bè xung quanh.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Giải phóng Vy khỏi sự căng thẳng và khôi phục năng lượng tích cực cho bản thân.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 4, '2026-07-07 05:54:05', '2026-07-07 05:54:05'),
(7156, 1182, 'reflection', '{\"question\": \"Bạn sẽ làm gì hôm nay để bảo vệ sự an toàn cảm xúc của bản thân tốt hơn?\"}', 5, '2026-07-07 05:54:05', '2026-07-07 05:54:05'),
(7157, 1182, 'takeaway', '{\"items\": [\"Bảo vệ sự bình yên trong tâm hồn là trách nhiệm cao nhất của bạn đối với chính mình.\"]}', 6, '2026-07-07 05:54:05', '2026-07-07 05:54:05'),
(7158, 1183, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Vượt qua Thử thách trong Mối quan hệ\'! Hãy cùng vượt qua các bẫy kiểm soát độc hại nhé.\"}', 1, '2026-07-07 05:54:05', '2026-07-07 05:54:05');
INSERT INTO `micro_lesson_blocks` (`id`, `micro_lesson_id`, `block_type`, `content_json`, `order_index`, `created_at`, `updated_at`) VALUES
(7159, 1183, 'scenario-choice', '{\"title\": \"Thoát khỏi lồng giam\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Người yêu yêu cầu bạn chặn kết bạn với tất cả các bạn khác giới trong lớp vì \'yêu thì chỉ được nghĩ đến tớ\'. Bạn chọn gì?\", \"choices\": [{\"text\": \"Đồng ý chặn vì sợ người yêu giận dỗi ghen tuông.\", \"nextNode\": \"fail_step1\"}, {\"text\": \"Từ chối ôn hòa và bảo vệ quyền tự do kết bạn lành mạnh.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Người yêu khóc lóc buộc tội: \'Cậu không còn yêu tớ nữa, cậu đang phản bội tớ!\'.\", \"choices\": [{\"text\": \"Sợ hãi tự trách bản thân và nhượng bộ giao mật khẩu tài khoản cho người yêu kiểm tra.\", \"nextNode\": \"fail_step2\"}, {\"text\": \"Khẳng định tình cảm nhưng giữ vững ranh giới: \'Tớ yêu cậu nhưng tớ cần giữ các mối quan hệ bạn bè bình thường\'.\", \"nextNode\": \"step3\"}]}, \"step3\": {\"text\": \"Người yêu đe dọa: \'Nếu cậu không chặn họ thì tụi mình chia tay đi!\'.\", \"choices\": [{\"text\": \"Sợ cô đơn nên lập tức đồng ý chặn mọi người.\", \"nextNode\": \"fail_step3\"}, {\"text\": \"Nhận diện đây là cờ đỏ thao túng cảm xúc nghiêm trọng, đồng ý chia tay ôn hòa.\", \"nextNode\": \"step4\"}]}, \"step4\": {\"text\": \"Sau chia tay, người yêu liên tục gọi điện quấy rối và dọa tự tử nếu bạn không quay lại.\", \"choices\": [{\"text\": \"Quay lại mối quan hệ vì lo sợ người yêu sẽ làm thật.\", \"nextNode\": \"fail_step4\"}, {\"text\": \"Cảnh giác, báo cáo sự việc với bố mẹ và chặn số điện thoại quấy rối.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã dũng cảm thoát khỏi mối quan hệ kiểm soát độc hại và bảo vệ bản thân an toàn!\", \"isEnd\": true, \"isSuccess\": true}, \"fail_step1\": {\"text\": \"❌ Thất bại! Nhượng bộ ghen tuông vô lý chỉ kích hoạt thêm sự kiểm soát độc hại sau này.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_step2\": {\"text\": \"❌ Thất bại! Giao mật khẩu tài khoản làm mất hoàn toàn ranh giới riêng tư.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_step3\": {\"text\": \"❌ Thất bại! Nhượng bộ vì sợ cô đơn làm bạn tiếp tục bị giam cầm trong lồng giam cảm xúc.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_step4\": {\"text\": \"❌ Thất bại! Quay lại vì bị đe dọa làm bạn tiếp tục bị thao túng tinh thần nặng nề.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-07 05:54:05', '2026-07-07 05:54:05'),
(7160, 1183, 'sorting', '{\"instruction\": \"Kéo các thẻ hành vi vào đúng hộp Green Flag hoặc Red Flag.\", \"leftBox\": {\"title\": \"Green Flag (Lành mạnh)\"}, \"rightBox\": {\"title\": \"Red Flag (Độc hại)\"}, \"items\": [{\"text\": \"Tôn trọng không gian riêng tư và bạn bè cũ của bạn.\", \"correctBox\": \"left\"}, {\"text\": \"Yêu cầu bạn giao mật khẩu Facebook để kiểm tra.\", \"correctBox\": \"right\"}, {\"text\": \"Khích lệ bạn theo đuổi ước mơ vẽ tranh.\", \"correctBox\": \"left\"}, {\"text\": \"Bắt bạn gửi ảnh định vị khuôn mặt liên tục để giám sát.\", \"correctBox\": \"right\"}, {\"text\": \"Lắng nghe và xin lỗi khi nhận ra mình sai.\", \"correctBox\": \"left\"}, {\"text\": \"Thường xuyên đe dọa chia tay để ép bạn nghe lời.\", \"correctBox\": \"right\"}, {\"text\": \"Chấp nhận việc bạn bận ôn thi không đi chơi được.\", \"correctBox\": \"left\"}, {\"text\": \"Cô lập bạn khỏi gia đình và bạn bè thân thiết.\", \"correctBox\": \"right\"}, {\"text\": \"Giao tiếp mắt dịu dàng tôn trọng khi đối thoại.\", \"correctBox\": \"left\"}, {\"text\": \"Thao túng bắt bạn luôn cảm thấy có lỗi vô cớ.\", \"correctBox\": \"right\"}]}', 3, '2026-07-07 05:54:05', '2026-07-07 05:54:05'),
(7161, 1183, 'matching', '{\"instruction\": \"Ghép cặp cờ đỏ và định nghĩa phù hợp.\", \"pairs\": [{\"left\": \"Gaslighting\", \"right\": \"Hành vi thao túng tâm lý khiến bạn nghi ngờ trí nhớ cá nhân.\"}, {\"left\": \"Cô lập\", \"right\": \"Hành vi ngăn cấm bạn tiếp xúc với gia đình, bạn bè.\"}, {\"left\": \"Kiểm soát\", \"right\": \"Đòi hỏi mật khẩu và bắt báo cáo vị trí liên tục.\"}, {\"left\": \"Bạo lực tinh thần\", \"right\": \"Chỉ trích, nhục mạ ngoại hình và lòng tự trọng của bạn.\"}, {\"left\": \"Đe dọa\", \"right\": \"Dùng cái chết hoặc sự tự hủy hoại để ép bạn nhượng bộ.\"}, {\"left\": \"An toàn cảm xúc\", \"right\": \"Ưu tiên hàng đầu cần bảo vệ trong mối quan hệ.\"}, {\"left\": \"Rời đi văn minh\", \"right\": \"Lời chia tay trực tiếp, tôn trọng và dứt khoát.\"}, {\"left\": \"Cờ đỏ\", \"right\": \"Dấu hiệu cảnh báo mối quan hệ độc hại cần cảnh giác.\"}]}', 4, '2026-07-07 05:54:05', '2026-07-07 05:54:05'),
(7162, 1183, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp vào chỗ trống trong đoạn văn sau.\", \"sentence\": \"Một mối quan hệ độc hại thường bắt đầu bằng những hành vi [blank1] núp bóng sự quan tâm chăm sóc. Kẻ kiểm soát sẽ yêu cầu mật khẩu tài khoản hoặc định vị liên tục, nhằm [blank2] bạn khỏi mạng lưới bạn bè thân thiết. Khi bạn bày tỏ sự khó chịu, họ sẽ sử dụng chiêu bài thao túng cảm xúc để bắt bạn cảm thấy có [blank3] vô cớ. Rời bỏ một mối quan hệ độc hại đòi hỏi rất nhiều dũng [blank4] để vượt qua nỗi sợ cô đơn. Hãy nhớ rằng sự an toàn cảm [blank5] luôn là ưu tiên hàng đầu của bản thân.\", \"blanks\": {\"blank1\": {\"correct\": \"kiểm soát\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"cô lập\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"lỗi\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"khí\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"xúc\", \"placeholder\": \"...\"}}, \"words\": [\"kiểm soát\", \"cô lập\", \"lỗi\", \"khí\", \"xúc\", \"yêu\", \"hòa\", \"giúp\", \"sợ\", \"nguy\"]}', 5, '2026-07-07 05:54:05', '2026-07-07 05:54:05'),
(7163, 1183, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp vào chỗ trống trong đoạn văn sau.\", \"sentence\": \"Việc chấm dứt một tình bạn độc hại cần được thực hiện một cách dứt khoát và [blank1]. Tránh việc nhắn tin chia tay qua SMS mà nên gặp gỡ đối thoại [blank2] ôn hòa. Sau khi chia tay, việc thiết lập ranh giới bảo vệ bằng cách chặn liên [blank3] quấy rối là vô cùng cần thiết. Đừng để những lời đe dọa tự hủy hoại của đối phương tiếp tục [blank4] cảm xúc của bạn. Hãy tìm kiếm sự hỗ trợ từ người lớn đáng tin [blank5] để được bảo vệ an toàn.\", \"blanks\": {\"blank1\": {\"correct\": \"văn minh\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"trực tiếp\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"lạc\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"thao túng\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"cậy\", \"placeholder\": \"...\"}}, \"words\": [\"văn minh\", \"trực tiếp\", \"lạc\", \"thao túng\", \"cậy\", \"nhanh\", \"gián tiếp\", \"thù hận\", \"yêu\", \"bỏ\"]}', 6, '2026-07-07 05:54:06', '2026-07-07 05:54:06'),
(7164, 1183, 'interaction', '{\"question\": \"Người yêu nhắn tin: \'Nếu cậu không đưa mật khẩu Instagram, tụi mình chia tay\'. Bạn nên làm gì?\", \"choices\": [{\"text\": \"Từ chối dứt khoát và bảo vệ ranh giới tài khoản cá nhân.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Đưa mật khẩu ngay lập tức vì sợ mất đi mối tình này.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 7, '2026-07-07 05:54:06', '2026-07-07 05:54:06'),
(7165, 1183, 'interaction', '{\"question\": \"Tại sao rời bỏ mối quan hệ độc hại lại đòi hỏi sự kiên định?\", \"choices\": [{\"text\": \"Vì kẻ thao túng thường dùng những lời hứa thay đổi giả tạo hoặc khóc lóc để níu giữ bạn.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Vì mối quan hệ độc hại thực chất mang lại rất nhiều niềm vui.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 8, '2026-07-07 05:54:06', '2026-07-07 05:54:06'),
(7166, 1183, 'interaction', '{\"question\": \"Biểu hiện nào của bạn bè cho thấy họ đang cô lập bạn độc hại?\", \"choices\": [{\"text\": \"Tức giận nói xấu khi bạn đi chơi với các bạn nhóm khác trong lớp.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Vui vẻ rủ bạn cùng tham gia câu lạc bộ học tập mới.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 9, '2026-07-07 05:54:06', '2026-07-07 05:54:06'),
(7167, 1183, 'interaction', '{\"question\": \"Bạn nên xử lý thế nào nếu sau chia tay người yêu cũ liên tục nhắn tin đe dọa làm hại bản thân?\", \"choices\": [{\"text\": \"Chặn số liên lạc, giữ khoảng cách và báo cáo ngay lập tức cho bố mẹ hoặc giáo viên đáng tin cậy.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Lập tức chạy đến xin lỗi và đồng ý quay lại vì lo sợ.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 10, '2026-07-07 05:54:06', '2026-07-07 05:54:06'),
(7168, 1183, 'interaction', '{\"question\": \"Sứ mệnh lớn nhất của việc thiết lập ranh giới sau chia tay là gì?\", \"choices\": [{\"text\": \"Cung cấp thời gian và không gian an toàn để cả hai cùng tự chữa lành chấn thương cảm xúc.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Tiếp tục theo dõi xem đối phương có đau khổ vì mất mình không.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 11, '2026-07-07 05:54:06', '2026-07-07 05:54:06'),
(7169, 1184, 'hook', '{\"title\": \"Tại sao bày tỏ điểm yếu lại là biểu hiện của sức mạnh kết nối?\"}', 1, '2026-07-07 05:54:06', '2026-07-07 05:54:06'),
(7170, 1184, 'explanation', '{\"bullets\": [\"Sự dễ tổn thương (vulnerability) là việc dũng cảm mở lòng nói về những khuyết điểm, nỗi sợ hay mong muốn sâu kín của bản thân.\", \"Khi bạn dám yếu đuối trước mặt ai đó, bạn đang trao cho họ chiếc chìa khóa của niềm tin.\", \"Đây là nền tảng để đưa tình bạn/tình yêu lên mức độ sâu sắc đích thực.\"]}', 2, '2026-07-07 05:54:06', '2026-07-07 05:54:06'),
(7171, 1184, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Sơn lấy hết dũng khí kể với Lâm về việc mình từng bị bắt nạt hồi tiểu học và cảm thấy rất tự ti về ngoại hình của mình.\"}', 3, '2026-07-07 05:54:06', '2026-07-07 05:54:06'),
(7172, 1184, 'interaction', '{\"question\": \"Hành động chia sẻ của Sơn thể hiện điều gì?\", \"choices\": [{\"text\": \"Sự yếu đuối, hèn nhát và muốn tìm kiếm sự thương hại vô lý.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Sự dũng cảm thể hiện khía cạnh dễ tổn thương để xây dựng niềm tin sâu sắc.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:54:06', '2026-07-07 05:54:06'),
(7173, 1184, 'reflection', '{\"question\": \"Đã bao giờ bạn dám khóc hoặc kể về nỗi sợ lớn nhất của mình với một người bạn thân chưa?\"}', 5, '2026-07-07 05:54:06', '2026-07-07 05:54:06'),
(7174, 1184, 'takeaway', '{\"items\": [\"Kết nối đích thực chỉ bắt đầu khi tụi mình dám gỡ bỏ lớp mặt nạ hoàn hảo để đến với nhau bằng sự chân thành.\"]}', 6, '2026-07-07 05:54:07', '2026-07-07 05:54:07'),
(7175, 1185, 'hook', '{\"title\": \"Làm sao biết bạn đang thực sự thấu cảm hay chỉ đang nghe xã giao?\"}', 1, '2026-07-07 05:54:07', '2026-07-07 05:54:07'),
(7176, 1185, 'explanation', '{\"bullets\": [\"Thấu cảm (Empathy) là việc đặt mình vào hoàn cảnh của người khác để cảm nhận nỗi đau hay niềm vui của họ.\", \"Không vội vàng phán xét: \\\"Có thế mà cũng buồn\\\" hay đưa ra lời khuyên sáo rỗng.\", \"Chỉ cần ôm nhẹ hoặc nói câu: \\\"Tớ hiểu cảm giác của cậu lúc này, tớ luôn ở đây cùng cậu\\\".\"]}', 2, '2026-07-07 05:54:07', '2026-07-07 05:54:07'),
(7177, 1185, 'scenario', '{\"title\": \"Tình huống giao tiếp\", \"body\": \"Hoa khóc vì trượt bài thi học sinh giỏi cấp trường. Đức nghe tin liền chạy đến bên Hoa.\"}', 3, '2026-07-07 05:54:07', '2026-07-07 05:54:07'),
(7178, 1185, 'interaction', '{\"question\": \"Đức nên phản hồi thế nào để thể hiện sự thấu cảm tinh tế nhất?\", \"choices\": [{\"text\": \"\\\"Cậu học chưa đủ chăm thôi, lần sau cố gắng học nhiều hơn là được.\\\".\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"\\\"Tớ biết cậu đã nỗ lực rất nhiều cho kỳ thi này. Tớ hiểu cậu đang rất buồn, tớ sẽ ngồi đây cùng cậu nhé.\\\".\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:54:07', '2026-07-07 05:54:07'),
(7179, 1185, 'reflection', '{\"question\": \"Bạn thường chọn cách khuyên bảo hay lắng nghe thấu cảm khi bạn thân tìm đến khóc lóc tâm sự?\"}', 5, '2026-07-07 05:54:07', '2026-07-07 05:54:07'),
(7180, 1185, 'takeaway', '{\"items\": [\"Thấu cảm quan trọng hơn lời khuyên, đôi khi sự hiện diện im lặng cùng nhau là tất cả những gì họ cần.\"]}', 6, '2026-07-07 05:54:07', '2026-07-07 05:54:07'),
(7181, 1186, 'hook', '{\"title\": \"Tại sao việc nói câu \\\"Tớ đang rất sợ\\\" lại khó đến thế?\"}', 1, '2026-07-07 05:54:07', '2026-07-07 05:54:07'),
(7182, 1186, 'explanation', '{\"bullets\": [\"Bản năng tự vệ khiến tụi mình luôn muốn thể hiện hình ảnh mạnh mẽ, hoàn hảo trước mắt mọi người.\", \"Nhưng chia sẻ nỗi sợ hãi thực chất là cách bạn mở ra cơ hội để đối phương được che chở, hỗ trợ bạn.\", \"Một mối quan hệ bền vững không sợ hãi bão giông, chỉ sợ sự im lặng chịu đựng của mỗi người.\"]}', 2, '2026-07-07 05:54:07', '2026-07-07 05:54:07'),
(7183, 1186, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Vy cảm thấy lo sợ tình bạn giữa mình và Hoa sẽ rạn nứt sau khi cả hai chọn học hai trường cấp ba khác nhau, nhưng cô giấu kín nỗi lo này.\"}', 3, '2026-07-07 05:54:07', '2026-07-07 05:54:07'),
(7184, 1186, 'interaction', '{\"question\": \"Vy nên ứng xử thế nào để củng cố tình bạn?\", \"choices\": [{\"text\": \"Tiếp tục giấu kín nỗi lo và âm thầm tạo khoảng cách trước vì sợ bị bỏ rơi.\", \"correct\": false, \"emoji\": \"😐\"}, {\"text\": \"Gặp Hoa tâm sự: \\\"Tớ hơi lo hai đứa học khác trường sẽ ít gặp nhau, tụi mình lên kế hoạch hẹn hò cuối tuần nhé.\\\".\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:54:07', '2026-07-07 05:54:07'),
(7185, 1186, 'reflection', '{\"question\": \"Có nỗi sợ hãi nào về mối quan hệ hiện tại mà bạn đang giấu kín trong lòng không?\"}', 5, '2026-07-07 05:54:07', '2026-07-07 05:54:07'),
(7186, 1186, 'takeaway', '{\"items\": [\"Chia sẻ nỗi sợ hãi giúp loại bỏ sự hoài nghi và thắt chặt thêm sợi dây gắn kết.\"]}', 6, '2026-07-07 05:54:07', '2026-07-07 05:54:07'),
(7187, 1187, 'hook', '{\"title\": \"Làm sao để tạo ra một không gian chia sẻ an toàn tuyệt đối?\"}', 1, '2026-07-07 05:54:08', '2026-07-07 05:54:08'),
(7188, 1187, 'explanation', '{\"bullets\": [\"Hãy chọn một không gian yên tĩnh, tắt các thiết bị gây xao nhãng.\", \"Cam kết bảo mật tuyệt đối: \\\"Những gì nói ra ở đây sẽ chỉ ở lại giữa hai chúng ta\\\".\", \"Lắng nghe không phán xét, tôn trọng sự riêng tư và cảm xúc của đối phương.\"]}', 2, '2026-07-07 05:54:08', '2026-07-07 05:54:08'),
(7189, 1187, 'scenario', '{\"title\": \"Tình huống chia sẻ\", \"body\": \"Lâm muốn kể cho Sơn nghe về việc mình đang thầm thương trộm nhớ một bạn cùng lớp, nhưng lo lắng sẽ bị Sơn mang ra làm trò đùa trước cả lớp.\"}', 3, '2026-07-07 05:54:08', '2026-07-07 05:54:08'),
(7190, 1187, 'interaction', '{\"question\": \"Sơn nên làm gì để Lâm cảm thấy an tâm chia sẻ bí mật của mình?\", \"choices\": [{\"text\": \"Hứa giữ bí mật nhưng hôm sau vẫn kể đùa vui với vài bạn thân khác.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Lắng nghe nghiêm túc, cam kết giữ bí mật tuyệt đối và đưa ra lời khuyên chân thành nếu Lâm cần.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:54:08', '2026-07-07 05:54:08'),
(7191, 1187, 'reflection', '{\"question\": \"Bạn có người bạn nào tin cậy đến mức sẵn sàng chia sẻ mọi bí mật thầm kín nhất không?\"}', 5, '2026-07-07 05:54:08', '2026-07-07 05:54:08'),
(7192, 1187, 'takeaway', '{\"items\": [\"Niềm tin sâu sắc được xây dựng trên nền tảng của sự bảo mật và tôn trọng bí mật của nhau.\"]}', 6, '2026-07-07 05:54:08', '2026-07-07 05:54:08'),
(7193, 1188, 'hook', '{\"title\": \"Làm sao để bạn bè tự động mở lòng tâm sự mà không cảm thấy bị thẩm vấn?\"}', 1, '2026-07-07 05:54:08', '2026-07-07 05:54:08'),
(7194, 1188, 'explanation', '{\"bullets\": [\"Tránh đặt những câu hỏi Có/Không đóng khung cuộc thoại (\\\"Cậu có buồn không?\\\").\", \"Hãy đặt câu hỏi mở bắt đầu bằng \\\"Thế nào\\\", \\\"Tại sao\\\" hoặc \\\"Cảm giác của cậu ra sao\\\".\", \"Ví dụ: \\\"Chuyện đó xảy ra thế nào?\\\" hoặc \\\"Cậu cảm thấy thế nào về quyết định đó?\\\".\"]}', 2, '2026-07-07 05:54:08', '2026-07-07 05:54:08'),
(7195, 1188, 'scenario', '{\"title\": \"Tình huống thực tế\", \"body\": \"Vy biết Hoa vừa gặp chuyện buồn ở lớp vẽ, Vy muốn hỏi thăm nhưng sợ làm Hoa khó chịu.\"}', 3, '2026-07-07 05:54:08', '2026-07-07 05:54:08'),
(7196, 1188, 'interaction', '{\"question\": \"Vy nên dùng câu hỏi nào để gợi mở tâm sự tinh tế nhất?\", \"choices\": [{\"text\": \"\\\"Cậu lại cãi nhau với thầy giáo à?\\\".\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"\\\"Hôm nay ở lớp vẽ có chuyện gì thế cậu? Cậu cảm thấy thế nào rồi?\\\".\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:54:08', '2026-07-07 05:54:08'),
(7197, 1188, 'reflection', '{\"question\": \"Bạn thường dùng câu hỏi đóng hay câu hỏi mở khi trò chuyện với bạn bè của mình?\"}', 5, '2026-07-07 05:54:08', '2026-07-07 05:54:08'),
(7198, 1188, 'takeaway', '{\"items\": [\"Đặt câu hỏi mở tinh tế giúp mở ra cánh cửa thấu cảm và sẻ chia sâu sắc.\"]}', 6, '2026-07-07 05:54:08', '2026-07-07 05:54:08'),
(7199, 1189, 'hook', '{\"title\": \"Giá trị của một người lắng nghe chân thành lớn lao thế nào?\"}', 1, '2026-07-07 05:54:09', '2026-07-07 05:54:09'),
(7200, 1189, 'explanation', '{\"bullets\": [\"Có một người bạn đáng tin cậy lắng nghe không phán xét là một tài sản vô giá.\", \"Người đó giúp bạn cảm thấy được thấu cảm, bớt cô đơn và tìm thấy sự bình yên.\", \"Hãy trân trọng mối quan hệ đó bằng cách cũng trở thành một người lắng nghe tốt cho họ.\"]}', 2, '2026-07-07 05:54:09', '2026-07-07 05:54:09'),
(7201, 1189, 'scenario', '{\"title\": \"Tình huống suy ngẫm\", \"body\": \"Lâm cảm thấy vô cùng may mắn khi luôn có Sơn bên cạnh lắng nghe mọi buồn vui, áp lực học tập và gia đình mà không hề phán xét hay cười cợt.\"}', 3, '2026-07-07 05:54:09', '2026-07-07 05:54:09'),
(7202, 1189, 'interaction', '{\"question\": \"Mối quan hệ giữa Lâm và Sơn mang lại giá trị gì lớn nhất cho cả hai?\", \"choices\": [{\"text\": \"Giúp cả hai cùng tiến bộ trong học tập nhờ làm bài tập hộ nhau.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Nuôi dưỡng sự an tâm tinh thần và xây dựng một tình bạn vững chắc đích thực.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:54:09', '2026-07-07 05:54:09'),
(7203, 1189, 'reflection', '{\"question\": \"Bạn đã gửi lời cảm ơn chân thành đến người bạn luôn lắng nghe mình chưa?\"}', 5, '2026-07-07 05:54:09', '2026-07-07 05:54:09'),
(7204, 1189, 'takeaway', '{\"items\": [\"Một người lắng nghe chân thành là tấm khiên bảo vệ tinh thần vững chắc cho bạn trước mọi áp lực.\"]}', 6, '2026-07-07 05:54:09', '2026-07-07 05:54:09'),
(7205, 1190, 'hook', '{\"title\": \"Đâu là đích đến cuối cùng của mọi cuộc giao tiếp lành mạnh?\"}', 1, '2026-07-07 05:54:09', '2026-07-07 05:54:09'),
(7206, 1190, 'explanation', '{\"bullets\": [\"Giao tiếp không chỉ để truyền đạt thông tin, nó là con đường ngắn nhất dẫn đến sự thấu cảm.\", \"Sự chân thành trong việc lắng nghe chủ động và dũng cảm bày tỏ tạo nên kết nối sâu sắc.\", \"Hãy luôn nuôi dưỡng các mối quan hệ bằng tình yêu thương, sự tôn trọng và chân thành nhất.\"]}', 2, '2026-07-07 05:54:10', '2026-07-07 05:54:10'),
(7207, 1190, 'scenario', '{\"title\": \"Tình huống đúc kết\", \"body\": \"Sau chặng đường dài cùng học cách giao tiếp, lắng nghe và tôn trọng ranh giới của nhau, nhóm bạn của Vy, Hoa, Nam và Sơn trở nên khăng khít và bền chặt hơn bao giờ hết.\"}', 3, '2026-07-07 05:54:10', '2026-07-07 05:54:10'),
(7208, 1190, 'interaction', '{\"question\": \"Chìa khóa vàng tạo nên sự gắn kết tuyệt vời của nhóm bạn là gì?\", \"choices\": [{\"text\": \"Sự ngụy trang cảm xúc để luôn tỏ ra hoàn hảo trước mắt nhau.\", \"correct\": false, \"emoji\": \"🛑\"}, {\"text\": \"Sự chân thành, thấu cảm và tôn trọng ranh giới của nhau qua giao tiếp.\", \"correct\": true, \"emoji\": \"💚\"}]}', 4, '2026-07-07 05:54:10', '2026-07-07 05:54:10'),
(7209, 1190, 'reflection', '{\"question\": \"Bạn sẽ áp dụng bài học giao tiếp lành mạnh nào đầu tiên vào cuộc sống của mình từ ngày hôm nay?\"}', 5, '2026-07-07 05:54:10', '2026-07-07 05:54:10'),
(7210, 1190, 'takeaway', '{\"items\": [\"Giao tiếp chân thành và thấu cảm biến những mối quan hệ bình thường thành kết nối sâu sắc trọn đời.\"]}', 6, '2026-07-07 05:54:10', '2026-07-07 05:54:10'),
(7211, 1191, 'hook', '{\"title\": \"Chào mừng bạn đến với Thử thách Tổng kết bài học \'Gắn kết Bền chặt qua Giao tiếp\'! Hãy chia sẻ và kết nối chân thành nhé.\"}', 1, '2026-07-07 05:54:10', '2026-07-07 05:54:10'),
(7212, 1191, 'scenario-choice', '{\"title\": \"Kết nối chân thành\", \"startNode\": \"step1\", \"nodes\": {\"step1\": {\"text\": \"Bạn thân rủ bạn ra bờ hồ tâm sự lúc tối muộn. Bạn thấy bạn có vẻ rất buồn. Bạn chọn gì?\", \"choices\": [{\"text\": \"Nói đùa cợt nhả để trêu chọc bạn cho vui vẻ lại.\", \"nextNode\": \"fail_step1\"}, {\"text\": \"Lắng nghe chăm chú, gật đầu nhẹ động viên bạn.\", \"nextNode\": \"step2\"}]}, \"step2\": {\"text\": \"Bạn kể: \'Tớ cảm thấy áp lực học tập quá, thi cử điểm kém làm bố mẹ mắng suốt\'.\", \"choices\": [{\"text\": \"\'Điểm thế bị mắng là đúng rồi, chăm học lên!\'.\", \"nextNode\": \"fail_step2\"}, {\"text\": \"Thấu cảm: \'Tớ biết cậu đã nỗ lực rất nhiều. Bị mắng như vậy chắc cậu buồn lắm đúng không?\'.\", \"nextNode\": \"step3\"}]}, \"step3\": {\"text\": \"Bạn khóc nấc lên và ôm lấy bạn. Bạn cảm thấy hơi ngượng ngùng trước cảm xúc mạnh mẽ này.\", \"choices\": [{\"text\": \"Đẩy bạn ra bảo: \'Con trai/con gái ai lại khóc lóc yếu đuối thế!\'.\", \"nextNode\": \"fail_step3\"}, {\"text\": \"Ôm nhẹ vỗ vai bạn, ngồi im lặng cùng bạn vượt qua cơn khóc.\", \"nextNode\": \"step4\"}]}, \"step4\": {\"text\": \"Bạn bình tĩnh lại và lau nước mắt, bảo: \'Cảm ơn cậu đã nghe tớ nói. Tớ thấy nhẹ lòng nhiều lắm\'.\", \"choices\": [{\"text\": \"\'Chuyện nhỏ ấy mà, nhớ bao tớ chầu nước nhé\' để lảng tránh.\", \"nextNode\": \"fail_step4\"}, {\"text\": \"\'Tụi mình là bạn thân mà, tớ luôn ở đây lắng nghe cậu. Hãy cùng cố gắng ôn thi đợt tới nhé!\'.\", \"nextNode\": \"success_end\"}]}, \"success_end\": {\"text\": \"🎉 Hoàn thành xuất sắc! Bạn đã xây dựng kết nối sâu sắc tuyệt vời qua sự thấu cảm và chân thành!\", \"isEnd\": true, \"isSuccess\": true}, \"fail_step1\": {\"text\": \"❌ Thất bại! Đùa cợt không đúng lúc làm bạn cảm thấy bị tổn thương và khép lòng.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_step2\": {\"text\": \"❌ Thất bại! Lời phán xét điểm số xát muối thêm vào nỗi đau áp lực của bạn.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_step3\": {\"text\": \"❌ Thất bại! Chê bai sự khóc lóc làm phá vỡ sự dễ tổn thương an toàn bạn vừa tạo ra.\", \"isEnd\": true, \"isSuccess\": false}, \"fail_step4\": {\"text\": \"❌ Thất bại! Lảng tránh cảm xúc làm giảm giá trị của buổi tâm sự chân thành.\", \"isEnd\": true, \"isSuccess\": false}}}', 2, '2026-07-07 05:54:10', '2026-07-07 05:54:10'),
(7213, 1191, 'sorting', '{\"instruction\": \"Kéo các thẻ phản hồi vào đúng hộp Thấu cảm hoặc Phán xét.\", \"leftBox\": {\"title\": \"Phản hồi Thấu cảm\"}, \"rightBox\": {\"title\": \"Phản hồi Phán xét\"}, \"items\": [{\"text\": \"\'Tớ hiểu cậu đang buồn, tớ ở đây cùng cậu.\'\", \"correctBox\": \"left\"}, {\"text\": \"\'Có thế mà cũng khóc, yếu đuối quá đi!\'\", \"correctBox\": \"right\"}, {\"text\": \"\'Chắc cậu đã phải chịu đựng áp lực lớn lắm.\'\", \"correctBox\": \"left\"}, {\"text\": \"\'Tại cậu không chịu nghe lời khuyên của tớ thôi.\'\", \"correctBox\": \"right\"}, {\"text\": \"\'Cậu có muốn nói thêm về cảm giác đó không?\'\", \"correctBox\": \"left\"}, {\"text\": \"\'Tớ thấy chuyện đó bình thường, chẳng có gì to tát.\'\", \"correctBox\": \"right\"}, {\"text\": \"\'Tớ cảm ơn vì cậu đã tin tưởng kể cho tớ nghe.\'\", \"correctBox\": \"left\"}, {\"text\": \"\'Đừng nghĩ lung tung nữa, đi ngủ đi là hết.\'\", \"correctBox\": \"right\"}, {\"text\": \"\'Tớ sẽ luôn giữ bí mật câu chuyện này của hai đứa.\'\", \"correctBox\": \"left\"}, {\"text\": \"\'Bố mẹ mắng cậu là đúng rồi, trách ai nữa.\'\", \"correctBox\": \"right\"}]}', 3, '2026-07-07 05:54:10', '2026-07-07 05:54:10'),
(7214, 1191, 'matching', '{\"instruction\": \"Ghép cặp từ khóa thấu hiểu với định nghĩa tương ứng.\", \"pairs\": [{\"left\": \"Thấu cảm\", \"right\": \"Việc cảm nhận nỗi đau của người khác từ góc nhìn của họ.\"}, {\"left\": \"Sự chân thành\", \"right\": \"Giao tiếp cởi mở, không che giấu khuyết điểm bản thân.\"}, {\"left\": \"Sự dễ tổn thương\", \"right\": \"Dũng cảm mở lòng nói về nỗi sợ sâu kín nhất.\"}, {\"left\": \"Câu hỏi mở\", \"right\": \"Công cụ kích hoạt cuộc tâm sự chia sẻ cảm xúc.\"}, {\"left\": \"Cam kết bảo mật\", \"right\": \"Giữ kín bí mật riêng tư của bạn bè tuyệt đối.\"}, {\"left\": \"Hiện diện\", \"right\": \"Sự tập trung hoàn toàn vào đối phương không bị xao nhãng.\"}, {\"left\": \"Không phán xét\", \"right\": \"Lắng nghe với thái độ chấp nhận sự khác biệt.\"}, {\"left\": \"Đồng minh tinh thần\", \"right\": \"Người luôn sát cánh lắng nghe và ủng hộ bạn.\"}]}', 4, '2026-07-07 05:54:10', '2026-07-07 05:54:10'),
(7215, 1191, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp vào chỗ trống trong đoạn văn sau.\", \"sentence\": \"Kết nối sâu sắc bắt nguồn từ sự [blank1] trong giao tiếp. Khi đối phương dám chia sẻ những nỗi sợ hãi thầm kín, họ đang bày tỏ khía cạnh dễ tổn [blank2] để xây dựng niềm tin. Phản hồi tốt nhất lúc này là sự lắng nghe thấu [blank3] thay vì đưa ra những lời phán xét hay chê bai. Hãy cam kết giữ [blank4] câu chuyện để bảo vệ sự an tâm tuyệt đối của bạn. Một người đồng minh tinh thần tốt sẽ luôn [blank5] bên cạnh bạn vượt qua mọi giông bão.\", \"blanks\": {\"blank1\": {\"correct\": \"chân thành\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"thương\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"cảm\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"kín\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"hiện diện\", \"placeholder\": \"...\"}}, \"words\": [\"chân thành\", \"thương\", \"cảm\", \"kín\", \"hiện diện\", \"giả tạo\", \"phá\", \"phụ thuộc\", \"độc\", \"tránh\"]}', 5, '2026-07-07 05:54:10', '2026-07-07 05:54:10'),
(7216, 1191, 'fill-blank', '{\"instruction\": \"Điền từ thích hợp vào chỗ trống trong đoạn văn sau.\", \"sentence\": \"Đặt câu hỏi [blank1] là kỹ năng tuyệt vời để khơi gợi đối phương chia sẻ nỗi lòng mà không cảm thấy bị ép buộc. Hãy tránh những lời khuyên [blank2] khi chưa hiểu rõ toàn bộ bối cảnh câu chuyện. Sự hiện diện trọn vẹn bằng ánh mắt và cái gật đầu nhẹ sẽ tiếp thêm [blank3] tích cực cho cuộc trò chuyện. Hãy trân trọng mối quan hệ lành mạnh bằng sự biết [blank4] chân thành nhất mỗi ngày. Giao tiếp hiệu quả biến những kết nối bình thường thành tình bạn [blank5] trọn đời.\", \"blanks\": {\"blank1\": {\"correct\": \"mở\", \"placeholder\": \"...\"}, \"blank2\": {\"correct\": \"sáo rỗng\", \"placeholder\": \"...\"}, \"blank3\": {\"correct\": \"năng lượng\", \"placeholder\": \"...\"}, \"blank4\": {\"correct\": \"ơn\", \"placeholder\": \"...\"}, \"blank5\": {\"correct\": \"bền vững\", \"placeholder\": \"...\"}}, \"words\": [\"mở\", \"sáo rỗng\", \"năng lượng\", \"ơn\", \"bền vững\", \"đóng\", \"ích kỷ\", \"nhanh\", \"giận\", \"mất\"]}', 6, '2026-07-07 05:54:10', '2026-07-07 05:54:10'),
(7217, 1191, 'interaction', '{\"question\": \"Khi bạn thân kể: \'Tớ lo sợ tụi mình học khác trường cấp ba sẽ xa cách\', phản hồi nào đúng đắn?\", \"choices\": [{\"text\": \"Tớ cũng lo chuyện đó, tụi mình cùng lập kế hoạch đi chơi cuối tuần nhé!.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Cậu lo hão huyền quá, có gì đâu mà sợ.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 7, '2026-07-07 05:54:10', '2026-07-07 05:54:10'),
(7218, 1191, 'interaction', '{\"question\": \"Tại sao dũng cảm thừa nhận điểm yếu lại giúp mối quan hệ thân thiết hơn?\", \"choices\": [{\"text\": \"Vì nó chứng minh bạn tin tưởng đối phương đủ nhiều để cởi bỏ lớp phòng ngự.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Vì nó khiến đối phương thương hại và luôn nhường nhịn bạn.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 8, '2026-07-07 05:54:10', '2026-07-07 05:54:10'),
(7219, 1191, 'interaction', '{\"question\": \"Kỹ năng đặt câu hỏi mở giúp ích gì cho buổi tâm sự?\", \"choices\": [{\"text\": \"Gợi mở câu chuyện tự nhiên giúp đối phương giải tỏa áp lực tinh thần.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Bắt đối phương phải trả lời Có hoặc Không nhanh chóng.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 9, '2026-07-07 05:54:10', '2026-07-07 05:54:10'),
(7220, 1191, 'interaction', '{\"question\": \"Biểu hiện nào vi phạm nghiêm trọng cam kết bảo mật tình bạn?\", \"choices\": [{\"text\": \"Kể bí mật thầm kín của bạn thân cho người khác nghe để làm trò đùa.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Giữ kín câu chuyện trong lòng và luôn âm thầm ủng hộ bạn.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 10, '2026-07-07 05:54:10', '2026-07-07 05:54:10'),
(7221, 1191, 'interaction', '{\"question\": \"Mục đích tối thượng của sự thấu cảm trong giao tiếp là gì?\", \"choices\": [{\"text\": \"Chia sẻ nỗi đau và kết nối tâm hồn sâu sắc với đối phương.\", \"correct\": true, \"emoji\": \"💚\"}, {\"text\": \"Chứng minh bạn là người thông minh và nhân hậu hơn đối phương.\", \"correct\": false, \"emoji\": \"🛑\"}]}', 11, '2026-07-07 05:54:11', '2026-07-07 05:54:11');
